window.PBP={"translated":456,"translatable":2309,"careful":439,"chapters":[{"n":null,"gu":"અર્પણ","en":"Dedication","url":"https://www.anirdesh.com/pbp/index.php?page=arpan","b":[{"i":null,"k":"heading","g":"અર્પણ...","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરબ્રહ્મ પુરુષોત્તમ ભગવાન શ્રી સ્વામિનારાયણનાં","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"વચનોનું મૂર્તિમાન સ્વરૂપ,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"જેમનાં દર્શનમાત્રે શ્રીહરિની પારલૌકિક મૂર્તિની","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"દિવ્ય અનુભૂતિ સહેજે થાય છે એવા, શ્રીહરિને અંગોઅંગ ધારણ કરનાર,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"મારા મોક્ષના દાતા, પ્રેરણામૂર્તિ ગુરુહરિ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પ્રગટ બ્રહ્મસ્વરૂપ શ્રી પ્રમુખસ્વામી મહારાજનાં કરકમળમાં","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"સાષ્ટાંગ પ્રણામ સાથે ...","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1,"k":"attrib","g":"સંપાદક","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false}]},{"n":null,"gu":"પ્રકાશકીય...","en":"Publisher's Note","url":"https://www.anirdesh.com/pbp/index.php?page=prakashkiya","b":[{"i":2,"k":"para","g":"પૂર્ણ પુરુષોત્તમ ભગવાન શ્રી સ્વામિનારાયણે આ ધરતી પર અવતરીને પોતાનાં દિવ્ય ચરિત્રો, ઐશ્વર્યો અને ઉપદેશો દ્વારા અસંખ્ય મુમુક્ષુઓને મોક્ષના અધિકારી કર્યા છે. તેમાંય તેમનું એક અજોડ વરદાન એટલે અહોરાત્ર સતત વહેતી તેમની ઉપદેશ-ભાગીરથી. પ્રભાત હોય કે મધરાત, મધ્યાહ્ન હોય કે સંધ્યાહ્ન, કથાપ્રસંગ હોય કે ભોજનપ્રસંગ, પ્રવાસ હોય કે નિવાસ, સ્વામિનારાયણ ભગવાને અહોરાત્ર પોતાની જ્ઞાનગંગા વહાવ્યે રાખી છે. સ્થળ, સમય, વ્યક્તિ ગમે તે હોય, પરંતુ શ્રીહરિએ તેને અનુરૂપ એટલો સુંદર બોધ આપ્યો છે કે વેદો અને ઉપનિષદો જ નહીં, પરંતુ સમગ્ર વિશ્વની દિવ્ય જ્ઞાન પરંપરાનો અર્ક તેમાં હોય. એટલું જ નહીં, ક્યાંક તો એમની પરાવાણીમાં શાસ્ત્રોના ગહન અર્થોના જે અસાધારણ વ્યવહારુ ઉકેલ જોવા મળે છે તે સાચે જ અજોડ છે. ભગવાન સ્વામિનારાયણની એ દિવ્ય વાણીને કોઈ વિશેષણ દ્વારા વર્ણવી શકાય તેમ નથી. સરળ અને ચિત્રાત્મક શૈલી, દિવ્ય અને અસાધારણ નિરૂપણ સામર્થ્ય, હથેળીમાં મૂકેલા આમળાને દેખી શકાય તેમ જ્ઞાનનો સમ્યક્ સાક્ષાત્કાર, સ્વાનુભવના જોર પર સિદ્ધ કરેલું જ્ઞાન, સકલ શાસ્ત્રો પણ તેનું પ્રમાણ આપતા હોય - એટલી વિગતો એમના ઉપદેશની લાક્ષણિકતા વર્ણવવા પૂરતી નથી. તેના માટે એક જ શબ્દ યથાર્થ છે: ‘દિવ્ય પરાવાણી.’","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":3,"k":"para","g":"ભગવાન સ્વામિનારાયણના મહાન પરમહંસ સંતોએ એ વાણીને સંગૃહીત કરીને, દસ્તાવેજી વિગતો સાથે સંપાદિત કરીને વચનામૃત ગ્રંથની અદ્‌ભુત અને અનન્ય ભેટ આપી છે. વચનામૃત ગ્રંથ ઉપરાંત, ભગવાન સ્વામિનારાયણે જીવનભર આપેલા ઉપદેશોનો અદ્‌ભુત સંચય ‘શ્રીહરિચરિત્રામૃત સાગર’ ગ્રંથમાં છે. ભગવાન સ્વામિનારાયણની હયાતીમાં સદ્‌ગુરુ મુક્તાનંદ સ્વામીએ કરેલી નોંધો પરથી, શિષ્ય આધારાનંદ સ્વામીએ રચેલો આ ગ્રંથ માત્ર સ્વામિનારાયણ સંપ્રદાયની જ નહીં, સમગ્ર હિન્દી સાહિત્ય જગતની એક અજોડ ભેટ છે. ઓગણત્રીસ પૂરમાં વહેંચાયેલો લગભગ એંશી હજાર દોહા - ચોપાઈઓમાં રચાયેલો આ ગ્રંથ હિન્દી સાહિત્યનો સૌથી વિશાળ પદ્ય ગ્રંથ છે. તેઓ હિન્દી વ્રજભાષી પ્રદેશના ન હોવા છતાં તેમણે કરેલું આ પ્રદાન એક અનન્ય કૃતિ બની રહ્યું છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":4,"k":"para","g":"આ ગ્રંથમાં કવિએ ખૂબ કુશળતાપૂર્વક ભગવાન સ્વામિનારાયણનાં ચરિત્રો ગૂંથ્યાં છે અને પ્રસંગે પ્રસંગે ભગવાન સ્વામિનારાયણનો ઉપદેશ પણ સુંદરતાથી ગૂંથ્યો છે. પરંતુ સાગરસમા એ વિશાળ હિન્દી-વ્રજ ભાષાના ગ્રંથમાંથી મુમુક્ષુઓ કેટલુંક આચમન કરી શકે! પૂર્વે હરિચરિત્રામૃતસાગર ગ્રંથને સંક્ષિપ્ત ગુજરાતી ભાષાંતર રૂપે સ્વામિનારાયણ સાહિત્ય પ્રકાશન મંદિર, ગાંધીનગર દ્વારા પાંચ ભાગમાં પ્રકાશિત કરાયો છે. તેના અનુવાદનું સ્તર પણ ખૂબ સ્તુત્ય છે. આમ છતાં, મૂળ પદ્યગ્રંથને વાંચીને તેમાંથી ભગવાન સ્વામિનારાયણના ઉપદેશનું ચયન કરીને તેને સ્વતંત્ર રીતે ગ્રંથરૂપે પ્રકાશિત કરવાની એક આવશ્યકતા હતી. પ્રમુખસ્વામી મહારાજના આશીર્વાદ સાથે મૂળ પદ્ય વાંચીને ભગવાન સ્વામિનારાયણના તમામ ઉપદેશભાગનું પરિશીલન કરીને, હિન્દી-વ્રજ પદ્યમાંથી ગુજરાતી ભાષાંતર કરીને વિષયવાર એક ગ્રંથ રચવાની ખૂબ જહેમત અક્ષરજીવન સ્વામીએ લીધી છે. આ જહેમતભરી સેવા કરવા બદલ અમે તેમના આભારી છીએ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":5,"k":"para","g":"ભગવાન સ્વામિનારાયણના ૨૨૭મા પ્રાગટ્યોત્સવે તેઓની આ પરાવાણીને પ્રકાશિત કરતાં સ્વામિનારાયણ અક્ષરપીઠ હર્ષ અનુભવે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":6,"k":"para","g":"આધ્યાત્મિક સાધનામાં આગળ વધવા ઇચ્છતા કે ભગવાનનો સાક્ષાત્કાર કરવા ઇચ્છતા મુમુક્ષુઓ માટે એ ઉપદેશ કેટલો અદ્‌ભુત અને વ્યવહારુ છે તેની પ્રતીતિ આ ગ્રંથ આપે છે. આશા છે કે આ ગ્રંથ સર્વે મુમુક્ષુઓ માટે સાધનાનો એક મહાન રાજમાર્ગ બની રહેશે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":7,"k":"attrib","g":"- સ્વામિનારાયણ અક્ષરપીઠ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":8,"k":"attrib","g":"સ્વામિનારાયણ જયંતી, ચૈત્ર સુદ-૯,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":9,"k":"attrib","g":"સંવત ૨૦૬૪. સને ૨૦૦૮","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false}]},{"n":null,"gu":"આ ગ્રંથ વિષે કિંચિત્...","en":"About This Text","url":"https://www.anirdesh.com/pbp/index.php?page=granth-intro","b":[{"i":10,"k":"para","g":"ભગવાન સ્વામિનારાયણનાં લીલાચરિત્રો અને ઉપદેશો તત્કાલીન સંતો-પરમહંસોએ લખી લીધાં હતાં. એ પરમહંસોમાં શ્રીહરિથી ૨૩ વર્ષ મોટા અને શ્રીહરિનાં લીલાચરિત્રોના પ્રત્યક્ષ સાક્ષી મુક્તમુનિનું પ્રદાન સ્વામિનારાયણ સંપ્રદાયમાં અજોડ રહેશે. તેમણે પદ્યગ્રંથમાં મુક્તાનંદ કાવ્ય રચ્યું. તેમણે કરેલી મહત્ત્વની નોંધોના ખરડા અને તેના પરથી તેમના શિષ્ય સિદ્ધાનંદમુનિ (આધારાનંદ સ્વામી)એ હિન્દી-વ્રજ ભાષામાં રચેલો વિરાટ ગ્રંથ ‘શ્રીહરિચરિત્રામૃત સાગર’ એમને યાવત્‌ચંદ્રદિવાકરૌ આ ભૂમંડલ પર ખ્યાતિ અપાવતો રહેશે. મુક્તાનંદ સ્વામીની લેખિની અંતિમ શ્વાસ સુધી શ્રીહરિનાં ચરિત્ર-ઉપદેશ લેખનમાં દોડતી રહી. ‘વચનામૃત’ ગદ્યગ્રંથના સંપાદન કાર્યમાં તેઓ તથા અન્ય ત્રણ સદ્‌ગુરુ સંતોની લેખનસેવા પણ સંલગ્ન છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":11,"k":"para","g":"સિદ્ધાનંદ સ્વામી રચિત ‘શ્રીહરિચરિત્રામૃત સાગર’ આજે સંપ્રદાયમાં ગુજરાતી ભાષાંતરમાં ઉપલબ્ધ છે. તેનાં થોડાંક પ્રકરણોના બે ભાગ હિન્દી-વ્રજમાં પણ પ્રકાશિત થયા હતા. મૂળ હસ્તપ્રત ‘હિન્દી-વ્રજ’ મિશ્રિત ચોપાઈ-દોહા-સોરઠામાં લખાયેલો, તેની હસ્તપ્રત આજથી ચાલીસેક વર્ષ પૂર્વે બ્રહ્મસ્વરૂપ યોગીજી મહારાજની જાણમાં આવી. તે વખતે તેમણે એ હસ્તપ્રતના લિપ્યાન્તર થયેલા મોટા ૨૯ ગ્રંથો મેળવી આપ્યા. નડિયાદના પરમ ભક્ત કૃષ્ણાભાઈ અને મંડળ દ્વારા એ ગ્રંથોની હાથેથી નકલો કરાવી. પાછળથી એની અસલ ફોટોકોપી પણ પ્રાપ્ત થઈ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":12,"k":"para","g":"સદ્‌ગુરુ પૂજ્ય ઈશ્વરચરણ સ્વામીના હૃદયમાં એક સંકલ્પ સતત રમ્યા કરતો - આ મૂળ હસ્તપ્રતોનું વ્યવસ્થિત પરિશીલન થાય. પાંચેક વર્ષ પૂર્વે સને ૨૦૦૧માં તેમણે મને આ અંગે સંશોધન કરવા આદેશ આપ્યો. જોકે તે વખતે ‘સ્વામિનારાયણ ચરિત માનસ’ પણ તેમને રચાવવું હતું, એટલે એ કાર્ય પહેલું આટોપવા કહ્યું. સન્ ૨૦૦૨થી ૨૦૦૪માં એ કાર્ય ગુરુહરિ પ્રમુખસ્વામી મહારાજની કરુણા-કૃપાથી સારી રીતે પૂર્ણ થયું. સદ્‌ગુરુ ઈશ્વરચરણ સ્વામીએ ફરી આ હસ્તપ્રતો પર કામ કરવા આદેશ આપ્યો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":13,"k":"para","g":"પરમ પૂજ્ય સ્વામીશ્રીના આશીર્વાદથી એ કાર્ય મેં હાથમાં લીધું. જેમ જેમ મૂળ વાંચતો ગયો, તેમ તેમ શ્રીહરિના ઉપદેશ પર વધુ ધ્યાન કેન્દ્રિત થતું રહ્યું. આ ઉપદેશોને વિષય-વિભાગવાર જુદા કરી અનુવાદ કરતો ગયો. મછોદરી બાગ વારાણસીથી પૂજ્ય શાસ્ત્રી હરિપ્રકાશ સ્વામીએ પ્રકાશિત કરેલા ગુજરાતી ગ્રંથોનો પણ આધાર મળ્યો. આમ કામ શરૂ કર્યું. કુલ મળીને ૨૯ જેટલા વિષય વિભાગ કર્યા. કામ જટિલ તો ખૂબ હતું, કારણ કે શ્રીહરિનો ઉપદેશ ૨૯ પૂરમાં ફેલાયેલો હતો. એ પ્રવાહિત અમૃતવાણીને વિષયવાર વહેંચવામાં ભાષાંતરને ક્યાંક દોઢે પણ ચઢાવવું પડ્યું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":14,"k":"para","g":"હા, આ ઉપદેશની પ્રાસાદિકતા જળવાઈ રહે તે સતત ખાલ રાખ્યો છે. પૂજ્ય ઈશ્વરચરણ સ્વામી સતત માર્ગદર્શન આપતા રહ્યા. જેને કારણે મૂળ ચોપાઈ-સાખીમાં વણેલા ઉપદેશને કોઈ અલંકાર ચઢાવ્યા વિના, યથાતથા ગુજરાતીમાં ઢાળવાનું જાણપણું રહ્યું. ક્યાંક ફૂટનોટમાં તેની મૂળ સાખીઓ પણ મૂકી છે, જેથી શ્રીહરિના મુખે ઉચ્ચારેલાં એ વાક્યોને મૂળ સ્વરૂપે માણી શકાય અને નાણી પણ શકાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":15,"k":"para","g":"પૂર્વે થયેલા ગુજરાતી અનુવાદો બેશક સારા જ છે, પરંતુ કદાચ ચરિત્ર લેખન સાથે ઉપદેશ મૂકવામાં પૃષ્ઠ સંખ્યાની મર્યાદા નડી હોય કે અન્ય કારણ હોય – મૂળ ગ્રંથમાં હોવા છતાં ગુજરાતી થયું નથી કે છૂટી ગયું છે કે કોઈ કારણસર બાકાત રહી ગયું છે, તે હકીકત છે. ‘પુરુષોત્તમ બોલ્યા પ્રીતે’માં કેવળ ઉપદેશનું આકલન કરવાનું હોઈ તે માટે સારી મોકળાશ મળી. શ્રીહરિનાં સિદ્ધાંતવચનો પર વધુ ધ્યાન કેન્દ્રિત કર્યું, જેથી અન્ય ઉપદેશને ગૌણપણે રહેવા દઈ વિષય-વિભાગ કર્યા છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":16,"k":"para","g":"‘પુરુષોત્તમ બોલ્યા પ્રીતે’માં કેવળ શ્રીમુખ વચનોને સ્થાન અપાયું છે. એ પછી શ્રીમુખથી સ્રવેલી વાણી હોય કે શ્રીહરિએ જ લખાવી મોકલેલા પત્રરૂપે હોય કે ખરડારૂપે - તેને અનુરૂપ પુર, તરંગ, પંક્તિની અંક સંખ્યા નોંધ સાથે અહીં મૂક્યાં છે. વળી, સ્થાનનિર્દેશ સાથે પૂર્વાપર સંબંધ પણ મૂક્યો છે. જેથી શ્રીહરિ કોને, ક્યાં, ક્યારે ઉપદેશ આપે છે, તે સુપેરે જાણી શકાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":17,"k":"para","g":"વળી, શ્રીહરિએ આપેલા ઉપદેશ સાથે મુક્તમુનિ, સિદ્ધાનંદમુનિ તેમજ અન્ય સંતોના મુખે ઉચ્ચારાયેલી પ્રાસાદિક વાતો પ્રસ્તુત વિષયને પુષ્ટિકારક હોય તે તે પ્રકરણના અંતે ‘પરિશિષ્ટ’ સ્વરૂપે કિંચિત્ રજૂ કરી છે. જે પૈકી સંપ્રદાયમાં કેટલાંક વાક્યો હરિચરિત્રામૃતસાગરના સંદર્ભ સ્વરૂપે જોવા મળે છે, જે શ્રીહરિના મુખે ઉચ્ચારાયાં ન હોય, પણ વિષયવસ્તુને પુષ્ટિકારક હોય એ દૃષ્ટિએ પણ એ વાક્યોની પ્રાસાદિકતાને ધ્યાનમાં રાખીને અહીં સંગૃહીત કર્યાં છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":18,"k":"para","g":"પાદટીપમાં ક્યાંક તરંગની સંખ્યા ડબલ મૂકી છે. જેમાં કૌંસમાં છે તે મૂળ ગ્રંથની જાણવી. લહિયાએ લિપ્યન્તર કરતી વખતે સરતચૂકથી બે-બે તરંગને એક જ ક્રમાંક આપ્યો હોય કે એક તરંગને બે ક્રમાંક આપ્યા હોય એવા સ્થાને આ સમસ્યા સર્જાઈ છે. પૂર્વપ્રકાશિત ભાષાંતર ગ્રંથોમાં એકથી સળંગ ક્રમાંક જાળવી રાખ્યા હોઈ દ્વિધાનું નિવારણ કરવા કૌંસમાં મૂળ તરંગ-અંક સંખ્યા રાખી છે. વળી, વ્રજ ભાષાની મૂળ તરંગ પંક્તિઓ ટાંકી હોઈ પૂર-તરંગ પછીની અંક સંખ્યા તે તે પંક્તિઓની જાણવી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":19,"k":"para","g":"વિરાટ સાગરમાંથી મોતી ખોળવાનું આ જટિલ કાર્ય પ્રગટ બ્રહ્મસ્વરૂપ ગુરુહરિ પ્રમુખસ્વામી મહારાજની કૃપા અને આશીર્વાદથી ચાર વર્ષમાં પૂર્ણ થઈ શક્યું. પૂજ્ય ઈશ્વરચરણ સ્વામીનું પ્રેમાળ માર્ગદર્શન કદી નહીં ભુલાય. પૂજ્ય વિવેકસાગર સ્વામીની નિર્ભેળ અનુવાદ તથા ચકાસણીની ટકોરે મને સતત જાગ્રત રાખ્યો છે. તેમનો આભાર માનું તેટલો ઓછો છે. અક્ષરપીઠના સર્વે સહકર્મીઓનો આભાર માની વિરમું છું. ક્યાંક કોઈ ક્ષતિ રહી જવા પામી હોય તો તે મારી ગફલત ગણી દરગુજર કરશો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":20,"k":"attrib","g":"- સાધુ અક્ષરજીવનદાસ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false}]},{"n":1,"gu":"સત્સંગ","en":"Satsang","url":"https://www.anirdesh.com/pbp/index.php?page=chp_1","b":[{"i":21,"k":"para","g":"શ્રીહરિએ વરિષ્ઠ બંધુને કહ્યું, “મોહનું અજ્ઞાન સત્સંગરૂપી સૂર્યથી ટળે છે. સત્સંગ બે પ્રકારનો હોય છે, ભગવાનનો અને ભગવાનના ભક્તનો. સત્સંગ કરતાં મોહ ટળે અને મોહ ટળતાં વિષયો વિષ જેવા લાગે છે. ખપ અને રુચિ અપાર હોય ત્યારે તેનો સત્સંગ પાર પડે છે. સત્સંગનો ખપ ઓછો ન થાય એવો નિત્ય તપાસ કરવો. જેને ઉત્કૃષ્ટ ખપ હોય તેના સંગમાં રહી સત્સંગ કરે તો રંગ ઊતરે નહિ. મન-ઇન્દ્રિયનો સંગ ન રહે એનું નામ જ સત્સંગ છે. એવા સત્સંગથી પરમપદ મળે છે.","e":"Shriharí said to His elder brother, “The ignorance of moha is dispelled by the sun in the form of satsang. Satsang is of two kinds — that of Bhagwan and that of the bhakta of Bhagwan. By doing satsang moha is dispelled, and when moha is dispelled the vishays seem like poison. When khap and liking are boundless, then one’s satsang is carried through. One should examine oneself daily, so that the khap for satsang does not lessen. If one stays in the company of one whose khap is of the highest and does satsang, the colour does not fade. That very state in which the company of the mind and the indriyas does not remain is what is called satsang. From such satsang the highest state is attained.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":22,"k":"para","g":"“મંદ, મધ્યમ ને તીવ્ર એમ શ્રદ્ધાના ત્રણ ભેદ છે. તેણે કરીને સત્સંગના ત્રણ ભેદ થાય છે. મંદ શ્રદ્ધાવાળાએ મધ્યમનો અને મધ્યમ શ્રદ્ધાવાળાએ તીવ્ર શ્રદ્ધાવાળાનો સત્સંગ કરવો. જીવન પર્યંત ઉત્તમ શ્રદ્ધા રાખી સત્સંગ કરે ને નિયમ-ધર્મમાં દૃઢ રહે તો તે અક્ષરધામમાં જાય છે. જેને ઉત્તમ શ્રદ્ધા નથી ને ગોલોકની રુચિ રાખે તો તે ગોલોકમાં જાય, વૈકુંઠની રુચિ હોય તો વૈકુંઠમાં જાય. જેવી રુચિ રાખી સત્સંગ કરે તેને તે પ્રકારનું ફળ મળે છે.”","e":"“Shraddha is of three kinds — mild, middling and intense. By that, satsang too becomes of three kinds. One with mild shraddha should keep the satsang of one with middling shraddha, and one with middling shraddha that of one with intense shraddha. If one keeps the highest shraddha for the whole of life and does satsang, and remains firm in niyam and dharma, then he goes to Akshardham. One who does not have the highest shraddha and keeps a liking for Golok goes to Golok; if he has a liking for Vaikunth, he goes to Vaikunth. With whatever liking one does satsang, that is the kind of fruit he receives.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":23,"k":"verse","g":"‘નિયમ ધર્મ મેં ઉત્તમ રહાવે, સો જન અક્ષરધામ મેં જાવે.","e":"‘Niyam dharma me uttam rahāve, so jan Akshardhām me jāve.","s":[],"sv":[],"mt":false,"gl":"[One who remains excellent in niyam and dharma — that person goes to Akshardham.]","a":false},{"i":24,"k":"verse","g":"ગોલોક કિ રુચિ ગોલોક મેં જાવે, વૈકુંઠ કિ રુચિ વૈકુંઠ મેં ઠેરાવે.","e":"Golok ki ruchi Golok me jāve, Vaikunth ki ruchi Vaikunth me thherāve.","s":[],"sv":[],"mt":false,"gl":"[A liking for Golok takes one to Golok; a liking for Vaikunth settles one in Vaikunth.]","a":false},{"i":25,"k":"verse","g":"જૈસી રુચિ કરે સત્સંગ જેહા, તે સેવા મહિં પાવે તેહા.’","e":"Jaisī ruchi kare satsang jehā, te sevā mahi pāve tehā.’","s":["1/80/7-12, 19-25"],"sv":[],"mt":false,"gl":"[With whatever liking one does satsang, that is what one obtains in His seva.]","a":false},{"i":26,"k":"para","g":"સાંકળી ગામમાં ભગવાન ઠક્કરને ઘરે શ્રીહરિએ વાત કરતાં કહ્યું, “સૌ હરિભક્તોએ સંધ્યા વખતે ભેગા થઈને કથાવાર્તા નિત્ય કરવી અને કુસંગ તજવો. અધર્મને કુસંગ કહેવાય છે. સત્સંગને ધર્મ શોભાવે છે. સત્સંગ કરે તો ભવસાગર તરે છે. સત્સંગમાં કોઈ પણ જાતના મનુષ્ય આવે તોપણ નરક-ચોરાશીથી છૂટે છે. સત્સંગમાં પ્રગટ હરિ વિચરે છે.”","e":"In the village of Sankali, at the home of Bhagwan Thakkar, while talking, Shriharí said, “All haribhaktas should gather at the time of sandhya and do katha-varta daily, and should forsake kusang. Adharma is what is called kusang. Dharma adorns satsang. If one does satsang, one crosses the ocean of birth and death. Whatever kind of person may come into satsang, he is freed nonetheless from hell and the eighty-four lakh births. In satsang the pragat Hari moves about.”","s":["3/40/19-22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":27,"k":"para","g":"શ્રીહરિએ ગઢપુરમાં અભયનૃપને કહ્યું, “જ્યારે કોઈ જન સત્સંગને તજે છે, ત્યારે અમે પણ તેને તજી દઈએ છીએ. સત્સંગ કરતાં તમે નિર્ભય રહી શકશો. તમે સૌ બીજાનો વિશ્વાસ ત્યજી અમારા દાસ (આશ્રિત) થયા તે અન્ન-વસ્ત્રે કરીને તમને કોઈ દુઃખ નહિ આવે. સત્સંગ છોડશો તો દુઃખ આવશે.”","e":"Shriharí said to Abhay Nrup at Gadhpur, “When a person forsakes satsang, then We too forsake him. By doing satsang you will be able to remain fearless. All of you have forsaken trust in others and become Our das (dependants); as far as food and clothing are concerned, no misery will come to you. If you leave satsang, misery will come.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":28,"k":"verse","g":"‘તુમ સબ ભયે હમારા દાસા, ઓરન કો છોડી વિશ્વાસા.","e":"‘Tum sab bhaye hamārā dāsā, oran ko chhodī vishvāsā.","s":[],"sv":[],"mt":false,"gl":"[You have all become Our das, having forsaken your trust in others.]","a":false},{"i":29,"k":"verse","g":"અન્ન વસ્ત્ર કરિકે જોઉ, તુમકું દુઃખ ન આનેકું સોઉ.","e":"Ann vastra karike joū, tumkum dukh na ānekum soū.","s":[],"sv":[],"mt":false,"gl":"[As for food and clothing, on that account no misery shall come to you.]","a":false},{"i":30,"k":"verse","g":"જબ જન છોડે સત્સંગા, તિનસેં હમ હોવે અસંગા.’","e":"Jab jan chhode satsangā, tinse ham hove asangā.’","s":["4/15/29-32"],"sv":[],"mt":false,"gl":"[When a person forsakes satsang, from him We become detached.]","a":false},{"i":31,"k":"para","g":"ઈંગોરાળા ગામે શ્રીહરિએ સત્સંગનો મહિમા કહેતાં કહ્યું, “સત્સંગરૂપી પુરમાં જેનો નિવાસ થયો તેને પીડા આપવા અધર્મી જન આશા છોડી દે છે, કારણ કે સત્સંગનો એવો પ્રતાપ છે કે અધર્મીજન તેમાં પગ મૂકતાં બળવા લાગે છે. સત્સંગમાં જે વાર્તા થાય છે તે સુદર્શન ચક્ર તુલ્ય છે. હરિભક્ત તેને સાંભળીને અંતરમાં ઉતારે તેની અહોનિશ રક્ષા થાય છે.”","e":"At the village of Ingorala, telling the mahima of satsang, Shriharí said, “Adharmi people give up all hope of tormenting one who has come to dwell in the city that is satsang, because such is the power of satsang that adharmi people begin to burn the moment they set foot in it. The talks that take place in satsang are equal to the Sudarshan chakra. The haribhakta who listens to them and takes them into his heart is protected day and night.”","s":["4/19/9-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":32,"k":"para","g":"સારંગપુરમાં શ્રીહરિએ વાત કરતાં કહ્યું, “સુખમાં તો સૌ સત્સંગ કરે, પણ વિપત્તિ આવે ત્યારે કસોટીમાં પાર ઊતરે તેના પર અમે રાજી થઈએ છીએ.”","e":"At Sarangpur, while talking, Shriharí said, “In sukh everyone does satsang; but We are pleased with one who comes through the test when calamity arrives.”","s":["4/43/35-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":33,"k":"para","g":"સારંગપુરમાં શ્રીહરિએ સત્સંગનો મહિમા કહેતાં કહ્યું, “જે સત્સંગ કરે છે તેને અનંત બ્રહ્માંડોથી પર રહેલું અક્ષરધામ અને જીવોની કળા હસ્તામલક થાય છે. આવી તો અનંત યોગકળા સત્સંગ કરવાથી વરે છે. બાકી અષ્ટાંગ યોગ સિદ્ધ કરવા પાછળ જીવન હોમી દે, દેહે કરીને અપાર કષ્ટ સહન કરે, વનફળ ને વાયુનો આહાર કરે તોય પણ ન્યૂન છે. સત્સંગ વિના ભવસાગર પાર કરી શકાતો નથી. આ વેળાએ જેને સત્સંગ થયો છે તેનાં પુણ્ય કહી ન શકાય તેટલાં છે. ઇન્દ્રિયો, અંતઃકરણ મળ્યાં તેનું પ્રયોજન સત્સંગ કરવો એ જ છે. મનુષ્યશરીર પામ્યા પછી જે જીવ સત્સંગથી વંચિત રહ્યો તેને દેખી ચોરાસી લાખ યોનિના અન્ય જીવ રુદન કરે છે. જે કંઈ સુખ માન્યું છે તે પ્રકૃતિ-પુરુષ સુધીનું છે, ને તેને પણ કાળ ગ્રસી લે છે. સત્સંગ કરે છે તેને આ વાત સમજાય છે.”","e":"At Sarangpur, telling the mahima of satsang, Shriharí said, “For one who does satsang, Akshardham — which lies beyond the infinite brahmands — and the workings of the jivas become as plain as a fruit held in the palm. Infinite such powers of yoga are won by doing satsang. Otherwise, though one pour away one’s life in perfecting ashtang yoga, though one bear boundless hardship with the body, though one live on the fruit of the forest and on air, it is still deficient. Without satsang the ocean of birth and death cannot be crossed. The punya of one who has obtained satsang at this time is more than can be told. The very purpose for which the indriyas and the antahkaran were obtained is to do satsang. Seeing a jiva who, having attained a human body, has remained deprived of satsang, the other jivas of the eighty-four lakh species weep. Whatever has been taken to be sukh extends only as far as Prakruti-Purush, and kal devours even that. One who does satsang understands this talk.”","s":["4/43/46-51"],"sv":[],"mt":false,"gl":null,"a":false},{"i":34,"k":"para","g":"મેથાણમાં શ્રીહરિ જમીને આવ્યા અને પછી હરિજનોને વાત કરતાં કહ્યું, “જીવને આ સંસારમાં ફરીથી માતા-પિતા મળે છે, પુત્ર, સ્ત્રી, રાજ્ય, ગજ, ઘોડા, મનવાંછિત ભોગ, સુરલોક, બ્રહ્મલોક, વૈકુંઠલોક અને બીજો સમાજ - એ બધું મળે છે, પણ સંત-સમાગમ મળવો કઠણ છે. સંત-સમાગમથી ઊંચું કોઈ સુખ નથી, એ સુખ અમે સૌને આપ્યું છે. આ વાત સૌ હૃદયમાં લખી રાખજો. વિસારી દેશો તો અર્થ નહિ સરે. ચિંતામણિ મળે અને રંક રહે તો તેની ઓળખ જ નથી. તેની લૌકિક બુદ્ધિ જાણવી.”","e":"At Methan, Shriharí came after taking His meal and then, while talking to the harijans, said, “In this sansar the jiva obtains mother and father again, and sons, wife, kingdom, elephants, horses, the enjoyments it wishes for, Surlok, Brahmalok, Vaikunthlok and other company besides — all this it obtains; but the samagam of the Sant is hard to obtain. There is no sukh higher than the samagam of the Sant, and We have given that sukh to all. Write this talk in your hearts. If you let it be forgotten, the purpose will not be served. If a man obtains a chintamani and yet remains destitute, he has simply not recognised it. Know his intellect to be a worldly one.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":35,"k":"verse","g":"‘ઔર સમાજ સો મિલહિ સબહિ, સંત સમાગમ મિલત ન કબહિ.","e":"‘Aur samāj so milahi sabahi, sant samāgam milat na kabahi.","s":[],"sv":[],"mt":false,"gl":"[All other company is obtained by everyone; the samagam of the Sant is never obtained.]","a":false},{"i":36,"k":"verse","g":"સંત સમાગમ દુર્લભ જેહિ, સબ હરિજનકું મિલે હેં તેહિ.’","e":"Sant samāgam durlabh jehi, sab harijankum mile hem tehi.’","s":["6/26/17-24"],"sv":[],"mt":false,"gl":"[That samagam of the Sant which is so rare — all you harijans have obtained it.]","a":false},{"i":37,"k":"para","g":"ગોંડળમાં હઠીસિંહ નૃપના ભુવનમાં શ્રીહરિ હિંડોળે આવીને વિરાજ્યા અને વાત કરવા લાગ્યા, “સત્સંગમાં આવીને બેસે છે ત્યારે મોક્ષનો વિચાર હાથમાં આવે છે. મોક્ષના વિચાર વિના અન્ય વિચાર અપાર દુઃખનું કારણ બને છે. સ્વર્ગ, મૃત્યુ, પાતાળનો અધિપતિ થાય, બ્રહ્મા કે પ્રકૃતિ-પુરુષ સુધીનું પદ મળે તોપણ તેને સુખ થતું નથી. ક્ષણભંગુર આ શરીરમાં જેને સત્સંગનો યોગ આવ્યો છે તેનાં દુઃખમાત્ર સદાયને માટે નાશ પામ્યાં છે. માટે સત્સંગ સાચવવાનું જતન કરવું.”","e":"At Gondal, in the residence of Hathisinh Nrup, Shriharí came and sat upon the swing and began to talk: “When one comes and sits in satsang, then the thought of moksha comes into one’s hands. Without the thought of moksha, other thoughts become the cause of boundless dukh. Though one become the lord of swarg, of the mortal realm and of patal, though one obtain a station as high as Brahma or Prakruti-Purush, still no sukh comes to him. For one who, in this fleeting body, has obtained the yog of satsang, every misery has been destroyed for ever. Therefore make every effort to safeguard satsang.”","s":["6/47/11-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":38,"k":"para","g":"જૂનાગઢમાં શ્રીહરિએ નાગરો સમક્ષ સત્સંગનો મહિમા કહેતાં કહ્યું, “સત્સંગ વિના મોક્ષનો અંકુર ક્યારેય ફૂટતો નથી. કોઠીમાં અનાજ કરોડ વરસ સુધી ભર્યું રહે, પણ પૃથ્વી અને જળના યોગ સિવાય તેમાં ક્યારેય અંકુર ફૂટે નહિ. તેમ કોઈ કાર્ય યોગ વિના બનતું નથી, આજે અથવા અનંત જન્મ પછી પણ, યોગ મેળવ્યા સિવાય કામ થવાનું નથી. સત્સંગ થાય ને સંતનાં દર્શન થાય એટલો શુભ કાળ, એ વિના બધો અશુભ કાળ છે. સત્સંગ કરવાથી જીવ બીજી જ રીતનો થઈ જાય છે, નિર્મળતા પામે છે. સત્સંગ એ છે કે જ્યાં મોક્ષ સિવાય બીજી કોઈ વાતનો પ્રવેશ ન હોય. જ્યાં હરિકથા-કીર્તન નિત્ય થતાં હોય. જગતના વિષયોને જ્યાં સ્થાન ન હોય. ભગવાનનાં ચરણકમળમાં સહજે અનુરાગ થાય. ભગવાનનું વિસ્મરણ કરાવે એ બધો કુસંગ છે. ભગવાન સિવાય બીજામાં રુચિ થાય તે પણ કુસંગ છે. ભગવાનમાં મન જોડાવે તે સત્સંગ સમજવો. ભગવાન મેં મન ચોંટાવે જેહિ, સત્સંગ સો સમઝનો તેહિ.”","e":"At Junagadh, telling the mahima of satsang before the Nagars, Shriharí said, “Without satsang the sprout of moksha never breaks forth. Grain may lie filled in a jar for a crore of years, but without the conjunction of earth and water it will never sprout in it. In the same way no work comes about without the right conjunction; whether today or after infinite births, without obtaining that conjunction the work is not going to be done. Only so much time is auspicious as satsang takes place and one has the darshan of the Sant; apart from that, all time is inauspicious. By doing satsang the jiva becomes of an altogether different kind; it attains purity. Satsang is that in which nothing but moksha has any entry; where hari-katha and kirtan take place daily; where the vishays of the world have no place; where love arises of itself for the lotus feet of Bhagwan. Everything that makes one forget Bhagwan is kusang. A liking that arises for anything other than Bhagwan is also kusang. Know that to be satsang which joins the mind to Bhagwan. Bhagwān mem man chontāve jehi, satsang so samajhno tehi. [That which fastens the mind upon Bhagwan — know that to be satsang.]”","s":["6/77/21-29"],"sv":[],"mt":false,"gl":null,"a":false},{"i":39,"k":"para","g":"બાબરાના ગ્રામજનોને વાત કરતાં શ્રીહરિએ કહ્યું, “જે સત્સંગ કરે છે તેનાં સઘળાં પાપ નાશ પામે છે. ભગવાન વિના બીજી જે કંઈ રુચિ થાય છે તે પાપ છે. સત્પુરુષના સંગમાં એ પાપ ટળે છે. એ સિવાય તેને ટાળવાનો બીજો ઉપાય નથી. ભગવાન વિના બીજો સંકલ્પ ઊઠે તે પાપ વાસના છે. હરિજનનો એ મત છે.”","e":"While talking to the villagers of Babra, Shriharí said, “All the sins of one who does satsang are destroyed. Whatever liking arises for anything other than Bhagwan is sin. In the company of the Satpurush that sin is dispelled. Apart from that there is no other means of dispelling it. Any sankalp that arises other than for Bhagwan is a sinful vasana. That is the conviction of a harijan.”","s":["6/91/12-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":40,"k":"para","g":"ભૂજમાં શ્રીહરિ કહે, “સત્સંગ કરાવવામાં પણ કળા છે. શુક, સનકાદિક અને નારદ તથા મોટા મોટા રાજાઓએ જે રીતે સત્સંગ કર્યો તે રીત દેખાડે ત્યારે સામાને સત્સંગ થાય. સત્સંગ કરતાં કરતાં હરિમાં જ્યારે મૂળ ચોંટે અને કોટિ કષ્ટ પડે, પરંતુ સત્સંગ મટે નહિ, પણ અધિક ઉત્સાહ થાય તે જ સંત અને હરિજનોમાં શિરોમણિ કહેવાય.”","e":"At Bhuj, Shriharí said, “There is an art even in bringing another to satsang. Only when one shows the way in which Shuk, the Sanakadik, Narad and the great kings did satsang does satsang come about for the other. If, while doing satsang, one’s root fastens upon Hari, and though a crore of hardships fall satsang is not broken but the enthusiasm becomes greater — he alone is called the crown jewel among the Sants and harijans.”","s":["7/9/26-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":41,"k":"para","g":"શ્રીનગરમાં શ્રીહરિએ હરિજનો પાસે વાત કરતાં કહ્યું, “અનંતકોટિ બ્રહ્માંડનાં સુખ સત્સંગ આગળ લૂખાં છે. સત્સંગથી એવું ફળ મળે છે કે ક્યારેય ભિખારી થવું પડે નહિ. સંસારનાં મિથ્યા સુખ માટે કરોડો દુઃખ સહન કરાય છે, તેમ સત્સંગ કરવામાં દુઃખ પડે તો આનંદથી સહન કરવાં. હરિની સાથે અચલ સ્નેહ કરે તે સમાન જગતમાં કોઈ હરિભક્ત નથી. સત્સંગના આશ્રય વિના સંસારમાં રહીને તેનાથી ન્યારું રહી શકાય નહિ. જેણે સત્સંગ વિના બીજા કોઈને વહાલા રાખ્યા નથી તે સંસારમાં રહેવા છતાં લોપાતા નથી.”","e":"At Shrinagar, while talking before the harijans, Shriharí said, “The sukhs of infinite crores of brahmands are insipid before satsang. From satsang such fruit is obtained that one never has to become a beggar. For the false sukh of sansar a crore of miseries are borne; in the same way, if misery falls in doing satsang, bear it with joy. There is no haribhakta in the world equal to one who forms unshakeable love with Hari. Without the asharo of satsang, one cannot live in sansar and remain apart from it. One who has held no one dear except satsang is not swallowed up, even while living in sansar.”","s":["8/4/17-32"],"sv":["अनंतकोटि ब्रह्मांड को सुखा । सत्संग आगे कहत सब लूखा ॥\n\n सत्संग में मिलत फल भारी । कबहु न होवत कोई भिखारी ॥\n\n सत्संग करे में परे दुःख हिता । आनंद में निगमना तेता ॥\n\n मिथ्या संसार सुख के हिता । कोटि दुःख जन करत सहिता ॥\n\n हरिजन सम जग में न केहा । निश्चल हरि सें कियेउ नेहा ॥\n\n संसार में रहि तिन से न्यारे । सत्संग विन और रखे न प्यारे ॥"],"mt":false,"gl":null,"a":false},{"i":42,"k":"para","g":"શ્રીહરિએ હરિભક્તો પ્રત્યે પત્રમાં લખ્યું, “સત્સંગની મોટપ અપાર છે. ભવબ્રહ્માદિક દેવો પણ આવો સત્સંગ વારંવાર માગ્યા કરે છે, પણ તેને મળવો દુર્લભ છે. સત્સંગનો માર્ગ છોડીને જીવ જગતના નોરે ચાલે તો તેને શિરેથી ક્યારેય નર્ક-ચોરાસી ટળતી નથી. જગતની રીતમાં વર્તતાં અનંત કાળ ગયા પણ ભક્ત ન થયા ત્યાં સુધી દુઃખ રહે છે. ભક્ત થયા પછી જો જગતની રીતે વર્તે તેને કદાપિ દુઃખ ટળે નહિ. બ્રહ્માના સુખ આગળ કીટનું સુખ શા લેખામાં? જીવને અનંતપુણ્ય પછી બ્રહ્માનું સુખ મળ્યું તોપણ સત્સંગના સુખ આગળ તે કીટ સમાન છે. ભગવાનના સુખ આગળ બીજાનાં સુખ તુચ્છ છે, છતાં એવાં સુખની વાંછના મનમાં રહેતી હોય તો ભક્ત થયો હોય, તોપણ તેનો કીટપણાનો સ્વભાવ ટળ્યો નથી, એમ જાણવું. અમારે તો સૌ હરિજનને બ્રહ્મરૂપ કરવા છે એટલો જ મનમાં વિચાર રહ્યા કરે છે. તે માટે વિચરીએ છીએ. અમે જે કંઈ ચરિત્ર કરીએ છીએ તે પાછળ પણ જીવને બ્રહ્મરૂપ કરવાનું તાન છે.","e":"Shriharí wrote in a letter to the haribhaktas, “The greatness of satsang is boundless. Devas such as Bhav and Brahma too ask again and again for such satsang, but for them it is hard to obtain. If a jiva leaves the path of satsang and walks in the fashion of the world, then hell and the eighty-four lakh births are never lifted from his head. Infinite ages have passed in behaving after the fashion of the world, and as long as one did not become a bhakta, misery remained. And if, having become a bhakta, one behaves after the fashion of the world, his misery will never be dispelled. Before the sukh of Brahma, of what account is the sukh of a worm? Though the jiva obtained the sukh of Brahma after infinite punya, before the sukh of satsang it is like a worm’s. Before the sukh of Bhagwan other sukhs are trifling; yet if a craving for such sukhs still remains in the mind, then know that though he has become a bhakta, his worm-like swabhav has not been dispelled. As for Us, this alone remains in Our mind — that We wish to make all the harijans brahmarup. It is for that that We travel. Whatever charitras We perform, behind them too is the yearning to make the jiva brahmarup.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":43,"k":"para","g":"“અમને જેવા જાણશે તેવું સુખ તેને મળશે.” આમ, કાગળ લખીને હરિજનો પર મોકલ્યો ને લખ્યું કે “આ કાગળને પ્રાણપ્રિય કરીને રાખજો.”","e":"“Whoever knows Us as We are will receive sukh accordingly.” Having written the letter thus, He sent it to the harijans, and wrote, “Keep this letter as dear as life.”","s":["8/20/29-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":44,"k":"para","g":"પીજમાં ઝવેરીદાસના ભવનમાં શ્રીહરિએ વાત કરતાં કહ્યું, “સંતો-હરિજનો અલૌકિક છે. તેમાં કોઈક દૈહિક દોષ જણાય તો ક્યારેય તેનો અભાવ ન લેવો. જો અભાવ લે તો તેનું ફળ અવશ્ય ભોગવવું પડે છે. સંતો બ્રહ્માગ્નિ છે. લીલું-સૂકું જે તેનો સ્પર્શ કરે તે બળી જાય. જે સંતો અને હરિભક્તો સત્સંગના પાંચ નિયમ-વર્તમાન દૃઢ કરીને રાખતા હોય, તે જ ખરા આશ્રિત છે, જે આ નિયમ નથી રાખતા તેને વિમુખ જાણવા. જો તે વ્રતભંગનું પ્રાયશ્ચિત્ત કરે તો તેને વિમુખ ન કહેવો. પ્રાયશ્ચિત્ત પૂરું થાય ત્યાં સુધી તેનું જતન કરવું.”","e":"At Pij, in the residence of Zaverídas, while talking, Shriharí said, “The Sants and harijans are alaukik. If some bodily flaw be noticed in one of them, never take abhav towards him. If one does take abhav, its fruit must certainly be borne. The Sants are brahmagni. Whatever touches it, green or dry, is burnt away. Only those Sants and haribhaktas who keep firm the five niyams — the vartman — of satsang are the true ashrits; those who do not keep these niyams should be known as vimukh. If such a one performs prayashchit for the breaking of his vow, then he should not be called vimukh. Until the prayashchit is complete, he should be looked after.”","s":["8/38(37)/22-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":45,"k":"para","g":"પીજમાં શ્રીહરિએ કહ્યું, “સત્સંગ મળ્યો એ ભવસાગરનો કાંઠો છે, તેમાં સાવધાનપણે રહેવું. તીર્થ, જપ, તપ કરે તોપણ ભવથી છૂટાય નહીં. છૂટવાનું એક જ દ્વાર છે સત્સંગ. સત્સંગ વિના કોટિ ઉપાયે પણ, બ્રહ્મલોક સુધી પહોંચે તોપણ ભવનો રોગ મટે તેમ નથી, સત્સંગ મળ્યા પછી દેહ, ઇન્દ્રિયો અંતઃકરણને સત્સંગના નિયમમાં રાખવાં અને મોક્ષરૂપી આહારની લાલચ આપી વિષયમાંથી પાછાં વાળવાં...”","e":"At Pij, Shriharí said, “To have obtained satsang is to have reached the shore of the ocean of birth and death; remain within it attentively. Though one perform pilgrimage, japa and tapa, one is not freed from birth and death. There is one door alone to freedom, and that is satsang. Without satsang, by a crore of means, and though one reach as far as Brahmalok, the disease of birth and death is not to be cured. Having obtained satsang, keep the body, the indriyas and the antahkaran within the niyams of satsang, and turn them back from the vishays by holding out to them the lure of the food that is moksha…”","s":["8/38(37)/31-37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":46,"k":"para","g":"શ્રીહરિએ અલર્ક રાજાને વાત કરતાં કહ્યું, “સત્સંગ કરતાં થકા દોષોની સદા બીક રાખવી ને મનનો વિશ્વાસ ન કરવો, કારણ કે મનનો જેટલો વિશ્વાસ કરે તેટલો સત્સંગ નાશ થાય, ઇન્દ્રિયો પણ બંધન તોડીને પોતપોતાના ચારામાં ચાલી જાય છે. ચારા વિના ચાલે નહિ એવો તેનો સ્વભાવ છે.”","e":"While talking to King Alark, Shriharí said, “While doing satsang, always keep a fear of the doshas and do not trust the mind; because as much as one trusts the mind, that much is satsang destroyed. The indriyas too break their bonds and run off, each to its own pasture. Such is their nature, that without their pasture they cannot manage.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":47,"k":"para","g":"ભગવાનમાં અપાર રસ રહેલો છે, પણ તે તેને ખારો લાગે છે અને જગતના રસમાં સોમલ કરતાં પણ વધારે વિષ રહેલું છે, તે તેને અમૃત જેવો લાગે છે. જ્યારે ભગવાનમાં રસ જણાય ત્યારે સત્સંગ થયો કહેવાય, જાગ્રતમાં જેવો સત્સંગનો દૃઢાવ રહે, તેવો જ સ્વપ્નમાં પણ રહે તેનો દૃઢ સત્સંગ કહેવાય. તોપણ મનનો વિશ્વાસ નહિ કરી હરિભક્તનો દાસ થઈને રહે તે બુદ્ધિમાન છે. દાસને ક્યારેય દુઃખ હોતું નથી. મોટાને જ દુઃખ હોય છે, કારણ કે તેમાં જેટલું માન હોય તેટલું દુઃખ થાય છે.”","e":"Boundless rasa resides in Bhagwan, but to him it tastes brackish; and in the rasa of the world there is poison greater even than somal, and to him it tastes like nectar. When rasa is felt in Bhagwan, then satsang is said to have come about. He whose firmness in satsang remains in dream just as it remains in the waking state — his satsang is called firm. Even so, he is wise who does not trust the mind and remains the das of the haribhaktas. A das never has misery. Only the great have misery, because however much maan there is in a man, that much misery comes to him.”","s":["9/43/7-15"],"sv":[],"mt":false,"gl":null,"a":false},{"i":48,"k":"para","g":"શ્રીહરિએ અલર્ક રાજાને નિષ્કામવ્રતની દૃઢતા અંગે વાત કરતાં કહ્યું, “જેનામાં નિષ્કામવ્રત નથી તે અમને પશુ જેવો લાગે છે. બ્રહ્મા ભવ જેવા દેવતાઓ બ્રહ્માંડોની સમૃદ્ધિ લાવીને આપે તોપણ તે નિષ્કામવ્રત પાસે તુચ્છ છે. ભગવાનને પ્રસન્ન કરવાના સાધનમાં આ એક મુખ્ય સાધન છે. સત્સંગથી જેવી મતિ થાય તેવી અષ્ટાંગયોગથી પણ ન થાય. બીજાં બધાંય સાધનનું ફળ તે સત્સંગ છે. સત્સંગમાં દંભથી ચાલે તે પાર ન પડે, અને અતિ દંભી હોય તે વિમુખ થઈને સત્સંગની દેશી કાઢે, અને સત્સંગની વાત શીખીને વિમુખ જીવને ધૂતે, એમ સત્સંગ તજીને જે સત્સંગનો દ્રોહ કરે તે કૃતઘ્નીમાં કૃતઘ્ની, ચાંડાળમાં ચાંડાળ અને નીચમાં નીચ છે. જાણીને પોતાનું માન વધારવા સત્સંગનો દ્રોહ કરે તેનું તો માન ભંગ થાય છે.”","e":"While speaking to King Alark about firmness in the nishkam vrat, Shriharí said, “One in whom there is no nishkam vrat appears to Us like an animal. Though devatas such as Brahma and Bhav should bring and offer the riches of the brahmands, they are trifling before the nishkam vrat. Among the means of pleasing Bhagwan this is one principal means. The understanding that comes from satsang does not come even from ashtang yoga. The fruit of all other means is satsang itself. One who moves in satsang with hypocrisy does not come through; and one who is utterly hypocritical becomes vimukh and mocks the ways of satsang, and having learnt the talk of satsang, cheats vimukh jivas. Thus one who forsakes satsang and commits droh against satsang is the most ungrateful of the ungrateful, the basest of the base, the lowest of the low. And one who knowingly commits droh against satsang in order to increase his own maan — his maan is broken.”","s":["9/45/3-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":49,"k":"para","g":"ગઢપુરમાં જીવેન્દ્ર નૃપને શ્રીહરિએ વાત કરતાં કહ્યું, “સત્સંગ ન મળે ત્યાં સુધી અનંત બ્રહ્માંડનો રાજા હોય તોપણ તેનું જીવન અલેખે છે. સત્સંગ વિના બીજા સુખની ચાહના છે ત્યાં સુધી મનુષ્યતન મળ્યું જ નથી એમ સમજવું. સત્સંગ કરતાં જો અનંત અપાર સુખની પ્રાપ્તિ થાય તો તેને બુદ્ધિવાળો માણસ દુઃખરૂપ માને છે. અને તે જ પાકો ભક્ત છે. બીજા બાળકબુદ્ધિ છે.”","e":"At Gadhpur, while talking to Jivendra Nrup, Shriharí said, “Until satsang is obtained, though a man be king of infinite brahmands, his life is of no account. As long as there is a craving for sukh other than satsang, understand that the human body has not been obtained at all. If, in doing satsang, boundless and infinite sukh should be attained, a man of intelligence regards even that as a form of misery. And he alone is the mature bhakta. The rest are of a child’s intellect.”","s":["10/5/22-30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":50,"k":"para","g":"માંડવીમાં મેઘજી સુથારને ત્યાં શ્રીહરિએ વાત કરતાં કહ્યું, “તમારા ભાગ્યનો પાર નથી. ભવબ્રહ્માદિક દેવો પણ જેને ઇચ્છે છે તેવો સત્સંગ તમને મળ્યો છે. પ્રકૃતિપુરુષ આગળ ભવબ્રહ્માની સ્થિતિ, સૂર્ય આગળ પતંગિયા જેવી છે. અક્ષરબ્રહ્મ આગળ પુરુષપ્રકૃતિ પતંગિયા જેવાં છે. તે સૌ સત્સંગને ઇચ્છે છે. નારદ, શુક, સનકાદિક પણ નિશદિન સત્સંગને ચાહે છે. એવા સત્સંગ ઉપર જેને ભાવ ન થાય તે માણસ ચતુર હોય તોપણ એના જેવો કોઈ આંધળો કે બહેરો નથી. જેને સત્સંગ થયો છે, તે તો અક્ષરધામનો અધિકારી છે.’","e":"At Mandvi, at the home of Meghji Suthar, while talking, Shriharí said, “There is no limit to your fortune. You have obtained that satsang which devas such as Bhav and Brahma desire. Before Prakruti-Purush the state of Bhav and Brahma is as that of a moth before the sun. Before Aksharbrahman, Purush and Prakruti are like moths. They all desire satsang. Narad, Shuk and the Sanakadik too long for satsang night and day. One in whom no feeling arises for such satsang — though he be clever, there is none so blind or so deaf as he. One who has obtained satsang is entitled to Akshardham.”","s":["10/27/15-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":51,"k":"para","g":"ભૂજમાં શ્રીહરિએ હિંડોળામાં બેસી હરિજનો પ્રત્યે વાત કરતાં કહ્યું, “પ્રગટ અગ્નિ હોય તે કાષ્ઠના યોગ વિના રહી શકે નહિ. ચાતુર્માસમાં મેઘના જોરથી સરોવર ભરાય છે, પણ મેઘનો વિયોગ થતાં ખૂટવા લાગે છે. મશાલ પણ તેલ વિના બુઝાઈ જાય છે. મશાલ, અગ્નિ ને સરોવરને ઠેકાણે હરિભક્તો જાણવા ને તેલ, કાષ્ઠ ને મેઘને ઠેકાણે સંતો જાણવા. સંતોનો યોગ જેમ વધુ રહે તેમ કરવું. સંતોનો અધિક વિયોગ થાય તો સત્સંગનું ઠેકાણું રહે નહિ. બહુ જોગ થાય તો પણ બહુ ભાવ રહે નહિ. એ તો લોકનો સહજ સ્વભાવ છે. સંતનો બહુ જોગ હોવા છતાં તેમાં ભાવ રહે તો તેને મુક્ત જીવ સમજવો. અલૌકિક બુદ્ધિ હોય ત્યાં સુધી સંતનો અભાવ ન આવે.”","e":"At Bhuj, seated upon the swing, while talking before the harijans, Shriharí said, “A burning fire cannot remain without the conjunction of wood. In the four months of the monsoon the lake is filled by the force of the clouds, but when the clouds are gone it begins to run dry. A torch too is extinguished without oil. Know the haribhaktas to stand in the place of the torch, the fire and the lake, and know the Sants to stand in the place of the oil, the wood and the clouds. Act so that the yog of the Sants remains as much as may be. If separation from the Sants is great, satsang will have no foundation. And yet if there is very much company, much feeling does not remain either. That is simply the way of people. If, despite much company of the Sant, feeling still remains, know him to be a liberated jiva. As long as one’s intellect is alaukik, no abhav towards the Sant will come.”","s":["10/33/27-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":52,"k":"para","g":"ભૂજમાં શ્રીહરિ કહે, “ભગવાન અને સંતને દેખીને ભાવ ન થાય તેને નપુંસક જાણવો ને પાષાણ હૃદયનો જાણવો. અતિવિષયી જીવ હોય પણ જો તેને સત્સંગમાં ચિત્ત ચોંટે તો નિર્વિષયી થઈ જાય, અને જેવો વિષયી હોય તેવો જ સત્સંગી થાય. જીવને બંધનરૂપ તો અનંત વિષયો છે. તેમાંથી છોડાવે તેવો તો સત્સંગ છે. તે સારમાં સાર અને દુર્લભમાં દુર્લભ છે. તેના વિષયી તો પ્રિયવ્રત, જનક, પ્રહ્‌લાદ, ચિત્રકેતુ, બલિ વગેરે ઘણા થઈ ગયા છે.”","e":"At Bhuj, Shriharí said, “Know one in whom no feeling arises on seeing Bhagwan and the Sant to be impotent, and to be of a heart of stone. A jiva may be intensely given to the vishays, but if his chitt fastens upon satsang he becomes free of the vishays; and he becomes as strong a satsangi as he was given to the vishays. The vishays that bind the jiva are infinite. Satsang is what frees him from them. It is the essence of essences and the rarest of the rare. Of those given to it there have been many — Priyavrat, Janak, Prahlad, Chitraketu, Bali and others.”","s":["10/48/35-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":53,"k":"para","g":"મુક્તમુનિએ શ્રીહરિની કહેલી વાત કરતાં કહ્યું કે, “શ્રીહરિ કહેતા - ગિરનાર ચડ્યા ત્યારે ગિરિ અને વૃક્ષો જોઈને જાણે સદા અહીંયાં રહીએ એમ મનમાં થાય છે. પ્રવૃત્તિ ગમતી નથી, પરંતુ જ્યારે શિવનાં વચન સાંભળીએ છીએ ત્યારે સત્સંગ છોડી શકાતો નથી. સત્સંગની સેવા તે ધ્યાન અને તપ કરતાં અધિક છે. કોટિ વરસનાં તપ અને ધ્યાનથી જે ફળ થાય તે એક દિવસની સત્સંગ સેવામાં સમાઈ જાય છે. તેવો વિચાર કરીએ છીએ ત્યારે સત્સંગ વિના બધું ખારું લાગે છે. પ્રિયવ્રત રાજાએ રાજ્ય કરવામાં પ્રવૃત્તિ જાણી અને નિવૃત્તિ લઈને પર્વતમાં તપ કરવા બેઠા. પિતા સ્વાયંભૂ મનુ ઉદાસ થયા. પ્રિયવ્રત નારદના શિષ્ય હતા તેથી તેને નારદજીએ તેડાવ્યા. બન્નેએ તેને ઉપદેશ આપ્યો.","e":"Muktamuni, relating a talk spoken by Shriharí, said, “Shriharí used to say — when We climbed Girnar, seeing the mountain and the trees it came into Our mind that We might stay here for ever. Pravrutti is not to Our liking; but when We hear the words of Shiv, satsang cannot be forsaken. The seva of satsang is greater than dhyan and tapa. The fruit that comes of a crore of years of tapa and dhyan is contained within a single day’s seva of satsang. When We reflect thus, everything without satsang tastes brackish. King Priyavrat knew the ruling of a kingdom to be pravrutti, and taking to nivrutti he sat in the mountains to perform tapa. His father Swayambhuv Manu became dejected. Priyavrat was a disciple of Narad, and so Naradji was sent for. The two of them gave him upadesh.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":54,"k":"para","g":"“બ્રહ્મા કહે, અમે ને નારદજી ભગવાનના વચનમાં વર્તીએ છીએ. ભગવાન પ્રસન્ન થાય તેમ કરવું તેનું નામ નિવૃત્તિમાર્ગ છે. અંતઃશત્રુ જિતાયા ન હોય ત્યાં સુધી નિવૃત્ત ગણાય નહિ, અને તે શત્રુઓ સાથે રહેલા હોવાથી તપ કરવા જાય તોપણ વિઘ્ન થયા વિના રહે નહિ. એ બળવાન છે. નારદનું મુખ પણ તેમણે મર્કટના જેવું કર્યું. શિવ સમાન કોઈ જોગી નથી અને હું તો નારદ અને શિવનો પિતા છું. પરાશર, જૈમિનિ, ઇન્દ્ર, ચંદ્ર, સૌભરિ, ચ્યવન, શૃંગી વગેરે સમર્થ પુરુષોનાં મન પણ ઠેકાણે રહે નહિ. માટે અંતઃશત્રુ જેવી રીતે વશમાં થાય તેવી રીતે ઘરમાં રહીને શીખવું. એમ કહી બ્રહ્માએ નારદ દ્વારા પ્રિયવ્રતને મનાવ્યા ને સત્સંગમાં જોડ્યા.","e":"“Brahma said: We and Naradji abide by the word of Bhagwan. To act so that Bhagwan is pleased — that is what is called the path of nivrutti. As long as the inner enemies have not been conquered, one is not counted as having renounced; and since those enemies remain with him, though he go to perform tapa, obstacles will not fail to arise. They are powerful. They made even Narad’s face like a monkey’s. There is no yogi equal to Shiv, and I am the father of both Narad and Shiv. The minds even of capable men such as Parashar, Jaimini, Indra, Chandra, Saubhari, Chyavan and Shrungi did not stay in place. Therefore learn, while remaining in the household, the way in which the inner enemies may be brought under control. Saying this, Brahma, through Narad, persuaded Priyavrat and joined him to satsang.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":55,"k":"para","g":"“રામાનંદ સ્વામી અમને વચનરૂપી દોરીએ બાંધી ગયા છે. અને બધાં સાધનો કરતાં સત્સંગ અધિક દેખાડ્યો છે. તે સિવાય રસને છોડી કૂચા ખાવા જેવું છે. સત્સંગથી જ મનોવાંછિત સુખ મનાય છે, પણ ધીરજ તજી દે તે દુઃખી થાય છે. દુઃખ દેખી ડગે નહિ તેનો સત્સંગ સાચો છે.”","e":"“Ramanand Swami has bound Us with the cord of his word. And he showed satsang to be greater than all other means. Apart from it, it is like leaving the juice and eating the husk. Through satsang alone is the sukh one wishes for realised; but one who abandons patience becomes miserable. He whose satsang does not waver at the sight of dukh — his satsang is true.”","s":["11/52/30-40, 53/1-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":56,"k":"para","g":"મુકુન્દવર્ણી પ્રત્યે શ્રીહરિએ કહ્યું, “એક દિવસ પણ જેણે સત્સંગ કર્યો તે ચોરાશીમાં જતો નથી, હરિભક્ત નામ પડ્યું તેને જમપુરીનું દુઃખ રહેતું નથી. ભગવાન અને ભગવાનના સંતનો જેને વિશ્વાસ હોય, તેને ભગવાન કષ્ટ પડવા દેતા નથી. જેવી સમજણ તેવો મોક્ષ થાય છે.”","e":"To Mukundvarni, Shriharí said, “One who has done satsang for even a single day does not go into the eighty-four lakh births; upon one who has received the name of haribhakta the misery of Yampuri does not remain. One who has trust in Bhagwan and in the Sant of Bhagwan — Bhagwan does not let hardship fall upon him. As one’s understanding is, so does one’s moksha come about.”","s":["11/60(50-b)34-37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":57,"k":"para","g":"બોટાદમાં શ્રીહરિએ જનો પ્રત્યે કહ્યું, “સમજણમાં જુદાં જુદાં અંગ હોય છે. કુટુંબ જેવો જ્યારે સત્સંગ થાય ત્યારે ડગાય નહિ. જગતમાં સ્ત્રી અને પુરુષ એક ઘરનાં હોતાં નથી, છતાં સ્ત્રી ઘરમાં આવે છે ત્યારે સૌથી અધિક થઈ જાય છે. અને ભિન્ન ભિન્ન દેહ હોવા છતાં તેની સાથે મન એક થઈ જાય છે. પરસ્પર હેત હોય ત્યાં સુધી જીવ બંધાય છે. તેમ સત્સંગમાં હિત મનાય તો જ સત્સંગમાં જીવ બંધાય. સત્સંગમાં મમત્વ બંધાય તો સહજે પક્ષ પણ રહે. પક્ષને માટે માથું કાપવા તૈયાર થવાય, જગતમાં એક દિવસ કોઈએ અન્ન-જળ આપ્યું હોય તો તેનો પણ પક્ષ રહે છે. મર્યા પછી તેનું કાંઈ ફળ નથી, પણ અહીંયાં બે દિવસ વખાણ કરે છે. જો અતિ સ્નેહ રાખવા જાય તો ભૂત-પ્રેત થવાનો પ્રસંગ આવે છે, એવું સત્સંગના પક્ષમાં નથી.”","e":"At Botad, Shriharí said to the people, “In understanding there are different dispositions. When satsang becomes like one’s own family, then one does not waver. In the world a wife and a husband are not of one house, yet when the wife comes into the house she becomes dearer than all; and though their bodies are separate, her mind becomes one with his. As long as there is mutual affection, the jiva is bound. In the same way, only if one’s own good is felt to lie in satsang is the jiva bound to satsang. If a sense of belonging is formed in satsang, then partisanship for it also remains of itself. One becomes ready to have his head cut off for that side. In the world, if someone has given food and water even for a single day, partisanship for him remains. After death there is no fruit of it, but here they praise him for two days. And if one goes so far as to keep excessive attachment, the occasion arises of becoming a bhut or a pret; it is not so in taking the side of satsang.”","s":["11/82(72)/1-22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":58,"k":"para","g":"શ્રીહરિએ પીપલાણામાં હરિજનોને વાત કરતાં કહ્યું, “પ્રગટ ભગવાન મળે કે તે ભગવાનના સંત મળે અથવા તેના કોઈ હરિભક્ત મળે તો તેને સત્સંગનો યોગ થાય છે ને ચોરાશીનો રોગ ટળે છે. અક્ષરધામનું અલૌકિક સુખ પ્રાપ્ત કરવા પ્રગટના સત્સંગ વિના બીજો કોઈ ઉપાય નથી. સંતો-હરિજનોએ આવી વાત બીજાને નિત્ય કરવી.”","e":"At Piplana, while talking to the harijans, Shriharí said, “If one meets the pragat Bhagwan, or meets the Sant of that Bhagwan, or meets any haribhakta of His, then the yog of satsang comes about for him and the disease of the eighty-four lakh births is dispelled. To attain the alaukik sukh of Akshardham there is no other means than the satsang of the pragat. Sants and harijans should tell this talk to others daily.”","s":["12/21(20)/35-36"],"sv":["प्रगट हरि वा संत हि ताके । वा हरिजन कोउ मिलत वाके ॥\n\n तेहि कर सत्संग को होत जोगा । चोराशि जमपुरि भागत रोगा ॥\n\n अलौकिक सुख लहन को जेहु । सत्संग विन उपाय न केहु ॥\n\n हरिजन संत कहावत जेते । एसी वात नित करना तेते ॥"],"mt":false,"gl":null,"a":false},{"i":59,"k":"para","g":"ભૂજમાં શ્રીહરિ કહે, “જગતને સત્સંગ ગમતો નથી. તેની લાજ રાખવા જાય તો સત્સંગ થાય નહિ. જગતને તો જમપુરીમાં જવું છે તેથી સત્સંગ કરતું નથી. મનમુખી થઈ ધર્મ પાળે કે તીર્થવ્રત કરે, પણ સત્સંગ વિના હાથીના સ્નાન જેવું નિરર્થક છે.”","e":"At Bhuj, Shriharí said, “The world does not like satsang. If one goes about preserving the world’s regard, satsang will not come about. The world wishes to go to Yampuri, and therefore it does not do satsang. One may follow dharma after the manner of one’s own mind, or perform pilgrimages and vows, but without satsang it is as useless as an elephant’s bath.”","s":["12/37(36)8-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":60,"k":"para","g":"ભૂજમાં શ્રીહરિએ હરિજનો પ્રત્યે વાત કરતાં કહ્યું, “સત્સંગમાં જેને જેવો ભાવ હોય તેનો તેવો મોક્ષ થાય છે. પ્રીતિ અને ધર્મપાલન વિના મોક્ષ મળતો નથી. જેમ લોભીને ધનમાં ને કામીને સ્ત્રીમાં પ્રીતિ છે તો તેને અર્થે તન-ધન ન્યોછાવર કરવામાં તલભાર વિચાર થતો નથી. સત્સંગમાં આવો ભાવ હોય તો ક્યારેય અભાવ ન આવે. અભાવ આવે તેટલી કસર જાણવી. ભગવાનનો નિશ્ચય ને ધર્મનું પાલન દૃઢ હોય તેનો સત્સંગ દૃઢ જાણવો.","e":"At Bhuj, while talking before the harijans, Shriharí said, “In satsang, as a man’s feeling is, so does his moksha come about. Without priti and the observance of dharma, moksha is not obtained. Just as the greedy man has priti for wealth and the lustful man for a woman, and for its sake there is not a hair’s weight of hesitation in sacrificing body and wealth — if such feeling exists towards satsang, abhav will never come. However much abhav comes, know that much to be the deficiency. Know the satsang of one whose nishchay of Bhagwan and observance of dharma are firm to be firm.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":61,"k":"para","g":"“સ્વરૂપનિષ્ઠા અને ધર્મનિષ્ઠા બેઉ કપડું અને તાર જેવા છે. તાણાવાણા વગર કપડું નથી ને કપડાં વગર તાણાવાણા નથી, તેમ નિશ્ચય અને ધર્મની વાત છે. તે જેટલાં દૃઢ તેટલો સત્સંગ દૃઢ જાણવો. ધર્મ અને નિશ્ચય એ બીજ-વૃક્ષ ન્યાયે રહ્યા છે.”","e":"“Swarupnishtha and dharmanishtha are both like the cloth and the thread. Without warp and weft there is no cloth, and without cloth there is no warp and weft; such is the matter of nishchay and dharma. However firm these two are, know satsang to be that firm. Dharma and nishchay stand in the relation of the seed and the tree.”","s":["12/38(37)7-13"],"sv":[],"mt":false,"gl":null,"a":false},{"i":62,"k":"para","g":"વઢવાણમાં તુલસી દવેના ઘરે વર્ણીએ રસોઈ કરી, શ્રીહરિએ ભોજન લીધું પછી પલંગ ઉપર બિરાજમાન થયા અને વાત કરતાં કહ્યું, “પૂર્વે જેણે સત્સંગ કર્યો છે તેની રીત તપાસ્યા વિના પોતાનો સત્સંગ પરખાય નહીં. સત્સંગની વાતમાં જ્યાં લગી પોતાનો તલભાર વિચાર ન ભળે અને તે નિશદિન અમારી પાસે રહેતો હોય તોપણ તેનું દુઃખ ટળતું નથી. સત્સંગ કરે, પણ વિવેક વગર સુખ આવતું નથી. વિવેક ખડગની ધાર જેવો રાખવો. જેટલો વિવેક એટલું સુખ. વિવેક ન હોય એટલું દુઃખ. નિયમ-મર્યાદાવાળો હોય તેને વિવેકી કહ્યો છે. અનંતકોટી બ્રહ્માડનાં ભોગ-સુખ, દુઃખ વિનાનાં જણાતાં નથી. એવું જાણી ભગવાન જેટલું આપે તેમાં સંતોષ માની મગન રહેવું અને કોઈને દોષ ન દેવો.”","e":"At Wadhwan, at the home of Tulsi Dave, the varni prepared the meal; Shriharí took the food and then sat upon the couch and, while talking, said, “Without examining the way of those who have done satsang before, one’s own satsang cannot be assayed. As long as not a hair’s weight of a man’s own reflection enters into the talk of satsang, then though he stay near Us night and day his misery is not dispelled. One may do satsang, but without vivek sukh does not come. Keep vivek like the edge of a sword. However much vivek, that much sukh; however much vivek is wanting, that much dukh. One who keeps niyam and maryada has been called a man of vivek. The enjoyments and pleasures of infinite crores of brahmands are not found to be free of misery. Knowing this, hold to contentment in whatever Bhagwan gives and remain joyful, and lay no fault upon anyone.”","s":["12/49/3-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":63,"k":"para","g":"ઉમરેઠના વિદ્વાન વિપ્રોને શ્રીહરિએ કહ્યું, “મહિમા વગર સત્સંગ સમજાય નહિ. મહિમા હોય તે સત્સંગમાં દિવસે દિવસે વધે છે. મહિમા વિનાનાં સાધન વૃથા થાય છે. મહિમા વિનાનાં સાધન મેરુ સમાન હોય તોપણ મહિમાએ યુક્ત સાધન બરાબર અણુ જેટલાં થાય નહિ. કરોડો મચ્છર ગરુડ તુલ્ય થઈ શકે નહિ.","e":"To the learned brahmins of Umreth, Shriharí said, “Without mahima, satsang is not understood. One who has mahima grows in satsang day by day. Means without mahima come to nothing. Means without mahima, though they be equal to Meru, do not equal even an atom of a means joined with mahima. A crore of mosquitoes cannot become the equal of a Garud.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":64,"k":"para","g":"“હરિભક્તને પરસ્પર હેત ન હોય તો સાધન અપાર કરે તોપણ ફળ મળતું નથી, બીજાં અંગ નીરોગી હોય, પણ શ્વાસ બંધ થાય તો કોઈ સહાય કરી શકે નહિ તેમ મહિમા વિનાનાં સાધન જાણવાં. મહિમા રસ છે ને સાધન કૂચા છે. મહિમા માયિક જીવને ગમે નહિ, તેને તો માયિક વસ્તુ ગમે. ગીંગો ગોબરમાં ને ગધેડો કૂચામાં જ લોભાય છે. ચિંતામણિનો મહિમા બાળકને નથી, એટલે જ બોરને ચિંતામણિ કરતાં તે અધિક માની બેસે છે. મહિમાયુક્ત ભક્તો માટે જ અમે સત્સંગમાં વારે વારે ફરીએ છીએ.”","e":"“If haribhaktas have no affection for one another, then though they perform boundless means, no fruit is obtained. Though the other limbs be free of disease, if the breath stops no one can render help — know means without mahima to be like that. Mahima is the juice and the means are the husk. Mahima is not to the liking of a mayik jiva; what he likes is mayik things. The dung-beetle is drawn only to dung and the donkey only to husks. A child has no sense of the mahima of a chintamani, and for that very reason it sets a jujube above a chintamani. It is for the sake of bhaktas endowed with mahima that We travel again and again through satsang.”","s":["12/56/10-30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":65,"k":"para","g":"નાગર સેનાપતિ કરિયાણામાં દેહાખાચરના ભવનમાં શ્રીહરિનાં દર્શને આવ્યો. શ્રીહરિએ ઉપદેશ આપતાં તેને કહ્યું, “મોક્ષના જેટલા સિદ્ધાંત છે કે જેટલા ગ્રંથમાં મોક્ષ માટે લખેલું છે તે સઘળું સત્સંગ કરવામાં સમાઈ જાય છે. સત્સંગ સિવાય બીજે મૃગતૃષ્ણા પાણી છે. સત્સંગમાં સાચું નીર રહેલું છે, જેને પીવાથી શાંતિ થાય છે. મૃગજળ પાછળ જિંદગી ખર્ચે તોપણ તેમાંથી મૃત્યુ પર્યંત દુઃખ નીપજે છે. સત્સંગમાં આવીને પણ જેને શાંતિ થતી નથી તેને પૂર્વેનો સંતનો દ્રોહી સમજવો અને શાપિત જાણવો. અનંત જન્મનાં સુકૃત ઉદય થાય તેને જ સત્સંગ મળે છે.”","e":"The Nagar senapati came at Kariyani, in the residence of Deha Khachar, for the darshan of Shriharí. Giving him upadesh, Shriharí said, “All the doctrines there are concerning moksha, and all that is written in the scriptures for the sake of moksha, are contained within the doing of satsang. Apart from satsang, everywhere else is the water of a mirage. In satsang there is true water, by the drinking of which peace comes. Though one spend his life running after a mirage, from it nothing but misery is produced until death. Know one who finds no peace even after coming into satsang to have been a committer of droh against the Sant in the past, and to be under a curse. He alone obtains satsang whose good deeds of infinite births have come to fruition.”","s":["13/31/34-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":66,"k":"para","g":"ગઢપુરમાં જીવેન્દ્ર નૃપના ભવનમાં શ્રીહરિએ હરિજનો પ્રત્યે વાત કરતાં કહ્યું, “અપાર જન્મોનું બંધન સત્સંગ કરવાથી દૂર થાય છે. જે લોકો યજ્ઞ, દાન, પુણ્ય, તીર્થ, વ્રત અતિ નિષ્કામભાવે કરે છે તેમને સત્સંગ થાય છે. માટે સત્સંગ સર્વથી શ્રેષ્ઠ છે. સંસારમાં સુખ મનાય છે ત્યાં સુધી સત્સંગ પૂરો સમજાયો નથી.”","e":"At Gadhpur, in the residence of Jivendra Nrup, while talking before the harijans, Shriharí said, “The bondage of boundless births is removed by doing satsang. Those who perform yagna, charity, punya, pilgrimage and vows with intense nishkam bhav obtain satsang. Therefore satsang is the highest of all. As long as sukh is taken to lie in sansar, satsang has not been fully understood.”","s":["13/67/1-7"],"sv":[],"mt":false,"gl":null,"a":false},{"i":67,"k":"para","g":"શ્રીહરિએ ગુડેલ ગામના હરિજનો પાસે વાત કરતાં કહ્યું, “કોટિ તીર્થ કરે તોપણ આવો સત્સંગ ન મળે. શિવ, બ્રહ્મા જેવા સત્સંગને ઇચ્છે છે, માટે કઠણ દેશકાળમાં પણ સત્સંગ તજવો નહિ. અનેકવાર ઇન્દ્ર, બ્રહ્માના દેહ મળ્યા હશે, પણ સત્સંગ મળ્યો નથી. જેવો સત્સંગ હોય તેવા જ ભક્તિ-ધર્માદિ ગુણો રહે છે. જ્યાં ધર્મ, જ્ઞાન, વૈરાગ્ય, ભક્તિ રહ્યાં છે ત્યાં શુભ નિયમો રહ્યા છે. સત્સંગ પણ ત્યાં છે ને શ્રીહરિ, અવતારો, સંતો સર્વે ત્યાં છે. આવી દૃઢ સમજણ જ્યારે થાય ત્યારે અખંડ આનંદ રહે. સત્સંગ ખરો એ જ છે કે જેને પામીને જીવ ક્યારેય કંગાલ ન રહે. જગસુખ દેખી તેને પામવા ઇચ્છે નહિ.”","e":"While talking before the harijans of the village of Gudel, Shriharí said, “Though one perform a crore of pilgrimages, such satsang is not obtained. Shiv and Brahma desire satsang; therefore do not forsake satsang even in a hard place and time. The bodies of Indra and Brahma may have been obtained many times over, but satsang has not been obtained. As one’s satsang is, so do the virtues of bhakti, dharma and the rest remain. Where dharma, gnan, vairagya and bhakti abide, there the auspicious niyams abide. Satsang too is there, and Shriharí, the avatars and the Sants are all there. When such firm understanding comes, then unbroken bliss remains. True satsang is that which, once attained, leaves the jiva never destitute. Seeing the sukh of the world, he does not wish to obtain it.”","s":["14/40/33-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":68,"k":"para","g":"બુધેજ ગામમાં શ્રીહરિએ વાત કરતાં કહ્યું, “અસતનો ત્યાગ કરવો ને સતનું સેવન કરવું તેનું નામ સત્સંગ છે. ધર્મ, જ્ઞાન, વૈરાગ્ય, ભક્તિ-એકાંતિક ધર્મ તથા ભગવાને આપેલા ભક્તોના નિયમો - એ સત છે. ભગવાનનાં અવતારો, ચરિત્રો, લીલાઓ, વિચરણ, ઉપદેશ એ બધું સત છે. ભગવાનનો સંબંધ જેને થયો તે સત છે. તીર્થો ને વ્રતોમાં ભગવાનનો સંબંધ હોય તો તે સત છે. આમ, સતનો સંગ તે સત્સંગ છે. ભગવાનનો સંબંધ જેને થયો છે તેને અસત જે કહે છે તે મોટા સત્સંગી જણાતા હોય તોપણ તે અસુરના રાજા છે. વળી, બીજા સંતથી પોતાનાં ધર્મ-નિયમ, ત્યાગ, ભક્તિ, જ્ઞાન અને ધ્યાન વધારે ઉત્કૃષ્ટ દેખાતાં હોય, પણ પોતાનું પ્રતિપાદન કરે તેવા સંતના ગુણ ગાય અને બીજાના અવગુણ ગાય એવા સંત-હરિભક્તોને કાળનેમિ દૈત્ય જેવા જાણવા. નિર્મળ સંતો-હરિજનો સરળ સ્વભાવે વર્તે છે.”","e":"In the village of Budhej, while talking, Shriharí said, “To forsake the asat and to serve the sat — that is what is called satsang. Dharma, gnan, vairagya, bhakti — ekantik dharma — and the niyams given by Bhagwan to His bhaktas: these are sat. The avatars of Bhagwan, His charitras, His lilas, His travels, His upadesh — all this is sat. One who has obtained a relationship with Bhagwan is sat. If there is a relationship with Bhagwan in pilgrimages and vows, then they too are sat. Thus, the sang of the sat is satsang. One who calls a person who has obtained a relationship with Bhagwan asat — though he appear to be a great satsangi — is a king among demons. Again, one’s own dharma-niyam, tyag, bhakti, gnan and dhyan may appear more excellent than another Sant’s; but those Sants and haribhaktas who sing the virtues of the Sant who upholds their own position and sing the faults of others should be known to be like the demon Kalnemi. Pure Sants and harijans conduct themselves with a simple nature.”","s":["14/42/27-36"],"sv":["असत हि करना त्याग, सत को रखना जोग हि ।\n\n तेसे जन बड भाग, सत्संग कहत ताहि कुं ।\n\n हरि हरि के जन जोउ, धर्म नियम जो जे ते तेउ ।\n\n भक्ति ज्ञान जो सोउ, वैराग्य जो सत हि कहत ॥\n\n श्रीहरि के संबंध कर जेहा । जितने तीर्थ व्रत रहे तेहा ॥\n\n सत करिके ताहि कुं कहेना । असत हें कबु न उचरना बेना ॥\n\n हरि के संबंध भये जो जाकुं । असत करि सो कहत हें ताकुं ॥\n\n सत्संग में बड़े होय जोउ । असुर के भूप देखना तोउ ॥\n\n धर्मनियम त्याग महिं केहा । अधिक रहे सब संत से एहा ॥\n\n भक्ति ज्ञान करि अधिक देखावे । ध्यान महिं तत्पर रहावे ॥\n\n आपके प्रतिपादन अपारा । संत जेहि करे वारमवारा ॥\n\n तेसे संत के गुन मुख गावे । अवर के अवगुन कहि देखावे ॥\n\n जितने संत हरिजन जो एसो । कालनिमि जानना तेसो ॥\n\n संत हरिजन निरमल तेते । सरल स्वभाव वरतत तेते ॥"],"mt":false,"gl":null,"a":false},{"i":69,"k":"para","g":"શ્રીહરિએ મોટેરા ગામના હરિજનો સમક્ષ વાત કરતાં કહ્યું, “સત્સંગ દૃઢ કરીને રાખજો, આવો સમય ફરીને નહિ આવે. સત્સંગ માટે દુઃખ સહન કરવું પડે તોપણ ધન્ય ભાગ્ય માનવું. સત્સંગ અર્થે જેટલું કષ્ટ સહન કરશો તેથી કોટિગણું અલૌકિક સુખ મળશે. રાજા થયા હોય પણ ભગવાનનું શરણ ન લીધું હોય તો છજા ઉપર ઊગેલા છોડ જેવી તેની મોટપ છે. હરિભક્તની મોટાઈ સત્સંગને લીધે છે. મનુષ્યતન પામી હરિનું શરણ ન લીધું તે પશુ સમાન છે.”","e":"While talking before the harijans of the village of Motera, Shriharí said, “Keep satsang firmly; such a time will not come again. Even if misery must be borne for the sake of satsang, count it as great good fortune. However much hardship you bear for the sake of satsang, you will receive alaukik sukh a crore times greater. One may have become a king, but if he has not taken the refuge of Bhagwan, his greatness is like a plant sprung up upon a parapet. The greatness of a haribhakta is on account of satsang. One who, having attained a human body, has not taken the refuge of Hari is the equal of an animal.”","s":["14/63/32-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":70,"k":"para","g":"સારંગપુરના જીવા ખાચરના દરબારમાં શ્રીહરિએ હરિજનોને કહ્યું, “લવ સત્સંગનું માહાત્મ્ય અપાર લખ્યું છે. સત્સંગ ન હોય તો બ્રહ્મા જેવા પણ કંગાળ છે. એ વાત જ્યારે પૂર્ણ સમજાય ત્યારે પાકો ભક્ત ગણાય. સરોવરની પાળ દૃઢ હોય તો પાણી ટકે. સૌ હરિજનો સરોવર સમાન છે. નિયમ અને સમજણ (નિશ્ચય) પાળને ઠેકાણે છે.","e":"In the darbar of Jiva Khachar at Sarangpur, Shriharí said to the harijans, “The mahatmya of even a moment of satsang has been written of as boundless. Without satsang even one such as Brahma is destitute. When that talk is fully understood, then one is counted a mature bhakta. If the embankment of a lake is firm, the water stays. All harijans are like the lake. Niyam and understanding (nishchay) stand in the place of the embankment.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":71,"k":"para","g":"“સત્સંગની કથાવાર્તા મેઘના જળ જેવી છે. ભગવાન અને સંત મેઘને ઠેકાણે છે. નિયમ અને સમજણમાં બધાં ગુણ ને રિદ્ધિ-સિદ્ધિ આવી ગયાં. જેટલા નિયમ-નિશ્ચય દૃઢ તેટલી તેની મોટપ જાણવી. ધામમાત્ર નિયમ-નિશ્ચયમાં આવી ગયાં. જેને નિયમ-નિશ્ચય દૃઢપણે હોય તેવા ભક્તનો ત્યાગ ક્યારેય ન કરવો. નિત્ય ચઢતો રંગ રાખવો. તુચ્છ બાબતમાં મમત્વ ન કરવો. સત્સંગ અને ભગવાન વિનાની બધી તુચ્છ વાત જાણવી. આવી સમજણ જેને અચલ રહે ને દેશકાળના વિષમપણામાં પણ ફરે નહિ એવો જે હરિભક્ત હોય તે ગરીબ સમાન દેખાતો હોય, તોપણ તેના અંતરમાં ભગવાન રહ્યા છે. તે વિના આવી સમજણ ન આવે.”","e":"“The katha-varta of satsang is like the water of the clouds. Bhagwan and the Sant stand in the place of the clouds. In niyam and understanding all the virtues and all the riddhi-siddhis are contained. However firm a man’s niyam and nishchay, know that to be his greatness. All the dhams are contained within niyam and nishchay. Never forsake a bhakta whose niyam and nishchay are firm. Keep the colour rising daily. Do not form attachment in trifling matters. Know all that is without satsang and Bhagwan to be a trifling matter. That haribhakta in whom such understanding remains unshaken, and who does not turn even in the adversity of place and time — though he appear like a poor man, Bhagwan abides within him. Without Him such understanding does not come.”","s":["14/82/1-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":72,"k":"para","g":"સારંગપુરના જીવા ખાચરના દરબારમાં શ્રીહરિએ હરિજનોને કહ્યું, “સત્સંગ પાકો કરવો. કાચો હોય તેટલું અંતરમાં સુખ રહે નહિ. કુસંગનો જેટલો પાશ છે તેટલો બ્રાહ્મણના ઘરમાં શ્વપચનો વાસ હોય તેવું છે. કાચો કે પાકો સત્સંગના યોગે કરીને સમજાય છે. આરસી વિના પોતાનું મુખ દેખાય નહિ. હાંડીના દીવા પોતાને તથા બીજાને પ્રકાશે છે તેમ સંતની વાત પણ તેવી છે. કેટલીક હાંડી એવી હોય કે બીજાને અજવાળું કરે, પણ પોતાની તળે અંધારું રાખે. ગૃહસ્થ હરિભક્ત તેવા જાણવા.","e":"In the darbar of Jiva Khachar at Sarangpur, Shriharí said to the harijans, “Make satsang mature. However unripe it is, that much sukh does not remain within. However great the noose of kusang, it is as though a shvapach were dwelling in the house of a brahmin. Whether one’s satsang is unripe or mature is understood through the yog of satsang. Without a mirror one’s own face is not seen. The lamps of a chandelier give light to itself and to others; the talk of the Sant too is like that. Some chandeliers are such that they give light to others but keep darkness beneath themselves. Know householder haribhaktas to be like that.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":73,"k":"para","g":"“ઘરમાં જે હરિભક્ત રહે તેણે સંતના દાસ થઈને રહેવું. ધનમાં ચિત્ત પરોવાતું હોય તો સ્ત્રીનો ત્યાગ કરવાથી શું થાય? અને માનરૂપી વિષ તો તેથી પણ ભારે છે. માન જેમાં આવે તે સંતમાં બ્રહ્માને પણ દુર્લભ એવા ઉત્તમ ગુણો હોય તે દોષરૂપ થઈ જાય છે, જે ગુણ છે તે જ સ્વયં મોટાઈરૂપ છે. જેમ ગુણ આવે તેમ દીન થાય અને સંતને આધીન રહે ત્યાં સુધી ગુણ શોભે છે.”","e":"“A haribhakta who remains in the household should remain as the das of the Sant. If the chitt is entangled in wealth, what comes of forsaking a woman? And the poison that is maan is heavier still than that. In a Sant into whom maan enters, the excellent virtues that are rare even to Brahma turn into flaws; that which is a virtue is itself greatness. As virtues come, so does one become meek; and as long as one remains submissive to the Sant, his virtues are adorned.”","s":["14/83/24-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":74,"k":"para","g":"શ્રીહરિએ ગઢપુરમાં હરિજનોને વાત કરતાં કહ્યું, “ઉત્પત્તિ, સ્થિતિ અને પ્રલય કાળ દ્વારા થાય છે. કાળ અમારા વચનમાં વર્તે છે. અમારી મરજી લોપે તો કાળચક્રનો કોપ થાય છે. સત્સંગ ન થાય તો વિઘ્નોનો પાર નથી. હરિભક્તોનાં વિઘ્ન બળી જાય છે. સત્સંગીનો પ્રતાપ વિમુખને દેખાતો નથી, હરિભક્તોનો પ્રતાપ દેખી ભયમાત્ર નાશ પામે છે. હરિભક્તોમાં સમજણ ન હોય તેટલા દુઃખી થાય છે. ભૂત-પ્રેતાદિકનાં દુઃખ પણ અણસમજણમાં રહેલાં છે.”","e":"At Gadhpur, while talking before the harijans, Shriharí said, “Creation, sustenance and dissolution take place through kal. Kal abides by Our word. If Our will is transgressed, the wheel of kal grows wrathful. If satsang does not come about, there is no end to obstacles. The obstacles of haribhaktas are burnt away. The power of a satsangi is not seen by a vimukh; seeing the power of the haribhaktas, every fear is destroyed. Haribhaktas suffer to the extent that understanding is wanting in them. The miseries of bhuts and prets too lie in want of understanding.”","s":["15/40/14-23"],"sv":[],"mt":false,"gl":null,"a":false},{"i":75,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સંતો પ્રત્યે વાત કરતાં કહ્યું, “ભગવાન અને સત્સંગ અર્થે અણુ જેટલું કોઈએ કર્યું હોય તો ભગવાન તેને મેરુ જેટલું સુખ આપે છે. તે અનંત કલ્પ વીતે તોય ભગવાન એ જીવનો અણુ જેટલો ગુણ ભૂલતા નથી, તેથી જ ભગવાનને જ્ઞાનમૂર્તિ કહી ગામોગામ જનો ભજે છે.","e":"At Gadhpur, while talking before the Sants, Shriharí said, “If anyone has done even an atom’s worth for the sake of Bhagwan and satsang, Bhagwan gives him sukh as great as Meru. Though infinite kalps pass, Bhagwan does not forget that jiva’s atom’s worth of virtue; and it is for that very reason that people in village after village worship Bhagwan, calling Him the embodiment of gnan.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":76,"k":"para","g":"“સત્સંગ કર્યા સિવાય કોઈ કાળે ઉદ્ધાર થવાનો નહિ. મોક્ષનું દ્વાર સત્સંગ છે. સંસારમાં એ અચળ છે. એના આશ્રય વિના જન્મમરણ, જમપુરી ને ચોરાશીનો ફેરો ટળતો નથી. મોક્ષનાં અન્ય સાધન ઘણાં છે, પણ તે માયિક છે. એ સાધન કરવાથી જનને કાળનો ભય નાશ થતો નથી. જ્યારે તે સત્સંગ કરે છે ત્યારે કાળ, કર્મ ને માયાથી છૂટે છે. વળી, મોક્ષ અર્થે જે જે સાધન કરવા જન ઇચ્છે છે તે સર્વે સત્સંગના પેટામાં સમાઈ જાય છે.”","e":"“Without doing satsang there will be no deliverance at any time. Satsang is the door of moksha. In sansar it is unshakeable. Without its asharo, birth and death, Yampuri and the round of the eighty-four lakh births are not dispelled. There are many other means of moksha, but they are mayik. By performing those means a man’s fear of kal is not destroyed. When he does satsang, then he is freed from kal, karma and maya. Moreover, all the means that a man wishes to perform for the sake of moksha are contained within the belly of satsang.”","s":["15/47/20-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":77,"k":"para","g":"વડતાલમાં હરિજનો પ્રત્યે શ્રીહરિએ કહ્યું, “સત્સંગમાં થતી વાત અલૌકિક છે, દિવ્ય છે. જે લૌકિક જાણે છે તેની મતિ વિપરીત રહી છે. મનુષ્યતન મળ્યું, ભૂપ થયો, ધનાઢ્ય થયો, પણ સત્પુરુષનો સંગ નથી તેને બધું જ નિરર્થક છે. દેવતા થવું તે પણ આશ્ચર્ય વાત નથી, મનુષ્યની દોટ દેવતા સુધી રહી છે, તેને આ લોકમાં સંતનો સંગ મળે અને મોટપ પામે તેવી બીજી મોટપ નથી. સત્સંગ મળે તોપણ કોઈ મોટપ ન પામ્યો તેમાં સત્સંગનો દોષ નથી. ચિંતામણિ મળી ને કંગાલ રહ્યો તેમાં ચિંતામણિનો શો દોષ! સત્સંગ છે ત્યાં ભગવાન પ્રગટ છે ને ત્યાં ભગવાનનું અક્ષરધામ પણ રહ્યું છે. જીવ વિનાના દેહમાં ચૈતન્ય ન હોય તેમ ભગવાન વિનાના સત્સંગમાં દિવ્યપણું ન હોય. અર્થાત્ જ્યાં દિવ્યતા હોય, અલૌકિક વાતો થતી હોય ત્યાં જાણવું ભગવાન રહ્યા છે.”","e":"At Vartal, Shriharí said before the harijans, “The talk that takes place in satsang is alaukik; it is divine. One who takes it to be worldly — his intellect has remained perverse. A human body has been obtained; one has become a ruler; one has become wealthy; but for one who has not the sang of the Satpurush, all of it is useless. To become a devata is no wonderful thing either; the running of man extends as far as the devatas; but there is no other greatness like the greatness he attains in obtaining the sang of the Sant in this realm. If, though satsang has been obtained, someone has attained no greatness, the fault is not satsang’s. One has obtained a chintamani and remained destitute — what fault is that of the chintamani’s! Where satsang is, there Bhagwan is pragat, and there the Akshardham of Bhagwan also abides. Just as there is no chaitanya in a body without a jiva, so there is no divinity in a satsang without Bhagwan. That is to say, where there is divinity and where alaukik talks are taking place, know that Bhagwan abides there.”","s":["15/67/13-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":78,"k":"para","g":"શ્રીહરિએ પત્રમાં લખાવ્યું, “જેને જીવનો સત્સંગ થયો હોય તેની સમજ આ પ્રકારની રહે છે: પરબ્રહ્મ એવા શ્રી પુરુષોત્તમનારાયણ નિશ્ચય શ્રીકૃષ્ણના સ્વામી છે. ‘એસે શ્રીપુરુષોત્તમ જેહિ, નિશ્ચય કૃષ્ણ-સ્વામી યહ તેહિ..’ તે એક એવા સમર્થ છે જેની લીલારૂપ માયા સર્જન-પોષણ-લય કરે છે. સહજપણે થતી આવી અપાર ક્રિયામાં તેઓ લેશ બંધાતા નથી. આમ સમજે છે તે બાઈ-ભાઈને કૃતાર્થ જાણવાં. તેને પંચભૂતનું શરીર નરક જેવું દેખાય છે. આત્માનો પ્રકાશ કોટિ સૂર્ય જેવો દેખે છે. દેહ મરે, બળે કે સડે તેને પોતાનું રૂપ માનતા નથી.”","e":"Shriharí had it written in a letter: “The understanding of one whose jiva has obtained satsang remains of this kind: Shri Purushottamnarayan, who is Parabrahman, is assuredly the swami of Shri Krishna. ‘Aise Shrī Purushottam jehi, nishchay Krishna-swāmī yah tehi..’ [Such is Shri Purushottam; know Him assuredly to be the swami of Krishna.] He alone is so mighty that His maya, in the form of His lila, performs creation, sustenance and dissolution. In such boundless activity, taking place of itself, He is not bound in the least. Know those bais and bhais who understand thus to be fulfilled. To such a one the body of the five bhuts appears like hell. He sees the light of the atma as that of a crore of suns. Though the body die, or burn, or rot, he does not hold it to be his own form.”","s":["15/77/31-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":79,"k":"para","g":"શ્રીહરિએ ધર્મપુરનાં રાણી કુશળકુંવરબાને કહ્યું, “જ્યાં સુધી સત્સંગ થયો નથી, ત્યાં સુધી જન્મ-મરણ, જમપુરી અને ચોરાશીનો બોજ રતીભાર છૂટતો નથી. મનુષ્ય જેટલો ધર્મ અને સત્સંગ સન્મુખ ચાલે છે તેટલો સુખી થાય છે.","e":"Shriharí said to Kushalkuvarba, the queen of Dharampur, “Until satsang has come about, the burden of birth and death, of Yampuri and of the eighty-four lakh births is not lifted by a grain’s weight. However far a person walks facing dharma and satsang, that much does he become happy.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":80,"k":"para","g":"“બાઈ! તમારાં ભાગ્ય અપાર છે. સત્સંગ કરીને રાજ તમને ખારું થયું છે. રાજમાં દુઃખ જણાયું છે અને સત્સંગમાં સુખ મનાયું છે. સત્સંગ કરતાં કરતાં સંસારમાં મોહ રહી જાય એટલો કુસંગ છે. કુસંગ રહે ત્યાં સુધી વારંવાર સત્સંગમાં દેહ ધરે છે. પછી અતિ શુદ્ધ થાય છે ત્યારે અક્ષરધામમાં જાય છે.”","e":"“Bai! Your fortune is boundless. Having done satsang, the kingdom has turned brackish to you. Misery has been perceived in the kingdom and sukh has been felt in satsang. However much attachment to sansar remains while doing satsang, that much is kusang. As long as kusang remains, one takes a body again and again within satsang. Then, when one becomes utterly pure, one goes to Akshardham.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":81,"k":"para","g":"બાઈએ કહ્યું, “હે મહારાજ! આપ અક્ષરના પણ કારણ છો અને આવીને મને મળ્યા છો. હવે, અંતરમાં દૃઢ નિરધાર કર્યો છે કે, તમારી મૂર્તિ અંતરમાં ધારી રાખવી છે.”","e":"The bai said, “O Maharaj! You are the cause even of Akshar, and You have come and met me. Now I have made a firm resolve within — that I shall hold Your murti within my heart.”","s":["16/27/26-41"],"sv":[],"mt":false,"gl":null,"a":false},{"i":82,"k":"para","g":"ઝીંઝાવદરમાં શ્રીહરિએ કહ્યું, “અમે સત્સંગ છોડીને જવા ઉદાસ થયા પરંતુ જ્યારે હરિજનોના ગુણ જોયા ત્યારે તે ઉદાસી ટળી ગઈ. સત્સંગનો પ્રતાપ વિચારતાં દોષ ટળી જાય છે ને અંતરમાં અજવાળું થાય છે. હરિભક્તના દોષ ગ્રહણ કરતાં અંતરમાં અંધારું થાય છે. હરિજનના ગુણ ગ્રહણ કરનારમાં તલમાત્ર દોષ રહેતા નથી. દોષ ગ્રહણ કરે છે ત્યારે સમજણ ફરી જાય છે, જેથી ગુણમાં પણ દોષ દેખાય છે. મોટા વાત કરે તેમાં પોતાના દોષ જણાવીને વાત કરે છે. મોટા પુરુષ સૂર્ય સમાન હોય છે. તે બધે અજવાળું પાથરતા રહે છે. અંતરમાં અને બહાર અજવાળું કરવું એ ભગવાન સિવાય થઈ શકે નહીં.”","e":"At Zinzavadar, Shriharí said, “We had grown dejected and were for leaving satsang; but when We saw the virtues of the harijans, that dejection was dispelled. On reflecting upon the power of satsang, faults are dispelled and light comes within. On taking hold of the faults of a haribhakta, darkness comes within. In one who takes hold of the virtues of a harijan not a sesame seed’s worth of fault remains. When a man takes hold of faults, his understanding is turned about, so that faults are seen even in virtues. When the great speak, they speak by naming their own faults. Great men are like the sun. They go on spreading light everywhere. To make light both within and without cannot be done by any but Bhagwan.”","s":["16/40/32-37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":83,"k":"para","g":"ઝીંઝાવદરમાં શ્રીહરિ કહે, “જેવો ખપ હોય તે પ્રમાણે ધર્મને માર્ગે ચલાય છે. ધર્મ રાખી ભગવાન ભજનાર થોડા હોય છે. ધન ઉપર દોડ વધારે રહે છે, તેટલી સત્સંગમાં રહેતી નથી. ધનને માટે મરવું કબૂલ કરે છે. ચારણ અને ભાટ લોકો ગરાસ માટે ચિતા રચી પોતે બળે છે. ચોરી કરનારા પણ ધનને માટે મરવાનો ડર રાખતા નથી. એમ સત્સંગનો જો મમત્વ રાખે તો બન્ને લોકમાં સુખી થાય. ગુરુ, ભગવાન અને રાજાના ચોર ન થવું, એ બધી વાતનું મૂળ છે.","e":"At Zinzavadar, Shriharí said, “A man walks the path of dharma according to the khap he has. Those who keep dharma and worship Bhagwan are few. The running after wealth is greater; so much does not remain in satsang. For wealth men accept death. Charans and Bhats build a pyre and burn themselves for the sake of a land grant. Those who steal too keep no fear of dying for wealth. In the same way, if a man keeps such attachment for satsang, he becomes happy in both realms. Do not become a thief of the guru, of Bhagwan and of the king — that is the root of the whole matter.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":84,"k":"para","g":"“સત્સંગ એટલે શ્રીહરિ તેના ગુણવાળા સંત અને મોક્ષપરક શાસ્ત્ર. આ ત્રણેનો સંગ કરવો એ સત્સંગ છે. સંગમાં મુખ્ય અર્થ મોક્ષ છે.”","e":"“Satsang means Shriharí, the Sant possessed of His virtues, and the scriptures that lead to moksha. To keep the sang of these three is satsang. In that sang the chief object is moksha.”","s":["16/41/22-42"],"sv":[],"mt":false,"gl":null,"a":false},{"i":85,"k":"para","g":"વડતાલમાં વાસણ સુથારને ઘરે શ્રીહરિએ સંતો-હરિજનોને કહ્યું, “જે વાત સાંભળી પછી તેનું મનન ન કરે તો એક પણ વાત હૃદયમાં ઠરતી નથી. જીવમાં સત્સંગ પણ મનન વિના વૃદ્ધિ પામતો નથી. રાત-દિન અમારો પ્રસંગ કરે, પણ તેનું મનન ન કરે તો ધર્યો રહે છે. (નિષ્ફળ જાય છે.) વ્યાવહારિક વાત પણ મનન વિના સિદ્ધ થતી નથી. બીજ વાવે પછી તેની સંભાળ રાખવી પડે. નકામું ઘાસ નીંદવું પડે. મનન એ ઉપયોગ વિનાની વાતનું નીંદણ છે. છોડની આસપાસનું ઘાસ કાઢતો રહે તો વિકસે ને અન્ન થાય, તેમ સત્સંગ મનન કરવાથી વધે ને મોક્ષરૂપી ફળ મળે. નિયમ ધાર્યા હોય તેનું પણ મનન કરવું. મનન કરવાથી જીવ શુદ્ધ થાય છે અને બળ આવે છે. શુદ્ધ ભક્તના અંતરમાં ભગવાન નિવાસ કરે છે.","e":"At Vartal, at the home of Vasan Suthar, Shriharí said to the Sants and harijans, “If, having heard a talk, one does not do manan of it, then not a single talk settles in the heart. Satsang too does not grow within the jiva without manan. Though a man keep Our company night and day, if he does not do manan of it, it lies where it was set down. (It comes to nothing.) Even a worldly matter is not accomplished without manan. After sowing the seed one must look after it. The useless grass must be weeded out. Manan is the weeding out of what is of no use. If one goes on removing the grass around a plant, it grows and yields grain; in the same way satsang grows by manan and the fruit that is moksha is obtained. One should do manan also of the niyams one has taken. By manan the jiva becomes pure and strength comes. Bhagwan comes to dwell within a pure bhakta.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":86,"k":"para","g":"“જે મનન કરે છે તે સંત-હરિજનની સત્સંગમાં મોટાઈ છે. ને એ મોટાઈ દિન દિન પ્રત્યે વધતી જાય છે. જીવમાં સત્સંગની વૃદ્ધિ અને વર્તન છાનાં રહેતાં નથી. મનનથી અંતર શુદ્ધ થાય છે, ને પછી તેમાં ભગવાન નિવાસ કરે છે. ભગવાન જેના અંતરમાં રહ્યા હોય તે તેના વર્તનથી દેખાઈ આવે છે. તેનું વર્તન નિર્મળ કાચ જેવું હોય, તલ જેટલોય મળ રહ્યો ન હોય. મનન કરનારનાં નેત્ર અને શ્રોત્ર ભગવાન અને સંત જેવાં બની જાય છે. સુમતિ જનને તે દેખ્યામાં આવે છે.”","e":"“The greatness of a Sant or a harijan in satsang lies in his doing manan. And that greatness goes on increasing day by day. The growth of satsang in the jiva, and one’s conduct, do not remain hidden. By manan the heart becomes pure, and then Bhagwan comes to dwell in it. One in whose heart Bhagwan abides is known by his conduct. His conduct is like clear glass, with not a sesame seed’s worth of impurity remaining. The eyes and the ears of one who does manan become like those of Bhagwan and the Sant. To a man of good understanding this becomes visible.”","s":["16/69/19-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":87,"k":"para","g":"ગોંડળમાં હઠીભાઈના ભવનમાં શ્રીહરિ કહે, “અનાદિ અજ્ઞાનરૂપી અંધકારનો નાશ સત્સંગ વિના થાય નહિ. સો વર્ષ સુધી સત્સંગ કરે અને એક દિવસ ન કરે તોપણ અનાદિ અજ્ઞાન એવું છે કે તેને આવરણ કરે છે. માટે નિત્ય સત્સંગ કરવો. જે બાઈ-ભાઈ હરિભક્ત કે સંતને સત્સંગ કરવાની જેટલી આતુરતા તેટલો તે અધિક ભક્ત છે. આતુરતા અને ઉત્સાહ રહિત હોય તે તો પૂર ઊતરી ગયાં પછી નીર વિનાની નદી હોય તેના જેવો છે. જેને સત્સંગનો જોગ ન રહે, છતાં સત્સંગ મંદ પડે નહિ અને બીજાને સત્સંગનો રંગ લગાવે એ હરિભક્ત શ્રેષ્ઠ છે. સંબંધના યોગે કરીને સત્સંગ થાય તેથી ઘણા જીવો સુધરી જાય છે.”","e":"At Gondal, in the residence of Hathibhai, Shriharí said, “The darkness of beginningless ignorance is not destroyed without satsang. A man may do satsang for a hundred years, and yet if he does not do it for a single day, such is beginningless ignorance that it casts its veil over him. Therefore do satsang daily. Whatever bai or bhai, haribhakta or Sant, has the more eagerness to do satsang, that much the greater a bhakta is he. One who is without eagerness and enthusiasm is like a river left without water after the flood has passed. That haribhakta is the best who, though he has no yog of satsang, does not let his satsang grow slack and who colours others with satsang. When satsang comes about through the connection of relationship, many jivas are set right by it.”","s":["17/11/19-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":88,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સત્સંગ કરવાની રીત હરિજનોને કહી, “સત્સંગને અર્થે કામ ન આવે તેટલો કુસંગ જાણવો. સંતના અર્થમાં આવે તે ભવન અને પદાર્થ ધન્ય છે. એવી સમજણ રાખે તેનું નામ સત્સંગ કહેવાય. અખંડ મૂર્તિ દેખાય એવા અપાર શ્રેષ્ઠ ગુણો પોતાનામાં સત્સંગના પ્રભાવે કરીને હોય અને તેનો પોતાને ગર્વ આવે નહિ. માન-અપમાનમાં જ્યાં સુધી વહે છે ત્યાં સુધી કાચું પાત્ર છે.”","e":"At Gadhpur, Shriharí told the harijans the way of doing satsang: “Know that to be kusang which does not come to use for the sake of satsang. Blessed is that dwelling and that possession which comes to the use of the Sant. One who keeps such understanding — that is what is called satsang. A man may possess, by the power of satsang, boundless excellent virtues, such that the murti is seen unbroken, and yet take no pride in them. As long as a man is carried along in honour and dishonour, he is an unbaked vessel.”","s":["17/19/27-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":89,"k":"para","g":"બોટાદમાં ફૂલદોલ પર આવેલા હરિભક્તો જમી રહ્યા પછી શ્રીહરિએ સૌને વાત કરતાં કહ્યું, “ઘણા હરિભક્તો અમને કહે છે કે તમારા દાસના દાસનો નિત્ય સમાગમ દેજો. જો તેનો નિત્ય સમાગમ ન થાય તો મન ખુવાર કરી નાખે છે. પર મન અને નિજ મન - બન્ને લશ્કર છે. તે જીવ સત્સંગ કરે છે ત્યારથી સામસામાં યુદ્ધમાં ઊભાં છે, સુખે રહેવા દેતાં નથી. ગબરગંડને આ વાતની ખબર પડે નહિ, ત્યારે બન્ને મન ઓળખાતાં નથી. સત્સંગથી અધિક કોઈ વાત નથી. શરીરની આધિ-વ્યાધિનું દુઃખ થાય તેણે કરીને સત્સંગ ત્યજવો નહિ.","e":"At Botad, after the haribhaktas who had come for Fuldol had eaten, Shriharí said to all, while talking, “Many haribhaktas say to Us: grant us the daily samagam of the das of Your das. If his daily samagam is not obtained, the mind ruins them. The other mind and one’s own mind — both are armies. From the time the jiva does satsang they stand facing one another in battle; they do not let one live in peace. A dull-witted man does not come to know of this matter, and then the two minds are not recognised. There is nothing greater than satsang. Do not forsake satsang on account of the misery of bodily ailment and disease.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":90,"k":"para","g":"“દુઃખમાં સત્સંગ મોળો પડે એટલી સત્સંગ કરવામાં કસર છે. દુઃખ પડે તેમ સત્સંગનો રંગ અધિક ચઢે તેને સમૈયાનું સાચું ફળ મળે છે. સુખદુઃખમાં લેવાય તેને કસરવાળો જાણવો.”","e":"“However much satsang grows slack in misery, that much is the deficiency in the doing of satsang. He receives the true fruit of the festival upon whom the colour of satsang mounts the higher as misery falls. Know one who is carried away by sukh and dukh to be one in whom there is a deficiency.”","s":["19/16/21-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":91,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ જીભાઈને વાત કરતાં કહ્યું, “જેવા ગુરુ મળે તેવી ભક્તની બુદ્ધિ થાય છે. અમે સત્સંગની રીત બાંધી છે, તે સૌ ત્યાગી-ગૃહીને આ લોક પરલોકમાં અતિ સુખી કરે એવી સવોંપરી બાંધી છે. આ સમયમાં જેને તે સમજ્યામાં નહિ આવે તો ગયેલો સમય પાછો આવે તેમ નથી.”","e":"At Gadhpur, while talking to Jibhai, Shriharí said, “As the guru a man obtains, so does the bhakta’s intellect become. We have laid down the way of satsang, and We have laid it down as supreme — such that it makes all tyagis and householders exceedingly happy in this realm and the next. If in this time it does not come into a man’s understanding, the time that has gone is not to come again.”","s":["22/49/5-7"],"sv":[],"mt":false,"gl":null,"a":false},{"i":92,"k":"para","g":"જેતલપુરમાં શ્રીહરિએ વાત કરતાં કહ્યું, “જ્યાં ધર્મ, જ્ઞાન, વૈરાગ્ય અને ભક્તિ હોય, ભગવાનનો પ્રગટ સંબંધ હોય, અને છળ-કપટ ન હોય ત્યાં સત્સંગ સજીવ છે એમ જાણવું. ત્યાં મોક્ષફળની પ્રાપ્તિ થાય છે. જ્યાં ભગવાનનો સંબંધ નથી, એકાંતિક ધર્મ નથી, અને છળ-કપટ દંભ છે, ત્યાં સત્સંગ નિર્જીવ છે. ત્યાં મોક્ષરૂપી ફળની આશા રાખવી નહિ.” એટલી વાત કરીને શ્રીહરિએ ગરબીનાં પદ સંતો પાસે બોલાવ્યાં.","e":"At Jetalpur, while talking, Shriharí said, “Where there are dharma, gnan, vairagya and bhakti, where there is a pragat relationship with Bhagwan, and where there is no guile and deceit — know that there satsang is alive. There the fruit that is moksha is obtained. Where there is no relationship with Bhagwan, where there is no ekantik dharma, and where there is guile, deceit and hypocrisy — there satsang is lifeless. There one should keep no hope of the fruit that is moksha.” Having spoken this much, Shriharí had the Sants sing the garbi verses.","s":["28/21/22-24"],"sv":["धर्म भक्ति वैराग्य जो ज्ञाना । भगवान संबंध जामें रहाना ॥\n\n जीव जुत तेहि रहेउ बाता । जामहिं छलकपट न रहाता ॥\n\n छलकपट जामें रहे जेता । निरजीव बात तितनी हि तेता ॥\n\n मोक्षरूप फल हि जेही । निरजीव बात तामें तेहि ॥\n\n होवत हि नहि कबहु रहाते । निरजीव बात एसी कहाते ॥\n\n इतनि करी हरि बात, गरबि ताकेउ पद पिछे ।\n\n बोलायेउ रहात, संत जीते बोलत भये ॥"],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":93,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":"The author’s comment upon, and corroboration of, the present subject as spoken by Shriharí:","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":94,"k":"para","g":"આંધળાને હીરો મળે પણ વિશ્વાસ ન હોય તો દુઃખ પામે છે, તેમ સત્સંગ પામ્યા પછી પણ જો દુઃખ મનાય તો તે પણ તેના જેવો જડ છે. આ લોકનાં સુખ ઉપર જ દૃષ્ટિ રાખે તેને સત્સંગ થયો જ નથી, એમ જાણવું. લૌકિક સુખમાં જેટલો રાગ તેટલું દુઃખ, લૌકિક સુખનો જેટલો ત્યાગ તેટલું સુખ. એવી સમજણવાળા સત્સંગીનાં મૂળ ઊંડાં છે. માટે સત્સંગમાં આવો યોગ વારે વારે આવતો નથી, એમ સમજી તુચ્છ સુખને કારણે સત્સંગ ગુમાવવો નહિ.”","e":"A blind man may obtain a diamond, but if he has no trust in it he suffers; in the same way, if a man feels misery even after obtaining satsang, he too is as dull as that man. Know that one who keeps his gaze only upon the sukh of this realm has not obtained satsang at all. However much attachment to worldly sukh, that much misery; however much renunciation of worldly sukh, that much sukh. The roots of a satsangi with such understanding go deep. Therefore, understanding that such a yog does not come again and again in satsang, one should not lose satsang for the sake of trifling sukh.","s":["6/21/32-38"],"sv":[],"mt":false,"gl":null,"a":true},{"i":95,"k":"para","g":"સત્સંગ વિના સંતનો યોગ થાય નહિ. સંત મળે ત્યારે જ ભવરોગ ટળે. સંત હરિના હાથમાં હાથ સોંપે છે. સંત કહે તેમ કરવું.","e":"Without satsang the yog of the Sant does not come about. Only when one meets the Sant is the disease of birth and death dispelled. The Sant places one’s hand in the hand of Hari. One should do as the Sant says.","s":["3/36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":96,"k":"para","g":"ભક્તોને સુખ આપવા શ્રીહરિ અને સંતો ઘરે-ઘરે વિચરે છે. તેમણે વિચરણમાં જ અધિક સુખ માન્યું છે. સંત-સમાગમ તુલ્ય અન્ય કોઈ બીજું સુખ નથી. જેને એવા સંતના સમાગમથી શુદ્ધ મતિ થાય છે, તેને અક્ષરધામનું સુખ અહીં જ મનાય છે. પિંડ-બ્રહ્માંડના માયિક સુખ કાજે તે રુએ નહિ. જેમાં ધર્માંશ હોય અને સત્-અસત્‌નો વિવેક હોય તે જ શ્રીહરિ અને તત્સ્વરૂપ સંતને ઓળખી શકે છે.","e":"To give sukh to the bhaktas, Shriharí and the Sants travel from house to house. They have held the greater sukh to lie in travelling itself. There is no other sukh equal to the samagam of the Sant. One whose understanding is made pure by the samagam of such a Sant feels the sukh of Akshardham here itself. He does not weep after the mayik sukh of the body and the brahmand. Only one in whom there is a portion of dharma and the vivek of sat and asat can recognise Shriharí and the Sant who is of His form.","s":["4/51/13-20"],"sv":[],"mt":false,"gl":null,"a":true},{"i":97,"k":"para","g":"પોતાની રુચિનો ત્યાગ કરીને નારાયણની મરજી પ્રમાણે વર્તે ત્યારે સત્સંગ થયો ગણાય અને તે સંસાર સમુદ્ર તરવા વહાણમાં બેસી ગયેલો છે. સત્સંગરૂપી નાવ ન મળે ત્યાં સુધી સંસાર સમુદ્ર પાર ન પમાય. સત્સંગ થતાં પહેલાં સંસાર માટે તન-મન-ધનનો ઉપયોગ કર્યો હોવાથી જમપુરી, લખચોરાશીનું દુઃખ ચાલુ રહેલું છે.","e":"When a man forsakes his own liking and conducts himself according to the will of Narayan, then satsang is counted as having come about, and he has seated himself in the ship for crossing the ocean of sansar. Until the boat that is satsang is obtained, the ocean of sansar is not crossed. Because, before satsang came about, he used body, mind and wealth for the sake of sansar, the misery of Yampuri and of the lakhs of births continues.","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":98,"k":"para","g":"સત્સંગમાં પ્રગટ હરિ રહ્યા છે તે દર્શન દે કે ન દે તે તેમની મરજીની વાત છે, પણ આપણે સદાય ગરજુ રહેવું. ગરજુ વિના શ્રીહરિનું હેત મળતું નથી. ગરજુ પાસે શ્રીહરિ ચાલીને આવે છે અને શ્રીહરિ ગરજુના સદાય બેલી થાય છે. ભક્તિરૂપી દોરીથી શ્રીહરિ સદાય બંધાયેલા રહે છે.","e":"The pragat Hari abides in satsang; whether He gives darshan or does not give it is a matter of His will, but we should always remain in real need of Him. Without such need the affection of Shriharí is not obtained. To one who is in real need Shriharí comes walking, and Shriharí becomes for ever the helper of such a one. Shriharí remains for ever bound by the cord that is bhakti.","s":["6/50/12-21"],"sv":[],"mt":false,"gl":null,"a":true},{"i":99,"k":"para","g":"શ્રીહરિ વિના બીજે સાર ન મનાય તે પાકો સત્સંગ કહેવાય. નેત્રમાં જેમ એક ઝીણી રજ પણ રહી શકતી નથી, તેમ હરિજનના મનમાં હરિ વિના બીજું હોય તેને ત્યાગ કરાવે ત્યારે જ શ્રીહરિને શાંતિ થાય છે. પછી તે ભક્તને તજીને ભગવાન દૂર રહી શકતા નથી.","e":"That is called mature satsang in which nothing but Shriharí is held to be the essence. Just as not even one fine speck of dust can remain in the eye, so only when the harijan is made to forsake whatever is in his mind other than Hari does Shriharí find peace. Thereafter Bhagwan cannot forsake that bhakta and remain far from him.","s":["6/50/19-20"],"sv":[],"mt":false,"gl":null,"a":true},{"i":100,"k":"para","g":"સત્સંગમાં બધું જ ઉત્તમ છે; તેનો દ્રોહ કરે તે અધમમાં અધમ છે અને જે ભગવાનને હાથ જોડતો નથી, માથું નમાવતો નથી, ગુણગાન કરતો નથી, ચાલીને દર્શને જતો નથી, તેને તે હાથ, પગ, આંખ, માથું, જીભ વગેરે અંગ વિનાનો જાણવો.","e":"In satsang everything is excellent; one who commits droh against it is the lowest of the low. And one who does not join his hands to Bhagwan, does not bow his head, does not sing His praise, does not walk to His darshan — know him to be without hands, feet, eyes, head, tongue and every other limb.","s":["6/60/32-34"],"sv":[],"mt":false,"gl":null,"a":true},{"i":101,"k":"para","g":"અનંત કલ્પ ગયા, તેમાં એકવાર પણ જો સત્સંગ મળ્યો હોત તો જન્મ-મરણ રહ્યું ન હોત. સત્સંગનું તેજ કોટિ સૂર્ય સરખું છે. તેમાં અધર્મરૂપી ઉલૂકને કાંઈ દેખાતું નથી. કોટિવાર મસ્તક જાય અને આખા બ્રહ્માંડનું રાજ્ય જતું હોય છતાં પણ સત્સંગ આગળ તે સોઘું છે.","e":"Infinite kalps have passed; had satsang been obtained even once within them, birth and death would not have remained. The light of satsang is like a crore of suns. In it the owl that is adharma can see nothing at all. Though one’s head should go a crore of times and the sovereignty of the whole brahmand should be lost, still it is cheap before satsang.","s":["8/37/14-17"],"sv":[],"mt":false,"gl":null,"a":true},{"i":102,"k":"para","g":"નેત્રમાં જેમ રજ સમાય નહિ, નેત્રને ઉપયોગી ન હોય તેવી કોઈ વસ્તુ નેત્ર સહન કરતું નથી, તેમ સત્સંગ પણ નેત્ર સમાન છે. તે પોતાને અહિતરૂપ હોય તેને સમાવી શકતો નથી.","e":"Just as dust cannot be contained within the eye, and the eye does not bear anything that is not of use to it, so satsang too is like the eye. It cannot contain within itself what is harmful to it.","s":["8/40/23"],"sv":[],"mt":false,"gl":null,"a":true},{"i":103,"k":"para","g":"સત્સંગ વિનાનાં બીજાં કર્મોનું ફળ અતિ તુચ્છ છે. ભવ-બ્રહ્મા પણ સત્સંગ ઇચ્છે છે. હરિ વિનાનાં દેખેલાં અને સાંભળેલાં કોઈ પણ પદાર્થમાં રુચિ ન રહે, તે જ સાચો સત્સંગ ગણાય. જેટલું હરિ વિનાનું સત્ય ભાસે એટલી સત્સંગ કરવામાં કસર સમજવી.","e":"The fruit of deeds other than satsang is exceedingly trifling. Bhav and Brahma too desire satsang. Only that is counted true satsang in which no liking remains for anything seen or heard that is without Hari. However much that is without Hari appears true, know that much to be the deficiency in one’s doing of satsang.","s":["10/2/21,25"],"sv":[],"mt":false,"gl":null,"a":true},{"i":104,"k":"para","g":"જેને સાચા સત્સંગનો લેશ હોય નહિ, પણ સત્સંગનો વેષ ધારી, નિયમ-ધર્મ નહિ પાળીને પેટ ભરે છે તેને પણ સત્સંગની ઓથે લોકો માને છે, તો પછી સાચા સત્સંગની તો વાત જ શી કરવી? ધર્મ, ભક્તિ, વૈરાગ્ય ને જ્ઞાન સાથે પ્રગટ હરિનો જેને નિશ્ચય હોય અને હરિ વિના બીજામાં અનુરાગ ન હોય તેને સાચો સત્સંગી કહેવાય. જેટલો ભગવાન વિના બીજામાં અનુરાગ તેટલી તેમાં કસર છે. સત્સંગ વિનાના જનોને દુઃખી દેખે ત્યારે સત્સંગમાં દૃઢતા થાય, સંસારમાં રસ મનાય ત્યાં સુધી સત્સંગ થાય નહિ. જેટલો સંસારમાં રસ છે તેટલો જ્યારે તેનો અભાવ આવે ત્યારે સત્સંગમાં પ્રીતિ થાય. સાચા સંતના મુખથી વાત સાંભળે ત્યારે જ તેને સંસારમાં દુઃખની ખબર પડે, અને લવ સુખ માટે વિમુખજન અપાર દુઃખ ભોગવે છે તે જાણ્યામાં આવે.","e":"Even one who has not a trace of true satsang, but who wears the guise of satsang and fills his belly without keeping niyam and dharma — even him people honour under the shelter of satsang; then what is there to say of true satsang? One who has nishchay of the pragat Hari together with dharma, bhakti, vairagya and gnan, and who has no attachment to anything other than Hari, is called a true satsangi. However much attachment there is to anything other than Bhagwan, that much is the deficiency in him. When he sees people without satsang suffering, then firmness in satsang comes. As long as relish is felt in sansar, satsang does not come about. Only when abhav towards it arises to the same measure as the relish felt in sansar does priti for satsang arise. Only when he hears the talk from the mouth of a true Sant does he come to know of the misery in sansar, and come to know that for a moment’s sukh vimukh people undergo boundless misery.","s":["10/25/27-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":105,"k":"para","g":"દેહાભિમાન ન રહે તે જ સત્સંગનું ફળ છે. સત્સંગ કરતા જેને કસર રહી છે તેવા ભવ, બ્રહ્મા, ઇન્દ્ર, નારદ, પરાશર, વગેરેના ગુણો તથા દોષો વ્યાસજીએ લખ્યા છે. સમર્થ વિના બીજા કોઈ લખે તે પ્રમાણ મનાય નહિ.","e":"The fruit of satsang is precisely this, that dehabhiman does not remain. Vyasji has written both the virtues and the faults of those in whom a deficiency remained in the doing of satsang — Bhav, Brahma, Indra, Narad, Parashar and the rest. What anyone other than a capable person writes is not to be taken as authoritative.","s":["10/42/34-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":106,"k":"para","g":"સત્સંગ અને ધર્મ વિના જનો ફાવે તેવાં તીર્થ વ્રતો કરે તોપણ તે મોહ ગણાય, અને મોહનું નામ જ સંસાર છે, અને સ્ત્રી પણ સંસાર છે. બધાંનું બીજ ધનમાં રહેલું છે, જે ધનનો સંતોએ ત્યાગ કર્યો છે.","e":"Without satsang and dharma, though people perform whatever pilgrimages and vows they please, it is counted as moha; and moha is precisely what is called sansar; and a woman too is sansar. The seed of all of it lies in wealth, which the Sants have renounced.","s":["10/52/25-31"],"sv":[],"mt":false,"gl":null,"a":true},{"i":107,"k":"para","g":"સત્સંગમાં એવી રીતિ હતી કે દશ વર્ષની છોકરી હોય અને દશ વર્ષનો છોકરો હોય તોપણ ભેગાં બેસી રમે નહિ. સત્સંગ સિવાય બીજે તો બધું એકાકાર થવાથી અગ્નિ અને દારૂના સંયોગ જેવું થતું. નિયમ વિના જે જે વાતો થાય તેમાં દુઃખ આવ્યા વિના રહે નહિ. નિયમ ત્યજીને ચાલે તો રાજા કે કરોડપતિ હોય તોપણ તે રંક બની જાય.","e":"Such was the way in satsang that though there were a girl of ten years and a boy of ten years, they would not sit and play together. Everywhere apart from satsang, from all becoming mingled together, it became like the conjunction of fire and gunpowder. Whatever takes place without niyam cannot fail to bring misery. If a man walks having forsaken niyam, then though he be a king or a millionaire, he becomes a pauper.","s":["12/26/7-10"],"sv":[],"mt":false,"gl":null,"a":true},{"i":108,"k":"para","g":"સત્સંગીનું વર્તન એવું શુદ્ધ અને નિર્મળ છે કે, તેને જોઈને ગમે તેવો કુસંગી હોય તેને પણ સત્સંગ થાય છે. સત્સંગ પામીને કુસંગ કરે તો કુસંગી થઈ જાય છે. તે જો સત્સંગ બહાર જઈને સત્સંગનો દ્રોહ કરે તો દિવસે દિવસે તેને બ્રહ્મહત્યા અને ગૌહત્યાથી પણ અધિક પાપ લાગે છે. જો સત્સંગનો દ્રોહ ન કરે ને સંત અને હરિભક્તો તેનો તિરસ્કાર કરે તોપણ નિત્ય સત્સંગના ગુણ ગાય, પણ મનમાં અવગુણ આવે નહિ અને કુસંગી આગળ બોલે કે જે સત્સંગના નિયમ પાળે છે તે ભક્તો ભાગ્યશાળી છે, તો તેના મોક્ષમાં સંશય નથી. જે સત્સંગનો પક્ષ રાખે છે તેનાં પાપ ભગવાન માફ કરે છે.","e":"The conduct of a satsangi is so pure and so clean that, on seeing it, even the worst kusangi comes to satsang. If, having attained satsang, a man keeps kusang, he becomes a kusangi. If he then goes outside satsang and commits droh against satsang, day by day sin greater even than the killing of a brahmin or of a cow attaches to him. If he does not commit droh against satsang, and though the Sants and haribhaktas treat him with contempt he still daily sings the virtues of satsang and no fault arises in his mind, and he says before kusangis that those bhaktas who keep the niyams of satsang are fortunate — then there is no doubt about his moksha. Bhagwan forgives the sins of one who takes the side of satsang.","s":["13/49/30-41"],"sv":[],"mt":false,"gl":null,"a":true},{"i":109,"k":"para","g":"જે સ્ત્રીઓ સત્સંગ કરે છે તે વિષયનો અભાવ કરીને પુરુષસંબંધી સુખને ઝેર સમાન માને છે. એવી અલૌકિક રીત સત્સંગ વિના આવે નહિ. પુરુષો પણ સત્સંગ કરીને સ્ત્રીના સુખને ઝેર સમાન માને છે. જેને માટે જગતમાં જીવપ્રાણીમાત્ર રાત્રિ-દિવસ મરી મટે છે તેનો ત્યાગ કરવો તે કંઈ સામાન્ય વાત નથી. સત્સંગની બધી રીત આશ્ચર્યકારક છે તે બુદ્ધિવાનને જાણ્યામાં આવે છે.","e":"Those women who do satsang, having formed abhav towards the vishays, hold the sukh connected with men to be equal to poison. Such an alaukik way does not come without satsang. Men too, doing satsang, hold the sukh of a woman to be equal to poison. To renounce that for which every living creature in the world dies night and day is no ordinary matter. All the ways of satsang are wonderful, and this comes to be known by one of understanding.","s":["13/55/25-28"],"sv":[],"mt":false,"gl":null,"a":true},{"i":110,"k":"para","g":"તીર્થમાત્રનું દૈવત ધર્માદિક ગુણોમાં રહ્યું છે. અને તે ગુણો સત્સંગને આધીન છે. ધર્માદિક ગુણો સત્સંગમાં પ્રવર્તે છે ત્યારે સત્સંગમાં બધા ધર્મોનું દૈવત આવે છે. ઈશ્વરને પ્રસન્ન કરવા કેટલાક મનુષ્યો ઉપાય કરે છે, હિમાલયમાં તન ગાળે છે, કોઈ ભૈરવજપ ખાય છે, કેટલાક ગંગામાં શરીર તણાતું મૂકે છે, કોઈ તીર્થમાં વસે છે, કોઈ પંચાગ્નિ તાપે છે, કોઈ અન્ન છોડી દે છે, કોઈ યજ્ઞ કરે છે, કોઈ ઠંડી-ગરમી સહન કરે છે, કોઈ હાથ ઊંચા કરી રાખે છે, કોઈ ગૌદાન કરે છે - એમ અનંત પ્રકારનાં સાધન મનધાર્યાં કરે છે, પણ ભગવાનની મરજી પ્રમાણે કરવા તૈયાર થતા નથી. જ્યાં શુભ નીતિ અધિક હોય, ત્યાં જ ભગવાન અને તીર્થ વસે છે. સહુ પોતપોતાના મતે મોક્ષ માને છે, પણ તપાસ કરીને કોઈ જોતા નથી.","e":"The power of every place of pilgrimage lies in the virtues of dharma and the rest. And those virtues are subject to satsang. When the virtues of dharma and the rest prevail in satsang, then the power of all the dharmas comes into satsang. Some men employ means to please Ishwar: they waste the body in the Himalaya; some live upon japa to Bhairav; some let their bodies be carried away in the Ganga; some dwell in places of pilgrimage; some heat themselves with the five fires; some give up food; some perform yagna; some bear cold and heat; some keep their arms raised; some make a gift of cows — thus they perform infinite kinds of means after their own minds, but they are not ready to act according to the will of Bhagwan. Only where good conduct is the greater do Bhagwan and the tirth dwell. Everyone holds to moksha after his own opinion, but no one examines and looks.","s":["13/57/23-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":111,"k":"para","g":"મોક્ષના ખપ વિનાના મનુષ્ય પશુ સમાન છે અને અપાર ક્લેશ સહે છે. સંત વિના સાચો માર્ગ કોઈ દેખાડી શકે નહિ. જે બ્રહ્માંડના સમગ્ર સુખને કાકવિષ્ટા સમાન જાણે તેનો જ સત્સંગ સાચો છે. એવાને કોઈ અંતરની વાત કહે, કોઈ આકાશમાં ઊડી બતાવે, કોઈ ધન-સંપત્તિ આપે કે પુત્ર આપે કે રોગ મટાડે, તોપણ તેમાં પ્રતીતિ ન આવે. હરિ વિના બીજામાં તે લોભાય નહિ. રોમે રોમે કોટિ વીંછીની વેદના થાય એવો રોગ આવે તોપણ કર્તાહર્તા એક હરિને માને. રોગ ન મટાડે તોપણ હરિનો અભાવ ન આવે તેના ઉપર હરિ રીઝે છે અને હરિ રીઝે તો બધા રીઝે છે.","e":"Men without khap for moksha are the equal of animals and bear boundless affliction. No one but the Sant can show the true path. His satsang alone is true who knows all the sukh of the brahmand to be like the droppings of a crow. To such a one, though someone tell him what is in his heart, though someone fly in the sky to show him, though someone give him wealth and riches, or give him a son, or cure his disease — even so, no conviction in it comes to him. He is not tempted by anything other than Hari. Though a disease come such that there is the pain of a crore of scorpions in every pore, still he holds Hari alone to be the doer and the undoer. Hari is pleased with one in whom no abhav arises even though his disease is not cured; and if Hari is pleased, then all are pleased.","s":["14/15/15-24"],"sv":[],"mt":false,"gl":null,"a":true},{"i":112,"k":"para","g":"દંભે કરીને સત્સંગ કરતો હોય તે અંતે જાતાં ઘટી જાય છે. દંભથી કરે તે સત્સંગ ટકે નહીં. પોતાને બધા સંતો-હરિજનો કરતાં મોટો જાણે. પોતે જ માને કરીને પોતાને વધતો જુએ. સત્સંગનો પ્રતાપ એવો છે કે અલ્પ હોય ને તેમાં પણ મહત ગુણ આવે. ક્યારે? તો બીજા ગુણવાનો પાસે પોતાને તુચ્છ કરી માને તો કંચન તુલ્ય થઈ જાય. સત્સંગ પારસ તુલ્ય છે. તેને લોઢું સ્પર્શ કરે તો કુંદન થાય. જે કંઈ ઉત્તમ ગુણો છે તે સત્સંગમાં જ છે. સત્સંગ સિવાય ક્યાંય નથી. સત્સંગ ઉત્તમ સંત-હરિજનનો કરે અને જો અવગુણ લેવા માંડે તો ઘટતાં ઘટતાં સાવ ઘટી જાય છે.","e":"One who does satsang out of hypocrisy diminishes in the end. Satsang done out of hypocrisy does not last. He holds himself greater than all the Sants and harijans. Through maan he himself sees himself as growing. Such is the power of satsang that a man may be small, and yet great virtue comes into him too. When? When, before others possessed of virtue, he holds himself trifling — then he becomes the equal of gold. Satsang is the equal of the paras stone. If iron touches it, it becomes pure gold. Whatever excellent virtues there are, they are in satsang alone. Nowhere apart from satsang. If a man keeps the satsang of excellent Sants and harijans and yet begins to take their faults, then diminishing and diminishing he diminishes away utterly.","s":["14/19/22-27"],"sv":[],"mt":false,"gl":null,"a":true},{"i":113,"k":"para","g":"ક્ષુદ્ર માણસના સંગથી ક્ષુદ્ર સમજ આવે ને ક્ષુદ્ર સત્સંગ થાય. તેનાથી પોતાના અંગની વૃદ્ધિ થાય નહિ. ચિંતામણિ સમાન સત્સંગ છે; તે જેવી સમજણ હોય તે પ્રમાણે ફળ આપે છે. સત્સંગરૂપી પુરમાં ભગવાનના અવતાર થાય છે. ભગવાનનાં ચરિત્ર, તીર્થ, વ્રત વગેરે ઉત્તમ વસ્તુ સત્સંગમાં રહેલી છે. સત્સંગરૂપી નાવમાં બેસી ભવસાગર તરાય છે. પરલોક જવા કોઈ સહાય કરી શકે તેમ નથી. સત્સંગ જ એક ત્યાં સહાયરૂપ થાય છે. તેમાં જેટલી કસર રહે છે તેટલું પાછળથી પસ્તાવું પડે છે.","e":"From the company of a mean man a mean understanding comes, and a mean satsang comes about. By it a man’s own disposition does not grow. Satsang is the equal of a chintamani; it gives fruit according to the understanding one has. In the city that is satsang the avatars of Bhagwan take place. The charitras of Bhagwan, the tirths, the vrats and every other excellent thing reside in satsang. Seated in the boat that is satsang, the ocean of birth and death is crossed. In going to the other realm no one is able to render help. Satsang alone is of help there. However much deficiency remains in it, that much must one repent afterwards.","s":["15/10/2-16"],"sv":[],"mt":false,"gl":null,"a":true},{"i":114,"k":"para","g":"વેદ-પુરાણ ભણે તોય મોક્ષના માર્ગમાં મનુષ્યની બુદ્ધિ અતિ અલ્પ છે. મોક્ષ મેળવવા સંસાર ત્યજી વનમાં જાય, અપાર તીર્થ કરે, અષ્ટાંગ યોગ સાધે, પરંતુ જ્યાં સુધી તેને સત્પુરુષનો સંગ ન થાય ત્યાં સુધી તે પશુબુદ્ધિ રહે છે. સંતના યોગમાં આવવાથી તેને આ વાત સ્પષ્ટ સમજાય છે. સત્સંગ વિના અપાર બુદ્ધિવંત હોય તોપણ તેને સમજ પડતી નથી. સત્સંગની વાત જ અલૌકિક છે, તે લૌકિક મતિથી કેમ સમજાય? જો સત્સંગમાં જીવ ન બાંધે તોપણ લૌકિક મતિ ટળતી નથી, અલૌકિકતા દેખાતી નથી. સત્સંગ કરવા છતાં જીવ મલિન રહે.","e":"Though a man study the Vedas and the Purans, his intellect in the path of moksha is exceedingly small. To obtain moksha he may forsake sansar and go into the forest, may perform boundless pilgrimages, may practise ashtang yoga; but until he obtains the sang of the Satpurush, his intellect remains that of an animal. By coming into the yog of the Sant this matter is clearly understood by him. Without satsang, though a man be of boundless intellect, understanding does not come to him. The talk of satsang is itself alaukik; how is it to be understood by a worldly intellect? If the jiva is not bound within satsang, then the worldly intellect is not dispelled and the alaukik is not seen. Though he does satsang, the jiva remains impure.","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":115,"k":"para","g":"તન-મન-ધન અર્પણ કરી નિષ્કપટ ભાવે સત્સંગ કરે તો લૌકિકભાવ કુસંગ ટળે. ગીંગાની ગોળી જેમ કુસંગ અંદર ભરાયેલો રહે છે. સંત તેને સત્સંગમાં ડુબાડે છે ત્યારે તેનો કુસંગ ટળે છે. સંતનો સંગ થવા છતાં કુસંગ રહેતો હોય તો તેમાં પોતાના જીવનો દોષ છે.","e":"If a man offers body, mind and wealth and does satsang with a nishkapat heart, then the worldly disposition, which is kusang, is dispelled. Kusang remains packed within like the ball of a dung-beetle. When the Sant plunges him into satsang, then his kusang is dispelled. If, despite obtaining the sang of the Sant, kusang still remains, then the fault lies in his own jiva.","s":["15/29/15-21"],"sv":[],"mt":false,"gl":null,"a":true},{"i":116,"k":"para","g":"હરિજનોનો ભાવ એક સરખો રહેતો નથી. એનો સત્સંગ હા જી હા ને રાખ-રખાવટમાં પૂરો થઈ જાય છે. તેને માન ન આપો ને બોલાવો નહીં તો તરત ભાવ ફરી જાય, એ જ એને કુસંગનો યોગ થયો જાણવો. લીલાગર દારૂ પીએ ને પળમાં જીવ ફરી જાય તેવો કુસંગનો પ્રભાવ છે. નક્કી હરિજન જણાતો હોય, કુસંગથી ચેતીને ચાલતો હોય તોપણ કોઈની મોળી વાત સાંભળે તેનું ઝેર ચઢે છે. એટલે સાર વાત કરવી, અસાર વાત ન કરવી. મોળી વાત કુસંગ છે. સાંભળવાથી સુખ કરે એ સત્સંગ છે. ઉદ્વેગ ને અસુખ કરે એ કુસંગ છે.","e":"The feeling of harijans does not remain of one measure. Their satsang is exhausted in saying ‘yes, yes’ and in keeping up appearances. Give them no honour and do not speak to them, and their feeling changes at once — know that itself to be the yog of kusang come upon them. Such is the power of kusang that it is like drinking lilagar liquor and the jiva turning in a moment. A man may certainly appear to be a harijan and may walk warily of kusang, and yet if he hears anyone’s lukewarm talk, its poison mounts in him. Therefore speak of what has substance and do not speak of what has none. Lukewarm talk is kusang. That which gives sukh on hearing is satsang. That which causes udveg and unease is kusang.","s":["15/44/5-11"],"sv":[],"mt":false,"gl":null,"a":true},{"i":117,"k":"para","g":"કુસંગ થવાથી ઉત્તમ સત્સંગી પણ નીચમાં નીચ થઈ જાય છે. ઉપરથી કરે પણ ભાવ છુપાતો નથી. રાતદિવસ ધ્યાન કરે, અન્ન ખાય નહિ, જીર્ણ વસ્ત્ર પહેરે, સત્સંગની ઊંચી વાતો શીખી રાખે એમ બધાથી સરસ દેખાય, પણ જ્યારે આદર ન થાય ત્યારે ઉઘાડું પડ્યા વિના રહે નહિ. માનને માટે અગ્નિમાં પડવા તૈયાર થાય.","e":"Through kusang even an excellent satsangi becomes the lowest of the low. He may do it outwardly, but his feeling is not hidden. He may meditate night and day, may not eat food, may wear worn clothes, may have learnt the lofty talks of satsang, and so appear better than all; but when he receives no regard, he cannot fail to be exposed. For the sake of maan he becomes ready to throw himself into fire.","s":["17/8/10-17"],"sv":[],"mt":false,"gl":null,"a":true},{"i":118,"k":"para","g":"કોઈ કસર ન રહી હોય તોપણ ઉમંગપૂર્વક નિશદિન તેણે સત્સંગ કરવો. તો તેનો અક્ષરધામમાં નિવાસ સરળ બને છે. અક્ષરપતિ પુરુષોત્તમ શ્રીહરિ જેને સાક્ષાત્ મળ્યા નથી તેને અક્ષરધામ દુર્લભ છે. માટે સત્સંગ દુર્લભ છે તે જ્ઞાનચક્ષુ વિના દેખ્યામાં આવતું નથી.","e":"Even if no deficiency has remained in him, he should do satsang night and day with eagerness. Then his dwelling in Akshardham becomes easy. For one who has not met Aksharpati Purushottam Shriharí face to face, Akshardham is hard to attain. Therefore satsang is rare, and that is not seen without the eye of gnan.","s":["18/37/34-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":119,"k":"para","g":"ગબરગંડ જન સત્સંગમાં આવે અને કથાવાર્તા સાંભળે તોપણ તૂટેલા સરોવર જેવો છે. તૂટેલા સરોવરમાં જેમ નીર ટકતું નથી તેમ ગબરગંડના હૃદયમાં કથાવાર્તા ટકતી નથી. ચાહે તેટલો તે સમાગમ કરે પણ મહિમા વગર તો દિન ગુજારો કર્યા બરાબર છે.","e":"Though a dull-witted man come into satsang and listen to katha-varta, he is like a breached lake. Just as water does not stay in a breached lake, so katha-varta does not stay in the heart of the dull-witted. However much samagam he may keep, without mahima it is no better than passing the days.","s":["18/41/34-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":120,"k":"para","g":"ભગવાન સંબંધી જેટલી વાત છે તે પ્રગટ મોક્ષ આપે છે, ને તેનું નામ જ સત્સંગ છે. પ્રગટની વાતમાં છતી દેહે પરમપદ રહેલું છે. ભગવાન વિનાની વાત કુસંગ છે ને તેમાં નરકનો પંથ રહ્યો છે. કુસંગ ભવ ભટકાવનારો છે.","e":"Every talk connected with Bhagwan gives moksha here and now, and that itself is what is called satsang. In the talk of the pragat, the highest state resides while yet in the body. Talk without Bhagwan is kusang, and in it lies the road to hell. Kusang is what sets a man wandering through births.","s":["27/45/29-30"],"sv":[],"mt":false,"gl":null,"a":true},{"i":121,"k":"para","g":"બ્રહ્મના કલ્પ સુધી અષ્ટાંગ યોગ સાધે, અશ્વમેધ યજ્ઞ કરે કે નિત્ય કરોડ ગાયોનું દાન કરે તોપણ સત્સંગ વિના મોક્ષ ન થાય.","e":"Though a man practise ashtang yoga for a kalp of Brahma, perform the ashwamedh yagna, or daily give a crore of cows in charity, without satsang moksha does not come about.","s":["28/42/19-21"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":2,"gu":"ધર્મ, નિયમ, સદાચાર","en":"Dharma, Niyam, Sadachar","url":"https://www.anirdesh.com/pbp/index.php?page=chp_2","b":[{"i":122,"k":"para","g":"શ્રીહરિએ માતાને ઉપદેશ આપતાં કહ્યું, “બ્રહ્માદિક દેવો, ઈશ્વરો તથા સ્વર્ગ, મૃત્યુ અને પાતાળ એ ત્રણેય લોક ધર્મથી ધારણ કરાયેલા છે. ધર્મનું જેટલું આચરણ કરે એટલી તે મોટાઈ પામે છે. નીચ જાતિનો પુરુષ પણ ધર્મમાં વર્તતો હોય તો બ્રહ્માદિક દેવોને પણ પૂજવા અને વખાણવા યોગ્ય થાય છે અને બ્રહ્માદિક દેવ પણ જો ધર્મમાંથી પડે તો મનુષ્યોએ પણ નીંદવા યોગ્ય બને છે. સત્પુરુષનો સદાચાર એ ધર્મનું પ્રમાણ છે.”","e":null,"s":["1/55/3-6"],"sv":[],"mt":false,"gl":null,"a":false},{"i":123,"k":"para","g":"પૂનામાં નીલકંઠવર્ણીએ બાજીરાવ નૃપને વાત કરતાં કહ્યું, “શિવ, બ્રહ્માદિક એક-એકથી અધિક છે, તેમ અધિક અધિક ભગવાનને આધીન વર્તે છે, ત્યારે તેમનો યશ પણ જગતમાં વિખ્યાત છે.”","e":null,"s":["2/50/23-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":124,"k":"para","g":"માંગરોળમાં વજરુદ્દીન રાજાને ત્યાં શ્રીહરિએ વાત કરતાં કહ્યું, “અધર્મ કરે તે યવન છે. ધર્મ પાળે તે જ વર્ણમાં કહેવાય, બીજા વર્ણની બહાર છે. માટે હરિભક્તોએ ધર્મમાં દૃઢ વર્તવું. ત્યાગીએ ત્યાગીના ધર્મમાં અને ગૃહસ્થે ગૃહસ્થના ધર્મમાં રહેવું. એકબીજાની દેશી લેવી નહિ. જે અમારું વચન માનશે નહિ, તેને અમે સહાય કરશું જ નહિ. પછી અમારો દોષ કાઢતા નહિ.”","e":null,"s":["3/15/35-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":125,"k":"para","g":"ગઢપુરમાં અભયરાજાને શ્રીહરિ કહે, “કોણ માતા અને કોણ પિતા? કોણ બંધુ અને કોણ પુત્ર? અમારે કોઈને વિશે પ્રીતિ નથી. અમે ધર્મને પરિવાર માન્યો છે. જેનામાં જેટલો ધર્મ વિશેષપણે હશે તેની સાથે અમે અધિક પ્રીતિ કરીએ છીએ. અધર્મ ટાળવા હું પ્રગટ થયો છું. જો અમને રાખવા હોય તો ધર્મ અને ભક્તિ રાખો. તે વિના સોનાનો મહેલ હોય તોપણ હું રહેતો નથી. ધર્મ-ભક્તિનું સન્માન હોય ત્યાં હું રહું છું.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":126,"k":"verse","g":"‘કોન માત કોન તાત, કોન બંધુ પુત્ર હિ કોન,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":127,"k":"verse","g":"કોઈકું ન હમ ચહાત, ધર્મ કું અબ હમ કુટુંબ કિયેઉ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":128,"k":"verse","g":"જિતનો જામે ધર્મ અધિકાઈ, તિનસેં પ્રીત અધિક હમ લાઈ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":129,"k":"verse","g":"હમકું રખન કું જેહિ હોત ભાવા, ધર્મ ભક્તિ સો અધિક રખાવા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":130,"k":"verse","g":"ધર્મ ભક્તિ કે જ્યાં સન્માના, તિહાં હમ રહે તજિકે માના.’","e":null,"s":["4/5/16-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":131,"k":"para","g":"કુંડળમાં શ્રીહરિ કહે, “અમે આપેલા નિયમ જે કોઈ રાખે છે તેને અન્ન અને વસ્ત્રનું ક્યારેય દુઃખ આવતું નથી.”","e":null,"s":["4/32/35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":132,"k":"para","g":"કુંડળમાં અમરા પટગરના ભવનમાં શ્રીહરિએ કહ્યું, “ભગવાન જ્યારે પ્રગટ થાય છે ત્યારે તેને ઓળખીને ભજે છે, તે અધર્મી પણ ધર્મી બની જાય છે. સવળું ગ્રહણ કરે તે ધર્મી અને સુબુદ્ધિ છે. અવળો વિચાર રાખે તે અધર્મી અને કુબુદ્ધિ છે. મોક્ષમાર્ગ અને જગત બન્નેની રીત ન્યારી છે. જગતમાં જેને સૌ ધર્મવાન્ કહેતા હોય પણ જો તે ભક્તનો દ્રોહ કરે તો અધર્મી જ છે. એ ગમે તેટલો ધર્મ પાળતો હોય પણ પંચ મહાપાપથી પણ તેને અધિક પાપી જાણવો. જગતનો જીવ પંચમહાપાપે યુક્ત હોય પણ તે જો ભગવાનના ભક્ત પાસે વિનય કરે, પ્રાર્થના કરે અને સત્સંગનું અન્ન પેટમાં જાય તે અંતે મહા શુદ્ધ થઈ જાય છે. જન્મમૃત્યુથી છૂટી અક્ષરધામને પામે છે. આવો ઉત્તમ ભક્તના સંગનો પ્રતાપ છે.”","e":null,"s":["4/35/8-22"],"sv":["पंच महापापी जन होई । हरिजन को करे विनय सोई ॥\n\n सत्संग में सो अन्न कुं पाई । अंत्ये महाशुद्ध हो जाई ॥\n\n जन्म मृत्यु कुं छुटि के ऐहू । अक्षरधाम में जावहि तेहू ॥"],"mt":false,"gl":null,"a":false},{"i":133,"k":"para","g":"કુંડળમાં મુક્તમુનિ અને બ્રહ્મમુનિને શ્રીહરિ કહે, “શુક-નારદ સમ સંતો અને અનંત ધામના મુક્તો તથા પૂર્વ અવતારના અંબરીષ, ધ્રુવ, પ્રહ્‌લાદ, પ્રિયવ્રત, પાંડવ, ઉદ્ધવ જેવા ભક્તો તથા રાધા, રમા, સીતા જેવાં બાઈ ભક્તો સત્સંગમાં આવ્યાં છે, તે ધર્મ પ્રવર્તાવવા અને અનેક જીવોનું કલ્યાણ કરવા નિયમમાં વર્તે છે. નિયમ એ સત્સંગની શોભા છે. વસ્ત્ર-અલંકાર વિના મનુષ્ય શોભતો નથી, નગ્ન સામું કોણ જુએ! પછી ભલે તે રાજા હોય કે જોગી - વસ્ત્રહીન તરફ કોઈ દૃષ્ટિ કરતું નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":134,"k":"para","g":"“કાશી, અયોધ્યા, ગોકુલ, વૃંદાવન, મથુરા ફરી આવો - આ સત્સંગ સિવાય વિષયનો અભાવ ક્યાંય નથી. અમારા નિયમ ન પાળે તેને ખળ જાણવો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":135,"k":"para","g":"“નિયમથી જ સત્સંગની શોભા છે, ખળજન તેને તુચ્છકારે છે, નિયમ પાળનાર ભક્તોને જોઈ તે હાંસી ઉડાવે છે, પણ દેહ છૂટ્યે તેને જમ બાંધીને લઈ જાય છે.”","e":null,"s":["4/37/20-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":136,"k":"para","g":"લોયામાં શ્રીહરિ કહે, “નીતિ-નિયમમાં જે દૃઢ રહેશે તેને અન્ન-વસ્ત્ર સામેથી આવીને મળશે. લોકમાં તેની કીર્તિ વધશે. નીતિમાં ચાલનાર અમારો ભક્ત કદી દુઃખી થતો નથી. નીતિનો માર્ગ અમને ગમે છે. નીતિ બહાર ચાલે છે તેના પર જમ કોપ કરે છે. તેનાં અન્ન, ધન અને બુદ્ધિ નાશ પામે છે. અમારું વચન નહિ માને તેને બીજો કોઈ બળજબરીથી એ વચન પળાવશે. ભગવાનના જ્ઞાન વિના ને ધર્મના પાલન વિના કોઈની મુક્તિ થતી નથી.”","e":null,"s":["4/66/8-20"],"sv":[],"mt":false,"gl":null,"a":false},{"i":137,"k":"para","g":"શેખપાટમાં સંતોને શ્રીહરિએ કહ્યું, “અમારાં વચન શાંતિદાયક છે. વચનમાં જે સુખ માને છે તેને ક્યારેય અસુખ ન વર્તે. આજ્ઞા પાળી ને અસુખ થયું તેમ કહે તેની સમજણમાં તેટલો ફેર છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":138,"k":"para","g":"“જીવમાત્રને પોતાનું મનનું ગમતું કરવાની ઇચ્છા રહ્યા કરે છે. ભગવાનનું ગમતું કરે તેને શાંતિ જ હોય. વચનાકાર ન થાય ત્યાં સુધી શાંતિ થતી નથી. જેટલું વચનમાં દુઃખ માને છે તેટલો ખપમાં વાંધો છે. જેને જેની સાથે સ્વાર્થ હોય તે તેની મરજી પ્રમાણે વર્તે.”","e":null,"s":["5/22/5-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":139,"k":"para","g":"કચ્છમાં માંડવી બંદરે હરિજનો પ્રત્યે વાત કરતાં શ્રીહરિએ કહ્યું, “અક્ષરધામના મુક્ત પણ અહીં અમારું વચન લેશ પણ લોપે તો તેનું મુક્તપણું નાશ થઈ જાય છે અને અંતરમાં ક્લેશને પામે છે. જેમ મહાસમર્થ નારદજી હરિનું મન કહેવાયા, પણ કન્યાનું રૂપ જોયું કે તરત મનમાં વિકાર થયો. શૃંગી ઋષિ, સૌભરિ, પર્વત, ભવ, બ્રહ્મા, ચ્યવન, ચંદ્ર, ઇન્દ્ર એવા મોટા સૌને ગુણના ભાવ જણાણા છે ને ક્લેશ થયો છે, માટે વચનમાં વર્તવું.”","e":null,"s":["5/37/25-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":140,"k":"para","g":"કોટડામાં શ્રીહરિ કહે, “અધર્મ-અનીતિ કરે તેની સહાય કોઈ ન કરે. વચન માને તેની સહાય સંત કરે છે.”","e":null,"s":["5/38/12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":141,"k":"para","g":"કાળાતળાવમાં શ્રીહરિ કહે, “અમારો જેટલો પ્રતાપ છે તે બધો નિયમમાં જોડી રાખ્યો છે. માટે સંત-હરિજને નિયમમાં દૃઢ રહેવું. સમાધિનિષ્ઠ હોય, બ્રહ્મવેત્તા હોય, પણ જો નિયમ અને નિશ્ચયમાં (આજ્ઞા-ઉપાસનામાં) શિથિલ વર્તે તો તેને અસુર અને વિમુખ જાણવો. નિયમ અને નિશ્ચય ઉપરથી જેવું અંતર હોય તેવું જણાય છે. તેમાં દંભ ટકતો નથી. સૌનો મોક્ષ કરવા અમે નિયમ બાંધ્યા છે.”","e":null,"s":["5/42/21-24"],"sv":["हमारो प्रताप कहावत जेता । नियम में सब रखे हे तेता ॥\n\n समाधिनिष्ठ होय ब्रह्म हि वेत्ता । एसे संत हरिजन केता ॥\n\n नियम अरु निश्वय विन तेहू । विमुख असुर जानना एहू ॥\n\n नियम-निश्चे में न डंभ रहावे । जेसो अंतर तेसो कलावे ॥\n\n तेहि कारन हम बांधे निमा । सब के मोक्ष करन हित सीमा ॥"],"mt":false,"gl":null,"a":false},{"i":142,"k":"para","g":"માનકુવામાં શ્રીહરિએ ગૃહસ્થના ધર્મ જણાવતાં કહ્યું, “જેના સંગથી પોતાના શીલનો ભંગ થાય તેનો સંગ તજવો. મા, બહેન અને પુત્રી સાથે આપત્કાળ વિના એકલા રહેવું નહિ. પરસ્ત્રીનું કલંક અતિ મોટું છે. ભવ, બ્રહ્મા, ઇન્દ્ર, ચંદ્ર, પરાશર વગેરે મોટાને પણ તે કલંક લાગ્યું છે, તો જીવની શી ગણના?”","e":null,"s":["5/50/25-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":143,"k":"para","g":"ગઢપુરમાં શ્રીહરિ જીવેન્દ્રને કહે, “ભગવાનનું ગમતું કરે તેને બીજાં સાધન આપોઆપ થઈ જાય છે.”","e":null,"s":["5/72/26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":144,"k":"para","g":"ભડલીમાં શ્રીહરિએ વેરાગીને વાત કરતાં કહ્યું, “નિયમમાં વર્તે તેની જ મોટાઈ સાચી છે. શાહુકાર કરતાં ચોરની પાસે ધન વધારે હોય, તેથી કરીને ચોર શાહુકાર બની જતો નથી. નિયમ-ધર્મમાં રહે તે શાહુકાર છે. નિયમ-ધર્મની બહાર રહે તે ચોર છે. ભૂખ-તરસ અને દેહનું ભાન હોય ત્યાં સુધી વિધિ-નિષેધ પાળવાં જ જોઈએ. જ્ઞાનચક્ષુ વગરના અંધ કહેવાય છે તે વિષયજાલમાં બંધાય છે. તે જ્યારે જ્ઞાની ગુરુનો સંગ કરે છે ત્યારે મોહજાલમાંથી મુક્ત થાય છે.”","e":null,"s":["6/2/18-22"],"sv":["शाहुकार को चोर धरिके बानां । कितनेक धन सो लावत छानां ॥\n\n तेहि कर चोर शाहुकार न होवे । बुद्धिमान तपासि जोवे ॥\n\n नियम धर्म शाहुकार सो जानो । बिन नियम हि चोर प्रमानो ॥\n\n देहकि स्मृति न रहे जाहि । नियम धर्म न रहे ताहि ॥\n\n ज्ञान चक्षु हिन अंध कहावे । विषयरूप जाल में बंधावे ॥\n\n ज्ञानि गुरु को संग करे जबहि । मोह जालसें छोरे तबहि ॥"],"mt":false,"gl":null,"a":false},{"i":145,"k":"para","g":"મેથાણમાં શ્રીહરિએ એકાદશીનું વ્રત કરવા હરિજનોને મીઠા વચને કહ્યું, “એકાદશીનું વ્રત કરવું. બધી એકાદશીને દિવસે ફલાહાર ન કરવો તે ઉત્તમ વ્રત છે. તેમાં પણ દેવપોઢી, દેવઊઠી અને જળઝીલણી એ ત્રણ એકાદશીએ તો ફલાહાર ન જ કરવો અને આખી રાત્રિ જાગરણ કરવું અને આનંદથી કથા-કીર્તન કરવાં જેથી મહાપાતક નાશ પામે છે. કોટિ યજ્ઞ જેટલું એક એકાદશીના વ્રતનું ફળ કહ્યું છે. એકાદશીના દિવસે અન્ન ખાય તેને માંસ તુલ્ય કહ્યું છે. વળી ભગવાને કહ્યું છે કે એકાદશીને દિવસે અજાણતાં પણ અન્ન ખાય છે તે મને છાતીમાં બાણ મારે છે. એકાદશીને દિવસે તો કાચા અન્નનો પણ સ્પર્શ ન કરવો. જે રોગે કરીને પરવશ હોય તેણે એક વખત ફરાળ ખાવું અને અશક્ત હોય તેણે મોટી ત્રણ એકાદશી સિવાય બીજી એકાદશીઓમાં ફલાહાર કરવો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":146,"k":"para","g":"“દૈવીજન હોય તેને ધર્મનું પાલન ગમે છે, દીનાધીન વર્તે છે, સરળપણે રહે છે. ભગવાન અને ભગવાનના ભક્ત સાથે તેની પ્રીતિ અધિક ને અધિક ચઢતી રહે છે. જે નીતિમાં ચાલે છે તેને અપાર સુખ મળે છે. અનીતિ થોડી કરે તો પણ દુઃખનો પાર ન રહે. જાણીબૂઝીને જે અનીતિ આચરે છે તેને અતિવિપત્તિ પડે છે. જેમ જેમ અનીતિ કરે તેમ તેનું ફળ તેને મળતું રહે છે. જેને અનીતિ કરવામાં ડર નથી તેને તત્કાલ તેન બૂરું ફળ મળે છે.”","e":null,"s":["6/26/5-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":147,"k":"para","g":"શ્રીહરિએ સાયલા પાસે જેઠસુર બ્રાહ્મણના ગામે વાત કરતાં કહ્યું, “જ્ઞાનરૂપી નેત્ર હોય તેને બધું દેખાય છે. વિવેકબુદ્ધિ જેવી હોય તે પ્રમાણે જ્ઞાન થાય છે. અજ્ઞાનરૂપી અંધકારનું આવરણ હોય તેને નરકમાં મોક્ષ દેખાય છે, અને મોક્ષમાં નરક દેખાય છે. અજ્ઞાન નેત્રવાળો અંધ છે, તે અધર્મમાં ધર્મ માનીને વર્તે છે. આવા જમપુરીના અધિકારી મનુષ્યોને ઓળખી રાખવા ને તેનાથી દૂર રહેવું.”","e":null,"s":["6/37//22-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":148,"k":"para","g":"ગોંડળથી જેતપુર જતાં શ્રીહરિ બોલ્યા, “શાસ્ત્રમાં વર્ણાશ્રમનાં ધર્મ તથા જપ, તપ, દાન, વ્રત વગેરે સાધનો લખ્યાં છે, પણ તેનું ફળ સ્વર્ગલોક છે. પ્રાકૃતજનો તેને જ મુક્તિ માને છે. વર્ણાશ્રમનો ધર્મ રાખે તેને જ મનુષ્ય કહેવાય. સંત, બ્રાહ્મણ અને ગાયો સારુ ઇન્દ્ર વૃષ્ટિ કરે છે. તેથી બધી પ્રજાને લાભ મળે છે, પણ જ્યારે પશુવૃત્તિ થઈ જાય છે ત્યારે ઇન્દ્ર વરસતો નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":149,"k":"para","g":"“ધર્મનું પાલન કરવાથી ઇન્દ્ર વરસે છે. ધર્મ રાખવાથી ભૂમિ ધાન્ય આપે છે, દેવતાઓ બધા પ્રસન્ન રહે છે.”","e":null,"s":["6/50/11-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":150,"k":"para","g":"જેતપુરમાં શ્રીહરિએ થાળ જમીને વાત કરતાં કહ્યું, “સ્ત્રીરૂપી માયા ભયંકર છે. ભગવાનની આજ્ઞામાં જે ભક્ત વર્તે છે, તેને એ માયા પીડતી નથી. હરિ આજ્ઞારૂપી કિલ્લામાં જે વસે છે તે કુશળ રહે છે. જે જે તે આજ્ઞારૂપી કોટમાંથી બહાર પગ મૂકે છે તેને એ માયા તરત ખાઈ જાય છે. આ ઘોર કળિકાળ વચ્ચે અમે પ્રગટ્યા છીએ. ધર્મના સૈન્ય વિના અધર્મનું મહાજોર પાછું હટતું નથી. અધર્મ સામે લડવા અમે ધર્મરૂપી હથિયાર સંતો-ભક્તોને આપતા રહીએ છીએ. જ્ઞાનરૂપી તોપના ગોળા છૂટે છે જે અધર્મના સૈન્યને હણે છે.”","e":null,"s":["6/52/37-40"],"sv":["स्त्रिरूप माया विकट, इतने कुं घीरत नाहि ।\n\n हरिअग्या में वर्तहि, तेहिकर कुशल रहाहि ॥\n\n हरिअग्या रूप कोट में, वसत सो कुशल रहात ।\n\n जो जो निकसे बार हि, देखे तर्त सो खात ॥\n\n कलिकाल मध्य घोर, तामें हम प्रगट भयेउ ।\n\n अधर्म को महाजोर, धर्मसैन्य विन न हठहि तेऊ ॥\n\n धर्मरुप हथियार, संत-हरिजन कुं देत रहत ।\n\n अधर्म सैन्य देवे माट, ज्ञानरुप तोप चढाइकर ॥"],"mt":false,"gl":null,"a":false},{"i":151,"k":"para","g":"માંગરોળના રાજાને શ્રીહરિએ કહ્યું, “વર્ણાશ્રમની રીત જે મોટાઓએ કરી છે તે પ્રમાણે રહીને પ્રીતિ રાખવી. તેમની રીત પ્રમાણે ચાલવાથી સુખ થાય છે. દેહની રીત અને જીવની રીત જુદી છે. મોટાએ બાંધેલી મર્યાદા જેટલી લોપાય છે તેટલું દુઃખ તત્કાળ આવે છે. મોટા માણસો પણ મર્યાદા ઓળંગીને ચાલે તો ફજેત થાય છે. આમ, જેવું કરે તેવું પામે એ ન્યાયે સુખ અને દુઃખ મનુષ્યને પોતાના હાથમાં છે.”","e":null,"s":["6/68/4-6"],"sv":[],"mt":false,"gl":null,"a":false},{"i":152,"k":"para","g":"જૂનાગઢમાં શ્રીહરિએ દાદાભાઈને કહ્યું, “વિધિ-નિષેધનાં જે વચન છે તે અમારાં જ વચન છે, તે પ્રમાણે વર્તવું જોઈએ. આપ-ડહાપણથી તેનો ત્યાગ કરવો નહિ. ઔષધની રીત વૈદ્ય જાણે છે અને તે પ્રમાણે કરી પળાવે છે. કરી ન પાળે તો અનેક રોગ થાય છે. વૈદ્યના હાથમાં નાડી આપી તો વૈદ્ય કહે તેમ કરવું જોઈએ.”","e":null,"s":["6/78/10-15"],"sv":[],"mt":false,"gl":null,"a":false},{"i":153,"k":"para","g":"બાબરાના જનોને શ્રીહરિ કહે, “જ્યાં ધર્મનું પાલન નથી, ત્યાં મોક્ષ પણ નથી. પ્રગટ મોક્ષ આ સત્સંગમાં છે. ધર્મ, જ્ઞાન, વૈરાગ્ય અને ભક્તિ એ ચાર સિદ્ધ કર્યાં વિના કોઈ મોક્ષ પ્રાપ્ત કરી શકતું નથી, એ દૃઢપણે સૌ માનજો. એ ચારે અહીં સત્સંગમાં છે માટે સત્સંગનો યોગ સદા રાખજો.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":154,"k":"verse","g":"‘ધર્મ નહિં તિહાં મોક્ષ ન દેખે, ભક્તિ જ્ઞાન વૈરાગ્ય ન લેખે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":155,"k":"verse","g":"ચાર વિન મોક્ષ ન પાવે કોઉ, એસે નિશ્ચય કિયે સબ સોઉ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":156,"k":"verse","g":"સત્સંગ કો જોગ રખના સદાઈ, એસે કહે શામ સુખદાઈ.’","e":null,"s":["6/91/5-6"],"sv":[],"mt":false,"gl":null,"a":false},{"i":157,"k":"para","g":"બાબરામાં શ્રીહરિએ જીવાખાચરને કહ્યું, “કરોડોની વસ્તીમાં મનુષ્ય તેને કહેવાય કે જે શાસ્ત્રની વાતમાં સમજતો હોય. શાસ્ત્ર લોપીને ચાલે તેનો મોક્ષ થતો નથી. જેને મોક્ષનો ખપ નથી તે જ શાસ્ત્ર લોપે છે. જગતના લોકો જેવી જો ક્રિયા કરે તો જગતને ગમે છે. પણ દુનિયાની મરજી સાચવવા કરતાં આ જગતના કર્તા પરમેશ્વરની મરજી સાચવે તો બધાની સચવાય છે એ સર્વશાસ્ત્રનો સિદ્ધાંત છે. જે શાસ્ત્રનો લોપ કરે, તે ભગવાનનો દ્રોહી છે.”","e":null,"s":["6/92/18-22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":158,"k":"para","g":"ભુજમાં હરિજનોને શ્રીહરિએ કહ્યું, “પોતાની આવકનો દશમો ભાગ ભગવાનને અર્પણ કરવાનો શાસ્ત્રમાં કહ્યો છે તે આપવો જ જોઈએ, નહિ તો ગૃહસ્થને પંચ પાપ લાગે છે. તેનું જે નિવારણ નથી કરતો તેને તે પાપ દિવસે દિવસે દસ ગણું વધે છે. અમે તમને આ વાત જો કહી દેખાડીએ નહિ, તો અમને પાપ લાગે. ભગવાનનું છે ને ભગવાનને શું આપવાનું? એવું કહે તેને કૃતઘ્ની સમજવો. હરિજને તો તન, મન, ધન ભગવાનને અર્પણ કર્યાં છે. ભગવાનને કંઈ જોઈતું નથી, તે તો કસાઈને પણ નિત્ય ખવડાવે છે, તો જે પોતાના જન છે તેને કેમ નહિ આપે! ભગવાનની આવી ઉદાર રીત જે ભક્ત જાણતો નથી તેને દશમો ભાગ આપવામાં સંશય થાય છે. તનથી પણ ધન અધિક છે. તન તજાય પણ ધન ન તજાય. નિર્મળ મનનો સત્સંગ દિવસે દિવસે શોભે છે, એમ લોભીજનનું અંગ દિવસે દિવસે ઘટે છે.”","e":null,"s":["7/8/27-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":159,"k":"para","g":"જેતલપુરમાં શ્રીહરિએ નિયમ પાલનની વાત કરતાં કહ્યું, “કુસંગીજનો નિયમ ન રાખે, પણ સત્સંગીએ નિયમ બહાર પગ મૂકવો નહિ. નિયમ એ સંતનો સંગ છે. અક્ષરબ્રહ્મ પર્યંત સૌ કોઈ અમારા નિયમ પાળે છે. ન પાળે તેના માથે કાળ, કર્મ અને માયાનો ભય છે. નિયમવાળાને ક્યારેય ભય થતો નથી.”","e":null,"s":["8/17/29-32"],"sv":[],"mt":false,"gl":null,"a":false},{"i":160,"k":"para","g":"શ્રીહરિએ શ્રીનગરમાં હરિજનોને વાત કરતાં કહ્યું, “જે સત્સંગી હરિજન થયો તેને તો તપ કરવું કે વનમાં રહેવું તે કરતાં પણ વચનમાં વર્તવું તે શ્રેષ્ઠ છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":161,"k":"verse","g":"‘હરિજનમાત્ર હિ જોઉં, સત્સંગી નામ ધરાયે તેહિ,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":162,"k":"verse","g":"બચન મમં વર્તનો સોઉ, તપ-વન સે હિ શ્રેષ્ઠ તેહિ.’","e":null,"s":["8/4/15"],"sv":[],"mt":false,"gl":null,"a":false},{"i":163,"k":"para","g":"જેતલપુરમાં શ્રીહરિ કહે, “આવો ઉત્સવ કોઈ વાર થયો નથી. અમે બહુ પ્રસન્ન થયા. દેખાદેખી કોઈ કરે તો તેમાં ઘણાં વિઘ્નો આવે અને ધર્મનિયમ રહે નહિ ફેલી, અધર્મી, વ્યસની, વ્યભિચારી એવા માણસોના ઉત્સવ દેશોદેશમાં થાય છે. તીર્થનું મિષ લઈને એવાં નરનારી ઘરની બહાર નીકળીને તીર્થ કરવાનો વિશેષ આગ્રહ રાખે છે, પણ હેતુ જુદો હોય છે. તેઓ એવો પ્રેમ જણાવે કે તેની આગળ સત્સંગી હરિભક્તોનો ભાવ તો કાંઈ શોભે નહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":164,"k":"para","g":"“તીર્થ-ઉત્સવનું ફળ તો જીવને શુદ્ધ કરવો એટલું જ છે. દેહના સંગે કરીને દેહરૂપ થઈ રહેલો જીવ જે પાપ કરે છે તે દેહના સંગમાં રહીને કોટિ ગણું તેણે ભોગવવું પડે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":165,"k":"para","g":"“સુપંથનો ત્યાગ કરીને દેહના મદમાં જે કુપંથે ચાલે છે તેના દુઃખનો પાર આવતો નથી. એવાને ઉપદેશ ન કરવો. શાસ્ત્ર, સંત અને હરિભક્તને ઉલ્લંઘીને વર્તે તેને મનુષ્ય નહિ પણ ખર અને કૂકર (કૂતરા) જેવો જાણવો. તેવાને માટે તીર્થ કર્યાં નથી. તેને તીર્થનાં પાપ વજ્રલેપ થાય છે. બ્રહ્મચર્યવ્રત રાખીને તીર્થ કરે તો જ તે ફળીભૂત થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":166,"k":"para","g":"“પાણી વિનાનું ખેતર બગડે તેમ નિયમ વિનાનું કોઈ પણ પુણ્ય સિદ્ધ ન થાય. વાડ કર્યા વિના તથા ખબર રાખ્યા વિના જે ખેતી કરે તેને કાંઈ પણ હાથમાં ન આવે. હરાયાં પશુ ખાઈ જાય. વાડ કરી હોય તોપણ પંખી ખાધા વિના રહે નહિ, પણ એક મનુષ્ય સાચવનાર હોય તો પંખી પણ ન બેસે, તેમ ઇન્દ્રિયો અને મન પંખી સમાન જાણવાં, સંતનો સમાગમ રાખે ને ભક્તિ કરે તો સત્સંગરૂપી ખેતર સચવાઈ રહે.”","e":null,"s":["8/18/17-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":167,"k":"para","g":"જેતલપુરના મહોલમાં શ્રીહરિએ વાત કરી કે, “ગૃહસ્થના નિયમમાં ગૃહસ્થોએ વર્તવું. સત્સંગીએ સત્સંગીનો નિત્ય યોગ રાખવો. સંતસમાગમનું વ્યસન પાડવું. બાઈઓએ બાઈઓમાં સત્સંગ કરવો. મન, કર્મ, વચને નિયમમાં રહીને જે સત્સંગ રાખશે, તેને અંત સમે આ મૂર્તિનાં દર્શન થશે.”","e":null,"s":["8/20(19)/38-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":168,"k":"para","g":"કણભામાં શ્રીહરિ કહે, “સત્સંગ એ વજ્રનો કોટ છે, તેને મન-કર્મ-વચને આશરીને રહેજો. અને ધર્મમાં ખામી આવવા દેવી નહિ. ધર્મ એ મારું હૃદય છે અને ભવન છે.”","e":null,"s":["8/28/40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":169,"k":"para","g":"વડતાલમાં રામનવમી ઉત્સવ કરવા શ્રીહરિ પધાર્યા. મુખી તથા પુરજનોને બોલાવી વાત કરતાં કહ્યું, “ધર્મ વિના ભક્તિ કરે, વ્રત કે તીર્થ વગેરે કરે તે ફળીભૂત થતું નથી. ધર્મ લૌકિક અને અલૌકિક બે પ્રકારનો છે. તેમાં લૌકિક ધર્મથી દેવલોકની પ્રાપ્તિ થાય છે. તીર્થ, વ્રત, જપ, તપ વગેરે તથા કૂવા, વાવ, સદાવ્રત, ધર્મશાળા, સડક, પુલ કરાવવા તેમજ વર્ણાશ્રમ ધર્મ પાળવો વગેરે લૌકિક ધર્મ છે. તેનાથી બ્રહ્મલોક સુધીનાં સુખ પ્રાપ્ત થાય છે. અને ભાગવત ધર્મ છે તે અલૌકિક ધર્મ છે. તેણે કરીને ભગવાનનું ધામ પમાય છે. પ્રથમ લૌકિક ધર્મમાં નિષ્ઠા થાય તેના ફળસ્વરૂપે અંતે ભાગવત ધર્મમાં નિષ્ઠા પ્રાપ્ત થાય છે. ધર્મમાં જેને શ્રદ્ધા ન હોય તે અલૌકિક ધર્મ ન પાળે, એવું શાસ્ત્રનું રહસ્ય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":170,"k":"para","g":"“જીવનું હિત સત્પુરુષ વિના કોઈ કરી શકે તેમ નથી. સાંસારિક સંબંધીઓ છે તે ભગવાનના ભક્ત ન હોય તો સંસારને જ હિતકારી માને અને મોક્ષના માર્ગમાં સમજે નહિ. માત-તાત, બંધુ અને નારી પણ મિથ્યા સ્નેહને લીધે જીવને મોક્ષને માર્ગે ચાલવા દેતાં નથી. સંસારનું જ્ઞાન કરનારા ગુરુથી અજ્ઞાન ટળે નહિ. જેને જેવું જ્ઞાન તેવું તે આપે.”","e":null,"s":["8/47/12-30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":171,"k":"para","g":"વડતાલમાં જોબનપગીને શ્રીહરિ કહે, “ધર્મપાલનમાં અડગ રહેવું કઠણ પડે છે. તેને અગ્નિમાં બળી જવું સુગમ છે, પણ ધર્મની કલમ કઠણ પડે છે.”","e":null,"s":["8/61/33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":172,"k":"para","g":"બુધેજમાં શ્રીહરિએ પાળાઓને કંસાર પીરસતાં કહ્યું, “દૃઢ ટેક ન હોય તો પલકમાં બધું ઊડી જાય. સરોવર નીરથી ભર્યું હોય પણ પાળમાં થોડું કાણું પડે ને નીર સ્રવે તે ધીમે ધીમે પાળો ધોઈ નાખે. પછી બધું નીર ચાલ્યું જાય. તેમ સત્સંગ કરતાં કરતાં ઘણા ગુણો પ્રાપ્ત કર્યા હોય, પણ નિયમની ટેક શિથિલ થઈ તો જાણવું કે બધા ગુણો સ્રવી જશે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":173,"k":"para","g":"“નિયમ વિના માયિક-અમાયિક કોઈ વાત સિદ્ધ થાય નહિ. ભવ-બ્રહ્માદિક દેવો પણ નિયમ વિના દુઃખી થાય છે, તો અલ્પ જનોની શી વાત કહેવી? જે સમજુ ને ચતુર છે તે નિયમમાં વર્તે છે. નિયમ પાળે છે તેના ભાગ્યનો પાર નથી. ભવ, બ્રહ્મા ને ઇંદ્ર પણ જો નિયમ ભંગ થવાથી દુઃખી થયા હોય તો અલ્પ જનની વાત જ શી કરવી!”","e":null,"s":["9/8/9-13"],"sv":[],"mt":false,"gl":null,"a":false},{"i":174,"k":"para","g":"સમઢિયાળામાં લાખાખાચરને ઘરે શ્રીહરિ થાળ જમ્યા. પછી વાત કરતાં કહ્યું, “સંસાર તજે તોપણ સંસારનો તેટલો અને તેટલો જ રંગ રાખે છે. નામ અને વેશ ફર્યાં. વેઠ ગઈ અને ભીખ આવી તેટલો જ ફેર પડ્યો. ગૃહસ્થને તો લોક અને વેદ ઉલ્લંઘીને નારી રખાય નહીં અને રાખે તો નાત બહાર મૂકે કે રાજા દંડ દે, કાં નાક-કાન કપાય.”","e":null,"s":["9/48(49)/22-25"],"sv":[],"mt":false,"gl":null,"a":false},{"i":175,"k":"para","g":"સમઢિયાળામાં શ્રીહરિએ લાખાખાચરને વાત કરતાં કહ્યું, “ધર્મ હોય ત્યાં જ ભક્તિ અને જ્ઞાન હોય. જ્ઞાન હોય ત્યાં વૈરાગ્ય હોય. અને આ ચારે જ્યાં હોય ત્યાં ભગવાન પ્રગટ હોય અને ત્યાં જ મોક્ષપદ હોય. ભગવાન હોય ત્યાં ધર્મ કુટુંબે સહિત નિવાસ કરીને રહે છે. વેદો, સ્મૃતિઓ અને પુરાણોમાં કહેલો આ અલૌકિક મર્મ છે.”","e":null,"s":["9/49/27-28"],"sv":["धर्म तिहां भक्ति ज्ञान, ज्ञान तिहां वैराग्य रहेउ ।\n\n वैराग्य तिहां भगवान, भगवान तिहां मोक्षपद ॥\n\n भगवान तिहां धर्म, कुटुंब सहित सो निवास करत ।\n\n अलौकिक यह मर्म, वेद स्मृति पुराण तिहां ॥"],"mt":false,"gl":null,"a":false},{"i":176,"k":"para","g":"બોટાદના અદા શેઠને શ્રીહરિ કહે, “ત્રણ જાતિના સંત થાય તેનો ત્રણ યુગમાં બાધ નહિ, પણ કળિમાં તેનો દોષ છે, કારણ કે કળિ જેવી બુદ્ધિ થાય અને શ્વપચ લગીના જન ભેખમાં છાની રીતે પેસી જાય. એમ કળિમાં જે નીચ જાતિના છે તે ત્યાગાશ્રમને વટાળે છે. તે બહુ ઠેકાણે જોવામાં આવે છે. તે લોકો ધર્મના ઉપર ખેદવાળા હોવાથી વર્ણનો ઉચ્છેદ કરે છે... સત્સંગમાં જે બાઈ-ભાઈ છે તેને જેટલો સત્સંગનો ખપ છે તેટલું તેને વચન મનાવીએ છીએ. ખપ ઉપર જ અમે જોર કરીએ છીએ. અમારાં વચન જેને હિતકારી મનાય તેને અમે આગળથી તપાસીએ છીએ. સત્સંગમાં જે અમે શુદ્ધ વર્તન રખાવ્યાં છે તે નિર્દોષ જનોને પ્રિય લાગે છે. દોષિત હોય તે સત્સંગમાં પાર પડે નહિ.”","e":null,"s":["9/57(58)/9-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":177,"k":"para","g":"કરિયાણામાં ઓઢા ખાચરના ભવનમાં શ્રીહરિએ વર્તનની વાત કરતાં કહ્યું, “સત્સંગમાં નિયમ વિનાની એકેય વાત નથી. જે નિયમ વિનાની વાત કરે તે અતિ સરસ હોય તોપણ એક દિવસ તે ઘાત કરે છે. મૃત્યુ થાય અર્થાત્ સત્સંગ મૂકી દે ત્યારે તેની ગમ પડે છે. જેમ દેહમાં કોઈ અંગ ખંડિત હોય તે જણાઈ જાય છે, તેમ નિયમ-વર્તનમાં જેટલો ખંડિત તેટલો તે તરત દેખાઈ આવે છે. શરીર પર આભૂષણ એ શોભા છે તેનાથી કોટિ ગણી શોભા નિયમ છે. નિયમરૂપી ભૂષણ ધર્યું તે તેના જીવની શોભા છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":178,"k":"para","g":"“અનંત બ્રહ્માંડમાં નિયમ જેવું ભૂષણ ન મળે. નિયમ આગળ બીજાં ભૂષણ કલંકરૂપ અને દુઃખરૂપ છે. નિયમ તજીને સારાં વસ્ત્ર, આભૂષણ, મોતી વગેરે ધારણ કરે તે લાંછન રૂપ છે અને પાપરૂપ લાગે છે. તેથી અમે નિયમરૂપી વસ્ત્ર-આભૂષણ હરિભક્તોને પહેરાવ્યાં છે, જે તેમને આ લોક અને પરલોકમાં અધિકપણે શોભાવે છે. જેને સત્સંગમાં પ્રીત હોય તે આ વાત સમજી શકે.” આટલી વાત કરીને શ્રીહરિ દરબારમાં પધાર્યા.","e":null,"s":["10/9/28-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":179,"k":"para","g":"શ્રીહરિએ માંડવી બંદરથી પ્રથાપત્ર લખાવ્યો, “સત્સંગના જે નિયમ છે, તે ધર્મનાં અંગ છે અને પરમ આભૂષણરૂપ છે. તેનાથી આ લોક અને પરલોકમાં જીવ શોભે છે. જે નક્કી નિયમ રાખતા હોય તેથી સત્સંગ વધે અને તેને જ સાચા સત્સંગી કહેવાય. નિયમ બહાર જે વર્તે છે તેનું ફળ અહીં કેટલાક પામે છે તે નજરે દેખાય છે. નિયમ તોડીને ઠગની પેઠે ઉપરથી જે સારો દેખાતો હોય, તેનો સંગ બાઈ-ભાઈ કોઈએ કરવો નહિ. દૃઢ નિયમ રાખે છે તે બ્રહ્મમહોલને પામે છે. જે નક્કી નિયમ રાખતા હોય અને ત્યાગી-ગૃહીના નિયમ તથા સત્સંગની પ્રથા પ્રમાણે નક્કી વાત કરતા હોય તથા અમારો જે પ્રતાપ જોયા સાંભળ્યામાં આવ્યો હોય તેની વાત કરતા હોય, તેથી સત્સંગ વધે છે, અને તેને જ સાચા સત્સંગી જાણવા.”","e":null,"s":["10/27/29-41"],"sv":[],"mt":false,"gl":null,"a":false},{"i":180,"k":"para","g":"તેરા ગામમાં શ્રીહરિએ વાત કરતાં કહ્યું, “નિયમમાં વર્તનારા રાજા, ગુરુ અને સૌનું પ્રતિદિન માન વૃદ્ધિ પામે છે. ધર્મ રાખવાના તાનથી અમે વારે વારે પ્રકરણ ફેરવીએ છીએ. અધર્મનું કામ એવું છે કે ધર્મનું રૂપ લઈ પ્રવેશ કરે છે. અમારાં વચનમાં ચાલે તેને જ અમે સત્સંગી કહીએ છીએ અને ન વર્તે તેને કુસંગી કહીએ છીએ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":181,"k":"para","g":"“નિયમ વિના ચાલે તેટલો અવિવેક છે. નિયમ એ જ વેદનો સાર છે. નિયમ વિના વર્તે તે દંડવા યોગ્ય છે. નિયમમાં જે વર્તે છે તે સર્વેનું પ્રતિદિન માન વૃદ્ધિ પામે છે.”","e":null,"s":["10/41/35-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":182,"k":"para","g":"ભુજમાં ફૂલદોલનો ઉત્સવ રચાયો. તેમાં શ્રીહરિએ વાત કરતાં કહ્યું, “બાઈઓએ રંગ રમવો નહિ. જેને હરિ રીઝવવાનું તાન નથી અને રંગ રમે છે ને અપશબ્દ બોલે છે તે તો જમપુરીનાં અધિકારી છે. હરિભક્તોએ તો રંગ રમતાં કીર્તન જ ગાવવાં. ભગવાનને સંભારવા તો વારંવાર ઉત્સવ કરીએ છીએ. ભાંડ-ભવાઈ, વિવાહ, હોળી ને દારૂના સંસર્ગમાં આવે તે ડાહ્યા હોય તોપણ પશુ જેવા થઈ જાય છે. અને વર્ણાશ્રમ તથા નરનારીના વિવેકની બુદ્ધિ ગુમાવે છે. ભાંડ-ભવાઈમાં તથા કેફી ચીજ વગેરે અસાર વસ્તુમાં હરિભક્ત હોય તે ક્યારેય પગ ધરે નહિ. વિમુખજન હોય તે જ તેમાં રસ માને છે. હરિભક્ત થઈને નિંદિત કામ કરે તે હરિભક્ત ન ગણાય.”","e":null,"s":["10/49/20-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":183,"k":"para","g":"માંડવીમાં શ્રીહરિ કહે, “મને પ્રસન્ન કરવાનું જેને તાન હોય તે ધર્મ લોપે નહિ. ધર્મમાં જ બધા અર્થ રહેલા છે. જ્યાં સુધી તે જતન કરી રાખે, ત્યાં સુધી મોટા મોટા ભૂપોના કરતાં પણ શ્રેષ્ઠ છે. ધર્મે કરીને મેડી, મંદિર, ગામ, ખેતીવાડી, અન્ન, ધન, હાથી, ઘોડા, પાલખી, રથ વગેરે જે જે ચિંતવે તે બધું અપાર પ્રાપ્ત થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":184,"k":"para","g":"“ધર્મ રાખશે તેને રૂપિયા અને સોનું ચરણમાં આવીને પડશે. ભૂમિ પરના જેટલા યોગ્ય પદાર્થ છે તે બધાંય ધર્મ દેખશે ત્યાં આવશે, માટે સર્વેએ ધર્મ રાખવો. ધર્મ પ્રમાણે ખાવું, પીવું, પહેરવું, ગાવું, પણ ક્યારેય ધર્મને વિસારવો નહિ. ધર્મનો પરિવાર જે શાસ્ત્રમાં ગણાવ્યો છે તે બધાય ગુણ રાખવા. જેમાં જેવો ગુણ હશે તે પ્રમાણે તે કહેશે. ધર્મ રાખશે તેને ધર્મી કહેશે, નહિ તો અધર્મી કહેશે. ધર્મ વિનાની અપાર સંપત્તિ હશે તે શ્વપચની સંપત્તિ જેવી ગણાશે અને ધર્મ રાખતાં સાધારણ સંપત્તિ હશે તોપણ શોભશે. ધર્મી માણસો દેખવામાં દુઃખી જણાતા હોય અને ખાનપાન ઉત્તમ ન હોય તોપણ જેને ધર્મ અને હરિમાં સ્નેહ છે તે ઉત્તમ છે.”","e":null,"s":["11/2/15-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":185,"k":"para","g":"શ્રીહરિએ મોડા ગામનાં પુરજનોનો ભાવ જોઈ વાત કરતાં કહ્યું, “નિયમ ન પાળે ને ગુપ્તપણે પાપ કરે તેને ધર્મરાજા દેખે છે. તેમને મન કોઈ ગુરુ કે રાજા નથી. ગુરુ કે રાજાનું ચલણ અહીંયાં હોય અને પૂર્વના તપે કરીને ફાવે તેમ વર્તે, પણ દેહ મૂકીને તેનું ફળ ભોગવવું પડે છે. ભગવાન તો પોતાની મોટપ સામું જોઈને તત્કાળ કોપ કરતા નથી. જીવની સંગે સદાય ભગવાન રહેલા છે. તે જીવ તેના કર્માનુસારે ઊંચ-નીચ જન્મને પામે છે.”","e":null,"s":["11/12/7-17"],"sv":[],"mt":false,"gl":null,"a":false},{"i":186,"k":"para","g":"ધોરાજીમાં શ્રીહરિ કહે, “અમારા ગુરુ રામાનંદ સ્વામી એકાદશી વ્રતને મુખ્યપણે માનતા. ત્યાગીઓની જેમ ગૃહસ્થોએ પણ કંઈક ને કંઈક તપ-વ્રત કરવાં જોઈએ. એકાદશીને દિવસે અનાજ ખાનારને શાસ્ત્રોમાં ઘણું મોટું પાપ થવાનું લખ્યું છે. શાસ્ત્રમાં કહેલાં સર્વ સાધનનાં અનંત ફળ એકાદશીના વ્રતમાં રહેલાં છે. વર્ષની બધી એકાદશીઓ જે કરે તે ભગવાનના ધામમાં જાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":187,"k":"para","g":"“કોટિ યજ્ઞ કરાવે તથા કરોડો ગાયોનું નિત્ય દાન કરે, નિત્ય એકભાર સુવર્ણનું દાન કરે તેના કરતાં પણ એકાદશીનું વ્રત અધિક છે. કોટિ કલ્પ સુધી તપ્તકૃચ્છાદિક વ્રત કરે તોપણ તેની બરોબર થાય નહિ. વિધિ સહિત કરેલાં તીર્થમાત્રનું ફળ એકાદશીના વ્રતમાં આવી જાય છે.”","e":null,"s":["11/24/19-25"],"sv":[],"mt":false,"gl":null,"a":false},{"i":188,"k":"para","g":"શ્રીહરિએ ધોરાજીમાં વાત કરતાં કહ્યું, “ધર્મ એ સૌનો હિતકારી છે. જેની સહાયતા ધર્મ કરે છે તેને અગ્નિ બાળતો નથી. સાપ કરડે તોય તે મરતો નથી. મહા સિંધુમાં નાવ ડૂબે ને બધા મરી જાય, પણ જેને ધર્મમાં અનન્ય નિષ્ઠા છે તેને તે રક્ષા કરી બચાવી લે છે. દુઃખરૂપી સંકટ તે અધર્મનું ફળ છે અને દુઃખનો નાશ ન થાય, સંકટમાં પણ સુખ આવે તે ધર્મનું ફળ છે. ચોરીનું કર્મ અધર્મનો માર્ગ છે. ધર્મિષ્ઠ જન અધર્મને ઓળખીને એ માર્ગે જતો નથી.”","e":null,"s":["11/33/33-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":189,"k":"para","g":"જૂનાગઢમાં દીવાનને શ્રીહરિ કહે કે, “કામ, ક્રોધ અને લોભનો અમે કદી વિશ્વાસ કરતા નથી. અમારા સંતો અને હરિજનો ધર્મને આશરીને રહેલા છે. અધર્મ કુળમાં તે ક્યારેય પ્રીતિ કરતા નથી. અધર્મ આચરણથી ભૂમિનું રાજ્ય મળે તો તેને નરકનો સાજ માને છે. ભગવાનના ધામના સુખમાં જેની મતિ દૃઢ ચોંટી ગઈ છે તેને નિશદિન એ સુખનો વિચાર આવે છે. અક્ષરધામથી નીચે પ્રકૃતિપુરુષ સુધીનાં સુખમાત્ર કાળનું ભક્ષણ છે, એમ તે દૃઢપણે માને છે.”","e":null,"s":["11/38/17-23"],"sv":[],"mt":false,"gl":null,"a":false},{"i":190,"k":"para","g":"જૂનાગઢમાં શ્રીહરિએ મુકુન્દાનંદ વર્ણી પ્રત્યે વાત કરતાં કહ્યું, “જે જે અવતારના આશ્રિત થયા, તેના ધર્મ અવતારની હયાતી સુધી રહ્યા. પાછળથી ગુરુ અને સંત જેટલા થયા તે સૌએ અવતારોનાં ચરિત્રો અને સંતોની વાતો કરીને પોતાનું ગુજરાન કર્યું. ચરિત્ર કહેવાં અને સાંભળવાં તેને પરમ મોક્ષ માન્યો. જ્યારે બહુ અધર્મ વધ્યો ત્યારે મનુષ્યનો ઉદ્ધાર કરવા પરમાત્માએ સાચા સંત સહિત પ્રગટ થઈ ધર્મનું સ્થાપન કર્યું. શ્રીહરિ અને સાચા સંત વિના ભક્તિ યુક્ત ધર્મનું સ્થાપન કોઈથી થઈ શકે નહિ એ સત્ય વાત છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":191,"k":"verse","g":"‘સાચે શ્રીહરિ સંત વિન, ભક્તિ જુત ધર્મ જોઉ;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":192,"k":"verse","g":"સ્થાપન હોત ન ઓર સે, સત્ય વાત હે સોઉ.’","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":193,"k":"para","g":"“ધર્મ વિનાના ભક્તિ, જ્ઞાન અને વૈરાગ્ય મોક્ષ આપી શકતાં નથી. વહાણનાં બધાં અંગ સંપૂર્ણ હોય ત્યારે તે તરી શકે છે અને બીજાને તારી શકે છે. તેમાં જેટલાં છિદ્ર તેટલાં વિઘ્ન આવે છે. એમ મોક્ષમાર્ગમાં પણ એ રીત જાણવી.”","e":null,"s":["11/61/(51-b)/1-15"],"sv":[],"mt":false,"gl":null,"a":false},{"i":194,"k":"para","g":"માંગરોળમાં શ્રીહરિએ વાત કરતાં કહ્યું, “વ્યાવહારિક ધર્મ-ભક્તિ જુદાં છે. તેનું ફળ અલ્પ છે. વ્યાવહારિક આચાર્ય હોય, વ્યાવહારિક ગુરુ હોય કે સંતો હોય તે બધા શિશ્નોદરની તૃપ્તિ માટે ફરતા હોય છે. તે જન્મમરણ અને ચોરાશીમાં જાય છે. વ્યાવહારિક તીર્થ મનુષ્યમાત્ર કરે છે. વ્યાવહારિક મત પણ અપાર છે. ધર્મમાં પશુ, પક્ષી કરતાં પણ જે ઊતરતા છે, તેને ગમાર માણસો શ્રેષ્ઠ જાણે છે, તેને તે વિષય પ્રાપ્તિ માટે સ્વીકારે છે, ભાગવત ધર્મ તેથી ન્યારો છે. તે તો બધાં સાધન શ્રીહરિની પ્રસન્નતા માટે સ્વીકારે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":195,"k":"para","g":"“ભાગવત (એકાંતિક) ધર્મનિષ્ઠ ત્યાગી-ગૃહી સૌ કોઈ શ્રીહરિને પ્રસન્ન કરવા જે કંઈ સાધન કરે છે તેની તુલનામાં અન્ય સર્વે સાધન લવ સમાન તુચ્છ છે. અપાર સાધન પણ એકાંતિક ધર્મની તુલનામાં ક્યારેય આવતાં નથી. જેને શુદ્ધ વિચાર પ્રાપ્ત થયો છે, તેને આ વાતની ગમ પડે છે.”","e":null,"s":["12/15/31-38"],"sv":["भागवत धर्मनिष्ठ हि, त्यागी गृही जेते ।\n\n श्रीहरि प्रसन्न करन हित, साधन करत हें तेते ॥\n\n तेहि साधन कि लव सम, ओर साधन अपार ।\n\n समता लहे नहि कबहु, जानत शुद्ध विचार ॥"],"mt":false,"gl":null,"a":false},{"i":196,"k":"para","g":"અઢાર પરમહંસો કર્યા પછી તેમને શ્રીહરિએ કચ્છથી પાછા ગૃહસ્થાશ્રમમાં મોકલ્યા અને કહ્યું, “અમારાં જે વચન છે તેને અમૃત જેવાં માનવાં. તેને જે વિષ માને છે તેને વિષયનું ફળ મળે છે. અમારાં વચન સુખદાયી છે. ભાગ્ય હોય તેને વચન મનાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":197,"k":"para","g":"“ત્યાગી ગૃહી હરિભક્તોને અમને રીઝવવાનું તાન છે, તે જગતના ઉપહાસને ગણતા નથી, અમારા સિવાય કોઈમાં રાગ રાખતા નથી. જપ-તપ કરે છે. અમારી મરજી પ્રમાણે ચાલવું એથી ભારે બીજો મોક્ષ નથી.”","e":null,"s":["12/25/7-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":198,"k":"para","g":"શ્રીહરિએ ભુજના જગજીવન અને અન્ય વિપ્રોને અહિંસાધર્મની વાત કરતાં કહ્યું, “પાતાળથી પ્રકૃતિપુરુષના લોક સુધી જીવપ્રાણીમાત્ર અધિક સુખ માટે અપાર દુઃખ સહન કરે છે. સંસાર એવો છે કે સૌ દુઃખમાં જ સુખ માની બેસે છે. ચોરી કરવામાં અત્યંત દુઃખ પામવા છતાં ચોર લોકો ચોરી છોડતા નથી. લીલા કાંટામાં ચોરને બાળવામાં આવે છે તે જોવા છતાં ચોરી મૂકી દેતા નથી. જે રાજાના દીવાન બને છે તે તપના પુણ્ય કરીને બને છે. તપનું પુણ્ય જ્યારે થઈ રહે ત્યારે રાજાને તુચ્છ ગણે છે, ત્યારે રાજા તેનું કોઈક દ્વારા માન ખંડન કરે છે, છતાંય ન માને તો તોપે બાંધીને ઉડાવી દે છે. રાજાની મરજી પ્રમાણે ચાલે તેનો દિવસે દિવસે ઉદય થાય છે. તેવી જ રીતે વિવેકી જનો વેદની મર્યાદાનું પાલન કરે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":199,"k":"para","g":"“વેદની મર્યાદા લોપનાર દેવ હોય તોપણ દુઃખી થાય છે, તો મનુષ્યો દુઃખી થાય તેમાં કાંઈ સંદેહ નથી. મનુષ્યતનથી કોઈ પણ પ્રાણીની હિંસા કરવી જોઈએ નહિ. જે પ્રાણીની હિંસા કરે છે, તે નિર્વંશ થાય છે અને દૈત્યમાં અધમ ગણાય છે. યજ્ઞમાં પશુ હોમ કરે તેના પર દેવ કોપે છે.”","e":null,"s":["12/29/13-23"],"sv":[],"mt":false,"gl":null,"a":false},{"i":200,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ વણિક પ્રત્યે વાત કરતાં કહ્યું, “બુદ્ધિશાળી હોય પણ ભગવાનનું જ્ઞાન ન હોય ત્યાં સુધી તાજા જન્મેલા બાળક જેવા છે. સુંદર મનુષ્ય તન પામીને જે અધર્મ કરે છે તેને તેના અધર્મ પ્રમાણે યમપુરીમાં પાપ ભોગવવાં પડે છે. સત્પુરુષો જેનો નિષેધ કરે છે તે અધર્મ કહેવાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":201,"k":"para","g":"“જેને મોક્ષનો ખપ નથી તે દેહ તથા ઇન્દ્રિયોને યોગે કરીને તથા મલિન અંતઃકરણને યોગે કરીને નવા નવા ભોગ ઇચ્છે છે અને જીવને સદાય નિર્લેપ માનીને પાપમાં પ્રવર્તે છે.”","e":null,"s":["13/47/8-20"],"sv":[],"mt":false,"gl":null,"a":false},{"i":202,"k":"para","g":"ડભાણમાં શ્રીહરિએ વાત કરતાં કહ્યું, “અધર્મ વંશનો ત્યાગ તો જ થાય જો તેમાં દોષબુદ્ધિ થાય, તે સિવાય તલભાર પણ અધર્મ ત્યાગ ન થાય અથવા સંત હેતે કરીને અધર્મનો દોષ દેખાડે તો ત્યાગ થાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":203,"k":"para","g":"“ઉત્તમ ભોજન લીધા પછી ઊલટી થઈ તો ફરી તેના સામું દૃષ્ટિ જતી નથી, તેમ પંચવિષય ઊલટી કરી નાખ્યા હોય તો તેમાં ભાવ થાય નહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":204,"k":"para","g":"“હરિભક્ત થઈને એક દિવસ પણ સત્સંગ કરવો ચૂકે તેટલો તેને કુસંગ પેસે છે.” એમ શ્રીહરિએ હિંડોળે બેસીને વાત કરી.","e":null,"s":["14/17/33-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":205,"k":"para","g":"કારિયાણીમાં વસંત, હોરી અને ધુમારનાં પદો સંતોએ ગાયાં. પછી શ્રીહરિએ વાત કરતાં કહ્યું, “ભગવાનનો નિશ્ચય ક્યારેય ડગવો ન જોઈએ. પ્રહ્‌લાદનો નિશ્ચય મૂર્તિમાન દેખાય છે.” એમ કહીને શ્રીહરિએ ધર્મ-નિયમની વાત કરતાં કહ્યું, “પૂર્વે જે ભક્તો થઈ ગયા છે તે સર્વેએ ધર્મને આગળ રાખ્યો છે. એમના જીવનથી એ પણ જણાય છે કે જેણે ધર્મ લોપ્યો છે તેને મૂર્તિમાન અનુભવ થયો છે. નારદજી જેવા ભગવાનને કોઈ વહાલા નહિ, છતાં તેણે જો લગારેક ધર્મનો લોપ કર્યો તો મર્કટમુખ થયા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":206,"k":"para","g":"“ભગવાનને ધર્મ એવો પ્રિય છે. શૃંગિ, સૌભરિ, ચ્યવન વગેરે મોટા મોટા મુનિવરોએ થોડો ધર્મ લોપ્યો તો તરત ઘરબારી થઈ ગયા. ઇન્દ્રિયોરૂપી અશ્વોને વિચારપૂર્વક નિયમમાં રાખે તો જ ધર્મ પળે છે. જો ઇન્દ્રિયોને નિયમમાં ન રાખે, તો પંચવિષય અંદર પેસે છે ને અધર્મનું આચરણ થાય છે.”","e":null,"s":["14/27/22-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":207,"k":"para","g":"શ્રીહરિએ ગોંડળમાં સંત-હરિજનોને વાત કરતાં કહ્યું, “જપ, તપ, તીર્થ, વ્રત આદિનું ફળ એટલું જ છે કે જેમાં પ્રગટ ભગવાન કે ભગવાનના સંતની પ્રાપ્તિ થાય. એ મળ્યા પછી એમના વચનમાં વર્તે. મન, કર્મ, વચને સંત-હરિજનની સેવા કરે. મોક્ષની આ સાચી રીત છે, પણ દંભથી ક્યારેય મોક્ષ થતો નથી. મોક્ષની વાત દંભ હોય ત્યાં હોય નહિ. આ વાત સર્વે નિશ્ચય કરીને જાણજો.”","e":null,"s":["14/29/32-35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":208,"k":"para","g":"શ્રીનગરમાં શ્રીહરિએ પંડિતોની સભામાં વાત કરતાં કહ્યું, “ધર્મનો લોપ કરે તેના પર પ્રભુનો કોપ થાય છે. ભગવાનનો કોપ બધા મનુષ્યોને દેખ્યામાં આવતો નથી. ભગવાને બાંધેલી મર્યાદાને મિથ્યા કહે તેના પર તેમનો કોપ થાય છે. સુમતિ જન મર્યાદાનું પાલન કરે છે. જે મર્યાદા લોપતા નથી, તે સુખી રહે છે. તે આ લોક-પરલોકમાં દુઃખી થતા નથી. આ વાત નક્કી જાણવી.”","e":null,"s":["14/67/20-22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":209,"k":"para","g":"સારંગપુરમાં સંત-હરિજનો ધૂન કરી રહ્યા પછી શ્રીહરિએ વાત કરતાં કહ્યું, “ફૂલદોલ આવી રહ્યો છે. જગતમાં તો લાજ-મર્યાદા ત્યજીને વર્તે છે. મનના સંકલ્પ દરેકને ઉઘાડા કરે છે. આઠ ઠેકાણે અંતરની વાત છૂપી રહેતી નથી - વિવાહ તથા ફાગના દિવસોમાં, ભાંડભવાઈ જોવામાં, યુવતીના સંગમાં, દર્પણ સામે, બાળકને રમાડવામાં અને જળ-સ્નાન - એ વખતે મનને જે નિયમમાં રાખે તેને દેવ જેવો જાણવો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":210,"k":"para","g":"“મનની રીત તો પીપળાનું પાન, વીજળી, દીવાની શિખા, હાથીનો કાન, નદીનો પ્રવાહ, કુંભારનું ચક્ર અને વાયુ જેવી છે. મનને વશમાં ન રાખે તેને મનુષ્ય કહેવાય નહિ, તે તો પશુ સમાન થાય. હરિભક્ત થયા તેમણે ઇન્દ્રિયો, અંતઃકરણ અને દેહને નિયમમાં રાખવાં. નિયમમાં ન રાખે તેટલું દુઃખ આવે છે. અમારા વચનથી જે નિયમમાં નહિ વર્તે તેને કોઈ રાજા આવશે અને બળાત્કારે આવીને વર્તાવશે.”","e":null,"s":["14/86/17-29"],"sv":[],"mt":false,"gl":null,"a":false},{"i":211,"k":"para","g":"સારંગપુરમાં શ્રીહરિએ સંતોને પંગતમાં પાંચવાર ફરીને પીરસ્યું પછી વાત કરતાં કહ્યું, “સાધુ અને વિધવા નારીએ રંગે રમવું નહિ, સંસારીઓ ભલે રમે. તેમાં પણ જે હરિજન છે તે ગૃહસ્થો-ગૃહસ્થોમાં ને સ્ત્રીઓ-સ્ત્રીઓમાં રમે. આ સદાચાર સર્વેએ પાળવો.”","e":null,"s":["14/87/27"],"sv":[],"mt":false,"gl":null,"a":false},{"i":212,"k":"para","g":"હળવદમાં નારાયણજી વિપ્રના ભવનમાં શ્રીહરિ કહે, “નિયમ વિનાની વાત લખ્યા વિનાના કાગળ જેવી છે. નિયમ વિના ધર્મ કેવળ નામમાત્ર રહે છે. ભક્તિ, જ્ઞાન ને વૈરાગ્ય પણ ટકતાં નથી. નિયમમાં બધા સુખનાં સાધન રહ્યાં છે. અમારા હરિભક્તોએ સુખિયા રહેવું હોય તો નિયમ દૃઢ કરીને રાખજો.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":213,"k":"verse","g":"‘સુખ હોવન હિત હરિજન જિતને, નિયમ રખના દૃઢ કર તિતને.’","e":null,"s":["15/3/13-17"],"sv":[],"mt":false,"gl":null,"a":false},{"i":214,"k":"para","g":"શ્રીહરિએ ગઢપુરમાં જીવેન્દ્ર નૃપને વાત કરતાં કહ્યું, “જે જનો અનીતિ કરે છે તે દુઃખી જ થાય છે. નીતિવાળા સુખી થાય છે. જેવાં વૃક્ષ તેવાં ફળ આવે તેમ મનુષ્યમાં જેવો સંગ થાય તેવા ગુણ આવે છે, ને તેવી બુદ્ધિ થાય છે ને તે પ્રમાણે ખાવું, પીવું, પહેરવું રાખે છે.”","e":null,"s":["15/19/3-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":215,"k":"para","g":"મુક્તમુનિ કહે શ્રીહરિ એક વાત વારંવાર કહેતા, “ભગવાન અને ભગવાનના સંત જ્યાં વાસ કરે છે તે ભૂમિ તીર્થ બની જાય છે. અને યથાર્થ ધર્મનું પાલન કરનાર ભક્તો પણ જ્યાં વસે છે, તે તીર્થ થઈ જાય છે. અન્ય તીર્થ નામમાત્ર જ છે. આ વાત તે આમ જ છે.”","e":null,"s":["15/44/39-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":216,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સર્વગ્રંથનો અભિપ્રાય કહેતાં કહ્યું, “ભરતખંડમાં જન્મ પામી પાપ-પુણ્યનું જેને જ્ઞાન છે તે જ મનુષ્ય કહેવાય છે. જે પશુ-પંખી અને માછલાં મારીને ખાય છે, તેની રજેરજ વાત ભગવાનને ત્યાં લખાય છે. અને જે પ્રમાણે તેણે અહીંયાં પ્રાણીઓને માર્યાં છે કે માંસ ખાધું છે તે જ પ્રમાણે તેની ત્યાં દુર્દશા થાય છે. અને જે અહીં જીવ મારીને પ્રસન્ન થાય છે તે દેહ મૂકે ત્યારે નરકમાં પ્રાણીઓ તેને એ જ રીતે મારીને ખાઈને પ્રસન્ન થાય છે. ઈશ્વરની મર્યાદા એ મૂર્તિમાન ધર્મ છે. જે ધર્મ લોપે તેના પર ઈશ્વરનો કોપ થાય છે.”","e":null,"s":["15/54/30-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":217,"k":"para","g":"વડતાલમાં શ્રીહરિએ બાઈઓ અને ભાઈઓને પોતાના ધર્મમાં વર્તવાની વાત કરી કહ્યું જે, “આ મુજબ વર્તે છે તેમાં કળિ ક્યારેય પ્રવેશી શકતો નથી. સંત-હરિજન જો કુસંગ કરે તો તેમાં કળિ પ્રવેશ કરીને પોતાનું બળ દાખવે છે. નિયમનો કોટ દેખી કળિ થરથર કાંપે છે. જેને નિયમની કસર રહી તે મોક્ષનો લાભ ખોવે છે. સંત અને સત્સંગી વગર માયા કળિનાં રૂપ ધરે છે તેને કોઈ દેખી શકતું નથી.”","e":null,"s":["15/64/35-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":218,"k":"para","g":"શ્રીહરિએ પત્રમાં લખાવ્યું, “દેહાભિમાની હોય તે નિયમ લોપે છે અને વારંવાર પશુ-પંખીમાં જન્મ ધરે છે. ચોરાશી લાખ યોનિમાં વારંવાર ભટકે છે. અંતે તેની બૂરી ગતિ થાય છે. તે માટે બાઈ-ભાઈ હરિજને નિયમમાં ખબરદાર થઈને વર્તવું.”","e":null,"s":["15/77/37-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":219,"k":"para","g":"પત્રમાં શ્રીહરિ કહે, “સત્સંગી બાઈ-ભાઈએ પોતાના ગમે તેવા સંબંધી સાથે પણ એકાંતમાં બેસવું, ઊઠવું તથા ચાલવું નહિ તથા ગાફલપણું રાખવું નહિ. ગાફલપણું રાખે તેને સત્સંગ બહાર કરવો. મોક્ષનો ખપ હોય તેને પોતપોતાના નિયમમાં વર્તવું જ જોઈએ અને નિયમમાં વર્તશે તેને અમે અંત સમે વિમાન લઈ તેડવા આવીશું અને અવિચલ સુખ આપીશું. સત્સંગ અને ભગવાન તથા મોક્ષને માટે જેટલો ખપ હોય તેટલું જગતમાં અપમાન સહન કરી શકાય છે.”","e":null,"s":["15/79/22-27"],"sv":[],"mt":false,"gl":null,"a":false},{"i":220,"k":"para","g":"શ્રીહરિએ પત્રમાં લખાવ્યું, “ગુરુ, ગુરુના શિષ્યો ધર્મ-નિયમનો ત્યાગ કરી વર્તે છે તેટલા એ ચોર ઠરે છે. ભગવાનના ગુનેગાર છે. તેને જમદૂત પકડી જાય છે ને વિકટ જંજીરમાં જકડીને મારે છે.”","e":null,"s":["15/81/39-42"],"sv":[],"mt":false,"gl":null,"a":false},{"i":221,"k":"para","g":"સાંખ્યયોગી બાઈ-ભાઈને વર્તવાની રીત શ્રીહરિએ પત્રમાં કહી, “સત્સંગ અને સમાજમાં સંત-હરિભક્તો બેઠા હોય ત્યારે બીજો માણસ સાંભળે તેવી રીતે અપાન વાયુનો ત્યાગ થાય તો પચ્ચીસ દંડવત્ પ્રણામ કરવા. ચાર ઘડી ધૂન કરવી. એ બે વચન જે ન માને તેને સત્સંગી કહેવો નહિ, સત્સંગમાં ભલે સુખેથી રહે, માંદા ને ઘરડાનો દોષ નથી.”","e":null,"s":["15/91/19-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":222,"k":"para","g":"શ્રીહરિએ પોતાના ભક્તોને પત્રમાં લખાવ્યું કે, “સંત-હરિભક્તને પાછા પાડવા જે અધિક વર્તન દેખાડે છે તે કાળનેમિ ને રાવણ છે એમ જાણવું. તેને મરતી વખતે ભગવાન તેડવા આવતા નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":223,"k":"para","g":"“જે ભગવાન અને સંતને રાજી કરવા માટે તેમની મરજી લઈને વર્તે ને તેમનો નિષ્કપટભાવે દાસ થઈને વર્તે, ઉદ્દંડ મતિ રાખે નહિ, કોઈની સાથે દ્વેષ રાખે નહિ, પોતાને સૌથી કનિષ્ઠ માને અને સંત-હરિભક્તોને મોટા સમજે, એવા સંત સમર્થ હોવા છતાં લેશમાત્ર મોટપ રાખતા નથી, તેને સાચા સાધુ જાણવા.”","e":null,"s":["15/97/34-41"],"sv":[],"mt":false,"gl":null,"a":false},{"i":224,"k":"para","g":"કુંડળમાં શ્રીહરિએ મામૈયા, અમરા પટગરને ધર્મપુરનાં રાણી કુશળકુંવરબાની વાત કરતાં કહ્યું, “રાણીએ અમારી મરજીમાં સુખ જોયું. ભગવાનની મરજીમાં ધામથી પણ અધિક સુખ માને તે સમાન કોઈ ભક્ત નથી. મરજીમાં રહે છે તે મુક્ત છે, સિદ્ધ છે, પ્રેમી છે, અક્ષર છે. મરજીમાં સુખ માનનારને કોઈ દુઃખ રહેતું નથી. શૂળીએ ચઢવું ને પૂજા પામવી એ બધું ભગવાનની મરજીથી થતું જાણી બન્નેમાં આનંદ પામે છે. એવાથી ભગવાન પળમાત્ર દૂર થતા નથી. સુખ અને સાધનમાત્ર ભગવાનની મરજી પાળવામાં આવી જાય છે. ગ્રંથમાત્રનું રહસ્ય પણ તેમાં આવી જાય છે. મરજીમાં ન ચાલે તે બધા ગ્રંથો ભણે કે તીર્થ-વ્રતાદિક સાધન કરે કે બ્રહ્માંડની રચના કરે, પણ ભગવાનના શત્રુ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":225,"k":"para","g":"“મરજી જાણે તેણે જ સત્સંગ કર્યો છે, બીજાનો ન કર્યા બરાબર છે. મરજી ન સમજતાં જય-વિજય વૈકુંઠમાંથી પડ્યા. ભગવાનની સેવા કંઈ કામ લાગી નહિ. માટે સત્સંગ કરી ભગવાનની મરજીનું ધ્યાન રાખવું. મરજી પાળનારા પર્વતભાઈ આદિ ભક્તોનો દિવસે દિવસે અધિક રંગ રહ્યો છે. એવા અંગવાળા હોય તે સંત હરિભક્ત મોટા કહેવાય.”","e":null,"s":["16/38/17-41"],"sv":[],"mt":false,"gl":null,"a":false},{"i":226,"k":"para","g":"શ્રીહરિએ ઉગામેડીના વૈષ્ણવ પટેલને વાત કરતાં કહ્યું, “ભગવાનનું વચન લોપે તેટલો એ ભગવાનનો ચોર ઠરે છે. પછી તે ગમે તેટલો બુદ્ધિવાન હોય તોપણ શું? ગુનેગારને તો રાજા પણ તોપે ઉડાડે છે કે ફાંસી આપે છે, એ આંખથી પ્રત્યક્ષ દેખાય છે. ભગવાન પોતાના ગુનેગારને માફ કરે છે, પણ જમના હાથથી તે છૂટી શકતો નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":227,"k":"para","g":"“ભગવાનની બાંધેલી મર્યાદામાં ન વર્તે તેને શાસ્ત્ર અસુર કહે છે. નાક અને જીવ વિનાનું શરીર જેવું શોભતું નથી, તેમ નીતિ અને ધર્મ વિનાનો માણસ શોભતો નથી.”","e":null,"s":["16/42/27-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":228,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ હરિજનોની સભામાં વાત કરતાં કહ્યું, “જ્યાં નિયમનું પાલન છે ત્યાં ધર્મ છે ને જ્યાં ધર્મ છે ત્યાં ભગવાન છે ને ભગવાન છે ત્યાં ભગવાનનું અક્ષરધામ છે. જ્યાં ધામ છે ત્યાં અપાર અવિચલ સુખ રહ્યું છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":229,"k":"para","g":"“જ્યાં નિયમ નથી ત્યાં અધર્મ છે. અધર્મ છે ત્યાં પાપ છે ને પાપને લીધે જમપુરી છે. જમપુરી છે ત્યાં અપાર દુઃખ છે. નિયમને મૂકીને ચાલે છે તે અપાર દુઃખને પામે છે.”","e":null,"s":["16/45/37-42"],"sv":[],"mt":false,"gl":null,"a":false},{"i":230,"k":"para","g":"વડતાલમાં ફૂલદોલ પર શ્રીહરિએ વાત કરતાં કહ્યું, “જે નિયમ પાળે છે તેનામાં ભગવાન આવીને વસે છે. નિયમ રાખતો નથી તેનામાં અધર્મ નિવાસ કરે છે.” શ્રીહરિનાં આવાં વચન સાંભળી સંતો-ભક્તો હાથ જોડી બોલ્યા, “હે, મહારાજ! અમે આપના આપેલા નિયમનો ક્યારેય ત્યાગ કરીશું નહિ.” આ સાંભળી શ્રીહરિ ઘણું પ્રસન્ન થયા.","e":null,"s":["16/64/39-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":231,"k":"para","g":"વડતાલમાં શ્રીહરિએ સંતો-ભક્તોને વાત કરતાં કહ્યું, “જે જે નિયમ ધાર્યા હોય તે મનન કરીને યાદ કરવા. મનન ન કરે તો નિયમ ધાર્યા ન ધાર્યા સમાન છે. અમારું દર્શન ટાણે ટાણે ઘણા સંતો-ભક્તો કરે છે, પણ મનન ન કરે તો તે સ્મરણમાં રહેતું નથી. એ સ્મરણમાં રહે તે માટે અમે હુતાશની, દિવાળી-અન્નકૂટ, વસંતપંચમી જેવા ઉત્સવ ઊજવીએ છીએ, યજ્ઞ કરીએ છીએ, ચોરાસીમાં વિપ્ર જમાડીએ છીએ, દાન દઈએ છીએ, વિપ્રને જનોઈ ને કન્યાદાન દઈએ છીએ - એ બધું મનન કરવાથી યાદ રહે, ને તે ભક્તને અમારું સ્મરણ અંતકાળે થઈ આવે તો તેનું કલ્યાણ થાય. આ સિદ્ધાંત વાત છે.”","e":null,"s":["16/69/21-27"],"sv":[],"mt":false,"gl":null,"a":false},{"i":232,"k":"para","g":"વડતાલમાં અન્નકૂટ પર આવેલ સંતો-ભક્તોને શ્રીહરિએ કહ્યું, “જપમાળા ફેરવવી તે નિત્ય નિયમ રાખીને ફેરવવી. નિયમ વિના જે ફેરવે છે તેને શાસ્ત્રકથિત ફળ મળતું નથી. માટે આજથી સંતો, બ્રહ્મચારીઓ, પાર્ષદો, સાંખ્યયોગી બાઈઓ અને સર્વે હરિભક્તોએ શરીર નીરોગી હોય ત્યાં સુધી નિત્યે પચાસ માળા ફેરવવી, તેમાં પ્રમાદ ન કરવો, અવશ્ય ફેરવવી. જેમ ભોજન કરવાનો નિયમ ભૂલતા નથી, તેમ માળાનો નિયમ રાખવો. નિયમ વિનાની માળા ફેરવે તે નિષ્ફળ કહેવાય છે. ક્યારેક ભૂલી જવાય તો બીજે દિવસે બમણી ફેરવવી. બે દિવસ ભૂલી જવાય તો ઉપવાસ કરવો. પચાસથી અધિક ફેરવે તો વધુ રાજી થઈએ છીએ.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":233,"k":"para","g":"પછી સંતો-ભક્તોએ શ્રદ્ધા પ્રમાણે માળાના નિયમ લીધા તેને શ્રીહરિએ છાતીમાં ચરણારવિંદ આપ્યાં. બાઈઓએ પણ નિયમ લીધો. શ્રીહરિ પ્રસન્ન થઈને બોલ્યા કે, “અમારા વચને કરીને જે નિયમ રાખે છે તેવાં મોટાં ભાગ્ય બીજા કોઈનાં નથી.”","e":null,"s":["17/6/27-37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":234,"k":"para","g":"શ્રીહરિએ ગોંડલના ભૂપને કહ્યું, “ધર્મ-નિયમ એ દિવ્ય અંબર અને આભૂષણ છે. આવો મહિમા જણાશે તો નિયમ રાખવામાં સુગમતા રહેશે. જે નિયમ નથી રાખતા તે જમપુરીના અધિકારી થાય છે ને અપાર કષ્ટ સહે છે. પ્રમાદ જ્યારે મિત્ર બને ત્યારે તે બધાય હિતેચ્છુ સાથે વેર કરાવે છે. સુલટ વિચાર કરવામાં પ્રમાદ રહે તેટલો સત્સંગનો રંગ ચઢે નહિ. પ્રમાદથી સત્સંગ, સંત અને હરિભક્તની અરુચિ થાય છે.”","e":null,"s":["17/12/5-15"],"sv":[],"mt":false,"gl":null,"a":false},{"i":235,"k":"para","g":"પંચાળામાં શ્રીહરિએ નારીધર્મ સમજાવતાં કહ્યું, “સધવા કે વિધવા કોઈ નારીએ સ્વતંત્ર રહેવું નહિ. સ્વતંત્ર રહેવામાં ઉમા જેવી સતી સ્ત્રીઓ દુઃખી થઈ. સ્ત્રી કામિની છે, તેને લીધે મોટા મોટા દેવ અને ઋષિઓ વિકારી બન્યા છે. જે સ્ત્રી વિધવા થાય તેણે પુરુષ કરવાની ઇચ્છા હોય તો કરવો, પણ કલંકથી ડરવું. માતા-પિતાના કુળને તથા સત્સંગને લાંછન દેવું નહિ. જેને માથે લાંછન આવે નહિ તે સત્સંગમાં શ્રેષ્ઠ છે. વિષયાસક્તિ વિઘ્ન કરે છે, માટે વિષયની અરુચિ રાખવી અને વિધવાના ધર્મમાં નટ દોર ઉપર ચાલે તેમ સાવધાન થઈને ચાલવું.”","e":null,"s":["17/14/18-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":236,"k":"para","g":"શ્રીહરિએ મુક્તમુનિને પત્રમાં લખ્યું, “નીતિ ઓળંગીને ચાલે તેને અસુર જાતિ જાણવો. ભગવાનથી ડરીને ચાલે તે મનુષ્ય હોવા છતાં દેવ જેવો છે.”","e":null,"s":["18/15/12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":237,"k":"para","g":"ગઢપુરથી શ્રીનગર મંડળ લઈને સંતોને મોકલતી વખતે શ્રીહરિએ વાત કરતાં કહ્યું, “નગરમાં બે વાર ઝોળી માંગજો. કેટલી ભિક્ષા મળે છે તેની અમને ખબર મોકલતા રહેજો. પુરજનોનો ભાવ ઝોળી અને સંતોને કેવા વચનથી બોલાવે છે તે પરથી જણાઈ આવશે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":238,"k":"para","g":"“સંતો પાસે પુરુષ હરિજન આવે પણ બાઈ હરિજન ન આવે તે ખ્યાલ રાખવો. પાસે આવનારના નિયમને નિત્ય તપાસવા. નિયમ વગરનો સત્સંગ મૂળ વગરના વૃક્ષ જેવો છે. જે જન સંતનો સમાગમ કરે છે તેને તેટલો સત્સંગ રહે છે. જે નક્કી વાત છે તે અમે કરતા રહીએ છીએ. અમને લલોપચો કરતા આવડતું નથી. જે જે ગામમાં બાઈ હરિભક્તો છે તેમાં જેને જેટલું નિયમમાં વર્તવાનું અધિક તાન હોય તેનો સમાગમ બીજી બાઈઓએ કરવો.”","e":null,"s":["19/18(17)/20-25"],"sv":[],"mt":false,"gl":null,"a":false},{"i":239,"k":"para","g":"ગઢપુરમાં શ્રીહરિ કહે, “અમારા વચનનું જેટલું પાલન તેટલી અમારી પૂજા છે. વચનમાં કુતર્ક કરે તેના પર અમે પ્રસન્ન થતા નથી. અમારા વચનને મૂકીને બીજું કરે તેને અમે મનમુખી ગણીએ છીએ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":240,"k":"para","g":"“મનમુખી ફાવે તેવો ગુણિયલ હોય તોપણ તેને અસુર જાણવો. આવા અસુર અમારાં આચરણ સાંભળીને અમારી દેશી કરે છે. મોક્ષભાગી જને આવા મનમુખી આચરણવાળા અસુરનો ત્યાગ કરવો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":241,"k":"para","g":"“મોક્ષના ખપ વિના ફાવે તેમ વર્તે તેની સાથે અમારે લેવા દેવા નથી, તેનું કરેલું તે ભોગવે, પણ જેને મોક્ષનો ખપ છે તેણે સત્સંગની રીતે નિયમમાં વર્તવું.”","e":null,"s":["19/19(18)/20-24"],"sv":["हमारे वचन करत हि जितना । हमकुं पूजत रहाये तितना ॥\n\n जितना कुतर्क करत यामें । हम नहि प्रसन्न होवत तामें ॥\n\n हमारे बचन बिन और जेता । मानत हम मनमुखी कर तेता ॥\n\n मनमुखी होय च्हाय जो जेसा । असुर की जाति देखना तेसा ॥\n\n हमारी देशी असुर हि जितने । आचरण हमारे सुनि तितने ॥\n\n लेवहि हमारे पिछे केते । असुर बड़े रहे जो एते ॥\n\n मोक्ष ताके खप होय जेहा । असुर कुं नहि मानहि तेहा ॥\n\n मोक्ष के खप न होय जाहि । च्हाय तेसे चलो ते ताहि ॥\n\n ता उपर नहि हकम हमारे । असुर की बात असुर रहे धारे ॥\n\n मोक्ष के रूप न रहेउ जाहि । च्हाय ते से चलहि यह ताहि ॥"],"mt":false,"gl":null,"a":false},{"i":242,"k":"para","g":"જવારજમાં શ્રીહરિ કહે, “બ્રાહ્મણો લસણ વગેરે અભક્ષ્ય વસ્તુ છાની રીતે ખાતા થઈ ગયા, તેથી તેમની વચનસિદ્ધિ રહી નહિ, બ્રહ્મચર્ય પણ રહ્યું નહિ.”","e":null,"s":["19/36(35)/11-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":243,"k":"para","g":"સુરતમાં શ્રીહરિએ હરિભક્તો પ્રત્યે વાત કરતાં કહ્યું,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":244,"k":"verse","g":"‘હરિ કહે હમારે બચન જીતનાં, વજ્ર કે કોટ સમ રહે તિતનાં;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":245,"k":"verse","g":"અક્ષરધામ બચન હમારે, જુદે ન રહે કોઉ કલ્પ લગારે.’","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":246,"k":"para","g":"“અમારાં વચન વજ્રના કોટ સમાન છે. અમારા વચનથી અક્ષરધામ કોઈ કાળે લેશ પણ જુદું નથી. અમારા વચનમાં રહે તેને વિઘ્ન આવતાં નથી. આજ્ઞારૂપી વજ્રનો કિલ્લો તજીને મનમાન્યું વર્તન કરે તેને માથે બધાં જ વિઘ્ન રહ્યાં છે. ઉન્મત્ત વર્તન એ જ વિષમ દેશકાળ છે. ધર્મનો લોપ કરે છે તે અંતર્યામીથી અજાણ્યું રહી શકતું નથી. પળેપળનું તે નિરંતર જાણે છે. જે જેવું કર્મ કરે છે તેને તેવું ફળ ભગવાન આપે જ છે.”","e":null,"s":["27/82/28-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":247,"k":"para","g":"સુરતના નાના શેઠને શ્રીહરિ કહે, “સ્ત્રીઓને ઉપદેશ દેવો તે સત્સંગીની રીત નથી. દારૂ અને અગ્નિ ભેગા થાય તો ઊડ્યા વિના રહે નહિ. અગ્નિના યોગથી ઘી નરમ થયા વિના રહે નહિ. પથ્થરનો પણ અગ્નિના યોગે રસ થઈ જાય છે. પુરુષ ને સ્ત્રી પરસ્પર અગ્નિ જેવાં છે. જળના યોગે કરીને બીજ ઊગ્યા વિના રહેતું નથી. નારીના પ્રસંગ વિના કામનું જોર ચાલતું નથી. રજસ્વલાના પડછાયાથી સર્પ પણ આંધળો થયાનું સંભળાય છે. ચ્યવન ઋષિ તપથી સિદ્ધ થયેલા હતા, છતાં રાજકન્યાનાં દર્શનમાત્રથી વિષયમાં રાગ થયો. માટે નિયમરૂપી કોટમાં રહે તેનો જ વિષયથી પરાભવ થાય નહિ.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":248,"k":"para","g":"શ્રીહરિની વાત સાંભળી નાના શેઠ લજ્જા પામી ગયા ને કહ્યું, “મારામાં ઉન્મત્તાઈ ચઢી અને નિયમ ત્યાગ્યા. મેં સો બાઈઓને શિષ્યા કરી છે, હું કહું તેમ તે કરે એમ છે. તે બાઈઓએ સહિત હું સત્સંગમાં આવવા ઇચ્છ છું. કાલે મારી રસોઈ લો ને ગુનો માફ કરો. બાર વર્ષ હું વિમુખ રહ્યો ને ફાવે તેમ ચાલ્યો. મારા જેવો કોઈ અધમ નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":249,"k":"para","g":"આમ, બહુ પ્રકારે અનુનય કર્યો. પછી શ્રીહરિએ સંતો-ભક્તોને પૂછી નાના શેઠને સત્સંગમાં લીધા.","e":null,"s":["27/85-86"],"sv":[],"mt":false,"gl":null,"a":false},{"i":250,"k":"para","g":"સુંદરિયાણામાં પુરની બહાર સંતો-ભક્તોની સભામાં શ્રીહરિ કહે, “ભગવાનનો આશ્રય કરે પણ ધર્મ-નિયમ ન રાખે તો તે આશ્રય ભાંગેલા નાવ સમાન છે. ધર્મ નિયમ વિનાની કોઈ વાત ફળીભૂત થતી નથી. જે માણસ વ્યભિચારી હોય તે મનુષ્ય હોવા છતાં કૂતરાની મતિમાં ખપે છે. અધર્મી સત્સંગમાં રહેતો હોય તોપણ છુપાયો રહેતો નથી.”","e":null,"s":["28/88/(87)/19-22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":251,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":252,"k":"para","g":"જેને શ્રીહરિને વિષે નિશ્ચય ન હોય અને અધર્માચરણવાળો હોય, તેને ધર્મવંશી જાણવો નહિ, પરંતુ પ્રગટ હરિનો જેને નિશ્ચય હોય તેને દૃઢ ધર્મવંશી જાણવો. આવી રીતે શ્રી સહજાનંદ સ્વામીએ પોતાના સંત-હરિભક્તો પ્રતિ કહ્યું.","e":null,"s":["1/4/11-12"],"sv":["धर्मकुल में रहे धर्म की रीता । सो धर्मवंशी जानहु पुनीता ॥\n\n अधर्माचरण कर ही कोई । धर्मवंशी न जानना सोई ॥\n\n प्रणट हरि का निश्चय जाकु । धर्मवंशी दृढ जानना ताकु ॥\n\n ऐसे कह सहजानंद स्वामी । हरिजन संत प्रति अंतर जामी ॥"],"mt":false,"gl":null,"a":true},{"i":253,"k":"para","g":"જગતના સુખને માટે ઈશ્વરે બાંધેલા નિયમો તોડે તો બ્રહ્માદિકની પણ લાજ ન રહે અને અપયશ તથા દુઃખના પાત્ર બને, માટે નિયમમાં વર્તવું જોઈએ.","e":null,"s":["2/49/38-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":254,"k":"para","g":"શ્રીહરિના વચનનો જેને લેશમાત્ર ડર નથી તેને માથે યમનો દંડ રહે છે ને તે અતિશય ક્લેશ પામે છે. તેનાં દુઃખ વર્ણવી ન શકાય તેટલાં છે. સુમતિ સંત તેને જાણે છે ને દેહ પર્યંત ભગવાનના વચનમાં વર્તે છે. આજ્ઞારૂપી કોટમાં તે નિર્ભય રહે છે.","e":null,"s":["4/97/39-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":255,"k":"para","g":"જે પોતાને અક્ષર માનીને આજ્ઞામાં વર્તન કરે છે, તે પોતાનું સ્વરૂપ શુદ્ધ નિર્મળ દેખે છે. જે દેહરૂપે વર્તન કરે છે તેને આડે મેરુ જેવો અટૂટ પડદો આવી જાય છે. તેથી તે પોતાના રૂપને જાણી શકતો નથી.","e":null,"s":["5/13/37"],"sv":[],"mt":false,"gl":null,"a":true},{"i":256,"k":"para","g":"હરિના વચનમાં જે રહે છે તેના પર કાળકર્મ કે માયા આદિનું જોર લેશ પણ ચાલતું નથી. સર્વે ભગવાનની આજ્ઞામાં થર થર કંપતાં રહે છે. સ્થાવર-જંગમ જીવ સૃષ્ટિ શ્રીહરિની નિયામક શક્તિને આધીન રહે છે. કાળ, કર્મ ને માયા શ્રીહરિના ભક્ત સિવાય સર્વેને પોતાને આધીન વર્તાવે છે. ભગવાનનું વચન મૂકી નિજ છંદે વર્તે તો મુક્ત હોય તે પણ તત્કાળ દુઃખ પામે છે.","e":null,"s":["5/47/34-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":257,"k":"para","g":"હરિની આજ્ઞા અનુસાર મિતાહારી ભોજન લે છે તે નિત્ય ઉપવાસી છે. સાધુ ગ્રાસે ગ્રાસે હરિનું સ્મરણ કરે, વચન મુજબ દિવસમાં એકવાર જમે, તે સદા ઉપવાસી છે.","e":null,"s":["5/48/6-7"],"sv":[],"mt":false,"gl":null,"a":true},{"i":258,"k":"para","g":"વચનમાં રહે તેને જ ધર્મ અને ભક્તિ વધે છે. જ્ઞાન, વૈરાગ્ય અને સુખ-સંપત્તિ પણ વચનમાં જ રહ્યાં છે. ભગવાનનું ધામ પણ વચનમાં જ છે. સાધનમાત્ર વચનમાં આવે છે. વચન બહાર ચાલે તેને દુઃખ જ પ્રાપ્ત થાય છે. વચન તજ્યું તેણે બધાં સાધન તજ્યાં છે. સાધન વિના સુખ-સંપત્તિ ચાહે તે મૂર્ખ છે. વચન એ જ ખરાં વસ્ત્ર-આભૂષણ છે. એમ વચનમાં પરમ લાભ છે, તેને વિવેકી સંત-હરિજનો જાણે છે.","e":null,"s":["5/48/17-26"],"sv":[],"mt":false,"gl":null,"a":true},{"i":259,"k":"para","g":"શ્રીહરિએ બાંધેલી મર્યાદા ન લોપે ત્યાં સુધી દિનદિન પ્રતિ સત્સંગની વૃદ્ધિ થતી રહે છે, જે દિવસે મર્યાદાનો લોપ કરવાનું શરૂ થશે તે દિનથી બુદ્ધિમાં અંધકાર થઈ જશે.","e":null,"s":["6/5/19"],"sv":[],"mt":false,"gl":null,"a":true},{"i":260,"k":"para","g":"ત્યાગી સંતો એ શ્રીહરિનાં ઘર છે. તે સર્વને ધર્મમાં રખાવવાની ચાડ શ્રીહરિ રાત-દિવસ રાખતા. ત્યાગી-ગૃહીમાં જે વધારે ધર્મ રાખે તેમના ઉપર શ્રીહરિ વધુ પ્રેમ રાખતા. તેને બોલાવતા, સંભારતા. ધર્મ રાખીને જેટલી ભક્તિ કરે તે સર્વ શ્રીહરિ અંગીકાર કરતા. જ્ઞાન, વૈરાગ્ય, ત્યાગ અત્યંત હોય કે નિશ્ચય ભક્તિ અપાર હોય, અહોનિશ ધ્યાન કરે, પણ જો ધર્મપાલન ન હોય તો શ્રીહરિ પ્રસન્ન થતા નહિ. ધર્મ વિના કોટિ જન્મ સુધી કોઈ ભક્તિ કરે તો પણ શ્રીહરિ તેને સ્વીકારતા નહિ. એવા ધર્મહીનને શ્રીહરિ વિમુખ કહેતા. તેને ક્યારેય ચાહતા નહિ.","e":null,"s":["6/42/32-37"],"sv":[],"mt":false,"gl":null,"a":true},{"i":261,"k":"para","g":"શ્રીહરિ સમક્ષ સંત-હરિજન આરતી ઉતારતા પછી સ્તુતિ ને નારાયણધૂન થતી. બાઈઓ બાઈઓમાં ને ભાઈઓ ભાઈઓમાં બેસીને ધૂન કરતાં. બાઈઓ પુરુષોને જે સ્વામિનારાયણ કરતી નહિ, તેમ પુરુષો પણ બાઈઓને જે સ્વામિનારાયણ કરતા નહિ. આવો આ સત્સંગનો ધારો રહ્યો છે.","e":null,"s":["6/68/19"],"sv":[],"mt":false,"gl":null,"a":true},{"i":262,"k":"para","g":"મહિલાઓ મહિલાવર્ગમાં બેસીને ગીતો ગાય, કીર્તન-ભજન કરે તેમાં કોઈ બાધ આવે નહિ. એ જ રીતે પુરુષો પુરુષવર્ગમાં બેસીને કીર્તન ગાય, કથાવાર્તા કરે. આ પ્રણાલી કદી ભુલાય નહિ. સત્સંગની આ સદાયની પ્રથા છે જેને બધા હરિભક્તો સહર્ષ જાળવી રહ્યા છે, ક્યારેય તૂટવા દેતા નથી.","e":null,"s":["6/71/7-12"],"sv":[],"mt":false,"gl":null,"a":true},{"i":263,"k":"para","g":"પુરુષો અને મહિલાઓ પોતપોતાના ધર્મમાં રહીને શ્રીહરિની સેવા કરતાં. ધર્મ પાળે તેને શ્રીહરિ મુખ્ય ગણતા. સત્સંગની પ્રથા જ એવી બાંધી છે કે ધર્મમાં રંચમાત્ર કોઈ હરિભક્ત શિથિલ જણાય તો મુખ્ય જવાબદાર હોય તે તેને તુરત વિમુખ કરે. જેને સત્સંગનો ખપ છે તે ધર્મને મુખ્ય કરીને રાખે છે. તેથી દિવસે-દિવસે તે અધિક ને અધિક વૃદ્ધિ પામતો રહે છે.","e":null,"s":["6/71/37-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":264,"k":"para","g":"સત્સંગના નિયમ સૌ માટે રક્ષાના કોટ છે. નિષ્કામાદિ પંચવ્રતે પૂર્ણ ગુરુ જેને મળે છે તેને એ કોટ વહાલો લાગે છે. ગુરુના સંગે નિયમવાળો નિર્ભય થાય છે. પછી કામાદિ શત્રુ સામે પણ તે ક્યારેય ડગતો નથી.","e":null,"s":["8/31/7-8"],"sv":[],"mt":false,"gl":null,"a":true},{"i":265,"k":"para","g":"અધર્મનાં મૂળ કાપવા શ્રીહરિએ સંતો-ભક્તોના નિયમ રચ્યા છે. શ્રીહરિએ જેટલાં કંઈ નિયમ આપ્યા છે તે પ્રત્યેક નિયમમાં તેમણે અદ્‌ભુત દૈવત મૂક્યું છે. દૈવત વિનાનો એકપણ નિયમ નથી.","e":null,"s":["10/11/7,10"],"sv":[],"mt":false,"gl":null,"a":true},{"i":266,"k":"para","g":"નીતિ એ હરિનું સ્વરૂપ છે. નીતિમાનને ખાનપાન પણ દેવ સમાન મળે છે, તથા જગતમાં તેનું સૌ પ્રમાણ કરે છે. નીતિ એ જ ધર્મ છે, અનીતિ પાપ છે, અને દુઃખરૂપ છે. વિષ ખાઈને સુખ માનવું તેમ નીતિ વિનાનું સુખ ઇચ્છે તેને સમજવું. શ્રીહરિ નીતિવાળાનો હાથ ગ્રહણ કરે છે અને સદાય તેને પાસે રાખે છે. આ બધું હરિકૃપા અને સંતના સંગ વિના સમજાતું નથી.","e":null,"s":["10/28/29-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":267,"k":"para","g":"બાઈઓની સભામાં બાઈઓ જ બેસે, પુરુષ કોઈ ત્યાં ભૂલથી ક્યારેય ન બેસે. એ જ રીતે પુરુષોની સભામાં બાઈભક્તો અજાણ્યે પણ ન બેસે. દશ-દશ વર્ષનાં છોકરા-છોકરી પણ સત્સંગી થયાં પછી ભેગાં રમે નહિ. આ સત્સંગની પ્રણાલી સૌ સહેજે પાળે. સત્સંગ વિના બીજા મતમાં તો બધું એકાકાર થઈ ગયું છે. અગ્નિ અને દારૂ ભેગાં થાય પછી તેનું જે પરિણામ આવે, એવું નિયમ વિના સ્ત્રી-પુરુષ ભેગાં બેસનારનું થાય છે. નિયમ ન પાળે તો રાજા રાજસમૃદ્ધિને ખોવે છે. કોટિપતિ ધનાઢ્ય કહેવાતો હોય, પણ નિયમ ન પાળે તો એ અંતે ખાખ થાય છે. નિયમની રેખા ઓળંગે તેટલી જનને કેદ થાય છે. મોટો નિયમ લોપે તો તો આ જ લોકમાં તેનું ફળ ભોગવે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":268,"k":"para","g":"રાજા પ્રજા માટે નિયમ કરે છે, તે જો પ્રજા લોપે તો દંડ દે છે. દંડ વિના નિયમ પળાતા નથી. અંગ પર ભૂષણ અનેક પ્રકારનાં પહેરે, પણ નિયમરૂપી ભૂષણ બધાં ભૂષણોમાં શ્રેષ્ઠતર છે. જેમાં જેટલો નિયમ તેનામાં તેટલી શોભા. જેને અંતરમાં ક્ષેમકુશળ રહેવાની ઇચ્છા હોય તેણે અહોનિશ નિયમ પાળવા. નિયમ વિના બધી વાતે પળે પળ દુઃખ આવશે. જે નિયમ ભંગ કરે છે તે એવાં દુઃખમાં પણ સુખ માને છે તેને પશુ જાણવો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":269,"k":"para","g":"સત્સંગ થયા પછી આંખે કરીને અયોગ્ય જુએ તો તે જન્મોજન્મ અંધ રહે છે. કાનથી અયોગ્ય સાંભળે તો જન્મોજન્મ બહેરો રહે છે. નાસિકાથી અયોગ્ય ગંધ લે તો જન્મોજન્મ નાક કપાવે છે. જિહ્વાથી અયોગ્ય સ્વાદ લે તો જન્મોજન્મ મુખરોગથી પીડાય છે. અયોગ્ય વાણી વદે તો જન્મોજન્મ મૂંગો રહે છે. ત્વચા અયોગ્ય સ્પર્શ કરે તો જન્મોજન્મ કોઢિયાપણું આવે છે. પગ અયોગ્ય જગ્યાએ ચાલે તો જન્મોજન્મ પંગુ બને છે. હાથ અયોગ્ય કામ કરે તો જન્મોજન્મ હાથમાં ગરમી નીકળતી રહે છે. માટે હરિજન સૌએ ચેતવું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":270,"k":"para","g":"આ વાતને જે હરિજન હૃદયમાં ઉતારીને તે પ્રમાણે વર્તે છે તેણે શ્રીહરિની સર્વપ્રકારે પૂજા કરી એમ જાણવું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":271,"k":"para","g":"કેસર-ચંદન ચર્ચે, વસ્ત્ર, આભૂષણ પહેરાવે, અપાર ફૂલોના હાર ધારણ કરાવે, છાતીએ ચંદન ચરચીને ભેટે, પ્રેમે કરીને આરતી ઉતારે, દુંદુભિ બજાવે, ગાન કરે ને હરખાય, તાલ બજાવે ને નાચે - અનેક પ્રકારે ચાતુરી દર્શાવે ને પૂજા કરે, પણ ભગવાન રીઝતા નથી. દેવો પણ જાણે છે કે હરિને રીઝવવાની આ ચતુરાઈ નથી. તેની બધી સેવા, પૂજા, નિયમ પાલન વગર નિષ્ફળ જાય છે. શ્રીહરિ એવી પૂજાને અંગીકાર કરતા જ નથી. જે શ્રીહરિને અક્ષરપતિ પુરુષોત્તમ પરબ્રહ્મ જાણીને આશરો-ભજન કરે છે, તે બધા હરિજન શ્રીહરિના વચનમાં શ્રેષ્ઠપણે વર્તે છે.","e":null,"s":["12/26/1-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":272,"k":"para","g":"શાસ્ત્રનું ઉલ્લંઘન કરીને વર્તવું તેટલો અધર્મ કહેવાય. શ્રીહરિના વચનમાં રહીને નિયમ પાળે તે સમાન બીજો કોઈ લાભ જ નથી. મનમુખી થઈને અધિક નિયમો રાખે અને અન્ન-જળ આદિકનો ત્યાગ કરે, મેલાં-જૂનાં વસ્ત્ર પહેરે, માનનો ત્યાગ કરે અને ઉપરથી ધ્યાનનું બળ દેખાડે, પણ ભગવાનનાં ચરિત્રમાં કે ભક્તિમાં રુચિ ન હોય તો તેનું ફળ તુચ્છ છે.","e":null,"s":["13/37/22-31"],"sv":[],"mt":false,"gl":null,"a":true},{"i":273,"k":"para","g":"સત્સંગી હરિભક્ત સ્ત્રીઓ પુરુષનું મુખ દેખતી નથી અને પોતાનું મુખ પુરુષને દેખાડતી નથી. સત્સંગની આ રીત રહી છે. સત્સંગ વિના બીજે આ રીતે જોવા ન મળે. જ્યાં વ્યભિચાર છે ત્યાં મોક્ષની વાત નથી. ઘોર નર્કની પ્રાપ્તિ છે.","e":null,"s":["13/53/10-11"],"sv":[],"mt":false,"gl":null,"a":true},{"i":274,"k":"para","g":"ધર્મમાં જે વર્તે છે તેને શ્રીહરિ અધિક પોતાની સેવા આપે છે. શિથિલ વર્તનાર શ્રીહરિનું સુખ લઈ શકતા નથી. શ્રીહરિને ધર્મ અતિશય વહાલો છે. ધર્મભંગ કરે તે શ્રીહરિને દીઠો ગમતો નહિ. તેનો તો તરત ત્યાગ કરી દેતા. સત્સંગથી તેને બહાર કરી દેતા. ફરી તેના પર ક્યારેય વિશ્વાસ કરતા નહિ.","e":null,"s":["13/54/21-23"],"sv":[],"mt":false,"gl":null,"a":true},{"i":275,"k":"para","g":"પૃથ્વીને એક પગલામાં સમાવી લે તેવા મહા બળવંતને પણ કામાદિકે જીતી લીધા છે. એવા એ મહાભયંકર દોષો છે, તેને જીતવા કઠણ છે, પરંતુ પ્રગટ હરિના વચને જે જનો સત્સંગના નિયમ પાળે છે તે કામાદિકને સહેજે જીતે છે. શ્રીહરિનો જેને માહાત્મ્યજ્ઞાને સહિત દૃઢ નિશ્ચય હોય કે આ ભગવાન તુલ્ય બીજો કોઈ ભગવાન નથી - એવી સમજણ સાથે નિયમ પાળે તેનાથી કામાદિ ડરીને ભાગે છે. જેને ભગવાનના ધામના સુખનો લોભ હોય ને ખપ હોય તેને નિયમ રાખવા કંઈ કઠણ પડતા નથી.","e":null,"s":["13/64/35-39"],"sv":[],"mt":false,"gl":null,"a":true},{"i":276,"k":"para","g":"જ્યાં સત્સંગના નિયમ છે ત્યાં ધર્મવંશ સ્થપાયો જાણવો. ભગવાન અને ભગવાનના સાધુ ધર્મવંશનું સ્થાપન કરવા સત્સંગમાં વિચરતા રહે છે. કથા-કીર્તન કરીને, કરાવીને અધર્મનું મૂળ ઉચ્છેદન કરતા રહે છે. જ્યાં સત્સંગ છે ત્યાં શ્રીહરિ નિવાસ કરીને રહે છે. સત્સંગીઓની રક્ષા કાજે નિયમરૂપી કોટ બાંધ્યો છે. સત્સંગમાં જેટલા કંઈ નિયમ કહ્યા છે તે ધર્મવંશ પરિવાર છે. જ્યાં નિયમનો કોટ નથી ત્યાં વર્તન પરથી જ દેખાઈ આવે છે કે ત્યાં અધર્મ વંશનો પરિવાર ફાલ્યો છે. એ અધર્મ વંશીનો સંગ જે જન કરે છે તેને મહાકુસંગ લપટાય છે ને જન્મમરણ, લખચોરાશી, જમપુરીમાં મહાદુઃખ ભોગવે છે. અધર્મને માર્ગે ચાલનારને રાજા દંડે છે ત્યારે કોરડા મારે છે, કેદ કરે છે, કેટલાકનાં નાક કાન કાપે છે, કેટલાકનું મસ્તક છેદે છે. એમ અનંત પીડા મનુષ્ય કુસંગને છંદે ભોગવે છે.","e":null,"s":["14/17/23-30"],"sv":[],"mt":false,"gl":null,"a":true},{"i":277,"k":"para","g":"એક જ નિયમ પણ દૃઢ કરીને રાખે એવા જન પર શ્રીહરિ પ્રસન્ન થઈ જતા. ધર્મ પર શ્રીહરિને અપાર હેત છે. જેમનામાં શ્રીહરિ નિષ્કપટ રૂપ ધર્મને દેખે છે ત્યારે તત્કાળ પ્રસન્ન થઈ જાય છે. કપટી પર રીઝવામાં વિચાર કરે છે. શ્રીહરિની પ્રસન્નતાનાં જેટલાં કાંઈ સાધન છે તેમાં નિષ્કપટપણું શ્રેષ્ઠ સાધન છે. આ સાધન જે સિદ્ધ કરે છે તેના પર તત્કાલ રીઝે છે. કોટિ સાધન કરે પણ કપટ તજે નહિ તેવા જન પર શ્રીહરિ ક્યારેય રીઝતા નહીં. બહાર સરળતા દેખાડે પણ અંદર કપટી અને કુટિલ હોય તો તે અતિ દુઃખી થાય છે.","e":null,"s":["15/8/32/37"],"sv":[],"mt":false,"gl":null,"a":true},{"i":278,"k":"para","g":"પર પુરુષના સંબંધથી સ્ત્રીઓને પોતાનો ધર્મ સચવાતો નથી. પિતા, પુત્ર કે બંધુ સાથે પણ એકાંતમાં બેસે નહિ, તો ધર્મ રહે. કારણ કે પુરુષ ઘી સમાન છે અને સ્ત્રી અગ્નિ સમાન છે. અગ્નિનો સંબંધ થતાં ઘી ઓગળ્યા વગર રહે જ નહિ. મેરુ જેટલો દારૂનો ઢગલો હોય તેમાં તલ જેટલો અગ્નિ અજાણ્યે પડે તો ફૂટ્યાં વિના રહે નહિ, માટે સંબંધ ન રાખે તો જ ધર્મ દૃઢ રહે.","e":null,"s":["15/45/26-29"],"sv":[],"mt":false,"gl":null,"a":true},{"i":279,"k":"para","g":"મોક્ષનો ખપ ન હોય તો નિયમ રાખવો કઠણ પડે છે. ભલે ચ્હાયે તેવો પ્રવીણ હોય, પણ ખપ વિના નિયમ પાળી ન શકે. અને ચિંતામણિ તુલ્ય આ શરીર વિષયમાં ખોઈ બેસે છે.","e":null,"s":["15/47/42"],"sv":[],"mt":false,"gl":null,"a":true},{"i":280,"k":"para","g":"જે નિયમમાં વર્તે છે તેને માયા બંધન કરતી નથી, નિયમનો જેટલો ત્યાગ એટલી માયા તેને પીડે છે ને બંધનમાં નાખે છે. એવા હરિભક્ત સત્સંગમાં ઘટી જાય છે. સત્સંગ કરતો થકો ઘટે તે નિયમના ભંગે કરીને ઘટે છે. ધનથી પણ જેને નિયમ અધિક વહાલા હોય તેનો સત્સંગ અચળ રહે છે. જેને કોઈ પ્રકારનો નિયમ ન હોય તે પોતાની પદવી થકી પડી જાય છે. ભવ-બ્રહ્માદિ દેવો પણ ભગવાનના નિયમમાં વર્તે છે. જે દિવસે નિયમનું ઉલ્લંઘન કર્યું છે, તે દિવસે તે પણ દુઃખી થયા છે. વાતનો કરનારો ગમે તેટલી મીઠી વાતો કરે, પણ નિયમ પાલન ન કરતો હોય તો તે વૃથા છે. જેટલા નિયમ અધિકપણે પાળે તેટલું તેનામાં ઐશ્વર્ય રહે છે તેની વાણીમાં ઐશ્વર્ય વધે છે. એટલે તેની વાત પણ અસર કરે છે.","e":null,"s":["16/66/28-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":281,"k":"para","g":"નિયમ એ શ્રીહરિનું સ્વરૂપ છે. જેટલી કંઈ શોભા છે તે નિયમથી છે. નિયમ વિના કોઈ શોભા નથી. જે નિયમનો ત્યાગ ક્યારેય કરતો નથી તેના પર શ્રીહરિ અનુરાગ રાખે છે.","e":null,"s":["17/42/22-24"],"sv":[],"mt":false,"gl":null,"a":true},{"i":282,"k":"para","g":"ગમે તેવો જ્ઞાની હોય, ધ્યાન હોય, વાક્‌પટુ હોય કે યોગકળાઓ જાણતો હોય, પણ સત્સંગના નિયમ ન પાળતો હોય તો તેના ગુણમાત્ર ઊલટી કરેલા અન્ન સમા છે. નિયમપાલનમાં ભગવાનનું દૈવત રહેલું છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":283,"k":"para","g":"જ્યાં સુધી નિયમોનું પાલન રહે, ત્યાં સુધી સત્સંગ વૃદ્ધિ પામતો રહે છે. નિયમોનું પાલન પણ ભગવાન કે ભગવાનના સાચા સંતનો યોગ હોય ને નિશ્ચય હોય ત્યારે થાય છે. ભગવાન ને સંતના નિશ્ચય કે યોગ વિના ચ્હાયે તેવા નિયમ પાળે તોપણ ભવ ન તરે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":284,"k":"para","g":"સંતના યોગમાં રહી નિષ્કપટ ભાવે સત્સંગ કરે તેને અંત સમે ભગવાન કે ભગવાનના સંત દર્શન દઈ તેડવા આવે છે. એવો યોગવાળો જીવ દોષ ટાળવા મથતો હોય ને તે ગણિકા જાતિ હોય તોપણ ભગવાન ને સંત તેને અંત સમે નિષ્કામી કરી દે છે.","e":null,"s":["25/63/10-16"],"sv":[],"mt":false,"gl":null,"a":true},{"i":285,"k":"para","g":"જે ભગવાનનાં વચનમાં રહે છે તેને ભગવાનની મૂર્તિ પલવાર દૂર જતી નથી. તેની સમીપે ભગવાન રહે છે તેથી તેને જગતના મળનો પાશ ટળી જાય છે.","e":null,"s":["27/48/14-16"],"sv":[],"mt":false,"gl":null,"a":true},{"i":286,"k":"para","g":"જ્યાં ધર્મ છે ત્યાં ભગવાન વાસ કરીને રહે છે. ને જ્યાં ભગવાન પ્રગટ છે ત્યાં જ ધર્મનું પાલન દેખ્યામાં આવે છે. અધર્મ હોય ત્યાં ભગવાન રહેતા નથી, ને ભગવાન હોય ત્યાં અધર્મ રહેતો નથી. ધર્મ વગરનો સંપ્રદાય વાડ વિનાના ખેતર જેવો છે. દેખાવા છતાં તે નામમાત્ર રહ્યો હોય છે.","e":null,"s":["27/50/10-11"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":3,"gu":"અભાવ-અવગુણ, દ્રોહ","en":"Abhāv-Avgun, Droh — Fault-Finding and Malice","url":"https://www.anirdesh.com/pbp/index.php?page=chp_3","b":[{"i":287,"k":"para","g":"બંધિયાથી પીપળિયા જતાં શ્રીહરિ કહે, “સાચા સંત માર્ગે ચાલ્યા જતા હોય તેનો વાયરો લાગે તે બધાનો મોક્ષ થાય છે. અજ્ઞાની અને અધર્મી લોકો એમને બાંધે, મારે કે ગાળો દે તોપણ બોલે નહિ. સૌનું હિત જ ઇચ્છે. એવા સંતને જે દૂભવે છે તે પોતાનું જ ગળું કાપે છે. જેમ જેમ સંત ક્ષમા કરે છે, તેમ તેમ તેનું (દૂભવનારાનું) કુળ સમૂળું નાશ પામે છે. અનંત પ્રકારનાં પાપ વેદમાં કહ્યાં છે, પણ સંતના દ્રોહ જેવું એકેય પાપ નથી.”","e":"While going from Bandhiya to Pipaliya, Shriharí said, “When a true Sant is walking along the road, all who are touched by his breeze attain moksha. Even if ignorant and adharmi people bind him, beat him or abuse him, he does not speak. He wishes only for the good of all. One who hurts such a Sant cuts his own throat. The more the Sant forgives, the more his (the offender’s) lineage is destroyed, root and all. Countless kinds of sin are described in the Vedas, but there is not a single sin like droh (malice, hostility) against the Sant.”","s":["3/52/26-35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":288,"k":"para","g":"કુંડળમાં શ્રીહરિએ વાત કરતાં કહ્યું, “જગતમાં ધર્મવાન ગણાતા પુરુષનો દ્રોહ કોઈ હરિભક્ત કરે તો તેનો દોષ કેટલો લાગે?” એ પુછાયેલ પ્રશ્નનો ઉત્તર આપતાં શ્રીહરિએ કહ્યું, “હરિજન હોય તે કોઈનો દ્રોહ કરે જ નહિ. દ્રોહની રીત તલવારની ધાર જેવી છે. તલવાર બધાને કાપે તેમ દ્રોહી બધાનો દ્રોહ કરે. માટે મારા આશ્રિત ભક્તે જીવ-પ્રાણીમાત્રનો દ્રોહ ન કરવો.”","e":"At Kundal, while talking, Shriharí said, “If some haribhakta commits droh against a man regarded in the world as dharmic, how great a fault accrues to him?” Answering the question that had been put, Shriharí said, “One who is a harijan does not commit droh against anyone at all. The way of droh is like the edge of a sword. Just as a sword cuts everyone, so one who commits droh commits droh against everyone. Therefore a bhakta who has taken My refuge should not commit droh against any jiva or living creature whatsoever.”","s":["4/35/25-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":289,"k":"para","g":"માનકુવામાં વાત કરતાં શ્રીહરિએ કહ્યું, “સંતો હરિભક્તો અક્ષરધામનું સ્વરૂપ છે. જો તેનો અભાવ આવે તો જ્યાં કાળનો પ્રવેશ નથી એવા અક્ષરધામમાંથી પણ પડે છે. અભાવ લેનારો અક્ષરધામમાં જઈ શકતો નથી. તેની સહાય બધા સંતો કરે, હરિભક્તો કરે તોય તેને ધામ મળતું નથી. અભાવનો દોષ બધા દોષોથી અધિક છે.","e":"At Mankuva, while talking, Shriharí said, “The Sants and haribhaktas are the very form of Akshardham. If abhav (a fault-finding, negative regard) toward them arises, one falls even from Akshardham, where kal (time) has no entry. One who takes abhav cannot go to Akshardham. Even if all the Sants help him and the haribhaktas help him, he still does not attain the Dham. The fault of abhav is greater than all other faults.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":290,"k":"para","g":"“હરિભક્તનો અભાવ લેતાં જે દોષ લાગે છે તેવો તો કામ, ક્રોધ, લોભમાં પણ દોષ નથી. માટે ભક્તમાં અવગુણ ન પરઠવો ને દોષ દેખાઈ જાય તો તત્કાળ શમાવી દેવો, જેથી અભાવનું બીજ હૃદયમાં ક્યારેય પ્રગટે નહિ.”","e":"“The fault that is incurred by taking abhav of a haribhakta — such a fault is not found even in kam, krodh and lobh. Therefore do not attribute avgun (faults) to a bhakta; and if a fault does come into view, quench it at once, so that the seed of abhav never sprouts in the heart.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":291,"k":"verse","g":"‘અભાવ મેં દોષ હૈ જૈસા, કામ-ક્રોધ મેં નહિ તૈસા,","e":"‘Abhāv men dosh hai jaisā, kām-krodh men nahi taisā,","s":[],"sv":[],"mt":false,"gl":"[Such fault as lies in abhav is not found in kam and krodh;]","a":false},{"i":292,"k":"verse","g":"તેહિકર દોષ ભક્તકો ન આવે, દોષ આવે તત્કાલ સમાવે.’","e":"Tehikar dosh bhaktako na āve, dosh āve tatkāl samāve.’","s":["5/52/14-17"],"sv":[],"mt":false,"gl":"[…therefore let the fault of a bhakta not enter the mind; if a fault enters, let it be quenched at once.]","a":false},{"i":293,"k":"para","g":"“જે સંતને તથા હરિભક્તને તુચ્છ ગણે છે તે ભક્તિ કરતો હોવા છતાં તેને અમે ભક્ત માનતા નથી. જેને કોઈ ભક્તનો ભાર ન હોય, સંતને ભિખારી તુલ્ય સમજે, પોતાનામાં મોટપનો કોઈ ગુણ ન હોવા છતાં પોતાને અતિ મોટો સમજે, તેનામાં મોટાઈના ગુણ રહેતા જ નથી. જે બીજાને મોટો જાણે નહિ, તેની મોટપ ક્યાં સુધી રહેશે?”","e":"“One who regards the Sant and the haribhakta as trifling — though he may be doing bhakti, We do not consider him a bhakta. One who holds no bhakta in regard, who considers the Sant to be like a beggar, and who, though he has no quality of greatness in himself, considers himself very great — in him the qualities of greatness do not remain at all. One who does not regard others as great — how long will his own greatness last?”","s":["5/52/14-21"],"sv":["भक्तजन संत की तुच्छता जेहि । कैसे समझना भक्त तेहि ॥\n\n कोई भक्त की भार न लेशा । संतकुं गिने भिखारी जैसा ॥\n\n आप में समझे अति मोटाई । मोटप के कोउ गुन न रहाई ॥\n\n कहाँ लग मोटप रहावे एहा । और न मोटप समझत तेहा ॥"],"mt":false,"gl":null,"a":false},{"i":294,"k":"para","g":"ભક્તનો અપરાધ લગાર થઈ જાય તેમાં મોટો દોષ સમજે અને અભાવ નાશ પામે ત્યાં સુધી જીવમાં ડર લાગ્યા કરે - એવું જેને વર્તતું હોય તે અમારા ચરણને અડો. કપટ રાખશો નહિ. કપટ વર્તનમાં જણાયા વિના રહેશે નહિ. વર્તન છે તે જ ઓળખવાની કસોટી છે.”","e":"One who regards even a slight offence against a bhakta as a great fault, and in whose jiva fear keeps gnawing until the abhav is destroyed — whoever lives in this way, let him touch Our feet. Do not harbour kapat (deceit). Kapat will not remain hidden; it shows itself in one’s conduct. Conduct alone is the touchstone by which one is known.”","s":["5/52/24-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":295,"k":"para","g":"ગઢપુરમાં જીવેન્દ્ર નૃપના ભુવનમાં શ્રીહરિ કહે, “હરિજનના અંતરમાં જ્યારે અસુરનો પ્રવેશ થાય છે ત્યારે એકએક ભક્તમાં તેને દોષ ભાસે છે. અને સત્સંગ ટળી જાય છે. અભાવ લેનાર દુષ્ટના જીવનરૂપી વૃક્ષના મૂળમાં ભક્તદ્રોહ રૂપી ઊધઈ લાગે છે અને જીવન નષ્ટ થાય છે. અભાવરૂપી ઊધઈ એવી છે કે તે હરિજનને મૂળમાંથી બાળી દે છે. જે હરિજન અભાવથી બીએ છે અને પ્રત્યેક ભક્તનો મહિમા જાણે છે તેના મુખમાં ક્યારેય ઘસાતું વચન આવતું નથી. એવા ભક્તના અંતરમાં ક્યારેય અસુર પ્રવેશી શકતો નથી. જો અભાવ વચન સાંભળવામાં રુચિ રાખે તો પછી તેનો કોઈ નિર્ધાર રહેતો નથી.","e":"At Gadhpur, in the residence of Jivendra Nrup, Shriharí said, “When an asur enters the heart of a harijan, then he perceives faults in each and every bhakta, and his satsang falls away. At the root of the tree of life of the wicked one who takes abhav, the termite of droh against bhaktas takes hold, and his life is destroyed. The termite of abhav is such that it burns the harijan away from the very root. The harijan who fears abhav and knows the mahima of every single bhakta — a disparaging word never comes to his lips. Into the heart of such a bhakta an asur can never enter. But if one keeps a relish for listening to words of abhav, then no certainty remains for him.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":296,"k":"para","g":"“જેને મરણ પર્યંત સત્સંગ જાળવી રાખવો હોય તેણે પૂર્વે થયેલા મોટા ભક્તોની આ રીત શીખવી. રીત શીખ્યા વગર કોટિ વર્ષ સત્સંગ કરે તોપણ વૃદ્ધિ ન પામે. આ વાત ત્યાગી-ગૃહી સર્વેએ સમજી રાખવી. જે આ વાત સમજે છે તેનો જ સત્સંગ દિન-પ્રતિદિન દૃઢ થાય છે ને અંગ વૃદ્ધિ પામે છે. આ વાત અમે કરી તે શ્રેષ્ઠમાં શ્રેષ્ઠ છે. જેણે સત્સંગ કર્યો છે તેને જ આ વાત સમજાશે. તેને કંઈ કરવું રહેતું નથી. આવો સત્સંગ છે તે પરમ ચિંતામણિ છે. આ સિવાય બીજી કોઈ ચિંતામણિ છે નહિ. આ વાત બુદ્ધિવાળો હોય તેને જાણ્યામાં આવે છે બીજાને દેખ્યામાં પણ આવતી નથી.”","e":"“One who wishes to preserve his satsang until death should learn this way of the great bhaktas who have gone before. Without learning the way, even if one does satsang for ten million years, one does not grow. All, tyagis and householders alike, should understand this well. Only for one who understands this does satsang become firmer day by day, and his ang (spiritual inclination) grows. This talk We have given is the best of the best. Only one who has done satsang will understand it; nothing further remains for him to do. Such satsang is the supreme chintamani (wish-fulfilling gem); apart from it there is no other chintamani. One who has understanding comes to know this; to others it does not even come into view.”","s":["6/102/29-36"],"sv":["अभाव उधेई लगे जेहि मूला । यो हरिजन जात समूला ॥\n\n ब्हिते रहे हरिजन सें जेहि । आपसें अधिक जाने तेहि ॥\n\n एक एक को महात्म्य जाने । घसातो वचन मुख न आवे ॥\n\n तब असुर हो चले न लेशा । कोउ हरिजन में करे न प्रवेशा ॥\n\n अभाव वचन में असुर करे जोरा । ता पिछे वात को रहे न ठोरा ॥\n\n जाकुं सत्संग मरण प्रंजता । रखनो होय जो बुद्धिवंता ॥\n\n बडे बडे हरिजन भये जेहि । ताकि रितकुं शीखना तेहि ॥\n\n रित शिखे विन बढता न पावे । कोटि वर्ष सत्संग करावे ॥\n\n सत्संग करनकि बात हें जेसि । कहि सुनावत हम हि तेसि ॥\n\n त्यागि गृहि पर वात हें सबहि । समझे विन पार न परे कबहि ॥\n\n समझे ताको हे सत्संगा । दिन दिन वृद्धि होय तेहि अंगा ॥\n\n श्रेष्ठ में श्रेष्ठ यह बात हें, सत्संग करना जेह ।\n\n सत्संग कियो तिन सब कियो, करन न रहे केह ॥\n\n सत्संग हे परम चिंतामनि, चिंतामनि ओर न लेख ।\n\n सबुद्धिमान सो जानहि, ओरकुं न आवत देख ॥"],"mt":false,"gl":null,"a":false},{"i":297,"k":"para","g":"પીજમાં ઝવેરીદાસના ભવનમાં શ્રીહરિએ હરિજનોને વાત કરતાં કહ્યું, “સંતો અને હરિભક્તો અલૌકિક છે, તેમનો દૈહિક દોષ દેખીને અભાવ ન લેવો. અભાવ લે છે તેને તેટલું ફળ ભોગવવું પડે છે. તે તો બ્રહ્મ અગ્નિ જેવા છે. લીલું, સૂકું જે તેનો સ્પર્શ કરે, તે બળી જાય એવો એમનો સહજ સ્વભાવ છે. તેની રક્ષા ભગવાન પણ કરી શકતા નથી. સત્સંગના પાંચે નિયમ દૃઢ કરીને રાખે તેને સંત-હરિભક્ત જાણવા.”","e":"At Pij, in the residence of Zaveridas, Shriharí said to the harijans while talking, “The Sants and haribhaktas are alaukik (beyond the worldly); do not take abhav on seeing their bodily faults. Whoever takes abhav has to suffer its fruit in that same measure. They are like the fire of Brahman: whatever touches it, green or dry, burns — such is their innate nature. Even Bhagwan cannot protect such a person. Know those who keep all five niyams of satsang firmly to be Sants and haribhaktas.”","s":["8/38(37)/23-25"],"sv":[],"mt":false,"gl":null,"a":false},{"i":298,"k":"para","g":"મુક્તમુનિએ ઉત્તમ નૃપને કહ્યું કે, “શ્રીહરિ અહોનિશ એક વાત કર્યા કરતા: ‘અમારી સંગે રહેવું હોય તેણે રીસ છોડવી પડશે. અજાણતાં પણ સંત કે હરિજનને ડારો કરવો નહિ. ક્યારેક કહેવું પડે તો નમ્રતાથી વિવેકથી હાથ જોડીને કહેવું. ઝેર ખાવું, અગ્નિમાં બળવું - એ બધું દુઃખદાયક છે, પણ તેનાથી અનંતગણું દુઃખ ભક્તને દુખવવામાં રહેલું છે.’”","e":"Muktamuni said to Uttam Nrup, “Shriharí would say one thing day and night: ‘Whoever wishes to stay in Our company will have to give up ris (sulking resentment). Even unknowingly, do not browbeat a Sant or a harijan. If at some time something has to be said, say it with humility, with discretion, with folded hands. Eating poison, burning in fire — all of these are painful, but infinitely greater misery lies in hurting a bhakta.’”","s":["8/50/31-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":299,"k":"para","g":"વડતાલમાં શ્રીહરિ કહે, “સંત-હરિભક્તોને પોતાના શરીર જેવા માનવા જેથી અપરાધ ન થાય. જુદાઈ રાખે તેટલો અપરાધ થાય, અને તેનું પાપ અવશ્ય ભોગવવું પડે. પોતાના શરીરની ક્યારેય અરુચિ થતી નથી, તેમ સંત-હરિભક્તની ક્યારેય અરુચિ ન થાય તેનું નામ ‘દ્રોહ ન કર્યો’ કહેવાય. અરુચિ થાય તે જ દ્રોહ છે. શરીર તો કોટિ દુઃખ આપે છે, તોપણ તેમાં રાગ થાય છે. નિત્ય મળ ધોવડાવે છે તોપણ તેનું જતન કરે છે. ભરણ-પોષણ કરવા છતાં આ શરીર હમેશાં દુઃખ દે છે આ તન કરતાં તો સંત-હરિભક્તો કોટિગણા સુખદાયી છે. પણ, એવું મનાતું નથી તેથી તેમનો દ્રોહ થાય છે. માટે સંતનો સંગ નિરંતર રાખીને સંત-હરિભક્તમાં અરુચિ ટાળવી. અરુચિ અને દ્રોહ ક્યારેય ન થાય તેનું જાણપણું રાખવું. એવા હરિજનને અંત સમયે અમે આવીને દર્શન દઈશું અને સહાય કરીશું તેમાં સંશય નથી.” એમ કહીને શ્રીહરિ અશ્વ પર બિરાજ્યા.","e":"At Vartal, Shriharí said, “Regard the Sants and haribhaktas as your own body, so that no offence is committed. To the extent one keeps separateness, to that extent offence is committed, and its sin must certainly be suffered. Just as one never develops aversion toward one’s own body, so never to develop aversion toward the Sants and haribhaktas — that is what is called ‘not having committed droh’. Aversion itself is droh. The body gives ten million miseries, yet one is attached to it. Every day it makes one wash away its filth, yet one takes care of it. Though one feeds and nourishes it, this body always gives misery. Compared to this body, the Sants and haribhaktas give ten million times more happiness. But that is not believed, and so droh is committed against them. Therefore, keeping the company of the Sant constantly, remove aversion toward the Sants and haribhaktas. Stay vigilant that aversion and droh never occur. To such a harijan We shall come at the time of death, give darshan and help — of this there is no doubt.” Having said this, Shriharí mounted His horse.","s":["9/4/33-42"],"sv":["श्रीहरि कहे निज तन जेसा । संत हरिजन कुं जानना तेसा ॥\n\n यामें जितनी रहे जो जुदाई । अपराध होवे कबहुक ताई ।\n\n जितने करे अपराध हि जेहु । अवश पाप सो भुक्तत तेहु ॥\n\n संत हरिजन ताहि की, अरुचि जितनी जाहि ।\n\n ताको नाम अपराध हे, द्रोह हि होवत ताहि ॥\n\n निज तन की अरुचि कबु, आवत नहि लगार ।\n\n तन देहे कोटिक दुःख हि, राग होई वार हि वार ॥\n\n सोहु करत हे जतन, धोवत तन मल नित नित ।\n\n भरण हि करत पोषण, तोहु देत दुःख हमेश तेहि ॥\n\n तन सें संत हरिजन, कोटि हें सुखदाई तेहु ।\n\n मनात न त्यां लग मन, त्यां लग देह सो करत जन ॥\n\n तेहि हित सत्संग, करनो सो वेर वेर सब ।\n\n हरिजन को कोउ अंग, अरूचि द्रोह न होय कबु ॥\n\n अंत समे हम आई, हरिजन कुं दरश देत सब ।\n\n करत अति सहाई, यामें नहि हे फरक कछु ॥"],"mt":false,"gl":null,"a":false},{"i":300,"k":"para","g":"ઝીંઝાવદરમાં અલર્ક નૃપને શ્રીહરિ કહે, “ભગવાનની સમજણ જુદા જ પ્રકારની છે. ભક્ત થાય છે તેને તે જાણ્યામાં આવે છે. ભગવાનને ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ રુચે છે, પણ તેનું માન આવે તે તેમને ગમતું નથી. ખરો ભક્ત હોય તે જેમ જેમ માન પામે તેમ તેમ દાસનો દાસ થઈને વર્તે અને સંતો-ભક્તોની સેવા ઇચ્છે. એવા ભક્તને અમે ભૂલતા નથી, વારંવાર સંભારીએ છીએ. આવી બુદ્ધિ પ્રાણપર્યંત રહે તે સર્વ ભક્તમાં શ્રેષ્ઠ છે. સત્સંગનું પણ એ જ ફળ છે કે સંત-હરિભક્તોનો ભાવ રહે અને તે નિત્ય નિત્ય વધતો રહે. સત્સંગ કરતા પ્રીતિ નાશ પામે તો મનનો તપાસ કરવો, નહીં તો સંત તથા ગરીબ હરિભક્તનો અપરાધ થઈ જાય.","e":"At Jhinjhavadar, Shriharí said to Alark Nrup, “Bhagwan’s understanding is of an altogether different kind. One who becomes a bhakta comes to know it. Bhagwan likes dharma, gnan, vairagya and bhakti, but He does not like it when maan comes of them. A true bhakta — the more maan (honour) he receives, the more he behaves as the servant of servants and desires the seva of the Sants and bhaktas. Such a bhakta We do not forget; We remember him again and again. One in whom such understanding remains until his last breath is the best among all bhaktas. The fruit of satsang, too, is only this: that one’s bhav (regard) for the Sants and haribhaktas remains and keeps increasing day after day. If, while doing satsang, one’s priti diminishes, one should examine one’s mind; otherwise an offence against a Sant or a garib (meek, lowly) haribhakta will be committed.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":301,"k":"para","g":"“સત્સંગમાં જે સંત-હરિજન ગરીબ સ્વભાવના છે, તેના અપરાધનું ફળ સુબુદ્ધિજન જાણે છે. તે ક્યારેય ગરીબના અપરાધમાં પડતા નથી. મોટાની સેવા કરતો હોય પરંતુ ગરીબ હરિભક્ત પર અણગમો હોય, તેનાથી ભગવાન દુભાય છે. ભલે મોટાની સેવા કરે પણ ભગવાન તેને લેશ પણ સ્વીકારતા નથી. ગરીબ ભક્તની સેવા મન-કર્મ-વચનથી કરે તેના પર શ્રીહરિ ખૂબ રીઝે છે. મોટાનું તો આખું જગત રાખે છે પણ ગરીબનું કોણ? ગરીબ હરિભક્તની ઘૃણા કરે, દ્રોહ કરે, એ પાપે કરીને મોટો હોય તે પણ તુચ્છ થઈ જાય છે. પોતે વધારે ત્યાગ રાખીને, બીજા સંત તથા હરિભક્તને ત્યાગની વાત કરીને વચનનો પ્રહાર કરી દુભાવે છે, તે પણ સારું નથી, કારણ કે જેનું જેવું અંગ હોય તે અંગ ઉપર જ તેને ભાવ રહે અને રંગ ચઢે, બીજા ઉપર ચઢે નહિ.”","e":"“In satsang, those Sants and harijans who are garib by nature — the wise know the fruit of offending them. They never fall into offence against the garib. One who serves the great but harbours dislike for a garib haribhakta — by that, Bhagwan is hurt. Though he may serve the great, Bhagwan does not accept it in the least. One who serves a garib bhakta with mind, action and speech — on him Shriharí is greatly pleased. The whole world looks after the great, but who looks after the garib? One who despises a garib haribhakta or commits droh against him — by that sin even one who is great becomes insignificant. One who himself keeps greater renunciation and hurts other Sants and haribhaktas by talking to them of renunciation and striking them with words — that too is not good, because whatever a person’s ang is, his regard stays on that ang alone and that colour takes on him; another does not.”","s":["9/40(41)/5-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":302,"k":"para","g":"ઝીંઝાવદરમાં શ્રીહરિ કહે, “હરિભક્ત થઈને હરિભક્તનો દોષ બોલે, તે સમાન કોઈ પાપી નથી. તેને બ્રહ્મવેત્તાને હણ્યાનું પાપ લાગે છે.”","e":"At Jhinjhavadar, Shriharí said, “There is no sinner equal to one who, having become a haribhakta, speaks of the faults of a haribhakta. He incurs the sin of having killed a brahmavetta (a knower of Brahman).”","s":["9/40(41)/28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":303,"k":"para","g":"શ્રીહરિ ઝીંઝાવદરમાં કહે, “બુદ્ધિશાળી કહેવાતો હોય તોપણ સંત-હરિભક્તનો જે દોષ જુએ તો તેને જમ પકડીને જમપુરીમાં લઈ જાય છે.”","e":"At Jhinjhavadar, Shriharí said, “Even if he is called intelligent, one who sees faults in the Sants and haribhaktas is seized by the messengers of Yama and taken to Yampuri.”","s":["9/41(42)/39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":304,"k":"para","g":"મુક્તમુનિએ શ્રીહરિએ કહેલી વાત કરતાં કહ્યું, “શ્રીહરિ કહેતા જે - ધર્મામૃતનો દિવસ-રાત પાઠ કરતો હોય અને પંચવર્તમાન પાળતો હોય; સર્વે સત્સંગીમાં, સંતોમાં અતિ પ્રીતિ હોય; અમારો અભિપ્રાય પ્રવર્તાવતો હોય એવા હરિજન ઉપર સૌને પ્રીતિ થાય છે. નિષ્પાપ હરિજન પર પાપબુદ્ધિ કરે અને તેની ઈર્ષ્યા કોઈ કરે તો તેનો ક્યારેય મોક્ષ થાય નહિ. સત્યમાં જે પાપબુદ્ધિ લાવવી તેનું નામ કુસંગ છે. સત્ય, સત્સંગી અને સંતનો અજાણે પણ દ્રોહ કરે તેને ક્યારેય મનુષ્યનું શરીર મળે નહિ. અને જાણીને દ્રોહ કરે તેને વૃક્ષનો અવતાર આવે. અને સંત થઈને સંત-હરિજનને ઘટે તેમ નમસ્કાર કરે નહિ. નમનમાં ત્યાગ-વિભાગ કરે અને નજરમાં આવે તેની સાથે પ્રીતિ રાખે અને ભોજન અને વસ્ત્રમાં યોગ્ય-અયોગ્ય કરે, તેને અનંત દેહે મહારોગ થાય છે.”","e":"Muktamuni, relating a talk Shriharí had given, said, “Shriharí would say: a harijan who recites the Dharmamrut day and night and observes the five vartmans, who has intense priti for all satsangis and Sants, and who spreads Our intent — everyone comes to love such a harijan. One who imputes sin to a sinless harijan, or who envies him, never attains moksha. To bring a sense of sin into what is true — that is called kusang. One who commits droh, even unknowingly, against the truth, a satsangi or a Sant never again obtains a human body. And one who commits droh knowingly is born as a tree. And one who, having become a Sant, does not bow to Sants and harijans as is fitting, who picks and chooses in bowing, keeps affection with whoever catches his eye, and makes distinctions of worthy and unworthy in food and clothing — he suffers a great disease through countless bodies.”","s":["11/23/17-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":305,"k":"para","g":"શ્રીહરિએ વર્ણીને વાત કરેલી તે મુક્તમુનિએ કહી, “જે સંતમાં ધર્મનો પરિવાર (ધર્મ, જ્ઞાન, વૈરાગ્ય, ભક્તિ આદિક ગુણો) છે તેની સેવા કોઈ નિષ્કામ ભાવથી કરે તો તે અક્ષરધામને પામે છે. અને ભગવાનનું અપરંપાર સુખ ભોગવે છે. જે વર્ણવ્યામાં આવે તેમ નથી. હરિભક્તોને પરસ્પર જ્યાં સુધી હેત રહે છે ત્યાં સુધી એ હરિના ધામમાં બેઠો છે. જ્યારે અભાવ આવે છે, ત્યારે ધામનું સુખ તે ગુમાવે છે. ભલે ભગવાન અને સંતની અપાર કૃપા થઈ હોય તોપણ જો હરિભક્તોનો તેને અભાવ હોય તો તે ધામમાં જઈ શકતો નથી.”","e":"Muktamuni related a talk Shriharí had given to the Varni: “If someone serves with a nishkam spirit a Sant in whom the family of dharma resides (dharma, gnan, vairagya, bhakti and the other virtues), he attains Akshardham and enjoys the boundless bliss of Bhagwan, which cannot be described. As long as haribhaktas keep het for one another, one is seated in Hari’s Dham. When abhav arises, one loses the bliss of the Dham. Even if Bhagwan and the Sant have shown him boundless grace, if he harbours abhav toward haribhaktas, he cannot go to the Dham.”","s":["11/60(50-b)/32-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":306,"k":"para","g":"મુક્તમુનિએ શ્રીહરિએ કહેલી વાતો ગઢપુરમાં કહી, “શ્રીહરિ કહેતા કે - ભગવાન અને ભગવાનના બ્રહ્મરૂપ એવા ભક્તનો દ્રોહ ન થાય. તે મોક્ષના માર્ગમાં બધાં વિઘ્નો તરી ગયો છે. તે વિનાનો પ્રાકૃત ભક્ત છે.”","e":"Muktamuni related at Gadhpur the talks Shriharí had given: “Shriharí would say: one who commits no droh against Bhagwan and against Bhagwan’s brahmarup bhakta has crossed all the obstacles on the path of moksha. One without that is a prakrut (worldly) bhakta.”","s":["11/86(77)/23-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":307,"k":"para","g":"મુક્તમુનિએ શ્રીહરિએ કહેલી વાતો ગઢપુરમાં કહી કે, “શ્રીહરિ કહેતા જે - ભગવાનના ભક્તમાં જ્યાં સુધી પ્રાકૃતભાવ છે ત્યાં સુધી તેનો ગુણ-અવગુણ આવ્યા કરે છે. જ્યારે તેમાં બ્રહ્મભાવ આવે ત્યારે એક પણ દોષ નહિ જણાય. જેને એકે એક હરિભક્તમાં દોષ જ સૂઝતા હોય તે ભગવાનનો ભક્ત કહેવાતો હોય, છતાં પ્રાકૃત (મિથ્યા, દંભી) ભક્ત છે. સત્શાસ્ત્રોમાં જેટલા કંઈ પ્રાકૃતભાવ કહ્યા છે તે પૈકી પોતામાં જેટલા હોય તે જાણે ને તેનો ત્યાગ કરે ત્યારે તે હરિનો જન કહેવાય છે.”","e":"Muktamuni related at Gadhpur the talks Shriharí had given: “Shriharí would say: as long as there is prakrutbhav (a worldly view) toward Bhagwan’s bhakta, his virtues and faults keep coming to mind. When brahmabhav comes, not a single fault will be perceived. One to whom only faults occur in each and every haribhakta — though he is called a bhakta of Bhagwan, he is a prakrut (false, hypocritical) bhakta. Of all the prakrutbhavs described in the true scriptures, whichever are in oneself — when one recognises them and renounces them, only then is one called Hari’s own.”","s":["11/86(77)/25-27"],"sv":["प्राकृतभाव ज्यां लगहि, गुन दोष त्यां लग ।\n\n ब्रह्मभाव आवे जबहु, दोष न तब जो लग ॥\n\n एक एक को दोष हि, देखत ज्यां लग जेहि ।\n\n भक्त होई भगवान के, प्राकृत भक्त हे तेहि ॥\n\n प्राकृतभाव हि जेते, कहे हें सत्ग्रंथ जो महि ।\n\n जानि के सब तेते, त्याण करे हरिजन तेहि ॥"],"mt":false,"gl":null,"a":false},{"i":308,"k":"para","g":"ગાંફમાં મનુભા રાજાને ત્યાં શ્રીહરિએ વાત કરતાં કહ્યું, “કુહેત એ અગ્નિ અને વિષ સમાન છે. પાપરૂપી કળિયુગ મુક્તમાં પ્રવેશ કરે તો તેને પણ એ વિરૂપ બનાવી દે છે, પછી તે હરિભક્તનો દોષ કહેવા લાગે છે. હરિજનનો દોષ લેવાથી એ મુક્તના બધા જ ગુણો દોષરૂપ થઈ જાય છે. સંતો હરિજનોના દોષ કહે ને હરિજનો સંતોના દોષ કહે એમ પરસ્પર દોષબુદ્ધિ થઈ જાય છે. સંતો ને હરિજનો કલ્પવૃક્ષ જેવા છે. તે જે કલ્પે તે પ્રત્યક્ષ દેખાઈ આવે છે. બન્નેના આત્મા તો શુદ્ધ દર્પણ તુલ્ય છે. તેથી સંકલ્પમાત્ર તાદૃશ્ય જણાઈ આવે છે.","e":"At Ganph, at the home of Manubha Raja, Shriharí said while talking, “Kuhet (soured affection, ill-will) is like fire and poison. If Kaliyug, which is sin itself, enters even a mukta, it deforms him too, and then he begins to speak of the faults of haribhaktas. By taking the faults of harijans, all the virtues of that mukta turn into faults. The Sants speak of the faults of the harijans and the harijans speak of the faults of the Sants — thus a fault-seeing mind arises on both sides. The Sants and harijans are like a kalpavruksh: whatever one imagines of them appears plainly before one. The atmas of both are like a pure mirror; therefore every intention is reflected exactly as it is.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":309,"k":"para","g":"“પરસ્પર જ્યારે કુહેત થાય છે ત્યારે ગુણમાત્ર દોષરૂપ થઈ જાય છે.","e":"“When kuhet arises between them, every virtue turns into a fault.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":310,"k":"para","g":"“કુહેત એ કળિનું રૂપ છે. સ્વાર્થભંગ થાય ત્યારે એ કળિયુગ ઝળકી ઊઠે છે. પરમાર્થનું રૂપ લઈ સ્વાર્થ રહ્યો છે. એ કામ પડ્યે દેખાઈ આવે છે. પરસ્પર હેત રહે ત્યાં સુધી કુહેત થતું નથી, સુહૃદભાવ તૂટતો નથી. કળિ પ્રવેશ થાય છે ત્યારે અપાર હેતને પણ ખારું ઝેર કરી મૂકે છે.","e":"“Kuhet is the form of Kali. When self-interest is thwarted, that Kaliyug flares up. Self-interest has remained, wearing the form of paramarth (the highest good); it shows itself when occasion arises. As long as het remains between them, kuhet does not arise and suhradbhav (friendship, goodwill) does not break. When Kali enters, it turns even boundless het into bitter poison.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":311,"k":"para","g":"“આ લોક કાજળ જેવો છે જે આકાશ જેવા નિર્લેપને પણ દાગ લગાડી દે છે. તુચ્છ સ્વાર્થ માટે આ દેહ એકબીજાનો દ્રોહ કરાવે છે. હરિજન સંગે જીવમાં હેત રહે તો દોષ નજરમાં ન આવે. હેત ટળે છે ત્યારે અપાર ગુણ પણ દોષરૂપ થઈ જાય છે. અભાવને લીધે દૃષ્ટિ વિરૂપ થઈ જાય છે ને ગુણને દોષ રૂપ કરી નાખે છે.”","e":"“This world is like kajal (lamp-black), which stains even one as untainted as the sky. For petty self-interest this body makes people commit droh against one another. As long as het remains in the jiva through the company of harijans, faults do not come into view. When het fades, even boundless virtues turn into faults. Because of abhav one’s vision becomes distorted, and it turns virtues into faults.”","s":["12/17(16)/16-30"],"sv":["कलियुग पाप हि रूप, करत प्रवेश जब मुक्त महिं ।\n\n तब सो होत विरुप, हरिजन के सो दोष कहत ॥\n\n संत हरिजन के हरिजन ताके । दोष कहन लगे जब वाके ॥\n\n हरिजन संत कल्पवृक्ष समाना । कल्पत जेसे आत देखाना ॥\n\n हरिजन संत के जीय जेहा । शुद्ध काच सम सबके तेहा ।\n\n तामें संकल्प कर हि जेसा । देखाई आवत सादृश्य तेसा ॥\n\n परस्पर कुहेत जब होवे । गुण सब दोष करि तब जोवे ॥\n\n कुहेत सो हे कलि को रुपा । स्वारथ भंग भये होत विरुपा ॥\n\n परमारथ सें स्वारथ रहेउ । काम परे देखात तब तेउ ॥\n\n परस्पर ज्यां लग रहे हेता । त्यां लग न होत कुहेता ॥\n\n कलि करत प्रवेश जेहि वारा । हेत अपार करि देत खारा ॥\n\n काजल सम यह लोक कहावे Iआकाश सम ताकुं दोष लगावे ॥\n\n हरिजन के संग ज्यां लग हि । हेत रहत जीय में त्यां लगहि ॥\n\n एक एक को हेत इच्छत अपारा । दोष न देखत कबहु लगारा ॥\n\n हेत को जब हि होवत नासा । अपार गुण को रहत न पासा ॥\n\n जितने गुण देखे दोष रूपा । अभाव सें गुण होत विरूपा ॥"],"mt":false,"gl":null,"a":false},{"i":312,"k":"para","g":"ભૂજમાં શ્રીહરિ કહે, “રાત-દિવસ ભગવાનને પ્રાર્થના કરવી કે કોઈ જીવનો ક્યારેય કોઈ રીતે દ્રોહ ન થાય. મન-કર્મ-વચનથી અજાણ્યે દ્રોહ લગારેક પણ થઈ જાય તો સ્તુતિ કરવી, ક્ષમા માગવી, ‘માફ કરજો, દયા કરીને દ્રોહથી ઉગારજો,’ એમ સંભારે તેની રક્ષા ભગવાન કરે છે.”","e":"At Bhuj, Shriharí said, “Pray to Bhagwan night and day that no droh is ever committed against any jiva in any way. If, by mind, action or speech, even the slightest droh is committed unknowingly, then offer stuti (prayerful praise) and ask forgiveness — ‘Please forgive me; mercifully save me from droh.’ Bhagwan protects one who remembers Him in this way.”","s":["12/30/35-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":313,"k":"para","g":"શ્રીહરિએ તુલસી દવેને કહ્યું, “કોઈ સત્સંગ પ્રત્યે દ્વેષ રાખે અને સંત અથવા હરિભક્તને વિના અપરાધે મારે તેને અનેક બ્રહ્માંડ ભાંગ્યાનું પાપ લાગે છે. અને એક મનુષ્ય સત્સંગને માર્ગે ચાલતો હોય તેને દોષ દેખાડી વિમુખ કરે અને બીજે માર્ગે ચલાવે તો તે ઘોર નરકમાં જાય છે. અને તેને પણ એક બ્રહ્માંડ ભાંગ્યાનો દોષ લાગે છે. એવા દોષનો જેને ત્રાસ નથી તેને અસુર કહેવાય. અને સંતમાં ભગવાનની બુદ્ધિ રાખીને નિષ્કપટભાવથી તેની સેવા કરે તો તે માયાના મળથી તરી જાય છે.”","e":"Shriharí said to Tulsi Dave, “One who harbours hatred toward satsang and strikes a Sant or a haribhakta who has done no wrong incurs the sin of destroying many brahmands. And one who, by pointing out faults, turns a man walking the path of satsang away and sets him on another path goes to a terrible narak, and he too incurs the fault of destroying a brahmand. One who has no dread of such a fault is called an asur. And one who serves the Sant without kapat, keeping toward the Sant the understanding one keeps toward Bhagwan, crosses beyond the impurity of maya.”","s":["12/48/5-11"],"sv":[],"mt":false,"gl":null,"a":false},{"i":314,"k":"para","g":"મેથાણમાં શ્રીહરિ કહે, “અમારો તથા અમારા સંતોનો જે અધર્મી દ્વેષ કરે છે, તેનો નાશ થાય છે. છતાં અધર્મીઓ તપાસીને જોતા નથી.”","e":"At Methan, Shriharí said, “The adharmi who bears hatred toward Us and Our Sants is destroyed. Yet the adharmis do not look closely and see this.”","s":["12/51/9"],"sv":[],"mt":false,"gl":null,"a":false},{"i":315,"k":"para","g":"મેથાણમાં શ્રીહરિએ વાત કરતાં કહ્યું, “અધર્મનો વંશ એકે એક ઓળખીને તેને તજીને જે સત્સંગ કરે છે તે દિવસે દિવસે વૃદ્ધિ પામે છે. અધર્મવંશનું એક પણ બીજ ગુપ્ત રહે ત્યાં સુધી સંત-હરિભક્તનો દ્રોહ થવાનો સંભવ છે.","e":"At Methan, while talking, Shriharí said, “One who recognises each and every member of the lineage of adharma, abandons it, and does satsang grows day by day. As long as even a single seed of the lineage of adharma remains hidden, there is the possibility of droh against the Sants and haribhaktas.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":316,"k":"para","g":"“સત્સંગમાં રહીને દ્રોહ કરે તે બીજાના દેખ્યામાં આવે નહિ. દ્રોહી હોય તે દસ-વીસ સંત-હરિભક્તના અપાર ગુણ ગાય પણ બીજા સંત-હરિભક્તના અવગુણ ગાય. સમય વિના જ્યાં ત્યાં અભાવ બોલે નહિ, પણ ગુણ બોલતાં સમય આવે ત્યારે અભાવનાં વચન બોલે. બીજાના દેખ્યામાં ન આવે તેમ અભાવ કહી દેખાડે. સરળ સંત-હરિભક્તને તેવું આવડે નહિ.","e":"“One who commits droh while remaining in satsang is not noticed by others. A drohi will sing the boundless virtues of ten or twenty Sants and haribhaktas, but sing the faults of other Sants and haribhaktas. He does not speak abhav anywhere and everywhere out of season; but when an occasion comes while speaking of virtues, he speaks words of abhav. He shows abhav in such a way that others do not notice it. A saral (guileless, straightforward) Sant or haribhakta does not know how to do this.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":317,"k":"para","g":"“સંત-હરિભક્તો પરસ્પર દ્રોહબુદ્ધિ રાખે તે ધર્મવંશી કહેવાય નહિ ને ત્યાં લગી તેનો આસુરી સ્વભાવ ગણાય. ધ્યાન, ધારણા અને સમાધિની મોટી મોટી વાતો કરે તથા અમારાં ચરિત્ર અને વચનામૃત કહી દેખાડે, ચાંદ્રાયણ આદિ વ્રતો વારંવાર કરે, અન્ન-ફળ-ફૂલ, મૂળ-જળનો ત્યાગ કરે, ફાટેલાં તૂટેલાં વસ્ત્ર પહેરે, ભૂમિ ઉપર સૂઈ રહે, સિદ્ધાસન વાળીને આખી રાત જાગે - એમ બધાં સાધન કરે તોપણ એ આસુરી સ્વભાવવાળાને નિષ્ફળ છે. જેટલું કંઈ કરે તે દ્રોહબુદ્ધિ વિના કરે તે સાચું દ્રોહનું રૂપ સૂક્ષ્મ છે તે કોઈને જણાય નહિ, બુદ્ધિવાળાને જ ખબર પડે.”","e":"“Sants and haribhaktas who keep drohbuddhi (a malicious attitude) toward one another cannot be called dharmavanshi (of the lineage of dharma), and until then their nature is reckoned asuri. They may speak grandly of dhyan, dharana and samadhi, narrate Our charitras and vachanamrut, repeatedly observe vows such as chandrayan, give up grain, fruit, flowers, roots and water, wear torn and tattered clothes, sleep on the ground, and sit in siddhasan awake all night — though they perform all such sadhanas, for one of asuri nature it is fruitless. Whatever one does — only what is done without drohbuddhi is true. The form of droh is subtle; no one recognises it — only one with understanding comes to know it.”","s":["12/51/23-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":318,"k":"para","g":"શ્રીહરિએ પત્રમાં લખાવ્યું કે, “ચાહે તેવો જીવ હોય પણ જો તે હરિભક્તના ગુણ ગ્રહણ કરે તો હરિજન થાય ને સંતના ગુણ ગ્રહણ કરે તો સંત થાય. દાસ થઈને રહે તો ઈશ્વરના જેવા ગુણ આવે છે.”","e":"Shriharí had it written in a letter: “Whatever kind of jiva one may be, if he imbibes the virtues of a haribhakta he becomes a harijan, and if he imbibes the virtues of a Sant he becomes a Sant. If he lives as a servant, qualities like those of Ishwar come to him.”","s":["12/71/35-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":319,"k":"para","g":"ગઢપુરમાં જીવેન્દ્રના દરબારમાં શ્રીહરિએ વાત કરતાં કહ્યું, “સંત-હરિભક્તોનો જે દ્રોહ કરે તેની જે મહોબત રાખે તે કેવી રીતે માયાને તરે! ભાંગેલા વહાણમાં બેસે તો સમુદ્ર તરી શકે નહિ. કોટિ ગૌદાન કરે તોપણ ડૂબે. તેમ હરિભક્ત હોય કે સંત હોય છતાં ભગવાન તથા ભક્તના દ્રોહીનો સંગ કરવા રૂપ જે ભાંગેલું વહાણ તેમાં બેસે તે તરી શકે નહિ.","e":"At Gadhpur, in the darbar of Jivendra, Shriharí said while talking, “How can one who keeps mahobat (fond attachment) for a person who commits droh against the Sants and haribhaktas cross maya? One who sits in a broken ship cannot cross the ocean; even if he gives ten million cows in charity, he still drowns. In the same way, whether he is a haribhakta or a Sant, one who sits in that broken ship — the company of those who commit droh against Bhagwan and His bhaktas — cannot cross.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":320,"k":"para","g":"“સંત-હરિભક્તને દેખીને જેની છાતી ઠરે નહિ અને નેત્રમાં ઝેર વરસે તે કુસંગી અને દ્રોહી કહેવાય છે. અને સંત-હરિજનને જોઈને જેની છાતી ઠરે છે અને તેમનો ગુણ ગ્રહણ કરે છે તેનાં કરોડો પાપ હોય તે પણ ભગવાન માફ કરે છે. ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિયુક્ત હોય છતાં મારા ભક્તનો દ્રોહ કરતો હોય તો તે મારા ચરણને પૂજી મારું માથું કાપનારો છે. એટલે કે મારો દ્રોહી છે. આ વાત યથાર્થ સમજાય તો કુસંગીની મહોબત રહે નહિ.”","e":"“One whose heart is not soothed (lit. whose chest does not cool) on seeing the Sants and haribhaktas, and from whose eyes poison rains, is called a kusangi and a drohi. And one whose heart is soothed on seeing the Sants and harijans and who imbibes their virtues — even if he has ten million sins, Bhagwan forgives them. Even if one is endowed with dharma, gnan, vairagya and bhakti, if he commits droh against My bhakta, he is one who worships My feet and cuts off My head — that is, he is My drohi. If this is understood as it truly is, no mahobat for a kusangi will remain.”","s":["13/65/21-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":321,"k":"para","g":"શ્રીહરિએ આખા ગામના હરિજનો પાસે વાત કરી કે, “જે હરિજન મોક્ષના દ્વારસમા ગુરુરૂપ સંતનો અવગુણ કહે તો તેને અમે અમારો દ્રોહી કહીએ છીએ.","e":"Shriharí said before the harijans of the whole village, “If a harijan speaks of the faults of the Sant who is the guru — the Sant who is like the very gateway of moksha — We call him Our drohi.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":322,"k":"para","g":"“કપટ અને કુટિલપણું ટાળ્યું ન હોય અને નિયમ-ધર્મ યથાર્થ પાળતો હોય ને બીજા દોષે યુક્ત હોય તો તેને અમે બદરિકાશ્રમ, શ્વેતદ્વીપમાં તપ કરાવીને શુદ્ધ કરીએ, પણ દ્રોહી શુદ્ધ થતો નથી. તપે કરીને શુદ્ધ થાય પછી સંતમાં જન્મ ધરાવીએ છીએ. તે હરિજન પછી સંત-ગુરુનો અલ્પ સરખા ગુણને મેરુ સમ મોટો કરી વારંવાર કહેતો હોય ને સૌના દાસાનુદાસ રહેતો હોય તો અમે તેને શુદ્ધ થયો માની જાળવીએ છીએ. તપ કરતાં પણ સાચા સંતના ગુણ ગ્રહણ કરવા તેનું બળ વધારે છે. એ અપાર બળને પ્રતાપે દ્રોહના પાપથી બચી જાય છે. પછી તે સરળપણે વર્તીને ભવસિંધુ સહેજે તરી જાય છે.”","e":"“If one has not rid himself of kapat and crookedness, yet observes niyam and dharma properly but is tainted by other faults, We purify him by making him perform tap (austerities) in Badrikashram and Shvetdwip; but a drohi does not become pure. Once he has been purified by tap, We have him born among the Sants. If that harijan then magnifies even a small virtue of the Sant-guru to the size of Mount Meru and speaks of it again and again, and remains the servant of the servants of all, then We consider him purified and look after him. The strength of imbibing the virtues of a true Sant is greater even than tap. By the power of that boundless strength he is saved from the sin of droh. Then, behaving with simplicity, he easily crosses the ocean of worldly existence.”","s":["14/31/28-35"],"sv":["हरिजन गुरु - संत, मोक्ष के हें जो द्वार यह ।\n\n अवगुन ताके कहंत, एसे कुं द्रोही कहत हम ॥\n\n नियम धर्म यथार्थ रखे जोउ । तप करिके शुद्ध होव हि तोउ ॥\n\n बद्रिधाम श्वेतद्विप मांहि । शुद्ध जब होवत रहाहि ॥\n\n हरिजन संत गुरु ताके । अल्प गुन हि जेहि वाके ॥\n\n मेरु सम गुन गावहि जबहि । हरि सो शुद्ध भये मानहि तबहि ॥\n\n कपट कुटिलता रहे ज्यां लगहि । हरि सो तप करात त्यां लगहि ॥\n\n नियम में जेति रहत कचाई । तितनी खोट सो जानत ताई ॥\n\n हरिजन संत गुरु तिनके । दासानुदास होई वरते इनके ॥\n\n अल्प गुन तेहि मेरु से भारी । मुख से कहेवे वार हि वारी ॥\n\n तप सें गुन के बल अपारा । जानत द्रोह न करत को वारा ॥\n\n सरल होइ सत्संग करहि । भवसिंधु सो सहज हि तरहि ॥"],"mt":false,"gl":null,"a":false},{"i":323,"k":"para","g":"શ્રીહરિએ પાદરામાં વાત કરતાં કહ્યું, “દેવોથી દૈત્યો સુધી સૌમાં રાજસ-તામસ ગુણ રહેલા છે. જેવા ગુણ તેવી બુદ્ધિ થાય છે. અને એ મુજબ સૌ ચાલે છે. પ્રથમ સત્યુગમાં દેવો-દૈત્યો અને મનુષ્યોની મતિ સત્ત્વગુણ પ્રધાન હતી. અને શુભ માર્ગે સૌ ચાલતા. ઘરે ઘરે કલ્પવૃક્ષ હતાં. જે ધારતાં તે થતું. એ સમયની નીતિ પણ કલ્પવૃક્ષ જેવી હતી. રાજા નીતિ છોડી રાજ કરતા તે ભ્રષ્ટવેશ કહેવાતા. સૌ માનતા કે પવિત્ર સંત અને શુદ્ધ વિપ્રના અપમાનથી મતિનો નાશ થઈ જાય છે. તેના પર ઈશ્વરનો કોપ થાય છે. સત્યયુગમાં મન ગમે ત્યાં લઈ જાય પણ તે રસ્તો સત્યનો જ હોય એમાં કોઈને શંકા રહેતી નહીં.”","e":"At Padra, Shriharí said while talking, “From the devas to the daityas, the rajas and tamas gunas reside in all. As the gunas are, so the mind becomes, and accordingly everyone behaves. At first, in the Satyayug, the minds of devas, daityas and humans were predominantly sattvik, and everyone walked the auspicious path. In every home there were kalpavruksh; whatever one wished came to be. The niti (right conduct) of that time too was like a kalpavruksh. Kings who ruled abandoning niti were called fallen. Everyone believed that by insulting a holy Sant or a pure Brahmin, one’s mind is destroyed and the wrath of Ishwar falls upon one. In the Satyayug, wherever the mind led, that path was only of truth; of this no one had any doubt.”","s":["14/62/7-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":324,"k":"para","g":"સારંગપુરમાં જીવાખાચરના દરબારમાં સંતોને વાત કરતાં શ્રીહરિએ કહ્યું, “એક જ દિવસના સાધુ હોય તેનો પણ રંચ જેટલો દોષ આવે તો કોટિ કલ્પથી સત્સંગ કર્યો હોય તોપણ તેનો ભંગ થાય છે. તે અપરાધ ભગવાન અને મોટા સંત પાસે ગયેથી છૂટતો નથી, પણ જેનો અપરાધ કર્યો હોય તેને નિષ્કપટ થઈને નમે તો જ છૂટે છે. એ વિના કોટિ ઉપાય કરે પણ રતીભર અપરાધ ટળતો નથી. અપરાધથી છૂટ્યા પછી પણ તે કોઈનો અપરાધ ન કરે, તો તેને વિઘ્ન આવતું નથી. સત્સંગના પ્રતાપથી કોઈ હરિજનને સમાધિ થતી હોય તો પણ તે સંતની તોલે ન આવે. જેટલો સંતનો દાસ થઈને વર્તે તેટલી તેની મોટપ છે. સર્વ મોટપમાં દાસ થવું તે અધિક મોટપ છે.”","e":"In the darbar of Jiva Khachar at Sarangpur, Shriharí said while talking to the Sants, “If one perceives even a speck of fault in a sadhu who has been a sadhu for only a single day, then even if one has done satsang for ten million kalpas, it is broken. That offence is not absolved by going to Bhagwan or to a great Sant; it is absolved only if one bows without kapat to the very person one has offended. Apart from that, though one tries ten million remedies, not a particle of the offence is removed. And after being freed from the offence, if he commits no offence against anyone, no obstacle comes to him. Even if, by the power of satsang, some harijan attains samadhi, he still does not equal the Sant. To the extent one behaves as the servant of the Sant, to that extent is his greatness. Of all greatness, becoming a servant is the greater greatness.”","s":["14/83/34-38"],"sv":["एक हि दिन के साधु ताके । रंच जो दोष आवे वाके ॥\n\n कोटि कल्प के रहे सत्संगा । तरत ताके होई जावत भंगा ॥\n\n भगवान बडे संत से जोउं । पाप नहि छुटत हें सोउ ॥\n\n जाको अपराध किने जाई । निष्कपट होई नमे ताई ॥\n\n फेर न करे कोईको अपराधा । तब ताकुं न रहत तेहि बाधा ॥\n\n ता विन करे कोटि उपाया । दोष न रतिभर जात रहाया ॥\n\n जाहि हरिजन जितने, सत्संग के प्रताप ।\n\n समाधि होय जद्यपि तोउ, संत जोनां अमाप ।\n\n संत संत के दास होई, वरतहि जो जितने जेहु ।\n\n मोटप से मोटप एहि हें, सबसें अधिक तेहुं ॥"],"mt":false,"gl":null,"a":false},{"i":325,"k":"para","g":"શ્રીહરિએ ગઢપુરમાં જીવેન્દ્ર નૃપને વાત કરતાં કહ્યું, “અમારી વાત સૌ બાઈ-ભાઈઓએ યાદ રાખીને પરસ્પર કહેવી. યાદ રાખ્યા વિના કોઈ હરિજનનું અંગ વૃદ્ધિ ન પામે. એટલે વાત સાંભળી યાદ રાખવી તેમાં ગાફલતા ન રાખવી. ગાફલતા હશે તો જેવા હશો તેવા ને તેવા રહેશો. પછી કહેશો કે અમે હરિભક્ત થયા પણ સત્સંગમાં કંઈ દેખ્યું નહિ. અમારી વાત હૃદયમાં ધારે તો તેનો સત્સંગ પાકો રહે.","e":"At Gadhpur, Shriharí said while talking to Jivendra Nrup, “All the women and men should remember Our talks and tell them to one another. Without remembering them, no harijan’s ang grows. Therefore, having heard the talks, remember them; do not be careless in this. If you are careless, you will remain just as you are. Then you will say, ‘We became haribhaktas, but we saw nothing in satsang.’ One who holds Our talks in the heart — his satsang stays firm.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":326,"k":"para","g":"“કેટલાક તો સત્સંગની વાત શીખીને સત્સંગનો દ્રોહ કરે છે તેના જેવો કોઈ કૃતઘ્ની નથી. સંત અને હરિભક્તમાં જેવા દોષ દેખાડે છે તેવા દોષ તેને લાગે છે. સત્સંગમાં નિયમ રાખનારા અગ્નિ સમાન શુદ્ધ છે ને દ્રોહ કરનારા વિકટ રોગે કરીને બીજી રીતે વિના અગ્નિએ બળતા રહે છે. તનમાં રોગ આવે છે ને તે રાત-દિન રડ્યા કરે છે. આત્મવિચાર લેશમાત્ર રહેતો નથી.”","e":"“Some, having learnt the talks of satsang, commit droh against satsang — there is no ingrate like them. Whatever faults they point out in the Sants and haribhaktas, those very faults attach to them. Those who keep the niyams in satsang are pure like fire, while those who commit droh burn in another way, without fire, through grievous disease. Disease enters their bodies and they weep night and day. Not a trace of atma-vichar (reflection on the self) remains.”","s":["15/19/28-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":327,"k":"para","g":"ગઢપુરમાં જીવેન્દ્રના દરબારમાં રંગોત્સવ પછી શ્રીહરિ કહે, “કામ ક્રોધાદિક શત્રુ અસુરથી પણ અધિક છે, જેનાથી અપરાધમાં પડાય છે. અપરાધ કરીને જે નમે છે તેને દેવ જાણવો અને ન નમે તેને અસુર જાણવો. પાંચવાર ગદ્‌ગદ કંઠે ગ્રંથ સાંભળે અને તેનો અભ્યાસ અંતરમાં રાખે, તત્ત્વરૂપી વાતને કંઠે કરે, રામદાસજી અને મુક્તમુનિ જેવાનો સમાગમ રાખે છતાં સંત-હરિભક્તને નમે નહિ, તે સત્સંગમાં અસુર જાણવા. જે સંત-હરિભક્તોને નમે છે તે જ સાચા સંત અને હરિભક્તો છે. નમનારાને ધર્મભક્તિ આદિ ગુણો, તત્ત્વરૂપી વાત, ધ્યાન-ધારણા વગેરે સાધન ને સંતસમાગમ - એ કોઈ તજી જતાં નથી. નમનારામાં એક પણ દોષ રહેતો નથી.”","e":"At Gadhpur, in the darbar of Jivendra, after the Rangotsav, Shriharí said, “Kam, krodh and the other enemies are worse even than asurs, for by them one falls into offence. Know one who bows after committing an offence to be a deva, and one who does not bow to be an asur. Even if one hears the scripture five times with a choked voice and keeps up its study within, learns by heart the talks of tattva (essential truth), and keeps the samagam of such as Ramdasji and Muktamuni — yet does not bow to the Sants and haribhaktas, know such people to be asurs in satsang. Only those who bow to the Sants and haribhaktas are true Sants and haribhaktas. The one who bows is never forsaken by the virtues of dharma, bhakti and the rest, by the talks of tattva, by sadhanas such as dhyan and dharana, or by the samagam of the Sant. In one who bows, not a single fault remains.”","s":["15/23(22-b)/29-37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":328,"k":"para","g":"શ્રીહરિએ કરજીસણમાં નાનાભાઈ અને ગોવિંદભાઈને ત્યાં જન્માષ્ટમીનો ઉત્સવ કર્યો. તેમાં વાત કરતાં કહ્યું, “કામી, ક્રોધી, લોભી જનો પોતાના દોષ દેખાડીને જો સંત-હરિભક્તના ગુણ ગાતા હશે તો તે કોઈક દિવસ સત્સંગ કરશે ને ગુણ લેવાથી તેનાં પાપ બળી જાય છે. પાપ છૂટવા માટે સંત-હરિભક્તને એકવાર માથું નમાવી હાથ જોડે ને ભાવથી અન્નજળ આપે તે સત્સંગ થવાનું બીજ છે. દ્રોહ કરવાથી સુકૃત નાશ પામે છે. સત્સંગના દ્રોહથી વૃક્ષ, ઘાસ કે પથ્થરનો દેહ આવે છે.”","e":"Shriharí celebrated the Janmashtami festival at Karjisan, at the home of Nanabhai and Govindbhai. Talking there, He said, “If people who are lustful, angry and greedy, while showing their own faults, sing the virtues of the Sants and haribhaktas, then some day they will do satsang; and by imbibing virtues their sins are burnt away. For release from sin, if one bows one’s head once to a Sant or a haribhakta, joins one’s hands, and offers food and water with feeling — that is the seed of coming into satsang. By droh, one’s sukrut (merit of good deeds) is destroyed. By droh against satsang one gets the body of a tree, grass or stone.”","s":["15/51/20-25"],"sv":[],"mt":false,"gl":null,"a":false},{"i":329,"k":"para","g":"વડતાલમાં અન્નકૂટ ઉત્સવ પર ભક્તોને ઉદ્દેશીને શ્રીહરિ કહે, “જે અમારી સન્મુખ છે તેની સન્મુખ અમે આ સભા સહિત રહીએ છીએ, પરંતુ જે સંતનો દ્રોહ કરે છે તે હરિભક્ત હોવા છતાં તેને અમે અસુર, અધર્મી જાણીએ છીએ. અમારા સંતો-ભક્તોએ કોઈની નિંદામાં પડવું નહિ. નિંદિત માર્ગનો ત્યાગ કરવો. નિંદિત કર્મનો ત્યાગ કરી જે વર્તે છે તે દેવથી અધિક છે. જેનાં નેત્ર સંતો-ભક્તોને જોઈ હરખતાં હોય, કોઈનો દ્વેષ-દ્રોહ જે ન કરતા હોય, એવી સમજ-બુદ્ધિવાળાને શ્રીહરિ સંત-હરિજનનના સંગમાં રાખે છે. સત્સંગની સાચી રીત જેને જેટલી સમજ્યામાં આવી તેની મોક્ષ તરફ ગતિ જાણવી.”","e":"At Vartal, at the Annakut festival, addressing the bhaktas, Shriharí said, “Whoever is turned toward Us — We, together with this whole assembly, remain turned toward him. But one who commits droh against the Sant, though he be a haribhakta, We regard as an asur and an adharmi. Our Sants and bhaktas should not fall into slandering anyone. Abandon the censured path. One who abandons censured actions and lives accordingly is greater than a deva. Those whose eyes rejoice on seeing the Sants and bhaktas, and who harbour no hatred or droh toward anyone — Shriharí keeps such people of understanding in the company of the Sants and harijans. To the extent one has understood the true way of satsang, know that to be his progress toward moksha.”","s":["15/64/17-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":330,"k":"para","g":"વડતાલમાં વાસણ સુથારને ઘરે શ્રીહરિ કહે, “સાચા સંતનો ને સત્સંગનો જ્યાં સુધી મનમાં અભાવ રહે, ત્યાં સુધી તે પાપના ફળરૂપ દુઃખ ભોગવે છે. જમપુરીનો માર ખાય છે. મતિ શુદ્ધ ન થાય એ જેવો બીજો કોપ નથી.”","e":"At Vartal, at the house of Vasan Suthar, Shriharí said, “As long as abhav toward the true Sant and toward satsang remains in the mind, one suffers misery as the fruit of sin and endures the beating of Yampuri. There is no other wrath like this — that one’s mind does not become pure.”","s":["16/57/29-32"],"sv":[],"mt":false,"gl":null,"a":false},{"i":331,"k":"para","g":"વડોદરાના દીવાન ઝુમખરામ જોષી ગઢપુર આવ્યા હતા, તેમને શ્રીહરિ કહે, “સત્પુરુષમાં જેવા ભાવ કલ્પે છે તેવું ફળ પામે છે. અમૃતની રુચિ હોય તેને અમૃત ગમે છે. બધું ઈશ્વરને આધીન વર્તે છે એમ જાણી ડાહ્યા માણસો કોઈનો દ્રોહ કરતા નથી.”","e":"Jhumkharam Joshi, the Diwan of Vadodara, had come to Gadhpur. Shriharí said to him, “Whatever bhav one imagines in the Satpurush, such is the fruit one attains. One who has a taste for amrut likes amrut. Knowing that everything functions subject to Ishwar, wise people commit droh against no one.”","s":["17/65/15-18"],"sv":[],"mt":false,"gl":null,"a":false},{"i":332,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ કહ્યું, “સાચાનો દ્રોહ કરનાર યમદૂતથી પણ અધિક પાપી છે. તેને મહાપાપી કહીએ, અપાર પાપી કહીએ.”","e":"At Gadhpur, Shriharí said, “One who commits droh against one who is true is a greater sinner even than the messengers of Yama. Call him a great sinner, a boundless sinner.”","s":["20/16/24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":333,"k":"para","g":"શ્રીનગરમાં શ્રીહરિએ ઉત્તમ-મધ્યમ અને કનિષ્ઠ ત્રણ પ્રકારના ભક્તની વાત કરતાં કહ્યું, “હરિજન ત્રણ પ્રકારના છે: ઉત્તમ, મધ્યમ ને કનિષ્ઠ. મરજી સચવાય ત્યાં સુધી હરિજન સારો દીસે, પણ મરજીખંડન જ્યારે થાય છે ત્યારે ભગવાન ને સંતના દ્રોહમાં પડે છે ને મતિ વિપરીત થઈ જાય છે. ઊતરતાં ઊતરતાં અધમ થઈ જાય છે. જો સંતનો દ્રોહ ન કરે તો તેનું સુકૃત તેને કનિષ્ઠ સુધી લાવે છે. તે પણ ટોકે નહિ ત્યાં સુધી કનિષ્ઠ રહે છે ને સત્સંગનો ત્યાગ કરતો નથી.","e":"At Shrinagar, speaking of three kinds of bhaktas — uttam, madhyam and kanishth (the best, the middling and the lowest) — Shriharí said, “Harijans are of three kinds: uttam, madhyam and kanishth. As long as his wishes are kept, a harijan appears good; but when his wishes are crossed, he falls into droh against Bhagwan and the Sant, and his mind becomes perverse. Descending and descending, he becomes base. If he does not commit droh against the Sant, then his sukrut brings him only as far down as kanishth. He too remains kanishth — so long as no one checks him — and does not abandon satsang.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":334,"k":"para","g":"“મધ્યમ ભક્ત એ છે કે એક સંત પર ભાવ રાખે ને તનથી ને મનથી એકપણે વર્તે. વળી, મારા જેવી સમજણ કોઈને નથી, એમ જે હરિજન સમજતો હોય તો તે મધ્યમ હરિજન જાણવો.","e":"“A madhyam bhakta is one who keeps bhav toward one Sant and behaves as one with him in body and mind. Moreover, the harijan who believes, ‘No one has understanding like mine’ — know him to be a madhyam harijan.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":335,"k":"para","g":"“ઉત્તમ હોય તે મન, કર્મ, વચને નિર્દંભ વર્તે. સંતો-ભક્તોને નિર્દોષ જાણે. નિષ્કપટપણે સત્સંગ કરે અને સર્વેનો જે દાસ થઈને રહે. ભગવાનને અને તેમના ધામને માયાપાર નિર્દોષ જાણે, હરિજનને પોતાથી અધિક જાણે, હરિજનનો પક્ષ રાખે અને જેનો સત્સંગ જીવનો હોય તે ઉત્તમ ભક્ત છે.”","e":"“The uttam bhakta behaves without pretence in mind, action and speech. He knows the Sants and bhaktas to be faultless. He does satsang without kapat and remains the servant of all. He knows Bhagwan and His Dham to be beyond maya and faultless, knows harijans to be greater than himself, takes the side of harijans — and one whose satsang is of the jiva is the uttam bhakta.”","s":["22/92/30-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":336,"k":"para","g":"ભૂજના હીરજીભાઈને શ્રીહરિએ કારિયાણીમાં કહ્યું, “સત્સંગીમાત્રમાં ગુણ દેખાય એને ભગવાન અને સંતની કૃપા થઈ જાણવી. સંતો-ભક્તોની ચરણરજ ઇચ્છવી. જ્યાં સુધી નિષ્કપટ મતિ રહે ને એટલામાં તન પડે તો નિશ્ચે તેનો મોક્ષ થાય. હરિજનમાં દોષ દેખતો હોય ને તે ચ્હાય તેવું વર્તન રાખતો હોય તો પણ દેહ છતાં જ સત્સંગથી વિમુખ થઈ જાય છે.”","e":"At Kariyani, Shriharí said to Hirjibhai of Bhuj, “When virtues are seen in every satsangi, know that the grace of Bhagwan and the Sant has come. Desire the dust of the feet of the Sants and bhaktas. So long as one’s mind remains free of kapat, if the body falls within that time, moksha is certain. But one who sees faults in harijans — whatever his conduct may be — turns vimukh (away) from satsang even while still in the body.”","s":["23/58/34-36"],"sv":["निष्कपट जिहां लगहि, एसी बुद्धि रहात ।\n\n तन छुटत रहे इनमें, निश्चे मोक्ष हो जात ॥\n\n हरिजन में देखत दोष हि, चाय तेसे रहेउ ।\n\n देह छते सत्संग में, विमुख होवत हि तेउ ॥"],"mt":false,"gl":null,"a":false},{"i":337,"k":"para","g":"નાગડકામાં શ્રીહરિએ વાત કરતાં કહ્યું, “સત્સંગ સૂર્ય સમાન છે. ઘુવડ જેવા જનોને તે દેખાશે નહિ. ફાવે તેવો અધર્મી હશે, પણ નિર્દોષ જાણી ગુણ ગ્રહણ કરશે તેનો ઉદ્ધાર થયા વિના રહે નહિ. અને ફાવે તેવો ગુણવાન હશે ને નિર્દોષમાં દોષ કલ્પશે કે દ્રોહ કરશે તે જમપુરીમાં ગયા વિના નહિ રહે.”","e":"At Nagadka, Shriharí said while talking, “Satsang is like the sun; owl-like people will not see it. However adharmi a person may be, if he regards [the Sants and bhaktas] as faultless and imbibes their virtues, he will not fail to be redeemed. And however virtuous a person may be, if he imagines fault in the faultless or commits droh, he will not escape going to Yampuri.”","s":["23/83/33-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":338,"k":"para","g":"શ્રીનગરમાં શ્રીહરિએ વાત કરી કે, “ભગવાન અને ભગવાનના ભક્તનું માહાત્મ્ય દિન દિન પ્રત્યે અધિક ને અધિક સમજે, તેનો અભાવ ક્યારેય ન લે અને ધર્મનું પાલન કરે એવી રીત અમે સ્થાપી છે. સત્સંગની પરમપુનિત આ પ્રણાલી ચાલુ રહેશે ત્યાં સુધી સત્સંગ વધતો રહેશે. સત્સંગની આ પ્રણાલી જે જાણે તે હરિજન કહેવાય છે. રીત જાણ્યા વિના હરિજનનું માહાત્મ્ય રહે નહિ ને માહાત્મ્ય વિના દરેકનો અભાવ લેવાતો થાય. હરિજન થઈને હરિજનનો અભાવ લે તે સત્સંગ કરતો હોય તોપણ તેની બાળકબુદ્ધિ જાણવી.” આવી અપાર વાત તો શ્રીહરિએ જેટલા દિવસ શ્રીનગરમાં રહ્યા તેટલા દિવસ કરી હતી. જેનો પાર આવે તેમ નથી. એમ મુક્તમુનિએ કહ્યું.","e":"At Shrinagar, Shriharí said, “To understand the mahatmya of Bhagwan and of Bhagwan’s bhakta more and more with each passing day, never to take abhav of them, and to observe dharma — this is the way We have established. As long as this supremely holy tradition of satsang continues, satsang will keep growing. One who knows this tradition of satsang is called a harijan. Without knowing the way, mahatmya does not remain in a harijan, and without mahatmya one comes to take abhav of each and every one. One who, being a harijan, takes abhav of a harijan — though he does satsang, know his understanding to be that of a child.” Such boundless talks Shriharí gave for as many days as He stayed in Shrinagar — there is no end to them. So said Muktamuni.","s":["28/11/7-11,19"],"sv":["भगवान, भगवान के जेता । भक्त जेते रहाये तेता ॥\n\n दिन दिन अधिक महात्म्य ताके । जानत रहे धर्मजुत हि वाके ॥\n\n ताके अभाव न कबु लहाता । धर्म की ज्यां लष्ण रीत चलाता ॥\n\n सत्संग की ज्यां लग चलत रीता । त्यां लग रहे यह परम पुनिता ॥\n\n सत्संग की ऐसे रीत रहाते । जानत तेहि हरिजन कहाते ॥\n\n रीत जाने विन हरिजन तिनके । महात्म्य नहि रहावत इनकें ॥\n\n महात्म्य बिन एक एक के जेहा । अभाव लेवत रहेउ तेहा ॥\n\n हरिजन होय हरिजन के जितनां । अभाव लेवत रहेउ तितनां ॥\n\n बाल मति रहे इतनां ताकि । सत्संग करेउ तोउ वाकि ॥\n\n जितने दिन श्रीनगर तामें । श्रीहरि रहत भये जो यामें ॥\n\n तितने दिन ऐसि बात अपारा । कहत भये न आयत पारा ॥"],"mt":false,"gl":null,"a":false}]},{"n":4,"gu":"આજ્ઞાપાલન","en":"Āgnā-Pālan — Obeying Commands","url":"https://www.anirdesh.com/pbp/index.php?page=chp_4","b":[{"i":339,"k":"para","g":"ઈંગોરાળામાં શ્રીહરિએ કહ્યું, “અમારા જનોએ મનમુખી ન થવું પણ આજ્ઞામાં રહેવું. મનમુખી થાય તે ભલે અનેક ધર્મ પાળે, કે મહાવૈરાગ્યવાળો હોય, કે મારું નામ લે, કે મારો મહિમા કહે, કે મને સંભારીને રોઈ જાય, શરીર સૂકવી નાખે, કે અહોનિશ ધ્યાન કરે કે કાવ્ય, કીર્તન કરે, તોપણ મારાથી વિમુખ છે.”","e":null,"s":["4/18/41-46"],"sv":[],"mt":false,"gl":null,"a":false},{"i":340,"k":"para","g":"મેમકામાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “નિયમમાં વર્તે તે માયાના પેચમાં ન આવે. તરવૈયો જળમાં બૂડે નહિ, પણ પ્રથમ તરતા શીખ્યો પછી તેને ભીતિ ટળે છે. શીખે નહિ ત્યાં સુધી મહા બળવાન મનુષ્ય પણ જળથી ડરે. સત્સંગનું પણ એવું છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":341,"k":"para","g":"“લૌકિક વિદ્યા અનેક પ્રકારની છે, તેમ બ્રહ્મવિદ્યા પણ અનેક પ્રકારે સત્સંગ થકી પ્રાપ્ત થાય છે. અંતર્દૃષ્ટિવાળાને તેની ગમ પડે છે. અંતર્દૃષ્ટિ વિના મોટા બુદ્ધિવાનને પણ બ્રહ્મવિદ્યા પરખાતી નથી.”","e":null,"s":["4/89/19-22"],"sv":["ब्रह्मविद्या के अंग हे अनंता । सो जानत बेठे बुद्धिमंता ॥\n\n अंतर्दृष्टि बिन बुद्धिवाना । ब्रह्मविद्या को न होवत ज्ञाना ॥"],"mt":false,"gl":null,"a":false},{"i":342,"k":"para","g":"જીવાખાચરના દરબારમાં સંતોને ઉદ્દેશીને શ્રીહરિ કહે, “મનનું ધાર્યું કરે ત્યાં સુધી જીવપણું મટતું નથી. ઈશ્વરનું ધાર્યું કરે ત્યારે ઈશ્વર જેવા બને છે.”","e":null,"s":["5/5/29"],"sv":[],"mt":false,"gl":null,"a":false},{"i":343,"k":"para","g":"ગઢપુરમાં શ્રીહરિ જીવેન્દ્રને કહે, “ભગવાનનું ગમતું કરવાની રીત રાખવી. જગતના જીવો પોતાનું ધાર્યું કરવા ઇચ્છે છે. ત્યાગ, જપ, તપ, તીર્થ, વ્રત, યજ્ઞ, બ્રહ્મભોજન તથા નાનાં પ્રકારનાં દાન કરે પણ મનમુખી હોય તેનું કલ્યાણ થતું નથી એમ અમે માનીએ છીએ. સૂર્ય ઉદય થાય તો દીવા, મશાલની જરૂર રહેતી નથી. વરસાદ પડે ત્યારે કોશથી પાણી કાઢવાની જરૂર રહેતી નથી. વહાણમાં બેસે તેને તુંબડાં બાંધવાની જરૂર રહેતી નથી. તેમ ભગવાનનું ગમતું કરે તેને બીજાં સાધન આપોઆપ થઈ જાય છે.”","e":null,"s":["5/72/20-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":344,"k":"para","g":"જેતપુરમાં શ્રીહરિએ વાત કરતાં કહ્યું, “મનમુખી વર્તન કરે છે તે બેહાલ થાય છે. જેને સત્સંગ રાખવો હોય તેણે લગારેય પણ મનમુખી ન થવું. નટ જેમ દોર પર નજર બાંધે છે, તેમ આજ્ઞારૂપી દોર પર નજર રાખીને જે ચાલે તેની જીત થાય છે. ભૂલથી પણ વચન ભંગ કરે છે તેની ફજેતી થાય છે. વળી, હરિભક્તને પાપ ન હોય તેમ કહો છો, પણ અમે એને જ હરિભક્ત જાણીએ છીએ કે જે અમારાં વચન પાળે, ગમતામાં વર્તે, નાની-મોટી આજ્ઞાઓમાં વિશ્વાસ કરે. સત્સંગ રાખવો તેણે મનમુખી વર્તવું નહીં, વચન તજીને ચાલવું નહિ. વચન પ્રમાણે ચાલે નહિ, તેને હરિભક્ત કહેવાય નહિ.”","e":null,"s":["6/64/25-30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":345,"k":"para","g":"માંગરોળમાં અન્નકૂટોત્સવ પછી શ્રીહરિ કહે, “અમારાં જે જે વચન છે તેમાં પ્રતીતિ લાવીને તે પ્રમાણે વર્તશે તેનો અમે મોક્ષ કરીશું. અમારાં ચરિત્ર જે સાંભળશે, તેને અમે અતિ સુખિયા કરીશું. અમારાં વચન એ અમે જ છીએ એમ જરૂર જાણજો. અમારાં વચન ન માને અને રાત-દિવસ અમારી પાસે રહી સેવા કરે, તેને અમે દૂર માનીએ છીએ. આ અમારો પાકો મત છે. અમારાં વચન અમારા કરતાં પણ મુખ્ય અમે માનીએ છીએ. વચનમાં અમારો અખંડ વાસ છે.”","e":null,"s":["6/73/20-24"],"sv":["हमारे जो वचन ही जितना । हमकुं सो जानना तितना ॥\n\n हमकुं जानी पालही जोहि । वचनरूप ता पास हें सोहि ॥\n\n हमारि पास रहत दिन रेनां । सेवा करत रहत प्रवेनां ॥\n\n वचन में न वरतहि जोउ । हमसे दूर तेहि जानना सोउ ॥\n\n हमारो मत नकि हे एहु । सब हरिजन सो जानि के लेहु ॥\n\n हमसे वचन हम मुख्य हि माने । वचन में हम अखंड ठाने ॥"],"mt":false,"gl":null,"a":false},{"i":346,"k":"para","g":"શ્રીનગરમાં શ્રીહરિ કહે, “સત્સંગીમાત્રે વચનરૂપી નિયમમાં રહીને ધર્મ પાળવો. નિયમમાં રહ્યા વિના ધર્મ પળાય નહિ. વચનમાં વર્તવું તે તપોવન કરતાં પણ શ્રેષ્ઠ છે.”","e":null,"s":["8/4/15"],"sv":[],"mt":false,"gl":null,"a":false},{"i":347,"k":"para","g":"ભૂજમાં શ્રીહરિએ હિંડોળામાં બેસીને વાત કરતાં કહ્યું, “ભગવાનનાં વચનમાં વર્તવાનું તાન રાખવું, એ અલૌકિક રીત કહેવાય. મનના કહ્યા પ્રમાણે ચાલે તો સિદ્ધ હોય તોપણ અસિદ્ધ થઈ જાય છે. વચનમાં વર્તે તે સિદ્ધનો પણ સિદ્ધ છે. ભગવાન પરોક્ષ થઈ ગયા તેમ જાણતો હોય તેને ભગવાનનાં વચન પ્રગટ માની તેમાં વર્તવું.”","e":null,"s":["10/33/35-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":348,"k":"para","g":"ગઢપુરમાં શ્રીહરિ કહે, “અમે કહીએ તે મુજબ સેવા કરે અને તેમાં ક્યારેય ન મૂંઝાય તેને અમે સેવામાં રાખીએ છીએ. મનનું ધાર્યું કરે તેવા સંતો, વર્ણી અને પાળાને અમે તજી દઈએ છીએ. ભવ, બ્રહ્મા, નારદ વગેરે મનગમતા માર્ગમાં ચાલ્યા તો તેઓ ફજેત થયા છે.”","e":null,"s":["11/78/5-8"],"sv":[],"mt":false,"gl":null,"a":false},{"i":349,"k":"para","g":"લોજમાં મુક્તમુનિ બ્રહ્મમુનિ પાસે ગાન કરાવી શ્રીહરિએ કહ્યું, “સાધનવાળો ભગવાનનાં ચરિત્રમાં અપાર દોષ પરઠે છે. સાધને કરીને પોતાનો મોક્ષ માને તેને અમારાં વચન માન્યામાં આવતાં નથી. માટે અમારાં વચન પ્રમાણે જ વર્તવું. અમારાં વચનમાં અનંત સાધન રહેલાં છે, એમ અમારા નિશ્ચયવાળા ગૃહી-ત્યાગી અનુયાયીઓએ જાણવું.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":350,"k":"verse","g":"‘હમારે વચન એક હિ તામે, સાધન અનંત જાનના વામે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":351,"k":"verse","g":"પ્રથમ હમારો નિશ્ચય જાકું, એસે ત્યાગિ રૂ ગૃહિ વાકું.’","e":null,"s":["12/17(16)/10-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":352,"k":"para","g":"ભુજમાં શ્રીહરિ કહે, “અમારાં જે વચન છે તેને અમૃત જેવાં માનવાં. તેને જે વિષ માને છે તેને વિષનું ફળ મળે છે. અમારાં વચન સુખદાયી છે.”","e":null,"s":["12/25/7"],"sv":[],"mt":false,"gl":null,"a":false},{"i":353,"k":"para","g":"ગઢપુરમાં શ્રીહરિની કહેલી વાત મુક્તમુનિએ કહી, “શ્રીહરિ કહે - પરબ્રહ્મના ઉપાસકોને બ્રહ્મ કહીને માને, ગુરુનાં વચન માથે ચઢાવે અને તે મુજબ વચનમાં વર્તે, સંતો સંતોના નિયમમાં, અને ગૃહસ્થો ગૃહસ્થોના નિયમમાં વર્તે તો તેને માયા પણ વિઘ્ન કરી શકતી નથી. કારણ કે માયા ભગવાનને આધીન છે. જે મનના કહ્યામાં વર્તે છે તેને માયા ગળી જાય છે. સત્સંગમાં તેનો પગ ટકતો નથી અને અંતે વિમુખ થઈ લખચોરાશી ભટકે છે. સંતનો, હરિજનનો કે અમારો અભાવ કોઈ સંત-હરિજન રતીભાર પણ લે તો તે દિવસે દિવસે ક્ષયના રોગીની પેઠે ઘટતો જાય છે.”","e":null,"s":["13/61/17-23"],"sv":[],"mt":false,"gl":null,"a":false},{"i":354,"k":"para","g":"જેતલપુરમાં શ્રીહરિએ વાત કરતાં કહ્યું, “અમારો સાધુ જો નારી સન્મુખ જુએ તો તેને અમે લબાડ માનીએ છીએ. અમારા સાધુ થઈ જે સ્ત્રીઓ સન્મુખ બેસે ને કોઈ પણ રીતે સ્ત્રીઓનો પ્રસંગ રાખે તેની મતિ વિપરીત થઈ જાણવી. અમારા વચનનું ઉલ્લંઘન કરી વર્તે તેની મહોબત અમે રાખતા નથી. સંત, વર્ણી કે પરમહંસ, પછી જે પણ નિયમ ભંગ કરે તેને સત્સંગથી બહાર કરીએ છીએ. ભલે ગમે તેવો તે ગુણવાન હોય તોપણ આ રીત રાખી છે, કારણ કે જીવ ગયા પછી કાયા શી કામની? એવાની લેશ પણ મહોબત રાખતા નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":355,"k":"para","g":"“બાઈ-ભાઈ સર્વ હરિભક્તોના નિયમોની પણ રીત બાંધી છે. એ તજીને પોતાની રીતે ચાલે તે ગુનેગાર છે. સ્ત્રીઓનો સત્સંગ તો વિવેક વિનાનો જ હોય છે. માન દઈ બોલાવે તેને તે આધીન થાય છે, અપમાન કરે તેને કલંક લગાડે છે. સીતા જેવી કોઈ સતી સ્ત્રી થઈ નથી તેણે પણ લક્ષ્મણને વણવિચાર્યું કહ્યું, તો બીજી સ્ત્રીઓની તો શી વાત કરવી! તેનાથી દૂર રહે તે જ બચે છે.”","e":null,"s":["14/72/16-25"],"sv":["संत होई हमार, नारी सन्मुख देखे जोउ ।\n\n ताकुं कहत लबार, हरिजन जानत बात सब ॥\n\n हमारे संत होई कर जेहा । नारि के सन्मुख बैठे तेहा ॥\n\n नारि को रखे प्रसंग कोउ रीता । मति ताकि जानना विपरीता ॥\n\n हमारे वचनरूप कोट जेता । उल्लंघन ताको करे तेता ॥\n\n द्वार विन चले कोटकुं तोरि । ताकि महोबत न रखत थोरि ॥\n\n संत वर्णि संन्यासि जेहु । पदाति तोरि रितकुं तेहु ॥\n\n ताकुं करत सत्संग ब्हारा । ऐसि कि म्होबत न रखत लगारा ॥\n\n गमे तेसे होय गुनवाना । जीय गये पिछे काय रहाना ॥\n\n हरिजन सबकि रीत हें जैसे । तपास करिके चलत तैसे ॥\n\n चलने कि रीत हि चलत जोउं । द्वार सडक यह कहत सोऊ ॥\n\n द्वार सडक विन चले जीतनां । गुनेगार हि होवे तितनां ॥\n\n बायुं के सत्संग हि जेतो । विवेक विन हि रहे सब तेतो ॥\n\n मान देई बोलावे जाहि । तरत ताके आधिन हो जाहि ॥\n\n अपमान करे नारि को जेऊ । कलंक दिये विन रहे न तेऊ ॥\n\n सिता सम नहि कोउ नारि । लछ्मन सें बोले विन विचारि ॥\n\n ओर नारि मात्र कि जोउ, कहाँ रहे अब बात ।\n\n दूर रहे जब तिनसें जेहु, बचे में तेहि आत ॥"],"mt":false,"gl":null,"a":false},{"i":356,"k":"para","g":"હળવદમાં નારાયણજી વિપ્રના ભવનમાં શ્રીહરિ કહે, “નિયમ વિનાની વાત લખ્યા વિનાના કાગળ જેવી છે. નિયમ વિના જ્ઞાન-ભક્તિ વગેરે શુભ ગુણો ટકતા નથી.”","e":null,"s":["15/3/15"],"sv":[],"mt":false,"gl":null,"a":false},{"i":357,"k":"para","g":"શ્રીહરિએ પત્રમાં લખાવ્યું કે, “સત્સંગમાં નિયમરૂપી કોટ અમે બાંધ્યો છે અને કળિને પ્રવેશવાનાં નાનાં-મોટાં દ્વાર અમે બંધ કરાવ્યાં છે. તે કોટમાં જ્યાં સુધી રહે ત્યાં સુધી કળિનું કાંઈ ચાલતું નથી. ચોર લોકો ગાફલને લૂંટે છે. સાવધાન માણસોમાં તે ફાવી શકતા નથી. અમારા નિયમો છે તે ચોકી અને પહેરેદાર છે. તેમાં કળિ ક્યારેય પ્રવેશ કરી શકતો નથી. છતાં સત્સંગમાં અનેક રૂપ ધારી પ્રવેશ કરવા તે ઇચ્છે છે. તેથી અમે નિયમ ફેરવતા રહીએ છીએ, તોપણ કળિનો વિશ્વાસ કરવો નહિ. કર્મયોગી તથા સાંખ્યયોગી સત્સંગી બાઈઓએ પોતાના સગાભાઈ સાથે પણ એકાકી ચાલવું નહિ. એકાંતમાં કળિનો વાસ રહેલો છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":358,"k":"para","g":"“જુગાર, મદ્ય, માંસ તથા કામ-ક્રોધાદિક અધર્મ સર્ગમાં કળિનો નિવાસ છે. પુરુષોએ પણ હરિભક્ત બાઈઓની સામે જોવું નહિ. નેત્ર, સ્પર્શ અને શ્રોત્ર દ્વારા અંતરમાં કળિનો પ્રવેશ થાય છે. કળિનો પ્રવેશ થતાં ન કરવા યોગ્ય બધું જ થાય છે. માટે અતિ પવિત્ર મોક્ષભૂમિ અને કર્મભૂમિ રૂપ ભરતખંડમાં જન્મ પામીને ધર્મ-નિયમમાં સાવધાન રહેવું.”","e":null,"s":["15/78/12-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":359,"k":"para","g":"વડતાલમાં દીપોત્સવે શ્રીહરિ કહે, “અમારાં વચને કરીને જે નિયમ રાખે છે તેવાં મોટાં ભાગ્ય બીજા કોઈનાં નથી.”","e":null,"s":["17/6/37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":360,"k":"para","g":"વડતાલમાં રાયણ નીચે સંતોને શ્રીહરિ કહે, “બંધન અને નિર્બંધ સમર્થનાં વચનમાં છે. સમર્થનાં વચનમાં રહે તેને બંધન થાય નહિ. નાના-મોટા ઈશ્વરના નિયમોને અમે વેદરૂપ માનીએ છીએ. એ મર્યાદા પ્રમાણે વર્તે તેને બંધન થતું નથી.”","e":null,"s":["17/10/35-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":361,"k":"para","g":"મેઉ ગામમાં ભૂખણ ભાવસારના ભવનમાં શ્રીહરિએ પુરજનોને વાત કરતાં કહ્યું, “અમારાં વચનમાં જે વર્તે છે તે બુદ્ધિશાળી છે. અમારો થઈને અમારાં વચનથી જે જન બહાર ચાલે છે તેની ચાહે તેટલી મોટપ હોય પણ તે રહેતી નથી. અમારાં વચનમાં વર્તવું તે સમાન કોઈ મોટાઈ નથી. વચનમાં દુઃખ માને તે ક્યારેય સુખી થતો નથી.”","e":null,"s":["18/65/18-20"],"sv":[],"mt":false,"gl":null,"a":false},{"i":362,"k":"para","g":"લાંઘણોજમાં શ્રીહરિ કહે, “જેમાં નિયમ હોય તે માર્ગ અત્યારે કઠણ લાગે છે પણ તેમાં મોક્ષ રહેલો છે.”","e":null,"s":["18/67/35-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":363,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ કહ્યું, “ભગવાન પ્રસન્ન થાય અને તેમની મરજી હોય તેમ ચાલે તેમાં સહેજે ભગવાનના ગુણ આવે છે. ભગવાનની મરજીમાં ચાલવું તે સર્વ શાસ્ત્રોનો સાર છે. ભગવાનની મરજી ન પાળતો હોય અને બીજી અપાર વાતો કરે તે વૃથા છે. મરજી ન પાળે અને સુવર્ણ, ગજ, વાજિ, વાહન, અન્ન, વસ્ત્ર, વગેરેનું વિપ્રોને અપાર દાન કરે અને ફાવે તેવાં કર્મ કરે તોપણ તેનું ફળ મળતું નથી.”","e":null,"s":["20/15/21-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":364,"k":"para","g":"શ્રીહરિએ ગઢપુરમાં હરિજનોને વાત કરતાં કહ્યું, “કોઈ વાતનો જેને નિયમ ન હોય અને તેના થકી જેણે મોક્ષ માન્યો હોય તેને અમે ગધેડો કહીએ છીએ. ધર્મ રહિત થઈને ભગવાનની મૂર્તિ પૂજે તેને તો બ્રહ્માંડ હણ્યાનું પાપ લાગે છે.” એમ કહી ઉન્મત્તગંગામાં સ્નાન કરી જીવાખાચરને ત્યાં પધાર્યા.","e":null,"s":["22/39/27-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":365,"k":"para","g":"શ્રીહરિએ ગઢપુરમાં હરિજનોને વાત કરતાં કહ્યું, “હરિજન થઈને હરિજનની દુઃખમાં સહાય ન કરે તો ચાહે તેવો સમર્થ હોય તોપણ અસુર થઈ જાય છે. હરિજનને દુઃખમાં સહાય કરે તે દૈવી છે. સાધનમાત્રથી આ વાત અધિક જાણવી. અને બધાથી પર મોટપ આ જ કહી છે, અને સત્સંગનું મૂળ પણ આને જ જાણવું. હરિજનને સહાય ન કરે તે હરિજનનું મૂળ રહેતું નથી. કોટિકલ્પ સુધી ધ્યાન કરે, સમાધિ કરે, જ્ઞાન શીખે પણ હરિજનના દુઃખમાં સહાય ન થાય તો તેનું સઘળું કરેલું વૃથા છે. અમે દેશ-દેશમાં શિખરબદ્ધ મંદિર કરવાનું ધાર્યું છે. ઈશ્વર ઇચ્છા હશે તેમ થશે. શુભ સંકલ્પ કર્યો છે તો ઈશ્વર મદદ કરશે. મંદિર કરીને હરિજનોની સેવા કરવાનો અવકાશ ન મળે તો અમે મૂંઝાઈએ છીએ.” આ સાંભળી સર્વે હરિજન પ્રસન્ન થયા અને શ્રીહરિની કહેલી વાત નિશ્ચય કરીને માની.","e":null,"s":["22/87/17-29"],"sv":[],"mt":false,"gl":null,"a":false},{"i":366,"k":"para","g":"અમદાવાદમાં શ્રીહરિએ વાત કરતાં કહ્યું, “અમારા આશ્રિત જે ત્યાગી, ગૃહી છે તે જ્યાં સુધી ધર્મમાં ચાલે ત્યાં સુધી અમે તેમને અમારા માનીએ છીએ.”","e":null,"s":["22/92/21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":367,"k":"para","g":"સારંગપુરમાં શ્રીહરિએ વાત કરતાં કહ્યું, “ધર્મ વિનાની ભક્તિ તે વિધવાભક્તિ છે. સૂકું વૃક્ષ ફળ આપે તો વિધવા-ભક્તિથી ફળ થાય. હરિભક્તની ભક્તિ ધર્મ સહિત છે. માટે તેમાંથી અક્ષરધામરૂપી ફળ મળે છે.”","e":null,"s":["23/15/19-22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":368,"k":"para","g":"બોટાદમાં માત્રા ધાધલની વાડીએ સંતોને ઉપદેશ આપતાં શ્રીહરિએ કહ્યું, “દશ, વીશ કે ત્રીસ વર્ષથી જે સંત થયા હોય તેમનો તેથી ઓછા વર્ષના સંતોએ નિષ્કપટ ભાવે શિષ્યભાવ રાખવો એ વિવેક કહેવાય. એક એકથી મોટા સંત હોય તેની સેવામાં નાના સંતો મતિ રાખે તેને વિવેકી જાણવા. માર્ગે ચાલે ત્યારે નાનો મોટાની અદબ ન રાખે ને ગાડામાં છકટો થઈને બેસીને જાય ને મોટા સંત ચાલતા આવે તે વિવેક ન કહેવાય. મોટા હોય તે કહ્યા વિના ગાડે ન બેસે તે વિવેક છે. અમારાં વચનમાં જે અધિક સુખ માને તે દેખાઈ આવે છે ને મનમુખીને પણ દેખીએ છીએ.”","e":null,"s":["23/78/30-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":369,"k":"para","g":"સુરતમાં શ્રીહરિએ હરિભક્તો પ્રત્યે વાત કરતાં કહ્યું, “અમારાં વચન વજ્રના કોટ સમાન છે. અમારાં વચનથી અક્ષરધામ જુદું નથી. અમારાં વચનમાં રહે તેને વિઘ્ન આવતાં નથી.”","e":null,"s":["27/82/28-29"],"sv":[],"mt":false,"gl":null,"a":false},{"i":370,"k":"para","g":"સુરતમાં નાના શેઠને શ્રીહરિ કહે, “નિયમરૂપી કોટમાં રહે તેનો જ વિષયથી પરાભવ થાય નહિ. ભગવાનની કથા-વાર્તા, કીર્તન જેને અમૃતરસ જેવાં લાગે અને તેનો સાંભળવામાં જેટલી રુચિ વર્તે તેટલો તેનો વિષયથી પરાભવ ન થાય, અને વિષયની રુચિ પણ ટળી જાય.”","e":null,"s":["27/86/6-8"],"sv":[],"mt":false,"gl":null,"a":false}]},{"n":5,"gu":"પરબ્રહ્મ પુરુષોત્તમનારાયણ","en":"Parabrahman Purushottam Nārāyan","url":"https://www.anirdesh.com/pbp/index.php?page=chp_5","b":[{"i":371,"k":"para","g":"શ્રીહરિ પોતાની માતાને ઉપદેશ દેતા થકા કહે છે,","e":"Shriharí, giving instruction to His mother, says,","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":372,"k":"verse","g":"‘હે માત, મેં અબહિ જો તોઈ, પરમાત્મા કે સ્વરૂપ હિ સોઈ.","e":"‘He māt, main abahi jo toī, Paramātmā ke swarūp hi soī.","s":[],"sv":[],"mt":false,"gl":"[O mother, what I tell you now is the very swarup of Paramatma;]","a":false},{"i":373,"k":"verse","g":"તાકે જ્ઞાન કહત હૈં જોઉ, જથાર્થ જૈસે રહાયે સોઉ.’","e":"Tāke gnān kahat hain jou, jathārth jaise rahāye sou.’","s":[],"sv":[],"mt":false,"gl":"[…the gnan of Him that I speak, just as He truly abides.]","a":false},{"i":374,"k":"para","g":"“હે માતા, હવે હું તમને પરમાત્માના સ્વરૂપનું યથાર્થ જ્ઞાન કહું છું: પરબ્રહ્મ પુરુષોત્તમ માયાના ગુણથી રહિત હોવાથી નિર્ગુણ કહેવાય છે, પ્રકૃતિના જે ગુણો છે તે તેમનામાં લેશ પણ નથી. શ્રીહરિ અક્ષરધામના અધિપતિ છે. મહાસમર્થ અવિનાશી છે. અલૌકિક દિવ્યમૂર્તિ છે. અક્ષર આદિના આત્મા છે. અક્ષરથી પર એવું મહાસ્વરૂપ છે. સર્વ જીવોના અંતર્યામી અને સર્વોપરી છે. એમનાં ચરિત્ર અને ગુણ અપાર છે.”","e":"“O mother, now I tell you the true gnan of the swarup of Paramatma: Parabrahman Purushottam is called nirgun because He is free of the gunas of maya; the gunas that belong to Prakruti are not in Him in the least. Shriharí is the sovereign of Akshardham. He is supremely powerful and imperishable. He is a transcendental, divine murti. He is the atma of Akshar and of all else. He is that great swarup which is beyond Akshar. He is the Antaryami of all jivas, and the highest of all. His charitras and His virtues are boundless.”","s":["1/58/31-32"],"sv":["ऐसे अक्षरधाम निवासी । महा समर्थ रहेउ अविनाशी ॥\n\n अलौकिक महास्वरूप रहाये । अक्षरादि के आत्मा कहाये ॥\n\n अक्षर तिनसें परहि रहाना । सब जीय अंतरजामी कहावा ॥\n\n सर्वोपरी श्रीहरि नाम जाही । चरित्र गुन अपार हैं ताही ॥"],"mt":false,"gl":null,"a":false},{"i":375,"k":"para","g":"શ્રીહરિ માતાને કહે, “હે માતા, પરમાત્મા શ્રીહરિ સૌના નિયંતા છે, બીજા સૌ એ પરમાત્માને આધીન છે - આવું જ્ઞાન સત્પુરુષનો પ્રસંગ કરવાથી પ્રાપ્ત થાય છે. એ પામ્યા પછી જાણવાનું કાંઈ બાકી રહેતું નથી. જે સત્પુરુષનો પ્રસંગ કરે છે તેનાં સંસારનાં બંધન તૂટે છે અને ભગવાનના ધામને તત્કાળ પામે છે.”","e":"Shriharí said to His mother, “O mother, Paramatma Shriharí is the controller of all, and all others are subject to that Paramatma — such gnan is obtained by keeping the company of the Satpurush. After attaining it nothing remains to be known. The worldly bondage of one who keeps the company of the Satpurush is severed, and he attains the abode of Bhagwan at once.”","s":["1/60/40-42"],"sv":[],"mt":false,"gl":null,"a":false},{"i":376,"k":"para","g":"ગઢપુરમાં ઉન્મત્તગંગામાં સ્નાન કરી શ્રીહરિ જીવેન્દ્ર નૃપના દરબારમાં આવી બિરાજ્યા ને સૌને પરાત્પર અક્ષરધામની વાર્તા કરવા લાગ્યા:","e":"At Gadhpur, having bathed in the Unmattaganga, Shriharí came and was seated in the court of King Jivendra, and began to speak to all of the Akshardham that is beyond the beyond:","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":377,"k":"verse","g":"‘અક્ષરધામ કહાવત જોઉ, તિનસે આપહિ આયે સોઉ;","e":"‘Akshardham kahāvat jou, tinse āpahi āye sou;","s":[],"sv":[],"mt":false,"gl":"[That which is called Akshardham — from there He Himself has come;]","a":false},{"i":378,"k":"verse","g":"જિન કારન લીને અવતારા, સો સબ કહત કરિ વિસ્તારા.’","e":"Jin kāran līne avatārā, so sab kahat kari vistārā.’","s":[],"sv":[],"mt":false,"gl":"[…and the reason for which the avatars were taken, all of that He now tells at length.]","a":false},{"i":379,"k":"para","g":"“માયાપાર જે અક્ષરધામ કહેવાય છે, ત્યાંથી અમે સ્વયં અહીં પ્રગટ થયા છીએ. સાથે અક્ષરધામ ને મુક્તોને લાવ્યા છીએ. એ સિવાય ત્રિલોક, વૈકુંઠાદિ ધામના વાસીઓ પણ આવ્યા છે. રાધા, લક્ષ્મી ને તેનો સેવકવર્ગ પણ આવ્યો છે. કેટલાક શ્વેતદ્વીપ ને બદરિકાશ્રમના મુક્તોએ પણ દેહ ધર્યા છે.”","e":"“That which is called Akshardham, beyond maya — from there We Ourself have become manifest here. We have brought Akshardham and the muktas along with Us. Besides them, the dwellers of the three realms and of Vaikunth and the other abodes have also come. Radha, Lakshmi and their retinue of servants have come as well. Some muktas of Shvetdwip and Badrikashram have also taken bodies.”","s":["4/11/1-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":380,"k":"para","g":"મોડા ગામે રણમલજીના ભવનમાં શ્રીહરિએ નિવાસ કર્યો. અરુણોદય પછી સંતોને ઉદ્દેશીને શ્રીહરિ કહેવા લાગ્યા, “એક એક ગુણ સાધુનો શીખવો. ગુણ શીખવા એ સંતની રીત છે. અમને તમે જે જે આવીને મળ્યા છો તે સર્વને બ્રહ્મરૂપ કરવા છે, માટે ખબરદાર થઈને રહેજો, નહીં તો પગ ટકશે નહીં. અમે જે દિવસથી સત્સંગમાં આવ્યા છીએ, તે દિવસથી અમારા સ્વરૂપના નિશ્ચયની દૃઢતા કરાવીએ છીએ હૃદયમાં અમારા સ્વરૂપની દૃઢતા પ્રથમ પાકી થઈ જાય પછી તેને પોતાનું સ્વરૂપ સહેજે ઓળખાય છે, ને તે પરમ પ્રકાશ અનુભવે છે. સૂર્ય વિના અંધારું ટળે નહિ, તેમ મારા સ્વરૂપની દૃઢતા વિના જ્ઞાન થતું નથી.”","e":"In the village of Moda, Shriharí took up residence in the mansion of Ranmalji. After daybreak, addressing the sadhus, Shriharí began to say, “Learn the virtues of a sadhu one by one. To learn virtues is the way of the Sant. All of you who have come and met Us — We wish to make you all brahmarup; so remain vigilant, otherwise your footing will not hold. From the day We came into satsang, We have been making firm the nishchay of Our swarup. Once the firmness of Our swarup has first ripened in the heart, then a person recognises his own swarup easily, and experiences that supreme light. Just as darkness does not go without the sun, so gnan does not arise without firmness in My swarup.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":381,"k":"verse","g":"‘મેરે સ્વરૂપ કી દૃઢતા, પ્રથમ હોવે ઉર જાસ;","e":"‘Mere swarūp kī drudhtā, pratham hove ur jās;","s":[],"sv":[],"mt":false,"gl":"[In whose heart the firmness of My swarup first arises,]","a":false},{"i":382,"k":"verse","g":"તેહિ કર નિજ સ્વરૂપ કો, હોવહિ પરમ પ્રકાશ.","e":"Tehi kar nij swarūp ko, hovahi param prakāsh.","s":[],"sv":[],"mt":false,"gl":"[…by that, the supreme light of his own swarup comes to be.]","a":false},{"i":383,"k":"verse","g":"સૂર્ય ઉદે બિન, તમ ન ટરે કબુ નેંનઉં સેં;","e":"Sūrya ude bin, tam na tare kabu nainaun sen;","s":[],"sv":[],"mt":false,"gl":"[Without the sun rising, darkness never departs from the eyes;]","a":false},{"i":384,"k":"verse","g":"સર્મ કરે કોટિ દિન, મમ જ્ઞાન બિન ન જ્ઞાન હોત.’","e":"Sarm kare koti din, mam gnān bin na gnān hot.’","s":["5/16/25-27"],"sv":[],"mt":false,"gl":"[…though one labour ten million days, without gnan of Me there is no gnan.]","a":false},{"i":385,"k":"para","g":"વડતાલમાં જોબનપગી તેમજ નારણગિરિ વગેરે ભક્તો સન્મુખ શ્રીહરિએ પોતાના સ્વરૂપની અદ્‌ભુત વાત કરતાં કહ્યું, “અહીં જન્મ પામનાર પંખીઓ, પૂર્વે ઋષિઓ હતા. તે મુક્તિ માટે આવ્યા છે.”","e":"At Vartal, before Jobanpagi, Narangiri and other devotees, Shriharí spoke a wondrous matter concerning His own swarup, saying, “The birds that take birth here were rishis in a former time. They have come for the sake of mukti.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":386,"k":"para","g":"હરિજનો કહે, “અમે તો કોઈને ઓળખતા નથી. તમારી ગત ન્યારી છે, તે તમે જાણો.”","e":"The harijans said, “We recognise no one. Your ways are beyond us — You alone know them.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":387,"k":"para","g":"ત્યારે શ્રીહરિ કહેવા લાગ્યા, “અમારું સર્વોપરી અક્ષરધામ અહીં ભેગું જ રહ્યું છે. પણ, કોઈના દેખ્યામાં આવતું નથી. મુક્તો પણ અપાર છે, પરંતુ અમારી ઇચ્છાથી કોઈને પોતાના આશ્ચર્યનું તાન નથી, બધા મનુષ્યભાવે વર્તે છે.”","e":"Then Shriharí began to say, “Our highest Akshardham is present here along with Us. But it does not come into anyone’s sight. The muktas too are boundless; yet by Our wish no one has any zeal for their own wonder — all conduct themselves in a human manner.”","s":["5/62/4-10"],"sv":["हम मनुष्य न जानत केहा । तुमारि गत तुम जानो तेहा ॥\n\n तब श्रीहरि बोलत भयेउ । इहां धाम सर्वोपरि रहेउ ॥\n\n अब हरि इच्छा कर ताई । देखे में न आत रहाई ॥\n\n इतने में हैं मुक्त अपारा । ताकी नहि है वार हि पारा ॥\n\n आप आपको ज्ञान न केहू । मनुष्यभाव होई वर्तत तेहू ॥\n\n सो तुमको सब होवहि ज्ञाना । तब तुमारे आवहि जाना ॥"],"mt":false,"gl":null,"a":false},{"i":388,"k":"para","g":"મેથાણમાં શ્રીહરિએ સભામાં વાત કરતાં કહ્યું, “અમે અમારા આશ્રિત ભક્તોને અક્ષરધામનું અલૌકિક સુખ આપવાનો સંકલ્પ કર્યો છે. એટલા માટે અમે સત્સંગમાં વિચરણ કરીએ છીએ. અમને બીજો કોઈ સ્વાર્થ નથી, અમારી કોઈ ક્રિયા અમારા સ્વાર્થ માટે નથી. ખાતાં, પીતાં, ઓઢતાં, પહેરતાં બધી ક્રિયામાં અમે અમારા સ્વરૂપનો વિચાર ભૂલતા નથી. સ્વરૂપ વિના બીજું ચિંતવન કરતા નથી. અમારા સ્વરૂપથી અધિક કોઈને જોતા નથી. વિચારરૂપી ખડગે કરીને માયાનાં બધાં આવરણો અમે છેદી નાખીએ છીએ. જીવના મોક્ષ માટે વિચરીએ છીએ.","e":"At Methan, while talking in the assembly, Shriharí said, “We have resolved to give Our ashrit devotees the transcendental happiness of Akshardham. It is for that reason that We travel about in satsang. We have no other interest of Our own; not one of Our actions is for Our own interest. In eating, drinking, covering and clothing — in every action — We do not forget the thought of Our swarup. We contemplate nothing other than the swarup. We see no one as greater than Our swarup. With the sword of contemplation We cut away every veil of maya. We travel about for the moksha of the jivas.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":389,"k":"para","g":"“બ્રહ્માંડના જેટલા પદાર્થ છે તેમાંથી કોઈ અમને આવરણ કરવા સમર્થ નથી. અમે અમારા સ્વરૂપના સુખે સુખિયા છીએ. બીજાં સુખમાત્રને દુઃખદાયી જાણ્યાં છે. જ્યાં લગી કાળનો ભય છે, ત્યાં લગી દુઃખ છાયું છે, એક ભગવાનનું શરણ અભયપ્રદ છે. આજ જે જે સત્સંગી થયા છે તે સર્વે અભયપદ પામી ગયા. અમારા સ્વરૂપની જેને સમજ નથી, તેને સુખની કોઈ ગમ જ નથી.","e":"“Of all the things that are in the brahmand, not one is able to veil Us. We are happy with the happiness of Our own swarup. We have known every other happiness to be a giver of misery. So long as there is fear of Kal, so long is misery spread over all; the refuge of Bhagwan alone bestows fearlessness. All who have become satsangis today have attained that fearless state. One who has no understanding of Our swarup has no notion whatever of happiness.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":390,"k":"para","g":"“રાજાએ જાતિથી હીન ભિખારણને રાણી કરી, પણ તેનો સ્વભાવ ભિખારણનો જ રહ્યો. તેમ સમજણ વિનાના હરિભક્તોને પણ એવા જ જાણવા.”","e":"“A king made a beggar-woman of low birth his queen, but her nature remained that of a beggar-woman. Know haribhaktas without understanding to be just the same.”","s":["6/26/24-42"],"sv":[],"mt":false,"gl":null,"a":false},{"i":391,"k":"para","g":"ગઢપુરમાં જીવેન્દ્રના ભવનમાં શ્રીહરિ વિરાજતા હતા ત્યારે જીવેન્દ્રએ પ્રાર્થના કરી કે, “પ્રભુ! હવે ક્યારેય ઉદાસ થશો નહીં, અને અહીંયા નિવાસ કરીને રહો.”","e":"Shriharí was seated in the residence of Jivendra at Gadhpur when Jivendra made a prayer: “Lord! Never again become despondent, and take up Your dwelling here.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":392,"k":"para","g":"શ્રીહરિ કહે, “અમને રાખવા કઠણ છે. અમે જેને પોતાના માન્યા છે, તેને વારંવાર વઢીને કહેવું એવો અમારો સ્વભાવ છે. અમે વઢીએ તોપણ અમારા સિવાય જીવનો ઠરાવ બધો ઉડાડી દે એવો હોય તેના ઉપર અમને હેત ઊપજે છે. જીવની દોટ સંસાર તરફ છે, અમારી દોટ ભગવાન તરફ છે. અમે સંસારને સ્વપ્ન જેવો અસત્ય જાણીએ છીએ. ચક્રવર્તી ભૂપ પણ નાશ પામે છે. એવું નાશવંત બધા લોકનું સુખ છે. બ્રહ્માંડનો પ્રલય વિચારે ત્યારે મોહમાત્ર ટળે, અને અમારામાં પ્રીતિ થાય. વર્તન અને સમજણમાં ભગવાનનું ધામ રહેલું છે. આ બે વાનાં ન હોય તેને ભગવાનના ધામનું સુખ મળતું નથી. આ દેહ વિકારવાન છે, અસત્ય છે, આત્મા અને પરમાત્મા સત્ય છે, અમારું ધામ સર્વોપરી છે. આ વાત જે સંત-હરિજન યથાર્થ જાણે તે બુદ્ધિવાન છે. તેનો દેહ પડે છે ત્યારે વિમાનમાં બેસીને તેનો આત્મા હરિના ધામને પામે છે.”","e":"Shriharí said, “We are hard to keep. It is Our nature to scold again and again those whom We have counted as Our own. Even though We scold him, Our affection arises for the one whose settled reliance on anything other than Us is entirely blown away. The jiva’s running is towards worldly life; Our running is towards Bhagwan. We know worldly life to be as unreal as a dream. Even an emperor of the whole earth perishes. Such is the perishable happiness of every realm. When a person contemplates the dissolution of the brahmand, then all delusion goes and love for Us arises. The abode of Bhagwan resides in one’s conduct and in one’s understanding. One who lacks these two does not obtain the happiness of the abode of Bhagwan. This body is subject to change and is unreal; the atma and Paramatma are real; Our abode is the highest of all. The sadhu or harijan who truly knows this matter is possessed of intelligence. When his body falls, his atma is seated in a vimana and attains the abode of Hari.”","s":["7/4/11-19"],"sv":[],"mt":false,"gl":null,"a":false},{"i":393,"k":"para","g":"જેતલપુરના મહોલમાં શ્રીહરિ વિરાજતા હતા. સંધ્યાવેળા થઈ. મશાલનો પ્રકાશ થયો. મોટી સભા ભરાઈને બેઠી. આરતી-નારાયણ ધૂન થયાં. પરોક્ષ અવતારોનાં નામ લઈ, તે તે અવતારે કરેલી ભક્તોની રક્ષા ને દિવ્ય ચરિત્રોનો ઉલ્લેખ કરી શ્રીહરિએ કહ્યું, “જેને જે અવતારનો યોગ થયો તેણે તે અવતારને સર્વથી મોટા ગણ્યા, પતિવ્રતા ભક્તિવાળાની આ રીત છે. અવતારોના પણ અનંત ભેદ છે તે જોઈને તેનું સાચું પારખું થાય, પરંતુ તેને પરખનાર પણ બહુ ઓછા છે. જેમ હીરાથી હીરો વેંધાય, તેમ જ્યારે સ્વયં શ્રીહરિ પ્રગટ થઈને પોતાનું સ્વરૂપ ઓળખાવે છે ત્યારે તે વાત માન્યામાં આવે છે. બીજો કોઈ શ્રીહરિના સ્વરૂપનું જ્ઞાન કરાવવા જાય તેમાં પોતાની સમજનો ગુણ મૂકે, પણ યથાર્થ નિરૂપણ કરી ન શકે. જે દર્પણ તુલ્ય, જેમ છે તેમ વાત કરે તે તેના વર્તનમાં દેખાઈ આવે. શ્રીહરિનો પ્રગટપણે સર્વોપરી નિશ્ચય જેને થયો તે જેવો શ્રીહરિનો મહિમા જાણે ને સર્વોપરી માને એના જેવું માહાત્મ્ય બીજો કોઈ જાણી ન શકે ને કહેવા જાય તોપણ તેમાં ન્યૂનતા જરૂર રહે. અરે, પાતાળ લોકથી પ્રકૃતિપુરુષ ને અક્ષરબ્રહ્મ પર્યંત બધાને ન્યૂન કહી દેખાડે.","e":"Shriharí was seated in the mansion at Jetalpur. Evening came. The torches were lit. A great assembly gathered and sat. The arti and the Narayan dhun were performed. Naming the avatars of the past and recounting the protection each of those avatars gave to devotees and their divine charitras, Shriharí said, “Whoever came into contact with a given avatar counted that avatar as the greatest of all — this is the way of one whose bhakti is like that of a devoted wife. There are infinite gradations among the avatars as well, and by seeing them a true discernment of them arises; but those who can discern them are very few. Just as a diamond is cut by a diamond, so when Shriharí Himself becomes manifest and makes His own swarup known, then that matter comes to be accepted. If anyone else goes to impart gnan of the swarup of Shriharí, he adds the flavour of his own understanding, and cannot expound it truly. One who speaks it as it is, like a mirror, will show it in his own conduct. One who has attained the nishchay that Shriharí manifest is the highest of all knows the mahima of Shriharí and holds Him supreme as no one else can know it — and if another attempts to speak of it, a deficiency will certainly remain in it. Why, he will show everything from Patal up to Prakruti-Purush and Aksharbrahman to be lesser.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":394,"k":"para","g":"“જ્યારે શ્રીહરિ પોતાના સ્વરૂપની વાત કરે તેમાં કસર રહેવા ન દે. કારણ, પોતે સર્વ અવતારના કારણ છે. દેખાદેખીથી કોઈ બીજા અવતારને આ પ્રમાણે (સર્વનું કારણ) કહેવા જાય તો તે અવતારનો ચોર ઠરે છે, કારણ કે પોતાનો મોક્ષ પ્રગટ વિચરતા શ્રીહરિના હાથમાં છે. પ્રગટ વગર કદી મોક્ષ થતો નથી. આગળ પણ અનેક અવતારો થયા તેમાં જેને જે મળ્યા ને ઓળખ્યા તેની તેવી ગતિ થઈ છે. પ્રગટની ઉપાસના ને કીર્તન સૌએ કર્યાં છે. પ્રગટનાં ચરિત્રો ગાયાં છે.","e":"“When Shriharí speaks of His own swarup, He leaves no deficiency in it — because He Himself is the cause of all the avatars. If anyone, merely following what he has seen, goes and speaks of some other avatar in this manner (as the cause of all), he is proved a thief of that avatar; for his own moksha lies in the hands of the manifest Shriharí who is moving about here. Without the manifest form, moksha never comes about. In the past too many avatars occurred, and whoever met and recognised one of them attained the corresponding state. All have performed the upasana and the kirtan of the manifest form. They have sung the charitras of the manifest form.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":395,"k":"para","g":"“જેને જે અવતાર મળ્યો તેણે તેનાં જ ચરિત્ર ગાયાં છે. એમ વિવેકી ભક્તે પ્રગટમાં તાન રાખવું જોઈએ. ભગવાનના અવતારની જેને ઉપાસના નથી તેને અવતારની વાત કરવી, જેથી તેને પ્રગટ ઉપર પણ ભાવ આવે. બીજાનું આપણે સાચું કહીએ તો આપણું સાચું માને અને અસત્ય કહીએ તો આપણને તે પણ અસત્ય કહે. બીજાને પૂજ્ય કરીને માને તો પોતે પણ પૂજાય. ભગવાનના અવતારોનું ખંડન કરે તે પાકો અસુર છે. જે અવતારે જેટલો પ્રતાપ દેખાડ્યો તે લખાયો છે. પ્રગટનાં ચરિત્રોનું ગાન-શ્રવણ કરવું તેમાં મોક્ષ નિશ્ચિત છે. પૂર્વે થયેલા અવતારોના ભક્તોએ પણ આ તાન રાખ્યું હતું. એમ સુબુદ્ધિ જને પોતાના ઘર પર (પ્રગટ મળ્યા છે તે પર) તાન રાખવું. જો એવું તાન ન રાખે, તો ત્રિશંકુ જેવી દશા થાય.”","e":"“Whoever obtained a given avatar sang the charitras of that one alone. So a devotee with vivek must keep his zeal upon the manifest form. To one who has no upasana of an avatar of Bhagwan, one should speak of that avatar, so that devotion may arise in him for the manifest form as well. If we speak truly of another’s, then ours too is accepted as true; and if we speak falsely, then he will call ours false as well. If one holds another as worthy of worship, then he too is worshipped. One who refutes the avatars of Bhagwan is a thorough demon. Whatever majesty each avatar displayed has been written down. In singing and hearing the charitras of the manifest form, moksha is assured. The devotees of the avatars of former times kept this same zeal. So a person of good understanding should keep his zeal upon his own house — upon the manifest form he has obtained. If he does not keep such zeal, his condition becomes like that of Trishanku.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":396,"k":"para","g":"એ પ્રમાણે શ્રીહરિને વાત કરી જે સાંભળી સંત-હરિજન સૌ પ્રસન્ન થયા, સુબુદ્ધિ ભક્તોમાં કંઈક સમજણની કસર હતી તે આ વાત સાંભળી ટળી ગઈ.","e":"Shriharí having spoken in this manner, all the sadhus and harijans who heard it were pleased; and whatever deficiency of understanding remained in the devotees of good understanding was removed on hearing this.","s":["8/13/1-40"],"sv":["जाकुं मिले अवतार, ताकुं हे सो सर्व पर ।\n\n तेसे हें निरधार, पतिव्रत भक्त को पक्ष तेहि ॥\n\n देखे सुने में भेद अनंता । एक हि एक बात रहंता ॥\n\n देखि पारखना साचे सोउ । पारख बिन परखात न सोउ ॥\n\n पारख कुं परखना जेहा । थोरे मनुष्य हें एसे तेहा ॥\n\n हिरा से हिरा जात विंधाई । ता बिन कोटि चले न पाई ॥\n\n श्रीहरि होवत प्रगट जबहि । आप दिये ज्ञान मनात तबहि ।\n\n और जन देवे ज्ञान हि जेहु । आप गुन तामें लावे तेहु ॥\n\n दरपन सम कहे जो बाता । वर्तन में आव देखाये ताता ॥\n\n हरि महिमा आप जाने जैसे । सर्वोपरि सो माने तैसे ॥\n\n और जाने न हरि महिमा जेता । तामें कसर देखावत तेता ॥\n\n पाताल से अक्षर प्रजंता । सबमें कसर देखावे रहंता ॥\n\n हरिमुख बात सो शोभे तेहि । सब अवतार कारन हें एहि ॥\n\n देखादेखी बोले युं जाहि । अवतार के चोर होत ताहि ॥\n\n अपनो मोक्ष हे ताके हाथा । प्रगट भोमि पर विचरत नाथा ॥\n\n प्रगट विन नहि मोक्ष तत्काला । बात करना जिमि लणे रसाला ॥\n\n अवतार आगे अवतारा । हो गए कछु वार न पारा ॥\n\n प्रगट कुं जन माने जबे, तब तेहि प्रसन्न होत ।\n\n एसे कहेना विवेक तेहि, विवेक बिन बात बिगोत ॥\n\n उपासना जाकुं नेह, भगवान के अवतार हु की ।\n\n प्रतिपादन करना तेह, प्रगट पर भाव सी करे तबे ॥\n\n ओर कुं रखिये सत, आपकुं माने सब तबे ।\n\n जो कहिये असत, तब सो कहे असत कर ॥\n\n अपनी बानी आपे पुजावे । पूज्य करि जो ओर कुं गावे ॥\n\n हरि अवतार चरित्र हि ताके । खंडन करे असुर हें पाके ॥\n\n जाकुं मिले प्रगट अवतारा । एसे भक्त भये अनंत अपारा ॥\n\n ताकि रीत जोई के चलना । ता उपरि पाव न धरना ॥\n\n मुख से चरित्र को करे गाना । ता उपर रीझत भगवाना ॥\n\n प्रगट सो करना गान हि जोउ । सत्य सो मोक्षदाई हे सोउ ॥\n\n सब अवतार के भक्त हें जेहु । ताको एसो तान हे तेहु ॥\n\n आप आपके घर को सबहु । जनमात्र तान रखत हें अबहु ॥\n\n सुबुद्धि जन सो जानना, घर पर रखे जो तान ।\n\n निज घर पर नहि तान जेहि, अंत्ये सो होत हेरान ॥\n\n त्रिशंकु गुरु कुं छोरि के, और गुरु किये जोय ।\n\n अधर लटकत हें अबहि, सब जग जानत सोय ॥"],"mt":false,"gl":null,"a":false},{"i":397,"k":"para","g":"ઝીંઝરમાં શ્રીહરિએ વાત કરતાં કહ્યું, “સર્વથી પર એવો હું આ સત્સંગમાં નિવાસ કરીને રહ્યો છું. મારા ઉત્તમ ભક્ત સેવક (અક્ષરબ્રહ્મ) છે તે મારા સ્વરૂપને યથાર્થ જાણીને મારું ચિંતવન કરે છે.","e":"At Zinzar, while talking, Shriharí said, “I, who am beyond all, have taken up My dwelling in this satsang. My highest devotee and servant — Aksharbrahman — knowing My swarup truly, contemplates upon Me.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":398,"k":"para","g":"“હું જે જે વાર્તા કરું છું તેમાં પણ મારે એ જ તાન રહે છે કે મારી મૂર્તિ સિવાય અન્ય પદાર્થમાત્ર સર્વ સત્સંગીને ટળી જાય, મૂર્તિ જેવી પ્રીતિ કોઈમાં થાય નહિ. જેનું ચિત્ત મારી મૂર્તિ સિવાય બીજું કોઈ ચિંતવન કરે નહીં તેવા ભક્ત પર મને પ્રીતિ થાય છે. તે વિના તો અક્ષરધામ સુધી બીજે ક્યાંય અમારે પ્રીતિ નથી.”","e":"“In every matter of which I speak, this same zeal of Mine remains: that apart from My murti every other thing should fall away for all satsangis, and that love like that for the murti should arise for nothing else. My love arises for that devotee whose mind contemplates nothing other than My murti. Apart from such a one, We have no love for anything anywhere, up to Akshardham itself.”","s":["9/27/25-27"],"sv":["सबसे पर सत्संग में, मैं रहूँ करि निवास ।\n\n जथार्थ मम स्वरूप को, चितवन करत मम दास ॥\n\n जो जो करत मैं वारता, मेरी हें यह तान ।\n\n मूर्ति सम रहे न कोउ कबु, पदार्थमात्र हि आन ॥\n\n मूर्ति विन नहि चित, चिंतवन करत न जाहि को ।\n\n ता पर हे मोय प्रीत, ओर प्रीत नहि अक्षरलग ॥"],"mt":false,"gl":null,"a":false},{"i":399,"k":"para","g":"સારંગપુરમાં શ્રીહરિએ હરિજનોને વાત કરતાં કહ્યું, “જે ભગવાનની મૂર્તિમાં સુખ નહિ માનીને બીજે સુખ માનનારા છે તે અમને કંચનના મહોલ, ઉત્તમ પ્રકારનાં ખાન-પાન તથા અમૂલ્ય વસ્ત્ર, હાથી, ઘોડા વગેરે આપવા માંડ્યા, પણ અમે ત્યાં પળમાત્ર ટક્યા નહિ. જે અમારી સિવાય બીજું કંઈ ન ઇચ્છે તેની પાસે તો અમે સદાય રહીએ છીએ. તેને માટે તો અમે દેહ ધર્યો છે. વિના રાખે પણ તેની પાસે અમે રહીએ છીએ.”","e":"At Sarangpur, while talking with the harijans, Shriharí said, “Those who do not find happiness in the murti of Bhagwan but find it elsewhere began to offer Us palaces of gold, food and drink of the finest kind, priceless garments, elephants, horses and the rest — but We did not remain there for a moment. With one who desires nothing apart from Us, We abide always. It is for such a one that We have taken a body. Even without being kept, We remain beside him.”","s":["9/32/21-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":400,"k":"para","g":"શ્રીહરિ આધોઈ, ધમડકા થઈ ભચાઉ આવ્યા અને લુહાર હરિભક્તને ઘેર ઊતર્યા. તે ભક્તને તુલસીકૃત રામાયણનો અભ્યાસ હતો. શ્રીહરિ તેમની પાસે વંચાવવા લાગ્યા. ત્યારે તેમને રામચંદ્રરૂપે શ્રીહરિનાં દર્શન થયાં. આ દર્શનથી લુહાર ભક્ત ગદ્‌ગદકંઠ થઈ ગયા. અહોભાવથી નેત્રમાં જળ વહેવા લાગ્યાં. ત્યારે શ્રીહરિએ તેને અક્ષરધામના પોતાના સર્વોપરી પરબ્રહ્મ સ્વરૂપનાં દર્શન કરાવ્યાં. લુહાર ભક્ત અનંત અવતારોને શ્રીહરિની હજૂરી કરતા જોયા, તેના ભક્તોને પણ જોયા. લુહાર ભક્તના આનંદનો પાર ન રહ્યો. વળી, એ બધા અવતારોને શ્રીહરિએ પોતાની મૂર્તિમાં લીન કરી લીધા. આથી તેમણે શ્રીહરિને સર્વ અવતારોના કારણ અવતારી રૂપે જાણ્યા.","e":"Shriharí, passing through Adhoi and Dhamadka, came to Bhachau and stayed at the home of a blacksmith haribhakta. That devotee had made a study of the Ramayan of Tulsidas. Shriharí had him read it aloud in His presence. Thereupon he had darshan of Shriharí in the form of Ramchandra. At this darshan the blacksmith devotee was overcome with emotion; water flowed from his eyes in wonder and reverence. Then Shriharí granted him darshan of His own highest Parabrahman swarup of Akshardham. The blacksmith devotee saw infinite avatars attending upon Shriharí, and saw their devotees as well. There was no limit to the joy of the blacksmith devotee. Moreover, Shriharí drew all those avatars into His own murti. From this he knew Shriharí as the Avatari, the cause of all the avatars.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":401,"k":"para","g":"શ્રીહરિ કહે, “અમે ભગવાન (પુરુષોત્તમ) પ્રગટ થયા છીએ. તે અમે અમારી વાત કરતા નથી, જેને પ્રતાપ દેખ્યામાં આવે છે તે અમારા સ્વરૂપની વાત જેમ છે તેમ કહે છે.”","e":"Shriharí said, “We are Bhagwan — Purushottam — become manifest. We do not speak of Ourself in this way; it is the one to whom Our majesty becomes visible who speaks of Our swarup as it truly is.”","s":["10/29/31-39"],"sv":["भचाउ गाम प्रति हरि आये । तिहां लुवार हरिजन रहाये ॥\n\n ताके भुवन उतरे हरि आई । हरिजन सो अति निर्मल रहाई ॥\n\n रामकथा तुलसीकृत जेहु । हरिजन सो पढे हें तेहु ॥\n\n रामचंद्र के चरित्र हि जेते । हष्टि वंचावने लगेउ तेते ॥\n\n हरि में रामचंद्र को रूपा । देखत भये हरिजन अनूपा ॥\n\n एसो दरश भये जेई वारा । नेत्र से नीर वहन लगे धारा ॥\n\n गद्‌गद कंठ मुन भये बेना । अचेतन भये देह रहे न चेना ॥\n\n तब श्रीहरि रूप लीन कीने । अक्षरधाम में दर्शन दीने ॥\n\n अवतार अनंत तेहि धाम में, हरि के देखे हजुर ।\n\n ताके देखे सब भक्त हि, आनंद भये अति उर ॥\n\n देखाये घडि चार हि, भये श्रीहरि में लीन ।\n\n सब कारन अवतार यह, जानत भये प्रवीन ॥\n\n श्रीहरि कहत न बात, में भगवान जो प्रगट भयेउ ।\n\n प्रताप जाकुं देखात, प्रताप सो कहत रहत ॥"],"mt":false,"gl":null,"a":false},{"i":402,"k":"para","g":"કચ્છ-ભૂજમાં સભાજનોને શ્રીહરિએ વાત કરતાં કહ્યું, “ભગવાનની કર્તૃત્વશક્તિ ભયરૂપે સર્વત્ર દેખ્યામાં આવે છે. સ્થાવર-જંગમ સૃષ્ટિ નિયમમાં રાખી છે. પાતાળથી પ્રકૃતિપુરુષ સુધી કોઈ નિયમ બહાર ડગ ભરી શકે નહિ. અનંતકોટિ બ્રહ્માંડોને આ રીતે નિયમમાં વર્તાવે છે, એવા એ સમર્થ છે. જે જીવને જે પ્રકારના દેહનો કર્મસંબંધ હોય, તેને તેવા દેહ ધરાવે છે. જેને જેવું કર્મ, તેને તેવો આહાર આપે છે. પોતાના કર્તૃત્વમાં ભગવાન પળનોય વિલંબ કર્યા વિના જીવોને કર્મનું ફળ આપે છે. અંતર્યામી છે. શુભ કર્મ કરે તેને શુભ ગતિ આપે છે, અશુભ કર્મ કરે તેને અશુભ ગતિ આપે છે. મનુષ્યને જ્ઞાનરૂપી નેત્ર દીધાં છે, છતાં જે બંધ રાખીને ચાલે છે તે ખુવાર થાય છે.”","e":"At Bhuj in Kutch, while talking with those assembled, Shriharí said, “The creative power of Bhagwan is seen everywhere in the form of awe. He has held the moving and unmoving creation within law. From Patal up to Prakruti-Purush none can take a step outside that law. He makes infinite millions of brahmands abide within law in this manner — so powerful is He. To whatever kind of body a jiva has a karmic connection, He causes it to take such a body. To whoever has such karma, He gives such sustenance. In His creatorship, Bhagwan gives the jivas the fruit of their karma without a moment’s delay. He is the Antaryami. To one who does good deeds He gives a good state; to one who does evil deeds He gives an evil state. He has given human beings the eyes of gnan, and yet one who walks about keeping them shut is ruined.”","s":["12/31/7-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":403,"k":"para","g":"કરિયાણામાં દેહાખાચરના ભવનમાં નાગર સેનાપતિ શ્રીહરિના દર્શને આવ્યો. શ્રીહરિએ ઉપદેશ આપતાં તેને કહ્યું, “પરબ્રહ્મનું ધામ સૌથી પર અક્ષરધામ છે. તે ધામનું સુખ અનંત છે. અન્ય ધામનાં સુખને ભેગાં કરીએ તોપણ અક્ષરના એક રોમમાં રહેલા સુખની આગળ કોઈ ગણતરીમાં આવતાં નથી. શિવ, બ્રહ્મા તો દેવતા છે. એનાં સુખ તો અક્ષરધામનાં સુખ આગળ અતિ તુચ્છ લાગે છે. સાકર આગળ ખારો કેવો લાગે એવું છે! બાળકબુદ્ધિ હોય તે તેમાં લોભાય છે. જેમ આ લોકમાં બાળકને ચિંતામણિ અને બોરમાં કેટલો ભેદ છે તે ખબર ન હોવાથી ચિંતામણિ મૂકીને બોર દેખી લોભાય, તેમ અક્ષરધામના સુખનું જ્ઞાન જેને નથી તે અન્ય ધામના સુખમાં લોભાઈ જાય છે.","e":"At Kariyani, in the residence of Dada Khachar, a Nagar commander came for the darshan of Shriharí. Giving him instruction, Shriharí said, “The abode of Parabrahman is Akshardham, highest of all. The happiness of that abode is infinite. Even were we to gather together the happiness of every other abode, it would not come into any reckoning before the happiness contained in a single hair of Akshar. Shiv and Brahma are but deities. Their happiness seems utterly trifling before the happiness of Akshardham. It is like how salt tastes beside sugar! One of a child’s understanding is lured by it. Just as in this world a child, not knowing how great the difference is between a chintamani and a jujube fruit, sets aside the chintamani and is lured by the sight of the jujube — so one who has no gnan of the happiness of Akshardham is lured by the happiness of other abodes.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":404,"k":"para","g":"“સાચા સંતનો સંગ ન મળે ત્યાં સુધી શ્રીહરિના ધામનો લોભ લાગતો નથી, જેને એવો સંગ મળે છે તે બહુ મોટી પદવીને પામ્યા છે, પરમ અનુપમ ભક્ત થયા છે. જ્યાં સુધી માયાની મોટપ અંતરમાં મનાય છે, ત્યાં સુધી તે બાળકબુદ્ધિ છે. અનંત બ્રહ્માંડનાં સુખ પણ શ્રીહરિના ધામ પાસે તુચ્છ છે. બાળકબુદ્ધિ હોય ત્યાં સુધી તે જીવ ચોરાશીમાં ભટકતો રહે છે. જ્યારે અક્ષરધામના સુખનું પરપણું યથાર્થ મનાય છે, ત્યારે બીજાં ધામનાં સુખ તુચ્છ થઈ જાય છે, અને જીવ ચોરાશીથી ને જમપુરીથી છૂટે છે.”","e":"“Until one obtains the company of a true Sant, no longing for the abode of Shriharí arises. Those who obtain such company have attained a very great station and have become supremely incomparable devotees. So long as the greatness of maya is held within, so long is he of a child’s understanding. Even the happiness of infinite brahmands is trifling beside the abode of Shriharí. So long as a person is of a child’s understanding, that jiva goes on wandering through the eight million four hundred thousand species. When the transcendence of the happiness of Akshardham is truly accepted, then the happiness of other abodes becomes trifling, and the jiva is released from the eight million four hundred thousand and from Yampuri.”","s":["13/30/1-11"],"sv":[],"mt":false,"gl":null,"a":false},{"i":405,"k":"para","g":"શ્રીહરિ ગઢપુર દાદાખાચરના દરબારમાં બિરાજતા હતા ત્યારે જ્ઞાનની વાતોમાં સમજી શકે એવા મોટા સદ્‌ગુરુઓને ગઢપુર તેડાવ્યા. નામ લખી લખી સૌને બોલાવ્યા હતા, તેથી એ મોટેરા સંતો એક એક સેવક સાથે લઈને ગઢડે આવ્યા. ઘેલાની સમીપે જીવેન્દ્રે સંતોને ઊતરવાની જગ્યા બનાવી હતી, ત્યાં સૌ ઊતર્યા. કથા-વાર્તા-કીર્તન-આરતી-ધૂન એમ સાંજ-સવાર સંતો કરતા. શ્રીહરિ દાદાના દરબારમાંથી ત્યાં સંતો પાસે પધારતા અને સ્વ-સ્વરૂપની અદ્‌ભુત વાતો કરતા. અન્ય અવતારો પૃથ્વી પર આવ્યા તેની પણ રહસ્ય વાતો કરતા, જે સાંભળીને સંતોને અદ્‌ભુત આશ્ચર્ય થતું.","e":"When Shriharí was seated in the court of Dada Khachar at Gadhpur, He summoned to Gadhpur the great sadgurus who were able to understand matters of gnan. Each was called by name in writing, and so those senior sadhus came to Gadhada, each bringing one attendant with him. Near the Ghela, Jivendra had made a place for the sadhus to stay, and there they all lodged. Morning and evening the sadhus performed katha, discourses, kirtan, arti and dhun. Shriharí would come to the sadhus there from Dada’s court and speak wondrous matters concerning His own swarup. He would also speak of the secrets of the other avatars who had come upon the earth, hearing which the sadhus were filled with wonder.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":406,"k":"para","g":"શ્રીહરિ કહે, “અવતારમાત્ર કોઈને કોઈ કાર્ય નિમિત્તે પૃથ્વી પર આવે છે, ને જેવું કાર્ય તેવું શરીર ધારે છે, ને સામર્થિ પણ એવી દેખાડે છે. ક્યારેક શરીરને અદૃશ્ય પણ કરી દે છે. ભગવાનમાં એવી કળા રહેલી છે. જગતના જીવ જાણી ન શકે એવા પાસે ભગવાન કામ લે છે. ભગવાન બુદ્ધિવંતોની બુદ્ધિમાં આવતા નથી, ને આજે પણ આવ્યા નથી. અવતારો કેવી રીતે આવે છે ને અદૃશ્ય થાય છે તેની ગમ પડતી નથી. જેમ કાષ્ઠમાં અગ્નિ રહ્યો છે તે અણુ-અણુમાં વ્યાપીને સર્વાંગ રહ્યો છે તોપણ કોઈના કળ્યામાં આવતો નથી, તો આ મનુષ્યતનમાં રહેલા ભગવાન કેમ કળ્યામાં આવે!","e":"Shriharí said, “Every avatar comes upon the earth for the sake of some work or other, and takes such a body as the work requires, and displays such power accordingly. Sometimes He even makes the body invisible. Such skill resides in Bhagwan. Bhagwan takes work from those whom the jivas of the world cannot know. Bhagwan does not come within the reasoning of the intelligent, nor has He come within it today. How the avatars come and how they become invisible is not comprehended. Just as fire resides in wood, pervading every atom and present throughout it, and yet is not perceived by anyone — then how is Bhagwan, residing in this human body, to be perceived!","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":407,"k":"para","g":"“બીજું દૃષ્ટાંત – જેમ આકાશ સ્વચ્છ હોય ને પલકારામાં અનેક વાદળ ચઢી આવે છે. તેના તરેહ તરેહના આકાર અને રંગ હોય છે. ગાજવીજ થાય પણ નીર ન દેખાય એ આશ્ચર્ય છે, જ્યારે વર્ષા થાય ત્યારે બધા જાણે જે આ નીર નહોતું ને ક્યાંથી આવ્યું!","e":"“Another illustration — just as the sky may be clear and in the blink of an eye many clouds come up, of all manner of shapes and colours. There is thunder and lightning, but no water is seen, which is a wonder; and when the rain falls, then all know: this water was not here — from where has it come!","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":408,"k":"para","g":"“સ્થાવર-જંગમના દેહ પણ ક્ષણે ક્ષણે બંધાતા હોવા છતાં તે નજરે દેખાતા નથી, એવી શ્રીહરિની કળા છે. તેમના જેવું સામર્થ્ય ક્યાંય જોવા મળતું નથી. જેમાં જેટલું સામર્થ્ય દેખાય છે તે શ્રીહરિની ઇચ્છાએ કરીને દેખાય છે. પૃથ્વી પર જ્યાં જ્યાં શુભનું પ્રવર્તન થાય છે કે શુભ દેખાય છે તે શ્રીહરિના સંકલ્પનો પ્રભાવ જાણવો. અશુભ જણાય છે તે વિમુખ જીવનું કર્તવ્ય છે.","e":"“Though the bodies of moving and unmoving beings are being formed moment by moment, they are not seen by the eye; such is the skill of Shriharí. Power like His is nowhere to be found. Whatever power is seen in anything is seen by the will of Shriharí. Wherever on earth good is set in motion or good is seen, know it to be the effect of Shriharí’s resolve. What appears as evil is the doing of a jiva turned away from Him.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":409,"k":"para","g":"“ભગવાનના ભક્તની સમજ અનોખી છે, જેવા ભગવાન માયાના ગુણથી રહિત નિર્દોષ છે, તેવા જ તેમના ભક્તો પણ નિર્દોષ છે, માયાથી રહિત છે. આ વાતમાં રતિભર પણ અસત્ય નથી.”","e":"“The understanding of a devotee of Bhagwan is unlike any other: as Bhagwan is free of the gunas of maya and faultless, so too His devotees are faultless and free of maya. In this matter there is not a particle of untruth.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":410,"k":"verse","g":"‘ભગવાન તાકું જો જન જેહા, નિર્દોષ જિતના સમજત તેહા;","e":"‘Bhagvān tākun jo jan jehā, nirdosh jitnā samajat tehā;","s":[],"sv":[],"mt":false,"gl":"[However faultless a person understands Bhagwan and His devotee to be,]","a":false},{"i":411,"k":"verse","g":"નિર્દોષ તિતના હોવત તાહિ, યામેં રતિ નહિ જૂઠ કહાહિ.’","e":"Nirdosh titnā hovat tāhi, yāmen rati nahi jūth kahāhi.’","s":["15/53/6-25"],"sv":[],"mt":false,"gl":"[…that much faultless does he himself become; in this there is not a particle of untruth.]","a":false},{"i":412,"k":"para","g":"ગઢપુરમાં ઉત્તમના દરબારમાં ઉત્તરદ્વારે શ્રીહરિનું ભવન હતું. એ અક્ષરઓરડીમાં શ્રીહરિ બેઠા હતા. મધ્યરાત્રિએ ચંદ્રનો પ્રકાશ થયો. નિત્યાનંદમુનિ તથા મુક્તાનંદમુનિ બે પાસે બેઠા હતા, મુક્તમુનિએ હાથ જોડી કહ્યું, “મનમાં અપાર શાંતિ રહે અને ક્યારેય અશાંતિ થાય નહિ એવો સારમાં સાર ઉપાય હોય તે કહો.”","e":"At Gadhpur, in the court of Uttam, Shriharí’s residence stood at the northern gate. Shriharí was seated in that Akshar Ordi. At midnight the moon shone. Nityanandmuni and Muktanandmuni were seated on either side. Muktamuni, joining his palms, said, “Tell us the essence of all remedies, by which boundless peace may abide in the mind and unrest never arise.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":413,"k":"para","g":"આ સાંભળી શ્રીહરિ મનોમન હસવા લાગ્યા, કે શાંતિના અપાર સિંધુ સમાન હું પ્રાપ્ત થયો તોપણ દૈવની માયાનું જોર તો જુઓ! એમ, શ્રીહરિ અંતરમાં અતિશય ઉદાસ થઈ ગયા ને બોલ્યા:","e":"Hearing this, Shriharí began to laugh within Himself: though I, who am like a boundless ocean of peace, have been obtained — yet see the force of divine maya! And so Shriharí became exceedingly downcast within, and said:","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":414,"k":"para","g":"“શાંતિ કરવા તો અમે સત્સંગમાં ટક્યા છીએ. અમે જે જે વાત કરીએ છીએ તેનું રહસ્ય શાંતિ કરવાનું છે. ધ્યાન, ધારણા, સમાધિ કરાવીએ છીએ. આશ્ચર્ય વાત કોઈ બાકી રાખતા નથી. અમારું ખાવું, પીવું, ચાલવું, સમૈયા કરવા, વસ્ત્ર આભૂષણ ધારવાં, જમાડવું, મળવું, પૂજા કરાવવી - વગેરે અમારી ક્રિયા જે જન અંતરમાં ધારે છે, ચિંતવે છે તેને શાંતિ થાય છે. અમારી બધી ક્રિયા શાંતિ માટે જ છે. અમે તો માનતા કે સત્સંગભરમાં મુક્તમુનિ સમાન કોઈ સમજુ નથી, પણ હવે વિચાર્યું કે સમજુના અંતરમાં પણ આજ સુધી શાંતિ થઈ નહિ તો બીજા જનની તો વાત જ શી!”","e":"“It is to bring about peace that We have remained in satsang. The secret of every matter We speak is the bringing about of peace. We have people perform meditation, contemplation and samadhi. We leave no wonder undone. Our eating, drinking, walking, holding festivals, wearing garments and ornaments, feeding others, meeting people, allowing Ourself to be worshipped — whoever holds these actions of Ours within, and contemplates them, attains peace. Every action of Ours is for peace alone. We used to think that in all of satsang there was none so understanding as Muktamuni; but now We have considered that if peace has not arisen even in the heart of one who understands, then what is to be said of others!”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":415,"k":"para","g":"એમ વિચારમાં શ્રીહરિને હૃદયમાં ચેન ન રહ્યું. મનમાં અતિ ઉદાસ થઈ ગયા ને કહેવા લાગ્યા, “અમારો બધો શ્રમ વ્યર્થ ગયો. કોઈ વખત દયા ન કરી હોય એવી દયા અમે આ વખતે કરી છે. જન્મમરણ, લખચોરાશી ને જમપુરીનાં અપાર દુઃખ બધાનાં ટાળ્યાં છે. અરે, અમે એવું ઐશ્વર્ય મૂક્યું છે કે સંત-હરિભક્તના વચનથી કોઈ સત્સંગ કરે ને તે ગમે તેવો અધમ હોય તોપણ ધામમાં જાય!","e":"Thinking thus, Shriharí found no ease in His heart. He became exceedingly downcast in mind and began to say, “All Our labour has gone in vain. We have shown at this time such compassion as We have never shown before. We have removed for all the boundless miseries of birth and death, of the eight million four hundred thousand species, and of Yampuri. Why, We have established such power that if anyone does satsang on the word of a sadhu or haribhakta, then however base he may be, he still goes to the abode!","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":416,"k":"para","g":"“અનંત અવતારો પૂર્વે થઈ ગયા. તેમના જેવું સામર્થ્ય આજે અમે એક એક સંત દ્વારા દેખાડ્યું છે. આશ્રિત જનોને અંત સમયે સંતના વચનથી દર્શન દઈએ છીએ. વળી, ઊંચ-નીચ ગમે તે જાતિનો હોય, પણ અમારો આશરો કરી હરિજન થાય છે, પછી સત્સંગ કરીને તેનો જીવ અતિ શુદ્ધ થઈ જાય છે. ગમે તેવું મેલું વસ્ત્ર જળે કરીને શુદ્ધ થાય તેમ અતિ મલિનતા જેમાં હોય એવાનાં પાપ પણ સત્સંગના યોગે કરીને અમારા વચનથી નાશ પામી જાય છે. અમારી મોટાઈ અમારા મુખે કહેવી યોગ્ય નથી, છતાં કહીએ નહિ ત્યાં સુધી જનોને શાંતિ થતી નથી, આજે જે જનને સત્સંગ થયો છે તેને અમે ઈશ્વર તુલ્ય જાણીએ છીએ. કારણ, પૃથ્વી પરના ગ્રંથમાત્રનું રહસ્ય તેણે અમારા વચનમાં માન્યું છે! અમારું વચન અને બધા ગ્રંથો - તે બન્નેને એકતા છે એમ તે સમજે છે.”","e":"“Infinite avatars occurred in the past. Power like theirs We have today displayed through each single Sant. At the final hour We grant darshan to Our ashrit devotees on the word of a Sant. Moreover, whether a person be of high or low birth, he takes Our refuge and becomes a harijan; and then, by doing satsang, his jiva becomes exceedingly pure. Just as however soiled a garment may be it is made clean by water, so even the sins of one in whom there is great impurity are destroyed by Our word through the union of satsang. It is not fitting for Us to speak Our own greatness with Our own mouth; and yet until We speak it, peace does not come to people. Whoever has attained satsang today, We count as the equal of an ishwar — because he has held the secret of every scripture on earth to lie in Our word! He understands that Our word and all the scriptures are one and the same.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":417,"k":"para","g":"આમ, શ્રીહરિને ઉદાસ થયેલા જોઈ નિત્યાનંદ સ્વામીએ વાતમાં વાત પલટી નાખી. તેઓ બોલવામાં અતિ પ્રવીણ હતા. તેમણે કહ્યું, “મુક્તમુનિનો કહેવાનો મર્મ પ્રભુ! સમજ્યા નહિ. તેઓ કહે છે કે આજે જેવી શાંતિ છે તેવી અખંડ કેમ રહે!”","e":"Seeing Shriharí thus downcast, Nityanand Swami turned the subject of the conversation. He was exceedingly skilled in speech. He said, “Lord! You have not understood Muktamuni’s meaning. He is asking how the peace that exists today may remain unbroken!”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":418,"k":"para","g":"ત્યારે શ્રીહરિ કહે, “ઠીક કહ્યું. તમે બોલ્યા ન હોત તો અમે તમારો ત્યાગ કરીને બદરીવનમાં જતા રહ્યા હોત. મનમાં એમ નિશ્ચય કરતા હતા તે વખતે તમે બોલ્યા. જીવ હવે સ્થિર થયો, ઉદાસીનતા જતી રહી, તમે ન બોલ્યા હોત તો સવારે અમને દેખત નહિ.”","e":"Then Shriharí said, “Well said. Had you not spoken, We would have abandoned you all and gone away to the forest of Badri. We were resolving it in Our mind at that very moment when you spoke. Our heart is settled now, the despondency has gone; had you not spoken, you would not have seen Us in the morning.”","s":["15/55/1-32"],"sv":[],"mt":false,"gl":null,"a":false},{"i":419,"k":"para","g":"પછી શ્રીહરિએ પ્રસન્ન થઈને મુક્તમુનિને અંતરમાં શાંતિ અખંડ રહે એવી વાત કરવા માંડી, “અમે આ બ્રહ્માંડમાં પ્રગટ થયા. ભગવાનની યોગકળાનો કોઈ પાર પામતું નથી. જેમ જેમ તર્ક કરવા જાય, તેમ તેમ તે અપારના અપાર રહે છે. તેને પાર પામવાની ઇચ્છા રાખે તે બાળકબુદ્ધિ છે. જેમાં સર્વે આશ્ચર્ય રહ્યાં છે, જેનાથી કોઈ પર નથી (એવા અમે પોતે પુરુષોત્તમ છીએ) એવી સ્પષ્ટ વાત અમે ઘણીવાર કહી છે, તોપણ જો અંતરમાં શાંતિ રહેતી ન હોય તો શાંતિ ક્યાંથી મળશે! અમને જેવો આવડ્યો એવો ઉત્તર કર્યો. શાંતિની વધુ વાત નિત્યાનંદ સ્વામી તમને કહેશે.” એવી શીખ દઈ શ્રીહરિ પોઢી ગયા.","e":"Then Shriharí, being pleased, began to speak in such a way that peace might remain unbroken within Muktamuni: “We have become manifest in this brahmand. No one reaches the limit of the yogic skill of Bhagwan. The more one goes on reasoning, the more it remains boundless beyond all bounds. One who keeps the desire to reach its limit is of a child’s understanding. That in whom all wonders reside, than whom there is none higher — that We Ourself am Purushottam — this plain matter We have said many times; and even so, if peace does not remain within, then from where will peace be found! We have answered as best We know how. Nityanand Swami will tell you more of peace.” Having given such instruction, Shriharí retired to rest.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":420,"k":"para","g":"પછી નિત્યાનંદમુનિએ મુક્તમુનિને શાંતિ પમાડવા વાતો કરી કે, “આ શ્રીહરિ મળ્યા છે. તેમનાં ચરિત્રોમાં શાંતિ છે. તેમને રાત-દિવસ સંભારવા એ શાંતિનો ઉપાય છે. નારદજીએ વ્યાસજીને પણ પ્રગટ શ્રીકૃષ્ણના ચરિત્રમાં મન પરોવવા કહ્યું હતું. આજે શ્રીહરિ ધર્મને ઘરે પ્રગટ્યા, ગૃહત્યાગ કર્મો. અહીં આપણી વચ્ચે આવીને રહ્યા, અનેક ચરિત્રો કર્યાં તે સર્વે ચિંતવતાં પરમ શાંતિ થાય છે.”","e":"Then Nityanandmuni spoke to bring peace to Muktamuni, saying, “This Shriharí has been obtained. Peace lies in His charitras. To remember Him day and night is the remedy for peace. Naradji too told Vyasji to fix his mind upon the charitras of the manifest Shri Krishna. Today Shriharí has become manifest in the house of Dharma, has renounced His home, has come and dwelt here among us, and has performed many charitras — contemplating all of these, supreme peace arises.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":421,"k":"para","g":"પછી મુક્તમુનિને ઘેડ બેઠી ને ચરિત્રો સંભારતાં હૃદયમાં શાંતિ થઈ. શ્રીહરિએ આ જાણ્યું ત્યારે પ્રસન્ન થયા. મુક્તમુનિએ વિનતિ કરી, “તમને પ્રસન્ન કરવાનું અમને તાન છે માટે આપની મરજી હોય તેમ કહેજો. આ આપની મૂર્તિ અક્ષરધામમાં અખંડ વિરાજમાન છે, છતાં એવી કંઈક યોગકળા છે કે એ આવ-જા કરતી દેખાય છે. ધામની મૂર્તિ અને આ મૂર્તિમાં અધિક-ન્યૂનપણું શ્રવણ કરવામાં આવે છે ત્યારે ઉત્તાપ થાય છે.”","e":"Then Muktamuni’s understanding settled, and on remembering the charitras peace arose in his heart. When Shriharí knew this, He was pleased. Muktamuni made a request: “Our zeal is to please You, so tell us as You wish. This murti of Yours is unbrokenly present in Akshardham, and yet there is some yogic skill by which it is seen to come and go. When one hears of a greater and a lesser between the murti in the abode and this murti, distress arises.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":422,"k":"para","g":"શ્રીહરિ કહે, “જેને જેવી સમજ તેનો તેવો મોક્ષ થાય. ન્યૂન જાણે તો ન્યૂન ધામને પામે. આ મૂર્તિને માયિક જાણે તો તે જન માયિક જ રહે. મૂર્તિ કરતાં તેજને અધિક કોઈ માની લે તો તેને કોઈ પ્રાપ્તિ નથી, લખચોરાશી ટળતી નથી. જેને હાથ છે, પગ છે, મુખ છે, નેત્ર છે, નાક અને કાન છે, સંપૂર્ણ અંગો છે એવી (સાકાર) મૂર્તિને તેજરૂપ નિરાકાર માને તેને વારંવાર દેહ ધરવા પડે છે. હવે આ જોગમાં આવ્યા પછી જેવી વાતોનું, શ્રવણ-મનન કરે તેવું અંગ બંધાય છે. જેમ કોઈ ભૂત-પ્રેતની વાત સાંભળે પછી તેને પશુમાં, પંખીમાં, વૃક્ષ-લતામાં ને ઘાસમાં પણ તે ભૂતનો આકાર બંધાઈ જાય છે. તેમ જીવ જેનામાં રુચિ કરે છે તેને તેવું તન પ્રાપ્ત થાય છે. શબ્દ સાંભળે છે તેવું અંગ બંધાય છે.”","e":"Shriharí said, “As a person’s understanding is, such is his moksha. If he knows it as lesser, he attains a lesser abode. If he knows this murti to be mayik, then that person himself remains mayik. If anyone holds the light to be greater than the murti, then he has no attainment, and the eight million four hundred thousand are not removed for him. One who holds that murti which has hands, has feet, has a mouth, has eyes, has nose and ears, and has all its limbs complete — one who holds that murti to be formless, as mere light — has to take a body again and again. Now, after coming into this company, whatever matters a person hears and contemplates, such an inclination is formed in him. Just as when someone hears talk of ghosts and spirits, thereafter the shape of that ghost forms for him in animals, in birds, in trees and creepers, and even in grass — so the jiva obtains such a body as that in which it takes interest. As are the words a person hears, such is the inclination that is formed.”","s":["15/56/1-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":423,"k":"para","g":"ગઢપુરમાં સંતોની સભામાં શ્રીહરિએ વાત કરતાં કહ્યું, “સર્વ અવતારના અવતારી, અક્ષરધામના ધામી એવા સાક્ષાત્ પુરુષોત્તમ જ્યારે પ્રગટ મળ્યા અને ઓળખાણ થઈ તેને સાધનમાત્ર પૂર્ણ થઈ ગયાં. વેદ-પુરાણ ને શાસ્ત્રવિદ્યા માત્ર તેમાં આવી રહી. હવે પછી જે કરવાનું છે તે કહીએ છીએ. તે તત્પર થઈને સાંભળો અને સાંભળી નિત્ય મનન કરી અમારો અંતરનો મત જેમ છે તેમ તમે સમજો. જે સર્વ સાધનનો સાર છે. તે વિના સાધનમાત્ર નિર્જીવ છે.","e":"At Gadhpur, in the assembly of sadhus, while talking, Shriharí said, “When the Avatari of all avatars, the Lord of Akshardham, Purushottam Himself, has been obtained manifest and has been recognised, then for such a one every spiritual endeavour has been completed. The Vedas, the Purans and all scriptural learning are contained within it. Now We tell you what is to be done hereafter. Listen to it attentively, and having heard it, contemplate it daily, and understand Our inner conviction as it truly is — which is the essence of every endeavour. Without it, every endeavour is lifeless.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":424,"k":"para","g":"“પ્રગટની (અમારી) ભક્તિ ઉપાસના કરવી અને ગુરુ, સંત ને હરિજનની સેવા કરવી. જે દેખાય છે તે ચૈતન્ય-ચૈતન્ય એક નથી, તે એક એકથી અધિક છે. સૌને સરખા સમજવા નહિ. જેમ તારાથી ચંદ્ર અધિક છે, ચંદ્રથી સૂર્ય અધિક છે, તેમ ચૈતન્યમાં પણ એવા ભેદ છે. જેમ પશુ કરતાં મનુષ્યમાં અધિક જ્ઞાન છે, મનુષ્ય કરતાં દેવો અધિક છે, દેવો કરતાં ઈશ્વરો અધિક છે અને ઈશ્વરો કરતાં પરમાત્મા પરબ્રહ્મ પુરુષોત્તમ નારાયણ અતિ અધિક છે, એમની ઉપાસના સૌએ કરવી.","e":"“Perform the bhakti and upasana of the manifest form — of Us — and do the seva of the guru, the Sant and the harijans. What is seen is not one and the same consciousness throughout; one is greater than another. Do not understand all to be equal. Just as the moon is greater than a star, and the sun greater than the moon, so there are such gradations in consciousness too. Just as there is greater gnan in a human being than in an animal, and the deities are greater than human beings, and the ishwars greater than the deities, so Paramatma Parabrahman Purushottam Narayan is exceedingly greater than the ishwars; it is His upasana that all should perform.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":425,"k":"para","g":"“સંત-અસંતમાં પણ અપાર ભેદ રહ્યા છે. જેમ ગંગાનું પાણી અને મદિરામાં ભેદ છે, તેમ સંત-અસંત જુદા છે, તેને ઓળખીને સંગ કરવો.","e":"“Between the Sant and the unholy also there remain boundless differences. Just as there is a difference between the water of the Ganga and liquor, so the Sant and the unholy are distinct; one should recognise this and keep company accordingly.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":426,"k":"para","g":"“પૂર્વે અવતારો થઈ ગયા તે વખતે જેને તેની ઓળખાણ થઈ તેણે તેનું ભજન કર્યું. પ્રગટને મળેલા હરિજન અને બીજા જન તેમાં ઘણો ભેદ છે - તે બન્નેને સરખા જાણવા નહિ. પ્રગટના ઉપાસકને તુલ્ય બીજો થઈ શકતો નથી, તે ચાહે તેટલાં સાધન કરે તોપણ તેને માયિક જાણવો.","e":"“Avatars occurred in the past, and whoever recognised them at that time worshipped them. Between a harijan who has obtained the manifest form and other people there is a great difference — do not know the two to be equal. None can become the equal of one who worships the manifest form; however many endeavours he may perform, know him to be mayik.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":427,"k":"para","g":"“સ્વયં પ્રગટ ભગવાન મળે તો તેનો આશ્રય કરવો અથવા તે પ્રગટ ભગવાનના મળેલા (ભગવાનના જેવા ગુણોને ધારણ કરેલા) સંત મળે તો તેનો આશ્રય કરવો અથવા તે સંતને મળેલા સાધુ કે હરિજનનો એક એક સંબંધ કરે તો ભગવાનનો યથાર્થ નિશ્ચય થાય. અને એ નિશ્ચય-આશ્રયે કરીને અપાર જનો ભવસાગર તરી જાય છે.","e":"“If Bhagwan Himself is obtained manifest, then take His refuge; or if a Sant who has obtained that manifest Bhagwan is obtained — one who has taken on virtues like those of Bhagwan — then take his refuge; or if one forms a connection, link by link, with a sadhu or harijan who has obtained that Sant, then a true nishchay of Bhagwan arises. And by that nishchay and that refuge, boundless numbers of people cross the ocean of worldly existence.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":428,"k":"para","g":"“મારાં લીલાચરિત્ર કહે તથા સાંભળે તેમાં આનંદ પામનારા મારા આશ્રિતોને અંતકાળે રથ કે વિમાનમાં બેસાડીને ધામમાં લઈ જાઉં છું.","e":"“Those ashrit devotees of Mine who take delight in speaking and hearing My lila-charitras — at their final hour I seat them in a chariot or a vimana and take them to the abode.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":429,"k":"para","g":"“દાસનો દાસ થઈ જે નિત્ય સત્સંગ કરે છે તેની જ ભક્તિને હું પ્રમાણ કરું છું, સ્વીકાર છું. અને એવા ભક્તની જ કીર્તિ વધી છે ને શાશ્વત રહી છે. મારી મૂર્તિ દિવ્ય છે, મારું ધામ દિવ્ય ગુણાતીત છે, મારું નામ-સ્મરણ કરતાં મારા સંતો-ભક્તો પણ દિવ્ય ગુણાતીત છે. તેને જે અસત્ય કરીને કહે છે ને અસત્ય જાણે છે તે જન જ્યારે મરે છે ત્યારે તેને જમ પકડીને લઈ જાય છે. જેમ શ્વપચ શ્વાનને ખેંચીને લઈ જાય છે, તેમ ઊંધે માથે ખેંચીને જમ લઈ જાય છે. એ જીવનું રૂડું કરવા ધારું તોપણ તેનું રૂડું થતું નથી. તે ભલે મારા જેટલા ગુણ છે ને જેટલી સામર્થિ છે તેનું ગાન કરતો હોય તોપણ તે અસત્ય (વૃથા) થઈ જાય છે.","e":"“I accept and acknowledge only the bhakti of the one who, becoming the servant of servants, does satsang daily. And it is the renown of such a devotee alone that has increased and has endured everlastingly. My murti is divine, My abode is divine and gunatit, and My sadhus and devotees who perform the remembrance of My name are divine and gunatit as well. When the person who calls this false and knows it to be false dies, then Yama seizes him and carries him away. Just as a dog-keeper drags a dog away, so Yama drags him away head downwards. Even were I to intend good for that jiva, good does not come about for him. Though he may sing of all the virtues and all the power that are Mine, even that becomes false and fruitless.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":430,"k":"para","g":"“મારી દૃષ્ટિથી બ્રહ્માંડો ઊપજે છે ને લય પામે છે. આ વાત કોઈની બુદ્ધિના તર્કમાં આવે તેવી નથી. એવો હું આ સત્સંગમાં સદાય પ્રગટ રહું છું અને જે ખરી ભક્તિ કરે છે તેના રંગમાં રાચું છું. એવા પરાભક્તિ યુક્ત પ્રેમી ભક્તના રંગમાં વારંવાર રંગાવું મને ગમે છે. એવા ભક્તનો જે દ્રોહ કરે છે તે જમનો કિંકર થાય છે. આ બ્રહ્માંડમાં હું અખંડ નિવાસ કરીને રહું છું. જોગી, સંત, રાજા કે વિપ્રનું રૂપ ધારું છું.","e":"“By My glance the brahmands arise and dissolve. This matter does not come within the reasoning of anyone’s intelligence. Such am I, and I remain forever manifest in this satsang, and I delight in the colour of the one who performs true bhakti. It pleases Me to be dyed again and again in the colour of such a loving devotee, filled with parabhakti. One who betrays such a devotee becomes a servant of Yama. In this brahmand I take up My dwelling unbrokenly. I take the form of a yogi, a Sant, a king or a brahmin.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":431,"k":"para","g":"“મારી જે પ્રકારની રીતભાત છે તે મેં તમને બધી જ સ્નેહપૂર્વક આ કહી છે. મારું જે સુખ ને ઐશ્વર્ય છે તે હું મારા જનને નિશ્ચે પ્રાપ્ત કરાવીશ.”","e":"“Whatever My ways are, I have told them all to you here with affection. That happiness and majesty which is Mine, I shall assuredly cause My devotee to attain.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":432,"k":"para","g":"શ્રીહરિની આ વાત સાંભળી સૌ સંત-હરિજન રાજી થયા અને શ્રીહરિની મરજીમાં શીઘ્ર વર્તવા દૃઢાવ કર્યો.","e":"Hearing this matter of Shriharí, all the sadhus and harijans were glad, and made a firm resolve to conduct themselves swiftly according to Shriharí’s wish.","s":["15/57/1-24"],"sv":["सहजानंद स्वामी जो, मुक्तमुनि कह रहे बात ।\n\n पिछे सो बोलत भयेउ, सर्वेश्वर साक्षात् ॥\n\n अक्षरधाम के धामी जो, प्रगट मिले जब जाहि ।\n\n वेद पुरान साधन सब, आई रहे ता मांहि ॥\n\n पिछे करना जेहि, ताकि कहत हें बात अब ।\n\n तत्पर सुनो मुनि तेहि, सुनि के करना मनन नित ॥\n\n हमारो मत हे जेह, तेसे समझना तुम सब ।\n\n साधन के सार हे एह, ता विन साधन निर्जीव रहे ॥\n\n गुरु संत हरिजन जेहा । भजना प्रगट हरि कुं तेहा ॥\n\n चैतन चैतन जो ता मांहि । एसे एक से अधिक रहाहि ॥\n\n सब हि सम समझना नाहि । तारे से चंद्र अधिक कहाहि ॥\n\n चंद्र से सूर्य अधिक देखाते । चैतन में एसे भेद रहाते ॥\n\n पशु करते मनुष्य जो तामें । अधिक ज्ञान रहाये हे यामें ॥\n\n मनुष्य से देव अधिक रहाये । देव से ईश्वर अधिक कराये ॥\n\n ईश्वर से परमेश्वर जेहु । अति अधिक सो रहाये तेहु ॥\n\n संत-असंत तामें जोउ । अपार भेद रचे हें सोउ ॥\n\n गंगोदक मदिरा जो जेसे । संत-असंत में भेद हें तेसे ॥\n\n जब जब जाकुं मिले भगवाना । ताके भजन जेते करत रहाना ॥\n\n सो सब जन हरिजन रहेउ । ताकि तुल्य ओर जन न कहेउ ॥\n\n च्हाय तेसे साधन करावे । तोउ मायिक जन सो कहावे ॥\n\n भगवान अरु भगवान ताके । मिलनवार मिले संत वाके ॥\n\n वा ताके मिलनवार मिलेउ । एक एक संबंध कर तेउ ॥\n\n हरि के निश्चय आश्रय करहि । अपार जन भवसिंधु तरहि ॥\n\n लीला सुंदर में प्रगट करेउ । के’ना सुनना आनंद भरेउ ॥\n\n अंतकाल जब होव हि, मेरे आश्रित ताहि ।\n\n रथ अश्व विमान लेइकर, लेइ जावहि याहि ॥\n\n दास के दास होई के, करना नीत सत्संग ।\n\n भक्ति प्रमान करहि तब, कीर्ति बढ़हि अभंग ॥\n\n मम मूर्ति मम धाम, मेरे संत हरिजन तेहि ।\n\n जपत जो मेरे नाम, गुणातीत हि रहे एहि ॥\n\n ताकुं जो असत् कहत, असत् कर जान हि जेउ ।\n\n तेह जन सबहि मरंत, जम जोरे ले जात पकड ॥\n\n ऊंधे सिर तेहि खेंचत जाई । श्वपच श्वान जिमि खेंचत ताई ॥\n\n धारत में दिल बात हि जेता । असत् होई जावत तेता ॥\n\n मेरे गुन कहावत हि जितने । साम्रथि जुत गवावत तितने ॥\n\n मेरी दृष्टि करिके जोउ । समय पर ब्रह्मांड यह सोउ ॥\n\n उपजत लीन हि होई जाते । कोउ के तर्क में यह न आते ॥\n\n सत्संग तामें रहत सदाई । हरिजन पर हि राचत रहाई ॥\n\n प्रेम रंग हरिजन जो केरा । रंगात रहत में वेर हि वेरा ॥\n\n हरिजन के द्रोह करत जितना । जम के किंकर होवत तितना ॥\n\n अखंड यह ब्रह्मांड तामें । रहत मैं निवास कर यामें ॥\n\n जोगि नृप विप्र रूप धारी । विचरत रहत हें वार हि वारी ॥\n\n मेरी रीत हें जेहि प्रकारा । तुम कुं कहे सब करिके प्यारा ॥\n\n एसि रीत जानिकर जन जेहा । मेरे कुं जेते भजहि तेहा ॥\n\n मेरे सुख रहाये जितनी । निश्चे पाव हि जन जो तितनो ॥\n\n इतनी बात हरि कर रहे जबहु । संत हरिजन सुनि के तबहु ॥\n\n प्रसन्न भये कोउ वार न पाया । हरि एसे सुख दिने अपारा ॥\n\n अपार मरजी देखे हरि केरी । हृरिजन शीघ्र सबहि ते वेरी ॥"],"mt":false,"gl":null,"a":false},{"i":433,"k":"para","g":"શ્રીહરિએ પત્રમાં જણાવ્યું, “મારા ભક્તને હું અપાર ઐશ્વર્ય બતાવું છું. જેનો કોઈ પાર પામી શકતો નથી. મારા દસ હજારમા અંશના પણ દસ હજાર અંશથી અને તેના પણ તેટલા અંશથી હું સમગ્ર વિશ્વમાં વ્યાપી રહ્યો છું. જેવો દેહને વિષે આત્મભાવ છે તેવું મારે વિષે હેત હોય તેને બ્રહ્મલોક પર્યંત બધું તૃણ જેવું લાગે છે. તેવા ભક્તોનો જાગ્રતમાં પણ સુષુપ્તિ જેવો દેહભાવ રહે છે. સદા આત્માને વિષે વૃત્તિ હોવાથી અખંડ જાગ્રત અવસ્થા પણ છે.”","e":"Shriharí stated in a letter, “I show My devotee boundless majesty, of which no one can reach the limit. By a ten-thousandth part of even a ten-thousandth part of Me, and by such a part of that again, I pervade the entire universe. To one who has for Me the affection that a person has as the sense of self in his body, everything up to Brahmalok seems like a blade of grass. In such devotees, body-consciousness remains even in waking as though it were deep sleep. And because their attention is always upon the atma, they are also in an unbroken waking state.”","s":["15/77/1-7"],"sv":[],"mt":false,"gl":null,"a":false},{"i":434,"k":"para","g":"ધર્મપુરનાં રાણી કુશળકુંવરબાને શ્રીહરિએ કહ્યું, “માયિક વસ્તુમાં અમે ક્યારેય બંધાતા નથી. પિંડ-બ્રહ્માંડથી પર અને અતિશય જુદા અમે રહીએ છીએ. પિંડ-બ્રહ્માંડનું કાર્ય ભગવાનના ઉપયોગમાં આવે તેટલું અમાયિક થઈ જાય છે, પછી તે બંધન કરતું નથી. ભગવાનના ઉપયોગમાં ન આવે તે વસ્તુ ચાહે તેટલી મોટી હોય તોપણ નિરર્થક કહેવાય છે.”","e":"Shriharí said to Kushalkuvarba, the queen of Dharmapur, “We are never bound by mayik things. We remain beyond body and brahmand, and utterly apart from them. Whatever work of the body and brahmand comes into the use of Bhagwan becomes amayik to that extent, and thereafter it does not bind. A thing that does not come into the use of Bhagwan is called worthless, however great it may be.”","s":["16/27/19-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":435,"k":"para","g":"ધર્મપુરમાં શ્રીહરિ કહે, “ભગવાનના સ્વરૂપ સંબંધી વાત સાચા સત્સંગ (સત્પુરુષ) વિના સમજાતી નથી, જ્યારે પરબ્રહ્મ પુરુષોત્તમ ભગવાનના સ્વરૂપનું જ્ઞાન પ્રાપ્ત થાય છે, ત્યારે જીવ બ્રહ્મરૂપ થાય છે. આ સિદ્ધાંત વાત છે. પરબ્રહ્મની ઉપાસના વિના બ્રહ્મસ્થિતિ થતી નથી, બ્રહ્મસ્થિતિ થાય ત્યારે ફાવે ત્યાં પ્રવેશ કરે છે અને બીજા લોકોની વાત પણ અહીં બેઠાં દેખે છે, અને બીજાની નાડી પણ ખેંચી લે છે.”","e":"At Dharmapur, Shriharí said, “Matters concerning the swarup of Bhagwan are not understood without true satsang — the Satpurush. When gnan of the swarup of Parabrahman Purushottam Bhagwan is obtained, then the jiva becomes brahmarup. This is a settled principle. Without the upasana of Parabrahman, the brahmic state does not come about. When the brahmic state is attained, one enters wherever he pleases, and sitting here he sees the affairs of other realms, and he can even draw out another’s pulse.”","s":["16/46/1-6"],"sv":["श्रीहरि पुनि कहत भये, हरिजनहि प्रति बात ।\n\n साचे सत्संग जोग बिन, बात नहि समझात ॥\n\n परब्रह्म भगवान के, ज्ञान बिन कोउ दिन ।\n\n ब्रह्मरुप जीव न होत कबु, सिद्धांत बात हि किन ॥\n\n परब्रह्म की उपासना बिन हि । ब्रह्मस्थिति न होवत किनहि ॥\n\n ब्रह्मस्थिति सिद्ध होवत जेहा । चाय तामें प्रवेश करे तेहा ॥\n\n इहां बैठे जेते लोक की बाता । देखत रहत हि जिमि साक्षाता ॥"],"mt":false,"gl":null,"a":false},{"i":436,"k":"para","g":"શ્રીહરિએ કહેલી વાત મુક્તમુનિએ કહી, “અનંતકોટિ બ્રહ્માંડની સમૃદ્ધિને કોટિ કોટિ કલ્પ સુધી અવિચ્છિન્નપણે ભોગવે તેનું જેટલું સુખ છે તેના કરતાં ભગવાનનાં એક દર્શનનું સુખ વધી જાય. વિષયસુખ અલ્પ ને તુચ્છ છે, ભગવાનનું સુખ અપાર ને દિવ્ય છે, તે બુદ્ધિવાનને જાણ્યામાં આવે છે.”","e":"Muktamuni related a matter Shriharí had spoken: “Even if one were to enjoy the riches of infinite millions of brahmands unbrokenly for millions upon millions of kalpas, the happiness of a single darshan of Bhagwan exceeds all the happiness of that. The happiness of the vishays is small and trifling; the happiness of Bhagwan is boundless and divine — and this comes to be known by one possessed of intelligence.”","s":["16/59/29-30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":437,"k":"para","g":"વિસનગરમાં શ્રીહરિ કહે, “ભગવાન વગરનું જેટલું આલંબન છે તેનો ત્યાગ કરીને જ્યારે ભગવાનનું આલંબન થાય એવા જનને ભગવાન પલભર છોડતા નથી. ભગવાનમાં રહેલી યોગકળાનો પાર અક્ષર પણ લઈ શકતા નથી. જ્યાં જેવું કાર્ય ત્યાં તેવા તે દેખાય છે.” એમ કહી પોઢી ગયા.","e":"At Visnagar, Shriharí said, “When a person renounces every support that is not Bhagwan and takes the support of Bhagwan, Bhagwan does not leave such a one for a moment. Even Akshar cannot reach the limit of the yogic skill residing in Bhagwan. Wherever there is such a work, there He is seen in such a form.” Saying this, He retired to rest.","s":["18/43/34-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":438,"k":"para","g":"શ્રીહરિએ જેતલપુરના મહોલ પર વાત કરતાં કહ્યું, “જે સંત-હરિજન સત્સંગના નિયમમાં વર્તે અને ધર્મ-ભક્તિના પુત્ર પ્રગટ શ્રીહરિના સ્વરૂપને વિષે જ તાન રાખે અને તે વિના ચાહે તેટલો મોટો હોય તોપણ તેને ક્યારેય માને નહિ તે સાધુ કે હરિજન શ્રેષ્ઠ છે. એવા સંત કે ભક્તને કોઈ દંભી કહે તો તેથી અધિક કોઈ પાપ નથી. સંત ઉપર સાચી પ્રીતિ હોય તે છુપાવી રહેતી નથી.”","e":"While talking on the terrace of the mansion at Jetalpur, Shriharí said, “That sadhu or harijan is the finest who conducts himself within the niyams of satsang, who keeps his zeal upon the swarup of the manifest Shriharí, the son of Dharma and Bhakti, alone, and who apart from Him never regards anyone, however great he may be. If anyone calls such a Sant or devotee a hypocrite, there is no sin greater than that. True love for the Sant does not remain hidden.”","s":["19/40(39)/35-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":439,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સંતો-હરિજનોને વાત કરતાં કહ્યું, “શ્રી પુરુષોત્તમ ભગવાનનું શરીર આત્મા અને અક્ષર છે. આત્મા અને અક્ષરમાં પોતે વ્યાપીને રહ્યા છે. પુરુષોત્તમ અતિ સમર્થ છે. આત્મા અને અક્ષર તેની પાસે પરતંત્ર છે, વ્યાપ્ય છે અને આધીન છે. એવી રીતે ભગવાન બંનેના શરીરી છે અને પ્રેરક, સ્વતંત્ર, નિયંતા, સકલ ઐશ્વર્ય સંપન્ન કહેવાય છે. સૌથી પર અક્ષર છે, તેનાથી પણ પર પુરુષોત્તમ કહેવાય છે. એ જીવોનાં કલ્યાણ કરવા કૃપા કરીને પરમ સ્નેહથી પૃથ્વી ઉપર મનુષ્ય દેહ ધારણ કરીને આવે છે. છતાં પણ એ સદા દિવ્ય છે. તેમને મૂર્તિમાન જાણીને તેમની ઉપાસના-ભક્તિ કરે તો તે ભગવાનનું સામર્થ્ય પામે છે. પોતાનો આત્મા બ્રહ્મભાવ પામે પછી પુરુષોત્તમ ભગવાનની સેવામાં તે રહી શકે છે.”","e":"At Gadhpur, while talking with the sadhus and harijans, Shriharí said, “The body of Shri Purushottam Bhagwan is the atma and Akshar. He resides pervading the atma and Akshar. Purushottam is exceedingly powerful. The atma and Akshar are dependent upon Him, are pervaded by Him, and are subject to Him. In this way Bhagwan is the indweller of both, and is called the impeller, the independent one, the controller, and the possessor of all majesty. Akshar is highest of all, and Purushottam is called higher even than Akshar. To bring about the redemption of the jivas, He shows grace and out of supreme affection takes a human body upon the earth. And yet He is forever divine. If one knows Him as possessed of form and performs His upasana and bhakti, then he attains the power of that Bhagwan. When his own atma attains the brahmic state, thereafter he is able to remain in the service of Purushottam Bhagwan.”","s":["21/65/18-36"],"sv":["श्री पुरुषोत्तम ऐसे जेउ । भगवान जेहि कहावत तेउ ॥\n\n ताके शरीर आत्मा कहेउ । तथा अक्षर ताकुं कहेउ ॥\n\n आत्मा अरु अक्षर पण जेहु । माया तिनमें पर रहे तेहु ॥\n\n एसे आत्मा रू अक्षर जोउ । भगवान के शरीर सोऊ ॥\n\n आत्मा अरु अक्षर हि ताके । विषे व्यापक रहाये वाके ॥\n\n अरु यह दोनु व्याप्य रहाते । भगवान के आधिन कहाते ॥\n\n अरु भगवान स्वतंत्र रहेउ । आत्मा अरु अक्षर जो तेऊ ॥\n\n भगवान के रहे आधिनां । परतंत्र रहेउ होय दीनां ॥\n\n प्रेरक स्वतंत्र नियंता रहाते । सकल ऐश्वर्य संपन्न कहाते ॥\n\n पर ऐसे जो अक्षर कहिता । तेहिसें पण पर सो कहिता ॥\n\n ऐसे जो पुरुषोत्तम कहीजे । भगवान जाके नाम लहिजे ॥\n\n सो जीवके कल्यान कहीता । कृपाये करीके परमप्रीता ॥\n\n पृथ्वीके विषे वेर हि वेरा । मनुष्य जेसे फेट हि फेरा ॥\n\n जनाई आवत हें जो ताकुं । ऐसि रीते सदा दिव्य वाकुं ॥\n\n मूर्तिमान जानिके ताकि । उपासना भक्ति करत वाकि ॥\n\n तेहि यह भगवान ताके । सामर्थ्यपनाकुं पावत वाके ॥\n\n अनंत ऐश्वर्य रहे जो तिनकुं । पावत रहे सहज हि ईनकुं ॥\n\n अरु ब्रह्मभाव तिनकुं जोऊ । पाये निजके आत्मा सोऊ ॥"],"mt":false,"gl":null,"a":false},{"i":440,"k":"para","g":"ગઢપુરમાં સંતો-હરિજનોને શ્રીહરિ કહે, “અમે સદા નિર્દોષપણે રહીએ છીએ. અમારે વિષે જે દોષબુદ્ધિ કરે છે તેને જાગ્રત-સ્વપ્નમાં ક્યારેય સુખ થતું નથી. મનમાં ભૂંડા ઘાટ તેને પીડ્યા કરે છે અને દેહ ત્યાગ સમયે બહુ કષ્ટ પડે છે.”","e":"At Gadhpur, Shriharí said to the sadhus and harijans, “We remain forever faultless. One who forms a fault-finding view towards Us never finds happiness, waking or dreaming. Evil thoughts torment him in the mind, and at the time of leaving the body he suffers great distress.”","s":["26/11/37-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":441,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":"The author’s notes and corroboration upon the foregoing subject as spoken by Shriharí:","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":442,"k":"para","g":"બાજીગર (નટ, ગોડિયો) ઘેર ઘેર ભિક્ષા માગી તુચ્છ નિર્વાહ કરે છે - તેની ગતિ કળા પણ સમજાતી નથી, તો માયાના પણ સ્વામી અને સિદ્ધના પણ સિદ્ધ શ્રીહરિનાં ચરિત્રમાં અનંત આશ્ચર્ય રહ્યાં હોય તેમાં શું કહેવું?","e":"A conjuror begs from door to door and makes a meagre living — and even his movements and his art are not understood. Then what is to be said of the infinite wonders that reside in the charitras of Shriharí, who is the master even of maya and the siddha even of the siddhas?","s":["2/9/30-31"],"sv":[],"mt":false,"gl":null,"a":true},{"i":443,"k":"para","g":"બદરિકાશ્રમમાં નીલકંઠવર્ણી વેશે શ્રીહરિ પધાર્યા ત્યારે નર-નારાયણ ઋષિ તેમની પ્રાર્થના કરતાં કહે છે - તમે અમારા આશ્રમમાં પધાર્યા, તેથી આશ્રમ મહાપવિત્ર થઈ ગયો. કારણ તમારાં ચરણના પ્રતાપથી અનંતકોટિ બ્રહ્માંડ નિષ્પાપ થઈ જાય છે. સર્વથી અધિક અક્ષર છે, તેમનો મહિમા આપની ચરણ-સેવાના પ્રતાપથી છે.","e":"When Shriharí came to Badrikashram in the guise of Nilkanth Varni, the rishis Nar and Narayan offered Him a prayer, saying — You have come to our ashram, and by that the ashram has been made greatly holy; for by the majesty of Your feet infinite millions of brahmands are made free of sin. Akshar is greater than all, and his mahima is by the majesty of the service of Your feet.","s":["2/18/10-11"],"sv":[],"mt":false,"gl":null,"a":true},{"i":444,"k":"para","g":"નરનારાયણ ઋષિ નીલકંઠપ્રભુ પ્રત્યે બોલ્યા, “આજ આ આશ્રમના ધન્યભાગ છે. વળી, આ બદરીતરુ સ્થાનના અતિશય ધન્યભાગ છે. પ્રભુ! તમને જે જાણતા નથી તે ખરેખર અભાગી છે. તમે અમને કૃતાર્થ કરવા માટે, તપને મિષે પધાર્યા છો. પોતાની અનંત સામર્થિને છુપાડીને વિચરો છો. તમે પરબ્રહ્મ પુરુષોત્તમ સ્વયં છો, અમે તો તમારાથી અધિક બીજાને જાણતા નથી. કોઈ બીજાને તમારાથી અધિક જે કહે છે તે દેવતા હોય કે મનુષ્ય, પણ તેને અમે પશુ જ જાણીએ છીએ. તમારી જેવા તો તમે એક જ છો, સૌના સ્વામી છો. એવું અમે જાણીએ છીએ. તમારાથી અધિક જો કોઈ બીજાને કહે છે, તે કહેનારા કોટિ વખત નરકનો ભોગ કરે છે. તમારા લીધે બીજાની મોટપ કહે છે તેનાં પાપમાત્ર નાશ પામે છે, ને તેને સદ્‌બુદ્ધિ પ્રાપ્ત થાય છે. પ્રભુ! તમારો પ્રતાપ જે યથાર્થપણે નથી જાણતા તે જ અમને અધિક કરીને માને છે. ખરેખર તો આજે આપે આવીને, અમને દર્શન દઈને અધિક કર્યા છે.”","e":"The rishis Nar and Narayan said to Nilkanth Prabhu, “Today this ashram is blessed. And this place of the badri tree is exceedingly blessed. Lord! Those who do not know You are truly unfortunate. You have come, on the pretext of austerity, in order to fulfil us. You travel about concealing Your own infinite power. You are Parabrahman Purushottam Himself; we know none greater than You. Whoever calls another greater than You — be he a deity or a human being — him we know to be nothing but an animal. There is only one such as You; You are the master of all. So we know. Those who call another greater than You suffer hell ten million times over. Those who speak of another’s greatness on account of You have all their sins destroyed, and good understanding is granted to them. Lord! It is only those who do not truly know Your majesty who count us as greater. In truth, it is You who have today come and, by granting us darshan, made us greater.”","s":["2/18/23-29"],"sv":["धन्य आज आश्रम को भागा । धन्य धन्य यह बद्रितर जागा ॥\n\n तरु यह सब भये बड़ भागी । तुमकुं न जाने सोहि अभागी ॥\n\n हमकुं कृतार्थ करन हित, तप के मिस ले आये ।\n\n निज सामृथी अनंत ही, फिरत हो छिपाये ॥\n\n तुम सें जो अधिक कोउ हि, हम हि देखत नाहि ।\n\n तुम सें अधिक हि कहत हैं, देव नर पशु कहाहि ॥\n\n तुम जैसे तुम एक हो स्वामी । ऐसे हम जानत बहुनामी ॥\n\n तुम से अधिक कहत हें जाही कोटि वेर नरक सो भुक्तत ताही ॥\n\n तुमकुं लई मोटप करे जाकी । पाप मिट सद्‌बुद्धि होय ताकी ॥\n\n तुम्हारे प्रताप न जानत जोई । हमकुं अधिक कर मानत सोई ॥\n\n अधिक में अधिक कियेउ आई । हमकुं दरस दिये हित लाई ॥"],"mt":false,"gl":null,"a":true},{"i":445,"k":"para","g":"પરબ્રહ્મ પુરુષોત્તમનારાયણ માયા અને કાળના નિયંતા છે. અક્ષરકોટિ (અક્ષરબ્રહ્મ અને મુક્તો) જેનું નિત્ય ધ્યાન ધરે છે. ક્ષર-અક્ષર પર્યંત સર્વના કર્મફલપ્રદાતા છે. એને સમાન બીજું કોઈ નથી.","e":"Parabrahman Purushottam Narayan is the controller of maya and of Kal. The Akshar-koti — Aksharbrahman and the muktas — meditate upon Him daily. He is the bestower of the fruits of karma upon all, from kshar up to Akshar. There is none equal to Him.","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":446,"k":"para","g":"સર્વ કારણના કારણ છે. અનંત શક્તિઓના ધારક છે. સૌના પ્રેરક છે. તેઓ બ્રહ્મપુરમાં સદા સાકાર સ્વરૂપે બિરાજમાન છે. અનંતકોટિ મુક્તો જેના ચરણની સેવા અને નામરટણ નિશદિન કરે છે. અક્ષરબ્રહ્મ, મુક્તો, ઈશ્વરો, જીવો વગેરે સૌના પોતે ધ્યેય-ઉપાસ્ય છે.","e":"He is the cause of all causes. He is the holder of infinite powers. He is the impeller of all. He is forever present in Brahmapur in a form possessed of shape. Infinite millions of muktas perform the service of His feet and the repetition of His name day and night. He Himself is the object of meditation and of worship for Aksharbrahman, the muktas, the ishwars, the jivas and all others.","s":["3/2/19-22"],"sv":["माया काल नियंता कहीये । क्षरअक्षर पर्यंत हि लहिये ॥\n\n कर्मके फलप्रद सबके ऐहा । एहि सम कोउ न और हि जेहा ॥\n\n सब कारन के कारन हैं ताई । अनंतशक्ति धर ईश्वर जाई ॥\n\n सब प्रेरक परब्रह्म कहाउ । साकार सदा ब्रह्मपुर रहाउ ॥\n\n मुक्तकोटि जेहि चरनकुं सेवे । निशदिन नामरटन मुख लेवे ॥\n\n अक्षर मुक्त ईश्वर जीय जोउ । सब कर ध्येय कहावत सोउ ॥"],"mt":false,"gl":null,"a":true},{"i":447,"k":"para","g":"બ્રહ્માનંદ સ્વામીને સમાધિમાં બદરીપતિ નરનારાયણે દર્શન દીધાં ને કહ્યું, “અનંત અવતારો થયા છે તે સૌ અવતારોના કારણ એવા અક્ષરપતિ શ્રીપુરુષોત્તમ અવિનાશી આજે અધર્મનો નાશ કરવા પ્રગટ્યા છે. તે મહાપ્રભુને મારા જય સ્વામિનારાયણ કહેજો.”","e":"In samadhi, Nar-Narayan, the lord of Badri, granted darshan to Brahmanand Swami and said, “Infinite avatars have occurred, and the cause of all those avatars — the imperishable Shri Purushottam, the lord of Akshar — has today become manifest to destroy adharma. Convey to that Mahaprabhu my ‘Jay Swaminarayan.’”","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":448,"k":"para","g":"બ્રહ્મમુનિ કહે, “અમે તો તમને અક્ષરપતિ પુરુષોત્તમ માનીએ છીએ. તમે જ એ (સહજાનંદ સ્વામી) રૂપે અહીં આવ્યા છો.”","e":"Brahmamuni said, “We hold You to be Purushottam, the lord of Akshar. It is You who have come here in that form — as Sahajanand Swami.”","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":449,"k":"para","g":"ત્યારે નરનારાયણ દેવે કહ્યું, “અમારા જેવા તો તેમને અનંત છે, તેમના સમાન કોઈ નથી. તે આદિ નારાયણ છે. તેનું ધ્યાન અમે નિત્ય ધરીએ છીએ અને ઇચ્છીએ છીએ કે, અમારા હૃદયમાં તેઓ ક્યારે દર્શન દેશે! એ પુરુષોત્તમ નારાયણ અમારા માટે અગમ્ય છે. તો બીજી (એમનાં ગુણ-મહિમા-સ્વરૂપ સંબંધી) શી વાત કરવી?","e":"Then Nar-Narayan Dev said, “Of such as us He has infinitely many; there is none equal to Him. He is Adi Narayan. We meditate upon Him daily, and we long to know when He will grant darshan within our hearts! That Purushottam Narayan is beyond our reach. Then what else is there to say of His virtues, His mahima and His swarup?","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":450,"k":"para","g":"“અમે તો એમની આજ્ઞા રતીભાર ભંગ કરતા નથી. અમારા સંકલ્પો તેઓ પોતાની શક્તિથી પકડીને તેને તોડે છે. વધું શું કહીએ? જ્યાં સુધી એમની મરજી હશે, ત્યાં સુધી લોકો અમને માનશે.”","e":"“We do not break His command by so much as a particle. Our own resolves He seizes by His power and breaks. What more shall we say? So long as it is His wish, so long will people regard us.”","s":["4/12/36-47"],"sv":["नारायन बोलत भये, सुनो नर तुम भ्रात ।\n\n अवतार अनंत भये, ऐसी न सुनि कोउ बात ॥\n\n अवतार अनंत कारन यह, अक्षरपति अविनाश ।\n\n श्री पुरुषोत्तम प्रगटे, अधर्म के करन नास ॥\n\n तब बोले मुनि तेहि जोई । हम जानत है तुम हो सोई ॥\n\n तब बोले नारायनदेवा । हम जैसे सो अनंत हें एवा ॥\n\n एहि सम ओर न कोउ कहावे । आदि नारायन एक रहावे ॥\n\n हम इनको नित करत हें ध्याना । उरमें दर्श कब देवत बखाना ॥\n\n हमकुं अगम हें ओर क्या बाता । मरजी में इनकी हम रहाता ॥\n\n इनकी अग्या हम रती न तोरे । हमारे विचार सो तोरे जोरे ॥\n\n ईनकी मरजी होय त्यां लग हमही । सब जग मानत हें तबही ॥"],"mt":false,"gl":null,"a":true},{"i":451,"k":"para","g":"અલર્ક, સોમ વગેરે રાજાઓએ બ્રહ્માનંદ સ્વામીને પૂછ્યું કે તમે સમાધિમાં શો પ્રતાપ દેખ્યો? ત્યારે તેમણે હસીને કહ્યું, “આપણને સર્વોપરિ વાત મળી છે. સર્વ સુખનું કારણ જે કહેવાય છે તે શ્રીહરિ અહીં રહ્યા છે. તેમનાથી કોઈ પર કે અધિક નથી – આ વાતનો મને દૃઢ નિશ્ચય થયો. સમાધિમાં શ્રીરામાનંદ સ્વામીને મેં બદરિકાશ્રમમાં દેખ્યા. શ્રીહરિ મને બદરિકાશ્રમ સુધી મૂકી અદૃશ્ય થઈ ગયા. ત્યાં અનંત ઋષિઓ સહિત નર-નારાયણના મેં દર્શન કર્યાં. તેમણે મને પોતાની પાસે બેસાર્યો.","e":"Kings such as Alark and Som asked Brahmanand Swami what majesty he had seen in samadhi. Then he said, smiling, “We have obtained the highest matter of all. That Shriharí who is called the cause of all happiness is dwelling here. None is beyond Him or greater than Him — of this I have gained a firm nishchay. In samadhi I saw Shri Ramanand Swami at Badrikashram. Shriharí brought me as far as Badrikashram and then became invisible. There I had darshan of Nar-Narayan together with infinite rishis. They seated me beside them.","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":452,"k":"para","g":"“શ્રીહરિનાં ચરિત્ર મને પૂછવા લાગ્યા. મેં કહ્યું, ‘તમે જ અહીં બેઠા થકા ત્યાં અવતાર લીધો છે.’","e":"“They began to ask me about the charitras of Shriharí. I said, ‘It is You Yourself who, seated here, have taken the avatar there.’","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":453,"k":"para","g":"“ત્યારે નરનારાયણ હસતાં થકા કહે, ‘શ્રીહરિ અક્ષરપતિ પુરુષોત્તમ છે. તેમના તુલ્ય કોઈ બીજા સમર્થ નથી. આ શ્રીહરિ અવતાર નથી, પરંતુ સર્વ(અવતારો)ના કારણ છે. તેમની ઉપર બીજું કોઈ નથી. એ સર્વોપરી સર્વનિયંતા છે. અવતારો અનંત થયા છે, તેમના ભક્તો પણ અનંત છે. તે સર્વે એકાદવાર એમનું (પરબ્રહ્મ પુરુષોત્તમનારાયણનું) દર્શન થઈ જાય એમ રાત-દિવસ મનમાં ઇચ્છ્યા કરે છે. અમને પણ એમનાં એકવાર દર્શન થવાં દુર્લભ છે. એમણે મનુષ્યનું શરીર ધર્યું છે તેથી ભરતખંડનાં મહાભાગ્ય કહેવાય. હવે શ્રીહરિને પ્રસન્ન કરી અનંતકોટિ મનુષ્યો ભવપાર થશે. આવો અવસર ક્યારેય આવ્યો નથી.’”","e":"“Then Nar-Narayan said, smiling, ‘Shriharí is Purushottam, the lord of Akshar. There is no other as powerful as He. This Shriharí is not an avatar, but is the cause of all the avatars. There is none above Him. He is the highest of all and the controller of all. Infinite avatars have occurred, and their devotees too are infinite. All of them go on wishing in their minds day and night that they might obtain His darshan — the darshan of Parabrahman Purushottam Narayan — even once. For us too it is difficult to obtain His darshan even once. He has taken a human body, and therefore the fortune of Bharatkhand is called great. Now, by pleasing Shriharí, infinite millions of human beings will cross beyond worldly existence. Such an occasion has never come before.’”","s":["4/14/8-39"],"sv":["तब बोले मुनि मुसकाई । सर्वोपरि बात हम पाई ॥\n\n सब सुखकारन जोई कहावे । सोउ श्रीहरि यहाँ रहावे ॥\n\n इनसें पर न कोउ अधिकाई । ऐसी बात हम निश्चय पाई ॥\n\n बदरिकाश्रम गये हरि संगा । रामानंद स्वामी देखे उमंगा ॥\n\n हरि मूर्ति अदृश्य भइ तबहि । बदरिकाश्रम गये हम जबहि ॥\n\n नरनारायण दर्श भयो, हमकुं बेठाये पास ।\n\n हरिचरित्र पुछन लगे, मन में होय हुलास ॥\n\n तब हम तिन सें पुछत भयेऊ । सुने अवतार तुमहि लियेऊ ॥\n\n सो तुम अखंड बेठे हो आंही । यह बात हम जानत नांही ॥\n\n हम पुछे यह बातहि जबही । नरनारायण बोले तबही ॥\n\n श्रीहरि अक्षरपति जोई । एहि सम समर्थ अवर न कोई ॥\n\n एसे यह नहि हरि अवतारा । यह सबके हें कारन वारा ॥\n\n इनके माथे नहि कोउ ओरा । एहि सब के हें माथे जोरा ॥\n\n अनंत भये अवतार, तिनके भक्त अनंत जेहि ।\n\n दर्श हि एकहि बार, निशदिन इछत रहत तेहि ॥\n\n हमकुं दुर्लभ एह, इनको दरश एक वेर हि ।\n\n सो नरतनु धरे देह, अब भरतखंड को भाग्य महा ॥\n\n अनंतकोटि जन होवेंगे, भव पार अबे ।\n\n हरि करि प्रसन्न, एसो समो न आये कबु ॥"],"mt":false,"gl":null,"a":true},{"i":454,"k":"para","g":"શ્રીહરિ સુરાભક્તની ઓસરી પર ઢોલિયે તકિયા પર આવીને બિરાજ્યા. મંદ મંદ હસતા થકા સંત-હરિજન પર દૃષ્ટિ કરી, સૌને સમાધિમાં મોકલ્યા, પછી પ્રીતિ સહિત સૌને નીરખવા લાગ્યા. સમાધિની આ વાત અટપટી છે. પૂર્વે કોઈ અવતારમાં આવું ઐશ્વર્ય કદી દીઠ્યું નથી. સામર્થ્ય જોતાં અવતાર અને અવતારી વચ્ચેનો ભેદ સ્પષ્ટ જણાઈ આવે છે. આ વાત સમાધિવાળા કહે છે, પણ બીજાને તે સમજાતી નથી.","e":"Shriharí came and was seated upon a cushion on a cot on the veranda of Sura Bhakta. Smiling gently, He cast His glance upon the sadhus and harijans and sent them all into samadhi; then He began to gaze upon them all with affection. This matter of samadhi is intricate. In no avatar of the past has such majesty ever been seen. When one considers the power, the difference between an avatar and the Avatari becomes plainly evident. Those who experienced samadhi speak of this matter, but others do not understand it.","s":["4/59/20-22"],"sv":["संत हरिजन प्रेमी जेते । समाधि कर रहे हें तेते ॥\n\n ताकु देखत हरि कर प्रीति । अवतार सें कबु न भई यह रीति ॥\n\n अवतार अवतारी में भेद रहेऊ । सामर्थ्य करके जान परेऊ ॥\n\n समाधिवारे कहत सो बाता । ओरकुं न आवे समझाता ॥"],"mt":false,"gl":null,"a":true},{"i":455,"k":"para","g":"સમાધિમાંથી જાગ્રત થઈને ભક્તોએ શ્રીહરિને કહ્યું કે, “સૂર્યલોકમાં સૂર્યદેવે સ્તુતિ કરતાં કહ્યું, ‘તમે અવતાર માત્રના કારણ છો. અધર્મનાં મૂળ ઉખાડવા પ્રગટ થયા છો. મને આજે પવિત્ર કર્યો.’”","e":"Awaking from samadhi, the devotees told Shriharí, “In Suryalok, Suryadev offered praise and said, ‘You are the cause of every avatar. You have become manifest to uproot adharma at its root. Today You have made me holy.’”","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":456,"k":"verse","g":"‘જો જો ભયે અવતાર, તાકો કારન તુમ હો હરિ;","e":"‘Jo jo bhaye avatār, tāko kāran tum ho Hari;","s":[],"sv":[],"mt":false,"gl":"[Whatever avatars have come to be, You, Hari, are their cause;]","a":true},{"i":457,"k":"verse","g":"અબ પ્રગટે ધર્મ કે દ્વાર, અધર્મ મૂલ ઉથાપ કરન.’","e":"Ab pragate Dharma ke dwār, adharma mūl uthāp karan.’","s":["4/59/27"],"sv":[],"mt":false,"gl":"[…now You have become manifest at the door of Dharma, to uproot adharma at its root.]","a":true},{"i":458,"k":"para","g":"શ્રીહરિ દૃષ્ટાંતો અને પ્રસંગો કહીને એકાંતિક ધર્મ સિદ્ધ કરવો એ એક વાત વારંવાર દૃઢાવતા ને કહેતા કે, “એકાંતિક ધર્મમાં ચાર તત્ત્વ આવે છે - ધર્મ, જ્ઞાન, વૈરાગ્ય, ભક્તિ. અમે આ ચાર વાત જીવના હૃદયમાં દૃઢ કરાવવા સારું સર્વોપરી અવતાર ધારણ કર્યો છે.”","e":"Speaking through illustrations and incidents, Shriharí repeatedly impressed this one matter — that ekantik dharma must be accomplished — and would say, “Four elements make up ekantik dharma: dharma, gnan, vairagya and bhakti. We have taken the highest avatar of all in order to make these four things firm in the hearts of the jivas.”","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":459,"k":"verse","g":"‘ભક્તિ ધર્મ વૈરાગ્ય રુ ગ્યાના, તો પર સબકો તોડત તાના;","e":"‘Bhakti dharma vairāgya ru gyānā, to par sabko todat tānā;","s":[],"sv":[],"mt":false,"gl":"[Bhakti, dharma, vairagya and gnan — beyond these He breaks the pull of all else;]","a":true},{"i":460,"k":"verse","g":"ચાર બાત દૃઢ કરને હિતા, સર્વોપરિ અવતાર ધરિતા.’","e":"Chār bāt drudh karne hitā, sarvopari avatār dharitā.’","s":["5/74/30"],"sv":[],"mt":false,"gl":"[…and for the good of making these four things firm, He took the highest avatar of all.]","a":true},{"i":461,"k":"para","g":"શિયાણીના શિવરામ વિપ્રે શ્રીહરિની પૂજા કરી. તેમણે ભાગવત અને બ્રહ્મવૈવર્ત પુરાણનો સારી રીતે અભ્યાસ કર્યો હતો. કૃષ્ણજન્મ ખંડ પ્રત્યે તેમને બહુ ભાવ રહેતો. શ્રીકૃષ્ણને તેઓ સૌથી પર માનતા.","e":"Shivram, a brahmin of Shiyani, performed the worship of Shriharí. He had made a thorough study of the Bhagwat and the Brahmavaivarta Puran. He had great devotion towards the section on the birth of Krishna, and held Shri Krishna to be the highest of all.","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":462,"k":"para","g":"આજે શ્રીહરિએ તેમને પોતાનું સ્વરૂપદર્શન કરાવ્યું. શિવરામ વિપ્રને સમાધિ થઈ. તેમાં તેમણે અનેક શ્રીકૃષ્ણ દીઠા. દશ અને ચોવીસ - જેટલા અવતાર પૃથ્વી પર થયા તે સર્વે શ્રીહરિની મૂર્તિમાંથી નીકળતાં ને પાછા મૂર્તિમાં લીન થતા જોયા. તેઓ શ્રીહરિના અનન્ય આશ્રિત થયા ને સ્વામિનારાયણ જપવા લાગ્યા. જેમ હાથીના પગલામાં બધાં પગલાં સમાઈ જાય તેમ સ્વામિનારાયણ નામમાં બીજાં અનંત નામ સમાઈ જાય એવો એ બળિયો મંત્ર છે. શિવરામ વિપ્રે આવો પ્રતાપ હૃદયમાં પ્રત્યક્ષ અનુભવ્યો પછી અન્યનો જાપ ત્યજી સ્વામિનારાયણમાં અધિક સામર્થિ જોઈ તેને ભજવા લાગ્યા.","e":"On this day Shriharí granted him darshan of His own swarup. Shivram the brahmin entered samadhi. In it he saw many Shri Krishnas. He saw all the avatars that had occurred upon the earth — the ten and the twenty-four — emerging from the murti of Shriharí and merging back into that murti again. He became an exclusive ashrit of Shriharí and began to repeat ‘Swaminarayan.’ Just as all footprints are contained within the footprint of an elephant, so infinite other names are contained within the name Swaminarayan — so powerful is that mantra. After Shivram the brahmin had directly experienced such majesty in his heart, he abandoned the repetition of any other name and, seeing greater power in Swaminarayan, began to worship that.","s":["6/13/31-40"],"sv":["ओर अवतार भये जितने । दश अरु चोविस हि तितने ॥\n\n श्रीहरि में सब हि हो गये लीना । एक रहे श्रीहरि सुख दिना ॥\n\n स्वामिनारायण नाम, तामें नाम अनंत जेहि ।\n\n सब भये विश्राम, तिनसे अधिक न रहे कोउ ।\n\n विप्र देखे प्रताप, ऐसो आपके उर महिं ।\n\n जपन लगे सो जाप, अनंत साम्रथ जानकर ॥"],"mt":false,"gl":null,"a":true},{"i":463,"k":"para","g":"અનંત બ્રહ્માંડોના દેવો, ઈશ્વરો, અનંત પ્રધાનપુરુષો, પ્રકૃતિપુરુષ - એકએકથી દશ-દશ ગણા અધિક સામર્થ્યવાન છે. તેનાથી પર અક્ષર છે ને એ સર્વેનું સામર્થ્ય પુરુષોત્તમ નારાયણનું આપેલું છે. રવિ આગળ તારા લીન થાય છે, તેમ તે સર્વેનું સામર્થ્ય પુરુષોત્તમ પાસે કશા લેખામાં નથી, પુરુષોત્તમનારાયણ એ સર્વની સહાય કરે છે, પરંતુ સર્વે મળીને પુરુષોત્તમની સહાયતા કરવાને સમર્થ નથી. પુરુષોત્તમને કોઈની સહાયની જરૂર પણ નથી. આનંદમય તેમનું ધામ છે. ભોગ પણ આનંદમય છે. તેમની મૂર્તિ પણ આનંદમયી છે.","e":"The deities of infinite brahmands, the ishwars, the infinite Pradhan-Purushes, and Prakruti-Purush — each is ten times more powerful than the one before. Beyond them is Akshar; and the power of all of these is given by Purushottam Narayan. Just as the stars are absorbed before the sun, so the power of all of them counts for nothing beside Purushottam. Purushottam Narayan gives help to all of them, but all of them together are not able to give help to Purushottam. Nor has Purushottam any need of anyone’s help. His abode is full of bliss. Its enjoyments too are full of bliss. His murti also is full of bliss.","s":["6/21/9-14"],"sv":["पुरुषोत्तम भगवान की, करत सहाय न कोई ।\n\n सब की सहाय सो करत हे, ऐसे सम्रथ हे सोई ।\n\n आनंदमय तेहि धाम हे, आनंदमय तेहि भोग ।\n\n आनंदमय मूर्ति तेहि, सदा परम अरोग ॥"],"mt":false,"gl":null,"a":true},{"i":464,"k":"para","g":"શ્રીહરિ જેતપુરમાં ભાદર નદીએ પધાર્યા, ત્યાં રામાનંદ સ્વામીનાં સાક્ષાત્ દર્શન થયાં. શ્રીહરિ ઘોડેથી ઊતરી તેમને પગે લાગ્યા. અદ્‌ભુત વેશ હોવાથી બીજા કોઈ તેમને ઓળખી શક્યા નહિ.","e":"Shriharí came to the river Bhadar at Jetpur, and there had the direct darshan of Ramanand Swami. Shriharí dismounted from His horse and bowed at his feet. Because his appearance was wondrous, no one else was able to recognise him.","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":465,"k":"para","g":"રામાનંદ સ્વામી કહે, “હું તમારાં દર્શન કરવા આવ્યો છું.” એમ કહીને કહેવા લાગ્યા, “બીજા અનંત અવતાર થયા, જેનો ગણતાં પાર આવે નહિ. જેનામાં જેટલો પ્રતાપ હતો તેણે તેટલી સામર્થિ જણાવી. કોઈએ દીપક તો કોઈએ મશાલ જેટલું સામર્થ્ય બતાવ્યું. કોઈએ અગ્નિ તો કોઈએ વીજળી, વડવાનળ કે સૂર્ય જેટલું સામર્થ્ય દર્શાવ્યું. જેમ મહાપ્રલયની તુલનામાં અન્ય પ્રલય કોઈ નજરમાં આવતાં નથી, એ જ રીતે હે શ્રીહરિ! આપના સામર્થ્ય-પ્રતાપમાં અન્ય અવતારોનું સામર્થ્ય લીન થઈ ગયું, ઢંકાઈ ગયું. આપનું સામર્થ્ય અધર્મી, અસુરોને જાણ્યામાં આવતું નથી. સદ્‌ધર્મ અને ભક્તિ તમારાં માતાપિતા છે, તથા સત્ જ્ઞાન ને વૈરાગ્ય તમારા બંધુ છે. આમ, આ સઘળું ધર્મકુળ (એકાંતિક ધર્મ) આ સત્સંગમાં છે. આમ, ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ ચારે અંગ યુક્તને ધર્મવંશ જાણવો અને એને સંત થકી મુખ્ય કરીને માનવો.","e":"Ramanand Swami said, “I have come to have Your darshan.” Saying this, he began to say, “Infinite other avatars have occurred, so many that in counting them no end is reached. Whatever majesty each possessed, that much power did he display. Some displayed power like a lamp and some like a torch. Some displayed power like fire, and some like lightning, or the submarine fire, or the sun. Just as beside the great dissolution no other dissolution comes into view, so, O Shriharí, in Your power and majesty the power of the other avatars has been absorbed and covered over. Your power does not come to be known by the adharmi and by demons. Sat-dharma and Bhakti are Your mother and father, and true gnan and vairagya are Your brothers. Thus this whole family of Dharma — ekantik dharma — is present in this satsang. So know one endowed with all four limbs — dharma, gnan, vairagya and bhakti — to be of the lineage of Dharma, and regard him as foremost among the sadhus.","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":466,"k":"para","g":"“ધર્મ, જ્ઞાન, વૈરાગ્ય, ભક્તિ યુક્ત સંતને સન્માનવા. ભગવાનના સ્વરૂપનું જ્ઞાન જેને થયું હોય તે આવા લક્ષણ વગરના સાધુનું મુખ પણ જોતા નથી. ભગવાનના સ્વરૂપના જ્ઞાન વિનાનો ધર્મવંશી હોય તેને માનવો પૂજવો નહિ, ભગવાનના સ્વરૂપ સંબંધી જ્ઞાન વિનાનો એ વાંજણી ગાય જેવો છે. તે ધર્મનો વંશ હોય તો એકવાર અન્ન આપવા યોગ્ય છે, પણ માનવા યોગ્ય નથી, કારણ કે વંધ્યા ગાયથી વિસ્તાર થાય નહિ. તમે બધું જાણો છો, પણ આટલો સંકલ્પ થયો તે તમને કહ્યો.","e":"“One should honour the Sant endowed with dharma, gnan, vairagya and bhakti. One who has attained gnan of the swarup of Bhagwan does not so much as look upon the face of a sadhu lacking these marks. One of the lineage of Dharma who lacks gnan of the swarup of Bhagwan is not to be honoured or worshipped; without gnan concerning the swarup of Bhagwan he is like a barren cow. If he is of the lineage of Dharma he is fit to be given food once, but he is not fit to be honoured, because from a barren cow no increase comes. You know all things, but this resolve arose in me and so I have told You.","s":["6/52/1-20"],"sv":["श्रीहरि आये जेतपुर, भद्रावति गंगा पास ।\n\n रामानंद स्वामी नाये जिहां, संग ले हरिजन दास ॥\n\n रामानंद स्वामी देखे ईहां, मूर्तिमान साक्षात् ।\n\n श्रीहरि उतरे अश्व सें, चरन परे सो आत ॥\n\n भेष धरे अद्भुत, ओर जन न कले कोउ ।\n\n लगाये अंग विभूत, श्रीहरि देखिके आनंद भयेउ ॥\n\n श्रीहरि कुं कहत, दरश करन कुं आये हम ।\n\n केसे तुम विचरत, जन मनोरथ पूरे करन ॥\n\n ओर भये अवतार अनंता । गिनत गिनत न पार लहंता ॥\n\n जितनो जामें प्रताप रहाये । तितनो सबने साम्रथ जनाये ॥\n\n दिपक मशाल हुताशन जेता । अति साम्रथ देखाये तेता ॥\n\n केतने विद्युत वडवानल जेते । अति प्रताप देखाये तेते ॥\n\n केतने तारा-चन्द्र समाना । इतनो प्रताप देखाये बलवाना ॥\n\n केतने एक सूर्य प्रमाना । साम्रथ में साम्रथ इतनो देखाना ॥\n\n आगे भये अवतार हि जितना । ताको साम्रथ देखे तितना ॥\n\n महाप्रले आगे प्रले ओरा । देखे में न आवे कोउ ठोरा ॥\n\n अनंत अवतार को साम्रथ जितनो । यामें आई गये सब तितनो ॥\n\n विचरन में सो आत देखाई । असुर जन नहिं देखत ताई ॥\n\n सत धर्म के पुत्र तुम, भक्ति सत् मात हि तोर ।\n\n ज्ञान वैराग्य सत बंधु तव, देखे में आये मोर ॥\n\n धर्मकुल हि जितनो, विचरत सत्संग माहि ।\n\n सत्संग हे एक आधार तेहि, तेहि विन ठोर नाहि ॥\n\n धर्म, भक्ति, ज्ञान, वैराग्य चारु अंग जुत ।\n\n धर्मवंश कुं जान, मानहि संतसें मुख्य कर ।\n\n धर्म भक्ति वैराग्य रु ग्याना । तेहि जुत संत को करहि सन्माना ॥\n\n चार में मुख्य हरिज्ञान जो होवे । ता विन संत को मुख न जोवे ॥\n\n हरि के ग्यान बिन धर्मवंशि भारी । एक वेर अन्न देवे को अधिकारी ॥\n\n मानने को नहि तेहि अधिकारा । बांझ गाउ से कहां होय विस्तारा ॥\n\n संत हरिजन की एसी रीति । बांझ जोई के न कर हि प्रीति ॥\n\n हरि के ग्यान जुत जन फलवाना । ताको करहि धर्म जोई सनमाना ॥\n\n तुम जानत हरि सबहि बाता । इतनो संकल्प भयो सो कहाता ॥"],"mt":false,"gl":null,"a":true},{"i":467,"k":"para","g":"રામાનંદ સ્વામીએ શ્રીહરિને દર્શન દઈ કહ્યું, “તમે અક્ષરધામનું મહા તખત છોડીને મૃત્યુલોકમાં પધાર્યા છો એટલે આ સત્સંગના ભાગ્યનો પાર નથી. તમારી સેવા-પૂજા માટે અક્ષરમુક્તો પણ પ્રગટ્યા છે. અક્ષરધામમાં રહેલા અહીં આવ્યા છે. જેને આપનું સ્વરૂપ ઓળખાયું તેને હૃદયમાં શાંતિ છે. હવે જે આવ્યા છે તેને ફરી આ પૃથ્વી પર આવવું ન પડે એવો આત્યંતિક મોક્ષ સૌનો કરજો. ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ કદી જીર્ણતાને પામે નહિ એવો ઉપાય કરજો.","e":"Ramanand Swami, having granted darshan to Shriharí, said, “You have left the great throne of Akshardham and come to the realm of death, and so there is no limit to the fortune of this satsang. For Your service and worship the Akshar-muktas too have become manifest. Those who dwell in Akshardham have come here. Whoever has recognised Your swarup has peace in his heart. Now grant to all those who have come such an ultimate moksha that they need never come again upon this earth. Make such provision that dharma, gnan, vairagya and bhakti may never fall into decay.","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":468,"k":"para","g":"“દેશો દેશમાં મંદિરો કરજો. તે મંદિરોમાં હંમેશાં સૌને તમારાં દર્શન થાય એવું કરજો અર્થાત્ તમારી મૂર્તિઓ પધરાવજો. તમારું સ્થાન સદાય રાખે એવો ધર્મવંશ (પૂર્વ કહેલા ધર્મ, જ્ઞાન, વૈરાગ્ય, ભક્તિ યુક્ત એવા એકાંતિક સંત) રહે.”","e":"“Build mandirs in land after land. In those mandirs make it so that all may always have Your darshan — that is, install Your murtis. Let there remain a lineage of Dharma — the ekantik Sant endowed with the dharma, gnan, vairagya and bhakti spoken of before — who will maintain Your place forever.”","s":["6/52/20-24"],"sv":["महा तखत छोरि इहाँ आये । सत्संग को अति भाग्य रहाये ॥\n\n तुमारी येवा-पूजा जोऊ । करने मुक्त इहां आवत सोऊ ॥\n\n रहेवत धाम में आवत आंहीं । तब ताके उर शान्ति रहा हि ॥\n\n फेर न आवनो परे यह ठोरा । एसो मोक्ष को करनो नोरा ॥\n\n धर्म-भक्ति वैराग्य हि जेहा । जिरनता कबउ न पावे तेहा ॥\n\n एसो कछु करो उपाया । तुमारी नजर में सबहि रहाया ॥\n\n मंदिर करब देश हि देशा । तुमारो दरश महिं होय हमेशा ॥\n\n तुमारो स्थान रखे सदाई । एसो एक धर्मवंश रहाई ॥"],"mt":false,"gl":null,"a":true},{"i":469,"k":"para","g":"કોઈ કીમિયાગર આવે ને અનંત ચમત્કાર બતાવે, શ્રીહરિની જેમ બોલે, ચાલે, હસે, જુએ. એમ અદલ દેશી લાવે, પણ શ્રીહરિના જંબુરિયા સંતો તેને કળી જતા ને લેશ પણ તેનામાં લોભાતા નહિ.","e":"Should some trickster come and display countless marvels, and speak, walk, laugh and look as Shriharí does, and so put on an exact likeness — yet the staunch sadhus of Shriharí would see through him and would not be lured by him in the least.","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":470,"k":"para","g":"હરિભક્તોમાં એક પર્વતભાઈ શ્રીહરિના એવા પાકા જંબુરિયા હતા. તેમની સર્વોપરીપણાની અને અવતારના અવતારીપણાની સમજણ શ્રીહરિએ વખાણી હતી. હરિ વિના તેમને બીજા અવતારનાં દર્શન થાય અને શ્રીહરિ કહે કે અવતાર એ હું જ છું તોપણ તે અવતારને વિષે પ્રેમ થાય નહિ. તેમને જ્યારે પૂર્વે થયેલા અનેક અવતારો દેખ્યામાં આવ્યા, ત્યારે પણ તેમાં રુચિ થઈ નહિ.","e":"Among the haribhaktas, one Parvatbhai was such a staunch devotee of Shriharí. Shriharí had praised his understanding of Shriharí’s supremacy and of His being the Avatari of the avatars. Though he might have darshan of other avatars apart from Hari, and though Shriharí might say that He Himself was that avatar, still no love would arise in him towards that avatar. Even when many avatars of the past came into his sight, no interest arose in him towards them.","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":471,"k":"para","g":"સ્વયં શ્રીહરિએ કહ્યું, “પર્વતભાઈ! આ અવતારોનાં દર્શન કરો.” તોપણ પર્વતભાઈ ડગ્યા નહિ. પર્વતભાઈની સમજણ ચકાસવા અવતારો પાંચ વર્ષ સુધી લાગ્યા રહ્યા. તે પર્વતભાઈની પાછળ પાછળ ફરતા. ખેતરમાં ખેતી કરવા જાય તો ત્યાં જતા.","e":"Shriharí Himself said, “Parvatbhai! Take the darshan of these avatars.” Yet Parvatbhai did not waver. To test Parvatbhai’s understanding, the avatars persisted for five years. They would follow after Parvatbhai. If he went to the field to farm, they would go there too.","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":472,"k":"para","g":"શ્રીહરિ તેમને પાંચ વર્ષ સુધી વઢ્યા ને કહ્યું, “પર્વતભાઈ! તમે અવતારોને કેમ માનતા નથી?”","e":"For five years Shriharí scolded him, saying, “Parvatbhai! Why do you not accept the avatars?”","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":473,"k":"para","g":"એમ શ્રીહરિ વઢતા ત્યારે પર્વતભાઈ હસી કાઢતા. પણ અવગુણ ક્યારેય લેતા નહિ. શ્રીહરિ બહુ વઢ્યા ત્યારે પર્વતભાઈ કહે, “મહારાજ! સર્વ કારણના કારણ આપ મળ્યા, પછી મારે પામવાનું ક્યાં બાકી રહ્યું? આવા અનંત આપનામાં સમાયા છે. આપનો પાર કોઈ લઈ શકતા નથી, બ્રહ્મા પણ માયામાં મૂંઝાઈ ગયા હતા. આપની માયા એવી અટપટી છે કે બીજાની મતિ મૂંઝાઈ જાય. હું તો એમ દૃઢપણે સમજું છું કે વૃક્ષની અનંત શાખાઓ હોય, નાની ડાળીઓ ને પાંદડાં ગણ્યાં ન ગણાય એટલાં હોય, એ બધો વિસ્તાર બાથમાં આવે નહિ, પણ એક થડને બાથ લીધી તો બધાંય બાથમાં આવી ગયાં ગણાય. પ્રભુ! મેં તો એવો વજ્ર સમાન દૃઢાવ કર્યો છે કે કરોડ ભુજાવાળા ભગવાન પ્રગટ થાય ને તમારી જેવું સામર્થ્ય દેખાડે તોપણ હું તમારાથી વિશેષ તેને લેખું નહિ, મનમાં અમે જેવો ઘાટ કરીએ છીએ તે પ્રમાણે તમે દર્શન આપો છો. પછી તમારા વિના અમે બીજી વાત શીદ કરીએ! કારણને છોડી કાર્યને વળગે તે હરિભક્ત હોય તોપણ ભોળો છે. તમારી પૂર્ણ કૃપા હોય તો સદાય તમારામાં એક મતિ રહે.","e":"When Shriharí scolded him thus, Parvatbhai would laugh it off. But he never took up any fault. When Shriharí scolded him greatly, Parvatbhai said, “Maharaj! I have obtained You, the cause of all causes; what then remains for me to attain? Infinite such as these are contained within You. No one can reach Your limit; even Brahma was bewildered in maya. Your maya is so intricate that another’s mind is bewildered by it. I understand it firmly thus: a tree may have infinite branches, and its small twigs and leaves beyond counting, and all that spread cannot be taken into one’s arms; but if one takes the single trunk into one’s arms, then all of it is counted as taken. Lord! I have made a resolve firm as adamant: that even if a Bhagwan with ten million arms were to become manifest and display power like Yours, still I would not count him greater than You. Whatever thought we form in our minds, accordingly You grant us darshan. Then why should we speak of anything but You! One who abandons the cause and clings to the effect, though he be a haribhakta, is simple. If Your full grace be upon me, may my mind remain forever one-pointed upon You.","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":474,"k":"para","g":"“તમારું સામર્થ્ય અપાર છે. દેખ્યાથી પાર પમાતું નથી. તમારા એક એક રોમ છિદ્રમાં અનંત કોટિ બ્રહ્માંડ રહ્યાં છે. એ અનંત બ્રહ્માંડોમાં બ્રહ્મા આદિ એક એકથી અપાર રહ્યા છે, એ બધાનું સામર્થ્ય તમારા થકી છે.","e":"“Your power is boundless. Its limit is not reached by seeing. In each single pore of Yours reside infinite millions of brahmands. In those infinite brahmands, Brahma and the rest reside, each beyond measure; and the power of all of them is from You.","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":475,"k":"para","g":"“એક બ્રહ્માનું સામર્થ્ય પણ પાર પામી શકાતું નથી તો આપના સામર્થ્યની શી વાત કરવી! જેમ ચિંતામણિમાં કોઈ પદાર્થ દેખ્યામાં આવતો નથી, પણ પદાર્થમાત્ર તેમાં રહ્યા છે તે બધા સમય આવ્યે પ્રગટ થાય છે. એમ આપનું સામર્થ્ય આપ ઢાંકીને વર્તો છો, પણ સમયે પ્રગટ થઈ આવે છે.”","e":"“The power of even a single Brahma cannot be fathomed — then what is to be said of Your power! Just as no object is seen within a chintamani, and yet every object resides within it and all of them become manifest when the time comes, so You go about with Your power concealed, but in due time it becomes manifest.”","s":["8/25/24-40"],"sv":["हरि विन और हरि होई आवे । चमत्कार अनंत देखावे ॥\n\n बाजीगर सम जाने ताकुं । विमुख करिके लेखे वाकुं ।\n\n हरि जनु बोलत तेहि संग, देशि लावत तेसि ।\n\n हरि के जंबुरिये संत हि, तामें लोभात न लेसि ॥\n\n हरिजन में जो पर्वतभाई, जंबुरिये भये एक ।\n\n हरि विन हरि अवतार हि, देखे में आवे अनेक ॥\n\n हरि कहे में हु तेह, तोहु न डगे मन लवलेश कबु ।\n\n अवतार सब हि जेह, पर्वतभाई के पिछे हि फिरत ॥\n\n खेत में खेति करत, पर्वतभाई सो जाई कर ।\n\n अवतार सो पिछे फिरत, पांच वर्ष लग रहेउ इमि ॥\n\n पांच वर्ष लग वढे हरि ताहि । अवतार कुं क्युं न मानत रहा हि ॥\n\n हरि वढत तब हसत तेउ । अवगुन कबहु न लेवत एहु ॥\n\n बोत वढत तब बोलत तेहा । सब कारन तुम मिले हो एहा ॥\n\n कारन में कारन रहे अनंता । तुमारो पार हि कोउ न लहंता ॥\n\n हम हें जीव एक मति वारे । तुमारे सामर्थ्य को नहि पारे ॥\n\n एक तरु के थड सें जोउ । डारे पात फल अनंत हि होउ ॥\n\n सो सब नहि बाथ में आवे । तरु विस्तार अपार रहावे ॥\n\n थड कुं लिये बाथ हि जबहु । कोउ बाहिर न रहे तबहु ॥\n\n हमारे थड तुम हि मनाये । तुम में थड सब हि जो आये ॥\n\n दृढाव करे हम वज्र समाना । कोटिभुज आवे भगवाना ॥\n\n तुमारो सो सामर्थ्य हम देखे । तुमसे विशेष कोउ न लेखे ॥\n\n मन में करत हम घाट हि जेसा । तर्त दरश देत तुम तेसा ॥\n\n तुम बिन कहत न बात हि ओरा । हरिजन भये तदपि रहे भोरा ॥\n\n कारन छोड कार्य में धावे । एसि मति जीय की रहावे ॥\n\n पुरन कृपा जब होत तुमारी । तुम में एकमति रहे हमारी ॥\n\n सामर्थ्य तुमारे अपार हि, देखत न आवे पार ।\n\n अनंत कोटि ब्रह्मांड हि, एक रोम रहे द्वार ॥\n\n ब्रह्मा अनंत ब्रह्मांड में, एक एक से अपार ।\n\n तुम सें सामर्थ्य ताहि को, देखे में न आवत पार ॥\n\n चिंतामनि के मांहि, पदार्थ एक न देखात तेहि ।\n\n ता महिं सब हि रहा हि, समय में आत देखाई सब ॥"],"mt":false,"gl":null,"a":true},{"i":476,"k":"para","g":"શ્રીહરિ તો એકના એક જ છે. તેમના ભજનથી જીવનાં પાપ બળી જાય અને અક્ષર જેવી મોટાઈ આવે. શ્રીહરિના બળથી જેવો સંકલ્પ ધારે તેવો સિદ્ધ થાય અને અનંત બ્રહ્માંડ રચવાનું સામર્થ્ય આવે. જેવા સમર્થ શ્રીહરિને જાણે તેવો પોતે બને, પણ શ્રીહરિ તો તેનાથી અપારના અપાર જ છે. એમ શ્રીહરિને જાણીને પોતે બ્રહ્મ સમાન થાય તોપણ શ્રીહરિનો ડર રાખી સંત-હરિભક્તોના દાસ થઈ અણુ પર્યંત કોઈ જીવને દુખવે નહિ, ત્યારે તેને અક્ષર જેટલું સામર્થ્ય પ્રાપ્ત થાય છે.","e":"Shriharí is the one and only. By worshipping Him the sins of the jiva are burnt away and greatness like that of Akshar comes. By the strength of Shriharí, whatever resolve one forms is accomplished, and the power to create infinite brahmands comes. As powerful as one knows Shriharí to be, so does one become oneself — yet Shriharí remains boundlessly beyond that. Even when, knowing Shriharí thus, one becomes the equal of Brahman, still one keeps the awe of Shriharí and, becoming the servant of the sadhus and haribhaktas, does not hurt any jiva by so much as an atom; and then power equal to Akshar’s is attained by him.","s":["9/24/29-35"],"sv":[],"mt":false,"gl":null,"a":true},{"i":477,"k":"para","g":"શ્રીહરિએ ફણેણીના હરિજનોને કહ્યું, “અમારે તો તમારી ઉપર તેવો ને તેવો જ ભાવ છે, પણ દેશદેશમાં હરિભક્તો થયા છે તે ઠેર ઠેર ખેંચી જાય છે. એક એક રાત રહીએ તોપણ પાર આવતો નથી.” ત્યારે હરિજનો કહે, “તમે સાચું કહો છો. હરિભક્તો માટે જ તમે પ્રગટ થયા છો. મોક્ષનું કામ તમારા વિના બીજા કોઈ દેવ-મનુષ્યથી બને તેમ નથી. જે જે કાંઈ આશ્ચર્ય દેખાય છે તે તમારામાં જ છે. બીજામાં જો કોઈ સામર્થ્ય માને તો તેને તમારા સ્વરૂપનો નિશ્ચય નથી, એવી અમારી સમજણ છે. વળી, તમારી મૂર્તિમાં અને બીજા અનંત અવતારમાં સૂર્ય અને મશાલ જેટલો ફેર છે. હુતાશની જેટલો અગ્નિ હોય પણ સૂર્યને પહોંચે નહિ. ગિરનાર જેટલો હોય તોપણ તે પ્રકાશ સૂર્યના પ્રકાશમાં સમાઈ જાય. સૂર્ય વિનાના તારા હોય તેમાં ચંદ્ર મોટો ગણાય, પણ સૂર્ય ઉદય થતાં લીન થઈ જાય. ચંદ્ર, તારા અને અગ્નિમાં પ્રકાશ છે તે સૂર્યનો છે એવી અમારી બુદ્ધિ છે.”","e":"Shriharí said to the harijans of Phaneni, “Our devotion towards you is exactly as it always was; but haribhaktas have arisen in land after land, and they draw Us away in every direction. Even were We to stay one night with each, there would be no end of it.” Then the harijans said, “You speak truly. It is for the haribhaktas alone that You have become manifest. The work of moksha cannot be done by any other deity or human being but You. Whatever wonder is seen anywhere, it is in You alone. If a person believes there is power in another, then he has no nishchay of Your swarup — such is our understanding. Moreover, between Your murti and the infinite other avatars there is as much difference as between the sun and a torch. There may be a fire as great as the Holi bonfire, yet it does not reach the sun. It may be as great as Girnar, and still that light is absorbed into the light of the sun. Among the stars, when there is no sun, the moon is counted great, but at the rising of the sun it is absorbed. Our understanding is that the light in the moon, the stars and fire is the sun’s.”","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":478,"k":"para","g":"શ્રીહરિ કહે, “જેમાં જેટલો પ્રતાપ છે તે છુપાવ્યો છુપાતો નથી. જેમ કસ્તૂરી ઢાંકી ઢંકાતી નથી તેમ.”","e":"Shriharí said, “Whatever majesty resides in a person is not hidden by hiding it — just as musk is not concealed by covering it.”","s":["11/14/21-37"],"sv":["तुमारी मूर्ति अवतार अनंता । अंतर में देखत रहंता ॥\n\n सूर्य मशाल में फेर हि जितना । तुम अरु अवतार में फिर हें तितना ॥\n\n सूर्य में प्रताप रहे हें जेसा । सबके देखे में आवत तेसा ॥\n\n तेसे हें हरि प्रताप तुमारा । कहे न आवे कबु मुख से बारा ॥\n\n श्रीहरि कहे हरिजन से, प्रताप जामें जेतो ।\n\n छपाये छपि न रहत हें, कस्तूरी गंध तेतो ॥"],"mt":false,"gl":null,"a":true},{"i":479,"k":"para","g":"પરબ્રહ્મ શ્રીહરિ જ્યારે અક્ષરધામથી અવતાર ધારણ કરે છે ત્યારે પૂર્વે થયેલા અવતારોનો પ્રતાપ પોતાની મૂર્તિમાં ખેંચી લે છે ને એ સર્વેના પ્રતાપને ઢાંકીને પોતાના પ્રતાપનું સ્થાપન કરે છે. એકાંતિક ભક્ત તેનો નિશ્ચય કરી સર્વોપરી જાણે છે.","e":"When Parabrahman Shriharí takes an avatar from Akshardham, He draws the majesty of the avatars of the past into His own murti, and covering the majesty of all of them, establishes His own majesty. The ekantik devotee gains the nishchay of this and knows Him as the highest of all.","s":["11/17/38-40"],"sv":["अवतार धरत हरि जब हि, आगे के प्रताप ।\n\n खेंचे लेवत निज मूर्ति में, तापर थापत आप ॥\n\n सर्वोपरि अवतार, जो भक्त कुं मिले जेहि ।\n\n ऐसे करे निरधार, एकांतिक जो जो भक्त तेहि ॥"],"mt":false,"gl":null,"a":true},{"i":480,"k":"para","g":"શ્રીહરિનો પ્રાગટ્યોત્સવ ભક્તોએ ફણેણીમાં સં. ૧૮૬૩માં કર્યો. તે દિવસે સૌએ નિર્જળ ઉપવાસ કર્યો હતો. ભજનમગ્ન રહી રાત્રિએ જાગરણ કર્યું. કારણ, સૌ શ્રીહરિને સર્વોપરી સમજતા હતા. કોઈ શ્રીહરિને સર્વોપરી કહે, પણ દેહાભિમાન હોય તો તે જ્ઞાન કથનમાત્ર છે. બુદ્ધિશાળી લોકો તેને સ્વીકારતા નથી. શ્રીહરિનો નિશ્ચય પોતાને દૃઢ થયો છે એવી અપાર વાતો લોકોમાં કરી દેખાડે ને લોકોને તેના પર ભાવ થાય એટલું ફળ મળે. પરંતુ શ્રીહરિને યથાર્થપણે સર્વોપરી જાણતા હોય એવા સંત તો પિંડ-બ્રહ્માંડથી પોતાને પર જાણીને વર્તતા હોય. જે જે વાત કરે તેમાં પણ દેહાભિમાન અને બ્રહ્માંડ-અભિમાન તજીને વર્તવાની વાત આવે. તનનું સન્માન તો કદી ઇચ્છે જ નહિ. પોતાના શરીરને તો તૃણ જેવું ગણે. લેશપણ રાગ-દ્વેષ કોઈ સાથે રાખે નહિ. તેને ઈર્ષ્યા-અસૂયા કોઈ પર હોય નહિ. એક ભગવાન શ્રીહરિનાં ચરણકમળમાં પરમ અનુરાગ દૃઢ કરીને રાખતા હોય. કોઈ અપમાન કરે તેનું લેશ દુઃખ તેને ન હોય. સમજણનું બળ અગાધ હોય. પિંડ-બ્રહ્માંડથી ન્યારા વર્તે. દુઃખનો લેશ સ્પર્શ નહિ એવા હોય. માયામાં પડેલા લોકોનો જેટલો કંઈ વ્યવહાર છે તેને ઢીંગલાં-ઢીંગલીનો ખેલ સમજે. જેમ જેમ પોતાના શરીરમાં અતિશય દુઃખ પડે, તેમ તેમ મહા સુખ થયું માને. દુઃખમાં ભગવાનનો અપાર ગુણ ગ્રહણ કરે. આવો ઊંચો વિચાર જેને હાથ આવ્યો છે એવા સંત પાતાળથી પ્રકૃતિ-પુરુષના લોક સુધીનાં સુખમાત્રને ઝેર સમજે છે. અધિક સુખને અધિક ઝેર માને છે. સ્વપ્નમાં પણ તેને સત્ય માને નહિ. સર્પ, અગ્નિ અને ઝેરને ભૂલમાં પણ કોઈ સુખરૂપ માની અડતું નથી, તેમ ઊંચા પ્રકારના વિષયોને વિષે વિષભાવના રહે અને દેહે કરીને વિષયનો યોગ થવા ન દે એવી સમજણ જેને આવી તેનો સાચો નિશ્ચય કહેવાય.","e":"The devotees celebrated the festival of Shriharí’s manifestation at Phaneni in Samvat 1863. On that day all kept a waterless fast. Absorbed in worship, they kept vigil through the night — because all understood Shriharí to be the highest of all. Someone may call Shriharí the highest, but if he has body-consciousness, then that gnan is words only. People of intelligence do not accept it. He may display before people boundless talk of how firm his nishchay of Shriharí has become, and he receives only as much fruit as that people feel devotion towards him. But a Sant who truly knows Shriharí to be the highest of all conducts himself knowing himself to be beyond body and brahmand. In whatever matter he speaks, there too comes the matter of conducting oneself having abandoned the pride of the body and the pride of the brahmand. He never desires honour for the body at all. He counts his own body as no better than a blade of grass. He keeps not the least attachment or aversion towards anyone. He has no envy or ill-will towards anyone. He keeps supreme love firmly fixed at the lotus feet of the one Bhagwan Shriharí. If anyone dishonours him, he has not the least misery from it. The strength of his understanding is unfathomable. He conducts himself apart from body and brahmand. He is such that not the least misery touches him. All the dealings of people sunk in maya he understands as a game of dolls. The more exceedingly his body suffers, the more he counts it as great happiness. In misery he takes up the boundless virtue of Bhagwan. A Sant into whose hand such a lofty understanding has come regards every happiness from Patal up to the realm of Prakruti-Purush as poison. The greater the happiness, the greater the poison he counts it. Not even in a dream does he hold it to be real. Just as no one, even by mistake, holds a serpent, fire or poison to be a source of happiness and touches it, so whoever has attained the understanding by which a sense of poison remains towards the highest kinds of vishays, and who does not let the body come into contact with the vishays — his is called a true nishchay.","s":["11/18/1-13"],"sv":["रामनौमि की रात्रि में, जाग्रन सारी रात ।\n\n प्रेमी भक्त जो करत भये, सर्वोपरि जानत वात ॥\n\n सर्वोपरि हरि कुं कहत हें, तन पर अधिक तान ।\n\n कथनमात्र सो ज्ञान है, मानत नहि बुद्धिमान ॥\n\n हरि को निश्चय अपार, जनकुं देखावे वात कर ।\n\n ता पर रखे जन प्यार, इतनो फल तेहि मिले रहेउ ॥\n\n जो जो करे वात, तन ब्रह्मांड से पर जेहि ।\n\n सन्मान तन को न च्हात, इतनो फल सो माने तेहि ॥\n\n सर्वोपरि हरि कुं जानि । साचे जो जो संत विज्ञानी ॥\n\n निज तन गिनत तृण तेहि जेसा । राग द्वेष न कोई से लेशा ॥\n\n ईर्ष्या असूया जन पर त्यागे । पद पंकज हरि के अनुयागे ॥\n\n अपमान करे कोउ दुःख न ताको । समझ बल अगाध हि वाको ॥\n\n तन ब्रह्मांड से वरते बारा । कबु तेहि दुःख न आवे लगारा ॥\n\n मायिक जन को व्यवहार हि जेता । बालक खेल सम समझे तेता ॥\n\n बुद्धिवंत यह संत अपारा । ऐसे संत न भये कोउ वारा ॥\n\n वर्णि हरिजन कहावत जेते । समझ अपार हि पाये तेते ॥\n\n ज्युं ज्युं तन में परे अति दुःखा । त्युं त्युं मानत भयेउ सुखा ॥\n\n दुःख में हरिगुन गहत अपारा । एसे पायेउ पर विचारा ॥\n\n तन ब्रह्मांड से वर्तना न्यारा । ऐसी समझ जन पाये हजारा ॥\n\n समझ रूप सुख सागर जेहा । आश्रित कुं हरि देखाये तेहा ॥\n\n समझ करि जन मगन रहावे । हरि विन ओर में नहि लोभावे ॥\n\n पाताल से पुरुष लग हि जोउ । जो जो सुख कहावत सोऊ ॥\n\n अधिक से अधिक सुख हि जेता । अधिक अधिक विष समझत तेता ॥\n\n श्रीहरि की एसि समझ देखाई । यह सुख से न लोभावे ताई ॥\n\n स्वप्न में सत्य न माने तेहि, असत जाने जो भोग ।\n\n सर्प अनल विष को जिमि, तन करि करत न जोग ॥"],"mt":false,"gl":null,"a":true},{"i":481,"k":"para","g":"સ્વામિનારાયણનું નામ ભજે તે સર્વ સંત હરિભક્ત દિવ્ય છે. અનંત અપાર અવતાર થઈ ગયા તે સર્વે સ્વામિનારાયણમાં આવી ગયા. બધાનું સામર્થ્ય આમાં આવી ગયું. આ શ્રીહરિથી પર કોઈ નથી. જે આનાથી પર કહે છે તેને વિવેક નથી, અને કોઈ અવતારનો દ્રોહ પણ ન કરવો. જે દ્રોહ કરે છે તેને એટલી કસર છે, ને તે અસુરમતિનો ગણાય. દ્રોહ તજી પ્રગટ શ્રીહરિમાં સર્વ પ્રકારે જોડાઈ જવું. અન્યનો દ્રોહ કર્યા વિના અતિ હિતની વાત દૃઢપણે કરે તેની સંતમતિ કહેવાય છે. તેની સમજણ સર્વોપરી છે. તે તો અવતારોના ભક્તોને પણ દિવ્યભાવથી જુએ છે.","e":"All the sadhus and haribhaktas who worship the name of Swaminarayan are divine. All the infinite and boundless avatars that have occurred are contained within Swaminarayan. The power of all of them is contained in this. There is none beyond this Shriharí. Whoever calls another beyond Him has no vivek; and one should not betray any avatar either. Whoever betrays has that much deficiency, and is counted as of demonic understanding. Abandoning betrayal, one should join oneself in every way to the manifest Shriharí. One who, without betraying another, speaks firmly of what is most beneficial is said to be of the Sant’s understanding. His understanding is the highest of all. He looks even upon the devotees of the avatars with divyabhav.","s":["11/42/17-21"],"sv":["हरिजन संत सो दिव्य कहावे । स्वामिनारायण मुख जो गावे ॥\n\n अवतार भये अनंत अपारा । इनसे कोउ न देखे पारा ॥\n\n सबको सामर्थ्य कहावत जेतो । इनमें सबहि समझे तेतो ॥\n\n इनसे परे न देखे एका । परे कहे ताकुं न विवेका ॥\n\n अवतार को द्रोह करे ज्यां लगहि । सत्संग करने कसर त्यां लगहि ॥\n\n अवतार के द्रोह करे जितना । असुर मति सो कहावे तितना ॥\n\n द्रोह तजी अवतार को जेता । प्रगट में तोडे तान हि तेता ॥\n\n द्रोह विन करे वात हि जेहि । अति हित लाई के तेहि ॥\n\n संत मति ताकि सो कहावे । सर्वोपरि तेहि समझ रहावे ॥\n\n दिव्यभाव करि समझे तेते । तेसे अवतार के भक्त हि जेते ॥"],"mt":false,"gl":null,"a":true},{"i":482,"k":"para","g":"શ્રીહરિની કૃપાથી સમાધિ થતી ત્યારે તે સમાધિવાળા જનોને અલૌકિક ભૂમિકાઓ દેખાતી, તેમાં વૈકુંઠ, ગોલોક આદિ ધામ જોવામાં આવતાં. તે સર્વેથી પર અક્ષરધામ જે શ્રીહરિનું સર્વોપરી ધામ છે તે દેખ્યામાં આવતું. આ લોકમાં શ્રીહરિની અતિ નિકટ રહેતા નિષ્કામ ભક્તો પણ આ બધાં ધામોને હૃદયમાં દેખતા.","e":"When by the grace of Shriharí samadhi occurred, those who experienced that samadhi saw transcendental realms, and among them Vaikunth, Golok and the other abodes came into view. Beyond all of these, Akshardham — which is the highest abode of Shriharí — came into view. In this world too, the nishkam devotees who stayed very close to Shriharí would see all these abodes within their hearts.","s":["11/88/25-26"],"sv":["समाधिवारे जन जेहि, देखत भये सब तेह ।\n\n ता विन जन देखत नहि, अलौकिक वात हे एह ॥\n\n वैकुंठ गोलोक धाम जो, सर्वोपरि अक्षरधाम ।\n\n श्रीहरि समीप रहत तेहि, देखत जन निष्काम ॥"],"mt":false,"gl":null,"a":true},{"i":483,"k":"para","g":"બ્રહ્મનિષ્ઠ પુરુષમાં ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ અખંડ રહે છે. તે ભગવાનને સાકાર માનીને ઉપાસે છે. પંચતત્ત્વ જીવ, ઈશ્વર, માયા, બ્રહ્મ અને પરબ્રહ્મને અનાદિ માને છે. મોક્ષની અનંત વાતો પ્રવર્તે છે તેમાં મૂળમાં આ પાંચ તત્ત્વ છે. બીજી વાતો શાખા ને પાંદડાં છે. અક્ષરબ્રહ્મ ધામ તેનું પુષ્પ છે અને પરબ્રહ્મ પુરુષોત્તમ સાકાર રૂપે તેનું ફળ છે.","e":"In a brahmanishtha person, dharma, gnan, vairagya and bhakti remain unbroken. He worships Bhagwan knowing Him to possess form. He holds the five entities — jiva, ishwar, maya, Brahman and Parabrahman — to be eternal. Among the infinite matters concerning moksha that are current, these five entities are the root. The other matters are branches and leaves. The abode of Aksharbrahman is its flower, and Parabrahman Purushottam in a form possessed of shape is its fruit.","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":484,"k":"para","g":"પુરુષોત્તમ ભગવાન અનંતકોટિ બ્રહ્માંડમાં એક સાથે તનુ ધારણ કરીને દર્શાય છે, પરંતુ પોતાનું અક્ષરધામનું તખત ક્યારેય ત્યાગ કરતા નથી. એમાં અનંત યોગકળાઓ રહેલી છે કે જેનો બ્રહ્મા વગેરે પણ પાર પામી શકતા નથી. મોટા પંડિત, પુરાણી કે તત્ત્વજ્ઞાની હોય અથવા મોટા મોટા સિદ્ધ કે સમાધિનિષ્ઠ હોય તોપણ તેની મતિમાં એ પરબ્રહ્મ આવતા નથી, પરંતુ અપાર ભક્તિવાળાના બંધનમાં તે આવે છે. ભક્તિ વિના તે કોઈને વશ થતા નથી એવા મહા બળિયા છે. આ વાત પણ જેને સત્સંગ હોય ને હૃદયની ભક્તિ હોય તેને જ માન્યામાં આવે છે.","e":"Purushottam Bhagwan takes a body in infinite millions of brahmands at one and the same time and is seen there, and yet He never abandons His throne in Akshardham. In this reside infinite yogic skills, of which even Brahma and the rest cannot reach the limit. Though a person be a great pandit, a puranic or a philosopher, or one of the great siddhas or those established in samadhi, still that Parabrahman does not come within his understanding; but He does come into the bondage of one who has boundless bhakti. He is so exceedingly mighty that without bhakti He is subject to no one. And this matter too comes to be accepted only by one who has satsang and bhakti of the heart.","s":["12/54/6-23"],"sv":["धर्म भक्ति वैराग्य हुं ज्ञाना । सदा साकार माने भगवाना ॥\n\n पंच तत्त्व कहावत जेहु । सर्वोपरि हम माने हें तेहु ॥\n\n अनंत बातन के मूल हे एहि । वात और शाखा पत्र हे तेहि ॥\n\n ताके पुष्प हे अक्षरधामा । फल साकार हे श्रीघनश्यामा ॥\n\n धाम को त्याग सो करत न कबहु । अनंत तन धरत तौ तबहु ॥\n\n जोगकला हें तामें अनंता । ब्रह्मादिक पार न लहंता ॥\n\n पंडित पुरानी और हि ज्ञानी । बडे बडे मुक्त सिद्ध ध्यानी ॥\n\n अकल कले में कबहु न आवे । भक्ति होवे ताकु देखावे ॥\n\n भक्ति विन वश होवे न ओरा । एसे हें अकल बड़ जोरा ॥\n\n तुम नजर कर देखो आगे । ऐसे ये नहि आवत लागे ॥\n\n भक्तिवंत होय जेहि पूरा । सो नहि देखत नजर से दूरा ॥\n\n सत्संग भक्ति विन जन जेते । वात माने में न आवत तेते ॥"],"mt":false,"gl":null,"a":true},{"i":485,"k":"para","g":"સંતદાસ નામે શ્રીહરિના સાધુ સદેહે જ બદરિકાશ્રમ, શ્વેતદ્વીપ વગેરે ધામોમાં જતા ને આવતા. શ્રીહરિ કરિયાણામાં વિરાજતા હતા તે સમયે સંતદાસ ત્યાં આવ્યા. સંતદાસને જે કોઈ સંત-હરિભક્ત જેવો પ્રશ્ન પૂછે તેવો ઉત્તર કરી દેતા. બધાં ધામોની વાત કરી છેલ્લે કહેતા કે, “એ સર્વેથી અધિક અહીં છે. આ શ્રીહરિની મૂર્તિ આગળ પૂર્વે થયેલા અન્ય અવતારોનું સામર્થ્ય અને સુખ કંઈ હિસાબમાં નથી. આ વાત ગ્રંથોમાં કહી છે તેનાથી પણ માલૂમ પડે છે. માટે તમને જે પ્રાપ્તિ થઈ છે તેવી કોઈને નથી થઈ. સર્વોપરી હરિની આ વાત પાત્ર વિના ટકતી નથી, જેમ કાચી માટીના ઘડામાં નીર ટકે નહિ, નીરનો સ્વભાવ એવો છે કે પાક્યા વિનાના પાત્રમાં ન રહે. આશરો કર્યો હોય ને દેશકાળ ફરે તોપણ એકમતિ રહે તે મતિ પાકી જાણવી. પાકી મતિવાળાને સર્વોપરી વાત કરતાં ડર ન રહે. તમારી બુદ્ધિ માયિક છે તેથી ડરીને કહેવું પડે છે. પરાધીન દશામાં પણ જેની મતિમાં ફેર ન પડે તેને કહેલી વાત સમાસ કરે. એવી મતિ શ્રીહરિમાં જ્યારે થાય ત્યારે તેને સિદ્ધમતિ થઈ જાણવી. તેને જેટલી વાત કરીએ તે બધી સમાસ કરે.”","e":"A sadhu of Shriharí named Santdas would go and come in his very body to Badrikashram, Shvetdwip and other abodes. At the time when Shriharí was seated at Kariyani, Santdas came there. Whatever question any sadhu or haribhakta put to Santdas, he would give the answer to it. Having spoken of all the abodes, at the last he would say, “Greater than all of them is here. Before this murti of Shriharí, the power and happiness of the other avatars of the past are of no account whatever. This matter is evident also from what is said in the scriptures. Therefore the attainment that has come to you has come to no one else. This matter of the supreme Hari does not hold without a fit vessel — just as water does not hold in a pot of unbaked clay; such is the nature of water, that it will not stay in an unbaked vessel. Know that mind to be ripe which, having taken refuge, remains one-pointed even though place and time may change. One of ripe mind has no fear in speaking of the highest matter of all. Your intelligence is mayik, and so it must be spoken with caution. What is spoken to one whose mind does not alter even in a state of dependence takes hold in him. When such a mind is formed towards Shriharí, know it to have become an accomplished mind. Whatever we may say to such a one takes hold in him entirely.”","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":486,"k":"para","g":"એમ કહી સંતદાસજીએ કહ્યું, “પૃથ્વી, જળ, તેજ, વાયુ, આકાશ, મહત્તત્ત્વ, પ્રધાનપુરુષ ને પ્રકૃતિપુરુષ - ઉત્તરોત્તર દશ-દશ ગણા અધિક છે. તે સઘળા લોક માયામય છે. માયાથી પર અક્ષરધામ છે. તે અક્ષરધામને આધીન અન્ય બધા લોક છે. આ હું તમને પ્રત્યક્ષ દેખીને કહું છું. તમને જે કંઈ અધિક વાત લાગતી હોય તો તે આ સત્સંગમાં શ્રીહરિ સ્વયં છે. જે તમને મળ્યા છે તેથી અધિક અક્ષરધામ પર્યંત બીજે ક્યાંય નથી. અક્ષરબ્રહ્મ ને અનંતકોટિ અક્ષરમુક્તો સ્વયં ત્યાં ધામમાં રહ્યા થકા આ પરબ્રહ્મ શ્રીહરિના વચનમાં વર્તે છે. તો પછી અન્ય લોક ને તેના અધિપતિ દેવતાઓ, મનુષ્યો એ બધાની વાત શી કરવી!","e":"Saying this, Santdasji said, “Earth, water, fire, wind, space, mahattattva, Pradhan-Purush and Prakruti-Purush — each in succession is ten times greater than the last. All those realms are made of maya. Beyond maya is Akshardham. All other realms are subject to that Akshardham. This I tell you having seen it directly. If anything seems to you a greater matter, it is that Shriharí Himself is present in this satsang. Than He whom you have obtained, there is nothing greater anywhere, up to Akshardham itself. Aksharbrahman and infinite millions of Akshar-muktas, dwelling there in that abode, themselves conduct themselves according to the word of this Parabrahman Shriharí. Then what is to be said of the other realms and their presiding deities and of human beings!","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":487,"k":"para","g":"“પ્રકૃતિપુરુષ, અનંતકોટિ પ્રધાનપુરુષ, અનંતકોટિ બ્રહ્માંડો, તેના અધિપતિઓ, બ્રહ્મા, ભવ, ઇન્દ્ર, ચંદ્ર, સૂર્ય આદિ દેવતાઓ, રાધા-લક્ષ્મી આદિ જેવી અનંત શક્તિઓ, નારદ, શુક, સનકાદિક જેવા મુનિઓ જેમની આજ્ઞા કદી લોપતા નથી, એવા સર્વનિયંતા મહાસમર્થ શ્રીહરિ આ લોકમાં ક્યારેય પધાર્યા નથી, તે આ અવસરે પ્રગટ થયા છે. તેમનાં દર્શન પ્રાપ્ત થયા તેનાં પુણ્યનો પાર નથી, અન્ન-જળ, દૂધ, ફળ-ફૂલનો ત્યાગ કરી કોટિ કલ્પ પર્યંત કોઈ તપ કરે તોપણ શ્રીહરિનાં એકવાર દર્શન કરનારાની તોલે ન આવે.","e":"“Prakruti-Purush, infinite millions of Pradhan-Purushes, infinite millions of brahmands and their presiding lords, deities such as Brahma, Bhav, Indra, Chandra and Surya, infinite powers such as Radha and Lakshmi, and munis such as Narad, Shuk and Sanakadik — none of whom ever transgress His command — that controller of all, the supremely powerful Shriharí, has never before come to this realm; and on this occasion He has become manifest. There is no limit to the merit of those who have obtained His darshan. Though one were to renounce food and water, milk, fruit and flowers, and perform austerities for ten million kalpas, still it would not come near the equal of one who has had the darshan of Shriharí even once.","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":488,"k":"para","g":"“શ્રીહરિ સર્વથી પર સર્વોપરી અવતારી પુરુષોત્તમ છે આ વાત સર્વેએ દૃઢ કરી લેવી. આ દૃઢતા(નિશ્ચય)માં જેટલી કસર રહી તે ક્યારેય મટવાની નહિ. મુખ્ય તો આ વાત મોક્ષ માટેની છે. તે તમારાં હિતની જાણીને મેં કહી છે.”","e":"“That Shriharí is beyond all, the highest of all, the Avatari Purushottam — this matter all should make firm. Whatever deficiency remains in this firmness of nishchay will never be removed. Chiefly, this matter is for the sake of moksha. I have spoken it knowing it to be for your good.”","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":489,"k":"verse","g":"‘તુમહિ મિલે ભગવાન, અક્ષરધામ પ્રજંત હિ.","e":"‘Tumahi mile Bhagvān, Akshardham prajant hi.","s":[],"sv":[],"mt":false,"gl":"[You have obtained that Bhagwan than whom, up to Akshardham itself,]","a":true},{"i":490,"k":"verse","g":"અધીન નહિ હેં આન, કહત હું મેં દેખકર.’","e":"Adhīn nahi hen ān, kahat hun main dekhkar.’","s":["14/33/14-40"],"sv":[],"mt":false,"gl":"[…there is no other to whom He is subject — this I say having seen it.]","a":true},{"i":491,"k":"para","g":"સર્વોપરી પુરુષોત્તમ ભગવાન કોશલ દેશમાં પ્રગટ થઈ, મુખ્ય મુખ્ય પર્વત, વન, તીર્થમાં દર્શન આપી, અનેક જીવોનો ઉદ્ધાર કરી રહ્યા છે. સર્વના કારણ હોય તે ધારે તે થાય છે. સમર્થ હોય તે અણુને મેરુથી અધિક કરે છે ને મેરુને અણુથી અલ્પ કરે છે.","e":"The supreme Purushottam Bhagwan, having become manifest in the land of Koshal, is granting darshan in the principal mountains, forests and places of pilgrimage, and is redeeming many jivas. Whatever He who is the cause of all intends comes to pass. He who is powerful makes an atom greater than Meru and makes Meru smaller than an atom.","s":["15/23/12,25"],"sv":[],"mt":false,"gl":null,"a":true},{"i":492,"k":"para","g":"શ્રીહરિ અક્ષરધામના ધામી છે, તેઓ અનંત સુખમય મૂર્તિ છે, અનંત ઐશ્વર્યોથી યુક્ત છે. અક્ષરધામના સુખનો કદાપિ નાશ નથી થતો એવું અવિનાશી સુખ છે. એવા શ્રીહરિને પ્રસન્ન કરવા મૃત્યુલોકમાં હરિજન બાઈ-ભાઈઓ મન, કર્મ વચને નિષ્કપટ ભાવે સત્સંગ કરે છે. કેટલાક પુરુષોએ નારીનો ત્યાગ કરી દીધો તો કેટલીક બાઈઓએ પુરુષોનો ત્યાગ કરી દીધો. કેટલાક સંસાર ત્યજીને ત્યાગી સાધુ થઈ ગયા છે ને પંચવિષયથી ડરીને દૂર રહે છે. શ્રીહરિની મરજીથી સ્ત્રી અને પુરુષ જુદાં જ્યાં સુધી રહેશે ત્યાં સુધી સર્વે બ્રહ્માંડો શ્રીહરિને ધન્ય ધન્ય કહી બિરદાવશે.","e":"Shriharí is the lord of Akshardham; He is a murti of infinite happiness and is endowed with infinite majesties. The happiness of Akshardham is never destroyed — such is that imperishable happiness. To please such a Shriharí, the harijan women and men in this realm of death do satsang with a sincere disposition in thought, word and deed. Some men have renounced women, and some women have renounced men. Some have renounced worldly life and become tyagi sadhus, and keep away in fear of the panchvishays. So long as women and men remain separate according to the wish of Shriharí, so long will all the brahmands praise and extol Shriharí.","s":["15/45/20-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":493,"k":"para","g":"શ્રીહરિને જે ભક્ત સર્વોપરી જાણે છે, તેટલો તે સર્વોપરી થાય છે. ભગવાન પણ જે ભક્ત પોતાને જેવી રીતના જાણે છે તેને તેવી રીતનો કરે છે. જેવડું પાત્ર તેટલું દિવેલ સમાય ને તે રીતે વાટનો પ્રકાશ થાય, તેમ પાત્ર પ્રમાણે શ્રીહરિ સૌમાં પ્રકાશ મૂકે છે ને તેટલું તમ નાશ કરવા તે સમર્થ થાય છે.","e":"However supreme a devotee knows Shriharí to be, that much supreme does he himself become. And Bhagwan too makes a devotee such as the devotee knows Him to be. As large as the vessel is, that much oil it holds, and accordingly the wick gives light; so Shriharí places light in each according to his vessel, and to that extent that person becomes able to destroy darkness.","s":["15/84/11-12"],"sv":["सर्वोपरि जानत हरि कुं जेता । सर्वोपरि होई जावत तेता ॥\n\n भगवान ताकुं जिस रीता । जानत जन होत तिस रीता ॥\n\n जेसे पात्र दिवेल हि ताको । बाती के जोग रहे वाको ॥\n\n जोग तेसे होवत प्रकाशा । तितनो तम को होत नाशा ॥"],"mt":false,"gl":null,"a":true},{"i":494,"k":"para","g":"શ્રીહરિની ઇચ્છાથી સૌ હરિજનને સમાધિ થઈ. સમાધિમાં દિવ્યતન ધરીને પૃથક્ પૃથક્ ધામ દીઠ્યાં, કેટલાક વૈકુંઠમાં ગયા, કેટલાક ગોલોકમાં ગયા, કેટલાક અપાર અક્ષરધામમાં ગયા. જે જે અવતારને જે ભક્ત માનતા હતા, તેને તે તે ધામમાં દીઠા, પૃથક્ પૃથક્ ભવન હતાં. તે એક એકમાં સ્ફટિક મણિ જડ્યા હતા. સૌથી પર અક્ષરધામ અપાર દીસતું હતું. શ્રીહરિની અપાર યોગકળાનો નિર્ધાર ક્ષુદ્રજન કેવી રીતે કરી શકે? શ્રીહરિના સ્વરૂપની સમજણ વિનાની જેટલી સમજણ છે તે બંધનરૂપ છે, એ માયાનું બંધન ટળતું નથી. જેને એ સ્વરૂપની ઓળખાણ થાય છે તેને બંધન ટળે છે તે અપરંપાર સુખને પામે છે. શ્રીહરિની સમજણ મુજબ ચાલે તેની કીર્તિ સૌ ધામમાં ગવાય છે.","e":"By the will of Shriharí, samadhi came upon all the harijans. In samadhi, taking divine bodies, they saw the various abodes separately: some went to Vaikunth, some went to Golok, and some went to the boundless Akshardham. Whichever avatar a devotee held to, in that abode he saw him; there were separate residences, each one inlaid with crystal gems. Highest of all, Akshardham appeared boundless. How can a petty person determine the boundless yogic skill of Shriharí? Whatever understanding there is that lacks understanding of the swarup of Shriharí is a form of bondage, and that bondage of maya is not removed. For one who comes to recognise that swarup, the bondage is removed and he attains boundless happiness. The renown of one who walks according to the understanding of Shriharí is sung in every abode.","s":["17/6/7,8,17,24"],"sv":["अपार ताहि समाधि भयेउ । वैकुंठ गोलोक में जाय रहेउ ॥\n\n केते जन गये अक्षरधामा ॥ शोभा देखत भये तेहि ठामा ॥\n\n जेते अवतार के हरिजन जेता । दिव्यतन देखे सबहि तेता ॥\n\n पृथक् पृथक् रहे भवन हि ताके । स्फटिक मनि बिन एक न वाके ॥\n\n अक्षर तासु अपार रहाये । ब्रह्मा वेद कुन लेख में कहाये ॥\n\n हरि की जोगकला रहे अपारा । क्षुद्रजन कैसे करे निरधारा ॥\n\n हरि की समझ बिन समझ जितना । जन के बंधनरूप रहे तितना ।\n\n आपकी बुद्धिबल चले जेता । तितना दुःख प्राप्त भये तेता ॥\n\n हरि की समझ पर चले जेउ । अपार सुख तेहि पावे तेउ ॥\n\n तितनी कीर्ति गवावत ताकी । हरि की समझ पर चले वाकी ॥"],"mt":false,"gl":null,"a":true},{"i":495,"k":"para","g":"શ્રીહરિનો સિદ્ધાંત અને ચરિત્ર સર્વોપરી છે. શ્રીહરિને સર્વોપરી જાણનાર વક્તા અને શ્રોતા પણ સર્વોપરી છે.","e":"The doctrine and the charitra of Shriharí are the highest of all. And the speaker and the listener who know Shriharí to be the highest of all are themselves the highest.","s":["17/25/16-18"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":6,"gu":"ભક્તિ, એકાંતિક ધર્મ","en":"Bhakti and Ekāntik Dharma","url":"https://www.anirdesh.com/pbp/index.php?page=chp_6","b":[{"i":496,"k":"para","g":"બોટાદમાં શ્રીહરિ સન્મુખ સંતોએ વાજિંત્ર સહિત ગાન કર્યું. શ્રીહરિ કહે, “ગાન કરીને ભગવાનને રીઝવવા એ ભક્તિ બને છે. લોક રીઝવવા થાય તો ગાન વૃથા છે. જ્ઞાન ધ્યાન તમે શીખો પણ ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ - એ ચારને હૃદયમાં ધારવાં એ ગુણ ભારે છે. આ સાધન સૌથી મોટું છે. ભગવાનની પ્રસન્નતાનું દૃઢ મૂળ આ જ છે. ગાન-વિદ્યા જેવા બીજા અનેક ગુણો ધારણ કરે, પણ એકાંતિક ધર્મની તોલે એ ન આવે. એકાંતિક ધર્મ એ મૂળ છે. મૂળનો ત્યાગ કરીને બીજું અનંત શીખે પણ તે સાધુને શોભાડતું નથી, આ વાતનો સૌ સંત નિશ્ચય કરજો. મૂળનો દૃઢાવ હોય પછી બીજો ગુણ અલ્પ સરખો પ્રાપ્ત થાય તોપણ તે મહાન છે ને મૂળ (એકાંતિક ધર્મ) વિના બીજા મહાન ગુણો કે આવડત વિકસે તોપણ તે બધાં અવગુણમાં ખપે છે. જેમ વૃક્ષનું પોષણ તેના મૂળમાં રહેલું છે. મૂળ પોષે તો ફલ-ફૂલ હાથ લાગે છે, તેમ એકાંતિક ધર્મ એ સત્સંગનું મૂળ છે, એને દૃઢ કરશો તો અનંત ગુણો પ્રાપ્ત થશે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":497,"k":"para","g":"“હે મારા વહાલા સંતો! આ અમારો દૃઢ સિદ્ધાંત છે તે તમને કહ્યો. મૂળને દૃઢ કરવા સંગીત ભણો કે અન્ય વિદ્યા ભણો, વર્તન રાખો આ એકાંતિક ધર્મ - મૂળ સંબંધી જ્ઞાન અને સમજ એવા એકાંતિક સંતના સમાગમે કરીને જ પ્રાપ્ત થાય છે. અમે ગામોગામ વિચરણ કરીએ છીએ, હરિજનને મળીએ છીએ, નામ-ગામ, વ્યવહાર બધું પૂછીએ છીએ, સમયે સમયે બાઈ-ભાઈને સંભારીએ છીએ, જે જે અમારી સેવા કરે છે તેને તત્કાળ ગ્રહણ કરીએ છીએ, હેત-પ્રીત કરીએ છીએ - આ બધું જ મૂળને (એકાંતિક ધર્મને) દૃઢ કરાવવા માટે કરીએ છીએ. ઠેર ઠેર સ્વાગત-સન્માન ને અનંત શોભા કરો છો તે સ્વીકારીએ છીએ. નિયમ-પ્રકરણ વારંવાર ફેરવીએ છીએ. અમારું ખાવું-પીવું, ઓઢવું-પાથરવું આ બધું મૂળને દૃઢાવવા માટે છે. મોટા-મોટા રાજાઓએ પોતાના મહેલમાં અમને પધરાવ્યા, પૂજા-સન્માન કર્યાં, રાજપાટ ધરી દેવા લાગ્યા, પણ અમે એ બધાનો ત્યાગ કરી દીધો. વનમાં વિચર્યા, ક્યારેક રસ લીધો ને ક્યારેક તજી દીધો - આ બધાં ચરિત્રોને તપાસીને દેખશો તો માલૂમ પડશે કે મૂળ એકાંતિકી ભક્તિનું પોષણ કરવાનો અમારો હેતુ છે. મૂલ દૃઢ કરાવન હોતા, તા હિત હમ કરત બહુ પ્રીતા.”","e":null,"s":["4/48/11-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":498,"k":"para","g":"શ્રીહરિએ માંડવીમાં વાત કરતાં કહ્યું, “ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ અને આત્મનિષ્ઠા, આ પાંચ ધનથી અતિ અધિક છે. ધનમાં વિઘ્ન અને દુઃખ પણ આવે છે પણ આ પાંચમાં આવતું નથી અને જે ચિંતવે તે મળે છે. જેને જ્ઞાન નથી તે રાજા, ગુરુ, શાહુકાર કે વહેપારી હોય તોપણ ધન સારું ખુવાર થાય છે. જ્ઞાન વિના કુબુદ્ધિ ટળતી નથી અને કુબુદ્ધિ હોય ત્યાં સુધી કાળ, કર્મ અને જમદૂતનો ભય મટતો નથી. કુબુદ્ધિ ટળે છે ત્યારે જ ભગવાનમાં પ્રેમ થાય છે.”","e":null,"s":["5/33/26-30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":499,"k":"para","g":"ભીમનાથના મહંત ગુમાનગરને શ્રીહરિએ કહ્યું, “દેહનો નિરધાર નથી, તે પરાધીન છે. તેમાં મનુષ્ય તન પામી ભગવાન ન ભજે તે બ્રહ્મા સમાન સમર્થ હોય તોપણ ચિંતામણિને વ્યર્થ ગુમાવ્યા જેવું કર્યું કહેવાય. ભરતખંડમાં મનુષ્યતન પામી હરિ સેવામાં ક્યારેય યોગ ન આવ્યો તો બ્રહ્માંડ જેટલું કનક મળે તોપણ છૂટી પડ્યું છે. બીજી સેવામાં ચિત્ત નહિ દઈને જેણે હરિની સેવા કરી છે તે પળે પળે બ્રહ્માંડ જેટલું સોનું કમાયો છે. હરિની સેવાથી તેનું માયિકતન દિવ્ય થઈ જાય છે. બીજા જનોને તે દેખાતું નથી, તેથી બાળી મૂક્યું એમ સમજે છે. દેહ તો ભગવાનની ઇચ્છાથી જ પડ્યું રહેલું એમ જણાય છે.”","e":null,"s":["9/29/1-8"],"sv":[],"mt":false,"gl":null,"a":false},{"i":500,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ જીવેન્દ્ર નૃપને કહ્યું, “સંસારમાં આસક્તિ તે ભક્તિનું ગોબરાપણું છે. માતા બાળકને કરુણા કરી ધૂએ છે ત્યારે ગોબરાપણું જાય છે. સંત મા સમાન છે. સત્સંગની રીત જ્યાં સુધી જાણ્યામાં ન આવે ત્યાં સુધી તે બાળકબુદ્ધિ છે. તો પણ ભગવાન દયાળુ છે, તે જ્યાં સુધી બાળક રહે છે, ત્યાં સુધી તેને પલભર છોડતા નથી.”","e":null,"s":["10/5/32-35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":501,"k":"para","g":"કરિયાણામાં ઓઢા ખાચરના ભવનમાં શ્રીહરિ કહે, “કોઈ કથા-કીર્તન કરે ત્યાં અમારું ચિત્ત ચોંટી જાય છે ને હરિ વિના બીજું કાંઈ સાંભરતું નથી અને મન દીવાનું થઈ જાય છે. હરિની સ્મૃતિ રહે તેટલો સત્સંગ કહેવાય, તે વિના બધો કુસંગ કહેવાય.”","e":null,"s":["10/9/19-20"],"sv":[],"mt":false,"gl":null,"a":false},{"i":502,"k":"para","g":"શ્રીહરિએ ભુજથી એક પત્ર લખાવ્યો. તેમાં લખ્યું કે: “ભુજનગરના હરિજન વસંતપંચમીનો ઉત્સવ કરાવે છે તેમાં સંતો, બ્રહ્મચારીઓ, પાર્ષદો ને બાઈ-ભાઈ હરિજનો પધારજો. હરિજનને વ્યવહાર-વ્યવસાય હોય, પણ ઉત્સવનું દર્શન દુર્લભ માનીને ખાસ આવવું. જીવને જ્યારે અંત સમય આવે છે ત્યારે અતિ કષ્ટ પડે છે તે વખતે સંતો-હરિભક્તોની સભા ભરાઈને બેઠી હોય ને તેની વચ્ચે અમે બેઠા હોઈએ, ઉત્સવ કર્યો હોય, ગુલાલ ઉડાડ્યો હોય, વાતો કરી હોય, કીર્તનો ગવરાવ્યાં હોય... ઇત્યાદિ અમારી સ્મૃતિ થઈ આવે તો તેને કષ્ટમાત્ર મટી જાય છે ને અમારી મૂર્તિ દર્શાય છે. માટે ઉપાધિ સહીને પણ સમૈયે આવજો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":503,"k":"para","g":"“અતિપુણ્યે કરીને મનુષ્યતન મળ્યું છે તેમાં સંત સમાગમ કરીને દુર્લભ એવું અક્ષરધામ પમાય છે. લોકમાં તો બહુ જન તીર્થ, પુણ્ય, દાન, બ્રાહ્મણભોજ ઇત્યાદિ મોક્ષ કાજે કરે કરાવે છે, પણ સકામ હોવાથી મોક્ષ થતો નથી. એ તો જ્યારે સત્સંગ કરે ત્યારે જ થાય છે. કોટિ યજ્ઞ કરવાથી પણ મોક્ષ ન થાય તે સત્સંગથી થાય છે. જ્યાં ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ સહિત એકાંતિક ધર્મ છે; વળી, ભગવાનનું પ્રગટપણું છે; વળી, ત્યાગી-ગૃહી પોતપોતાના બ્રહ્મચર્યાદિક ધર્મમાં દૃઢ વર્તે છે; ગૃહસ્થો વ્યસન, ફેલ, ભાંડ-ભવાઈ ઇત્યાદિનો ત્યાગ કરીને નિયમમાં વર્તે છે ને સંતો અષ્ટ પ્રકારનું બ્રહ્મચર્ય વ્રત રાખે છે; ચૌદ લોકમાં જેને ક્યાંય પ્રીતિ નથી - એવો સત્સંગ જ્યાં દેખાય ત્યાં મોક્ષ માનવો. આટલી વાત જ્યાં જોવા ન મળે તો જાણવું કે ત્યાં મોક્ષ નથી.” આવો પત્ર શ્રીહરિએ લખ્યો જેને સાંભળીને હરિજન ચકિત થઈ ગયા.","e":null,"s":["10/30/9-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":504,"k":"para","g":"ભૂજમાં શ્રીહરિએ હરિજનો પ્રત્યે સત્-અસત્ ગુરુની વાત કરતાં કહ્યું, “મોક્ષરૂપી નિધિ ચિંતામણિથી પણ અધિક છે. અપાર રિદ્ધિ-સિદ્ધિ પણ મોક્ષ નિધિ વિના નકારી છે. મોક્ષનો ખપ તે સૌથી શ્રેષ્ઠ છે અને તે ચિંતામણિથી અધિક છે. તેનાથી ભગવાનના ધામની પ્રાપ્તિ થાય છે ને બીજા ફીકા લાગે છે. કૂચામાં અને રસમાં જેટલો ફેર છે તેટલો મોક્ષ અને બીજા સુખમાં ફેર છે. સત્પુરુષના સંગ વિના આ વાત સમજાતી નથી. પોતાની મેળે સમજવા જાય તો ક્યારેક ધર્મમાં અધર્મ માની બેસે. જેમાં ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિનો લેશ હોય નહિ વળી, વ્યસન અને કેફી ચીજોનું સેવન કરતા હોય, તે મિથ્યા ગુરુ છે. મોક્ષના ખપવાળા જનોએ એવા ગુરુનો ત્યાગ કરવો.”","e":null,"s":["10/49/39-50"],"sv":[],"mt":false,"gl":null,"a":false},{"i":505,"k":"para","g":"આખા ગામમાં શ્રીહરિ કહે, “ભક્તોના ભાવ સમાન અમને બીજો કોઈ રસ (સ્વાદ) દેખાતો નથી. શબ્દ, સ્પર્શ, રૂપ, રસ ને ગંધ પણ ભાવ પાસે લૂખા છે. ભક્તોના ભાવ જોઈને અમે સત્સંગમાં ફરીએ છીએ. દુર્જન મન ફાવ્યું મર બોલે અમે તેને ગણતા નથી. અમારી પ્રકૃતિ તો એવી છે કે ભાવ વિના લેશ પણ ક્યાંય ટકીને રહીએ નહિ.”","e":null,"s":["14/31/8-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":506,"k":"para","g":"શ્રીહરિએ ઝીંઝાવદરમાં અલૈયા ખાચરના પિતા સામંત ખાચરને કહ્યું, “જે ભગવાનને ભજે છે તેને જીવના જેવા અજર, અમર અને અપ્રાકૃત દેહ મળે છે. જે તોપના ગોળાથી પણ નાશ પામે નહિ.”","e":null,"s":["14/37/34-35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":507,"k":"para","g":"વડતાલમાં શ્રીહરિનું પૂજન કરવા તત્પર થયેલા સંતોને શ્રીહરિએ ઉપદેશ આપતાં કહ્યું, “અમારી પૂજા કરવા માટે સંતોએ હરિભક્ત પાસે કેસર, ચંદન કે હાર માગવાં નહિ. અમારે માટે નિર્લોભી વર્તમાનનો ભંગ કરવો નહિ. અમારા માટે મીઠાઈ કે વસ્ત્ર, આભૂષણ માગવાં નહિ. અમારા વચન-પાલનને અમારી પૂજાથી પણ અધિક અમે માનીએ છીએ. તમો સંતો, વર્ણી ને પાર્ષદો સત્સંગને અર્થે જે જે કરો છો તે અમે સેવા જ માની છે.”","e":null,"s":["15/43/5-7, 10-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":508,"k":"para","g":"શ્રીહરિએ ગઢપુરમાં સંતોને વાત કરતાં કહ્યું, “ભક્ત જ્યારે ભગવાનને વશ, આધીન થઈને વર્તે છે, ત્યારે ભગવાન પણ એ ભક્તને વશ થઈ જાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":509,"k":"para","g":"“ભગવાનની મર્યાદાને કોઈ સીમા નથી એ સર્વોપરી છે. પાતાળથી અક્ષર સુધી સૌ એમને પૂજે છે. એ ભગવાને પોતાને વશ કરવાના સાધનરૂપે નિયમ આપ્યા છે. સૌ પોતપોતાના ધર્મમાં વર્તે તો કોઈને દુઃખ દૂષણ રહે નહિ.”","e":null,"s":["15/54/12-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":510,"k":"para","g":"ગઢપુરમાં શ્રીહરિ કહે, “કથામાં જેને પ્રીતિ ન હોય તે અમને બહુ પ્રિય લાગતા નથી. ભગવાનની કથાવાર્તા ને કીર્તનના અંગવાળા હોય તેનાં અમે વખાણ કરીએ છીએ. જીવને અનંત યુગથી સંસારમાં મન ચોંટેલું છે, તેને ઉખાડવાનો અભ્યાસ રાખે તેને દેખી અમને આનંદ થાય છે, કારણ કે અમે જાણીએ છીએ કે આ તો પ્રત્યેક જીવને કરવાનું કામ છે, તે તત્પર થઈને આ ભક્ત કરે છે. એમ જાણી એવા ભક્ત પર અમારી પ્રીત દિવસે દિવસે વધતી જાય છે. અને જેનું ચિત્ત સંસારમાં લોભાતું હોય તે દેખીને તેનાથી અમારું ચિત્ત તોડીએ છીએ, તેનો સંબંધ કાપી નાખીએ છીએ. એ ભક્ત થયો તોપણ સંસાર અને દેહમાં આસક્ત રહેતો હોય, એ તેને મોટું વિઘ્ન છે. આ વાત જે બરાબર સમજે છે, તેનો સત્સંગ ટકે છે. વળી, સંતો-ભક્તોને નિર્દોષ જોતો હોય અને બીજાને પણ એના નિર્દોષપણાની વાત કરતો હોય, તેના પર અમને અત્યંત હેત રહે છે.”","e":null,"s":["15/55/35-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":511,"k":"para","g":"શ્રીહરિએ પોતાના ભક્તોને પત્રમાં લખાવ્યું કે, “ભગવાન સંબંધી એકાદશી આદિ વ્રત કરવાં. તેનું જાગરણ કથાવાર્તા, કીર્તન કરીને આખી રાત કરવું. જેથી ભગવાન અતિ પ્રસન્ન થાય છે. ભગવાનના નામની ધૂન કરવી. વ્યર્થ કામ તજવાં. રાત્રિ-દિવસ વ્યર્થ સૂવું નહિ. વિવાહ, ભાંડ ભવાઈ જોનારા આખી રાત જાગે છે. ચોર અને કામી લોકો પણ જાગે છે, તેમ ભગવાનને પ્રસન્ન કરવા શ્રદ્ધાએ યુક્ત જાગે તેને અક્ષરધામ રૂપી ફળ મળે છે. ચાર પહોર જાગી શકે નહિ તે ત્રણ, બે કે એક પહોર જાગે. એક પહોર (ત્રણ કલાક) પણ ન જાગે તેને ગુણબુદ્ધિ છે એમ માનવું.”","e":null,"s":["15/97/25-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":512,"k":"para","g":"શ્રીહરિએ પત્રમાં વાત લખાવતાં કહ્યું, “ભક્તિશાસ્ત્ર, ધર્મશાસ્ત્ર ને યોગશાસ્ત્ર - બધાનો એક જ સિદ્ધાંત શુકજી વગેરેએ આપ્યો છે: પોતાનું રૂપ બ્રહ્મરૂપ માનીને પરબ્રહ્મ પુરુષોત્તમની દાસભાવે સેવા કરવી. સંતો-હરિજનોનો સંગ તજવો નહિ. દેહ-ઇન્દ્રિયો-અંતઃકરણનો સંગ હોય તેની મતિ વિપરીત થઈ જાય છે. સત્સંગ કરવા ન દે ને ચોરાશીમાં ભમાવે છે, એટલે તેનો સંગ ક્યારેય ન કરવો. પરમાત્મા પર બુદ્ધિ લક્ષિત ન થાય એટલો કુસંગ કહેવાય છે.”","e":null,"s":["15/100/29-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":513,"k":"para","g":"શ્રીહરિ ધર્મપુરનાં રાણી કુશળકુંવરબાની ભક્તિ વખાણતાં ગઢપુરના ભક્તજનોને કહે, “રાણી અમારાં દર્શન કરતાં નેત્રમાં મટકું મારતાં નહિ અને અંગોઅંગ નીરખીને અંતરમાં ઉતારતાં. દેવહુતિ માતા જેવી તેમની વૃત્તિ હતી. તેમની રાજ્ય આપવાની ઇચ્છા જોઈને અમે ત્યાંથી વહેલા ચાલી નીકળ્યા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":514,"k":"para","g":"“અમે તો એક ઘડી ભગવાનનું ધ્યાન કરીએ તે બરાબર ત્રિલોકીના રાજ્યને પણ માનતા નથી. મૂર્તિના સુખ કરતાં વચનના સુખને અધિક માનીએ છીએ. દૈહિક સુખ સમાન બીજું દુઃખ નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":515,"k":"para","g":"“ભગવાનની મરજીમાં ધામથી પણ અધિક સુખ માને તે સમાન કોઈ ભક્ત નથી, મુક્ત, સિદ્ધ, પ્રેમી કે અક્ષર નથી. મરજીમાં સુખ માનનારને કાંઈ દુઃખ રહેતું નથી. શૂળીએ ચઢવું અને પૂજા પામવી, એ બધું ભગવાનની મરજીથી થતું જાણી બન્નેમાં આનંદ પામે છે. એવાથી ભગવાન પળમાત્ર દૂર થતા નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":516,"k":"para","g":"“સુખ અને સાધનમાત્ર ભગવાનની મરજી મુજબ વર્તવામાં આવી જાય છે. ગ્રંથમાત્રનું રહસ્ય પણ આવી જાય છે. મરજીમાં ન ચાલે તે બધા ગ્રંથો ભણે કે તીર્થ-વ્રતાદિક સાધન કરે કે બ્રહ્માંડની રચના કરે પણ ભગવાનના શત્રુ છે. મરજી જાણે તેણે જ સત્સંગ કર્યો છે. બીજાનો ન કર્યા બરાબર છે. મરજી ન સમજતાં, જય-વિજય વૈકુંઠમાંથી પડ્યા, ભગવાનની સેવા કંઈ કામ લાગી નહિ. માટે સત્સંગ કરી ભગવાનની મરજીનું ધ્યાન રાખવું.”","e":null,"s":["16/38/7-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":517,"k":"para","g":"બોટાદમાં આરતી-સ્તુતિ સંત કરી રહ્યા પછી શ્રીહરિએ કહ્યું, “અમે સંતનાં દર્શનનો પરમ લાભ માન્યો છે. તે લાભ લેવા તો અમે વર્ષમાં બે વાર ઉત્સવ-સમૈયા કરીએ છીએ ને હરિભક્તોને તેડાવીને કથાવાર્તા કરી ચેતાવીએ છીએ. અતિ અંધારી રાતે દીવા વગરનાં ઘર કેવાં લાગે? તેમ સમૈયા વિનાનાં અંતર અંધકારમય થઈ જાય. ભગવાનના સાધુ અને હરિજનો પ્રિય લાગે નહિ એટલો કુસંગ જાણવો અને એ તેને માથે વિઘ્ન છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":518,"k":"para","g":"“સમૈયામાં સંત-સમાગમ થાય. હરિજનોમાં એક મન થાય. સત્સંગનું પોષણ થાય. સમાગમરૂપી ફળ લેવા ઇચ્છા હોય અને કોઈ આડે આવી વિઘ્ન કરે તો શત્રુ જાણી તેનો ત્યાગ કરવો. શત્રુ જ્યાં સુધી મિત્ર મનાય છે, ત્યાં સુધી વિઘ્ન રહેવાનાં. સમૈયાનો કેફ એક વર્ષ સુધી રહે છે. બીજે વર્ષે ન આવે તો તે ઘટવા લાગે છે. આ વાત નક્કી આમ જ છે, પ્રત્યક્ષ દેખીને કહીએ છીએ.”","e":null,"s":["19/16/5-20"],"sv":[],"mt":false,"gl":null,"a":false},{"i":519,"k":"para","g":"વડતાલમાં શ્રીહરિ આરતી નારાયણ ધૂનમાં તાળી પાડી ચિત્ત પરોવી દેતા અને વચ્ચે ક્યારેય વાત કરતા નહિ. બીજો કોઈ વાત કરે તેને શ્રીહરિ ઠપકો દેતા અને કહેતા કે, “ભગવાનનું નામસ્મરણ, ભજન, ધ્યાન, કથા-કીર્તન અને વાતમાં જે અનાદર રાખે છે, તેનો અનાદર અંતર્યામી ભગવાન પણ એટલો જ રાખે છે અને કોપ કરે છે.”","e":null,"s":["19/57(56)/18-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":520,"k":"para","g":"ગઢપુરમાં શ્રીહરિ વહેલી સવારે ઊઠીને નારાયણ ધૂન કરીને પલંગમાં બેઠા. સામે સંતો બેઠા. સંતોને કહ્યું કે, “સૌ પોતપોતાનાં અંગ કહો. પહેલાં અમે અમારું અંગ કહીએ છીએ, અમે ધર્મ, જ્ઞાન, વૈરાગ્ય અત્યંત નિર્દંભપણે રાખીએ છીએ. પોતાને આત્મસ્વરૂપ માની ભગવાનમાં અત્યંત સ્નેહ રાખીએ છીએ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":521,"k":"para","g":"“ભગવાન સદા સાકાર, મૂર્તિમાન છે એવી અમારે દૃઢમતિ છે, સાકાર વિના ભક્તિ સંભવે નહિ. ભક્તિ વિના જ્ઞાન, વૈરાગ્ય, ધર્મનું કાંઈ ફળ નથી. એ ચાર ગુણ હોય ત્યાં ભગવાનનો નિવાસ છે ને ત્યાં જ મોક્ષ છે. એવો જેને નિશ્ચય હોય તેને પરિપક્વ અંગ કહેવાય. સ્થિતિ અને અંગ બેઉ એક વસ્તુ છે.”","e":null,"s":["20/68/2-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":522,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":523,"k":"para","g":"પ્રભુ કીર્તન-ભક્તિને વશ વર્તે છે. શ્રીહરિમાં જે જન વૃત્તિ જોડે છે ત્યારે તેની સમીપ તેઓ આવીને ઊભા રહે છે. ગાન કરે તેની પાછળ પાછળ ફરે છે. જેટલી હરિમાં વૃત્તિ જોડે તેટલો તે નિર્વાસનિક થાય. આવો અતિ અપાર લાભ સમજીને જે વૃત્તિ જોડતો નથી તેને નીચ જાણવો.","e":null,"s":["4/72/20-21"],"sv":[],"mt":false,"gl":null,"a":true},{"i":524,"k":"para","g":"કીર્તન-ભક્તિમાં શ્રીહરિનો નિવાસ છે. અને ધર્મ, જ્ઞાન ને વૈરાગ્ય તેમાં રહેલાં છે, તેનાથી શ્રીહરિનાં ચરિત્રની સ્મૃતિ થાય છે અને સાંભળનારનો જીવ તદાકાર થાય છે. વ્યાધિમાત્ર ટાળવાનો તે ઉપાય છે.","e":null,"s":["6/37/6"],"sv":[],"mt":false,"gl":null,"a":true},{"i":525,"k":"para","g":"ભક્તના અંતરમાં ભગવાનનાં દર્શન-પૂજન-અર્ચનની જેટલી આતુરતા હોય તેટલા શ્રીહરિ તેની પાસે આવે છે અને મનોરથો પૂરા કરે છે. જેટલી આતુરતા ઓછી એટલી કસર છે.","e":null,"s":["7/31/38-39"],"sv":[],"mt":false,"gl":null,"a":true},{"i":526,"k":"para","g":"શ્રીહરિ પધારતાં જેને પ્રેમ વધતો રહે તેને શ્રીહરિ ઓળખી લેતા ને તેને જ ઘરે જતા, ભલે નિર્ધન હોય પણ પ્રેમ છે તો તે કુબેરથી અધિક ધનવાન છે. કુબેર જેવા ધનવાન હોય તોપણ જો ભક્તિ ન હોય તો તે કંગાલ છે. શ્રીહરિ તેની કંચનમય સેવા હોય તોપણ નિર્માલ્ય જેવી જ માને છે. દુર્બળ ભક્ત ભાવથી રોટલો ને ડોડીની ભાજી અર્પણ કરે તોપણ દસ દિવસના ભૂખ્યા હોય તેમ પ્રેમથી જમે. પ્રેમ અને શ્રદ્ધા એ બેય જેમાં હોય અને કુટિલતા ન હોય તેને શ્રીહરિ વશ વર્તે છે. આકાશ નિર્બંધ છે છતાં બ્રહ્માંડમાં બંધાયેલું છે, તેમ નિર્બંધ શ્રીહરિ પ્રેમ અને શ્રદ્ધાની દોરીથી બંધાયેલા છે.","e":null,"s":["8/25/7-14"],"sv":[],"mt":false,"gl":null,"a":true},{"i":527,"k":"para","g":"શ્રીહરિનાં ચરિત્રોમાં જીવનું કલ્યાણ રહેલું છે. ચરિત્રરૂપી રસ આગળ બીજા રસો તો સાકરની આગળ લવણ સમાન છે. સુખમાત્ર તો તેમાં રહેલું છે, ને તે સર્વ સાધનના ફળરૂપ છે. તેમાં જેને હેત થાય તેનાં સાધન પૂર્ણ થયાં અને તેનું ભવ-ભટકણ મટી જાય છે. ધામમાં પણ ભગવાનનાં ચરિત્રો અને મહિમાનું શ્રવણ અને ગાન કરતાં મુક્તો પણ તૃપ્ત થતા નથી, એવો ભગવાનની મૂર્તિનો રસ છે.","e":null,"s":["8/55/18-24"],"sv":[],"mt":false,"gl":null,"a":true},{"i":528,"k":"para","g":"શ્રીહરિને ધર્મ, જ્ઞાન, વૈરાગ્ય, ભક્તિ ગમે છે. જેણે આ એકાંતિક ધર્મ સિદ્ધ કર્યો છે, તેને શ્રીહરિ જેમ જેમ વધુ માન દે તેમ તેમ તે દાસનો દાસ થઈ વર્તે. સંતો-ભક્તોની સેવાના ફળરૂપે વખતોવખત શ્રીહરિ તેને સંભાર્યા કરે છે.","e":null,"s":["9/41(40)/5-7"],"sv":[],"mt":false,"gl":null,"a":true},{"i":529,"k":"para","g":"બ્રહ્માંડ જેટલું ધન મળે, પણ ભગવાન ને સંતના ઉપયોગમાં ન આવ્યું તો તે વ્યર્થ છે - એવી જેને સમજણ ન હોય તે હરિભક્ત કસરવાળા કહેવાય. ભગવાનથી અધિક કોઈ સુખને માને નહિ. સ્વપ્નમાં પણ તેમ ન મનાય ત્યારે યથાર્થ જ્ઞાન કહેવાય. ક્યારેક ચિત્તભંગ થાય તથા દીર્ઘરોગ થાય અને પ્રારબ્ધવશ થઈને દેહનો નિર્ધાર ન રહે ત્યારે પણ જે જ્ઞાન જાય નહિ અને શ્રીહરિને જીવ સાથે જડ્યા હોય, સંત-હરિભક્તોનો દાસ થઈને વર્તતો હોય, વિના વાંકે અપમાન કરે તોપણ ધીરજ રહેતી હોય, તે જ પાકો સત્સંગી છે.","e":null,"s":["10/46/18-28"],"sv":[],"mt":false,"gl":null,"a":true},{"i":530,"k":"para","g":"રસિકજનોને ભગવાનનાં ચરિત્ર અમૃત સમાન છે. વિષયીજનોને વિષરૂપ છે. કથામાં લેશ પણ આળસ પ્રમાદ રહે તે સાચો રસિક નથી. રસિકને તો શત્રુના મુખે ભગવાનની વાત અમૃત સમાન લાગે. પોતે ભગવાનની વાત કરે તેમાં કોઈ પર વેર-ઈર્ષ્યા રાખે નહિ; અને રાખે તો કોટિ ગૌહત્યાથી અધિક પાપી છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":531,"k":"para","g":"અનંત બ્રહ્માંડના રસથી પણ અધિક રસ ભગવાનનાં ચરિત્રમાં છે. તે પીવામાં નિદ્રા, આળસ હોય અને ધ્યાનમાં રાત-દિવસ બેસતો હોય તોપણ તેને ભક્ત ન જાણવો. કારણ, શુક-સનકાદિક જેવા ધ્યાની અને સિદ્ધો પણ ભગવાનનાં ચરિત્રનું પ્રેમથી ગાન કરે છે. વાયુનો આહાર કરે, અગ્નિમાં બેસે, એમ પૂજાવાના અનેક ઉપાયો કરે છે, પણ ભગવાન ઉપર પ્રીતિ ન હોય તે છૂપું રહેતું નથી. શ્રીહરિ અને સંતમાં પ્રીતિ હોય તે સેવામાં પરખાય છે, પણ બધાયને તે વાત દેખાતી નથી એવી અટપટી છે.","e":null,"s":["12/60/17-29"],"sv":[],"mt":false,"gl":null,"a":true},{"i":532,"k":"para","g":"શ્રીહરિનાં ચરિત્ર સંભારવાં તેના જેવું કોઈ સાધન બળવાન નથી. હરિનાં ચરિત્રો એક દિવસનાં જ હોય, પણ તેને કહેતાં વરસ જેટલો સમય લાગે. ચરિત્ર સાંભળીને હરિજન બીજાને કહે તે ધન્ય થઈ જાય છે. હેતે કરીને સાંભળે તે અતિધન્ય થાય છે. તેને જન્મમરણ કે લખચોરાશીના ફેરા રહેતા નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":533,"k":"para","g":"શાસ્ત્રોમાં કહેલાં તીર્થ, વ્રત, તપ કરે તે એક હજાર કલ્પ સુધી કરે તોપણ તેનો ઉદ્ધાર ન થાય, તે હરિનાં ચરિત્રથી સહેજે થાય છે. કાળ, માયાના ભયથી રહિત થઈને ઇચ્છિત સુખને પામે છે. આવું જાણી સંતો-ભક્તોએ શ્રીહરિના ચરિત્રો કહેવાં. હરિનાં ચરિત્ર કેવળ મનુષ્યયોનિમાં જ શ્રવણ થઈ શકે છે. એટલે જ વ્યાસજી અને શુકજી તે કહેતાં થાકતા નથી, પ્રહ્‌લાદ, ઉદ્ધવ, ગોપીઓ જેવાં ભક્તો શ્રીહરિનાં ચરિત્રને અમૃત જાણી રસપૂર્વક તેનું પાન કરે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":534,"k":"para","g":"હરિનાં ચરિત્રના જે લોભી છે તેને મનુષ્યનું તન મળે છે. પછી બ્રહ્માંડ જેટલી રાજસમૃદ્ધિ મળે તોપણ તેને સહજે ઠેલી દે છે ને હરિનાં ચરિત્રોમાં બહુ લાભ ગણીને શ્રવણ કરવાથી નિવૃત્ત થતા નથી. ત્રિલોકીનું રાજ મળે ને તે જો હરિનાં ચરિત્ર સાંભળે નહિ તો તેને રાક્ષસ ને દૈત્ય લેખવા. ચરિત્ર કહે અને શ્રવણ કરે પણ બીજા પર અસૂયા કરે તો તે રુરુ નર્કમાં પડે છે.","e":null,"s":["13/25/10-24"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":7,"gu":"નિર્દોષબુદ્ધિ, દિવ્યભાવ","en":"Nirdoshbuddhi, Divyabhāv — Seeing No Fault, Divine Perception","url":"https://www.anirdesh.com/pbp/index.php?page=chp_7","b":[{"i":535,"k":"para","g":"શ્રીહરિએ માતાને ઉપદેશ દેતાં કહ્યું, “ભગવાન મનુષ્ય-નાટ્ય ધારીને મનુષ્યરૂપે વર્તે છે, છતાં તેમની બધી ક્રિયા મોક્ષકારી છે એમ માની, લવમાત્ર દોષ ગ્રહણ કરે નહિ. ફાવે તેટલું દુઃખ આવે તોપણ ભક્ત હોય તેને ભગવાનનો દૃઢ વિશ્વાસ હોય છે.”","e":null,"s":["1/67/24-25"],"sv":[],"mt":false,"gl":null,"a":false},{"i":536,"k":"para","g":"શ્રીહરિએ ઉત્તમ ભક્તની ઓળખ આપતાં ગોંડલના નૃપને કહ્યું, “અમારા ઉત્તમ ભક્ત છે તે અમને સૌથી ઉત્તમ પૂર્ણપુરુષોત્તમ નારાયણ પૂર્ણકામ જાણે છે અને અમારાં ચરિત્રમાં ક્યારેય પ્રાકૃત બુદ્ધિ કરતા નથી. અમારાં સર્વ ચરિત્રને અલૌકિક, દિવ્ય અને મોક્ષદાયી માનીને તેનું ગાન કરે છે, વળી, જેને જેને અમારો સંબંધ થયો છે તે સર્વેને પણ દિવ્ય કરીને માને છે. ઉત્તમ ભક્ત અમારાં વચનને લેશમાત્ર લોપતા નથી. અમને અંતર્યામી જાણી છળકપટ તજીને ભજે છે.”","e":null,"s":["3/49/22-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":537,"k":"para","g":"શ્રીહરિ ગોંડલના રાજા હઠીસિંહને કહે, “અમારા સ્વરૂપનું અનંત જીવોને દિવ્યજ્ઞાન આપવા અમે ચાર ધામમાં ફર્યા અને દિવ્યજ્ઞાન કરાવી અમારા દિવ્યધામમાં તેમને પહોંચાડ્યા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":538,"k":"para","g":"“મોક્ષભાગીજન અમને અતિપ્રિય છે. અમે કોઈને આધીન થતા નથી. જેમ જેની શ્રદ્ધા વધે, તેમ તેને આધીન થઈએ છીએ. જ્યાં સુધી માયાનું બંધન છે, ત્યાં સુધી જીવ બ્રહ્મરૂપ થતો નથી. બ્રહ્મરૂપ થયા વિના જન્મ વૃથા ખોવે છે. જીવોને બ્રહ્મરૂપ કરવા જ અમે અવતાર ધારણ કર્યો છે. અને અનંતનો ઉદ્ધાર કરવા સાધુરૂપે અમે વિચરીએ છીએ. જે જે અવતાર થયા છે, તેણે પણ મારા સાધુને બહુ કરીને માન્યા છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":539,"k":"para","g":"“મારા દિવ્ય અક્ષરધામમાં અનંત કોટિ મુક્ત વસે છે. અનંતધામો છે, તેનાં સુખ અનંત છે, એ બધાં સુખો કરતાં સંતપદ શ્રેષ્ઠ છે. અમે સંતની પાસે દીન થઈ જઈએ છીએ. કારણ કે સાધુની પદવીથી ઊંચી કોઈ પદવી નથી. સારમાં સાર સાધુની પદવી છે. અમને એ પદવી ગમે છે. બીજા પદમાં અમે અરુચિ રાખીએ છીએ. જેને બીજા લોકની અરુચિ થાય છે, તેને મારી રુચિ થાય છે. મારામાં રુચિ થઈ તેનો હું ક્યારેય ત્યાગ કરતો નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":540,"k":"para","g":"“હું અખંડ સંતની પાસે રહું છું. એ સંતને મારા સિવાય મનમાં કોઈ બીજી આશા નથી. તેના ગુણનો કોઈ પાર લઈ શકે તેમ નથી. એવા સંતને પરમ એકાંતિક સંત કહે છે. એ સંતથી પર કોઈ નથી. સૌને પરમપદ પમાડવા આજે હું સાધુરૂપે થયો છું. મારા શરણે આવ્યા છે તે અનંત જીવોને બ્રહ્મરૂપ કર્યા છે અને હજુ પણ માયાનું બંધન તોડીને અનંતને બ્રહ્મરૂપ કરવા છે. અમે ભક્તો માટે દેશોદેશ મહા ઉત્સવ કરીએ છીએ. સંતો-ભક્તોને ભેળા કરીએ છીએ. તે સૌનું કોઈ દર્શન કરે, એ પણ બ્રહ્મરૂપ થાય, એવો અમારો સંકલ્પ છે. અમારો સંકલ્પ સત્ય હોય છે. બીજું બધું અસત્ય થઈ જાય. અમારા સંકલ્પ પાસે કાળનું જોર ચાલતું નથી. કાળ પણ થર થર ધ્રૂજતો રહે છે.”","e":null,"s":["3/49/32-52"],"sv":["दिव्य ज्ञान देन जीव अनंता । च्यार धाम में फिरत विचरंता ॥\n\n दिव्य हि मेरो ज्ञान कराई । दिव्य धाम में पोंचाये ताई ॥\n\n मोक्ष भागि तेहि जन हमारा । तेहि लगत हमकुं बहु प्यारा ॥\n\n कोईके न होवत हम आधिना । श्रद्धा ज्युं ज्युं वृद्धि होय तेहा ॥\n\n माया को बंधन जबहि लग, जीय ब्रह्मरूप न होत ।\n\n ब्रह्मरूप हि होय बिन, वृथा जन्म सब खोत ॥\n\n ब्रह्मरूप जीय करन हित, में धारे अवतार ।\n\n साधुरूप धरि फिरत हें, करन अनंत उध्धार ॥\n\n जो जो अवतार होत हें मेरा । मानत सो साधुकुं घनेरा ॥\n\n मेरो दिव्य हे अक्षरधामा । अपार पार्षद रहत सो ठामा ॥\n\n तेहि सब सुख सें संत पद भारि । सो पद अबहि रहे में धारि ॥\n\n सबसें रुचि मोय संतकि मांई ॥ संतकि आगे दीन होइ जाई ॥\n\n संतके पद सम पद न कोई । सार में सार जोई कहे सोई ॥\n\n संत पद में होत जब रुचि । और पदकि होवत अरुचि ॥\n\n अरुचि होत तब रुचि होत मोरि । रुचि जोई तेहि दियुं न छोरि ॥\n\n अखंड रहत में संतकि पासा । मो बिन जेहि नहि मन आसा ॥\n\n मो बिन आस नहि जो संता । तिनके गुनको को लहेउ अंता ॥\n\n परम एकांतिक संत कहाई । इनसें पर न कोउ रहाई ॥\n\n सो परमपद देन हि काजा । अब में भयोहुं संत हि आजा ॥\n\n ब्रह्मरूप अनंत हि, किन शरन भये मोर ।\n\n अबहि करन कुं अनंत हें, माया बंधन तोर ॥\n\n ब्रह्मरूप हि करन हित, मेरो लहि चरित ।\n\n देश देश उच्छव करत महा, हरिजन के हित ॥\n\n संत हरिजन सोय, तिनको करे दरश कोउ ।\n\n तेहि ब्रह्मरूप होय, ऐसो संकल्प किन मोइ ॥\n\n संकल्प सत्य होत मोर, ओर असत् होई जात सबे ।\n\n काल को चले न जोर, थर थर ध्रुजत रहत हें ॥"],"mt":false,"gl":null,"a":false},{"i":541,"k":"para","g":"ચૂડાપુરમાં શ્રીહરિએ થાળની પ્રસાદી જીવેન્દ્રને આપી અને સૌને વાત કરતાં કહ્યું, “અમારી સઘળી વાર્તા અમાયિક છે. તે જેનું વર્તન અમાયિક હોય તેના અંતરમાં જ ઠરે છે. માયિક અંતરવાળો કરોડવાર તેને ઘૂંટે, પણ તેમાં ટકતી નથી. દેહાકારે વર્તે તેને માયિક ભક્ત જાણવો. તેના હૃદયમાં માન જેવા અનંત દોષ નિરંતર ઘર કરીને રહે છે. જેને અપમાન લાગી જાય, તેને સત્સંગ થયો જ નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":542,"k":"para","g":"“અમારી વાતો તોપના ગોળા જેવી છે. માયિક ભાવનો કાચો કોટ તોપના ગોળાથી ન બચે. જેનું આત્માકારે વર્તન હોય તેનો વજ્રના કોટમાં નિવાસ છે એમ જાણવું, એ નિરભે થઈ ગયો. એને અપમાનની ચોટ ન લાગે. સત્સંગી માત્રને અમારે એવા બ્રહ્મરૂપ કરવા છે, તેનું માન કાઢવું છે. માયિકભાવ ટાળવો છે તેથી અપમાન કરીશું. એમાં બ્રહ્મરૂપ કરવા સિવાય અમારે કોઈ મતલબ નથી. અમારા યોગમાં આવ્યો તેને બ્રહ્મરૂપ કરવો, એ નિર્ધાર અમે કર્યો છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":543,"k":"para","g":"“એક ભગવાન સિવાય બધું અસાર છે - એમ મનાય ત્યારે જાણવું કે એ બ્રહ્મરૂપ થયો. જેની આત્માકારે દૃષ્ટિ થઈ તેને ભગવાન વિના બીજું મળ્યું કે ન મળ્યું કે હાથ આવેલું ટળી ગયું તોય લેશમાત્ર તેને ક્લેશ ન થાય, દુઃખ ન થાય. જે જે ક્રિયા કરો તે આત્મરૂપ થઈને કરવી, તો તે બંધન નહિ કરે. આત્મારૂપે વર્તે તે આકાશની પેઠે નિર્બંધ, નિર્લેપ રહે છે. આત્માને કોઈ ક્રિયા લાગતી નથી - એવું માની મારો ભક્ત કોઈ અધર્મનું આચરણ ન કરે. અધર્મ આચરે તેને પાખંડી જાણી તજી દેવો.”","e":null,"s":["4/74/5-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":544,"k":"para","g":"સુખપુરમાં રાવત ધાધલને ઘરે શ્રીહરિએ મુક્તમુનિને કહ્યું, “અમે જે વાત કરી તેમાં તમને સમજાયું નહિ. ભગવાનનાં દિવ્ય ચરિત્ર અને મનુષ્ય ચરિત્ર બંનેને દિવ્ય જાણે તેનો સત્સંગ દૃઢ સમજવો. ગોપીઓનો સત્સંગ દૃઢ હતો તો કૃષ્ણનાં યોગ્ય-અયોગ્ય ચરિત્ર દેખીને ઇન્દ્ર અને બ્રહ્મા જેવા દેવ ભૂલ્યા પણ ગોપીઓ ભૂલી પડી નહિ. ગોપીઓને તો મનુષ્યચરિત્ર દેખીને ભગવાનમાં પ્રેમની વૃદ્ધિ થઈ. ભગવાનનાં ચરિત્રોમાં સંદેહ ન થાય તો સાધનમાત્ર તેમાં આવી ગયાં. ભગવાનનો આવો દૃઢ નિશ્ચય જેને હૃદયમાં થયો તેને સત્સંગનો કેફ વર્તે. આવો ભક્ત હોય તેને અમે ઘરનો ત્યાગ કરવાનું કહીએ તોપણ સંશય ન થાય. મૃત્યુથી પણ ઘર છોડવાનું કામ કઠણ છે, પણ ભગવાનને સર્વોપરિ સમજે તેને કાંઈ કઠણ નથી.”","e":null,"s":["6/4/1-26"],"sv":["जितनो निश्चे उर में, भयो हे दृढ जाहि ।\n\n तितनो केफ सत्संग को, वर्तत जीय में ताहि ॥\n\n मृत्यु में घर छोडना, कठिन अति रहाय ।\n\n भगवान जाने सब पर जेहि, कछु कठिन न ताय ॥"],"mt":false,"gl":null,"a":false},{"i":545,"k":"para","g":"મેથાણમાં શ્રીહરિ બોલ્યા કે, “ભક્તોને અલૌકિક સુખ આપવા અમે સત્સંગમાં વારે વારે ફરીએ છીએ. અમારી એક પણ ક્રિયા સ્વાર્થને માટે નથી. અમારા આત્મસ્વરૂપના ચિંતન સિવાય બીજું કાંઈ અધિક જોતા નથી અને એ વિચારરૂપી જાણપણામાં રહીને જ અમે ભૂમિ ઉપર ફરીએ છીએ, જેથી અમને કોઈ પણ પદાર્થ આવરણ કરે એમ નથી. સ્વરૂપના સુખે સુખી છીએ. જગતનાં સુખમાં દુઃખ રહ્યાં છે તે સદાય દૃષ્ટિમાં રહે છે.”","e":null,"s":["6/26/12-17"],"sv":[],"mt":false,"gl":null,"a":false},{"i":546,"k":"para","g":"સરધારમાં શ્રીહરિએ વાત કરતાં કહ્યું, “સત્સંગ નીતિરૂપી પુરમાં ધર્મનો વાસ છે. સંતો-ભક્તો ને અમે એ પુરમાં વસીએ છીએ. જે ધર્મમાં રહે છે તેનાથી અમે લેશમાત્ર દૂર રહેતા નથી. એ જ રીતે નિષ્ઠા સમજણમાં ફેર રહે તેટલા અમે દૂર દેખાઈએ છીએ. લૌકિકભાવ અને દિવ્યભાવ - બે સમજણ છે. લૌકિક સમજણમાં નજીક હોવા છતાં દૂર લાગે છે દિવ્યભાવમાં દૂર હોવા છતાં નજીક લાગે છે. લૌકિક દૃષ્ટિમાં દુઃખ છે. દિવ્ય દૃષ્ટિમાં અપાર સુખ રહ્યું છે.”","e":null,"s":["6/44/10-15"],"sv":[],"mt":false,"gl":null,"a":false},{"i":547,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ જીવાખાચરને કહ્યું, “ભક્તનો જેવો ભાવ હોય તે પ્રમાણે અમે ચરિત્રો કરીએ છીએ, અમારી એ સરળ રીત છે. અમારી મૂર્તિ કલ્પવૃક્ષ સમાન છે. ભક્તનો ભાવ હોય તે તેમાં દેખાઈ આવે છે. તેમાં ક્યારેય વિષમભાવ હોતો નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":548,"k":"para","g":"“જેમ નિર્મળ દર્પણમાં જેવી વસ્તુ હોય તેવું પ્રતિબિંબ પડે છે. તેમાં કાચનો કોઈ ગુણ-દોષ નથી, છતાં કાચનો દોષ કહે તે મૂર્ખ છે. અને જેમ આકાશ ત્રણે ઋતુમાં સ્વભાવથી નિર્લેપ છે, તેમ જ્ઞાની મનુષ્ય અમારી મૂર્તિને સદાય નિર્મળ અને નિર્લેપ સમજે છે. તેવા જ્ઞાનીનો જે સંગ કરે તેને પણ તેવું જ્ઞાન થાય છે. જેના ચિત્તમાં અજ્ઞાનરૂપ વિકાર હોય તેને અમારો ગુણદોષ આવ્યા કરે છે. અને તે કૃષ્ણપક્ષના ચંદ્રની પેઠે દિવસે દિવસે સત્સંગમાં ઘટતો જાય છે.”","e":null,"s":["6/98/11-20"],"sv":[],"mt":false,"gl":null,"a":false},{"i":549,"k":"para","g":"રામગ્રીમાં જીવા પટેલને ઘરે થાળ જમીને શ્રીહરિએ વાત કરતાં કહ્યું, “ભગવાન ને સંતમાં જેટલો માયિકભાવ એટલો મોહ છે. જ્ઞાનરૂપી સૂર્ય જ્યારે ઉદય થાય છે ત્યારે એ મોહ અંધકાર ટળે છે.”","e":null,"s":["7/31/14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":550,"k":"para","g":"વડતાલમાં શ્રીહરિ કહે, “અમે જે જે સમૈયા કરીએ છીએ તે હરિજનોનું હિત કરવા કરીએ છીએ. ભગવાનને ભજતા સર્વે હરિજનો દિવ્ય છે. આ મર્મની વાત જે કોઈ સમજે, ધારે ને વિચારે છે તે મગ્ન થઈ જાય છે ને જગ જીતી જાય છે. આઠો પહર આનંદ એનો ટળતો નથી.”","e":null,"s":["9/4/25-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":551,"k":"para","g":"ધોરાજીમાં ભૂપના આમંત્રણથી શ્રીહરિ પધાર્યા. ત્યાં શ્રીહરિએ સભામાં રાજાને વાત કરતાં કહ્યું, “આ સભાનાં દર્શન કોઈને અંતકાળે યાદ આવે તો તેના પ્રારબ્ધનો નાશ થઈ જાય. આવું ધ્યાન કોઈ બ્રહ્માંડમાં નથી. આ સભાનું ધ્યાન અવતારો ધરે છે, અમે અને મુક્તો પણ આ ધ્યાન કરીએ છીએ. સંતો-ભક્તો મનુષ્ય જેવા દેખાય છે, પણ તે કોઈ મનુષ્ય નથી. અમે કહ્યું તે તો જીભ દાબીને બોલીએ છીએ. દેખીએ છીએ તેવું કહેતા નથી. અપાર વાતમાંથી તલભાર જેટલી બીજાને મનાય તેટલી કરીએ છીએ, પણ વિમુખને તો તલ પણ મેરુ જેવડો દેખાય છે. જે ઉદ્ધવ જેવા ભક્તો છે તે તો સત્સંગની બધી જ વાતને દિવ્ય સમજે છે. ભગવાનનો સંબંધ થાય તો તે દિવ્ય છે, એમ શાસ્ત્રમાં કહ્યું છે, તોય પણ દેહનો વ્યવહાર હોય તે પ્રમાણે ચાલવું જોઈએ. જગતની સ્થિતિ જે પ્રમાણે બંધાઈ છે તે સ્થિતિ રાખીને દિવ્યભાવ સમજવો. તે સ્થિતિને તોડે તો આધુનિક જાણવો.”","e":null,"s":["11/33/15-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":552,"k":"para","g":"જૂનાગઢમાં શ્રીહરિએ વર્ણીને વાત કરતાં કહ્યું, “જે અમાયિક છે (અર્થાત્ માયાથી પર અક્ષરબ્રહ્મ-પરબ્રહ્મ છે) તે સૌને અમાયિક જુએ છે. અમાયિક જોવા તે સવળી સમજણ છે ને તે જેટલી સિદ્ધ થાય તે મોક્ષ આપનારી બને છે. અને તેને જ બ્રહ્મવિદ્યા કહી છે. આ લોકમાં કે પરલોકમાં ભગવાનના સંબંધવાળી જેટલી વાત છે તેને બ્રહ્મવિદ્યા કહે છે.”","e":null,"s":["11/61(51-b)/35-36"],"sv":["अमायिक कर देखे सब तेहु । अमायिक जो कहावत जेहु ॥\n\n सुलट समझ मोक्षदायी जेती । ब्रह्मविद्या सो कहावत तेती ॥\n\n हरि संबंध जेति जेहि बातां । यह लोक परलोक हि रहाता ॥\n\n ब्रह्मविद्या हें ताके नामा । अर्थ जान बिन लहत न ठामा ॥"],"mt":false,"gl":null,"a":false},{"i":553,"k":"para","g":"મુક્તમુનિએ શ્રીહરિએ કહેલી વાતો ગઢપુરમાં કહી કે, “શ્રીહરિ કહેતા કે - જેમ ભગવાનમાં મોહ ન થાય તેવી જ રીતે ભક્તમાં પણ જેને મોહ ન થાય, ભગવાન અને ભગવાનના ભક્ત બ્રહ્મરૂપ છે, દિવ્ય પ્રકાશે યુક્ત છે, એમ સમજે તેનો મોક્ષમાર્ગ નિર્વિઘ્ન બની જાય છે. ભગવાન ને ભગવાનના ભક્તમાં જ્યાં સુધી પ્રાકૃત ભાવ આવે છે, ત્યાં સુધી તે પ્રાકૃત ભક્ત કહેવાય છે.”","e":null,"s":["11/86(77)/23-24"],"sv":["भगवान में मोह न होवे जेसे । भक्त में मोह न होवे तेसे ॥\n\n मोक्ष के मग में विघ्न जेता । तरत भये सो पार हि तेता ॥\n\n भगवान अरु भगवान के दासा । ब्रह्मरूप रहे दिव्य प्रकाशा ॥\n\n प्राकृतभाव आवे ज्यां लगहि । प्राकृत भक्त कहे त्यां लगहि ॥"],"mt":false,"gl":null,"a":false},{"i":554,"k":"para","g":"મુક્તમુનિએ શ્રીહરિએ કહેલી વાતો ગઢપુરમાં કહી કે, “શ્રીહરિ કહેતા કે - હું માન હોય તેને પગે લાગતો નથી, પરંતુ જે હરિ ને હરિજનનો દાસ થયો તે ભક્તને સર્વોપરી માનું છું. આ અમારા નિશ્ચય જેવો જેને મતિમાં નિશ્ચય હશે તેને કદી માન નહિ આવે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":555,"k":"para","g":"“અમારું ધામ સર્વોપરી છે, તેના નિવાસી આ સર્વે હરિજન છે. આવી બુદ્ધિ સદા જેને હોય તેને ક્યારેય માન આવતું નથી. હરિજનને આ લોકના સમજે છે તેના હૃદયમાં કામ, ક્રોધ, લોભનાં પૂર આવ્યાં કરે છે. તેમાં તે તણાયા કરે છે ને અધર્મવંશથી દુઃખી થાય છે. હરિજનોને પરસ્પર અભાવ આવે છે, તેનું કારણ લૌકિકભાવ છે. જો દિવ્યભાવ રાખે તો ક્લેશ આવતો નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":556,"k":"para","g":"“સંતો, બાઈ-ભાઈ, બ્રહ્મચારી, પાળાઓ - સર્વેને એકબીજામાં જ્યાં સુધી પ્રાકૃતભાવ હશે ત્યાં સુધી સત્સંગ કરવા છતાં સુખ નહિ આવે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":557,"k":"para","g":"“જેને સત્સંગ થયો તેનો બીજો જન્મ થયો જાણવો, તેનું નામ પણ ‘સત્સંગી હરિજન’ પડ્યું, સત્સંગરૂપી સર્વોપરી ધામમાં દિવ્ય મુક્તો સાથે નિવાસ થયો એટલે સંત, વર્ણી, હરિજન બધા જ એક ઘરના પરિવાર જન થયા. એમ સમજી એક મન રાખીને સર્વે વર્તે તો ક્લેશનું નામ ન રહે.”","e":null,"s":["11/87(78)/32-40"],"sv":["हरि कहे मान देखूँ में जेहा । पाव कबु में लागूँ न तेहा ॥\n\n हरि हरिजन के दास हि जितने । सर्वोपरि में मानत तितने ॥\n\n सर्वोपरि हरिधाम जो कहावे । हरिजन ताके निवासी रहावे ॥\n\n एसी मति सदा हरिजन में । मान न आवे कबु तेहि तन में ॥\n\n काम क्रोध लोभ उर मांही । वेर वेर तनावत रहा हि ॥\n\n इहां के हरिजन जानत जेहु । अधर्मवंश दुःखि करत हें तेहु ॥\n\n परस्पर हरिजन में जेहि । विरोध होइ जावत अति तेहि ॥\n\n इहां की मति रखे होवत क्लेशा । हम जानत त्युं कहे तेसा ॥\n\n संत बाई-भाई सब, ब्रह्मचारी पदाति ।\n\n इहां के जानत जाहि लग, तिहां लग सुख न रहाति ॥\n\n सत्संग भये जाहि कुं, ताके जन्म भये ओर ।\n\n हरिजन परे नाम तेहि, कुसंग तजे कुनोर ॥\n\n सत्संगरूपी धाम, सर्वोपरि सो धाम रहेउ ।\n\n हरिजन जितने नाम, तामें किये हें निवास सब ॥\n\n संत वर्णि हरिजन, एक घर के भये तेहि ।\n\n एक रहे एसो मन, करे क्लेश न होय तब ॥"],"mt":false,"gl":null,"a":false},{"i":558,"k":"para","g":"શ્રીહરિએ જસદણથી પીપરડી જવા વિદાય લેતા પૂર્વે પુરજનોને વાત કરતાં કહ્યું, “આ જગતમાં જે અધર્મ રાખે અને અમારો તથા અમારા સંતો-હરિભક્તોનો જે અવગુણ બોલે તેવા જનનો ત્યાગ કરવો. દેહમાં પ્રાણ રહે ત્યાં સુધી આટલો નિયમ રાખજો. તો અમે તમારો તત્કાલ ઉદ્ધાર કરીશું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":559,"k":"para","g":"અમારો તથા અમારા સંતો-હરિજનોનો જે ગુણ કહે છે તેનો અમે તત્કાળ ઉદ્ધાર કરીએ છીએ. આ અવસરે અમે એવી ટેક લીધી છે. ભૂમિ પરના જનમાત્રનો ઉદ્ધાર કરવો છે, પરંતુ જે જન અમારા સંતો-હરિજનોના અવગુણ કહે ને બીજાની પાસેથી સાંભળે તો તેનો ઉદ્ધાર ક્યારેય થતો નથી, એ તો બધા જમપુરીમાં જાય છે. મોક્ષ થાય અને મોક્ષ ન થાય એ બંને વાત જેમ છે તેમ તમને પ્રગટ કહી છે. આટલી વાત અંતરમાં દૃઢ કરીને રાખજો. આ અમારી આજ્ઞા છે.”","e":null,"s":["12/40/7-10"],"sv":["हमारो संत हरिजन ताके । जे जन बोलत गुन हि वाके ॥\n\n ताके सद्य हम करत उद्धारा । एसी हम टेक रखे यह वारा ॥\n\n भूमि पर जन हि रहे जेता । उद्धार करन हम आये तेता ॥\n\n हमारे संत हरिजन के जेहि । अवगुन कहत सुनत तेहि ॥\n\n ताको उद्धार होत न कबहि । ऐसे जमपुरी जावत सबहि ॥\n\n मोक्ष होत न होवत जेहु । प्रगट वात कहि दीने तेहु ॥\n\n इतनि वात उरमें दृढ रखना । तुमकु कहे हम एक हि वचना ॥"],"mt":false,"gl":null,"a":false},{"i":560,"k":"para","g":"શ્રીહરિએ પત્રમાં લખાવ્યું, “ખોખરા મહેમદાવાદમાં યજ્ઞ કરવો છે. યજ્ઞ થાય ન થાય એ ભગવાનના હાથની વાત છે, પણ તેમાં સંશય ન થાય તે હરિભક્ત પાકો કહેવાય. અમારાં ચરિત્ર જોઈ સત્સંગ છૂટી જાય તેવાને સાથે લાવવો નહિ.”","e":null,"s":["12/71/36-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":561,"k":"para","g":"નાગર સેનાપતિ કરિયાણામાં દેહાખાચરના ભવનમાં શ્રીહરિના દર્શને આવ્યો. શ્રીહરિએ ઉપદેશ આપતાં તેને કહ્યું, “જેને મોક્ષનો અંકુર હોય, તેને જ્ઞાનનો પ્રકાશ થાય છે ને અજ્ઞાન તમ ટળે છે. અમારી રીત અને અમારા સંતની રીત અલૌકિક છે, દિવ્ય છે, તે દેખાઈ આવે છે. જેનામાં મોક્ષનો અંકુર જ નથી તે અજ્ઞાન તમસથી ભરેલો રહે છે, તેની મતિ અંધકારયુક્ત હોવાથી અમારી અને સંતની અલૌકિક રીતને માયિક સમજે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":562,"k":"para","g":"“બહુત કાળ સુધી સત્સંગ કરે ત્યારે તેનું અજ્ઞાન-તમ ટળે છે. અમારી વાત માયા પરની અલૌકિક છે. તે કોઈને તરત સમજ્યામાં આવતી નથી. જેમ ચમક પથ્થર છે, પણ લોઢાને ચલાવી દે છે, ચિંતામણિ પથ્થર જેવી જ લાગે પણ જેને તેનું જ્ઞાન છે તેને તે અલૌકિક લાગે છે તેમ ભગવાન અને સંત મનુષ્ય જેવા જ લાગે, પણ જેને ઓળખાણ થઈ તેને દિવ્ય અલૌકિક લાગે છે.”","e":null,"s":["13/29/9-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":563,"k":"para","g":"શ્રીહરિએ જૂનાગઢમાં દાદાભાઈને વાત કરતાં કહ્યું, “જેની જીભ પર પરબ્રહ્મ પુરુષોત્તમના ગુણોનું વર્ણન હોય અને મનુષ્યભાવ અને દિવ્યભાવ બન્નેમાં એકમતિ રહેતી હોય, તેનાં નામ ગ્રંથોમાં લખાયાં છે. ભગવાનનો ખરો મુમુક્ષુ ભક્ત જ એ છે કે ભગવાન અને સંબંધવાળા ભક્તોમાં તે મનુષ્યભાવ ન પરઠે. જો ક્યારેય મનુષ્યભાવ દેખી અભાવ ન આવે તો તેનો મોક્ષ નક્કી છે, તેમાં સંદેહ નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":564,"k":"verse","g":"‘હરિ-હરિજન કે મનુષ્યભાવા, મુમુક્ષુ દેખિ ન લેત અભાવા;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":565,"k":"verse","g":"મોક્ષ હોત તાકે ન સંદેહા, શ્રીહરિ બાત કહિ સો તેહા.’","e":null,"s":["13/39/29-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":566,"k":"para","g":"શ્રીહરિએ આખા ગામના હરિજનો પાસે વાત કરતાં કહ્યું, “આ સત્સંગને અમે ચિંતામણિ સમાન દેખીએ છીએ અને હરિભક્તોને કલ્પવૃક્ષ જેવા દેખીએ છીએ ને છતાં હરિજનો પરસ્પર એકબીજામાં મનુષ્યભાવ દેખે છે, મનુષ્યભાવે કરીને એક એકનો દ્રોહ થાય છે, દ્રોહથી આસુરી બુદ્ધિ થઈ જાય છે, પછી મહિમાનો ભાવ ક્યાં રહે! અરે! જેના થકી મોક્ષ માન્યો હોય તેનો (ભગવાન અને સંતનો) પણ તેને અભાવ આવે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":567,"k":"para","g":"“જ્યાં સુધી મનુષ્યભાવ નથી આવતો, ત્યાં સુધી સૌ પ્રત્યે સૌને પરમભાવ વર્તે છે. આ પરમભાવ છે તે મોક્ષનું દ્વાર ખોલી આપે છે. મનુષ્યભાવ આવ્યો તો જાણવું કે મોક્ષદ્વાર બંધ થયું ને તમ(અજ્ઞાન અંધકાર)નું દ્વાર ખૂલ્યું. માટે ભક્તોએ પરસ્પર સુહૃદભાવ રાખવો. એક ભક્ત બીજા ભક્ત પ્રત્યે જેટલો સુહૃદ થયો તેટલો તે અમારો પ્રાણ થયો. સુહૃદપણું અમારો પ્રાણ છે. અમે પરસ્પર અરુચિ, દંભ રહે તેને શત્રુ માનીએ છીએ. જે સર્વોપરી હરિભક્ત છે તેની આ સુરીત છે તે કહી. ભગવાન ને ભગવાનના ભક્તો-સંતોમાં અધિક ભાવ રાખવો. અમે જે જે નિયમ કહ્યા છે તેમાં તત્પર રહેતા હોય ત્યાં સુધી તેનો અભાવ ન લેવો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":568,"k":"para","g":"“નિયમભંગ કરે તો તેને ભાવ ન દેવો, એટલું જ, પણ તેનો અભાવ તો લેવો જ નહિ. જ્યાં સુધી નિયમમાં વર્તન છે, ત્યાં સુધી તે સાધુ કે હરિજન કહેવાય છે, ને નિયમ પાળે ત્યાં સુધી તેને નભાવવો. કારણ, નિયમ પાળે છે ત્યાં સુધી કલ્યાણનું બારું બંધ થતું નથી. નિયમભંગ કરે પછી તેનું ઠેકાણું નહિ. જે નિયમભંગ કરતો હોય, તે અમારો દ્રોહી છે. વળી, જે સાચા સંત સાથે ને હરિજન સાથે સુમેળ ન રાખે ને કુમેળ રાખે તે પણ અમારો દ્રોહી છે. જે હરિજન સાચા સંત કે એકાંતિક ભક્ત પાસે ચિત્ત ચોરે, કપટ રાખે એટલો તે કાચો રહે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":569,"k":"para","g":"“સાચા સંતને મનથી નિર્દોષ જાણી તેમની સાથે સરળ વર્તે એવા ભક્તને સત્સંગનો આનંદ અખંડ રહે છે. હરિજન હોય પણ જો તે મોક્ષના દ્વારરૂપ ગુરુ-સંતનો અવગુણ બોલે તો તે અમારો દ્રોહી છે.”","e":null,"s":["14/31/17-28"],"sv":["यह सत्संग कहावत जेता । चिंतामनि हम देखत तेता ॥\n\n हरिजन जो कहावत हि जेते । कल्पवृक्ष हम देखत तेते ॥\n\n परस्पर जो हरिजन जितना । मनुष्यभाव देखत हें तितना ॥\n\n मनुष्यभाव करिके कबहु । एक एक के द्रोह होवे तबहु ॥\n\n द्रोह से बुद्धि आसुरि होवे । महात्म्यरूप भाव हि खोवे ॥\n\n जिनसे माने मोक्ष को भावा । ताके बोलत पिछे अभावा ॥\n\n मनुष्यभाव नहि जिहां लगहु । परमभाव वरतत तिहां लगहु ॥\n\n परमभाव है मोक्ष को द्वारा । मनुष्यभाव तमद्वार नकारा ॥\n\n तम में निवास हम करे न कबहि । हरिजन सुहृद रखना सबहि ॥\n\n सुहृद तितनो हमारे हें प्राना । अरुचि दंभ शत्रु हम माना ॥\n\n सर्वोपरि हरिजन जो ताकी । सुरीत यह सो कहत हें वाकी ॥\n\n हरिजन संत भगवान तामें । सबसें भाव अधिक रहे यामें ॥\n\n जाके नियम कहे हें जेसे । तत्पर तामें वरते तेंसे ॥\n\n तिहां लग तामें अभाव न लेना । नियमभंग ताकुं भाव न देना ॥\n\n हरिजन कहे वरते ज्यां लगहि । निभाव ताहि करना त्यां लगहि ॥\n\n त्यां लग ताके होत कल्याना । नियमभंग के नाहि ठिकाना ।\n\n नियमभंग करे जितनो, तितनो द्रोही हे तेह ।\n\n साचे संत हरिजन मे, कुमेल द्रोही हे एह ॥\n\n साचे संत हरिजन से, जितनो चित्त चोरात ।\n\n तितनो वगल हे ताहि में, प्रसिद्ध आत देखात ॥\n\n साचे संत हरिजन, तिनसे जितने सरल रहत ।\n\n शुद्ध हि जानत मन, सत्संग में मोज करत ॥\n\n हरिजन शुद्ध संत, मोक्ष के हे जो द्वार यह ।\n\n अवगुन ताके कहंत, एसे कुं द्रोही कहत हम ॥"],"mt":false,"gl":null,"a":false},{"i":570,"k":"para","g":"સારંગપુરમાં જીવા ખાચરના દરબારમાં સંતોનાં મંડળો મળ્યાં. શ્રીહરિ કહે, “જ્યાં સુધી સંતોમાં પરસ્પર મહાઅલૌકિક ભાવ રહે, હેત રહે ત્યાં સુધી ભગવાન પ્રગટ છે.”","e":null,"s":["14/84/15-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":571,"k":"para","g":"કુંડળમાં શ્રીહરિએ રામદાસ સ્વામી આદિ સંતોને વાત કરતાં કહ્યું, “જ્યાં સુધી પ્રાકૃતમતિ હોય ત્યાં સુધી લેશ પણ સત્સંગ કર્યો નથી. પ્રાકૃતમતિ હોય તેને પ્રાકૃત ભોગ મળે છે. પ્રાકૃત સમજણવાળા સંત-હરિભક્તોની વાતમાં પણ પ્રાકૃત સમજણ દેખાય છે. દિવ્ય સમજણવાળા સંતો-ભક્તો સત્સંગને દિવ્ય માને છે. ભગવાનમાં દિવ્યભાવ-મનુષ્યભાવ એક કરી જાણે છે તેને અપ્રાકૃત (દિવ્ય) જાણવા. વિષયમાં રુચિ હોય તેને ભગવાનનાં ચરિત્રોમાં મોહ થાય છે. અભ્યાસ કરવાથી જેની જેવી રીત-રુચિ હોય તે જાણ્યામાં આવે છે.”","e":null,"s":["15/25/29-32"],"sv":[],"mt":false,"gl":null,"a":false},{"i":572,"k":"para","g":"વલાસણમાં પાટીદારના ફળિયામાં શ્રીહરિએ વાત કરતાં કહ્યું, “ભગવાન અને સંત કલ્પવૃક્ષ અને ચિંતામણિ જેવા છે. તેમને જેવા ભાવે દેખે તેવું ફળ મળે છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":573,"k":"verse","g":"‘કલ્પવૃક્ષ ચિંતામનિ જેસે, ભગવાન સંત રહાયે તેસે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":574,"k":"verse","g":"તાકું દેખત હેં જેસિ રીતા, ફલ હોવત તેહિ તેસિ રીતા.’","e":null,"s":["15/49/34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":575,"k":"para","g":"ગઢપુરમાં શ્રીહરિ સંતોને કહે, “અમે તમારો ત્યાગ જોઈને પ્રસન્ન થયા છીએ, પણ અમે તમને જે વચન કહીએ તે પ્રમાણે કરવું એ અતિ કઠણ વાત છે. પોતાને ધાર્યે તન છૂટતું હોય તો તે તલ જેટલું કઠણ લાગતું નથી, વળી, પ્રારબ્ધે કરીને વારંવાર અપાર દુઃખ આવે તોપણ સહન થઈ શકે છે. કોઈ બ્રહ્માંડમાં પ્રવેશ કરે તે પણ સહેલું છે, કારણ કે વૈરાજ નામનો જીવ તેમાં પ્રવેશ કરીને રહ્યો જ છે, પણ અમારા વચને પોતાને અક્ષરરૂપ માનવું તે થઈ શકતું નથી. જેના એક એક રોમમાં અનંતકોટિ બ્રહ્માંડ રહ્યાં છે. રોમ રોમ બ્રહ્માંડોનો બોજ ધરી રાખવો તે અક્ષર સિવાય કોઈથી થતું નથી. પોતાને અક્ષર માને તે રોમે રોમે એવો બોજ રાખી રહ્યો છે એ આશ્ચર્યની વાત છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":576,"k":"para","g":"“આવી અલૌકિક વાત લૌકિક એક એક તનમાં અપાર રહી છે, પણ લૌકિક સમજણ છે, ત્યાં સુધી તેને માયિકભાવ ટળતો નથી, અલૌકિક સમજણ આવે તેટલી અમાયિક (માયા પારની, દિવ્ય) સમજણ જાણવી. આ વાતનો નિત્ય અભ્યાસ રાખવો. બે જણ એક અંગમાં રહ્યા હોય તેમાં એક અભ્યાસ રાખે ને બીજાને જો અભ્યાસ ન હોય તો એકને જ્ઞાન થાય છે, બીજાને થતું નથી. જેવો અભ્યાસ કરે તેવું રૂપાંતર થાય.”","e":null,"s":["15/58/28-35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":577,"k":"para","g":"શ્રીહરિએ પત્ર લખાવ્યો તેમાં કહ્યું, “અમારે સંતો-હરિજનો પર અપાર હેત છે. એટલે સૌની હિતકારી વાત લખીએ છીએ – અમે જે વાત લખીએ કે કહીએ તે સઘળી વાત બ્રહ્મમહોલના માર્ગની છે. અમારાં બધાં ચરિત્રો અને ક્રિયાઓ મોક્ષકારી છે. એમાં જે માયિકભાવ પરઠે છે તેનો મોક્ષ થતો નથી, તે જીવ લખચોરાસીમાં વારંવાર ભટકે છે. અમારું તાન કુમાર્ગનો ત્યાગ કરાવવા પર રહ્યું છે. એ તાન તમારે પણ રાખવું.”","e":null,"s":["15/88/16-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":578,"k":"para","g":"શ્રીજીમહારાજે પત્ર લખાવ્યો: “સત્સંગના યોગ વિના બ્રહ્મા જેવાનો પણ મોક્ષ ન થાય. પરમેશ્વરની વાતમાં જેને દૃઢ વિશ્વાસ આવ્યો તે વિદ્યામાત્ર ભણી ચૂક્યો. અંગઉપાંગ સહિત કોઈ વેદ ભણે, પણ ભગવાનમાં આસ્થા ન થાય. ભગવાનમાં આસ્થા અને મોક્ષ બંને સાથે જ રહે છે. જેને સત્સંગ મળે છે તેને જ ભગવાનમાં દૃઢ આસ્થા થાય છે, સત્ય-અસત્યનો વિવેક આવે છે. મોક્ષને સહાય કરે તે સત્ય વસ્તુ છે, બીજી અસત્ય છે. અસત્યનો ત્યાગ થાય છે ને સત્યનું ગ્રહણ થાય છે. અસત્ય પર લક્ષ્ય રહે તેટલો કુસંગ જાણવો. તેની ભવભટકણ ટળે નહિ.”","e":null,"s":["15/98/29-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":579,"k":"para","g":"શ્રીહરિએ પત્રમાં લખાવ્યું: “ભગવાન પુરુષોત્તમ નિર્ગુણ છે, તેમનાં ચરિત્રો નિર્ગુણ છે. તેમાં ગુણ પરઠાય તેટલું માયાનું આવરણ છે. શુક, સનકાદિક, નારદ, વ્યાસ, ઉદ્ધવ, પ્રહ્‌લાદ સરખા દાસ થાય તેને અક્ષરધામમાં જેવા પુરુષોત્તમ ભગવાન છે તેવા જ મનુષ્યતન ધરે ત્યારે પણ દિવ્ય જણાય છે. ભગવાનને માયાના ગુણ બાધ કરતા નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":580,"k":"para","g":"“નિર્ગુણપણું અને સગુણપણું એ તો ભગવાનની યોગકળા છે. ભગવાન તો એ બેઉના કારણ છે. આવું જાણી ભક્તિ કરતા હરિભક્તો માયાના ગુણથી મુક્ત થઈ અક્ષરધામમાં જઈને નિવાસ કરે છે.”","e":null,"s":["15/98/35-41"],"sv":[],"mt":false,"gl":null,"a":false},{"i":581,"k":"para","g":"સારંગપુરમાં રાઠોડ ધાધલે શ્રીહરિનો ખૂબ લહાવો લીધો. ગઢપુરથી જીવુબા તથા સૂરબાઈ વગેરે શ્રીહરિને તેડવા માટે આવ્યાં. તેમણે અન્ન-જળ ત્યાગ્યાં હતાં અને રુદન કરતાં હતાં. શ્રીહરિએ દયા લાવીને દર્શન દીધાં ત્યારે અન્ન જમ્યાં. શ્રીહરિ કહે, “અમે ગઢપુર આવીશું. જેમનામાં શ્રદ્ધા છે, આદર છે, પ્રીત છે એવા ભક્તમાં જો અલૌકિક ભાવ આવે તો એ સરસમાં અતિ સરસ થઈ જાય છે. જેનામાં જેટલો દિવ્યભાવ તેટલા તે અમને ગમે છે. જેને અલૌકિકમાં જ્યારે લૌકિકભાવ દેખાય છે, ત્યારે અમે તરત ઉદાસ થઈ જઈએ છીએ. અમે આ વાત ઘણીવાર સમજાવી છે, પણ કોઈ સમજતું નથી.”","e":null,"s":["16/14/27-29"],"sv":["अलौकिक जो फल रस, श्रद्धा आदर प्रीत रहेउ ।\n\n सरस में अति सरस, उत्तम में हें उत्तम यह ॥\n\n श्रेष्ठ में इतनो श्रेष्ठ, अलौकिक जितनो भाव जो ।\n\n नेष्ठ में अति नेष्ठ, लौकिक समझ रहे जेति सो ॥\n\n अलौकिक में लौकिक भावा । हमकुं जब आवत देखावा ॥\n\n तरत उदास होवत तबहु । समझावत तोउ समझत न कबहु ॥"],"mt":false,"gl":null,"a":false},{"i":582,"k":"para","g":"શ્રીહરિએ ધર્મપુરમાં ભૂપનો ભાવ દેખીને કહ્યું, “હરિજનો અને સંતો અમારાં દર્શન કરે છે, તેમાં જેને જેટલો અધિક ભાવ તેને તેટલું ફળ થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":583,"k":"para","g":"“નિર્દોષબુદ્ધિવાળા સૂર્ય સમાન છે. જેને નિર્દોષભાવ નથી તે ચંદ્રની કળાની પેઠે વધતો-ઘટતો રહે છે. સૂર્ય ક્યારેય વધતો-ઘટતો નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":584,"k":"para","g":"“માયિકભાવ હોય ત્યાં સુધી સત્સંગનો પ્રતાપ જેવો છે તેવો જાણ્યામાં આવતો નથી. સંતો-ભક્તોને માયિક જાણે પછી તેનો અભાવ આવે છે. ભગવાન તેને અંત સમયે સત્સંગનો યથાર્થ પ્રતાપ દેખાડીને દિવ્ય કરી મૂકે છે.”","e":null,"s":["16/24/3-9"],"sv":[],"mt":false,"gl":null,"a":false},{"i":585,"k":"para","g":"શ્રીહરિએ પીપળાવમાં કહ્યું, “અમે અહીંયાં જેવા રૂપે રહ્યા છીએ તેવા જ ધામમાં છીએ. તેમાં કાંઈ પણ મિથ્યા નથી. મિથ્યા બોલે તેને કોટિ કાળે નરકનો અંત આવતો નથી.”","e":null,"s":["16/55/13-15"],"sv":[],"mt":false,"gl":null,"a":false},{"i":586,"k":"para","g":"શ્રીહરિએ વડતાલમાં સંતોને વાત કરતાં કહ્યું, “અમે અક્ષરધામથી આવ્યા છીએ, એટલે અમારી સઘળી વાત આશ્ચર્યકારક છે. જેને અમારી વાત આશ્ચર્યકારી લાગતી હોય તે અમારી સેવાને દુર્લભ માને છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":587,"k":"para","g":"“વળી, સંતોની સેવા પણ દુર્લભ છે. તે થોડા પુણ્યવાળાને મળતી નથી, આ વાત જીવનું જીવન છે. ભગવાનનું માહાત્મ્ય જેમ છે તેમ યથાર્થ જાણવું. યથાર્થ માહાત્મ્ય જાણ્યા વિના સત્સંગમાં નભી શકાતું નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":588,"k":"para","g":"“વળી, સંતો-હરિજનોનું માહાત્મ્ય જેવું જાણવું જોઈએ તેવું યથાર્થ જાણતો ન હોય અને ભગવાનનો નિશ્ચય પૂરો હોય તોપણ સત્સંગમાં નભી શકતો નથી, તે સત્સંગથી અતિશય દૂર થઈ જાય છે. ભગવાનનો, સંતોનો, હરિભક્તોનો મહિમા સમજવામાં તલ જેટલી કસર રહી, એટલો પ્રમાદ પણ તેને નિશ્ચય હોવા છતાં ફેંકી દે છે. એવું અપાર માયાનું બળ છે. પૂર્વે ઇન્દ્ર, ભવ-બ્રહ્માદિક દેવતાને તથા ભગવાનનું મન કહેવાતા નારદને પણ માયાનું બળ પરાભવ કરી ગયું છે. માટે સાવધાન રહેવું.”","e":null,"s":["16/58/8-13"],"sv":["अक्षरधाम से आये ताकि । आश्चर्य बात रहाये वाकि ॥\n\n हमारी सेवा दुर्लभ माने । मन में तेहि आश्चर्य जाने ॥\n\n यह सब संत की सेवा जोउ । थोरे पुन्य न मिलत सोउ ॥\n\n आश्चर्य दुर्लभ मानत रहाहि । जीवन बात हि समझे ताहि ॥\n\n भगवान के माहात्म्य जेसे । जथार्थ जाने चैये तेसे ॥\n\n जथार्थ जाने बिन हि ताई । सत्संग में निभत न रहाई ॥\n\n संत हरिजन रहाये केसे । यथार्थ जाने बिन तेसे ॥\n\n भगवान के निश्चय होय पूरा । तोउ हो जावे अति दूरा ॥\n\n भगवान संत हरिजन तामें । समझवे में तिलभर यामें ॥\n\n कसर रतिभर होय न तोउ । परमाद जितनो रखत कोउ ॥\n\n निश्चय रखत रखत उड जावे । माया के बल अपार रहावे ॥\n\n इन्द्र भव ब्रह्मादिक जेहु । नारद भगवान के मन तेहु ॥"],"mt":false,"gl":null,"a":false},{"i":589,"k":"para","g":"શ્રીહરિએ વડતાલમાં સંતોને વિવેક શીખવતાં કહ્યું, “ભગવાન ગર્વગંજન છે. જેની મતિ સંત-હરિજનમાં જેવી હોય તેવી ભગવાન તેની પણ કરી દે છે. જો તે સંતો-ભક્તોમાં નિર્દોષબુદ્ધિ રાખે, તો ભગવાન તેને નિર્દોષ કરી મૂકે છે. દોષ ગ્રહણ કરતો હોય તો તેનામાં બધા દોષ આવીને વસે છે. ભક્તમાં દોષ ન હોય ને દોષ જુએ તો જોનારને અંતરમાં સુખ રહેતું નથી, વગર અગ્નિએ તન બળે છે. અંતરની વ્યથા કહેવાય નહિ ને સહેવાય નહિ એવી થાય છે, પણ એ દંભી ક્યાં સુધી છુપાવી રાખે! અંતર્યામી બધું જ જાણે છે.”","e":null,"s":["16/58/23-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":590,"k":"para","g":"સંતો પ્રત્યે વડતાલમાં શ્રીહરિએ વાત કરતાં કહ્યું, “શ્રવણ, મનન, નિદિધ્યાસન અને સાક્ષાત્કારમાં બધાં સાધન આવી જાય છે. તેમાં શ્રવણ પ્રથમ છે. શ્રવણ કરેલી વાતને મનન કરીને ગ્રહણ કરવા યોગ્ય એટલી ગ્રહણ કરે અને બીજી ત્યજી દે. ગ્રહણ કર્યા પછી તે વાતનો વારેવારે અભ્યાસ કરવો, જેથી તેનો સાક્ષાત્કાર થાય. સંત કહે તેમ કરે તે અપાર સુખ પામે છે. સંતમાં લોભ દેખે તેની મતિ દૂષિત થઈ જાય છે. પછી સંતનાં વચન તેને ઝેર સમાન લાગે છે. તેને જે જે મળે તેના હૃદયમાં પણ તે સંતના દોષ સંભળાવીને અભાવ નાખે છે. પોતાને જ્વર થયો તેમાં અન્નનો શો દોષ? સંત અન્ન જેવા નિર્દોષ છે. દોષ જણાય છે તે પોતાનો છે એવું ભાન થાય તો સંતનાં વચન અમૃત જેવાં લાગે. સંતમાં નિર્દોષબુદ્ધિ થઈ ત્યારે જાણવું કે તે સત્સંગમાં વધતો રહેશે. સાચા સંતનું વર્તન ભગવાનનાં વચન અનુસાર હોય છે. ભગવાનને નિર્દોષ જાણ્યા તેને સંત નિર્દોષ જણાય છે.”","e":null,"s":["16/70/1-22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":591,"k":"para","g":"વડતાલમાં શ્રીહરિએ સંતોને ઉદ્દેશી કહ્યું, “અમારાં ચરિત્રને જે દિવ્ય સમજે છે તેનો ભવરોગ ટળે છે. તેમાં મનુષ્યભાવ લાવે છે, તેનો ભવરોગ ટળે નહિ. સત્સંગની વાતનું આલોચન ન થાય તેટલી કસર રહી જાય છે.”","e":null,"s":["17/4/34-37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":592,"k":"para","g":"વડતાલમાં રાયણ નીચે શ્રીહરિએ સંતો પ્રત્યે કહ્યું, “રામાનંદ સ્વામી સ્વધામ ગયા તે દિવસથી અમારી રુચિ ત્યાગ ઉપર રહી છે. અને તે રીતે અમે હિત લાવીને સંતોને વર્તાવીએ છીએ. અક્ષર સમાન કોઈ સમર્થ નથી છતાં તે પરમેશ્વર આગળ દસ-દીન થઈને વર્તે છે. એવા પરમેશ્વર મનુષ્ય તન ધારે છે ત્યારે સઘળી ક્રિયા મનુષ્ય જેવી હોય છે, પણ એ અલૌકિક છે, દિવ્ય છે. આ વાત બધા મનુષ્યને દેખ્યામાં આવતી નથી. પરમેશ્વર ભેગો સદા રહે તોપણ પરમેશ્વરનું રહસ્ય તે જાણી શકે નહીં. એ તો જેને પરમેશ્વરનું જ એક તાન રહે, પરમેશ્વર સિવાય ચિત્તમાં કંઈ હોય નહીં, એમ પરમેશ્વરાકાર મતિ થાય તેને આ રહસ્ય હાથમાં આવે છે.”","e":null,"s":["17/9/5-11"],"sv":[],"mt":false,"gl":null,"a":false},{"i":593,"k":"para","g":"પંચાળામાં શ્રીહરિ કહે, “સત્સંગ કરવામાં એક સરખી રીત રહેતી નથી. ભગવાન અને સંતની પ્રસન્નતામાં ફેર તેટલો મોક્ષમાં ફેર. સત્સંગ કરતાં કરતાં ભગવાનને, સંતને તથા હરિભક્તને કુરાજી કરે તેનો દોષ લાગે છે. એ દોષનું ફળ મનુષ્યબુદ્ધિ છે. જ્યાં સુધી મનુષ્યભાવ રહે છે ત્યાં સુધી ભવભટકણ ટળતી નથી, અંતરમાં પણ સુખ આવતું નથી. રાત-દિવસ ક્લેશ મટતો નથી. માટે સંત, ભગવાન અને હરિભક્તો જેમ પ્રસન્ન થાય તેમ મન, કર્મ, વચને કરે તેની અલૌકિક મતિ કહેવાય અને તેનો સત્સંગ પણ શુભ છે.”","e":null,"s":["17/20/1-9"],"sv":[],"mt":false,"gl":null,"a":false},{"i":594,"k":"para","g":"શ્રીહરિએ પિપળાવથી મહેળાવ જતાં રસ્તામાં વાત કરી, “જેને ભગવાનનો યથાર્થ નિશ્ચય થયો તે જન માયિક જેવા દીસે તોપણ તેને અમાયિક જાણવા. ભગવાનને પ્રસન્ન કરવા તે અક્ષરધામથી અહીં આવ્યા છે. દેખવા માત્રે મનુષ્ય જેવા લાગે, પરંતુ તે હરિજન અક્ષરરૂપ છે. માયિકજનોને અમાયિક કરવા ભગવાનની મરજીથી તે માયિક જેવા થયા છે.”","e":null,"s":["17/25/3-4"],"sv":[],"mt":false,"gl":null,"a":false},{"i":595,"k":"para","g":"અમદાવાદ નવાવાસમાં શ્રીહરિ સભા કરીને બિરાજ્યા અને વાત કરવા લાગ્યા, “સત્સંગમાં સંત-હરિભક્તોને અલૌકિક દેખે તે પરમપદનો અધિકારી છે. એવા ભક્તનો મોક્ષ નિશ્ચય થઈ ગયો જાણવો. એમાં રંચમાત્ર ફેર નથી. આ સમજણમાં જેટલો ફેર તેટલો મોક્ષમાં ફેર રહે છે. સત્સંગમાં જેટલો દિવ્યભાવ તેટલો તેનો નિષ્કપટ સત્સંગ જાણવો. અલૌકિક ભાવ લાવીને સત્સંગ નથી કરતો, તેટલો કુસંગ છે.”","e":null,"s":["18/83/12-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":596,"k":"para","g":"બોટાદમાં શ્રીહરિએ ભગાશેઠ આદિ ભક્તો આગળ વાત કરતાં કહ્યું, “સંત-હરિભક્તને દિવ્ય દેખે પણ મનુષ્યભાવ ન દેખે એવા હરિજન વિરલ હોય છે. એનો સંગ કરવો. મનુષ્યભાવ રહે તેટલું વિઘ્ન છે. મનુષ્યભાવ આવે પછી દ્રોહ થાય ને સત્સંગથી દૂર થઈ જાય. પરસ્પર મન મળેલાં રહે તે પડે નહિ.”","e":null,"s":["19/12/27-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":597,"k":"para","g":"ભૂજના હીરજીભાઈ કારિયાણી આવ્યા હતા. શ્રીહરિએ તેમને વાત કરતાં કહ્યું, “સંત-હરિભક્તમાં દિવ્યભાવ રાખી તેની સેવામાં જે મન ચોરશે નહિ તથા પોતાનો દોષ જોતો રહેશે તેનો ઉદ્ધાર થશે. સત્સંગમાં જ્યાં સુધી હેત ને અલૌકિક ભાવ રહે ત્યાં સુધીમાં તન છૂટી જાય તો તેનું કલ્યાણ નિશ્ચિત છે. દિવ્યભાવમાં ફેર પડી ગયો ને તન છૂટી ગયું તો મોક્ષ થતો નથી. કોઈ કદાચ કોટિ સાધન કરે તોપણ જન્મમરણ લખચોરાશીના દુઃખથી ક્યારેય છૂટી શકતો નથી ને ભગવાનના ધામને પામી શકતો નથી.”","e":null,"s":["23/58/29-41"],"sv":["सत्संग में हित जिहां लगहु । अलौकिक हि रहे तिहां लगहु ॥\n\n तन छूटत ताके होत कल्याना । यामें जूठ न रंच रहाना ॥\n\n साधन कोटि कबु करे केहा । भगवान के धाम न पावत तेहा ॥\n\n जन्म मरन चोराशी केरा । दुःख न छूटत कोउ वेरा ॥"],"mt":false,"gl":null,"a":false},{"i":598,"k":"para","g":"પંચાળામાં ઝીણાભાઈના દરબારમાં શ્રીહરિએ સંતો-ભક્તોને વાત કરતાં કહ્યું, “ભગવાનનો પરિપક્વ નિશ્ચય ન થાય ત્યાં સુધી પૂરો હરિજન કહેવાય નહિ. ભગવાનના વચનમાં વર્તે, ધર્મ-નિયમ સંપૂર્ણ રાખે તેને ભગવાનનો નિશ્ચય થયો જાણવો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":599,"k":"para","g":"“નારી-ધનનો ત્યાગ કરવો એ વાત કઠણ નથી. વળી, હમેશાં કથા-કીર્તન કરે, ધ્યાન-સ્મરણમાં મોળો ન પડે, ધર્મ-નિયમમાં દૃઢ રહે તોપણ સંત અને હરિજનને મનુષ્ય જેવા દેખે છે ત્યાં સુધી તેનાં કોઈ સાધન મોક્ષમાં ઉપયોગી થતાં નથી. સંતો-ભક્તોમાં મનુષ્યભાવને લીધે તેના ગુણ-અવગુણ આવ્યા કરે છે. ને ગુણ-અવગુણ આવે ત્યાં સુધી તે પાકો સત્સંગી કહેવાય નહિ. સત્સંગ કરતાં કરતાં તેની ખામી ભાંગે છે. પછી વર્તમાન પણ લોપે નહિ ને અવગુણ પણ લે નહિ, એમ પાકો થઈ જાય છે.”","e":null,"s":["25/11/29-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":600,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":601,"k":"para","g":"ભગવાનના સ્વરૂપને જે દિવ્ય જાણે છે તે દિવ્ય થાય છે. ભગવાનનાં બધાં ચરિત્રો દિવ્ય છે, તેને જે માયિક જાણે છે તેને માયા ગ્રસી લે છે. તે માટે ભગવાનમાં દિવ્યભાવ રાખવો, મનુષ્યભાવ તજવો.","e":null,"s":["3/3/19-20"],"sv":[],"mt":false,"gl":null,"a":true},{"i":602,"k":"para","g":"ભગવાન ક્યારેક પોતામાં અપૂર્ણતા દેખાડે તોપણ ભક્તને તેમાં સંશય ન થાય. ભગવાનમાં દોષ કલ્પે તે અભક્ત છે. હરિજનમાં ને વિમુખમાં આટલો ફરક છે. જે અતર્ક્ય તત્ત્વ છે તેમાં જાતજાતના તર્ક કરે તે વિમુખ છે, અસુર સ્વભાવે યુક્ત છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":603,"k":"para","g":"ભગવાનનું ખાવું, પીવું, બોલવું, ચાલવું, ઊઠવું, બેસવું, હસવું, રડવું, ઉદાસ થવું, કોઈની સામે જોવું, ન જોવું, કોઈને બોલાવવો, ન બોલાવવો, કોઈ પર વગર વાંકે ખીજવું, ક્યારેક ત્યાગ બતાવે તો ક્યારેક રાગ બતાવે, ક્યારેક ડરીને ભાગે તો વળી ક્યારેક બીજાને ભગાવે, ક્યારેક કોઈના લાગ-બંધનમાં ન આવે - એવી એમની રીત અતર્ક્ય છે. તેને જે યથાર્થ જાણે છે તે બુદ્ધિશાળી છે. ભગવાનનું પ્રત્યેક ચરિત્ર દિવ્ય છે, જીવના કલ્યાણ માટે છે - એમ જે ભક્ત, ભગવાનને નિર્દોષ જાણે છે તે નિર્દોષ થઈ જાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":604,"k":"para","g":"દર્પણ સદાય નિર્દોષ-નિર્મળ છે. તેમાં દોષ દેખાય છે તે સન્મુખ ઊભેલાનું પોતાનું પ્રતિબિંબ છે. પોતાનું જેવું મુખ હોય તેવું દર્પણમાં દેખાય. પ્રાકૃત બુદ્ધિવાળા પોતાના જેવો દોષ પ્રભુમાં કલ્પે છે. ભક્તજનો તો તેવી લીલાનું ધ્યાન ધરે છે.","e":null,"s":["4/26/18-32"],"sv":[],"mt":false,"gl":null,"a":true},{"i":605,"k":"para","g":"સંતની કૃપાથી અલૌકિક મતિ થાય છે, પછી હરિજનની દૈહિક બાહ્ય ક્રિયા પણ નિર્દોષ લાગે છે. સૌમાં નિર્દોષબુદ્ધિ થઈ જાય તે સંતની કૃપા વિના શક્ય નથી, મનધાર્યા અપાર ઉપાય કરે તોપણ નકામા છે.","e":null,"s":["8/42/11-13"],"sv":[],"mt":false,"gl":null,"a":true},{"i":606,"k":"para","g":"ભગવાન પ્રગટ થાય છે ત્યારે મનુષ્યના જેવા ભાવ બતાવે છે ને દિવ્યભાવ પણ બતાવે છે. આ બન્ને જુએ છતાં જેની મતિ ફરે નહિ તેવા સંત ને હરિભક્તોને પગે લાગવું.","e":null,"s":["10/3/36-37"],"sv":[],"mt":false,"gl":null,"a":true},{"i":607,"k":"para","g":"જીવમાં જે અનંત પ્રકારનાં અવ્યક્ત બીજ રહ્યાં છે તે કોઈ કાળે નાશ થતાં નથી, પરંતુ જો ભગવાનના માયિક જેવાં ચરિત્રને પણ દિવ્ય સમજે અને ભગવાનને અગ્નિ તથા બ્રહ્મ સમાન જાણે તો તે નષ્ટ થાય.","e":null,"s":["10/46/31-34"],"sv":[],"mt":false,"gl":null,"a":true},{"i":608,"k":"para","g":"સ્થાવર-જંગમ સૃષ્ટિમાં ચાર યોનિમાં અનંત પ્રકારના જીવ રહ્યા છે. એક એક જીવને કારણ શરીરરૂપ વાસના-લિંગદેહ અવ્યક્ત બીજ રૂપે વળગ્યું છે. જેને લીધે તે જન્મમરણથી પર થઈ શકતો નથી. આ અવ્યક્ત બીજ કોઈ દેખી શકતું નથી. જીવનું આ બીજ દિવ્યદૃષ્ટિવાળા એકાંતિક સાધુ જોઈ શકે છે. આ બીજ દ્વારા જ્યારે જેવો જોગ બની આવે, ત્યારે તેવા દેહને આ જીવ પામે છે. ભગવાન ને ભગવાનના સંત વિના તે કોઈના દેખ્યામાં આવે નહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":609,"k":"para","g":"આ કારણ દેહરૂપી બીજનો નાશ જ્ઞાનયજ્ઞ દ્વારા થાય છે. ભગવાનના ચરિત્રનું કથન-શ્રવણ કરવું તે જ્ઞાનયજ્ઞ છે. તેને બ્રહ્માગ્નિ પણ કહે છે. પ્રાકૃત જેવાં જણાતાં હોય છતાં એ ચરિત્રો દિવ્ય છે, તેમાં માયિકભાવનો લેશ નથી એમ સમજીને ચરિત્રમાં મન રાખે તો એ બીજ બળીને રાખ થઈ જાય છે. તે સિવાય અન્ય અગ્નિ મહાપ્રલય કાળ જેવા હોય તોપણ કોટિ કલ્પે લેશ પણ આ કારણ શરીરના બીજને બાળી શકતા નથી. શ્રીહરિ અમાયિક છે તેમજ તેમના સંબંધમાં આવનાર જડ-ચૈતન્ય સર્વે અમાયિક છે. સંતો હરિજનો દિવ્ય છે. શ્રીહરિની મૂર્તિ, તેમનું ધામ, તેમનાં ચરિત્રો દિવ્ય છે. શ્રીહરિનાં તીર્થસ્થાન દિવ્ય છે. તેમનો સ્પર્શ પામનાર તરુ, પશુ, પાષાણ, ઇત્યાદિ સર્વે અમાયિક છે. શ્રીહરિનાં વસ્ત્રો, આભૂષણો દિવ્ય છે. કેસર, ચંદન, પુષ્પ દિવ્ય છે. ભોજન અને ભોજનપાત્ર, પત્ર, ફૂલ, કંદમૂળ આદિ સર્વે વસ્તુ અમાયિક છે. જેને લખતાં પાર આવે નહિ.","e":null,"s":["10/46/30-41"],"sv":[],"mt":false,"gl":null,"a":true},{"i":610,"k":"para","g":"પાખંડ હોય ત્યાં પ્રપંચ વિના કોઈ વાત હોય નહિ. સભામાં જુદી વાત કરે અને એકાંતમાં જુદી કરે. એકાંતમાં ફાવે તેવાં કુકર્મ કરે તોપણ દોષ ન લે ને તેની સાથે અધિક પ્રીતિ કરે તેને નિષ્પાપ જાણે. દોષ લે તેને પાપી જાણે. કોટિ સાધન કરતાં પણ નિર્દોષ દૃષ્ટિવાળાને અધિક માને. ગીતા કહે છે: પાપી-પાખંડી લોકો ધર્મના અર્થને સમજે નહિ. જેમાં કામ-ક્રોધાદિક અધર્મનાં દ્વાર રહેલાં હોય તેને મોક્ષનું દ્વાર તેઓ સમજે છે.","e":null,"s":["11/32/25-29"],"sv":[],"mt":false,"gl":null,"a":true},{"i":611,"k":"para","g":"જ્ઞાની, ધ્યાની, ધર્મ, વૈરાગ્ય અને ભક્તિવાળા પણ હોય, પરંતુ શ્રીહરિનાં મનુષ્યચરિત્ર દેખીને ચિત્ત ભમે નહિ તેવા ભક્તો દુર્લભ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":612,"k":"para","g":"આત્મનિષ્ઠા અને ધર્મનિષ્ઠા અથવા એવા બીજા ગુણની નિષ્ઠાવાળાની લોકો પ્રશંસા કરે છે. કીર્તિને માટે પણ ધન અર્પણ કરનારા તથા કઠિન તપ કરનારા પણ હોય છે. બાર વર્ષ સુધી હાથ અધ્ધર રાખી અન્ન ત્યાગ કરનારા તથા વાયુનો આહાર કરનારા પણ હોય છે. કીર્તિને માટે જળ પીને રહેનારા, ભૈરવજપ ખાનારા, પંચાગ્નિ તાપનારા, અગ્નિમાં પેસનારા, પગે ચાલી તીર્થ કરનારા - એમ પોતપોતાની રુચિ પ્રમાણે સાધન કરનારા ઘણા હોય છે. રુચિ પ્રમાણે કરવામાં કઠણ પડે નહિ, પણ જ્યાં બીજાની રુચિથી મોક્ષના માર્ગમાં રુચિ કરવી પડે તે કઠણ છે. બીજી બધી વાર્તા સુલભ છે, પણ મનુષ્યચરિત્રમાં મોહ ન થાય એ બહુ દુર્લભ છે. એવો તો કોઈ એકાદ મળે.","e":null,"s":["15/4/15-28"],"sv":[],"mt":false,"gl":null,"a":true},{"i":613,"k":"para","g":"સત્સંગમાં મનધાર્યું કરતા હોય ને નિશ્ચયવાળા હોય તેવાને ભગવાન ને મોટા સાધુ બાળક જાણી જાળવી લે છે. જેમ બાળક અંધ, રોગી કે ગાંડો હોય તેને માતાપિતા જાળવે છે. ગાંડો હોય તેને બીજા લોકો સહાય ન કરે, પણ માતાપિતા સહાય કરે છે. મનધાર્યું વર્તતા હોય તેના પ્રત્યે ભગવાન અને સંતને અરુચિ થતી નથી, કારણ કે તેઓ માયા પરના, અલૌકિક છે. ભક્તને પોતાના જાણી અરુચિ નથી કરતા તે જ તેમની અલૌકિકતા છે. વિધિ-નિષેધ લોપે તેને રાજાની જેમ શિક્ષા અવશ્ય કરે છે, પણ પોતાનો જાણીને શિક્ષા કરે છે. શિક્ષા ન કરે તો ભક્તકોટિમાંથી પશુકોટિમાં જતો રહે છે.","e":null,"s":["15/10/29-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":614,"k":"para","g":"જીવ સદા માયિકભાવે યુક્ત છે. સંત અને ભગવાનના યોગથી અમાયિક વાત સાંભળે ત્યારે અમાયિકમાં મન બંધાય છે. ભગવાન અને સંત કલ્પતરુ અને ચિંતામણિ જેવા છે. બન્નેમાં જ્યાં સુધી દિવ્યભાવ સમજાય છે, ત્યાં સુધી નિશ્ચય રહે છે. સંત અને ભગવાન ભેળે રહી રહીને હરિજન તેમનામાં પોતાના જેવા ભાવ પરઠે છે, પછી લૌકિક સમજ થાય છે ને મનુષ્યભાવ દેખાય છે. સમજણના માને કરીને સમભાવ આવી જાય છે.","e":null,"s":["15/65/21-24"],"sv":[],"mt":false,"gl":null,"a":true},{"i":615,"k":"para","g":"ભગવાનનાં મનુષ્ય ચરિત્ર દેખીને જેની મતિમાં ભ્રમ ન થાય તેને ભગવાનનો એકાંતિક દાસ જાણવો. અને ભગવાન રોગ ગ્રહણ કરે, ને ચિત્ત ભ્રમ થઈ આવે ત્યારે પણ મતિ ન ફરે તે તેથી પણ શિરોમણિ સમો છે.","e":null,"s":["15/69/15-16"],"sv":[],"mt":false,"gl":null,"a":true},{"i":616,"k":"para","g":"ભગવાન સ્વતંત્ર અને પૂર્ણકામ છે. તેમને મનુષ્યચરિત્ર કરવાં તે અસ્વાભાવિક છે. મનુષ્યચરિત્રમાં દિવ્યભાવ દેખનારા જનો અનાદિ ભક્ત છે. ભગવાનનું આવવું-જવું એ બધું અલૌકિક છે. છળકપટ ત્યાગ કરી જે સાચો ભક્ત બને છે તેને જ ભગવાનની ગતિ સમજાય છે. સાચા સંતના સંગ વિના સાચા ભક્ત કોઈથી થવાતું નથી.","e":null,"s":["15/69/32-34"],"sv":["आवन-जावन जनावत जेतो । अलौकिक यब रहाये तेतो ॥\n\n कोइ के तरक में न कबहि । आये नहि हरि अब लगहि ॥\n\n हरि की गति इस रीत रहावा । साचे भक्त बिन न आत देखावा ॥\n\n छलकपट करि के त्यागा । प्रथम भक्त जो होत बडभागा ॥\n\n साचे संत के संग बिन हि । साचे भक्त न होवत किनहि ॥"],"mt":false,"gl":null,"a":true},{"i":617,"k":"para","g":"જે ભક્ત ભગવાનનાં ચરિત્રને દિવ્ય જાણે છે તેને સંસારમાં રહેવું એક દિવસ પણ ગમતું નથી. સાંસારિક સુખ તેને અગ્નિ અને ઝેર જેવાં લાગે છે. સંતોનો યોગ થાય છે તેને અધિક ઉત્સાહ વધે છે. એટલામાં એ તન છૂટે તો ભગવાન તેને તેડવા આવે છે. સંત દ્વારા સત્સંગની વૃદ્ધિ થાય તેવી બીજા દ્વારા થાય નહિ. સત્સંગ કરાવવો સંતના હાથમાં છે અને મોક્ષ કરવો હરિના હાથમાં છે.","e":null,"s":["17/13/29-37"],"sv":[],"mt":false,"gl":null,"a":true},{"i":618,"k":"para","g":"ભગવાનનાં ચરિત્રોને જે પરમ દિવ્ય જાણે છે ને અંતરથી નિષ્કપટ છે એવા સંતોને તથા નર-નારી હરિભક્તોને અક્ષરરૂપ જાણવા. એ સર્વે એકાંતિક છે, મુક્ત છે.","e":null,"s":["17/25/10"],"sv":[],"mt":false,"gl":null,"a":true},{"i":619,"k":"para","g":"કોઈ ભગવાન કે ભગવાનના સંત-હરિજનની ભાવથી સેવા કરે તેને શ્રીહરિ ક્યારેય ભૂલતા નથી. ભગવાનનું તાન તો સર્વને સુખિયા કરવાનું છે, પણ મનુષ્ય, ભગવાન અને સંતને પોતાના જેવા જાણે છે તેણે કરીને તે દુઃખ પામે છે તેમાં લેશ સંદેહ નથી.","e":null,"s":["17/36/21-24"],"sv":[],"mt":false,"gl":null,"a":true},{"i":620,"k":"para","g":"હરિભક્ત થઈને સંત કે હરિભક્તનો મહિમા ન સમજે તે ફળ, ફૂલ, રસ અને છાયા વિનાના વૃક્ષ જેવો છે.","e":null,"s":["17/90/23-24"],"sv":[],"mt":false,"gl":null,"a":true},{"i":621,"k":"para","g":"પ્રગટ ભગવાનનો થયેલો યોગ અને સેવા નિષ્ફળ જાય નહિ. પ્રગટનો યોગ બહુ દુર્લભ છે. મહિમા સમજે તેવો મોક્ષ થાય છે. મહિમામાં કસર તેટલી મોક્ષમાં કસર રહે છે. અનુવૃત્તિ પાળવામાં કસર તેટલી મહિમા જાણ્યામાં કસર છે.","e":null,"s":["18/37/7, 19-21"],"sv":[],"mt":false,"gl":null,"a":true},{"i":622,"k":"para","g":"ભગવાનના સાચા સંત જ્યાં સ્નાન કરે છે ત્યાં નવું તીર્થ રચાય છે. સાચા સંતનો આવો અપાર મહિમા છે. તેને ઓળખીને નમે તે જન ભવપાર થઈ જાય છે. સાચા સંતના આ પ્રકારના મહિમાને મિથ્યા કહે છે તે દૈત્ય અસુર ને રાક્ષસ કુળના જાણવા. ખોટા સંતનો મહિમા ઘોરતમ નરક છે, તે ઠેર ઠેર હોય છે. સાચા સંત એ છે જેમાં ભગવાનનો વાસ છે. એ પોતે કહેતા નથી કે મારામાં ભગવાન રહ્યા છે, પણ તેમનો પ્રૌઢ પ્રતાપ દેખ્યામાં આવે છે તેનાથી તે ઓળખાય છે.","e":null,"s":["22/89/31-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":623,"k":"para","g":"ધર્મપાલન કરતા થકા ભક્તોમાં દિવ્યભાવ - અલૌકિકભાવ રહે તે જ સાચો અલૌકિક ભાવ કહેવાય છે. સત્સંગ પણ દિવ્ય ત્યારે જ કહેવાય જેમાં ધર્મ હોય. ધર્મનું પાલન પણ ભગવાનના પ્રગટ સ્વરૂપના જ્ઞાન વિના અભદ્ર છે. જેમાં ભગવાનનું પ્રગટપણું છે એ જ ધર્મને અલૌકિક કહ્યો છે. ભગવાનના સંબંધ વિનાના મતમાત્ર નિર્જીવ છે. તેમાં કોઈ પ્રકારનું દૈવત હોતું નથી.","e":null,"s":["23/69/5-7"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":8,"gu":"હેત-પ્રીત","en":"Het-Prīt — Affection and Love","url":"https://www.anirdesh.com/pbp/index.php?page=chp_8","b":[{"i":624,"k":"para","g":"શ્રીહરિએ ગોંડલના ભૂપને વાત કરતાં કહ્યું, “કહ્યા વિના હિત કરે તે ઉત્તમ મિત્રનું લક્ષણ છે. મિત્ર ત્રણ પ્રકારના છે, ઉત્તમ, મધ્યમ અને કનિષ્ઠ. ઉત્તમ મિત્રની પ્રીત પથ્થરમાં રેખા જેવી છે તે ક્યારેય ટળતી નથી. મધ્યમ મિત્રની રીત રેતીમાં રેખા જેવી છે જેને કોઈ સ્પર્શે નહીં ત્યાં સુધી દેખાય છે. પછી ટળી જાય છે. કનિષ્ઠ મિત્રની રીત તો આકાશની રેખા જેવી છે જે દેખાતી જ નથી. દેખાય તો ક્ષણમાં ટળી જાય છે.”","e":"While talking with the ruler of Gondal, Shriharí said, “To do good without being asked is the mark of the best kind of friend. Friends are of three kinds — the best, the middling and the lowest. The love of the best friend is like a line cut in stone; it never wears away. The way of a middling friend is like a line drawn in sand, which shows only until someone touches it, and then it is gone. And the way of the lowest friend is like a line drawn in the sky, which is not seen at all — and if it is seen, it vanishes in a moment.”","s":["3/48/46-49"],"sv":[],"mt":false,"gl":null,"a":false},{"i":625,"k":"para","g":"બંધિયાથી પીપળિયા જતાં માર્ગમાં શ્રીહરિ કહે, “સિંહ બધાને મારે છે, પણ પોતાનાં બચ્ચાને મારતો નથી. બિલ્લી ઉંદરને મારે છે, પણ પોતાનાં બચ્ચાંને મારતી નથી. તેમ જેને જેના ઉપર હેત હોય તે તેનું અહિત કરે નહિ.”","e":"On the road from Bandhiya to Pipaliya, Shriharí said, “A lion kills every creature, but does not kill its own cubs. A cat kills mice, but does not kill its own kittens. In the same way, one who has affection for another does him no harm.”","s":["3/52/17-18"],"sv":[],"mt":false,"gl":null,"a":false},{"i":626,"k":"para","g":"સરધારમાં શ્રીહરિએ વાત કરતાં કહ્યું, “હું સદા ભક્તને આધીન છું. જે મારે વિષે પ્રીતિ કરે છે તેમાં હું કરોડ ઘણી પ્રીતિ કરું છું. નિષ્કપટની સાથે મારે પ્રીતિ ટકે છે.”","e":"At Sardhar, while talking, Shriharí said, “I am forever subject to My devotee. Whoever loves Me, I love him ten million times over. My love endures with the one who is without deceit.”","s":["3/60/17-18"],"sv":[],"mt":false,"gl":null,"a":false},{"i":627,"k":"para","g":"ગઢપુરમાં શ્રીહરિ કહે, “જગતનો માર્ગ અને મોક્ષનો માર્ગ બન્ને જુદા છે. અમે મોક્ષને માર્ગે ચાલ્યા છીએ. જે કોઈ નીતિ-નિયમમાં રહીને મોક્ષને માર્ગે ચાલે છે તેની સાથે અમે હેતપ્રીત કરીએ છીએ.”","e":"At Gadhpur, Shriharí said, “The path of the world and the path of moksha are two different things. We have walked the path of moksha. With whoever walks the path of moksha, abiding within niti and niyam, we form affection and love.”","s":["4/5/19"],"sv":[],"mt":false,"gl":null,"a":false},{"i":628,"k":"para","g":"કુંડળમાં શ્રીહરિ કહે, “સાકરમાં સોમલખાર ભળે તો સાકર પણ ઝેર થઈ. તેમ સજ્જન કુસંગી સાથે હેત કરે તો તે પણ ખળ બને છે. અમારા સત્સંગી આશ્રિતે એવા ખળને ઓળખવા તેની સાથે કદાપિ હેત ન કરવું. નિર્દોષ ચરિત્રમાં પણ દોષ પરઠે તેને ખળ જાણવો.” ‘ખલ જન ખોજત દોષ’","e":"At Kundal, Shriharí said, “If arsenic is mixed into sugar, the sugar too becomes poison. In the same way, if a good person forms affection with one in kusang, he too becomes wicked. Our ashrit satsangis should recognise such a wicked person and never form affection with him. Know him to be wicked who imputes fault even to a faultless charitra.” ‘Khal jan khojat dosh’ — the wicked go about seeking faults.","s":["4/37/15-18"],"sv":[],"mt":false,"gl":null,"a":false},{"i":629,"k":"para","g":"બોટાદમાં શ્રીહરિ કહે, “હરિજનોને સત્સંગમાં આત્મબુદ્ધિ ન થાય ત્યાં સુધી પ્રાકૃત બુદ્ધિ રહે છે, અને ત્યાં સુધી ગુણદોષ લીધા કરે છે. જેને જેના પર હેત હોય તેને તેના માટે કોઈ કામ કરવું કઠણ નથી, અરે! તેને માટે ઘરબાર સહિત સર્વસ્વ ત્યાગ કરી દે. જગતની આ રીત છે. એ જ રીત ભગવાનના માર્ગની છે. ભગવાનમાં જેને અલૌકિક પ્રીતિ લાગી ગઈ તે મરણ પર્યંત જપ, તપ, વ્રત, તીર્થ, યજ્ઞ, દાન આદિ ઉમંગથી કરે છે. જેને સારી રુચિવાળા સંતનો સંગ મળે છે, તેને સારી રુચિ પેદા થાય છે. માયિકનો સંગ થાય તો માયિક પદાર્થમાં રુચિ કરાવે છે.","e":"At Botad, Shriharí said, “Until harijans develop atmabuddhi towards satsang, a worldly understanding remains, and until then they go on taking up virtues and faults. To one who has affection for another, no task done for that person is difficult — why, he will renounce home and everything he has for their sake. This is the way of the world. And that is exactly the way of the path of Bhagwan. One in whom transcendental love for Bhagwan has taken hold performs japa, tapa, vows, pilgrimage, yagna, charity and the rest with enthusiasm until death. Whoever obtains the company of a Sant with good inclinations develops good inclinations himself. And if he gets the company of the worldly, it produces in him an inclination for mayik things.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":630,"k":"para","g":"“જેને સાચા ગુરુ ન મળે તેનો મનુષ્ય જન્મ એળે જાય છે.”","e":"“The human birth of one who does not obtain a true guru goes to waste.”","s":["4/51/2-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":631,"k":"para","g":"મોડા ગામે શ્રીહરિ સંતોને કહે, “જેને જેના પ્રત્યે પ્રીતિ હોય તે છાની રહેતી નથી. વચન ઉચરે તેમાં અંતરની પ્રીત જણાઈ આવે છે. અતિ પ્રિય પદાર્થ પણ આપી દે છે.”","e":"In the village of Moda, Shriharí said to the sadhus, “Whoever has love for another cannot keep it hidden. In the words he utters, the love within becomes evident. He will give away even what is most dear to him.”","s":["5/16/32"],"sv":[],"mt":false,"gl":null,"a":false},{"i":632,"k":"para","g":"સરધારમાં શ્રીહરિ કહે, “જેને દૃઢ સત્સંગ છે એવા એકનિષ્ઠાવાળા હરિભક્તો પરસ્પર મળે છે ત્યારે આનંદ ને પ્રસન્નતાના ઊભરા આવે છે. સંત અને હરિજનને પરસ્પર આનંદ થાય છે તે અમારે કારણે છે.”","e":"At Sardhar, Shriharí said, “When haribhaktas of single-minded devotion, whose satsang is firm, meet one another, surges of joy and delight arise. The joy that the sadhus and the harijans feel in one another is on our account.”","s":["6/43/35-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":633,"k":"para","g":"સરધારમાં શ્રીહરિ કહે, “અલૌકિક સમજણવાળાને સુખ અને સંતોષ રહે છે. એવા જન પર હરિભક્તોનું હેત પણ દિન-પ્રતિદિન વધતું રહે છે. હેત વધે એ જ સત્સંગ કરવાનું ફળ છે. ભગવાન કે ભગવાનના ભક્તની સાથે નિશદિન રહે, પણ હેત વધે નહિ તો એમાં શું રૂડું થયું? માટે દૂર રહે પણ હેત વધે તો સાથે રહ્યા છે એમ સમજવું. સ્વાર્થરૂપી વિષ ભળે ત્યારે હેત તે કુહેતરૂપ બની જાય છે. વધારે પરિચયથી દોષદૃષ્ટિ થાય છે. પરમ મિત્રની પેઠે સંત-હરિજનમાં હેત હોય તો જ દોષ દેખાતા નથી.”","e":"At Sardhar, Shriharí said, “One with transcendental understanding remains in happiness and contentment. The affection of the haribhaktas towards such a person also goes on increasing day by day. That affection should increase is itself the fruit of doing satsang. If one stays day and night with Bhagwan or with the devotees of Bhagwan and yet affection does not increase, what good has come of it? So if a person stays far away and yet his affection increases, understand that he has stayed near. When the poison of self-interest is mixed in, affection turns into ill-will. From too much familiarity, a fault-finding vision arises. Only when the affection among sadhus and harijans is like that of the dearest friend are faults not seen.”","s":["6/44/17-19, 26-27"],"sv":[],"mt":false,"gl":null,"a":false},{"i":634,"k":"para","g":"બાબરામાં શ્રીહરિ કહે, “જીવને જેમાં સ્નેહ લાગે છે તેનો તેને ક્યારેય અભાવ આવતો નથી. સ્નેહ મનુષ્ય પાસે અતિ નીચ કામ કરાવે છે.”","e":"At Babra, Shriharí said, “Whatever the jiva becomes attached to, towards that it never develops aversion. Attachment makes a person do the lowest of deeds.”","s":["6/91/32, 35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":635,"k":"para","g":"ગઢડામાં અભય નૃપનો ભાવ જોઈ શ્રીહરિ પ્રસન્ન થયા ને કહેવા લાગ્યા, “તમને અને તમારા પરિવારને ધન્ય છે જે તમને ભગવાનમાં ને સંતમાં પ્રીત થઈ છે. દેહ અને ગેહથી પણ અધિક સંતમાં પ્રેમ થાય તેથી મોટું કોઈ સાધન નથી. શ્રીહરિ પછી આ પૃથ્વી પર એવા સંત જ ભવજળ તરવાનું નાવ છે. દૈત્ય-રાક્ષસ અધર્મી છે, પણ સંતને નમતા રહે છે. ભવ, બ્રહ્મા, ઇન્દ્ર ને દેવતામાત્ર સંતને નમે છે. જગતમાં રાજાઓ કે ધનાઢ્ય પુરુષો સંતને દેખીને વારંવાર મસ્તક નમાવે છે કારણ કે સંતનો મુખ્ય સરળ સ્વભાવ છે. તેની આંખોમાં ને વાણીમાં અમૃત ભર્યું છે. પોતાનો દ્રોહ કરે તેના પ્રત્યે પણ તે ક્યારેય કુટિલ વચન ઉચ્ચારતા નથી. પોતે દ્રોહને નજરમાં લેતા જ નથી, બાળકબુદ્ધિ જાણીને ક્ષમા કરી દે છે. એકમાત્ર ભગવાનની મૂર્તિમાં જ સુખને દેખે છે. તે સિવાય બધું દુઃખદાયી જાણે છે. છતાં પણ અનેક જીવનું કલ્યાણ કરવાનું હિત ધાર્યું છે તેથી લોકો સાથે એટલી હેત-પ્રીત રાખે છે.","e":"At Gadhada, seeing the devotion of King Abhay, Shriharí was pleased and said, “Blessed are you and your family, that love for Bhagwan and for the Sant has arisen in you. There is no greater spiritual endeavour than that love for the Sant should exceed even love for one’s body and home. After Shriharí, on this earth it is such a Sant alone who is the boat for crossing the waters of worldly existence. Demons and rakshasas are adharmi, yet they go on bowing to the Sant. Bhav, Brahma, Indra and every deity bow to the Sant. In the world, kings and wealthy men bow their heads again and again upon seeing the Sant, because the Sant’s chief nature is simplicity. His eyes and his speech are filled with nectar. Even towards one who betrays him he never utters a crooked word. He does not so much as take the betrayal into account; knowing it for a child’s understanding, he forgives it. He sees happiness in the murti of Bhagwan alone; apart from that he knows everything to be a source of misery. And yet, because he has taken to heart the good of redeeming countless jivas, he keeps that much affection and love with people.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":636,"k":"para","g":"“તમારે સંતમાં પ્રીતિ થઈ છે તે ત્રિલોક જીતી ગયા છો. જે મુખ્ય સાધન કરવાનું કહ્યું છે તે તમે સિદ્ધ કરી લીધું. સંતમાં પ્રીતિ કરી તે સાધનમાત્ર તેમાં આવી ગયાં. ભગવાન અને સંતના વચનમાં વિશ્વાસ આવ્યો કે દુઃખમાત્ર નાશ પામી ગયાં! ભગવાન અને સંતને મૂકીને જે કોઈ સુખને ઇચ્છે છે તે દિન-દિન પ્રત્યે અધિક દુઃખને પામે છે.","e":"“Love for the Sant has arisen in you — you have conquered the three realms. You have accomplished what has been named as the chief spiritual endeavour. Having formed love for the Sant, every other endeavour is contained within it. The moment faith in the words of Bhagwan and the Sant arrived, all misery was destroyed! Whoever sets aside Bhagwan and the Sant and desires happiness elsewhere meets with greater misery day by day.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":637,"k":"para","g":"“જે મનુષ્ય મોહને વશ થઈ દુઃખને સુખ કરી માનતા હોય તે ક્યારેય સંતને ન માને. ને સંતને ન માને તેથી તેનું કલ્યાણ પણ ક્યારેય થતું નથી, તે લખચોરાસીમાં હેરાન થતા ફરે છે. તમે અત્યંત ભાગ્યશાળી છો કે જગતથી પ્રીત તોડીને સાધુમાં કરી છે. ભગવાનમાં સુખ માન્યું છે. આવા ભક્તને જોઈ ભગવાન તેને આધીન થઈ જાય છે. જેમ બલિરાજાનું રાજ ભગવાને છીનવી લીધું, પણ તેને આધીન થઈ ગયા. સુવર્ણને ભઠ્ઠીમાં તપાવે પછી જ તેનો રંગ આવે છે. ભક્તની કસોટી પણ ભગવાન કરે છે ત્યારે તેની પ્રીત પરખાય છે. દુનિયાદારીનું અભિમાન હોય તો તે તાપ ખમી શકતો નથી, ને તે વિના શાંતિ પણ પામતો નથી.","e":"“Those people who, being overcome by delusion, take misery to be happiness will never accept the Sant. And because they do not accept the Sant, their redemption never comes about either; they go on wandering in distress through the eight million four hundred thousand species. You are exceedingly fortunate, that you have broken your love for the world and formed it with the sadhu. You have found happiness in Bhagwan. Seeing such a devotee, Bhagwan becomes subject to him. Just as Bhagwan seized King Bali’s kingdom from him, yet became subject to him. Only after gold is heated in the furnace does its colour come out. So too, when Bhagwan tests a devotee, then his love is assayed. If a person has the pride of worldly affairs, he cannot endure that heat — and without enduring it he does not attain peace either.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":638,"k":"para","g":"“ભગવાન અને ભગવાનના સંતની સેવામાં પોતાનું મોટું ભાગ્ય માને તેટલું તેને ફળ મળે છે, સુખ થાય છે. હરિજનને સંસારનું દુઃખ એ દુઃખ જ ન હોય, તેને તો સંતનો સંગ જેટલો ન થાય તેટલું દુઃખ મનાય છે.","e":"“However great a fortune one considers it to serve Bhagwan and the Sant of Bhagwan, that much fruit one receives, and that much happiness comes. For a harijan the misery of worldly life is no misery at all; however much he fails to obtain the company of the Sant, that much he counts as misery.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":639,"k":"para","g":"“લોકમાં તો લોકની રીતે રહેવું પડે, પણ ખરી પ્રીત તો ભગવાન ને સંતમાં દૃઢપણે જોડી હોય, સત્સંગના નિયમ મુખ્ય કરીને દૃઢ પાળતો હોય, સત્સંગમાં ન બેસતો હોય પણ સત્સંગનું કોઈ ઘસાતું બોલે તે ખમી શકે નહિ, શિર સાટે દૃઢ પક્ષ રાખે તો તેનું કલ્યાણ સત્સંગી જેવું જ થાય છે. સત્સંગના નિયમ ન રાખે અને સત્સંગનો પક્ષ ન હોય ને પોતાને સત્સંગી કહેવડાવતો હોય તોપણ તેને સત્સંગી ન જાણવો, તેને તો કુસંગી જાણવો. ભક્ત હોય ને ભક્ત સાથે લોભને વશ થઈ વેર બાંધે તો તેમાં અસુરનો પ્રવેશ થયો છે એમ સમજવું. ભક્ત સામે વેર કરવું એ હરિજનની રીત નથી.","e":"“Among people one must live in the manner of people; but if a person has firmly joined his true love to Bhagwan and the Sant, if he observes above all the niyams of satsang firmly, if — though he may not sit in satsang — he cannot bear to hear anyone speak disparagingly of satsang, and takes its side staunchly at the cost of his head, then his redemption comes about just as a satsangi’s does. And one who does not keep the niyams of satsang, who does not take the side of satsang, and yet has himself called a satsangi — do not know him to be a satsangi; know him rather to be one in kusang. And should a devotee, overcome by greed, form enmity with another devotee, understand that a demon has entered into him. To create enmity against a devotee is not the way of a harijan.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":640,"k":"para","g":"“અંદર અસુર પ્રવેશ કરે ત્યારે સંત હિતની વાત કરે તોપણ તે મનાય નહિ. ઊધઈ લાગે પછી પર્ણ વિનાનું વૃક્ષ જેમ શોભતું નથી તેમ તે પણ શોભાહીન થઈ જાય છે. તેમ સંતના દ્રોહ રૂપી ઊધઈ જો મૂળમાં લાગી ન હોય ત્યાં લગી તેને સત્પુરુષ રૂપી માળી મળી જાય તો લીલુંછમ કરી દે.","e":"“When a demon enters within, then even if the Sant speaks words for his good, they are not accepted. Just as a tree stripped of its leaves by termites has no beauty left, so he too becomes devoid of beauty. But so long as the termite of betraying the Sant has not reached the root, if he meets the gardener that is the Satpurush, he will be made green and flourishing again.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":641,"k":"para","g":"“જેને સંત મળ્યા છે તે ભક્તના દ્રોહથી બીતો રહે છે. એકે એક ભક્ત પોતાથી મોટા છે, મહાત્મા છે એમ તે જાણે ને ઘસાતું વેણ તો ક્યારેય ન ઉચ્ચારે.","e":"“One who has obtained the Sant goes in fear of betraying a devotee. He knows every single devotee to be greater than himself, to be a mahatma, and never utters a disparaging word.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":642,"k":"para","g":"“જેને દેહના અંત સુધી સત્સંગ દૃઢ કરીને રાખવો હોય, તેણે મોટા મોટા ભક્ત થઈ ગયા તેની રીત શીખવી, મોટાના વર્તન સામું જોયા કરવું. તેની રીત ન શીખે તો કરોડ વર્ષ સુધી સત્સંગ કરે તોપણ મોટાઈ ન આવે. સત્સંગની જે રૂડી રીત છે તે અમે જેમ છે તેમ તમને કહી સંભળાવી. આ પ્રમાણે વર્તે તેને ત્યાગી કે ગૃહી જેવા છે તેવા પરખાઈ જાય છે. માટે જેની સમજણ દૃઢ થાય છે તેનું જ અંગ સત્સંગમાં દિનદિન પ્રત્યે વૃદ્ધિ પામતું જાય છે. આ વાત મોક્ષભાગી જનને અમૃત તુલ્ય છે. તે દિન દિન સાંભળવા તલસે છે.”","e":"“Whoever wishes to keep his satsang firm until the end of his body should learn the manner of the great devotees who have gone before, and keep watching the conduct of the great. If he does not learn their manner, then even if he does satsang for ten million years, greatness will not come to him. We have told you, just as it is, the noble manner of satsang. Whoever conducts himself accordingly, whether tyagi or householder, is recognised for what he is. So it is only the one whose understanding becomes firm whose inclination in satsang goes on increasing day by day. To one destined for moksha this matter is like nectar; day after day he thirsts to hear it.”","s":["6/102/1-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":643,"k":"para","g":"શ્રીનગરના ભક્તોની પ્રાર્થના સાંભળી શ્રીહરિ કહે, “જેવી કુળ કુટુંબમાં પ્રીતિ છે તેવી પ્રીતિ જો ભગવાન અને સંતમાં કરે તો તે તરત ભવપાર થાય. હરિભક્તોએ ભગવાન ને સંતમાં પ્રીતિ કરવી તે નિષ્કામ ભાવે કરવી, તેનો ક્યારેય અભાવ ન આવે એ મહિમારસ સહિતની પ્રીતિ છે.","e":"Hearing the prayer of the devotees of Shrinagar, Shriharí said, “If a person were to form for Bhagwan and the Sant the love he has for his family and kin, he would cross beyond worldly existence at once. The love haribhaktas form for Bhagwan and the Sant should be formed without selfish motive; love that never turns to aversion is love accompanied by the flavour of mahima.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":644,"k":"para","g":"“સંતનાં દર્શન દેવ (ભગવાન) જાણીને કરે ત્યારે દર્શન કરનારને સંત સાથે અધિક ને અધિક સ્નેહ વધે છે, ને માયિકભાવ ઘટતો જાય છે. જેમ માતાપિતા પુત્રની સેવા મળ-મૂત્ર ધોઈને રાત્રિ-દિવસ કરે છે, તોપણ અભાવ આવતો નથી અને વળી જેમ પોતાના દેહનો મળ સૌ ધુએ છે, પણ અભાવ આવતો નથી. કારણ, તેમાં આત્મબુદ્ધિ મનાઈ ગઈ છે. આ હેતરૂપી માયા વજ્રસાર જેવી છે. એની બેડીથી કોઈ કાળે મુક્ત થવાતું નથી, પણ એવી આત્મબુદ્ધિ ને પ્રીતિ જો ભગવાનના સંતમાં થઈ જાય તો તે ભવના બંધનથી છૂટે છે.”","e":"“When one takes the darshan of the Sant knowing him to be Dev — Bhagwan Himself — then the affection of the one taking darshan for the Sant increases more and more, and mayik feeling goes on diminishing. Just as a mother and father serve their child day and night, washing away his filth, and yet no aversion comes; and just as everyone washes the filth of his own body without aversion coming — because atmabuddhi has been formed towards it. This maya in the form of affection is as hard as adamant. By its fetters one is never freed at any time. But if such atmabuddhi and love come to be formed towards the Sant of Bhagwan, then one is released from the bondage of worldly existence.”","s":["8/3/25-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":645,"k":"para","g":"જેતલપુરના મહોલમાં શ્રીહરિએ વાત કરતાં કહ્યું, “અમારાં દર્શન મૂકી સંતો માટે રસોઈ કરે છે તેનું ફળ દર્શનથી પણ અધિક છે. આવા સંતો ઠેર ઠેર મળતા નથી. ભેગા રહેવાથી માહાત્મ્ય ઘટી જાય; ભેગા રહેવા છતાં માહાત્મ્ય ન ઘટે તેને શુદ્ધ મુમુક્ષુ જાણવો. એક સાધુની પૂજા દેખી બીજો સાધુ દ્વેષ ન કરે અને મનમાં અતિ પ્રસન્ન થાય તો તેને સર્વે સાધુમાં શિરોમણિ જાણવો.”","e":"In the mansion at Jetalpur, while talking, Shriharí said, “Those who forgo our darshan and cook for the sadhus — the fruit of that is greater even than darshan. Such sadhus are not to be found in place after place. From living together, mahatmya diminishes; know him to be a pure mumukshu whose mahatmya does not diminish even while living together. If, on seeing one sadhu honoured, another sadhu holds no malice but is exceedingly pleased within, know him to be the crown jewel among all sadhus.”","s":["8/9/18-23"],"sv":[],"mt":false,"gl":null,"a":false},{"i":646,"k":"para","g":"જેતલપુરના મહોલમાં શ્રીહરિએ વાત કરતાં કહ્યું, “સંત અને હરિભક્તોએ ભગવાનમાં પ્રીતિ થાય તે રીત શીખવી. પ્રથમ હરિભક્તોએ સંતની સાથે પ્રીતિ કરવી, તુચ્છ સ્વભાવ અને સ્વાર્થને માટે પ્રીતિ તૂટે નહિ તેનું નામ પ્રીતિ ગણાય.”","e":"In the mansion at Jetalpur, while talking, Shriharí said, “The sadhus and haribhaktas should learn the way by which love for Bhagwan arises. First, haribhaktas should form love with the Sant; that alone is counted as love which does not break on account of some petty tendency or self-interest.”","s":["8/20(19)/29-30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":647,"k":"para","g":"જીવેન્દ્ર નૃપને શ્રીહરિ કહે, “‘બધું ભગવાનનું છે’ એમ કહેવામાં ફેર છે. ભગવાનને તો સૌ જાણે છે, પણ તેના નિમિત્તે ક્યારેય કશું થતું નથી. ભગવાન પોતે આવીને કહે, ‘તમારો પુત્ર આપો.’ ત્યારે અંતરમાં હરખ ન રહે અને વિમુખ થાય. ભગવાન જાણ્યામાં સંશય નથી, પણ પ્રાકૃત સમજણ વિશેષ રહી જાય છે. ભગવાનને યથાર્થપણે ભગવાન જાણીને એ મુજબ વર્તે એવા શૂરવીર હરિભક્તો થોડા હોય.”","e":"Shriharí said to King Jivendra, “There is a difference in merely saying ‘everything belongs to Bhagwan.’ Everyone knows Bhagwan, but nothing is ever done for His sake. Should Bhagwan Himself come and say, ‘Give Me your son,’ then joy would not remain within, and one would turn away. There is no doubt in the knowing of Bhagwan, but a worldly understanding remains over and above it. Haribhaktas valiant enough to know Bhagwan as Bhagwan truly is, and to conduct themselves accordingly, are few.”","s":["8/21(20)/17-20"],"sv":[],"mt":false,"gl":null,"a":false},{"i":648,"k":"para","g":"પીજમાં શ્રીહરિએ વાત કરતાં કહ્યું, “કુટુંબ અને દેહમાં જેવી પ્રીતિ થઈ છે તેવી સત્સંગમાં કરવી. કુટુંબ દેહને મિથ્યા જાણે તો સત્સંગમાં વિઘ્ન ન થાય. જેણે આવી પ્રીત સત્સંગમાં કરી છે તે જગત જીતી ગયા છે.”","e":"At Pij, while talking, Shriharí said, “The love one has formed for family and body should be formed for satsang. If one knows family and body to be false, no obstacle arises in satsang. Those who have formed such love for satsang have conquered the world.”","s":["8/44(45)/24-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":649,"k":"para","g":"શ્રીહરિએ વડતાલમાં વાત કરતાં કહ્યું, “જેને મોક્ષનો ખપ ન હોય તે કરોડ ઇન્દ્રાણી સમાન હોય તો તેને પણ અમે સત્સંગમાં રાખવા ચાહતા નથી.”","e":"At Vartal, while talking, Shriharí said, “One who has no khap for moksha — even were he the equal of ten million Indranis, we would not wish to keep him in satsang.”","s":["8/68(67)/40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":650,"k":"para","g":"ઝીંઝરમાં શ્રીહરિ હેત વિષે કહેવા લાગ્યા કે, “જગતમાં વિવિધ પ્રકારના રસ છે, પણ હેતનો જે રસ છે તે સૌથી શ્રેષ્ઠ છે. હેત હોય તેને માથું આપે. તેના દોષ દેખાય નહિ.”","e":"At Zinzar, Shriharí began to speak about affection: “There are flavours of many kinds in the world, but the flavour of affection is the finest of all. For one he has affection for, a person will give his head. He does not see his faults.”","s":["9/27/19"],"sv":[],"mt":false,"gl":null,"a":false},{"i":651,"k":"para","g":"ઝીંઝાવદરમાં અલૈયા ખાચરના ભવનમાં વાત કરતાં શ્રીહરિએ કહ્યું, “રાજા દશરથને પુત્ર કરતાં પણ સ્ત્રીમાં વધારે સ્નેહ હોવાથી રામને વગર અપરાધે વનમાં જવા પ્રેર્યા. લગાર પણ પુત્ર પ્રત્યે દયા ન આવી. રાજ્યના અધિકારી પુત્રને વનવાસ ન હોય, પણ નારીના સ્નેહમાં અંધ થયા હોવાથી કેટલાય યુગો સુધી વાયુભક્ષણ કરીને તપ કર્યા પછી ભગવાન પુત્રરૂપે થયા, છતાં પુત્રનો સંબંધ તોડી નાખ્યો.”","e":"While talking in the palace of Alaiya Khachar at Zinzavadar, Shriharí said, “Because King Dashrath had greater attachment to his wife than to his son, he sent Ram to the forest though he had committed no offence. Not the least compassion arose towards his son. There is no exile in the forest for a son who is heir to the kingdom; but being blinded by attachment to a woman, he severed the bond with his son — even though, after performing austerities for many ages subsisting on air, Bhagwan had come to him in the form of a son.”","s":["9/40(41)/29-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":652,"k":"para","g":"મેઘપુરમાં શ્રીહરિએ વાત કરતાં કહ્યું, “રંકથી આરંભીને બ્રહ્મા પર્યંત સૌને જેટલી ધન (લક્ષ્મી) ઉપર પ્રીતિ છે એટલી લક્ષ્મીપતિ ઉપર નથી. લક્ષ્મી કાજે દોડનાર બધા રંકના રંક છે. ભગવાન ઉપર જેને તાન છે તે તો ધનને ધૂળ સમાન માને છે અને અસાર વસ્તુમાં હેત કરતા નથી. તે સર્વે જન્મ-મરણથી રહિત થઈ ગયા છે. અમારી સમજણ તો એવી છે કે ભગવાન વિના બીજે ક્યાંય પ્રીતિ ન કરવી. ઉપર ઉપરથી વ્યવહાર કરીએ પણ અંતરમાં આ નિર્ધાર અમારો દૃઢ છે.”","e":"At Meghpur, while talking, Shriharí said, “From the pauper up to Brahma, everyone has as much love for wealth as they do not have for the Lord of Lakshmi. All those who run after Lakshmi are the poorest of the poor. One whose zeal is for Bhagwan regards wealth as no better than dust, and forms no affection for worthless things. All such have become free of birth and death. Our understanding is this: that love should be formed nowhere but in Bhagwan. Outwardly we carry on our dealings, but within, this resolve of ours is firm.”","s":["10/20/23-32"],"sv":[],"mt":false,"gl":null,"a":false},{"i":653,"k":"para","g":"મુક્તમુનિએ શ્રીહરિએ કહેલી વાતો ગઢપુરમાં કહી, “શ્રીહરિ કહેતા કે - હરિજનની સમજણ એક-એકથી અધિક છે. પોતાની સમજણ મુજબ ભગવાનનું સ્વરૂપ ઓળખાવે, અને રુચિ અનુસાર જ્ઞાન-ધ્યાન કરે, પરંતુ ભગવાન અને ભગવાનના સંત-હરિજન ઉપર જેને પ્રીતિ નથી તે ફાવે તેવું જ્ઞાન, ધ્યાન કરતો હોય તોપણ શબતુલ્ય છે.”","e":"Muktamuni related at Gadhpur the matters Shriharí had spoken: “Shriharí used to say — the understanding of harijans varies from one to another. Each makes known the form of Bhagwan according to his own understanding, and performs gnan and meditation according to his own inclination; but one who has no love for Bhagwan and for the sadhus and harijans of Bhagwan is like a corpse, however much gnan and meditation he may perform.”","s":["11/22/40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":654,"k":"para","g":"મુક્તમુનિએ શ્રીહરિએ કહેલી વાતો ગઢપુરમાં કહી, “શ્રીહરિ કહેતા કે - પાંચ આંગળીઓ નાની મોટી છે, પણ સૌનો સંબંધ એક પહોંચામાં છે. તેથી પહોંચો શોભે છે. એમ સંપ કરીને રહેવું એ અધિક બુદ્ધિનું કામ છે. બે જણ ભેગા સંપીને રહે ત્યારે બુદ્ધિ કળ્યામાં આવે. સંપ રાખી સાથે ચાલે તેટલા તે બુદ્ધિવંત જાણવા.”","e":"Muktamuni related at Gadhpur the matters Shriharí had spoken: “Shriharí used to say — the five fingers are of different sizes, but all are joined to a single wrist, and so the wrist is graced by them. In the same way, to live in harmony is the work of greater intelligence. When two people live together in harmony, their intelligence becomes apparent. Know as possessed of intelligence as many as keep harmony and walk together.”","s":["11/59/10-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":655,"k":"para","g":"માંગરોળમાં શ્રીહરિ કહે, “તમારા જેવા હેતવાળા હરિભક્તો સત્સંગમાં જ્યાં જ્યાં છે, તેમની હેતરૂપી દોરીથી અમે સત્સંગમાં બંધાઈ રહ્યા છીએ. જેની જેટલી હેતની દોરી બળવાન તેટલા અમને ખેંચી જાય છે.”","e":"At Mangrol, Shriharí said, “Wherever in satsang there are haribhaktas of affection like yourselves, we are bound to satsang by the cord of their affection. However strong a person’s cord of affection, that much does it draw us to him.”","s":["12/16(15-b)/21-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":656,"k":"para","g":"લોજમાં મુક્તમુનિ બ્રહ્મમુનિ પાસે ગાન કરાવી શ્રીહરિએ કહ્યું, “અક્ષરધામ, ગોલોક, વૈકુંઠ, શ્વેતદ્વીપ અને બદરિકાશ્રમમાંથી અનંત મુક્તો આવ્યા છે એવું માહાત્મ્ય તમારે સૌએ પરસ્પર જાણવું. માહાત્મ્ય વિના સ્નેહ રહે નહિ. દરેક સત્સંગી પર હેત રાખવું. કુહેત છે તે અગ્નિ અને વિષ સમાન છે.”","e":"At Loj, having Muktamuni sing before Brahmamuni, Shriharí said, “All of you should know this mahatmya of one another: that infinite muktas have come from Akshardham, Golok, Vaikunth, Shvetdwip and Badrikashram. Without mahatmya, affection does not remain. Keep affection for every satsangi. Ill-will is like fire and poison.”","s":["12/17(16)/13-15"],"sv":[],"mt":false,"gl":null,"a":false},{"i":657,"k":"para","g":"ભુજમાં શ્રીહરિએ વાત કરતાં કહ્યું, “કામી પુરુષને જેમ સ્ત્રીમાં પ્રીતિ છે તેવી રીતે ભગવાનમાં પ્રીતિ અને ધર્મ એ બે હોય તો મોક્ષ થયા વિના રહે નહિ. સત્સંગમાં ભાવ રાખે તો પ્રીતિ અને ધર્મ ટકે છે. ભૂમિ અને નીરના સંયોગ વિના બીજમાંથી વૃક્ષ થાય નહીં, તેમ પ્રગટ હરિ અને સંત વિના નિશ્ચય અને ધર્મ રહે નહિ. માહાત્મ્યે સહિત નિશ્ચય હોય તો પ્રીતિ ટકે છે.”","e":"At Bhuj, while talking, Shriharí said, “If a person had for Bhagwan the love a lustful man has for a woman, and had dharma along with it — with these two, moksha could not fail to come about. If one keeps devotion towards satsang, then love and dharma endure. Without the union of earth and water a seed does not become a tree; so too, without the manifest Hari and the Sant, nishchay and dharma do not remain. If nishchay is accompanied by mahatmya, then love endures.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":658,"k":"verse","g":"‘ભોમિ નીર કે જોગ વિન, બીજ વૃક્ષ ન હોઈ,","e":"‘Bhomi nīr ke jog vin, bīj vruksh na hoī,","s":[],"sv":[],"mt":false,"gl":"[Without the union of earth and water, a seed does not become a tree;]","a":false},{"i":659,"k":"verse","g":"તેસે પ્રગટ હરિ સંત વિન, નિશ્ચય ધર્મ ન રહે કોઈ.’","e":"Tese pragat Hari Sant vin, nishchay dharma na rahe koī.’","s":["12/38(37)/9-14"],"sv":[],"mt":false,"gl":"[…so too, without the manifest Hari and the Sant, neither nishchay nor dharma remains in anyone.]","a":false},{"i":660,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ મુક્તમુનિને વાત કરતાં કહ્યું, “ઉદ્ધવજી ઘણા જ્ઞાની હતા તોપણ ગોપીઓને પોતાથી અધિક માની. ગોપીઓનાં ચરણની રજ ઇચ્છ્યા. સંત-હરિભક્તોએ પરસ્પર ઉદ્ધવજી જેવો ભાવ રાખવો. સંત અને હરિભક્ત એકબીજાનો ભાર ન રાખે તો હાથી ગંગામાં નાહીને શરીર ઉપર ધૂળ નાખે તેના જેવું થાય છે. ઉદ્ધવ મતના થઈ પરસ્પર પ્રેમ ન રાખે તે લાંછનરૂપ છે અને હડકાયા શ્વાન જેવા છે.","e":"At Gadhpur, while talking with Muktamuni, Shriharí said, “Uddhavji was greatly learned, and yet he regarded the gopis as greater than himself. He longed for the dust of the gopis’ feet. The sadhus and haribhaktas should keep towards one another the disposition of Uddhavji. If a sadhu and a haribhakta do not bear regard for one another, it becomes like an elephant bathing in the Ganga and then throwing dust over its body. Those who claim to be of Uddhav’s persuasion and yet keep no love for one another are a disgrace, and are like rabid dogs.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":661,"k":"para","g":"“દિવસે દિવસે જે સંત-હરિભક્તોમાં પરસ્પર પ્રેમ વધારે એવા ભક્તોનાં કથા, વાર્તા, ધ્યાન, કીર્તન, વૈરાગ્ય સહુને સુખદાયી થાય છે, અને તે એકાંતિક ભક્ત છે.”","e":"“The katha, the discourses, the meditation, the kirtans and the vairagya of those devotees who increase mutual love among the sadhus and haribhaktas day by day become a source of happiness to all — and they are ekantik devotees.”","s":["13/50/23-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":662,"k":"para","g":"ડભાણમાં શ્રીહરિએ હરિભક્તોને ઉદ્દેશી કહ્યું, “જેનું મન સત્સંગથી ઉથડક થયું તેને હેતે કરીને, મિત્રતા દાખવીને સમજાવે તોપણ તેને મનાતું નથી. બધી વાતો તેને વિષ સમાન લાગે છે.”","e":"At Dabhan, addressing the haribhaktas, Shriharí said, “When a person’s mind has become unsettled towards satsang, then even if one explains to him with affection, showing friendship, it is not accepted by him. All such talk seems to him like poison.”","s":["14/20/15-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":663,"k":"para","g":"મોટેરા ગામમાં શ્રીહરિ કહે, “ભગવાનમાં ને ભગવાનના સંત તથા હરિભક્તોમાં જેટલું હેત વધુ તેટલું કારણ શરીર ટળે. હેત ઓછું હોય તો કારણ શરીરનો ભાગ જાણવો. એકબીજામાં મન ન મળે, એ પણ કારણ શરીરનો ભાગ છે. તે પોતપોતાની સમજથી તપાસી જુઓ. જેનું જેમ હશે તેમ જણાઈ આવશે. ડુંગળી ને લસણની ગંધ છીપી છીપે નહિ. સંતના દોષ જોતો હોય ત્યાં સુધી લસણ જેવી મતિ જાણવી.”","e":"In the village of Motera, Shriharí said, “However much affection one has for Bhagwan and for the sadhus and haribhaktas of Bhagwan, that much is the causal body removed. If the affection is less, know that to be a portion of the causal body. That minds do not meet with one another is also a portion of the causal body. Examine this each of you by your own understanding; whatever a person’s condition is, so will it become apparent. The smell of onion and garlic cannot be concealed however one tries. So long as a person is seeing the faults of the Sant, know his intelligence to be like garlic.”","s":["14/64/28-30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":664,"k":"para","g":"સારંગપુરમાં જીવા ખાચરના દરબારમાં શ્રીહરિ કહે, “સાત્ત્વિક પુરુષમાં સંપનો અમૃત ગુણ રહેલો છે. રાજસી તીખા તમ-તમતા હોય છે અને તમોગુણી વિષ સમાન દેખાય છે. ત્રણેયના સ્વભાવ આહારે કરીને જાણ્યામાં આવે છે. રાજસીનો આહાર રાજસી અને તામસીનો આહાર તામસી હોય છે. તેથી વિચાર પણ તેના જુદા હોય છે. તામસી લોકો સર્પ, સિંહ, ચિત્તા, ચોર અને ઝેર જેવા છે. તેનાથી સાચવીને ચાલવું, નહિ તો બગાડ થાય પછી સુધારવું કઠણ પડે.”","e":"At Sarangpur, in the court of Jiva Khachar, Shriharí said, “In the sattvik person there resides the nectar-quality of harmony. The rajasi are sharp and biting, and the tamogunī appear like poison. The natures of all three become known by their food. The food of the rajasi is rajasi and the food of the tamasi is tamasi, and therefore their thinking too is different. Tamasi people are like serpents, lions, leopards, thieves and poison. One should walk carefully with them; otherwise, once damage is done, it becomes difficult to repair.”","s":["14/78/32-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":665,"k":"para","g":"સારંગપુરમાં શ્રીહરિ સંતોને કહે, “મોટા મોટા સંત-હરિભક્તો જેમણે અમારે માટે સંસાર તજ્યો છે અને રાતદિવસ કથાવાર્તા-કીર્તન કરે છે, પણ ખચીત (જરૂરી, અવશ્ય) કરવાની જે વાત છે તેને યાદ રાખતા નથી અને બીજા ભારે ભારે ડોળ રચે છે. કૌપીન અને તુંબડાનું જેટલું જતન કરે છે તેટલું ભગવાનનું નથી. દેહમાં આસક્તિ છે તેટલી ભગવાનમાં થતી નથી. આ બધું મોક્ષમાં વિઘ્ન કરે છે. આ તમને સ્પષ્ટ કહી દીધું, હવે અમારું રહસ્ય ગ્રંથમાં લખાવીશું. કોઈ અત્યારે સમજે કે ન સમજે, લખેલું કોઈક સમજશે. જ્યાં સુધી દેહમાં હેત છે, ત્યાં સુધી અહંમમત્વ ને લોભ રહે છે. અને ગ્રંથમાં લખેલી વાત લગાર પણ કામ આવતી નથી.","e":"At Sarangpur, Shriharí said to the sadhus, “There are great sadhus and haribhaktas who have renounced worldly life for our sake and who perform katha, discourses and kirtan day and night — but they do not keep in mind the one thing that must certainly be done, and instead they get up other grand displays. They take as much care of their loincloth and gourd as they do not take of Bhagwan. The attachment they have to the body is not formed towards Bhagwan. All of this creates an obstacle in moksha. This we have told you plainly; now we shall have our inner secret written down in a text. Whether anyone understands it now or not, someone will understand what is written. So long as there is affection for the body, so long do I-ness, my-ness and greed remain — and then what is written in a text is of not the least use.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":666,"k":"para","g":"“પદાર્થમાં જેવો મમત્વ છે, તેવો ભગવાનમાં કરવો. એમાં વેદો, શાસ્ત્રો અને અનંત ગ્રંથો સમાઈ ગયાં! કરી કરીને કરવાનું એટલું જ છે કે ભગવાનમાં ચિત્ત જોડવું. ભગવાન તુલ્ય કોઈ વસ્તુ નથી. એ દૃઢ સમજવું.”","e":"“The my-ness one has towards material things should be formed towards Bhagwan. In that, the Vedas, the shastras and infinite texts are all contained! When all is said and done, this much alone is to be done: to join the mind to Bhagwan. There is nothing equal to Bhagwan. Understand this firmly.”","s":["14/84/16-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":667,"k":"para","g":"કરજીસણમાં શ્રીહરિ કહે, “લોકો એવું માને છે કે ક્યાં મનુષ્ય ને ક્યાં ભગવાન! એ બન્નેનો મેળ બેસે નહિ, એમ સમજી સંકોચ પામે છે, પણ પિતા, ગુરુ, સંબંધીની પેઠે શ્રીહરિમાં સંબંધ રાખવો.”","e":"At Karjisan, Shriharí said, “People believe: what is a human being, and what is Bhagwan! Thinking that no relation can be established between the two, they hold back. But one should keep a relationship with Shriharí as with a father, a guru, or a kinsman.”","s":["15/52/33-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":668,"k":"para","g":"વડતાલમાં સંતો-ભક્તો રંગે રમવા તૈયાર થયા, તેને શીખ દેતાં શ્રીહરિ કહે, “હાર-જીત હોય ત્યાં મન જુદાં પડી જાય. એક મન હોય ત્યાં જ બધા રંગ અને રસ રહે છે. એક મન રાખવા માટે જ અમે સદા વિચરીએ છીએ.”","e":"At Vartal, giving instruction to the sadhus and devotees who had made ready to play with colours, Shriharí said, “Where there is winning and losing, minds become divided. All the colour and all the flavour reside only where there is one mind. It is for the sake of making minds one that we travel about always.”","s":["17/41/13-15"],"sv":[],"mt":false,"gl":null,"a":false},{"i":669,"k":"para","g":"ભાવનગરના એક ઠગની વાત જીવાભાઈ અને રૂપાભાઈએ શ્રીહરિ પાસે કરી, ત્યારે શ્રીહરિએ બધા પદાતિને બોલાવી વાત કરતાં કહ્યું, “ધુતારાનો વિશ્વાસ ન કરવો એ વાત અમે વારંવાર કરી છે, તોપણ અમારા હરિજન તેનો વિશ્વાસ કરીને ઠગાય છે. ધુતારાનો વિશ્વાસ ન કરે અને અમારો વિશ્વાસ કરે તે અમારા સાચા દાસ છે.”","e":"When Jivabhai and Rupabhai told Shriharí about a swindler of Bhavnagar, Shriharí called all the attendants and, while talking, said, “We have said again and again that one should not trust a cheat, and yet our harijans trust such a one and are deceived. Those who do not trust the cheat but trust us are our true servants.”","s":["19/27(26)/32-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":670,"k":"para","g":"બોટાદના ભગા શેઠને દુઃખમુક્ત કરવા શ્રીહરિ પધાર્યા. તેઓ ગદ્‌ગદ થયા ત્યારે શ્રીહરિ કહે, “જે ભક્ત અમારા વિના બીજે ક્યાંય હેત રાખે નહિ તેની સમીપે અમે અખંડ રહીએ છીએ. એવા ભક્તથી અમારે બીજું અધિક નથી. મારા અક્ષરધામ જેવો પ્રિય તેને હું ગણું છું. જેને જેટલો મારો વિશ્વાસ છે તેની તેટલી હું રક્ષા કરું છું.”","e":"Shriharí came to free Bhaga Sheth of Botad from his misery. When he was overcome with emotion, Shriharí said, “The devotee who keeps affection nowhere but with Me — near him I abide unbrokenly. To Me there is nothing greater than such a devotee. I count him as dear as My Akshardham. However much faith a person has in Me, that much do I protect him.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":671,"k":"verse","g":"હરિ કહે મો બિન રખે ન જાહિ, તાકે મૈં સમીપ જો રહાહિ.","e":"Hari kahe mo bin rakhe na jāhi, tāke main samīp jo rahāhi.","s":[],"sv":[],"mt":false,"gl":"[Hari says: whoever keeps affection nowhere but with Me — near him do I abide.]","a":false},{"i":672,"k":"verse","g":"મો બિન જો રખત રહે જિતના, તિન સે દૂર રહત મૈં તિતના.","e":"Mo bin jo rakhat rahe jitnā, tin se dūr rahat main titnā.","s":[],"sv":[],"mt":false,"gl":"[However much a person keeps affection apart from Me, that much do I remain far from him.]","a":false},{"i":673,"k":"verse","g":"ભક્ત સે મૈં અધિક ન રખેઉ, અક્ષરધામ જો એસે તેઉ.","e":"Bhakta se main adhik na rakheu, Akshardham jo ese teu.","s":["19/24(23)/35-40"],"sv":[],"mt":false,"gl":"[I hold nothing greater than such a bhakta; he is to Me as My Akshardham.]","a":false},{"i":674,"k":"para","g":"જેતલપુરમાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “કોઈ પણ વાતને વિચારીને તેમાં બીજાનું હિત રહેલું હોય તેવાં જ વચન મોઢેથી બોલે, તેના પર સૌને પ્રીતિ થાય છે. તે પ્રમાણે બોલવું કઠણ છે. બીજાનું હિત ઇચ્છે તેટલું પોતાનું થાય છે.”","e":"At Jetalpur, while talking to the sadhus, Shriharí said, “Whoever considers a matter and speaks from his mouth only such words as hold the good of another — towards him everyone forms love. To speak in that manner is difficult. However much one desires the good of another, that much comes about for oneself.”","s":["19/41(40)/11-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":675,"k":"para","g":"વડતાલમાં શ્રીહરિએ હરિજનોને વાત કરતાં કહ્યું, “સંપ એ ભગવાનનું દૈવત છે. કુસંપ એ કળિયુગ છે. જ્યાં સંપ રહે છે ત્યાં રિદ્ધિ-સિદ્ધિ ને પ્રભુતા રહે છે. સંપ નથી ત્યાં કળિ કુટુંબ સહિત વસે છે.","e":"At Vartal, while talking to the harijans, Shriharí said, “Harmony is the divine power of Bhagwan. Discord is Kaliyug. Where harmony abides, there abide riddhi, siddhi and greatness. Where there is no harmony, there Kali dwells together with his whole family.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":676,"k":"para","g":"“પરસ્પર વિરોધ થાય તે કળિયુગનું લક્ષણ છે. સંપ, સુહૃદભાવ અને દયા-મરજાદા હોય ત્યાં ભગવાન વસે છે. જ્યાં આ સર્વે નથી ત્યાં ધર્માદિક પણ કથનમાત્ર છે એમ જાણવું. અને દયા-મર્યાદા, સુહૃદપણું ને સંપ છે ત્યાં જ મોક્ષ છે. આ ચાર વિના ફાવે તેવી મોઢે વાતો કહે ને ગુરુ થઈને પૂજાય તથા ગાદી, તકિયા, વાહન, વસ્ત્ર, ભૂષણ, ધન, ખાન-પાન, પૂજા મળતાં રહે, પણ તેનો કાંઈ અર્થ નથી.","e":"“That mutual opposition should arise is a mark of Kaliyug. Where there are harmony, suhradbhav and compassion with propriety, there Bhagwan dwells. Where all these are absent, know that dharma and the rest are there in name only. And moksha is only where there are compassion and propriety, suhradpanu and harmony. Without these four, a person may speak whatever he pleases, may be worshipped as a guru, and may go on receiving a seat of honour, cushions, conveyance, garments, ornaments, wealth, food and drink and worship — but none of it has any meaning.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":677,"k":"para","g":"“આકાશમાં ગતિ કરે તોપણ સંપ-સુહૃદભાવ વગર મોટાઈ આવતી નથી ને એ વિના મોટાઈ છે તોપણ કૃષ્ણપક્ષના ચંદ્રમાની પેઠે લુપ્ત થઈ જાય છે.”","e":"“Even if he could travel through the sky, greatness does not come without harmony and suhradbhav; and greatness held without them is eclipsed like the moon in its waning fortnight.”","s":["19/58(57)/1-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":678,"k":"para","g":"વડતાલમાં ગોમતી કાંઠે શ્રીહરિએ વાત કરતાં કહ્યું, “ભગવાન કે સત્પુરુષમાં જ્યાં સુધી જીવ બાંધે નહિ ત્યાં સુધી શાસ્ત્ર ભણે કે હુન્નર શીખે તો પણ મોક્ષ થાય નહિ.”","e":"At Vartal, on the bank of the Gomti, while talking, Shriharí said, “Until the jiva binds itself to Bhagwan or to the Satpurush, then however much one may study the shastras or learn a craft, moksha does not come about.”","s":["28/54/26-27"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":679,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":"The author’s notes and corroboration upon the foregoing subject as spoken by Shriharí:","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":680,"k":"para","g":"જ્યાં હરિભક્તોમાં પરસ્પર સુહૃદપણું હોય, એકબીજાનું હિત ઇચ્છતા હોય, છળ, કપટ અને મલિનતા હોય નહિ, એક એકથી મન છૂપું ન હોય, ધર્મનિયમમાં શૂરા થઈને એક જ ભાવથી સૌ વર્તતા હોય, પરસ્પર દૈહિક સંબંધ વિના પણ ગાઢ સંબંધી જેવું હેત રાખતા હોય એવા ભક્તોની પાસે શ્રીહરિ વારંવાર પધારતા. તેમની પ્રેમ અને શ્રદ્ધા-મહિમાની દોરીથી બંધાઈ રહેતા.","e":"Where there was suhradpanu among the haribhaktas towards one another, where they wished each other’s good, where there was no guile, deceit or impurity, where no mind was hidden from another, where all conducted themselves valiantly in dharma and niyam with a single disposition, and where they kept an affection like that of close kin even without any bodily relation — to such devotees Shriharí came again and again. He remained bound by the cord of their love, their faith and their mahima.","s":["8/25/15-18"],"sv":[],"mt":false,"gl":null,"a":true},{"i":681,"k":"para","g":"જેને સંત-હરિભક્તોમાં પ્રીતિ નથી તેને ભગવાનમાં ક્યારેય સ્નેહ વધતો નથી. સંત-હરિજનોમાં જેને અરુચિ થઈ તેને પોતાનું સ્વરૂપ નહીં ઓળખાય. સંત-હરિજન દર્પણ છે. તે વિના ભગવાનની મૂર્તિ દેખાતી નથી. આ સમજણ જે ભક્તને નથી તેને વિમુખ જાણવો.","e":"One who has no love for the sadhus and haribhaktas never grows in affection for Bhagwan. One who has developed distaste for the sadhus and harijans will not recognise his own swarup. The sadhus and harijans are a mirror; without them the murti of Bhagwan is not seen. Know the devotee who lacks this understanding to be one turned away.","s":["8/66(65)/24-26"],"sv":[],"mt":false,"gl":null,"a":true},{"i":682,"k":"para","g":"શ્રીહરિ વારંવાર વઢે તોપણ ઝાંખા ન પડે, પણ મનમાં સુખ માને એવા ભક્તો ઉપર શ્રીહરિ અતિ કૃપા વરસાવતા ને હેત કરતા. હેતની વૃદ્ધિ કરવા માટે જ શ્રીહરિ વારંવાર વઢતા. જેમ જે હીરો તોડ્યો ન તૂટે તે અમૂલ્ય છે અને તેના પર હેત થાય છે, એમ અમૂલ્ય હરિજન કરવા માટે શ્રીહરિ તેમને વઢતા. ક્યારેક ક્યારેક મૂંઝાય તેના ગુણ શ્રીહરિ જાણી લેતા અને પછી તેની સાથે તે પ્રમાણે વર્તી તેનું હિત થાય તેમ કરતા.","e":"Upon those devotees who did not grow dim even when Shriharí scolded them again and again, but rather took happiness in it within, Shriharí showered exceeding grace and affection. It was for the very purpose of increasing affection that Shriharí scolded them again and again. Just as the diamond that does not break when struck is priceless, and affection is formed for it, so Shriharí scolded them in order to make them priceless harijans. Now and then, when one became distressed, Shriharí would perceive his qualities, and thereafter conduct Himself with him accordingly, so as to bring about his good.","s":["9/18/14-18"],"sv":[],"mt":false,"gl":null,"a":true},{"i":683,"k":"para","g":"શ્રીહરિની મરજીથી ભક્તોને સમાધિ થતી, તેમાં આશ્ચર્યની વાત દેખાતી, અને કોઈકને વિષે હેત હોય તેથી કરીને દુર્ગતિ પામ્યો હોય તેને દુઃખથી છોડાવવા ઇચ્છા કરે ત્યારે શ્રીહરિને વીનવતા. ત્યારે શ્રીહરિ કહેતા કે જે સંબંધી તમને તજીને જાય તેને સંબંધી ન કહેવાય. દેહાદિકના જે સંબંધી છે તેને સંતો સંબંધી કહેતા જ નથી.","e":"By Shriharí’s will, devotees would enter samadhi, and wondrous things were seen in it; and when, having affection for someone who had come to a bad state, a devotee wished to free him from his misery, they would entreat Shriharí. Then Shriharí would say that a relative who forsakes you and departs is not to be called a relative. Those who are relatives of the body and the like, the sadhus do not call relatives at all.","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":684,"k":"para","g":"હરિભક્તની અને જગતના જીવોની સમજણ જુદી જુદી છે. માટે જીવતો હોય ત્યારે જ સંબંધીને સત્સંગ કરાવવો. મૂઆ પછી તો મનુષ્યશરીર પામ્યા સિવાય મોક્ષ થાય નહિ. કેટલાક સંબંધીઓ જમનો માર ખાય છે, કેટલાય ભૂત, પ્રેત, સર્પ, પશુ, પંખી, તરુ, લતા વગેરે જન્મને પામ્યા છે, તે દિવ્ય દૃષ્ટિવાળા જોઈ શકે છે. તમારામાં હેત હશે તો તમે ઉચ્ચારણ કરેલું સ્વામિનારાયણ નામ સાંભળીને વિકટ યોનિમાંથી છૂટી જશે. સત્સંગીમાં હેત થયા વિના દુઃખમાંથી છુટાય નહિ, શ્રીહરિનો પ્રતાપ મહિમા જેના હૃદયમાં જેટલો દૃઢ હશે તેટલો તે મોક્ષ કરશે.","e":"The understanding of a haribhakta and that of the jivas of the world are different from one another. Therefore one should bring a relative into satsang while he is still living. After death there is no moksha without attaining a human body. Some relatives are suffering the blows of Yama; many have come to birth as ghosts, spirits, serpents, animals, birds, trees and creepers — those with divine vision can see it. If there is affection in you, then on hearing the Swaminarayan name uttered by you, they will be released from those terrible species. Without affection arising in a satsangi, one is not released from misery; however firmly the majesty and mahima of Shriharí is fixed in a person’s heart, that much moksha will he accomplish.","s":["10/48/8-19"],"sv":[],"mt":false,"gl":null,"a":true},{"i":685,"k":"para","g":"જે હરિભક્તો મરજી સમજે અને મરજી રાખે તેને ત્યાં શ્રીહરિ વિના બોલાવ્ય વારંવાર જતા. મરજી જાણ્યા વિના પ્રેમ દેખાડ્યા કરે તેને ત્યાં વારે વારે જતા નહિ. ભય, પ્રીતિ અને પ્રતાપ દેખીને મરજી સચવાય છે. સ્વાર્થે કરીને મરજી રાખે છે, પણ સ્વાર્થ સિદ્ધ થાય ત્યારે તે રાખતો નથી, તે ક્યારેક દ્રોહ કરવા પણ તૈયાર થાય.","e":"To the homes of those haribhaktas who understood His wish and kept it, Shriharí would go again and again without being invited. To the homes of those who went on displaying love without understanding His wish, He did not go again and again. His wish is kept by perceiving awe, love and majesty. Some keep His wish out of self-interest; but when their interest is fulfilled, they do not keep it, and such a one is sometimes even ready to betray.","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":686,"k":"para","g":"જીવે ત્યાં સુધી એકમતિ રહે તો રંગ પાકો જાણવો. પણ મતિ એક સરખી રહેતી નથી, દેશકાળે મતિ ફરી જાય છે તે પ્રત્યક્ષ દેખ્યામાં આવે છે. જીવે ત્યાં સુધી જે હરિભક્તની મતિ ફરે નહિ, સંતની સેવામાંથી પાછો પગ ભરે નહિ. અનેક વિઘ્નો આવે તોપણ અધિક ને અધિક હેત-ભાવ, ઉત્સાહ રહ્યા કરે એવા હરિજનને અક્ષરધામનો મુક્ત લેખવો. તેની મોટપ સંતની મોટપ જેટલી છે.","e":"If a person remains of one mind as long as he lives, know his colour to be fast. But minds do not stay the same; with place and time the mind turns — this is seen plainly. That haribhakta whose mind does not turn as long as he lives, who does not step back from the service of the Sant, and in whom, though many obstacles come, affection, devotion and enthusiasm go on increasing more and more — reckon such a harijan a mukta of Akshardham. His greatness is as great as the greatness of the Sant.","s":["15/41/25-28"],"sv":[],"mt":false,"gl":null,"a":true},{"i":687,"k":"para","g":"સંસાર છોડી ત્યાગી થયો, પણ વિવેક વિના ધન-સ્ત્રીમાં બંધાય છે. ત્યાગીને મોટું બંધન ધન અને સ્ત્રી છે. ત્યાગી થઈને ધન-સ્ત્રીનો પ્રસંગ રાખે છે તે આખા જગતનું મળ ખાય છે. સાચા ત્યાગીની એ રીત નથી.","e":"A person renounces worldly life and becomes a tyagi, but without vivek he is bound by wealth and women. For the tyagi the great bondage is wealth and women. A tyagi who keeps association with wealth and women eats the filth of the whole world. That is not the way of a true tyagi.","s":["27/53/15-16"],"sv":[],"mt":false,"gl":null,"a":true},{"i":688,"k":"para","g":"જેમણે નારી-ધનનો ત્યાગ કર્યો છે તેવા ત્યાગી ફરી પોતાના ઘરમાં આવે જાય તો તેને ત્યાગી નહીં પણ ઘરબારી જ જાણવો. અને એવા ત્યાગીને ગૃહસ્થ જો ધન આપે તો તે આપનાર નરકમાં પડે છે. અને ત્યાગી પણ જે દિવસથી ધન પોતાનું કરીને રાખે કે અન્ય પાસે રખાવે તે દિવસથી નિત્ય એક ગાય માર્યાનું પાપ તેને લાગે છે. વળી, એવા ત્યાગીનું ધન કોઈ ગૃહસ્થ પોતાના ઘરે રાખે તો તે ત્યાગી અને ગૃહસ્થ બન્ને નરકમાં પડે છે.","e":"Those tyagis who have renounced women and wealth — if they come and go in their own homes again, know them not as tyagis but as householders. And if a householder gives wealth to such a tyagi, the giver falls into hell. And from the day the tyagi keeps wealth as his own, or has another keep it for him, from that day the sin of killing a cow daily attaches to him. Moreover, if any householder keeps such a tyagi’s wealth in his own home, then both the tyagi and the householder fall into hell.","s":["28/98/5-10"],"sv":["नारी धन त्याग कर हि जितने । त्यागी जेते कहावत तितने ॥\n\n ताकुं घर में रहेउ जेते । घरबारी रहाये जो तेते ॥\n\n त्यागी कुं धन देवत हि जेता । नरक में परत गृहस्थ तेता ॥\n\n त्यागी होय धन जेते दिन हि । पोताके करी के रखहि तिनहि ॥\n\n तेते दिन गाउ एक एक हि । वध करन पाप जो यह तिनहि ॥\n\n लगत रहे इमि त्यागी ताके । धर्म शास्त्र में कहे कर वाके ॥\n\n रखहि रखावहि त्यागी हि जेहू । धन नाम धरावत यह तेहू ॥\n\n त्यागी कुं पाप लगत अपारा । कहत ताके न आवत पारा ॥\n\n त्यागी का धन रखत हें जितने । गृहस्थ नाम धरावत तितने ॥\n\n एसे त्यागी गृहस्थ तिनके । नर्क में निवास होवत इनके ॥"],"mt":false,"gl":null,"a":true}]},{"n":9,"gu":"નિર્માનીપણું","en":"Nirmānīpanu — Humility","url":"https://www.anirdesh.com/pbp/index.php?page=chp_9","b":[{"i":689,"k":"para","g":"બંધિયાથી પીપળિયા જતાં શ્રીહરિ કહે, “અમારા સંતોને અમે નિર્માની કર્યા છે. નિર્માનીપણા જેવો બીજો કોઈ ગુણ નથી.”","e":"While going from Bandhiya to Pipaliya, Shriharí said, “We have made Our Sants nirmani. There is no other virtue like nirmanipanu.”","s":["3/52/22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":690,"k":"para","g":"સરધારમાં શ્રીહરિએ વાત કરતાં કહ્યું, “જગતમાં માન કે અપમાન થાય તે તુલ્ય માનવું, કારણ કે તે માન-અપમાન અચળ નથી, બધુંય જવાનું જ છે. વાદળની છાયાનું સુખ ક્યાં સુધી રહે?”","e":"At Sardhar, while talking, Shriharí said, “Maan or apmaan — honour or dishonour — as they come in the world, both should be regarded as equal, because that honour and dishonour are not fixed; all of it is bound to pass. How long does the comfort of a cloud’s shade remain?”","s":["3/56/41-42"],"sv":[],"mt":false,"gl":null,"a":false},{"i":691,"k":"para","g":"ચરોતરમાં વિચરણ માટે નીકળતાં આનંદાનંદ મુનિના મંડળને શ્રીહરિ વાત કરતાં કહે, “પ્રગટ પ્રભુની વાત કરવામાં કોઈથી દબાવું નહીં. તમારો ત્યાગીનો ધર્મ છે, તેમાં ફેર પડવા દેવો નહીં. જે વિવેકી હશે તે તમને માનશે. અધર્મી લોકો તમને દેખીને બળી મરશે. ધર્મ અને અધર્મને સદા વેર છે. ક્ષમા રૂપી ખડગ ધારણ કરજો, તેને દેખીને અધર્મ હારી જશે. સંતમાત્રે ક્ષમાશસ્ત્રને સજ્જ રાખવું. વાત કરવામાં કોઈનું ઘસાતું ન આવે તેમજ દ્રોહ ન થાય તે જાણપણું રાખવું. સંતનો શાંત ગુણ નીરથી પણ અધિક કહ્યો છે. નીર તો આગ પાસે તપી જાય છે, પણ સંત તપતા નથી. જેમ ચકોર અંગારા ખાય છે, પણ લેશમાત્ર મુખ ઝલતું નથી તેવો ગુણ સંતનો છે. સંત હોય તેને કોઈ ક્લેશ ન રહે. નમવામાં તમારી જીત છે. નિર્માનીપણું સંતોનું મહાભૂષણ છે અને એ મુખ્ય ગુણ છે.”","e":"As the mandal of Anandanand Muni set out to travel through Charotar, Shriharí said to them, “In speaking of the pragat Prabhu, do not be suppressed by anyone. It is your dharma as a tyagi; do not allow any lapse in it. Whoever is discerning will honour you. Adharmi people will burn at the sight of you. Dharma and adharma are forever at enmity. Bear the sword of kshama (forgiveness); seeing it, adharma will be defeated. Every Sant should keep the weapon of kshama at the ready. In speaking, keep the awareness that nothing disparaging is said of anyone and that no droh is committed. The Sant’s quality of calmness is said to be greater even than water’s. Water grows hot near fire, but the Sant does not grow hot. Just as the chakor eats embers yet its mouth is not scorched in the least, such is the quality of the Sant. One who is a Sant has no strife left in him. Your victory lies in bowing. Nirmanipanu is the great ornament of the Sants, and it is the principal virtue.”","s":["4/7/44-51"],"sv":[],"mt":false,"gl":null,"a":false},{"i":692,"k":"para","g":"ગઢપુરથી વિચરણ કરવા નીકળતા સંતોને શ્રીહરિ વાત કરતાં કહે, “સંતોએ એકબીજાનો ભાર રાખવો, વચન માનવું. તુચ્છ વચન કદી ન બોલવું. જડભરત, શુકજી અને પરમહંસની રીતનો ત્યાગ ન કરવો. જીવમાં જેનો અભ્યાસ હોય તેનો નિવાસ થાય. ત્યાગનો અભ્યાસ અને ખપ વગર સંત થવાતું નથી. સંત થયા વિના જન્મ એળે જાય છે. ચૌદ લોકમાં સાધુ જેવી કોઈ મોટાઈ નથી. કથાવાર્તા કરવી. ગુણગાન ગાવાં. સાધુનો ગુણ આવે તો બધા ગુણ આવે. સાધુમાં શુભ ગુણો અનંત રહ્યા છે. તેમાં મુખ્ય ગુણ નિર્માનીપણું છે. નિર્માનીપણું એકડો છે. આ ગુણ પ્રગટ હરિના નિશ્ચય વિના ફળીભૂત થતો નથી. માહાત્મ્ય વિનાનો નિશ્ચય મૂળ વગરના વૃક્ષ જેવો છે. હરિના માહાત્મ્ય જેવું જ હરિજનનું માહાત્મ્ય જાણવું. કોઈ એક હરિજનની ઓટ લઈને હરિનું અપાર માહાત્મ્ય કહે અને બીજા હરિજનોનું ઘસાતું બોલે તે સત્સંગમાં મહા કુસંગ છે. એવા મલિન આશયવાળાને બોલીથી ઓળખવો અને તેનો ત્યાગ કરી દેવો.”","e":"As the sadhus set out from Gadhpur to travel, Shriharí said to them, “Sadhus should bear regard for one another and should honour each other’s word. Never speak a demeaning word. Do not forsake the way of Jadbharat, Shukji and the paramhansas. Whatever a jiva practises comes to dwell in it. Without the practice of tyag and without khap one does not become a Sant. Without becoming a Sant, birth is wasted. In the fourteen realms there is no greatness like that of a sadhu. Do katha-varta. Sing His glory. If the virtue of the sadhu comes, all virtues come. Infinite noble virtues reside in a sadhu. Among them the principal virtue is nirmanipanu. Nirmanipanu is the figure one [the leading digit, without which the rest count for nothing]. This virtue does not bear fruit without nishchay of the pragat Hari. Nishchay without mahatmya is like a tree without roots. Know the mahatmya of a harijan to be just like the mahatmya of Hari. One who takes the support of some one harijan and speaks of the boundless mahatmya of Hari, yet speaks disparagingly of other harijans — that is great kusang within satsang. Recognise one of such impure intent by his speech, and forsake him.”","s":["4/8/1-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":693,"k":"para","g":"કુંડળમાં શ્રીહરિ સંતોને કહે, “જેમ જેમ પોતાનામાં ગુણોની વૃદ્ધિ થાય છે, તેમ તેમ નમ્રતા આવે છે. ભૂમિ પર પડતું અપાર જળ લઈને નદીઓ સાગરને મળે છે, પરંતુ એ જળથી સાગર ફુલાતો નથી. ભૂમિનું જળ જેમ જોર કરે છે તેમ ઓછું થતું જાય છે. નિર્માની સંતના ગુણો સાગર જેવા છે.”","e":"At Kundal, Shriharí said to the sadhus, “As virtues increase within a person, so does humility come. The rivers gather the boundless water that falls upon the earth and meet the ocean, yet the ocean does not swell with that water. The more the water upon the land forces its way, the more it goes on diminishing. The virtues of a nirmani Sant are like the ocean.”","s":["4/35/46-48"],"sv":[],"mt":false,"gl":null,"a":false},{"i":694,"k":"para","g":"શ્રીનગરમાં શ્રીહરિ સંતોને પ્રીતિપૂર્વક પૂછવા લાગ્યા, “સંતમાં શુભ ગુણો ઘણા હોય તેમાં એક મુખ્ય ગુણ કયો રહ્યો છે?”","e":"At Shrinagar, Shriharí began to ask the sadhus affectionately, “Among the many noble virtues that are in a Sant, which is the one principal virtue?”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":695,"k":"para","g":"કોઈથી સત્ય ઉત્તર થયો નહિ. તેથી શ્રીહરિએ ઉત્તર કરતાં કહ્યું, “નિર્માનીપણાનો ગુણ મોટો છે. ઘટમાં પ્રાણ હોય ત્યાં સુધી નિર્માનીપણું સૌએ રાખવું. શુકજી ને જડભરતના ગુણ હૃદયમાં વિચારવા ને ધારવા, ને પછી એ મુજબ વર્તવું. સાધુપણું ત્યારે જ કહેવાય જ્યારે તેમાં નિર્માનીપણું આવે. નિર્માની ગુણ વિનાના સાધુના ગુણો ટકતા નથી. નિર્માનીપણું, ધીરજ અને ક્ષમા એ સાધુનાં આભૂષણ છે. આ ત્રણે ગુણ સિદ્ધ કરે તેને ત્રિગુણાતીત જાણવો.","e":"No one gave the true answer. So Shriharí, giving the answer, said, “The virtue of nirmanipanu is great. As long as there is prana in the body, everyone should keep nirmanipanu. One should reflect upon the virtues of Shukji and Jadbharat and hold them in the heart, and then behave accordingly. Sadhuta is called such only when nirmanipanu comes into it. The virtues of a sadhu who lacks the virtue of nirmani do not last. Nirmanipanu, patience and kshama are the ornaments of a sadhu. One who perfects these three virtues should be known as trigunatit.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":696,"k":"para","g":"“નિર્માનીપણું, ધીરજ અને ક્ષમા જેમાં હોય તે ત્રણ દેહ અને ત્રણ અવસ્થાથી પર થઈ ચૂક્યો. તે અનંત લોકોમાં પૂજાય છે. દેહમાં વર્તે તે દેખ્યામાં આવે છતાં નિર્માન ગુણને લીધે તેને દેહથી પર જાણવો.","e":"“One in whom there is nirmanipanu, patience and kshama has already passed beyond the three bodies and the three states. He is worshipped in the infinite realms. Though he is seen to conduct himself in the body, on account of the virtue of nirman he should be known to be beyond the body.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":697,"k":"para","g":"“નિર્માન, ધીરજ ને ક્ષમાનાં મૂળ વિના કોઈ ગુણ આવતા નથી.”","e":"“Without the root of nirman, patience and kshama, no virtue comes.”","s":["4/104/1-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":698,"k":"para","g":"શ્રીનગરમાં શ્રીહરિ કહે, “સત્સંગમાં જેને અતિશય ખપ હોય, સંતને દીન-આધીન રહે ને મોક્ષનો ગરજુ થઈ રહે, પોતાની બુદ્ધિને અતિશય તુચ્છ જાણે, બીજા હરિભક્તોને મોટા માને એની જ પ્રગતિ થાય છે. જે માન રાખે છે, તે સત્સંગમાં ઘટી જાય છે. કોઈ ગુણનું માન ન આવે એ વાત કદી ભૂલશો નહીં. જેમ રસને ઝેર બગાડે છે તેમ માન બધા ખેલ બગાડી નાખે છે. હરિભક્તે તો માનને ત્યાગવું, જો ન ત્યાગે તો કુસંગ તેને વળગે છે.","e":"At Shrinagar, Shriharí said, “In satsang, only he progresses who has intense khap, who remains meek and dependent upon the Sant and stands in real need of moksha, who regards his own intellect as utterly trifling and considers other haribhaktas great. One who keeps maan diminishes in satsang. Never forget this talk: let no maan of any virtue arise. Just as poison spoils a delicacy, so maan spoils the whole play. A haribhakta must forsake maan; if he does not forsake it, kusang clings to him.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":699,"k":"para","g":"“દીનતા સંતનું ભૂષણ છે અને સંત જેવી કોઈ પદવી નથી. રાધા, રમા પણ તેવા ગુણ પામવા ઇચ્છે છે, પરંતુ આજ સુધી આ ગુણ તે પામી શકી નથી.”","e":"“Meekness is the ornament of the Sant, and there is no station like that of a Sant. Radha and Rama too desire such a virtue, yet to this day they have not been able to attain it.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":700,"k":"verse","g":"‘દીનતા પદ હૈ સંત કો, સંત સમ પદ નહિ કોઈ,","e":"‘Dīnatā pad hai sant ko, sant sam pad nahi koī,","s":[],"sv":[],"mt":false,"gl":"[Meekness is the station of the Sant; there is no station equal to the Sant’s.]","a":false},{"i":701,"k":"verse","g":"રાધા રમા સો ઇચ્છત હૈ, અબ લગ ન પાયે સોઈ.’","e":"Rādhā Ramā so ichchhat hai, ab lag na pāye soī.’","s":["4/109/24-26, 38"],"sv":[],"mt":false,"gl":"[Radha and Rama desire it, yet to this day they have not attained it.]","a":false},{"i":702,"k":"para","g":"નાગડકામાં શ્રીહરિએ હરિજનોને વાત કરતાં કહ્યું કે, “કુમતિ હોય તેને ગુણનું અભિમાન હોય. અભિમાન ચંડાળ જેવું છે. અભિમાન આવે તો જ્ઞાન રહેતું નથી અને અસૂયા, દ્રોહ, મત્સર, અટંટપણું અને મોહ વ્યાપે છે. અને અલ્પ વાતમાં વેર બંધાય છે. બીજાના શુભ ગુણો હોય તેમાં દોષ બતાવે છે. શબ્દના ઊલટા અર્થ કરે છે.”","e":"At Nagadka, while talking to the harijans, Shriharí said, “One of corrupt intellect has abhiman of his virtues. Abhiman is like a chandal. If abhiman comes, gnan does not remain, and asuya, droh, matsar, obstinacy and moha spread through him. And over a trifling matter enmity is formed. Where others have noble virtues, he points out flaws in them. He turns the meaning of words upside down.”","s":["6/8/5-6"],"sv":[],"mt":false,"gl":null,"a":false},{"i":703,"k":"para","g":"જૂનાગઢમાં સંતોને શ્રીહરિ કહે, “નિર્માનીપણાનું શસ્ત્ર બહુ સમર્થ છે. ઇન્દ્રનું વજ્ર નિષ્ફળ જાય, પણ તે નિષ્ફળ જાય નહિ.”","e":"At Junagadh, Shriharí said to the sadhus, “The weapon of nirmanipanu is exceedingly powerful. Indra’s vajra may fail, but that weapon does not fail.”","s":["6/81/28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":704,"k":"para","g":"કુંડળમાં રાજાઓને વાત કરતાં શ્રીહરિએ કહ્યું, “જેટલા રાજાઓ ભક્ત થયા છે તેમને બ્રહ્માંડનું વિશાળ રાજ મળે તોપણ સત્સંગ વિના ક્યાંય સુખ નથી એ બરાબર ધારવું. દૈહિક સુખ એ સુખ નથી. આ લોકનું સુખ આવું ને આવું ક્યારેય ટકતું નથી. સત્સંગ સંબંધી સુખ અવિચલ છે. ભગવાનનાં ચરિત્ર સાંભળીને દિવસ નિર્ગમવો. ઈર્ષ્યા અને માન મૂકી સંત-સમાગમ કરવો. કોઈ આદર દે કે ન દે તોપણ ગરજુ થઈ સત્સંગ રાખવો. સુવર્ણ માથું કપાવે છે, એમ પ્રત્યક્ષ જણાય છે, તોય તેમાંથી પ્રીતિ મટતી નથી, કારણ કે જીવ તેનો ગરજુ છે. તેમ આદરને બદલે તિરસ્કાર મળે તોય અભાવ ન આવે તેને ગરજ કહેવાય. દેહ તેમજ પુત્ર-પરિવાર સર્વે દુઃખરૂપ છે, છતાં પણ જીવ તેનો ગરજુ છે, તો સુખ માને છે. એનો એને અભાવ આવતો નથી. તેમ સત્સંગમાં ખપ હોય તો અભાવ આવે નહિ. જેટલું દુઃખ મનાય છે તેટલી ખપમાં કસર છે.”","e":"At Kundal, while talking to the kings, Shriharí said, “Let all those kings who have become bhaktas hold this firmly: even were they to receive the vast sovereignty of the brahmand, there is no sukh anywhere without satsang. Bodily sukh is not sukh. The sukh of this realm never remains as it is. The sukh connected with satsang is unchanging. Pass the day listening to the charitras of Bhagwan. Setting aside jealousy and maan, keep the samagam of the Sant. Whether anyone gives you regard or does not, keep satsang as one who stands in real need of it. Gold has heads cut off — this is plainly seen — and yet love for it does not cease, because the jiva stands in need of it. In the same way, one in whom no abhav arises even when he receives contempt in place of regard — that is what is called genuine need. The body, and sons and family, are all a form of dukh, yet the jiva stands in need of them and so regards them as sukh. No abhav towards them arises in him. In the same way, if there is khap in satsang, abhav will not come. However much dukh is felt, that much is the deficiency in khap.”","s":["7/36/36-42"],"sv":[],"mt":false,"gl":null,"a":false},{"i":705,"k":"para","g":"સિદ્ધપુરમાં શ્રીહરિએ વાત કરતાં કહ્યું, “ભગવાનનો ભક્ત થયો તેણે કોઈ વાતનો અહંકાર ન રાખવો. એક દિવસનો હરિભક્ત હોય અને સ્વામિનારાયણનું નામ લેતો હોય તેના પણ મન કર્મ, વચને કરીને દાસપણે વર્તવું. ઉપરથી જુદું અને અંતરથી જુદું એમ ન રાખવું. કોઈ કટુ વચન કહે તોય તેને પણ આકાશનો ભાગ માનવો અને સામર્થિ વધુ તેમ વધુ ગરીબ બનવું. યુક્તિ કે દાવપેચથી તેને પીડવાની ઇચ્છા રાખવી નહિ, પણ મિત્રની પેઠે વર્તવું.","e":"At Siddhpur, while talking, Shriharí said, “One who has become a bhakta of Bhagwan should keep ahankar of nothing whatsoever. Even towards one who has been a haribhakta for a single day and who takes the name of Swaminarayan, one should behave in daspanu by mind, deed and word. Do not keep one thing outwardly and another inwardly. Even if someone speaks bitter words, regard them as a portion of the sky; and the greater one’s capability, the more lowly one should become. Do not harbour the wish to torment him by stratagem or manoeuvre, but behave towards him as a friend.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":706,"k":"para","g":"“જેમ જેમ શુભ ગુણ આવે છે, તેમ તેમ ભક્તનું વર્તન અમાપ થતું જાય છે. જે સત્સંગ કરે છે તેને કોઈ વિઘ્ન આવતું નથી. કોઈ અપમાન કરે તોપણ મિત્રથી પણ અધિક ગુણ લેવો. ભક્તે તો ભગવાનને અંતર્યામી જાણ્યા છે. તલ-તલમાં ભગવાન સાક્ષીરૂપે રહ્યા છે એમ જાણીને વર્તનમાં કચાશ રાખે નહિ તો ભગવાન તેને વશ થઈ જાય છે.”","e":"“As noble virtues come, so does the bhakta’s conduct become immeasurable. No obstacle comes to one who does satsang. Even if someone dishonours him, he should take virtue from him more than from a friend. The bhakta has known Bhagwan to be antaryami. Knowing that Bhagwan abides as witness in every particle, if he keeps no slackness in his conduct, then Bhagwan becomes subject to him.”","s":["7/45/35-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":707,"k":"para","g":"શ્રીહરિને સન્મુખ લેવા બોટાદ ગયેલા જીવેન્દ્ર અને ઉત્તમ નૃપને શ્રીહરિ કહે, “અમે કહીએ તે પ્રમાણે જે સરળપણે વર્તે તેની સાથે અમારે સહેજે પ્રીતિ રહે છે. વારંવાર વિના વાંકે કહીએ તોપણ જે મૂંઝાઈ જાય નહિ, ખપ રાખીને વચનમાં વળગ્યો રહે તેને અમે મૂકતા નથી. મૂંઝાઈ જાય તેનો અમે તરત ત્યાગ કરીએ છીએ. તે પ્રીતિ રાખવા જાય તોપણ અમારે તેની સાથે પ્રીતિ રહેતી નથી.”","e":"To Jivendra and Uttam Nrup, who had gone to Botad to receive Shriharí before Him, Shriharí said, “With one who behaves with simplicity according to what We say, affection remains with Us of itself. Even if We rebuke him again and again without fault, one who does not become dejected but keeps khap and stays clinging to Our word — him We do not forsake. One who becomes dejected, We forsake at once. Even if he then tries to keep affection, affection for him does not remain with Us.”","s":["9/59/27-29"],"sv":[],"mt":false,"gl":null,"a":false},{"i":708,"k":"para","g":"મુક્તમુનિએ શ્રીહરિએ કહેલી વાતો ગઢપુરમાં કહી, “શ્રીહરિ કહેતા કે - બ્રહ્માંડની ઉત્પત્તિ, સ્થિતિ, પ્રલય કરે એટલું સામર્થ્ય ભગવાન આપે તોપણ સંતને દીન થઈને સેવે અને છળકપટનો ત્યાગ કરીને વર્તે તે સત્સંગમાં શ્રેષ્ઠ કહેવાય, જેટલી નમ્રતા ને દીનતા હોય તેટલો તે સંતને વિષે આધીન રહે છે.”","e":"Muktamuni related in Gadhpur the talks that Shriharí had spoken: “Shriharí used to say — even if Bhagwan were to grant one such power as to create, sustain and dissolve the brahmand, he who serves the Sant meekly and conducts himself having forsaken deceit is called the best in satsang. However much humility and meekness there is, that much does he remain submissive to the Sant.”","s":["11/68(58-b)/18-20"],"sv":[],"mt":false,"gl":null,"a":false},{"i":709,"k":"para","g":"ગઢપુરમાં જીવેન્દ્ર નૃપના દરબારમાં શ્રીહરિએ કહ્યું, “ભગવાન અતિ સમર્થ છે, તેમનું કર્યું બધું થાય છે, તોપણ તુચ્છનું અપમાન સહે છે. સહનશક્તિ અતિ મોટપ વધારે છે. જેટલું જે અપમાન કરે છે, તેટલું તે અપમાન કરનારનું જ માન ઘટે છે. આ વાત તરત દેખ્યામાં આવતી નથી, પણ અંતે ઘટ્યા વિના તે રહેતો નથી. જેમ ભીંડાનો છોડ પ્રથમ તો વડના છોડને દાબી દે છે, પણ આસો માસ આવતાં ઘરડો થઈને સુકાઈ જાય છે, તેમ સમર્થ પુરુષની મોટપ દેખાય નહિ, પણ તે વડના અંકુર જેવી છે. ધીરે ધીરે વૃદ્ધિ પામે છે ને અપમાન કરનારો ભીંડાના છોડ જેવો છે. ધીરજમાં અપાર સુખ રહેલું છે.”","e":"At Gadhpur, in the darbar of Jivendra Nrup, Shriharí said, “Bhagwan is exceedingly powerful, and all that He does comes to pass; yet He bears the insult of the lowly. The capacity to bear increases greatness greatly. However much a person dishonours another, by that much does the maan of the one who dishonours diminish. This is not seen at once, but in the end it does not fail to diminish. Just as the bhindi plant at first overshadows the banyan sapling, but when the month of Aso comes it grows old and dries up — in the same way the greatness of a capable person is not seen, but it is like the shoot of the banyan. Little by little it grows, and the one who dishonours him is like the bhindi plant. In patience lies boundless sukh.”","s":["13/63/28-32"],"sv":[],"mt":false,"gl":null,"a":false},{"i":710,"k":"para","g":"શ્રીહરિ ગઢપુરમાં કહે, “બુદ્ધિનું ફળ એટલું જ છે કે સૌ આગળ નમ્રતા રહે. જેનો જેટલો ભાર હોય તેટલું તેને નમવામાં કઠણ પડે નહિ.”","e":"Shriharí said at Gadhpur, “The fruit of intellect is only this much — that humility remains before all. However much weight a person carries, by that much should bowing not come hard to him.”","s":["14/93(94)/39-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":711,"k":"para","g":"ગઢપુરમાં જીવેન્દ્ર નૃપના ભુવનમાં શ્રીહરિ કહે, “કામ, ક્રોધ અને લોભ અસુરથી પણ અધિક અસુર છે. જેનામાં રજોગુણ તમોગુણ હોય તેમાં તે વસે છે. ગુણમાં પણ અવગુણ રહ્યો છે; તે શું જે, અપરાધ કરીને નમે નહિ. અપરાધ કરીને અંતર્દૃષ્ટિ થાય અને દીન થઈને નમતો રહે, તેને મનુષ્યમાં દેવ જાણવો. અપરાધ કરીને નમે નહિ તે અસુરનો પણ અસુર છે.","e":"At Gadhpur, in the residence of Jivendra Nrup, Shriharí said, “Kam, krodh and lobh are demons greater even than a demon. They dwell in one who has rajogun and tamogun. Within a virtue too a flaw resides — and what is it? That having committed an offence, one does not bow. One who, having committed an offence, turns his vision inward and remains bowed in meekness — know him to be a deva among men. One who commits an offence and does not bow is a demon even among demons.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":712,"k":"para","g":"“ધર્મ, જ્ઞાન, વૈરાગ્ય, ભક્તિ - એકાંતિક ધર્મની વાત દિનમાં પાંચ વાર સાંભળતો હોય, નિરંતર ધ્યાન કરતો હોય, ગ્રંથ કંઠે કરતો હોય, વાતનો અભ્યાસ નિરંતર રાખતો હોય, રામદાસ ને મુક્તમુનિ જેવા મોટા સંતનો સમાગમ હોય, પરંતુ તે જો સંતો-હરિભક્તોને નમતો ન હોય તો તે સત્સંગમાં રહેતો થકો અસુર છે. જે સંત-હરિભક્તને નમે છે તેને જ અમે સંત કે હરિભક્ત તરીકે દેખીએ છીએ. જે નમતો રહે છે તેનો ત્યાગ ધર્મ, જ્ઞાન, વૈરાગ્ય કે ભક્તિ એ કોઈ કરી શકતું નથી. તત્ત્વજ્ઞાનની વાતો છે તે બધી નમ્ર હરિજનને વરે છે. જે નમે છે તેને ધ્યાન, ધારણા, સમાધિ સહિત બધું સિદ્ધ થયું જાણવું. તેણે મોટા સંતો ને મોટા હરિભક્તોનો સમાગમ કર્યો એમ જાણવું. નમે છે તેમાં એક પણ દોષ રહેતો નથી. જે નથી નમતો તેનામાં બધા દોષો નિવાસ કરે છે.”","e":"“One may hear the talk of ekantik dharma — dharma, gnan, vairagya, bhakti — five times a day; may meditate ceaselessly; may have the scriptures by heart; may keep constant practice of the talks; may have the samagam of great Sants such as Ramdas and Muktamuni — yet if he does not bow to the Sants and haribhaktas, then, though he dwells in satsang, he is a demon. Only him do We see as a Sant or a haribhakta who bows to the Sant and the haribhakta. One who remains bowed — neither dharma, nor gnan, nor vairagya, nor bhakti can forsake him. All the talks of tattva-gnan wed themselves to the humble harijan. Of one who bows, know that dhyan, dharana, samadhi and all else has been accomplished. Know that he has kept the samagam of great Sants and great haribhaktas. In one who bows, not a single flaw remains. In one who does not bow, all flaws take up residence.”","s":["15/23(22-b)/29-37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":713,"k":"para","g":"ગઢપુરમાં જીવેન્દ્ર નૃપને શ્રીહરિએ ધરમપુરની વાત કરતાં કહ્યું, “જેટલું નિર્માનપણું તેટલી ભગવાનની કૃપા થાય. નિર્માનીતા જેવી કોઈ મોટાઈ નથી. નિર્માનીપણું એ બ્રહ્મનો ગુણ છે. નિર્માનીપણું એ ગુણમાત્રનો જનક છે. બીજા અપાર ગુણ હોય, પણ નિર્માનીપણું ન આવે ત્યાં સુધી એ ગુણો કલંકરૂપ છે. નિર્માનીપણું એ ચૌદ લોકનો આધાર છે. પૃથ્વીનો ગુણ નિર્માનિતા છે. ભગવાનના અવતાર પણ પૃથ્વીમાં જ થાય છે. જે હરિજન ભૂમિ જેવા નિર્માની રહે છે, તેમાં ભગવાન નિવાસ કરીને રહે છે.”","e":"At Gadhpur, while relating the talk of Dharampur to Jivendra Nrup, Shriharí said, “However much nirmanpanu there is, that much of Bhagwan’s grace comes. There is no greatness like nirmanita. Nirmanipanu is the virtue of Brahman. Nirmanipanu is the begetter of every virtue. One may have boundless other virtues, but until nirmanipanu comes, those virtues are a blemish. Nirmanipanu is the support of the fourteen realms. The virtue of the earth is nirmanita. The avatars of Bhagwan, too, take place only upon the earth. In that harijan who remains nirmani like the earth, Bhagwan comes to dwell.”","s":["16/46/23-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":714,"k":"para","g":"આણંદ જતાં રસ્તામાં શ્રીહરિ કહે, “નિર્માનીપણું રાખીને માનને જીતી લેવાનું છે. નિર્માનીપણારૂપી શસ્ત્રનો ક્યારેય ત્યાગ કરવો નહિ. તે શસ્ત્ર સૌથી શ્રેષ્ઠ છે.”","e":"On the way, while going to Anand, Shriharí said, “Maan is to be conquered by keeping nirmanipanu. Never forsake the weapon of nirmanipanu. That weapon is the highest of all.”","s":["17/92/37-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":715,"k":"para","g":"કારિયાણીમાં શ્રીહરિએ વાત કરતાં કહ્યું, “પોતાને અધિક માને અને બીજાને તુચ્છ સમજશે ને તે જ્ઞાની, ત્યાગી અને ધ્યાની હશે તોપણ તેના કલ્યાણમાં ફેર છે. સંત-હરિભક્તનાં ચરણની રજ પોતાને સમજે ને નિષ્કપટ વર્તે તેનો સહેજે મોક્ષ થાય છે.”","e":"At Kariyani, while talking, Shriharí said, “One who regards himself as superior and considers others trifling — though he be a gnani, a tyagi and a dhyani, there is a shortfall in his kalyan. One who understands himself to be the dust of the feet of the Sants and haribhaktas and behaves nishkapat — his moksha comes about of itself.”","s":["23/58/31-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":716,"k":"para","g":"નાગડકામાં શ્રીહરિએ વાત કરતાં કહ્યું, “સત્સંગમાં જે પ્રભુતા પામીને તેને શમાવી નમ્રતાથી વર્તે અને સંત-હરિભક્તનો મન-કર્મ-વચને નિષ્કપટપણે દાસ થઈને રહે તો તેને બધા મોટો ગણે છે. અને સહજ સ્વભાવે પૂજ્ય થાય છે. તે મોટાઈ ઇચ્છતો નથી છતાં સહેજે મળે છે. ભગવાન અને સંતો-ભક્તોમાં જેને નિષ્ઠા હોય તેને સત્સંગની મોટપ સહજપણે પ્રાપ્ત થાય છે.”","e":"At Nagadka, while talking, Shriharí said, “In satsang, if one who has attained eminence subdues it and conducts himself with humility, and remains the nishkapat servant of the Sants and haribhaktas by mind, deed and word, then all regard him as great. And he becomes worthy of worship by his very nature. He does not desire greatness, yet it comes to him of itself. One who has nishtha in Bhagwan and in the Sants and bhaktas attains the greatness of satsang naturally.”","s":["23/82/14-18"],"sv":["संत हरिजन के दास जेहि । मन क्रम बचन होई के तेहि ॥\n\n निष्कपट वरतत रहे ताकुं । बडे करी सब मानत वाकुं ॥\n\n बडता के गुन रहाये जामें । छिपाये कबहु न रहत तामें ॥\n\n पोताकि इच्छा कर जे तें । बडे बडता कुं न इच्छत तेते ॥\n\n सत्संग कि बडता इनकुं । आवत रहत हें सहज तिनकुं ॥\n\n भगवान संत हरिजन में जितनां । निष्ठा वरतत रहत हें तितनां ॥"],"mt":false,"gl":null,"a":false}]},{"n":10,"gu":"અક્ષરબ્રહ્મ","en":"Aksharbrahman","url":"https://www.anirdesh.com/pbp/index.php?page=chp_10","b":[{"i":717,"k":"para","g":"શ્રીહરિએ લોજમાં સંતોને ષટચક્રની વાર્તા કરી. તેમાં સૌથી પર ભગવાનના અક્ષરધામનું વર્ણન કરતાં તેમણે કહ્યું, “બધા લોકથી પર, સર્વાધાર, સર્વવ્યાપક અને સૌથી વિલક્ષણ એવું દિવ્ય અક્ષરધામ છે. જેને પરમ ચૈતન્ય, સત્ય, જ્ઞાનરૂપ, અનંત અને પ્રમાણરહિત કહે છે. વેદો જેને અક્ષરબ્રહ્મ કહે છે, તેને જ પુરુષોત્તમ-નારાયણનું ધામ કહીએ. એ અક્ષરબ્રહ્મના પ્રકાશને ચિદાકાશ કહે છે. તેને તથા અક્ષરધામને કોઈ ભૌતિક ઉપમા સંભવતી નથી. જેમ અનંતકોટિ જોજન વિસ્તારવાળી કાચની ભૂમિ હોય અને સ્થાવર જંગમ બધું જ કાચનું હોય, આકાશમાં જેટલાં તારામંડળ છે તે બધા જ સૂર્ય હોય તેનો જેવો પ્રકાશ થાય તેવો અપાર પ્રકાશ અક્ષરધામનો છે. અનંતકોટિ સૂર્ય જેવી કાંતિ જેમના એક એક રોમમાં રહી છે તેવા અનંત દિવ્ય ભક્તો ત્યાં વસે છે. મહાશીતલ, સુખમય, અનંત અપાર તેજ અક્ષરધામનું છે. ત્યાં કાળનો પ્રવેશ છે નહીં. સૌના સ્વામી એક પુરુષોત્તમનારાયણ ત્યાં સાકારરૂપે બિરાજમાન છે.”","e":null,"s":["3/25/8-15"],"sv":["तापर सर्वाधार कहावे । सब व्यापक दिव्य रहावे ॥\n\n पूर्व कहे जो लोक सब जोऊ । तिनसें विलक्षन जानो सोउ ॥\n\n परम चैतन्य सत्य हि ज्ञाना । अनंत हें जाको न कशी प्रमाना ॥\n\n अक्षरब्रह्म कहत वेद जाकु । पुरुषोत्तम स्थान कहिये वाकु ॥\n\n प्रकाश कुं चित्त व्योम कहावे । अरु अक्षरधाम रहावे ॥\n\n अद्भुत उपमा करिके कहाई । भूतिक उपमा न संभवे ताई ॥\n\n अनंतकोटि जोजन विस्तारा । ऐसि काचकि भुमि होय सारा ॥\n\n स्थावर जंगम कहावत जेहु । सबहि काचके होवे तेहु ॥\n\n तारामंडल हें नभमें जेता । सूर्य सबहि होवे तेता ॥\n\n तिनको प्रकाश होत ज्युं अपारा । तेसो धामको कहे निरधारा ॥\n\n कोटि सूर्यसम कांति हि, एक एक रोमके मांहि ।\n\n ऐसे भक्त अनंत हि, रहत अलौकिक तांहि ॥\n\n तेहि तेज सितल महा, सुखमय अनंत अपार ।\n\n काल को नहि प्रवेश तिहां, पुरुषोत्तम एक सिरदार ॥"],"mt":false,"gl":null,"a":false},{"i":718,"k":"para","g":"સારંગપુરમાં શ્રીહરિ કહે, “અનંતકોટિ બ્રહ્માંડ છે તેમાં અક્ષરધામનો વાસ છે.”","e":null,"s":["4/4/46"],"sv":[],"mt":false,"gl":null,"a":false},{"i":719,"k":"para","g":"ગઢડામાં જીવા ખાચરને ઉદ્દેશીને શ્રીહરિ કહે, “અમારે કોઈના થકી લેશમાત્ર સ્વાર્થ સાધવો નથી. અમે નિઃસ્વાર્થભાવે તમને કહીએ છીએ. અનંતકોટિ બ્રહ્માંડનું સુખ અમને શૂલી જેવું લાગે છે. અક્ષર અમારા સેવક છે. તેમના સંકલ્પે કરીને અનંત બ્રહ્માંડ ઊપજે છે ને લય પામે છે. એ અક્ષરના પણ દાસ અનંતકોટિ પુરુષ છે. અમારે અનંતકોટિ બ્રહ્માંડોની ગણતી નથી.”","e":null,"s":["5/2/10-12"],"sv":["अनंतकोटि ब्रह्मांड के सुखा । हमकुं सुलि सम लगत हे दुःखा ॥\n\n हमारे दास हे अक्षर जेहा । ताके दास बहु पुरुष तेहा ॥\n\n ताके संकल्प करिके जोऊ । अनंत ब्रह्मांड हि होत हे सोउ ॥\n\n ताकि नहि है गनति हमारे । अल्प सुख गनति हे तुम्हारे ॥"],"mt":false,"gl":null,"a":false},{"i":720,"k":"para","g":"મોડા ગામે રણમલજીને ત્યાં શ્રીહરિએ સંતોને ઉદ્દેશીને વાત કરતાં કહ્યું, “અમને તમે જે જે આવીને મળ્યા છો તે સર્વેને બ્રહ્મસ્વરૂપ કરવા છે, જીવમાં માયાનો ભાગ ભળ્યો છે તે કાઢવો છે. માટે ખબરદાર થઈને રહેજો, નહિ તો તમારો પગ ટકશે નહિ.”","e":null,"s":["5/16/22-23"],"sv":["हमकुं मिले तुम जितने आई । ब्रह्मस्वरूप करना हे ताई ॥\n\n मायिक भाग मिले हे एका । तासें जुदे करने हे छेका ॥\n\n खबडदार अब रहेना तुम्हारे । नहि तो पाव न टिकनेवारे ॥"],"mt":false,"gl":null,"a":false},{"i":721,"k":"para","g":"ગાલોલના માવા ભક્તે શ્રીહરિની પૂજા કરી પછી પૂછ્યું, “તમો સાક્ષાત્ ભગવાન પ્રગટ્યા છો, પણ તે વાત બીજાને મનાતી નથી. અને સંતની વાત મનાય છે, પરંતુ તમને જાણ્યા વિના મોક્ષ કેમ થાય?”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":722,"k":"para","g":"ત્યારે શ્રીહરિ કહે, “અનાદિથી રીત જ એવી છે. ભગવાનને જાણવા માટેનાં બે દ્વાર પ્રસિદ્ધ છે: એક તો ભગવાનના અનાદિ ભક્ત (અર્થાત્ અક્ષરબ્રહ્મ). બીજા પ્રગટના ઉપાસક સંતો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":723,"k":"para","g":"“અને ભગવાનનો નિશ્ચય એ વજ્રના કોટ જેવો છે. નિશ્ચયના કિલ્લામાં કોઈ રીતે પ્રવેશી શકાય તેમ નથી. તેમાં પ્રવેશવા અનાદિ ભક્ત (અક્ષરબ્રહ્મ) સિદ્ધના સ્થાને છે. તેમના મુખે ભગવાનની વાત સાંભળે તો તરત નિશ્ચય થઈ જાય. એમનો યોગ ન થયો હોય એવા જેટલા જન છે તેનું દ્વાર સંતો છે.”","e":null,"s":["6/84/6-13"],"sv":["भक्त करन लगे हरि से बाता । भगवान प्रगटे तुम साक्षाता ॥\n\n यामें नहि संदेह हि लेशा । हमकुं दृढ जनाये एसा ॥\n\n ओरकुं करत तुमारी बाता । तरत नहिं आत मनाता ॥\n\n संत की बात करत हे जबहि । तर्त माने में आवत तबहि ॥\n\n तुमारो लेवत जब नामा । तब थडकत नर अरु वामा ॥\n\n तुमकुं जाने विन मोक्ष न होई । हम एसे मन जानत सोई ॥\n\n श्रीहरि तब बोलत भयेउ । सनातन रीत एसि रहेउ ॥\n\n आज नहिं हे नई यह रीति । तुमकुं बात करत कर प्रीति ॥\n\n भगवान जांने के दो हे द्वारा । प्रसिद्ध सब जानत संसारा ॥\n\n वज्र को कोट रचाये जेहा । तोप करि न परे तेहा ॥\n\n द्वार विन पेठाय न तामें । कोटि उपाय ओर करे यामें ॥\n\n सिद्ध अरु पंछी ताकुं । अंतराय करे न वाकुं ॥\n\n भगवान के भक्त अनादि जेई । पंछि सिद्ध हि जानना तेई ॥\n\n अने निश्चयरूप कोट हि जेऊ । ताकुं अंतराय न करे तेऊ ॥\n\n भगवान की सुनत बात हि, तर्त निश्चय हो जाय ।\n\n ता विन जितने जन हि, संत द्वार हे ताय ॥"],"mt":false,"gl":null,"a":false},{"i":724,"k":"para","g":"ભચાઉમાં લાધાજી નામના ભૂપને શ્રીહરિએ કૃપા કરીને બ્રહ્મવિદ્યાનો બોધ આપ્યો, “બધી વિદ્યાઓમાં બ્રહ્મવિદ્યા શ્રેષ્ઠ છે. મનુષ્યને ક્ષણે ક્ષણે જે શોક-મોહ વ્યાપે છે તે દુઃખ બ્રહ્મવિદ્યાવાળાને ટળી જાય છે. બ્રહ્મવિદ્યા પ્રાપ્ત થઈ તેને ચિંતામણિ મળી એમ જાણવું. બ્રહ્મવિદ્યાના જાણકાર પાસે રહી તેના વચન મુજબ અભ્યાસ કરે અને પ્રકૃતિપુરુષ સુધીના વિષયમાત્રને તુચ્છ ગણી વર્તે તેને બ્રહ્મવિદ્યા વરે છે. વિષયથી નિરાશ થયા વિના બ્રહ્મવિદ્યા તત્કાળ પ્રાપ્ત થાય નહિ. સાચું લક્ષ્યજ્ઞાન થાય ત્યારે જ તે બ્રહ્મવિદ્યા પામે. બ્રહ્મવિદ્યા પામેલો પુરુષ દેશકાળ આદિકથી લોપાય નહિ. વાચક જ્ઞાનથી કોટિ જન્મે બ્રહ્મવિદ્યા પ્રાપ્ત ન થાય. હરિનો રાગ રહે અને અખંડ સ્મૃતિ રહે એ જ બ્રહ્મવિદ્યા છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":725,"k":"para","g":"“બ્રહ્મવિદ્યા પામેલા પુરુષની પરીક્ષા શી? તો શરીર પર ક્યારેક કૌપીન પહેરવા મળે ને ક્યારેક ભાત-ભાતનાં અનેક વસ્ત્ર મળે તેમાં તેને સમાનબુદ્ધિ રહે, ક્યારેક પકવાનનાં ખાનપાન મળે ને ક્યારેક કોરા કડાકા થાય તેમાં મન ક્ષોભ ન પામે, ક્યારેક વૃક્ષ તળે ભૂમિ પર વાસ મળે તો ક્યારેક મોટા મહેલમાં પલંગ તળાઈ-તકિયા મળે તેમાં તેને સમાન ભાવ હોય. હાથીની અંબાડી પરથી ઉતારીને ગધેડે બેસવાનો સમય આવે ત્યારે ચિત્તમાં વિક્ષેપ ન થાય – તેને બ્રહ્મવિદ્યા પ્રાપ્ત થઈ છે એમ જાણવું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":726,"k":"para","g":"“દિવસ-રાત ભગવાનની સ્મૃતિમાં રમમાણ રહે તેણે બ્રહ્મવિદ્યા સિદ્ધ કરી એમ અમે માનીએ છીએ.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":727,"k":"verse","g":"‘સ્મૃતિ દિન અરુ રાત, હરિ મૂર્તિ કી કરાવે જેહુ,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":728,"k":"verse","g":"બ્રહ્મવિદ્યા સો સાક્ષાત્, હમ નિશ્ચે સો કીયેહિ તેઉં.’","e":null,"s":["7/15/24-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":729,"k":"para","g":"જેતલપુરમાં શ્રીહરિએ જીવેન્દ્ર નૃપને વાર્તા પ્રસંગે કહ્યું, “પ્રાકૃત શરીર આ જીવને મળ્યું છે તેને પોતાનું સ્વરૂપ ન માનવું. જીવનું સ્વરૂપ તો શુદ્ધ અક્ષરરૂપ છે એમ ચિત્તમાં અક્ષર(બ્રહ્મ)ની ભાવના અને ચિંતવન કરતાં કરતાં જીવમાં અક્ષરભાવ પ્રગટ થાય, ત્યારે પ્રાકૃતભાવ નાશ પામે છે. વળી, એ અક્ષરમાં શ્રીહરિ (પુરુષોત્તમ) સદા રહ્યા છે. એ દિવ્ય અલૌકિક મૂર્તિ છે ને સત્સંગમાં સદા પ્રગટ વિચરે છે, તે જ મૂર્તિ પોતાના આત્મામાં રહી છે.”","e":null,"s":["8/20/22-24"],"sv":["प्राकृत देह यह जिय को जेहा । जिय को स्वरूप न मानना तेहा ॥\n\n अक्षर शुद्ध रूप हें अपना । एसी स्वरूप जियको चिंतवना ॥\n\n अक्षरभावना जिय में लाई । चिंतवन करना चित्त में ताई ॥\n\n अक्षरभाव जब जिय में आवे । प्राकृतभाव तब दूर रहावे ॥\n\n अक्षर में हरि रहे हें सदाई । दिव्यमूर्ति अलौकिक जाई ॥\n\n सत्संग में विचरत मूर्ति जेहि । एहि एक जिय में रहे तेहि ॥"],"mt":false,"gl":null,"a":false},{"i":730,"k":"para","g":"ઝીંઝર ગામે સંતો તથા નૃપને પીરસીને શ્રીહરિએ વાત કરતાં કહ્યું, “અમારું નિવાસસ્થાન અક્ષરધામ છે. તે અક્ષરધામમાં જેવું સુખ છે તેવું અન્ય કોઈ ધામમાં સુખ નથી. ગોલોક, વૈકુંઠ, શ્વેતદ્વીપ આદિ ધામોનાં સુખ છે તે અક્ષરધામના સુખ આગળ સાવ લૂખાં છે, તુચ્છ છે. બદરિકાશ્રમનું સુખ દેવતાના સુખની અપેક્ષાએ અધિક છે. એ સુખનો અનુભવ છે તે પણ પ્રકૃતિપુરુષની અંદર આવી જાય છે, તેનાથી પરનો એ અનુભવ નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":731,"k":"para","g":"“અક્ષરધામના સુખ અન્ય ધામોનું સુખ સુવર્ણ આગળ પિત્તળ સમાન ભાસે છે. અક્ષરધામના અપરંપાર સુખની વાત અનુભવ વગર માન્યામાં આવતી નથી. એ સુખને અમે સંભારીએ છીએ ત્યારે અમારું દિલ અહીં ટકતું નથી, ત્યાં પહોંચી જાય છે. એ અક્ષરધામને કોણ જાણે છે? તો સત્સંગમાં જે મોટા (એકાંતિક ભક્ત) છે તેને અક્ષરધામની પરખ છે, બીજાને નથી. અમે હેત કરીને જીવને એ વાત કરીએ છીએ ને સત્સંગમાં રાખીએ છીએ, છતાં અક્ષરધામની વાત એ સમજતા નથી ત્યારે અમે અતિ ઉદાસ થઈ જઈએ છીએ.”","e":null,"s":["9/27/20-24"],"sv":["हमारे निवास हे अक्षरधामा । तेहि सम सुख न अवर कोउ ठामा ॥\n\n गोलोक वैकुंठ श्वेतद्विप सुखा । अक्षरधाम के आगे सो लूखा ॥\n\n बदरिकाश्रम को सुख जोउ । देव के सुख से अधिक हें सोउ ॥\n\n सो सुख को अनुभव होत जेहा । प्रकृतिपुरुष लग सुख हि तेहा ॥\n\n सोवर्ण आगे पित्तल हि जेसा । अक्षरधाम आगे सुख सब तेसा ॥\n\n अनुभव विन आत न देखाई । जेसो सुख हें अपरमताई ॥\n\n सो सुख हम संभारत जबहु । हमारो दिल इहाँ टकत न तबहु ॥\n\n भगवान के भक्त सत्संग मांहि । बडे बडे रहे जानत ताहि ॥\n\n हित करि के सो जियकु हमारा । सत्संग में रखे हें कर प्यारा ॥\n\n सत्संग से वेर वेर हि जोई । हम उदास अति होवत सोई ॥"],"mt":false,"gl":null,"a":false},{"i":732,"k":"para","g":"માંડવી બંદરે શ્રીહરિએ સંતોને શીખ આપતાં કહ્યું, “વેદશાસ્ત્ર ભણવાનું ફળ એટલું છે કે, ધર્મ દૃઢ કરીને રાખવો. વેદશાસ્ત્ર અપાર ભણે પણ ધર્મનો લેશ ન હોય તેને ચોરાશીના ફેરા મટતા નથી. જન્મ-મરણ અને ઘોર જમપુરીનાં દુઃખ ભોગવવાં પડે છે. બ્રહ્મજ્ઞાન બ્રહ્મ સમાન છે, આનંદમય છે. બ્રહ્મ વિના દેહાદિક કોઈ પણ પદાર્થમાં સ્નેહ ન રહે અને શુકદેવ જેવા ગુણ આવે ને વિષયમાત્ર કાકવિષ્ટા સમાન લાગે એવું થાય ત્યારે તે સાચું બ્રહ્મજ્ઞાન કહેવાય. રમણીય ભોગને વિષ, અનલ અને સર્પ તુલ્ય માને અને તેનો ત્યાગ કરે તે સાચો બ્રહ્મનિષ્ઠ છે. તેને સ્ત્રી-ધનનો મોહ ન હોય, બ્રહ્મજ્ઞાન વિનાનો બીજો કેફ ન હોય. અને જે દંભી જ્ઞાની હોય તે તો વાતો મોટી મોટી કરે, પણ શુકજી કે જનક જેવું કંઈ પણ વર્તન હોય નહિ. ધર્મને લોપે અને હિંસા કરતા હોય તથા બ્રહ્મની દેશી લઈને બોલે કે અમે તો બ્રહ્મ વિના કંઈ દેખતા નથી, બ્રહ્મજ્ઞાનીને પાપમાત્રનો સ્પર્શ થતો નથી, એવા દંભી જ્ઞાની નરનારીને નરકમાં નાખે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":733,"k":"para","g":"“ભગવાનના સ્વરૂપને મૂર્તિમાન નહિ માનતા તેજને માને તથા ભગવાનના અવતારને માયિક કહે તેવા દંભી જ્ઞાનીઓ અપાર દુઃખના અધિકારી થાય છે. શુદ્ધ જ્ઞાની તો ભગવાનની મૂર્તિથી કાંઈ પણ અધિક માનતા નથી. શ્રુતિ-સ્મૃતિમાં પ્રતિપાદિત સનાતન ધર્મનો ક્યારેય લોપ કરતા નથી, એવા જ્ઞાનીનો જે સંગ કરે છે તથા તેમનાં વચન જે માને છે તેનાં સર્વ પાપ નાશ પામે છે.” એમ કહી શ્રીહરિ કહે, “તમે સૌ શુદ્ધ જ્ઞાનની મૂર્તિઓ છો. તમને દંભી ક્યારેય પહોંચે નહિ. ધર્મની સેનાને હઠાવવા ફાવે તેટલો સાજ સજે, પણ અધર્મની સેના નાશ જ પામે. કરોડ પતંગિયાં આવે તોપણ અગ્નિને બુઝાવી શકે નહિ, ઊલટો તેમનો જ નાશ થાય, તેમ પાખંડી, નાસ્તિક, દંભી, બ્રહ્મજ્ઞાની જેને ધર્મસર્ગનો લેશ નથી, તે બધા સહેજે ઊડી જાય છે.”","e":null,"s":["10/37/8-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":734,"k":"para","g":"માંગરોળમાં ભક્તોને શ્રીહરિ કહે, “જે અમને પરમ હેતથી બાંધે છે તેની પાસે અમે ખેંચાઈને રહીએ છીએ. રામાનંદ સ્વામીનું હેત, સત્સંગીઓ પર અધિક રહેતું, સત્સંગીઓના હેત કરતાં ચઢી જતું. જેમ પવન પાંદડાંને નચાવે, તેમ રામાનંદ સ્વામી હેતે કરીને ખેંચતા.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":735,"k":"para","g":"આણંદજી સંઘેડિયા કહે, “તમારા વચનમાં બધા સંતો એ જ રીતે નાચે છે ને! અનંતકોટિ બ્રહ્માંડ તમારે આધીન વર્તે છે. તમારું ધામ અક્ષર કે જે સૌથી અધિક શ્રેષ્ઠ છે તે તમારા દાસ થઈને વર્તે છે, મરજી પાળે છે. અક્ષર સુધી તમારે આધીન હોય તો બીજા તો હોય જ. બીજાં કેટલાનાં નામ લેવાં!”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":736,"k":"verse","g":"‘અક્ષર અધિક ધામ, વરતત સો તવ દાસ હોઈ,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":737,"k":"verse","g":"ઓર કો લહત નામ, તુમારી મરજી તાહિ લગ.’","e":null,"s":["12/16(15-b)/22-27"],"sv":[],"mt":false,"gl":null,"a":false},{"i":738,"k":"para","g":"પીપલાણામાં શ્રીહરિ કહે, “પ્રગટ હરિ કે સંત હરિજનનો સંગ થાય છે ત્યારે તે જન્મ-મરણના દુઃખથી છૂટે છે. અલૌકિક સુખ મેળવવા સત્સંગ વિના બીજો ઉપાય નથી. સૌ સંતો અને હરિભક્તોએ દેશદેશમાં આવી વાત કરવી. કારણ કે આ બ્રહ્મવિદ્યા છે. માયિક વિદ્યા પણ અભ્યાસ વગર ટકતી નથી તો આ બ્રહ્મવિદ્યા અભ્યાસ વિના ક્યાંથી ટકે? સતત અભ્યાસ અધિક ને અધિક કરતો રહે તો તેના હૃદયમાં પ્રગટ શ્રીહરિનો નિવાસ થાય છે.”","e":null,"s":["12/21(20)/35-40"],"sv":["मायिक विद्या जोउ, अभ्यास विन न रहत कोउ ।\n\n ब्रह्मविद्या यह सोउ, कछु न रहे अभ्यास विन ॥\n\n सत्संग को अभ्यास, करना सो सब से अधिक ।\n\n प्रगट हरि को निवास, होवत हें तेहि उर बीच ॥"],"mt":false,"gl":null,"a":false},{"i":739,"k":"para","g":"મેથાણમાં શ્રીહરિએ કહ્યું, “બ્રહ્મવેત્તા ગુરુ મળ્યા વિના બ્રહ્મની પ્રાપ્તિને માટે ફાંફાં મારી મરી જાય છે. ‘હું બ્રહ્મ છું’ એમ કહેવાથી બ્રહ્મ થવાય નહીં. બગલો પોતાને હંસ કહે તેથી હંસના ગુણ તેમાં આવે નહીં.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":740,"k":"verse","g":"‘બ્રહ્મવિત ગુરુ મિલે વિન કબહુ બ્રહ્મ કિ પ્રાપ્તિ ન હોવત સબકું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":741,"k":"verse","g":"હમ હેં બ્રહ્મ યું શિખે બાતા, બાત સે બ્રહ્મગુન લેશ ન આતા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":742,"k":"verse","g":"હંસ કે આકાર જોઈ કે જાહિ, બગલે કહે હમ હંસ રહા હિ.’","e":null,"s":["12/52/32-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":743,"k":"para","g":"ઉમરેઠમાં વિદ્વાનોની સભામાં શ્રીહરિ કહે, “બધાં સાધનનું ફળ એટલું જ છે કે વિષયથી રાગ તોડી આત્મારૂપે થવું. અને આત્મારૂપ થઈ ભગવાનમાં પ્રીતિ કરવી, તેને અમે બ્રહ્મનિષ્ઠ કહીએ છીએ. વેદ, ભાગવત, ગીતા આદિ શાસ્ત્રોને અમે સત્ય માનીએ છીએ. ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ તથા ભગવાનને સદા સાકાર માનવા - આ પાંચ વાતને અમે સર્વોપરી માનીએ છીએ. અક્ષરધામમાં સદા સાકારપણે અમે વિરાજમાન રહીએ છીએ. અનંત તનુ ધરીએ છીએ તો પણ તે ધામનો ક્યારેય ત્યાગ કરતા નથી. એવી અનંત યોગકળા છે જેનો બ્રહ્માદિક પાર લઈ શકતા નથી. જેને એવી પરમ ભક્તિ ઉદય થાય છે તેને અમારી આ અકળ કળા કળ્યામાં આવે છે. ભક્તિ વિના મોટા મોટા પંડિતો, પુરાણીઓ, જ્ઞાનીઓ, મોટા મોટા મુક્તો, સિદ્ધો, ધ્યાનીઓ, કોઈની નજરમાં એ રૂપ આવતું નથી. જે પૂર્ણ ભક્તિવાળો છે તે ક્યારેય અમને પોતાની દૃષ્ટિથી દૂર કરી શકતો નથી. અર્થાત્ અમે તેની પાસે રહીએ છીએ. જેને અંતરમાં એવી ભક્તિ હોય તેને જ આ વાત માન્યામાં આવે છે.” આટલી વાત કરીને શ્રીહરિ કહે, “હવે કીર્તન બોલો. સંતોએ ગોપાળદાસના ધોળ ગાયા.”","e":null,"s":["12/53/14-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":744,"k":"para","g":"સારંગપુરના જીવેન્દ્ર નૃપને શ્રીહરિએ ગઢપુરમાં વાત કરતાં કહ્યું, “જે દિવસથી અમે દેહનાં કુટુંબીનો ત્યાગ કર્યો છે ત્યારથી આજ દિન પર્યંત તે સ્વપ્નમાં પણ કદી આવ્યાં નથી. અમે અમારા અક્ષરધામથી પૃથક્ રહી શકતા નથી. સ્વપ્નમાં અક્ષરધામ, સંતો-ભક્તો અખંડ દેખાય છે. તેની વિસ્મૃતિ થાય તો અપાર દુઃખ થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":745,"k":"para","g":"“સત્સંગ વિના અનંતકોટિ બ્રહ્માંડનું રાજ્ય મળે તોપણ મોક્ષમાર્ગમાં તેને પરમ વિઘ્ન માનીએ છીએ. અમારી આ સમજણ છે. અમારા જેવી સમજ જેને હોય તેની બોલીમાં અમારા જેવો આનંદ છલકાય. અમારા તુલ્ય મળ્યા વિના કોઈને આ વાત અમે કરતા નથી, મનમાં ને મનમાં ઠોઈ રાખીએ છીએ. જેટલી પાત્રતા હોય તેટલી તેને વાત કરીએ છીએ. જેમ કીડીના ઉદરમાં સમુદ્ર ન સમાય, તેમ આ વાત પણ કોઈના પેટમાં સમાય તેવી નથી, એવી ગંભીર વાત છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":746,"k":"verse","g":"‘કીરી કે ઉદર મહીં, સિંધુ કો સબ હિ નીર,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":747,"k":"verse","g":"પીવત સમાવે કિસવિધ, વાત હે એસી ગંભીર.’","e":null,"s":["12/65/7-13"],"sv":[],"mt":false,"gl":null,"a":false},{"i":748,"k":"para","g":"કચ્છમાં કાળાતળાવ ગામે શ્રીહરિએ સંતોને વર્તન અને સમઝણની વાત કરતાં કહ્યું, “ભગવાનનું ધ્યાન સ્થિર આસન લગાવીને કરવું. દેહમાં વૃત્તિ લેશ પણ રહે નહિ તે રીતે ત્રણ દેહ, ત્રણ ગુણ ને ત્રણ અવસ્થાથી પોતાનું સ્વરૂપ ન્યારું (અક્ષર) સમજવું. જીવના સાચા સંગી ભગવાન તથા ભગવાનના સંત છે. ધામમાત્ર તેના સંગમાં રહ્યાં છે. અક્ષરધામમાં ધામમાત્ર આવી ગયાં. સર્વ ધામો કરતાં અક્ષરધામ અપાર છે. તેનું સુખ પણ અપાર અપાર છે. તેવી જેની સમજણ હોય તે જ સાચી સમજણવાળા છે. આવી સમજણ વગરની જેની સમજણ છે તે પોતાની રુચિ અનુસાર જાણવી.”","e":null,"s":["13/7/30-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":749,"k":"para","g":"લશ્કરનો સેનાપતિ નાગર કરિયાણામાં દેહાખાચરના ભવનમાં શ્રીહરિના દર્શને આવ્યો. શ્રીહરિએ તેની પાસે જ્ઞાનની વાર્તા કહેતાં કહ્યું, “ભગવાનના ચરિત્ર પરમ મોક્ષરૂપ છે. તેને જે સાંભળે છે તેનું જન્મ-મરણ ટળી જાય છે. અક્ષર જે ભગવાનનું ધામ છે, તેમાં ભગવાનનાં નામ-ચરિત્ર સમાયાં રહે છે. જેમ આંબાનું બીજ ગોટલી છે, તેમાં આંબો, પાંદડાં, મોર કે કેરીઓ દેખાતાં નથી, પણ તેમાં એ બધું સમાયેલું છે, તેવું અક્ષરનું છે. તે હમણાં કશું દેખાય નહિ, પણ સમય આવે ત્યારે ભગવાન સંબંધી નામ-ચરિત્રો બધું અક્ષરમાં દેખાઈ આવે છે. એમ, ભગવાનનાં ચરિત્રો અક્ષરમાં રહેલાં છે ને ચરિત્રોમાં અક્ષરધામ રહેલું છે. આ કહ્યું તેમાં લેશમાત્ર સંશય નથી. જેને જ્ઞાનરૂપી ચક્ષુ છે તે પ્રત્યક્ષ દેખે છે. દિવ્ય તત્ત્વ કે વાત છે તે દિવ્ય નયનથી જ દેખાય છે. માયિક દૃષ્ટિથી તે દેખાતાં નથી.”","e":null,"s":["13/31/26-36"],"sv":["हरि के चरित्र हि नाम, परम मोक्ष हि कहत तेहि ।\n\n अक्षर कहत जो धाम, चरित्र नाम तामहिं रहेउ ॥\n\n आंब पत्र मोर फलहि जेहा । रस ओर कहावत जेहा ॥\n\n सबहि रहे हें बीज के मांहीं । ताके समय देख परत रहां हि ॥\n\n यामें फारफेर नहि लेशा । चरित्र में धाम फल रहे एसा ॥\n\n ज्ञानी संशय न रहावे । ज्ञानरूप चक्षु कर देख आवे ॥\n\n दिव्य वात कहावत जेती । दिव्य नेंन देख परत तेती ॥\n\n मायिक दृग सें कबु न देखावे । मनुष्य के जन्म कोटि धरावे ॥"],"mt":false,"gl":null,"a":false},{"i":750,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ વણિકને વાત કરતાં કહ્યું, “ગમાર લોકો મોટાની દેશી કાઢે છે, પણ વેદથી વિરુદ્ધ વર્તે તે પાખંડ કહેવાય છે. કર્મથી ઉદ્ધાર માને અને ભગવાનનું નામ ન લે તે બેસવાની ડાળ કાપે છે. ભગવાનના અવતારનું ચરિત્ર મોક્ષદાયી છે. ભગવાનના શરણ વિના જીવ ચોરાશીમાં ભટકે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":751,"k":"para","g":"“ભગવાન પુરુષોત્તમ સિવાય અક્ષરમુક્તો, દેવો, ભૂપો, મનુષ્યો, અનંતકોટિ બ્રહ્માંડના અધીશ્વરો, કાલ-કર્મ, માયા - બધાનું તપ ભેગું કરીએ તોપણ અક્ષરના એક રોમ જેટલું પણ સમર્થ નથી, ક્ષુદ્ર છે. અને અક્ષરબ્રહ્મ જેવા અનંતનો તપ પ્રતાપ ભગવાનના એક રોમમાં સમાઈ જાય છે એવા એ સમર્થ છે.”","e":null,"s":["13/48/20-23, 29-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":752,"k":"para","g":"ચલોડે આવતાં પૂર્વે શ્રીહરિએ સંતોને કહ્યું, “તમે ત્યાગ કર્યો તેથી હવે લેશ પણ ડર રહ્યો નહીં. હવે જેનો ડર હશે તેનો અમે ત્યાગ કરાવીશું. જેટલી નિર્ભય વસ્તુ છે તે અમે તમને આપી છે. તમારા ઉપર અમને અપાર હેત છે. તમારા સ્વરૂપને કોઈની ઉપમા ઘટે નહિ. માયિક તનના સંબંધથી એકબીજાનું સ્વરૂપ દેખાતું નથી, પણ અમારા સ્વરૂપનું યથાર્થ જ્ઞાન થશે ત્યારે માયિક તન (દેહભાવ) છૂટી જશે. તમે જે આ સ્થૂળ આંખોથી જુઓ છો, હવેથી એ આંખોથી નહિ પણ જ્ઞાનચક્ષુથી દેખી સ્વરૂપ દૃઢ કરી લેજો. પછી તેનું શ્રવણ, મનન, દિનરાત કરી તેનો બહુ પ્રકારે અભ્યાસ કરવો. અભ્યાસ કરવામાં જેટલી આળસ તેટલી જ્ઞાનની વૃદ્ધિ ન થાય, તે સો વર્ષ સુધી શ્રવણ કરો તોપણ અભ્યાસ (મનન, નિદિધ્યાસ) વિના સાક્ષાત્કાર ન થાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":753,"k":"para","g":"“વિદ્યાઓનો પાર નથી, પણ દુર્લભમાં દુર્લભ બ્રહ્મવિદ્યા કહી છે. બ્રહ્મવિદ્યા ચિંતામણિથી અધિક છે. બ્રહ્મવિદ્યા સિદ્ધ કર્યા વિના શાંતિ થવાની નહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":754,"k":"para","g":"“પ્રત્યક્ષ ભગવાનનાં (અમારાં) જેટલાં ચરિત્રો છે તેનું રસપૂર્વક શ્રવણ કરવું. તેમાં એવું તાન રાખવું, જેવું વિષયીજનને વિષયમાં તાન છે. અમારાં જેટલાં ચરિત્ર છે તેમાં તાન રહે તે બ્રહ્મવિદ્યા છે. સુખપ્રાપ્તિનું સાધન આ જ છે. એ વિના શાંતિ થતી નથી. આ અમે તમને કહ્યું.” એટલી સંતોને વાત કરી ‘જય સચ્ચિદાનંદ’ કહી શ્રીહરિ અશ્વ પર બિરાજ્યા.","e":null,"s":["14/4/17-29"],"sv":[],"mt":false,"gl":null,"a":false},{"i":755,"k":"para","g":"શ્રીહરિએ પત્ર લખાવ્યો, જેમાં ઉત્તમ ભક્તની ઓળખ આપતા લખ્યું: “જે ભક્ત ત્રણ દેહ, ત્રણ અવસ્થાથી પર વર્તે, દેહને અસત્ય માને, આત્માને સત્ય માને, પોતાના આત્માને દેહથી પૃથક્ બ્રહ્મરૂપ જાણે ને પરબ્રહ્મ ભગવાન પુરુષોત્તમનો જોગ (ઉપાસના) કરે. એવા ભક્તને વિવેકી ને સમર્થ જાણવો.”","e":null,"s":["15/96/21-26"],"sv":["हरिभक्त विवेकी जितने, भये समर्थ जो जेह ।\n\n असत मानत हि देह कुं, जीय मानत सत तेह ॥\n\n परब्रह्म भगवान के, जोग करि के जोउ ।\n\n ब्रह्मरूप जाने जीय कुं, पृथक् तन देख हि सोउ ॥"],"mt":false,"gl":null,"a":false},{"i":756,"k":"para","g":"પત્રમાં શ્રીહરિ કહે, “‘હું બ્રહ્મરૂપ એવો ભગવાનનો દાસ છું’ એવો અહંકાર ઉત્તમ ભક્તને હોય છે. આવો ભક્ત અક્ષરરૂપ થયો હોઈ ગોલોકથી પર એવું અક્ષરધામ છે તેને પામે છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":757,"k":"verse","g":"‘આવત હેં અહંકાર હિ એસા, મેં હૂઁ બ્રહ્મસ્વરૂપ તેસા;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":758,"k":"verse","g":"ગોલોક સે પર અક્ષરધામા, એસે ભક્ત રહત તેહિ ઠામા.’","e":null,"s":["15/100/12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":759,"k":"para","g":"શ્રીહરિએ ધર્મપુરનાં રાણી કુશળકુંવરબાને કહ્યું, “પાતાળથી પ્રકૃતિપુરુષ સુધીના લોકના ભોગ માયામય છે ને દસ-દસ ગણા અધિક છે. પ્રકૃતિપુરુષથી પર અપાર અક્ષરધામ છે જેને તુલ્ય કોઈ સ્થાનક નથી. બીજાં સ્થાનકમાત્રનાં સુખ અક્ષરધામની આગળ દુઃખ અને ભયથી યુક્ત છે. જે ભગવાનનો ભક્ત થાય છે તે અક્ષરધામ સિવાય બીજા કોઈ લોકના સુખમાં આસક્ત થતો નથી. જે આસક્ત થાય છે, મોહાય છે તે માયાના ભક્ત છે.”","e":null,"s":["16/27/14-18"],"sv":[],"mt":false,"gl":null,"a":false},{"i":760,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ હરિજનો પ્રત્યે વાત કરતાં કહ્યું, “ભગવાનના સંબંધ વગર કોઈ બ્રહ્મ થઈ શકતું નથી. જે સાચા બ્રહ્મ છે તે ભગવાન મળ્યા હોય તોપણ દેહની સ્મૃતિ જ્યાં સુધી રહે ત્યાં સુધી સાધનનો ત્યાગ કરતા નથી. ભગવાનની ઉપાસના કરીને જીવ બ્રહ્મ થાય છે. ઉપાસના અને ભગવાનને પ્રસન્ન કરવાનાં સાધન વગર બ્રહ્મ થવું અસંભવ છે. જે સાચા બ્રહ્મ છે તે ભગવાનનું ધ્યાન, વંદન, પૂજન, ભગવાનનો જન્મોત્સવ, એકાદશી આદિક વ્રત તથા ભગવાન સંબંધી તીર્થવ્રતાદિક વિધિવત્ કરતા રહે છે. વળી, જે સાચો બ્રહ્મરૂપ થયો છે તેના અંતરમાં કોઈ પ્રપંચ હોતો નથી. દેહના અંત સુધી માન અને અધર્મથી ડરતો રહે છે. વિષય-વ્યસનનો ત્યાગ કરીને ભગવાનમાં અનુરાગ રાખે છે. અને એમ સમજે છે જે, ભગવાન અને ભગવાનનું ધામ આત્યંતિક પ્રલયમાં પણ નાશ પામતું નથી. પ્રકૃતિ સંબંધી કાર્ય પ્રકૃતિમાં લીન થઈ જાય છે. એ ભગવાનની લીલા છે. એમનાં ચરિત્રો ને મહિમાનો કોઈ પાર પામતું નથી.”","e":null,"s":["16/47/1-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":761,"k":"para","g":"ગઢપુરમાં શ્રીહરિ કહે, “જે બ્રહ્મરૂપ થઈને પરબ્રહ્મની ભક્તિ કરે છે, તે જ સાચા બ્રહ્મ છે. તે વિના તો બ્રહ્મદ્રોહી છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":762,"k":"verse","g":"‘બ્રહ્મ હોઈ કે જેહ, પરબ્રહ્મ તાકિ સેવ કરત;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":763,"k":"verse","g":"સાચે બ્રહ્મ હિ તેહ, તો બિન બ્રહ્મદ્રોહી હોત.’","e":null,"s":["16/47/40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":764,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ હરિજનોને વાત કરતાં કહ્યું, “જે ભક્ત અંતર્દૃષ્ટિથી દેખે છે તેને ધામ સહિત ભગવાન પુરુષોત્તમ સમીપમાં જ જણાય છે. સ્થૂળ દૃષ્ટિથી જુએ તો અતિ દૂર છે. માયિકભાવ પલટી અંતર્વૃત્તિ કરે અને જાણપણા રૂપ દરવાજે ઊભો રહી શ્રવણ-મનન કરે તેને એ ધામ અને ધામી અષ્ટાવરણથી પર હોવા છતાં તેનો અનુભવ છતી દેહે થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":765,"k":"para","g":"“જ્યારે માયિકવૃત્તિ પલટાય છે અને અલૌકિક વૃત્તિ થાય છે ત્યારે આવરણ પાર રહેલું ધામ અંતરમાં દેખાય છે. જેને અંતર્વૃત્તિ થાય છે તે જ આ કળાને જાણે છે. કળા જાણ્યા વગર સમજમાં આવતું નથી એવી આ વાત છે.” આટલી વાત શ્રીહરિએ કરી ત્યાં વડતાલના હરિજનો આવ્યા અને શ્રીહરિનાં ચરણોમાં પડીને ફૂલદોલ ઉત્સવ કરવાનો નિમંત્રણપત્ર કરમાં આપ્યો.”","e":null,"s":["16/49/3-11"],"sv":[],"mt":false,"gl":null,"a":false},{"i":766,"k":"para","g":"પીપળાવમાં શ્રીહરિએ આનંદાનંદમુનિ આદિક સંતોને વાત કરતાં કહ્યું, “બ્રહ્મરૂપ થઈને જે ભગવાનની ઉપાસના કરતો નથી તે કૃતઘ્નીમાં કૃતઘ્ની છે. ભગવાનની સાકાર ઉપાસના વિનાના ચાહે તેવા વેદાંતના ગ્રંથો હોય તેને ભણવા કે સાંભળવા નહીં. શ્રુતિ-સ્મૃતિના ગ્રંથોમાં પણ જો જીવ અને ભગવાનને એક કરીને કહેતા હોય તો તે પણ અમારા સાધુ, હરિજન, વર્ણી ઇત્યાદિ કોઈએ સાંભળવા નહીં કે ભણવા નહીં. આટલું અમારું વચન દૃઢ કરીને રાખજો. આ વાત તમારા સૌના હિત માટે અમે હેતે કરીને કહી છે.”","e":null,"s":["16/54/19-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":767,"k":"para","g":"વડનગરમાં સંતો પાસે વાત કરતાં શ્રીહરિએ કહેલું તે સ્મૃતિ કરતાં મુક્તમુનિ કહે,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":768,"k":"verse","g":"‘હરિકી બાત જબ હરિ, કહત ભયે તબ જાન પરેઉ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":769,"k":"verse","g":"વેદ તેહિ સ્તુતિ કરી, ઉચરત રહે સંત પ્રતિ.’","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":770,"k":"para","g":"વેદો જેની સ્તુતિ કરે છે એવા શ્રીહરિ પોતાની વાત સ્વયં કરે, ત્યારે જ સમજ્યામાં આવે. એ શ્રીહરિ સંતો પ્રત્યે કહેવા લાગ્યા, “ભગવાનમાં જડ અને ચૈતન્યરૂપ બે શક્તિ રહેલી છે. એમના એ ઐશ્વર્યને ‘યોગકળા’ કરીને કહે છે. શ્રીહરિના એક રોમમાં અક્ષરકોટિ અનંત સમાઈ જાય એવું તેમનું ઐશ્વર્ય છે. વળી, અક્ષરના એક એક રોમમાં બ્રહ્માંડોની કોટિયુંની કોટિયું રહી છે. અક્ષર એવા મોટા છે તોપણ શ્રીહરિના દાસ થઈને વર્તે છે. હરિનો દાસ થાય છે તેનામાં અક્ષર જેવું અનંત અપાર ઐશ્વર્ય આવે છે. જીવ જ્યાં સુધી શ્રીહરિનો દાસ થતો નથી, ત્યાં સુધી ફાવે તેટલો જ્ઞાની હોય તોપણ તે શુષ્કજ્ઞાની રહે છે. તે જ્ઞાતિજનમાં પુછાતો હોય પણ દાસનું એક રૂંવાડું પણ તે થઈ શકતો નથી.”","e":null,"s":["18/53/27-32"],"sv":["अक्षर के एक रोम रोम तामें । ब्रह्मांड की कोटि कोटि वामें ॥\n\n रहाये अक्षर रहे ऐसे । हरि के दास होई कर तेसे ॥\n\n हरि के दास होई वर्तत तिन में । ऐश्वर्य अनंत अपार इनमें ॥\n\n श्रीहरि के जिहां लगहि जेहा । होवत नाहि दास जन तेहा ॥\n\n च्हाय तेसे यह ज्ञानी होउ । शुष्क ज्ञानी रहावत सोउ ॥\n\n हरि के दास दिन च्हाय तितना । ज्ञातिजन में होवे जितना ॥\n\n श्रीहरि ताके दास हि तेहि । रोम एक सम होत न एहि ॥"],"mt":false,"gl":null,"a":false},{"i":771,"k":"para","g":"શ્રીહરિએ ગઢપુરમાં વાત કરતાં કહ્યું, “માયા અને માયાના કાર્યરૂપ અનંતકોટિ બ્રહ્માંડમાં અક્ષરબ્રહ્મ અન્યપણે કરીને રહ્યા છે. વળી, એ બધાથી જુદા વ્યતિરેક સ્વરૂપે સચ્ચિદાનંદપણે કરીને અક્ષરબ્રહ્મને કહેવા તે તેમનું વ્યતિરેકપણું છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":772,"k":"verse","g":"‘માયા માયા કે કાર્ય જિતના, અનંતકોટિ બ્રહ્માંડ તિતના.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":773,"k":"verse","g":"તાકે વિષે અન્વયપના જેહુ, અક્ષરબ્રહ્મ કું કહે તેહું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":774,"k":"verse","g":"યહ સબસેં વ્યતિરેક જો જેહિ, સચ્ચિદાનંદપને કર તેહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":775,"k":"verse","g":"અક્ષરબ્રહ્મ કું કે’ના જેહુ, વ્યતિરેકપના તાકે હેં તેહુ.’","e":null,"s":["21/5/30-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":776,"k":"para","g":"શ્રીહરિએ ગઢપુરમાં સંતો-ભક્તોને વાત કરતાં કહ્યું, “અક્ષરબ્રહ્મના તેજમાં મહામાયાનો લય થઈ જાય છે. જે દેખ્યામાં આવતો નથી. જેમ દિવસમાં રાત્રિનો લય થઈ જાય છે તે જ રીતે અક્ષરબ્રહ્મમાં માયાનો લય થઈ જાય તેને આત્યંતિક પ્રલય કહેવાય છે.”","e":null,"s":["21/8/38-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":777,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સત્સંગીમાત્રને દૃઢ નિર્ધાર કરવાની વાત કરતાં કહ્યું, “ભગવાનનું ધામ અક્ષરધામ છે. તેને ભગવાનનો નિષ્કામ ભક્ત હોય તે પામે છે. અક્ષરધામનાં બે સ્વરૂપ છે. એક પ્રકાશરૂપ નિરાકાર છે જેને એકરસ ચૈતન્ય ચિદાકાશ કહે છે. જે દિવ્ય તેજોમય બ્રહ્મમહોલ કહેવાય છે, જે અનંતકોટિ મુક્તોને તથા પરબ્રહ્મ શ્રીહરિને ધરી રહ્યું છે. બીજે રૂપે એ અક્ષર પુરુષોત્તમનારાયણની સેવામાં દાસભાવે અખંડ હજૂરરૂપે વર્તે છે, પળ પણ દૂર થતા નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":778,"k":"para","g":"“અક્ષરધામને એ જ પામે છે જે એકાંતિક ભક્ત થાય છે. અક્ષરનું સાધર્મ્યપણું પામે છે તેને એકાંતિકના ગુણે ઓળખવા. ભગવાન પુરુષોત્તમનારાયણ જ્યાં અખંડ બિરાજે છે એવું અક્ષરબ્રહ્મ ધામ છે. એ અક્ષરના સાધર્મ્યને પામેલા અનંતકોટિ મુક્તો ભગવાનની અખંડ સેવામાં રહે છે. અને પુરુષોત્તમનારાયણના દાસભાવે વર્તે છે. આ વાત દૃઢપણે સમજીને દરેક સત્સંગીએ એવો નિર્ધાર કરવો કે અક્ષરરૂપ થઈ એ મુક્તની પંક્તિમાં બેસવું છે. નિશ્ચે કરના ઈસ વિધિ હિ, અપને અક્ષરરૂપ, મુક્ત તાકી પંક્તિ મેં જો, મિલના બાત અનૂપ.”","e":null,"s":["21/16/42-52"],"sv":["भगवान के अक्षर हि धामा । पावत हे भक्त जो अकामा ॥\n\n अक्षरधाम के स्वरुप दोउ । निराकार एक कहत हे सोउ ॥\n\n एक रस चैतन्य चिदाकाशा । ब्रह्ममहोल कहत उजासा ॥\n\n दूजे रूप कर अक्षर जेहु । पुरुषोत्तम की सेवा में तेहु ॥\n\n अखंड रहे पल होत न दूरा । दास होइ कर होत हजूरा ॥\n\n अक्षरधाम कुं पावत जितना । एकांतिक भक्त जो तितना ॥\n\n अक्षर के साधर्म्य जो ताकु । एकांतिक गुन कर पावत वाकुं ॥\n\n भगवान की अखंड जो एहि । सेवा में रहत भये तेहि ॥\n\n पुरुषोत्तम नारायण स्वामी । विराजमान रहे बहुनामी ॥\n\n अक्षर यह धाम जो तामें । अक्षर के साधर्म्यपना यामें ॥\n\n पाये अनंतकोटि हि एसा । मुक्त जो रहाये सबहि तेसा ॥\n\n पुरुषोत्तम के दास हि भावा । वरतत रहे सहज स्वभावा ॥\n\n पुरुषोत्तम नारायण जेउ । सबहि के स्वामि रहेउ तेउ ॥\n\n अनंतकोटि ब्रह्मांड के, राजाधिराज रहेउ ।\n\n एसि वातकुं समज कर, सत्संगि आपनेउ ॥\n\n निश्चे करना इस विध हि, अपने अक्षर रुप ।\n\n मुक्त ताकि पंक्ति में जो, मिलना बात अनूप ॥\n\n अक्षरधाम तामें जाय, अखंड भगवान की ।\n\n हजुर रहिके यामें, सेवा करना भाव कर ॥\n\n नाशवंत तुच्छ जेह, ऐसे मायिक सुख जोउ ।\n\n इच्छत नहि कबु तेह, लोभावत न यामें कबु ॥"],"mt":false,"gl":null,"a":false},{"i":779,"k":"para","g":"શ્રીહરિએ ગઢપુરમાં મુનિ તથા હરિજનની સભામાં પુરુષોત્તમ સ્વરૂપની વાત કરતાં કહ્યું:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":780,"k":"verse","g":"‘અક્ષર તામેં રહેઉ જૈસે, પુરુષ-પ્રકૃતિ મેં નહિં તેસે;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":781,"k":"verse","g":"એસી રીત પુરુષોત્તમ જેહિ, તારાત્મ્યતાએ કરિકે તેહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":782,"k":"para","g":"“પુરુષોત્તમ ભગવાન જેવા અક્ષરમાં રહે છે એવા પ્રકૃતિપુરુષમાં નથી અને એવા અવાન્તર મનુષ્ય, કીટ-પતંગ સુધી કોઈમાં નથી. બીજા પ્રધાનપુરુષ, મહત્તત્ત્વ, વિરાટનારાયણ બ્રહ્મા, મરિચ્યાદિક પ્રજાપતિ, કશ્યપ પ્રજાપતિ, ઇન્દ્રાદિક દેવતા, મનુષ્ય, પશુ-પક્ષી - બધામાં તારતમ્યતાએ કરીને છે, પણ જેવા અક્ષરમાં રહ્યા છે તેવા પુરુષ-પ્રકૃતિ આદિ અન્યમાં નથી રહ્યા. પોતે અંતર્યામી છે, યોગકળા ધરીને બધામાં કારણપણે કરીને જ્યાં જેમ ઘટે તેમ તે રીતે રહ્યા છે. એવું એમનું અગણિત સામર્થ્ય છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":783,"k":"verse","g":"‘સબમેં કારનપને કરીકે, અંતર્યામિ યોગ કલા ધરિકે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":784,"k":"verse","g":"રહેઉ જીહાં જેસે ઘટિતા, સામૃથ એસે રહે અગનીતા.’","e":null,"s":["21/38/18-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":785,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ અક્ષરતત્ત્વની વાત કરતાં કહ્યું, “પુરુષોત્તમ ભગવાનનું જે અક્ષરધામ છે તે અક્ષરના એક દેશમાંથી મહાપુરુષ ઊપજે છે, માટે જ્યારે અક્ષરની દૃષ્ટિએ કરીને જોઈએ છીએ ત્યારે મહાપુરુષ નજરમાં આવતો નથી એક અક્ષર જ દેખાય છે. અક્ષર વિના બીજું કાંઈ જણાતું નથી. એ અક્ષરથી પર અક્ષરાતીત પુરુષોત્તમ ભગવાન છે.”","e":null,"s":["21/48/39-41"],"sv":[],"mt":false,"gl":null,"a":false},{"i":786,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ અક્ષરબ્રહ્મનો મહિમા કહેતાં કહ્યું, “અક્ષરના રોમ રોમ પ્રત્યે અનંતકોટિ બ્રહ્માંડ અણુની પેઠે ઊડે છે એવું પુરુષોત્તમ ભગવાનનું ધામ અક્ષર છે. એ અક્ષરધામમાં ભગવાન પુરુષોત્તમ સદાય દિવ્ય સાકારરૂપે બિરાજે છે. જે અક્ષરના પણ કારણ છે અને મૂર્તિમાન છે. એ ભગવાનના ધામરૂપ અક્ષરની મોટાઈ વર્ણવી શકાય તેમ નથી. જેમ મોટા હાથીના શરીર પર કીડી ચાલે તે તેની ગણતીમાં હોય નહીં. એમ અક્ષરની મોટાઈ આગળ કોઈ ગણતીમાં આવતું નથી. અક્ષરની મોટાઈ વર્ણવવામાં આવે નહીં. તો પુરુષોત્તમની મોટપ વર્ણવ્યામાં કેમ આવે?","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":787,"k":"para","g":"“બધાનું કારણ અક્ષરબ્રહ્મ છે. એ અક્ષર પુરુષોત્તમનું ધામ છે ને કરચરણ યુક્ત મૂર્તિમાન છે. પણ અતિશય મોટપને લીધે અક્ષરનું રૂપ નજરમાં આવતું નથી. એ સૌથી મહાનમાં મહાન છે અને સૂક્ષ્મ પણ છે. તેના એક એક રોમમાં અસંખ્યાત બ્રહ્માંડ ઊડે છે, એવા અક્ષરનો પાર પમાતો નથી તો તેનાથી પર અતિ સમર્થ અને પ્રતાપી એવા મહારાજાધિરાજ ભગવાન પુરુષોત્તમ, જે અક્ષરધામમાં સદા વિરાજમાન છે તેમનો મહિમા કેમ વર્ણવી શકાય?”","e":null,"s":["21/64/37-77"],"sv":["अनंत कोटि ऐसे ब्रह्मांड एक एक रोमे ।\n\n प्रत्ये अणु जेसे, उडत फिरत हि रहे तेहि ॥\n\n ऐसे भगवान ताके, अक्षर यह जो धाम रहे ।\n\n धाम के विषे वाके, पुरुषोत्तम भगवान यह ॥\n\n सूक्ष्म अरु कारन रहेउ, एह सब मूर्तिमान ।\n\n भगवान के अक्षर जोऊ, धाम हि बडे रहान ॥\n\n जाके एक एक रोम हि, अनंतकोटि जोऊ ।\n\n ब्रह्मांड अणु सम हि जो, उडते फिरत हि सोऊ ॥\n\n जीमि कोउ करी बडेउ, हस्ति होय शरीर यह ।\n\n किडि चलत हि रहेउ, गणति में कहां रहे तेऊ ॥\n\n तिमि यह अक्षर ताकि, मोटाई आगे ओर सब I\n\n गणतिमें न आवत वाकि, अक्षर रहे सबसें अधिक ॥\n\n एहि सबके कारन जो, अक्षरब्रह्म रहेउ ।\n\n अक्षर पुरुषोत्तम हुके, धाम रहाये तेऊ ॥\n\n एह अक्षर जो तिनकि, संकोच अरु विकास ।\n\n अवस्था होवत नहि हें, एक रूप रहे तास ॥\n\n अक्षर कहे जो जेह, मूर्तिमान हि रहे तेहि ।\n\n अति बडे रहे तेह, कोईकि नजरे रूप यह ॥\n\n आवत नहि ताके, जिमि चोविश तत्त्व तिनके ।\n\n कारज्य जेहि वाके, ब्रह्मांड पुरुषावतार हि ॥\n\n तिमि अक्षरधाम पण जेहु । मूर्तिमान रहायेउ तेहु ॥\n\n पण कोई कि नजर नहि आते । सबसें बडे सुक्ष्म रहाते ॥\n\n शा माट हि ऐसे हि एसेउ । ब्रह्मांड एक एक रोम तेहु ॥\n\n असंख्यात उडत फिरेउ । ताके पार को न लहेउ ॥\n\n एसे बडे जो अक्षरधामा । ताके विषे पुरुषोत्तम नामा ॥\n\n भगवान पोते सदा रहाता । महाराजाधिराज कहाता ॥\n\n महिमा किमि हि के’वाय ताके । अपार ऐसे प्रताप रहे जाके ॥\n\n अति समर्थ ऐसे हि भगवाना । यह आप अक्षरमें रहाना ॥"],"mt":false,"gl":null,"a":false},{"i":788,"k":"para","g":"ગઢપુરમાં શ્રીહરિ કહે, “અક્ષરની એટલી મોટાઈ છે કે તેની આગળ કોઈ ગણતરીમાં આવતું નથી. એટલે બધાથી પર અક્ષર રહ્યા છે.”","e":null,"s":["21/64/51-52"],"sv":[],"mt":false,"gl":null,"a":false},{"i":789,"k":"para","g":"ગઢપુરમાં શ્રીહરિ કહે, “પૃથ્વી, જળ, તેજ, વાયુ, આકાશ, અહંકાર, મહત્તત્ત્વ, પ્રધાનપુરુષ, મૂળ પ્રકૃતિ, મહાપુરુષ - એ સર્વેનું કારણ અક્ષરબ્રહ્મ છે. એ અક્ષર પુરુષોત્તમનારાયણનું ધામ છે. તેની સંકોચ-વિકાસ અવસ્થા નથી, સદાય એકરૂપે રહે છે. એ જ અક્ષર મૂર્તિમાન પણ છે. પરંતુ અતિશય મોટા હોવાથી તેનું સ્વરૂપ કોઈની નજરમાં આવતું નથી.”","e":null,"s":["21/64/58-63"],"sv":[],"mt":false,"gl":null,"a":false},{"i":790,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ વાત કરી, “અક્ષરધામ મૂર્તિમાન છે, તે બધાથી સૂક્ષ્મ પણ છે ને બધાથી મોટા પણ છે. તેમના એક એક રોમમાં અસંખ્ય બ્રહ્માંડો ઊડી રહ્યાં છે. તેમનો પાર કોઈ લઈ શકતું નથી. એવું મોટું જે અક્ષરધામ તેને વિષે પુરુષોત્તમ ભગવાન પોતે સદાય વિરાજમાન રહે છે.”","e":null,"s":["21/64/68-71"],"sv":[],"mt":false,"gl":null,"a":false},{"i":791,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સંતો-ભક્તોને ઉપાસના સંબંધી વાત કરતાં કહ્યું, “પ્રકૃતિપુરુષાદિક સર્વેનું કારણ અક્ષર છે, તે સર્વનો આધાર છે ને સર્વેના અંતર્યામી છે. પોતાની અંતર્યામી શક્તિએ કરીને એ અક્ષર સર્વેમાં વ્યાપીને રહ્યા છે. જે કારણ હોય, આધાર હોય, અને પ્રેરક હોય તે કાર્યથી જુદા ન હોય. એટલે શાસ્ત્રો અક્ષરબ્રહ્મને સર્વરૂપ કહે છે, પણ એ બ્રહ્મ ચરાચર જીવરૂપે થઈ ગયા એમ ન સમજવું. અને એ અક્ષરબ્રહ્મથી પરબ્રહ્મ પુરુષોત્તમનારાયણ પૃથક્ છે. એ તો અક્ષરબ્રહ્મના પણ કારણ છે, આધાર છે અને પ્રેરક છે. જીવાત્માએ એ અક્ષરબ્રહ્મ સાથે એકતા સાધીને પરબ્રહ્મની સ્વામી-સેવકભાવે ઉપાસના કરવી. જેને પરમપદ એવી મુક્તિ પ્રાપ્ત કરવી હોય તેને આ બ્રહ્મજ્ઞાનનો નિર્વિઘ્ન અને શ્રેષ્ઠ માર્ગ છે.”","e":null,"s":["22/9/84-92"],"sv":["अरु यह ब्रह्म सें जोउ, परब्रह्म यह जेहु ।\n\n पुरुषोत्तम नारायण हि, पृथक रहाये तेहु ॥\n\n एह ब्रह्म ताके, कारण रु आधार रहेउ ।\n\n अरु प्रेरक हें वाके, ऐसे समझ जीवात्मा ॥\n\n यह ब्रह्म के संग, एक हिता करीके जोउ ।\n\n परब्रह्म सें अभंग, स्वामि सेवक भाव कर ॥\n\n उपासना यह जेउ, करना ऐसि समझ कर ।\n\n ब्रह्मज्ञान तब तेउ, परम पद मिलन हुके ॥\n\n निरबिघ्न जउ तेहु, मारग रहेउ श्रेष्ठ यह ।\n\n ऐसि रीत करहि जेहु, प्रश्र के उत्तर करत हरि ॥"],"mt":false,"gl":null,"a":false},{"i":792,"k":"para","g":"શ્રીહરિએ પંચાળામાં ઝીણાભાઈ નૃપના દરબારમાં વાત કરતાં કહ્યું, “અક્ષરબ્રહ્મના એક એક રોમમાં અનંતકોટિ બ્રહ્માંડ અણુની પેઠે ઊડે છે. એવા અક્ષરના પણ ઈશ સ્વામી પુરુષોત્તમનારાયણ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":793,"k":"para","g":"“એ પુરુષોત્તમને બ્રહ્માંડની મોટપ શા લેખામાં? પોતે અહીં મનુષ્યાકૃતિ ધરીને વિચરે છે, પણ એવા ને એવા જ અક્ષરધામમાં રહ્યા છે. એટલે મનુષ્ય જેવા જણાય છે, પણ દિવ્ય છે. શ્રીહરિ અહીં જે રીતે રહે છે તે જ રીતે અક્ષરધામમાં વિરાજે છે. અને જેવા અક્ષરધામમાં વિરાજે તેવા જ અહીં વિચરે છે.”","e":null,"s":["25/28/9-12"],"sv":["अक्षर के एक एक जोउ । रोम ताके हि माहिं सोउ ॥\n\n अनंत अनंत कोटि हि जाही । ब्रह्मांड उडत अणु जीमी ताही ॥\n\n ऐसे अक्षर के रहे ईशा । ब्रह्मांड की मोटप कोन दीशा ॥\n\n मनुष्याकृति धरे कहा होई । जेसे के तेसे रहे सोई ॥\n\n इहां हरि रहे जिस रीता । अक्षर तामें रहे तिस रीता ॥\n\n अक्षर तामें रहाये जीमी । इहां बिचरत रहाये तीमी ॥"],"mt":false,"gl":null,"a":false},{"i":794,"k":"para","g":"ગઢડામાં ઉત્તમ નૃપના ભવનમાં શ્રીહરિએ સંતો-ભક્તોને અક્ષરબ્રહ્મ તથા સ્વસ્વરૂપની અદ્‌ભુત વાતો કરતાં કહ્યું, “સગુણ સ્વરૂપે જેટલા મોટા પદાર્થ કહેવાય છે તેનાથી પણ અતિશય મોટા અક્ષરબ્રહ્મ છે. એવા અક્ષરના એક એક રોમમાં અષ્ટાવરણે યુક્ત કોટિ કોટિ બ્રહ્માંડ અણુની પેઠે રહ્યાં છે. તે બ્રહ્માંડ તો એવડાં જ છે, નાનાં થતાં નથી, પણ અક્ષરની અતિશય મોટપ આગળ તે નાનાં દીસે છે. એ અક્ષર સૂર્યમંડળ જેવા છે. જેમ સૂર્ય ઊગે ત્યારે દશે દિશાનું જ્ઞાન થાય છે, તેમ અક્ષરધામની ફરતે ઉપર નીચે બધી દિશામાં બ્રહ્માંડોની કોટિયું અગણિત અપાર રહી છે. એ અક્ષરધામમાં પુરુષોત્તમ પરબ્રહ્મ નારાયણ સદા બિરાજમાન રહે છે. જ્યાં પુરુષોત્તમની મૂર્તિ રહે છે, ત્યાં જ અક્ષરધામનું મધ્ય છે.”","e":null,"s":["26/47/13-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":795,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":796,"k":"para","g":"ધર્મપિતાએ શ્રીહરિને શાસ્ત્રોનો અભ્યાસ કરાવ્યો તેમાં શ્રીહરિએ વ્યાસ અને રામાનુજના ગ્રંથમાંથી જે સાર તારવ્યો તે આમ હતો, “પરમેશ્વર (પુરુષોત્તમનારાયણ) અક્ષરમાં રહે છે અને એ અક્ષર પરમેશ્વરમાં રહે છે. એ બન્ને ક્યારેય જુદા રહેતા નથી, અખંડના અખંડ સાથે જ સદાય રહે છે. માયા અનંત છે, પરંતુ અક્ષર પાસે તેનું લેશ પણ ઊપજતું નથી. જેની દૃષ્ટિ અક્ષરમાં પહોંચે છે તેને કોઈ વાત અગમ કે અપ્રાપ્ય રહેતી નથી. અક્ષરમાં સર્વ વાત રહી છે. અક્ષરના સુખ આગળ અનંતકોટિ બ્રહ્માંડનું સુખ લૂખું છે. એવું અપાર સુખ અક્ષરમાં રહેલું છે, જેનું વર્ણન થઈ શકે તેમ નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":797,"k":"para","g":"“એ અક્ષરનું અનંતકોટિગણું સુખ પણ શ્રીહરિના એક અંગમાં સમાઈ જાય છે. એવું એ મૂર્તિનું સુખ અપાર છે એને કોઈક જ જાણી શકે છે.”","e":null,"s":["1/52/3-8"],"sv":["ईश्वर रहे अक्षर मांहि, अक्षर रहे सो ईश्वर मांहि ।\n\n जुदे कबु रहत नाहिं, अखंड के अखंड रहत सदा ॥\n\n माया अनंत कहावत तेहा । अक्षर आगे लेश चलत न ऐहा ॥\n\n अक्षर लग दृष्टि जेहि जावे । ताकुं अगम कोउ न रहावे ॥\n\n अप्राप्य न रहे कोउ ताई । अक्षर में बात सबहि आई ।\n\n अनंत कोटि ब्रह्मांड को सुखा । अक्षर आगे सब लगत हें लुखा ॥\n\n ऐसो सुख अक्षर में रहेउ । अनंत सुख न बनत कियेउ ।\n\n अनंत कोटि सुख अक्षर केरा । हरि के एक अंग में हें घनेरा ॥\n\n मूर्ति में ऐसो सुख हें अपारा । सो जानत कोउ जाननहारा ॥"],"mt":false,"gl":null,"a":true},{"i":798,"k":"para","g":"મુક્તમુનિએ કહ્યું, “અક્ષરબ્રહ્મ સત્યરૂપ, જ્ઞાનરૂપ ને અમાપ છે. પુરુષોત્તમનું ધામ છે. અનંત શક્તિના ધારક છે. તે પૂરણ બ્રહ્મ છે. શુદ્ધ, અખંડ ને અવિનાશી છે, તેનો પ્રકાશ અનંત છે. તે સદા એક અને અદ્વિતીય છે. જીવો, ઈશ્વરો ને માયા અક્ષરબ્રહ્મની પ્રસન્નતા ચાહે છે. અક્ષરબ્રહ્મનાં બે સ્વરૂપ છે - મૂર્ત અને અમૂર્ત. તે સર્વાધાર છે. સદા વિકાર રહિત છે. માયાના ગુણથી રહિત અલિપ્ત છે. નિત્ય અને અખંડિત સ્વરૂપ છે.”","e":null,"s":["3/2/15-17"],"sv":[],"mt":false,"gl":null,"a":true},{"i":799,"k":"para","g":"ભગવાન શ્રીહરિ અને તેમનું અક્ષરધામ - બન્ને માયા પરનાં તત્ત્વો છે, અમાયિક છે. જે અમાયિક છે તેનો નિશ્ચય અનુમાનથી ન થાય. શ્રીહરિએ કરુણા કરીને સમાધિ દ્વારા પ્રત્યક્ષ અનુભવ કરાવ્યો, પોતાનું ધામ દેખાડ્યું, પોતાના પ્રતાપે કરીને સૌને માયાના બંધનથી રહિત સ્વતંત્ર કરી દીધા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":800,"k":"verse","g":"પ્રભુ પ્રતાપહિ બલ, હરિજન કે વૃંદ વૃંદ હિ,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":801,"k":"verse","g":"ભયે સ્વચ્છંદ અચલ, જ્યૂઁ મહાભક્ત અનાદિ કે.","e":null,"s":["3/31/5-14"],"sv":[],"mt":false,"gl":null,"a":true},{"i":802,"k":"para","g":"ભાદરાથી ત્રણ હરિજન આવ્યા. વિપ્ર મૂળજી શર્મા, કણબી ડોસા ભક્ત, સુથાર વિશરામ ભક્ત - ત્રણે ભગવાનની મૂર્તિમાં લીન થયા. મૂળજી ભક્તે (ગુણાતીતાનંદ સ્વામીએ) હાલરની લકડી જેમ મૂર્તિને પકડી અંતરમાં ધારી લીધી, તે દેહ પર્યંત અંતરમાં ધારી. દેહક્રિયા બધી કરતા, પણ મૂર્તિમાં રહીને કરતા. તે અખંડ મૂર્તિમાં રહેતા. તાર તૂટવા દેતા નહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":803,"k":"verse","g":"દેહ પ્રજંત સો મૂર્તિ, રખિ નેંન કે માંહિ,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":804,"k":"verse","g":"દેહ ક્રિયા કરત સબ, મૂર્તિ મેં અખંડ રહા હિ.","e":null,"s":["5/17/39-44"],"sv":[],"mt":false,"gl":null,"a":true},{"i":805,"k":"para","g":"વિષયનું બીજ રહે ત્યાં સુધી અધર્મવંશ ન જાય. કામ, ક્રોધ, લોભ, ઈર્ષ્યા, માન, મત્સર, અસૂયા, કપટ, છલ, દંભ, હિંસા, અભક્ષ્યનું ભક્ષણ, અપેયનું પાન, કેફી દ્રવ્યનું સેવન કરવાની રુચિ - આ બધો અધર્મવંશ છે, જે સંતમાં આ અધર્મવંશ ન હોય, તે ગુણાતીત કહેવાય છે. પ્રગટ શ્રીહરિ સાથે તેનો સંબંધ છે તે ગુણાતીત સંબંધ છે. શ્રીહરિના સંબંધે કરીને હરિભક્તો પણ ગુણાતીત કહેવાય છે.","e":null,"s":["11/15/29-32"],"sv":["विषय को बीज रहत ज्यां लगहि । अधर्मवंश न जात त्यां लगहि ॥\n\n काम, क्रोध, लोभ, ईर्षा माना । मत्सर असूया, कपटछल नाना ॥\n\n डंभ, हिंसा, अभक्ष्य हि खाना । अपेय वस्तु को करना पाना ॥\n\n केफ करना रूचि बहु जेहा । ए आदिक अधर्मवंशी तेहा ॥\n\n संत में सो कबु नहि आवे । तेहि करि गुणातीत कहावे ॥\n\n प्रगट हरि की संबंध जोउ । गुणातीत कहावत सोउ ॥\n\n हरि के संबंध करि हरिजन जेते । गुणातीत सो कहे तेते ॥"],"mt":false,"gl":null,"a":true},{"i":806,"k":"para","g":"બ્રહ્માંડો અનંતકોટિ છે, જે અક્ષરના એક એક રોમમાં અણુની જેમ રહ્યાં છે, તે ધામમાં અક્ષર જેવા (અક્ષરના સાધર્મ્યને પામેલા) અનંતકોટિ મુક્તો રહ્યા છે તે દાસ થઈને ભગવાન શ્રીહરિની સેવા કરી રહ્યા છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":807,"k":"para","g":"અક્ષર જેવી મોટપ કોઈની નથી, તેની મોટપની શક્તિની તુલના થઈ શકે નહિ. બદરિકાશ્રમ અને શ્વેતદ્વીપના મુક્તો અક્ષરનું સાધર્મ્ય પામવા કઠોર તપ કરે છે. શુક, સનકાદિક, શિવજી ને નારદ જેવા પણ આજ દિન સુધી તપ કરે છે, છતાં અક્ષર જેવી મોટપ તેમને મળી નથી.","e":null,"s":["12/75/32-34"],"sv":[],"mt":false,"gl":null,"a":true},{"i":808,"k":"para","g":"શ્રીહરિએ સંતોની પંક્તિમાં જલેબી અને મોતીચૂર પીરસ્યાં. જેમને લક્ષાવધિ મનુષ્ય ભગવાન કરી માને છે. તે શ્રીહરિને પંક્તિમાં પીરસવું કઠણ વાત લાગતી નથી. અતિશય મોટા અક્ષરબ્રહ્મ છે. અક્ષરના એક એક રોમમાં અનંતકોટિ બ્રહ્માંડ અણુસમ દિસે છે. અષ્ટાવરણથી યુક્ત આ બ્રહ્માંડો તેવડાં ને તેવડાં જ રહે છે, નાનાં થઈ જતાં નથી, પરંતુ અક્ષરની એવી અતિશય મોટપ છે કે, બ્રહ્માંડો તેની પાસે અતિ સૂક્ષ્મ જણાય છે. એવા એ મોટા છે તેનાથી પર શ્રીહરિ છે.","e":null,"s":["26/47/14-16"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":11,"gu":"ખપ - સહનશીલતા","en":"Khap, Sahanshīltā — Spiritual Eagerness and Forbearance","url":"https://www.anirdesh.com/pbp/index.php?page=chp_11","b":[{"i":809,"k":"para","g":"સરધારમાં શ્રીહરિએ વાત કરતાં કહ્યું, “ધ્યાન, ભજન, યોગાભ્યાસ, જપ, તપ, ત્યાગ, વૈરાગ્ય વગેરેનું ફળ એટલું જ છે, જે પોતાને ભગવાનના ભક્તના દાસનો દાસ માને. અમે એને જ શ્રેષ્ઠ માનીએ છીએ. હરિભક્ત દોષ વિના અપમાન કરે તેને સહન કરે, તેના ઉપર હું પ્રસન્ન થાઉં છું.”","e":"At Sardhar, while talking, Shriharí said, “The fruit of meditation, worship, the practice of yoga, japa, tapa, renunciation, vairagya and the rest is only this much — that one comes to regard oneself as the servant of the servants of the devotees of Bhagwan. That alone we consider the highest. When a haribhakta is dishonoured without fault and bears it, I am pleased with him.”","s":["3/56/37-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":810,"k":"para","g":"કુંડળમાં શ્રીહરિ કહે, “જેમાં જેટલી સહનશક્તિ વધુ તેટલું તેનામાં સામર્થ્ય અધિક માનવું. સહનશક્તિ જેટલી ઓછી તેટલો તે ભક્તપણામાં ન્યૂન છે. સહન કરે તેનો પાયો અચળ છે. સંતોએ શુકજી ને જડભરતની જેમ વર્તવું.","e":"At Kundal, Shriharí said, “However much capacity to bear a person has, that much strength should be understood to be in him. However little his capacity to bear, that much is he deficient in his devotion. The foundation of one who bears is unshakeable. Sadhus should conduct themselves as Shukji and Jadbharat did.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":811,"k":"para","g":"“ભક્તોએ જયદેવ, હરિશ્ચંદ્ર, મયૂરધ્વજ જેવા સહનશીલ ભક્તોના માર્ગે ચાલવું, જે આપત્કાળમાં પણ વિચલિત થયા નહોતા. પાકો હરિજન ત્યારે કહેવાય જ્યારે તેનામાં સહનશક્તિ આવે. અમારે તમને પાકા કરવા છે, જેથી જગત તમારું પ્રમાણ લે, તમારે પગલે પગલે ચાલે.”","e":"“Devotees should walk the path of forbearing devotees such as Jaydev, Harishchandra and Mayurdhwaj, who were not shaken even in times of calamity. A haribhakta is called ripe only when the capacity to bear comes into him. We want to make you ripe, so that the world takes you as its measure and walks in your footsteps.”","s":["4/35/34-37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":812,"k":"para","g":"સારંગપુરમાં બોટાદના ભગા શેઠને શ્રીહરિએ પ્રસન્ન થકા કરુણારસ લાવીને વાત કરતાં કહ્યું, “સુખમાં તો સૌ સત્સંગ કરે, પણ વિપત્તિ આવે ત્યારે કસોટીમાં પાર ઊતરે તેના પર અમે રાજી થઈએ છીએ. વિપત્તિમાં ડગવું નહિ એ અગ્નિ કરતાં પણ મોટી કસોટી છે. આત્મવેત્તા જ્ઞાની ભક્ત હોય તે જ કસોટીમાં પાર ઊતરે, બીજાથી ન ઊતરી શકાય, એવો જ્ઞાની તો જેમ દુઃખ પડે તેમ તેમ સુખમાં રહે. એ તો એમ સમજે કે અંતર્યામીને કશું અજાણ નથી. વળી, આત્માને ક્યાં દુઃખ છે? દુઃખ તો આ દેહને છે. દેહને ક્યારેય સુખ થવાનું નથી, એ સિદ્ધાંત એણે દૃઢ કર્યો છે.","e":"At Sarangpur, pleased and moved by compassion, Shriharí talked with Bhaga Sheth of Botad and said, “In happiness everyone does satsang; but we are pleased with the one who comes through the test when adversity arrives. Not to waver in adversity is a greater test than fire. Only a gnani bhakta who knows the atma comes through that test — no one else can. Such a gnani remains in happiness the more misery falls upon him. He understands it thus: nothing is unknown to the Antaryami. And besides, where is there misery for the atma? Misery belongs to this body. He has made firm this principle: that there is never going to be happiness for the body.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":813,"k":"para","g":"“વળી, એને નિત્ય અંતર્દૃષ્ટિ રહે છે - ચોરાશી લાખ યોનિના દેહ સઘળા દુઃખમય છે. તેમાં કોણ રાજા ને કોણ રંક? કોણ દેવ ને કોણ દૈત્ય? પ્રકૃતિપુરુષ સુધીના દેહમાત્રને તે દુઃખમય સમજે છે. જીવ-નગરમાં યમનો પ્રવેશ નથી, ત્યાં તો હરિકૃષ્ણ પ્રગટ બિરાજે છે. આવો અવસર અને આ ભગવાન ક્યારેય આવ્યા નથી, એ સત્ય કરીને માને તે બુદ્ધિમાન છે.”","e":"“Furthermore, his inward vision remains constant — that the bodies of all eight million four hundred thousand species are full of misery. In them, who is a king and who a pauper? Who a god and who a demon? He understands every body, up to Prakruti-Purush, to be full of misery. Yama has no entry into the city of the jiva; there Harikrishna dwells manifest. Such an occasion, and such a Bhagwan, have never come before — he who holds this to be true is the intelligent one.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":814,"k":"verse","g":"‘એસો સમો ન આયે કબુ, એસે ન આયે ભગવાન;","e":"‘Eso samo na āye kabu, ese na āye Bhagvān;","s":[],"sv":[],"mt":false,"gl":"[Such a time has never come before, nor has such a Bhagwan ever come;]","a":false},{"i":815,"k":"verse","g":"સો સત કરી માનિયો, તબ જાનહુ બુદ્ધિમાન.’","e":"So sat kari māniyo, tab jānahu buddhimān.’","s":["4/43/35-52"],"sv":[],"mt":false,"gl":"[…hold this to be true, and then know a person to be wise.]","a":false},{"i":816,"k":"para","g":"અમદાવાદમાં શ્રીહરિ કહે, “સહન કરવું એ અમારો મહામોટો પરમ ધર્મ છે. સહન કરવું તેને અમે સિદ્ધિ ગણીએ છીએ. અમે ક્ષમારૂપી હથિયાર ધારણ કર્યું છે, તેનાથી અધર્મનો નાશ કરીશું.”","e":"At Amdavad, Shriharí said, “To bear is our greatest and highest dharma. We count bearing as an attainment. We have taken up the weapon of forgiveness; with it we shall destroy adharma.”","s":["4/102/43-44"],"sv":[],"mt":false,"gl":null,"a":false},{"i":817,"k":"para","g":"જૂનાગઢમાં દેવદિવાળીનો ઉત્સવ કરી શ્રીહરિએ સંતનાં મંડળ વહેંચ્યાં અને વાત કરતાં કહ્યું, “હે સંતો! અજ્ઞાની જન ઉપાધિ કરે તે બધી તમારે સહન કરવી. સમય એવો ક્રૂર આવ્યો છે તેમાં તમારે ધીરજ ધરી રાખવી પડશે. તમે સહનશક્તિ કેળવો એ અમારી મરજી છે. તમારા પર અમારે અપાર હેત છે. તમે બધાએ જગતના ઉપકાર માટે દેહ ધર્યા છે. માટે ઉપાધિ સહન કરીને વિચરવું, તેમાં પીછેહઠ ન કરવી. સહન કરીને ઉપદેશ કરશો તો તમારો જશ અતિશય વધશે.","e":"At Junagadh, having celebrated the festival of Dev Diwali, Shriharí distributed the groups of sadhus and, while talking, said, “O sadhus! Whatever trouble ignorant people cause, all of it you must bear. The times that have come are cruel, and in them you will have to hold patience. It is our wish that you cultivate the capacity to bear. We have boundless affection for you. All of you have taken bodies for the good of the world. So travel about bearing trouble, and do not retreat from it. If you preach while bearing, your renown will increase exceedingly.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":818,"k":"para","g":"“કોઈ દ્વેષ કરે, ગાળ દે, બાંધી મૂકે કે માર મારે પણ મનમાં મગન રહેશો તો હું તમારી સાથે છું એમ નિશ્ચય જાણજો. આપણે અધર્મનું ઉચ્છેદન કરી ધર્મનું સ્થાપન કરવું છે તો દુર્જનનું સહન કરજો. ક્ષમા કરવી એ ખૂણાનો ખેલ નથી, રણની બાજી છે.”","e":"“Should anyone show malice, abuse you, tie you up or beat you — if you remain joyful within, know for certain that I am with you. We wish to uproot adharma and establish dharma; so bear with the wicked. To forgive is no game played in a corner; it is a gambit on the battlefield.”","s":["6/80/34-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":819,"k":"para","g":"ગઢપુરમાં જીવેન્દ્ર નૃપના ભવનમાં શ્રીહરિ કહે, “બલિરાજાનું રાજ ભગવાને છીનવી લીધું, પણ તેને આધીન થઈ ગયા. સુવર્ણને ભઠ્ઠીમાં તપાવે પછી જ તેનો રંગ આવે છે. ભક્તની કસોટી પણ ભગવાન કરે છે ત્યારે તેની પ્રીત પરખાય છે. દુનિયાદારીનું અભિમાન હોય તો તે તાપ ખમી શકતો નથી, ને તે વિના શાંતિ પણ પામતો નથી.","e":"At Gadhpur, in the palace of King Jivendra, Shriharí said, “Bhagwan seized King Bali’s kingdom from him, yet became subject to him. Only after gold is heated in the furnace does its colour come out. So too, when Bhagwan tests a devotee, then his love is assayed. If a person has the pride of worldly affairs, he cannot endure that heat — and without enduring it he does not attain peace either.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":820,"k":"para","g":"“ભગવાન અને ભગવાનના સંતની સેવામાં પોતાનું મોટું ભાગ્ય માને તેટલું તેને ફળ મળે છે, સુખ થાય છે. હરિજનને સંસારનું દુઃખ એ દુઃખ જ ન હોય, તેને તો સત્સંગ ન થાય તેટલું દુઃખ મનાય છે.”","e":"“However great a fortune one considers it to serve Bhagwan and the Sant of Bhagwan, that much fruit one receives, and that much happiness comes. For a harijan the misery of worldly life is no misery at all; the only thing he counts as misery is not attaining satsang.”","s":["6/102/15-20"],"sv":[],"mt":false,"gl":null,"a":false},{"i":821,"k":"para","g":"ઝીંઝાવદરમાં શ્રીહરિએ અલર્ક રાજાને કહ્યું, “જેને મોક્ષનો ખપ જાગે તે તન-ધનને ધૂડ સમાન જાણે છે. તન-ધન બહુ વખત મળ્યાં છે, પણ મોક્ષ મળવો દુર્લભ છે. લોકમાં પણ સત રાખવા કાજે શરીરને અગ્નિમાં બાળી દે છે, તેમ અતિશય ખપ જેને હોય તેનાથી શું ન થાય! ખપ વિના કોટિ ઉપાયે મોક્ષ થાય નહિ. હરિભક્ત થઈને હરિભક્તનો દોષ બોલે તે સમાન કોઈ પાપી નથી. જેને પોતાના દોષ દેખાય એ સારામાં સારો હરિભક્ત જાણવો.”","e":"At Zinzavadar, Shriharí said to King Alark, “One in whom khap for moksha has awakened knows body and wealth to be no better than dust. Body and wealth have been obtained many times over, but moksha is difficult to obtain. Even in the world people burn their bodies in fire to keep their word; so what could not be done by one who has intense khap! Without khap, moksha does not come by ten million means. There is no sinner equal to one who, having become a haribhakta, speaks of another haribhakta’s faults. Know the one who sees his own faults to be the very best of haribhaktas.”","s":["9/41(40)/25-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":822,"k":"para","g":"બોટાદમાં હમીર ખાચરના ભવનમાં શ્રીહરિએ વાત કરતાં કહ્યું, “જેના પર જેને ઇશક હોય તે તેના નિમિત્તે દુઃખ સામું જોતો જ નથી, અને જુએ તો ઇશક ઓછો કહેવાય. ચોરી કરવા પર ઇશક હોય તે મરવાનો ડર રાખતો નથી. તેમ પરનારીના ઇશકમાં પણ છે. સતીને પતિનો ઇશક છે તો અગ્નિ દેખીને ડરતી નથી. ઇશકવાળાને દુઃખ આવે તેમ તેમ તે શોભા માને છે. માયિક વસ્તુ પર ઇશક છે તેવો જ ભગવાનમાં માને તો તેને ભગવાન પાસે જ છે.”","e":"At Botad, in the palace of Hamir Khachar, while talking, Shriharí said, “Whoever loves a thing passionately does not so much as look at the misery he suffers on its account — and if he does look, his passion is said to be less. One who is passionate about thieving keeps no fear of dying. It is the same in the passion for another’s wife. A sati is passionate for her husband, and so does not fear at the sight of fire. To one with such passion, the more misery comes the more he counts it an adornment. If a person held for Bhagwan the same passion he holds for mayik things, then Bhagwan would be right beside him.”","s":["9/58(57)/13-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":823,"k":"para","g":"મેઘપુરમાં જન્માષ્ટમીના સમૈયા ઉપર આવેલા ભક્તોને શ્રીહરિએ શીખ દેતાં કહ્યું, “કોઈક મારે અથવા ગાળ દે તો સહન કરવું. હોળી ઉપર ને વસંતોત્સવમાં લોકો જેમ રાજીખુશીથી ગાળો અને મારામારી સહન કરે છે તેમ સંત-હરિભક્તે નિર્વૈર રહેવું. વિવાહમાં પુત્ર નિમિત્તે બાપ, ગીત ગાનારીની ગાળો સાંભળીને રાજી થાય છે, પણ દ્વેષ રાખતો નથી, તે અજ્ઞાનથી સહન કરે છે તેમ હરિભક્તે જ્ઞાને કરીને વર્તવું. એ અમારી આજ્ઞા છે. તેને પાળશો તો કોઈ દિવસ દુઃખી નહિ થાઓ.","e":"At Meghpur, giving instruction to the devotees who had come for the Janmashtami festival, Shriharí said, “If someone strikes you or abuses you, bear it. Just as at Holi and at the spring festival people willingly and gladly bear abuse and blows, so should the sadhus and haribhaktas remain free of enmity. At a wedding a father hears the abuse of the women singers on his son’s account and is pleased, holding no malice — he bears it out of ignorance. In the same way a haribhakta should conduct himself out of gnan. That is our command. If you observe it, you will never be miserable.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":824,"k":"para","g":"“એકેકથી અધિક થઈ ગયેલા હરિભક્તોની રીત વિચારવી. મોટા લોકો તો ક્યારેય મુખથી ગોળ બોલે જ નહિ. સૌથી મોટી પૃથ્વી છે તે અપાર પાપ કરનારાને પણ ક્ષમા કરે છે, અને જીવમાત્રને અન્ન, વાહન, ભવન આપે છે. વળી, ભગવાનની આજ્ઞામાં વર્તે છે. તે રીતે જળ, તેજ, વાયુ ને આકાશ પણ સહન કરે છે. હરિભક્તને તો તેથી અધિક વર્તવું, કારણ કે પંચભૂત મોક્ષ કરે તેવાં નથી, જ્યારે હરિભક્તના વચનને કોઈ મુમુક્ષુ ગ્રહણ કરે તો તેનો મોક્ષ થાય છે. માટે જેટલી મોટાઈ છે તેટલી ક્ષમા જોઈએ. અને નિર્દંભ હોય તે જ મોટાઈને પામે છે.”","e":"“One should consider the manner of the haribhaktas who have surpassed one another. Great people never speak a harsh word from their mouths. Greatest of all is the earth, which forgives even those who commit boundless sin, and gives food, conveyance and dwelling to every living being — and moreover, it conducts itself according to the command of Bhagwan. In the same way water, fire, wind and space also bear. A haribhakta should conduct himself even more so than these, because the five elements cannot grant moksha, whereas if some mumukshu takes up the word of a haribhakta, his moksha is accomplished. So however much greatness there is, that much forgiveness is required. And only one who is free of pretence attains greatness.”","s":["10/23/15-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":825,"k":"para","g":"ધોરાજીમાં શ્રીહરિ સંતોને સભામાં બોલાવી કહેવા લાગ્યા કે, “વિમુખજનો ફાવે તેમ બોલે તોપણ આનંદ પામી સહન કરવું. જેને જેટલી સહનશક્તિ, તેને તેટલી અધિક મોટપ છે. બધી મોટપમાં સહન કરવું તે ઉત્તમ મોટપ છે. સાધુએ શુક-સનકાદિકની રીતિ અનુસાર વર્તવું.”","e":"At Dhoraji, Shriharí called the sadhus into the assembly and said, “Even though those turned away from God may say whatever they please, one should be glad and bear it. However much capacity to bear a person has, that much greater is his greatness. Among all forms of greatness, to bear is the highest greatness. A sadhu should conduct himself according to the manner of Shukji and Sanakadik.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":826,"k":"verse","g":"‘મોટપ મેં મોટપ અધિક યહ, સહનશક્તિ જેતિ;","e":"‘Motap men motap adhik yah, sahanshakti jeti;","s":[],"sv":[],"mt":false,"gl":"[Among all greatness this greatness is the highest — as much capacity to bear as one has;]","a":false},{"i":827,"k":"verse","g":"શુક સનકાદિક રીતિ કું, સહન કરના તેતિ.’","e":"Shuk Sanakādik rīti kun, sahan karnā teti.’","s":["11/36/1-2"],"sv":[],"mt":false,"gl":"[…to bear in the manner of Shukji and Sanakadik, that much.]","a":false},{"i":828,"k":"para","g":"જૂનાગઢમાં શ્રીહરિએ વર્ણીને વાત કરી, “વિવેકી હોય તે સારને ગ્રહણ કરે અને ખપ વિનાની વાતને જતી કરે. ખપવાળો કોઈની સાથે વેર કરે નહિ અને સરળ વર્તે. જેથી વૈરી હોય તે પણ મિત્ર થઈ જાય. વર્તન ઉપરથી બુદ્ધિ દેખાઈ આવે છે.”","e":"At Junagadh, Shriharí talked with the varni, saying, “One who has vivek grasps the essence and lets go of matters he has no khap for. One with khap creates enmity with no one, and conducts himself with simplicity — so that even one who was hostile becomes a friend. A person’s intelligence shows itself in his conduct.”","s":["11/61(51-b)/19-22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":829,"k":"para","g":"ગઢપુરની સભામાં શ્રીહરિ કહે, “ભજન-સ્મરણ કરવું, બીજાને સત્સંગ કરાવવો, સત્સંગ માટે ખર્ચ કરવો, કોઈ હરિજન કટુ વચન કહે તો તેને હિતકારી માની સહન કરવું એ મોટા હરિભક્તનું લક્ષણ છે.","e":"In the assembly at Gadhpur, Shriharí said, “To do worship and remembrance, to bring others into satsang, to spend for the sake of satsang, and — should a harijan speak a bitter word — to regard it as being for one’s good and bear it: these are the marks of a great haribhakta.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":830,"k":"para","g":"“હરિભક્તો-સંતોનાં કડવાં વચન અને અપમાન સહન કરે તે મોટો હરિભક્ત છે. સત્સંગની સમજણ જેટલી કંઈ છે તે સઘળી સહનશીલતામાં રહેલી છે. તે જેમ જેમ સહન કરે તેમ મોટપ વધતી જાય છે.”","e":"“He who bears the bitter words and the dishonour of haribhaktas and sadhus is a great haribhakta. Whatever understanding of satsang there is, all of it resides in forbearance. The more a person bears, the more his greatness goes on increasing.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":831,"k":"verse","g":"‘સત્સંગ કી સમઝ જિતની, સહનતા તિતની તાય;","e":"‘Satsang kī samajh jitnī, sahantā titnī tāy;","s":[],"sv":[],"mt":false,"gl":"[As much understanding of satsang as one has, that much forbearance comes to him;]","a":false},{"i":832,"k":"verse","g":"સહનતા બઢત તિતિની, દિન દિન બઢત સો જાય.’","e":"Sahantā badhat titinī, din din badhat so jāy.’","s":["11/84(74)/11-14"],"sv":[],"mt":false,"gl":"[…and as that forbearance increases, so it goes on increasing day by day.]","a":false},{"i":833,"k":"para","g":"હીરજી સુથાર વગેરે હરિજનો પ્રત્યે શ્રીહરિએ કહ્યું, “કાચા-પાકા હરિભક્ત કષ્ટ આવે ત્યારે દેખાય છે. કષ્ટમાં જે ધીરજ રાખે તેની યુગોયુગ કીર્તિ ગવાય છે. સત્સંગ નિમિત્તે કષ્ટ સહે તેટલું અધિક સુખ મળે છે... ભગવાન જેના પતિ છે એવા સીતાજીને પણ અપાર કષ્ટ સહન કરવાં પડ્યાં છે. કષ્ટ આવે ત્યારે સહન કરવાં જ જોઈએ. સહન કર્યા વિના અતિ દુર્લભ મોક્ષ કેવી રીતે મળે?”","e":"To Hirji Suthar and the other harijans, Shriharí said, “Whether haribhaktas are unripe or ripe becomes visible when hardship comes. The glory of one who keeps patience in hardship is sung age after age. The more hardship one bears for the sake of satsang, the greater the happiness one receives… Even Sitaji, whose husband was Bhagwan Himself, had to bear boundless hardship. When hardship comes it must simply be borne. Without bearing it, how is the exceedingly rare moksha to be attained?”","s":["12/35/7-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":834,"k":"para","g":"કારિયાણીમાં શ્રીહરિએ કહ્યું, “જેને સત્સંગનો ખપ છે તે હરિભક્ત પોતાના કરતાં સંતને અધિક કરીને માને છે, ને તેનો સંગ રાખે છે. જે અધિક નથી માનતા તે પોતાનું જ મૂળ કાપે છે.”","e":"At Kariyani, Shriharí said, “The haribhakta who has khap for satsang regards the Sant as greater than himself, and keeps his company. Those who do not regard him as greater cut away their own root.”","s":["12/43/18-19"],"sv":[],"mt":false,"gl":null,"a":false},{"i":835,"k":"para","g":"ગઢપુરમાં શ્રીહરિ સંતોને કહે, “ખપ વિનાના હોય તે જતન કરવા છતાં ચાલ્યા જાય છે. અને ખપવાળા અપાર દુઃખ પડે તોપણ ટકે છે. અમે હવે અધિક સુખ દેવાનો સંકલ્પ કર્યો છે તેથી ખપ હોય તેટલા સંતો રહે.”","e":"At Gadhpur, Shriharí said to the sadhus, “Those without khap go away despite every effort to keep them. And those with khap remain even though boundless misery falls upon them. We have now resolved to give greater happiness, and so as many sadhus as have khap will stay.”","s":["15/59/8-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":836,"k":"para","g":"શ્રીહરિએ પત્રમાં એક વાત લખાવી કે: “સત્સંગ અને ભગવાન તથા મોક્ષ માટે જેટલો ખપ હોય તેટલું જગતમાં અપમાન સહન કરી શકાય છે. અપમાન અને કષ્ટને જે ભગવાન માટે સહન કરે છે તેના પર ભગવાન પ્રસન્ન થાય છે.”","e":"Shriharí had a matter written in a letter: “However much khap one has for satsang, for Bhagwan and for moksha, that much dishonour in the world can be borne. Bhagwan is pleased with one who bears dishonour and hardship for the sake of Bhagwan.”","s":["15/79/27-30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":837,"k":"para","g":"શ્રીહરિએ હરિજનો પ્રત્યે પત્રમાં લખાવ્યું કે: “મિથ્યા સુખને માટે લોકો અગણિત દુઃખ સહન કરે છે. તેટલું દુઃખ ભગવાનનાં સાચાં સુખ માટે સહન કરતા નથી. સહન કર્યા વિના સુખ મળતું નથી. અલ્પ વાત પણ ઉદ્યમ કર્યા વિના સિદ્ધ થતી નથી. જો મોક્ષનું ફળ લેવું હોય, તો પ્રથમ સુખનો ત્યાગ કરવો પડે.”","e":"Shriharí had this written to the harijans in a letter: “For the sake of false happiness people bear uncountable misery. They do not bear that much misery for the true happiness of Bhagwan. Without bearing, happiness is not obtained. Even a small matter is not accomplished without effort. If one wishes to take the fruit of moksha, then one must first renounce happiness.”","s":["15/80/1-4"],"sv":[],"mt":false,"gl":null,"a":false},{"i":838,"k":"para","g":"શ્રીહરિએ પત્રમાં કહ્યું, “વિષરૂપ વચન જે સહન કરે તે પણ મૂર્તિમાન અમૃત છે. સમર્થ થઈને સહન કરવું તે બહુ જ કઠણ છે. તેવા પુરુષો જગતને ધારી રહ્યા છે.”","e":"Shriharí said in a letter, “One who bears words that are like poison is himself nectar embodied. To be capable and yet to bear is very difficult indeed. It is such men who are upholding the world.”","s":["15/88/27-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":839,"k":"para","g":"શ્રીહરિએ વડતાલમાં આંબલા નીચે બિરાજમાન થઈને હરિજનોને વાત કરતાં કહ્યું, “નિયમ ઓળંગીને ચાલવું તે દુઃખનો માર્ગ છે. જેનામાં જેટલી ક્ષમાવૃત્તિ છે તેટલા તે સુખી હોય છે. ક્ષમામાં વિવેકની જરૂર હોય છે. ક્ષમા અને વિવેક રાખીને વર્તે તેને ક્યારેય દુઃખ આવે નહિ. એવા ગુણથી જ અમારી કીર્તિ પ્રસરે છે. એવાં ગુણરૂપી વસ્ત્ર-આભૂષણ અમને પ્રિય છે. કીર્તિનાં મોટાં મંદિર રચ્યાં તેને દેખીને અમને શાંતિ છે. કીર્તિરૂપ ગુણ ન હોય તે ધામ અને મંદિર નામ માત્રનાં જાણવાં. તેમાં ક્યારેય ભગવાન રહે નહિ.”","e":"At Vartal, seated beneath the tamarind tree, Shriharí talked with the harijans and said, “To go about overstepping one’s niyams is the road to misery. However much disposition to forgive a person has, that much happiness he has. Forgiveness requires vivek. One who conducts himself keeping both forgiveness and vivek will never meet with misery. It is by such virtues alone that our renown spreads. Such virtues are the garments and ornaments dear to us. Seeing the great mandirs of renown that have been built gives us peace — but know that any abode or mandir without the virtue that constitutes renown is one in name only. Bhagwan never dwells in it.”","s":["17/94/19-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":840,"k":"para","g":"શ્રીહરિ સંતોને લોયામાં વાત કરવા લાગ્યા, “સંપનું કારણ ગરજ છે. ગરજ વિના સંપ રહે નહિ. ગરજની દિશા ભૂલે તો મિત્ર સાથે વેર કરે, તેમ મોક્ષનો ખપ જ્યાં સુધી હોય ત્યાં સુધી સંત-હરિભક્તને દિવ્ય દેખે ને ખપ ન રહે તો દિવ્યપણું મટી જાય છે. ઉપરથી નમસ્કારનો વહેવાર રાખે પણ અંતરમાં ભાવ રહે નહિ, પણ એ સાચા હરિભક્તની રીત નથી.”","e":"At Loya, Shriharí began to talk with the sadhus: “The cause of harmony is need. Without need, harmony does not remain. If a person mistakes the direction of his need, he creates enmity even with a friend. In the same way, so long as there is khap for moksha, one sees the sadhus and haribhaktas as divine; and if the khap does not remain, that divineness disappears. Outwardly he keeps up the practice of bowing, but inwardly the feeling does not remain — and that is not the way of a true haribhakta.”","s":["24/56/22-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":841,"k":"para","g":"સુરતના હરિજનોને શ્રીહરિ કહે, “સત્સંગ ઉપર ભાવ થાય તેને એટલો ખપ ગણાય. ખપ હોય તેને સંત-હરિભક્તોનાં વચન અમૃત સમાન લાગે. અને જેમ સાંભળે તેમ દિવસે દિવસે ભાવ વધે, ને ભાવ વધે તેથી સત્સંગ વધ્યો કહેવાય અને તેનાં અંતરમાં આનંદના સિંધુ ઊછળે. સત્સંગ સમાન બીજું કોઈ સુખ નથી. અનંત બ્રહ્માંડનાં સુખ કાળના કોળિયા જેવાં દેખે. આવું મરણપર્યંત દેખતો રહે તેનું નામ સમાધિ કહેવાય છે. સત્સંગ અને ભગવાનના સુખને કાળ સ્પર્શી શકતો નથી.”","e":"Shriharí said to the harijans of Surat, “However much love arises for satsang, that much khap is counted. To one who has khap, the words of the sadhus and haribhaktas seem like nectar. And the more he listens, the more his love increases day by day; and as his love increases, his satsang is said to have increased, and oceans of joy surge within him. There is no other happiness equal to satsang. He sees the happiness of infinite brahmands as a mere mouthful for Kal. To go on seeing thus until death — that is what is called samadhi. Kal cannot touch the happiness of satsang and of Bhagwan.”","s":["27/86/15-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":842,"k":"para","g":"સુરતમાં શ્રીહરિએ નાના શેઠને વાત કરતાં કહ્યું, “ખપ વિનાનાને સદાય વિઘ્ન રહે છે અને તેનો સત્સંગ રહેતો નથી. કોટિ વખત મસ્તક કપાય પણ સત્સંગનો ત્યાગ ન કરવો. સત્સંગ નિમિત્તે ચહાય તેટલાં દુઃખ આવે તોપણ તે દુઃખોથી સત્સંગ દુર્લભ છે. પ્રહ્‌લાદ, પ્રિયવ્રત, જનક, ઉદ્ધવ, ગોપ-ગોપીની સમજણ રાખવી. ભગવાને મનફાવ્યાં ચરિત્રો કર્યાં તોપણ તેને મોક્ષદાયી માન્યાં, લેશ પણ સંશય ન કર્યો ત્યારે ભગવાન તેને વરણીય થયા.”","e":"At Surat, while talking with Nana Sheth, Shriharí said, “For one without khap, obstacles remain forever, and his satsang does not last. Though the head be severed ten million times, one should not abandon satsang. However much misery may come for the sake of satsang, satsang is rarer than those miseries. One should keep the understanding of Prahlad, Priyavrat, Janak, Uddhav, and the gopas and gopis. Though Bhagwan performed charitras as He pleased, they held them to be bestowers of moksha and did not doubt in the least — and then Bhagwan became worthy of their choosing.”","s":["27/86/32-36"],"sv":[],"mt":false,"gl":null,"a":false}]},{"n":12,"gu":"ભક્ત","en":"The Bhakta — The Devotee","url":"https://www.anirdesh.com/pbp/index.php?page=chp_12","b":[{"i":843,"k":"para","g":"શ્રીહરિએ માતાને ઉપદેશ આપતાં કહ્યું, “ભક્ત બે પ્રકારના છે: સકામ અને નિષ્કામ. લૌકિક પદાર્થની કામનાવાળા સકામ છે, જે ગોલોકાદિ ધામમાં મનવાંછિત ભોગ ભોગવે છે. બીજા નિષ્કામ ભક્ત તો ચાર પ્રકારની મુક્તિને પણ ઇચ્છતા નથી, આણિમા, લઘિમા જેવી અષ્ટ સિદ્ધિઓને પણ ઇચ્છતા નથી. ભક્તવત્સલ ભગવાન નિષ્કામ ભક્ત પર પ્રસન્ન થાય છે. આવા ભક્ત ઉત્તમ છે ને પૂર્ણકામ છે; ભગવાનના હૃદય સમાન છે. તેમનો પ્રેમ દિન દિન પ્રત્યે વૃદ્ધિ પામે છે. ગંગાના પ્રવાહની પેઠે કોઈ અંતરાયનો રોક્યો રોકાતો નથી. દેશકાળાદિ વિઘ્નોથી તેનો પ્રેમ ઘટતો નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":844,"k":"para","g":"“નિષ્કામ ભક્તની ઇન્દ્રિયો અને અંતઃકરણની વૃત્તિઓ સહજે ભગવાનમાં જ વર્તે છે. બીજે તેમને આસક્તિ થતી નથી. જગતનાં અતિ રમણીય પદાર્થોને તે અતિ દુઃખદાયી સમજે છે. ભગવાનના સંબંધ વિનાના પુષ્પહાર કે આભૂષણ તેમને સર્પ જેવા તેમજ દૂષણરૂપ લાગે છે, વળી, ભગવાનના સંબંધથી રહિત ભોગમાત્ર તેમને દુઃખરૂપ થઈ પડે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":845,"k":"para","g":"“અંદર ને બહાર એક ભગવાનની જ સ્મૃતિ તેને રહે છે. તે ક્યારેક નિર્લજ્જપણે કીર્તન ગાય છે. ઊંચે સ્વરે ભગવાનના નામનું ઉચ્ચારણ કરે છે. ભગવાનના મહિમાનું ગાન ને નવધા ભક્તિ વિના તે રહી શકતો નથી. એવા ભક્ત પોતાના ચરણની રજથી જગતને પવિત્ર કરે છે. દેહ મૂકીને આવા ભક્ત અક્ષરધામમાં ભગવાનની સેવાનો આનંદ લે છે. ભગવાન તેને અપાર દિવ્ય સુખ આપે છે.”","e":null,"s":["1/68, 69"],"sv":[],"mt":false,"gl":null,"a":false},{"i":846,"k":"para","g":"ગોંડલના રાજા હઠીસિંહને શ્રીહરિએ ભક્તનાં લક્ષણ જણાવતાં કહ્યું, “ઉત્તમ ભક્તમાં ચિંતામણિ અને કલ્પવૃક્ષ જેવા અનેક ગુણો સદાય રહેલા છે. કાચનું જેવું પાત્ર તેવો ગુણ તેમાં છવાય છે, તેમ મારા અવતારોના ગુણ છે. તે જેવું પાત્ર તેવો ગુણ તેમાં દેખાયો પરંતુ મોક્ષરૂપી ગુણ કેવળ મારામાં છે, જે ગુણ ક્યારેય ખંડિત થતો નથી, અખંડપણે રહે છે. બીજા રહેલા ગુણોમાં નિર્દોષગુણ અખંડ રહે છે. આ ગુણ એક જ છે, એનાં નામ અનંત થયાં છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":847,"k":"para","g":"“ભક્તોના મનોરથ પૂર્ણ કરવા અમારો સહજ સ્વભાવ છે. શાંત સ્વરૂપ, સદા સુખદાયીપણું, પુરુષોત્તમનારાયણ એવું નામ વગેરે મારો ઉત્તમ ભક્ત હોય, તે જાણે છે. એ ભક્ત મને સર્વોત્તમ(સર્વોપરિ) જાણે છે. મારાં જેટલાં ચરિત્રો છે, તેને દિવ્ય ને મોક્ષદાયી માને છે. ઉત્તમ ભક્ત મારા ચરિત્રમાં ક્યારેય પ્રાકૃતબુદ્ધિ લાવતો નથી. દિવ્ય અને અલૌકિક કરીને તેનું ગાન કરે છે. મારી મનુષ્ય જેવી મૂર્તિમાં પણ દિવ્યભાવ રાખે છે. મારી મૂર્તિનો જેને જેને સંબંધ થાય છે તેને પણ તે દિવ્ય ને અલૌકિક માને છે. એવો મહા ઉત્તમ ભક્ત જ અક્ષરધામની પરમગતિ પ્રાપ્ત કરે છે. એવો ઉત્તમ ભક્ત મારા વચનને સર્વોત્તમ ગણી તેનો ક્યારેય લોપ કરતો નથી. મને અંતર્યામી જાણે છે અને છળકપટનો ત્યાગ કરીને મને ભજે છે. મને ભજતો હોય અને છળકપટ રાખતો હોય, તેની સાથે મારે પ્રીત થતી નથી.”","e":null,"s":["3/49/17-26"],"sv":["चिंतामनि कल्पवृक्ष हि जोई । सबको सार इच्छते हें सोई ॥\n\n जेसो भाव जो पात्र के मांई । तेंसे फल तेहि देवत हें ताई ॥\n\n चिंतामनि में गुन सार सदाई । असार गुनसें में नांहि कराई ॥\n\n सदाय गुन यामें रहत एका । विविध पात्र में शुन हें अनेका ॥\n\n स्वच्छ एक गुन रहे काचमें छाई । जेसो पात्र तिहां सो देखाई ॥\n\n मेरे अवतार के गुन हें ऐसा । जेसो पात्र तेहि फल दिये तेसा ॥\n\n मोक्ष गुन हें मोये अखंडा । तेहि गुन कबहु न होवे खंडा ॥\n\n जेसो पात्र त्यां तेसो फल दाया । निर्दोष गुन अखंड रहाया ॥\n\n एक गुन के भये नाम अनंता । कहत कहत न आवत अंता ॥\n\n पूर्ण मनोरथ सहज स्वभावु । शांत स्वरूप सदा सुखदावु ॥\n\n नरोत्तम पुरुषोत्तम नामा । नारायन पुरन जन कामा ॥\n\n मेरो भक्त उत्तम हें जेउ । उत्तम मोय जानत हें तेउ ॥\n\n मोरे चरित्र कहावत जेता । दिव्य मोक्षदाई मानत तेता ॥\n\n प्राकृत बुद्धि कबु न ल्यावे । दिव्य अलौकिक करिके गावे ॥\n\n मोर मूर्ति मनुष्य सम जेसि । तामें दिव्य मति रहे तेसि ॥\n\n संबंध भया मूर्ति का जाकु । दिव्य करिके मानत ताकुं ॥\n\n सो उत्तम महा भक्तहि, उत्तम गति लहे तेहु ।\n\n उत्तम मोरे वचन गनि, लेश न लोपे केहु ॥\n\n अंतरजामि जानि मोय, छलकपट करे त्याग ।\n\n छल कपट रखि मोय भजे, तेहिसुं न मोय अनुराग ॥"],"mt":false,"gl":null,"a":false},{"i":848,"k":"para","g":"ઈંગોરાળામાં શ્રીહરિએ મુક્તમુનિ અને બ્રહ્મમુનિને વાત કરતાં કહ્યું, “શુદ્ધ થયા વગર ભગવાનનો પ્રતાપ જુએ તોપણ ઉત્તાપ રહ્યા કરે. શુદ્ધ થવાનું કારણ ખપ અને વિશ્વાસ છે. ખપ-વિશ્વાસ વગર શુદ્ધ વૈરાગ્ય પ્રગટતો નથી. ચાર પ્રકારનો પ્રલય જાણે તે વૈરાગ્યનું કારણ બને છે. નિત્ય શ્રવણ મનન રાખે અને અભ્યાસ કરે ત્યારે જ્ઞાનનો પ્રકાશ થાય છે. ખોટ રહે છે તે અભ્યાસ કરવામાં આળસ છે તેનાથી તે વૃદ્ધિ પામતો નથી. આ લોકના સુખનો નિત્ય અભ્યાસ છે તો ચિત્તમાં તેનો અભાવ આવતો નથી અને વધુ ને વધુ ઇચ્છા કરે છે. સત્સંગમાં જન આવે અને ધર્મ પ્રમાણે વર્તે અને ભગવાનમાં દૃઢ નિશ્ચય થાય તે અક્ષરધામમાં પહોંચે છે. ધીરજ વિનાનો હોય તે પોતાની મનોકામના પૂરી કરવા અન્ય દેવને ભજવા લાગે છે. અમને અને અન્ય દેવને તે એક કરીને માને છે. સત્સંગમાં રહીને જે અન્ય દેવની આરાધના કરે તેને સકામ ભક્ત જાણવો, તે કદી અક્ષરધામને પામતો નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":849,"k":"verse","g":"‘સત્સંગ મેં રહિ કે જોઉ, અન્ય દેવ આરાધત કોઉ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":850,"k":"verse","g":"સો ન જાવત અક્ષરધામા, એસો ભક્ત સો જાનો સકામા.’","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":851,"k":"para","g":"સંતની આજ્ઞા મુજબ વર્તન કરે, યથાશક્તિ કથા-વાર્તા કરે, ધ્યાન-ભજન કરે, સંતને દીન-આધીન રહે, નિર્માનીપણે વર્તે તેને અમે પાકો સત્સંગી જાણીએ છીએ. તે અમારો છે.”","e":null,"s":["4/18/29-47"],"sv":[],"mt":false,"gl":null,"a":false},{"i":852,"k":"para","g":"ઈંગોરાળા ગામે શ્રીહરિ કહે, “જેને અમારો દૃઢ વિશ્વાસ છે, અમારા વિના જે બીજાને સંભારતા નથી તેની ચિંતા અમે કરીએ છીએ, તેની સંભાળ અમે લઈએ છીએ. તેના સુખે સુખી રહીએ છીએ ને તેના દુઃખે દુઃખી થઈએ છીએ.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":853,"k":"verse","g":"‘દૃઢ વિશ્વાસ હમારો જેહી, રહત ચિંતા હમારે તેહી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":854,"k":"verse","g":"હરિજન જાનિ કે હિત હમારે, તેહિ બિન ઓરકું નાહિ સંભારે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":855,"k":"verse","g":"તિનિકે સુખે હમ હેં સુખી, તિનિકે દુઃખે હોત હમ દુઃખી.’","e":null,"s":["4/19/17-18"],"sv":[],"mt":false,"gl":null,"a":false},{"i":856,"k":"para","g":"ઝીંઝાવદરમાં શ્રીહરિએ સ્નાન કરતાં કરતાં વાત કરી, “ભગવાનને સંભાર્યા વિના જે ભક્ત જળ પીએ કે આહાર કરે તે દારૂ પીધા ને માંસ ખાધા બરાબર છે. માટે હરિને સંભારીને ક્રિયા કરવી.”","e":null,"s":["4/22/39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":857,"k":"para","g":"કારિયાણીમાં શ્રીહરિ કહે, “જીવના સાચા મિત્ર ભગવાન કાં ભગવાનના ભક્ત એ બે જ છે. તે વિના બીજા સઘળા જીવનું હિત બગાડનારા કુમિત્ર છે. એવા કુમિત્રને મિત્ર ગણી કોઈ તેનો સંગ કરે તો તે પણ કુમિત્ર જેવો થઈ જાય છે. ભક્તનો સંગ મળે ને હરિવિમુખનો સંગ ન મળે તેવો યત્ન કરવો.”","e":null,"s":["4/29/38-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":858,"k":"para","g":"કુંડળમાં મુક્તમુનિના પ્રશ્નનો ઉત્તર આપતાં શ્રીહરિ કહે, “મૃત્તિકાના પાત્રની પેઠે જ્ઞાનરૂપ અગ્નિમાં પક્વ થાય ત્યારે હરિજન સાચો. જેમાં જેટલી સહન શક્તિ તેટલું સામર્થ્ય વધારે. જયદેવ, મયૂરધ્વજ અને હરિશ્ચંદ્ર આપતકાળમાં પણ દૃઢ રહ્યા. તમને જે સત્સંગ મળ્યો છે તેવો તેમને નહોતો, છતાં અચલ દૃઢતા રાખી. એવી દૃઢતા થાય ત્યારે પાકો હરિભક્ત કહેવાય.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":859,"k":"verse","g":"‘એસો જન હરિજન કહાવે, તેહિ બિન સબહિ કચ્ચે રહાવે.’","e":null,"s":["4/35/25-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":860,"k":"para","g":"ચૂડાપુરના રાણીના ભવનમાં શ્રીહરિએ થાળ જમ્યા પછી વાત કરતાં કહ્યું, “બળહીન ભક્ત ક્યારેય ભગવાન ભજી ન શકે. તે સત્સંગ કરતો થકો વિમુખ થઈ જાય. મડદાને કોણ સંઘરે? બળહીન ભક્ત મડદા તુલ્ય જાણવો. તેને અડવાથી આભડછેટ લાગે, એટલે દૂર જ રહેવું. સંતો! ગામ ગામ ફરીને સૌને શૂરવીર ભક્ત થવા પ્રેરણા આપવી, વાતો કરવી.”","e":null,"s":["4/74/29-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":861,"k":"para","g":"લીંબડીના હરિસિંહ નૃપને શ્રીહરિએ કહ્યું, “જેના હૃદયમાં મોક્ષનો અંકુર પ્રગટ્યો હોય તેને મનુષ્ય જાણવો. મોક્ષના ખપ વિનાનો મનુષ્ય પશુ તુલ્ય છે. સુવર્ણ, હીરા, માણેકને દુર્લભ ધન જાણ્યું છે તો તેનું જતન કરીને રાખે છે. તે કરતાં સંતરૂપી ધન અનેકગણું દુર્લભ છે, તેને જતન કરી જાળવવું.”","e":null,"s":["4/83/5-7"],"sv":[],"mt":false,"gl":null,"a":false},{"i":862,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ જીવેન્દ્ર નૃપને કહ્યું, “સારો-નરસો હરિભક્ત વિપત્તિ પડ્યે પરખાય છે. લોક-વ્યવહારની મોટાઈ લોકમાં શોભાડે પણ સત્સંગની મોટાઈ જુદી છે. નિર્માની થઈને સંતને દીન-આધીન રહે તેની સત્સંગમાં મોટપ છે.”","e":null,"s":["5/2/25-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":863,"k":"para","g":"ગઢપુરમાં જીવા ખાચરના દરબારમાં મુક્તમુનિએ શ્રીહરિને કહ્યું, “રામાનંદ સ્વામીની મરજી આપ જ એક જાણો છો. એટલે અમે આપની મરજીમાં વર્તવાનો દૃઢ નિરધાર કર્યો છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":864,"k":"para","g":"આ સાંભળી શ્રીહરિ કહે, “પોતાનું ધાર્યું કરે ત્યાં સુધી જીવપણું મટતું નથી. ભગવાનનું ધાર્યું કરે ત્યારે તેમાં ભગવાનના જેવા ગુણ આવે છે. ભગવાનના ગુણ જ્યારે આવે ત્યારે તે અતિ પ્રતાપી થાય છે. પ્રકૃતિપુરુષ સુધીના ભોગ તેને હળાહળ ઝેર જેવા દીસે છે. સહજ રીતે દેહ નિભાવવા ગુજરાન કરે, પણ દેહનું જતન ન કરે. સર્વ કરતાં ભગવાનમાં અધિક માલ માને. ભગવાન વિનાનું સુખ મહાભયંકર માને. આવી સમજણવાળો હરિભક્ત મોટો છે.”","e":null,"s":["5/5/29-32"],"sv":[],"mt":false,"gl":null,"a":false},{"i":865,"k":"para","g":"ભુજ આવવા સાથે જોડાનાર હરિભક્તોને શ્રીહરિએ કહ્યું, “હરિભક્તોએ નાતજાતનો ભેદ ભૂલી પરસ્પર એકબીજાના સેવક બનવું. એકબીજાને તુંકારે બોલાવવા નહિ, કોઈને પારકો માનવો નહિ. આ પ્રમાણે અમારું વચન માનીને વર્તે તે બુદ્ધિવાળો છે. બુદ્ધિવાળાને સાચી વાત તરત સમજાય છે. સવળું ગ્રહણ કરે, તેને કોઈ પ્રકારનો ક્લેશ થતો નથી. સવળું ન લે, એ બુદ્ધિવાળો નથી. અવળું લેતો હોય, તેના સંગથી દૂર રહેવું. સત્સંગમાં ધર્મ-નિયમ યુક્ત તથા સંત ઉપર પ્રીતિવાળા, એક મતિવાળા અને સમાધિનિષ્ઠ ઘણાય ભક્તો છે. તેમને કોઈ સિદ્ધિઓ દેખાડે, ધન, પુત્ર કે ગરાસ આપે તથા કામણ-ટૂમણ કરે, મરેલાને જીવતાં કરે, આકાશમાં ચઢે એવા સત્સંગ વિનાના બીજા મનુષ્યો મળે તોપણ તેને વિષે તેમને નિષ્ઠા થતી નથી. અને એવાને તે પાખંડી માને છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":866,"k":"para","g":"“દેહમાં ગમે તેવો રોગ આવે તેને પ્રારબ્ધકર્મનું ફળ સમજીને તે મટાડવા માટે દોરા-ધાગા બાંધતા નથી. બે દિવસ વહેલું-મોડું મરવાનું તો છે જ. પુરુષપ્રકૃતિ સુધી કોઈ અમર રહેતું નથી - એમ સમજીને પુત્ર કે સ્ત્રી જીવે-મરે તેનો શોક કરતાં નથી. અમારાથી અધિક કોઈને હિતકારી માનતા નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":867,"k":"para","g":"“હરિનું શરણું લીધું તેને બીજા બીચારા દેવ વગેરે શા કામના છે? ચક્રવર્તીનું શરણ લીધા પછી કંગાલનું શરણ લેવાનો કાંઈ અર્થ નથી. જેમનો પાકો સત્સંગ હોય છે તેમાં કોઈ ભૂત, પ્રેત કે પાખંડી પ્રવેશ કરી શકતા નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":868,"k":"para","g":"“નાસ્તિકને ઈશ્વરનો ડર નથી. ભગવાન કે ભગવાનના સંત પ્રગટ મળે છે ત્યારે જીવની બુદ્ધિ આસ્તિક થાય છે. આસ્તિક થયા વિના મોક્ષ થાય નહિ. નાસ્તિક, શુષ્કવેદાંતી, ફૂડાપંથી, શક્તિપંથી અને અસુર - પાંચે એક નાતના છે. અમારા સત્સંગીઓએ તેનો સંગ ન કરવો.”","e":null,"s":["5/39/10-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":869,"k":"para","g":"સુખપુરમાં રાવત ધાધલના ભવનમાં શ્રીહરિએ રાજાને કહ્યું, “ધારેલી ટેક, ઘટમાં પ્રાણ હોય ત્યાં સુધી મૂકે નહિ, વિષમ દેશકાળે પણ તેમાં ફેર ન પડે, મનનું ધાર્યું ક્યારેય ન કરે, જેમ પતાકા પવનની દિશામાં વળે છે, તેમ ઘડી ઘડીએ પોતાના મનને સંત કહે તેમ વાળે તેને સર્વે હરિભક્તોમાં મોટેરો જાણવો.”","e":null,"s":["6/5/37-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":870,"k":"para","g":"ટિકરેપુરના વસ્તા સુથારને કાશી જવાની ઇચ્છા હતી. શ્રીહરિએ તેમના મનનો સંકલ્પ જાણીને કહ્યું, “જેને ભગવાન અને ભગવાનના ભક્તનો યોગ થયો છે તેને ગોકુલ, મથુરા, અયોધ્યા, કાશી, જગન્નાથ, બદરીનાથ, મુક્તનાથ, દ્વારકા વગેરે બધાં તીર્થ તેમાં આવી ગયાં. લોકો તીર્થ કરવા જાય છે એ બધાં તીર્થ આજે તમારા ઘરે આવ્યાં છે. આ અમારું વચન નહિ માનો તો ફરી ઘર આંગણે પાછા નહિ આવો.” આ સાંભળી વસ્તા સુથારને તીર્થ કરવા જવાનો ઘાટ ટળી ગયો.","e":null,"s":["6/31/15-16"],"sv":["हरि हरिजन के जोग, गोकुल मथुरा अवध्यपुर ।\n\n काशी जावत लोग, सो सब आये हें तव घर ॥\n\n जगन्नाथ सो आये, बदरीनाथ सो आये तेहि ।\n\n मुक्तनाथ हि ताय, द्वारापुरी लग आये सब ॥\n\n वचन नहि मानो जो हमारा । फेर नहि आवो घर द्वारा ॥"],"mt":false,"gl":null,"a":false},{"i":871,"k":"para","g":"જેતપુરમાં શ્રીહરિ કહે, “ગરીબનો અપરાધ કદાચ મારાથી જો થઈ જાય તો મને અતિ દુઃખ થાય છે, તો બીજાની શી વાત! એક તો બીજાના કટુ વચન સહન કરીને ચાલતો એવો ભગવાનનો ભક્ત હોય, બીજો એ કે જેનો દેહ પરવશ હોય, જે અતિ બાળક હોય ને જે અતિવૃદ્ધ હોય તે ચારેને ગરીબ જાણવા.”","e":null,"s":["6/65/24-25"],"sv":[],"mt":false,"gl":null,"a":false},{"i":872,"k":"para","g":"સાચા હરિજનની પરખ એ છે કે તેને ભગવાન વિના બીજો ઘાટ ન થતો હોય. સત્ય વાત કરે ને સત્ય વાતનો આદર રાખે, વર્તનનું અભિમાન ન હોય તેને શ્રેષ્ઠ હરિજન જાણવો. વળી, અપમાન કરનારા સામે વેર ન બાંધે, વેર કરે તેટલો કુસંગ જાણવો. ભગવાનનાં વચન મુજબ વર્તે એ હરિભક્તનું મુખ્ય લક્ષણ છે. ભગવાનની આજ્ઞા પાળવામાં લોક પ્રસન્ન થાય કે કુરાજી થાય, ભક્ત તે મનમાં લેતો નથી. મનમાં ભગવાનનાં વચન દૃઢ રાખીને એમ ઇચ્છે છે કે ભગવાનની પ્રસન્નતામાં બધાની પ્રસન્નતા સમાઈ છે. સાચો ભક્ત જીવમાંથી બધાનું હિત ઇચ્છે, પણ બૂરું ન ઇચ્છે. કોઈનું બૂરું થાય તેવું વચન ભૂલથી પણ ન કહે. પોતાના ભજનમાં કોઈ વિક્ષેપ કરે તોપણ તેને સહન કરી લે. સહન કરવા જેવી બીજી કોઈ મોટપ નથી.”","e":null,"s":["6/91/14-18"],"sv":[],"mt":false,"gl":null,"a":false},{"i":873,"k":"para","g":"ગઢપુરમાં શ્રીહરિ જીવાખાચરને કહે, “સંસારી બુદ્ધિ અંધકાર છે. જેને સંસારી બુદ્ધિ છે તેને અજ્ઞાનરૂપી વિકાર ટળતા નથી. જ્યાં સુધી અજ્ઞાન વિકાર છે, ત્યાં સુધી સત્સંગમાં ગુણ-દોષ પરઠ્યા કરે છે. ગુણદોષ પરઠે છે ત્યાં સુધી તેને શાંતિ પ્રાપ્ત થતી નથી. જેમ સુદ પક્ષમાં અજવાળું ને વદ પક્ષમાં અંધારું રહે છે, તેમ સંસારી મતિ વદ પક્ષ છે. અમાયિકમતિ સુદ પક્ષ છે. સત્સંગનો ચંદ્ર હૃદયમાં અજવાળું પાથરતો રહે ત્યાં સુધી ભક્તના હૃદયમાં શાંતિ વરતે, પણ કુસંગરૂપી અંધારાનો યોગ થતાં જ તેની શાંતિ હણાઈ જાય છે ને વિક્ષેપ પેદા થાય છે. સંસારના સુખમાં જેવી રુચિ છે તેવી રુચિ સત્સંગમાં થાય તેને હૃદયે સદા શાંતિ રહે છે.”","e":null,"s":["6/98/21/22"],"sv":["सत्संग चांद उर रहे ज्यां लग हि । शांति उर में वरते त्यां लग हि ॥\n\n कुसंग अंधतम जोग जब होवे । विक्षेप चित्त होई शांति कुं खोवे ॥\n\n संसारिक सुख में हे रुचि जेसी । सत्संग में जो होवे तेसी ॥\n\n ताकुं शांति सदा उर रहेवे । वेद शास्त्र संत इमि सब केवे I"],"mt":false,"gl":null,"a":false},{"i":874,"k":"para","g":"ભૂજમાં શ્રીહરિએ કહ્યું, “સત્સંગને અર્થે જ બધું કરી રાખે અને સત્સંગમાં જે લેવું દેવું તે સ્વાર્થને માટે ન કરતા હોય, એવા ભક્ત ઉપર ભગવાન પ્રસન્ન થાય છે. સ્વાર્થ માટે સત્સંગમાં લેવા-દેવાનો વહેવાર કરે છે તે પરસ્પર લડીને સંત-હરિજનનો અવગુણ લઈને કુસંગી થઈ જાય છે. જેને કલ્યાણ વિના બીજો સ્વાર્થ નથી તે દિવસે દિવસે સત્સંગમાં વધે છે. સત્સંગથી કુસંગનો દોષ ઓળખાય છે. કુસંગનો ગુણ રહે ત્યાં સુધી સત્સંગની દૃઢતા ગણાય જ નહિ.”","e":null,"s":["7/9/17-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":875,"k":"para","g":"ભુજના ભક્તોએ કહ્યું, “પ્રભુ! અહીં અન્નકૂટ કરો. ખર્ચ થશે તે બધા સત્સંગી મળીને સરખે ભાગે ઉપાડી લઈશું.” ત્યારે શ્રીહરિ કહે, “અમને એવી રીત ગમતી નથી, કારણ કે કોઈક ગરીબ હરિજન મહા મુશ્કેલીએ નિર્વાહ કરતો હોય તેને પણ ખર્ચમાં બરોબર ગણો ત્યારે એને સત્સંગ રહે નહિ, સત્સંગ વધારવા માટે તો અમે ઉત્સવ કરીએ છીએ. આ તો ધનાઢ્યનું કામ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":876,"k":"para","g":"“નિર્ધન ભક્ત તો જેવી શ્રદ્ધા હોય તેવી શરીરથી સેવા કરે. હુકમ કરીને સેવા કરાવવાની સત્સંગની રીત નહિ. નિર્ધનનો સત્સંગ ટકે એવી બરદાસ રાખવી જોઈએ. એક જણને સત્સંગ કરાવે તેને કેટલુંય પુણ્ય છે તે ભૂલવું ન જોઈએ. નિર્ધનની મરજી ન હોય તે કામ તેને કહેવું નહિ. જેમ તેમ કરીને તેને નભાવવો. જ્યારે સત્સંગ નિમિત્તે ખર્ચ કરવું હોય, ત્યારે ધનાઢ્ય હરિભક્તોએ જ માથે લેવું. સત્સંગ નિમિત્તે ખર્ચ કરે તે મુખ્ય હરિભક્ત ગણાય. અને તે જ ખરો ધનાઢ્ય છે. ધનાઢ્ય હરિભક્ત થઈને સત્સંગ નિમિત્તે જાણવા છતાં ખર્ચ ન કરે તેનાથી સત્સંગની શોભા નથી.”","e":null,"s":["7/9/30-40"],"sv":["सत्संग निमित्त खर्च करे, सो हरिजन हे मुखी ।\n\n यह लोक परलोक में, कबहु न होवे दुःखी ॥\n\n धनाढ्य हरिजन होई, सत्संग निमित्त जानकर ।\n\n खरच करे न कोई, शोभा नहिं हे सत्संग में तेहि ॥"],"mt":false,"gl":null,"a":false},{"i":877,"k":"para","g":"ભુજમાં શ્રીહરિ બોલ્યા, “હરિભક્તે કોઈનો વિશ્વાસઘાત ન કરવો અને સત્સંગની અદલ રીતથી ચાલવું. સત્સંગીનો શુદ્ધ ધર્મ જોઈ કરોડો પ્રતિષ્ઠિત લોકો પોતાના પુત્ર કરતાં વધુ વિશ્વાસ કરે છે. શુદ્ધ સંતના સેવનથી શુદ્ધ મતિ થાય છે. કેટલાક સત્સંગી ઠગ થઈને સંતોને ઠગે છે. કુસંગી કુસંગીનો વિશ્વાસ ન રાખે. મિત્ર મિત્રમાં પણ ધન અને નારીના સંબંધમાં વિશ્વાસ રાખનારા થોડા હોય, પરંતુ તે સૌ સત્સંગીઓનો વિશ્વાસ કરે છે. ધર્મથી સત્સંગીની મોટાઈ છે.”","e":null,"s":["7/10/1-7"],"sv":[],"mt":false,"gl":null,"a":false},{"i":878,"k":"para","g":"ગઢપુરમાં શ્રીહરિ કહે, “અમે વઢીએ અને મૂંઝાય નહિ તો તેના પર અમારે અધિક પ્રીત થાય છે, પણ એવા હરિભક્ત ઘરે ઘરે હોય નહિ. તેવા પાકા હરિભક્તને અમે પારખી લઈએ છીએ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":879,"k":"para","g":"“ભગવાન અને ભગવાનના ભક્ત વિના આ જગતમાં બીજી કોઈ સાર વસ્તુ નથી. ભગવાન ને ભક્ત વિનાનું બધું મલિન છે. તે સત્સંગ કરીને જાણવું.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":880,"k":"verse","g":"‘હરિ-હરિજન વિન, જગ મેં નહિ હેં સાર કોઈ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":881,"k":"verse","g":"તા વિન સબહિ મલિન, સત્સંગ કરિ જાનના તેહિ.’","e":null,"s":["10/7/3, 4, 40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":882,"k":"para","g":"કરિયાણામાં ઓઢા ખાચરના ભવનમાં શ્રીહરિ કહે, “જેને જીવનો સત્સંગ છે, તે તરત દેખ્યામાં આવે છે. સત્સંગ તો મહા સૂર્ય જેવો છે તે વર્તનમાં જ દેખાડી દે. સત્સંગના નિયમોનો જે સત્કાર કરે તે દિન દિન પ્રત્યે સરસ ભક્ત થતો જાય છે. નિયમ વિનાની વાત સરસ હોય તોપણ ક્યારેક ઘાત કરી દે છે. તે પાછળથી ખબર પડે છે. સત્સંગમાં નિયમ વિનાની એકેય વાત નથી.”","e":null,"s":["10/9/24-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":883,"k":"para","g":"શ્રીહરિએ ભુજ નગરના હરિભક્તોને કહ્યું, “મન તો ભૂત જેવું છે, ગુણને વશ વર્તે છે. હરિભક્તે તો તન, મન ભગવાનને અર્પણ કરીને હરિને અધીન વર્તવું. મનનો એવો સ્વભાવ છે કે કોટિ ચરિત્ર દેખાડે. સત્સંગ જે દિવસથી થયો છે ત્યારથી હરિભક્તને દિવ્યાકાર પ્રાપ્ત થયો છે. પણ દેહનો સંગ જ્યાં સુધી છે ત્યાં સુધી ગુણની ભ્રાંતિમાં સત્યતા દેખાય છે. જેમ બળેલી દોરડી હોય તે સત્ય જેવી દેખાય તેમ હરિ અને સત્સંગ અમાયિક છે. ભગવાનનો પ્રતાપ દેખીને માયા સદા આધીન રહે છે. જે ભગવાનને શરણે થયા છે તેને માયાનું લેખું નથી, બીજાને તો માયા પરાભવ કરે છે, કારણ કે સત્સંગી તો કોઈ પ્રકારે અનીતિમાં ચાલતો નથી. તેને મન શું કરનારું છે? કાળ, કર્મ, માયા, જમદૂત તે પણ તેને સ્પર્શ કરી શકતાં નથી. તેને તો ભગવાન એ જ સર્વસ્વ છે. પ્રગટ હરિના સંત છે, તે પણ નિયમમાં વર્તી સત્સંગના આશ્રિત જનોનું પોષણ કરે છે. પોષણ વિના તો બ્રહ્મા જેવો હોય તોપણ મનનું ભાવ્યું કરવાં લાગે. પોષણ વિના નિયમ નિષ્ઠા રહે નહિ તે પ્રગટ દેખ્યામાં આવે છે.”","e":null,"s":["10/34/11-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":884,"k":"para","g":"મૂળીલા ગામમાં સંતોએ કીર્તન ગાયાં, ત્યાં સુધી ગ્રામજનો બેઠાં. પછી શ્રીહરિએ વાત કરવાનો આરંભ કર્યો, ત્યારે સૌ ઊઠી ઊઠીને ચાલતાં થયાં. એટલે શ્રીહરિ સંતોને વાત કરવા લાગ્યા, “તમારાં ભાગ્યનો પાર નથી. આવો સર્વોપરી સત્સંગ અલ્પ પુણ્યવાળાને મળતો નથી. સર્વોપરી સુખના લોભી હોય તે સત્સંગ કરે છે. ઊલટી સમજણ હોય ત્યાં સુધી સત્સંગ ગમે નહિ. પ્રહ્‌લાદ અને પ્રિયવ્રત જેવાની સમજણ ગ્રહણ કરવી. પિતાએ બહુ સમજાવ્યો તથા ડરાવ્યો તો પણ પ્રહ્‌લાદે સત્સંગ વિના બીજામાં સાર માન્યો નહિ, દેહ સુધીનું મમત્વ છોડી દીધું અને ભગવાનને માટે દુઃખ સહન કર્યાં. ભગવાન માટે નાક-કાન કપાય કે ગધેડે બેસવું પડે તેને પણ મંગળકાર્ય જાણ્યું. સંતો-હરિભક્તોએ એવી સમજણ રાખવી.”","e":null,"s":["11/13/16-22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":885,"k":"para","g":"શ્રીહરિએ પત્રમાં લખાવ્યું કે, “ભગવાનનું શરણ જેમણે નથી લીધું તેનો જન્મ વૃથા છે. શરણું ગ્રહણ કરનાર હરિભક્તને અમે દેવથી અધિક માનીએ છીએ. અમે આપેલ નિયમ મુજબ વર્તે તે ભક્ત સર્વોપરી થઈ જાય છે.”","e":null,"s":["15/84/10-11"],"sv":[],"mt":false,"gl":null,"a":false},{"i":886,"k":"para","g":"શ્રીહરિએ અક્ષરધામને ન પામે એવા ભક્તની વાત પત્રમાં કરતાં કહ્યું, “ભગવાનની પ્રતિમાની નવ પ્રકારની ભક્તિ પ્રત્યક્ષભાવ લાવીને ગદ્‌ગદકંઠ થઈને નિત્ય કરે, ચતુર્ભુજ મૂર્તિને હૃદયમાં ધારીને નિત્ય માનસી કરે, જેમાં મૂર્તિને પોતાના હૃદયમાં બોલતી-ચાલતી દેખે, એવા ભક્તો મરીને ગોલોકમાં જાય છે. ‘ગોલોક પામે ધામ હિ, કછુ સંદેહ ન એહ.’ એવા ભક્તને પરોક્ષ ભગવાનની મૂર્તિમાં અતિ હેત હોવાથી તેને તેવી પ્રાપ્તિ કહી છે. તે ભક્તો અક્ષરધામ સિવાય જેવા ધામને ઇચ્છે તેવા ધામને પામે છે, પણ અક્ષરધામને પામતા નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":887,"k":"verse","g":"‘જેસે ધામકિ ઇચ્છા તાહિ, અક્ષર વિન પાવત રહાહિ.’","e":null,"s":["15/99/20-30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":888,"k":"para","g":"પછી શ્રીહરિ ઉત્તમ, મધ્યમ અને કનિષ્ઠ એમ ત્રણ પ્રકારના ભક્તોની વાત પત્રમાં કરવા લાગ્યા. પ્રથમ ઉત્તમ ભક્તની ઓળખ આપતાં કહ્યું, “અપાર બ્રહ્માંડની ઉત્પત્તિ, સ્થિતિ અને પ્રલયનાં કાર્યમાં જુદા જુદા અવતારો થયા છે. તેના ભક્તો પણ અપાર થયા છે, પરંતુ જીવનું કલ્યાણ કરવા જ્યારે ભગવાન પુરુષોત્તમ પ્રગટ થાય છે અને ચરિત્રો કરે છે, તેનાં કીર્તન, ધ્યાનમાં સર્વોપરિ રસ રહ્યો હોય છે. એ સાક્ષાત્કાર પ્રગટ ભગવાનનું ભજન કરનારા હરિજન ઉપર અમને બહુ હેત છે. એ ભક્તો ભગવાનની ક્રિયામાત્રને કલ્યાણરૂપ દેખે છે અને હિતકારી માને છે, ભગવાનને અનંત જીવોના જન્મ અને કર્મના ટાળનારા માને છે. પોતાના દેહને મિથ્યા તેમજ પોતાના આત્માને સત્ય માનીને તથા ભગવાનને નિર્દોષ અને અસંગી માનીને આત્મારૂપ થઈ પ્રગટ ભગવાનનું ભજન કરે છે. એ ભક્તો ઉત્તમ છે ને અક્ષરધામમાં ભગવાનનું અખંડ સુખ લે છે.”","e":null,"s":["15/99/31-41"],"sv":[],"mt":false,"gl":null,"a":false},{"i":889,"k":"para","g":"શ્રીહરિએ મધ્યમ ભક્તની વાત પત્રમાં કરતાં કહ્યું, “જે ભક્તને ભગવાનની મૂર્તિ ધારતાં ધન-ત્રિયાદિક વિષયમાં વૃત્તિ જાય ત્યારે મનમાં દાઝ થાય અને ધ્યાન છોડે નહીં. વળી, ઘાટ સંકલ્પને ખોટા કરતો રહે. શ્રીકૃષ્ણમાં ગોપી જેવું અસાધારણ હેત હોય પણ કોઈ પ્રકારનો આત્મા-અનાત્માનો વિવેક હોય નહીં. તેને દેહ મૂક્યા પછી ગોલોકની પ્રાપ્તિ થાય છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":890,"k":"verse","g":"‘આત્મા-અનાત્મા કે વિવેકા, કછુ જન જો જાનત નહિ છેકા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":891,"k":"verse","g":"મૂવે પિછે ભક્તજનહિ તાકું, ગોલોક કી પ્રાપ્તિ હોત વાકું.’","e":null,"s":["15/100/5-7"],"sv":["श्रीहरि पुनि कहत भयेउ, प्रसन्न होई बात ।\n\n उत्तम भक्त कुं कहे अब, मध्यम कहत साक्षात् ॥\n\n धन-त्रियादिक पदार्थ जेहा । मूर्ति कुं धारत बिच में तेहा ॥\n\n धारे में आवे अंतर में जबहु । ताकी दाझ अंतर होय तबहु ॥\n\n मूर्ति के ध्यान छोरे नहि तोउ । घाट संकल्प खोटे करे सोउ ॥\n\n असाधारण हित हि जो जेही । भगवान में रहाये तेही ॥\n\n आत्मा-अनात्मा के विवेका । कछु जन जो जानत नहि छेका ॥\n\n मुवे पिछे भक्तजन हि ताकुं । गोलोक की प्राप्ति होत वाकुं ॥"],"mt":false,"gl":null,"a":false},{"i":892,"k":"para","g":"ફરી શ્રીહરિએ પત્રમાં ઉત્તમ ભક્તની વાત કરતાં કહ્યું, “ઉત્તમ ભક્ત પિંડ-બ્રહ્માંડને મિથ્યા સમજી ભગવાનને ભાવથી ભજે છે. મનુષ્યરૂપે પ્રગટ થયેલા પરબ્રહ્મ પુરુષોત્તમ પરમાત્મા શ્રીહરિને જેવા ધામમાં છે તેવા જ અહીં સમજે, નિર્ગુણ અને દિવ્ય સમજે, એમનાં ચરિત્રો, ક્રિયા કલ્યાણકારી સમજે. ભગવાનમાં અસાધારણ સ્નેહથી દેહભાવ ભૂલી ઉન્મત્તપણે જોડાઈ જાય, વૃત્તિમાં મૂર્તિ ચોંટાડી દે. વૃત્તિને મંદિર બનાવી તેમાં મૂર્તિ પધરાવી દે. તેને લૌકિક અહંકાર ન હોય, પણ પોતાને બ્રહ્મસ્વરૂપપણાનો અહંકાર હોય. આવા ભક્તને ઉત્તમ ભક્ત જાણવો. એવો ભક્ત દેહ મૂકે છે ત્યારે ગોલોકથી પર એવા અક્ષરધામને પામે છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":893,"k":"verse","g":"‘આવત હે અહંકાર હિ એસા, મેં હું બ્રહ્મસ્વરૂપ એસા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":894,"k":"verse","g":"ગોલોક સે પર અક્ષરધામા, એસે ભક્ત રહત તેહિ ઠામા.’","e":null,"s":["15/100/7-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":895,"k":"para","g":"શ્રીહરિએ કનિષ્ઠ ભક્તની વાત પત્રમાં લખતાં કહ્યું, “કનિષ્ઠ ભક્ત ભક્તિ ગૌણપણે કરે અને તેને જગતનું પ્રધાનપણું અધિક રહે. ભગવાનનો નિશ્ચય હોય, પણ દેહાત્મબુદ્ધિ સહિત હોય. સંતમાં ચિત્ત ઠરે પણ જગતમાં આસક્તિ રહે. સંતની સેવા કરવામાં ઉત્સાહ હોય, પણ એ ભક્તને જેવી પરોક્ષમાં પ્રતીતિ છે, તેવી પ્રગટમાં થતી નથી. મૂર્તિ ન દેખે તો ગદ્‌ગદકંઠ થઈ જાય, ભગવાન પ્રગટ બિરાજતા હોય ત્યારે તે દર્શન મૂકીને ધ્યાનમાં બેસી પરોક્ષનું ચિંતવન કરે. તેવા ભક્તને પરોક્ષ ભક્ત સાથે જેવી સુવાણ થાય છે, તેવી પ્રગટના ભક્ત સાથે થતી નથી. હેત પણ થતું નથી અને પરોક્ષના જેવું માહાત્મ્ય પણ પ્રગટના ભક્તનું જાણતો નથી. તેની રુચિ મુજબ ભગવાન તેને પ્રાપ્તિ કરાવે છે ને વૈકુંઠલોકમાં વસાવે છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":896,"k":"verse","g":"‘પ્રોક્ષ ભક્ત કું હિત રહે જેસા, પ્રત્યક્ષ ભક્ત કું હિત નહિ તેસા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":897,"k":"verse","g":"પ્રોક્ષ જેસે માહાત્મ્ય ન રહાયે, તેહિકર વૈકુંઠ તામે વસાય.’","e":null,"s":["15/100/13-19"],"sv":[],"mt":false,"gl":null,"a":false},{"i":898,"k":"para","g":"ફરી ઉત્તમ ભક્તની ઓળખ આપતાં શ્રીહરિ પત્રમાં કહે, “ભગવાન વિના જેને કોઈ ઇચ્છા નથી તેને ઉત્તમ ભક્ત જાણવો. એવો ભક્ત અક્ષરધામને પામે છે અને ભગવાનનું સુખ લે છે. જેને પરબ્રહ્મ પુરુષોત્તમ પરમાત્માનો સત્સંગ-સંબંધ થયો છે એવો ભક્ત પોતાના આત્મસ્વરૂપને બ્રહ્મ (અક્ષરબ્રહ્મ) માને છે. પોતાને બ્રહ્મ માની ભગવાન(પરબ્રહ્મ)ની સેવા કરે છે. એ સેવા જેવી બીજી કોઈ પ્રાપ્તિ તે માનતો નથી.”","e":null,"s":["15/100/23-26"],"sv":["भगवान बिन नहि इच्छा जाहि । ऐसे भक्त उत्तम रहे ताहि ॥\n\n अक्षरधामकुं पावत तेहु । भगवान के सुख लहत हें ऐहु ॥\n\n पुरुषोत्तम परब्रह्म जेहि । परमात्मा कहावत तेहि ॥\n\n ताके भये सत्संग जो, ऐसे भक्त हि जोउ ।\n\n पोताके आत्मस्वरूपकुं, ब्रह्म हि मानत सोउ ॥\n\n आपकुं ब्रह्म मानिके, भगवान कि करत सेव ।\n\n सेवा सम प्राप्ति कोउ, देखत नहि रहेव ॥"],"mt":false,"gl":null,"a":false},{"i":899,"k":"para","g":"શ્રીહરિએ ત્રણ પ્રકારના ભક્તોની વાત પત્રમાં કર્યા પછી કહ્યું કે, “ભગવાનની સેવાને જે ભક્ત પ્રવૃત્તિ કહે છે એવા ભક્તને ભગવાન બદરિકાશ્રમ કે શ્વેતદ્વીપમાં રાખે છે.”","e":null,"s":["15/100/27-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":900,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ હરિજનો પ્રત્યે વાત કરતાં કહ્યું, “પાકા સત્સંગીની ઓળખાણ એ છે કે સુખદુઃખમાં એક રંગ રહે. સત્સંગ વિનાનું ગમે તેવું સુખ હોય તેને નકામું માને. સત્સંગથી વિમુખ કરાવે એવી રિદ્ધિ-સિદ્ધિનો ત્યાગ કરે. દેહમાં દુઃખ આવે તોપણ સત્સંગ મોળો ન પડે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":901,"k":"para","g":"“સત્સંગ થતાં પુત્ર કે ધનનો નાશ થાય કે માતા-પિતા દ્વેષ કરે, ઘર બળી જાય, કુળ-કુટુંબ રૂઠે તોપણ સત્સંગ મોળો ન પડે, પણ સત્સંગમાં વિરોધ કરનારાઓને તૃણ સમાન ગણે. સત્સંગ કરતાં ગુરુ કોપે, દીર્ઘ રોગ થાય, મૃત્યુ થાય - એમ ગમે તેવું વિઘ્ન આવે તોપણ સત્સંગની દૃઢતા ઘટે નહિ. તે હરિભક્ત સત્સંગિ-શિરોમણિ અને શૂરવીર છે. તેની વાત સાંભળીને પણ બીજા ભક્તો શૂરવીર બને છે. વિપત્તિમાં પણ પાકો સત્સંગ રાખે તે ભક્ત હરિશ્ચંદ્ર અને પ્રહ્‌લાદની પેઠે વિખ્યાત થાય છે. સત્સંગને માટે દુઃખ સહે તેને ભગવાન સર્વોપરી સુખ આપે છે.”","e":null,"s":["16/48/5-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":902,"k":"para","g":"શ્રીહરિએ બાપુભાઈના દરબારમાં મછિયાવમાં વાત કરતાં કહ્યું, “ત્યાગી અને ગૃહી હરિજનોએ પરસ્પર એકબીજાનું હિત ઇચ્છવું. જે હરિભક્તનું હિત ઇચ્છે તે સમાન કોઈ હરિભક્ત નથી. હરિભક્ત થઈને બીજા હરિભક્ત સાથે ક્યારેય વેર ન કરવું. હરિજન ઉપર જે વેર રાખે છે તેને દેખીને અમે ઉદાસ થઈએ છીએ. અન્ન, વસ્ત્ર, સન્માન તથા દેહસુખને માટે અમને ક્યારેય ઉદાસી થતી નથી. આ અમારી પ્રકૃતિ છે.”","e":null,"s":["18/19/23-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":903,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “જે હરિભક્તને મોક્ષનો ખપ જાગે છે ત્યારે અંતરમાં સદ્‌બુદ્ધિ પ્રગટ થાય છે. એક એક સંતમાં ગુરુબુદ્ધિ વર્તવા લાગે છે. જે સાધુને અન્ય સાધુમાં ગુરુબુદ્ધિ જાગે તો તેને પરમ ભાગવત જાણવા.”","e":null,"s":["21/88/5-6"],"sv":[],"mt":false,"gl":null,"a":false},{"i":904,"k":"para","g":"ગઢપુરમાં શ્રીહરિ કહે, “જે અપમાન થવા છતાં ક્ષોભ પામતા નથી એવા સંતો-હરિભક્તો અમારાં સગાંવહાલાં છે. તે વિનાના બીજા ભેગા રહેતા હોય તોપણ આનંદ થાય નહિ. ધર્મેયુક્ત ભક્તિ જેનામાં હોય તેને અમે વશ વર્તીએ છીએ.”","e":null,"s":["26/19/47-50"],"sv":[],"mt":false,"gl":null,"a":false},{"i":905,"k":"para","g":"શ્રીહરિએ ગઢપુરમાં વાત કરતાં કહ્યું, “જે હરિભક્તો સત્સંગને પોતાનો માને છે તે અમારા માટે, સંતો માટે કે મંદિરને માટે ફાવે તેટલું કરવું પડે તો પણ મનમાં કઠણ માનતા નથી. સમજણમાં ફેર તેટલું જ કઠણ પડે છે.”","e":null,"s":["28/65/29-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":906,"k":"para","g":"શ્રીહરિ કહેતા, “ભગવાન અને ભગવાનનું અક્ષરધામ એ વિના અનંત બ્રહ્માંડોના અપાર વૈભવ પણ વિઘ્નકર્તા છે ને કાળનું ભક્ષણ છે એમ જાણીને સત્સંગ કરે તેને સત્સંગી કહેવાય.”","e":null,"s":["28/130/7-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":907,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":908,"k":"para","g":"અતિ દૃઢ હરિભક્તની પરખ કઈ? જેને ભગવાન અને ભગવાનના સંતમાં અપાર હેત હોય, તેનાં દર્શન-સમાગમ વિના તેનાથી રહેવાય નહિ, સંતનો સંગ નિરંતર રાખે, સંત વિના એક દિવસ પણ રહી ન શકે. સંતની પ્રસાદી નિત્ય ઝંખે, મન, કર્મ, વચનથી સંતની સેવામાં જોડાયેલો રહે. ભગવાનની કથા-વાર્તા, ચરિત્રનું શ્રવણ કરે, તે વિના બીજી વાત ન કરે. સત્સંગ કરવામાં કોઈની પરવા રાખે નહિ. આવો હરિભક્ત ગુણે કરીને સરલચિત્ત અને નિષ્પાપ કર્મ કરનારો હોય, કપટ, કુટિલતાનો જેમાં લેશ પણ ન હોય, આવા હરિભક્ત પર ભગવાન અતિશય હેત રાખે છે અને માની જનથી દૂર રહે છે.","e":null,"s":["4/57/11-14"],"sv":[],"mt":false,"gl":null,"a":true},{"i":909,"k":"para","g":"ભગવાન અને ભગવાનના ભક્ત દર્પણ સમાન છે. હરિ-હરિજન મેં જૈસો ભાવા, તેંસો હોત હૈ આપ સ્વભાવા. હરિ અને હરિજનમાં જેવો ભાવ રાખે તેવો પોતે થાય છે. દર્પણ તો જેવું મુખ હોય તેવું બતાવે. ઘી-સાકર તુલ્ય કોઈ મેવો નથી, પણ તે જ્વરવાળાને ઝેર સમાન લાગે છે.","e":null,"s":["4/58/21-22"],"sv":[],"mt":false,"gl":null,"a":true},{"i":910,"k":"para","g":"ભગવાનની મરજીને રતીભાર પણ ન લોપે તે સાચો શરણાગત કહેવાય. જે મરજી લોપીને વર્તે છે તેને કુમાર્ગનું ફળ મળે છે.","e":null,"s":["4/61/18"],"sv":[],"mt":false,"gl":null,"a":true},{"i":911,"k":"para","g":"જેને ભગવાનના વચનપાલનમાં પ્રીતિ છે તેવા ભક્તને હરિનું સ્વરૂપ જાણવા. શ્રીહરિ એવા ભક્તના ચિત્તમાં અખંડ વસે છે. વચનમાં વર્તે તે નિર્બંધ છે. એ સનાતન મુક્ત છે. એવું જીવથી વર્તી શકાય નહિ.","e":null,"s":["5/74/39-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":912,"k":"para","g":"ભક્ત હોય તે સંગ ઓળખે. જેને પંચવિષયમાં આસક્તિ હોય તેવો સંગ તે કદી ન કરે. સહજ સ્વભાવે દેહનિર્વાહ થાય તેટલું સર્જન કરે. ભગવાનમાં જ તે અથાહ ને નિર્ભય સુખ માને, અનંત ધામોનું સુખ ભગવાનના સુખથી તુચ્છ માને, પાત્ર જોઈ એ સુખને વહેંચતો રહે, પાતાળથી પ્રકૃતિપુરુષ સુધી કોઈ સુખમાં કદી ન બંધાય. આત્મલાભ અને ભગવાનની મૂર્તિના સુખનો વિચાર કરે, બીજાં ધામનાં સુખ ભગવાનના સુખની પાશંગમાં પણ નથી આવતાં એવું જે માને તે સાચા ભગવાનના ભક્ત છે.","e":null,"s":["6/11/22-26"],"sv":[],"mt":false,"gl":null,"a":true},{"i":913,"k":"para","g":"ભગવાનનાં ચરિત્ર ભક્તને અમૃત સમાન લાગે છે. દરેક ચરિત્ર તે કલ્યાણકારી માને છે. ભક્ત હોય તે કદી પરમાત્મામાં દોષબુદ્ધિ ન કરે. તેની સદા એકમતિ રહે. તેને એક હરિમાં જ અનુરાગ હોય, સર્વ સારનો સાર હરિની મૂર્તિ છે. સુખમાત્ર તેમાં માને. એક શ્રીહરિને પૂજવાથી દેવમાત્ર પૂજાય તેમ દૃઢપણે સમજે. આવી મતિ શ્રીહરિમાં જે જન કરે છે તેને કોઈ માન આપે કે અપમાન કરે - તેની સામે તે દૃષ્ટિ પણ કરતો નથી. જેટલું કંઈ માયિક સુખ છે તેને તીવ્ર વિષ તુલ્ય ગણે છે.","e":null,"s":["6/21/18-27"],"sv":[],"mt":false,"gl":null,"a":true},{"i":914,"k":"para","g":"શ્રીહરિને મન કોઈ ભક્ત દૂર નથી. ભક્તના મનમાં એવું દૂરપણું લાગે છે. જો ભક્ત શ્રીહરિને પાસે જાણે તો શ્રીહરિ તેની પાસે દર્શાય છે. જો ભક્ત શ્રીહરિને મનની વૃત્તિમાં ધારે, તો શ્રીહરિ વૃત્તિમાં દર્શાય છે. આત્મરૂપ થઈને ધારે તો આત્મામાં દર્શાય છે અને આંખો સામે તો મૂર્તિમાન દર્શાય છે.","e":null,"s":["6/51/25-26"],"sv":[],"mt":false,"gl":null,"a":true},{"i":915,"k":"para","g":"સત્સંગ થતાં પહેલાં તો જીવ માયાના ત્રણ ગુણથી આવૃત્ત હતો. તે સત્સંગમાં આવ્યો ત્યારે તેના ત્રણ પ્રકારનાં કર્મ છૂટી ગયાં અને ગુણાતીત બન્યો. અને હરિભક્ત કહેવાયો. હવે તન, મન, ધનથી જે કંઈ કરે તે ભગવાનના સંબંધવાળું જ હોય - અર્થાત્ તેણે તન, મન, ધન ભગવાનને અર્પણ કર્યાં કહેવાય. એટલે અંબરીષ, બલિ, પ્રહ્‌લાદ, પ્રિયવ્રત, જનકની જેમ એ પણ આત્મનિવેદી થયો. એટલે તેણે તને, મને, ધને કરીને ભગવાન કહે તેમજ કરવું જોઈએ.","e":null,"s":["6/51/32-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":916,"k":"para","g":"હરિભક્તો પરસ્પર ઈર્ષ્યા નહિ રાખીને એકબીજાને ધર્મ પાળતા જોઈને આનંદ પામે ને એકબીજાનાં વખાણ કરે તથા પરસ્પર વિશ્વાસ રાખે. અંતરમાં કોઈ ઘાત રાખે નહિ. લોભવશ થઈ કોઈ તેવી ઘાત રાખે તો તે ફાવે તેવી સેવા કરતો હોય તોપણ તેને સત્સંગી ગણે નહિ. અને પ્રાયશ્ચિત્ત કરે તોપણ તેની પૂરી પ્રતીતિ રાખે નહિ, એકવાર ધર્મ ત્યાગ કરે તેનો સંગ પણ કોઈ હરિભક્ત રાખે નહિ. આવી સત્સંગની દૃઢ પ્રથા છે.","e":null,"s":["9/32/31-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":917,"k":"para","g":"જીવન પર્યંત સંતનો સમાગમ કરવો ને મનનું ધાર્યું કરવું નહિ તે ઉત્કૃષ્ટ સમાધિ છે. દૃઢ સત્સંગ થયો તે ડગે નહિ. મોટાં મોટાં વૃક્ષ હોય પણ તે વાયુની ઝડી લાગે ત્યારે ડગે છે, પણ નાનો પર્વત હોય તો તેનાં મૂળ ક્યારેય ડગતાં નથી. તેને ઊધઈ અને અગ્નિનો પણ ભય નથી. માટે વિપરીત દેશકાળમાં પણ જેનો સત્સંગ અડગ હોય અને તે સમાધિહીન હોય પણ પાકો છે. અને સમાધિવાળો હોય અને તેને દેશકાળ લાગે તો તે કાચા બાળક જેવો છે. બાળકને બોરમાં રસ મનાય છે, તેને ચિંતામણિ હાથમાં આવે તો ફેંકી દે. તેમ સત્સંગરૂપી ચિંતામણિનો મહિમા જેને બાળબુદ્ધિ ન હોય તેને જ સમજાય છે. બીજાને તો સમાધિ હોય તેટલી જ વાર આશ્ચર્ય રહે છે અને પછી દેહાકાર થઈ જાય છે અને આશ્ચર્યમાં ભૂલી જાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":918,"k":"para","g":"ગોપ-ગોપીઓને ભગવાન આશ્ચર્ય દેખાડતા પણ તે ભૂલી જતાં, નારદજી ભૂલ્યા નહિ. ઉદ્ધવને પણ એવું જ્ઞાન હતું. તે પ્રતાપ દેખાય કે ન દેખાય અપાર મહિમા સમજતા. અક્રૂર સમાધિનિષ્ઠ હતા પણ દેશકાળથી મતિમાં મોહ થયો અને સમાધિ કામ આવી નહિ. માટે નિષ્કામ ભક્ત થવું એ સૌથી કઠણ છે.","e":null,"s":["10/22/27-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":919,"k":"para","g":"શૂરવીરતા સમય ઉપર જણાઈ આવે. સૌ હરિભક્તની સમજણ એક હોય નહિ. દેશકાળે કરીને હરિભક્તોનાં વર્તન એક સરખાં રહે નહિ. શૂરવીર કાયર થાય અને કાયર શૂરવીર થઈ જાય, પણ ભક્તપણામાં જે માન તે ભગવાનને ગમતું નથી.","e":null,"s":["10/45/9-11"],"sv":[],"mt":false,"gl":null,"a":true},{"i":920,"k":"para","g":"વિપત્તિરૂપી કસોટી વિના ભક્ત ઓળખાય નહિ. પ્રહ્‌લાદ, બલિ, ધ્રુવ, મયૂરધ્વજ, હરિશ્ચંદ્ર, દધીચિ, રામ, સીતા, લક્ષ્મણ, પાંડવ, કુંતા, દ્રૌપદી, ગોપ, ગોપી, નંદ, જશોદા, વસુદેવ, દેવકી તથા વિદુરજી વગેરેએ અતિકષ્ટ પામવા છતાં સત્સંગનો પક્ષ રાખ્યો. જ્યાં અનંત સુખનો લોભ હોય, ત્યાં પ્રથમ દુઃખ તો આવે જ. માટી કે ધાતુના ઘાટ બનાવે તથા અનંત જાતનાં પકવાન કરાવે તે અગ્નિની કસોટીમાં પસાર થાય ત્યારે જ સિદ્ધ થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":921,"k":"para","g":"ભક્તને જે કષ્ટ આવે છે તે ભગવાનથી અજાણ્યાં નથી. ભક્ત જેટલું સહન કરે છે તેથી કરોડગણું સુખ ભગવાન પ્રસન્ન થઈ તેને આપે છે. પછીથી કાંઈ વિઘ્ન ન રહે. ભગવાનનો આવો નિશ્ચય જેને હોય તે દિવસે દિવસે વૃદ્ધિ પામે અને કોટિ વિઘ્ને પણ પાછો હઠે નહિ.","e":null,"s":["10/54/17-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":922,"k":"para","g":"સોરઠનાં જેટલાં બાઈ-ભાઈઓ હતાં તે સૌ સત્સંગના સ્તંભ જેવાં હતાં, પણ કોઈના કળ્યામાં આવતાં નહિ. શ્રીહરિનાં વચન પ્રમાણે વર્તતાં. સંસારમાં હાણ-વૃદ્ધિ થાય તેનો હર્ષ-શોક રાખતાં નહિ, પણ ઘરમાં મહેમાન થઈને રહેતાં. જેથી કોઈનું મરણ થતાં વિયોગનું દુઃખ થતું નહિ. અને ધ્યાન-ધારણાનો અભ્યાસ રાખતાં જેથી ગૃહસ્થાશ્રમી હોવા છતાં જોગી જેવાં હતાં. કોઈ મારે કે ગાળ દે તો મોઢેથી વચન બોલતાં નહિ. તથા કોઈની સાથે વિરોધ કે વૈર થાય તેવી ક્રિયા કરતા નહિ. ખાવા-પીવા માટે ક્લેશ કરતા નહિ. સત્સંગને માટે તન, મન, ધન કોઈ પણ કામ ન લાગે તેને કુસંગ સમજતા. પશુ, વાહન, ખેતી, આ બધું સત્સંગના કામમાં ન આવે તો તેને ભોગવતા નહિ. વસ્ત્ર, ભોજન, આભૂષણ આદિ પણ સત્સંગમાં કામ ન લાગે તો વાપરતા નહિ. એવા હરિભક્તોનાં દર્શન કરવા શ્રીહરિએ બીજા દેશના હરિભક્તોને તેડાવ્યા. દરેક દેશના હરિભક્તોને વર્ષમાં એકવાર શ્રીહરિ ભેગા કરતા, જેથી સત્સંગની પરસ્પર સમવૃદ્ધિ થતી અને પોતપોતાની ન્યૂનતાને ઓળખીને ચઢતો રંગ રાખતા, ભેગા ન થાય તો આ બધું સમજાય નહિ.","e":null,"s":["11/46/25-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":923,"k":"para","g":"અક્ષરના એક રોમમાં અનંતકોટિ બ્રહ્માંડ રહ્યા છે. એ શ્રીહરિના અક્ષરધામમાં અનંતકોટિ અક્ષરમુક્તો શ્રીહરિની સેવા દાસભાવે કરે છે. આ વાત એ જ ભક્ત સમજી શકે છે કે જેની બુદ્ધિમાં પ્રકાશ થયો હોય. જેટલો પ્રકાશ તેટલો વાતનો પ્રસંગ સમજે. આકાશના બધા તારા સરખા નથી, સૂર્ય જુદો છે, તેના પ્રેકાશ પાસે તારાનો પ્રકાશ કાંઈ નથી. તેમ બધાની બુદ્ધિ સમાન નથી. ભગવાનના ભક્ત અનંત છે, તેમ બુદ્ધિમાં ભેદ પણ અનંત છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":924,"k":"para","g":"અનંતકોટિ સૂર્યનો પ્રકાશ જેના એક એક રોમમાં ભર્યો છે એવા શ્રીહરિ પરમ દયાળુ છે. તે જેની સામે કૃપાએ કરીને જુએ છે તેની બુદ્ધિમાં એવો અનંત પ્રકાશ આવે છે. હરિની કૃપાચક્ષુ દ્વારા અણુ પણ મેરુ બને. તે સુમતિ પુરુષ જાણે છે. કુમતિ જનની બુદ્ધિ અંધ તમસ જેવી રહે છે.","e":null,"s":["11/56/31-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":925,"k":"para","g":"શ્રીહરિ પોતાની મરજીમાં વર્તાવે અને અનેક પ્રકારે ઇચ્છામાં આવે તેમ તાવણી કરે તોપણ નારી અને ધનનો જેમ અભાવ આવતો નથી, તેમ હરિનો અને સંતનો અભાવ ન આવે, દિન દિન પ્રતિ ભાવ વધતો રહે એવા જનો હોય તે સાચા ભક્તો છે.","e":null,"s":["12/19/19-20"],"sv":[],"mt":false,"gl":null,"a":true},{"i":926,"k":"para","g":"સાચો હરિભક્ત સંત, ગુરુ ને મંદિરની કોઈ પણ વસ્તુ ભોગવવાની ઇચ્છા ન કરે, સેવાથી પ્રસન્ન થઈ, ગુરુ જે પ્રસાદ આપે તે આદરથી લે. બને તેટલી સેવા કરે. બીજાની ઈર્ષ્યા કરે નહિ. પરસ્પર મોટાઈ સમજે. ભગવાન, સંત ને લોકનો ડર રાખે તે ધર્મવંશી છે. અને ભગવાન, સંત, લોક, નીતિ, શાસ્ત્ર અને રાજાનો ડર ન રાખે તે અધર્મવંશી છે. અધર્મવંશીનું બળ ચઢે ત્યારે દૈવીજનો ધર્મવંશી સંતોને પૂછીને યોગ્ય માર્ગ પર ચાલે છે. અધર્મવંશી તો માણસને મારી નાખે તો પણ તેના મનમાં ક્યારેય ક્ષોભ થતો નથી. અધર્મવંશી વધે છે ત્યારે સાચા ગુરુ ને સંતો લોકોને સદ્‌બુદ્ધિ આપતા રહે છે, ને માતા-પિતાથી પણ અધિક ઉપકાર કરે છે.","e":null,"s":["19/5/11, 14, 24-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":927,"k":"para","g":"જેને અન્ન-ધનની સહાય ન હોય તેવા ગરીબ હરિભક્તની સંભાવના સમર્થ હરિભક્ત ન રાખે તો સાચો હરિભક્ત નથી. ગરીબ હરિભક્તની જેટલી સંભાવના રાખે તેટલો મોટો હરિભક્ત કહેવાય. પર્વતભાઈ, ઝીણાભાઈ કાશીદાસ અને વડોદરાના સદાશિવને ગરીબ હરિભક્તો ઉપર બહુ દયાભાવ રહે છે. હરિભક્તોનો ધર્મ જે જીવતા સુધી દૃઢ રાખે અને રખાવે તે સર્વોપરી હરિભક્ત છે. કોઈ હરિભક્તને સત્સંગ નિમિત્તે દુઃખ આવ્યું હોય તો બીજા હરિભક્તને તેનું કષ્ટ નિવારણ થાય તેવો ઉપાય કરવો. હરિભક્તોમાં જેવો સંપ હોય તેવો સત્સંગ રહે છે. કુસંપ હોય તેટલો કુસંગ પ્રવેશ કરે છે. માટે હરિભક્તે કુસંપનો ત્યાગ કરવો.","e":null,"s":["20/29/1-16"],"sv":[],"mt":false,"gl":null,"a":true},{"i":928,"k":"para","g":"હરિભક્ત થયા છતાં હરિ નિમિત્તે ધન વાપરવામાં સંકોચ રહે અને સંસાર નિમિત્તે જ્યાં જ્યાં જરૂર પડે ત્યાં વારે વારે ખર્ચે તેને સંસાર મુખ્ય છે એમ કહેવાય. ધનથી ગરીબ હોય પણ ભગવાન અને સંતને મુખ્ય રાખે અને સંપત્તિ પ્રમાણે ખર્ચ કરે તેને ભગવાન મુખ્ય છે એમ કહેવાય. ઉત્સાહથી સેવા કરે તેટલી સંપત્તિ વધતી રહે છે. ભગવાન અને સંતના કામમાં આવે તેટલું જ અન્નધનાદિક સાચું છે. આવી સમજણ અલ્પ પુણ્યથી આવતી નથી. હરિભક્ત એમ સમજે છે કે ભગવાન અને સંત વિના બીજા નિમિત્તે મેરુ તુલ્ય પુણ્ય થાય તોપણ તેનું ફળ અલ્પ છે. વર્તન ઉપરથી સંત-હરિભક્તોની ઓળખાણ થાય છે.","e":null,"s":["22/64/4-26"],"sv":[],"mt":false,"gl":null,"a":true},{"i":929,"k":"para","g":"હરિભક્ત હોય તે ભગવાન ને ભગવાનના સંતનું અપાર માહાત્મ્ય સમજે. તેને દોષદૃષ્ટિ હોય નહિ, નિષ્પાપ વર્તે, ધર્મ-નિયમ દૃઢ પાળે અને મનમાં એવાં મનોરથ રહ્યા કરે કે ભગવાન અને સંતને અર્થે ન અપાય એવો કોઈ પદાર્થ અધિક નથી, તો ભગવાન તેનાથી દૂર રહેતા નથી.","e":null,"s":["25/11/9-12"],"sv":[],"mt":false,"gl":null,"a":true},{"i":930,"k":"para","g":"ભગવાનનો ખપ હોય તે જ મોક્ષને માર્ગે ચાલે છે. હરિભક્તે હરિભક્તમાં વિક્ષેપ કરવો નહિ. હરિભક્તમાં મન મળે તે જ સાચો ભક્ત છે. પાંચ હરિભક્તો સાથે મન મળે નહિ તે બુદ્ધિશાળી હોય તોપણ માની ભક્ત કહેવાય. મંદિરમાં નિત્ય આવે, કથા-કીર્તનનો નિયમ રાખે, હરિભક્તને ભાવથી નમે અને નિષ્કપટભાવે હરિભક્તને પોતાનાથી શ્રેષ્ઠ માને, કદી ક્રોધ ન કરે તે હરિભક્તની સાચી રીત છે.","e":null,"s":["27/52/12-17"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":13,"gu":"દાસપણું","en":"Dāspanu — Servitude","url":"https://www.anirdesh.com/pbp/index.php?page=chp_13","b":[{"i":931,"k":"para","g":"શ્રીહરિએ માતાને ઉપદેશ દેતાં કહ્યું, “માનમાત્રને તજીને ભગવાનના દાસ થઈને વર્તવું અને સમયે સમયે સેવામાં હાજર રહેવું તેને દાસભક્તિ કહેવાય છે. ભગવાનને માટે જે કાંઈ જળ, પુષ્પ, તુલસી, ચંદન, ભોજન વગેરે જોઈએ તે પોતે જાતે તૈયાર કરે અને ઋતુને અનુસારે વિનયપૂર્વક તે તે વસ્તુ અર્પણ કરવામાં તત્પર રહે, તે દાસભક્તિ કહેવાય છે. દાસભક્તિ યુક્ત પુરુષ ગમે તેટલો મહાન હોય તોપણ ભગવાનની નીચામાં નીચી કોઈ પણ ટહેલ કરવામાં તથા મંદિરમાં વાળવું, લીંપવું વગેરે ક્રિયામાં સહેજ પણ માન નહિ રાખતાં, પોતાનાં અહોભાગ્ય સમજે છે તથા બીજા ભક્તોને પોતાથી અધિક માની તેમને નમતો રહે છે, તેમની સાથે કપટ રાખતો નથી.”","e":null,"s":["1/67/12-22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":932,"k":"para","g":"સરધારમાં શ્રીહરિએ વાત કરતાં કહ્યું, “બીજાનો મહિમા સમજી સેવા કરે ને પોતાના દોષ જુએ તે દાસ. દાસનો દાસ થાય તે જ સિદ્ધ છે. ધ્યાન, ભજન, યોગાભ્યાસ, જપ, તપ, ત્યાગ, વૈરાગ્ય વગેરેનું ફળ એટલું જ છે જે પોતાને ભગવાનના ભક્તના દાસનો દાસ માને. ભક્તના દાસનો દાસ થઈને રહે તેને જ અમે શ્રેષ્ઠ માનીએ છીએ.”","e":null,"s":["3/56/29-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":933,"k":"para","g":"રાજકોટમાં શ્રીહરિએ ડુંગરજી અને અલર્ક નૃપ વગેરે ભક્તોને વાત કરતાં કહ્યું, “નાનો સંત હોય તેના પણ દાસાનુદાસ થવું, કારણ કે નાનો તણખો પણ બ્રહ્માંડનો નાશ કરવા સમર્થ છે. કોઈ ગુણનું માન સંત પાસે ન રાખવું. જે અભિમાન રાખે છે, તેના પ્રત્યે અમને સહેજે અરુચિ રહે છે. સરલચિત્ત રહેવું, તે અનંત ગુણોનું મૂળ છે. સરળતા વિના મેરુ જેટલા ગુણ હોય, તોપણ ટકતા નથી.”","e":null,"s":["5/13/61-63"],"sv":["अल्प संत होय ताहि के, रेहेना दास हि होय ।\n\n अल्पाग्नि ब्रह्मांड को, नाश करे पल सोई ॥\n\n अभिमान कोई गुन को, संत से रखना नाहि ।\n\n अभिमानी जन उपरि, अरुचि अमार रहाहि ॥\n\n सर्ल चित्त होय जाहि, अनन्त गुन को मुर एहि ।\n\n ता विन और न रहाहि, मेरु सम होय गुन तेहि ॥"],"mt":false,"gl":null,"a":false},{"i":934,"k":"para","g":"અલૈયા ખાચરને શ્રીહરિ વાત કરતાં કહે, “બહુ છક છે તે અનંત દોષનું મૂળ છે. ભવ-બ્રહ્માદિકને છકને લઈને વિઘ્ન આવ્યાં. માટે દાસના દાસ થઈને રહેવું. દાસના દાસ થઈને રહે તેને વિઘ્ન નડતાં નથી. પૂર્વે ઉદ્ધવ, પ્રહ્‌લાદ થઈ ગયા તેની રીતિ જોવી. તે ભક્તોમાં શિરોમણિ હતા તો પણ તેમણે દાસના દાસ અને તેના પણ દાસ થવા વર માગ્યા છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":935,"k":"para","g":"“દાસ થઈને સેવા કરે તેનાથી વિઘ્ન બધાં ડરીને દૂર ભાગે છે. દાસાનુદાસ થઈને જે ભક્તની સેવા કરે તે સેવાથી જેવા ભગવાન પ્રસન્ન થાય છે તેવા બીજા કોઈ સાધનથી પ્રસન્ન થતા નથી. હરિજનમાં જે મોટેરો કહેવાતો હોય તેને ભક્તની સેવારૂપી સાધનમાં જો પ્રીતિ ન હોય તો તેને મનુષ્ય જાતિમાં ન માનવો. તેને ભૂત-પ્રેતનો અવતાર મળે છે. વળી, તેને માથે કોઈ રક્ષાનો કરનાર ન હોવાથી જમકિંકર તેનો રક્ષક બને છે. હરિભક્તોમાં જે મોટેરો થઈને ફરે તેથી તે હરિજનની સેવા કરે નહિ, પણ હરિજનો પાસે પોતાની સેવા કરાવે છે તે તો મોટા પર્વતના દેહને પામે છે.”","e":null,"s":["5/53/1-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":936,"k":"para","g":"જેતપુરમાં શ્રીહરિ રામદાસ સ્વામી અને સંતોને કહેવા લાગ્યા, “જે સેવક સરળ ચિત્તવાળા, માન વિનાના, ક્રિયામાં નિપુણ, કોઈનાં છિદ્રો કહે નહિ તેવા, હરિજનોના દાસ થઈને રહેતા હોય, ખાવા-પીવાની વસ્તુ કોઈને આપ્યા વિના ખાતા ન હોય, કોઈનું કામ બગાડતા ન હોય, કોઈ પર ક્રોધ કરતા ન હોય - એવા સેવક ઉપર અમારે ભાવ રહે છે. એવા તો એક મુકુંદાનંદ છે. અમે ક્યારેક તપીએ છીએ, પણ એમની વૃત્તિ તો એકધારી શાંત છે.”","e":null,"s":["6/60/11-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":937,"k":"para","g":"બુધેજમાં શ્રીહરિએ વાત કરતાં કહ્યું, “સંત-હરિજનોમાં જેને ભાવ હોય તેને સેવાનો ઉત્સાહ રહે છે. સત્સંગની સેવા તે જ મોક્ષપદ છે. સત્સંગમાં સેવા કરે છે તેને અમે ધામમાં જ દેખીએ છીએ. ધામમાં રહીને અમે બધાને પીરસીએ છીએ તે તમને દેખ્યામાં આવતું નથી. તમને પીરસવાની અમને વારે વારે શ્રદ્ધા જાગે છે. તમે બધા સંતો, વર્ણી અને પાર્ષદો સેવા કરો છો તેથી તમારાં ધન્ય ભાગ્ય છે. તમે જે સેવા કરો છો તેને ભવ-બ્રહ્માદિ દેવતાઓ ઇચ્છે છે, પણ તેને મળતી નથી. એવી સેવા મળી છે છતાં તેને મૂકીને બીજી ઇચ્છા રહેતી હોય તેને ભિખારી જાણવો. જેમ રાજાએ ભીખતી વાઘરણને રાણી બનાવી, કંચનના મહોલમાં રાખી, દાસ-દાસીઓને તેની સેવામાં રાખ્યાં. વિવિધ પકવાન મળતાં, અંગ પર સુવર્ણ-મોતીના ભૂષણનો પાર નહિ, પણ તેને ભીખવાની ટેવ હતી તો રાજમહેલ તેને બંદીખાનું લાગ્યું ને સાહ્યબી બધી અંગારા તુલ્ય લાગી. તેમ સેવા વિના જે બીજું ચિંતવે છે તે બધાય ભિખારી છે.”","e":null,"s":["9/8/33-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":938,"k":"para","g":"સારંગપુરમાં શ્રીહરિએ હરિજનોને વાત કરતાં કહ્યું, “જગતમાં જે પ્રભુ ન હોય છતાં પ્રભુ થઈને બેસે તેને અમે પાપી માનીએ છીએ. નિત્ય તેને આખા બ્રહ્માંડનું પાપ લાગે છે. તેમાં જેટલી પ્રભુતા હોય તે જણાયા વિના રહે નહિ. જેમ સૂર્યનો ઉદય થાય તે કોઈને કહેવું પડતું નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":939,"k":"para","g":"“મનુષ્યમાત્રને મોટા થવાની હોંશ છે, પણ સૌના દાસ થયા વિના મોટાઈ મળે નહિ. અમે તો મોટાઈમાં સુખ માન્યું જ નથી. જેવી સ્વામીની મરજી તેમાં અમે સુખ માન્યું છે. પછી ક્યારેય દુઃખ રહેતું નથી. અમારી પેઠે માને તેને પણ સુખનો માર્ગ મળે. અંત સમે તેની સહાય પણ અમે કરીએ.”","e":null,"s":["9/32/8-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":940,"k":"para","g":"શ્રીહરિએ અલર્ક રાજાને કહ્યું, “હરિભક્તોનો દાસ થઈને રહે તે બુદ્ધિમાન છે. દાસને ક્યારેય દુઃખ હોતું નથી. મોટાને જ દુઃખ હોય છે, કારણ કે તેમાં જેટલું માન હોય તેટલું દુઃખ થાય છે.”","e":null,"s":["9/42/14-15"],"sv":[],"mt":false,"gl":null,"a":false},{"i":941,"k":"para","g":"કરિયાણામાં ઓઢા ખાચરના ભવનમાં શ્રીહરિ કહે, “સંત-હરિભક્તોના દાસ થવાનો નિત્ય અભ્યાસ રાખવો. પોતાથી તેમને અધિક સમજવા અને સદા ગરજુ રહેવું. ક્યારેય તેમની સાથે બખેડો કરવો નહિ. જેટલો વિરોધી થઈને વર્તે તેટલો તેમાં ફરક સમજવો. વર્તન ઉપરથી જ જેટલો સત્સંગ થયો હોય તેટલો ઓળખવામાં આવે છે. અંતરમાં ફરક હોય તે ઉપરથી દેખાય નહીં. પણ સત્સંગ સૂર્ય જેવો છે, તે વર્તનમાં જ દેખાડી દે છે.”","e":null,"s":["10/9/22-25"],"sv":[],"mt":false,"gl":null,"a":false},{"i":942,"k":"para","g":"જેતપુરમાં મૂળુવાળાના ભવનમાં શ્રીહરિએ વાત કરતાં કહ્યું, “જે જ્ઞાની જનો છે તે ક્યારેય અજ્ઞાનીના નોરમાં ચાલે નહિ, આ લોકના અનિત્ય ભોગમાં બંધાય નહિ, તથા પંચવિષયને નીરસ માને છે. મૂર્તિમાં રસ લાગ્યો હોય તેને ખાવું-પીવું પણ ગમતું નથી. અન્ય રસમાત્ર ખારા થઈ જાય છે. શુદ્ધ ચિત્ત વિના અતિ શુદ્ધ મૂર્તિ ધાર્યામાં આવે નહિ. અભ્યાસ કરીને દેહ અને બ્રહ્માંડના ભાવમાં વૈરાગ્ય પામે અને જે જે ક્રિયા કરે તે મૂર્તિ ધારીને કરે. મૂર્તિને મૂકીને એક પણ ક્રિયા કરે નહિ. મૂર્તિ વિના અન્ય સર્વનો જ્ઞાનપ્રલય કરી નાખે. જેમ અતિશય ગરીબ માણસ હોય અને તેને અતિ તૃષ્ણા હોવા છતાં અન્ન-વસ્ત્ર મળતું ન હોય તેને અચાનક બ્રહ્માંડનું રાજ્ય આવી પડે ને જેવું સુખ થાય તેથી કરોડ ઘણું સુખ મૂર્તિમાં રહ્યું છે. આવી જ્ઞાનદૃષ્ટિ સાથે મોટાનો વિશ્વાસ રાખે તે સમાન મોટો કોઈ દાસ નથી.”","e":null,"s":["10/17/13-25"],"sv":[],"mt":false,"gl":null,"a":false},{"i":943,"k":"para","g":"શ્રીહરિએ માંડવીમાં વેદાંતીને વાત કરતાં કહ્યું, “પરબ્રહ્મ પુરુષોત્તમ ભગવાનનું પાકું જ્ઞાન મેળવી, તેમના દાસ થઈને દેહ અને બ્રહ્માંડથી પર વર્તે ત્યારે બ્રહ્મભાવ આવ્યો કહેવાય. જે બ્રહ્મરૂપે વર્તે છે તે આત્મા(અક્ષરબ્રહ્મ)ને પરમાત્માને, તેમના ભક્તોને તથા શ્રીહરિના દિવ્ય ધામને સત્ય માને છે. અને તે વિના અન્ય આકારમાત્રને દેખે, કે કાને કરીને સાંભળે પણ તેને લેશ પણ સત્ય માનતા નથી. તે (માયામય સઘળું) નાશ પામે ત્યારે શોક કરતા નથી. નાશવંત વસ્તુ પાછળ મનુષ્યને જ્યાં સુધી શોક થાય છે ત્યાં સુધી તેનું જ્ઞાન મિથ્યા છે. ભલે તે વિવિધ પ્રકારે તેનો બોધ કરાવતો હોય!”","e":null,"s":["11/3/36-40"],"sv":["ताके दास हि होई कर, ब्रह्मांड देह सें पर ।\n\n वरते जन यह जब हि तब, ब्रह्म होवत हि वर ॥\n\n आत्मा अरु परमात्मा, ताके भक्त हि जेह ।\n\n दिव्य हरि के धाम जो, सत्य हि जाने तेह ॥\n\n ता विन ओर आकार, देखे सुने यह श्रवण कर ।\n\n सत्य न माने लगार, नास भये न शोक करत ॥\n\n नाशवंत की शोक, करे जन ज्यां लग जेहि ।\n\n ज्ञान ताको सब फोक, कथे विविध प्रकार कर ॥"],"mt":false,"gl":null,"a":false},{"i":944,"k":"para","g":"જૂનાગઢમાં શ્રીહરિ કહે, “અભાવ અરુચિ વર્તે અને સેવા કરવામાં ઉમંગ ન જાગે તો જાણવું તેને સત્સંગમાં પ્રીતિ નથી. ધ્યાન કરે તોપણ સેવામાં તાન ન હોય તો ધ્યાન મિથ્યા છે. સમાધિ, ધ્યાન, ધારણા, જપ-તપ, તીર્થ, દાન-પુણ્ય અને આત્મનિષ્ઠા એ બધાંય સાધનોનું ફળ સેવા છે. સેવા વિનાનાં સાધન તે ફળ વિનાનાં વૃક્ષ જેવાં છે. ચિત્રકેતુ, ઇન્દ્ર વગેરે ઘણાય દેવ મનુષ્યોએ સેવાથી મોટાઈ મેળવી છે અને માને કરીને પડી ગયા છે.”","e":null,"s":["11/60(50-b)/21-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":945,"k":"para","g":"વર્ણીને શ્રીહરિ કહે, “સેવા સમાન કોઈ કસોટી નથી. સેવા બધાંય સાધનોનું મૂળ છે.”","e":null,"s":["11/57/25"],"sv":[],"mt":false,"gl":null,"a":false},{"i":946,"k":"para","g":"વર્ણી પ્રત્યે શ્રીહરિએ કહેલી વાત મુક્તમુનિએ સભાજનોને કહી, “શ્રીહરિ કહે - હરિજન સેવકની એવી રીત છે કે ગુરુ-સંતની સેવા પરમ પ્રીતિ ને રસપૂર્વક કરે છે. દાસ થઈને જે જે સેવા જે પ્રકારે કરે તે હરિજન તે પ્રકારના થાય છે. નાનપ-મોટપ સેવામાં રહેલી છે. જેવી ખેતી કરે તેવી ઊપજ મળે. સ્વાતિ નક્ષત્રની વર્ષાનાં બૂદ એક પ્રકારનાં છે, પણ પાત્ર પ્રમાણે ન્યારા ન્યારા ગુણ પ્રગટે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":947,"k":"para","g":"“રોગ કરોડ પ્રકારના હોય છે. બધા રોગનું ઔષધ એક નથી, જુદું જુદું છે. વળી, રોગની ગુણવત્તા જાણીને ઔષધ આપે તે જ ઔષધ ગુણ કરે છે. ઔષધના જેટલા ગુણ છે તે સઘળા એક અમૃતમાં સમાઈ જાય છે. શ્રીહરિ અને સંત ગુરુની વાત અમૃત તુલ્ય જાણવી. કુમતિ જન જો એ અમૃત-ઉપદેશને વિષ માને તો તેને વિષ તુલ્ય ફળ આપે છે. એમ, વાતને માને ને ન માને તે પર સન્મુખ અને વિમુખના ભેદ પડે છે. હરિ-ગુરુની વાતને શ્રદ્ધાપૂર્વક ઝીલે ને અંતરમાં ઉતારે તેને માટે તે અમૃતનું ફળ આપે છે. આહાર જે રીતે કરે તેવું તેને ફળ મળે. જે આહાર જિવાડે છે તે જ આહાર મારે છે. તેમ સત્સંગ કરતાં કરતાં ઘટી પણ જાય છે ને વૃદ્ધિ પણ પામે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":948,"k":"para","g":"“આ બધાં દૃષ્ટાંતનું સિદ્ધાંત એટલું છે કે દાસપણે ભગવાન અને ભગવાનના ભક્તની સેવા કરવી. જે રીતે પૂર્વે ભક્તોએ સેવા કરી છે તે રીતે શુદ્ધ મને કરીને કરવી. કારણ, આ વખતે સત્સંગમાં ધામના મોટા મુક્તોએ દેહ ધર્યા છે ને નારદ, શુક, સનકાદિક અનંત મુક્ત પણ આવ્યા છે.”","e":null,"s":["11/58/29-40"],"sv":["हरिजन सेवक कर इस रीता । गुरु संत की परम रस प्रीता ॥\n\n जो जो सेव करे जिस रीति । भये सो हरिजन तिस रीति ॥\n\n हरि गुरु संत की बात जेहु । अमृत तुल्य जानना तेहु ॥\n\n भगवान के भक्त अपार, हो गये सेव करत जेहि ।\n\n करना तेहि प्रकार, सेव सो शुद्ध मन होई ॥\n\n सत्संग में अब वार, धाम के बडे मुक्त जेहु ।\n\n आये वार न पार, नारद शुक आदिक अनंत ॥"],"mt":false,"gl":null,"a":false},{"i":949,"k":"para","g":"મુક્તમુનિ કહે, “શ્રીહરિ કહેતા કે - મનુષ્ય તન પામીને ચક્રવર્તી રાજ્ય મળે પણ ભગવાનનો દાસ ન થાય તો તેનાં દુઃખનો અંત આવતો નથી.”","e":null,"s":["11/70(60)/13"],"sv":[],"mt":false,"gl":null,"a":false},{"i":950,"k":"para","g":"કારિયાણીમાં શ્રીહરિએ વાત કરતાં કહ્યું, “આંખમાં સેવાનો ગુણ વસી જાય પછી તેના દુર્ગુણ કે અવગુણ નજરમાં આવતા નથી. સેવાનું આ અંજન અન્ય પંચરસના અંજન કરતાં પણ શ્રેષ્ઠ છે. ધનનું અંજન પણ આ અંજન પાસે ઝાંખું પડે છે. ભવ-બ્રહ્મા જેવા કોઈ સિદ્ધ, સમર્થ ને અંતર્યામી નથી, પણ કોઈ અસુર જો તેની આરાધના - સેવા કરે તો તેને વર દઈ દે છે. સેવકાઈ પાસે અનંત દોષ ઢંકાઈ જાય છે. સેવા જોઈ અંતર્યામી દેવ પણ અંધ બની જાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":951,"k":"para","g":"“સેવાથી હેત બંધાય છે, પછી તેનું બંધન થવાથી મન તેનો અભાવ જોતું નથી. અભાવ આવે ત્યાં સુધી સેવામાં કાચપ છે.”","e":null,"s":["12/43(42)/33-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":952,"k":"para","g":"ગઢપુરમાં પ્રાગજી પુરાણી પાસે મહાભારતનું શાંતિપર્વ વંચાવીને શ્રીહરિએ વાત કરતાં કહ્યું, “ભગવાનનો દાસ થાય તો તેનામાં ભગવાનના જેવા ગુણો આવે છે. સંતનો દાસ ન થાય કે હરિભક્તનો દાસ ન થાય તો તુચ્છ કીટમાં નિવાસ કરે છે. અનંત મહત પુણ્યે કરીને દાસપણું મળે છે. જે દાસાનુદાસ રહે છે તે વધતો વધતો વધી જાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":953,"k":"para","g":"“ચિંતામણિ, પારસમણિ કે કલ્પવૃક્ષ તેના કરતાં પણ દાસપદ ઊંચું છે, શ્રેષ્ઠ છે, અધિક છે. ઈશ્વરો, અક્ષરમુક્તો કે રાધા-રમાદિ ભક્તો દાસપણાના ગુણથી જ તે સ્થિતિને પામ્યા છે. ભગવાન અને ભગવાનના સંતની સેવા કોટિ કલ્પ સુધી કરે અને ક્યારેય બરોબરિયાપણું આવવા ન દે, દાસના દાસનો દાસ થઈ રહે ત્યારે શ્રીહરિ તેને ‘દાસ’ની પદવી આપે છે. દાસ પદવી પરથી પર પદવી છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":954,"k":"para","g":"“પોતે જ ભગવાન થઈ બેસે છે તેના પર શ્રીહરિનો કોપ ઊતરે છે. ને શ્રીહરિ કોપે તેના પર સંતનો કોપ પણ થાય છે. તેથી તેનામાં હદ વગરની કુમતિ પેદા થાય છે અને તે પાપે કરીને અસુરનું આચરણ થઈ જાય છે. તે હરિજનોને વાત કરે છે કે, પોતાનાથી કોઈ મોટું નથી. અંતે એ અસુરનો નરકમાં નિવાસ થાય છે. સત્સંગના દાસ થઈને વર્તે નહિ અને બહુ ધ્યાન અને જ્ઞાન કરતા હોય તથા તપ પણ અન્ન તજીને કરતા હોય તોપણ તેમનો વિશ્વાસ કરવો નહિ. દાસપણું રાખવાથી દિવસે દિવસે વૃદ્ધિ પમાય છે.”","e":null,"s":["12/71(70)/36-47"],"sv":[],"mt":false,"gl":null,"a":false},{"i":955,"k":"para","g":"ઘોડાસરમાં શ્રીહરિએ વાત કરતાં કહ્યું, “દુઃખી (રોગી) સંતની સેવા કરે તેને કરોડ મહાપાપ લાગ્યાં હોય તોપણ નાશ પામે. દુઃખી સંતની સેવા કરનાર ધ્યાનમાં મૂર્તિનો સાક્ષાત્કાર કરે તેના કરતાં પણ અધિક છે. કોઈ પણ પદાર્થની લાલચ વિના જેઓ સેવાની ભાવનાથી જ સેવા કરે તે ભગવાનના ધામમાં જાય છે. લાલચથી સેવા કરે તે ધામને પામે નહિ.”","e":null,"s":["13/15/12-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":956,"k":"para","g":"ગઢપુરમાં વણિક પાસે વાત કરતાં શ્રીહરિ કહે, “મોટા મોટા ભક્તો થયા તેમણે ભગવાનને ભગવાનના ભક્તની સેવા કરી છે. સેવામાં અનંત અપાર સાધન લીન થઈ જાય છે. સંતોની જાણે-અજાણે જે સેવા કરશે તે પરમ મોક્ષને પામશે એમાં સંદેહ નથી.”","e":null,"s":["13/46/22,40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":957,"k":"para","g":"ગઢપુરમાં સંતો-ભક્તોને ઉદ્દેશીને શ્રીહરિએ કહ્યું, “ભગવાનના કેટલાય અવતારો થયા છે અને તે દરેકના જુદા જુદા ભક્તો થયા છે, તે બધા ભગવાનના દાસ થઈને રહ્યા છે, પણ કોઈ સ્વામી થઈને બેઠું નથી. કોઈ પણ થયો હોય તો બતાવો. આ મોક્ષની ગાદી સનાતન છે ને એક ચાલી આવે છે. તેના પર ગુરુએ કોટિવાર નિરધાર કરીને અમને બેસાર્યા છે. તેના પર બીજો કોઈ ભગવાન થઈને બેસે તે માયાનો જીવ કહેવાય. તેને તો કોટિ ગૌહત્યા જેટલું પાપ લાગે છે. જગતના બધા રાજા થઈ શકતા નથી. જેનામાં રાજાની લાયકાત હોય તે રાજા થાય છે. બીજો રાજા થવા જાય તો દુઃખના કૂવામાં પડે. પોતાને ભગવાન કહે તે અધમમાં અધમ છે, નીચમાં નીચ છે ને પાપીમાં પાપી છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":958,"k":"verse","g":"‘અધમ મેં અધમ જેતે, પાપિ મેં પાપિ પ્રબલ જેહિ,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":959,"k":"verse","g":"ભગવાન હોત જન તેતે, નીચ મેં નીચ ભગવાન હોત.’","e":null,"s":["13/59/20-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":960,"k":"para","g":"ગઢપુરમાં સંતો-ભક્તોને ઉદ્દેશીને શ્રીહરિએ કહ્યું, “ભગવાન સિવાયના ભગવાન તરીકે પૂજાવા જાય છે તેના પૌંડ્રક જેવા હાલ થાય છે. અંતે નરકનો તે અધિકારી બને છે અને અતિ દુઃખને પામે છે. અત્યંત કઠિન સાધનો કરી કરીને મરી જાય, તોપણ અક્ષરબ્રહ્મ પર્યંત કોઈ ભગવાન થવાને સમર્થ થતું નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":961,"k":"para","g":"“પૃથ્વી પરના બધા રાજાનો પ્રતાપ એક દેવતાના રોમમાં સમાઈ જાય છે. બધા દેવતાનો પ્રતાપ કશ્યપ પ્રજાપતિના એક રોમમાં સમાઈ જાય છે. કશ્યપનો પ્રતાપ મરિચ્યાદિકના રોમમાં, મરિચ્યાદિકનો પ્રતાપ બ્રહ્માના એક રોમમાં, બ્રહ્માનો પ્રતાપ વૈરાટનારાયણના એક રોમમાં સમાઈ જાય છે. તેમ વૈરાટનો મહત્તત્ત્વના રોમમાં, મહત્તત્ત્વનો અહંકારના રોમમાં, અહંકારનો પ્રધાનપુરુષના રોમમાં, પ્રધાનનો પ્રતાપ મૂલપુરુષના એક રોમમાં ને મૂલપુરુષનો પ્રતાપ અક્ષરબ્રહ્મના એક રોમમાં સમાઈ જાય છે. એ અક્ષરબ્રહ્મ પુરુષોત્તમની દાસભાવે સેવા કરે છે. જેવો અક્ષરનો પ્રતાપ છે, તેવો ભગવાનના એક એક રોમમાં ભર્યો છે. આ વાત બરાબર સમજાય છે તેને એક તલભર પણ પોતાની મહત્તા મનાતી નથી. આ વાત અતિ અકળ છે તે ભવ-બ્રહ્મા જેવાના કળ્યામાં પણ આવતી નથી.”","e":null,"s":["13/60/30-38"],"sv":["प्रधान में प्रताप हि जेता । मूलपुरुष के एक रोम तेता ॥\n\n मूलपुरुष में प्रताप हि जेतो । अक्षर के एक रोम हि तेतो ॥\n\n अक्षर में प्रताप हें जेहि । भगवान के एक रोम हि तेहि ॥\n\n तिलभर पिछे ताके तेहु । महत्ता कछु न रहत एहु ॥\n\n अकल रहत ज्यां लग जो वाता । महत अल्प जो जो रहाता ॥\n\n तिहां लग वात रहत अतोला । कले होत जरूर तोला ॥\n\n अकल बात अकल एक जाने । भव ब्रह्मा न कलत रहाने ॥\n\n देखावे न देखावे तोउ । अखंड सदा रहे सोउ ॥"],"mt":false,"gl":null,"a":false},{"i":962,"k":"para","g":"શ્રીહરિએ ગોંડળમાં સંત-હરિજનોને વાત કરતાં કહ્યું, “મનુષ્યદેહે કરીને જપ, તપ, તીર્થ થાય પછી તેનું ફળ એ છે કે પ્રગટ ભગવાન કે ભગવાનના સંત મળે. પછી તેમનાં વચન અનુસાર ચાલવું. ભગવાન અને ભગવાનના સંતો-ભક્તોની સેવા મન-કર્મ-વચને કરવી તે આત્મારૂપે રહેવા કરતાં પણ અધિક છે. સેવા કરવામાં દંભને અવકાશ નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":963,"k":"para","g":"“આત્મારૂપ વર્તન કરવામાં દંભ પોષાય છે. ભગવાન ને સંતની સેવા વિના આત્મસુખની વાત પણ શુષ્ક છે, નીરસ છે. મોટા સિદ્ધ ધ્યાનમાં બેસે તે તેની મોટાઈ તેના પૂરતી છે, પછી તેની પાછળ દંભની વાત રહે છે. દંભથી ક્યારેય મોક્ષ થતો નથી. શ્રીહરિના દાસ થઈને જે રહે છે, તેનામાં મોક્ષ નિવાસ કરે છે. અર્થાત્ તે મોક્ષનું દ્વાર બની જાય છે.”","e":null,"s":["14/29/31-40"],"sv":["हरि हरिजन-संत जो ताकी । सेवा करना मन क्रम वाकी ॥\n\n आत्मा से अधिक जानना ताहि । यामें दंभ के न माग रहा ही ॥\n\n सेवा बिन आत्मसुख जेहा । नीरस सो सब बात हे तेहा ॥\n\n बड़े सिद्ध की हें बड़ाई । बड़े सिद्ध जिहां लग रहाई ॥\n\n बड़े सिद्ध जब ध्यान में जावे । पिछे दंभ सब बात रहावे ॥\n\n दंभ से मोक्ष न होवत कबहि । बात निश्चे कर जानना सबहि ।\n\n हरि सम कहे न कोई, हरि के रहे दास होई ॥\n\n मोक्ष रहत हें सोई, करिके निवास तहां ॥"],"mt":false,"gl":null,"a":false},{"i":964,"k":"para","g":"શ્રીહરિએ અલર્ક રાજાને વાત કરતાં કહ્યું, “નમ્ર થવામાં મોટપ છે. મોટાઈ પણ નમ્રતા વગર શોભતી નથી. જેમાં નમ્રતા નથી તો મોટપ પણ નથી. અનંત વિદ્યાઓ ભણે તેનું ફળ નમ્રતા છે. નમ્રતાથી વિદ્યા શોભે છે. જેણે નમ્રતા સિદ્ધ કરી તેને વગર મોટપે મોટપ મળે છે. સારાં આભૂષણ પહેર્યાં હોય તે પણ નમ્રતાથી શોભે છે. નમ્રતા ન હોય તો તે શોભતાં નથી. બીજા ગુણ ઘણા મેળવ્યા હોય, પણ નમ્રતા ન હોય તો તે ગુણ ઝેર રૂપ છે. પારસમણિ તથા ચિંતામણિ તથા બીજી રિદ્ધિ-સિદ્ધિ પામે, પણ નમ્રતા ન આવે ત્યાં સુધી મોટપ શોભે નહીં.”","e":null,"s":["15/13/32-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":965,"k":"para","g":"ગઢપુરમાં શ્રીહરિ સંતોને કહે, “દુઃખી સંતની જે સેવા કરે છે, તે મારી જ સેવા કરે છે. દુઃખી(રોગી) સંત, વર્ણી અને પાર્ષદની સેવા અલૌકિક ભાવ લાવીને કરવી. તે સેવાથી થયેલા લાભનો કોઈ દિવસ નાશ થતો નથી. પદાર્થનો લોભ રાખીને માયિક ભાવથી સેવા કરે તો માયિક ફળ મળે છે અને ભગવાન તથા ભગવાનના સંત ક્યારેય પ્રસન્ન થતા નથી. ભગવાન ને સંતનાં વચન પદાર્થ કરતાં અધિક છે. એ કાનથી સાંભળે તોપણ અંતઃકરણ શુદ્ધ થઈ જાય છે, જે પદાર્થે કરીને થતું નથી.”","e":null,"s":["15/46-47/5"],"sv":[],"mt":false,"gl":null,"a":false},{"i":966,"k":"para","g":"શ્રીહરિએ સર્વે સંતોને પત્ર પાઠવ્યો. જેમાં સાચા સંતનાં લક્ષણ જણાવતાં લખ્યું, “જે સમાધિથી પણ મારી મૂર્તિને વિષે અધિકભાવ રાખે છે તે જ શ્રેષ્ઠ ભક્ત છે. સંતો-ભક્તોનો દાસ થઈ જે વર્તે છે તેને સમાધિ વિના સમાધિ છે. જે દાસ થયો તેના હૃદયમાં પ્રકાશ થાય છે. તે પ્રકાશમાં ભગવાનની મૂર્તિ દેખાય છે. જે એકાંતિક સંત છે તેને દાસના હેતુની વાત ખબર છે.”","e":null,"s":["15/72/31-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":967,"k":"para","g":"કુંડળમાં રાજાઓ આગળ શ્રીહરિ ફરી કહેવા લાગ્યા, “સંત-હરિભક્તની મોટાઈ જે સમજે છે અને તેમનાં દર્શનથી જેનું અંતર ઠરે છે, તેને વિઘ્ન નડતાં નથી. દાસભાવ ન રહે તો મેરુ સમાન ગુણ હોય તોપણ શોભતા નથી. અનંત ધ્યાન-ધારણા કરતો હોય, ભૂત-ભવિષ્ય કહેતો હોય, અંતરનું જાણતો હોય, અનંત જીવોની નાડી જાણતો હોય, અનંત પરાક્રમ કરતો હોય, તોપણ જો દાસપણું ન હોય તો અંક વિનાના શૂન્ય જેવું છે... દાસના ઉરમાં શ્રીહરિ નિવાસ કરીને રહે છે.”","e":null,"s":["16/39/6-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":968,"k":"para","g":"વાસણ સુથારને ઘરે શ્રીહરિ કહે, “સત્સંગના પ્રતાપથી સત્સંગના ગુણ આવે છે, પણ તેને જીરવવા કઠણ છે. સત્સંગ મળવો સુગમ છે, પણ પાત્ર થવું કઠણ છે. સત્સંગીમાં જેમ જેમ ગુણ આવે, તેમ તેમ સહજ રીતે દીન થતું જવાય. મોટા સંતની આગળ સૌ સહેજે દીનપણે વર્તે છે. ભાવથી પગે લાગી સેવા કરે છે, પણ નાના સંતને તુચ્છ માને છે તેને ગમ રહેતી નથી. અન્યને તુચ્છ માને તે પોતે જ તુચ્છ થાય છે. સંત-હરિભક્તોનો રંગ જે રીતે દિવસે દિવસે વધતો રહે, મેરુ જેવા ગુણ હોય પણ આવી વાત ગ્રહણ ન કરે તો તે ગુણ આકડાનાં તૂરની જેમ ઊડી જાય છે.”","e":null,"s":["16/58/1-7"],"sv":[],"mt":false,"gl":null,"a":false},{"i":969,"k":"para","g":"શ્રીહરિએ આનંદમુનિને કહ્યું, “ત્યાગ, વૈરાગ્ય, ધર્મ, જ્ઞાન થઈ શકે પણ સેવામાર્ગ કઠણ છે. ભગવાનના મંદિરને માટે જે જેવી સેવા કરશે તેને તેવું ફળ મળશે. જ્ઞાન અને ધ્યાનની ઓથ લઈને સત્સંગમાં ઘણાય આત્મનિષ્ઠ બનશે, પણ સેવા-નિષ્ઠ છે તે જ સાચા આત્મનિષ્ઠ છે. સેવાનિષ્ઠ વિના જ્ઞાન અને ધ્યાનવાળા દંભી છે. શરીર, વચન અને ધનથી ભગવાનની સેવા થાય, તે સિવાય બીજું કાંઈ અધિક નથી.”","e":null,"s":["20/60/1-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":970,"k":"para","g":"સુરતમાં શ્રીહરિએ પુરજનોને જે વાત કરી હતી તે મુક્તમુનિએ ઉત્તમનૃપને કહી, “ભગવાનના દાસના દાસના ચરણસેવક થઈ વર્તતા હોય એ ભગવાનના સાચા સંત છે. એવા સંતની ભાવે સહિત જે સેવા કરે છે, રાત-દિન ખડે પગે રહે છે, ને સેવામાં ક્યારેય અરુચિ લાવે નહિ તેની મોટપ સર્વથી શ્રેષ્ઠ છે. તેને પાકા હરિભક્ત જાણવા.”","e":null,"s":["27/47/8-9, 12"],"sv":["भगवान के दासदास ताके । चरनसेवक होई वर्तत वाके ॥\n\n भगवान के साचे संत सो ताकि । भाव सहित सेवा जो वाकी ॥\n\n रात-दिन सेवा करे तामें । अरुचि न होवे कबु यामें ॥\n\n एसी समझ रहायेउ जाकी । सर्वोपरी मोटप रहे वाकी ॥"],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":971,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":972,"k":"para","g":"જીવ જ્યારે શ્રીહરિને શરણે થઈને ભજે ત્યારે તે બંધનથી છૂટે. દાસ થઈને જે વર્તે તેની જ સમજણ સાચી છે. આત્મસ્વરૂપે વર્તનારા દાસપણું ભૂલી જાય છે, તેથી કર્મબંધન રહે છે. આત્મારૂપે થઈ હરિના દાસ રહે તે નક્કી હરિભક્ત કહેવાય. તે શ્રીહરિના વચનને ક્યારેય ઉલ્લંઘે નહિ. જેટલું વચન પર તાન તેટલો શ્રીહરિ તેને સમાસ કરે છે.","e":null,"s":["9/22/31-35"],"sv":[],"mt":false,"gl":null,"a":true},{"i":973,"k":"para","g":"જેવા સમર્થ શ્રીહરિને જાણે તેવો પોતે બને, પણ શ્રીહરિ તો તેનાથી અપારના અપાર જ છે. એમ શ્રીહરિને જાણીને પોતે બ્રહ્મ સમાન થાય તોપણ શ્રીહરિનો ડર રાખી સંત-હરિભક્તોના દાસ થઈ અણુ પર્યંત કોઈ જીવને દુખવે નહિ, ત્યારે તેને અક્ષર જેટલું સામર્થ્ય પ્રાપ્ત થાય છે.","e":null,"s":["9/24/34-38"],"sv":[],"mt":false,"gl":null,"a":true},{"i":974,"k":"para","g":"પોતાનામાં અક્ષર જેવા ગુણ આવે તોપણ હરિ અને હરિજનના દાસ થઈને રહે તેવા સંતો-ભક્તો ભગવાનને ગમે છે. તેના ભુવનમાં શ્રીહરિ સદા વસે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":975,"k":"verse","g":"‘અક્ષર કે ગુન કહાવત સબહુ, આપમેં બસે અખંડ જબહુ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":976,"k":"verse","g":"હરિ હરિજન કે રહે તોહુ દાસા, હરિજન કે ગુન કરે ન વિનાસા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":977,"k":"verse","g":"એસે હરિજન હરિ મન ભાવે, તાકે ભુવન હરિ સદા રહાવે.’","e":null,"s":["9/31/33-34"],"sv":[],"mt":false,"gl":null,"a":true},{"i":978,"k":"para","g":"સેવા કરે પણ મરજી વિના કરે તેના પર શ્રીહરિ રીઝતા નહિ. દાન, પુણ્ય, યજ્ઞ, તીર્થ વગેરે સાધન મરજી જોયા વિના કરે તેના ઉપર શ્રીહરિ પ્રસન્ન થતા નથી. બીજા ભક્તો પર દ્વેષ કે ઘૃણા રાખીને કોઈ ભક્ત ફાવે તેવું શ્રેષ્ઠ વર્તન કરે તોપણ શ્રીહરિ રીઝે નહિ. દ્વેષરૂપ અગ્નિથી તેનાં સાધન સઘળાં બળી જાય છે. દૂધ-સાકરમાં ઝેર પડે તેના સમાન તે સમજવું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":979,"k":"para","g":"હરિભક્તોમાં શુદ્ધભાવ હોય ને જો થોડો જ ગુણ હોય તોપણ શ્રીહરિ તેને મેરુ સમાન માને છે અને અનંત દોષોને જોતા નથી. જેમ આ દેહ અંદર બહાર નખશિખ મલિન છે, પણ અણુ જેટલા જીવના સંબંધે કરીને શુદ્ધ દેખાય છે. જે હરિભક્ત હોય તેણે એકબીજાના દાસ થઈને રહેવું. પોતાના મનમાં પોતાને અધિક માનવો નહિ. અધિક મનાય તેટલો કુસંગ ગણાય.","e":null,"s":["11/8/28-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":980,"k":"para","g":"મુક્તમુનિએ શ્રીહરિની સ્વાભાવિક પ્રકૃતિ કહી, “જે ભગવાન અને સંતનો દાસ થઈને રહેતો હોય તેને દેશકાળ લાગતા નથી. તેનો ભક્તિભાવ કોઈ કાળે ઓછો થતો નથી. સત્સંગમાં દાસપણું જોઈને શ્રીહરિ જનોનો સત્સંગ નક્કી કરતા. હરિજનોમાં જેટલો દાસભાવ તેટલી તેની સાથે શ્રીહરિ પ્રીતિ રાખતા. તેનો ભક્તિભાવ જોઈ અંતર શુદ્ધ થાય, દોષો ટળે તેની ચાડ અંતર્યામીપણે રાખતા. જનોના ઉત્તમ ગુણો જેટલા વધે તેમ જતન કરતા. નિષ્કપટપણું એ તો અમૃત જેવો ગુણ છે. ગુણમાત્રમાં એ ઉત્તમ ગુણ છે. અને કપટ એ વિષ છે. જેનામાં શ્રીહરિ કપટ દેખતા તેનો ત્યાગ કરી દેતા. અને જેનામાં નિષ્કપટપણું દેખતા તેની સાથે અનુરાગ કરતા.”","e":null,"s":["15/59/32-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":981,"k":"para","g":"ભગવાન અને સંત ભેગા રહે ને મતિ ન ફરે, એનો ઉપાય એ છે કે ભગવાન અને સંતના જે ગમતામાં વર્તે, કોઈ વખાણે તોય છક ન આવે, કથાવાર્તા, કીર્તન-ભજન, ધ્યાન-સમાધિ વગેરે ગુણો હોય ને બીજા પણ સત્સંગના ગુણો પ્રાપ્ત થયા હોય તોપણ તેનું માન ન આવે. ભગવાન ને સંત ગમે તેવી મોટપ આપે તથા મોટા મોટા રાજાઓ અને પ્રજા ચરણમાં આવીને નમે, છતાં સંત-હરિભક્તોનો કિંકર-દાસ થઈને રહે એની મતિ ક્યારેય ફરતી નથી, અને એને જ સુમતિ જન જાણવો. જે સત્સંગથી મોટપ પામ્યો હોય છતાં તેને ભૂલી જાય છે એને ભગવાન જોઈ રાખે છે ને અતિ ઊંચે ચઢાવી પટકે છે, તોપણ તેની ગમ તેને પડતી નથી.","e":null,"s":["15/65/30-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":982,"k":"para","g":"સંત આગળ સરળતા ન હોય તે મોટામાં મોટું વિઘ્ન છે. મોટા સંત પાસે દબાઈને રહેવું. સંત આગળ સરળ વર્તે તેને ક્યારેય વિઘ્ન ન આવે. માનીને જીવે ત્યાં સુધી સન્માન મળતું રહે તો તે નભ્યો જાય. સન્માન બંધ થાય ત્યારે સત્સંગ છૂટી જાય. માટે સંત-હરિજનના દાસ થઈને રહેવું. દાસ થઈને રહેવાનો અભ્યાસ રાખે છે તે ક્યારેય ઝાંખા થતા નથી. જે પોતાને સૌથી અધિક માને તે જ ન્યૂન થતો જાય છે. જે સંતો-ભક્તોનો દાસ થઈને નિષ્કપટ વર્તે છે, તેટલો તે મોટપને પામે છે. માનની મોટાઈ મન સુધી છે. માનને કાજે કઠિન સાધન માત્ર થાય, તે હરિજનને દબાવવા કરે છે. કઠણ સાધન કરે અને અન્નજળ તજે તેથી કરીને મોટાઈ આવતી નથી. હળીમળીને ચાલે તેના ઉરમાં આનંદ રહે છે.","e":null,"s":["19/9/29-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":983,"k":"para","g":"જે ભક્તના દાસ થઈને વર્તે છે તેને વિઘ્ન નથી. પોતામાં ગમે તેવા ગુણ હોય ને સત્સંગના પ્રતાપથી ઈશ્વર જેવો સમર્થ હોય, છતાં હરિભક્ત આગળ તેનો છક રાખે નહિ, ત્યારે તેને કંઈ વિઘ્ન રહેતું નથી. દાસપણા વિના એક પણ ગુણ શોભતો નથી અને ભગવાનની પ્રસન્નતા પણ ત્યાં સુધી થતી નથી.","e":null,"s":["22/42/36-40"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":14,"gu":"નિષ્કામવ્રત, બ્રહ્મચર્ય","en":"Nishkām-Vrat, Brahmacharya — Celibacy","url":"https://www.anirdesh.com/pbp/index.php?page=chp_14","b":[{"i":984,"k":"para","g":"શ્રીહરિનો ઉતારો જૂનાગઢના નાગરવાડામાં અમરસિંહ દીવાને ગોઠવ્યો હતો. તેમણે શ્રીહરિને કહ્યું, “આપનો નિવાસ ક્યાં કરાવું?”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":985,"k":"para","g":"ત્યારે શ્રીહરિ બોલ્યા, “જ્યાં સ્ત્રીનો પગફેર ન હોય ત્યાં અમને ગમે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":986,"k":"para","g":"તેણે કહ્યું, “એવું તો એક દીવાનખાનું છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":987,"k":"para","g":"શ્રીહરિ ત્યાં પધાર્યા અને ઉતારો કરી મોદ પામ્યા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":988,"k":"verse","g":"‘સહજ જગે સબહિ હેં તુમારિ, કહો તિહાં ઉતરાયે બ્રહ્મચારિ,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":989,"k":"verse","g":"તબહિ બોલે સો બર્નિરાયા, જહાં ત્રિય પગ ફેર ન રહાયા.’","e":null,"s":["3/37/46-48"],"sv":[],"mt":false,"gl":null,"a":false},{"i":990,"k":"para","g":"જીવુબાનો ત્યાગ જોઈ રાજબાઈએ ગૃહત્યાગ કર્યો. ભગવાન ભજવા ગઢડા આવ્યાં, તે વાત જીવુબાએ શ્રીજીમહારાજને કરી. શ્રીહરિએ મુક્તાનંદ સ્વામી, ગોપાળાનંદ સ્વામી, નિત્યાનંદ સ્વામી અને બ્રહ્માનંદ સ્વામીને બોલાવીને જીવુબાએ કરેલી વાત કરી. પછી કરુણા કરી કહેવા લાગ્યા -","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":991,"k":"para","g":"“જુઓને, સત્સંગની વાત કરવામાં ત્યાગની ચાનક ચઢી જાય છે. બાઇયું પરણ્યા ધણીનો ત્યાગ કરી દે છે, પછી તેના પિતા સમજાવે તો મીરાંબાઈનું ઉદાહરણ આપે છે. રામાનંદ સ્વામી કાશી જઈને છાના રહ્યા. એમ ત્યાગમાં ઉપાધિ બહુ રહી છે. નરનો અભાવ નારી જીવમાંથી કરે ને નારીનો અભાવ નર જીવમાંથી રાખે તો ત્યાગ પાર પડે. નિષ્કામવ્રત પાળવું કઠિન છે. ગોપીઓ જેવા કોઈ ભક્ત નહિ, પરંતુ નિષ્કામવ્રત રાખનાર ભક્ત, ગોપીઓ કરતાં પણ અધિક છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":992,"k":"para","g":"“બ્રહ્મચર્ય વ્રત પાળવાની ઇચ્છા જેને હોય તેણે નિયમોનું બહુ પ્રકારે કડક પાલન કરવું પડે. ઔષધ કરતાં પણ ચરી ચઢે. રોગીને ચરીમાં અધિક શ્રદ્ધા હોય તો કામ સરે. નિષ્કામવ્રત દૃઢ રાખવાની આટલી ચરી છે –","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":993,"k":"para","g":"“પ્રથમ દેહને અનિત્ય માની તેનું નિરંતર દમન કરે ત્યારે દેહ નિયમમાં આવે છે. બીજું, આત્માને અછેદ્ય, અભેદ્ય, અજર, અમર માની આત્મનિષ્ઠા કેળવવી. ત્રીજું, રસાસ્વાદ જીતવો. દેહમાં જેટલો રસ જાય તેટલો જીવમાં કામ જાગે. મધુર, ખાટો, ખારો, તીખો ને કડવો – પાંચે રસમાં કામ રહેલો છે. ધીમે ધીમે આહારનો સંકોચ કરવો. ચોથું, વિચાર્યા વિના કોઈનો વાદ ન લેવો, મોટા સત્પુરુષ નાવ સમાન છે તેનો સંગ રાખવો, માન મૂકીને તેમની સેવા કરવી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":994,"k":"para","g":"“પાંચમું, ગુરુમુખી થવું. પોતાનું ધાર્યું જેટલું થાય છે તેટલું માન જાણવું. અગ્નિમાં પ્રવેશ કરવો સહેલો છે, પણ મનનું ધાર્યું મૂકવું કઠણ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":995,"k":"para","g":"“છઠ્ઠું આત્મવિદ્ થવું. આત્માને મનનો સંગ ન રહે ત્યારે તેને આત્મવિદ્ જાણવો. આવા આત્મનિષ્ઠ પુરુષ સરળ સ્વભાવના હોય છે. એવા તો એક જડભરત થયા જે સરળપણે વર્ત્યા. બીજા મોટા જોગીઓ ઘણા પણ જડભરતની તોલે ન આવે. અમે જડભરતને સંભારીએ છીએ ત્યારે નેત્રમાંથી જળ વહેવા લાગે છે. પ્રહ્‌લાદ, બલિ, પ્રિયવ્રત, શુક, સનકાદિકને સંભારીએ છીએ ત્યારે દિલમાં ખુમારી પ્રગટે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":996,"k":"para","g":"“બદરીતળે બેઠા થકા નરનારાયણ ઋષિ મહાનૈષ્ઠિક વ્રત રાખે છે. એવા ભક્ત પર અમારી પ્રીતિ-રુચિ જાણી બધા સંતોએ એ રીતે વર્તવું.”","e":null,"s":["4/41/1-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":997,"k":"para","g":"શ્રીહરિએ સરધારમાં ગ્રામજનો પાસે વાત કરતાં કહ્યું, “નિષ્કામ વ્રત રાખે તે સત્સંગમાં મોટેરો છે. નિષ્કામ વ્રતનો ભંગ કોઈ કરે તો તે અમને તત્કાળ જણાવી દેવું, વિલંબ ન કરવો. નિષ્કામધર્મ રાખે તે અમારો છે. તેમાં જે ફેર પાડશે તેને સત્સંગ બહાર કરીશું. જો તેને સત્સંગનો ખપ હશે તો પ્રાયશ્ચિત્ત આપીશું. પ્રાયશ્ચિત્ત ન કરે તે અશુદ્ધ કહેવાય અને તે સત્સંગમાં બધાને અભડાવે છે. પોતાનું પાપ જે છાનું રાખશે તે મરીને બ્રહ્મરાક્ષસ થશે. એ અમારે શરણે રહેતો હશે તોપણ તેની સહાય અમે નહિ કરીએ. વચનમાં વર્તશે તે જ અમારો છે.”","e":null,"s":["5/10/6-12"],"sv":["निष्कामी धर्म दृढता ताकी । श्रीहरि वात करन लगे वाकी ॥\n\n त्यागि रु गृहस्थ कहावत जेते । निष्कामि नियम दृढ रखना तेते ॥\n\n तामे फेर पार हि जेहि । ताकुं विमुख करहि तेहि ॥\n\n ताको लोभ न रखहि लेशा । जग में वड़ो होवहि केसा ॥\n\n निष्कामी धर्म रखे सो हमारा । ओर सत्संग से करहि बारा ॥\n\n निष्कामी नियम रखे जाई । सो सत्संग में बडो रहाई ॥\n\n निष्काम में फेर पार हि जेहा । जाने में जेहि आवे तेहा ॥\n\n हमकुं तेहि केना आई । तर्त विमुख हम करतहि ताई ॥"],"mt":false,"gl":null,"a":false},{"i":998,"k":"para","g":"જેતલપુરમાં શ્રીહરિ કહે, “બ્રહ્મચર્યનો નિયમ રાખ્યા વિના જપ, તપ, વ્રત તથા સત્સંગ આદિક કાંઈ પણ ફળીભૂત થતું નથી. એક સંતને જમાડે તો કોટિ યજ્ઞનું ફળ કહ્યું છે, પણ બ્રહ્મચર્ય વ્રત પાલન વિના તે ફળને ન આપે. યજ્ઞથી જગતમાં કીર્તિ મળે, પણ પાપ કરેલું ભોગવવું પડે.”","e":null,"s":["8/18/29-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":999,"k":"para","g":"વડતાલમાં એકાદશી અને પૂનમનો સમૈયો કરવા ભક્તો આઠમથી આવવાના શરૂ થઈ ગયા. પુરમાં ભીડ ખૂબ થવાથી સંતો તથા બાઈ-ભાઈ હરિભક્તોની વિભાગવાર સભા થઈ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1000,"k":"para","g":"સભાની વ્યવસ્થા જોઈને શ્રીહરિએ પ્રસન્ન થકા કહ્યું, “ધર્મ વિના મોક્ષ હોય નહિ. નિષ્કામધર્મ વિના જગતમાં રહેલા અપાર ધર્મો જેમ નાક વિના મુખ શોભે નહિ તેમ શોભતા નથી. માટે અમારા હરિભક્તોએ નિષ્કામધર્મ મુખ્ય રાખવો. અને તેને દૃઢ કરવા માટે જ અમે વારંવાર દેશ-પરદેશ જઈ સમૈયા ને કથાવાર્તા કરીએ છીએ. અમારાં ચરિત્રોમાં પણ નિષ્કામધર્મ મુખ્યપણે રહ્યો હોય છે. અમે પ્રકરણો ફેરવીએ છીએ તેમાં પણ કામનું જોર ટાળવાનો હેતુ સમાયો છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1001,"k":"para","g":"“કામનું જોર અપાર છે. ઇન્દ્ર, ચંદ્ર, નારદ, ભવ-બ્રહ્માદિકને પણ ઘેરી લીધા છે. એટલા માટે જ મનુષ્યથી ન બને તેવાં તપ બહુ કર્યાં. શિવ સમાન કોઈ યોગી કહેવાય નહિ, બીજા યોગી તેમના આગળ પ્રાકૃત જેવા છે, છતાં પણ કામે તેમને વિઘ્ન કર્યું. જોગીઓના જોગી એવા નરનારાયણ ઋષિ અને શ્વેતદ્વીપમાં વાસુદેવ પણ નિષ્કામધર્મનું દૃઢ પાલન કરે છે, તપમાં રુચિ રાખે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1002,"k":"para","g":"“લોભ અને કામનું જોર એવું છે કે નિશ્ચયને તોડી નાખે, માટે તેનો વિશ્વાસ કરવો નહિ. દારૂ વગેરે કેફી પીણાથી જેમ બુદ્ધિનો નિયમ રહેતો નથી તેમ લોભ અને કામ પણ બુદ્ધિને ભ્રષ્ટ કરે છે, માટે નિષ્કામપણું રાખવું.”","e":null,"s":["8/53(52)/16-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1003,"k":"para","g":"વડતાલની સભામાં શ્રીહરિએ કહ્યું, “નિષ્કામધર્મ દૃઢ પાળવો, બીજાં જપ, તપ વગેરે અનેક કરે, પણ નિષ્કામપણા સમાન કોઈ તપ નથી. માટે તેમાં ગાફલ ન રહેવું. નિષ્કામપણું ન હોય ત્યાં સુધી આપણે ભેગા થયા તેનું તથા ભક્તિ કરી તેનું કંઈ ફળ નથી.”","e":null,"s":["8/54/1-2, 10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1004,"k":"para","g":"મુક્તમુનિ કહે: “નિષ્કામવ્રત ઉપર શ્રીહરિને બહુ હેત હોવાથી વારંવાર તે સંબંધી વાત કરતા ને કહેતા કે, ‘નિષ્કામવ્રત વિનાનાં નરનારી પશુ સમાન છે. નિષ્કામી હરિભક્તો પાસે અમને રહેવું ગમે છે. બીજા ભાવથી જમાડે પણ તેનાથી ઉદાસ રહીએ છીએ. બ્રહ્મા અને ભવ જેવા દેવ આવીને બ્રહ્માંડની સમૃદ્ધિ આપે તોપણ નિષ્કામ વ્રત સિવાય પ્રિય લાગતી નથી.’”","e":null,"s":["9/44/2-5"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1005,"k":"para","g":"બોટાદમાં હમીર ખાચરના ભુવનમાં થાળ જમીને શ્રીહરિ કહે, “કહ્યા વિના અમારી રુચિ જાણે તેવા સેવકો અમને બહુ ગમે છે. સમય ઉપર સેવા થાય તે સેવા અતિ ઉત્તમ કહેવાય. તેવા સેવકો ઉપર વિના કર્યે ભાવ વધતો અને વધતો જ રહે છે. મુકુંદવર્ણી જે અમારા સેવક છે તેમાં બે ગુણ બહુ ભારે છે. એક તો સનકાદિક જેવું નિષ્કામપણું છે. એટલે કે બ્રહ્માંડમાં નારીમાત્રને માતા, બહેન અને પુત્રીરૂપે જુએ છે. સ્વપ્નમાં પણ તે ભાવના ફરતી નથી. બીજું અનુવૃત્તિ જોઈ સેવા કરવી એ તેમને આવડે છે.”","e":null,"s":["9/56(57)/5-11"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1006,"k":"para","g":"તેરા ગામમાં શ્રીહરિએ વાત કરતાં કહ્યું, “જે સ્ત્રીઓ એકલી તીર્થમાં જાય છે તેનો ધર્મ રહે નહિ, અને પોતાના કુળને બોળનારી થાય છે. સુમતિ હોય તેમણે ઘરમાં રહીને ધર્મ પાળવો જોઈએ. ઘરમાં રહીને ધર્મ પાળે અને ભ્રષ્ટ ન થાય તો એકોતેર કુળને તારનારી થાય છે. માટે સધવા કે વિધવા બન્નેએ એકલા તીર્થ કરવાનો આગ્રહ ન રાખવો. પુરુષવર્ગના કહ્યામાં વર્તવું પણ સ્વતંત્રપણે ન વર્તવું. ઘર મૂકી સ્વતંત્રપણે ચાલે તો તે અંતે ભ્રષ્ટ થયા વિના રહેતી નથી.”","e":null,"s":["10/41/20-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1007,"k":"para","g":"ખોખરા મહેમદાવાદમાં શ્રીહરિએ સંતોને નિષ્કામધર્મ સંબંધી વાત કરતાં કહ્યું, “સંતના વર્તનમાં, અનંત ગ્રંથમાં કહેલી મોક્ષની વાત આવી જાય છે. લોકને રીઝવવા માટે જે કરે છે, તેનાં વર્તન તો જુદાં હોય છે. શૃંગી ઋષિ પિતા સાથે વનમાં રહેતા હતા. નારીનો શબ્દ પણ તેમણે સાંભળ્યો નહોતો. કોઈ નારીને દીઠી પણ નહોતી. તેથી સ્ત્રી-પુરુષનું ભાન નહોતું. એવાને પણ નારીએ છળ્યા છે. સૌભરિ, ચ્યવન વગેરે પણ ભ્રષ્ટ થયા છે. તો જે ધર્મ ન રાખે તેવા કળિયુગના જોગીનું શું લેખું? તેનો વિશ્વાસ રાખે તેની આશા છોડવી જ રહી, કારણ કે ઝેર પીએ તેનું ઘડી પછી મૃત્યુ થયા વિના રહે નહિ. તમને અમારાં વચન ન ગમે પણ અમે કહ્યાં છે, કારણ કે કામના વેગની તમને ગમ નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1008,"k":"para","g":"ત્યારે સંતો બોલ્યા કે, “આપ જેમ કહો તેમજ અમારે વર્તવું છે. તમે અમારા નાવરૂપ છો.”","e":null,"s":["13/6/23-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1009,"k":"para","g":"ગઢપુરમાં જીવેન્દ્રના દરબારમાં અન્નકૂટને દિવસે સંતોની સભામાં શ્રીહરિએ વાત કરતાં કહ્યું, “કામ અને લોભ બેઉ નરકનાં દ્વાર કહ્યાં છે. જ્યાં સુધી તેમાં મન રહે છે, ત્યાં સુધી તેને અનાસક્ત પુરુષ નરકમાં પડેલાં દેખે છે. નારી અને ધનને લીધે વારંવાર જન્મમરણ થાય છે. લખચોરાશીનું દુઃખ પણ ધન અને નારીમાં રહેલું છે. જે કંઈ દુઃખમાત્ર છે, તે ધન અને નારીમાં રહ્યાં છે. ધન-નારીનો જે ત્યાગ કરે છે તેને બ્રહ્માદિ દેવતાઓ વંદન કરે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1010,"k":"para","g":"“જેને ભગવાન અને ભગવાનના સંતને પ્રસન્ન કરવાનો મનમાં ભાવ હોય અને દેહનો અભાવ થયો હોય તે ધન અને નારીનો ત્યાગ કરી શકે છે. આ પ્રકારના જે ત્યાગી કે ગૃહસ્થ હરિજન છે તે મનુષ્ય તનમાં મુક્ત છે, કારણ કે આવો ત્યાગ માયિક જન કરી શકે નહિ. આવા બ્રહ્મચર્યનિષ્ઠ સંતો-ભક્તોને કારણે અખિલ બ્રહ્માંડમાં સત્સંગનું સર્વાધિકપણું આજે જણાય છે. બ્રહ્માદિ દેવતાઓ કરતાં પણ આવો સત્સંગ અધિક છે.”","e":null,"s":["13/66/35-40"],"sv":["नारी-धन कहावत जोउ । नर्क के द्वार देखत हें दोउ ॥\n\n नारी-धन में मन ज्यां लगहु । नर्क परे देखत त्यां लगहु ॥\n\n जन्म-मरण वेर हि वेरा । नारी धन करी होत फेर फेरा ॥\n\n चोराशी के दुःख हि जितना । धन-नारी में रहे तितना ॥\n\n जो जो दुःख कहात वो, धन-नारी में रहाय ।\n\n धन-नारी करे त्याग जेहि, ब्रह्मादि वंदत ताय ॥\n\n धन-नारी को त्याग जेहि, देह को जेहि अभाव ।\n\n भगवान संत ताहि कुं, प्रसन्न करत मन भाव ॥\n\n एसे जेते जन, त्यागी अरु हरिजन जेहि ।\n\n मुक्त मनुष्य रहे तन, मायिक जन न होय अरु ॥\n\n एसे जन कर जोउ, सत्संग सबसे अधिक ।\n\n ब्रह्मांड में नहि कोउ, ब्रह्मा से सत्संग अधिक ॥"],"mt":false,"gl":null,"a":false},{"i":1011,"k":"para","g":"મહેળાવથી વડતાલ જતાં રસ્તામાં શ્રીહરિએ કહ્યું, “નિષ્કામવ્રત જેટલું જેનામાં રહેલું હોય, તેટલો તેનામાં નરનારાયણ દેવનો વાસ છે. વસંત પણ સદાય ત્યાં રહે છે. યશ અને નીતિ, રૂપ-રંગ પણ ત્યાં રહે છે. અમે જે જે ચરિત્ર કરીએ છીએ તેમાં સત્સંગની આ રીત-મર્યાદા સહેજે રહી હોય છે. વિપરીત રીત અમને રુચતી નથી.”","e":null,"s":["17/39/17-18"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1012,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ કહ્યું, “બાઈ-ભાઈ હરિજનોએ નિષ્કામવ્રતનો ભંગ ન થાય એ રીતે વર્તવું. એવું અમે પ્રીતે કરીને ઘણીવાર કહ્યું છે. જે પુરુષ હરિભક્તનું નિષ્કામવ્રત ભંગ થાય તેને હરિભક્ત કહેવો નહિ અને તેને સત્સંગથી દૂર કરવો. દેશકાળે કરીને કોઈને ફેર પડે, તેને સત્સંગનો ખપ હોય તો તે પ્રાયશ્ચિત્ત કરી લે. જેટલો ખપ હોય તે બધાને દેખ્યામાં આવે છે. બિનસત્સંગી પણ તેનું પ્રમાણ કરે છે, અને કાચપ હોય તે કહી દે છે. કાંટે ચઢે ત્યારે અધિક-ન્યૂન માલૂમ પડે. અંદર-બહાર એકસરખું વર્તન જેનું હોય તેને માયા રહિત જાણવો. અંતરમાં કપટ હોય તેને હરિભક્ત કહેવાય નહિ. નિષ્કપટી હરિભક્તોનો પાયો જ સત્સંગમાં પાકો છે. એક એકનો વિશ્વાસ ન હોય તો શત્રુભાવ ને કપટ રહે છે.”","e":null,"s":["19/18(17)/26-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1013,"k":"para","g":"જવારજમાં શ્રીહરિએ ગામના પટેલને વાત કરી, “મનુષ્ય જે જે સાધન કરે છે તે બધાં સાધનો બ્રહ્મચર્ય વ્રતના પાલન વિના નિષ્ફળ છે. મનુષ્ય જાતિને બ્રહ્મચર્યનું પાલન એ મુખ્ય ધર્મ કહ્યો છે. બ્રહ્મચર્ય ભંગ કરે તેને માથે રાજાનો પણ દંડ છે.”","e":null,"s":["19/36(35)/17-18"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1014,"k":"para","g":"મછિયાવમાં ફૂલદોલનો ઉત્સવ કરવા એકત્ર થયેલ સંતોને શ્રીહરિએ વાત કરતાં કહ્યું, “અષ્ટપ્રકારે સ્ત્રીનો ત્યાગ રાખવો તે દૃઢ બ્રહ્મચર્ય છે. તેમાં જેટલો ફર્ક પડે તેટલો તેને ક્લેશ થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1015,"k":"para","g":"“ગૃહસ્થએ પોતાની સ્ત્રી સિવાય અન્યને મા, બહેન, દીકરી સમજી તેનો ત્યાગ રાખવો. પોતાની સ્ત્રીનો ત્યાગ પણ વ્રતને દિવસે રાખવો. ઋતુકાળે સ્ત્રીનો સંગ કરવો.”","e":null,"s":["20/30/33-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1016,"k":"para","g":"સુરતમાં શ્રીહરિએ પુરજનોને જે વાત કરી હતી તે મુક્તમુનિએ ઉત્તમનૃપને કહી, “એકનારી એ ગૃહસ્થનું બ્રહ્મચર્ય છે. પોતાની સ્ત્રી વિના અન્ય સ્ત્રીનો ત્યાગ રાખે તે લોકમાં ને શાસ્ત્રમાં મળતું આવે. ધર્મશાસ્ત્રનું ઉલ્લંઘન કરે તેને માથે દંડ થાય છે. પરસ્ત્રી સાથે હેત-પ્રીત કરે તેને શાસ્ત્ર-ઉલ્લંઘન દોષ કહ્યો છે.”","e":null,"s":["27/47/35-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1017,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1018,"k":"para","g":"મંદિરમાં દેવની સેવા-પૂજા કરે તેણે બ્રહ્મચર્ય દૃઢપણે પાળવું. બ્રહ્મચર્ય ન પાળે ને સેવા કરે તો તેના પર દેવનો કોપ થાય છે. અને અંતે તે ખુવાર થાય છે.","e":null,"s":["2/49/35-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1019,"k":"para","g":"નિષ્કામધર્મ જે પાળે છે તે જ ભક્તમાં રહી શકે છે. નિષ્કામધર્મ નથી પાળતો તે ભક્ત નથી. ભૂમિમાં અવતાર-ભક્તો અનંત અપાર થઈ ગયા, પણ નિષ્કામવ્રત, નિયમ-પાલન ને જ્ઞાનમાં પ્રગટના ભક્ત જેવું સામર્થ્ય કોઈનું સાંભળવામાં નથી આવ્યું. આમ, આ વ્રતને સર્વથી શ્રેષ્ઠ જાણવું. તેની તુલનામાં બીજું કોઈ વ્રત આવી શકતું નથી.","e":null,"s":["4/55/34-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1020,"k":"para","g":"અધર્મનાં જેટલાં દ્વાર છે તે સર્વે બંધ કરે ત્યારે નિષ્કામધર્મ રહે. બ્રહ્માએ નિજપુત્રી સામે દૃષ્ટિ માંડીને જોયું તે જ તેનો પ્રથમ અધર્મ કહેવાય. એ રૂપમાંથી કામ જન્મ્યો ને પછી મતિમાં અંધકાર થયો. માટે સ્ત્રી ચેતનવાળી હોય કે ચેતનહીન ચિત્ર, કાષ્ઠ, પાષાણની હોય પણ તેને જોવાય નહિ કે સ્પર્શ ન કરાય. દારૂ અને અગ્નિ એક સ્થાનમાં રહી ન શકે, તે કોટિ કરામત - ઉપાય કરે તોપણ ભડકો થયા વિના ન રહે. વળી, જે જે ઉત્પાત થયા છે તે નારીના પ્રસંગે કરીને થયા છે. આ વાત શ્રીહરિ વારંવાર કરતા.","e":null,"s":["9/61(62)/39-41"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1021,"k":"para","g":"ગમે તેવા સમર્થ પુરુષો હોય અને નારીને નાગણી જેવી સમજતા હોય, વિષયને નરક જેવા માનતા હોય, છતાં જેણે પણ નારી તજી નથી તેને વિષ ચઢતાં વાર લાગે નહિ. પાષાણ અને લોહ સમાન કઠણ હૃદય હોય, પણ નારીનાં નયનરૂપી અગ્નિ જો લગાર પ્રવેશ કરે તો પાણી થઈને તરત વહેવા લાગે. શિવ અને બ્રહ્મા જેવા સમર્થ પણ પીગળીને પાણી થઈ ગયા, તો બીજાનું શું લેખું! સૃષ્ટિ થઈ છે ત્યારથી નારી અને પુરુષ અંતરમાં એકરસ થઈને રહ્યાં છે. દેહથી ફક્ત જુદાઈ દેખાય છે. તે અંતરને જુદાં કરવા માટે ભગવાને વર્ણાશ્રમના ધર્મ બાંધ્યા છે. તેનો જે લોપ કરે તેને દંડ થાય છે. માટે ભગવાનને અંતર્યામી જાણી તેમનાથી ડરીને નીતિ પ્રમાણે ચાલવું.","e":null,"s":["10/40/20-26"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1022,"k":"para","g":"નિષ્કામાદિ ગુણ એક એવો અલંકાર છે કે તેને ધારણ કરનારની શોભા જેવી બ્રહ્માંડમાં કોઈની શોભા નથી. આ ગુણો ગુણાતીત છે. તે જેવા તેવા પુરુષમાં કદી આવતા નથી. ભલે ચૌદ લોક પોતાને વશ વર્તે તોપણ નિષ્કામાદિક ગુણ ક્યારેય ત્યજવા નહિ. આ ગુણને પ્રાપ્ત કર્યા પછી જો માયિક પદાર્થની તૃષ્ણા કરે તો તેટલી ગુણપ્રાપ્તિમાં કસર જાણવી. સહજ મળે તેનાથી ગુજરાન કરી લે એવા સંત સૌથી મોટા છે. આવી વાત શ્રીહરિ નિત્ય કરતા જેથી લેશ પણ માયાનો પાશ ન રહે.","e":null,"s":["11/15/19-24"],"sv":["बडे बडे गुन कहावत जेते । निष्कामादिक कर जो तेते ॥\n\n ब्रह्मादिक कुं दुर्लभ तेहा । संत में स्थापे हरि गुण एहा ॥\n\n देव से दुर्लभ संत कर दीन्हे । गुण करिके आवत चीन्हे ॥\n\n ब्रह्मांड से शोभा न एसी कोई । निष्कामादिक रखना सोई ॥\n\n गुणातीत यह गुण कहावे । अल्पजन में कबहु न आवे ॥\n\n चौद लोक जो भये वश ताई । निष्कामादिक गुण वरतत जाई ॥\n\n निष्कामादिक गुण कुं पाई । तृष्णा रहत मायिक की आई ॥\n\n मायिक की तृष्णा जेती जेऊ । संतता में कसर तेती तेहु ॥\n\n सहज मिले करत गुदराना । ऐसे संत सब पर रहाना ॥\n\n श्रीहरि वात करत नित ऐसि । माया को पास लगे न लेशि ॥\n\n माया के पास लगन के द्वारा । श्रीहरि बंध किये अब वारा ॥"],"mt":false,"gl":null,"a":true},{"i":1023,"k":"para","g":"સત્સંગમાં શ્રીહરિએ બાઈઓ અને ભાઈઓમાં નિષ્કામધર્મ દૃઢ કરાવ્યો. બન્ને એકબીજાના સંબંધથી રહિત થઈ ભક્તિ કરે એવી યોજના કરી. એમ ચારે વર્ણમાં આ ધર્મ પ્રવર્તાવ્યો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1024,"k":"para","g":"સ્ત્રી પરપુરુષ સામે દેખે નહિ કે બોલે નહિ. જો જોવા-બોલવાનો સંબંધ રાખે તો તેનો ધર્મ ક્યારેય રહે નહિ. તે પિતાનો, ભાઈનો કે પુત્રનો પણ સંબંધ ન રહે. એટલે જ પિતા, ભાઈ કે પુત્ર સાથે એકાંતમાં તેણે રહેવું નહિ. નારી અગ્નિ સમાન છે ને પુરુષ ઘી સમાન છે. બન્નેનો યોગ થાય ત્યારે કઠિન ઘી પીગળ્યા વિના રહે જ નહિ. દારૂનો ઢગલો મેરુ તુલ્ય હોય પણ તલભાર અગ્નિનો સંબંધ થાય તો બળ્યા વિના રહે નહિ. આવાં દૃષ્ટાંત અપાર છે. માટે સ્ત્રી-પુરુષનો સંબંધ એવો છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1025,"k":"para","g":"સાધુ રોગે કરીને અવરાઈ ગયેલો વૃદ્ધ હોય તોપણ તેને જો નારીનો સંબંધ ભૂલ્યથી પણ થઈ જાય તો એ વિષયમાં પોતાનું મન અવશ્ય પરોવી દે છે.","e":null,"s":["15/45/22-32"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1026,"k":"para","g":"શ્રીહરિ જેનામાં નિષ્કામધર્મની દૃઢતા દેખતા તેને પ્રોત્સાહિત કરતા, પણ કોઈએ નિષ્કામધર્મનો લોપ કર્યો હોય પછી પ્રાયશ્ચિત્ત કરવા ઇચ્છે નહિ તો તેના પર શ્રીહરિ અકળાઈ જતા. તેનો ઉત્સાહ ભંગ કરતા અને બ્રહ્મચર્ય લોપ કરનારને દૂર કરતા, પણ એ મડદાનું જતન કરતા નહિ.","e":null,"s":["17/24/24-25"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1027,"k":"para","g":"બાઈઓ બાઈઓમાં ચાલે ને ભાઈઓ ભાઈઓમાં ચાલે આવી સત્સંગની પ્રથા સ્વયં પુરુષોત્તમનારાયણ શ્રીહરિએ બાંધી છે. નિષ્કામધર્મ જે રીતે દૃઢ રહે એવી રીત પ્રવર્તાવી છે. નિષ્કામધર્મ ન દેખે તેના ઉપર શ્રીહરિ પ્રસન્ન થતા નહિ, તેની સાથે હેત પણ રાખતા નહિ. નિષ્કામધર્મ વિનાના જેટલા મત, તીર્થ, ઉત્સવ-સમૈયા છે તેમાં બાઈ-ભાઈ એકાકાર છે. જેમાં નિષ્કામધર્મનું પાલન નથી તેને શ્રીહરિ અધર્મ જ માનતા. દારૂના મોટા ઢગલામાં રત્તીભર અગ્નિનો તણખો પણ વિસ્ફોટ સર્જે છે. તેમ નારી અને પુરુષનો સંસર્ગ નિષ્કામવ્રતને નાશ કરનારો છે. એમ બ્રહ્મા લગી નારીનો સંગ શ્રીહરિએ દેખ્યો પછી વિચારીને જોગવૃત્તિ ધારણ કરી.","e":null,"s":["17/26/31-36"],"sv":["बायुं बायुं में चलत रहेउ । भाई भाई में चलत हे तेउ ॥\n\n सत्संग ताकि प्रथा एसी । पुरुषोत्तम आप बांधे तेसी ॥\n\n निष्काम धर्म रहे जिस रीता । श्रीहरि कुं रहे तामे मीता ॥\n\n निष्काम धर्म न देखत जामें । श्रीहरि प्रीत न रखत हि तामें ॥\n\n निष्काम धर्म नहीं जो जिनमें । एकाकार रहे जो तिनमें ॥\n\n धर्म बिन जितने रहेउ ताकु । अधर्म मानत रहे हरि वाकुं ॥\n\n दारू तामें अनल जबहु । रत्तीभर जब परजावे तबहु ॥\n\n उडे बिन कबु न रेवे ताई । नारी-पुरुष संग एसे रहाई ॥\n\n ब्रह्मा लग हरि देखे विचारी । नारी संग, जोगवृत्ति धारी ॥"],"mt":false,"gl":null,"a":true},{"i":1028,"k":"para","g":"ધન-સ્ત્રીમાં બંધાયેલા ગુરુના શરણે જવાથી કોઈ બંધાયેલો છૂટ્યો દેખ્યો નથી, નિર્બંધ ગુરુ મળે તો માયાનું બંધન પલકમાં ટાળી દે છે. ધન-સ્ત્રીમાં રાજા, રંક, ફકીર ને ઠેઠ દેવતા સુધી બંધાયેલા છે. તેમાં તમે સંતો વીરલા છો કે નિર્બંધ છો, ધન અને સ્ત્રીમાં જ જગત સમાયેલું છે. તે બન્નેનો જેણે ત્યાગ કર્યો તે જગત જીતી લીધું એમ બુદ્ધિમાન કહે છે.","e":null,"s":["20/46/37-40"],"sv":["बंधे के शरन बंधे गयेउ, छोडत एसे न देखे तेउ ।\n\n बंधे कुं निरबंध रहे जेहा, छोड देवे पलक महिं तेहा ॥\n\n धन त्रिया जो तिन महिं, राजा रंक फकीर ।\n\n देव लग बंधाये सब, निरबंध तुम हो वीर ॥\n\n धन त्रिया उहे जक्त हि, त्याग हि ताके किन ॥\n\n जग सब जीत हि लिन तेहि । कहत हि इमि प्रवीन ॥"],"mt":false,"gl":null,"a":true},{"i":1029,"k":"para","g":"નિષ્કામધર્મ વિના કરોડગણી ભક્તિ કરો તોપણ ભગવાન તે સ્વીકારતા નથી. નિષ્કામધર્મ વિના આકાશમાં ચાલતો હોય તોપણ શું? ને ભવ, બ્રહ્મા ને ઇન્દ્ર જેવો થાય તોપણ શું થઈ ગયું? નિયમ વિના નિષ્કામપણું સચવાય નહિ. બ્રહ્માદિક દેવને પણ નિયમ વિના નિષ્કામધર્મનો ભંગ થયો છે. પુલ વિના સમુદ્ર ઓળંગાય નહિ, તેમ નિષ્કામધર્મ રાખવાને માટે નિયમરૂપી પુલ છે.”","e":null,"s":["25/62/22-33"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1030,"k":"para","g":"નારી અને પુરુષનું ભેગું વર્તન જ્યાં હોય અને તેને ભેગા કરવામાં જે સુખ માનતા હોય તે અસત્પુરુષ છે. તે ક્યારેય સત્પુરુષના માર્ગે ચાલી શકે નહિ કે સજ્જનોમાં પણ તેનું નામ શોભે નહિ.","e":null,"s":["28/55/37-38"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":15,"gu":"એકાંતિક સત્પુરુષ","en":"The Ekāntik Satpurush","url":"https://www.anirdesh.com/pbp/index.php?page=chp_15","b":[{"i":1031,"k":"para","g":"ભક્તિમાતાને શ્રીહરિએ મોક્ષના દ્વારરૂપ એકાંતિક સત્પુરુષનો મહિમા કહેતાં કહ્યું, “સત્પુરુષના સંગથી ભગવાનનું દૃઢપણે માહાત્મ્ય જાણવામાં આવે છે. અને ત્યારે જ સ્વધર્મ, જ્ઞાન, વૈરાગ્ય અને માહાત્મ્ય સહિત ભક્તિનો ઉદય થાય છે. હે માતા! ધર્મ, જ્ઞાન, વૈરાગ્ય ત્રણે અંગ સહિત ભગવાનની ભક્તિ ઉદય થવાનું કારણ સત્પુરુષ છે. એ ત્રણ અંગસહિત એવી ભક્તિ વિના કાલમાયાના ભયથી રહિત એવું અક્ષરબ્રહ્મધામ કોઈથી પમાતું નથી.”","e":null,"s":["1/53/31-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1032,"k":"para","g":"ભક્તિમાતાએ શ્રીહરિને મોક્ષના દ્વારરૂપ સત્પુરુષનાં લક્ષણ પૂછ્યાં ત્યારે શ્રીહરિ તે વિસ્તારથી કહેવા લાગ્યા:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1033,"k":"para","g":"શ્રીહરિ કહે, “એવા સંત પર - અપરાધને ક્ષમા કરનાર, જીવપ્રાણીમાત્ર પર દયા રાખનાર, સર્વ જીવનું હિત ઇચ્છનાર, ઠંડી-ગરમી વગેરે સહન કરનારા, અસૂયારહિત હોય છે. ગુણમાં ક્યારેય દોષ ધારતા નથી. શાંત સ્વભાવે વર્તે છે. જેને કોઈ શત્રુ હોતો નથી. ઈર્ષ્યા રહિત વર્તે છે. માન રહિત, મત્સર રહિત હોય છે. બીજાની મોટપ દેખી પ્રસન્ન થાય છે. જેવું ઘટે તેવું બીજાને માન આપી રાજી થાય છે. નિર્વૈર, સત્ય અને પ્રિયવાણી બોલનારા, કામ, ક્રોધ, મદ અને લોભ રહિત, દેહમાં અહંબુદ્ધિ અને દેહના સંબંધીમાં મમત્વબુદ્ધિએ રહિત, સ્વધર્મમાં દૃઢ વર્તનવાળા હોય છે. દંભ રહિત, અંદર બહાર પવિત્ર, શરીર-ઇન્દ્રિયોને દમનારા, સરળ સ્વભાવવાળા, મિતભાષી, ઇન્દ્રિયોના ગણને જીતનારા, પ્રમાદ રહિત હોય છે. સુખ-દુઃખ, માન-અપમાન, હર્ષ-શોકમાં વિકાર રહિત, ધીરજવાન, જ્ઞાનેન્દ્રિય અને કર્મેન્દ્રિયની ચપળતાએ રહિત હોય છે. ક્ષોભ રહિત, પદાર્થ સંગ્રહ નહિ કરનારા, ધર્મબોધ આપવામાં ચતુર, આત્મનિષ્ઠ, હરિસેવામાં તત્પર હોય છે. પરોપકારી, નિર્ભય, નિઃસ્પૃહ, નિર્વ્યસન, શ્રદ્ધાવાન, ઉદાર હોય છે. તપમાં નિષ્ઠાવાળા, કોઈ પણ પ્રકારના પાપકર્મે રહિત, ગ્રામ્યવાર્તા નહિ કરનારા, સત્શાસ્ત્રના વ્યસની, માયિક પંચવિષયની આસક્તિથી રહિત હોય છે. આસ્તિક, બુદ્ધિવંત, સત્-અસત્‌ના પરમવિવેકી, મદ્ય-માંસ આદિના સંસર્ગ રહિત સાત્ત્વિક ભોજન જમનારા, બીજાની ગુપ્ત વાત પ્રસિદ્ધ નહિ કરનારા, ચૌર્યવૃત્તિ રહિત, આહાર અને નિદ્રાને જીતનારા હોય છે. સંતોષી, નિજધર્મમાં સ્થિર મતિ રાખનારા, અહિંસક, તૃષ્ણા રહિત, અમૃત દૃષ્ટિવાળા, બીજાનાં સુખદુઃખને જોઈ સુખીદુઃખી થનારા, અઘટિત કાર્ય કરવામાં લજ્જાશીલ હોય છે. પોતાના મુખે કરીને ક્યારેય પોતાનાં વખાણ નહિ કરનારા, બીજાની નિંદા નહિ કરનારા, સત્શાસ્ત્રમાં કહેલા નિષ્કામધર્મનું દૃઢ પાલન કરનારા બ્રહ્મચર્યનિષ્ઠ હોય છે. યમ, નિયમ, આસન, પ્રાણાયામ વગેરે યોગકળા જાણનારા, ભગવાનનો દૃઢ આશ્રય રાખનારા, ભગવાનની નવધાભક્તિ કરનારા, અવતાર ચરિત્ર કહેવા-સાંભળવામાં પ્રીતિવાન, ભગવાનની મૂર્તિમાં ધ્યાનપરાયણ, ભગવાનની ભક્તિ વિના ક્ષણમાત્ર વ્યર્થ સમય જવા નહિ દેનારા, સર્વ પ્રકારના દોષે રહિત એવાં લક્ષણયુક્ત ભગવાનના એકાંતિક સાધુના સમાગમે કરીને ધર્મ, જ્ઞાન, વૈરાગ્ય સહિત માહાત્મ્ય-જ્ઞાનયુક્ત ભક્તિ ઉત્પન્ન થાય છે. હે માતા! એવા સત્પુરુષ મુમુક્ષુજનને મળે છે ત્યારે નિશ્ચય કરીને માનવું કે, એને કોઈ વસ્તુ અપ્રાપ્ય રહી નથી. હે માતા, એવા સાધુ મળે ત્યારે ભગવાન સાક્ષાત્ મળ્યા છે એમ જાણજો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1034,"k":"para","g":"“તેમના મુખે ભગવાનના ચરિત્રનું શ્રવણ કરવું. તો ભગવાનનું તથા ભગવાનનાં ધામોનું માહાત્મ્ય અને ઐશ્વર્ય જાણ્યામાં આવે છે. ભરતખંડમાં રહેલાં તીર્થોનું માહાત્મ્ય પણ તેમના દ્વારા સમજાય છે. તેમની પાસેથી શ્રવણ કરવાની રીતે જે ભક્તિ વગેરેનું શ્રવણ કરે તેને અપાર ફળ મળે છે. અપાર પુણ્ય વિના એવા સાધુ મળવા દુર્લભ છે. તેમનાં દર્શન, સ્પર્શ, નમસ્કાર, સેવન, ભોજન અને પૂજનથી અનેક જન્મનાં પાપ નાશ પામે છે. એવા સાધુને ભગવાને પોતાના હૃદય સમાન ગણ્યા છે. તેમનાં ચરણમાં બધાં તીર્થ નિવાસ કરીને રહે છે. એવા સાધુનો પ્રસંગ મન, કર્મ અને વચનથી કરે તો મુમુક્ષુ જનોને કાંઈ પણ દુર્લભ નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1035,"k":"verse","g":"‘એસે સાધુ તાકે, ચરણ રહે જો તિન મહિં,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1036,"k":"verse","g":"તીર્થ સમુહ હિ વાકે, નિવાસ કરિકે રહે યહ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1037,"k":"verse","g":"સાધુ તાકે પ્રસંગ, મન, કર્મ, બચન હિ કર તેહિ,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1038,"k":"verse","g":"મુમુક્ષુ જનકું અભંગ, સિદ્ધિ હોત દુર્લભ જેહિ.’","e":null,"s":["1/54/1-63"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1039,"k":"para","g":"શ્રીહરિએ માતાને ઉપદેશ આપતાં એકાંતિક સત્પુરુષનો મહિમા કહેતાં કહ્યું, “હે માતા! સ્વધર્મ, જ્ઞાન, વૈરાગ્ય, શ્રીહરિની માહાત્મ્ય સહિત ભક્તિમાં જેની દૃઢ નિષ્ઠા હોય છે તેને એકાંતિક ભક્ત કહેવાય છે. એકાંતિકમાં દંભ, કપટ લેશ પણ હોતાં નથી તેના જેવો કોઈ શ્રેષ્ઠ નથી. એવા એકાંતિક ભક્તમાં શ્રીહરિ નિરંતર વાસ કરીને રહે છે. તેમાં રંચ પણ સંદેહ નથી. શ્રીહરિના વાસને લીધે એકાંતિક ભક્ત શ્રેષ્ઠ કહેવાય છે. એકાંતિક ધર્મમાં જેટલી કસર રહે તેટલો તે ઊતરતો ભક્ત જાણવો. એકાંતિક ધર્મ જેમાં જેટલો ઉત્કૃષ્ટ હોય તેટલો શ્રીહરિનો વાસ તેમાં વિશેષ જાણવો.”","e":null,"s":["1/56/65-69"],"sv":["भक्त एकांतिक जेउ, स्वधर्म, ज्ञान, वैराग्य कर ।\n\n भक्त रहाये तेउ, श्रीहरि के महात्म्य जुत ॥\n\n भक्ति रहाये जेहु, ताके विषे निष्ठा रहेउ ।\n\n तेहि सम श्रेष्ट न केहु, दंभ कपट न रखे तोउ ॥\n\n दंभ रहित एकांतिक तामे । भक्त जो रहायेउ यामे ॥\n\n श्रीहरि निरंतर रहे तेहा । यामे नहि रंच संदेहा ।\n\n तेहि कर एकांतिक हि जेते । भक्त सो श्रेष्ठ रहावे ते ते ॥\n\n एकांतिक धर्म जितना जिनमें । श्रेष्ठ भक्त रहे तितना तिनमें ॥\n\n एकांतिक धर्म में कसर जितना । उतरते भक्त रहेउ तितना ॥\n\n एकांतिक धर्म जामें जेसा । भगवान के निवास तामे तेसा ॥"],"mt":false,"gl":null,"a":false},{"i":1040,"k":"para","g":"બરેલીમાં નીલકંઠવર્ણીએ પુરજનોને વાત કરતાં કહ્યું, “સત્પુરુષ હોય તે ધર્મનો ભંગ ન કરે. જીવનું અજ્ઞાન ટાળી તેને શુદ્ધ કરે. જીવની કુસંગમાં જેટલી રુચિ રહે તેટલો તે અશુદ્ધ છે. સત્પુરુષના સંગે જેટલો તે શુદ્ધ થાય તેટલો પ્રગટ ભગવાનનો નિશ્ચય તેને થાય. સત્પુરુષનો યોગ જેટલો રહે તેટલો તેને સત્સંગ કરવાનો ભાવ જાણવો. ભગવાન વિના કોઈ વાત કાને ન ધરે તે સત્પુરુષનું લક્ષણ છે. ભગવાનના સ્મરણ વિનાની જે પળ ગઈ તેને હાનિ સમજે. અધર્મ સર્ગનો દૂરથી ત્યાગ કરે, ભગવાન વિના બીજું વ્યસન હોય નહિ. હરિનાં ચરિત્રોને અમૃતસિંધુ તુલ્ય જાણે. તેને કહેવા-સુણવામાં સદા અનુરાગ ધરે.”","e":null,"s":["2/10/30-37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1041,"k":"para","g":"નીલકંઠવર્ણીએ પૂનામાં બાજીરાવ નૃપને સત્પુરુષની ઓળખ આપતાં કહ્યું, “સત્પુરુષ ચિંતામણિ સમાન હોય છે. તેની સમીપ જઈને મનુષ્ય, જેવું ચિંતવે તેવું તેને મળે છે. એ ચિંતામણિ એવી છે જે બધાનું ભલું ઇચ્છે છે. સત્પુરુષ કદી કોઈને દુઃખી કરતા નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1042,"k":"para","g":"“જેમ નાવનો સ્વભાવ તારવાનો છે, તેમાં ઊંચ-નીચ જે કોઈ બેસે તેને નાવ તારે છે. સત્પુરુષ નાવ સમાન છે, તેનો આશ્રય કરે તો અપાર ભવસાગરથી તે જીવને પાર ઉતારે છે.”","e":null,"s":["2/50/36-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1043,"k":"para","g":"લોજમાં શ્રીહરિએ સંતોને કહ્યું, “ધ્યાન દઈને સાંભળો, જેને પૂર્વ જન્મનાં ભાગ્ય ઉદય થયાં હોય તેને સંતની સેવા કરવાની ઇચ્છા થાય છે. મનમાન્યાં જપ, તપ, તીરથ, વ્રત આદિ તો સૌ કોઈ કરે છે પણ તેનો ઉદ્ધાર થતો નથી. એવા જન ભવસિંધુમાં ડૂબીને દુઃખી થાય છે. પરંતુ ભગવાનના સંત એ ભવસિંધુમાં નાવ સમાન છે. જીવના ઉદ્ધાર માટે તેઓ પ્રવર્તે છે. અગમ-નિગમમાં આ વાત લખેલી છે.”","e":null,"s":["3/1/55-58"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1044,"k":"para","g":"શ્રીહરિએ ગોંડલના રાજા હઠીસિંહને એકાંતિક સંતની વાત કરતાં કહ્યું, “અન્યલોકનાં બધાં સુખો કરતાં પરમ એકાંતિક સંતની પદવી ઊંચી છે. અમને એ સંતમાં સર્વથી અધિક પ્રીતિ છે. એ સંતની પદવી જેવી અમને ગમે છે તેવી બીજી કોઈ પદવી ગમતી નથી. સંતની આગળ અમે દીન થઈ જઈએ છીએ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1045,"k":"para","g":"“સંતની પાસે હું અખંડ રહું છું, કારણ કે એ સંતને મારા સિવાય બીજા કોઈની આશા મનમાં નથી, એવા સંતના ગુણોનો કોઈ અંત લઈ શકે તેમ નથી. અમે પરમ એકાંતિક સંતથી કોઈને પર જાણતા નથી. જીવોને એ પરમપદની પ્રાપ્તિ કરાવવા માટે હવે હું સંત થયો છું.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1046,"k":"verse","g":"‘પરમ એકાંતિક સંત કહાઈ, ઈનસેં પર ન કોઈ રહાઈ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1047,"k":"verse","g":"સો પરમપદ દેવ હિ કાજા, અબ મેં ભયો હુઁ સંત હિ આજા.’","e":null,"s":["3/49/44-48"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1048,"k":"para","g":"શ્રીહરિએ ગોંડલ પુરવાસીઓને વાત કરતાં કહ્યું, “મોક્ષનો અંકુર પ્રગટે ત્યારે સંતનો સંગ શોધે છે. અનંત પ્રકારની વિદ્યા છે, પણ તે બંધનરૂપ કહેવાય છે. એક બ્રહ્મવિદ્યા જન્મ-મરણથી છૂટવાનું દ્વાર છે, તે શુદ્ધ સત્સંગ દ્વારા પ્રાપ્ત થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1049,"k":"para","g":"“સંત મળતાં મોક્ષનું દ્વાર પ્રાપ્ત થાય છે. સંત બતાવે તે માર્ગે ચાલવું. એનું નામ જ જપ, તપ અને વ્રત છે. સત્સંગ કરીને સંત-અસંતને ઓળખવા. સંત હોય તે ધન ત્રિયામાં પ્રીતિવાન ન હોય. અષ્ટ પ્રકારે તેનો ત્યાગ રાખે. હરિ વિના બીજામાં પ્રેમ રાખે નહિ. બીજાને પણ હરિમાં પ્રેમ કરાવે. જગતમાં અરુચિ થાય તેમ વાત કરે. જેવી પ્રીતિ જગતમાં છે તેવી સંત અને ભગવાનમાં હોય તો અભય પદને પમાય.”","e":null,"s":["3/51/40-50"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1050,"k":"para","g":"બંધિયાથી પીપળિયા જતાં શ્રીહરિએ રાજાઓને વાત કરતાં કહ્યું, “અમારા નિર્માની સંત અમારા વચનની મહત્તાને સમજે છે. આવા સંત જગતમાં ક્યાંય નથી. દેખાય છે મનુષ્ય જેવા પણ એ મનુષ્ય નથી. તેના ગુણો વર્ણવવામાં આવે તેવા નથી. તેમની સામર્થિ અપાર છે, પણ અમે તે છુપાવીને રાખી છે. અક્ષરધામમાંથી મુક્તોએ પણ અવતાર ધર્યા છે તે એકે એક સાધુ પલકારે બ્રહ્માંડ ઊભું કરે એવા છે, તેને અમે જ જાણીએ.”","e":null,"s":["3/52/22-25"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1051,"k":"para","g":"સરધારમાં શ્રીહરિએ સભામાં વાત કરતાં કહ્યું, “ભગવાન સિવાય વસ્તુમાત્ર દુઃખદાયી છે. એમ જાણ્યા વગર અનંત જન્મે પણ તેનો અભાવ થાય નહીં. જેને સત-અસતનું જ્ઞાન છે તેનું તાન ભગવાનમાં લાગે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1052,"k":"para","g":"“ભગવાનમાં જીવ જોડાય એવી જે કંઈ પ્રવૃત્તિ છે તે નિવૃત્તિ જ છે - એમ એકાંતિક ભક્ત જાણે છે. તે એકાંતિક ભક્ત વિના બીજા તેને એક સમાન માને છે. એકાંતિક ભક્ત અને અભક્તની રીત હંસ અને બગલા જેટલી ભિન્ન છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1053,"k":"verse","g":"‘હરિ મેં તાન મિલાવન કાજા, જો જો કરહિ પ્રવૃત્તિ સાજા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1054,"k":"verse","g":"સો નિવૃત્તિ સુખ હિ જાનો, ઓર નિવૃત્તિ દુઃખ પ્રમાનો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1055,"k":"verse","g":"યું એકાંતિક ભક્ત હિ જાને, ભક્ત બિન સબ એક હિ માને.’","e":null,"s":["3/56/17-23"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1056,"k":"para","g":"શ્રીહરિ ખાંભડા ગામના ગ્રામજનોની અપાર મુમુક્ષુતા જોઈને વાત કરવા લાગ્યા. જેમાં શ્રીહરિએ સૌને મોક્ષનું દ્વાર ઓળખાવી દીધું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1057,"k":"para","g":"શ્રીહરિ કહે, “આ લોકમાં જે અધર્મ અને પાપ આચરે છે તે મરીને જમપુરીમાં અતિ અપાર દુઃખ ભોગવે છે. એક એક જણને શિરે જન્મ જન્મનાં જે પાપ ચઢ્યાં છે તેનું માપ નીકળી શકે નહિ. પાપને ગણકારતાં નથી તે અજ્ઞાની છે. કેટલાય યુગ પછી મનુષ્યતન મળે છે. મનુષ્યતનમાં તેને આત્માનું શુદ્ધ જ્ઞાન થાય પછી અજ્ઞાન ટળે છે. રાતનું અંધારું સૂર્ય વિના ટળે નહિ. કરોડ આગિયા ભેગા થઈને પ્રકાશ કરે તોપણ રાતનું અંધારું ન હટે. તે પ્રગટ સૂર્યથી જ હટે. ચિતરામણના કોટિ સૂર્ય શા કામના? સાચા ગુરુ એ સૂર્ય તુલ્ય છે. એવા ગુરુ મળે ત્યારે અનંત જન્મનાં પાપ ટળે છે. સાચા ગુરુ કેવા હોય કે જેમના દ્વારા જ્ઞાનનો સાક્ષાત્કાર થાય, તેની ઓળખ દઈએ તે સાંભળો - પ્રથમ તો ધન અને નારી - બેઉનું બંધન તોડવું મુશ્કેલ છે. એ બન્ને બંધનો જેમણે કાપ્યાં છે. સ્ત્રીનો અષ્ટ પ્રકારે ત્યાગ રાખે છે. જગતથી સાચો વૈરાગ્ય જે પામ્યા છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1058,"k":"para","g":"“જેટલું કંઈ સ્વાદુ ભોજન કહેવાય છે તે પ્રથમ ભગવાનને ધરાવે છે. પછી પોતે એક પાત્રમાં ભેગું કરી, જળ મેળવી તેને સ્વાદ રહિત કરીને ઔષધની જેમ આહારમાં લે છે. જેઓ દૈહિક સુખને લેશમાત્ર કદી ઇચ્છતા નથી. જેને દેહસંબંધી વિચાર જ ટળી ગયો છે. કોઈ અપમાન કરે તો તે દેહને છે, એમ માનતા થકા હર્ષ પામે છે. કોઈ સન્માન કરે તો મનમાં ગ્લાનિ-શોક પામે છે. જેમને ભગવાનસંબંધી જ ઘાટ-સંકલ્પ નિરંતર થયા કરે છે. ભગવાન સિવાય બીજો ઘાટ થાય તો ઝેર તુલ્ય માની તેનો ત્યાગ કરી દે છે. ભગવાનસંબંધી ઘાટને અમૃત તુલ્ય ગણે છે. અમૃત તજી વિષપાન કરે તેને મલિન શબ તુલ્ય ગણે છે. ભગવાનની મૂર્તિનું અમૃત રસપાન નિરંતર કરતા હોય આવાં લક્ષણે યુક્ત સંતને સાચા સંત જાણવા. એમનું સાંનિધ્ય મળે એ સાક્ષાત્ ભગવાનનું સાંનિધ્ય માનવું. એવા સંત પંચવિષયને વિષ તુલ્ય સમજે છે, અને એટલે જ તેનું ક્યારેય પ્રતિપાદન કરતા નથી. એવા સાચા સંતને વેદપુરાણ વખાણે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1059,"k":"para","g":"“ભગવાનની ભક્તિ સિવાય જેમણે કોઈ વ્યસન રાખ્યું નથી. જે પોતાના મનની વૃત્તિ અહોનિશ ભગવાનમાં જોડી રાખે છે. એવા લક્ષણે યુક્ત સંતને ઓળખી તેમના સંગમાં નિરંતર રહેવું. તો જન્મોનાં ભયંકર પાપ પણ નાશ પામે છે ને જમપુરીનો ત્રાસ મટે છે. પાપ અને જમપુરીનાં દુઃખનો વિચાર કરી આવા સાચા સંતનો સદા સંગ કરવો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1060,"k":"para","g":"“બ્રહ્માંડનાં જીવ-પ્રાણીમાત્રને બે દિવસ આગળ-પાછળ પણ મરવાનું નિશ્ચિત છે. આવું મનુષ્ય તન વારંવાર મળતું નથી. જેને ભગવાનનું અપાર સુખ પ્રાપ્ત કરવાની ઇચ્છા હોય, તેણે સાચા સંતનો સત્સંગ કરવો.”","e":null,"s":["4/39/1-18"],"sv":["तेहि गामके जन सब, भाविक देखि अपार ।\n\n श्रीहरि बात करन लगे, मोक्षके देखाये द्वार ॥\n\n अधर्म पाप हि करत जन, यह लोक में जोय ।\n\n जमपुर सो दुःख पावहि, अति अपार हि सोय ॥\n\n एक एक जनके शिर, पापको नहि परमान कछु ।\n\n देखत नाहि लगिर, एहि सम नहि अग्यानि कोउ ॥\n\n कंई जुगको अग्यान, सो मेटन हें मनुष्य तन ।\n\n शुद्ध जब पावे ज्ञान, तब अग्यान को होत हरन ॥\n\n निशि को तम कहावत जोउ । सूर्य उदे विन नाश न होउ ॥\n\n कोटि पतंग करे प्रकाशा । तेहिसें न होवत निशिको नाशा ॥\n\n चित्र के सूर्य कोटिक करावे । तेहि कर राति अंधकार न जावे ॥\n\n सूर्य सम साचे गुरु मिले जबहि । अनंत पापकुं टारे तबहि ॥\n\n अब साचे गुरु कि कहत हें बाता । जीन करि ज्ञान होवे साक्षाता ॥\n\n धन त्रिया दोउ विकट पासा । तिनको जेहि किये नाशा ॥\n\n अष्ट प्रकारे करे जो त्यागा । संत तोहि साचा वैरागा ॥\n\n स्वादु अन्न कहावत जेता । प्रथम हरिकुं धरे तेता ॥\n\n निस्वाद कर ताकु खावे । उपाधवत करिके पावे ॥\n\n दैहिक सुख न इच्छे कबहु । युं विचार करे दिन सबहु ॥\n\n देहको जब कोउ करे अपमाना । तबहि हर्ष पावे सुजाना ॥\n\n करे सन्मान देह को कोउ । मनमें पावे शोक हि सोउ ॥\n\n हरिके घाट अनंत प्रकारा । करहि निरंतर वार हि वारा ॥\n\n अनित घाट कहावत जोइ । तिनको करत त्यागहि सोई ॥\n\n अनीत घाट विष सम जाने । हरि के घाट अमृत प्रमाने ॥\n\n अमृत तजी करे विष को पाना । सो मलिन मृतक समाना ॥\n\n हरि अमृत रस पान हि, करे निरंतर जोय ।\n\n सो साचे संत जानिये, हरि के सानिध सोय ॥\n\n पंच विषय गने विष सम, तिनकुं न कबु सुनात ।\n\n साचे संत सो कहत हें, वेद पुरान गुन गात ।\n\n हरि जीन व्यसन ओर, सबहि किने त्याग तेहि ॥\n\n हरि में वृत्ति जोर, रहवत हें अहुनिश जेहि ॥\n\n ऐसे साधु जानि, तिनको करना संग सदा ।\n\n पाप भयंकर आनि, जमपुर दुःख विचार कर ॥\n\n यह ब्रह्मांड के जीव हें जेहा । दो दिन आगे पाछें तेहा ॥\n\n मरना यामें नहि संदेहा । तुम जान लियो सब ऐहा ॥\n\n वारवार तन ऐसो न आवे । हरि भजे अपार सुख पावे ॥\n\n अपार सुख कि इच्छा जाकुं । सत्संग सब करना ताकुं ॥"],"mt":false,"gl":null,"a":false},{"i":1061,"k":"para","g":"ભેંસજાળમાં કાયાભાઈને ત્યાં શ્રીહરિ પધાર્યા. રાજભવનની પરસાળમાં સભા થઈ. ત્યારે જીવેન્દ્રે પ્રશ્ન પૂછ્યો, “જીવને મોક્ષનો અંકુર ક્યારે ઉદય થાય?” તેનો ઉતર આપતાં શ્રીહરિ કહેવા લાગ્યા:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1062,"k":"verse","g":"‘શુક સનકાદિક નારદ જૈસે, સાચે સંત મિલે જબ ઐસે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1063,"k":"verse","g":"સત્ય પ્રતીતિ આવે જબ તામેં, અતિ પ્રીત પ્રથમ કરે યામેં.’","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1064,"k":"para","g":"“શુક-સનકાદિક, નારદ જેવા સાચા સંત જ્યારે મળે ને તેમનામાં સાચી પ્રતીતિ આવે, પછી પ્રથમ તેની સાથે અતિ દૃઢ પ્રીતિ, આત્મબુદ્ધિ કરે. તેમનાં વચનને હિતકારી માની તે મુજબ વર્તે, બીજો સ્વાર્થ રાખે નહિ, એ સંતને પરમ પરમાર્થી માને, તેની સાથોસાથ પોતાની બુદ્ધિને તુચ્છ માનીને દીન-આધીનપણે નમતો રહે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1065,"k":"para","g":"“વ્યાવહારિક બુદ્ધિ અપાર હોય પણ લગારેય મોક્ષના કામમાં ન આવે, એ બુદ્ધિનું એટલું ફળ કે ખાન, પાન ને સન્માન મળે, પણ એ બુદ્ધિ દૂષિત છે. તેનું દુઃખરૂપી ફળ અહીં જ મળે છે. પરલોકનું વિચારે એ બુદ્ધિ સાચી એમ વિચારી સાચા સંતનો સમાગમ પ્રીતિપૂર્વક કરે તો સત્સંગના પ્રતાપે કરીને ધર્મ ને અધર્મનો ભેદ જાણ્યામાં આવે છે. ધર્મનું ફળ સુખ છે ને અધર્મનું ફળ દુઃખ છે - એમ જાણી ધર્મને માર્ગે ચાલે ત્યારે મોક્ષનો અંકુર પ્રગટે. એ અંકુરને વિઘ્ન કરનારનું પછી ધ્યાન રાખે, રાત-દિવસ તેનું જતન કરે. એમ કરતાં તેમાંથી ઉત્તમમાં ઉત્તમ વૃક્ષ બની આવે છે. વૃક્ષ મોટું થાય છતાં પણ તેને કુસંગરૂપી ઊધઈનો ભય રહે છે, માટે કુસંગનો વિશ્વાસ કદી ન કરે. સત્સંગમાં નિર્દોષબુદ્ધિ રાખે, દિન દિન પ્રત્યે સૌમાંથી ગુણ ગ્રહણ કરતો રહે ત્યારે તેને મોક્ષરૂપી અંકુર ઉદય થયાનું મહાફળ મળે છે.” એમ શ્રીહરિએ ઉત્તર કર્યો.","e":null,"s":["4/68/30-40"],"sv":["शुक सनकादिक नारद जेसे । साचे संत मिले जब ऐसे ॥\n\n सत्य प्रतिति आवे जब तामे । अति प्रित प्रथम करे यामे ॥\n\n ताके वचन लगे हितकारि । स्वारथ न जनाय लगारि ॥\n\n परम परमारथि संतकु जाने । निज बुद्धिकुं तुच्छ प्रमाने ॥\n\n व्यवहारिक बुद्धि होय अपारा । मोक्ष में काम न आत लगारा ॥\n\n खानपान मिले सन्माना । इतनो फल यामें रहाना ॥\n\n दुषित बुद्धि जो होवे जाई । इहाँ के इहाँ दुःख फल मिले ताई ॥\n\n परलोक में सुख मिले अनंता । ऐसि बुद्धि कर बुद्धिवंता ॥\n\n संत समागम करिके प्रीता । सत्संग करे अति हिता ॥\n\n सत्संग को ऐसो है प्रतापा । जाने में आवे धर्म रु पापा ॥\n\n पाप धर्म को फल विचारे । सुखदुःख दृढ दिलमें धारे ॥\n\n मोक्ष अंकुर उदे तब होवे । विघ्न करन ताकुं पिछे जोवे ॥\n\n रात-दिन तेहि करे जतनाई । जत्न विन न उदे होय ताई ॥\n\n उत्तम में उत्तम जो वृक्ष कहावे । जत्न विना न कबु रहावे ॥\n\n उधेइ के कुसंग, ताको न करे विश्वास कबु ।\n\n निरदोष जानि सत्संग, दिन-दिन गुन ग्रहे हितकर ॥\n\n तबहि मोक्ष अंकुर, उदे होवे अधिक अधिक ।\n\n धारे विचारे उर, ऐसे उत्तर कियेउ तेहि ॥"],"mt":false,"gl":null,"a":false},{"i":1066,"k":"para","g":"અમદાવાદમાં સાંજના સમયે શ્રીહરિએ ચીમનરાવને વાત કરતાં કહ્યું, “સત્પુરુષનો દ્રોહ કરનારને હિરણ્યાક્ષ, કંસ અને રાવણ તુલ્ય જાણવા. આકડાના તૂરની જેમ તે ઊડી જાય છે. સત્પુરુષનો દ્રોહ કરનારની મતિ મોહાંધ થાય છે ને અંતે તે નાશ પામે છે.”","e":null,"s":["4/103/11-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1067,"k":"para","g":"શ્રીહરિ રાજકોટમાં લાખાજી નૃપને ત્યાં એકાંતિક સંતનો મહિમા કહેવા લાગ્યા, “અતિ ભાગ્ય ઉદય થયાં હોય, તેને સંતનો મહિમા જાણ્યામાં આવે છે. ભાગ્ય વિના ભેગા રહે, તોપણ સંતનો અવગુણ લે. સંતમાં રહેલા અપાર ગુણને તે દેખે નહિ. જેમ ઇતરડી ગાયના સ્તનમાં રહેવા છતાં દૂધ ત્યજી રુધિર પીએ છે, તેમ એવાને સાધુના સંગમાં પણ ઇતરડી જેવા જાણવા. ભગવાનનાં વચન યથાર્થ ન પાળે, તે મરીને રાક્ષસ થાય છે. પોતાને આત્મારૂપ માને ને સંતને દેહરૂપ માને, તે ખળ અને પાપી છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1068,"k":"para","g":"“સંતનાં વચન અનેક ભવની પીડા મટાડે એવાં નિર્મળ છે. તેમાં દોષ દેખાડે તેને માયાવી ખલ જાણવા. સંત નટના ખેલની પેઠે વચનરૂપી દોર ઉપર ચાલે છે, શૂરા અને સતીથી પણ અધિકપણે મરણ હાથમાં લઈને વર્તે છે. ભવ, બ્રહ્માદિ દેવો ને નારદ જેવા દેવર્ષિઓ સંતનું વર્તન જોઈ કંપે છે. પ્રકૃતિ-પુરુષ ને અક્ષરમુક્ત સુધીના સૌ ધન્ય ધન્ય ઉચ્ચારે છે. ભગવાનના જેટલા અવતારો થયા છે, તે પણ આવા સંતને ધન્ય ધન્ય કહે છે. તેવા સંતનું અક્ષરરૂપે વર્તન હોય છે, તેને નિર્મળ હૃદયવાળા દેખે છે. દેહરૂપ મેરુગિરિ આડે બેઠેલાને તે દેખ્યામાં આવતું નથી. મારા ભક્તે કીડી જેવાનો પણ દ્રોહ ન કરવો, એવી અમારી આજ્ઞા છે. સંતનો દ્રોહ કરે તે પાપીમાં પાપી છે. અક્ષરમુક્ત પણ આવા સંતની તુચ્છતા કહે તો તે નીચમાં નીચ છે. આ અમે સંતના સોગંદ દઈને કહીએ છીએ. તેમાં જરા પણ જૂઠ નથી. સંતની વારંવાર પ્રાર્થના કરવી અને સંતના દાસ થઈને વર્તવું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1069,"k":"para","g":"“સનકાદિકનું અપમાન જયવિજયે કર્યું તો રાક્ષસ થવું પડ્યું. ભગવાનના સેવક હતા તોપણ એવું થયું. ભગવાને તેમને કહ્યું કે હું સંતને આધીન છું. સંતનો અપરાધ પળમાત્ર સહન કરું નહિ. સંતનો દ્રોહ કરે છે તે મારો કંઠ છેદે છે. કોટિ કલ્પ સુધી પણ હું તેનું મુખ જોવા ઇચ્છતો નથી. મારો હાથ અપરાધ કરે તો તેને પણ કાપી નાંખું લક્ષ્મીથી પણ અધિક મને સંત પ્રિય છે. સંત મારું હૃદય છે, સંત મારો કંઠ છે, સંત મારાં નેત્ર છે. સંતનો થોડો દ્રોહ થાય તોપણ મને કરોડ ઘણો ડર લાગે છે. એવો ડર તો શિવનું ત્રિશૂલ કે ઇન્દ્રનું વજ્ર જોઈને પણ ક્યારેય લાગતો નથી. મારો અપરાધ કોઈ કોટિ વાર કરે તોપણ હું દુખાતો નથી, પરંતુ સંતનો અલ્પ અપરાધ કરે તેના પર કરોડ ઘણો દુખાઈ જાઉં છું. હું તેને કદી માફ ન કરું. સંત માફ કરે તો ભલે. સંત માફ કરે તો જ તે અપરાધનું પાપ ટળે છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1070,"k":"verse","g":"‘સંત કરે જબ માફ, તબ હોવત હે માફ તેહિ,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1071,"k":"verse","g":"તા વિન ટરત ન પાપ, સંત હિ કે દ્રોહિહુ કો.’","e":null,"s":["5/13/20-53"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1072,"k":"para","g":"“સંતના દ્રોહથી હું કરોડગણો ડરું છું. એવા સંતનો મુખ્ય ગુણ એ છે કે તેને મારા વિના કોઈનામાં સ્નેહ નથી. વળી, ધર્મ, જ્ઞાન, વૈરાગ્ય અને ભક્તિ એક એક ગુણ કરોડગણા તેનામાં રહેલા છે. એવા સંતની ચરણરજ હું ઇચ્છુ છું.” આવી કેટલીક વાતો શ્રીહરિએ રાજકોટમાં લાખાજીને ત્યાં ડુંગરજી અને અલર્ક રાજાને કરી.","e":null,"s":["5/13/53-60"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1073,"k":"para","g":"મોડા ગામે શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “સત્પુરુષની સેવા એ જ મોક્ષ છે. મોક્ષનો બીજો અર્થ નથી. એમ સમજનારા બહુ થોડા હોય છે. એમ સમજીને સત્પુરુષની સેવા કરે તેને અનાદિ મુક્ત જાણવા. તેઓ સત્પુરુષની સેવાને મોક્ષપદથી પણ અધિક માને છે. સ્વાર્થથી સેવા કરે તેને આધુનિક મનુષ્ય જાણવા.”","e":null,"s":["5/16/32-36"],"sv":["मोक्ष को अर्थ एक अर्थ न ओरा । ऐसे जन ही निकसे थोरा ॥\n\n ऐसे संत हरिजन में जेते । अनादि मुक्त जानना तेते ॥\n\n संत की सेवा करना जोऊ । मोक्ष पद से अधिक हे सोऊ ॥\n\n यूँ समझी सेवा करे जेहि । अनादि मुक्त समझना तेहि ॥\n\n स्वारथ सें सेवा करे जेऊ । आधुनिक जन जानना तेऊ ॥"],"mt":false,"gl":null,"a":false},{"i":1074,"k":"para","g":"શ્રીહરિએ પૂરના નૃપ પ્રત્યે વાત કરતાં કહ્યું, “આ સંતનું ચિંતવન પ્રીતિ પૂર્વક કરવું. જે તેનું ચિંતવન કરે છે તેને ચારેય દુઃખ ટળી જાય છે. જન્મ-મરણ, જમપુરી, ચોરાશી તેને માથે રહેતી નથી. આ સંતને જે ભાવથી જમાડે છે અને ચંદન, પુષ્પો, વસ્ત્રોએ કરીને વેળા-વેળાએ પૂજે છે એ મનુષ્ય જે જે લોકમાં જાય છે ત્યાં દેવતાઓ તેનું પૂજન કરે છે, આ વાત તે સત્ય જ છે અને તેનું ફળ સમય આવે દેખાય છે. સંતનું વચન જે માને છે તેનું ધર્મમાં વર્તન થાય છે. આવા સંતની મધ્યે પ્રગટ શ્રીહરિ બિરાજે છે, એવી પ્રતીતિ જેને આવે છે તે તત્કાળ અક્ષરધામ પ્રાપ્ત કરે છે. સંત-સમાગમ કરે છે તેને અક્ષરધામ દૂર રહેતું નથી.”","e":null,"s":["5/30/1-6"],"sv":["श्रीहरि कहत नृप प्रति, पुनि हित हि लाय ।\n\n यह संत को चिंतवन, करना हित लगाय ॥\n\n या को करत चिंतवन तेहि, चारुं दुख टरि जात ।\n\n जन्ममरण जमपुरि हि, चोराशी न रहात ।\n\n याकुं जेंवावत जेहि, अति करि कें भाव मन ।\n\n पूजत वेरवेर ते हि, चंदन पुष्प वसन करि ॥\n\n ताकुं पूजत देव, जो जो भुवन में जाय तेउ ।\n\n वचन सत्य हे एव, समे में फल देखात तेहि ॥\n\n या को वचन मांनत जेहा । तत्काल धर्म में वर्तत तेहा ॥\n\n प्रगट हरि कहावत जोउ । एसे संत मध्य राजत सोउ ॥\n\n ताकि जो आवे प्रतिता । अक्षयधाम सो सद्य लहिता ॥\n\n संत समागम करे जेहि । ताकुं दूर नहि हे तेहि ॥"],"mt":false,"gl":null,"a":false},{"i":1075,"k":"para","g":"કચ્છમાં તેરા ગામે શ્રીહરિ જમી રહ્યા પછી સંતો અને નૃપને વાત કરતાં કહ્યું, “જેમ જેમ સત્સંગ કરે છે, તેમ તેમ જીવની માયા ટળતી જાય છે. સત્પુરુષ તેને હરિનું શરણું લેવડાવે છે. નિયમ ધરાવી શુદ્ધ કરે છે. પછી જેમ જેમ સત્સંગ કરે, તેમ તેમ તેનામાં મુક્તપણું પ્રગટતું જાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1076,"k":"para","g":"“વર્તમાન ધાર્યા એટલે તત્કાળ ‘સત્સંગી’નું વિશેષણ મળ્યું, કુસંગના માર્ગથી દૂર રહ્યો. પછી સત્પુરુષનો સંગ તજી કુસંગ કરે તો તે ઘટતો ઘટતો નીચ યોનિને પામી જાય છે, માટે ઉત્તમનો સંગ કરવો. જે કંઈ માયિક વસ્તુ કહેવાય છે તે બંધો કુસંગ સમજવો. સત્પુરુષ માયાથી મુક્ત છે, અન્ય જીવ બદ્ધ છે. બદ્ધનો સંગ કરે તો અમાયિક પણ માયિક થઈ જાય. મુક્તનો સંગ કરે તો માયિક પણ અમાયિક થઈ જાય.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1077,"k":"verse","g":"‘માયિક અમાયિક હોત હે, અમાયિક માયિક હોત;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1078,"k":"verse","g":"બધ અબધ કો સંગ કર, દેખાત અંતર મેં જોત.’","e":null,"s":["5/44/21-25"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1079,"k":"para","g":"શ્રીહરિએ નવાનગરના રાજાએ શ્રીહરિને પૂછ્યું કે, “તીર્થમાં જવાથી મોક્ષ થાય છે એમ શાસ્ત્રો કહે છે પણ મને સંશય થાય છે કે તીર્થમાં જ પાપ થતાં હોય ત્યાં શું સમજવું?” શ્રીહરિએ તેનો ઉત્તર કરતાં કહ્યું, “સત્પુરુષના સંગ વિના તીર્થો ફળીભૂત થતાં નથી. જેમ લાકડામાં અગ્નિ છે, પણ ચકમકના ઇલમથી પુરુષ તેને પ્રગટ કરી આપે છે. તેમ સત્પુરુષ મળે ને તેમાં પ્રતીતિ લાવીને તેમની સેવા કરે, તેમના વચનમાં ટૂકટૂક વર્તે તો તેનો મોક્ષ થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1080,"k":"para","g":"“એટલે સત્પુરુષને ઓળખવા એ સાધનમાત્રમાં મુખ્ય સાધન છે, કારણ કે સત્પુરુષના સંગ વિના તીર્થથી કોઈનો મોક્ષ થતો નથી. તીર્થનું ફળ એટલું જ છે કે કોઈક વખત ત્યાં સંત મળી જાય. સંત જીવના સંશય છેદી ભગવાનનો મેળાપ કરાવી દે છે. અનાદિ અજ્ઞાન કે જે જીવને કારણ શરીરરૂપે વળગ્યું છે, તેને સંત ઓળખાવી ટાળી દે છે. સત્પુરુષ વિનો પોતાના આત્મસ્વરૂપનું જ્ઞાન થતું નથી, પછી ભલે વેદાદિ શાસ્ત્રોને ભણે તોય તે અજ્ઞાની રહે છે. મોક્ષની વાત તો તેમાં પડી છે, પણ પોતાની મેળે તે સમજાતી નથી, જ્યારે સત્પુરુષ મળે છે ત્યારે તત્કાળ મોક્ષની વાત બતાવી દે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1081,"k":"para","g":"“સત્પુરુષના સંગ વિના વેદાદિ શાસ્ત્રો ભણે તોય તે મોક્ષના માર્ગથી દૂર થતો જાય છે. તેના હૃદયમાં વિશેષ વિભ્રાન્તિ પેદા થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1082,"k":"para","g":"“ટૂંકમાં, અનંત વાતોનો ગલિતાર્થ એ છે કે સત્પુરુષને ઓળખી લેવા. જ્યારે સત્પુરુષ ઓળખાશે ત્યારે સાધન બધાં સંપૂર્ણ થયાં જાણવાં.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1083,"k":"para","g":"“સંત જ્યાં સુધી ઓળખાયા નથી, ત્યાં સુધી મનુષ્યદેહ મળ્યો, તે ન મળ્યા તુલ્ય છે. પછી રાજા કે પંડિત થયો કે ન થયો, અનંત તીર્થ ફર્યો કે ન ફર્યો - બધું સરખું છે. અમે આટલો સિદ્ધાંત દૃઢ માન્યો છે, તે તમારી પાસે કહ્યો.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1084,"k":"verse","g":"‘સંત જ્યાં લગી ના ઓલખાય, ત્યાં લગ સો ન કછુ કરાય,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1085,"k":"verse","g":"મનુષ્ય દેહ આઈ સો ન આઈ, નૃપતિ ભયે કહા કહાએ,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1086,"k":"verse","g":"પઢે ગ્રંથ સો ન પઢે કાઉ, તીર્થધામ અનંત કરે તાઉ,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1087,"k":"verse","g":"હમ સિદ્ધાંત માને હૈ ઇતના, તુમ આગે કહે જાનત જિતના.’","e":null,"s":["5/27/11-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1088,"k":"para","g":"કચ્છમાં માંડવી બંદરે હરિજનો પ્રત્યે વાત કરતાં શ્રીહરિ કહે, “વિષયમોહરૂપી મહા સમુદ્ર છે, તેમાં જગત બધું ડૂબ્યું છે. ડૂબતા જીવોનો ઉદ્ધાર સંત કરે છે. સંત તેની બાંહ ગ્રહે છે. મહાસમુદ્રમાંથી બહાર કાઢે છે. જગત મહાકાળના મુખમાં ગરક થતું જાય છે તેની કોઈને ગમ નથી. તેથી જીવ દુઃખ પામે છે. કોઈ એક જીવને કાળના મુખમાંથી ઉગારી લે ને તેનો ઉદ્ધાર કરે તો એક બ્રહ્માંડના ઉદ્ધારનું ફળ તેને મળે છે.”","e":null,"s":["5/37/37-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1089,"k":"para","g":"કચ્છમાં કોટડા ગામે શ્રીહરિએ નૃપ તથા સંતો-ભક્તોને વિવેકની વાત કરતાં કહ્યું, “જન્મ-મરણ, નરક-ચોરાશીના દુઃખથી મુક્ત થઈ સુખ પ્રાપ્ત કરવું હોય તો તેણે વેદ-શાસ્ત્ર-પુરાણોમાં આસ્તિક મતિ રાખવી. ભગવાન કે ભગવાનના પ્રગટ સંત મળે ત્યારે જીવમાં આસ્તિક મતિ આવે છે. અમારા આશ્રિતે અધર્મ કરવામાં ડરવું. જેને મોક્ષ માર્ગે ચાલવું છે તેમણે અમારું વચન અંતરમાં દૃઢ કરવું. જેટલું વિષમાત્ર કહેવાય છે તેનું મૂળ પારખવું. બે દિવસ પણ જીવવું હોય તેણે એ વિષનો હૃદયથી ત્યાગ કરવો. ભગવાન અને ભગવાનના સંતો-ભક્તોનો અભાવ લેવો એ વિષ છે. જે અભાવ લેતો હોય તેનો વિશ્વાસ કરે તેને પણ અસુર જાણવો. પરિપક્વ અસુરને સાચા સંત ગમતા નથી. સંત વાત કરે તો તે તરત ત્યાંથી ઊઠી જાય છે. અસુરનું બળ હોય ત્યાં સંતે વિચાર કરીને બોલવું. દેશકાળ પરખી નીકળી જવું.”","e":null,"s":["5/39/29-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1090,"k":"para","g":"શ્રીહરિ તેરાપુરના જનોની સંત પ્રત્યે પ્રીતિ જોઈને તેમને વાત કરવા લાગ્યા, “સાચા સંત જ્યારે આવીને મળે છે ત્યારે જીવને બંધનથી મુક્ત કરે છે. ભગવાન વિના બીજે પ્રીતિ એ જ બંધન છે. જીવ અજ્ઞાનવશ હોઈ તેની દૃષ્ટિમાં આ બંધન જણાતું નથી. વળી, પૂર્વે અનંત પાપ કરીને આવ્યો છે એટલે સહજે વિષયમાં રાગ થાય છે, જે મૂઆ સુધી જીવને છોડતો નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1091,"k":"para","g":"“વિષયવાસનાને કારણે લખચોરાશીમાં જીવ અનંતવાર જન્મ્યો છે અને નરકનાં દુઃખ ભોગવ્યાં છે છતાં વિષયનો અભાવ થતો નથી. જ્યારે તેને સાચા સંત મળે છે ત્યારે વિષયના રોગથી મુક્ત કરે છે. કારણ કે એ સંત ધન્વંતરિ વૈદ્ય જેવા છે. અસાધ્ય રોગને પણ મટાડે છે. આત્માના સ્વરૂપનું જ્ઞાન આપીને અજ્ઞાન-અંધારું ટાળે છે. સંત વિના અન્ય કોઈ મોક્ષના દાતા નથી. પોતે વિષયથી મુક્ત છે. જે મુક્ત હોય તે બીજાને મુક્ત કરે, જે બંધાયેલો છે તે શું છોડાવે? સંત માયાથી મુક્ત છે તો તેની વાત જીવને માન્યામાં આવે છે. જેને ધન, સ્ત્રી ને રસાસ્વાદમાં આસક્તિ હોય ને તે જનોને ઘણો બોધ કરે, પણ તેની વાત માન્યામાં આવતી નથી. જેને વિષયનો ત્યાગ નથી તેના બોધથી ક્યારેય બીજાને ત્યાગ ઉદય થતો નથી. વિષયનો ત્યાગ કરનાર સંત બડભાગી છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1092,"k":"para","g":"“જગતમાં સાર વસ્તુ જણાતી હોય, પણ તેમાં જો ભગવાનનો સંબંધ ન હોય તો તે અસાર છે. સત્પુરુષ ભગવાન વિના બધું અસાર સમજે છે. હરિભજનમાં સાર માનીને ભગવાનમાં દૃઢ પ્રીતિ રાખે છે.”","e":null,"s":["5/45/24-40"],"sv":["श्रीहरि प्रीति जोई के तेहि । वात करन कु लगे एहि ॥\n\n साचे संत मिलत जब आई । जिय के बंधन देत छोराई ॥\n\n हरि विन ओर में प्रीति जो, सो बंधन हे ताय ।\n\n जिय तेहि जानत हित कर, अज्ञान सो अति रहाय ॥\n\n अनंत हि पाप करिके, मोह छाये मति माहिं ॥\n\n विषे में होवत राग अति, मुवे छूटत नाहिं ॥\n\n संत मिले तेहि साचे जबहि । हित करि कहे जिय कुं तबहि ॥\n\n धनवंतरि वैद्य है तेहा । असाध्य रोग हे टारि एहा ॥\n\n संत विन मोक्ष न दाता कोई । आपे विषे से छुट गये सोई ॥\n\n छुटे होय ओरकुं छोरावे । ताकि वात माने में आवे ॥\n\n धन त्रिय रसास्वाद में, आसक्ति हे जाहि ।\n\n करे सो जन वारता, माने में न आवे ताहि ॥\n\n त्याग बिन विषय का, कबहु न होवे त्याग ।\n\n विषय कु जेहि त्याग करे, सोई संत बड़ भाग ॥\n\n हरि बिन जितनो सार, सो सब माने असार तेहि ॥\n\n करि के दृढ़ निरधार, लाभ अलाभ विचार कर ॥"],"mt":false,"gl":null,"a":false},{"i":1093,"k":"para","g":"પીપળી ગામે દાદાભાઈને ત્યાં શ્રીહરિએ સંત-અસંતની ઓળખ આપતાં કહ્યું, “બધા પથ્થર કંઈ પારસમણિ હોતા નથી. ચિંતામણિ પણ પથ્થર છે, તેના ગુણ તો વળી બહુ જુદા છે. ધાતુ પણ ઘણી જાતની છે અને દૂધ પણ ઘણી જાતનાં છે, પણ બુદ્ધિશાળી જનો તેના ભેદને સમજે છે. તેમ સંત-સંતમાં પણ ભેદ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1094,"k":"para","g":"“વિવેક વિનાના દરેકની સાથે સરખો વ્યવહાર કરે છે, તે બુદ્ધિહીન છે. તે ક્યારેય સુખી થાય નહિ. જગતમાં રાજા-રાજામાં જેમ ભેદ છે તેમ સંત સંતમાં પણ ભેદ છે. તે વિવેકી માણસને સમજાય છે. વિવેકીને અનુભવજ્ઞાન છે. સૂર્ય જગતમાં બહાર પ્રકાશ કરે છે, પણ જ્ઞાનરૂપી સૂર્ય અંતરમાં પ્રકાશ કરે છે. અંતરમાં અજ્ઞાન અંધારું હોય ત્યાં સુધી મોક્ષનો માર્ગ સૂઝતો નથી. જ્ઞાની-વિવેકી હોય તે સાચા સંતને ઓળખી લે છે. સંત સંતના ભેદ કહેતાં પાર ન આવે એટલા છે. નામે રૂપે સમાન દીસે પણ વર્તને કરી ભેદ નજરમાં આવે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1095,"k":"verse","g":"‘સંત સંત મેં ભેદ અતિ, કહત ન આવે પાર;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1096,"k":"verse","g":"નામ કરિ નહિ ભેદ કછુ, વર્તન કરિ ભેદ અપાર.’","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1097,"k":"para","g":"“જીવમાં મોક્ષનો અંકુર પ્રગટાવી દે તેને ખરા અર્થમાં સાધુ જાણવા. તેની દૃષ્ટિ અજાણતાં પણ રમણીય વિષયમાં જતી નથી. લોકોને મન અતિ રમણીય વિષય છે, તે સત્પુરુષને મન અત્યંત અસાર છે, વિષ્ટાની પણ વિષ્ટા છે ને તેની પણ વિષ્ટા છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1098,"k":"verse","g":"‘મોક્ષ અંકુર ઉપજાહિ, સો જથાર્થ સંત તેહિ;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1099,"k":"verse","g":"અજાનન દૃષ્ટિ તાહિ, રમણિક વિષય કું દેખકર.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1100,"k":"verse","g":"જ્યું જ્યું રમણિક સાર, વિષય દેખહિ નજર કર;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1101,"k":"verse","g":"જાનહિ અતિ અસાર, મલ કે મલ તેહિ મલ.’","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1102,"k":"para","g":"“ભગવાન વિના ક્યાંય માલ ન માને તેને સાચા સંત જાણવા. સાચા સંત છાના રહેતા નથી, વર્તનથી તે ઓળખાઈ જાય છે. સાચાનું વર્તન છુપાવ્યું છુપાતું નથી. અંધ હોય તેને ન દેખાય. સાચા સંતનું વર્તન જોવા છતાં તેને જ ન માને તે આંધળા ને બહેરા સમજવા.”","e":null,"s":["5/69/1,32"],"sv":["हरि विन सार न देखत कोऊ । साचे संत समझना सोऊ ॥\n\n साचे संत सो रहत न छाने । वर्तन में तेहि आत पिछाने ॥\n\n साचे वर्तन होवे जेहा । छपाये सो छपात न तेहा ॥\n\n अंध होय सो देखे नाहि । बेरे होय शब्द न सुनत ताहि ॥\n\n संत कुं देखि न माने जेहू । अंध बेरे समझना तेहू ॥"],"mt":false,"gl":null,"a":false},{"i":1103,"k":"para","g":"કારિયાણીમાં શ્રીહરિએ વાત કરતાં કહ્યું, “સંતનો યોગ થાય છે ત્યારે સત્ય વાત હૃદયમાં ઠરે છે, અંતર નીરોગી બને છે ત્યારે શ્રીહરિના સ્વરૂપનું જ્ઞાન થાય છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1104,"k":"verse","g":"‘સંત કો હોવે જોગ, સત્ય વાત તબ ઠરે ઉર;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1105,"k":"verse","g":"અંતર હોય નિરોગ, હરિ કો જ્ઞાન તબ હોત ઉર.’","e":null,"s":["5/71/16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1106,"k":"para","g":"સાયલાથી શ્રીહરિ જેઠસુર વિપ્રને ગામે પધાર્યા. ગ્રામજનોને વાત કરતા કહેવા લાગ્યા, “સંતની ઓળખાણ થાય છે ત્યારે જીવ જન્મમરણના બંધનથી છૂટે છે. સાચા સંત પારખ વિના ઓળખાતા નથી. જીવનું કલ્યાણ કરનાર સંત જગતથી સદા નિઃસ્પૃહ હોય છે. નારી અને ધનમાં કદી લપટાતા નથી. ઉપદેશમાં પણ નારી અને ધનની જે નિંદા કરતા હોય તેને સાચા સંત જાણવા. વિષયમાત્રને ઝેર સમાન જાણીને તેનો ક્યારેય સંગ થવા દેતા નથી. દેહમાં પ્રાણ હોય ત્યાં સુધી આ મુજબ વર્તન રાખે છે.”","e":null,"s":["6/37/34-36"],"sv":["संत होय निःस्पृह रहावे । नारि धन में नहि लपटावे ॥\n\n नारि धन कि करे निंदा जेही । साचे संत हि जानना तेहि ॥\n\n विषयमात्र कहावत जेता । ताकुं जानत विष सम तेता ॥\n\n ताको संग न करत कबऊ । देह में प्राण रहे त्यां लगऊ ॥"],"mt":false,"gl":null,"a":false},{"i":1107,"k":"para","g":"શ્રીહરિ માંગરોલમાં સર્વ સભાજનોને કહે, “આ પુરમાં અમે પૂર્વે ઘણા ચમત્કારો બતાવ્યા, સમાધિ કરાવી હતી. હવે અમે જુદી રીત રાખી છે. ચમત્કારને છોડી દીધો છે. ચમત્કાર જોઈ અલ્પમતિ જનનું ચિત્ત વિભ્રાંત થઈ જાય છે. માયિક દેહના યોગે કરીને સત્ય પણ માયિક થઈ જાય છે. અમે કરેલી વાત અપાર છે, પણ તુચ્છમતિ તેને સમજી શકતો નથી. સમાધિ, ધ્યાન, ધારણા દેવોને પણ દુર્લભ છે. યોગાભ્યાસ કરે તોપણ સમાધિ થાય નહીં. ખરના (ગધેડાના) અંગ પર કેસર-ચંદનનો લેપ કરે, કપૂરના હાર પહેરવે પણ શબ્દ કરે ત્યારે તેનું ખરપણું ઉઘાડું થઈ જાય છે. મોટાનો પ્રતાપ અપરંપાર છે. જેનો પાર ભવ, બ્રહ્માદિ દેવતાઓ પણ લઈ શકતા નથી. જેમ ફૂટેલા પાત્રમાં પાણી સ્રવી જાય, તેમ તે પ્રતાપ દેખીને તેને તરત ભૂલી જાય છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1108,"k":"verse","g":"‘બડે઼ મેં પ્રતાપ હે અપરમપારા, ભવબ્રહ્માદિક લહત ન પારા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1109,"k":"verse","g":"પ્રતાપ દેખિ તરત ભૂલ જાવે, ફુટે ભાજન મેં નીર ન રહાવે.’","e":null,"s":["6/69(68)/30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1110,"k":"para","g":"જૂનાગઢમાં શ્રીહરિએ સંતોનાં મંડળ બાંધ્યાં અને ઉપદેશ આપતાં કહ્યું, “હે સંતો! તમારો દ્રોહ કર્યા વિના અધર્મીનો નાશ થતો નથી. સાચા સંતનો જે દ્રોહ કરે છે તેનો તરત જ વિનાશ થાય છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1111,"k":"verse","g":"‘એધર્મી ન હોવહિ નાસ, તુમારો દ્રોહ અતિ કરે બિન;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1112,"k":"verse","g":"તર્ત હોવહિ વિનાસ, સાચે સંત કે દ્રોહ કર.’","e":null,"s":["6/81/27"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1113,"k":"para","g":"ગાલોલના માવા ભક્તને શ્રીહરિએ પ્રશ્નનો ઉત્તર આપતાં કહ્યું, “સત્સંગનો અર્થ છે શાસ્ત્રમાં વર્ણવેલા એવા સાચા સંત. એવા સંતમાં તીર્થમાત્ર સમાયાં છે ને તપનું ફળ પણ એ જ છે.” એમ કહી શ્રીહરિએ એ સંતની ઓળખ આપતાં કહ્યું:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1114,"k":"para","g":"“એ સંત સરળચિત્ત છે. એ બધાને ગમતા હોય છે, એટલે જ મુમુક્ષુજન તેનામાં પ્રીત કરે છે. એ સંત બધાના મિત્ર છે. કંઈ કહેવાનું હોય તે મિત્રપણે રહીને સૌને કહે છે, ને હિત કરે છે. ગંગા નદી જેમ જગતને પવિત્ર કરે છે, તેમ એવા સંત ત્રણે લોકને પવિત્ર કરે છે. એવા સંત સ્વયં અંતરથી પવિત્ર છે તો પોતાના સંબંધમાં આવનાર સૌને પવિત્ર કરે છે. વળી, પોતામાં જે ગુણો છે તે ગુણો બધામાં તેઓ જુએ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1115,"k":"para","g":"“અન્યમાં અનંત અવગુણ હોવા છતાં સાચા સંત તે અવગુણને લેશમાત્ર જોતા નથી. અવગુણ જોવો તે અસંતનું લક્ષણ છે. એટલે જ અસંત પર કોઈને ભાવ થતો નથી. અસંત શ્વાન, શૂકર, ગર્દભ અને કાક સમાન છે. જે ઊંચાં ખાન-પાન તજી વિષ્ટાનો આહાર કરે છે!","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1116,"k":"para","g":"“હંસ અને બગલા રંગે સરખા લાગે, પણ બન્ને જુદા છે તેમ સંત અને અસંત જુદા છે. સાચા સંત ક્યારેય કઠોર વચન ઉચ્ચારે નહિ. એમની વાણીમાં અમૃત વરસતું હોય છે. તેમની વાત જે સાંભળે તેની મતિ પવિત્ર થાય છે ને સૌનાં હૃદયમાં તેમના ગુણો વસે છે. અનંત અવગુણો ધોવાઈ જાય છે. દોષોનો નાશ થાય એવો હિતકારી અભ્યાસ સાચા સંત શીખવે છે. બીજાને સુખ પમાડે એવાં વચન ઊચરે છે. સંત થઈને કટુવાણી બોલે તેને સંત ન કહેવાય. સંત છે કે અસંત - તે વાણી પરથી માલૂમ પડે છે. વાણી ક્યારેય છૂપી છુપાતી નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1117,"k":"para","g":"“સંતનો વેષ લીધો પછી સંતના ગુણ ન આવે તો તે વૃથા છે, તેનાથી મનુષ્યને ત્રાસ ઊપજે છે. સાધુતા વગર સંત કહેવાય જ નહિ, પછી ભલે તે કોટિ પ્રકારે વાત બનાવતો હોય! સંતમાં નિષ્કપટપણાનો ગુણ દેખી જગત તેમાં આકર્ષાય છે. જે નિષ્કામી વ્રતનું દૃઢ પાલન કરતા હોય, અંદર-બહાર નિષ્કપટ (દંભ રહિત) હોય, શાંત ગુણને સદા ધારણ કર્યો હોય, શત્રુનું છિદ્ર પણ ક્યારેય પ્રકાશિત ન કરતા હોય - એવા સંત જગતનો આધાર છે. આવા સંતમાં રહેલા શુભ ગુણો સર્વે ભગવાનના ગુણ છે. એવા સંત અનંત જીવોના મોક્ષ કરવા પ્રગટ થાય છે. અને એવા શુભગુણોથી શોભતા એ સંત શ્રીહરિનું અક્ષરધામ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1118,"k":"para","g":"“એવા શુભ ગુણે યુક્ત અક્ષરધામરૂપ સંતને શ્રીહરિ ક્યારેય તજી શકતા નથી. (અર્થાત્ શ્રીહરિ એવા સંતથી ક્યારેય પૃથક્ રહી શકતા નથી) અનંતકોટિ બ્રહ્માંડોમાં અનંત નામરૂપે ભગવાન પ્રકાશે છે, જ્યાં જેવું કામ ત્યાં તેવું અવતાર-ચરિત્ર કરે છે. તેમનું આવવું-જવું ને અદૃશ્ય થવું કોઈના કળ્યામાં આવતું નથી. અહીં પ્રગટ થાય છે, પણ અક્ષરધામમાં તેવા ને તેવા જ સદા રહે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1119,"k":"para","g":"“એમનાં ચરિત્રો ભક્તને કાજે છે. જીવનું અનાદિ અજ્ઞાન આવાં ચરિત્રો કરીને તેઓ ટાળે છે. અને ‘ચરિત્રો દ્વારા અનાદિ અજ્ઞાન ટાળવું’ એવો ધારો - નિયમ પણ નથી. પોતે પ્રત્યક્ષ હોય ત્યારે પોતે ટાળે છે, ને પછી પોતાના (અક્ષરધામરૂપ) સંતને એ જીવનું અનાદિ અજ્ઞાન ટાળવા આ ભૂમંડળ પર રાખે છે. એ પુરુષોત્તમનો મહિમા જેવો ને જેટલો છે, તેવો ને તેટલો યથાર્થપણે એ સંત દ્વારા જાણ્યામાં આવે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1120,"k":"para","g":"“શ્રીહરિ જે કરે તેમાં કોઈ ભૂલ-ખામી હોય નહીં. - આ રીતે જે સમજે તે એકાંતિક છે. ‘હરિ કરે તામેં ભૂલ ન કોઈ, એસે સમજે એકાંતિક સોઈ’ પછી તેનામાં દુનિયાદારીની સમજ આવે કે ન આવે - એ માટે શ્રીહરિને કોઈ દાવો નથી. એવા સંતને જે ઓળખે છે તેનું કલ્યાણ થાય છે. જે નથી ઓળખતા તેને લખચોરાસીમાં અનંત દુઃખ ભોગવે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1121,"k":"para","g":"“પાકા હરિભક્તની પરખ એ છે કે તેને ભગવાન ને ભગવાનના સંતમાં જેવી પ્રીતિ છે તેવી બીજામાં પ્રીતિ થતી નથી. વળી, બીજું એ કે ભગવાન અને સંતનો આશ્રય કરવામાં જે કોઈ વિઘ્ન કરે તેને શત્રુ જાણીને તેનો ત્યાગ કરી દે. વળી, ચૌદ લોકના સર્વ સુખને સત્સંગ આગળ તુચ્છ ગણે છે. એનો એકનો એક રંગ કહે ને તે દિનદિન વૃદ્ધિ પામતો રહે, પણ લેશમાત્ર મોળો ન પડે. આવા સંત-હરિજનથી શ્રીહરિ અળગા રહેતા નથી. માટે જેને મોક્ષની ઇચ્છા હોય એવા મોક્ષભાગી મનુષ્યે એવા સંતને ઓળખીને તેમનામાં અનુરાગ (હેતપ્રીત) કરવાં. જે કંઈ સામાન્ય કે વિશેષ વચનો ભગવાન કે સંતે કહ્યાં હોય તે જ વચનો ભક્ત માટે વિધિ-નિષેધ બની જાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1122,"k":"para","g":"“એવા સંત મન-વચન-કર્મે અનંતકોટિ બ્રહ્માંડોમાં જૂ કે લીખ સુધીનાં જંતુને ભૂલ્યે પણ ક્યારેય દુખવતા નથી. જગત બધું એ સંતનો ઉપહાસ કરે, પરંતુ તેઓ પોતાની ધર્મ ને ભક્તિ સંબંધી ક્રિયામાં ક્યારેય ઊણપ આવવા દેતા નથી.” આમ, શ્રીહરિએ એકાંતિક સંતના જેટલા ગુણો હતા તે યથાર્થપણે કહી દેખાડ્યા.","e":null,"s":["6/84/12-40"],"sv":["संत सरल जोई चित्त, तापर रुचि होवे सबे ।\n\n रुचि विन होय न प्रीत, कोटि करो उपाय कोउ ॥\n\n संत हे सबके मित्र, मित्र होई कर वचन वदत ।\n\n त्रिलोक करत पवित्र, गंगा ज्युं करत पवित्र जग ॥\n\n आप रहे पवित्र हि जेहा । ओरकुं करे पवित्र हि तेहा ॥\n\n आप में होवे गुन हि जेसा । ओर में सो देखहि तेसा ॥\n\n ओर के अवगुन हो अपारा । संतजन न देखत लगारा ॥\n\n अवगुन देखे असंत स्वभावा । ता पर कोई कुं न होवे भावा ॥\n\n खानपान हे विविध प्रकारा । ताकुं छोडि करे मल अहारा ॥\n\n कुकर शूकर गर्दभ माना । काक चारनि सम प्रमावा ॥\n\n हंस सम सो गुन न कहावे । बक सम तेहि संत दरसावे ॥\n\n वज्र सम वचन संत न उचारे । वचनवृष्टि करे अमृत धारे ॥\n\n वात सुनत तेहि गुन कर आवे । अगुन अनंत हि दूर बहावे ॥\n\n दोष होय जेहिकर नासा । हितकर एसे सिखवे अभ्यासा ॥\n\n ओरकुं करना सुख हि जोउ । एसे वचन वदत संत सोउ ॥\n\n कटुक वचन उचरे संत होई । ताकुं संत न जानत कोई ॥\n\n संत-असंत वचन कहि देवे । वचन कबु छपाई न रहेवे ॥\n\n संत भये संतगुन न आवे । वेर वेर जन कुं बात उपजावे ॥\n\n साधुता विन संत व कहावे । कोटि प्रकार हि बात बतावे ॥\n\n निष्कपट गुन देखे जामें । जग सब लोभात हे यामें ॥\n\n निष्काम निष्कपट हि, शांत शुन रहे धार ।\n\n छिद्र न प्रकाशे शत्रु को, सो संत जग-आधार ॥\n\n शुभ गुन हरिगुन कहत हे, प्रगटहि मोक्ष हित ।\n\n हरि को अक्षरधाम तेहि, संत एसे शोभित ॥\n\n शुभ गुन अक्षरधाम, श्रीहरि ताकुं न तजत कबु ।\n\n अगणित धरत हे नाम, अवतार सो अनंत लेई कर ॥\n\n जिहां जेसो काम, तिहां तेसो अवतार धरत ।\n\n अंतरजामी श्याम, करत चरित्र सो अनंतविध ॥\n\n प्रगट होई अदृश हि होना । सो सब चरित्र कर जोना ॥\n\n आवत जावत चरित्र हे ताके । चरित्र कले में न आवत वाके ॥\n\n आवन-जावन नहि हे तेहा । जेसे के तेसे सदा हे एहा ॥\n\n आत-जात देखावत जोउ । ताके एसे चरित्र हे सोउ ॥\n\n भक्त कुं चरित्र देखावन काजा । वेर वेर करत रहत महाराजा ॥\n\n अनादि जुग जन के अग्याना । चरित्र करि टालत भगवाना ॥\n\n अज्ञान टालने याकुं न वारा । एसो नहि हे याको धारा ॥\n\n संत के द्वारा करते तेऊ । अज्ञान टालने रखे हे एऊ ॥\n\n आप महिमा जथार्थ जेता । संत में जाने में आवे तेता ।\n\n हरि करे तामें भूल न कोई । एसे समझे एकांतिक सोई ॥\n\n जग के समज आवो न आवो । श्रीहरि कुं नहि माको दावो ॥\n\n समजे ताको होवे कल्याना । न समजे सो दुःख सहे नाना ॥\n\n पके हरिजन की यह रीति । हरि संत सम ओर में न प्रीति ॥\n\n हरि संत में करे विघ्न जेहि । शत्रु जानि करे दूर हि तेहि ॥\n\n चौद लोक को जो जो सुखा । सत्संग आगे लगे सब लूखा ॥\n\n एक को एक रंग रहे एसा । दिन दिन चढे खसे नहि लेशा ॥\n\n एसे संत-हरिजन को, हरि न करे कबु त्याग ।\n\n मोक्षभागि युं जानि के, संत में करे अनुराग ॥\n\n संत हरि के वचन हि, विधि निषेध हि जोउ ।\n\n सामान विशेष सहि, प्रगट हरि देखे सोउ ॥\n\n लिंख प्रजंत से जंत, अनंत कोटि ब्रह्मांड भर ।\n\n भूले नहि दुखवंत, मन वच कर्म संत कबु ॥\n\n संत के जितने गुन, वेद जथार्थ वात कर ॥\n\n क्रिया न करे नून, जग करे उपहास जिमि ॥"],"mt":false,"gl":null,"a":false},{"i":1123,"k":"para","g":"માવા ભક્તે મહારાજને પૂછ્યું, “દરેક સંતના ગુણ એક સરખા જણાતા નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1124,"k":"para","g":"ત્યારે શ્રીહરિ કહે, “જ્યાં સુધી સંત-અસંતને એક જાણે છે ત્યાં સુધી તેનામાં બુદ્ધિ નથી એમ જાણવું. અને એવા બુદ્ધિહીનનો મોક્ષ પણ થતો નથી, તેણે જાતે જ પોતાનું મોક્ષદ્વાર બંધ કરી દીધું! વ્યાવહારિક વાત પણ બુદ્ધિ વગર સિદ્ધ થતી નથી. બુદ્ધિ હોય તે જ સાર-અસાર ગ્રહણ કરી શકે છે; બીજી અનેક પ્રકારની બુદ્ધિ મનુષ્ય શીખે, પણ મોક્ષની બુદ્ધિ જ્યાં સુધી શીખે નહિ ત્યાં સુધી નકામું છે. સત્સંગ વિના મોક્ષની બુદ્ધિ આવતી નથી. બધાં શાસ્ત્રોમાં મોક્ષની વાત કરી છે, પણ મોક્ષનો ખપ ન જાગે ત્યાં સુધી તે વાત સમજાતી નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1125,"k":"para","g":"“સંસારનાં સુખ માટે લોકો જપ, તપ, તીર્થ, વ્રત કરે છે; દાન, પુણ્ય, યજ્ઞયાગ કરે છે; હઠયોગ સાધે છે, પણ તે સુખ મળીને ટળી જાય છે. ભગવાનના ધામનું સુખ ક્યારેય નાશ પામતું નથી, પરંતુ એ સુખને કોઈ ઇચ્છતું નથી, એટલે આખા જગતની એકમતિ થઈ ગઈ છે. ભગવાન કાં ભગવાનના સંત જ્યારે પ્રગટ થાય છે ત્યારે તેમના મુખે શાસ્ત્રની વાત શ્રવણ કરે ને ભગવાનના સુખનો નિશ્ચય કરે પછી તે ભવપાર થાય છે.”","e":null,"s":["6/85/1-13"],"sv":["श्रीहरि से भक्त तेहि, फेर पुछत कर जोर ।\n\n संतमात्र के गुन हि, देखात नहिं एक नोरा ॥\n\n तब श्रीहरि बोलत भये, सुनिये भक्त हि वात ।\n\n विन बुद्धि होय जांहि लग, तिहां लग एक देखात ॥\n\n जिहां लग एक देखाय, विन बुद्धि समजना तांहि लग ।\n\n मोक्ष न होवे ताय, मोक्षद्वार अटकाई दियेउ ॥\n\n व्यावहारिक जितनी वात, बुद्धि विन नहिं करत कोउ ।\n\n तब तेहि सुख पात, विन बुद्धि दुखि सो होत तेहि ॥\n\n सार-असार गुन हि जितना । बुद्धि में सहज रहे हे तितना ॥\n\n ओर बुद्धि जन सिखे अनेका । मोक्ष के काम न आवे सो एका ॥\n\n मोक्ष की बुद्धि जन सिखे जबऊ । सत्संग से सो आवत हे तबऊ ॥\n\n सत्संग विन मोक्षबुद्धि न आवे । मोक्षबुद्धि विन दुख न जावे ॥\n\n शास्त्र में मोक्ष कहत हे सबऊ । खप विन सुमझत न कबऊ ॥\n\n संसार में सुख लेवन हिता । कोउक दिन शास्त्र सुनिता ॥\n\n जप तप तीर्थ व्रत करे जेता । दान पुण्य यज्ञ करे केता ॥\n\n संसार सुख को करन भोगा । अभ्यास करत केते हठ जोगा ॥\n\n मरिके सुख हरिधाम हि केरा । कबु न नास होवे कोउ फेरा ॥\n\n एसो सुख न इच्छत कोऊ । एकमति सब जग की सोउ ॥\n\n हरि वा साचे संत हि, प्रगट होत जेहि वार ।\n\n तेहि मुख सुनत शास्त्र जब, तब जन होत भवपार ॥"],"mt":false,"gl":null,"a":false},{"i":1126,"k":"para","g":"ગાલોલમાં મહારાજે સંતોને વાત કરતાં કહ્યું, “સૂર્યને પ્રકાશતો જોઈ કોઈ દુર્જન તેના પ્રત્યે ધૂળ ઉછાળે તો સૂર્ય ટળી જતો નથી, પરંતુ દુર્જનની આંખોમાં જ તે ધૂળ પડે છે. પૂર્વે જે જે અવતાર થયા તેને પણ વિરોધ કરનાર અસુરો મળ્યા છે. તેમ સત્પુરુષ પ્રગટ થાય ત્યારે પણ દુર્જનની દુર્મતિ રહે જ છે. પૂંઠને સો વાર શુદ્ધ પાણીથી ધૂઓ તોપણ તે શુદ્ધ થઈ દીઠી?","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1127,"k":"para","g":"જેમ ગધેડો ભૂંકે કે કૂતરો ભસે તેના તરફ હાથી લક્ષ્ય આપતો નથી, તેમ સત્પુરુષ ક્યારેય દુર્જનના શબ્દોને ધ્યાનમાં લેતા નથી. દુર્જનને અંતર્દૃષ્ટિ થાય અને સત્પુરુષનો ગુણ અંતરમાં ધરે તો તત્કાલ શુદ્ધ થઈ જાય. મનુષ્ય જે પ્રકારનો ભાવ સત્પુરુષમાં દાખવે છે તેવું તેનું રૂપાંતર થાય છે. નારદ-સનકાદિકની વાર્તા પુરાણમાં પ્રસિદ્ધ છે. સત્પુરુષ અમે તેને કહીએ છીએ જે કુમાર્ગથી ડરીને સત્માર્ગે ચાલે છે, પ્રત્યક્ષ ભગવાનનું ભજન કરે છે, ભગવાન વિના જેને બીજું કોઈ વ્યસન નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1128,"k":"verse","g":"‘સત્મારગ ચલે જોઈ કે જોઈ, પ્રત્યક્ષ હરિ કું ભજે સોઈ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1129,"k":"verse","g":"હરિ વિન વ્યસન નહિં કેહા, સત્પુરુષ કહત હમ તેહા.’","e":null,"s":["6/89/14-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1130,"k":"para","g":"બાબરા ગામમાં મધ્યરાત્રિ સુધી શ્રીહરિએ કીર્તન ગવડાવ્યાં. સવારે ચાલવાની તૈયારી કરી, ત્યારે પુરજનોએ નિયમ ધાર્યા. તેમને શ્રીહરિએ વાત કરતાં કહ્યું, “હવે સંતોનો યોગ રાખજો. યોગ વિના સત્સંગ દૃઢ થતો નથી. જેમ શેરડી જતન વગર મળતી નથી ને વળી, જેમ વિદ્યા ભણ્યા પછી તેનો અભ્યાસ ન રાખે તો તે લુપ્ત થાય છે, તેમ સત્સંગનું નામ બ્રહ્મવિદ્યા છે. તે આદર વગર પ્રાપ્ત થતી નથી. જેમાં મોક્ષનો અંકુર પ્રગટે છે તેને બ્રહ્મવિદ્યા વરે છે. બ્રહ્મવિદ્યા જે પ્રાપ્ત કરે છે તેણે વિદ્યામાત્રને પ્રાપ્ત કરી લીધી. બ્રહ્મવિદ્યામાં અપાર તેજ છે. તેનાથી પાપમાત્ર દૂર ભાગે છે.”","e":null,"s":["6/91/8-10"],"sv":["जोग विना सत्संग न रहावे । जत्न विन ज्युं ईक्षु न पावे ॥\n\n विद्या पढे रखे न अभ्यासा । तर्त विद्या सो होवे नासा ॥\n\n ब्रह्मविद्या सत्संग को नामा । विन आदर न रहे तेहि ठामा ॥\n\n मोक्ष अंकुर देखे जा माहीं । ब्रह्मविद्या सो रहत ताहीं ॥\n\n ब्रह्मविद्या कुं पाये जन जेहि । विद्यामात्र हि पाये तेहि ॥\n\n ब्रह्मविद्या में तेज अपारा । पापमात्र होई जावे छारा ॥"],"mt":false,"gl":null,"a":false},{"i":1131,"k":"para","g":"શ્રીહરિ કુંડમાં નહાઈને બહાર આવીને બોલ્યા, “જીવમાત્ર સમજણ વિના લખચોરાશીનાં દુઃખ ભોગવે છે. તેને સંત મળે છે ત્યારે દુઃખના સમુદ્રમાંથી તેને ઉગારે છે. કોઈ અનંત કળાઓ દેખાડે કે આખી ભૂમિ પર રાજ કરે, પણ તેને બુદ્ધિ કહેવાય નહિ. જીવનો ઉદ્ધાર કરે તે જ ખરી બુદ્ધિ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1132,"k":"para","g":"“પૃથ્વીનું રાજ કરે તે બુદ્ધિશાળી નહિ પણ આત્મઘાતી છે. સ્વર્ગ ને પાતાળનું રાજ કરે ને દેવતાના નિયંતા બને તોપણ તેની બુદ્ધિ માયિક છે. ભગવાન ભજવાની બુદ્ધિ જ્યાં સુધી આવતી નથી, ત્યાં સુધી બધી બુદ્ધિ માયિક છે. એ સંતને અસંત કહે છે ને અસંતને સંત ઠરાવે છે. સંત પાતાળથી પ્રકૃતિપુરુષ સુધીના ભોગમાત્રને ઝેર સમાન જાણે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1133,"k":"para","g":"“પરમાર્થને માટે કેટલાક લોકો કૂવા, કુંડ, વાવ, વૃક્ષ, નદી-તળાવના ઘાટ, અન્નક્ષેત્ર, ધર્મશાળાઓ વગેરે બંધાવે છે. તે ક્યારેક સત્પુરુષના કામમાં આવી જાય છે ત્યારે તે કૃતાર્થ થઈ જાય છે. અને તે પુણ્યે કરીને ઉત્તમ મનુષ્યતન પામી પ્રભુનો ભક્ત બને છે. અને અંતે સંસાર તરીને ભગવાનના ધામને પામે છે.”","e":null,"s":["6/92/29-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1134,"k":"para","g":"કરિયાણામાં રંગોત્સવ પછી શ્રીહરિ કહે, “ભગવાન અને સંત બે નિર્બન્ધ છે, બાકી સર્વે બંધનમાં છે, નિર્બન્ધનો વિશ્વાસ કરે તો નિર્બન્ધ થવાય. માયા કરતાં જીવ સમર્થ છે, પણ જ્ઞાનનાં નેત્ર નથી, તેથી સર્વત્ર અંધારું છે. સત્પુરુષ તેને જ્ઞાનરૂપી નેત્ર આપે છે ને અજ્ઞાન અંધકાર દૂર કરે છે. જ્ઞાનનેત્ર મળવાથી તે નિર્બંધ થઈ જાય છે. નિર્બંધ પુરુષ મળ્યા વિના કોટિ ઉપાયે પણ મોક્ષ થતો નથી. વળી, નિર્બંધ પુરુષ મળે પણ તેના વચનમાં જો વિશ્વાસ ન આવે, ને વચન મનાય નહિ તોપણ મોક્ષ થાય નહિ.”","e":null,"s":["6/96/33-36"],"sv":["निर्बन्ध को जो करे बिसवासा । बन्धन मात्र सो करे खुलासा ॥\n\n माया से समर्थ जीव अपारा । ज्ञाननेत्र बिन भयो अंधकारा ॥\n\n ज्ञाननेत्र माया किये नासा । माया को एक रहे अभ्यासा ॥\n\n ज्ञाननेत्र हि पावे जबहि । निरबंध होई जावे तब हि ॥\n\n निर्बन्ध मिले बिन मोक्ष न होई । कोटि उपाय करे ओर कोई ॥\n\n निर्बन्ध को विश्वास न होई । ताके वचन न ले मानि सोई ॥"],"mt":false,"gl":null,"a":false},{"i":1135,"k":"para","g":"ગઢપુરમાં જીવા ખાચરના દરબારમાં શ્રીહરિએ સંતોને પીરસ્યું, પછી વાત કરતાં કહ્યું, “અક્ષરધામની સુખ-સંપત્તિ બધી એક એક સંતમાં રહી છે. તે સંપત્તિ એક સંત બીજા સંતમાં જોઈ શકતા નથી તેને ઈશ્વર ઇચ્છા જાણવી. જે સંત ઈશ્વરની પેઠે વર્તે છે, તે તેને જાણે છે. બધા જો ઈશ્વર પેઠે વર્તવા લાગે, તો બ્રહ્માંડની સ્થિતિ એક સરખી ન રહે, કારણ કે પ્રભુતા જીરવવી કઠણ છે. એમ જાણી અમે સૌનું સામર્થ્ય ઢાંકી રાખ્યું છે. વચનમાં વર્તવું તે મોટી પ્રભુતા છે. જેના હૃદયમાં ભગવાનની ઉપાસના દૃઢપણે હોય તે સેવક થઈને વર્તે. ભગવાનના જે દાસ તેનો પણ દાસ થઈને વર્તે. ભગવાન સિવાય તેને બીજી કોઈ આશા જ ન હોય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1136,"k":"para","g":"“ભગવાન પણ આવા ઉપાસકને દુર્લભ માને છે અને તેનાથી પળમાત્ર દૂર રહેતા નથી. એવી ઉપાસનાવાળાની સમજણ ઊંચી હોય છે. તેને આ જગતના લોકો માને કે ન માને પણ પોતે સૌ સાથે સામે ચાલીને નેહ બાંધે છે. જગતના બધા જીવોનો ઉદ્ધાર કરવા તેણે ધાર્યું છે અને એટલે જ કોઈ અપમાન કરે તેનાથી હારતા નથી. પાછો પગ ભરતા નથી. જેમ મેઘ વર્ષા કરે છે, તે સારી કે નરસી ભૂમિ, પાપી કે પુણ્યશાળી જન સામે જોતો નથી ને સમયે સમયે વર્ષા કર્યા કરે છે તેમ આવા એકાંતિક સાધુ પણ પાપી જનના દોષો સામે લેશ પણ જોતા નથી. જીવ જન્મોજન્મ પાપ કરતો રહે, પણ કોઈક દિવસ તેને ભગવાનના ઉપાસક આવા સાચા સંત મળી જાય છે, ત્યારે તેણે નિત્ય બ્રહ્માંડ ભરાય તેટલાં પાપ કર્યાં હોય તોપણ તે પલકારામાં નાશ પામે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1137,"k":"para","g":"“સાચા સંત જીવને મળે છે ત્યારે અધિકારી પ્રમાણે તેના સ્વરૂપનું જ્ઞાન આપે છે. આ સંત શ્રીહરિનાં વચનના દ્વાર પર ઊભા છે, કોઈ અલૌકિક આનંદ અંતરમાં ભરીને શ્રીહરિના હૃદયમાં વસી ગયા છે - આમ, મહિમા સમજી સંતમાં જોડાય તેનાં અનંત પાપ પળમાં નાશ પામી જાય છે ને તરત જ સત્સંગ થઈ જાય છે. જ્યાં સાચો સત્સંગ છે ત્યાં મોક્ષનો માર્ગ પાકોજ આ વાત બને છે. સાચા સત્સંગ વિના કોટિ વ્રત-તપ કરો, પણ મોક્ષ થતો નથી. વેદ પુરાણ ને મોટા સંતો પણ આ વાત કરી ગયા છે, તે સિદ્ધાંત વાત છે.”","e":null,"s":["6/99/9-22"],"sv":["हरि की रखे उपासना जेहा । सेवक होई के वतें तेहा ॥\n\n हरि के दास ताके रहे दासा । हरि बिन और नहीं जेहि आसा ॥\n\n हरि मानत अति दुर्लभ ताको । पल एक दूर रहत न वाको ॥\n\n जन मानो न मानो केहा । तजत न तोहु जनसें नेहा ॥\n\n उद्धार करन सब जगको धारे । अपमान करे तिनसे न हारे ॥\n\n मेघ वर्षात करत हे जबऊ । ठोर-कुठोर न गिनत हे तबऊ ॥\n\n पापी के दोष गिनत न लेशा । समय पर वर्षत रहत हमेशा ॥\n\n पापी धर्मी दोई कुं, मेघ विन नहिं सहाय ।\n\n समर्थ सो जानत वात सब, बडी हे समझन ताय ॥\n\n पाप करत करत हि, कोइक दिन हि ताहि ।\n\n साचे संत मिले आई कर, पाप पल में छुट जाहि ॥\n\n एक ब्रह्मांड भराय, इतनो करत नित पाप जिय ।\n\n हरि से विमुख रहे जाय, ताकी कहे बात सो यह ॥\n\n साचे मिलत जब संत, जिय कुं करत हे बात तब ।\n\n ज्ञान देत बलवंत, जेसो जन अधिकारी जोई ॥\n\n संत वचन के द्वार करि के । हरिउर बसे कोउ मुद भरिके ॥\n\n तब तेहि तर्त होवे सत्संगा । पाप अनंत पल में होय भंगा ॥\n\n मोक्ष को माराग अभंग रहावे । जिहां सत्संग सत्य रहावे ॥\n\n सत्य सत्संग विन मोक्ष न होवे । कोटिक तन व्रत तप करि खोवे ॥\n\n वेदपुराण को सिद्धांत हे एहा । संतजन हि कहत सब तेहा ॥"],"mt":false,"gl":null,"a":false},{"i":1138,"k":"para","g":"ગઢપુરમાં શ્રીહરિ જીવેન્દ્ર ભૂપને કહેવા લાગ્યા, “અજ્ઞાનીના વચનને એક સત્પુરુષ જ સહન કરે છે, ને એટલે જ તે સર્વથી શ્રેષ્ઠ છે. સંત બાવના ચંદનથી પણ અધિકપણે શીતળ અને અત્યંત શાંત હોય છે. સંત નિષ્કલંક હોવાથી તેનાં દર્શનથી લોકો શુદ્ધ થાય છે. વસ્ત્ર સૂઝે તેટલું ગંદું-મેલું હોય પણ શુદ્ધ નીર તેની સઘળી મલિનતા ધોઈ શુદ્ધ કરે છે. સત્પુરુષના યોગે પણ જીવની મલિન વાસના ટળે છે ને તે જન્મમરણના દુઃખથી છૂટે છે. બુદ્ધિશાળી જન આ વાત જાણે છે.”","e":null,"s":["7/59/27-28"],"sv":["संत हे शांत अत्यंत, बावने चंदन से अधिक ।\n\n निष्कलंक हि रहत, सो देखि जन शुद्ध होत तेहि ॥\n\n केसो है बसन मलिन, शुद्ध नीर सो शुद्ध करत ।\n\n जानत जन प्रवीन, जन्ममरन दुःख छुटत तेहि ॥"],"mt":false,"gl":null,"a":false},{"i":1139,"k":"para","g":"શ્રીહરિએ શ્રીનગરમાં હરિજનો પ્રત્યે વાત કરતાં કહ્યું, “સંસાર છોડી ભગવાન ભજવા વનમાં જાય, પણ જો ત્યાં કોઈ ટોકનાર ન મળે તો મન બદલાઈ જાય. શૃંગી, ચ્યવન, અને સૌભરિ ઋષિ મહા સમર્થ હતા ને એકાકી વનમાં બેઠા હતા, પરંતુ વિષયનો જોગ થતાં મનમાં રોગ પેઠો ને તપથી પડ્યા અને સંસારમાં પ્રીતિ કરી. તપમાં જેટલો ભાવ હતો તેથી અધિક સંસારમાં ચોંટ્યા. એટલે સત્સંગ જેવું કોઈ વન નથી, એમ રામાનંદ સ્વામી કહેતા. સત્સંગમાં સમજણ છે તેવી ચૌદ લોકના બ્રહ્માંડમાં નથી.”","e":null,"s":["8/4/4-8"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1140,"k":"para","g":"જેતલપુરના મહોલમાં સંતની પંક્તિ થઈ. શ્રીહરિ પીરસવા પધાર્યા ત્યારે વાત કરતાં કહ્યું, “જ્યાં સત્સંગ નથી ત્યાં ધર્મનું પાલન કથનમાત્ર છે. ઉપરથી ધર્મ રહ્યા છે, ઉપરથી ધર્મ પાળે છે તે પણ સારા છે. કારણ, તેમનો વહેવાર ભ્રષ્ટ થાય નહિ. ઉપરથી નિયમ રાખશે તો અંતરમાં પણ આવશે. જનોનું અંતર તો ધોળા કપડા જેવું છે, જેવો પાસ લાગે તેવું થઈ જાય, પણ સુવર્ણ જેવા જીવ છે તેનો તો ફાવે તેવી પરિસ્થિતિમાં પણ વર્ણ ફરે નહિ. ઘાટ બદલાય પણ જાત એકની એક રહે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1141,"k":"para","g":"“સાચા સાધુ પારસમણિ અને મલિયાગર (ચંદન) જેવા છે. પારસના સંબંધથી લોખંડનું સોનું થાય, પણ કાટ ન ચઢ્યો હોય તો થાય, પરંતુ ચિંતામણિનો સંગ થાય ત્યારે તેવો નિયમ ન રહે, પણ તે ચિંતામણિય ચિંતવન કર્યા વિના સોનું ન કરે. ભગવાન ચિંતામણિ તુલ્ય છે. તેની પાસે પ્રાર્થના કરવી પડે.”","e":null,"s":["8/10/20-30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1142,"k":"para","g":"જેતલપુરના મહોલમાં શ્રીહરિએ પૂજા કરી રહેલા સંતોને કહ્યું, “હવે અમારે તમને પૂજવા છે. સંતને પૂજે નહિ તેને ઈશ્વર કોઈ કહે નહિ. સંતને પૂજે તે જ સાચા ઈશ્વર છે. ઈશ્વરના ગુણો આવવાનું દ્વાર અમે સંતને માનીએ છીએ. સંતને પૂજવામાં જ અમે મોટપ માની છે. સંતને અમે પ્રાણથી પણ વિશેષ પ્યારા માનીએ છીએ.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1143,"k":"verse","g":"‘સંત કું પૂજે સો ઈશ્વર સાચે, પૂજે નહિ સો કહાવે કાચે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1144,"k":"verse","g":"સંત હમ માનત પ્રાન પ્યારા, ઈશ્વર ગુણ આવન કે દ્વારા.’","e":null,"s":["8/17/8-11"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1145,"k":"para","g":"જેતલપુરના મહોલમાં શ્રીહરિએ સંતને ઓળખી સત્સંગ કરવાની રીત હરિજનોને કહેતાં કહ્યું, “જેની ક્રિયા દેખીને સત્સંગીને પ્રેમ થાય એવા સંતને મોટા જાણવા. તે કુસંગીને સત્સંગમાં વાળીને સમાસ કરે એવા હોય અને તેને ભગવાન વશ વર્તતા હોય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1146,"k":"para","g":"“સંત-હરિજનોને ભગવાનમાં પ્રીતિ રાખવાની કળા શીખવી. તુચ્છ પદાર્થ અને સ્વભાવને લીધે પ્રીતિ તૂટે છે, તે ન તૂટે તે માટે સંતનો સમાગમ રાખવો. કામ, ક્રોધ, લોભ, રસાસ્વાદ અને માન એ મુક્તમાં પ્રવેશ કરે તોપણ સુધ ભુલાવે છે, તો પ્રાકૃતમતિની સુધ ભુલાવે તેમાં શું કહેવું? માટે પ્રથમથી નિયમ ઉલ્લંઘન ન થાય તેવો અભ્યાસ રાખવો. શુક-સનકાદિકની પેઠે બ્રહ્મસ્થિતિ પામેલા હોય તે પણ પ્રાકૃત દેહનો સંબંધ હોય ત્યાં સુધી ઉન્મત્ત થઈને ફરે નહિ, પણ ત્યાગીના નિયમમાં જ વર્તે અને બ્રહ્મચર્ય જ રાખે.”","e":null,"s":["8/20(19)/27-34"],"sv":["सत्संग में करे समास, कुसंग में करे समास तेहि ।\n\n संत के रहि सो पास, रीत सो सीखना तेउ ॥\n\n जाकि क्रिया देख, सत्संगी कुं प्रीति होय ।\n\n जानना मुनि अलेख, भगवान वश वर्तत तेहि ॥\n\n मुक्त सिद्ध होय ब्रह्म समाना । शुक सनकादिक जेसे रहाना ॥\n\n प्राकृत देह में विचरे जहाँ लगहि । उन्मत्त होई न फिरे त्यां लगहि ॥\n\n प्राकृत देह सिद्ध पाये जितना । नियम विन भ्रष्ट हो गये तितना ॥\n\n नियम होय तोउ त्यागी जेता । ब्रह्मचर्य में वर्ते दृढ तेता ॥"],"mt":false,"gl":null,"a":false},{"i":1147,"k":"para","g":"કણભામાં ઝવેરીદાસના ભવનમાં શ્રીહરિએ સત્પુરુષની વાત કરતાં કહ્યું, “સત્ મારગ મેં ચલત જેહુ સત્પુરુષ સો કહાવત તેહુ. સત્યને માર્ગે ચાલે તેને સત્પુરુષ કહેવાય. સત્પુરુષમાં ધર્મ, ભક્તિ, જ્ઞાન, વૈરાગ્ય એ ચારે પરિપૂર્ણ હોય. આમાંથી બહાર સત્પુરુષ કદાપિ ન વર્તે. વળી, માંસ-મદિરા, કેફ, વ્યસન કે ફેલ ક્યારેય ન કરે. દેહભાવ તજીને વર્તે. પાતાળથી પ્રકૃતિપુરુષના લોક સુધીના વિષયમાત્રને તે કાકવિષ્ટા તુલ્ય જાણે. ક્યારેય ચોરી-અવેરી ન કરે. ભગવાન સિવાય બધું કાળનું ભક્ષ સમજે. ભગવાન સિવાયના ભોગમાત્રને વિષથી પણ અધિક જાણીને ત્યાગે. સત્પુરુષ પોતે પ્રથમ સત્યમાર્ગે ચાલે ને પછી શિષ્યને ચલાવે.”","e":null,"s":["8/27(26)/20-26"],"sv":["धर्म भक्ति ज्ञान वैराग्य चारि । तिनमें पूर्ण हि वरते बारि ॥\n\n केफ, व्यसन, फेल करे न केहु । देह को भाव तजे हें एहु ॥\n\n विषयमात्र कहावत जेता । पाताल खे प्रकृति लग तेता ॥\n\n काक विष्टा सम जाने ताकुं । जन तब सत्य माने मत वाकुं ॥\n\n सत मारग में चलत जेहु । सत्पुरुष सो कहावत तेहु ॥\n\n चोरी अवेरी न करे कबहु । सत्पुरुष सो कहे जन सबहु ॥\n\n मांस मदिरा को करे जे त्यागा । हरि बिन रखे न कोई में रागा ॥\n\n हरि बिन जावे काल चविना । सत्पुरुष जानना प्रविना ॥\n\n पाताल से प्रकृति प्रजंता । बडे बडे भोग जो रहंता ॥\n\n बडे भोग बडे रोग हि जाने । सत्पुरुष सो जन तेहि माने ॥\n\n हरि विन भोग जो जितने, विष से अधिक हि जेहु ।\n\n सत्य हि समझे तेहि विध, सत्पुरुष सत्य एहु ॥\n\n सत्पुरुष सत् मग प्रथम, चले आप हि जोउ ।\n\n पिछे चलाबे शिष्य कुं, सत्पुरुष सत् सोउ ॥"],"mt":false,"gl":null,"a":false},{"i":1148,"k":"para","g":"શ્રીહરિએ વડતાલમાં રામનવમીનો ઉત્સવ કરવા માટે દેશોદેશના હરિભક્તોને નિમંત્રણ પત્ર લખ્યો અને લખ્યું કે: “જીવનું હિત સત્પુરુષ વિના કોઈ કરી શકે તેમ નથી. સાંસારિક સંબંધીઓ છે તે ભગવાનના ભક્ત ન હોય તો સંસારને જ હિતકારી માને અને મોક્ષના માર્ગમાં સમજે નહિ. માત-તાત, બંધુ અને નારી પણ મિથ્યા સ્નેહને લીધે જીવને મોક્ષને માર્ગે ચાલવા દેતાં નથી. મોક્ષના માર્ગમાં ચાલવામાં અસુરો વિઘ્ન કરે છે. જેને સત્સંગનું બળ હોય તે અસુરને ગણતા નથી. સંસારનું જ્ઞાન કરનારા ગુરુથી અજ્ઞાન ટળે નહિ. જગતના સંત અને વિપ્ર વેદપુરાણ ભણ્યા હોય, પણ જગતમાં આસક્તિ હોવાથી શિષ્યોને પણ જગતમાં જોડે. તેનાથી જન્મમરણ છૂટે નહિ. સત્પુરુષના યોગ વિના જગતમાં કોઈને આ વાત સમજાય નહિ.”","e":null,"s":["8/48(47)/28-32"],"sv":["जिय को करना हित, सत्पुरुष विन करत नहि ।\n\n संत हें परम हि मित, खचित कर समझना तेहि ॥\n\n जग के संत अरु विप्र हि जेते । जग कुं प्रिय बतावत तेते ॥\n\n वेदपुराण सो पढे कहा होई । जाकुं जग आसक्ति जोई ॥\n\n तिन सें जन्म मरन न छुटाई । मरि के जमपुरी में सो जाई ॥\n\n सो नहि जानत जग सब कोई । सत्पुरुष मिले विन सोई ॥"],"mt":false,"gl":null,"a":false},{"i":1149,"k":"para","g":"વડતાલમાં શ્રીહરિ કહે, “જેવો યુગ તેવો ધર્મ રહે. જે વખતે પૃથ્વી પર સમર્થ સત્પુરુષ પ્રગટ થાય છે ત્યારે પ્રજામાં તપ અને ધર્મ પ્રગટ કરે છે. ભૂપ અને ગુરુઓ જેટલા નીતિમાં દૃઢ રહે તેટલા જ તે વૃદ્ધિ પામે નહિ તો સ્થાનભ્રષ્ટ થઈ જાય.”","e":null,"s":["8/62/1-6"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1150,"k":"para","g":"વડતાલમાં શ્રીહરિ ભક્તોને કહે, “તમારાં ભાગ્ય અપાર છે. ફળની ઇચ્છાથી કરોડો રૂપિયા વારંવાર ખર્ચે તોપણ માયિક ફળમાં આશારૂપી મગરથી પકડાયેલા તે જનને અમાયિક સંત મળે નહીં. માયિક સત્સંગ તો ઘરોઘર જનો કરે છે પણ એથી કુસંગ મટતો નથી. માયિક સુખમાં જ્યાં સુધી રાગ છે ત્યાં સુધી અમાયિક સુખ ન જ મળે. જે પળ ગઈ તે ફરી આવતી નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1151,"k":"para","g":"“સત્પુરુષની જેટલી સેવા બની આવે તેટલું જ ધનનું ફળ છે, બીજું તો મળરૂપ છે. અતિ પુણ્યનું ધન જેને મળે તેનું ધન સત્પુરુષને મુખે જાય.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1152,"k":"verse","g":"‘અતિ પુણ્ય કો ધન મિલે જેહા, સત્પુરુષ મુખ જાવે તેહા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1153,"k":"verse","g":"પાપ કો ધન હિ કોટિ ભંડારા, સંત કે મુખ ભાવે ન લગારા.’","e":null,"s":["9/3/13-18, 29"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1154,"k":"para","g":"વડતાલમાં હરિભક્તોને આનંદ પમાડી શ્રીહરિએ સત્સંગની રીત દેખાડી, પછી શીખ આપી કે, “સંતના વર્તનની, ધર્મ-નિયમની વાતો કહેવી અને સાંભળવી જેથી મનનાં પાપ બળી જાય. હરિજનના નિયમો નિત્ય કહેતા રહેવા પણ છુપાવવા નહિ.”","e":null,"s":["9/4/16-18"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1155,"k":"para","g":"ઝીંઝરમાં શ્રીહરિએ વાત કરતાં કહ્યું, “જેનું મોટું ભાગ્ય હોય તે જ સંતને પોતાનું મન અર્પણ કરી શકે છે. એવા સંત ભગવાનમાં રાગ કરાવે છે, પણ પોતામાં ક્યારેય જોડતા નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1156,"k":"verse","g":"‘જાકો બડો બડ઼ભાગ, સંતકું દેખત મન જેહિ,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1157,"k":"verse","g":"હરિ મેં કરાવત રાગ, આપમેં ન બંધાવત કબુ.’","e":null,"s":["9/27/40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1158,"k":"para","g":"શ્રીહરિએ જેતપુરમાં મૂળુવાળાને વાત કરતાં કહ્યું, “જ્યાં ધર્મ, જ્ઞાન, ભક્તિ અને વૈરાગ્ય તેનું વાણી અને વર્તનમાં પ્રતિપાદન હોય, ભગવાનને પ્રત્યક્ષ માની તેનું ભજન થતું હોય, હરિને પોતાની પાસે સમજીને યોગ્ય ક્રિયા કરે પણ લોકોને દેખાડવા કરે નહીં, અને પોતાના મોક્ષ માટે જ ધર્મનું આચરણ કરતા હોય, તથા સન્માર્ગને અનુસારે યોગ્ય વાત કરતા હોય, એવા જનોનો સંગ તે સત્સંગ કહેવાય. ગમે તેટલો ધર્મ પાળે પણ જો લોકને દેખાડવા માટે હોય તો અંતે તે વિમુખની ગતિને પામે છે. ભગવાન તેને સહાય કરે નહીં. પણ નિર્દંભપણે વાત કરે તથા ભગવાનનાં વચન નિર્દંભ થઈને પાળે તેનું નામ સત્સંગ છે. સત્પુરુષ વિના સત્સંગ ઓળખાય નહીં.”","e":null,"s":["10/15/20-27"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1159,"k":"para","g":"જેતપુરમાં શ્રીહરિ કહે, “જ્ઞાનીજન ક્યારેય અજ્ઞાનીના નોરમાં ચાલે નહિ. આ લોકના અનિત્ય ભોગમાં બંધાય નહિ તથા પંચવિષયને નીરસ માને છે. એક ભગવાનમાં જ યથાર્થ રસ માને છે. મોટા જ્ઞાની કહેવાય છે તે તો ભગવાનના સંબંધ વિનાના સુખમાત્રને ઘોર જમપુરીનાં દુઃખ માને છે. ભગવાનની મૂર્તિમાં રસ લાગે છે ત્યારે તેને ખાવું-પીવું પણ ગમતું નથી. અણુના કોટિ કટકા કરો તોપણ અણુથી આકાશ જુદો પડતો નથી. તેમ આવા જ્ઞાની છે તેને ભગવાનની મૂર્તિ એક પળ પણ જુદી થતી નથી.”","e":null,"s":["10/17/13-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1160,"k":"para","g":"શ્રીહરિએ મોડા ગામના પુરજનોનો ભાવ જોઈને વાત કરી કે, “જીવના મોક્ષની વાત એવી છે કે તે અભ્યાસ વિના સ્રવી જાય છે, હાથ આવતી નથી. જેને મોક્ષનો જેટલો ખપ હોય તે તેટલો અભ્યાસ રાખે છે. ખપ જાગે તો સંતની વાત સમજ્યામાં આવે. કેટલાંક બીજ એવાં હોય છે કે તેનો અંકુર ફૂટતાં લાંબો સમય લાગે, પરંતુ સંતની વાતરૂપી બીજ એવું છે કે તે કાને પડે કે તરત અંકુરિત થઈ ઊઠે છે. સંતનાં દર્શન જાણે-અજાણે પણ કોઈ કરે તો નેત્ર દ્વારા તેનું દર્શનરૂપી બીજ અંકુરિત થઈ મોક્ષ પ્રાપ્ત કરાવે છે. આમ, સંતનું દર્શન અને કથાશ્રવણ એ બે પ્રકારનાં બીજમાં મોક્ષનો અંકુર સમાયેલો છે. એ અંકુરનો નાશ કાળરૂપી પક્ષી પણ કરી શકતો નથી.”","e":null,"s":["11/12/32-36"],"sv":["मोक्ष की वात कहावत जेती । अभ्यास करे विन रहे न तेती ॥\n\n खप हि जितना जाकुं रहावे । तितनो अभ्यास सो तेहि करावे ॥\n\n खप के अंकुर उदय होय जैसे । संत कुं वात सो आवत तैसे ॥\n\n केतेक बीज के अंकुर जोउ । बहुत काल उदय होवे सोउ ॥\n\n संत की वात रूप बीज जेहु । जाके श्रवन पे परत हि तेहु ॥\n\n संत के दरस कहत जन जेता । जान अजान करिके तेता ॥\n\n दरश रूप बीज हि जाकु । नेत्र के द्वार जेहि परत हि ताकुं ॥\n\n दरश श्रवन बीज दोउ प्रकारा । मोक्ष अंकुर हें करन वारा ॥\n\n कालरूप जो पक्षी ताको । नास कबु न कर सके वाको ॥"],"mt":false,"gl":null,"a":false},{"i":1161,"k":"para","g":"ધોરાજીમાં નિત્યવિધિથી પરવારી શ્રીહરિ સભામાં આવીને બેઠા, પછી વાત કરતાં કહ્યું, “સાધુમાં સાત્ત્વિક ગુણ અખંડ રહેલો છે. તેથી કરવા યોગ્ય અને ન કરવા યોગ્ય વાતનું જ્ઞાન તેમને હોય છે. તેઓ મનુષ્યમાત્રને પોતાના મિત્ર સમજે છે. ભગવાનના સુખે કરીને જ તે સુખિયા હોય છે. તેમને પદાર્થને માટે કદી ક્ષોભ થતો નથી, અને ભગવાન વિના બધું દુઃખરૂપ સમજે છે. સહેજે પદાર્થ મળે તેને ધર્મ અનુસારે ભોગવે. કારણ, ધર્મ વિનાનાં સાધન ફળીભૂત થાય નહિ.”","e":null,"s":["11/33/27-32"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1162,"k":"para","g":"ઝીંઝરમાં શ્રીહરિ હરિજનોને કહે, “ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિયુક્ત સંતની સેવા કરે તો તે અમારી સેવા કર્યા બરાબર છે. આ અમે તમને હિત લાવીને વાત કરી છે. તે કોઈ દિવસ ભૂલવી નહીં.”","e":null,"s":["11/59-b/13-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1163,"k":"para","g":"જૂનાગઢમાં શ્રીહરિએ વર્ણીને વાત કરતાં કહ્યું, “જ્યારે અધર્મનું બળ વધે છે ત્યારે શ્રીહરિ અક્ષરધામથી સાચા સંત (અક્ષરબ્રહ્મ) સહિત પધારે છે ને (એકાંતિક) ધર્મનું સ્થાપન કરે છે. શ્રીહરિ અને તેમના સાચા સંત (અક્ષરબ્રહ્મ) છે તે જ ભક્તિ સહિત ધર્મનું સ્થાપન કરે છે. બીજા કોઈથી એ એકાંતિક ધર્મનું સ્થાપન થઈ શકતું નથી, આ સત્ય વાત છે.”","e":null,"s":["11/61(51-b)/12-13"],"sv":["बहोत अधर्म होत जेहि वारा । श्रीहरि जन के करन उधारा ॥\n\n साचे संत सहित सो आई । धर्मस्थापन करत हें ताई ॥\n\n साचे श्रीहरि-संत बिन, भक्ति जुत धर्म जोउ ।\n\n स्थापन होत न ओर से, सत्य वात हे सोउ ॥"],"mt":false,"gl":null,"a":false},{"i":1164,"k":"para","g":"માંગરોળમાં શ્રીહરિએ અરુણોદય થતાં વાત કરતાં કહ્યું, “ભાગવત ધર્મનિષ્ઠ (એકાંતિક) ત્યાગી-ગૃહી સૌ કોઈ શ્રીહરિને પ્રસન્ન કરવા જે કંઈ સાધન કરે છે તે અન્ય સર્વે સાધન પાસે લવ સમાન તુચ્છ છે. અપાર સાધન પણ એકાંતિક ધર્મની તુલનામાં ક્યારેય આવતાં નથી. જેને શુદ્ધ વિચાર પ્રાપ્ત થયો છે, તેને આ વાતની ગમ પડે છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1165,"k":"verse","g":"‘ભાગવત ધર્મનિષ્ઠ હિ, ત્યાગીગૃહી જેતે,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1166,"k":"verse","g":"શ્રીહરિ પ્રસન્ન કરન હિત, સાધન કરત હેં તેતે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1167,"k":"verse","g":"તેહિ સાધન કી લવ સમ ઓર સાધન અપાર,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1168,"k":"verse","g":"સમતા લહે નહિ કબહુ, જાનત શુદ્ધ વિચાર.’","e":null,"s":["12/15/37/38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1169,"k":"para","g":"શ્રીહરિએ ભુજમાં વિપ્રોની સભામાં વાત કરતાં કહ્યું, “સત્પુરુષની વાત સર્વ જીવનું હિત કરે છે, કારણ કે સત્પુરુષ રાગ-દ્વેષથી પર ને મેઘ સમાન પરોપકારી હોય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1170,"k":"para","g":"“સ્વાતિ નક્ષત્રમાં વર્ષાનું બુંદ છીપમાં પડે તો મોતી પાકે અને સર્પના મુખમાં પડે તો ઝેર બને છે. તેમ સત્પુરુષની વાત પણ દૈવી જીવને અમૃત સમાન થાય છે ને આસુરી જનને વિષ સમાન લાગે છે. જવાસાના જેવા સ્વભાવના જીવ હોય તે મેઘને દેખીને સુકાવા લાગે છે, અન્ય વનસ્પતિ પોષણ પામીને ફળે છે.”","e":null,"s":["12/31/29-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1171,"k":"para","g":"કચ્છ-ભૂજમાં હીરજીભાઈને શ્રીહરિ કહે, “તમારે જગતનો જેટલો અભાવ છે એટલું અમારે તમારી સાથે હેત રહે છે. ભક્ત હોય પણ તેની જગતમાં આસક્તિ જોઈને તેનાથી અમે દૂર રહીએ છીએ. ભગવાનમાં પ્રીતિ અને ધર્મના પાલન વગર મોક્ષ થતો નથી. જેમ ભૂમિ અને નીરના સંયોગ વગર બીજ અંકુરિત થતું નથી તેમ પ્રગટ ભગવાન અને સંત વિના ભગવાનનો નિશ્ચય થતો નથી અને ધર્મમાં પણ રહેવાતું નથી.”","e":null,"s":["12/37/6-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1172,"k":"para","g":"શ્રીહરિએ અલર્ક રાજાને વાત કરતાં કહ્યું, “ભગવાન અને સાચા સંત જે રીતે પ્રસન્ન થાય તે રીતે પોતાના શરીરને વરતાવવું. જે શુભમતિ પુરુષ આ પ્રમાણે વર્તે છે તેનો સત્સંગ દૃઢ રહે છે.”","e":null,"s":["12/49/39-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1173,"k":"para","g":"શ્રીહરિએ મુક્તમુનિને જે વાત કરેલી તે તેમણે ઉત્તમ નૃપને કહી, “સાચા સંત સરળ હોય છે. અંદર અને બહાર એક સરખું વર્તે છે. પ્રત્યેક પ્રાણી પર પ્રેમ રાખે છે. પોતાનાથી બીજા સંતને અધિક ગુણવાન દેખે છે અને પોતાનામાં રહેલા ગુણોમાં દોષ દેખે છે. અને બીજાના ગુણ થોડા હોય તેને અધિક કહે છે. સાધુના ગુણ જે સાધુ હોય તે જ અધિકપણે કહી શકે છે. સંતના દ્રોહી હોય તે સંતના અધિક ગુણને તુચ્છ કરી દેખાડે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1174,"k":"para","g":"“દંભી, કપટી, ઈર્ષ્યાવાળા તો સંતપણા પાસે મળરૂપ છે. તે સાચા સંતનું અપમાન કરવા બધાં વચનામૃત કંઠે કરે, શ્વાસોચ્છ્‌વાસે હરિનામ રટે, ધ્યાનમાં અખંડ રહે, વાતમાં પંચવિષયની ઊલટી કરાવી દે, રાત-દિવસ કથાવાર્તા સૌથી અધિક કરે, ફાટ્યાં તૂટ્યાં વસ્ત્ર પહેરે, લોટ પીને રહે, એકાંતરે ઉપવાસ કરે, તેમાં એકવાર જળ પીએ તો ઉપવાસનો ભંગ થાય - એમ વાત કરે. છતાંય મળરૂપ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1175,"k":"para","g":"“કોઈ અપમાન કરે તોપણ વિચલિત થાય નહિ એવા સત્પુરુષની ઓળખાણ જે સંત-ભક્તને થાય છે પછી તેના ગુણ ગાવા લાગે છે.”","e":null,"s":["12/81/5-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1176,"k":"para","g":"શ્રીહરિએ માનકુવાથી પત્ર લખાવ્યો. એમાં લખ્યું કે: “સંત- હરિજનને જે પડે છે તે કળિયુગના અસુર કહેવાય છે. સંતની સેવા કરવા માટે તો અમે ઘર છોડ્યું છે. જેણે સંતની સેવા નથી કરી, અને અપરાધ કરે છે તે ઘોર-નર્કમાં પડે છે. જેનાં તન, ધન સંતને અર્થે કામ નથી આવતાં તેનો જન્મ અમે નિષ્ફળ જાણીએ છીએ, ને તે જન્મોજન્મ દુખિયો રહે છે. એ ફરીવાર મનુષ્યનું તન પામતો નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1177,"k":"para","g":"“ભગવાનના અક્ષરધામ તુલ્ય કોઈ શ્રેષ્ઠ ધામ નથી, તે ધામને યજ્ઞ-યાગથી પમાતું નથી. જપ, તપ, તીર્થ, વ્રત, ચાહે તેટલાં કરો તોપણ તે ધામ મળતું નથી. તે સંતસેવાથી પ્રાપ્ત થાય છે. બીજાં સાધન કરે તો દેવલોક પામે, કાં તો ધનાઢ્ય થાય, કાં તો પવિત્ર બ્રાહ્મણ થાય, પરંતુ સંતની સેવાથી ભગવાનનું ધામ મળે છે. સંત સિવાય હરિધામને પામવા કોઈ દ્વાર નથી. એવું શાસ્ત્રો વારંવાર કહે છે.”","e":null,"s":["13/1/32-39"],"sv":["संत हरिजन कुं पीडत जेते । असुर कलि के कहावत तेते ॥\n\n संत की सेव करत हि काजा । छोड दीन्हे हम घर-समाजा ॥\n\n संत की सेव करत न जेहु । घोर नर्क में परत हि तेहु ॥\n\n तन धन संत अर्थ न आया । निष्फल हम जानत रहाया ॥\n\n अपराध करत संत को कोई । जन्म जन्म तेहि दुःखी होई ॥\n\n फेर नहि मनुष्य तन पावे । द्विपि व्याघ्र के तन धरावे ॥\n\n हरिधाम सम श्रेष्ठ न कोउ । जज्ञ जाग्य सें न पावत सोउ ॥\n\n जप तप से न मिलत सो, तीर्थ व्रत न मिलात ।\n\n देवलोक पावत तेहि, कहां भूप हो जात ॥\n\n कहां होत धनाढ्य महा, कहां द्विज ही होई ।\n\n संत से मिले सत्संग हि, हरिधाम मिले सोय ॥\n\n हरिधाम के द्वार, संत विन न अवर कोउ ।\n\n वेद पुरान अढार, कहत हैं वेर वेर तेहि ॥"],"mt":false,"gl":null,"a":false},{"i":1178,"k":"para","g":"કચ્છ દેશમાં માનકુવાથી શ્રીહરિએ પત્ર લખ્યો તેમાં સંતમહિમા વર્ણવતાં લખ્યું કે: “જગતમાં મહાનથી મહાન સંત છે. પૂજ્યોમાં પૂજ્ય સંત છે. સંત એ ભગવાનની ઉપાસના-ભક્તિ છે, ને સૌ જનનાં પાપ હરે છે. ભગવાન પણ સંતને પૂજે છે ને સંતની રક્ષા માટે જ વારંવાર પૃથ્વી પર અવતરે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1179,"k":"para","g":"“આ લોકમાં કોઈ દેવ, ભૂપ કે મનુષ્યોને માન ઘટે છે તેના કરતાં વિશેષ માન-સન્માન સંતને આપવું જોઈએ, તેને પૂજવા જોઈએ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1180,"k":"para","g":"“અનંતકોટિ બ્રહ્માંડોમાં દેવ, દૈત્ય, મનુષ્ય સર્વે ધન અને સ્ત્રીમાં સુખ માને છે ને તેમાં રચ્યાપચ્યા રહે છે. સ્ત્રી-ધનથી અધિક કોઈને દેખતા નથી ને તેને અર્થે દેશવિદેશ ફરીને કોટિ સાધન ને ઉદ્યમ કરે છે કે જાણે ધન, સ્ત્રી ક્યારેય મળ્યાં ન હોય! જ્યાં સુધી તેમાં બંધાયા છે, ત્યાં સુધી તેને સંત ન કહેવાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1181,"k":"para","g":"“સાચા સંત તો ધન રાખે-રખાવે નહિ. ધનને તો તે જગતનો મળ કહે છે. ધન કાજે સંત બને તે સ્ત્રી-ધનના ત્યાગી સાચા સંતને દેખીને બળી મરે છે. સાચા સંત ધન અને સ્ત્રીમાં પ્રીતિ કરતા નથી. ધન-સ્ત્રીને નકારાં જાણી તેનો ત્યાગ કર્યો છે. આવા સંત છે તે જગતના ઉદ્ધારનું નાવ છે. દેવ-મનુષ્યથી તે અધિક છે. કેફ, વ્યસન કે ફેલ તો તેણે દૂરથી જ ત્યાગ્યાં છે. આમ, સાચા સંતનાં લક્ષણ તપાસીને જુએ તો તે ઓળખ્યામાં આવે છે. સોનાની કસોટી અગ્નિમાં થાય છે, તેમ સાચા સંત વર્તનથી ઓળખાય છે. ઉપરથી સંત હોય ને ભીતર અસંત હોય તેનું વર્તન છૂપું રહેતું નથી. સંત અવગુણ તજી ગુણ ગ્રહણ કરે છે અને અસંત અવગુણ ગ્રહણ કરે છે. સંતનું મુખ્ય લક્ષણ અપમાન સહન કરવું એ છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1182,"k":"verse","g":"‘અપમાન સહન કરના જોઉ, સંત કો મુખ્ય લછન હેં સોઉ.’","e":null,"s":["13/2/1-18"],"sv":["बडेसे बडे संत हें, पूज्य में पूज्य हें संत ।\n\n हरिकुं सेवत संतहि, पाप जनके हरंत ॥\n\n हरि पूज हें संतकुं, संत हित वारमवार ।\n\n अवतार धरत हें भोमि पर, संतकि करत रखवार ॥\n\n संतको करत अपमान, जीसविध यह लोक महिं ।\n\n तेसे घटत तेहि मान, देव भूप, मनुष्य लग ॥\n\n संतकु पूजत जेह, ताकुं पूजत देव सब ।\n\n भूप हि पूजत तेह, मनुष्य पूजत रहत तेहि ॥\n\n धन त्रियमें ब्रह्मांड जेता । देव मनुष्य देत हि तेता ॥\n\n रचि पचि अति रहे हें यामें । सुख सबहि जो माने तामें ॥\n\n अधिक तिनसें न देखत कोई । तेहि हित उद्यम करत हें सोई ॥\n\n देश प्रदेश सेवत तेहि हिता । तिन हित साधन कोटि करिता ॥\n\n धन त्रिय जनु मिले नहि कबहु । तेहि उदय में लगे जन सबहु ॥\n\n धन में बंधाये जहां लग जेहु । संत न कहावत तिहां लग तेहु ॥\n\n संत होई धन रखे रखावे । सो सब जगके मल कहावे ॥\n\n धन हित संत होत हें जेते । साचे संत देखि जरत तेते ॥\n\n साचे संतकि ऐसि हें रीता । धन त्रियेमें करत न प्रीता ॥\n\n धन त्रिय देखत नर्क के द्वारा । त्याग करत तेहि जानि नकारा ॥\n\n ऐसे संत हें जगके नावा । देव मनुष्य सें अधिक रहावा ॥\n\n केफ व्यसन जे ते कहावे । जगमें जे ते फेल रहावे ॥\n\n दूरसें त्याग करत हें ताके । साचे संत भये सो पाके ॥\n\n संतके लछन करिके जोउ । संत पेचाने आवत सोउ ॥\n\n हुतासन कसोटि जेहा । जेसो सोवर्ण कहत हें तेहा ॥\n\n उपर संत भितर असंता । वर्तन नहि छपत रहंता ॥\n\n धोरि जे ते मुलके, धर सो देखाई देत ।\n\n वर्तन में जेति संतता, वर्तन परख हि लेत ॥\n\n गुन गुन संत ग्रहत हें, अवगुन देवत त्याग ।\n\n गुन त्यागि अवगुन लहत, असत तेहि निरभाग ॥\n\n शस्त्र रखत हें जेते, धन नारि रखत जो ।\n\n जगा बंधत तेते, ठाकर के हि ओड जेहि ॥\n\n नारद शुकमुनि जेह, सनकादिक संत जोउ ।\n\n दत्तात्रय मुनि तेह, जगे न बांधे निज हित ॥\n\n लठियां हथियार रखे न तेहा । त्रिये धन में करे न नेहा ॥\n\n व्यसन केफ फेल किये त्यागा । श्रीहरि पद में करे अनुरागा ।\n\n मुखसें गारि न उचरे कबहु । जगको अपमान सहे सबहु ॥\n\n अपमान सहन करना जोउ । संतको मुखय लछन हें सोउ ॥"],"mt":false,"gl":null,"a":false},{"i":1183,"k":"para","g":"જાલમસિંહ પ્રત્યે શ્રીજીમહારાજે કહ્યું કે, “તીર્થમાત્રના સેવનનું ફળ કે સર્વે મૂર્તિઓનાં દર્શન-પૂજનનું ફળ ધર્મનું પાલન કરે તો મળે છે. ધર્મ મૂકી તીર્થ કરે તો દુર્ગતિ થાય છે. તીર્થમાં કરેલું પાપ વજ્રલેપ થાય છે. તીર્થો ને મૂર્તિઓ સત્પુરુષ વિના ફળતાં નથી, સત્પુરુષ તીર્થમાત્રનું ફળ આપે છે.”","e":null,"s":["13/13/4-7"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1184,"k":"para","g":"શ્રીજીમહારાજ જૂનાગઢમાં દાદાભાઈના દીવાનખાનામાં સંઘ સહિત ઊતર્યા. સામે ગિરનાર પર્વતની શોભા જોઈ અપાર પ્રસન્ન થયા ને કહ્યું, “અમે મોટાં મોટાં શહેર જોઈને મનમાં અતિ ઉદાસ થઈએ છીએ. પરંતુ વન-પર્વત દેખીને અંતરમાં આનંદ થાય છે. પંચવિષયનું સુખ ભગવાનના ધામના સુખ પાસે અધિક માને તેને વિમુખ જાણવો. સાચા સંતની લેશ પણ સેવા કરે તેને મહાસુખ મળે છે. જો અધિક સેવા કરે તો તેનાથી પણ વિશેષ ઘણું સુખ પ્રાપ્ત થાય છે. જેમ સેવા અધિક તેમ લાભ પણ અધિક મળે છે. સાચા સંતની સેવાથી ક્યારેય ખોટ જતી નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1185,"k":"para","g":"“સાચા કેવી રીતે ઓળખવા! તો પ્રથમ ખોટા ઓળખવા પડે. જે માયામાં અંધધંધ રહેતા હોય, વારંવાર માયા(જગત પદાર્થ, સમૃદ્ધિ, ધન, સુવર્ણ, સ્ત્રી આદિ)નાં વખાણ કરે. ને તેને જે મળે તે શિષ્યને પણ અપાર માયા મળે એવું ઇચ્છે. જેની પાસે ભગવાન સંબંધી કે ભગવાનના ધામના સુખ સંબંધી કોઈ વાત ન હોય તેને અસંત જાણવા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1186,"k":"para","g":"“સાચા સંતની સમજણ કેવી હોય? તો એવા સંત ભગવાનના ધામને માયાથી પર સમજે છે. ધામના નિવાસી મુક્તોને દિવ્ય જાણે છે. ધામના સુખ આગળ અવાંતર લોકનાં સુખ કે અનંતકોટિ બ્રહ્માંડનાં સુખને તુચ્છ ગણે છે. ધામ(અક્ષરબ્રહ્મ)ના એક રોમના સુખ આગળ એ સમગ્ર સુખ ભેળું કરીને મૂકીએ તોપણ તેની તુલનામાં આવતું નથી, અક્ષરધામનું સુખ ક્યારેય કોઈ પ્રમાણિત કરી શકતું નથી. સાચા સંત-હરિજનની આવી સમજણ હોય છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1187,"k":"verse","g":"‘ધામ કે સુખ કે આગે સુખ ઓરા, અનંત બ્રહ્માંડ કે કરે એક ઠોરા,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1188,"k":"verse","g":"ધામ કે એક હિ રોમ સમાના, નાહીં હોવત કબુ પ્રમાના.’","e":null,"s":["13/39/5-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1189,"k":"para","g":"શ્રીહરિએ ગઢપુરમાં મુક્તમુનિને વાત કહેતાં કહ્યું, “ઉદ્ધવ મતને આશરેલા સંત-હરિજન હોય તેને દિન દિન પ્રત્યે પરસ્પર અધિક અધિક ભાવ વધતો રહે. ગૃહસ્થ હોવા છતાં સંતથી અધિક ધર્મ, જ્ઞાન, વૈરાગ્ય, ભક્તિ ને ત્યાગ તે રાખતો હોય, કથાવાર્તા ને ધ્યાન અધિક કરતો હોય, પણ સંતનો ભાર ન હોય, હરિજન-હરિજન વચ્ચે ક્લેશ કરાવતો હોય, કુસંગીની જેવું સત્સંગનું ઘસાતું બોલતો હોય તો તેના બધા ગુણો ગજસ્નાનની જેમ દોષ બની જાય છે. સંત સાથે પ્રીતિ તોડવે એ તો હડકાયા શ્વાન જેવો જાણવો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1190,"k":"para","g":"“જે હરિભક્ત શુક્લ પક્ષના ચંદ્રમાની પેઠે દિન દિન પ્રત્યે સંત-ભક્તોમાં પ્રીતિ વધારતો રહે, ગુણનું ગાન કરે, મહિમા કહે, એવા હરિભક્તનાં ધર્મ, જ્ઞાન, વૈરાગ્ય, ભક્તિ, કથાવાર્તા, ધ્યાન, કીર્તન થોડાં હોય તોપણ બધાને સુખદાયક થાય છે; એવા આકાશ પેઠે નિર્લેપ રહેનાર સંત-હરિજનને એકાંતિક જાણવા.” આ પ્રકારે શ્રીહરિએ બહુ વાતો કરી. તેને સાંભળીને મોટા રાજાઓએ કુમતિનો ત્યાગ કર્યો.","e":null,"s":["13/50/29-36"],"sv":["उद्धव को मत इमि दिन दिन हि अधिक अधिक ।\n\n भाव बढे ज्युं तिमि, संत-हरिजन करे जो तेहि ॥\n\n धर्म भक्ति अरु ज्ञान वैरागा । संत से अधिक हि रखे त्यागा ॥\n\n कथावार्ता अधिक ध्याना । दिनरात रखे ता पर ताना ॥\n\n संत को भार रखे न लेशा । हरिजन हरिजन करे क्लेशा ॥\n\n एक एक को च्हाय तिमि । बोले घसातो कुसंगी तिमि ॥\n\n गज गंगा जिमि न्हावत जाई । तन पर रज सो डारत आई ॥\n\n हडकाये श्वान जानना ताई । संत सुं प्रीत जो देत तोडाई ॥\n\n दिन दिन प्रीत अधिक बढ़ावे । शुक्ल दिन के जिमि चंद रहावे ॥\n\n ऐसे के कथावार्ता जेते । ध्यान कीर्तन भक्ति तेते ॥\n\n धर्म ज्ञान वैराग्य हि जेतो । सबकु हे सुखदायक तेतो ॥\n\n एसे संत हरिजन जितना । आकाश सम एकांतिक तितना ॥"],"mt":false,"gl":null,"a":false},{"i":1191,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ કહેલી વાત મુક્તમુનિએ કરતાં કહ્યું, “ધર્મવંશનો પરિવાર જેટલો કહેવાય છે તે (ધર્મ, જ્ઞાન, વૈરાગ્ય ભક્તિ સહ એકાંતિક ધર્મ) મોક્ષનું દ્વાર છે અને સત્સંગ ત્યાં જ વધતો રહે છે. જેમાં ભક્તિ, ધર્મ, જ્ઞાન અને વૈરાગ્ય જેટલાં ન્યૂન રહે તેટલા તેને ન્યૂન જાણવા. દારૂ, માંસ, કેફી દ્રવ્યનું સેવન, વ્યભિચાર, અભક્ષ્યનું ભક્ષણ વગેરે અધર્મવંશ કહેવાય છે. અધર્મવંશ પરિવાર એ જમપુરીનું દ્વાર છે ને ચોરાશીની ભટકણ છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1192,"k":"verse","g":"‘ધર્મવંશ પરિવાર, જિતનો જો કહાત તેહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1193,"k":"verse","g":"મોક્ષ કે હેં સો દ્વાર, સત્સંગ તિહાં રહત હૈ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1194,"k":"verse","g":"અધર્મવંશ પરિવારહિ જેતા, જમપુરિ કે દ્વાર રહે તેતા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1195,"k":"verse","g":"જન્મ-મરણ કે દ્વાર હૈ તેહા, ચોરાશિ ભમત હેં એહા.’","e":null,"s":["14/24/12, 16-17"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1196,"k":"para","g":"બુધેજ ગામમાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “જે સંતનું વર્તન અંદર-બહાર એક સરખું હોય અને સરળપણે વર્તે તેને અમૃત સમાન જાણવા. એવી સરળ પ્રકૃતિવાળા સંતને કોઈ પર ક્યારેય ખેદ, ઘૃણા થતાં નથી. વાત કરે તેમાં પણ ખેદનો ભાવ લાવે નહિ. હૃદય ઉત્સાહથી ભર્યું ભર્યું રહે. બધા સંતોના ગુણ વારંવાર કહેતા હોય. અવગુણનો ક્યારેય ઉચ્ચાર ન કરે એ સાચા સંત જાણવા. એવા સંત ક્યાંય છુપા રહેતા નથી. સાચા સંત-હરિજનના નિયમ ધર્મ નિત્ય કહેવા.”","e":null,"s":["14/42/37-40"],"sv":["संत सरल जो जितने, अंतर बाहिर जेह ।\n\n वरतत हें एक रीत हि, अमृत सम हें तेह ॥\n\n सरल संत जे ताहि कुं, कोउ जन पर नहि खेद ।\n\n बात करत न खेद रख, उर में रहत उमेद ॥\n\n संत के गुन अपार, वार वार कहे मुखकर ।\n\n अवगुन न करत उच्चार, साचे संत न छिप रहत ॥\n\n नियम धर्म हि जेते, साचे संत हरिजन के ।\n\n नित हि कहना तेते, श्रीहरि करे बात यह ॥"],"mt":false,"gl":null,"a":false},{"i":1197,"k":"para","g":"જ્યારે જ્યારે સંતોનાં મંડળ ભેગાં મળતા ત્યારે શ્રીહરિ તેમને સાથે રાખી પોતાના હૃદયની એક વાત ખાસ કરતા. વૌઠામાં શ્રીહરિ કહે, “પૂર્વે જે આચાર્ય થયા છે, તે બધાની રુચિ ભિન્ન ભિન્ન જણાય છે. તેમાં જેને ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ પર તાન હોય તે જ મોટા થયા છે ને તેની કીર્તિ વધી છે. વાટમાં દીવેલ ચઢે તેટલો પ્રકાશ થાય. દીવા કરતાં મશાલનો પ્રકાશ વધુ છે. વીજળીનું દૈવત તેથી વધુ છે તો વધુ પ્રકાશ જણાય છે. વડવાનળ તો સમુદ્રમાં જ રહે છે. તે પાણીમાં પણ પ્રજ્વલિત રહે છે. સિંધુનો પવન તેને ઠારી શકતો નથી. તેમ દીવા જેવા ભક્તો ઘરને અજવાળું આપે, પણ ફૂંક લાગે તો બુઝાઈ જાય, તેને થોડો કુસંગ થાય તોપણ સત્સંગ ટળી જાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1198,"k":"para","g":"“મોટા રાજા-મહારાજાનાં સન્માન મળે ત્યારે તેની સમજ-સ્થિતિ ફરી જાય, એવા સંતો મશાલ જેવા છે. તે મેઘના વાયુથી બુઝાઈ જાય. મોટા સાધુ સંતદાસ, રામદાસ કે મુક્તાનંદ સ્વામી જેવા હોય તે વીજળી તુલ્ય છે. વીજળી મેઘમાં રહેવા છતાં બુઝાતી નથી, તે રાજાના સન્માનથી લેવાતા નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1199,"k":"para","g":"“ભગવાન, ભગવાનના ધારક સંત ને ભગવાનના અવતાર એ વડવાનળ જેવા છે. જે ચારે અગ્નિમાં શ્રેષ્ઠ અગ્નિ કહેવાય છે. વડવાનળ જેવા હોય તે દેવના પણ દેવ છે. તે ક્યારેય માયાના બંધનમાં આવતા નથી, અન્ય સર્વે તેની પાસે રંક તુલ્ય જણાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1200,"k":"para","g":"“અનંત બ્રહ્માંડના દેવો બ્રહ્માદિક સર્વે રંક જેવા છે. સર્વોપરી શ્રીહરિ મનુષ્ય તન ધારે, વર્ણીનો વેશ લે પણ સામર્થિ ઢાંકીને વર્તે છે. પોતાની ઇચ્છાથી ગમે તે યોનિમાં પ્રગટ થાય, પણ અન્ય સર્વે તેમની આગળ રાંક જેવા ભાસે છે. અણુ જેવા તનમાં આવે તો પણ બ્રહ્માદિક દેવો તેના આગળ રંક છે. જે કોઈને મળ્યા નથી તે તમને મળ્યા છે.” એમ શ્રીહરિએ સર્વે હરિજનને કહ્યું. ને વળી કહ્યું કે, “હવે તો પોતાનું મન ડગાવે તોપણ સત્સંગ છોડવો નહિ. કારણ, અંત સમે એ હરિજનને દર્શન દઈ અમે તેડી જઈએ છીએ.”","e":null,"s":["14/50/15-36"],"sv":["करत हें एसी बात, संत हि भेगे होत जब ।\n\n हरि जब भेगे रहात, तब हरि एक बात करत ॥\n\n हरि की बात हि एसी, जो आचार्य जैसे भयेउ ।\n\n बात करत सो तेसी, रुचि में फरक देखाई देत ॥\n\n जेसी रेचि ताके जेसे धामा । बात में देखात घनश्यामा ॥\n\n धर्म, भक्ति, वैराग्य रु ज्ञाना । तामें जाकुं जेसो ताना ॥\n\n तेसे बडे भये जो तेहा । तेसी कीर्ति बढे ताकी तेहा ॥\n\n बत्ती जैसे दिवेल रहाये । दीपक प्रकाश तेसे कराये ॥\n\n मशाल में जेतो प्रकाशा । तम को तेतो करत हि नाशा ॥\n\n बिजली में दैवत रहे जैसा । प्रकाश सो देखावत तेसा ॥\n\n वडवानल कहावत जेहुं । सिंधु में सो रहत हें तेहु ॥\n\n तामें दैवत रहेउ एसो । सिंधु पवन से बुझात न तेसो ॥\n\n हरि कहत हरिजन हि जेता । दीपक सम कहत हैं तेता ॥\n\n भुवन में सो करत उजियारा । फूंक लगे बूझ जावे सारा ॥\n\n थोर कुसंग के जोग ताई । सत्संग ताके मिट जावे भाई ॥\n\n संत रहे मशाल समाना । मेघ से कबु न रहे ठिकाना ॥\n\n बडे भूप आवट करे जबहु । समझ ताकी फरि जावे तबहु ॥\n\n संतदास, रामदासजी जोउ । मुक्तानंद मुनि जैसे सोउ ॥\n\n संत रहे सो विज हि जैसे । विजरी मेघ से बुझात न तेसे ॥\n\n भगवान संत ताहि के, अवतार जो रहाय ।\n\n वडवानल से अधिक हें, देव के देव कहाय ॥\n\n अनंत ब्रह्मांड के देवा । रंक रहे ब्रह्मा जैसे तेवा\n\n मनुष्य देह में आवत तोउ । वर्णि के वेश लेवत जोउ ॥\n\n सर्वोपरि महिमा रहे तोई । साम्रथि तेति रखत हें गोई ॥\n\n हरिजन कुं हरि एसे कहेऊ । तुमकुं मिले हे वस्तु जेउ ॥\n\n कोईकु न मिले अब लगहु । सत्संग कुं रहेना वलगहु ॥\n\n अपनो मन डगावे तोउ । सत्संग न छोडना कोउ ॥\n\n अंत समे हरिजन कुं तेकुं । दर्शन देवत हरि तेतेकुं ॥"],"mt":false,"gl":null,"a":false},{"i":1201,"k":"para","g":"મોટેરા ગામમાં શ્રીહરિ કહે, “જન્મમરણ, જમપુરી, લખચોરાશી જેવા અસાધ્ય રોગ એક સત્પુરુષ સિવાય કોઈ મિટાવી શકતું નથી. સત્પુરુષ મળે ને ઓળખાય છે ત્યારે મોક્ષનો માર્ગ યથાર્થ દેખાય છે ને મનાય છે. પૂર્વના સુકૃત વિના સત્પુરુષ મળતા નથી ને મળે તો તેમાં જીવ ચોંટતો નથી. સત્પુરુષ તો ચમકનો પહાડ છે. લોહ જેવા કેટલાય જીવો તેમની સમીપ આવતાં ખેંચાઈ જાય છે. તેમનાં અમૃત સમાં વચનો સાંભળી જીવ જડી દે છે. પછી તેમને કોઈ વાતે છોડતા નથી. કારણશરીર નાશ થાય તો જ સત્પુરુષ વળગે છે. જે નિદ્રા, આળસ, પ્રમાદ (દેહભાવ) તજીને સત્સંગ કરે, ભગવાનના વચન મુજબ જીવે ને વચનને ધારે વિચારે તો તેનું કારણદેહ ટળે છે.”","e":null,"s":["14/64/21-27"],"sv":["जन्म मरण जमपुरि जोउ । चोराशि जो कहावत सोउ ॥\n\n जथार्थ मोक्ष के मारग जेउ । देखत मानेमें न आवत तेउ ॥\n\n तेहि सम रोग असाध्य न केउ । सत्पुरुष मिटावत एउ ॥\n\n सुकत विन सत्पुरुष तामें । जीय नहि चोंटत हें यामें ॥\n\n सत्पुरुष रहे चमक समानां । केते जीय लोह सम रहानां ॥\n\n सत्पुरुष समीप आत जबहि । अमृत सम वचन सुने तबहि ॥\n\n सत्पुरुष में चोंटि हि जाते । छोरत नहि तेहि केहि वाते ॥\n\n कारन तन रहे जीयमें जेसे । सत्पुरुष में चोंटत तेंसे ॥\n\n सत्संग के जोग कर, कारन तन के नास ।\n\n हो जावत नहि संदेह हि, बोले युं अविनाश ॥\n\n कारन तनको नाश हि, जीतनो होवत जेह ।\n\n तितनो चोंटत हरि बातमें, प्रगट देखना तेह ॥\n\n निंद, आलस, प्रमाद, जीतनो होवत जेह ।\n\n तितनो चोंटत हरि बातमें, प्रगट देखना तेह ॥"],"mt":false,"gl":null,"a":false},{"i":1202,"k":"para","g":"શ્રીનગરમાં શ્રીહરિએ દીવાનને ઉદ્દેશીને કહ્યું, “સાચો સત્સંગનો સંગ મળે તો પામર પશુ જેવો જીવ દેવકોટિનો થઈ જાય છે વિષયમાત્ર છૂટી જાય છે ને મતિ ઉત્તમ થાય છે. વિષયમાં રાગ રહે ત્યાં સુધી ભગવાનમાં ચિત્ત ચોંટે નહિ. સાચા સંત કેવા હોય તો જેને ભગવાન સિવાય કોઈ વિષયમાં રાગ ન હોય, દ્રવ્ય અને સ્ત્રીનો ત્યાગ અષ્ટપ્રકાર પાળતા હોય, વ્યસનમાત્રથી દૂર રહેતા હોય. જે કોઈ જીવ પોતાની સમીપે આવે તેને ભગવાનમાં જોડતા હોય તેને સાચા સંત જાણવા. ભગવાન વિના બીજામાં જોડે તેને શિશ્નોદર પરાયણ જાણવા.”","e":null,"s":["14/69/30-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1203,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ વાત કરતાં કહ્યું, “જેનામાં જેટલું સામર્થ્ય હોય તેટલું દેખાઈ આવે છે. અંદર રહેલા ગુણ છૂપા રહેતા નથી, સોનામહોર અને રૂપિયાની કિંમત તેના પારખુને હોય છે. હીરા-માણેકની સાચી કિંમત ઝવેરી કરી આપે છે. તેમ ભગવાન સૌમાં રહ્યા છે તે જેટલું દૈવત અધિક જણાવે તેમાં અધિકપણે રહ્યા છે એમ જાણવું. ભક્તોમાં, સંતોમાં ને બ્રહ્મનિષ્ઠ સદ્‌ગુરુમાં જે ભગવાનનો વાસ છે, તે તેમના દૈવતથી જાણ્યામાં આવે છે. એ ગુણ છિપ્યા છિપાતા નથી. સંત અને અસંત પણ તેમના વર્તનથી પરખાય છે. તેના વર્તન વિષે ગ્રંથોમાં ઠેર ઠેર લખ્યું છે. જેને મોક્ષનો ખપ હોય તેને મોક્ષદાતા સંત રુચે છે. વિષયીજનને વિષયી ગુરુ ગમે છે. દુષ્કાળ પડે છે, તે આવા મિથ્યા ગુરુનું ફળ છે.” એમ વાત કરતાં શ્રીહરિ ઝિંઝાવદર પધાર્યા.","e":null,"s":["15/12/29-37"],"sv":["जामें सामर्थ्य रहाये जेसा । गुन देखाई देवत तेसा ॥\n\n सौवर्न में दैवत हि जेसे । अनल सो कहि देवत तेसे ॥\n\n रुपिये की कीमत रहे जेसी । साचे पारख कहत हि तेसी ॥\n\n हीरा मोती की कीमत जाई । झवेरी जो कहि देवत ताई ॥\n\n हरिजन संत गुरु ताके । भगवान जो रहाये वाके ॥\n\n जेसो दैवत जामें रहाये । गुन ताके न रहत छिपाये ॥\n\n संत-असंत हि वरतन मांहि । तरत देखे में आवत ताहिं ॥\n\n मोक्ष को खप होय जाकुं । मोक्षरूप संत रुचत ताकुं ॥\n\n ब्रह्मांड में जन रहे जेते । विषय पर तान रहे सब तेते ॥\n\n तेसे जो गुरु मिले जाहि । तरत ताकुं मानत रहा हि ॥\n\n मिथ्या गुरु के फल यह । ऐसे परत जो काल ॥\n\n श्रीहरि वात करत ईमि । निज जन प्रति पाल ॥"],"mt":false,"gl":null,"a":false},{"i":1204,"k":"para","g":"વડતાલમાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “લોકને ઠગવા માટે ત્યાગ, ધ્યાન વગેરે કરે છે તે પોતે જ ઠગાય છે અને અંતે વિમુખ થાય છે. આ નક્કી વાત છે. સાચા સંત તો અંદર-બહાર સરખા જ હોય છે. એવા સંત ઉપર અમે દિન દિન પ્રસન્ન રહીએ છીએ, એવા નિષ્કપટ (નિર્દંભ) સંત, વર્ણી, પદાતીને અમારી સેવામાં સદાય રાખીએ છીએ.”","e":null,"s":["15/43/13-15"],"sv":["ठगावत हें ठग तेहि, ताकी गम नहि तेउ ।\n\n अंते विमुख होवत हि, निश्चे बात हें एउ ॥\n\n उपर तेंसे भीतर हि, साचे संत हें तेहु ।\n\n दिन दिन एसे संत पर, रिझत हम जो रहेउ ॥\n\n निष्कपट संत जेते । वर्णि पदाति जेते जोउ ।\n\n हमारी सेवा में तेते । निरंतर मानत हम हि यह ॥"],"mt":false,"gl":null,"a":false},{"i":1205,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સંતો-ભક્તોને ભાત-ભાતનાં ભોજન જમાડ્યા પછી વાત કરતાં કહ્યું, “અમે વિચાર કરીને જોયું કે અપાર તીર્થ કરે, વ્રત કરે, અપાર યોગ સાધે, યજ્ઞો કરે, અનંત જન્મ લગી દાન પુણ્ય કરે તોપણ જે પુણ્ય ન મળે તે ભગવાનના સંતને એકવાર ભાવથી જમાડે ને પૂજે તેમાં મળે છે. એવા સંતને તીર્થાદિકથી પણ અધિક અમે માન્યા છે.”","e":null,"s":["15/57/39-40"],"sv":["तीर्थ व्रत हि अपार, जोग जज्ञ अपार करे ।\n\n दान पुण्य नहि पार, करे अपार जन्म लगहि ॥\n\n हरि-संत एक वार, जेंवाये पूजे भाव कर ।\n\n कर देखे विचार, तीर्थादिक सें अधिक रहे ॥"],"mt":false,"gl":null,"a":false},{"i":1206,"k":"para","g":"શ્રીહરિએ સર્વે સંતોને પત્ર પાઠવ્યો. જેમાં સાચા સંતનાં લક્ષણ આ રીતે લખાવ્યાં: “સાચા સંતને બ્રહ્મવેત્તા કહેવાય છે. તે સત્ય વચન બોલે છે. દયા, દાન ને કોમળ અંતરવાળા હોય છે. હિંસા રહિત, કોઈની અવગણના કરે નહિ એવા, કૃપાળુ, દ્રોહ રહિત, સહિષ્ણુ, નિર્મળ મનવાળા, કામનાથી રહિત, ચતુર, પવિત્ર, અકિંચન, ભગવાનમાં પ્રીતિવાળા, જગતના નાશવંતપણાને જાણનારા, દેહની અયોગ્ય ચેષ્ટાથી રહિત, યુક્ત આહાર-વિહારવાળા, સ્થિર મનવાળા, ભગવાનના શરણાગત, સદા શુભ વિચાર કરવાવાળા, મુનિ, શુભ વર્તનમાં સાવધાન, ધીરજવાન, નિર્માની, માન આપનારા, રાગદ્વેષથી રહિત, દીનપણાથી રહિત, મૈત્રી ભાવવાળા, ગ્રંથના તત્ત્વને જાણનારા એવાં અનંત લક્ષણે યુક્ત સાચા સંત જાણવા.”","e":null,"s":["15/72/1-11"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1207,"k":"para","g":"શ્રીહરિએ પત્રમાં લખાવ્યું: “મારા સાધુની સેવા અપવિત્ર પાપીજને ક્યારેક થોડી કરી હશે તો તે પવિત્ર નિષ્પાપ થઈ જશે. અને જો તેનો દ્રોહ કો’ક દિન થઈ ગયો તો પવિત્ર જન પણ અપવિત્ર પાપી થઈ જશે.”","e":null,"s":["15/75/39-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1208,"k":"para","g":"પત્રમાં શ્રીહરિ કહે, “હરિવિમુખમાં કળિયુગ પ્રગટ દેખાઈ આવે છે. સંતના યોગ વિના ભાગ્યનો ઉદય થાય નહિ. જ્યારે સાચા સંત મળે છે, ત્યારે તેની કીર્તિ બધા લોકમાં છવાઈ જાય છે. એ સંતે નારી અને ધન મળની પેઠે ત્યાગ કર્યાં છે. ફેલ-વ્યસન કરતા નથી. કારણ કે સાચા સંત ભગવાન વિના બીજી વસ્તુમાં લોભાતા નથી. લોકોને દેખાડવા જે ત્યાગ રાખે છે, તે કપટયુક્ત સંત કહેવાય.”","e":null,"s":["15/78/2-11"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1209,"k":"para","g":"શ્રીહરિએ પત્ર લખાવ્યો: “સત્પુરુષનો જે સંગ કરે છે તેનામાં સત્પુરુષના ગુણ આવે છે. સત્શાસ્ત્રમાં રુચિ થાય છે. તીર્થ-વ્રતાદિકમાં શ્રદ્ધા ઉત્પન્ન થાય છે. અસત મતમાંથી વૃત્તિ ઊખડે છે. ભગવાનની સાકારપણે ઉપાસના થાય છે. ભગવાન સત્ય છે અને અધર્મ અસત્ય છે એ જીવમાં દેખાય છે. ભગવાનને અંતર્યામી સમજે છે. પ્રતિમામાં શ્રદ્ધા બેસે છે. એવા જનનો દેહ છૂટ્યે મોક્ષ થાય છે.”","e":null,"s":["15/80/31-37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1210,"k":"para","g":"શ્રીહરિએ સાંખ્યયોગી બાઈ-ભાઈને પત્રમાં જણાવ્યું: “જેને ધન-સ્ત્રીનો ત્યાગ છે, મોક્ષનો ખપ છે ને ભગવાનમાં દૃઢ અનુરાગ છે એવા સંતના યોગ વિના સુમતિ પુરુષ પણ કુમતિ થઈ જાય છે. ભરતજી તો ભગવાનના પુત્ર હતા ને પૃથ્વીની સંપત્તિ ત્યજી દીધેલી, પરંતુ સંતના યોગ વિના એમને વિઘ્ન થયું.”","e":null,"s":["15/91/54-55"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1211,"k":"para","g":"શ્રીહરિએ પત્ર લખાવ્યો: “અમારા ભક્તોએ એકાદશી આદિ વ્રતનું જાગરણ એક પહોર સુધી અવશ્ય કરવું. જગતનો ડર હોય તેણે ગુપ્ત જાગરણ કરવું. મનમાં ભજન કરવું. પરમહંસો અને સાંખ્યયોગી બાઈ-ભાઈઓએ ચાર પહોરનું જાગરણ અવશ્ય કરવું. જે આ વચન ન માને તેને દેહરૂપ જાણવો. એ બ્રહ્મરૂપ નથી. સત્સંગના જેટલા નિયમ-ધર્મ છે તેમાં તત્પર થઈને વર્તવું. વચનમાં નથી વર્તતો તેને નર્ક મળે છે. વ્યાસજીએ ભાગવતના ગદ્યમાં નર્ક ગણાવ્યાં છે તે અમે પત્રમાં લખ્યાં છે. નિયમમાં વર્તી જે હરિજન ભજન સ્મરણ કરે છે તેને અમે પ્રગટ દર્શન દઈએ છીએ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1212,"k":"para","g":"“વ્યાસજીએ વેદ-પુરાણ રચ્યાં, પણ જેને જેવી રુચિ તે મુજબ તેમાંથી ગ્રહણ કરે છે. જેનામાં ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ રહ્યાં હોય તે ચારેનું પ્રતિપાદન કરે. કોઈમાં જ્ઞાન અંશ વધુ હોય તો એકલા જ્ઞાનનું પ્રતિપાદન કરે. અમારા હૃદયમાં અક્ષરાતીત પુરુષોત્તમ ભગવાન પ્રગટ પ્રમાણ વિરાજે છે. એ મૂર્તિને નખશિખ દેખીએ છીએ ને અક્ષરધામને પણ ભેળું જ દેખીએ છીએ. અક્ષરધામ અને પુરુષોત્તમની મૂર્તિ એ જેટલાં બ્રહ્માંડ છે તેમાં એક એકમાં દેખાય છે. આ અતર્ક્ય વાત છે. જીવને એ તર્કમાં લાવવી તે અતર્ક્ય સ્થિતિ (બ્રાહ્મી સ્થિતિ) સિવાય બને નહિ. અમારી બધી જ વાત અતર્ક્ય છે. જેમાં વેદનું રહસ્ય સમાયેલું છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1213,"k":"para","g":"“અમે પરબ્રહ્મ પુરુષોત્તમ પરમાત્મા છીએ. બે રૂપે યોગકળાથી રહીએ છીએ. એક ધામમાં ને બીજે રૂપે અનંતકોટિ બ્રહ્માંડમાં પ્રકટ દેખાઈએ છીએ. જેવો અધિકારી તેવી વાત જીવમાં ઠરે. નાવ વિના સિંધુ પાર ન થાય, ને પાંખો વિના આકાશમાં ગતિ ન થાય, તેમ બ્રહ્મવિદ્યા પ્રાપ્ત કર્યા વિના અમારી આ યોગકળા જાણ્યામાં આવે નહિ. ચ્હાયે તેવો પંડિત હોય, પણ શાસ્ત્રમાં રહેલી આવી વાતને યોગકળા વિના જેવી છે તેવી જાણી શકતો નથી. બુદ્ધિમાં બેસે નહિ તેથી આસ્થા થતી નથી, ને શાસ્ત્રને ભણવા છતાં નાસ્તિક થઈ બ્રહ્મરાક્ષસ થાય છે ને મનુષ્યજન્મ હારે છે.”","e":null,"s":["15/98/1-27"],"sv":["श्रीहरि पुनि कहत भयेउ, हरिजन पर हित रहाय ।\n\n जाग्रन करनां अवश्य हि, एक पोर हरिजन ताय ॥\n\n जगको डर होय जीनकुं, गुप्त करनो जाग्रन ।\n\n कोउ जाने नहि तिसविध, मनमें करना भजन ॥\n\n परमहंस जे तेउ, सांख्यजोगि बाई भाई जोउ ।\n\n चार पोर के एउ, जाग्रन करनां अवश्य यह ॥\n\n बचन न मानहि जेहु, देहरूप देखना तेहि ।\n\n ब्रह्मरूप नहि एहु, जरूर पावहि नर्क जेहि ॥\n\n गद्य में नर्कके नाम कहेउ । पत्र में जोईके लिखे हम तेऊ ॥\n\n नियम धर्म सत्संग के जेता । तामें तत्पर वरतत तेता ॥\n\n वेद पुरान व्यास के जोई । जेसी जाकी रुचि रहे सोई ॥\n\n ज्ञान अंश जामें रहे जेसे । समग्र ताकि रहाये तेसे ॥\n\n धर्म भक्ति वैराग्य जो ग्याना । प्रतिपादन तिमि करत रहाना ॥\n\n ज्ञान अंश हमारे में जेसा । अक्षरातीत पुरुषोत्तम तेसा ॥\n\n हृदय हि प्रगट प्रमाना । प्रसन्न होई भये विराजमाना ॥\n\n पुरुषोत्तम की मूरति, नख शिख तन के मांहि ।\n\n देखात रहत हे अखंड हि, धाम देखात रहाहि ॥\n\n धाम-मूर्ति बिन जितनेउ, ब्रह्मांड जेते रहात ।\n\n पृथक् देखत हि तिनकुं, मूर्ति में कबु देखात ॥\n\n अतर्क्य बात रहाये केती । तर्क में लावना जीय कुं तेती ॥\n\n अतर्क्य स्थिति विन हुं पाये । अतर्क्य बात न आत देखाये ॥\n\n अतर्क्य हम कहत हें बाता । वेद ताके रहस्य रहाता ॥\n\n पुरुषोत्तम परब्रह्म जेहा । परब्रह्म जो कहावत तेहा ॥\n\n ताके दोउ स्वरूप कहाते । जोग कला रूप दोउ रहाते ॥\n\n जेसे अधिकारि जीय रहाये । तेसि रीत ताकुं देखन में आये ॥\n\n जेहि बात देखना होय जबहु । तिनकि दृष्टि करि देखना तबहु ॥\n\n अपार सिंधु रहाये ताकुं । उतरना होय जबहि वाकुं ॥\n\n नाव बिन ओर कोटि उपाया । उतरे नहि जावत रहाया ॥\n\n पांख विना आकाश तामें । गति कबहु न होवत यामें ॥\n\n मनुष्य पंखि अल्प कहावा । आकाश में ताकि गति रहावा ॥\n\n ब्रह्मविद्या कहावत जेती । जोगकला जुक्त रहे तेती ॥\n\n जोग कला जाने बिन जोउ । चाय तेसे पंडित रहे तोउ ॥\n\n शास्त्र में बात रहाये जेसी । माप करे में न आवत तेसी ।\n\n पिछे शास्त्र तिनकुं यह, पढि के नास्तिक होत ।\n\n आस्ता रहत न कोउकी, मनुष्य तन कुं खोत ॥\n\n नास्तिक पंडित जितने, पढिकर होवत जेह ।\n\n ब्रह्मराक्षस हि होत तेहि, सत्संग हि नहि तेह ॥"],"mt":false,"gl":null,"a":false},{"i":1214,"k":"para","g":"ધરમપુર-વાંસદાના રાજાને શ્રીહરિ કહે, “આવા સંતને એકવાર પગે લાગે છે તેમનો ઉદ્ધાર થઈ જાય છે. એમાં સંશય નહિ. સંતની પૂજા સેવા કરે કે જમાડે, સંભારે તેનાં પાપ નાશ પામે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1215,"k":"para","g":"સંતનો પ્રતાપ અનલથી પણ અધિક છે. જેનાં ભાગ્ય ઉદય થાય તેને સંત મળે છે. તેમનો અભાવ લેનારા ફરી મનુષ્ય જન્મ પામતા નથી. અર્થાત્ ભૂત-પ્રેતાદિ યોનિમાં ભટક્યા કરે છે.”","e":null,"s":["16/29/19-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1216,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ જીવેન્દ્ર નૃપ અને હરિજનોને વાત કરતાં કહ્યું, “ભગવાન અથવા ભગવાનના સંત મળે ને એ જીવ પર અત્યંત દયા કરે ને જીવનો ઉદ્ધાર કરે ત્યારે તે ઉદ્ધરે છે. તે સિવાય જીવનાં મુક્તિનાં દ્વાર બધાં બંધ જ રહે છે. આપમેળે કોઈ માયાના બંધનથી છૂટ્યો હોય તેમ આજ દિન સુધી દેખ્યામાં આવ્યું નથી. સિંહ જેવો પ્રતાપી બળવાન કોઈ નથી તોપણ લોઢાના પાંજરામાં પડ્યો પછી તે ફાવે તેટલા ઉપાય કરે, પણ પોતાના બળથી તે મુક્ત થઈ શકતો નથી, તેમ પાપ અને અજ્ઞાન-અંધકારના કૂપમાંથી બહાર નીકળવા જીવને સંત વિના બીજો ઉપાય જ નથી. માટે સંતને દુખવતાં થકા રાત-દિવસ મનમાં ડરવું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1217,"k":"para","g":"“વ્રત વગેરે ચાહે તેટલાં સાધન કરે, પણ સંત મળ્યા વિના નકામું. જે કરે તેમાં અધિક અધિક બંધન થાય છે, તેની તેને ખબર રહેતી નથી. જે દી તે દી સાચા સંતનો સંગ કરશે ને તેના વચનમાં વિશ્વાસ લાવી મંડશે ત્યારે સંત તેને બંધનથી મુક્ત કરશે. આ સિદ્ધાંત વાત છે. સિદ્ધાંત હોય તે કોઈ દિવસ ફરે નહિ. સંત વિના જીવનું બંધન ટળતું નથી, એમાં તલમાત્ર ફેર નથી. અગણિત જીવોનો મોક્ષ કરવા આ વખતે અમે સાચા સંતને જુદા રાખ્યા છે. જો મિથ્યા સંતોમાં સાચા સંત ભળી જાય તો બધાનું એક મૂળ થઈ જાય પછી સાચા-ખોટાનો વિભાગ જ ક્યાં રહ્યો? માટે બન્ને એક-બીજામાં ભળી શકતા નથી. જેમ દિવસમાં ક્યારેય રાત ભળે નહિ ને રાતમાં દિવસ ભળે નહિ. આ વખતે અમે આ પ્રકારનો ચોખ્ખો વિચાર કરી રાખ્યો છે જે રાત ને દિવસની જેમ કુસંગ અને સત્સંગની રીત જુદી છે. સાચા સંતનું વર્તન દેખી મુમુક્ષુને તેની પરખ પડે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1218,"k":"para","g":"“સાચા સંત સાચા સત્સંગમાં છે. જ્યાં સત્ય વર્તન છે ત્યાં તેટલો ભગવાનનો વાસ છે અને અસત્ય વર્તન છે ત્યાં અધર્મ વસે છે. આ સિદ્ધાંત વાત છે, તેમાં રતિભર જૂઠ નથી. અને સાચો સિદ્ધાંત પણ તેને જ કહેવાય કે જેમાં લેશપણ ફેરવણી ન રહે. બ્રહ્મા જેવા અપાર આવે તોય લગાર પણ આ વાતને ફેરવીને જૂઠી કરી શકે નહિ. આવી વાત સિદ્ધાંત કહેવાય. સિદ્ધાંત કદી ફરે નહિ. ફરે તે સિદ્ધાંત રહે નહિ. મનુષ્યો જ્યાં સુધી સત્સંગના નિયમમાં વર્તે છે ત્યાં સુધી અમારા વચને કરીને તેનો મોક્ષ થશે.” આવી વાત શ્રીહરિએ કરી તે હરિજનો સાંભળી જ રહ્યા.","e":null,"s":["16/45/20-35"],"sv":["भगवान वा भगवान के संता । दया जन पर लाये अत्यंता ॥\n\n उद्धार करे तब होत उद्धारा । ता बिन बंध भये सब द्वारा ॥\n\n बंधे आपसे छुटे ऐसे । आज दिन लग न देखे तेसे ॥\n\n सिंह जेसे बलवंत न कोउ । लोह की अजारी में परे तोउ ॥\n\n च्हाय तितने करे उपाया । आपके बल न चलत रहाया ॥\n\n पाप ताके अज्ञान रूपा । अंधकार रहाये कूपा ॥\n\n संत बिन ताके न कोउ उपाया । रातदिन इनसे डरत रहाया ॥\n\n तीर्थव्रत दान पुन्य जेहा । करत रहे दिन दिन तेहा ॥\n\n बंधन से अधिक बंधन होवे । एसे करत रहे पिछे न जोवे ॥\n\n जे दिन ते दिन हि तेही । साचे संत तिन के एहि ॥\n\n करहि विश्वास जबहु । बंधन से संत छोडहि तबहु ॥\n\n बात रहे सिद्धांत यह, सिद्धांत ना फिर जेउ ।\n\n बंधन जीय के रहे सब, तिलभर फेर न तेउ ॥\n\n मोक्ष करन हित जीय के, अगनीत जो अब वेर ।\n\n साचे संत जो जितने, जुदे रखे बहु पेर ॥\n\n मिथ्या संत के माहि, साचे संत मिल जाय जब ।\n\n सब एक मूल रहाहिं, मिथ्या कुन रहेउ तब ॥\n\n दिनमें मिलत न रात, रातमें दिन न मिलत कबु ॥\n\n विचार करे एहिभांत, एहिवेर हमहि जो अब ॥\n\n रात-दिन रहे जिस रीता । सत्संग कुसंग तिस रीता ॥\n\n जुदे हि तिहां लग भगवाना । सत्य वर्तन रूप रहाना ॥\n\n सत्य वर्तन रहे जीहाँ जितना । भगवान के वास तिहां तितना ॥\n\n रतिभर यामें न फेर रहाये । सिद्धांत यह बात ठेराये ॥\n\n ब्रह्मा जेसे आवे अपारा । फिरे नहि जो बात लगारा ॥\n\n एसी बात सिद्धांत कहाते । फिर जावे सिद्धांत न रहाते ॥\n\n सत्संग के नियम में जेहु । जिहां लग जनहि वरतहि तेहु ॥\n\n तिहां लग मोक्ष होवहि ताके । हमारे वचन करके वाके ॥\n\n एसि हरि कहत रहेउ बाता । हरिजन जेते सुनत रहाता ॥"],"mt":false,"gl":null,"a":false},{"i":1219,"k":"para","g":"શ્રીહરિએ પીપળાવમાં કહ્યું, “જે ભગવન્નિષ્ઠ સંત છે તેને ભગવાનની સાથે જ તાન છે. ભગવાન કહે તેનો જ સંગ રાખે છે. ભગવાનને પણ એવા સંતથી બીજું અધિક નથી, એવા સંતને અર્થે ભગવાન અહીં પ્રગટ થાય છે. એવા ભગવન્નિષ્ઠ સંતની સેવા કરવાનો અમને ઉરમાં અત્યંત ભાવ જાગે છે.”","e":null,"s":["16/55/1-3"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1220,"k":"para","g":"પંચાળામાં શ્રીહરિએ સોરઠના હરિજન પ્રત્યે કહ્યું કે, “અમારી જેવી રુચિ છે તે તમને યથાર્થ જણાવીએ છીએ. સાચા સંત વિના કોઈથી જીવનો ઉદ્ધાર ક્યારેય થતો નથી. જેનામાં ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ હોય તે સાચા સંત છે. રામાનંદ સ્વામીમાં અમે આ ચારે ગુણો શુદ્ધપણે જોયા ત્યારે મન ઠર્યું. મોક્ષનો ખપ હોય તે આવા સત્પુરુષને ઓળખી તેના ભેગો રહે ત્યારે યથાર્થ દેખ્યામાં આવે છે. ઘી અને ખીર અમૃત તુલ્ય છે, પણ કીટ અને શ્વાનને તે વિષ જેવાં છે.”","e":null,"s":["17/17/32-35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1221,"k":"para","g":"વડનગરમાં શ્રીહરિએ વિદ્વાન વિપ્રોને વાત કરતાં કહ્યું, “ભગવાન તથા ભગવાનના એકાંતિક સંતના શરણ (આશ્રય) વિના ભગવાન સંબંધી જ્ઞાનની ગમ ક્યારેય પડતી નથી. ભગવાન અને ભગવાનના સાચા સંત તે જ્ઞાનનાં બે નેત્ર છે. બંને નેત્ર વિના પ્રાણી અંધ કહેવાય છે. બંનેમાંથી એકનો યોગ ન હોય તોપણ સાચા જ્ઞાનને પામતો નથી. બંનેના જોગ વિના બ્રહ્મા જેવો સમર્થ હોય તોપણ શું થયું? તેના અજ્ઞાનપાશનો નાશ થતો નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1222,"k":"para","g":"એ સાંભળી સભામાં જેટલા વિદ્વાનો બેઠા હતા તેઓ મનમાં અતિ આશ્ચર્ય પામ્યા. અને કહ્યું કે, “તમે ભગવાન સાચા.”","e":null,"s":["18/50/28-32"],"sv":["भगवान जो ताके, एकांतिक संतहु के ।\n\n शरन बिन जो वाके, ज्ञान की गम न परत कबु ॥\n\n भगवान अरु भगवान ताके । साचे संत रहाये वाके ॥\n\n ज्ञान के दोनुं नेत्र रहाये । दोनुं नेत्र बिन अंध कहाये ॥\n\n दो में एक के जोग बिन हि । ज्ञान साचे न पावत किनहि ॥\n\n दो के जोग बिन विधि जैसे । समृथ भये तोउ कहा तैसे ॥\n\n अज्ञान बंधन होत न नासा । अज्ञान के एसे रहे दृढ पासा ॥\n\n सभा में जेते बैठे विद्वानां । हरि की बात सुनिके काना ॥\n\n अति आश्चर्य पाये मनमांहि । बोलत भये तबहि तांहि ॥\n\n तुमहि सत्य रहे भगवाना । बातमें हमारे आये जाना ॥"],"mt":false,"gl":null,"a":false},{"i":1223,"k":"para","g":"શ્રીહરિએ દક્ષિણી વિપ્ર જનુબા હાકેમને સંતમહિમા કહેતાં કહ્યું, “જેના જીવમાં કાન્તા અને કનકનો ત્યાગ હોય અને એક કેવળ ભગવાનમાં અનુરાગ હોય એવા સંત જન્મમરણ-સંસૃતિથી જીવને મુકાવે છે. મોટાં ભાગ્ય હોય તેને જ આવા સંત ગમે છે. આવા સંત મોક્ષનું દ્વાર છે. આવા સંતનાં દર્શન દુર્લભ છે. જેના જીવમાં કાન્તા અને કનકનો ત્યાગ ન હોય એવા સાધુ હોય તે અપાર જન્મમરણનું દ્વાર છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1224,"k":"verse","g":"‘કનક કાન્તા ત્યાગ, હરિમેં રહે અનુરાગ એક.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1225,"k":"verse","g":"જાકે હોય બડ ભાગ, એસે સંત રૂચત તેહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1226,"k":"verse","g":"એસે સંત હિ જેઉ, મોક્ષ તાકે મગ રહેઉ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1227,"k":"verse","g":"એહિ વિન મગ જે તેઉ, સંસૃતિ અપાર દ્વાર રહેઉ.’","e":null,"s":["19/13/39-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1228,"k":"para","g":"વડતાલમાં શ્રીહરિએ સત્સંગમાં દંભી અને સાચા હરિજનની રીત બતાવતાં કહ્યું, “સાચા સંતના પ્રસંગ વિના ભગવાનની વાત અંતરમાં ચોંટતી નથી. સાચા સંતની જ્યારે ભાવથી સેવા ને પ્રસંગ કરે છે, ત્યારે ભગવાનની વાત સમજાય છે. સંતનો પ્રતાપ અગ્નિ જેવો છે. ચાહે તેટલો ડુંગર જેવડો દારૂનો ઢગલો હોય તો પણ એક તલ જેટલો તણખો તેને ઉડાડી દે છે. જનનાં પાપ જન્મ-જન્મનાં ભેગાં થયાં હોય તે જ્યારે સાચા સંત મળે છે ત્યારે ટળે છે. ભગવાન મળ્યા, સંત મળ્યા હવે ભાવમાં કસર તેટલી મોક્ષમાં કસર જાણવી.”","e":null,"s":["19/59(58)/10-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1229,"k":"para","g":"ગઢપુરમાં શ્રીહરિ કહે, “જેને ભગવાન સિવાય બીજી વાસના ન હોય અને પોતાના આત્માને બ્રહ્મરૂપ માનીને અતિશય સ્નેહે કરીને શ્રદ્ધા સહિત ભગવાનની ભક્તિ કરે, તેને એકાંતિક ભક્ત જાણવા.”","e":null,"s":["21/7/10-11"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1230,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ ભગવાનનાં દર્શન તુલ્ય જેનું દર્શન છે એવા સંતનો મહિમા કહેતાં કહ્યું, “જેને ભગવાનની ભક્તિ હોય અને એમ સમજે કે પુરુષોત્તમ ભગવાન, અક્ષરધામ અને મુક્તો આત્યંતિક પ્રલયમાં નાશ પામતા નથી અર્થાત્ એ દિવ્ય છે, અવિનાશી છે. વળી, એ ભગવાન સદા સાકાર છે, સર્વકર્તા છે. તેમના સિવાય આ જગતનો કરનારો બીજો કોઈ નથી અને એ ભગવાનની મરજી વિના સૂકું પાંદડું પણ હલવાને સમર્થ નથી. આવી પ્રગટ ભગવાનને વિષે જેની દૃઢ ભક્તિ હોય તે ભક્ત સાધારણ જેવો દેખાતો હોય તોપણ તે અમને પ્રિય છે. તેના માથે કાળ, કર્મ કે માયાનો હુકમ ચાલતો નથી. તેને દંડ દેવો હોય તો સ્વયં ભગવાન દંડ દે છે, પણ બીજાનો અધિકાર નથી. એવા નિષ્ઠાવાન સંતની ચરણરજ તો અમે માથે ચઢાવીએ છીએ, એ રખે દુખાઈ જાય! એમ અંતરમાં ડરીએ છીએ, એમનાં દર્શનને ઇચ્છીએ છીએ. એ સંત સાધનનું બળ લેશ પણ રાખતા નથી. વળી, ભવસિંધુ તરવા નાવ રૂપી ભગવાનનો આશ્રય રાખી કલ્યાણ ઇચ્છે એવા પ્રવીણ હોય છે. ને દેહત્યાગ પછી ભગવાનની હજૂરમાં બેસે છે. એવા ભક્તનું દર્શન ભગવાનનાં દર્શન તુલ્ય છે. વળી, એ સંતનાં દર્શનથી અનંત પતિત જીવોનો ઉદ્ધાર થાય છે, એવા એ મોટા છે.”","e":null,"s":["21/33/22-50"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1231,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સાચા સાધુની ઓળખ આપતાં કહ્યું, “સાચો સાધુ એ છે કે જે દેહ અને દેહનાં સંબંધીજનો પ્રત્યેનો અહં-મમત્વ ત્યાગ કરીને પોતાના આત્માને બ્રહ્મરૂપ માને. ભગવાન સિવાયની વાસનામાત્ર ત્યાગ કરે અને સ્વધર્મમાં રહીને ભગવાનની ભક્તિ કરે. એવું સાધુપણું જેનામાં આવ્યું તેને ને પુરુષોત્તમ ભગવાનને અણુ જેટલું છેટું રહેતું નથી. જે એવો સાધુ છે તે હું છું, અર્થાત્ એ મારું સ્વરૂપ છે.”","e":null,"s":["21/41/42-45"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1232,"k":"para","g":"ગઢપુરમાં રામનવમીના ઉત્સવ પછી શ્રીહરિ કહે, “ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ - આ ચારેય નિષ્ઠા એક પુરુષમાં આવી મળે, અને તે બધાથી અધિક વર્તતા હોય તે પુરુષને પરમ ભાગવત જાણવા અને એકાંતિક ભક્ત પણ તેને જ જાણવા.”","e":null,"s":["21/44/55-56"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1233,"k":"para","g":"શ્રીહરિએ ગઢપુરમાં જીવના મોક્ષની વાત કરતાં કહ્યું, “સ્વધર્મ, જ્ઞાન, વૈરાગ્ય, આત્મનિષ્ઠા ને માહાત્મ્યજ્ઞાને સહિત ભગવાનની ભક્તિએ યુક્ત હોય તેને ભગવાનના એકાંતિક સાધુ જાણવા. એવા એકાંતિક સાધુનો નિશદિન પ્રસંગ કરે તો ભાગવત ધર્મનું પોષણ થાય છે અને જીવના મોક્ષનું દ્વાર પણ એવા સાધુના પ્રસંગથી ઊઘાડું થાય છે.”","e":null,"s":["21/51/9-11"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1234,"k":"para","g":"નિર્વાસનિક એવા એકાંતિક ભક્તને ભગવાન વશ વર્તે છે.","e":null,"s":["21/62/29"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1235,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સંતનો મહિમા કહેતાં કહ્યું, “સંતના હૃદયમાં ભગવાન અખંડ નિવાસ કરીને રહ્યા છે માટે સંતની મર્યાદા રાખવી જોઈએ. જે ભક્ત ભગવાનની મૂર્તિને ચિત્રની કે પાષાણાદિકની જાણે છે અને સંતને બીજા મનુષ્ય જેવા જાણે છે તેને ભગવાન અને સંતમાં નાસ્તિકભાવ અવશ્ય આવે છે.”","e":null,"s":["21/71/20-24, 33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1236,"k":"para","g":"ગઢપુરમાં ઉત્તમ રાજાના દરબારમાં શ્રીહરિએ સંતનાં લક્ષણ કહેતાં કહ્યું કે, “જે સંતમાં કોઈ અપેક્ષા નથી, જેને કોઈ સાથે વેર નથી, જે મત્સર રહિત છે, બધા સાથે મિત્રતા રાખે છે, અંતરથી નિષ્પાપ છે, સૌનું હિત ઇચ્છે છે, પોતા કરતાં બીજાને અધિક માને છે, પોતાના ગુણોથી એક ગુણ પણ જેનામાં અધિક દેખે છે તેને પોતા કરતાં મોટો ગણે છે અને તેને જીવે ત્યાં સુધી ગુરુ માને છે - એવા અનંત શુભ ગુણ જેમાં રહ્યા હોય તેને અમે વિવેકી સાચા સંત કહીએ છીએ. સંતમાં લોભ આવે છે ત્યારે વિચાર અને ધીરજ તે ધારી શકતો નથી, લોભનો પ્રવેશ તેનું સંતપણું હરી લે છે. પોતાને નિર્દોષ માને છે અને અન્યમાં દોષ દેખે છે તેનું અંતર અતિશય મલિન થઈ જાય છે.”","e":null,"s":["21/87/5-7"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1237,"k":"para","g":"ગઢડામાં શ્રીહરિએ સંત-હરિજનો પ્રતિ વાત કરતાં કહ્યું, “જો સૂર્યની હાજરીમાં અંધારું થાય, જળ વિના અન્ન થાય, રાજા વિનાની પ્રજા સુખી થાય તો સંત વિના મોક્ષ થાય. સંતને તજીને મોક્ષને ઇચ્છે છે તે ભૂમિનો ત્યાગ કરીને કોઈ ચાલવાને ઇચ્છે તેના જેવો જ મૂર્ખ છે.”","e":null,"s":["22/27/33-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1238,"k":"para","g":"જળઝીલણી ઉત્સવ પર સભામાં શ્રીહરિએ સત્સંગ અને ભગવાનના નિર્ગુણપણા સંબંધી તથા ખપ સંબંધી ઘણીક વાતો કરી અને કહ્યું કે, “પરમ ભાગવત સંત ભગવાનમાં જ બધું સુખ જુએ છે. ત્યાગી અને ગૃહી જે કોઈ એવી સમજણવાળા હોય તે બધા ભાગવત સંત છે, અને ભવસાગર તારે છે.”","e":null,"s":["22/37/33-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1239,"k":"para","g":"ગઢપુરમાં સંતમહિમા કહેતાં શ્રીહરિ કહે, “એકાંતિક ભક્તના ધર્મ વાસુદેવ માહાત્મ્યમાં કહ્યા છે. એકાંતિક હોય તે પોતાને દેહરૂપે ન માને પણ ચૈતન્યરૂપ માને. સ્વધર્મ, જ્ઞાન, વૈરાગ્યે યુક્ત ભગવાનની ભક્તિ ભાવથી કરે. ભગવાન વિના બીજા કોઈ પદાર્થની ઇચ્છા ન રાખે. આવી રીતે ભગવાનને ભજીને જે (એકાંતિક) સાધુ થયો તેને સાધુથી અધિક બીજી કોઈ પદવી પ્રાપ્ત કરવાની બાકી રહેતી નથી. બધી પદવીઓમાં શ્રેષ્ઠ સાધુની પદવી છે. જેમ રાજાનું રાજ્ય તેટલું રાણીનું રાજ્ય કહેવાય છે ને રાજાનો હુકમ ચાલે તેવો રાણીનો હુકમ ચાલે તેમ જેવો ભગવાનનો પ્રતાપ છે તેવો જ પ્રતાપ ભગવાનના સાધુનો કહ્યો છે.”","e":null,"s":["22/103/59-66"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1240,"k":"para","g":"લોયામાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “સત્પુરુષનો પ્રતાપ કુબુદ્ધિ જનને દેખાતો નથી. સત્પુરુષ પણ પોતાનો પ્રતાપ છુપાવીને વર્તે છે. ખબર પણ ન પડે તે રીતે સત્પુરુષ ભગવાનના બળથી અસત્યને ઉથાપે છે, સત્ય જ્ઞાનનું પ્રવર્તન કરે છે. સત્સંગ ત્યાં જ રહ્યો છે જ્યાં સત્ય જ્ઞાનનું પ્રવર્તન છે.”","e":null,"s":["24/51/15-17"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1241,"k":"para","g":"લોયામાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “સત્પુરુષ પ્રગટ થાય છે ત્યારે તેમના મુખે અથવા ભગવાનના મુખે સત્સંગ અને કુસંગનું રૂપ યથાર્થ ઓળખાય છે. સત્પુરુષ અને ભગવાનની ઓળખાણ એનું દૈવત છે અને એ દૈવત વર્તનનું છે. દેશકાળમાં એક સરખું વર્તન રહે તો જાણવું કે તે સત્પુરુષ છે કે ભગવાન છે. જેમ નીતિમાં રહેતો હોય તે પ્રજામાં પણ નીતિપાલન કરાવતો હોય એવા રાજાનું મૂળ અચળ હોય છે. નીતિ નેત્ર છે, નીતિ વિનાના અંધ કહેવાય તેમ નિયમપાલન ન હોય તે અંધ છે. સંતનો તે દ્વેષ કરે છે, પણ ક્યાં રાત્રિ ને ક્યાં સૂર્ય?”","e":null,"s":["24/51/22-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1242,"k":"para","g":"શ્રીહરિએ મુક્તમુનિને એક વાત કરેલી તે તેમણે ઉત્તમનૃપને કહી કે, “સત્પુરુષ જે જે ક્રિયા કરે છે તેમાં ભગવાનને મુખ્ય રાખે છે. સામાન્યજનને નદીના પ્રવાહની જેમ સંકલ્પ-વિકલ્પનો પ્રવાહ ચાલતો હોય છે. જ્યારે ભગવાનના સાચા હરિજનને ભગવાનના સંકલ્પ થાય છે. કથાવાર્તા, કીર્તન, ભજન, સ્મરણ, ધ્યાન, સેવા વગેરે ભગવાન સંબંધી થયાં કરે છે. જગત સંબંધી સંકલ્પોનું મૂળિયું ઉખાડી નાખે છે.”","e":null,"s":["26/8/34-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1243,"k":"para","g":"શ્રીહરિએ સુરતમાં અરદેશર કોટવાલ સાથે વાત કરતાં કહ્યું, “સાચો સત્સંગ કર્યા વિના લખચોરાશીનાં દુઃખ તલભર જાણ્યામાં આવતાં નથી. પોતાની રુચિ અનુસાર ગુરુઓ, સાધુઓ અને આચાર્યો ઘર-ઘર મોક્ષ માને છે, પરંતુ તેમ મોક્ષ થતો નથી. જેમ સરકારની મહોરછાપ લાગે તે વસ્તુ સર્વત્ર પ્રમાણ થાય તેમ જેમાં ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ રહ્યાં હોય એવા ધર્મવંશી ગુરુની મહોરછાપ મોક્ષના માર્ગે પ્રમાણભૂત ઠરે છે. જ્યાં અધર્મ થતો હોય એવા ગુરુ કે આચાર્ય પોતાના શિષ્યો સહિત કોટિ કલ્પો સુધી જમપુરી ને લખચોરાશી ભમે છે. મનમાન્યું વર્તન કરી કલ્યાણ માને ને પેટ ભરવા ગુજરાન કરે તેને યાતનાઓ કેડો છોડતી નથી.”","e":null,"s":["27/46/27-32"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1244,"k":"para","g":"સુરતમાં પીરુશાના ભવનમાં શ્રીહરિએ સત્પુરુષનાં લક્ષણ જણાવતાં કહ્યું, “સત્પુરુષનું તે જ લક્ષણ છે કે જેમાં કોઈ દોષ નથી, એવી સત્ય વાતનો સંગ્રહ કરે છે. સંતમાં અનંત તીર્થો સમાયાં છે, એવા સંતનો આશ્રય જે નર-નારી કરે છે ને તેની પ્રેમભાવથી સેવા કરે છે તેનાં પાપમાત્ર નાશ પામે છે, કારણ કે તેમાં ભગવાન પ્રગટ રહ્યા છે. અસદ્‌બુદ્ધિવાળા જન તેનો દ્રોહ કરે છે, પણ સત્પુરુષના જોગ વિના કલ્પેય મોક્ષ થાય નહિ.”","e":null,"s":["27/62/29-40"],"sv":["श्रीहरि तब बोलत हि भयेउ । सत्पुरुष के चिह्न हे तेउ ॥\n\n संत के आश्रय करत जेता । नारी-नर कहावत तेता ॥\n\n संत में अनंत तीर्थ रहीता । ताकि सेवा जेते करीता ॥\n\n भाव, प्रीत, सेवा तामें । भगवान प्रगट रहायेक यामें ॥\n\n चाय तितना जन पाप कराता । सेवा करत ताके बलि जाता ॥\n\n सेवा में जितना मंद भावा । तितना पाप हि दुःख देखावा ॥\n\n सत्पुरुष हि ताके, जोग बिन कोटि कल्प लग ।\n\n असत् जन जो वाके, मोक्ष न सत्य बात कहत ॥"],"mt":false,"gl":null,"a":false},{"i":1245,"k":"para","g":"શ્રીહરિએ સુરતમાં પીરુશાને વાત કરતાં કહ્યું, “સત્પુરુષની બધી વાતો સત્ય હોય છે. જે જન પોતાના દોષ ઓળખી સત્પુરુષની સેવા-પ્રાર્થના કરે છે તો સત્પુરુષના યોગથી તેની શુભ ગતિ થાય છે. મોટા મનુષ્ય કહેવાતા હોય અને તે અતિ ભાવથી જો સત્પુરુષનો પક્ષ ન રાખે તો તેનાં બધાં કરેલાં કોટિ સાધન પણ પરલોકમાં સહાય કરતાં નથી. આ વાતને જે સમજે તે બુદ્ધિશાળી છે.”","e":null,"s":["27/63/2-7"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1246,"k":"para","g":"સુરતમાં શ્રીહરિએ ઇંદરસન સાહેબના બંગલે વાત કરતાં કહ્યું, “સંસારની વાતમાં જેવો ભાવ છે તેવો ભાવ ભગવાનને વિષે સત્પુરુષનો યોગ થયા વિના થતો નથી.”","e":null,"s":["27/79/29"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1247,"k":"para","g":"મુક્તમુનિ અને નિત્યાનંદમુનિને શ્રીહરિએ વાત કરતાં કહ્યું, “ભગવાનમાં જ્યાં સુધી જીવ ચોંટે નહિ ત્યાં સુધી વેદ પુરાણ ભણે કે આખી ભૂમિની સમૃદ્ધિ મેળવે તોપણ જન્મમરણથી છૂટે નહિ. ભગવાનમાં ચિત્ત જોડે તેને સત્પુરુષ કહેવાય છે. પોતાનું ચિત્ત ભગવાનમાં જોડવું ને બીજાનું જોડાવવું એ બે વાત પર તેને તાન રહે છે.”","e":null,"s":["28/50/5, 13-15"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1248,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1249,"k":"para","g":"સત્પુરુષ નાવ સમાન છે. જેમ કોઈ નાવ સમીપે જઈને તેનો આશ્રય કરે છે તેને નાવ સામે કાંઠે લઈ જાય છે, તેમ સત્પુરુષનો આશ્રય કરવાથી ભવસાગર તરાય છે. સંત વિના પ્રગટ ભગવાનનો નિશ્ચય થતો નથી. સંત ઘરે આવે ને મુમુક્ષુબુદ્ધિ હોય તો નિશ્ચય થાય. જગતનો રાગ ટળે નહિ ત્યાં સુધી મુમુક્ષુતા જાગતી નથી. ચાર પ્રકારના પ્રલયની વાતો સંતમુખે સાંભળે ત્યારે વૈરાગ્ય થાય છે. પછી ભગવાન વિના કંઈ રૂડું લાગતું નથી. મુમુક્ષુ હોય તેના હૃદયમાં ભગવાનનો મહિમા ટકે છે. નાસ્તિકપણું મોટું પાપ છે, તે સંત મળે ત્યારે ટળે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1250,"k":"verse","g":"‘નાસ્તિકભાવ સબ પાપ સેં ભારી, સો વહિ જાત લગત ન વારી.’","e":null,"s":["1/77/26-32"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1251,"k":"para","g":"સંત પારસમણિ, ચિંતામણિ, કલ્પતરુ અને કામધેનુ સમાન છે. સર્વ સુખનું ધામ - એવા સંત મળે તો રિદ્ધિ અને સિદ્ધિનું શું કામ છે? સાચા સંતની ચરણરજ પાપી જનને દુર્લભ છે. એવા સંતની ચરણરજ જે માથે ચઢાવે છે તેનો ભગવાનની સમીપે વાસ થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1252,"k":"verse","g":"‘સંત ચિંતામની પારસ જૈસે, કલ્પતરુ કામધેનુ એસે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1253,"k":"verse","g":"ઓરહિ રિદ્ધ સિદ્ધ કો કહા કામા, સંત મિલે જબ સબ સુખધામા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1254,"k":"verse","g":"તિનકી ચરનરજહિ જોઉ, પાપી જનકું દુર્લભ સોઉ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1255,"k":"verse","g":"સંત કી રજ શિર જેહિ બઢાવા, હરિ સમીપ તેહિ વાસ કરાવા.’","e":null,"s":["3/36/34-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1256,"k":"para","g":"સત્સંગનું કારણ સંત છે. સંત વિચરતા રહે તો સત્સંગનો રંગ તાજો રહે. સંત વિના સત્સંગનો રંગ ઊતરી જાય. જેમ ગંગા કપડાનો મેલ ધૂએ છે, તેમ સંત હૃદયનો મેલ ધુએ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1257,"k":"verse","g":"‘સત્સંગ કો કારણ હૈ સંતા, જો રહેવે અખંડ વિચરંતા,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1258,"k":"verse","g":"તબ સત્સંગ કો રહે મહારંગા, જ્યું પટ પવિત્ર કરત હૈ ગંગા.’","e":null,"s":["3/61/43"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1259,"k":"para","g":"દામ-વામથી દૂર રહે તેને સાચા સંત લેખવા. તે ક્યારેય અભક્ષ્ય ન ખાય. પોતાનો આત્મા ભગવાનની હજૂરમાં નિત્ય રહે છે. બધી ઇન્દ્રિયોને તે નિયમમાં વર્તાવે છે. ઇન્દ્રિયોનો આહાર મલિન થવા દેતા નથી. એવા સંતને ભગવાનના ચરિત્રનો આહાર એ જ આહાર છે. એ વિના બીજો આહાર ઇન્દ્રિયોને આપતા નથી. તેઓ ઇન્દ્રિયોને ચોર જાણીને તેનો કદી વિશ્વાસ કરતા નથી. ઇન્દ્રિયરૂપી શત્રુ તેનાથી થર થર ધ્રૂજે છે. ભગવાનના દૃઢ નિશ્ચય યુક્ત એવા એ સંતને સાચા સંત કહ્યા છે. જે મોક્ષની ઇચ્છા રાખે છે તેણે એવા સંત જ્યાં દેખાય ત્યાં જઈ તેમનો સત્સંગ નિઃશંકપણે કરવો.","e":null,"s":["4/26/35-41"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1260,"k":"para","g":"ભગવાનમાં અનંત આશ્ચર્ય રહેલાં છે, એકાંતિક ભક્ત સિવાય તે કોઈના કળ્યામાં આવતાં નથી. એકાંતિક વિના અન્ય મોટા મુક્તો ને સિદ્ધોને પણ એમાં મોહ થાય છે. એકાંતિક ભક્ત ભગવાનની અનાદિની રીત બરાબર જાણે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1261,"k":"para","g":"ભગવાન મનુષ્યચરિત્ર કરે છે તેમાં એકાંતિક ભક્તને સુખ ઊપજે છે, અન્યને તે બંધનકારી થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1262,"k":"para","g":"લૌકિક મનુષ્યભાવ ને અલૌકિક દિવ્યભાવ બન્ને એકાંતિકને મતે દિવ્ય જ છે, તેમાં તેને ભેદ જણાતો જ નથી. એટલા માટે એકાંતિકપણું પ્રાપ્ત કરવું તે આત્મનિષ્ઠા ને ધર્મનિષ્ઠા કરતાં અનંતગણું અધિક છે.","e":null,"s":["4/31/27-35"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1263,"k":"para","g":"જગતના જીવ સત્પુરુષને ઓળખી ન શકે. અસત્પુરુષ ભેટતાં તેના માર્ગે ચાલે છે તેની અસદ્‌બુદ્ધિ થઈ જાય છે. પાપ કરતાં અંતર મૂઢ થાય છે. પછી સત્પુરુષનો દ્રોહ કરીને તે ખુવાર થાય છે.","e":null,"s":["4/40/41-43"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1264,"k":"para","g":"જે સાધુમાં શીલ-સદાચાર ને બ્રહ્મચર્યરૂપ ધર્મ નથી અને વિવિધ રસનો યોગ છે તે હળાહળ વિષ ખાય છે ને ભવરોગથી પીડાય છે. જેનામાં શીલ-સદાચાર ને બ્રહ્મચર્યરૂપ ધર્મ છે, જે રસમાત્રને વિષતુલ્ય જાણી તેનાથી દૂર રહે છે, અનન્ય એવા પરમાત્મા સિવાય જેમને બીજો કોઈ રસ નથી એવા સાધુનો સંગ કોઈ કરે તો તેમાં તેના ગુણોનો નિશ્ચય ઉદય થાય છે. તેને પણ ભગવાનના રસ વિના બીજો રસ ઊડી જાય છે ને પ્રગટ મુક્તિ પામે છે.","e":null,"s":["4/45/50-52"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1265,"k":"para","g":"જીવ અનંતકાળથી લોઢાથી પણ કઠોર રહેલો છે. તેણે અનેક મોટાં પાપ કરેલાં છે. તેને શુદ્ધ કરવા સત્પુરુષ સિવાય કોઈ ઉપાય નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1266,"k":"para","g":"ભગવાન તો ચિંતામણિ છે, પણ સત્પુરુષ પારસ તુલ્ય છે. જીવ જ્યારે તેનો સંગ કરે છે ત્યારે તે લોઢાનું કંચન કરી મૂકે છે. એવો તેમાં પ્રતાપ રહ્યો છે. એ સત્પુરુષ પાસે કોઈ જાય અને તન-મન તેને સોંપી દે, પોતાની સમજ-ડહાપણ તેની પાસે ન રાખે તો તેનું અંગ પલટે, તે વિના લોઢાનું કંચન ક્યારેય ન બને. તે કરોડ વર્ષ સુધી સંગ કરે તોપણ અવયવ ન ફરે.","e":null,"s":["4/58/16-18"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1267,"k":"para","g":"ખમવું એ સાધુનો ગુણ છે. ‘હરિ બિન એસો ગુણ ન આવે.’ આવો ગુણ ભગવાન સિવાય કોઈમાં આવતો નથી. પૃથ્વી અને વૃક્ષનો ગુણ મોટો છે. એકને ખોદે છે ને બીજાને કાપે છે તોપણ દોષ વિના બન્ને ધાન્ય અને ફળ-ફૂલ આપે છે. સહન કરવાનો ગુણ મોટા સત્પુરુષનો છે, તે અલ્પ જનમાં કદી આવતો નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1268,"k":"para","g":"સંતનો પ્રથમ ગુણ સહનશીલતા છે. સિદ્ધનો વેશ લઈ લોકને ડરાવે છે તેમાં આ ગુણ રતી જેટલો પણ નથી હોતો. તિતિક્ષા રહિતપણું અસુરનો ગુણ છે. સત્પુરુષ કામ ક્રોધ, લોભાદિક અધર્મસર્ગને શ્વપચની પેઠે ત્યાગીને વર્તે છે. ભગવાન વિના એમને કશામાં અનુરાગ નથી. એ જગ-ઉપહાસ સહનારા, દયાળુ ને પરમ સુખકારી છે.","e":null,"s":["4/59/8-12"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1269,"k":"para","g":"જ્યાં ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ - એકાંતિક ધર્મ નથી ત્યાં કોઈનું ઠેકાણું ન રહે. જ્યાં આ ચારે દિન-પ્રતિદિન વૃદ્ધિ પામતાં દેખાય, ત્યાં જાણવું જે શ્રીહરિને ભજવાની શ્રદ્ધા અહીં છે. અક્ષરધામ અને સમગ્ર લોક પણ ત્યાં જ વસે છે તેમ નિશ્ચય માનજો. લોક માને કે ન માને, કોઈ વખાણે કે ન વખાણે તેનાથી તેઓ (એકાંતિક) ઝાંખા પડતા નથી કે તેની સાથે વૈર બાંધતા નથી. આવા ભગવાનના એકાંતિક ભક્ત હરિના ધામ(અક્ષરધામ)થી આવેલા જાણવા.","e":null,"s":["4/72/6-12"],"sv":["धर्म, भक्ति, वौराग्य हि ज्ञाना । ताको न रहत ठिकाना ॥\n\n दिन दिन अधिक रहे हें चारी । हम अंतर में देखे धारि ॥\n\n हरि लोक में श्रद्धा जाकुं । धाम के लोक समझना ताकुं ॥\n\n लोक मानो न मानो कोई । तिन सें न झांखे परे सोई ॥\n\n वखानो न वखानो कोउ । ता संग वैर न बांधे सोउ ॥\n\n एसि रित के जन हि जेता । हरि के धाम के जानना एता ॥"],"mt":false,"gl":null,"a":true},{"i":1270,"k":"para","g":"હરિજનનાં નેત્ર સમાન સંત છે. જીવોનું આત્યંતિક કલ્યાણ સંત કરે છે. સંત વિના સત્સંગ આંધળો છે. એવા સંત મળ્યા તે અલૌકિક અવસર કહેવાય. ભવ-બ્રહ્માદિક દેવ જેમની પૂજા કરવા ઇચ્છે છે, પણ તેમને લહાવો મળતો નથી. જે સેવા દેવતાને ન મળે, તે તમને મળી છે.","e":null,"s":["4/78/3-4"],"sv":["हरिजन-नेत्र हैं संत, आत्यंतिक मोक्ष करन हित ।\n\n संत बिना न देखंत, समय अलौकिक आवे यह ॥\n\n भव-ब्रह्मादिक देव, जाकी पूजा सो चहत नित ।\n\n ताकु मिलत न सेव, सो तुमने सेव कियेउ सब ॥"],"mt":false,"gl":null,"a":true},{"i":1271,"k":"para","g":"ભગવાનની શક્તિ-સામર્થિનું જ્ઞાન, એકાંતિક ભક્તને છે. એકાંતિક ભક્ત સિવાય બીજા શ્રીહરિનું સામર્થ્ય જાણે છે છતાં તે ન જાણ્યા જેવું છે. તેથી તેનાં પાપ ટળતાં નથી ને લખચોરાશીમાં ફરે છે. જ્યાં સુધી તે એકાંતિક સંતને માને નહિ ત્યાં સુધી તેનાં પાપ ટળતાં નથી. સંત નથી ઓળખાતા ત્યાં સુધી પાપ છે એમ જાણવું. સર્વ કારણનું કારણ સંત છે. અસંતને ઓળખે પછી સંત ઓળખાય છે. સંત ઓળખાયા તેનાં દુઃખમાત્ર ટળી જાય છે.","e":null,"s":["5/47/36-39"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1272,"k":"para","g":"સ્વાદિષ્ટ ભોજનને એક પાત્રમાં મેળવીને, સ્વાદ રહિત કરીને જમે, હરિ વિના બીજું વ્યસન લેશ પણ ન હોય, સર્વને બ્રહ્મવિદ્યાનો ઉપદેશ કરે, નારી અને ધનથી દૂર રહે, અજાણતાં અડી જાય તો ઉપવાસ કરી નાખે! એવા સંતને મનુષ્ય ન જાણવા, પરંતુ ભગવાન તુલ્ય જાણવા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1273,"k":"verse","g":"‘હરિ બિન વ્યસન ઓર ન લેશા, સબહિ કરત સત ઉપદેશા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1274,"k":"verse","g":"નારી ધન કો નિકટ ન જાવે, અજાન અડે ઉપવાસ કરાવે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1275,"k":"verse","g":"...યાકુ નહિ મનુષ્ય જાના...’","e":null,"s":["5/28/20, 22"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1276,"k":"para","g":"સાધુતા અને અસાધુતા વર્તનથી જણાય છે. જેવું વર્તન દેખે તેવો ગુણ લોકો લે છે. જેને શ્રીહરિનો સાક્ષાત્કાર છે, જેના જિવાડ્યા સૌ જીવે છે, એવા મોટા ક્યારેક કટુ વચન કહે તો અસાધુને વસમું લાગે છે. મોક્ષના દાતા માન્યા હોય તોપણ એ સત્પુરુષનો તે દ્રોહ કરે છે.","e":null,"s":["5/66/30-32"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1277,"k":"para","g":"ભગવાનના પ્રતાપથી કોઈ મોટી સિદ્ધગતિને પામ્યો હોય તોપણ તે સત્સંગમાં નાના-મોટા સૌ કોઈ સંતો-હરિભક્તોનો મન, કર્મ, વચને દાસ થઈને રહે અને સૌને ઘટતું સન્માન કરે, માન આપે. વળી, જેવો મુખ પર ભાવ તેવો અંતરમાં ભાવ રાખે તેને સત્સંગમાં મોટો જાણવો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1278,"k":"para","g":"સિદ્ધ-મુક્ત એ જ સાચા કે જે રસમાં લોભાય નહિ. શ્રીહરિની જેટલી આજ્ઞામાં વર્તે તેટલો મુક્ત. રસમાં લોભાય તો તે કાચો છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1279,"k":"verse","g":"‘સો સિદ્ધ મુક્ત હિ સાચે, રસ મેં લોભાય તિતને કાચે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1280,"k":"verse","g":"શ્રીહરિ આજ્ઞા મેં વર્તે જિતના, સિદ્ધ મુક્ત જાનના તિતના.’","e":null,"s":["7/61/23"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1281,"k":"para","g":"સંતની કૃપા થાય ત્યારે શ્રીહરિને ઓળખવાની અલૌકિક મતિ પ્રાપ્ત થાય છે. સંતની કૃપા વિના કોટિ પ્રકારે જતન કરે તોપણ અલૌકિક મતિ કોઈ કાળે આવતી નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1282,"k":"verse","g":"‘સંત કી કૃપા હોવત જબહિ, અલૌકિક મતિ જન પાવત તબ હિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1283,"k":"verse","g":"સંત કૃપા વિન કોટિ પ્રકારા, અલૌકિક મતિ ન હોત કોઉવારા.’","e":null,"s":["8/42/8-10"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1284,"k":"para","g":"જેને ભગવાન વિના બીજી કોઈ ચાહના-ઇચ્છા નથી, તેને સદા શ્રીહરિ નિકટ વસે છે. જો બીજી ચાહના રાખે તો હરિ તેટલા દૂર રહે છે. જીવનું ખાતું તપાસે ત્યારે આ હિસાબ મળે છે. જ્યારે સંતની સેવા કરે છે, ત્યારે શ્રીહરિ તે જીવનો ઉદ્ધાર તરત કરે છે. સેવા પણ મંદ, મધ્ય ને તીવ્ર એમ ત્રણ વેગથી થાય છે. સમજુ હોય તેણે તીવ્ર વેગથી સંતની સેવામાં મંડી પડવું. મોક્ષ કરવાની ભગવાનની રીત પણ અનંત પ્રકારની છે. અક્ષર મુક્તો પણ તેનો પાર પામતા નથી. શ્રીહરિની મરજી જાણી તે મુજબ વર્તતા હોય તેને પરમ એકાંતિક સંત જાણવા. તેને એક શ્રીહરિનો જ દૃઢ વિશ્વાસ છે ને એટલે જ તેને બધાથી અધિક કહે છે ને ભગવાન જે રીતે રાખે તેમાં સદા મગન રહે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1285,"k":"para","g":"બ્રહ્મા, શેષ વગેરે પોકારીને કહે છે કે શ્રીહરિની મરજી અનુસાર વર્તવું આનાથી વધીને કોઈ મોક્ષ નથી. શ્રીહરિ તેને જ્યાં રાખે ત્યાં અક્ષરધામ જ છે. હરિની મરજીમાં રહેવું તે અનંત અક્ષરધામ કરતાં પણ અધિક છે. હરિ રાખે તેમ રહેવામાં કોટિગણું દુઃખ આવે છતાં અનંતગણું સુખ એમાં છે એમ માનવું. સંતની સેવા કરવામાં જેટલું દુઃખ આવવું હોય તે ભલે આવે, પણ અંતે માયાપારનું દિવ્ય સુખ મળે છે. ભલે તેણે ચિંતવ્યું ન હોય તોપણ એ સુખને પામે છે.","e":null,"s":["9/21/27-40"],"sv":["हरि विन चाह न रखत जेहा । श्रीहरि निकट वसत तेहा ॥\n\n हरि बिन चाह जितनो जाकु । तितनो दूर रखत हरि ताकु ॥\n\n खातो जिय को तपासे जबहु । ऐसो हिसाब मिलत हें तबहु ॥\n\n संत की करे सेव जेहि वारा । तर्त जिय को हरि करत उद्धारा ॥\n\n मोक्ष होवन की नहि एक रीता । तीव्र, मध्य, मंद सेव लहिता ॥\n\n जो समझु होई जेहि प्रकारा । ताको मोक्ष करे तेहि अनुसारा ॥\n\n हरि में मोक्ष की रीत अनंता । अक्षर मुक्त न पार लहंता ॥\n\n हरि की मरजी जानत जन जेहु । परम एकांतिक एसे हें तेहु ॥\n\n हरि को रखत विश्वास हि एका । सब सें अधिक कहत जो विवेका ॥\n\n हरि रखे जेहि विधि जाहि । तामें रहेनो मगन सदा हि ॥\n\n इनसें पर नहि मोक्ष कोउ, ब्रह्मा कहे पोकार ।\n\n शेष कहत पोकार के, निश्चे एही निरधार ॥\n\n हरि की मरजी अनुसार हि, वरतना तत्पर होई ।\n\n जिहां दिये निवास हरि, अक्षरधाम हें सोई ॥\n\n हरि की मरजी जोई, अक्षर सें अनंत अधिक ।\n\n रखे त्युं रहना सोई, कोटि गण दुःख सो सुख अनंत ॥\n\n संत की करत सेव, दुःख आवो सो आवो अब ।\n\n ताकु सुख मिलहि अभेव, चितवे विन सो आई कर ॥"],"mt":false,"gl":null,"a":true},{"i":1286,"k":"para","g":"સત્પુરુષના સંગ વિના ફાવે તેવું તપ કરે તોપણ હિરણ્યકશિપુની પેઠે તામસ કર્મરૂપે જ તે બને. ચ્યવન ઋષિએ વિષયસુખ માટે શરીરનો રાફડો કર્યો! સૌભરિ ઋષિ પણ તપ કરવા છતાં સત્પુરુષના સંગ વિના ખુવાર થયા. સત્સંગ વિના બીજું જેણે ચિંતવ્યું તે શિવ, બ્રહ્મા, નારદ વગેરેને પણ ખોટ લાગી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1287,"k":"para","g":"સત્પુરુષ જ્યાં હોય ત્યાં ધર્મ, જ્ઞાન, વૈરાગ્ય અને ભક્તિનો નિવાસ હોય, અધર્મ અને ફેલ વ્યસનનો ત્યાં બિલકુલ પ્રવેશ હોય નહિ. વળી, સ્ત્રી-પુરુષો પણ એકરસ ન બનતાં હોય ત્યાં જ મોક્ષ રહે છે એમ જાણવું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1288,"k":"para","g":"રામ ત્યાં કામ નહિ અને કામ ત્યાં રામ નહિ. રવિ અને રાત્રિ સાથે હોય નહિ. મોક્ષ ત્યાં ફેલ નહિ ને ફેલ ત્યાં મોક્ષ નહિ. ફેલ હોય ત્યાં અધર્મનો ખેલ હોય, તે પાપમાં મોક્ષ મનાવે છે.","e":null,"s":["9/36/29-42"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1289,"k":"para","g":"સંતની સેવા ને પ્રસંગથી કોટિ કોટિ પાપ બળે. નારદ દાસીપુત્ર હતા, પ્રહ્‌લાદ દૈત્યપુત્ર હતા, પણ સંતના પ્રસંગથી સંત કહેવાયા. ધામ કરતાં પણ સંતતાનો ગુણ દુર્લભ છે. સૌ સાધન સંતતામાં આવી જાય છે. સાધુતા ન હોય તો ગુણ અને સાધન શોભતાં નથી, અને શ્રીહરિ પણ દૂર રહે છે.","e":null,"s":["9/37/21-24"],"sv":["संत की सेव को फल हे भारी । कोटि कोटि अघ दिये जारी ॥\n\n नारद दासीपुत्र रहाये । संत सेव कर संत कहाये ॥\n\n प्रह्‌लाद दैत्य के सुत रहावा । संत प्रसंग से संत कहावा ॥\n\n अक्षर से संतता गुन अधिकाई । संतता दुर्लभ कहत हरि ताई ॥\n\n अनंत साधन कहावत जेते । संतता तामे रहे हें तेते ॥\n\n अनंत गुन साधन अनंता । संतता से सब शोभा लहंता ॥\n\n संतता न आई ज्यां लगहि । गुन साधन सो न सोहत त्यां लगहि ॥\n\n संतता विन हरि रहत दूरा । उर में हें नहि भासत उरा ॥"],"mt":false,"gl":null,"a":true},{"i":1290,"k":"para","g":"સંતની મરજી મુજબ વર્તીને સંતને રાજી કરે એવો જન શ્રીહરિની હજૂરમાં રહે છે એ શાસ્ત્રપ્રમાણ છે. સાચા સંતનો યોગ અલ્પ પુણ્યથી થતો નથી, અનંત જન્મ તપ કરે ને તન ખુએ ત્યારે સાચા સંત મળે છે. એવા સંતનું માહાત્મ્ય શ્રીહરિ વિના કોઈ જાણી શકતું નથી, બીજા કોઈ તેને બુદ્ધિથી જાણવા મથે છે, પણ તેની બુદ્ધિ ત્રિગુણમયી હોવાથી ત્રણે ગુણોથી પર વર્તતા એવા (ગુણાતીત) સંતને તે ઓળખી શકતા નથી. જ્યારે તે સંતને ત્રણ ગુણથી પર દેખે ને તેની સેવા કરે ને એ સેવામાં જ પોતાનું સર્વસ્વ સાર્થક થયું લેખે ત્યારે વાત બને. તે વિના જ્યાં સુધી ગુણનો ભાવ દેખાય છે, ત્યાં સુધી સંત પર ભાવ થતો નથી.","e":null,"s":["9/37/26-30"],"sv":["संत मरजी तिमि चलत हें, संत करत प्रसन्न ।\n\n सो जन हरि की हजूर हें, ऐसे अनेक वचन ॥\n\n अल्प पुन्य नहि होत, साचे संत की जोग जोउ ।\n\n तप से अनंत तन खोत, तब मिलत संत सेव तेहि ॥\n\n संत को माहात्म्य जोउ, श्रीहरि विन जाने न कोउ ।\n\n ओर जाने मति ज्युं सोउ, तिन गुन में वर्तत तेहि ॥\n\n तिन गुन मति में आवे न जबहु । मति शुद्ध अति रहे सो तबहु ॥\n\n तिन गुन पर संतकुं जब देखे । सेवा तब तिनकी आवे सब लेखे ॥\n\n ता विन संत पर होये न भावा । गुन ज्यां लग आये देखावा ॥"],"mt":false,"gl":null,"a":true},{"i":1291,"k":"para","g":"સંસારનો મોહ જેને ટળી ગયો છે ને ભગવાન વિના કોઈ વસ્તુ જીવમાં પ્રધાન નથી એવા સંતના મુખેથી સાંભળેલી હરિકથા જીવના મોહનો નાશ કરે છે. રાત્રિદિવસ તેનું શ્રવણ કરી ધારવી, વિચારવી જોઈએ.","e":null,"s":["10/52/18-19"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1292,"k":"para","g":"એકાંતિક ભક્ત છે તે પોતાને જે ભગવાનનું સ્વરૂપ પ્રાપ્ત થયું હોય તેને જ સર્વોપરી માને છે.","e":null,"s":["11/17/40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1293,"k":"para","g":"અનંતકોટિ બ્રહ્માંડમાં જેને શ્રીહરિ સિવાય કોઈ અધિક ન હોય, શ્રીહરિના અક્ષરધામ સિવાયનાં અન્ય લોકના વૈભવમાત્રને મળ સમાન જાણે અને પોતે પણ દેહગુજરાન કાજે ગ્રહણ કરે તોપણ મળ તુલ્ય જાણતા થકા ગ્રહણ કરે, પિંડ-બ્રહ્માંડમાં ભૂલ્યે પણ સુખ ન દેખે - આવું વર્તન જીવમાં જેને હોય તે સત્પુરુષ કહેવાય. અને લોકને દેખાડવા વૈભવને અસત્ય કહે, પણ પોતે સત્ય માનીને દ્રવ્ય-વિત્તનું જતન કરતો હોય તે અસત્પુરુષ છે. તેનું જ્ઞાન દ્રવ્ય ભેળું કરવા માટેનું જાણવું.","e":null,"s":["11/31/18-21"],"sv":["हरि बिन अधिक न कहे केहा । अनंत ब्रह्मांड के वैभव तेहा ॥\n\n हरि के धाम विन वैभव जेता । मलवत देख सब जो तेता ॥\n\n मलवत जानि भोगवे जितना । सत्पुरुष जानना तितना ॥\n\n देह ब्रह्मांड लग कोउ मांहि । सुख न देखे भूले कबु तांहि ॥\n\n जीय में होवे वरतन ऐसो । सत्पुरुष सो कहावत तेसो ॥\n\n लोक कुं देखावन असत्य कहेवे । आपे द्रव्य वित्त ज्ञान कर लेवे ॥\n\n असत्पुरुष सो कहत हि ऐसे । द्रव्य हित ज्ञान जानना तेसे ॥"],"mt":false,"gl":null,"a":true},{"i":1294,"k":"para","g":"સંત અને અસંત જુદા જ છે, પરંતુ જે નર-નારીને મોક્ષનો ખપ નથી તે તો ઘરબારીને પણ સંત કહીને પૂજે છે. તે સાચા સંતને અને આવા ઘરબારીને સમાન દૃષ્ટિથી જુએ છે. જેને સમુદ્ર તરવાની ઇચ્છા નથી, તેને સાજી કે તૂટલી નાવની ચિંતા નથી, તેને બેઉ સરખી છે. વહાણનો ખપ ત્યારે જાગે જ્યારે બૂડવાનો ભય લાગે.","e":null,"s":["11/31/22-24"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1295,"k":"para","g":"સાચા સંત છે તે ભગવાન સિવાયનાં રૂપમાત્રને અત્યંત ઝેર સમાન માને છે. ભગવાન સિવાય બીજું વહાલું રાખતા નથી. વિષયમાં અતિ દુઃખ જુએ છે. રાત-દિવસ પંચવિષયનાં મૂળ ઉખાડવાની વાતો સમયે-સમયે કર્યા કરે છે. પંચવિષયનાં મૂળ પાતાળથી લઈ પ્રકૃતિપુરુષ સુધી વ્યાપેલાં છે, તેને ઉખેડવાનું કપરું કામ કરે છે. જ્યાં સુધી પ્રકૃતિ પુરુષથી પર (જે અક્ષરબ્રહ્મ છે તે રૂપે) વર્તે તેને પંચવિષય લોપી શકતા નથી. તેમની સઘળી ક્રિયા ભગવાનના સંબંધે કરીને પ્રકૃતિપુરુષથી પરની (ગુણાતીત) જાણવી. એકમાત્ર સંબંધ શ્રીહરિનો અને સત્સંગનો રાખે છે, એવા સંતમાં ગુરુ, સાધુ, હરિભક્ત - સઘળા આવી ગયા એમ સમજવું. એવા સંતની સેવા ‘આ મારો મોક્ષ અવશ્ય કરશે’ એવી મોક્ષમતિ રાખીને કરે તો તેની મતિ ક્યારેય દૂષિત ન થાય.","e":null,"s":["11/41/20-25"],"sv":["हरि विन रूप कहावत जितना । अति विष सम समझत तितना ॥\n\n ओर न रखे हरि विन केहा । विषय में देखत दुख अति एहा ॥\n\n रात दिन पंचविषय ताको । मूल उच्छेदत वेर वेर याको ॥\n\n पंचविषय के मूल हि जोउ । पाताल से प्रकृति लग हें सोउ ॥\n\n प्रकृति पर वरते ज्यां लगहि । पंचविषय न लोपे त्यां लग हि ॥\n\n हरि संबंध कर क्रिया जितनी । प्रकृति पर जानना तितनी ॥\n\n हरि सत्संग संबंध हे एका । जानत जाकुं परम विवेका ॥\n\n गुरु संत हरिजन हि जेता । यामें आई गये सब तेता ॥\n\n मोक्ष मति रखि सेवा करे याके । दूषित मति कबु होवे न ताके ॥"],"mt":false,"gl":null,"a":true},{"i":1296,"k":"para","g":"પૃથ્વી પર જ્યાં ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિએ ધર્મનો વંશ છે ત્યાં શ્રીહરિ પ્રગટ રહે છે. ધર્મવંશને (એકાંતિક ધર્મને) અક્ષરબ્રહ્મ સાથે અખંડ એકતા છે. શ્રીહરિનો મહાબળિયો સંકલ્પ છે તેથી એવો મત કોઈક ઠેકાણે રહેશે ને તે ગુરુમુખી હશે. જેમ આરુણિ, ઉપમન્યુ વેદ વગેરે ગુરુની સેવાથી મોટી પદવી પામ્યા હતા.","e":null,"s":["11/54/30-31"],"sv":["धर्मादिक हे वंश हि जेहि । तामें प्रगट रहत हें तेहि ॥\n\n धर्मवंश हि अक्षर जो ताकु । एकता अखंड वर्तत वाकु ॥\n\n ऐसे मत रहत कोउ ठोरा । हरि के संकल्प हे बड जोरा ॥\n\n आरुणि उपमन्यु वेद जोहि । गुरु सेव से बडे भये तोहि ॥"],"mt":false,"gl":null,"a":true},{"i":1297,"k":"para","g":"સત્પુરુષની સેવા છે તે અસત્પુરુષને ક્યારેય મળતી નથી. સત્પુરુષ ક્યારેય પૃથ્વી પરથી જતા નથી, એ વિચરતા હોય છે, પણ અસત્પુરુષને દેખ્યામાં આવતા નથી. સત્પુરુષ વિષે દ્વેષભાવે તે જેમ તેમ બોલે તોય સત્પુરુષ તેનો મોક્ષ કરે છે. આ સત્પુરુષનો ગુણ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1298,"k":"para","g":"અસત્પુરુષને તજી ન શકે ને તેની સેવા ભાવ સહિત કરે તો તે પાપે કરીને નરકમાં પડે છે. આ વાત તે એમ જ છે તેમાં જરા પણ જૂઠ નથી. જેમ પ્રગટ દેખ્યામાં આવે છે, તેમ અંતરનો જે વિચાર છે તે કહ્યો. અને એ વાત પણ એટલી જ સત્ય છે કે કરોડો કરોડો પાપ કર્યાં હોય છતાં તે એક જ વાર અતિભાવ લાવીને સત્પુરુષનું સેવન કરે તો સત્પુરુષ તેનો ઉદ્ધાર કરે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1299,"k":"para","g":"સત્પુરુષનું સેવન અગ્નિ કરતાં કરોડગણું પ્રતાપે યુક્ત છે. એ પાપીનાં પાપ તત્કાળ બાળે છે ને ઉદ્ધાર કરવામાં વાર લગાડતા નથી.","e":null,"s":["11/63/10-15"],"sv":["सत्पुरुष की सेवा जोउ । असत्पुरुष कुं मिलत न सोउ ॥\n\n सत्पुरुष भोमि विचरत जोहु । असत्पुरुष न देखत तोहु ॥\n\n सत्पुरुष पर द्वेष उर लाई । वारि वार स्मरण करे ताई ॥\n\n तो हुं मोक्ष फल ताकुं देवे । सत्पुरुष में गुन रहे एवे ॥\n\n असत्पुरुष कुं सेवे अति भावा । कोई दिन न लेवे अभावा ॥\n\n तोहु जावे सो नर्क में, जूठ न यामें लगार ।\n\n प्रगट देखे आत तेहि, अंतर जेहि विचार ॥\n\n कोटि कोटि करे पाप हि, सत्पुरुष एक वार ।\n\n सेवे अति भाव कर, ताको करे उद्धार ॥\n\n सत्पुरुष की सेव, अनल से कोटि प्रताप जुत ।\n\n करत सद्य ही एव, उधार करत नहि वार लगत ॥"],"mt":false,"gl":null,"a":true},{"i":1300,"k":"para","g":"સત ધર્મ, સત જ્ઞાન, સત વૈરાગ્ય ને સત ભક્તિ - અર્થાત્ એકાંતિક ધર્મ જે સ્થાનમાં વર્તતો હોય (પ્રગટ હોય) ત્યાં સુધી શ્રીહરિ સ્વયં ત્યાં (પ્રગટ) રહે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1301,"k":"verse","g":"‘સત ધર્મ સત ભક્તિ જો જેહા, સત વૈરાગ્ય સત જ્ઞાન તેહા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1302,"k":"verse","g":"જિહાં લગ વરતત જેહિ ઠોરા, તિહાં લગ હરિ રહત તેહિ કોરા.’","e":null,"s":["13/41/21"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1303,"k":"para","g":"મોટા પુરુષને જે દુઃખ દે છે તેના વંશનો ઉચ્છેદ થઈ જાય છે. તે મોટો હોય તો પદવી થકી પડી જાય છે ને દિન દિન પ્રત્યે ઘટી જાય છે. મોટા પુરુષના અપમાનનું ફળ તત્કાળ જાણ્યામાં આવતું નથી, પરંતુ ક્ષય થયો તે નિશ્ચે મરે તેમ અપમાન કરનાર જરૂર દુઃખી થાય છે. મોટા પુરુષનો જે સત્કાર કરે છે તે ચાંડાલથી પણ નીચ કેમ નથી! તે ભૂપનો ભૂપ બને છે. આમાં રંચ પણ મિથ્યા નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1304,"k":"para","g":"અનંત બ્રહ્માંડનાં નાડી-પ્રાણ સત્પુરુષના હાથમાં છે. તેમના જિવાડવાથી જીવો મોજ કરે છે. જેમ બાળક, રોગી અને ગાંડા માણસની અપરાધરૂપી ક્રિયાઓને મોટા માણસો માફ કરે છે, તેમ સત્પુરુષ જીવના દોષ સામું જોતા નથી. જીવના કરોડો ગુના માફ કરે એવી એમની મોટાઈ છે. સત્પુરુષનાં વચન અસત્પુરુષને સુદર્શન ચક્ર જેવાં છે. સત્પુરુષનું જેટલું અપમાન કરે, તેટલું અપમાન કરનારાનું માન ઘટી જાય છે. પછી તે ઇન્દ્ર, બ્રહ્માદિક જેવા પણ કેમ ન હોય!","e":null,"s":["14/65/18-26"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1305,"k":"para","g":"સત્પુરુષ અને સત્સંગનો મહિમા જેવો દેવતાઓ યથાર્થપણે જાણે છે તેવો મનુષ્ય કોઈ જાણતું નથી. સંતના સમાગમથી હરિભક્તો થોડો જાણે છે. કોઈ વેદ-પુરાણ ભણે તોપણ તેનો ભવરોગ સાચા સંતના જોગ વગર મટતો નથી.","e":null,"s":["14/85/37-40"],"sv":["सत्संग हि जो ताहि को, महिमा यथार्थ जोउ ।\n\n जानत भयेउ देव सब, एसो न जानत कोउ ॥\n\n हरिजन ते ते जानहि, संत के कर हि जोग ।\n\n पढ़त और वेदपुरान हि, मिटत न भवदुःख रोग ॥\n\n मिटत न भवदुःख रोग, साचे संत के जोग बिन ।\n\n संत के कर हि जोग, भव भटकन तब रहत नहि ॥\n\n सत्संग मोक्ष के द्वार, संत सो हरिजन जोउ ॥\n\n प्रसिद्ध रहेउ धार, कुमति कुं नाहि देख परत ॥"],"mt":false,"gl":null,"a":true},{"i":1306,"k":"para","g":"નિર્વાસનિક પુરુષ હોય તેને ભગવાન ગોલોક, વૈકુંઠ, આદિ ધામના અપાર ભોગ આપે તોપણ તે તેને અસાર માને છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1307,"k":"verse","g":"‘ગોલોક વૈકુંઠધામ કે, દેવત ભોગ અપાર,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1308,"k":"verse","g":"નિર્વાસનિક જન જીતને, માનત તેહિ અસાર.’","e":null,"s":["15/10/25"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1309,"k":"para","g":"મોટા સંતના પ્રતાપે પાપીજન તરત નિષ્પાપ થઈ જાય છે. જે કંઈ પ્રતાપ જણાય છે તે બધો ભગવાનનો છે એમ સાચા સંત સમજે છે. એ સંતમાં બીજાને અપાર પ્રતાપ જણાતો હોય, તે પ્રતાપને બુદ્ધિશાળી મનુષ્ય દેખે ત્યારે તેને આ પ્રતાપ સંતનો છે એમ સમજે છે, પણ તે ભગવાનનો પ્રતાપ છે તે સમજી શકતો નથી, પણ જે ખરેખરા સાચા સંત છે તે બધો પ્રતાપ ભગવાનનો માને છે. જે પોતાનામાં પ્રતાપ છે એમ માને તે અતિ મલિન સંત જાણવો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1310,"k":"para","g":"મૂઆને વચને કરીને જિવાડે, કેટલાક વાંઝિયાને પુત્ર આપે, એવો અપાર પ્રતાપ જણાવે તોપણ બધો પ્રતાપ શ્રીહરિનો છે એમ અપાર મહિમા ગાય એ સાચા સંતની સનાતન રીત છે. સમર્થ છતાં કોઈ વાતનો લેશ પણ ગર્વ કરે નહિ ને નાનામાં નાના સંતના દાસ મન, કર્મ, વચને થઈને રહે, આખા બ્રહ્માંડના મનુષ્યો માને, દેવતા માત્ર આવીને તેમનું ભાવથી પૂજન કરે તોપણ સાચા સંત છે તેને એ વાતનો ક્યારેય ગર્વ હોય નહીં, પોતે એવો ગર્વ કોઈને દેખાડે પણ નહીં. એવા સંત જે કંઈ મનમાં ધારે છે, સંકલ્પ કરે છે તે પૂર્ણ થયા વિના રહેતો નથી. એવા સંત કોઈના કળ્યામાં આવતા નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1311,"k":"para","g":"જે દંભી છે તેને આવા સંત ‘શિર ફર્યા’ લાગે છે. તે સાચા સંત ભેગો રહેતો હોય, ને જોતો હોય કે આ સંતનાં ચરણોમાં લોકો ભેટ-સામગ્રી ઉપરાઉપર ધરે છે. ભાવથી હાથી પર બેસારે છે. સવારી કાઢે છે - તોપણ તે (સાચા સંત) તેનાથી નિઃસ્પૃહ રહે છે. આવું જાણવા છતાં દંભી એમને ઓળખી શકે નહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1312,"k":"para","g":"ભક્તોનો ભાવ જોઈ સાચા સંત પ્રસન્ન થાય છે. એમને કોઈ સાથે દ્વેષભાવ નથી, એવો એમનો પ્રબળ ઠરાવ રહે છે. તે અહોનિશ પિંડ-બ્રહ્માંડથી પર વર્તે છે. તેઓ દુઃખ-સંતાપને તરી ગયા છે.","e":null,"s":["15/28/30-40"],"sv":["बडे संत के करी प्रतापा । तरत जन हो जात निष्पापा ॥\n\n साचे संत प्रताप हि जितना । भगवान के समझात तितना ॥\n\n प्रताप संत में होवे अपारा । हरि के देखे न बुद्धि हि वारा ॥\n\n आपमें प्रताप देखत जेते । मलिन संत अति जानना तेते ॥\n\n मुवेकुं वचन करि के जिवावे । केतेक जनकुं सुत देवावे ॥\n\n जो प्रताप आपमें देखावे । हरि के प्रताप मुख से गावे ॥\n\n सनातन संत की रीत हि एसा । गरव कोउ वात के न लेशा ॥\n\n अदने संत के दास रहावे । मन कर्म वचन एसे रखावे ॥\n\n सब ब्रह्मांड के जन जेता । देवता के कहावत तेता ॥\n\n पूजत आपकुं आई भावा । ताके गरव कबु न देखावा ॥\n\n एसे संत मन धारत जेसे । होये विन निश्चे रहत न तेसे ॥\n\n एसे संत कले नहि आते । दंभि कुं शिर नित फिरत लगाते ॥\n\n भेट सामग्रि कहावत जेती । उपर उपर यह धरत तेती ॥\n\n म्याना सुखपाल चारट लाई । गज तो रंग अच्छे जो ताई ॥\n\n बेठावत अति भाव कर, साचे संत हि जानि ।\n\n साचे संत रहे संग हि, पेचानत नहि प्रानि ॥\n\n साचे संत प्रसन्न होत हि, जन के देख हि भाव ।\n\n मन में खेद न पावहि, प्रबल रहे ठेराव ॥\n\n पिंड-ब्रह्मांड से पर, वरतन निशदिन रहेउ ।\n\n दुःख ताप गये तर, पिंड-ब्रह्मांड में दुःख रहे ॥\n\n हरि के जेते संत, एसी वात में प्रित जेहि ।\n\n समझ पाये बलवंत, ताप में देखात न, जरत तन ॥"],"mt":false,"gl":null,"a":true},{"i":1313,"k":"para","g":"સત્પુરુષમાં દિવ્યભાવ રાખી તેમના શરીરને પણ દિવ્ય જાણે, અને ભગવાનની પેઠે જ એવા સંતના ગુણોનું ગાન કરે તો એવા જનની જીભ અમૃત જેવી અને પૂજવા યોગ્ય છે.","e":null,"s":["15/43/33-34"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1314,"k":"para","g":"પ્રગટ ભગવાન મળે કે ભગવાનના સાક્ષાત્કારવાળા સંત મળે એ બન્ને અલૌકિક છે ને મોક્ષના દાતા છે. તેમના સ્વરૂપનું જ્ઞાન જેને થાય છે તેનું આવાગમન ટળે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1315,"k":"verse","g":"‘ભગવાન સંત પ્રગટ સાક્ષાતા, અલૌકિક મોક્ષ કે દાતા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1316,"k":"verse","g":"તાકે જ્ઞાન ભયે અબ જિનકું, આવાગમન છુટ ગયે તિનકું.’","e":null,"s":["18/29/5"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1317,"k":"para","g":"ભગવાનને મળેલા સાધુને જેટલા દુભાવે છે તેટલું તે પોતાનું બૂરું કરે છે અને તે પાપ વજ્ર સમાન છે. ભગવાનને મળેલા ને મળેલાને મળેલા એ બન્ને ભવસાગર તરવાના વહાણરૂપ છે, તેને જ દુભાવે પછી તેની કરેલી સેવા નિષ્ફળ જાય છે.","e":null,"s":["18/51/8-11"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1318,"k":"para","g":"સાચા સંત ભગવાનમાં જોડે છે. તેમનામાં જેટલો ભગવાનનો પ્રત્યક્ષ ભાવ તેટલો તેનો મોક્ષ થાય. પ્રત્યક્ષ ભાવની દૃઢતા વિના મોક્ષ થતો નથી. પરોક્ષ કરીને દેખે તેને તેવું ફળ થાય.","e":null,"s":["19/38(37)/22-23"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1319,"k":"para","g":"મનુષ્યનું અજ્ઞાનરૂપી આવરણ સંત હટાવે છે ત્યારે મહિમા સમજાય છે. સાચા સંતના યોગ વિના ભવસાગર કોઈ તરી શકતું નથી. તે કોટિ ઉપાય કરે તો પણ નિષ્ફળ જાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1320,"k":"verse","g":"‘સાચે સંત કે જોગ વિન હિ, ભવસાગર ન તરત હેં કિનહિ.’","e":null,"s":["20/19/29-32"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1321,"k":"para","g":"મુમુક્ષુના હૃદયમાં મોક્ષનો અંકર સત્પુરુષના સંગે કરીને જ પ્રગટ થાય છે. અસત્પુરુષ મળી જાય તો ઉદય થયેલો અંકુર પણ બળી જાય છે.","e":null,"s":["20/47/2-3"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1322,"k":"para","g":"અનંત બ્રહ્માંડના જીવમાત્રને જમાડવા કે દેવતાઓ, ઋષિઓને જીવનભર જમાડવા તે કરતાં પણ એક ભગવાનના સાચા સાધુતાવાળા સંતને જમાડવા તેનું ફળ અપાર ને અધિક છે. આ વાત બુદ્ધિથી સમજાતી નથી. જે શ્રદ્ધાથી નિષ્કપટ ભાવથી સત્સંગ કરે છે તેને સમજ્યામાં આવે છે. એવા ભક્તો તો એમ સમજે છે કે ભગવાનના સાધુ માટે જેટલું કંઈ બની આવે તેટલો પરમ લાભ છે ને સંત માટે ઉપયોગમાં ન આવે એ પદાર્થ ઘરમાં રહ્યો છે તે પણ શોક કરવા યોગ્ય છે.","e":null,"s":["22/44/21-24"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1323,"k":"para","g":"જસદણના રાજા ચેલાખાચરે શ્રીહરિને કહ્યું, “તમે અમારો હાથ ગ્રહ્યો છે એટલે અમારો ઉદ્ધાર તમારા હાથમાં છે.” ત્યારે શ્રીહરિ કહે, “તમારો ભાવ જેવો અમારામાં છે તેવો અમારા સાચા સંતમાં થાય તો એ ફળ મળે. સાચા સંત નારી અને ધનથી દૂર રહે છે, ને હૃદયમાં ભગવાનના સ્વરૂપનું જ્ઞાન તથા ધર્મ, ભક્તિ ને વૈરાગ્યથી યુક્ત છે. એવા સંત ચિંતામણિ ને કલ્પતરુ સમાન છે.”","e":null,"s":["24/67/24-26"],"sv":["तुमहि ग्रहेउ हाथ हमारा । उद्धार रहे अब हाथ तुमारा ॥\n\n नृप प्रति हरि तब बोले ताई । हममें जेसे भाव रहाई ॥\n\n साचे संतहि जितना, नारी हि धन से दूर ।\n\n धर्म, भक्ति, वैराग्य जुत, हरि के ज्ञान हि उर ॥\n\n चिन्तामनि कल्पतरु जो, ऐसे संत कहात ।\n\n ता पर जैसे भाव यह, तेसे फल सो पात ॥"],"mt":false,"gl":null,"a":true},{"i":1324,"k":"para","g":"સત્પુરુષના યોગ વિના જિતેન્દ્રિયપણું આવતું નથી ને ચ્હાયે તેવો પ્રવીણ હોય તોપણ તેને ભગવાનની ગમ પડતી નથી. ભગવાન, ભગવાનનું ધામ, ને ભગવાનના ભક્ત-આ ત્રણેની મોટપ સર્વોપરી છે. તેના જેવી કોઈની મોટપ નથી.","e":null,"s":["25/52/14, 17, 18"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1325,"k":"para","g":"હરિ-વિમુખ જન સત્પુરુષનાં વચનને પ્રમાણ ન કરે તેણે કરીને સત્પુરુષ મટી જતા નથી. અસત્પુરુષ ક્યારેય સત્પુરુષ થઈ શકે નહિ ને સત્પુરુષ મટીને ક્યારેય અસત્પુરુષ થાય નહિ. સત્પુરુષ ક્યારેય નીંદિત કર્મ કરતા નથી. અસત્પુરુષને નીંદિત કર્મ કરવામાં જ ઉત્સાહ રહે છે. તેના હૃદયમાં દયા તલભાર પણ હોતી નથી.","e":null,"s":["25/52/24-27"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1326,"k":"para","g":"ભગવાનના વચન મુજબ ચાલે તે સત્પુરુષ કહેવાય. સત્પુરુષ ત્યાગી પણ હોય ને ગૃહસ્થ પણ હોય. તે ક્યારેય ભગવાનના વચન વિરુદ્ધ પગ ન ભરે. અસત વાણી ન વદે. ભગવાનનું નાનું વચન પણ તે મોટું કરીને માને છે.","e":null,"s":["26/10/34-35"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1327,"k":"para","g":"સંતપણાની પિછાણ ન હોય તેને સંતની ગમ ક્યાંથી હોય? સંતના અપમાનથી ભગવાન દુખાય છે, તેની પણ તેને ગમ હોતી નથી. સંતનો અનાદર થતાં ભગવાનનો કોપ થાય છે. અપમાન સહન કરવું તે સંતનું ભૂષણ છે, પણ અપમાન કરનારનું તેથી બહુ ભૂંડું થાય છે.","e":null,"s":["26/62/22, 36-38"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1328,"k":"para","g":"સત્પુરુષની મરજી ઉલ્લંઘાય તેટલો તેમનો અપરાધ કહેવાય. જીવને તે દેખાતો નથી, એટલું અજ્ઞાનરૂપી અંધારું છે, પણ તેને મોટાપુરુષ ગણતા નથી. શરણે આવેલાનો ગુણ માને છે.","e":null,"s":["27/33/29-30"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1329,"k":"para","g":"ભગવાન અને સત્પુરુષના સંકલ્પમાં બળ રહ્યું છે. તેમનો પ્રત્યેક સંકલ્પ સિદ્ધ થાય જ છે. એમણે કરેલ કોઈ સંકલ્પ મિથ્યા થતો નથી. તેને મિથ્યા માનનાર ભવ ભટકણથી છૂટતો નથી.","e":null,"s":["28/54/7-9"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1330,"k":"para","g":"સત્પુરુષના યોગ વિના શુભ મતિ ઉદય થતી નથી તેથી દેવદુર્લભ આવું સુંદર મનુષ્ય તન અસત્પુરુષના સંગમાં ખોઈ બેસે છે.","e":null,"s":["28/110/13"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":16,"gu":"દેહભાવ","en":"Dehbhāv — Body-Consciousness","url":"https://www.anirdesh.com/pbp/index.php?page=chp_16","b":[{"i":1331,"k":"para","g":"વનવિચરણમાં સિદ્ધોને શ્રીહરિ કહે, “અંતર્દૃષ્ટિ કરીને જુઓ કે દેહમાં કઈ વસ્તુ સારી છે? મળ, મૂત્ર, રુધિર વગેરેથી ચમારના કુંડ જેવો મલિન દેહ છે. તેનું જતન કરવું એમાં ડહાપણ કેવું? આત્મા અજર-અમર છે, તેને પોતાનું રૂપ માનીને દેહથી પર થઈ નિત્ય આત્માભ્યાસ કરવો.”","e":null,"s":["2/38/11-15"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1332,"k":"para","g":"મેઘપુરમાં શ્રીહરિ કહે, “જીવનું સુખ અમૃતરૂપ છે અને દેહનું સુખ ઝેરરૂપ છે. દેહ ચિત્તને વિભ્રાન્ત કરાવે છે. તેનાથી બીતા રહેવું.”","e":null,"s":["3/34/42-43"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1333,"k":"para","g":"શ્રીનગરમાં શ્રીહરિએ કહ્યું, “અક્ષરધામનો મહામુક્ત હોય, પણ જો તે દેહભાવમાં વર્તે તો તેનું મુક્તપણું દેહદશામાં પલટાઈ જાય છે. દેહબુદ્ધિ એવી પ્રબળ હોય છે કે મુક્તપણાનું જોર તેની પાસે ટકી શકતું નથી. આ વાત યથાર્થપણે અમારા સિવાય ને અમારા દિવ્ય અક્ષરધામ (સાકાર, મૂર્તિમાન) સિવાય કોઈના જાણ્યામાં આવતી નથી. એટલે અમે તે પ્રકાશ કરતા નથી.”","e":null,"s":["4/109/20-23"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1334,"k":"para","g":"શ્રીહરિએ પોતાની સાથેના અનુચરોને કહ્યું કે, “અહીં ખાવાપીવાનું કાંઈ દુઃખ નથી, પણ જેને ઘેર જવાની ઇચ્છા હોય તે અહીંથી જ પાછા ફરજો. જેને ખરી ઇચ્છા હોય તે જ અમારી સાથે ચાલજો. જેને ઘરનાં માણસ પાછળ રડે કે ક્લેશ કરે તેવા હોય તે પાછા જાઓ. શરમાશો નહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1335,"k":"para","g":"“જીવમાં એવી અવળાઈ છે કે જે દુઃખનું મૂળ છે તેને સાચું માની જતન કરે છે. જેવી સગામાં મમતા છે, એવી સત્સંગમાં કરવી, જેથી મોક્ષનો સંદેહ ન રહે. તન-ધન-પુત્ર-પરિવાર – બધું મિથ્યા જાણીને, દેહભાવ ટાળીને સત્સંગની મમતા રાખી જે ભક્ત વર્તે છે તેને અક્ષરધામની મોજ મળે છે. તેની ગમે તે જાતિ હોય, પણ તેનો મોક્ષ નિશ્ચિત છે.”","e":null,"s":["5/6/31-47"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1336,"k":"para","g":"માંડવીમાં શ્રીહરિ કહે, “પાપમાત્રનું મૂળ દેહ છે, તેનું જતન કરે તો પ્રભુ ભૂલી જવાય છે અને વિષયમાં સુખ અધિક મનાય છે. વિષયસુખ માટે લોકો માથાં કપાવે છે અને નાક-કાન પણ કપાવે છે, પણ વિષયનો અભાવ થતો નથી. તપમાં રુચિ રાખે તો વિષયનો અભાવ થાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1337,"k":"para","g":"“ભગવાનની મૂર્તિ અંતરમાં ધારી દેહને કષ્ટ દે તો ભગવાન સહાય કરે છે. લોકોને દેખાડવા જપ-તપ કરે, તેનું ફળ મળતું નથી. આ સંતો તો ભગવાનને રીઝવવા માટે જ તપ કરે છે અને દેહને શત્રુ માનીને તેની સાથે વેર રાખે છે. જેથી તેમને ભીડામાં જેમ લઈએ તેમ રાજી થાય છે.”","e":null,"s":["5/36/27-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1338,"k":"para","g":"સાયલા પાસે જેઠસુર બ્રાહ્મણના ગામમાં શ્રીહરિ કહે, “ભગવાનનાં ચરિત્રોની સ્મૃતિ અને શ્રવણ કરવાથી દેહ અને જગત ભુલાઈ જાય છે. દેહમાં ને જગતમાં વર્તે ત્યાં સુધી દુઃખ અનંત પ્રકારનાં વળગે છે, કારણ કે તે દુઃખનું ધામ છે. તેમાં જે સુખ માને છે તે માર્ગ ભૂલ્યો છે.”","e":null,"s":["6/37/7-8"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1339,"k":"para","g":"જૂનાગઢમાં શ્રીહરિએ કહ્યું, “જે દેહનું સુખ ઇચ્છે છે કે એ માટે જતન કરે છે તે સદા દુઃખી રહે છે, પણ તેનો વિચાર તેને નથી. સંસારનાં સુખ સ્વપ્ન જેવાં છે. સ્વપ્નસુખનું જતન કરનારો બુદ્ધિશાળી કહેવાતો નથી. બુદ્ધિમાં જેવો પાસ લગાવો તેવો લાગે ને જીવની રુચિ પણ તેવી થઈ જાય. દેહ વધે તેમ એ બુદ્ધિ વધે. બુદ્ધિ અનંત પ્રકારની છે, પણ મોક્ષના કામમાં ન આવે તે બધી વ્યાવહારિક બુદ્ધિ કહી છે. આ દેહમાં જીવ ન હોય ને ઉપર વસ્ત્ર ન હોય તે મડદું કોઈ કામમાં આવતું નથી, તેમ વ્યાવહારિક બુદ્ધિ, શબ તુલ્ય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1340,"k":"para","g":"“પિંડ બ્રહ્માંડમાં ક્યાંય પણ આસક્તિ રહી તો તેને પશુબુદ્ધિ જાણવી, જ્યાં સુધી મોક્ષનો વિચાર નથી ઊપજ્યો, ત્યાં સુધી જીવપ્રાણીમાત્ર પાતાળથી પ્રકૃતિપુરુષ સુધી એક સમાન છે.”","e":null,"s":["6/79/27-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1341,"k":"para","g":"જેતલપુરના મહોલમાં શ્રીહરિ કહે, “કામ, ક્રોધ, લોભ, સ્વાદ અને માન તે પ્રાકૃત મતિવાળાને હેરાન કરે છે. તેનો જ્યારે પ્રવેશ થાય, ત્યારે મુક્ત જેવા પણ સૂધ ભૂલી જાય છે. શુક-સનકાદિકની પેઠે બ્રહ્મસ્થિતિ પામેલા હોય તે પણ પ્રાકૃત દેહનો સંબંધ હોય ત્યાં સુધી ઉન્મત્ત થઈને ફરે નહિ, પણ નિયમમાં જ વર્તે અને બ્રહ્મચર્ય રાખે જ.”","e":null,"s":["8/20(19)/31-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1342,"k":"para","g":"જેતલપુરમાં જીવેન્દ્ર નૃપને શ્રીહરિ કહે, “દેહ અને દેહનાં સંબંધી જીવથી અત્યંત વિજાતીય છે. મિથ્યા સ્વાર્થ માનીને પોતે અજ્ઞાનરૂપ થયો છે, તેથી દેહ મરે છે છતાં સ્નેહનો તાર તૂટતો નથી. આવો જ સ્નેહ જો સત્ય એવો જે આત્મા ને સત્ય એવા જે પરમાત્મા તેની સાથે કરે તો નિષ્પાપ થઈ જાય ને મુક્તિને પામે.”","e":null,"s":["8/21(20)/25-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1343,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ જીવેન્દ્ર અને મૂલેન્દ્ર પ્રત્યે કહ્યું, “પ્રકૃતિ-સ્વભાવ બધાનાં સરખાં હોતાં નથી. પ્રથમ તો તેને ઓળખવાં તે જ વિવેક છે. પ્રકૃતિ-સ્વભાવ ટાળવાનું મોટું સાધન સત્પુરુષમાં પ્રીતિ કરવી તે છે. સત્પુરુષમાં હેત-પ્રીત વિના પ્રકૃતિ ટાળવાની વાત કરે તો મૂળગો અસમાસ કરે છે. થોડી ઘણી પ્રીત હોય તો તે પણ ટળી જાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1344,"k":"para","g":"“બધાનાં પ્રકૃતિ-સ્વભાવ એક કરવાં તે સમર્થ વિના થાય નહિ. જેમ રાજા સમર્થ હોય તે નાનાં રજવાડાં જીતીને પોતાને તાબે કરી લે છે. શત્રુનો નાશ કરી નાખે છે, તેમ સમર્થ સંત (પરમ એકાંતિક સત્પુરુષ) જ્યારે મળે અને તેની સાથે હેત થાય ત્યારે જીવની સંપૂર્ણ અયોગ્ય પ્રકૃતિ ને સ્વભાવ છોડાવે છે. અને બોધ પણ એવો આપે છે કે અનંત વાતોમાં મોક્ષ એ સાર છે. મોક્ષરૂપી ફળનો જેને નક્કી લોભ હોય તે સંતની વાતને અંતરમાં દૃઢપણે ધારી લે છે. એવા જનને અયોગ્ય પ્રકૃતિ-સ્વભાવ લેશ પણ રહેતાં નથી.”","e":null,"s":["10/7/3-12"],"sv":["समर्थ संत मिलत हि जबहु । हित करि के जीय संग तबहु ॥\n\n अजोग्य प्रकृति स्वभाव हि जेसा । त्याग करावत बोध दे तेसा ॥\n\n अनंत वात से मोक्ष हि जेहु । ताको फल अपार हें तेहु ॥\n\n सो फल को लोभ नकि जाहि । अंतर में होवे दृढ करि ताहि ॥\n\n ताकुं प्रकृति स्वभाव हि, अजोग्य न रहे लगार ।\n\n लोभ करिके मोक्ष के, देखे में आत अपार ॥"],"mt":false,"gl":null,"a":false},{"i":1345,"k":"para","g":"ભુજમાં શ્રીહરિએ કહ્યું, “સત્સંગ જે દિવસથી થયો છે ત્યારથી હરિભક્તને દિવ્ય આકાર પ્રાપ્ત થયો છે, પણ દેહનો સંગ જ્યાં સુધી છે ત્યાં સુધી ભ્રાન્તિથી દેહની સત્યતા દેખાય છે. જેમ કે બળેલી દોરડી હોય તે સત્ય જેવી દેખાય, તેમ હરિ અને સત્સંગ અમાયિક છે, તેમાં માયિકપણું આવી શકે નહિ; એ જ રીતે જે શ્રીહરિને શરણે થયા છે તેને માયા લાગતી નથી અને બીજાનો તો તે પરાભવ કરે છે.”","e":null,"s":["10/34/13-17"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1346,"k":"para","g":"જૂનાગઢમાં શ્રીહરિએ વર્ણીને વેદઋષિની વાત કરી હતી. એ સઘળી વાર્તા મુક્તમુનિએ યાદ રાખીને ઉત્તમ નૃપને કહી, “દેહ અસત્ છે, અનાત્મા છે, અત્યંત અપવિત્ર છે. આત્મા વિના દેહના ગુણ જ નથી. દેહ લેશ પણ શુદ્ધ નથી. આ મલિન દેહમાં સાર વસ્તુ જીવ છે. જે આત્મા અને દેહને એક કરી માને છે તેને જ બીજાનો અવગુણ દેખાય છે. આત્મજ્ઞાન વગર સર્વે મનુષ્યો અંધ છે. કોઈ પોતાને આત્મારૂપ કહેવડાવતો હોય અને બીજાના અવગુણ લેતો હોય તો તે આત્મારૂપ નથી. જેમ સિંહે પેટ ભરવા સાધુનો વેશ ધર્યો હતો તેવો તેને જાણવો.”","e":null,"s":["11/56/13-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1347,"k":"para","g":"બોટાદમાં શ્રીહરિએ વાત કરતાં કહ્યું, “જીવ દેહ સાથે એક થઈ ગયો છે, તેથી પોતાના સ્વરૂપની ગમ નહિ રહેવાથી દેહના અને ધનના સુખે સુખ અને દુઃખે દુઃખ પામે છે. આવું જ સુખ-દુઃખ ભગવાન ને ભગવાનના સંતને માટે પામે તો મોક્ષમાં તેને કાંઈ બાકી રહ્યું નથી.”","e":null,"s":["11/81(71)/8-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1348,"k":"para","g":"ગઢપુરમાં સંત પોતાના આહાર પ્રમાણે જમ્યા. પછી શ્રીહરિ કહે, “તમે કાંઈ જમ્યા નહિ. હરિભક્તોએ બહુ ભાવથી અને શ્રમથી ભોજનો કર્યાં છે તે તમો બરાબર જમ્યા નહિ.” ત્યારે બ્રહ્માનંદ મુનિએ ગીતાનો શ્લોક બોલી યુક્ત આહાર વિહાર કરવાનું કહી સંભળાવ્યું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1349,"k":"para","g":"ત્યારે શ્રીહરિ કહે, “મારવું-જિવાડવું જેમના હાથમાં છે, એનો તમને જોગ થયો છે, છતાં પણ તમે દેહનો મમત્વ રાખો છો તે જ્ઞાની થઈને શોભે નહિ. અમે સંકલ્પ કર્યો છે કે તમે આજ સુધી જેવો ત્યાગ રાખ્યો છે તેથી અધિક સુખ તમને દેવાં છે. હવે ખપવાળા સંતો જ રહ્યા છે. ખપ વિનાના હોય તે જતન કરવા છતાં ચાલ્યા જાય છે અને ખપવાળા અપાર દુઃખ પડે તો પણ ટકે છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1350,"k":"para","g":"બ્રહ્મમુનિ કહે, “તમે મળ્યા તે બધાં દુઃખ મટી ગયાં છે. અક્ષરધામ જેવું સુખ બધાને આવે છે એ સત્સંગમાં પ્રગટ દેખાય છે. આ અવસરે મતિ ફરે ને ત્યજી જાય એ આશ્ચર્ય વાત કહેવાય.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1351,"k":"para","g":"શ્રીહરિ કહે, “જાય છે તેનામાં દિવ્યભાવની ખાધ રહી જાય છે. જેને દિવ્યભાવ રહે છે તે આ સત્સંગમાં ટકી રહે છે. માયિકભાવ, મનુષ્યભાવ આવે ત્યારે તેની મતિ વિપરીત થઈ જાય છે. માટે અલૌકિક, દિવ્યભાવ રહે એવો સત્સંગ કરવો તો જ તેનો પગ સત્સંગમાં ટકશે.”","e":null,"s":["15/59/5-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1352,"k":"para","g":"વડતાલમાં રાયણ નીચે સંતોને શ્રીહરિ કહે, “ભગવાનનું ધ્યાન કરવા બેસવું કે સભામાં જેટલી વાર બેસવું તેટલીવાર સંતોએ નાસિકાગ્ર વૃત્તિ રાખી બેસવું. માંખ-મચ્છર કરડે તો થડકવું નહિ. એવા સંત શૂરવીર હોય તે ઊભા થાઓ.” ત્યારે કૃષ્ણાનંદ મુનિ વગેરે ઊભા થયા. દેહમાં વર્તનારા તરત દેખાઈ આવતા. એમ સંતોને ફાવે તેમ વર્તાવે છતાં પાછો પગ ધરતા નહિ.”","e":null,"s":["17/10/5-11"],"sv":[],"mt":false,"gl":null,"a":false}]},{"n":17,"gu":"સંસાર","en":"Sansār — Worldly Life","url":"https://www.anirdesh.com/pbp/index.php?page=chp_17","b":[{"i":1353,"k":"para","g":"વનવિચરણમાં નીલકંઠ કહે, “સંસાર એવી બેડી છે કે જેથી ભગવાન ભજવામાં મહાન વિઘ્ન પડે છે. સંબંધીજનનું બંધન બહુ ભારે છે, તેને મરતા સુધી તોડવું બહુ કઠણ છે.”","e":null,"s":["2/6/6, 8"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1354,"k":"para","g":"શ્રીહરિએ પત્રમાં લખાવ્યું કે, “સત્સંગ નિમિત્તે કોઈ સત્સંગી સાથે વેર ન કરવું. સંસાર વ્યવહારમાં સંસારની રીતે વર્તવું. અંતરમાં વૈરાગ્ય હોય તોપણ ગૃહસ્થે પોતાની સ્ત્રીને તજવી નહિ. અને નારીએ પોતાના પતિને તજવો નહિ. પતિ પાપી હોય તો તેનો ત્યાગ કરવામાં દોષ નથી. સંસાર ત્યાગની અંતરમાં દૃઢતા ન હોય તેણે ત્યાગ પ્રકાશિત (જાહેર) ન કરવો. વિચાર્યા વિના ગૃહત્યાગ કરે તે અંતે પાર પડે નહીં. સારા સત્સંગનું હિત ઇચ્છે અને જેને લેશ પણ સ્વાર્થ ન હોય એવા પરમ પુનીત સંતના સંગમાં રહેવું. તે કહે તે ઉપદેશ ગ્રહણ કરવો. એવા સંત જે માર્ગ બતાવે તેમાં ક્લેશ હોતો નથી. અને જીવને શાંતિ થાય છે. એવા સંતમાં વિશ્વાસ કરવાથી મોક્ષ પ્રાપ્ત થાય છે. અને દિન દિન પ્રત્યે તેના સત્સંગનો રંગ તથા ઉમંગ વધતા ને વધતા રહે છે.”","e":null,"s":["3/30/43-48"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1355,"k":"para","g":"ઝીંઝાવદરમાં અલર્ક રાજાના નાનાભાઈ દેહ મૂકી ગયા, તેથી માતા માંગલબાઈ કલ્પાંત કરતાં હતાં. શ્રીહરિએ તેમને ઉપદેશ આપતાં કહ્યું, “આ જીવને કોઈ સગું-વહાલું નથી, માતા-પિતા, ભાઈ કે પુત્ર - બધો સંબંધ દેહનો છે. અને દેહ તો જીવાત્મા નીકળી જાય પછી અહીં જ પડ્યો રહે છે. જો પુત્રમાં સાચું હેત હોય તો જીવાત્મા નીકળી ગયા પછી તેને બાળી શા માટે દે છે! માટે એ સ્નેહ મિથ્યા છે, કારણ કે દેહ મિથ્યા છે. દેહ જો સત્ય હોય તો સ્વપ્નમાં ભોગ ભોગવ્યા પછી જાગ્રતમાં એ ભોગ સત્ય ઠરવા જોઈએ, પણ એકેય ભોગ ટકતો નથી. ભવ-બ્રહ્માદિ અનંત દેવતા છે, તે સર્વના ભોગ પણ સ્વપ્ન તુલ્ય છે. આત્માનું જ્ઞાન થાય તેને જ બુદ્ધિમાન કહ્યો છે. જ્ઞાનીને મતે અસત્ય કદી સત્ય ઠરતું નથી અને સત્ય કદી અસત્ય થતું નથી. જગત અને ભોગ અસત્ય છે, ભગવાન અને તેનું ધામ સત્ય છે. સત્સંગ કરીને જે જ્ઞાની થાય છે તેને કદી રોવાનું થતું નથી.”","e":null,"s":["4/22/13-19"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1356,"k":"para","g":"કુંડળમાં શ્રીહરિ કહે, “અમને બાળપણાથી જ સ્ત્રીનો ગંધ ગમતો નહિ. ગંધ આવે ત્યારે ઉદરમાં અન્ન ટકી શકતું નહિ. અમને સ્ત્રી જેવી અરુચિ આ જગતના કોઈ પદાર્થમાં નથી. તેમાંય રજસ્વલા દોષને નહિ ગણનારી સ્ત્રી તો નખશિખ અપવિત્ર રહે છે. જે એ ધર્મ પાળે છે તે હરિભક્ત સ્ત્રી શુદ્ધ કહેવાય છે.”","e":null,"s":["4/36/45-48"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1357,"k":"para","g":"કારિયાણીમાં શ્રીહરિએ નૃપને કહ્યું, “જીવ અનંત રુચિ ધરાવે છે, પણ ભગવાન ભજવાની રુચિ કરતો નથી તેથી સંસારમાં વારંવાર ભટકે છે.”","e":null,"s":["5/71/28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1358,"k":"para","g":"શ્રીહરિએ ભડલીમાં વાત કરતાં કહ્યું, “અમૂલ્ય મનુષ્યદેહ પામી તેમાં ભૂલા ન પડવું. મનુષ્યદેહ દિવસ જેવો છે. અન્ય યોનિના દેહ અંધારી રાત્રિ જેવા છે. દિવસે ન સૂઝે ને ભૂલો પડે પછી રાત્રિએ પગ જ ક્યાં મૂકશે! મનુષ્યદેહ છૂટ્યો તો સંસારરૂપી કૂપમાં પડ્યો જ સમજવો. પછી ઊગર્યાનો કોઈ ઉપાય નથી. અનંત દેહના પાપનો ભાર ઉતારવા મનુષ્યદેહ મળ્યો, તેમાં પણ જો પાપ કરે તો છૂટવાનો ઉપાય ક્યાં રહ્યો? જેને સંત મળે છે તે સંસારરૂપી કૂવાને ઓળખે છે. સંત તેને જ્ઞાન આપે છે, ને તારી લે છે. પૂર્વે મોટા મોટા રાજાઓ પણ સંત મળતાં સંસાર તરી ગયા છે.”","e":null,"s":["6/1/37-42"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1359,"k":"para","g":"શ્રીહરિ સાથે વિચરતાં સુરાખાચર કહે, “મહારાજ! અમારાં ધન્ય ભાગ્ય છે કે તમે મળ્યા અને તમારામાં હેત થયું, હવે સગા-પરિવારનો સંસારી સંબંધ નીરસ થઈ ગયો છે. એ ભોગમાત્ર ઝેર જેવા લાગે છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1360,"k":"para","g":"શ્રીહરિ કહે, “ઘરે જાઓ. પછી આ વાતની ખાતરી થશે. આવો ને આવો વિચાર છ મહિના સુધી ચાલુ રહે અને સંસારમાં વૃત્તિ ઉદાસ રહ્યા કરે, પછી અમારી પાસે આવજો. વૃત્તિ ઠર્યા વિના જ્ઞાન સ્રવી જાય છે. વૃક્ષને મૂળમાંથી કાપ્યું હોય, પણ મૂળ ચોંટી રહ્યું હોય અને મેઘનો જોગ થાય તો લીલું થઈ જાય છે. સંબંધીનું હેત તો વડ, પીપર ને થોરના ઝાડ જેવું છે. જીવને સ્વપ્ન આવે છે તે ઉપરથી સંસારમાં ભાવ કે અભાવ છે એનો ખ્યાલ આવે છે.”","e":null,"s":["6/54/26-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1361,"k":"para","g":"શ્રીનગરમાં શ્રીહરિ કહે, “સંસારનો સંગ રાખે તેને ફરી ફરી સંસારમાં આવવું પડે છે. નિત્ય સત્સંગ કરે તો સંસારનો સંગ નિવૃત્ત થાય. સંસારનો ત્યાગ કરી એકાંતમાં બેસી હરિપદમાં પ્રીતિ કરે તો અનંત દુઃખથી છૂટે છે.”","e":null,"s":["8/3/41-42"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1362,"k":"para","g":"નડિયાદમાં ગંગારામ વિપ્રને ઘરે થાળ જમીને શ્રીહરિએ વાત કરતાં કહ્યું, “ચિત્તનો સ્વભાવ સ્વચ્છ દર્પણ જેવો છે, જે સંકલ્પ થાય તે દેખાય. આખું બ્રહ્માંડ ચિત્તમાં ભરેલું છે. ચિંતવન કરતાં તરત જ આવીને ઊભું રહે છે. તેને અસાર જાણે તો આવરણ કરે નહિ. સંકલ્પનો પ્રવાહ ચાલુ છે ત્યાં સુધી સંકલ્પ પ્રમાણે તે દેખાય છે. સંકલ્પનો પ્રવાહ તૂટતાં ચિત્તમાં કંઈ પણ આવતું નથી. સંકલ્પ અને ચિત્ત વિના મૂર્તિ પણ દેખાય નહિ. સાર અસારને જાણવામાં ચિત્ત અને સંકલ્પ ઉપયોગી છે. પંચ જ્ઞાનેન્દ્રિયો જીવને અમૃત અને ઝેર બેઉ દેખાડે છે. વિષયો ઝેર છે, સત્સંગ અમૃત છે. જેને સદ્‌ગુરુ મળે છે તે ઝેર ત્યજી દે છે ને અમૃતપાન કરે છે.”","e":null,"s":["8/32/34-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1363,"k":"para","g":"ભૂજમાં શ્રીહરિએ વાત કરતાં કહ્યું, “ગ્રામ્યવાર્તા કહેવી સાંભળવી તે સત્સંગ ન કહેવાય. ગ્રામ્યવાત ઉપર જીવને અનાદિથી ભાવ છે, તે જ જન્મમરણનું બીજ છે.”","e":null,"s":["10/36/16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1364,"k":"para","g":"મોડા ગામમાં શ્રીહરિ કહે, “પાતાળથી બ્રહ્મલોક પર્યંત સૌ કાળને વશ છે. કોઈનું બળ ત્યાં ચાલતું નથી. ભરતખંડમાં મનુષ્યતન પામી જેવું કાર્ય કરે તેવું ભાથું બંધાય છે અને ચોરાશી જમપુરીમાં તે ગોથાં ખાય છે.”","e":null,"s":["11/12/16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1365,"k":"para","g":"જૂનાગઢમાં મૂળજી શેઠને ઉદ્દેશીને શ્રીહરિ કહે, “નારી અને ધન જેની પાસે હોય તેનો કોઈને વિશ્વાસ ન આવે. જે જન પારકી નારી ને પારકું ધન રાખે છે તેની મતિમાં ફેરફાર થયા વિના રહેતો નથી. દારૂ જેવો તેનો ગુણ છે. ધન-નારીની પ્રાપ્તિ માટે લોકો લાજ તજે છે અને વૈર કરે છે. ભગવાનને ભજનારા ભક્તોને તે વિઘ્નરૂપ છે. કામ અને લોભ સમાન કોઈ શત્રુ નથી, એમ જાણીને સંતોને સંસારનાં આ વિઘ્નોથી દૂર રાખ્યા છે.”","e":null,"s":["11/54/6-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1366,"k":"para","g":"બોટાદમાં શ્રીહરિએ હરિજનોને વાત કરતાં કહ્યું, “કુટુંબ જેવું હેત સત્સંગમાં હોય તો ડગાય નહિ. જગતમાં સ્ત્રી અને પુરુષ એક ઘરનાં હોતાં નથી, છતાં સ્ત્રી ઘરમાં આવે છે ત્યારે તે સૌથી અધિક થઈ જાય છે અને ભિન્ન ભિન્ન દેહ હોવા છતાં તેની સાથે મન એક થઈ જાય છે. માતા-પિતાના પ્રતાપે કરીને દેહ મળ્યો, ઘર મળ્યું, વસ્ત્રાભૂષણ મળ્યાં; ગામ, ગરાસ, ભૂમિ, દુકાન, ઘોડા, વાહન, બળદ, ગાય, ભેંસ એ બધું મળ્યું. તેમના પ્રતાપથી જ આ બધું છે છતાં પુત્ર સ્ત્રી પરણીને ઘરમાં લાવે છે ત્યારે એ નારી બધો પ્રતાપ હરી લે છે. માતા-પિતા, ભાઈ-ભગિનીના સંબંધ કરતાં પણ પત્નીનો જ સંબંધ મુખ્ય થઈ જાય છે. સંસારની આ રીત પરંપરાથી ચાલતી આવે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1367,"k":"para","g":"“પશુ-પંખીની પણ એવી જ રીત છે કે જ્યાં બંધાય ત્યાં જ પ્રીતિ કરે. નારીના સંબંધથી જન્મ-મરણ અને જમપુરીનાં અપાર દુઃખ વારે વારે આવે છે, અને આ લોકમાં પણ અપાર દુઃખ ભોગવે છે, છતાં મોહ છૂટતો નથી. તેવો સંબંધ સત્સંગમાં બંધાય તો સંત-હરિભક્તોનાં કડવાં વચનનો ડાઘ અંતરમાં પડે નહિ.”","e":null,"s":["11/82(72)/1-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1368,"k":"para","g":"મુક્તમુનિએ શ્રીહરિએ કહેલી વાતો ગઢપુરમાં કહી, “શ્રીહરિ કહેતા કે - ખર-દૂષણની બહેન શૂર્પણખા રામચંદ્રને વરવા આવી. રામચંદ્રજીને એકપત્ની વ્રત હોવાથી તેને નહિ બોલાવતાં તે લક્ષ્મણ પાસે ગઈ અને નાક-કાન ખોયાં. ખર-દૂષણ પાસે જઈ આ વાત કરી. તેથી સૈન્ય સાથે તેઓ રામને મારવા આવ્યા. રામે તે સર્વેનો નાશ કર્યો. શૂર્પણખા રાવણ પાસે ગઈ ત્યારે રાવણે મારીચ દૈત્યને માયાવી મૃગનું રૂપ લઈ સીતા પાસેથી નીકળવાનું કહ્યું. તે મૃગને જોતાંવેંત સીતાએ રામને તે લાવી આપવા કહ્યું, ત્યારે રામ કહે, ‘આ તારા કામનું નથી.’ સીતા કહે, ‘ક્ષત્રિય થઈને તમે મૃગથી બીઓ છો?’","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1369,"k":"para","g":"“ત્યારે રામ કહે, ‘સ્ત્રીની તુચ્છ મતિ હોય છે. સ્ત્રીઓને વિષે શ્રેષ્ઠ સમજીને અમે સીતાજીને વર્યા. અમને ભગવાન જાણે છે છતાં દોષદૃષ્ટિ રાખી તે સ્ત્રીના શરીરનો સ્વભાવ છે. સ્ત્રીને વશ જે પુરુષ વર્તે છે તે દુઃખી થાય છે. અમારા પિતાને પણ તે પ્રમાણે થયું હતું.’","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1370,"k":"para","g":"“એમ કહી રામ ગયા ને પાછળથી સાધુ વેશે રાવણ આવ્યો ને સીતાને લંકામાં ઉપાડી ગયો. લક્ષ્મણે રક્ષાની રેખા દોરેલી ને કહેલું કે આને ઓળંગશો નહિ. તોપણ સીતાએ તેનું ઉલ્લંઘન કર્યું. માતાના મુખ સામે દૃષ્ટિ કરીને લક્ષ્મણે કદી જોયું નહોતું, તેને સીતાએ કડવાં વેણ કહ્યાં કે રામ મરે ને હું તને વરું એવું મનમાં હોય તો તું ભૂલે છે. જીભ કરડીને મરીશ પણ તને નહિ વરું - ન છૂટકે લક્ષ્મણ રામની વહારે ગયા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1371,"k":"para","g":"“ત્યારે રામે કહ્યું, ‘લક્ષ્મણ, તને બુદ્ધિ નથી, સીતાને છોડીને કેમ આવ્યો?’ એમ કહી આશ્રમે આવ્યા ત્યારે સીતાને દીઠાં નહિ. તેથી રામ, સીતાના વિયોગે ઉન્મત્ત જેવા થઈ ગયા, અને મનુષ્યથી પણ અતિ પ્રાકૃત ચરિત્ર કરવા લાગ્યા. વાલ્મીકિએ આ બધું લખ્યું છે.”","e":null,"s":["11/86-87 [77-78]"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1372,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ વાત કરતાં કહ્યું, “મોક્ષના માર્ગે ચાલવામાં પરિવાર વિઘ્ન કરે છે. તેથી સત્સંગને અમે કુટુંબ-પરિવાર માન્યો છે. સત્સંગથી બીજું કાંઈ અધિક જાણતા નથી, દેહના કુટુંબને વિસારી દીધું છે. જ્યારથી અમે કુટુંબનો ત્યાગ કર્યો છે તે દિવસથી આજ પર્યંત કોઈ દિવસ તે સ્વપ્નમાં યાદ કર્યું નથી. અમને વહાલા સંતો-ભક્તો છે તે સ્વપ્નમાં અખંડ દેખાયા કરે છે. અમારું અક્ષરધામ અને અહીંના સંતો-હરિભક્તો તે એકરૂપ દેખાય છે.”","e":null,"s":["12/66/5-8"],"sv":["सत्संग माने कुटुंब परिवारा । देह के कुटुंब दिये विसारा ॥\n\n कुटुंब को त्याग किये जा दिन से । सुपने में न आये ता दिन से ॥\n\n संत हरिजन कहावत जेता । सुपने में अखंड देखत तेता ॥\n\n अक्षरधाम संत हरिजन जेहु । एक हि देखत इहां के तेहु ॥"],"mt":false,"gl":null,"a":false},{"i":1373,"k":"para","g":"ગઢપુરમાં અભય નૃપના દરબારમાં શ્રીહરિ કહે, “અમારે આશ્રિત સ્ત્રીઓએ ગૃહત્યાગ ન કરવો, પતિનો ત્યાગ કર્યા વિના ધર્મનું પાલન કરવું, ત્યાગધર્મ પાળવો સ્ત્રીને માટે અતિ કઠિન છે. પ્રથમ સંસાર ત્યાગ કરે પછી ફરી વળી સંસાર કરે એવી સ્ત્રીઓ જગતમાં ઘણી છે. ધણી વગરની નારીની હાંસી થાય છે. આજ ઘોર કળિકાળમાં ગૃહત્યાગ કરીને સ્ત્રીએ રહેવું નહિ. સ્ત્રી ત્યાગી હોઈ શકે જ નહિ, માટે નવી રીત આચરવી નહિ. આ અમે તમને સત્ય વાત કહી છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1374,"k":"verse","g":"‘કલિકાલ હેં આજ હિ ઘોરા, ત્યાગી નહિ હેં બાયું કોઉ ઠોરા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1375,"k":"verse","g":"નઈ રીત નહિ કરના તુમ હી, સત્ય કહત હેં તુમકું હમ હી.’","e":null,"s":["13/54/9-11"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1376,"k":"para","g":"ધરમપુરમાં શ્રીહરિએ ભીલોના આગેવાન રાજાને વાત કરતાં કહ્યું, “રાજ, નારી, ધન એ કાજલનો કોટ છે. ત્યાગીને તો તે મોટું વિઘ્ન છે. સત્તા લીલાગર ભાંગ જેવી છે. એ જેમ મળે તેમ વધુ કેફ ચઢે. રાજસત્તા એ ત્યાગીને મોટું બંધન છે. સંસારમાં સુખ માને છે એ તુચ્છ અને પ્રાકૃતમતિ છે. અહીંનું સુખ પલકારામાં નાશ પામે છે. આ સુખ જેને દુઃખ મનાય છે તેને અપ્રાકૃતમતિ થઈ જાણવી. એવો જન અપાર સુખને પામે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1377,"k":"para","g":"“સંસારીજનોને સંસાર ઉપર દોડ રહે છે. ધન, નારી અને પુત્રમાં સંસાર મુખ્ય છે. ગામ, ગરાસ અને ધન બધું પુત્ર અને સ્ત્રી માટે માને છે, પણ શરીર જાય ત્યારે કશું રહેવાનું નથી. એમ પ્રત્યક્ષ દેખે છે, છતાં ભૂલી જાય છે.”","e":null,"s":["16/30/1-20"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1378,"k":"para","g":"ગઢડા આવતાં શ્રીહરિએ રસ્તામાં વાત કરી, “જગતમાં ગમે તેવી કીર્તિ હોય, પણ મર્યા પછી કોઈ જાણતું નથી. કીર્તિ માટે ઠેર ઠેર રૂપિયા વેરે છે, પણ પરલોકમાં કંઈ કામ લાગતી નથી, પરલોકમાં કામ આવે તેવો ઉદ્યમ કરે તે બુદ્ધિશાળી છે.”","e":null,"s":["17/43/17-20"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1379,"k":"para","g":"ભરૂચમાં તુઈરામે કરેલી ગાડા-બળદની ટાણાની સેવા શ્રીહરિએ વખાણી અને કહ્યું, “તમને ધનનો મદ ચઢ્યો નથી. જેને ધનમાં મોટાઈ મનાણી છે, તેને ભગવાન ભજવામાં મોટાઈ મનાતી નથી. ધન-નારીરૂપી આવરણમાં સૌ કોઈ બંધાયા છે. કદાચ બ્રહ્માંડનો અધિપતિ હોય ને જો સ્ત્રી-ધનમાં સુખ ન માને તો તે ભગવાનની માયાને તરી ગયો છે. સમજણ વગર તેનું બધું જ્ઞાન બૂરું કરનારું નીવડે છે. જો સાચા સંતનો યોગ થાય ને તેની સેવા કરે તો ભગવાનનું જ્ઞાન થાય ને જીવ ભવસાગર ઊતરે.”","e":null,"s":["27/101/6-11"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1380,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1381,"k":"para","g":"ગૃહસ્થને ઘરમાં રહ્યાનું એટલું જ ફળ છે જેટલી ભગવાન અને ભગવાનના સંતની સેવા બની આવે. જેના ઘરમાં સંતનાં પગલાં થતાં નથી, ને હરિકથા અને કીર્તન થતાં નથી, તેને ત્યાં જમનો નિવાસ થાય છે. અને એવા ઘરને સ્મશાન તુલ્ય કહ્યું છે. સંત મળે છે ત્યારે સંસારની, દેહની આસક્તિ મુકાવે છે. ભગવાનમાં આસક્તિ કરાવે છે, આ સંતનો ગુણ છે. જે સંત ભગવાનમાં પ્રીતિ ન કરાવે ને ગ્રામ્યવાર્તામાં ચિત્ત દેતા હોય, તેવા સંતને સેવવા નહિ. શ્રીહરિમાં જોડે એવા સંતને ઓળખવા.","e":null,"s":["6/43/22-25"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1382,"k":"para","g":"દેહ અને દેહના સંબંધી કેટલું દુઃખ દે છે, તોપણ સંસારી લોકો સુખ માની તેના ગુલામ થઈને રહે છે. સંસારમાં સાર નથી, પણ તેમાં વિચાર વિના સાર દેખાય છે. શુદ્ધ વિચાર પ્રાપ્ત થાય છે ત્યારે ભગવાનમાં પ્રીતિ થાય છે.","e":null,"s":["6/54/19, 24"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1383,"k":"para","g":"સંસારની ગ્રંથિ અનંતકાળે પણ છેદાય નહિ એવી છે. બ્રહ્મલોક પર્યંત તે સંસારગ્રંથિ વજ્ર સમાન છે. કાળ પ્રકૃતિપુરુષ સુધી બધા લોકનો કોળિયો કરી જાય છે એવો અતિ બળવાન છે, પરંતુ સંસાર ગ્રંથિ તેનાથી પણ નષ્ટ થતી નથી, એવી વજ્રસાર ગ્રંથિ સંતની વાત સાંભળવાથી તત્કાળ નાશ પામે છે. સત્સંગનો આવો પ્રતાપ જોઈ બ્રહ્માદિ દેવો પણ આશ્ચર્ય પામે છે.","e":null,"s":["8/36/9-11"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1384,"k":"para","g":"શ્રીહરિના શરણમાં અનેકને અમાયિક સુખ મળે છે. બ્રહ્માંડના સુખથી ઉદાસી હોય એવા સાચા સંતનો યોગ બની આવે તો જીવને જગતની અરુચિ થાય.","e":null,"s":["10/26/28-30"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1385,"k":"para","g":"બ્રહ્મા જેવો પ્રવીણ હોય તેને પણ સત્પુરુષનો સંગ ન હોય તો સંસારનું બંધન ઓળખાતું નથી, તો સામાન્ય નરનું શું ગજું? ભવબંધન ઓળખાય નહિ ત્યાં સુધી જન્મમરણ થયા કરે છે. સ્થાવર-જંગમ બધી યોનિઓમાં ફરતો રહે છે. તે કોટિ કલ્પ સુધી પાર આવતો નથી. જીવમાત્ર સત્સંગ વગર આ બંધનમાં ફસાયા છે.","e":null,"s":["15/42/16-18"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":18,"gu":"અસત્પુરુષ, અસાધુ","en":"Asatpurush, Asādhu — The Unholy","url":"https://www.anirdesh.com/pbp/index.php?page=chp_18","b":[{"i":1386,"k":"para","g":"ઈંગોરાળામાં શ્રીહરિ કહે, “અમારી આજ્ઞા પાળે નહિ અને મનમુખી થઈને ધર્મનું અપાર પાલન કરે, ખાનપાનનો ત્યાગ કરે, લોકમાં મહાવૈરાગ્ય દેખાડે, ફાટેલાં-તૂટેલાં વસ્ત્ર પહેરે, મુખમાં મારું નામ ઉચ્ચારે અને મને સંભારીને ખૂબ મારો મહિમા કહે અને રડે, સત્સંગ અને સંતનો મહિમા પણ વારંવાર અપાર કહે, પોતાનું તન સૂકવી નાખે, અહોનિશ અમારું રટણ કરે, ધ્યાન ધરે, આંખોની પાંપણો પણ મટકાવે નહિ! કથા કરે, કાવ્ય કરે, સારાં ગુણગાન ગાય, એવું અનેક પ્રકારનું વર્તન કરે, તે જોઈ ભૂલા ન પડવું, કારણ કે તે મારી આજ્ઞામાં વર્તતો નથી ને મનમુખી વર્તન કરે છે એટલે તે મારાથી વિમુખ છે, અંત સમે તેને લેવા માટે અમે આવતા નથી.”","e":null,"s":["4/18/42-46"],"sv":["संत से विरुद्ध वर्तन जाका । काव्य कीर्तन करे में पाका ॥\n\n अहोनिश ध्यान करे मेरा । पलक न पारहि नेत्र हि केरा ॥\n\n सो सब मोंसे विमुख कहावे । अंत समे तेहि हम नहिं आवे ॥"],"mt":false,"gl":null,"a":false},{"i":1387,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ જીવેન્દ્ર નૃપને વાત કરતાં કહ્યું, “અસત્પુરુષને અસુર જાણવો. જેને સત્સંગ થયો છે તેને જ અસુર ઓળખાય છે. અવતારોનું મૂર્તિઓનું ખંડન કરે, સત્પુરુષનો દ્રોહ કરે તે અસુર છે. હરિજનને વિષભરી દૃષ્ટિથી જુએ, સંત-હરિભક્તમાં અનંત દોષ પરઠે, તેને જોઈને રાત-દિવસ બળ્યા કરે, તે પણ અસુરની જાતિ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1388,"k":"para","g":"“ભક્ત પાસે હાથ જોડી નમાય નહિ, મુખ મરડે, કસાઈ તુલ્ય પાપી જીવોના ગુણ ગાય, હરિવિમુખને હરિજનથી અધિક બુદ્ધિવાન કહી તેનાં વખાણ કરે, જગતના ફેલફિતૂરમાં આનંદ માને, હરિજન સાથે કુસંપ કરે - આવાં લક્ષણવાળા પાપીને અધર્મી જાણવા. દૈત્ય રાક્ષસ, અસુર ને નિર્દય કસાઈ જાણવા.”","e":null,"s":["4/11/22-29"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1389,"k":"para","g":"ચૂડાપુરમાં થાળ જમ્યા પછી શ્રીહરિ સંતો-ભક્તોને કહે, “સત્ય ક્યારેય અસત્ય થતું નથી, અસત્ય ક્યારેય સત્ય ઠરતું નથી. આમ વિચારી અમારા સત્સંગી હરિભક્તોએ ગાફલપણે ધર્મહીન લોકોની જાળમાં ફસાવું નહિ. દૃઢ નિષ્ઠાવાળા ભક્તોને ઘસારો લાગતો નથી.”","e":null,"s":["4/74/26-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1390,"k":"para","g":"માંડવીના પુરજનોને શ્રીહરિએ વાત કરતાં કહ્યું, “શુદ્ધ વર્તન વિના મોક્ષ આપવાની વાત કરતો હોય તેને અસુર જાણવો. શાસ્ત્રો ભણીને અનંત જન્મ ખુવાર કરે, પણ શુદ્ધ વર્તન વિના મોક્ષ ન થાય. શુદ્ધ ગુરુ મળ્યા વિના શુદ્ધ વર્તન થતું નથી.”","e":null,"s":["5/33/17-18"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1391,"k":"para","g":"કાળાતળાવમાં શ્રીહરિ કહે, “સંત-હરિજનનું રૂપ ધરી સત્સંગમાં આસુરી જન ફરતા હોય તેનાથી ડરતા રહેવું. અમે સત્સંગના નિયમ બાંધ્યા છે, તેને તોડીને જે વર્તે તેને અસુર જાણવો. કોઈ સંત-હરિભક્ત બ્રહ્મવેત્તા કે સમાધિનિષ્ઠ હોય, પણ નિયમ અને નિશ્ચય વિનાનો હોય તો તેને અસુર અને વિમુખ જાણવો. નિયમ અને નિશ્ચય ઉપરથી જેવું અંતર હોય તેવું જણાય છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1392,"k":"verse","g":"‘નિયમ નિશ્ચે મેં ન દંભ રહોવે, જેસો અંતર તેસો કલાવે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1393,"k":"verse","g":"તેહિ કારન હમ બાંધે નિમા, સબકે મોક્ષ કરન હિત સીમા.’","e":null,"s":["5/42/22-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1394,"k":"para","g":"ભદ્રેશીમાં સુરચંદ શેઠને ઘરે શ્રીહરિએ વાત કરતાં કહ્યું, “સંત-અસંતના ગુણ સમાન નથી. જેમ બગલો અને હંસ સમાન નથી. ચારામાં તેનો વિવેક જણાઈ આવે છે. હંસ મોતી અને પયનો ચારો કરે છે. બગલો માછલાં ખાય છે. જે સાધુ ધન રાખે, સ્ત્રીનો પ્રસંગ રાખે, લસણ-ડુંગળી ખાય, ગાંજો, ધંતૂર, માજમ, અફીણ, દારૂ, માંસ, સ્ત્રી વગેરેનું સેવન કરતા હોય તેવાને જે ગુરુ કરે તેનો શી રીતે મોક્ષ થાય? તેની કોઈ તપાસ કરતું નથી. જેવો ગુરુનો મોક્ષ થાય તેવો શિષ્યનો થાય. સંત થઈને ધર્મ ન રાખે તે ઘોર નરકમાં પડે છે. સાધુ થઈને ધન-સ્ત્રીનો સંગ રાખે તે અતિ પાતકી છે. પાપ કરે તેને પાતકી કહેવાય, તેને સંત કેવી રીતે કહેવાય? સંતને માર્ગે ચાલે તો સંત કહેવાય. સંત જીવનો મોક્ષ કરે, અસંત તો દુઃખ જ આપે. અસંતને પાપરત દેખીને લોક સાચા સંતને પૂજે છે.”","e":null,"s":["6/29/31-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1395,"k":"para","g":"ભુજમાં શ્રીહરિ હરિજનોને કહેવા લાગ્યા, “ધર્મનો એવો પ્રતાપ છે કે જે જન જેવો હોય તેને તેવો દેખાડી દે છે. સત્સંગમાં કપટથી ચાલી ધર્મની નકલ કરે ત્યારે અધર્મને લાગ મળે છે. તે તેને કુસંગમાં મોટેરો બનાવી નાક-કાન કપાવે. પછી જગતમાં નકટો થઈને ફરે, જગત તેને જાણે છે, પણ એકબીજાની મહોબતે કહી બતાવે નહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1396,"k":"para","g":"“અધર્મીને બધી કળા આવડે છે. અધર્મી સત્સંગી થઈને બધાથી સરળ વર્તે, અમારાં વચનને તલ તલ જેટલાં યાદ રાખે અને કહી બતાવે, જેથી હરિભક્તને સાંભળીને ચિત્તમાં મોહ થાય ને તેને કોઈ કળી શકે નહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1397,"k":"para","g":"“અધર્મી વિવિધ પ્રકારની કથાવાર્તા, તપ કરી સત્સંગમાં જોર ભર્યો વર્તે, ને સત્સંગમાં ત્યાગી-ગૃહીના એક એક નિયમને તથા સત્સંગની બધી જ રીત કહી બતાવે. ખપવાળાને પણ જેવું તાન ન હોય તેવો સાવધાન તે દંભી વર્તે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1398,"k":"para","g":"“સત્સંગમાં એવો ધારો છે કે વિશેષ ચાલે તેને સૌ સારો કહે, અધર્મી તેને કેમ કહેવાય? ધર્મમાં ચાલે તેને અધર્મી કહે તે સમાન બીજો કોઈ પાપી ન કહેવાય. સત્સંગની આ રીત છે કે મહાપાપી હોય તે પણ ઉત્તમમાં ખપે, અંદરનું કપટ તો કોણ કળી શકે?","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1399,"k":"para","g":"“અતિ કુટિલ ને કપટી હોય તે પોતાનું કપટ કળાવા દે નહિ. અંતર્યામી ભગવાન કોઈને દેખાડે તોપણ ધર્મવાળો હોય તેથી મુખે કહી શકે નહિ. સત્સંગમાં જ્યારે બૂરું કરે ત્યારે બધાના જાણ્યામાં આવે. જ્યારે તેને સત્સંગમાંથી બહાર કરે ત્યારે તેની મોટાઈ રહે નહિ. મોટેરાને કહેવાની રીત નહિ, કહેવા જાય તેને જ માથે દોષ નાખે અને ન્યાયનાં વચનને પણ અનીતિ કહે એવા ચાલાક હોય. એવાને અમે સત્સંગ કરાવતા નથી, કારણ કે તે આખા સત્સંગને ડુબાડે.”","e":null,"s":["7/10/9-23"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1400,"k":"para","g":"શ્રીહરિએ ઝીંઝરમાં ખોડાભાઈને ત્યાં થાળ જમીને વાત કરતાં કહ્યું, “ધુતારાનો વિશ્વાસ ન કરવો એમ અમે વારે વારે કહીએ છીએ. હરિભક્ત હોવા છતાં ધુતારાનો વિશ્વાસ કરે છે. ધુતારા જેવું તો સાચાને પણ બોલતા આવડે નહિ ને તેથી તે સહેજે પૂજાય છે. ધુતારા માટે તો જમપુરી કરી છે.”","e":null,"s":["9/26/35-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1401,"k":"para","g":"બોટાદમાં શ્રીહરિ કહે, “ભગવાનનાં કથા, કીર્તન અને ચરિત્ર રાત્રિ-દિવસ ધન અને નારીના તાનથી જે કરતાં હોય તેને કાકચાતુરી કહેવાય.”","e":null,"s":["11/80(70)/38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1402,"k":"para","g":"વઢવાણમાં તુલસી દવેને શ્રીહરિએ કહ્યું, “સત્સંગના યોગ વિના સંત-અસંત ઓળખાય નહિ અને તે વિના ભવરોગ ટળે નહિ. જેનાથી ભવરોગ ટળે એવા સંતને આસુરી સંતો પાખંડી માને અને મનાવે છે. જ્યાં આસુરી સંતનું ચલણ હોય, ત્યાં સાચા સંતનું સન્માન થવા દે નહિ. હર કોઈ પ્રકારે ચાલે ત્યાં સુધી તેમનું અપમાન કરાવે છે. સાચા સંત જ્યારે સત્ય વાત કરે ત્યારે અસંતને દુઃખ લાગે છે.”","e":null,"s":["12/48/15-19"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1403,"k":"para","g":"સારંગપુરના જીવાખાચરના દરબારમાં શ્રીહરિએ હરિજનોને કહ્યું, “ઉપરથી ડોળ રાખતા આવડે તેની જગત પૂજા કરે છે, પણ ગરીબ હરિભક્ત તો જગતની પૂજાને ગણ્યા વિના નિયમ, કથા-વાર્તા, કીર્તન કરીને મનમાં મગન રહે છે. ગરીબ કરતાં પ્રપંચીની સાધુતા વધારે દેખાય ને લોકોને રંજન કરવા વાતો પણ બહુ સંઘરી રાખે, પણ સાચા સંત પોતાના જીવના હિતનું જ અનુસંધાન રાખે છે ને સંસારીજનો પોતાની મોટપ જાણે નહિ એ રીતે વાત કરે છે.”","e":null,"s":["14/82/12-18"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1404,"k":"para","g":"શ્રીહરિએ પત્રમાં વાત લખાવી, “અસત્પુરુષના યોગથી જીવની મતિ અસત થઈ જાય છે. પછી જીવનભર તે અસત્ માર્ગે જ ભાવ રાખીને દોડ્યા કરે છે. વિષનું વૃક્ષ વાવે પછી વિષનાં જ ફળ પામે છે. અમૃતનું વૃક્ષ વાવે તો અમૃતફળ પામે છે.”","e":null,"s":["15/81/3-5"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1405,"k":"para","g":"અમદાવાદ નવાવાસમાં શ્રીહરિએ વાત કરતાં કહ્યું, “ગબરગંડને સત્સંગનો પાસ લાગતો નથી, તે આસુરી જીવ છે. છતાં ઉપરથી ધર્મ-નિયમ રાખે છે, પણ તેથી સંત-હરિભક્તો સાથે જીવ મળતો નથી. પોતાના જેવો દેખે ત્યારે આનંદ થાય. પાકા અસુરને કોઈ પુણ્યે કરીને સત્સંગ થાય તો તે સૌથી અધિક વર્તનમાં રુચિ રાખે છે અને હરિના વચનથી અધિક વર્તે ત્યારે જ તેને શાંતિ થાય. સેવા-કીર્તનમાં તેને સહેજ પણ રુચિ હોય નહિ. આત્મસત્તારૂપ રહેવું તેમાં નિવૃત્તિ માને ને ભગવાનને બીજાની સાચી સમજણ કરતાં પોતે અધિક દેખે છે એમ કહે. સભાની વાત તેને સારી લાગે નહિ. બીજી વાત જોડે તાન હોય. અલગ બેસીને વાત કરવામાં ને અલગ ધ્યાન-સ્મરણ કરવામાં તેને ગમતું આવે. પોતાની રુચિમાં મળતો આવે તેને સારો માને. પોતાનું જ્ઞાન, ધ્યાન ને ધામ ત્રણેય સૌથી અધિક છે એમ કહે. પોતાની રુચિમાં ભળતા ન હોય તેની ઘૃણા કરે. પોતાનું માને તેમાં કોટિ ગણી પ્રીતિ રાખે ને તે વિમુખ હોય તો પણ ત્યાગ કરી શકે નહિ. ભગવાનનાં વચન ઉલ્લંઘીને વર્તે - એવા મનમુખી આ લોક અને પરલોકમાં દુઃખી થાય છે. કોઈ કઠણ વચન કહે ને સહન કરે ત્યાં સુધી નભ્યે જાય. સહન ન થાય ત્યારે પૂછ્યા વિના ચાલ્યો જાય! જેને અનંત સુખનો લોભ લાગ્યો હોય તે જ હળીમળીને રહે. તે દૈવી હોય તો બને.”","e":null,"s":["18/83/21-44"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1406,"k":"para","g":"ગઢપુરમાં ગેબી બાવાની ડીંગ જૂઠી પડી એ પછી શ્રીહરિએ સૌને વાત કરતાં કહ્યું, “જેમાં જેટલો ધર્મ હોય તેમાં તેટલો પ્રતાપ રહે. સત્પુરુષ વેદ પુરાણ સ્મૃતિનું પ્રમાણ કરે છે. અસત્પુરુષો પ્રમાણ કરતા નથી. તેને બળદ ને ખર સમાન કહ્યા છે. શાસ્ત્રો સાંભળ્યા વિના મનુષ્ય થઈ શકાય નહિ. ઇન્દ્ર અને બ્રહ્માએ પણ જેટલો શાસ્ત્રનો લોપ કર્યો, તેની મહોબત નહિ રાખતાં શાસ્ત્રોમાં તે સૂચવી દીધું છે. રાજકોટના લોંગ સાહેબે અમને કહ્યું હતું કે સત્સંગ વિના બીજા મતો ધર્મ માર્ગે ચાલતા નથી, તેથી સત્સંગનું ઉચ્છેદન કરવા ઇચ્છે છે. દ્વેષી લોકો ધર્મથી રહિત હોય છે. એમ ડહાપણ ને નીતિવાળા સાહેબ પણ સમજી ગયા છે. અધર્મીની સાથે વિવાદ કરવાથી તેને કંઈ અસર થતી નથી. એવા બગલાઓ ઠેર ઠેર હોય છે, પણ ધર્મી હંસ સત્સંગરૂપી માનસરોવરમાં હોય છે.”","e":null,"s":["19/22(21)/14-27"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1407,"k":"para","g":"વડતાલમાં શ્રીહરિએ વાત કરતાં કહ્યું, “જીવ થઈને ભગવાન જેવાં આચરણ લોકને ભમાવવા કરે છે, તે ભગવાનનો અતિ ભારે દ્રોહી છે. તેનો દૂરથી ત્યાગ કરવો. મિથ્યા વાસુદેવની ગતિ થઈ તેવી તેની થાય છે. તેની બુદ્ધિ નીચમાં નીચ અને બૂરામાં બૂરી છે અને મરીને મળના દ્વારમાં નિવાસ કરે છે. આ વાત સમજ્યા વિના મોક્ષના માર્ગમાં વિઘ્ન થાય છે.”","e":null,"s":["19/59(58)/29-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1408,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સંતોને વાત કરી, “સાધુ અને અસાધુ વર્તનથી પરખાય છે. સાધુને ભગવાનનો અપાર ખપ છે, અસાધુને લેશમાત્ર ખપ નથી.”","e":null,"s":["20/15/13-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1409,"k":"para","g":"પંચાળામાં શ્રીહરિએ વાત કરતાં કહ્યું, “જેને જીવનમાં ધર્મ-નિયમ ન હોય તે ચ્હાય તેવી વાતો કરે કે પ્રતાપ જણાવે તોપણ અમારા હરિભક્તો તે પ્રતાપને ક્યારેય માનતા નથી. જે ધર્મ-નિયમ પાળે છે તેને જ પ્રતાપ આધીન રહે છે. ભગવાનને જાણ્યા પછી તેના વચનમાં ન વર્તે તો તેનો મોક્ષ થતો નથી. વળી, ધર્મ-નિયમમાં વર્ત, પણ પ્રગટ ભગવાનને ન ઓળખે તો તેનું જન્મ-મરણ ટળતું નથી. જેને નિશ્ચય દૃઢ હોય તે ધર્મ-નિયમ લોપે નહિ.”","e":null,"s":["25/10(11)/12-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1410,"k":"para","g":"વડતાલમાં ગોમતી કાંઠે શ્રીહરિએ વાત કરતાં કહ્યું, “ભગવાન અને સત્પુરુષના સંકલ્પમાં સિદ્ધિનું ફળ સમાયેલું છે. એ જે જે વાત કરે કે સંકલ્પ કરે તે સિદ્ધ થાય છે. કદી મિથ્યા થતા નથી. સત્પુરુષના સંકલ્પને મિથ્યા કહે તે અસત્પુરુષ છે. અસત્પુરુષ ભવભટકણના ત્રાસથી છૂટે નહિ. મનફાવ્યું વર્તન કરે, આજ્ઞા લોપે ને શાસ્ત્ર વિરુદ્ધ વર્તે તેમાં શંકા કે ડર ન હોય એવાં લક્ષણોથી અસત્પુરુષને ઓળખવા.”","e":null,"s":["28/54/5-13"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1411,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1412,"k":"para","g":"ઘર છોડ્યું, સાધુનો વેષ ધર્યો, પણ સાધુતા ન આવી તો શું કામનું? પેટ ભરવા જે સાધુ થયો હોય તે તરત ઓળખાઈ જાય. ભગવાનને મૂકીને અન્ય પદાર્થમાં જેટલો રાગ છે તે જ અસાધુપણું છે. તે નામ માત્રનો સાધુ છે. ભગવાનનું નામ ન લે તો કોઈ ખાવાનું ન આપે એટલે નામ લે છે. હરિનું નામ લે ત્યારે તો ફેલ કરવા મળે છે. સંત થઈ પોતાના દેહને લાડ લડાવે તેની સહાય શ્રીહરિ કરતા નથી.","e":null,"s":["5/22/30-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1413,"k":"para","g":"દંભી સાધુ પોતાના દેહભાવને ક્યારેય ખોદતા નથી ને પોતાનો મહિમા ગાય છે. પોતાના દોષોને ગુણ કરીને દેખાડે છે અને સાચા સંતમાં રહેલા હરિના અખંડ સાંનિધ્ય જેવા અપાર ગુણોને દંભમાં ખપાવે છે. ભગવાનનું અખંડ સાંનિધ્ય સૌ માટે દોહ્યલું છે. દિનરાત હરિની સેવામાં એ સાચા સંત ખડે પગે રહે છે. આવું સાંનિધ્ય તો અનંત વર્ષ સુધી અન્ન તજી દે, અષ્ટાંગ યોગ પણ યુગો સુધી સાધે, તપે કરીને શરીર રાફડો કરી નાખે, શરીરમાં કેવળ હાડકાં જ રહે એવું તપ કરે તોપણ શ્રીહરિને ધારણ કરવા રૂપ સામર્થ્ય તેને દુર્લભ છે. આ ગુણ એવો છે કે કોટિ જન્મ સુધી કહીએ તોપણ તેનો પાર આવે નહિ. દંભી સાધુ બીજા અનંત ગુણો કેળવે ને દેખાડે, પણ આ ગુણ તેનામાં આવતો નથી. એટલે પોતાના અન્ય ગુણો સાચા સંતને પાછા પાડવા દેખાડે છે ને એનો આલોચ-આગ્રહ અગણિત રીતે બહાર લાવે છે. એટલું જ નહિ એ ગુણોનું અધિકપણું કહીને સાચા સંતના અનંત અપાર ગુણોને ઢાંકી દે છે. વળી, એ સંત જે ભગવાનની સેવા કરે છે તે વાતને જુક્તિએ કરીને જૂઠી કરે છે. એવા દંભી સંતને એના જેવા જ બીજા દંભી ભક્તો મળી રહે છે. તેને ભક્ત શિરોમણિ કરીને તે વખાણે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1414,"k":"para","g":"દંભી એવા બડા ઠગ હોય છે કે સાચા સાધુને પણ ઠગ કહીને વગોવે છે. છતાં સાચા સાધુ સિદ્ધ હોઈ તેમને લોકો ઘરો ઘર પૂજે છે.","e":null,"s":["10/52/32-40"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":19,"gu":"ગુરુ","en":"Guru","url":"https://www.anirdesh.com/pbp/index.php?page=chp_19","b":[{"i":1415,"k":"para","g":"મેઘપુરમાં શ્રીહરિ મુક્તમુનિને કહે, “અંધારી રાત્રિ હોય તે સૂર્યનો ઉદય થયા વિના ટળે નહિ. સૂર્યને ઠેકાણે ધર્મની વાત છે. ધર્મને અમે પિતા માન્યા છે, અને ધર્મની પત્ની ભક્તિને અમે માતા માની છે. તેમના પુત્ર, જ્ઞાન, વૈરાગ્યને અમે ભાઈ માન્યા છે. તે બધું અમારું કુટુંબ છે. અધર્મ વંશનું મૂળ ઉખાડવા અમે પ્રગટ થયા છીએ.”","e":null,"s":["3/33/22-25"],"sv":["सूर्य रूप है धर्म की बाता | धर्म कुं हम माने हैं ताता ।\n\n धर्म की पत्नी भक्ति जेहू । सो हम माने माता तेहू ॥\n\n तिनके पुत्र जो ज्ञान-वैरागा । बंधु तेहि माने बड़भागा ।\n\n तिनके वंश महा शांत कहावे । सो हमारो कुटुंब रहावे ॥"],"mt":false,"gl":null,"a":false},{"i":1416,"k":"para","g":"શ્રીહરિએ મેઘપુરમાં વાત કરતાં કહ્યું, “ગાફલનો વિશ્વાસ અને સંગ કરવો નહિ. ગાફલ નર જ્યાં ત્યાં વિશ્વાસ મૂકે છે અને માર ખાય છે. ભગવાનમાં ચિત્ત રાખતા હોય એવા પુરુષનો સદા સંગ કરવો. પાણીને ગાળીને પીવું તેમ સમજીને ગુરુ કરવા. જોઈ તપાસીને સંગ કરે તેને પસ્તાવાનું રહેતું નથી.”","e":null,"s":["3/34/51-52"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1417,"k":"para","g":"શ્રીહરિએ ગુંદાળા ગામના લોકોને વાત કરતાં કહ્યું, “મિથ્યા ગુરુ જીવને યમપુરીના દુઃખથી છોડાવી શકતા નથી. સાચા ગુરુ હોય તે જ છોડાવી શકે છે, માટે તેમનો આશ્રય કરવો.”","e":null,"s":["3/41/9"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1418,"k":"para","g":"લોયામાં રાજાઓનો ભાવ જોઈ શ્રીહરિએ રાજી થઈને અમૃતવચનો કહ્યાં, “જગતનો જીવ જેવા તેવા ગુરુમાં વળગી જાય છે, તે ગુરુની તપાસ કરતો નથી. ગુરુ પોતાની રુચિ અનુસાર શિષ્યને વર્તાવે છે, પણ મોક્ષદાતા ગુરુની રીત જુદી છે. મિથ્યા ભગવાન અનેક હોય છે. તે વર્તન જોતાં જણાઈ આવે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1419,"k":"para","g":"“સૂર્ય ગ્રહ છે તેમ બીજા પણ અનંત ગ્રહો છે પણ તેનાથી અંધકાર ટળતો નથી. સૂર્ય ઊગે પછી અન્ય ગ્રહની મહત્તા રહેતી નથી. તેમ સાચા ગુરુ મળે પછી ખોટા ઓળખાય છે. સાચા ગુરુ ધર્મની વૃદ્ધિ કરે છે. અધર્મનું ખંડન કરે છે. નીતિ-નિયમ અનુસાર સૌને વર્તાવે છે. અનીતિમાં ક્યારેય પ્રીતિ રાખતા નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1420,"k":"para","g":"“નારી અને ધન દેખી તેમાં તણાતા નથી. ચક્રવર્તી રાજમાં પણ લોભાતા નથી. પાતાળથી પ્રકૃતિપુરુષ સુધી સૌમાં દુઃખ દેખે છે. જ્ઞાન વિના કશામાં લાભ જોતા નથી. લોકમાં કોઈને ઘણું બધું પ્રાપ્ત થયેલું જુએ, પણ તેને ભગવાનની સમજ ન હોય તો બધું શૂન્ય ગણે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1421,"k":"para","g":"“અક્ષરધામમાં રહેલી ભગવાનની મૂર્તિને સદા સાકાર માને છે. બીજાને સ્વધર્મમાં વર્તાવી ભગવાનનું જ્ઞાન દૃઢ કરાવે છે. તેના હૃદયમાં હરિ વગર કોઈને સ્થાન આપતા નથી. ઉત્તમ વિષય પ્રાપ્ત થાય તો તરત ત્યાંથી અળગા થઈ જાય છે. અળગા થવાની મુખ્ય નિશાની એ કે મનવાંછિત કશુંક નાશ પામે ત્યારે રંચમાત્ર દુઃખ ન થાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1422,"k":"para","g":"“ખાન-પાન કે સ્ત્રી-દ્રવ્ય કાજે ક્યારે યત્ન કરતા નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1423,"k":"para","g":"“કોઈ સન્માન ન કરે તોપણ મન મગન રહે છે. આવું જીવથી ન થાય. સિદ્ધ પણ આવું વર્તી ન શકે. મુક્તને પણ માનની રુચિ ટળતી નથી (એટલે કે આવા ગુરુ મુક્તથી પણ પર છે, અક્ષરબ્રહ્મ છે.) એ નિશાની જોઈ સાચા ગુરુની ખાતરી કરવી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1424,"k":"para","g":"“બીજું પણ અનંત પ્રકારનું સામર્થ્ય તેમાં રહેલું છે. એવા ગુરુ નિશ્ચય ભગવાન તુલ્ય છે, એમ બધાના અંતરમાં સાક્ષી કબૂલે છે.”","e":null,"s":["4/66/27-40"],"sv":["तामें जन भ्रमात, निरधार होत न वात कोउ ।\n\n जिहां तिहां लग जात, जेसे गुरु मिलहि तिमि ॥\n\n गुरु को करे विश्वास, जाकि रूचि होय जीमि ।\n\n गुरु बतावत तास, मोक्ष गुरु कि हें रिति भिन्नि ॥\n\n हरि धरत अवतार जबहु । ता विन गम न परत कबहु ॥\n\n पाखंड प्रभु कर होत अनंता। वर्तन करि आवत देखंता ॥\n\n साचे कि दृढता होवत तबहि। जुठ प्रभु ओर चलत जबहि ॥\n\n तेजवान काय हि केसा । साचे मति सम होत न तेसा ॥\n\n लंबकर्ण पर होद्दा धारे । साचे गज न होत तेउ वारे ॥\n\n सूर्य पतंग ओर पतंग अवंता । गनत ताको न आवत अंता ॥\n\n ओर पतंग अंधकार न खोवे । नाम कर तेहि काम न होवे ॥\n\n साचे सूर्य उदे होत जबहि। पतंग जुठ जनात तबहि ॥\n\n धर्म कि करे वृद्धि जेहा । अधर्म के करे खंडन तेहा ॥\n\n अदल नीति चलवे सुरिता । अनीति में न करे कबु प्रीता ॥\n\n नारि, धन देखि न तनावे । चक्रवर्ति राज में न लोभावे ॥\n\n पाताल सें पुरुष प्रकृति प्रजंता । बडे में बडो दुःख देखत रहंता ॥\n\n ज्ञान विन कोई में न देखत लाभा । विन समझ सब कहत अलाभा ॥\n\n ब्रह्मपुर में रहि मूर्ति जेहु । ताकुं साकार कहत तेहु ॥\n\n स्वधर्म रखि ताको ज्ञान करावे । हरि बिन ऐसो कोउ न आवे ॥\n\n उत्तम विषय प्राप्त होय तोउ । तिनसें अलग रहेवे सोउ ॥\n\n अलग को हे ऐंधान यह, अति प्रसिद्धि हि जान ।\n\n मनवांछित होय वास तब, रंच न दुःख उर मान ॥\n\n खानपान धन नारि हित, कबहु न करहि जत्न ।\n\n सन्मान कोउ न करत कबु, तोहु रहत हें मग्न ॥\n\n ऐसो जीवसें न होय, ऐसो न होवत सिद्ध तेहु ।\n\n मुक्त हि होवे जोय, तोहु मानकि रहत रुच ॥\n\n एहि वर्तन हें ऐंधान, ओर सामृथ हें अनंत तेहि ।\n\n एहि निश्चे भगवान, अंतर में एसे देखात सब ॥"],"mt":false,"gl":null,"a":false},{"i":1425,"k":"para","g":"અલૈયા ગામેથી શ્રીહરિએ હરિભક્તોને ઉદ્દેશીને એક પત્ર લખ્યો તેમાં લખ્યું કે: “જીવનું હિત કરે તે સાચા ગુરુ છે. એવા ગરુના આશ્રયે શિષ્ય ક્યારેય દુઃખ પામતા નથી. આ લોક-પરલોકનું હિત બતાવે તે સાચા ગુરુ છે. પરલોક સુધારવો એ જ મનુષ્ય-દેહનું ફળ છે. શુક, સનકાદિક, નારદ, પ્રહ્‌લાદ, પ્રિયવ્રત વગેરેનો એ મત છે. તે સિવાયનું બધું ડહાપણ નકામું છે. પ્રભુ ભજતો હોય તેને ડારો દે તે જમદૂત કરતાં વધુ હત્યારો છે.”","e":null,"s":["5/19/18-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1426,"k":"para","g":"માંડવીમાં શ્રીહરિએ પુરજનોને વાત કરતાં કહ્યું, “શુદ્ધ વર્તન વિન મોક્ષ ન હોવે, અનંત જન્મ પઢિ પઢિ ખોવે. શુદ્ધ ગુરુ મિલે બિન જબહૂ, શુદ્ધ મોક્ષ ન પાવત કબહૂ. - શુદ્ધ વર્તન વિના અનંત જન્મ સુધી શાસ્ત્રો ભણે, પણ તેનો મોક્ષ થતો નથી. શુદ્ધ ગુરુ મળ્યા વિના શુદ્ધ મોક્ષ ક્યારેય થતો નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1427,"k":"para","g":"વિષયમાં રાગ હોય અને તે ધર્મ-ભક્તિ-વૈરાગ્ય અને જ્ઞાનનો બોધ કરે, આત્મનિષ્ઠા દેખાડે, નારીને રાક્ષસી કહે, પિંડ બ્રહ્માંડને ખોટાં કહે, ઉપરથી બહુ ત્યાગ રાખે, શરીર સૂકવી નાંખે, વિષયની નિંદા કરે, છતાં પણ તેના મોક્ષનું કાચું છે. ઉપરના તેવા બધા આચારથી લોકો તેને આધીન થાય અને તેથી તે જે જે કહે તેને સાચું માને, અને સેવા કરે અને તેનો અભાવ લે નહિ એમ તે પૂજા તો કરે છે, પણ તે ખુવાર થાય છે. ગુરુ પરમેશ્વરના દાસ થઈને તેની ઉપાસના કરે છે. પરમેશ્વરના બાંધેલા નિયમમાં ગુરુ વર્તે છે ત્યારે તેનો જશ સકલ લોકમાં વધે છે. ગુરુ થઈને પરમેશ્વરના બાંધેલા નિયમ લેશ પણ લોપે તો તે દંડને પાત્ર બને છે. આ અમારો મત છે.”","e":null,"s":["5/33/17-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1428,"k":"para","g":"શ્રીહરિએ જીવેન્દ્રને કહ્યું, “કસબી લુહારને પાકું લોઢું મળે તો તેજદાર તલવારનું નિર્માણ થાય, તે જ રીત મોક્ષમાર્ગમાં જાણવી. ગુરુ લુહાર છે ને શિષ્ય લોઢું છે. ગુરુ કસબી ન હોય ને શિષ્ય કાચો હોય તો મોક્ષનું કામ સરતું નથી. એક હાથથી તાળી પડે નહીં. ગુરુ ધર્મ, જ્ઞાનાદિક ગુણે યુક્ત હોવા જોઈએ. શિષ્ય પાકો વિશ્વાસી હોય ને તે ગુરુના વચન પ્રમાણે દેહને વર્તાવે તો તેની કીર્તિ વધે છે.”","e":null,"s":["5/72/28-30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1429,"k":"para","g":"માવાભક્ત પ્રત્યે શ્રીહરિએ વાત કરતાં કહ્યું, “ભગવાન કે ભગવાનના સાચા સંત જ્યારે પ્રગટ થાય છે ને જ્યારે તેના મુખે શાસ્ત્ર સાંભળે છે, ત્યારે જીવનો ઉદ્ધાર થાય છે. બાકી સ્ત્રી અને ધનમાં લપટાયેલા એવા ગુરુઓનો પાર નથી. તેનું શરણું લેવાથી કોઈ ભવજળ પાર ઊતરી શકતું નથી. ત્યાગી હોય ને ગુરુપદ સરસ શોભાવતો હોય, પણ ધન-સ્ત્રીનો યોગ જ્યારે થાય છે ત્યારે ભ્રષ્ટ થઈ જાય છે. શાસ્ત્રમાં ઠેર-ઠેર એનાં દૃષ્ટાંતો છે. જે ગુરુપદે આવે છે તેને ધન અને સ્ત્રી તો પ્રથમથી જ મળી જાય છે. ધન અને સ્ત્રીનો ત્યાગ રાખનાર ગુરુ મળવા કઠણ છે. ધન ને સ્ત્રીના પ્રસંગે કરીને ભગવાન લોપાય નહિ, બાકી મોટા મોટાને નારી-ધને ફજેત કર્યા છે. અગ્નિ અને ઝેરીલા સાપનું વિષ તેનો સ્પર્શ કર્યા વિના ચઢતું નથી, પણ નારી અને ધનરૂપી વિષ તો દેખવા માત્રે ચઢે છે. પલકમાં સૂધ-બૂધ ભુલાવી દે છે. વિષ ચઢે પછી કોઈ નિયમ રહેતો નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1430,"k":"para","g":"“શાસ્ત્રોમાં લખેલાં ઉદાહરણો ગુરુએ નજર સામે રાખવાં અને પોતાના ત્યાગી શિષ્યોને અવાર-નવાર તેની વાત કરવી. ગુરુ એવા હોય કે તેનું વર્તન જોઈ ત્યાગી સાધુ ક્યારેય સ્ત્રી-ધનમાં આસક્ત ન થાય. ગુરુ પોતાના ત્યાગી શિષ્યને આ બધી વાતો કરતા તો હોય છે, પણ એ ત્યાગીઓ તેને કાને ધરતા નથી, વારી ફેરીને ફેંકી દે છે, ગુરુ સંપૂર્ણ ત્યાગ પાળે પછી ત્યાગની વાતો કરે તો શિષ્યને માન્યામાં આવે છે. ધન અને સ્ત્રીથી સંપૂર્ણ દૂર રહે તેને પૂરો ત્યાગી જાણવો. તરતા ન આવડતું હોય તે બીજાને શું તારે?","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1431,"k":"para","g":"“સાચા સંતો તો ઈશ્વરની પેઠે સમર્થ થકી જરણા કરે છે. આકાશની જેમ નિર્લેપ રહે છે. તેને ક્યારેય કોઈ દાગ લાગતો નથી.” આ સાંભળી માવા ભક્તે કહ્યું, “મોટા મોટા સંતો અને અવતારોનો ગણતા પાર આવે નહિ. તે બધાનું બીજ તમે છો, મહારાજ!”","e":null,"s":["6/85/14-40"],"sv":["हरि वा साचे संत हि, प्रगट होत जेहि वार ।\n\n तेहि मुख सुनत शास्त्र जब, तब जन होत भव पार ॥\n\n नारी धन-संग्रह करत, ऐसे गुरु अपार ।\n\n तिनसें न भवजल तरत कोउ, शरन लेत नरनार ॥\n\n त्यागी गुरु सरस, शास्त्र में किये ठोर ठोर तेहि ।\n\n तरत हो जावत नरस, धनत्रिया को होत जोग जबे ॥\n\n गुरु होवे जेहि, धनत्रिया ताकुं प्रथम मिलत ।\n\n ता विन जग में केहि, त्यागी गुरु धन त्रिय हीन ॥\n\n धन त्रिया को जोग रहे जेहा । ईश्वर कुं डाग न लगे केहा ॥\n\n धन त्रिय हे अनल समाना । भस्म करे संग करत माना ॥\n\n अनल मादक विष हि व्याला । परस विन कबु चढि न हाला ॥\n\n नारी धन देखत चढ़ि जावे । पलक में सुध बुद्ध भुलावे ॥\n\n चढे पिछे नियम रहे न कोऊ । तर्त फजित कर डारे सोऊ ॥\n\n बडे बडे त्यागिगृहि जेते । नारिधन फजित किये तेते ॥\n\n नाम निमेष लिखे हे ताके । त्यागी जनकुं जनावन वाके ॥\n\n ताकी रीत जोई कर त्यागी । नारी धन में न होवे अनुरागी ॥\n\n गुरु वचन कहे सो वेरी । तोऊ त्यागी पिछें देवे फेरी ॥\n\n तेहि कर गुरु वचन को कबसा । त्यागी पूरे सो त्यागे तबसा ॥\n\n धन-त्रिय से त्यागी रहे दूरा । ताकुं त्यागी जानना पूरा ॥\n\n ईश्वर की कछु बात न करना । ओर के दोष करे सब जरना ॥\n\n आकाश सम सब गुन हे वाहि । कोउ न दाग लगे कबु ताहि ॥\n\n भक्त बोले तेहि वार, बड़े बड़े संत अवतार जेहि ।\n\n गनत न आवहि पार, सो सबके हो बीज तुम ॥"],"mt":false,"gl":null,"a":false},{"i":1432,"k":"para","g":"કણભા ગામે ઝવેરીદાસના ભવનમાં દીનબંધુ શ્રીહરિ હેતે કરીને હરિભક્તોને કહેવા લાગ્યા, “તમારાં ધન્ય ભાગ્ય છે કે તમને સત્સંગ મળ્યો છે. સત્સંગ વિના અભિમાની જનો દુઃખ પામે છે અને કુમાર્ગમાં જઈને નાક, કાન, શિર કપાવે છે. તેને દુઃખનો પાર નથી. દુઃખ ભોગવવા છતાં કુમાર્ગને તજી શકતા નથી, જગતમાં જેટલા મતમાં ગુરુપદે આચાર્ય થયા છે, તેને પણ રુચતું હોવાથી પોતાના શિષ્યોને કુમાર્ગથી પાછા વાળતા નથી. આચાર્યગુરુઓ ફેલમાં રાચે, પોતાને ને બીજાને બ્રહ્મ માને, પણ હકીકતે તે બ્રહ્મ નથી, મિથ્યા ગુરુ થઈને જન્મ વગોવે છે. બ્રહ્મસ્વરૂપ ગુરુ તો જુદા જ છે. એવા ગુરુનું પ્રથમ લક્ષણ એ છે કે પોતે બ્રહ્મચર્યવ્રતનું દૃઢપણે પાલન કરે ને બીજા પાસે કરાવે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1433,"k":"para","g":"“બીજું, પોતે ફેલ ન કરે, કેફ ન કરે કે વ્યસન ન રાખે. ત્રીજું, મન-કર્મ-વચને થતી હિંસામાત્રનો ત્યાગ રાખે ને બીજા પાસે ત્યાગ રખાવે. અર્થાત્ અહિંસા ધર્મમાં દૃઢ વર્તે. આવું વર્તન ગુરુનું બ્રહ્મસ્વરૂપપણું દર્શાવે છે. ચોથું એ કે ધર્મ, જ્ઞાન, વૈરાગ્ય અને ભક્તિ - અર્થાત્ એકાંતિક ધર્મ પોતે પૂર્ણ રીતે ધારણ કરે ને એમાં પોતે શૂરા હોય એવા ગુરુને બ્રહ્મસ્વરૂપ ગુરુ જાણવા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1434,"k":"para","g":"“વળી, પાંચમું લક્ષણ એ કે દિવસ-રાત ભગવાન સંબંધી જ ક્રિયા કરે, ભગવાનના સ્વરૂપનું જ્ઞાન ફેલાવે. કથા-કીર્તનમાં મગ્ન રહે. તેમાં ક્યારેય તૃપ્તિ ન પામે, પરંતુ દિન-પ્રતિદિન તેમાં અધિક ચઢતો ને ચઢતો રંગ રહે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1435,"k":"para","g":"“છઠું લક્ષણ એ કે ભગવાનનાં લીલા ચરિત્રો રૂપી મહાસાગરમાં નિમગ્ન રહે, તેમાંથી ક્યારેય બહાર ન નીકળે. મીન જે રીતે સિંધુમાં મગ્ન રહી આનંદ કરે, નાચે-કૂદે, ક્રીડા કરે પણ તેમાંથી બહાર પલમાત્ર નીકળે તો પ્રાણ ખૂએ, આનંદ ઊડી જાય તેમ આવા બ્રહ્મસ્વરૂપ સદ્‌ગુરુ ભગવાનમાં રહીને બધી દેહક્રિયા કરે. આ તેની ઉત્કૃષ્ટ બ્રહ્મદશા કહી છે. વળી, સાતમું લક્ષણ એ કે ભગવાન સિવાય બીજી વાત મુખે ઉચ્ચારે નહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1436,"k":"para","g":"“બ્રહ્મસ્થિતિનાં આવાં અપાર લક્ષણોથી યુક્ત ગુરુને મુમુક્ષુએ ઓળખવા. ગ્રંથોમાં પણ શુક-સનકાદિક, શિવજી, જડભરત, કપિલ, દત્તાત્રેયને એવી બ્રહ્મદશા હતી. તેમના જેવાં ચરિત્ર જેમાં હોય તેવા ગુરુનાં લક્ષણ ઓળખવાં. એવાં લક્ષણ ન હોય ને પોતાને બ્રહ્મ કહેવડાવતો હોય પણ એમ કોઈ બ્રહ્મ થઈ શકતું નથી. આ મર્મ સુબુદ્ધિ જન પામી જાય છે. કુબુદ્ધિજન તો એ માર્ગે ચાલી જ શકતા નથી.”","e":null,"s":["8/26/1-16"],"sv":["श्रीहरि घनश्याम हि, भक्तवत्सल कृपाल ।\n\n हरिजन सें बोले हेत कर, दीनबंधु प्रतिपाल ॥\n\n तुमारो धन्य भाग्य हि, मिले यह सत्संग ।\n\n सत्संग बिन अभिमानी जन, लहत दुःख सो अभंग ॥\n\n कुमारग में चलत, यह लोक में जन जोउ ।\n\n केसो चहे सुख लहंत, नाक-कान शिर खोत तरत ॥\n\n एसो दुःख गिने पार न आवे । यह लोक में प्रसिद्ध देखावे ॥\n\n देखत दुःख तोहु त्रास न लेशा । कुमारग में चलत हमेशा ॥\n\n आचार्यगुरु मत जग में जेते । कुमारग न निवारत तेते ॥\n\n निजकुं रुचत कुमारग जबहु । शिष्य कुं निवारत नहि तबहु ॥\n\n आचार्य गुरु भये फेल अपारा । फेल करन ब्रह्म बनत गमारा ॥\n\n फेल करे सो ब्रह्म न होवे । गुरु होई ओर के जनम विगोवे ॥\n\n गुरु होई ब्रह्मचर्य कुं रखावे । ऐसे गुरु सो ब्रह्म कहावे ॥\n\n फेल रु केफ व्यसन हि जेता । गुरु न करे करावे तेता ॥\n\n हिंसामात्र न करत, न करावे । ऐसे गुरु ब्रह्मरूप दरशावे ॥\n\n भक्ति, धर्म, ज्ञान, वैराग्य पूरा । ब्रह्मरूप गुरु जानना शूरा ॥\n\n दिन-रात हरिसंबंध हि ज्ञाना । कथा कीर्तन करत रहाना ॥\n\n तामें तृप्ति कबहु न पावे । दिन दिन चढा रंग अधिक रखावे ॥\n\n कामी अरु लोभी जन हि जेसे । तृप्ति न पावत पलहि तेसे ॥\n\n हरि के चरित्र हि सागर मांहि । झिलत रहे बार निकसत नाहि ॥\n\n मीन ज्युं मगन सिंधुके संगा । आनंद खेल महिं करत अभंगा ॥\n\n तामें सुं निकसे पल हि बारा । तब आनंद न रहत लगारा ॥\n\n ब्रह्मदशा के चिह्न हि, एसे हें जो अपार ।\n\n भगवान विन नहि वात हि, करत न मुख उच्चार ॥\n\n शुक सनकादिक शिव हि, ब्रह्मदशा शुद्ध पाये ।\n\n जडभरत कपिल हि, दत्तात्रय श्रेष्ठ कहाये ॥\n\n तिनको जोना एह, ग्रंथ में लिखे हें प्रसिद्ध तेहि ।\n\n जाकुं होय उर चाह, ब्रह्मदशा में सो ग्रहन करत ॥\n\n मुख से कहे में ब्रह्म, ऐसे ब्रह्म नहि होत कोउ ।\n\n सबुद्धि लहत यह मर्म, कबुद्धि चलत नहि राह यह ॥"],"mt":false,"gl":null,"a":false},{"i":1437,"k":"para","g":"ઝીંઝાવદરમાં શ્રીહરિએ અલર્ક નૃપ પ્રત્યે વાત કરતાં કહ્યું, “જેમનું મન ધન-નારીમાં બંધાય નહિ, તે સાચા ગુરુ કહેવાય. જગતમાં ત્યાગી અને ગૃહી બે પ્રકારના ગુરુઓ છે. તેમાં ત્યાગી ગુરુની રીત ન્યારી છે. તે ધન માટે દોડાદોડ કરે નહિ અને ગૃહી ગુરુ ધન-નારી માટે જેટલો ઉદ્યમ કરે તેટલો તેમાં દોષ કહેવાય, પણ નિર્લોભ વર્તન જે રાખે તેને શિષ્યો બહુ ધન આપે. ઘેર ઘેર જે ધન માગે તે લોભી ગુરુ કહેવાય.”","e":null,"s":["9/40(41)/20-24"],"sv":["सो गुरु साचे जग में जानो । धन नारी में न मन बंधानो ॥\n\n जग में गुरु हें दोउ प्रकारा । एक त्यागि एक गृहिधर्म धारा ॥\n\n त्यागि गुरु की रीत हे ओरा । धन हित सो न करहि दोरा ॥\n\n गृही होई धन-नारी हिता । उद्यम रहे सो जितनो करिता ॥\n\n तितनो तामें दोष कहावे । लोभ ताकुं सो देखे न आवे ॥\n\n निर्लोभ वर्तन रखत हि जाहि । शिष्य बहु धन देवत हें ताहि ॥\n\n घर घर मागत धन हि जेहु । लोभी गुरु सब कहेवत तेहु ।"],"mt":false,"gl":null,"a":false},{"i":1438,"k":"para","g":"ઝીંઝાવદરમાં શ્રીહરિએ અલર્ક રાજાને વાત કરતાં કહ્યું, “જે ગુરુ ધનનો સંગ્રહ નહિ કરીને શિષ્યોને ખવડાવે તે સાચા કહેવાય અને ધન-નારીમાં બંધાય નહિ. જે ધન માગે તે લોભી ગુરુ કહેવાય.”","e":null,"s":["9/41(40)/20"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1439,"k":"para","g":"શ્રીહરિએ માંડવીમાં વેદાંતી પાસે વાત કરતાં કહ્યું, “સત્સંગ વિના જ્ઞાન કથે તે મિથ્યા જ્ઞાની છે. મનુષ્યમાત્રને અજ્ઞાનરૂપી તમસ વળગ્યું છે, તે બ્રહ્મરૂપ ગુરુ મળ્યા વિના જતું નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1440,"k":"verse","g":"‘જનમાત્ર જો કહાવત જેતે, બ્રહ્મરૂપ ગુરુ મિલે વિન તેતે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1441,"k":"verse","g":"અજ્ઞાન તમ નહિં જાવત દેખે, સબ બાત કું એક કર લેખે.’","e":null,"s":["11/3/31-32"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1442,"k":"para","g":"જૂનાગઢમાં શ્રીહરિએ વર્ણીને વેદઋષિની વાત કરી હતી. એ સઘળી વાર્તા મુક્તમુનિએ યાદ રાખીને ઉત્તમ નૃપને કહી, “આદર્શ શિષ્ય હોય તે ગુરુની આજ્ઞામાં દેહને ગણકારે નહિ, ભૂખ-તરસ જુએ નહિ, ઠંડી-ગરમીને ગણકારે નહિ, મનનો એક પળ વિશ્વાસ ન કરે અને પ્રેમથી ગુરુને મન અર્પણ કરી મંડ્યો રહે. ગુરુ સુખ-દુઃખનું ક્યારેય પૂછે નહિ, તો પણ ગુરુનો અવગુણ ન આવે. લાંબો સમય આ રીતે સેવા કરે એવા શિષ્ય પર ગુરુ પ્રસન્ન થાય છે અને મોક્ષ કરે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1443,"k":"para","g":"“ગુરુ યોગ્ય કહે કે અયોગ્ય - એ ટેલચાકરી તેની પરીક્ષા છે. ગુરુ શિષ્યની એ રીતે બહુવિધ પરીક્ષા કરે છે. ગુરુ નિર્દયપણે તેને સેવામાં જોતરે છે, તોપણ તેમાં ક્યારેય પાછો પગ ન ભરે. ગુરુની સેવા દેવ જાણીને કરે. જેમ વેદ નામના મુમુક્ષુએ ગુરુની એ રીતે સેવા કરી તો ગુરુનો રાજીપો થઈ ગયો. ગુરુસેવાથી વેદ બ્રહ્મરૂપ થઈ ગયો. ગુરુની સેવાનું એવું માહાત્મ્ય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1444,"k":"para","g":"“વેદની જેમ હરિજન પણ ગુરુની સેવા કરે તો બ્રહ્મરૂપ થઈ જાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1445,"k":"para","g":"“ગુરુ-સંતનો દોષ જે લે છે તે સત્સંગ કરતો ઘટતો જાય છે. ગુરુ-સંતને જેવી દૃષ્ટિથી જુએ તેવા ગુણ શિષ્યમાં આવે છે. ગુરુને દેવ સમાન જાણીને સેવવા. એ રીતે હરિભક્ત સેવા કરે તો વધે ને બ્રહ્મરૂપ થાય. ધર્મ, જ્ઞાન, વૈરાગ્ય, ભક્તિ એ એકાંતિક ધર્મ ગુરુમાં વસે છે તે શિષ્યમાં પણ વસે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1446,"k":"para","g":"“ગુરુની જેમ એ પણ પુરુષોત્તમ ભગવાનને રહેવાનું સદન બની જાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1447,"k":"para","g":"“ગુરુ-સંતનો દોષ ન જુએ તો દિન દિન પ્રતિ વૃદ્ધિ પામે છે. સત્સંગ કરતાં કરતાં શુભ વિચાર પ્રગટ થાય છે.”","e":null,"s":["11/56/4-16"],"sv":["क्षुधा तृषा सित घाम, सहन करि घरकाम करत ।\n\n करत न पल विश्राम, गुरु सेव में प्रेम अधिक ॥\n\n गुरु सुखदुःख हि पूछे न कबहु । गुरु के अवगुन लिये न तबहु ॥\n\n प्रेम से सेवा करे बहु काला । ता पर गुरु तब रिझे तत्काला ॥\n\n परम श्रेष्ठ मोक्ष तेहि दीने । वेदशास्त्र में सर्वज्ञता कीन्हे ॥\n\n धर्म भक्ति जुत दिनेउ ज्ञाना । सेव में गुरु के मन जब माना ॥\n\n जोग्य अजोग्य टेल जो जेती । करन परीक्षा कराये तेती ॥\n\n गुरु के अभाव न लिए कोउ रीता । बहु बहु रीत परीक्षा करीता ॥\n\n गुरु निर्दय होई सेवा कराये । कोई में पिछे पग न धराये ॥\n\n गुरु के अभाव तोहु न लीन्हा । देव जानि के सेवा कीन्हा ॥\n\n सेव से वेद तेहि ब्रह्म सम भयेउ । सेवा को माहात्म्य ऐसे रहेउ ॥\n\n वेद सम हरिजन करे सेव जेता । ब्रह्मरूप हो जावे तेता ॥\n\n गुरु संत के दोष लेत जाहि । सत्संग करत घटत हि ताहि ॥\n\n गुरु संतकुं देखे जिस भाँति । हरिजन में गुन आवे तिस जाति ॥\n\n गुरु संत कुं सेवे देव समाना । हरिजन बढे सो परम सुजाना ॥\n\n धर्मभक्ति आदिक परिवारा । तामें वसत लगत न वारा ॥\n\n पुरुषोत्तम के सदन सो होवे । गुरु संत के दोष न जोवे ॥\n\n दिन दिन बढत सो जात अपारा । सत्संग करत जेहि शुभ विचारा ॥"],"mt":false,"gl":null,"a":false},{"i":1448,"k":"para","g":"જૂનાગઢમાં શ્રીહરિએ વર્ણી પ્રત્યે વાત કરી, “ગુરુ-સંતમાં નિર્દોષબુદ્ધિ રાખી તેને બ્રહ્મરૂપ જાણીને સેવે તો તે મુમુક્ષુ ભગવાનના ધામને પામે છે. ગુરુની સેવા વગર ધામ મળતું નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1449,"k":"verse","g":"‘યૂં ગુરુ સંત કું જોઉ, સેવે બ્રહ્મરૂપ જાનિ જેહિ;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1450,"k":"verse","g":"હરિધામ લહે સોઉ, સેવ બિન ધામ ન લહત.’","e":null,"s":["11/58/28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1451,"k":"para","g":"જૂનાગઢમાં શ્રીહરિએ વર્ણી પ્રત્યે વાત કરતાં કહ્યું, “જેને જેવા ગુરુ મળે તેવો તેને કરી દે. ગુરુના મહિમાનું મૂળ તેનું દૈવત છે. જેવી શિષ્યની બુદ્ધિ હોય તેવા ગુરુ તેને મળે છે. બ્રહ્મવિદ્યા અપાર છે અને અમાયિક છે. તે અમાયિક ગુરુ મળ્યા વગર સિદ્ધ થતી નથી. બ્રહ્મવિદ્યાની જેટલી કંઈ વાત કહેવાય છે તે અમાયિક ગુરુ થકી શિખાય છે. માયિક ગુરુથી કદી શિખાતી નથી. અમાયિક ગુરુની ઓળખાણ એ છે કે ચૌદ લોકના જેટલા પંચવિષય છે તેમાં પોતે સાર માનતા નથી. પ્રકૃતિ પુરુષ સુધીના આશ્ચર્યકારી સઘળા લોકને કાળનું ભક્ષણ માને છે. વળી, ભગવાન વિના કોઈને સત્ય દેખતા નથી. ભગવાન પોતાની ઇચ્છાએ કરીને પૃથ્વી પર આવે તો પણ તે સદા અમાયિક છે. તેનું સ્વરૂપ અને ચરિત્ર પણ અમાયિક છે. અમાયિક ગુરુ ભગવાનને ક્યારેય માયિક જેવા કહેતા નથી અને દેખતા પણ નથી. જે અમાયિક છે (અર્થાત્ માયાથી પર અક્ષરબ્રહ્મ-પરબ્રહ્મ છે) તે સૌને અમાયિક જુએ છે. અમાયિક જોવા તે સવળી સમજણ છે ને તે જેટલી સિદ્ધ થાય તે મોક્ષ આપનારી બને છે. દીન થઈને ભગવાનના ચરિત્રમાત્રનું ગાન કરવામાં મગન રહે તેમાં ઉપનિષદ માત્ર આવી ગયાં. અને એને જ બ્રહ્મવિદ્યા કહે છે. ભગવાનના સંબંધમાં આવતી જેટલી કંઈ વાત છે તે બધી જ બ્રહ્મવિદ્યા છે.” એટલી વાત કરીને શ્રીહરિ અશ્વ પર બેઠા. સંતો-હરિજનો મગન થકા હરિગુણ ગાતા ચાલ્યા.”","e":null,"s":["11/61(51-b)/25-40"],"sv":["जेसे जाकुं मिलत गुरु, तेसे ताकुं कर देत ।\n\n दैवत ते तो मूल तेहि, बुद्धि जेसे जोई लेत ॥\n\n ब्रह्मविद्या हे अपार हि, अमायिक सब हि तेह ।\n\n अमायिक गुरु मिले विन, सिद्ध न होवत एह ॥\n\n ब्रह्मविद्या की बात, जेति जेह कहात जोउ ।\n\n अमायिक गुरु सिखात, मायिक गुरु न सिखात कबु ॥\n\n पंचविषय चौद लोक के जेते । सार न माने एकहि ते ते ॥\n\n प्रकृतिपुरुष लग कहावत जेतो । अधिक आश्चर्य मनात तेतो ॥\n\n काल चविना देखत निहारि । ऐसि मति जाकि वर्तत भारि ॥\n\n अमायिक गुरु कहत हें तेहा । श्रीहरि विन साच देखे न जेहा ॥\n\n श्रीहरि धाम सामे रहे जेता । अमायिक सो कहावत तेता ॥\n\n हरि इच्छाकर भोमि पर आवे । तोहु तेह अमायिक कहावे ॥\n\n अमायिक हरि स्वरूप सदाई । ताके जो जो चरित्र हि ताई ॥\n\n मायिक सम न कहे मुख कबहु । मायिक सम नहि देखे जबहु ॥\n\n हरि अरु हरि के जेते चरिता । भक्त हित हि जेते करीता ॥\n\n प्रगट हरि के भये जोग हि जाहि । संत हरिजन ते ते ताहि ॥\n\n अमायिक कर देखे सब तेहु । अमायिक जन जो कहावत तेहु ॥\n\n सुलट समझ मोक्ष दाई जेति । ब्रह्मविद्या सो कहावत तेति ॥\n\n उपनिषद मात्र हि जितना । हरि के चरित्र कुं दीन होई तितना ॥\n\n मगन होई कहत गुन गाना । तेहि करि तेहि अधिक रहाना ॥\n\n हरिसंबंध हें ताके नामा । यह लोक परलोक हि रहाता ॥\n\n ब्रह्मविद्या हें ताके नामा । अर्थ जान विन लहत न ठामा ॥\n\n इतनी करि हरि बात, संत हरिजन मगन भयेउ ।\n\n चले जन हरि गुन गात, श्रीहरि बैठे अश्व पर ॥"],"mt":false,"gl":null,"a":false},{"i":1452,"k":"para","g":"માણાવદરમાં ગજેન્દ્રનૃપને શ્રીહરિએ કહ્યું, “ગુરુઓ જગતમાં ઘણા છે, પણ સમર્થની વાત જ ન્યારી છે. જેનાથી સમર્થ હોય તેની વાત તે વિચારી જુએ ત્યારે સમજ્યામાં આવે. વિચારે નહિ તેને કંઈ ખબર પડતી નથી. એટલે પ્રતાપ પણ દેખ્યામાં આવતો નથી. સમર્થ હોય તેનું સામર્થ્ય ઢાંક્યું રહેતું નથી, પ્રગટ દેખાઈ આવે છે. તે સૌને પોતાને વશ વર્તાવે છે. વર્તન ઉપરથી જેને જેવો ખપ હોય તે જણાય છે. સુવર્ણની કસોટી જેમ અગ્નિ છે, તેમ ગુરુની કસોટી વર્તન છે. વર્તન ઉપરથી તેનું સ્વરૂપ ઓળખાય છે. જેમ સાત સામેલિયો બળદ હોય તે તેના કાર્ય પરથી ઓળખાઈ આવે છે. વિવિધ ધૂંસરીએ જોડવાથી સાત સામેલિયાની કુશળતા પરખાય છે, તેમ સત્સંગમાં ત્યાગી-ગૃહી જેટલા કંઈ આશ્રિતો છે તેને પ્રસન્ન મનથી એક રહેણીમાં વર્તાવવા તે સમર્થ ગુરુ વિના શક્ય થતું નથી. સમર્થ ગુરુ સૌને પોતાની ઇચ્છા પ્રમાણે વર્તાવે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1453,"k":"para","g":"“ધાતુ, કાષ્ઠ, પાષાણ ને માટી - તેમાં એક પણ ઘાટ દેખાતો નથી, પરંતુ કુશળ શિલ્પી તેમાં અનેક ઘાટ રચે છે એવો તેનો પ્રતાપ છે. જગતમાં અનેક પ્રકારની ક્રિયા પ્રવર્તે છે, તેના પ્રેરક ગુરુઓ જુદા જુદા છે. તેવી જ રીતે મોક્ષદાતા ગુરુ જગતમાં એક જ પ્રગટ હોય છે. એ મોક્ષદાતા ગુરુને શરણે જે મનુષ્ય આવે છે, તે પછી ત્યાગી હોય કે ગૃહસ્થ - સર્વેને તે ભવસાગર પાર કરાવે છે. એ ગુરુના વચનમાં એવો પ્રતાપ રહ્યો છે કે એમના વચને જીવનાં અનંત જન્મોનાં પાપ છૂટે છે. સમર્થ ગુરુ વિના જીવને જન્મોનાં પાપથી રહિત કરવો અશક્ય છે. આ તેમની પ્રત્યક્ષ પરખ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1454,"k":"para","g":"“પાપ છૂટે તેની પરખ એ છે કે ગમે તેવો પાતકી હોય પણ આવા મોક્ષદાતા સદ્‌ગુરુની કૃપાદૃષ્ટિથી તેનું પરિવર્તન થઈ જાય છે. તેની મતિ ધર્મમાં રહેતી હોય. મોક્ષપ્રદ ધર્મનું પાલન તેને રુચે. મોક્ષરૂપ ભક્તિ પ્રિય લાગતી હોય તથા જ્ઞાન વૈરાગ્યમાં અતિ અનુરાગ હોય. તેણે કરીને તેની બધી ક્રિયા ગુરુપ્રતાપે પવિત્ર થઈ જાય છે અને અંતર-બાહ્ય શુદ્ધિ વર્તે છે. બાહ્યશુદ્ધિ હોય પણ અંતર મલિન હોય તો? પરંતુ મોક્ષદાતા ગુરુ જેને મળે છે તેની સઘળી ક્રિયામાં એક રાગ હોય છે. તે ક્રિયા જોવાથી માલૂમ પડે.”","e":null,"s":["12/19/10-24"],"sv":["जो जिनसे समर्थ हि होवे । ताकी वात विचारी के जोवे ॥\n\n तब ताकुं तेहि वात देखावे । ओरकुं नहि देखे में आवे ॥\n\n जो समर्थ जब आवत जेहा । निज साम्रथ तब जनवत तेहा ॥\n\n तेहि कर जिनमें साम्रथ जेता । देखाई प्रगट आवत तेता ॥\n\n ताके नजर में आवत जेसे । फेरवत सो वर्तन हि तेसे ॥\n\n वर्तन में जाकुं खप जेसो । प्रगट देखाई आवत तेसो ॥\n\n सोवर्ण में दैवत जितनो, अनल कसोटी जोउ ।\n\n कहि देवत हे तितनो, ता विन कहे न कोउ ॥\n\n वर्तन हे अनल कसोटी ही, वर्तन से जन हि जेसो ।\n\n देखे में आवत तर्त ही, तामें न रह हें अंदेशो ॥\n\n एक धर में धोरी, जोरे होत न परख तेहि ।\n\n विविध धर में जोरी, परखत होत हें जिमि जोउ ॥\n\n तेसे आश्रित जन, त्यागी गृही जो कहात तेहु ।\n\n प्रसन्न होई के मन, वर्तावहि गुरु समर्थ जोउ ॥\n\n सोवर्ण आदिक धातु में जेहा । तामें एक घाट नहि तेहा ॥\n\n काष्ट पाषाण मृत्तिका तामें । घाट एक न देखात यामें ।\n\n कपास में घाट देखात न एका । ताके गुरु जब मिलत विवेका ॥\n\n तब एक सें घाट अनेक रचावे । तेसे सम्रथ की रीत रहावे ॥\n\n जग में क्रिया हें अनेक प्रकारा । सबके गुरु हें न्यारा न्यारा ॥\n\n तेसे मोक्षदाता गुरु जोउ । प्रगट जग में एक हि सोउ ॥\n\n मोक्षदाता गुरु ताके जेहि । जे जन शरण आवत हें तेहि ॥\n\n त्यागी गृही जो जो जेता । भवतारन जनकुं होवत तेता ॥\n\n वचन में एसो रहे प्रतापा । अनंत जन्म के छोरावत पापा ॥\n\n समर्थ विन नहि पाप छुटावे । पाप छुटे सें परख हि पावे ॥\n\n पाप छुटे की परख हें एसा । धर्म में मति करत प्रवेशा ॥\n\n धर्म रुचे मोक्ष अनुसारी । मोक्षरुप भक्ति लगे प्यारी ॥\n\n मोक्षरूप ज्ञान वैराग्या । तामें अति होवे अनुरागा ॥\n\n तेहिकर दैहिक क्रिया जेती । पवित्र होइ जावत हे तेती ॥\n\n बाहिर शुद्ध अंतर मलीना । क्रिया में सो आवत चीना ॥"],"mt":false,"gl":null,"a":false},{"i":1455,"k":"para","g":"ઉમરેઠમાં વિદ્વાનોની સભામાં શ્રીહરિ કહે, “બ્રહ્મના ગુણ પાત્ર વિના ટકતા નથી. પાત્ર વિના આવે તો ઉન્મત્ત થઈ જાય. પાપ કે પુણ્ય બ્રહ્મને સ્પર્શતાં નથી તેમ છતાં એવા પુરુષ પાપમાત્રથી છેટે રહે છે. બીજાને પણ માંસ, મદિરા, પરસ્ત્રીનો સંગ આદિ પાપથી છોડાવીને નિર્ભય કરે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1456,"k":"para","g":"“વિષય પ્રાપ્ત થાય ત્યારે બ્રહ્મનિષ્ઠપણું પરખાય છે. બ્રહ્મના ગુણ જેમાં આવ્યા હોય તે પુરુષને વિષયમાત્ર અસાર થઈ જાય છે. બ્રહ્મજ્ઞાની જો વિષયાસક્ત હોય તો તે બ્રહ્મદ્રોહી છે ને મારો દ્રોહી છે એમ શ્રીકૃષ્ણ કહે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1457,"k":"para","g":"“એકથી લાખ સાધન કરે પણ તેનું ફળ એટલું જ છે કે વિષયથી રાગ તોડી, આત્મારૂપ થઈ પરમાત્માની ભક્તિ કરવી. આત્મનિષ્ઠ થઈ ભગવાનમાં પ્રીતિ કરે છે તેને અમે બ્રહ્મનિષ્ઠ કહીએ છીએ. આટલી વાત નવીન છે.”","e":null,"s":["12/53/6-14"],"sv":["पात्र विन ब्रह्म के गुन भारी । उन्मत्त होइ जावत नरनारी ॥\n\n पाप मात्र कहावत जेते । ब्रह्म कुं कहत अडे न तेते ॥\n\n मांस मदिरा परत्रिय संगा । निर्भय करत भये अभंगा ॥\n\n ब्रह्म को गुन हि हें एसा । विषय मारग न चलना तेसा ॥\n\n विषय में जब देखे असारा । तब ब्रह्म के गुन आये सारा ॥\n\n विषयासक्त ब्रह्मज्ञानी जोई । कृष्ण कहे मम दास न सोई ॥\n\n ब्रह्मद्रोही मम द्रोही तेहु । श्रीकृष्ण मुख से कहे एहु ॥\n\n एक से साधन बहु को, इतनो फल कहेउ ।\n\n विषय से तोडी राग सब, आत्मा होना तेउ ॥\n\n आत्मनिष्ठ होई कर, भगवान में करना प्रीत ।\n\n ब्रह्मनिष्ठ हम कहत तेहि, इतनी बात हि नवीन ॥"],"mt":false,"gl":null,"a":false},{"i":1458,"k":"para","g":"શ્રીહરિએ કહેલી વાત મુક્તમુનિએ કહી, “ગુરુનાં ધર્મયુક્ત વચન તે ગુરુરૂપે છે એમ માનવું. ગુરુરૂપી સૂર્ય વિના જે જ્ઞાન છે તે અંધારામાં દર્પણ ધરવા જેવું છે. કક્કો લખેલો હોય અને બે નેત્રથી જુએ છતાં કહેનાર ગુરુ ન હોય તો અક્ષરજ્ઞાન થાય નહિ. સત્પુરુષના સંગ વિનાનું જ્ઞાન, આંધળો આપમેળે માર્ગ પામવા મથે તેના જેવું છે. નિયમ-ધર્મ વિનાનાં જ્ઞાન બધે એવાં જ છે, જે દીવો લઈને કૂવામાં પડે છે. સાચા ગુરુ તેને જ્ઞાનનું નેત્ર ખોલી આપે છે. આંખો પણ હોય અને સૂર્ય પણ હોય છતાં નેત્રની જ્યોતિ ન હોય તો કંઈ દેખાતું નથી. ગુરુ જ્ઞાનની જ્યોતિ પ્રગટ કરી આપે છે, પછી માયિક વસ્તુમાત્ર તેને તુચ્છ થઈ જાય છે.”","e":null,"s":["13/58/33-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1459,"k":"para","g":"હળવદમાં નારાયણજી વિપ્રને ઘરે શ્રીહરિએ વાત કરતાં કહ્યું, “ગાઢ વનમાં ભોમિયા વિના અજાણ્યાને રસ્તો જડે નહિ, તેમ શાસ્ત્રના વિવિધ શબ્દો જોઈને પંડિતો પણ નહિ સમજીને નાસ્તિક થઈ જાય છે. મહાસિંધુ તરવો હોય તો આપ બળે તરાય નહિ. પાંખવાળાં પ્રાણીઓ પણ પાર થઈ શકે નહિ, પણ સિદ્ધ ગતિ પામેલા સાગરને ઉલ્લંઘી જાય છે. સિદ્ધ ગુરુ નાવ સમાન છે. નાવમાં બેસે તે સમુદ્ર તરે.”","e":null,"s":["15/3/29-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1460,"k":"para","g":"શ્રીહરિએ ગઢપુરમાં જીવેન્દ્ર નૃપને વાત કરતાં કહ્યું, “જેવા ગુરુ મળે એવા ગુણ પ્રાપ્ત થાય છે. લોભના પાશથી સૌ જીવ બંધાયેલા છે. ભવબંધન કરાવનારો લોભ છે. સાચા ગુરુ મળે તો ભવબંધન દૂર થાય.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1461,"k":"verse","g":"‘ભવબંધન દૂર ન હોત, સાચે ગુરુ કે જ્ઞાન બિન;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1462,"k":"verse","g":"ચિંતામનિ તન ખોત, ભવબંધન માનત નિધિ મહા.’","e":null,"s":["15/19/13-15"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1463,"k":"para","g":"શ્રીહરિએ ભૂપને કુશલકુંવરબાઈની વાત કરતાં કહ્યું, “સત્યને જાણ્યા વિના રાણીએ પોતાના રાજ્યમાં ધન-નારીમાં બંધાયેલાને ગુરુ કરી રાખ્યા અને તેનાથી મોક્ષ માન્યો હતો. પછી અમારા સાધુને જોઈ તેમને સત્ય-અસત્ય સમજાયું. રાણીએ સંસારથી બંધાયેલા કથાકારને કહ્યું, ‘મને એ વાતનું આશ્ચર્ય છે કે સ્ત્રી-ધનમાં બંધાયેલા ગુરુ હોય તે બંધાયેલાને કેવી રીતે છોડી શકે? નિર્બંધ ગુરુ મળે તો જ છોડાવે. બંધાયેલાને બાંધેલાએ છોડ્યો હોય તેવું મેં આજ સુધી જાણ્યું નથી. શિષ્ય અને ગુરુ બંને નેત્ર વિનાના અંધ હોય, તે એકબીજાને સહારે માર્ગ પર ચાલે પછી કૂવામાં જ પડે. તેમાં સંદેહ નથી.’ પછી તે કથાકાર આવીને સંતનાં ચરણમાં પડ્યો. અને કહ્યું, ‘તમારા જેવા સંત આજ સુધી અહીં આવ્યા નથી.’”","e":null,"s":["16/36/18-29"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1464,"k":"para","g":"ઉગામેડીના પટેલને શ્રીહરિ કહે, “લૌકિક ગુરુ મળે તે લૌકિક વાત શીખવે. એ પોતે જ અલૌકિક વાત સુણી ન શકે તો તેના શિષ્ય ક્યાંથી તે સાંભળે! અલૌકિક ગુરુના મુખે અલૌકિક વાત સાંભળે ત્યારે મોક્ષ થાય છે. તે વિના મોક્ષ ક્યારેય થાય નહિ.”","e":null,"s":["16/43/34-35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1465,"k":"para","g":"શ્રીહરિએ ભાઈરામદાસજી પર પત્ર લખ્યો એમાં કહ્યું, “સ્ત્રી, ધન અને પંચવિષય પર જેને તાન હોય તે કુસંગી ગુરુ છે. એવાનો યોગ થાય તો મુમુક્ષુની શુભમતિ પલટાઈને અશુભ થઈ જાય છે. વિષયી ગુરુ તો પથ્થરની નાવ જેવા છે. તે પોતે તો ડૂબે છે, પણ પોતાને વળગેલાને પણ ડુબાડે છે.”","e":null,"s":["16/50/38-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1466,"k":"para","g":"કરજીસણમાં શ્રીહરિએ ગુરુના સાધુસ્વભાવની વાત કરતાં કહ્યું, “મનનું રાજ્ય હોય ત્યાં સુધી જન્મમરણ ટળે નહિ. જ્યારે ગુરુ કહે તેમ કરે ત્યારે મનનું રાજ્ય રહેતું નથી. ગુરુ બધી મોક્ષની વાત જાણે છે. તે ભગવાનને ઓળખે છે. હરિથી અધિક કાંઈ માનતા નથી. વિષમ દેશકાળમાં પણ જેમની એકની એક મતિ રહે, પણ રંગ પલટાય નહિ તે સાચા ગુરુ કહેવાય. જ્યાં લગી રંગ પલટાય છે, ત્યાં સુધી ગુરુમાં કચાશ છે.”","e":null,"s":["18/21/19-22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1467,"k":"para","g":"આદરજમાં રતુ ખાંટને ઘરે શ્રીહરિએ હરિભક્તોને વાત કરતાં કહ્યું, “ગુરુ વિના કોઈ વાતનું જ્ઞાન થાય નહિ અને અજ્ઞાન ટળે નહિ અને મહામાયાના અંધારે અટવાયા કરે. ભગવાન વિના બીજામાં સુખ જણાય છે તે જ દુઃખ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1468,"k":"para","g":"“સાચા સંત મળે છે તે મોક્ષનો માર્ગ દેખાડે છે. તેમનામાં અપાર વિદ્યા રહી છે. તેમાં મોક્ષની વિદ્યા અધિક છે, તે શીખવે છે. મુમુક્ષુ મોક્ષને માર્ગે ચાલે નહિ ત્યાં સુધી તેને એક પણ વાત તે કરતા નથી. ભગવાન સિવાય સઘળું અસાર કરી દેખાડે તે સાચા સંત છે. જે ભગવાન અને જગતને સમાન કહે છે તે ગ્રંથ અને સંત અસત્ જાણવા.”","e":null,"s":["18/32/20-24"],"sv":["गुरु बिन कोउ बात के ज्ञाना । होवत नहि रहत अज्ञाना ॥\n\n हरि बिन देखत ओर में सुखा । सुख एहि रहाये दुःखा ॥\n\n साचे संत मिलतहि जबहि । मोक्ष के मग देखावत तबहि ॥\n\n विद्या अपार रहेउ तामें । मोक्ष की विद्या अधिक हें यामें ॥\n\n जो जो बात रहाये तिनमें । मोक्ष मग अधिक रहे इनमें ॥\n\n मोक्ष के मग न चले जिहां लगहि । एक बात न किये तिहां लगहि ॥"],"mt":false,"gl":null,"a":false},{"i":1469,"k":"para","g":"લોયામાં સંતો સન્મુખ શ્રીહરિ પોતાના હૃદયની વાત ફરી કહેવા લાગ્યા, “સમર્થ ગુરુ હોય તે દેશકાળમાં લોપાય નહિ. વિષમ દેશકાળે પણ પોતાનું દૈવત ઝાંખું ન પડે. દૈવત વગરનો હોય તે દેશકાળમાં લેવાઈ જતો હોય એવાનું વચન કોઈ ન માને. ગુરુમાં દેખાતું એ દૈવત ધર્મનું છે, ભક્તિનું છે, જ્ઞાન-વૈરાગ્યનું છે. આ ચારે ગુણ ગુરુમાં સંપૂર્ણપણે દેખીને મોક્ષના ખપવાળો શિષ્ય તેનું વચન માને છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1470,"k":"para","g":"“ગુરુને પણ ધર્માદિનો ખપ હોય છે. ખપ વગરનો ગુરુ ‘ગુરુ’ કહેવાય નહિ. ધર્મપાલનનો ખપ હોય એવા ગુરુ અને શિષ્ય બન્ને મળવા દુર્લભ છે. એવા ગુરુ સૂર્ય સમાન છે. કનક-કામિનીરૂપી સિંધુમાં દેવ, મનુષ્ય ને પ્રાણી સર્વે ડૂબકાં ખાય છે, દુઃખ ભોગવે છે, તેને ઉગારનાર આવા ગુરુ છે. ગુરુ તેને સત્ય વાતનું ભગવાનનું જ્ઞાન આપે છે, કારણ કે એના હૃદયમાં સ્પષ્ટ છે કે જેમાં ભગવાનનો સંબંધ નથી તેમાં દુઃખ જ ભર્યું છે. જેટલું કંઈ સુખ છે તે ભગવાનની વાતમાં રહ્યું છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1471,"k":"para","g":"“સાચા ગુરુને જીવનો મોક્ષ કરવાનું જ એક તાન હોય છે. અને જે જીવ મોક્ષનું જતન કરે તેને જ તે બુદ્ધિશાળી માને છે.”","e":null,"s":["24/51/1-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1472,"k":"para","g":"પંચાળામાં શ્રીજીમહારાજે સાચા ખોટા ગુરુની વિક્તિ સમજાવતાં કહ્યું, “સાચા ગુરુ મળે ને તેને સન્મુખ થાય તો દોષમાત્ર ટાળી દે. સાચા ગુરુ વિના મોક્ષનો સાચો માર્ગ કોટિ યુગે પણ મળે નહિ. મોક્ષની ઇચ્છા હોય તેણે સાચા ગુરુની કીર્તિનું (મહિમાનું) ગાન કરવું. ડહાપણ તજી નિષ્કપટ થઈ ગુરુ કહે તેમ કરવું. જે સાચા ગુરુ છે તે ભગવાન સાથે નેહ દૃઢ કરાવે છે. સુખમાત્ર શ્રીહરિમાં દેખે છે.”","e":null,"s":["25/40/34-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1473,"k":"para","g":"શ્રીહરિએ મોક્ષદાતા ગુરુનાં લક્ષણ મુક્તમુનિને કહેલાં તે તેમણે ઉત્તમ નૃપને કહેતાં કહ્યું, “ઇન્દ્રિયો-અંતઃકરણને જેણે જીતી લીધાં છે એવાને કોઈથી જીતી ન શકાય, એવા અજીત ગુરુ જ્યાં છે ત્યાં કલ્યાણ રહ્યું છે. એવા ગુરુ સમાગમે કરીને ઓળખાય છે. લોભને જીતી લીધો છે તેણે કરીને મોક્ષદાતા ગુરુનું દૈવત જાણ્યામાં આવે છે.”","e":null,"s":["26/27/33-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1474,"k":"para","g":"શ્રીહરિએ વસોમાં વાત કરતાં કહ્યું, “જેટલા ગુરુ અને શિષ્ય ધર્મ-નિયમ રહિત છે તેને ઠગ જાણવા. ભગવાનના સાચા ભક્ત જે સત્પુરુષ છે તેમનાં વચનને સત્યપણે ગ્રહણ કરી સત્પુરુષના માર્ગે જો ચાલે તો તેનો ઉદ્ધાર થાય.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1475,"k":"verse","g":"‘ભગવાનહુ કે જેહુ, ભક્ત લાયે રહેઉ યહ,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1476,"k":"verse","g":"ગુરુ-શિષ્ય હિ જેતેઉ, નિયમ બિન રહે ઠગહિ સબ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1477,"k":"verse","g":"સત્પુરુષ હિ તાકે, સત્ય બચન રહેઉ બહુત,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1478,"k":"verse","g":"ચલત મગ જબ વાકે, ઉધ્ધાર હોવત રહે તબ.’","e":null,"s":["(26/39/15-16)"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1479,"k":"para","g":"સુરતમાં શ્રીહરિ કહે, “ગુરુ થઈને શિષ્યને સાચી વાત દેખાડે નહિ તે ગુરુ પથ્થરના વહાણ સમાન છે.”","e":null,"s":["(27/48/19)"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1480,"k":"para","g":"શ્રીહરિ સુરતથી આવીને ગઢપુરમાં વિરાજ્યા અને સુરતમાં રહેલા ભૂમાનંદ અને ગોવિંદાનંદ વગેરે સંતો પર પત્ર લખાવ્યો, તેમાં કહ્યું, “જે ગુરુ ધર્મ રાખે અને રખાવે તે જ સાચા ગુરુ કહેવાય. ધર્મ વિનાના ગુરુ તથા સંપ્રદાય શબની સમાન જાણવા. ગુરુ થતાં પહેલાં ગુરુના ધર્મ જાણવા જરૂરી છે. તે શ્રીકૃષ્ણે ભાગવતના એકાદશના સ્કંધમાં પ્રભાસમાં ઉદ્ધવ પ્રત્યે હેતે કરીને કહ્યા છે. એમાં કહેલી વાર્તા પ્રમાણે સાચા ગુરુને પરખવા. જેને ભગવાનના સ્વરૂપનું, બ્રહ્મનું જ્ઞાન નથી એવા ગુરુ બની બેસે તો નિત્ય એક બ્રહ્માંડનો નાશ કર્યાનું પાપ તેને લાગે છે. સ્ત્રીનો સંગ કરનાર ગુરુને રાજા પણ કપાળમાં બળબળતો ડામ દઈ તડીપાર કરે છે. કામી ગુરુને કૂતરા જેવા કહ્યા છે, લોભીને ચાંડાલ કહ્યા છે. તેનો સંગ કરનારને વારંવાર કાળ કોળિયો કરે છે.”","e":null,"s":["(28/5/18-26)"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1481,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1482,"k":"para","g":"મુક્તમુનિએ ઉત્તમ નૃપને શ્રીહરિએ કહેલી વાત કરતાં કહ્યું, “ભગવાનની વાત ગુરુથી સમજાય છે. તેમાં પણ જેને જેટલી આસ્તિકતા ને મોક્ષનો ખપ હોય તેને તેટલી તે વાત સમજાય છે. દેશકાળની વાતનો પાકો અભ્યાસ હોય તે જ્ઞાની ગુરુ છે, એવા ગુરુ કોઈક જ હોય છે.","e":null,"s":["1/72/37-38"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1483,"k":"verse","g":"‘નૃપ યહ બાત કરત મેં જોઈ, તાકી ગમ નહીં હેં કોઈ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1484,"k":"verse","g":"શ્રીહરિ મો પર કૃપા કીને, જિતની બાત સો જનાઈ દીને.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1485,"k":"verse","g":"સો મેં કહત હૂઁ નૃપતિ તોઈ, જિતની સ્મૃતિ હરિ દિયે મોઈ.’","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1486,"k":"para","g":"મુક્તમુનિ કહે છે, “હે નૃપ! હું જે આ વાત કરું છું તેની કોઈને ગમ નથી. શ્રીહરિએ મારા પર કૃપા કરી જે કંઈ મર્મની વાત હતી તે મને કહી દીધી છે. તેમાંથી જે કંઈ મારા સ્મરણમાં છે તે તમને કહું છું:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1487,"k":"para","g":"“અગમ વાત કહેવી દુષ્કર છે. એ બધાના અંતરમાં બેસતી નથી. જે આસ્તિક છે, મોક્ષના ખપવાળો છે, સુબુદ્ધિ છે, કપટ-કુટિલતાથી રહિત છે તેને આ વાત તરત મનાઈ જાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1488,"k":"para","g":"“શ્રીહરિએ મને કહ્યું હતું કે પરાવિદ્યા - બ્રહ્મવિદ્યા સર્વ કળાઓમાં કઠણ કળા છે. બ્રહ્મનિષ્ઠ ગુરુ થકી બ્રહ્મવિદ્યા પ્રાપ્ત થાય છે. એ વિદ્યા શીખવાનો વિચાર આવવો જોઈએ. સાથે બ્રહ્મનિષ્ઠ ગુરુ મળવા જોઈએ. દેશ, કાળ આદિ વાતનો જેને પરિપક્વ અભ્યાસ હોય એવા ગુરુને બ્રહ્મનિષ્ઠ જ્ઞાની જાણવા. બ્રહ્મનિષ્ઠ સિવાયના અન્ય ગુરુઓ ગર્દભ તુલ્ય જાણવા, જેમ ગર્દભનો શબ્દ સુણી ત્રાસ ઊપજે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1489,"k":"para","g":"“જ્ઞાન આવડ્યું તે ગુરુ તો કહેવાય, પણ બ્રહ્મનિષ્ઠ ગુરુના ગુણ તેનાથી જુદા જ છે. હરિ એવા ગુરુમાં પ્રગટ રહે છે. તેને ઓછા મનુષ્ય પરખી શકે છે. હીરાના પરખુ ઝવેરી કોઈક જ હોય, વધુ ન હોય. હરિ પ્રગટ હોય ત્યારે કોઈ વાતનો મેળ રહે નહિ. એક જ એ એવા છે કે પોતે જે ચાહે તે કરવાને સમર્થ છે. સમર્થને કોઈ મેળ ન હોય તે જે કરે તે બધું સત્ય જ સત્ય થાય છે. બીજો કોઈ એની દેશી કરી શકે નહિ. દેખાદેખીથી પણ એમના જેવું કરી ન શકે. કરવા જાય તો હાંસી થાય. લોકમાં પણ દેખાય છે કે જે માપનું પાત્ર હોય તેમાં તેટલું જ સમાય, માપ્યા વિના તેમાં કોઈ વસ્તુ ભરીએ તો તે સહેજે ઊભરાઈને બહાર પડે છે.”","e":null,"s":["1/72/29-42"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1490,"k":"para","g":"ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ - આ ચાર જેનામાં દૃઢપણે હોય તેવા ગુરુ થકી પૂર્વજન્મનાં પાપ બળે છે. જેમ રાત્રિનો અંધકાર સૂર્ય વિના ન ટળે, તેમ એકાંતિક ગુરુ વિના પૂર્વ જન્મનાં પાપ ન બળે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1491,"k":"verse","g":"‘ભક્તિ વૈરાગ્ય અરુ જ્ઞાન, ધર્મ જુત ગુરુ હોત જેહિ;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1492,"k":"verse","g":"તિનસે હોત પાપ હાન, સૂર્ય જ્યું તમકું હરત સબ.’","e":null,"s":["4/108/3-4"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1493,"k":"para","g":"શિષ્ય લોકનિંદિત પાપકર્મ કરે તો ગુરુએ તેને પંક્તિ બહાર કરવો, નહીં તો તેનું પાપ બધાને લાગે. ગુરુએ શિષ્યને પ્રાયશ્ચિત્ત કરાવવું. અને જો તે પોતાનું વચન ન માને તો તેવા શિષ્યોનો ત્યાગ કરવો, પણ તેની સાથે વૈર ન કરવું. તેમજ પાપી શિષ્યોનો લોભ ન રાખવો. શાંતિથી તેનો ત્યાગ કરવો. વૈર કરે તો વધુ બગાડ થાય. ગુરુએ બધાયનો મોક્ષ સુધરે તેવો ઉપાય કરવો. બીજા જનો જે કહે તથા પોતાને જે ભાસે તે બન્નેનો વિચાર કરી ગુરુએ કરવું. પ્રીતિ રાખી શિષ્યને ધર્મ પળાવવા અને જીવ ઉપર દયા કરવી. સમુદ્ર, મેઘ અને આકાશની પેઠે ગુરુએ મોટા દિલના, નમ્ર, નિર્લેપ અને સર્વના હિતકર્તા બનવું. પિતાનું જેમ અપાર દ્રવ્ય હોય તેને કપૂત ઉડાડી દે, પછી ભીખ માંગવી પડે, તેમ બ્રહ્મવિદ્યાની ગાદી પર બેઠેલા ગુરુ બ્રહ્મવિદ્યા વિનાના હોય તો ધીરે ધીરે ક્ષીણ થઈ જાય. જેનું દ્રવ્ય સંત, હરિભક્ત, વિપ્ર અને ભગવાનને અર્થે વપરાયું તે જ ખરું દ્રવ્ય કમાયા છે. બીજાનું ધન તો નિર્બીજ છે. તેમ બ્રહ્મવિદ્યા વિનાના ગુરુ નિર્બીજ છે. તેમના શિષ્યો પણ તેમની દેશી શીખે. ગુરુ લોભી હોય તો તે પણ લોભી થાય. ક્રોધી-કામી હોય તો તેવા ગુણો શિષ્યોમાં આવે. બેય મોક્ષનો માર્ગ ભૂલ્યા છે. એક આંધળો છે ને બીજો બહેરો છે. બહેરાએ આંધળાનો વિશ્વાસ રાખ્યો છે, તે ખાડામાં લઈ જઈને નાખે કારણ કે તેને રસ્તો દેખાતો નથી. આ સત્સંગમાં જેવા ગુરુ છે તેવા ચૌદે ભુવનમાં નથી. જેનાં ભાગ્ય ઉદય થયાં હોય તેને તે ગુરુ મળે.","e":null,"s":["8/60/15-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1494,"k":"para","g":"જેવા ગુરુ હોય તેવા તેના શિષ્ય પાકે. ગુરુ વૃક્ષ છે તો શિષ્ય તેનાં ફળ-ફૂલ છે. ફળ-ફૂલના ગુણ જોઈ વૃક્ષના ગુણ પર દૃષ્ટિ જાય છે. જેના પર અમૃતફળ પાકે તેનો મહિમા જુદો જ કહેવાય. વિષફળ જોઈ તેવા વૃક્ષથી સૌ દૂર રહે છે. તે જ રીતે ગુરુની પરીક્ષા તેના શિષ્ય પરથી થાય છે. સંસારમાં પ્રીતિ કરાવવાવાળા ગુરુઓ ઠેર ઠેર અપાર છે. પશુ-પંખીથી લઈ બ્રહ્માંડના દેવો-દૈત્યો ને મનુષ્યો સૌને સંસારમાં પ્રીતિ છે. અને એ પ્રીતિને જ ભવબંધન કહ્યું છે - એવી પ્રીતિ ભગવાનમાં થઈ જાય તેનું જન્મમરણ અને સર્વવ્યાધિ ટળે છે. એ પ્રીતિ કરાવનાર ગુરુ પરબ્રહ્મરૂપ છે એ વિના બીજા જે કંઈ ગુરુઓ છે તેને ઉદર ભરવાનું તાન છે. વળી, તેના શિષ્યોને પણ એવું જ ઉદરભરણનું તાન છે. માટે એવા ગુરુ અને શિષ્યને પશુ સમાન જાણવા.","e":null,"s":["9/11/7-13"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1495,"k":"para","g":"સત્સંગના જેટલા નિયમ છે તેમાં તત્પર રહેતા હોય અને જે રીતે ભગવાનનાં વચન છે તેમાં ફેર ન પાડતા હોય એવા ગુરુવરને સેવે ત્યારે મોક્ષ થાય. ગુરુ પર શિષ્યનો જેવો ભાવ રહે તેટલી સંભાવના ગુરુ કરે. ગુરુ-શિષ્યનો પરસ્પર સ્નેહ દિન-પ્રતિદિન તો જ વધતો રહે, જો શિષ્ય ગુરુ પાસે નિષ્કપટ વર્તે. જે શિષ્ય મન ચોરે છે તે ઘટતો ઘટતો અતિશય ઘટી જાય છે. ગુરુનાં લક્ષણ યથાર્થ હોય તે સાચા ગુરુ કહેવાય. ત્યાગીની રીત ત્યાગી રાખે અને ગૃહસ્થની રીત ગૃહસ્થ રાખે. બન્ને પ્રકારના ગુરુ શાસ્ત્રમાં પ્રસિદ્ધ છે. તેમાં ધન-સ્ત્રીવાળા જે ગુરુ છે તે ભવ-બ્રહ્મા સમાન સમર્થ હોય તોપણ બદ્ધ ગુરુ કહેવાય છે. બદ્ધગુરુથી જનોનાં બંધન તૂટી ન શકે એ શાસ્ત્રનો સિદ્ધાંત છે.","e":null,"s":["9/23/25-31"],"sv":["नियम सत्संग के जितने, तामें रहि तत्पर ।\n\n हरि के वचन जिसविध, तेंसे सेवे गुरुवर ॥\n\n जेसे सेवक को भाव हि, गुरु उपरि रहाय ।\n\n तेसे गुरु तेहि शिष्य की, संभावना रखे सदाय ॥\n\n गुरु-शिष्य को नेह, दिन-दिन सो बढत अति ।\n\n तामें मन चोरे जेह, तब सो घटत घटत अति ॥\n\n गुरु के लच्छन यथार्थ जेहा । पाले सो साचे गुरु तेहा ॥\n\n त्यागी की रीत सो त्यागी रहावे । शास्त्र में प्रसिद्ध सो कहावे ॥\n\n तामें धन त्रिय वंत गुरु जेही । भव ब्रह्मा सम समर्थ तेहि ॥\n\n तोहु बंधे गुरु कहावत तेहु । शास्त्र को सिद्धांत सब एहु ॥"],"mt":false,"gl":null,"a":true},{"i":1496,"k":"para","g":"જગતમાં જે ગુરુ થઈને બેઠા છે, પણ મોક્ષનું રહસ્ય નથી સમજતા તો તે ઘોર અંધારા જેવા છે, અને નિયમ-ધર્મનો અભાવ હોવાથી જમપુરીમાં જાય છે. જેવો ગુરુનો મોક્ષ થાય, તેવો જ શિષ્યનો પણ થાય. આમાં કાંઈ પણ સંશય નથી, તે પ્રત્યક્ષ જણાય છે. જે ગુરુને ભગવાનનું યથાર્થ જ્ઞાન હોય, પોતે ધર્મ-નિયમમાં દૃઢ વર્તે અને શિષ્યને પણ વરતાવે. એવા ગુરુ પોતાનો અને શિષ્યનો ઉદ્ધાર કરી શકે, એમાં સંશય નહિ. એવો જ્યાં સત્સંગ હોય ત્યાં શ્રીહરિ અવશ્ય પ્રગટ હોય છે. જેટલું જેમાં દૈવત હોય તે આચરણે કરીને દેખ્યામાં આવે. ચક્રવર્તી નામ પાડ્યું તેથી ચક્રવર્તી થાય નહિ. ગુરુ અને સંત નામ પડવાથી તેવા થવાતું નથી. જેમ સૂર્યનો પ્રકાશ જ સૂર્યનું પ્રમાણ છે તેમ સાચા ગુરુનું પ્રમાણ તેમનામાં રહેલા સદ્‌ગુણો છે.","e":null,"s":["9/24/17-27"],"sv":["गुरु होई बैठे जग में जेहा । रहस्य न समझे मोक्ष को तेहा ॥\n\n सो गुरु अंध हि तम कहावे । नियम धर्म विन जमपुर जावे ॥\n\n गुरु के मोक्ष हि होवत जेसा । शिष्य के मोक्ष हि होवत तेसा ॥\n\n यामें संशय कछु न रहाये । सो कहत नजर हि देखाये ॥\n\n गुरु कुं जथार्थ होय हरिज्ञाना । धर्मनियम ता पर होय ताना ॥\n\n धर्मनियम में शिष्य कुं चलावे । आपे वर्ते शिष्य कुं वरतावे ॥\n\n ऐसे गुरु शिष्य को होत उद्धारा । यामें संशय नहि लगारा ॥\n\n ऐसो सत्संग होवे जेहि ठोरा । हरि निश्चय प्रगट तेहि कोरा ॥\n\n आचरण करि देखे में आवे । जेतो जामे दैवत रहावे ॥\n\n चक्रवर्ति करि के जो नामा ॥ चक्रवर्ति न होत कोउ ठामा ॥\n\n हरि किये हरि होत नहि, गुरु किये गुरु न होत ।\n\n संत भये संत न होत हि, गुन कर होत उद्योत ॥\n\n जेसे गुन रहे जाहि में, एसी हे वात अपार ।\n\n तेसे प्रकाश हि होत तेहि, सूर्य जैसे उजियार ॥"],"mt":false,"gl":null,"a":true},{"i":1497,"k":"para","g":"સૌ જનનું કલ્યાણ ઇચ્છે, પોતાનું કોઈ બૂરું કરે તેનું પણ હિત ઇચ્છે, તે ઉત્તમ ગુરુ છે ને તેવા જનો શ્રીહરિને અતિ વહાલા છે. શ્રીહરિ તેમની પાસે જ રહે છે. આવા ગુરુ કુટિલતા, ઈર્ષ્યા, મત્સર આદિથી રહિત તથા નિષ્કપટ, નિર્દંભ, નિષ્કામ, નિર્લોભ આદિ ગુણોથી યુક્ત હોય છે ને તે જ પરમ ગુરુ ગણાય. તેનાથી જીવોનું કલ્યાણ થાય. તેવાને ભગવાન સમીપમાં છે. બીજાને દેખાય કે ન દેખાય તો પણ ભગવાન એમની પાસે છે એ અનુભવ સૌને થાય છે. ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ અર્થાત્ એકાંતિક ધર્મના એ ધારક છે. અને ધન-સ્ત્રીનો ત્યાગ રાખે એ જ સાચો ત્યાગી છે. આ ઉદ્ધવ સ્વામીનો મત છે તે અમને પ્રિય લાગે છે.","e":null,"s":["9/26/23-35"],"sv":["सब जनको कल्याण हि इच्छे । जो जन आई प्रीत से पीछे ॥\n\n आपको बुरो करन कोउ धारे । तोहु ताको हित विचारे ॥\n\n हरि कुं लगत सो प्रिय भारी । देखत समीप तेहि वार हि वारी ॥\n\n निष्कपट निरदंभ हि, कुटिलता नहि मन लेश ।\n\n ईर्षा मत्सर विन मान हि, धर्म जुक्त विन क्लेश ॥\n\n निष्काम रहे निर्लोभ, निःस्पृह रहे सरल चित्त ।\n\n निःस्वाद इन्द्रि सब माहि, परम गुरु के चिह्न यह ॥\n\n ताके मन जो वचन, श्रीहरि मोक्ष सो करत तेहि ।\n\n होवत अति प्रसन्न, मोक्षरूप गुन हि जानिकर ॥\n\n मोक्षरूप गुन के जेहा । जन को मोक्ष हि होवत तेहा ॥\n\n कल्यान मोक्षधाम एक कहावे । नाम करि भिन्न भिन्न रहावे ॥\n\n सब के कारन हें हरि प्रधाना । शुद्ध धर्म तहां हरि रहाना ॥\n\n दूर जो निकट हरि रहत तब हि । ज्ञानी गुरु सो जानत सब ही ॥\n\n दूर निकट हें भक्त के भावा । भाव तेंसे आवत देखावा ॥\n\n निकट देखावो न देखावो कबहु । निकट तोकुं हरिकुं देखत दिलहुं ॥\n\n ताके निकट हरि को वासा । प्रेमीजन जानत ऐसे दासा ॥\n\n उद्धव स्वामी को मत है जेहु । हमकुं प्रिय लगत हे तेहु ॥\n\n धर्म, भक्ति, ज्ञान, वैराग्या । धन त्रिय ही त्यागी कुं हे त्यागा ॥\n\n जथार्थ शास्त्र में कहे जेहि भाँति । शुद्ध रीत जो यामें रहाती ॥"],"mt":false,"gl":null,"a":true},{"i":1498,"k":"para","g":"નારી-પુત્ર અને સમૃદ્ધિ સુખ માટે મિથ્યા ગુરુને લોકો પૂજે છે. જે માયાનું સુખ ઇચ્છે છે તે સર્વે માયિકજનોને આવા માયિક મિથ્યા ગુરુ મળી જાય છે. મિથ્યા ગુરુ પોતાનું પેટ ભરવા મૂર્તિને પૂજે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1499,"k":"para","g":"શ્રીહરિ સર્વોપરી ભગવાન છે, તેના તુલ્ય અવર બીજો થઈ શકવાને સમર્થ નથી, છતાં તેને સમાન બીજાને કહે છે તેને મિથ્યા ગુરુ જાણવા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1500,"k":"verse","g":"‘સર્વોપરિ ભગવાન હિ, તા સમ અવર ન કોઈ;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1501,"k":"verse","g":"હરિ સમ કહે અવર જેહિ, મિથ્યા ગુરુ હેં તેહિ.’","e":null,"s":["11/70/33-37"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1502,"k":"para","g":"ગુરુ બે પ્રકારના છે - લૌકિક અને અલૌકિક. જેને સત્સંગ થાય છે તેને આ ભેદ દેખ્યામાં આવે છે. લૌકિક ગુરુને જે વળગે છે તે શિષ્ય લૌકિક જેવા જ રહે છે. તેમાંથી કોઈને પણ એકેય નિયમનું પાલન હોતું નથી. મોટો મહેલ હોય પણ અંદર ક્યાંય દીપકનો પ્રકાશ ન હોય તો તે શોભતો નથી એમ લૌકિકની રીત જાણવી. જેને વિવેક દૃષ્ટિ છે, તેને સત્ય-અસત્ય યથાર્થપણે દેખાય છે.","e":null,"s":["13/30/21-24"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1503,"k":"para","g":"જેના અંતરમાં શુદ્ધ મોક્ષનો અંકુર ઉદય થાય છે તે નિયમ-ધર્મ વિનાના ગુરુને પાપી સમજીને તેનાથી દૂર રહે છે. નિયમધર્મયુક્ત ગુરુને પ્રગટ શ્રીહરિ પર એક તાન રહે છે. તેઓ ભગવાનને સદા સાકાર માને છે. એવા ગુરુ મોક્ષના દાતા છે.","e":null,"s":["13/41/36-37"],"sv":["नियमधर्म विन जितने जेहि । गुरु देखे में आवे तेहि ॥\n\n ढिमर सम देखत सो पापी ताकु । शुद्ध अंकुर उर रहे जाकुं ॥\n\n नियमधर्म जुत जितने, प्रगट हरि पर तान ।\n\n साकार रूप कुं मान हि, सो गुरु मोक्ष आन ॥"],"mt":false,"gl":null,"a":true},{"i":1504,"k":"para","g":"ભરતખંડ કર્મભૂમિ છે. તેમાં જીવને મનુષ્યતન મળે છે ત્યારે મોક્ષ સરળ બને છે. સંત તેને જ્ઞાનરૂપી નેત્ર લગાડી આપે છે. ગુરુ અને સંત બન્ને એક છે. તેના વચનમાં વર્ત્યો જાય તે પરમપદને પામે છે.","e":null,"s":["14/27/29-30"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1505,"k":"para","g":"જે ગુરુ ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ રહિત હોય તો તેને તૂટેલા વહાણ જેવો જાણવો. ફૂટેલું નાવ સાગર પાર કરતું નથી, વચ્ચે જ ડુબાડે છે, તેમ એવા ગુરુને જે વળગે છે તેને જન્મમરણ, ચોરાશી ને જમપુરીમાં દુઃખ ભોગવવાં પડે છે.","e":null,"s":["19/4/9-12"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1506,"k":"para","g":"અજાણ્યે પણ સાચા સંતની સેવા થઈ જાય તો તેની સહાયતા થાય છે, પણ સાચા સંતની સેવા ભાગ્ય વિના મળતી નથી. એની સેવા મળે તો તેમાં સાધનમાત્ર આવી ગયાં.","e":null,"s":["19/4/14-16"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1507,"k":"para","g":"જ્ઞાન વિનાના ગુરુ તો નરકનું દ્વાર છે. વિષયમાત્ર તેમાં રહ્યા હોય છે, એવાને હજારો લોકો ગુરુ માને છે અને અભાવ લેતા નથી. જે ગુરુ વિષયનું ખંડન કરી તેમાંથી પ્રીતિ તોડાવતા હોય તેને સાચા ગુરુ કહેવાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1508,"k":"para","g":"વિષય ઉપર દોડ રાખે તે ગુરુ ને શિષ્ય બન્ને બંધનમાં છે. જેટલા વિષયથી દૂર રહે એટલો તેમાં ભગવાનનો નિવાસ થાય છે ને એટલું અજ્ઞાનરૂપી અંધારું દૂર થાય છે.","e":null,"s":["19/31(30)/23-28"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1509,"k":"para","g":"ભગવાન અને સાચા સંત વિષયીજનને મળવા દુર્લભ છે, કારણ કે વિષયીજન વિષયમાં જ સુખ માને છે ને વિષય માટે જ જપ-તપાદિ કરે છે. મરણનો ભય ત્યાગ કરીને વિષય માટે પરદેશમાં જવા જહાજમાં બેસી સમુદ્ર ઓળંગે છે. કેટલાંય વહાણ ડૂબે છે, પણ તેનો ડર રાખતા નથી.","e":null,"s":["19/32(31)/13-19"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1510,"k":"para","g":"કેટલાય પ્રકારના ગુરુઓ છે તેમાં મોક્ષના દાતા ગુરુને ઓળખવા તે કઠણમાં કઠણ વાત છે. નિર્બંધ ગુરુ મળવા દુર્લભ છે. જેને શ્રીહરિ સિવાય બીજી વાત ન હોય તે સર્વોપરી ગુરુ છે. એવા ગુરુ વિના બીજા ગુરુઓ બધા જ વ્યાવહારિક જાણવા. વ્યાવહારિક ગુરુથી મોક્ષ ન થાય.","e":null,"s":["20/66/25-28"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1511,"k":"para","g":"સાધુતાની રીત લોપે નહિ, સાધુતામાં જ હિત માને, એ સાચા સંત છે. તે ભગવાનને સર્વથી અધિક દેખે છે. એવા સંતમાં ભગવાન નિવાસ કરીને રહે છે. એકપળ પણ તેમનાથી દૂર જતા નથી. ભગવાનનો નિવાસ એ સંતમાં છે એ તેમના વર્તનથી સૌને પ્રત્યક્ષપણે જણાઈ આવે છે. એ સંતની આંખોમાં અને વચનમાં પણ ભગવાનનો વાસ દેખાઈ આવે છે. પોતે પદાર્થ માટે ક્યારેય ક્ષોભ કરતા નથી. પોતાને જનો માને કે ન માને, તેણે કરીને પોતાની સ્થિતિમાં ફેર પડતો નથી. પોતાની પ્રતિષ્ઠા વધારવા ક્યારેય વિચાર કરતા નથી. સંતો-ભક્તોની પ્રતિષ્ઠા વધે એવો પ્રયત્ન દિન દિન પ્રત્યે કરે છે, તેમાં મગન રહે છે. જ્ઞાનનાં દ્વાર ખોલે છે.","e":null,"s":["22/43/30-35"],"sv":["संतता कि लोपत न रीता । संतता में जेहि मानत हिता ॥\n\n संत साचे रहे जो जेता । भगवानकुं अधिक देखत तेता ॥\n\n भगवानकुं अधिक जिहां लगहि । देखत संत तिहां लगहि ॥\n\n भगवान तामें निवास करीता । पलक एक न दूर रहिता ॥\n\n भगवान निवास करत जामें । प्रगट देखावत वरतन तामें ॥\n\n नैन बेन में आत देखाई । पदार्थ हित न क्षोभ कराई ॥\n\n जन मानो न मानो कोई । जन ताके माने कहा होई ॥\n\n प्रतिष्ठा आप कि जो लगारा । बढावन हित न करत विचारा ॥\n\n संत हरिजन कि प्रतिष्ठा जीमि । दिन दिन अधिक बढे तिमि ॥\n\n मगन मगन मन रहे अपारा । ज्ञान ताके जेहि खोले द्वारा ॥"],"mt":false,"gl":null,"a":true}]},{"n":20,"gu":"ત્યાગી સાધુ","en":"The Tyāgī Sādhu — The Renunciant","url":"https://www.anirdesh.com/pbp/index.php?page=chp_20","b":[{"i":1512,"k":"para","g":"શ્રીહરિએ ભક્તિમાતાને ધર્મશાસ્ત્રનો બોધ આપતાં ત્યાગીનું વર્તન જણાવતાં કહ્યું, “ત્યાગી સાધુએ કાષ્ઠ, ધાતુ, ચિત્રની સ્ત્રીની પ્રતિમાને અડવી કે જોવી નહિ. સુવર્ણ આદિ ધનનો ત્યાગ રાખવો. સ્ત્રી તથા સ્ત્રીને આધીન પુરુષનો સંગ ટાળવો. ત્યાગી સાધુએ સર્પની પેઠે સ્ત્રીથી દૂર રહેવું. જ્ઞાન, ભક્તિ, તપ, ત્યાગ, યોગ અને સત્શાસ્ત્રમાં પ્રેમ રાખવો. કામ, ક્રોધ, લોભ, માન, માયિક પદાર્થમાં સ્નેહ, રસાસ્વાદ વગેરે દોષને તજવા. ઇન્દ્રિયોને જીતવી. અષ્ટાંગ બ્રહ્મચર્ય રાખવું. ભગવાનની નવધા ભક્તિ અખંડ કરવી. ભગવાનની સેવા વિનાની મુક્તિ પણ ઇચ્છવી નહિ.”","e":null,"s":["1/57/57-66"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1513,"k":"para","g":"જે ત્યાગી થયો તેણે પૂર્વાશ્રમના સંબંધીને સંભારવાં નહિ, જો સંભારે તો જરૂર તેને બંધન થાય છે. પ્રથમ સંભારે પછી મિલન થાય અને અંતે ત્યાગી ન રહે ને લાજ ખૂએ.”","e":null,"s":["2/43/30-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1514,"k":"verse","g":"‘પૂર્વાશ્રમ કે સંબંધી જોઉ, ત્યાગી કું ન સંભારના સોઉ;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1515,"k":"verse","g":"ત્યાગી હોઈ સંભારત જેહા, જરૂર બંધન હોવત તેહા;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1516,"k":"verse","g":"સંબંધી સબ જબ હોવે ભેરે, ત્યાગ લજ્જા ન રહે તેહિ વેરે.’","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1517,"k":"para","g":"લોજમાં શ્રીહરિએ સંતોને કહ્યું, “સંતની સેવા કરવાની ઇચ્છા થાય ત્યારે જાણવું કે પૂર્વજન્મનાં ભાગ્ય ઉદય થયાં.”","e":null,"s":["3/1/56"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1518,"k":"para","g":"સરધારમાં શ્રીહરિએ હરિજન સમક્ષ સંતોનો મહિમા કહેતાં કહ્યું, “આ સંતો આ લોકના નથી. બધાનાં એક મન છે. ભગવાનની મૂર્તિમાં વૃત્તિ ડોલાવ્યા વિના એક તાન થઈને સૂર્યની જેમ શોભે છે. ભગવાન વિના બીજી કોઈ ચાહના નથી. દેહાદિકના દુઃખને ગણકારતા નથી. ભગવાનમાં અપાર સુખ માને છે. વિષયમાં દુઃખ માનીને કોઈ સંગ્રહ કરતા નથી. ભગવાન વિનાની વસ્તુ બધી દુઃખદાયક જાણે છે. જો દુઃખદાયક ન જાણે તો તેનો અભાવ ન થાય. અને અનંત જન્મ ખોવે છે. જેને સત્-અસત્‌નું જ્ઞાન છે, જે કાંઈ પ્રવૃત્તિ કરે છે તે ભગવાન સંબંધી કરે છે અને તેને નિવૃત્તિ માને છે એવા એકાંતિક ભક્ત હોય તેને આ વાતની ગમ પડે છે. તે સિવાય બીજા તો બધું એક કરીને માને છે. હંસ અને બકની જેમ ભક્ત અને અભક્તની રીત જુદી હોય છે. તે સત્સંગ કર્યા વિના માલૂમ પડે નહિ. સત્સંગ કરવા છતાં જે ઘટી જાય તેને સત્સંગ થયો ગણાય નહિ.”","e":null,"s":["3/56/15-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1519,"k":"para","g":"સરધારમાં શ્રીહરિએ વાત કરતાં કહ્યું, “હે સંતો! સંતના સમૂહમાં રહેવું એ પરમ કલ્યાણ છે. થોડે પુણ્યે સંત-સમાગમ મળતો નથી. જેને આવો યોગ મળ્યો તેનાં ધન્યભાગ્ય છે.”","e":null,"s":["3/58/49-50"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1520,"k":"para","g":"ઈંગોરાળામાં શ્રીહરિએ સંતનો મહિમા કહેતાં કહ્યું, “અમે પાતાળથી લઈ વૈકુંઠ સુધી તપાસી જોયું, સાધુ જેવી અન્ય કોઈ મોટી પદવી નથી. ચાર વેદ, ખટ શાસ્ત્ર - બધાંનો એક સિદ્ધાંત છે: સરળ ચિત્તવાળો સાધુ સૌથી મહાન છે. જે સરળ-ચિત્ત નથી તેને સાધુ જ ન જાણવો, એવો હોય તે વિનાપ્રયોજન ક્લેશ કરે. જે સરળ છે તેને સત્સંગમાં અહોનિશ સુખ મનાય છે. વિપરીત સંજોગોમાં તે કદી કચવાતો નથી. આત્મવિચારનું બળ તેને સદા રહે છે.”","e":null,"s":["4/18/49-52"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1521,"k":"para","g":"શ્રીહરિએ કુંડળમાં મામૈયાના ભવનમાં સંતોને વાત કરતાં કહ્યું, “હે સંતો! પૂર્વે સંતો-ભક્તો મહાસમર્થ થઈ ગયા. જે કંઈ કષ્ટ આવ્યું તે સઘળું સૌએ હસતે મોંએ સહન કર્યું છે, પણ અકળાયા નથી. આ પરથી તમે કેવી સમજણ દૃઢ કરી છે તે વિચારવું. જેથી ક્યારેય અધિક કષ્ટ પડે તો પણ મન પાછું ન હઠે! દેશકાળે પણ સમજણ ન ફરે! આજે તમને શિરા-પૂરી ને દૂધપાક મળે છે, રુચે તેવી ધોતી ને પુસ્તક-પોથી રાખો છો, એ ક્યારેક ન મળ્યું તો ‘હરિ બિન સબહિ હરામ’ પદ વારંવાર ગાઓ છો, પણ કામ પડ્યે તેની સૂરત રહે ખરી?”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1522,"k":"para","g":"એમ કહી શ્રીહરિ સંતોને કહેવા લાગ્યા, “શેરડી પોતે પિલાય છે તો ખાંડ, મિશ્રી, બૂરું બને છે. પિલાયા વિના કામ સરતું નથી, તેમ તમે જીવોના મોક્ષ માટે આવ્યા છો. દૈહિક સંબંધો તજ્યા છે. હવે સત્સંગ મળ્યો, તો જેમ હરિની ઇચ્છા હોય તેમ દેહને રાખવો. આ દેહની અંતે કાં તો રાખ થાય છે, કાં એ માટીમાં મળે છે ને કાં તો વિષ્ટામાં પરિણમે છે. આ ત્રણ બાબતને કોઈ મિટાવી શકતું નથી, એ નક્કી વાત છે. આનો નિત્ય વિચાર કરવો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1523,"k":"para","g":"“જીવ વગર આ દેહમાં કોઈ સાર વસ્તુ નથી, તો તેનું જતન કરવાથી શું મળે? આ વસ્તુવિચાર ન હોય તો નિર્બળતા આવી જાય છે. દેહ-ઇન્દ્રિયોનો કુસંગ મહામોટો છે, મોટા મુક્તો પણ તેનાથી ખુવાર થયા છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1524,"k":"para","g":"“તમારું હિત વિચારી અમે નિયમરૂપી કોટ વજ્ર જેવો અભય બનાવ્યો છે. આ કોટ તુલ્ય બીજો કોટ નથી. આ કોટના પાયા પાતાળ સુધી ઊંડા છે ને તેની ઊંચાઈ અક્ષરધામ સુધી કરી છે. કાળ-કર્મ તેને સ્પર્શી શકતાં નથી. આ કોટમાં તમે સુરક્ષિત છો. હવે બાહ્ય કુસંગીમાત્રનો ભય લેશ પણ નથી. મને નિશ્ચય ભગવાન જાણીને તમે સર્વે જગ-અપમાન સહો છો.”","e":null,"s":["4/33/1-17"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1525,"k":"para","g":"કુંડળમાં શ્રીહરિ સંતોને કહે, “હે સંતો! અહોનિશ અંતર્દૃષ્ટિ કરીને તપાસ કરવો. સુખ અને દુઃખ અંતર્દૃષ્ટિથી પરખાય છે. અંતર્દૃષ્ટિને કોઈ આવરણ નડતું નથી. અંતર્દૃષ્ટિ યુક્ત સાધુની સંગત કરવી. તરતા ન આવડતું હોય તે તરનારાને સંગે તરી જાય. લૌકિક વિદ્યા પણ શીખ્યા વિના વરતી નથી. તો આ અલૌકિક વાત શીખ્યા વિના કેમ વરે?","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1526,"k":"para","g":"“અમારી વિદ્યા બ્રહ્મવિદ્યા છે. તે સર્વથી પર મહાવિદ્યા કહેવાય છે. આ વખતે સૌ પર અમે કૃપા કરી છે તો બ્રહ્મવિદ્યામાં સૌની ગતિ થઈ છે. મેં સંકલ્પ કર્યો છે - સૌ જીવને મારો યોગ કરાવી માયાપાર કરવા તેનાથી જીવમાત્ર તરી જશે. અમારો સંકલ્પ મિથ્યા થતો નથી તે નિશ્ચય જાણજો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1527,"k":"para","g":"“ચાર વર્ણ ઉપરાંત પણ જેણે જેણે અમારો આશ્રય કર્યો છે તેનો મોક્ષ કરીશું. અમારી નિયંતાશક્તિ મહાબળવતી છે. અમે જે જે નિયમ કર્યા છે તેને જીવો, ઈશ્વરો કોઈ લોપી શકતા નથી. જે તેનો લોપ કરે છે તે સ્વયં તત્કાળ લોપાઈ જાય છે. આ અમારી મરજી તમને કહી. માટે જે કરો તે વિચારીને કરજો. મરજી પ્રમાણે વર્તે તેમાં અપાર સુખ રહ્યું છે. તમે સર્વે મુનિ સુજ્ઞ છો, તમને વધુ શું કહેવું?”","e":null,"s":["4/33/27-41"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1528,"k":"para","g":"કુંડળમાં શ્રીહરિ સંતોને કહે, “સાધુતાનો ગુણ સૌથી ઊંચો છે. સાધુતામાં ગુણમાત્ર સમાઈ જાય છે. બીજા શુભ ગુણ ઘણામાં અમે જોયા, પણ સાધુતાની વાત જ ન્યારી છે. સાધુના પદ તુલ્ય બીજું કોઈ પદ નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1529,"k":"para","g":"“પૂર્વે સાધુતાના ગુણ લાવવા કેટલાક મુનિઓ ને રાજાઓએ તપ કર્યાં, પણ આ ગુણ મેળવી ન શક્યા. સાચા સંતમાં જ આ ગુણ વસે છે. એવા સંત અને સાધુતા બન્ને એકરૂપ છે, જુદા નથી. એવા સાધુતાયુક્ત સંતમાં ભગવાન અખંડ નિવાસ કરીને રહે છે. એવા સંતને અમે બ્રહ્મપુર (અક્ષરધામ) તુલ્ય માનીએ છીએ. અમે ચારે ધામ ફર્યા, વન-પર્વતમાં વિચર્યા, ક્યાંય માન રહિત સાધુ ન મળ્યા. જ્યારે રામાનંદ સ્વામી મળ્યા, ત્યારે એમની સાધુતા જોઈને અમારું મન ઠર્યું.”","e":null,"s":["4/35/44-53"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1530,"k":"para","g":"ચૂડાપુરમાં શ્રીહરિએ સંત-હરિજનોને કહ્યું, “સત્સંગને જુઠલાવીને આચરણ કરતો હોય તેને ત્યજી દેવો. દ્રવ્ય હરી પેટ ભરે તેનો વિશ્વાસ ન કરવો. કોઈ સાધુ દ્રવ્ય ભેગું કરતો હોય તેને પાખંડી જાણી તેનો સંગ મારા આશ્રિતે ન કરવો. લસણની ગંધ જેમ પાખંડીનું પાખંડ ઢાંક્યું રહે નહિ. સાપને દૂધ પિવડાવો તો પણ તે કદી ઝેરનો ત્યાગ કરતો નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1531,"k":"verse","g":"‘પાખંડીજન રહે ન છિપાઈ, જ્યું લહસુન કી ગંધ રહાઈ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1532,"k":"verse","g":"સર્પકું દૂધ પિવાવો જબહૂઁ, તોહુ ન જહર છાંડે કબહુઁ.’","e":null,"s":["4/74/33-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1533,"k":"para","g":"લીંબડીના હરિસિંહ નૃપને શ્રીહરિ કહે, “જગતમાં સંત છે તેવા આ સંત નથી. બન્નેનું ધર્મપાલન જોવું પછી વિવેકથી પૂજવા. યથાર્થ ધર્મ છે તે તો જાણી જ નથી શકાતો, સદ્‌ધર્મીના સંગે ધર્મ ઓળખાય છે. રાજપાટ, ધન-વૈભવ, કરોડો રૂપિયાના ખજાના કરતાં પણ સંત અનંતગણા અધિક છે. એ સંતરૂપી ધન તમને મળ્યું છે. તેને જતન કરીને રાખવું.”","e":null,"s":["4/83/3-7"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1534,"k":"para","g":"અમદાવાદમાં કાંકરિયામાં સ્નાન કરી મુકામ પર શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “ધન અને સ્ત્રીનો ત્યાગ રાખે તે જ સાચો ત્યાગી છે. ત્યાગ ન રાખે તેને અસંત જાણવા. ત્યાગી થયો તે જગતની વાર્તા કરે નહિ ને સુણે પણ નહિ. ભગવાન સંબંધી કથા-કીર્તન વાતો કરે. ભગવાન સિવાય બીજું ચિંતવન કરે નહિ. જેવું ચિંતવન કરે એવું ચિત્ત થાય. શ્રીહરિમાં લીન રહી નવધા ભક્તિ કરે ત્યારે તેના અનંત જન્મ ટળે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1535,"k":"para","g":"“સંસારમાંથી ચિત્ત ઉખેડી હરિમાં જોડે તે સંત. સંત જીવના સાચા હેતુ છે. ભગવાન અને સંત વિના બીજું બધું ઘોર નર્ક તુલ્ય જાણે તે હરિજન સાચો.”","e":null,"s":["4/107/19-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1536,"k":"para","g":"રાજકોટમાં મધ્યરાત્રિએ શ્રીહરિએ સંતોને બોધ આપતાં કહ્યું, “સંત થઈને જે સંતના ગુણ ગ્રહણ નથી કરતો તેને પાપ લાગે છે. ભગવાન સિવાય બીજામાં રાગ થાય એ જ સાધુને મોટું પાપ કહ્યું છે. સાધુને તો અપલક્ષણ અને અભક્ષણ બંનેનો ત્યાગ હોય અને સાધુના જેટલા ગુણ છે તે નિત્ય શીખતો હોય. પોતામાં રહેલા અવગુણને ઓળખે અને તેનો ત્યાગ કરે, એવા સંતનો જેને સંગ છે તેને ભગવાનનો રંગ લાગે છે અને જન્મ-મરણનો ભય ટળે છે. એ વિના કોટિ ઉપાય કરે તો પણ કાળ-માયાથી મુક્ત થાય નહિ અને ક્યારેય સુખ પામે નહિ. જેની સાધુતામાં રુચિ હોય એવા સંતમાં ભગવાન નિવાસ કરે છે. જ્યાં સુધી હૃદયમાં પાપ છે ત્યાં સુધી તેને સાચા સંત ગમતા નથી અને અસાધ્ય રોગ જતો નથી. એવાને સંત ઉપદેશ પણ કરતા નથી. જ્ઞાની સંત આ બધી વાત જાણે છે.”","e":null,"s":["5/12/1-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1537,"k":"para","g":"મોડા ગામે રણમલજી નૃપના ભવનમાં રાત્રે સંતો સિદ્ધાસનમાં ધ્યાન લગાવીને બેઠા અને ધૂન કરવા લાગ્યા. અરુણોદય થયો ત્યારે શ્રીહરિ સંતોને વાતો કરવા લાગ્યા, “સાધુએ એક એકની મોટાઈ જાળવવી. મોટા હોય તેને તે પ્રકારે બોલાવવા. દિવસ-રાત ભેગા રહેતા હોય તેની મોટપ જાણ્યામાં આવતી નથી એ જગતની રીત છે. પણ હરિજનની એ રીત નથી. ઉદ્ધવજીએ ગોપીઓનો મહિમા જાણ્યો અને પોતાને ન્યૂન જાણ્યા. સાધુ થયા પણ સાધુના ગુણ ન આવે ત્યાં સુધી તેને માથે ભય છે. માટે સાધુના જેટલા ગુણ કહ્યા છે તે પ્રાપ્ત કરવા. રોજ એક એક ગુણ શીખવો. ગુણો શીખ્યા વગર તે સિદ્ધ થતા નથી. તે સો વર્ષ સુધી અમારા સંગમાં રહે તો પણ સિદ્ધ ન થાય. એ તો જડભરત જેવા અવધૂત ત્યાગીનાં આખ્યાન નિત્ય વારંવાર વિચારે, જીવને તે રૂપ કરી દે, તેના ગુણને હૃદયમાં ધારે ને તે મુજબ વર્તે ત્યારે તેમના ગુણો પોતાનામાં પ્રગટ થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1538,"k":"para","g":"“નારદ, શુક-સનકાદિકમાં પણ અધિક ગુણ રહ્યા હતા તે પ્રીત સહિત ગુણ શીખવા એ સંતની રીત છે. શીખ્યા વગર ગુણ આવતા નથી. અને નામમાત્રનો સાધુ રહે છે. અમને તમે જે જે આવીને મળ્યા છો તે સર્વેને બ્રહ્મસ્વરૂપ કરવા છે, જીવમાં માયાનો ભાગ ભળ્યો છે તે કાઢવો છે. માટે ખબરદાર થઈને રહેજો. નહિ તો તમારો પગ ટકશે નહિ. પ્રથમ અમારા સ્વરૂપની દૃઢતા જેના અંતરમાં થાય છે તેને પોતાનું સ્વરૂપ પરમ પ્રકાશિત દેખાય છે. સૂર્ય વિના અંધારું ન ટળે તેમ અમારા સ્વરૂપની દૃઢતા વિના પોતાનું સ્વરૂપ ઓળખાતું નથી. મારી મૂર્તિ અને મારા વચન તેને અધિક ન્યૂન ન સમજવાં. જે નિષ્કપટ વર્તન કરશે તેનો સત્સંગ દિન-દિન વૃદ્ધિ પામશે. સંતની સેવા કરવી તે મોક્ષપદથી પણ અધિક છે.”","e":null,"s":["5/16/9-35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1539,"k":"para","g":"ભુજના સુંદરજીએ શ્રીહરિને કહ્યું, “તમે મળ્યા તે બધાં સાધનો પૂરાં થયાં, તોય હજુ આ સંતોને શીદને દમો છો?”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1540,"k":"para","g":"ત્યારે શ્રીહરિએ કહ્યું, “અમારી રીત અટપટી છે, તે તમને નહિ સમજાય. અમારા શરણે જે કોઈ આવે છે તેને અમે ક્યારેય દુઃખ પડવા દેતા નથી. તેમાં સંતો તો અમારા પરમ નિધિ છે. સંતથી મોટું કોઈ નથી, પણ દેહનું જતન કરવામાં ભગવાનને ભૂલી જાય ને વિષયમાં પ્રીતિ કરે ત્યારે અમને દુઃખ થાય છે. મનુષ્યમાત્રને સર્વ પાપનું મૂળ કારણ આ દેહ છે. દેહમાં આસક્તિ ત્યારે ન રહે, જ્યારે તપમાં રુચિ થાય. ને વિષયનો અનાદર થાય ત્યારે તપમાં રુચિ થાય છે. ભગવાનની મૂર્તિ અંતરમાં ધારીને દેહને અત્યંત કષ્ટ આપે તેની સહાય અમે કરીએ છીએ. રુચિ શુદ્ધ હોય તો સહાય કરીએ. નહિ તો કોટિ કલ્પ સુધી જપ-તપ કરે તોપણ જન્મમરણ ન ટળે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1541,"k":"para","g":"“જે સાચો ત્યાગી છે તે મન-ઇન્દ્રિયોને પરમ વેરી જાણીને તેને કેદમાં રાખે છે. દેહ સાથે વેર કરે તો જ ઇન્દ્રિયોનો ગણ નરમ પડે એમ માનીને સાચો સાધુ પોતાના દેહને જેમ ભીડો પડે, કસણી થાય તેમ આનંદ પામે છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1542,"k":"verse","g":"‘સાચે સંત હોય જેહ, વિષય-ઇન્દ્રિ માત્ર હિ;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1543,"k":"verse","g":"કેદ મેં રખે તેહ, પરમ વૈરિ જાનિ કે તેહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1544,"k":"verse","g":"વૈર કરે દેહ સંગ, સબ ઇન્દ્રિગન પરે નરમ હિ;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1545,"k":"verse","g":"સંત રહત ઉછરંગ, ભિરે મેં દેવત દેહ જિમિ.’","e":null,"s":["5/36/20-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1546,"k":"para","g":"પીપળીમાં દાદાભાઈને ત્યાં શ્રીહરિએ સંતની વ્યાખ્યા કરતાં કહ્યું, “સત્ અને અસત્ બે માર્ગ છે. સત્‌ને જાણે તે સંત છે. જેને ભગવાનની ગમ છે તે યથાર્થ વાત સમજે છે.”","e":null,"s":["5/68/38-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1547,"k":"para","g":"શ્રીહરિએ પૂરના નૃપ પ્રત્યે વાત કરતાં કહ્યું, “આ સંતનું ચિંતવન પ્રીતિ પૂર્વક કરવું. જે તેનું ચિંતવન કરે છે તેને ચારેય દુઃખ ટળી જાય છે. જન્મમરણ, જમપુરી, ચોરાશી તેને માથે રહેતી નથી. આ સંતને જે ભાવથી જમાડે છે અને ચંદન, પુષ્પો, વસ્ત્રોએ કરીને વેળા-વેળાએ પૂજે છે એ મનુષ્ય જે જે લોકમાં જાય છે ત્યાં દેવતાઓ તેનું પૂજન કરે છે, આ વાત તે સત્ય જ છે અને તેનું ફળ સમય આવે દેખાય છે. સંતનું વચન જે માને છે તેનું ધર્મમાં વર્તન થાય છે. આવા સંતની મધ્યે પ્રગટ શ્રીહરિ બિરાજે છે, એવી પ્રતીતિ જેને આવે છે તે તત્કાળ અક્ષરધામ પ્રાપ્ત કરે છે. સંત-સમાગમ કરે છે તેને અક્ષરધામ દૂર રહેતું નથી.”","e":null,"s":["5/30/1-6"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1548,"k":"para","g":"સુખપુરમાં રાવત ધાધલને ઘરે શ્રીહરિ મુક્તમુનિને કહે, “જેને જેટલો દૃઢ નિશ્ચય હોય, તેને તેટલો સત્સંગનો કેફ વર્તે. ગૃહત્યાગ કરવો તે તો મરવાથી પણ કઠણ છે, પરંતુ ભગવાનને બધાથી પર સર્વોપરિ જાણે તેને કંઈ કઠણ નથી.”","e":null,"s":["6/4/25-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1549,"k":"para","g":"જૂનાગઢમાં દેવદિવાળીનો ઉત્સવ કર્યો અને દસ-દસ સંતોનાં મંડળ અને દેશ વહેંચ્યાં. અને એક-એક સંતને પ્રેમથી મળ્યા (ભેટ્યા). પછી ઉપદેશ આપતાં શ્રીહરિએ સંતોને કહ્યું, “અમારે તમારા દ્વારા અગણિત કાર્યો કરવાં છે, માટે સાવધાનપણે વર્તજો. જે પ્રકારે ત્યાગીઓના નિયમ અમે બાંધ્યા છે તેમાં ખબડદાર રહેજો. નિષ્કામધર્મના પાલનમાં તત્પર રહેજો. અષ્ટ પ્રકારે સ્ત્રીનો ત્યાગ રાખજો. એ જ રીતે ધનનો ત્યાગ રાખજો. સુવર્ણથી લઈને કોઈ પણ ધાતુમાં રાગ ન રહે તેની તકેદારી રાખજો. અમારાં વચન પાલનમાં રાગ જરૂર રાખજો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1550,"k":"para","g":"“નિઃસ્વાદી, નિર્માની, નિઃસ્પૃહી (નિર્લોભી), નિઃસ્નેહી તથા નિષ્કામી - આ પંચવ્રત સાવધાનપણે પાળજો. તમારા ધર્મપાલનની વાત લોકોને કરજો. હરિભક્તોના ધર્મ પણ વિસ્તારથી સમજાવજો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1551,"k":"para","g":"“અમો જે હેતુ લઈને પૃથ્વી પર પ્રકટ થયા છીએ તેની (એટલે કે એકાંતિક ધર્મ પાલન કરાવી જીવને અક્ષરરૂપ કરી માયા પાર અક્ષરધામમાં લઈ જવાની) વાત સૌને વારંવાર કરજો. અને કહેજો કે જે સત્સંગ કરશે, અને અમારા સ્વરૂપનો યથાર્થપણે દૃઢ નિશ્ચય કરશે તેનાં અપાર પાપ પણ ટળી જશે. અમારા નિશ્ચયમાં કોઈની લેશ પણ કાચ્યપ અમને રુચતી નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1552,"k":"para","g":"“સૌને પ્રગટના ભજનમાં જોડવા. જેને અમારો દૃઢ વિશ્વાસ થાય અને નિશ્ચયમાં શંકા ન રહે તે પ્રગટનું ભજન હંમેશાં કરે; પણ બીજા લોકો પોતપોતાના ઇષ્ટદેવનાં નામ લેતા હોય તેની નિંદા કે ખંડન કરવું નહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1553,"k":"para","g":"“તલવાર મ્યાનમાં હોય તો કોઈ બીતું નથી, પણ ખુલ્લી હોય તો સૌ બીએ. કોઈ નાગો થઈને ફરે તો લોકો તેને પૂરી દે છે, પણ દેહનું ભાન ન હોય કે ગાંડો હોય, તેના આચરણને કોઈ દોષરૂપ માનતું નથી, પણ જાણીને નાગો ફરે તો માર ખાય છે. તમે સંતો ધર્મરૂપ છો તેથી ધર્મીજનો તમને પોતાના પ્રાણ સમાન માનશે અને અધર્મીને ડારો દેશે, પણ તમે શાંતિ રાખશો તો તેમનો નાશ થશે. ભગવાનની ઇચ્છાથી તમારી રક્ષા કરે એવો એક રાજા આવશે જેથી બીક રાખશો નહિ.” એટલી વાત કરી શ્રીહરિ અશ્વે બેઠા ને વડાદ પધાર્યા.","e":null,"s":["6/82/1-27"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1554,"k":"para","g":"શ્રીહરિ પોતાના હૃદયની વાત વારંવાર સંતોને કરતા. ગઢપુરમાં શ્રીહરિ કહે, “અમને સાધુતા ગમે છે. જેમાં અપાર સાધુતા દેખુ છું તેને દિન-રાત ચાહું છું. અક્ષરધામનું સુખ અને આનંદ સંતમાં રહ્યાં છે, પણ કોઈના દેખ્યામાં આવતાં નથી. દરેક સંતને જો પોતાનું અસલ સ્વરૂપ દેખાડીએ તો બ્રહ્માંડની સ્થિતિ ન રહે. કારણ, બધામાં ઈશ્વર જેવું વર્તન છે. એટલા માટે અમે જાણી જોઈને બધાની સામર્થિ છુપાડી રાખી છે. બધી સામર્થિમાં પ્રભુતા જીરવવી તે મોટી સામર્થિ છે. બધા મદમાં પ્રભુતા (ઐશ્વર્ય)નો મદ મોટો છે. શાસ્ત્રના વચનમાં વર્તે તે મોટું ઐશ્વર્ય છે. શાસ્ત્રના વચનમાં વર્તવું તે મોટી પ્રભુતા છે. અગમ-નિગમની વાર્તા કહેતો હોય ને શાસ્ત્ર લોપીને ચાલતો હોય તેને શ્વાન, શૂકર ને ગર્દભ સમાન જાણવો.”","e":null,"s":["6/99/2-9"],"sv":["तेहि जानि साम्रथ रखे हे गोई । प्रभुता जिरवना कठिन हे जोई ॥\n\n सब हि मद में मद हे भारी । प्रभुता जिरवना लगारी ॥\n\n शास्त्र के वचन में वर्तना जेऊ । बडी प्रभुता समझना तेऊ ॥\n\n शास्त्र कुं लोपि चले जाहि । अगम निगम बात कहेता हि ॥\n\n कुकर शूकर गर्दभ की नाई । एसे कुं समझना मन मांई ॥"],"mt":false,"gl":null,"a":false},{"i":1555,"k":"para","g":"ભૂજમાં શ્રીહરિએ હરિભક્તોને કહ્યું કે, “સત્સંગી એને જ જાણવો જે પોતાનું ધન સંત અર્થે કરી રાખે. ત્યાગી એ સાચો કે જે સ્ત્રી-ધનનો ત્યાગ રાખે. સંસાર થકી ઉદાસ હોય. બીજાને અર્થે અન્ન-વસ્ત્ર અને દેહનો પણ ત્યાગ કરી દે. હરિને રીઝવવા પંચ ઇન્દ્રિયોના સ્વાદનો ત્યાગ કરે, તેને કેવળ ભગવાન સંબંધી જ પંચવિષય હોય. નિષ્કામાદિ પંચવર્તમાન દૃઢ પાળે ને તેના પાલનનું ફળ પણ ભગવાનનો સ્નેહ થાય એ જ છે એમ સમજે. હરિ વિના બીજા સુખને ઇચ્છે જ નહિ. એવા ભક્તને હરિ અનંત સુખ આપે છે. ભગવાનનું સુખ અપાર છે, તે કોઈના કળ્યામાં આવતું નથી. ભગવાનના આકારે જ્યારે દૃષ્ટિ થાય છે ત્યારે એ સુખનો અનુભવ થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1556,"k":"para","g":"“પાતાળથી પ્રકૃતિપુરુષ સુધી દેહાકાર વર્તન છે. જ્યારે દેહભાવ ત્યાગે ત્યારે નિરાવરણ થાય છે. પ્રકૃતિપુરુષ સુધીના સુખનો ત્યાગ કર્યો ત્યારે જાણવો જ્યારે બ્રહ્મના આનંદમાં સદા ગરકાવ રહે. કોઈ પ્રકારની લૌકિક ઇચ્છા ઊપજે નહિ, દુઃખદ્વન્દ્વ પણ રહે નહિ. ભગવાનના સુખનો વિચાર કરે છે તે જ્ઞાની છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1557,"k":"para","g":"“ભગવાનના સુખ સિવાયનું જે સુખ છે તે સઘળું દુઃખ જ છે, એમ સમજી ભગવાનમાં વૃત્તિ રાખનાર ત્યાગી હોય કે ગૃહી એ સંત છે.”","e":null,"s":["7/9/2-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1558,"k":"para","g":"ભૂજમાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “અસુરો ઉત્પાત કરે તોપણ સહન કરવું એ સંતોનો સનાતન ધર્મ છે. શાસ્ત્રમાં તે લખેલો છે, પણ આજ સુધી યથાર્થ રહ્યો નથી, તે અમારે પ્રગટ કરવો છે. અસુરે ધર્મ તોડવાની ટેક લીધી છે. તેમને શસ્ત્ર વિના સાધુતાના વર્તનથી જીતવા છે. અગ્નિ ફાવે તેવો ભયંકર હોય, પણ પ્રમાણમાં વધુ જળ હોય તો ક્ષીણ થઈ જાય છે. માટે સંતોએ આકાશ અને નીર સમાન ગુણ રાખવા. દત્તાત્રેયની પેઠે સૌ સાધુઓએ સર્વત્ર શુભ ગુણો ગ્રહણ કરવા, જેથી શુભ ગુણ આવે અને અપકીર્તિ નાશ પામે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1559,"k":"para","g":"“અપકીર્તિ થવા છતાં દુર્ગુણ તજે નહિ તે મનુષ્ય ન કહેવાય. સાધુનાં વચન તો અમૃતથી મીઠાં હોય. બાવનાચંદન જેવો ગુણ સાધુમાં ગણાય છે. તીક્ષ્ણ કુહાડીની ધાર પણ બૂઠી થઈ જાય એ બાવનાચંદનનો સ્વભાવ છે. સંતનાં વચન એ ચંદન જેવાં શીતળ હોય જેથી અસાધુ પણ તેના સંગે સાધુ થઈ જાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1560,"k":"para","g":"“ઝેર જેવાં અસાધુનાં વચન સાંભળીને અમૃત વચન કહીને તે ઝેર ઉતારે એવાં સાધુનાં વચન હોવાં જોઈએ. સાધુતાનો વિચાર વારંવાર કરવો. વિચાર વિના સાધુતા આવે નહિ. માયા પર અક્ષર છે ને અક્ષરથી પર પુરુષોત્તમ ભગવાન છે. સાધુતા આગળ એ ભગવાન પણ દીન-આધીન રહે છે અને સાધુને પોતા કરતાં પણ પર માને છે, અને સાધુને ભગવાન વિના બીજું કાંઈ અધિક નથી. તેઓ સદાય હરિનાં ચરણોમાં જ લપટાયા રહે છે. સંતને હરિ વિના કોઈ અધિક નથી, અને શ્રીહરિને પણ એવા સંત વિના કોઈ પૂજ્ય નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1561,"k":"para","g":"“ભવ, બ્રહ્મા, વિષ્ણુ, ઇન્દ્રાદિ દેવ સિદ્ધ અને મુક્તોના ગુણ પણ પ્રસન્ન થયેલા શ્રીહરિ તરત જ આપે છે, પણ સાધુતાના ગુણ આપતા નથી. સાધુ સદાય ભગવાનની મૂર્તિમાં ચિત્ત રાખતા હોવાથી તેને ઉદ્વેગ કે ચિંતા હોતાં નથી. સાધુ સૌના મિત્ર થઈને રહે છે, અને સદાય શાંત રહે છે.”","e":null,"s":["7/13/5-28"],"sv":["सर्वोपरि है साधुगुन भारी । भगवान शिर हृदय रहे धारी ॥\n\n साधु आगे भगवान हि जेहा । दीनाधीन रहत हे तेहा ॥\n\n गुन अनंत कहावत जेते । साधुता में रहत हे तेते ॥\n\n माया से पर अक्षर सुख रूपा । पुरुषोत्तम तेहि पर अनूपा ॥\n\n पुरुषोत्तम साधु कुं जोई । आपसे पर मानत हे सोई ॥\n\n साधु कुं हरि विन न अधिकाई । हरिचरन रहत लपटाई ॥\n\n संत कुं हरि विन पूज्य न जोहुं । हरि कुं संत विन पूज्य न कोहुं ॥\n\n भव ब्रह्मा अरु विष्नु हि, इन्द्रादिक देव जोउ ।\n\n सिद्ध मुक्त गुन देत हरि, साधु गुन देत न सोउ ॥\n\n साधु भये ताहि कुं, उद्वेग होत न चित्त ।\n\n हरिमूर्ति रखे चित्त में, रहत हे सबके मित ॥\n\n शांत सुखी कहे संत, संत विन नहि शांत कोउ ।\n\n संत गुन है बलवंत, बलवंत गुन सो देना अबे ॥"],"mt":false,"gl":null,"a":false},{"i":1562,"k":"para","g":"શ્રીહરિ સિદ્ધપુર પધાર્યા ત્યારે નૃપ સામૈયું લઈને સન્મુખ આવ્યા. શ્રીહરિ હાથી ઉપર બિરાજ્યા અને સંતોને કહ્યું, “કોઈ સાધુએ અસવારીમાં અશ્વ ઉપર બેસવું નહીં એ અમારી આજ્ઞા છે. ભૂમિ પર ચાલવું તે સાધુની ઉત્તમ રીત છે. સાધુ ભૂમિ પર ચરણ માંડે છે ત્યારે ભૂમિનાં પાપમાત્ર નાશ પામે છે. સંતની ચરણરજના પ્રતાપથી અનંત તીર્થ નિષ્પાપ થઈ જાય છે. જ્યારે સંત તીર્થની સન્મુખ ચાલે છે, ત્યારે તીર્થ પણ સામે ચાલીને તેનાં દર્શને આવે છે. સંતનાં ચરણમાં તીર્થમાત્ર નિવાસ કરીને રહે છે. સંત તો જીવમાત્રને પાવન કરે છે.”","e":null,"s":["7/43/28-32"],"sv":["भूमि पर संत धरत जे चरना । पाप तितनो होत निकंदना ॥\n\n संत के चरण करि प्रतापा । तीर्थ अनंत होत निष्पापा ॥\n\n तीर्थ सन्मुख संत चलत जबहु । सन्मुख तीर्थ आवत तबहु ॥\n\n संत के चरण करत निवासा । होई के मन परम हुलासा ॥\n\n संतचरण प्रताप अनूपा । जिय मात्र कुं करे पावन रूपा ॥"],"mt":false,"gl":null,"a":false},{"i":1563,"k":"para","g":"જેતલપુરના મહોલમાં શ્રીહરિ સંતોને કહેવા લાગ્યા, “અધિક લાભ લેવા સૌ ઘર છોડીને આવ્યા છો, લોકલાજે નામ લે, પણ અંતરમાં ખપ ન હોય તો અંતે કાર્ય બગડે છે. ભય તજીને સુખે સૂઈ રહે તે સંસારનો રાગી હોય. ઉઠાડવામાં લાભ માનીને સંતો પ્રેમથી ઉઠાડે છે. આવ્યા ભજન કરવા અને ભજનમાં લાભ મનાયો નહિ. સત્સંગમાં આવ્યા વધવા અને આદર કર્યો ઘટવાનો તેને કેવો સમજવો! મોટા સંતમાં જ્યારે દોષ દેખાય ત્યારે ભ્રષ્ટમતિ થાય. તેમનો સ્વભાવ ન ગમે અને રાતદિવસ અભાવ લે, એવા અપરાધી વિમુખ જીવો જગતમાં ફજેત થાય છે, બીજા જનો તો આદર દે પણ છેવટે દુઃખી ચિત્તે મરે. રાતદિન અભાવ કહેતો હોય તેને શાંતિ ક્યાંથી હોય! એવા અપરાધીને પણ સંત ક્ષમા આપે છે. તેની રક્ષા કરે છે, પણ પોતાના દુષ્ટ સ્વભાવને લીધે તેનો પાપનો વ્યાધિ વધતો રહે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1564,"k":"para","g":"“પ્રથમથી જ તો ભગવાનની નાની-મોટી આજ્ઞા પર તાન રાખે તો મન બદલે નહિ, વિઘ્ન આવે નહિ. આજ્ઞાનો ભંગ કરી અભાવ-અવગુણમાં પડે છે, ત્યારે તેનું નિશાન ચુકાઈ જાય છે, અંગ બદલાઈ જાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1565,"k":"para","g":"“અંતરમાં મોક્ષનો થોડો પણ ખપ હોય તો સંતને નમે, ભૂલ ક્ષમા કરાવે. ખપવાળાને પોતાની ભૂલ સૂઝે ને સત્સંગમાં ટકી રહે. ખપ ન હોય તો સંતનો અભાવ લે ને પડી જાય. દિવસ-રાત સંત ભેગો રહેતો હોય ને તેને નમે નહિ તો તેને કુજાતિ જાણવો.”","e":null,"s":["8/14(13)/8-20"],"sv":["दोष आवत बड़े संत को जबहु । भ्रष्टमति हो जात हें तबहु ॥\n\n कोउ संत को न गमत स्वभावा । रातदिन बोले अभावा ॥\n\n तोहु न लहे शांति मन, ऐसो होत अपराधि ।\n\n संतजन रक्षा करे तोहु, वधत हें पाप की व्याधि ॥\n\n एसे होत विमुख तेहि, जग में होत फजीत ।\n\n आदर देत जन अवर, मरत दुःखि होय चित्त ॥\n\n मन बदले तब हो गये ओरा । एक स्थिति को रहे न ठोरा ॥\n\n हरि अग्या को करत हे भंगा । तेहि कर बदल जात है अंगा ॥\n\n संत कुं नमे वारमवारा । खप अंतर में होय जो लगारा ॥\n\n खपवंत निज भूल विचारे । संतकुं नमी देत तेहि वारे ॥\n\n संत को अभाव लेत तेहि करि के । सत्संग में सो न टके फरि के ॥\n\n संत के भेले रहे दिनराती । नमे न सो जानना कुजाति ॥"],"mt":false,"gl":null,"a":false},{"i":1566,"k":"para","g":"નડિયાદમાં શ્રીહરિ સંતોને કહે, “જે ત્યાગી થયો હોય તેને ભગવાનનાં ચરણોમાં રસ અને પ્રીતિ હોય. ત્યાગીને સંસારના રસમાત્ર વિષ સમાન થઈ ગયા હોય. ત્યાગી થઈને સ્વાદ ન જીતે અને રસનો ભોગ કરે તો તેનો જોગ નાશ પામે. માછલું અધિક સ્વાદ કરે છે, તો તે જીવ ખુવે છે. સંસારનો સ્વાદ લે તેને જન્મમરણ ભોગવવા પડે છે.”","e":null,"s":["8/34(32)/5-6"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1567,"k":"para","g":"નરસંડામાં શ્રીહરિ સંતોની પંક્તિમાં લાડુ પીરસવા લાગ્યા, “સંતો, મહારાજો! લાડુ લિયો,” એમ બોલતા જાય ને એક એક સંતને ભાવથી પીરસતા જાય. એમ સંતો તૃપ્ત થયા ત્યાં સુધી પીરસ્યું, પછી શ્રીહરિ બોલ્યા, “સંતોને પીરસવાની આટલી સેવા નિત્ય કરવી એવી અમારે ટેવ પડી છે. સંતની સેવાથી અંતરમાં લાભ થાય છે. સેવા વિનાના લાભને અમે લાભ માનતા નથી, એ બધો અલાભ છે. સમયે સમયે જાતજાતનાં સાધન શાસ્ત્રોએ કહ્યાં છે, એ બધાં સાધનનું ફળ સંતની સેવા મળે એ છે. સંતની સેવા કરે તેના પર ભગવાન તત્કાળ પ્રસન્ન થાય છે. સંતની સેવા પણ ધર્મ રાખીને કરવી, તો જ તે ફળીભૂત છે. ધર્મ વિનાનાં કોટિ સાધન કરે તોપણ તેને મોટી પ્રાપ્તિ થતી નથી.”","e":null,"s":["8/44(43)/4-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1568,"k":"para","g":"વડતાલમાં બાપુજી પટેલને ઘરે શ્રીહરિએ સંતોની પંક્તિ કરીને ડંકા ભરી ભરી કંસાર પીરસ્યો. ‘વાસુદેવ હરે’ થયા અને સંતોએ જમવાનું શરૂ કર્યું તે વખતે શ્રીહરિ કહેવા લાગ્યા, “સંતની સેવા કરવી તેમાં અમે મોટપ માનીએ છીએ. સંતની સેવા સમાન બીજું સુખકારક પદાર્થ જગતમાં નથી. સંતની સેવા કરીને માયિક પદાર્થ ઇચ્છે તે નરને પશુ જેવો પામર જાણવો.” એમ કહીને શ્રીહરિ સંતોને સંબોધી કહેવા લાગ્યા, “સંતના દાસ થઈને રહે ત્યારે સંતના ગુણ આવે, અને ગુણ શીખે ત્યારે સંત કહેવાય. ખાલી સંતનો વેષ ધરવાથી ગુણ આવે નહિ. સંતો પણ ભેગા રહેતા હોય તેણે એકબીજાનો ભાર રાખવો અને એકબીજાના ગુણ શીખવા અને કહેવા. અવગુણ કોઈ રાખવો નહિ. જીવમાં કંઈ દોષ હોય અને સંત તેને દેખાડે તો તે તજી દેવો. પોતાના દોષ પોતાને દેખાય નહિ એવો જીવમાત્રનો સ્વભાવ છે. દેહ-ઇન્દ્રિયો અંતઃકરણ વગેરે દોષરૂપ જ છે. જેટલો આ જીવને દેહનો ગુણ છે તેટલો કુસંગ છે અને તેટલાં જન્મમરણ અને યમયાતના છે. માટે સ્વપ્નમાં પણ તેનો ગુણ ન મનાય તેનો વિચાર કરવો, અને તે દોષ કોઈ દેખાડે તો રાજી થાય તેને સંત જાણવા. દેહના મમત્વથી રહિત થવું એ જ સંતનો પાકો પાયો છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1569,"k":"para","g":"“પોતાના ગુણમાં પણ દોષનું રૂપ જોવું એ જ સાચી સાધુતા છે. સાધુ થવું તે સાધનમાત્રમાં કઠણ સાધન છે. જ્યારે બ્રહ્મવિદ્યા પ્રાપ્ત થાય છે ત્યારે તે સર્વોપરી સાધુ કહેવાય છે. ભેખ લીધો પણ દેશ દૂર રહી ગયો, તેણે કરી સાધુના ગુણ પણ અધૂરા રહે છે. અને તેના પર મોટા સંત પ્રસન્ન થતા નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1570,"k":"para","g":"“મોટા સંત રીઝે ત્યારે સાચી સાધુતા આવે. સઘળી બ્રહ્મવિદ્યા સાચી સાધુતામાં સમાઈ જાય છે. બ્રહ્મવિદ્યા વરી તેને સર્વોપરી સાધુ જાણવો.” શ્રીહરિએ ભોજન પીરસતાં પીરસતાં આટલી વાત કરી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1571,"k":"verse","g":"‘બ્રહ્મવિદ્યા કહાવત જેતિ, સર્વોપરિ સાધુ હોનાં તેતિ;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1572,"k":"verse","g":"ઇતનિ કરી હરિ બાત હિ જેહા, ભોજન પિરસત પિરસત તેહા.’","e":null,"s":["8/49(48)/17-35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1573,"k":"para","g":"મેઘપુરમાં જન્માષ્ટમીના સમૈયા ઉપર આવેલા ભક્તોને શ્રીહરિએ શીખ દેતાં કહ્યું, “ઉપરથી રાખેલી સાધુતા કામ ન આવે. ઉપરથી અને અંદરથી બન્ને પ્રકારની જોઈએ તો મોક્ષ થાય. તે વિના મોક્ષ થતો નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1574,"k":"para","g":"“નિર્દંભ પુરુષના દ્વારા મોક્ષનો માર્ગ શોભે છે. દંભી તો અધોગતિ જ પામે છે. નિર્દંભ સાધુના સંગથી જગતના બધા મેલ ધોવાઈ જાય. એવાના સંગે પણ અંતરનો મેલ ન જાય તો જાણવું કે તેને ભારોભાર કુસંગ થાય છે. મેલ રહે તેટલો કુસંગ અને તેટલું દુઃખ થયા વિના રહે નહિ.”","e":null,"s":["10/23/22-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1575,"k":"para","g":"મોડા ગામમાં પુરજનોનો ભાવ જોઈ શ્રીહરિ કહે, “સંત અને હરિ વિના સત્સંગનો પટ કોણ આપે? નિર્લોભ, નિષ્કામ, નિર્માન, નિઃસ્વાદ, નિઃસ્નેહ આદિક સંતના મહાગુણ છે, અને મોક્ષ માટે અમૂલ્ય આભૂષણ છે. આ સંતના ગુણ ભવ-બ્રહ્માદિ દેવતાને દુર્લભ છે. તેને કોઈ ઉપાયે આ ગુણ પ્રાપ્ત થતા નથી. સંતના અંગે રહેલાં આ ગુણનાં આભૂષણ જે જન દેખે છે તેને ભગવાનનો રંગ ચઢે છે. તેનામાં રહેલો મોક્ષનો અંકુર પ્રગટે છે. ખપ પ્રગટે છે. ખપ હોય તેટલો અભ્યાસ થાય. ખપનો અંકુર ઉદય થાય તેવી વાત સંતને આવડે છે.”","e":null,"s":["11/12/29-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1576,"k":"para","g":"ધોરાજીમાં શ્રીહરિ સંતો પર હેત લાવીને નિત્ય કહેતા, “ધનરૂપી માયા હોય ત્યાં સુખ રહે નહિ. ગૃહસ્થ ભક્તને પણ એ માયા કોટિ ક્લેશ કરાવે છે તો જે ત્યાગી છે તેને તો અનંતગણો ક્લેશ થાય.”","e":null,"s":["11/30/29-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1577,"k":"para","g":"શ્રીહરિએ ધોરાજીમાં સંતોને સભામાં બોલાવીને વાર્તા કરી, “વિમુખજન ચાહે તેવું બોલે, પણ સંતોએ પ્રસન્ન થકી સહન કરવું. સહનશક્તિ એ બધી મોટપમાં અધિક મોટપ છે. સાધુએ શુક-સનકાદિકની રીતને ગ્રહણ કરવી. સાધુનો મુખ્ય ધર્મ નિર્માનીપણું છે. નિર્માનધર્મ વિનાનો ત્યાગ ત્યાગીને શરમરૂપ છે. નિર્માની સંત દુર્લભમાં દુર્લભ છે. ભગવાનને તે અતિ પ્રિય છે. નિર્માનમાં અપાર મોટપ રહેલી છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1578,"k":"para","g":"“બીજાને ક્રોધ ચઢે એવું વચન સંત ક્યારેય બોલે નહિ. મુખથી કોઈનું ઘસાતું બોલવું નહિ. શાસ્ત્રની રીત શીખવી. શુક-સનકાદિક બોલ્યા છે તે પ્રમાણે બોલતાં શીખવું. શીખ્યા વિના આવડે નહિ. વાત કરવાની કળા તો વશીકરણ મંત્ર કહેવાય છે. નિર્માનીપણું રાખ્યા વિના જેટલી કસર રહી જાય છે તે દેખાઈ આવે છે, એમાં દંભ ઢાંક્યો રહેતો નથી. વિવિધ રસ મળે ત્યારે નિઃસ્વાદપણું છૂપ્યું છુપાતું નથી, તેમ જ કોઈ કુત્સિત શબ્દ બોલે ત્યારે નિર્માનીપણાની ખબર પડે. એમ નિર્લોભપણું, નિઃસ્નેહપણું, નિષ્કામપણું વગેરે તે તે પ્રસંગ પડે ત્યારે જણાયા વિના રહે નહિ. નિયમરૂપી કોટમાં રહેવું. સત્સંગરૂપી વહાણથી શ્વપચ સુધીનાં અનંત નરનારીઓ સંસાર તરી જાય છે તો ભગવાનના યોગમાં આવેલા ત્યાગીની શી વાત કહેવી?”","e":null,"s":["11/36/3-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1579,"k":"para","g":"જૂનાગઢમાં શ્રીહરિએ સંતોને બહુ વાતો કરી કહ્યું કે, “જે મનનું કહ્યું ન કરે તે મોટા સંત જાણવા. વારે વારે સાવધાન રહે ત્યારે મનરૂપી શત્રુ ઓળખાય. દમ્યા વિનાના હાથી ને ઘોડા જેમ ઉન્મત્ત હોય છે, તેમ દમન વિનાનું મન પણ એવું છે. માટે તેને પકડવાની રીત શીખવી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1580,"k":"para","g":"“હરિઇચ્છાએ પંક્તિમાં જે વસ્તુ ફરતી હોય તેનો વિચાર કરીને પોતાની ભૂખ પ્રમાણે લેવી. મન માગે તે માગીને લે અને મનને ન ગમે તે ન લે એ સાધુ મનને વશ વર્તે છે એમ જાણવું.”","e":null,"s":["11/56-b/35-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1581,"k":"para","g":"મુક્તમુનિએ શ્રીહરિએ કહેલી વાતો ગઢપુરમાં કહી, “શ્રીહરિ કહેતા કે - ધન નારી જ્યાં સુધી ઉરમાં રહ્યાં હોય ત્યાં સુધી કાચો ત્યાગી ગણાય. અંતર-બહાર ત્યાગી થઈને રહે તે પાકો ત્યાગી ગણાય. ત્યાગીનું વર્તન સત્સંગમાં દર્પણ જેવું છે. પાકી સમજણવાળા સંસારના સુખને ઇચ્છતા નથી. સંસારનાં સુખનું વમન કરી નાખે ને પછી ઇચ્છે જ નહિ એવા ત્યાગીને સાચા ત્યાગી માનવા. વિષયો પ્રત્યે દશ ઇન્દ્રિયો ને અંતઃકરણમાંથી ઊલટી કરેલા અન્ન જેવો એ અભાવ રાખે છે. એક પણ ઇન્દ્રિયમાં રાગ હોય ત્યાં સુધી ત્યાગ કાચો છે.”","e":null,"s":["11/78(68)/30-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1582,"k":"para","g":"રામજી સંપ્રદાયમાં જે મુમુક્ષુ સંતો હતા તે દ્વારકા દર્શન કરીને પાછા ફરતા હતા, ત્યારે શ્રીહરિનો યોગ થઈ ગયો. તે સંતોમાં કેટલાક શસ્ત્રબંધી હતા, કેટલાક બંદૂકો રાખતા. આનંદમુનિના મંડળના સંતો તેમને મળ્યા તે બધા પૂર્વદેશના હોવાથી ભાવ થયો. સત્સંગની વાત સાંભળી શ્રીહરિને ભગવાન જાણીને રહી ગયા. શ્રીહરિને કહે, “અમને પણ દીક્ષા આપો. તમને છોડીને અમે જવાના નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1583,"k":"para","g":"ત્યારે શ્રીહરિ કહે, “તમે ભારે અડબંગી છો. વારે વારે ગાળો બોલો છો. ગાંજો, લીલાગર પીઓ છો. એકલા ચાલો છો. નારી સાથે બોલો છો. ધન મળે તો રાખો છો. હથિયાર રાખો છો. સ્વાદે કરીને અન્ન ખાઓ છો. અમારા સંત એવું કંઈ કરતા નથી. જડભરત, શુક અને કપિલની પેઠે વર્તે છે. કોઈ મારે કે ગાળો દે તે સહન કરે છે. તેઓ ક્ષમારૂપી ખડ્ગ અને ધીરજરૂપી ઢાલ અને બ્રહ્મચર્યરૂપી બંદૂક રાખે છે. નિર્માલ્ય દેખાય છે, પણ નિયમથી શૂરવીર છે. અને નિયમરૂપી હથિયાર સર્વથી શ્રેષ્ઠ છે. શત્રુમાત્ર તેનાથી પરાભવ પામે છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1584,"k":"para","g":"આવાં શ્રીહરિનાં વચન સાંભળી પૂર્વદેશના સંતોએ લોઢાનાં હથિયાર છોડી દઈને હરિવચનમાં પ્રેમ કર્યો. પોતાની કંઠી માળા ઉતારી દીધી. લોકો તે જોઈને આશ્ચર્ય પામી ગયા. શ્રીહરિનો પ્રતાપ જોઈ સર્વે પરમહંસ થઈ ગયા. મોટી મોટી જટાઓ ધારી હતી તે શ્રીહરિ મળતાં ઉતારી દીધી. અગ્નિમાં બેસે છતાં બળે નહિ એવા સિદ્ધોએ પણ કેશ ઉતાર્યા. જળ ઉપર ચાલે અને ધારે તેમાં પ્રવેશ કરે એવાએ પણ જટા ઉતારી, અને શ્રીહરિએ કહ્યું તે પ્રમાણે કરવા લાગ્યા.","e":null,"s":["12/5/16-35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1585,"k":"para","g":"માંગરોળમાં મધ્યરાત્રિ વીતી ત્યાં સુધી કથા, કીર્તન અને ધ્યાન થયાં. પછી શ્રીહરિએ વાત કરતાં કહ્યું, “નિદ્રા, ભૂખ, તરસ વગેરે દેહના ધર્મ છે, પણ તેને નિયમમાં કરવાં. દેહને વધુ પડતો આહાર ન આપવો. ત્યાગી અને ગૃહીના નિયમ કહ્યા છે તેમાં દેહને વર્તાવવો. ભગવાન અને સત્પુરુષ વિના વેદ, નિયમ કે નીતિની વાત કોઈ પ્રવર્તાવી શકે નહિ. જેનું વર્તન દેહાકાર હોય તે વેદ ભણે તોય તેના અર્થને લેશ પણ પામી શકે નહિ. ભગવાન અને આત્મદર્શી સંત વેદનો અર્થ જાણે છે. સંત પોતે જ મૂર્તિમાન વેદ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1586,"k":"para","g":"“અમારી સમજણ જે રીતે રહી છે તેને આત્મદર્શી સંત યથાર્થ જાણે છે, ને તમને હેતે કરીને શ્રેય કરવા માટે કહે છે. વેદશાસ્ત્રના મત અનુસારે અમારાં વચન બધાં સુખ આપનારાં છે. આ પ્રમાણે સમજીને જે વર્તે છે તે અક્ષરધામને પામે છે. અમારાં વચનનો જેને ભાર નથી એવા જનો જમપુર જાય છે એ નિશ્ચય જાણજો.” એટલી વાત કરી શ્રીહરિ પોઢી ગયા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1587,"k":"para","g":"સવારે અરુણોદય થયો ત્યારે સંતોએ ઊઠીને નારાયણધૂન કરી. શ્રીહરિ કહે, “સંતો, હરિજનો જે જે નગર અને ગામમાં ધૂન કરે છે તેને અમે ત્યાં જઈને સાંભળીએ છીએ. વળી, સંતો, હરિજનો પ્રેમથી કીર્તન ગાય છે, તેને પણ અમે પ્રત્યક્ષપણે જઈને સાંભળીએ છીએ. એવી અમારી સદાની રીત છે.”","e":null,"s":["12/15/15-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1588,"k":"para","g":"લોજમાં શ્રીહરિએ સંતોને કહ્યું, “તમારા એક એક દ્વારા અનંત જીવો ઉદ્ધારવા છે. તમને હાથ જોડે, ભાવથી દર્શન કરે, ચરણમાં માથું નમાવે, અન્ન-જળ, વસ્ત્ર, ફળ-ફૂલ આપે તે બધા બ્રહ્માને દુર્લભ એવું અનંત અક્ષરધામનું સુખ પામશે.”","e":null,"s":["12/17/15-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1589,"k":"para","g":"ભૂજમાં શ્રીહરિ સંતોને કહે, “પુરની બહાર સુંદર વૃક્ષ જોઈને તેની નીચે ઉતારો કરવો. પ્રશ્નોત્તર શીખવા. જ્ઞાનનો વિચાર કર્યા કરવો. સાંખ્ય અને યોગનો અભ્યાસ નિત્ય રાખવો. ગીતા-ભાગવતનું શ્રવણ વારંવાર પ્રીતિપૂર્વક કરવું. ભાગવત શીખવું - એ પરમહંસનો શણગાર છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1590,"k":"para","g":"“પવિત્ર ગૃહે ભિક્ષા કરવી. બે જણે ભેગા મળીને ભિક્ષા લેવા જવું. કોઈ ભાવિક ભક્ત રસોઈ બનાવીને લાવે તે અન્નના ગોળા કરવા અને તે જળનું પ્રોક્ષણ કરીને જ કરવા. જળ નાખવું તે અન્નની શુદ્ધિ છે. ઝોળીને તળિયે ઘાસ નાંખી ગોળા ઝોળીમાં રાખવા. ડાબા હાથમાં ગોળો લઈ ગ્રાસે ગ્રાસે સ્વામિનારાયણ કહીને જ જમવું.”","e":null,"s":["12/39(38)/1-9"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1591,"k":"para","g":"ખોખરા મહેમદાવાદમાં શ્રીહરિ સંતોને કહે કે, “અમારા ધામમાં જે સુખ છે તેની આગળ અનંત કોટિ બ્રહ્માંડનાં સુખ સૂર્ય પાસે દીવા જેવાં દેખાય છે. એ ધામના તમે અધિકારી છો. તમને અમારો પ્રતાપ દેખાતો નથી, તેથી અંતર ભારે રહે છે, પણ તમારા એક એક દ્વારાએ અનેક જીવોનો ઉદ્ધાર કરવો છે. તમે મોક્ષના બીજરૂપ છો. અમે જે કંઈ વાત કરીએ છીએ, તે પ્રત્યક્ષ દેખીને કહીએ છીએ. તમે તેને દેખતા પણ નથી ને જાણતા પણ નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1592,"k":"verse","g":"‘કરત હમ જેતિ વાત હિ, પ્રત્યક્ષ સો દેખાત.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1593,"k":"verse","g":"તુમ દેખત જાનત નહિ, એસે હે યહ બાત.’","e":null,"s":["12/74/6-9, 38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1594,"k":"para","g":"શ્રીહરિએ ખોખરા મહેમદાવાદમાં સંતોને કહ્યું, “વર્ણી, સંન્યાસી, પરમહંસ, સંત, સાધુ - એમ જેટલા કંઈ ત્યાગીમાત્ર કહેવાય છે તેમણે નાનું સરખું પણ આયુધ ન રાખવું. જો રાખે તો તે જગતના બંધનનું કારણ બને છે. વળી, ત્યાગી થઈને ધન અને સ્ત્રીનો ત્યાગ પણ સર્વપ્રકારે રાખવો જોઈએ. છાને-છપને પણ ધન-નારીનો યોગ સાધુને લાંછન લગાડે છે. વળી, તેને સંગે પાપ પણ મોટું લાગે છે.” એમ વાત કરી શ્રીહરિ પુર બહાર આવ્યા અને વહેલાલ તરફ ચાલ્યા.”","e":null,"s":["12/77/21-23"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1595,"k":"para","g":"ખોખરા મહેમદાવાદમાં શ્રીહરિએ સંતોને કહ્યું, “દરેક આગેવાન સંતોએ ગામડામાં ફરવું. અમારા વચનરૂપી કોટમાં નિરભે થઈને રહેવું. તો માયા પ્રવેશ કરશે નહિ અને બંધન કરશે નહિ. દિવસે ગામની સમીપમાં રહેવું. મધ્યાહ્‌નકાળે ભિક્ષા માગવી, ભગવાનની ઇચ્છાએ જેવું અન્ન ઝોળીમાં આવે તે ઉદર ભરાય એટલું થાય ત્યાં સુધી ભિક્ષા માંગવી. સૂકું, લૂખું, પત્ર, કંદ, મૂળ, ફળ ઇત્યાદિનો આહાર કહેવાય, છતાં અમે અન્ન જમવાની છુટ્ટી આપી છે, જેથી તમે જેનું અન્ન જમો, એવા ઘણાય જીવોનો ઉદ્ધાર થાય.”","e":null,"s":["13/5/17-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1596,"k":"para","g":"કચ્છમાં કાળાતળાવ ગામે શ્રીહરિ બધા સંતોને મળ્યા અને કહેવા લાગ્યા, “અમારે તમારા દ્વારા કેટલાંય કામ કરવાં છે. તમે અમારા કલ્પવૃક્ષ સમાન છો. તમારાથી મને કોઈ અધિક પ્રિય નથી. તમે અમારા પ્રિય છો એમ જાણીને અમને જે વાત ગમે છે તે તમને કહીએ છીએ. તેનાથી તમારી કીર્તિ વધશે. કીર્તિ પામીને મરવું તે શ્રેષ્ઠ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1597,"k":"para","g":"“અમારી આજ્ઞાથી નિર્ભયપણે એકાકી વિચરવું. સતી અને શૂરવીર મરવા માટે ટૂક ટૂક થઈ જાય છે. પતંગિયું અગ્નિમાં બળી જાય છે. એવા શૂરવીર થવું. જગતના જીવો તુચ્છ છે ને તેની કીર્તિ પણ તુચ્છ છે. ભગવાન અને સંતને અર્થે જેટલું કષ્ટ સહન કરે તેટલી કીર્તિ વધે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1598,"k":"para","g":"“ભગવાનનું ધ્યાન સ્થિર આસન લગાવીને કરવું. દેહમાં વૃત્તિ લેશ પણ રહે નહિ તે રીતે ત્રણ દેહ, ત્રણ ગુણ ને ત્રણ અવસ્થાથી પોતાનું સ્વરૂપ ન્યારું (અક્ષર) સમજવું. જીવના સાચા સંગી ભગવાન તથા ભગવાનના સંત છે. રાતે સ્ત્રીઓનો શબ્દ સંભળાય નહિ એટલે ગામથી દૂર રહેવું. તેવી જેની સમજણ હોય તે જ સાચી સમજણવાળા છે. ધ્યાનનો અભ્યાસ કરતાં દેહની સ્મૃતિ ન રહે, અને સ્મૃતિ થાય તો ફરીથી ધ્યાનમાં બેસવું. લઘુ કરવા ઊઠવું પડે તો ફરીથી ત્યાં જ આસન ન કરવું. દેહ અને કુટુંબીની પેઠે આસનનો મમત્વ પણ તજવો. ભગવાન તથા સંતો અને હરિભક્તોનું કથા-કીર્તન, સ્મરણ, શ્રવણ કર્યા કરવું.”","e":null,"s":["13/7/1-9, 30-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1599,"k":"para","g":"ઘોડાસરમાં ઝાલમસિંહ બાપુના દરબારમાં શ્રીહરિ કહે, “દુઃખી (રોગી) સંતની સેવા મોટા ભાગ્યવાનને મળે છે. ધ્યાન કરીને વારંવાર મૂર્તિનો સાક્ષાત્કાર કરે, તોપણ તે દુઃખી સંતની સેવા તુલ્ય થઈ શકે નહીં. રોગી સંતની સેવા કરે તે મારી સેવા કર્યા બરાબર છે. એ સેવા તો રાધા-લક્ષ્મી જેવાં ભક્તો પણ ઇચ્છે છે, પણ તેને મળતી નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1600,"k":"para","g":"“દુઃખી સંતની સેવા કરે તેને કરોડ મહાપાપ લાગ્યાં હોય તોપણ નાશ પામે. કોઈ પણ પદાર્થની લાલચ વિના જેઓ સેવાની ભાવનાથી જ દુઃખી સંતની સેવા કરે છે તે ભગવાનના ધામમાં જાય છે. લાલચથી સેવા કરે તે ધામને પામે નહિ. દુઃખી સંતને દેખી તેની સેવાની જે ઉપેક્ષા કરે છે તે ચાંડાલથી પણ અધિક ચાંડાલ કહેવાય છે. કોટિ જ્ઞાન કથતો હોય પણ તે અંતે બહુ દુઃખી થાય છે. સંતો ને હરિજનો પર જેની વૈરબુદ્ધિ થઈ તેની અતિ દુર્ગતિ થાય છે. તે ગમે તેવો મોટો હોય તોપણ અમે તેની સહાય કરતા નથી. દયા વિના મોટાઈ શોભે નહિ.”","e":null,"s":["13/15/15-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1601,"k":"para","g":"ડભાણમાં શ્રીહરિ કહે, “સાધુતામાં અપાર મોટપ રહી છે. મોટા રાજાઓ પણ સાધુતાને નમે છે. સાધુતા આગળ ચૌદ લોકના કોઈ પણ સુખની ગણના નથી. અંતર્યામી પ્રભુ, જે જેટલી સાધુતા રાખે છે તેને જાણે છે.”","e":null,"s":["13/22/29, 36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1602,"k":"para","g":"ડભાણમાં શ્રીહરિ કહે, “અમારો અને મોટા મોટા સંતનો જે ડર રાખે છે તેના ઉપર અમે પ્રસન્ન થઈએ છીએ. મોટા સંત અને મોટા હરિભક્તો સભામાં જેને પ્રમાણ કરે તેને અમે પૂરા સંત માનીએ છીએ. જે સંતો સરલ સ્વભાવે વર્તે અને કોઈની સાથે દાવ બાંધે નહિ તે અમને ગમે છે. જે સંતે પોતાના કરતાં એક દિવસ પણ આગળ દીક્ષા લીધી હોય તેની અદબ રાખવી, એ ગુણે કરીને દીન વર્તતા હોય તોપણ તે મોટા છે એમ જાણી તેની સાથે વિવાદ ન કરવો. આમન્યા રાખવી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1603,"k":"para","g":"“સાધુ, બ્રહ્મચારી, પાળા તમે સૌ અમારા કહેવાવ છો, એટલે તમારા સુખ માટે અમે આ તમને વિવેક શીખવીએ છીએ. જો આ પ્રમાણે નહિ વર્તો તો તમારી મોટપ રહેશે નહિ. જે દિવસે અદબ ચૂક્યા, તે દિવસે સામાન્ય ભેખ જેવા પણ નહિ રહો. મોટા સંતનો ડર અને ઝાઝાં ચોમાસાંવાળાની અદબમાં મોટપ રહેલી છે. ડર અને અદબ એ બધા જનને દેખ્યામાં આવે. સંત થઈને સંતને દબાવે તો તે પ્રતિષ્ઠાહીન થઈ જાય છે. સર્વે સાધુ, બ્રહ્મચારી ને પાળાને આ રીત અમે પરમ હેત લાવીને કહી છે. સત્સંગમાં મોટપ લેવાની ઇચ્છા હોય તો ડર અને અદબ બહુ કરીને રાખજો. ખાવામાં-પીવામાં, આસનમાં, નાહવા-ધોવામાં બધી ક્રિયામાં આ વિવેક શીખવો. સંતનું આ ભૂષણ છે.”","e":null,"s":["13/24/29-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1604,"k":"para","g":"કચ્છમાં વિચરતા શ્રીહરિ માંડવીના માર્ગે ચાલ્યા. વચ્ચે અંજારનો માર્ગ ફંટાયો. ત્યાંથી સંતમંડળ શ્રીહરિથી જુદું પડતું હતું. શ્રીહરિએ સંતોને કહ્યું, “ભક્તિમાં મગ્ન રહેવું. મન મૂંઝાય ત્યારે અમને કહેવું, અનાદિકાળથી મન જીવને લખચોરાશીમાં ફેરવે છે. વારંવાર જન્મ-મરણ લેવડાવે છે. મન સદા માયાનો દાસ થઈને રહ્યું છે. તેનો નિવાસ જ માયામાં છે. પરંતુ એ માયા અક્ષરના મહા તેજમાં લીન થઈ જાય છે. તે દૃષ્ટાંતથી કહીએ છીએ જે, જેમ તારામંડળનો પ્રકાશ રાત્રે પૃથક્ પૃથક્ દેખાય છે, પણ સૂર્ય ઉદય થતાં બધા તારા તેમાં લીન થઈ જાય છે, તેમ માયા અક્ષરમાં લીન થઈ જાય છે. જીવ જ્યાં સુધી માયાનો સંબંધ એકરસ થઈને કરે છે, ત્યાં સુધી માયારૂપ થઈને માયામાં લીન રહે છે. પરંતુ, જેવો માયાનો સંબંધ છે તેવો સંબંધ જો અક્ષરનો અને શ્રીહરિનો કરે તો ચોરાશીના ફેરા ટળે.”","e":null,"s":["13/34/8-17"],"sv":["जिहां लग जीव सोउ, माया को संबंध रखत तेहि ।\n\n मायारूप हि होउ, माया में रहत लीन होई ॥\n\n माया को संबंध जीय जेसे । कर रहे एक रस होई तेसे ॥\n\n तेसो जो रखे अक्षर हरि केरा । छुट जावे चोराशी फेरा ॥"],"mt":false,"gl":null,"a":false},{"i":1605,"k":"para","g":"ગઢપુરમાં શ્રીહરિ મુક્તમુનિને કહે, “મોક્ષ સંબંધી જ્ઞાન સંતના યોગ વિના પ્રાપ્ત થતું નથી. પિંડ અને બ્રહ્માંડમાં જીવની વૃત્તિ ચોંટી રહી છે. સંત જ્ઞાનરૂપી કુહાડાથી તેનાં મૂળ કાપે છે ને જીવની વૃત્તિ ભગવાનમાં ચોંટાડે છે. એ જીવે ત્યાં સુધી સંતની આગળ નિર્માનીપણે વર્તે. પોતાનામાં ઘણું જ્ઞાન હોય અને સંતમાં તેટલું જ્ઞાન ન હોય, છતાં સંતનો ગુલામ થઈને રહે, તેમની સાથે વાદવિવાદ કરે નહિ. ભગવાનનાં વચન પાળે, સંતનો અભાવ બોલે નહિ, દેહમાં રોગ થાય અને કોઈ સંત પોતાની ખબર ન રાખે, છતાં સંતનો ગુણ ગ્રહણ કરે, તે સંત શ્રેષ્ઠ છે.”","e":null,"s":["13/50/13-22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1606,"k":"para","g":"ગઢપુરમાં જીવેન્દ્રના દરબારમાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “અમે તો સાધુનો માર્ગ ગ્રહણ કર્યો છે, તેથી કોઈનું ભૂંડું થાય તેમ ઇચ્છતા નથી. તેનો ઉદ્ધાર થાય એમ જ વિચાર કરીએ છીએ. ગ્રંથમાં શુભગુણ અપાર લખેલા છે. જેવી જેની રુચિ હોય તે ગ્રહણ કરે, પણ સાધુતામાં જ બધા ગુણ રહેલા છે. એથી અમે જે જે કામ કરીએ છીએ તે સાધુતા રાખીને જ કરીએ છીએ.”","e":null,"s":["13/68/28-30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1607,"k":"para","g":"શ્રીહરિએ ડભાણમાં વાત કરી કે, “સાધુતા તજીને મેરુ જેવી મોટી મોટી વાતો કરે, તો પણ તે અસર ન કરે. સાંભળે તેને અપ્રિય લાગે. સાધુતા રાખીને અલ્પ સરખી વાત કરે તો પણ સમાસ થાય ને બધાને પ્રિય લાગે. કોઈ સાધુ વાતને ફેરવતાં ફેરવતાં સ્વાર્થ ઉપર લાવે ને યુક્તિથી વાત કરે તેનાથી સમાસ થાય નહિ. સત્સંગ કરીને જેને અભાવ આવે છે તેને તે પાપથી ભૂત કે બ્રહ્મરાક્ષસ થવું પડે છે.”","e":null,"s":["14/20/17-22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1608,"k":"para","g":"જેતલપુરના મહોલમાં શ્રીહરિ સંતોને વાત કરતાં કહેવા લાગ્યા, “હથિયાર કરતાં સાધુતાની મોટાઈ અધિક છે. અંતઃશત્રુ મોટા અસુર છે. તે તોપથી પણ મરતા નથી, પણ નિષ્કામ, નિર્લોભ, નિઃસ્વાદ, નિઃસ્નેહ, નિર્માન - એ પંચવર્તમાન તોપથી અધિક છે. તે કોઈને દેખ્યામાં આવતું નથી. જેને પ્રગટ ભગવાન મળે અને તેને પ્રસન્ન કરવા માટે જે તેમના વચનમાં વર્તે, તેને સહેજે પ્રાપ્ત થાય છે. જગતમાં જે વચન માને તેના પર પ્રસન્ન થાય છે, તો ભગવાનનું વચન માને તેના પર ભગવાનને હેત થાય એમાં શું કહેવું? પોતપોતાના મનમાં તો સૌ પોતાને મોટા માને છે, પણ બીજાના વચનમાં વર્તવું તે કઠણ છે. એટલા માટે અમે પ્રકરણ ફેરવીએ છીએ. જેને ખપ હોય તે જ નભી શકે. કપટ રાખ્યું રહે નહિ. એક જણ દુષ્ટ હોય તો બધા દુષ્ટ દેખાય. સોનામાં ભેગ દેખાય ત્યાં સુધી સોની તેને તપાવે છે, એમ અમે કરીએ છીએ. વચન અનુસાર જે ન વર્તે અને વિષયમાં રાગ રાખે તથા સાચા સંતથી વધારે ત્યાગ દેખાડે, અમારો ડર રાખે નહિ, તેને માટે આજે પ્રકરણ ફેરવીએ છીએ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1609,"k":"para","g":"અમારા સંતોએ મોઢા ઉપર વસ્ત્ર રાખવું. જેટલા સંત ભેગા રહેતા હોય તેમાં એક સંતે આગળ ચાલવું. જેની નેત્રવૃત્તિ નિયમમાં રહેતી હોય, એવો જે બધાયની નજરમાં આવે તેવો પીઢ સંત હોય તેને આગળ રાખવો. એકની નજરમાં આવે તેને રાખવો નહિ. નારીનું મુખ જેટલીવાર દેખાય તેટલા ઉપવાસ કરવા. ઉપવાસ જે નહિ કરે તેને અંત સમયે જમના દૂત આવશે. ત્યારે જે ભગવાનને તથા મોટા સંતને ‘હું ભૂલ્યો’ ‘હું ભૂલ્યો’ એમ પ્રાર્થના કરશે ને પોતે જેટલા ઉપવાસ ન કર્યા હોય તે પાપ સંત-હરિભક્તોને કહી દેખાડી, હાથ જોડીને કહેશે કે હું શ્રીહરિનો ચોર છું, મેં ઘણા અપરાધ કર્યા છે. મારા અપરાધ માફ કરો. એમ દીન-આધીન થઈ નિષ્કપટ તથા સરળ થઈને વર્તે, તેના પર સૌની કૃપા થાય છે. ઈર્ષ્યા, મત્સર અને માન રહિત થઈ સેવા કરવાની તેને રુચિ થાય ત્યારે તેનું સારું થાય.”","e":null,"s":["14/71/13-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1610,"k":"para","g":"જેતલપુરમાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “અમારો સાધુ જો નારી સન્મુખ જુએ તો તેને અમે લબાડ માનીએ છીએ. અમારા સાધુ થઈ જે સ્ત્રીઓ સન્મુખ બેસે ને કોઈપણ રીતે સ્ત્રીઓનો પ્રસંગ રાખે તેની મતિ વિપરીત થઈ જાણવી. અમારા વચનનું ઉલ્લંઘન કરી વર્તે તેની મહોબત અમે રાખતા નથી. સંત, વર્ણી કે પરમહંસ, પછી જે પણ નિયમ ભંગ કરે તેને સત્સંગથી બહાર કરીએ છીએ. ભલે ગમે તેવો તે ગુણવાન હોય તો પણ આ રીત રાખી છે, કારણ કે જીવ ગયા પછી કાયા શી કામની?”","e":null,"s":["14/72/16-20"],"sv":["संत होई हमार, नारी सन्मुख देखे जोउ ।\n\n ताकुं कहत लबार, हरिजन जानत बात सब ॥\n\n हमारे संत होई कर जेहा । नारी के सन्मुख बैठे तेहा ॥\n\n नारी को रखे प्रसंग कोउ रीता । मति ताकी जानना विपरीता ॥\n\n हमारे वचनरूप कोट जेता । उल्लंघन ताको करत तेता ॥\n\n संत वर्णि संन्यासी जेहु । पदाति तोरि रीत कुं तेहु ॥\n\n ताकुं करत सत्संग ब्हारा । एसि की म्होबत न रखत लगारा ॥\n\n गमे तेसे होय गुनवाना । जीय गये पिछे काय रहाना ॥"],"mt":false,"gl":null,"a":false},{"i":1611,"k":"para","g":"જેતલપુરમાં શ્રીહરિ કહે, “હરિજનોએ સાધુની રીત તપાસીને ચાલવું. વળી, બાઈઓનો સત્સંગ વિવેક વિનાનો હોય છે. તેને માન દઈને બોલાવે તો આધીન થઈ જાય અને અપમાન કરે તો કલંક આપે. સીતાએ પણ લક્ષ્મણને કલંક દીધું છે. તો બીજાની શી વાત? તેનાથી દૂર રહે તો જ બચાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1612,"k":"para","g":"“નારીનાં બધાં અંગ કલંકરૂપ છે, તેથી વિવેકી સ્ત્રીઓ તેને ઢાંક્યાં રાખે છે અને મોટા લોકો ઓઝલ રાખે છે. વળી, પુરુષથી દૂર રહે છે, પોતાના યુવાન પુત્રથી દૂર રહે છે. જેટલા મોટા કહેવાય તેટલી લાજ રાખે છે. લાજ વિનાનાં હોય તે ફૂટલાં વાસણ જેવાં છે. ફાવે તેટલાં રૂપવાન હોય તે કામ ન લાગે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1613,"k":"para","g":"“સુવર્ણમાં રૂપ છે તો સૌને પ્યારું લાગે છે, પણ ડાહ્યો માણસ તેમાં મૃત્યુ દેખે છે, તેમ પાંચેય પ્રકારના શબ્દાદિક વિષયો અતિ ઉત્કૃષ્ટ હોય, પણ તેમાં મૃત્યુ નજીક રહેલું છે. ભય અને દુઃખમાત્ર તેમાં રહેલાં છે. એવું જે સમજે તેના ઉપર અમને હેત થાય છે.”","e":null,"s":["14/72/23-37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1614,"k":"para","g":"સારંગપુરમાં જીવા ખાચરના દરબારમાં શ્રીહરિ સંતોને કહે, “ત્યાગી બે પ્રકારના - ગરીબ અને પ્રપંચી. ગરીબ સરળ હોય, પ્રપંચી અધિક સાધુતાનો દંભ કરે. લોકરંજન કરવાવાળા બહુ વાતો સંઘરી રાખે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1615,"k":"para","g":"“સરળ સંત પોતાના જીવનું કલ્યાણ કરવાનો વિચાર નિત્ય રાખે. જેમ નટ દોર પર ચાલે ત્યારે કોઈ સામે નજર ન કરે તેમ વર્તે. પોતાનું હિત કરવા તાન હોય તેને પૂજાવાની મોટપ હોય નહિ. કપટ રહિત આવા સંતની મોટાઈ ભગવાને આપી છે, પણ તે ઢાંકીને વાત કરે. પોતાની આ મોટપ કોઈ જાણી ન જાય તેનું જાણપણું રાખે છે, તેથી સંસારી તેમને ઓળખી શકતા નથી. પોતાનો કોઈ તિરસ્કાર કરે તો તેના પર રોષ કરવાને બદલે અતિ પ્રસન્ન થાય છે. કોઈ સંતના દોષ ન જુએ તેની પૂર્ણ સંતતા કહેવાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1616,"k":"para","g":"“પોતાની મોટપ માને ને બીજાને જણાવવા રાતદિન ઉપાય કરે, બીજાની મોટપ જોઈ હૃદયમાં બળી મરે ને પોતાને માને એવા બે-ચાર સંતોનાં વખાણ કરે ને બીજાનાં અપમાન કરે. બીજાની પૂજા-પ્રતિષ્ઠા ખમી ન શકે, તેનું અપમાન કરી જંપે, આવા બીજાને ન્યાયપ્રિય લાગે એમ કપટથી બોલે, પણ કપટ જણાવા ન દે. પોતાની પૂજા-પ્રતિષ્ઠા અપાર કરાવે અને બીજા સંતને અન્યાય કરે એવા સંસારી સંતો બુદ્ધિમાન હોવાથી અમારી બધી વાત મુખે શીખી લે, અને વાતો કરી લોકોને રંજન કરે અને સત્સંગમાં દોષ દેખાડે. આવો જે હોય તે સુંદર દૂધપાક કરી છાનું ઝેર નાખીને જમાડે તેના જેવો અમને લાગે છે.”","e":null,"s":["14/82/15-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1617,"k":"para","g":"સારંગપુરમાં ફૂલદોલ પર સંતોનાં મંડળ આવવાં લાગ્યાં. શ્રીહરિ સંતોને કહે, “અમારે સંતથી કોઈ અધિક નથી. કેટલાક સંતો વિવિધ ગ્રંથ ભણે છે, પણ પ્રથમ સંતનો ગુણ શીખીને ભણવા લખવાનું શીખવું. સંતની વાત શીખે, પણ અંતરમાં ભગવાન વિના બીજો વિચાર રાખે તો તે હરિનો ચોર છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1618,"k":"para","g":"“મોટા સંત હિત લાવીને તેને વાત કહે, પણ એ છેટે રહે છે. તોપણ સંતની રીત જીવને સુધારવાની છે, તે તેની પાસે જઈને શિખામણ દે છે, પરંતુ તે ઊલટી કરી નાખે છે. ગમે તેટલું જતન કરે તોપણ તેની મતિ સવળી થતી નથી ને મનધાર્યું કરે છે. પછી સંતનો શો વાંક?","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1619,"k":"para","g":"“સત્પુરુષ આકાશ જેવા છે ને સાધુ-હરિજન વાદળ જેવા છે. તે વાદળ જેવા જનની એક સ્થિતિ રહેતી નથી, આવ-જા કરે છે. એક સ્થિતિ બંધાય નહિ ત્યાં સુધી ક્યારેય વિશ્વાસ ન આવે. માટે એવા હરિજન કે સાધુને ભણાવવો નહિ, તેને રાખવો જ નહિ. જો રાખવો તો પાછળથી અમને સંભારશો. જેને શિષ્યનો લોભ હશે તે અમારા વચનનો અનાદર કરીને પણ તેને રાખશે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1620,"k":"para","g":"“સાધુ નિર્લોભી ત્યારે જ કહેવાય કે જ્યારે શિષ્યનો પણ લોભ ન રહે. મુક્તમુનિ અને બ્રહ્મમુનિ બન્ને સંત શિરોમણિ છે, છતાં શિષ્યનો લોભ જ્યારે કર્યો તો પરસ્પરનું હેત તૂટ્યું. અમી દૂર થયું. એ અલૌકિક હેત ન કહેવાય.”","e":null,"s":["14/84/1-14"],"sv":["मुक्तमुनि ब्रह्ममुनि हि, शिरोमनि संत दोउ ।\n\n लोभ न रखत हें जाहि लग, शिष्य हि को जो सोउ ॥\n\n शिष्य को लोभ जब कर लिन, परस्पर हित हि जेह ।\n\n अमी दूर तबहि होवहि सो, अलौकिक हित नहि तेह ॥"],"mt":false,"gl":null,"a":false},{"i":1621,"k":"para","g":"સારંગપુરમાં શ્રીહરિ સંતોને કહે, “કૌપીન અને તુંબડાનું જતન જેટલું થાય છે તેટલું ભગવાનનું જતન થતું નથી. દેહમાં આસક્તિ છે તેવી ભગવાનમાં થતી નથી. આવો અવિવેક સાધુને રહી જાય છે. અને વારંવાર મોક્ષમાં વિઘ્ન કરે છે. પદાર્થમાં છે એવું મમત્વ ભગવાનમાં કરવું એ વાતમાં વેદ, શાસ્ત્ર અને અનંત ગ્રંથો સમાઈ ગયા.”","e":null,"s":["14/84/19-23"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1622,"k":"para","g":"કુંડળમાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “સંતો! અમારી મરજી પ્રમાણે તમારે વર્તવું. અમારા કહેવા પ્રમાણે તમે વ્રત ધારણ કર્યાં, તેથી અમે પ્રસન્ન થયા છીએ. હવે જમાડીએ છીએ તો જમો. રસોઈમાં સાકર, ઘી, ગોળ કોઈ લાવે તો લેવું નહિ, પણ ઝોળીમાં જે કાંઈ આવે તે જમવું. ઝોળીના અન્નના ગોળા વાળીને જમવા. ઝોળી વિના દૂધ, દહીં, ફળ વગેરે વસ્તુ આવે તે ખાવી નહિ. આખો દિવસ અને રાત અનિયમિત ખાધા કરવું તે પશુનો નિયમ ગણાય. ખાઈને કથાવાર્તા કર્યા વિના સૂવું નહિ. પશુ પંખી વગેરે અજ્ઞાની જીવો પણ દિવસે સૂતાં નથી. ભૂમિનું રાજ્ય કરતા હોય તે પણ દિવસે સૂતા નથી, જો સૂએ ને કેફ વ્યસન કરે તો રાજ્ય નાશ પામે. રાજા કરતાં પણ ગુરુ અને સંતો અધિક કહેવાય, કારણ કે રાજા પણ તેમને પૂજ્ય માને. ગુરુમાં ગુરુનાં લક્ષણ હોય તો ગુરુ. અને સંતમાં સંતનાં લક્ષણ હોય તો સંત. નહિ તો ત્યાગી થયે શું વળ્યું?”","e":null,"s":["15/15/9-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1623,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ મોટેરા સંતોને બોલાવીને ત્યાગીના ધર્મો કહેતાં કહ્યું, “શાસ્ત્રોમાં ત્યાગી અને ગૃહસ્થના ધર્મો પૃથક્ પૃથક્ નિરૂપ્યા છે. તેમાં વૈષ્ણવ ત્યાગી માટે ધન-સ્ત્રીનો ત્યાગ અવશ્ય રાખવા જણાવ્યું છે. ધન-સ્ત્રી, ઘર-પરિવાર, દેહ અને દેહના સંબંધીનો ત્યાગ રાખે ને પોતાનું વાહન ન રાખે, પોતાના માટે આશ્રમ-મઠ ન બાંધે. આ નિયમોમાંથી છૂટ લે તો તેને ત્યાગના માર્ગથી ભ્રષ્ટ થયો જાણવો, એ પછી ભગવાનનો રહેતો નથી. ત્યાગી થઈને ગામ-ગરાસ રાખે, બાગ-બગીચા નિજ અર્થે કરાવે, નાનું સરખું પણ વ્યસન રાખે, અને જેટલાં કંઈ શસ્ત્ર કહેવાય છે તેમાંથી એક પણ શસ્ત્ર રાખે, કેફ કરનારી વસ્તુ અંગીકાર કરે, મુખથી ગાળ બોલે, એ અમારો સાધુ નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1624,"k":"para","g":"“વળી, અમે આપેલા નિર્લોભ, નિર્માન, નિષ્કામ, નિઃસ્નેહ, નિઃસ્વાદ – એ પંચવ્રત નિયમ જેને ન હોય, ભગવાનને આધીન નહિ, પરંતુ ઇન્દ્રિયોને આધીન વર્તે, જેને ભગવાનનાં કથા-કીર્તન, ધ્યાન-ભજન, સ્મરણ ન હોય, ભગવાનને નિરાકાર કહે એવા ભેખ પાખંડી છે. તોફાની, ફેલી, ઢોંગી, કીમિયાગર, મંત્ર-જંત્ર કરનાર, એવા લોકોને સાધુ કહેવાય નહિ. તેને રાજા જેલમાં નાખે તોપણ તેને દોષ લાગે નહિ.”","e":null,"s":["15/53/32-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1625,"k":"para","g":"વડતાલમાં મધ્યરાત્રિ થઈ. બધા સંતો સૂઈ ગયા હતા. થોડા જાગતા હતા. શ્રીહરિ તે સૌને વાત કરવા લાગ્યા, “અમે મોક્ષની જે જે વાત કરીએ છીએ તે જે વિચારતા નથી તે કોરા રહી જાય છે. જે વાતનો અભ્યાસ થાય તે જ વાત દૃઢ થાય તે લોકમાં પણ પ્રત્યક્ષપણે જણાય છે. ભગવાનના અવિનાશી સુખમાં જેની દૃષ્ટિ પડી હોય તેની અલૌકિક સમઝણ હોય છે. એ સમઝણ દેશકાળે કરીને ક્યારેય ફરે નહિ. ભગવાન અને મોટા સંતનો ક્યારેક વિયોગ થઈ જાય ત્યારે અમે કરેલી વાતનો ખપ રાખે તો તેની સહાય થાય છે. અમે જેટલી વાત કરીએ છીએ તે અલૌકિક છે. લૌકિક સુખમાં જેની બુદ્ધિ રહે છે તેને અર્થે એ વાત આવતી નથી. ચિંતામણિ મળે પણ પારખ વિના તેને પથ્થર જ દેખે છે.” એટલી વાત કરીને શ્રીહરિ સંતોને મળ્યા અને પછી સૂતા.","e":null,"s":["15/65/2-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1626,"k":"para","g":"વડતાલમાં સંતમંડળ ભેગાં થયાં. સંતોએ વિવિધ તપ કર્યાં હતાં. એ જાણી શ્રીહરિ પ્રસન્ન થયા પછી બોલ્યા કે, “તમે સાચા શૂરવીર સંતો છો. વળી, એક એકથી અધિક છો અને કહ્યું તેથી અધિક કરી શકો તેમ છો એમ અમે જાણ્યું છે. પરંતુ, અમારી આ એક વાત તમે માનો કે, તમે દેહ નથી, પણ આત્મા છો. ચૈતન્યરૂપ છો. દેહ દુઃખરૂપ છે, ચેતનના સંબંધે કરીને ચેતન જેવું દેખાય છે પણ તે જડ છે. તે ફાવે તેવું રૂપવાન, ધનવાન, સત્તાવાન, બુદ્ધિમાન કે ઉદ્યોગમાં કુશળ હોય પણ આત્માનો સંબંધ ન હોય તો જડ બની જાય છે. માટે તેને જડરૂપ માનીને તમારું સ્વરૂપ આત્મા સમજો. આત્માને ચેતન સમજવો.”","e":null,"s":["16/13/34-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1627,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “સંગ્રહ ન કરવો એ ત્યાગીની ઉત્તમ રીત છે. ત્યાગી થઈને સંગ્રહ કરે તેટલું તેને બંધન અને ક્લેશ થાય છે. ભગવાન વિના બીજી વસ્તુમાં સુખ દેખાય તેટલો મૂર્તિમાન ક્લેશ જાણવો. ભગવાન સિવાય બીજી વસ્તુમાં રાગ રહી જાય તેટલી બાળકબુદ્ધિ છે. સત્સંગ કરતાં કરતાં જ્યારે જીવમાં ભગવાનથી અધિક કોઈ ન રહે ત્યારે માયાને તરી ગયો જાણવો.”","e":null,"s":["16/53/28-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1628,"k":"para","g":"શ્રીહરિએ પીપળાવમાં સંતોને વિવેક શીખવતાં કહ્યું, “હરિભક્તોએ રસોઈ આપી હોય તે ભાવ હોય કે સાધુ ભેળું કરીને ન જમે. ને અમને પણ કહે કે જુદું જુદું પીરસજો. અમે તેને રાજી રાખવા જુદું પીરસીએ, પણ તમારે સાધુની રીતે ભેળું કરી પાણી નાખીને જ જમવું. પોતપોતાનું તુંબડું ભરીને જ બેસવું.”","e":null,"s":["16/55/31-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1629,"k":"para","g":"જેતલપુરમાં સંતોને શ્રીહરિ કહે, “સંતના વર્તનમાં ફરક ન હોય અને કોઈ જૂઠું કહે તો તે નારકી થાય છે. મુક્તમુનિ સરખા સંતમાં કાંઈક ફરક જોવામાં આવે તો એક અમારી આગળ જ કહેવું પણ બીજાની આગળ ચૂપ રહેવું. જેને જેની સાથે મન જુદું પડ્યું હોય તેને તેનામાં દોષ ન હોવા છતાં દેખાય છે. માટે જેને એકમન હોય એવા પાંચ જણને દોષ જોવામાં આવે ત્યારે તે દોષ સાચો માનવો. પોતાનો દોષ જે કબૂલ કરે તેને સત્સંગનો ખપ છે અને જે ન કરે તેને ખપ નહીં હોવાથી તેની સાથે કોઈએ સ્નેહ રાખવો નહીં. જેમાં જેટલો ધર્મ હોય તેટલી મોટાઈ તે પામે છે. ધર્મ ન હોય તેને શબ તુલ્ય જાણવો.”","e":null,"s":["17/48/16-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1630,"k":"para","g":"વહેલાલમાં શ્રીહરિ સંતોને વાત કરવા લાગ્યા, “સંતની રીત જેવી કોઈની પરમ પવિત્ર રીત નથી. મોટા મોટા દેવ અને ઋષિઓ પણ સંતને પૂજે છે. ભગવાનને પ્રસન્ન કરવાનું તાન હોય તે સાધુ ક્યારેય વર્તનમાં ફેર પડવા દેતા નથી. જેને વર્તનમાં ફેર હોય તે સૌના દેખ્યામાં આવે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1631,"k":"para","g":"“સાધુએ દિવસમાં એક વખત જમવું. બીજી વખત કોઈ જમાડે તો જમવું નહિ. એક વખત જમવાનો નિયમ હોય તે બોલો. દેહમાં ક્યારેક રોગ હોય અને અન્નની અરુચિ હોય, થોડું અન્ન ખવાતું હોય ત્યારે તથા જેના દાંત પડી ગયા હોય અથવા આખો દિવસ ભારે સેવા કરી હોય અથવા જમેલા અન્નની ઊલટી થઈ ગઈ હોય અથવા પંદર વર્ષથી ઓછી ઉંમર હોય એટલા સંતોને બીજીવાર જમવાની અમે છૂટ આપીએ છીએ.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1632,"k":"para","g":"પછી જે એક વખત જમતા હતા તે સભામાં ઊઠીને બોલ્યા. શ્રીહરિએ તેમને કહ્યું, “તમારા નિયમનો ભંગ થવા દેવો નહિ. અમારે વર્ષોવર્ષ તમને સાથે લઈને સત્સંગમાં ફરવું છે અને ઘણી ઘણી વાતો કહેવી છે. હરિ વિના બીજે ચિત્ત દોડે છે એટલી જીવમાં કસર છે અને ભજનમાં વિઘ્ન થાય છે.”","e":null,"s":["17/78/18-37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1633,"k":"para","g":"આણંદ જતાં રસ્તામાં શ્રીહરિ સંતોને હિતકારી વાત કહેવા લાગ્યા, “સાધુતા સમાન કોઈ નિધિ અમે જોયો નથી. સાધુતા જેવી કોઈ પદવી નથી. એ પદનો મહિમા અપાર છે. સાધુતા આગળ પારસ, ચિંતામણિ કે કલ્પતરુની કોઈ ગણના નથી. અવતારો પણ સાધુને ભાવથી માને છે. રાજારૂપે આવે તો પણ તેમના શિષ્ય થાય છે. માટે સાધુતાનું પદ સર્વથી અધિક છે. આવું ઊંચું પદ જાણ્યા વિના સાધુતામાં કાચો રહે તે સંત ભેગો રહેતો હોય તોપણ તેનામાં રહેલા અન્ય ગુણો નિષ્ફળ થઈ જાય છે. કામ પડ્યા વિના સાધુતાનો ગુણ દેખાય નહીં. સાધુ સાધુ સરખા જ લાગે. સાધુતા સમય આવે પરખાય છે.”","e":null,"s":["17/92(93)/1-6"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1634,"k":"para","g":"વડોદરામાં મુક્તમુનિએ સભા જીતી ત્યારે બે સાધુને ઈર્ષ્યા આવી, તે પર શ્રીહરિએ વાત કરતાં કહ્યું, “ઈર્ષ્યા સમાન કોઈ બીજો દોષ નથી. વિમુખ થાય પણ મરે ત્યાં સુધી ઈર્ષ્યા જાય નહિ. મોટા દૈત્યોએ મરવા છતાં ઈર્ષ્યા મૂકી નથી. સંત થઈને ઈર્ષ્યા રાખે તે દૈત્ય સમાન છે. જેનામાં ઈર્ષ્યાનો સ્વભાવ છે તે અમોને ગમતા નથી. તેને અમે સંત કહેતા નથી. તેવી જ રીતે માન, ક્રોધ, કામ, લોભ, મત્સર, અસૂયા વગેરે દોષો છે તે સંતને વિપરીત કરી દે છે. એમાંથી એક પણ હોય તો આખો અધર્મ સર્ગ આવીને વસે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1635,"k":"para","g":"“સંત સંતમાં બહુ સાવધાની રાખવી. જેટલું ગાફલપણે વર્તાય તેટલો અધર્મ સર્ગ પેસી જાય છે અને ખુવાર કરે છે. છીંડું પડ્યા પછી સંતપણું ટકવું કઠણ છે. સંત સમાન કોઈ મોટાઈ નથી, પણ મહિમા ન હોય ત્યાં સુધી બાળકને ચિંતામણિ મળી હોય પણ તેને પથ્થર સમજે તેના જેવું છે. મહિમા વગર રંકપણું ન જાય. સંત ભેગા રહીને સંતનું માહાત્મ્ય ન સમજાય તો રંક રહ્યા ગણાય. ભેગા રહીને વિમુખ બન્યા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1636,"k":"para","g":"“માહાત્મ્ય વિના બીજા ફાવે તેટલા ગુણો હોય પણ મોક્ષ થાય નહિ. નરકમાં પડેલા જીવ પણ ભગવાન કે સંતનું માહાત્મ્ય સમજીને તેમને એકવાર સંભારે તો ધામમાં જાય છે. અને ધામમાં બેઠો હોય પણ માહાત્મ્ય ન હોય તો ઘોર નરકમાં પડ્યા સમાન છે. સુખ અને શાંતિમાત્ર માહાત્મ્યમાં રહેલાં છે. નિયમ અને ધર્મ વિનાનું માહાત્મ્ય સાચું નથી, પણ કપટરૂપ છે. સંતનો વેષ ધરીને અંતરમાં જેટલું કપટ રાખે છે તેવું ફળ થાય છે.”","e":null,"s":["18/14/5-25"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1637,"k":"para","g":"આદરજમાં રતુ ખાંટના ભક્તિભાવને વશ થઈ દિવાળી અન્નકૂટ કરવા શ્રીહરિ સંતમંડળ સહિત પધાર્યા. દીપમાળા પ્રગટી. આરતી, ધૂન થઈ રહી. પછી શ્રીહરિ પ્રસન્ન થઈને સંતોને ઉપદેશ વચન કહેવા લાગ્યા કે, “જેનામાં સંતના ગુણ છે તેને અમે સૌથી અધિક ગુરુ કરીને માનીએ છીએ. તેની મોટાઈ જે સહન ન કરે તે સંતમાં રહી શકતો નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1638,"k":"para","g":"“સંતને મોટાઈ વીંછણ જેવી છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1639,"k":"para","g":"“શ્રીકૃષ્ણ ભગવાને સૌ કરતાં સંતને વહાલા ગણ્યા છે. નારદજી પોતાને ત્યાં આવે ત્યારે શ્રીકૃષ્ણ તેમનાં ચરણ ધોઈને તે જળ પોતાના માથે ચઢાવતા ને ભવનમાં છાંટતા. દુર્વાસાને રથમાં બેસાડી તે રથ પોતે ખેંચ્યો! પાંડવના યજ્ઞમાં ભક્ત કે અભક્ત જે કોઈ ઋષિ આવ્યા તેમના પગ ધોયા, છતાં તેમની કીર્તિ અધિક ને અધિક રહી. મોટા થઈને બીજાને નમે છે તેની મોટાઈ વધે છે. સરોવર ને નદીથી સમુદ્ર અતિ નમતો છે, તો બધું જળ ગ્રહણ કરવા શક્તિમાન થાય છે. સંતમાં ગુણ હોય તે કામ પડે દેખાય છે. સંતને સેવીને શક્તિમાન થાય તેટલી મોટાઈ અમે તેને આપીએ છીએ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1640,"k":"para","g":"“આજે દિવાળીનો શ્રેષ્ઠ દિવસ છે. આજે સૌ સંત-હરિભક્તોમાંથી જેને મોટાઈનો સ્વાદ લેવો હોય તેને અમે મોટાઈ આપીએ. આજ સુધી કોઈને તેનો સ્વાદ આવ્યો નથી. કોઈના મનમાં મોટાઈના સંકલ્પ થતા હોય તે આવો અમે રાજી થઈને આપીએ. અમારી આપેલી મોટાઈ કોઈથી મિથ્યા થશે નહિ.”","e":null,"s":["18/30/4-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1641,"k":"para","g":"વડનગરમાં સંતો ઊતર્યા હતા તે ધર્મશાળામાં શ્રીહરિ પધાર્યા. સંતોની પંક્તિ થઈ. શ્રીહરિએ સાકરના લાડુ સંતોને પીરસ્યા. વચમાં ચોકવાળી તે ધર્મશાળાની જગ્યા હતી તે જોઈને શ્રીહરિ બોલ્યા કે, “વડતાલ અને શ્રીનગરમાં આવી જ ધર્મશાળા કરવી છે. આવી ધર્મશાળા હોય ત્યારે સંતની પંક્તિ કરવી સારી લાગે. એમાં કોઈ અંતરાય રાખવો નથી. અંતરાયે કરીને ગૃહસ્થના ઘર જેવું દેખાય. જ્યાં બહુ સાધુઓ રહે તેમનો આશ્રમ છૂટો (અલાયદો) જ જોઈએ. ગોખ, અટારી, જાળિયાં તે નિર્દોષ સાધુને ક્યારેક દૂષણરૂપ થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1642,"k":"para","g":"“દીવા વિનાનું સાધુનું રહેણાક દોષરૂપ કહેવાય. મેદાન જગ્યા હોય તોપણ રાત્રિમાં સાધુએ એકલા પથારી કરવી નહિ. ત્યાગી માત્રને રાતે સૂવું હોય ત્યારે એકબીજાના હાથ-પગ નિદ્રામાં અડે નહિ તેવી રીતે વિચારીને સૂવું. આ વાત ન કરીએ તો અંધારું રહી જાય. વાતનું જેટલું મનન કરે તેટલું અર્થમાં આવે છે ને પોતાનો તથા પારકો મોક્ષ એમાં રહેલો છે.”","e":null,"s":["18/48/7-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1643,"k":"para","g":"કરજીસણમાં સંતોને વાત કરતાં શ્રીહરિએ કહ્યું, “લોકમાં પણ જેવો વેશ ધારે છે તેવો તે ભજવી દેખાડે છે. સતીનો વેશ લેનારો અગ્નિમાં બળી મરે છે, પણ પાછો પગ ભરતો નથી. લીધેલો વેશ ભજવે નહિ તેની લાજ જાય છે. ફાતડા, વેશ્યા, ભાંડ, નાગડા હોય તે નિર્લજ્જ થઈને ફરે છે. તેથી તેમને નાક-કાનની પડી હોતી નથી, તેમનો સમાગમ જે કરે તેમને પણ તેવા જ જાણવા. સત્ વાતને ગ્રહણ કરે તેને સત્પુરુષ જાણવા. સત્ અને અસત્ એ અનાદિના માર્ગ ચાલ્યા આવ્યા છે.”","e":null,"s":["18/73/1-7"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1644,"k":"para","g":"બોટાદમાં ફાગણ સુદ એકાદશીને દિવસે સંધ્યા વખતે શ્રીહરિ ગાડા પર વિરાજમાન થયા. આરતી, નારાયણધૂન થઈ રહ્યા પછી સંતો પ્રત્યે નિયમની વાત કરી કે, “સાધુ-વર્ણીઓએ જીવતાં સુધી ધન-નારીનો ત્યાગ દૃઢ રાખવો. જેની આંટી દૃઢ હોય તે આવીને અમારે પગે અડો. આજે એકાદશી છે. કહ્યા વિના કેમ દેખાય? મનમાં જેને દૃઢ વિશ્વાસ ન હોય તે બેઠા રહેજો અને દૃઢ આંટી હોય તે જ પગે અડજો.” પછી સૌ સંત-વર્ણી પગે લાગ્યા, ને સૌ સભામાં બેઠા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1645,"k":"para","g":"શ્રીહરિ પ્રસન્ન થઈને વાત કરવા લાગ્યા કે, “સમગ્ર બ્રહ્માંડ કાળનું ચવાણું છે. કાળ, ભગવાનની અલૌકિક કળા છે. અક્ષર સિવાય જેટલું કંઈ છે તે સર્વનો કાળ નાશ કરે છે. ચ્હાયે તેવો બળવાન પણ કાળને આધીન છે. એવા સમર્થ ભગવાન જાણી તેનું શ્વેતદ્વીપના નિરન્નમુક્તો ધ્યાન ધરે છે. ભગવાનથી ડરીને તેમનામાં ચિત્ત જોડી રાખે છે તોપણ કાળ તેને છોડતો નથી. કાળ ભગવાનને આધીન છે. મહામાયા, મહાપુરુષ, અનંત પ્રધાન પુરુષ, અનંત વિરાટ ને વૈરાજપુરુષ તથા શિવ, બ્રહ્મા, વિષ્ણુ, યમરાજ વગેરે ભગવાનને આધીન છે ને તેમની કળારૂપ છે. ભગવાનની આજ્ઞા મુજબ પોતપોતાનું કામ કરે છે. અક્ષરાતીત પુરુષોત્તમ ભગવાનની કળા ન્યારી છે, અલૌકિક છે. જીવોના મોક્ષ માટે તે ઉત્પત્તિ, સ્થિતિ ને પ્રલય કરે છે. સર્વે બ્રહ્માંડના અધિપતિ એમની આજ્ઞામાં તત્પર રહે છે. જે વચનમાં વર્તે છે તેની સહાયતા ભગવાન કરે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1646,"k":"para","g":"“જીવ જેમાં આસક્તિ કરે છે તેવા દેહને પામે છે ને દેહરૂપ પોતાને માને છે, પણ દેહથી જીવ જુદો જ છે. એ જ્ઞાન ગુરુ વગર તેને થતું નથી. દેહ જડ છે, જીવ ચેતન છે. નારી-ધન દુઃખકારી છે, તે તો અનંત જન્મથી પ્રાપ્ત થતાં આવ્યાં છે. એમ સાચા સંત છે તે જાણે છે. તેણે શુદ્ધ જ્ઞાને કરીને સંસારનો ત્યાગ કર્યો છે, તેનો મોહ રાખતા નથી. સંસાર ત્યાગ કરીને ધન-નારીને ચિંતવે તે સંત નથી. ગમે તેવાં ભોજન જમ્યા હોય, પણ તેની ઊલટી કરી નાખી હોય તો તેને ફરી કોઈ પણ માણસ ખાઈ શકે નહિ, ખાય તે માણસ કહેવાય નહિ, શ્વાન કહેવાય. માટે ત્યાગીમાત્રે અષ્ટપ્રકારે નારીથી ને ધનથી દૂર રહેવું, કારણ કે એ બન્ને સંસારનાં મૂળ છે. નારીનો વિષય એવો છે કે જીવ જે જે યોનિમાં જાય છે ત્યાં પુરુષરૂપે તેમાં મોહાંધ બને છે. વિષયથી તૃપ્ત ન થવાથી અંતે અપાર દુઃખી થાય છે. તે દુઃખનું યથાર્થ જ્ઞાન થાય ત્યારે તેને પ્રભુમાં પ્રીતિ થાય છે. ભગવાનનો નિશ્ચય પરિપક્વ જેને થાય છે તે સ્ત્રી-ધનના ત્યાગનો નિયમ દૃઢ રાખે છે, તેની અસદ્‌ગતિ થતી નથી.”","e":null,"s":["19/7/1-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1647,"k":"para","g":"શ્રીહરિ જેતલપુર આવ્યા. અહીં દુઃખી(રોગી) સંતોની સેવામાં મહોલમાં રહેલાં સાધુને શ્રીહરિ ભાવથી ભેટ્યા અને ફૂલનો હાર પહેરાવ્યો. બીજા હાર રોગી સંતોને પણ પહેરાવ્યા અને વાત કરતાં કહ્યું, “ભગવાનની મરજીમાં રહે છે તે જ ભગવાનનો ભક્ત કહેવાય છે. જે ભક્ત નથી તે ચાહે તેટલું રોગનું દુઃખ સહે, પણ તેની વાસના નિર્મૂળ થતી નથી, તે તો તેના પ્રારબ્ધનું ભોગવે છે ને ભક્તને રોગ આવે છે તે અંતર શુદ્ધ કરાવવા ભગવાન રોગને પ્રેરે છે. જે સાધુ છે તે તનના રોગને ઉપદેશ સમજી મગન રહે છે. ભગવાને પ્રેરેલો રોગ સૂક્ષ્મ જેટલી પણ રહેલી દેહાસક્તિનો નાશ કરી નાખે છે. અને તેના વાસનાલિંગ દેહનું બીજ ટાળી દે છે. હરિભક્ત અને વિમુખમાં બહુ ફેર છે. સમજુ હરિભક્ત શરીરના દુઃખને ગણતો નથી. ભગવાન ભક્તના તનમાં જો રોગ ન મૂકે તો કેવળ એકલા જ્ઞાનથી તેની વાસના નિર્મૂળ થતી નથી.” પછી રોગી સંતોની સેવામાં રહેલ સાધુને કહ્યું, “રોગી સંતની સેવા અલૌકિક ભાવ રાખીને કરવી તો તે ફળીભૂત થાય છે. નિઃસ્વાર્થપણે સેવા કરે છે તેના પર અમે પ્રસન્ન થઈએ છીએ. પોતાનો કંઈક સ્વાર્થ હોય ને તે ચાહે તેટલી રોગી સાધુની સેવા કરે તેનું ફળ રતીભાર પણ મળતું નથી.”","e":null,"s":["19/37(36)/13-22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1648,"k":"para","g":"વડતાલમાં ગોમતી કાંઠે આંબાવાડિયામાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “સંત જેવી કોઈ પદવી નથી. સંતના ગુણોથી પર કોઈ ગુણ નથી. તુચ્છમતિ જન માટે સાધુના ગુણો શીખવા કઠણ છે. સાધુ થઈને જે માયિક પદાર્થ માટે વલખાં મારે છે ને ભગવાનના સુખ જેવું કોઈ સુખ નથી એવું જાણે નહિ તેની તુચ્છ બુદ્ધિ જાણવી. સંતના માર્ગે ચાલે છે તેનામાં સંતના ગુણ આવે છે. સંતના ગુણ અમાયિક છે અને ભગવાન પણ અમાયિક છે. તેમાં ચિત્ત પ્રોઈને ચરિત્રગાન કરતા હોય ને વચનમાં વર્તતા હોય તે સંત છે. નિષ્કપટ, નિર્મત્સર, નિર્દંભ વર્તનવાળા આવા સંત ભવસાગરમાં નાવ સમાન છે. આવા સંતને ભગવાનના સુખ સિવાય અન્ય સુખમાત્ર નર્ક સમાન લાગે છે.”","e":null,"s":["19/56(55)/13-23"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1649,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “આત્મનિષ્ઠ છે કે દેહનિષ્ઠ છે તે સેવામાં દેખાય છે. સેવાનિષ્ઠ હોય તે જ સાચો આત્મનિષ્ઠ છે. જ્ઞાન અને ધ્યાનની ઓટ લઈને સત્સંગમાં ઘણા આત્મનિષ્ઠ બનશે, પણ તે આત્મનિષ્ઠ નથી. સેવા વગર તે જ્ઞાન અને ધ્યાનવાળા દંભી છે. ત્યાગીને શરીર, વચનથી ને ગૃહસ્થને ધનથી પણ ભગવાનની સેવા થઈ શકે છે. તે સિવાય બીજું કાંઈ અધિક નથી. ભગવાન અને ભગવાનના દાસની સેવા સમાન કોઈ વાત નથી. અલ્પ સુકૃતથી તે મળે નહિ.”","e":null,"s":["20/60/15-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1650,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ નિર્માની સાધુની વાત કરતાં કહ્યું, “સાધુએ લેશમાત્ર અભિમાન ક્યારેય ન રાખવું. નિર્માની સાધુ તો કીડી જેવા જીવને પણ દૂભવે નહિ. એવા સાધુના ધર્મમાં રહે ત્યારે તે સંત થયો પ્રમાણ.”","e":null,"s":["21/63/43-44"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1651,"k":"para","g":"ગઢપુરમાં સંતોની સભામાં શ્રીહરિએ વાત કરી, “સંતે સંતની મર્યાદા રાખવી. બેસવું-ઊઠવું, આવવું-જવું, બોલવું એમાં મર્યાદા રાખવી. સંતના ગુણ તપાસવા. સંત સમાન કોઈ નથી. સંતના ગુણ નિત્ય ચિંતવે તો તે પોતાનામાં આવે. કોઈને ઉદ્વેગ થાય તેવું વચન સંતે બોલવું નહિ. જો ઉદ્વેગ થાય તેવું બોલે તો એટલી સંતના ગુણમાં કાચપ જાણવી. નિષ્કામ, નિર્લોભ, નિર્માન, નિઃસ્વાદ, નિઃસ્નેહ - એ પાંચ ગુણ હોય તેને સંત જાણવા. ભગવાન સિવાય અન્ય વાતનું ચિંતવન કરે તે નામ માત્રના સંત છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1652,"k":"verse","g":"‘ભગવાન કું છોડ પદાર્થ તિનકે, ચિંતવન જિતના કરત ઈનકે,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1653,"k":"verse","g":"સંત ભયે યહ બાત ન આયે, નામમાત્ર યહ સંત કહાયે.’","e":null,"s":["21/86/1-11"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1654,"k":"para","g":"ગઢપુરમાં સંતોને શ્રીહરિ કહે, “સંતમાં લોભ આવે છે ત્યારે વિચાર અને ધીરજ તે ધારી શકતો નથી, લોભનો પ્રવેશ તેનું સંતપણું હરી લે છે. પોતાને નિર્દોષ માને છે, અન્યમાં દોષ દેખે છે અને અંતર અતિશય મલિન થઈ જાય છે.”","e":null,"s":["21/87/5"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1655,"k":"para","g":"શ્રીહરિએ ગઢપુરમાં સંતોને વાત કરી, “સંતો-સંતોમાં જેનો જેટલો વિવેક રહે છે, તેને અમે દેખીએ છીએ. પોતાથી એક દિવસ વહેલો સંત થયો હોય તેની પણ મર્યાદા રાખવી. એમ જેટલો વહેલો ત્યાગી થયો હોય તેની પછીથી થયેલાએ મર્યાદા રાખવી, તેવાને ગુરુ તરીકે માનવા. વર્તનમાં જેટલું દૈવત છે તે છુપાઈ રહેતું નથી. મનમુખી જે વર્તન રાખે તેમનામાં સંતપણું રતીભાર રહેતું નથી. તેમનામાં જેવા સંકલ્પ થાય તેવી ક્રિયા કરે છે, એટલે સંતનો દાસ મટીને મન આગળ ઘાસ લે છે. સંતના વચનનો ત્યાગ કરીને જે સાધુ મનમુખી વર્તે તેનામાં તલભાર પણ સંતપણું રહેતું નથી. મનમુખી જાણીને સંત તેનો ત્યાગ કરે છે અને સંત જ્યારે ત્યાગ કરે છે ત્યારે ભગવાન પણ તેને તજી દે છે. પોતામાં અપાર દોષ હોવા છતાં પોતાને શ્રેષ્ઠ માને તેનું માથું ફર્યું એમ જાણવું. પોતાને શ્રેષ્ઠ માનતો હોય તે અપરાધી છે. બીજાથી પોતાને અધિક માનતો હોય તો તેને અધમમાં પણ અધમ જાણવો.”","e":null,"s":["21/88/2-20"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1656,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ ગોપાળાનંદ સ્વામીને વાત કરતાં કહ્યું, “દગાબાજ અને સાચા સંતમાં ઘણો ફેર છે. દગાબાજ સંત હોય તે એકાંતમાં બેસાડીને, બહુ આગતા-સ્વાગતા કરીને, વખાણ કરીને વાત કરે છે, પણ શ્રેષ્ઠ થવું બહુ કઠિન છે.”","e":null,"s":["21/89/25-29"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1657,"k":"para","g":"ગઢપુરમાં ભીમ એકાદશીને દિવસે શ્રીહરિએ સંતોને કહ્યું, “સંતને ભગવાન સિવાય કોઈનું મમત્વ ન હોય તેટલી તેનામાં સાધુતા કહેવાય. મમતા રહિતને ક્યારેય ક્યાંય પણ રાગ થતો નથી. હેતનું કારણ મમતા છે. જેટલી મમતા બતાવે તેટલો તેના પ્રત્યે ભાવ થાય. જગતમાં જેટલું મારાપણું મનાય તેટલી સત્સંગમાં ખામી કહેવાય.”","e":null,"s":["22/111/23-25"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1658,"k":"para","g":"લોયા-પંચાળામાં શ્રીહરિએ એક માસ સુધી ત્યાગી સાધુઓને પોતાની સમીપે રાખ્યા ને નિત્ય વાતો કરી. પંચાળામાં શ્રીહરિ કહે, “સેવા કરે છે તેને મોટપ મળે છે પણ કહે ને સેવા કરે તેની મોટપ માનતા નથી. મન ધાર્યું કરે એની સેવા અમને રુચતી નથી. જેણે સાધુતાના ગુણ પ્રાપ્ત કર્યા હશે તેને આદર અને સન્માન મળશે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1659,"k":"para","g":"“ભગવાન પ્રગટ મળ્યા હોય તોપણ જો સાધુના ગુણ શીખ્યા નહિ હોય તો લોકવહેવારે ચહાયે તેવો મોટો હશે, પણ જીવ વિનાના શરીર જેવો (મડદું) જાણવો. મુમુક્ષુનો જીવ પણ સાધુના ગુણો દેખશે તેમાં જોડાશે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1660,"k":"para","g":"“ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ જેનામાં નિશદિન રહ્યાં હોય એવા સંત, મુમુક્ષુને પાત્ર મુજબ સહાય કરે છે. ભગવાનના ગુણ જેમ સર્વોપરી કહેવાય છે, તેમ સંતના ધર્માદિ ગુણ મોક્ષરૂપ છે, તે પણ સર્વોપરી ગણાય છે. પાત્ર મુજબ સંતમાં ગુણ વસે છે ને વિવેકી સંત એ ગુણોનું આદરપૂર્વક જતન કરે છે. માટે સાધુએ પોતામાં અલૌકિક ગુણ આવે એવો પુરુષાર્થ કરવો.”","e":null,"s":["25/9/24-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1661,"k":"para","g":"પંચાળામાં શ્રીહરિએ હરિયાનંદ અને વિશ્વાસચૈતન્યાનંદને બોધવચનો કહેતાં કહ્યું, “તમે મોટાં સંતો છો, તમને દેખીને અન્ય ત્યાગી વર્તન કરે એટલે અમે કહીએ તેમ તમે કરો. તમે ત્યાગીની રીત જાણો છો. અમને પ્રસન્ન કરવા માટે સંતો હરિજનો સાધન કરે છે. પરંતુ, અમે કહીએ તેમ કરવું તે સાધન સર્વ સાધનમાં સર્વોપરિ છે. અમારી પ્રસન્નતા અમારા વચનના પાલનમાં રહેલી છે. અમારા વચનમાં શંકા કરે તેનો માયામાં નિવાસ જાણવો. હરિજનો તો ભગવાન અને સંતનું અમાપ માહાત્મ્ય જાણે છે. તેમાં દોષ દેખતા નથી. ભગવાન અને સંતને ન દઈ શકાય તેવું પદાર્થ પોતે અધિક કરીને રાખતા નથી, નિષ્પાપપણે વર્તે છે. ભગવાન તેનાથી દૂર જતા નથી. સમજણમાં કાચપ રહે તેટલા ભગવાન દૂર થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1662,"k":"para","g":"“ધર્મ-નિયમ વગર, ચાહે તેટલી વાત કરતો હોય કે પ્રતાપ દેખાડતો હોય પરંતુ, હરિજન તે પ્રતાપને કોઈ દિવસ માનતા નથી. સાધુ ધર્મ-નિયમ પાળે તેટલા હરિજનો તેને આધીન વર્તે છે. ભગવાનના વચનમાં વર્તવું તે સંતનું ભૂષણ છે. મનમુખી વર્તે તેને દુઃખ થાય છે. સત્સંગની રીતે ન ચલાય તો ત્યાગી થયા તે ન થયા જેવું છે. ભગવાન મળે પણ રીતમાં ન ચાલે તો દુઃખ મટે નહિ. પોતાનો દોષ દેખાય ત્યારે દુઃખ ટળે અને સત્સંગમાં નભાય. પોતામાં ગુણ મનાય તો વિમુખ થવાય. વાળે તેમ વળે ત્યાં સુધી સુખ રહે ને ન વળે તો ઉથડકપણું રહેવાથી સુખ આવે નહિ.”","e":null,"s":["25/10(11)/1-19"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1663,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સંતો-ભક્તોને વાત કરતાં કહ્યું, “સંત સમાન કોઈ નિધિ નથી. સંત-નિધિ સિવાયનો બીજો નિધિ અમે શ્રેષ્ઠ માનતા નથી. સંત સિવાયના નિધિમાં જન્મમરણનું અપાર દુઃખ રહેલું છે, તે ભગવાનથી દૂર કરાવે છે.”","e":null,"s":["26/11/35-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1664,"k":"para","g":"શ્રીહરિએ બ્રહ્મમુનિને વડતાલ મંદિરના કામકાજ માટે નિયુક્ત કર્યા અને સંતો હરિજનોને વાત કરતા કહ્યું, “સંત હોય તેને કંઈ ન જોઈએ. અન્ન-વસ્ત્ર સત્સંગમાં મળી રહે છે. સાધુએ આજ મળે પછી કાલનો સંકલ્પ ક્યારેય ન કરવો. સંકલ્પ કર્યા વિના ભગવાન તેને સમયે સમયે આપી રહે છે. હરિભક્તોનાં મેલાં વસ્ત્રો જોઈને તેનો અનાદર ન કરવો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1665,"k":"para","g":"“હરિભક્તો પણ ભાવ રાખીને મંદિરની અને તમારી અન્ન-વસ્ત્રની જેટલી સેવા કરે છે, તે ક્યારેય દુઃખી રહેતા નથી. તેમાં જેટલો નિરુત્સાહ રહે એટલો આ લોક-પરલોકમાં સુખનો સંકોચ રહે છે.”","e":null,"s":["26/43/20-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1666,"k":"para","g":"શ્રીહરિ બુવાથી ભરુચ પધાર્યા ત્યારે સંતોને વાત કરતાં કહ્યું, “સર્વોપરી સુખ સંતમાં રહ્યું છે, પણ તે સમજવું કઠણ છે. મોટા સાધુ આ વાત જાણે છે. ત્રણે અવસ્થામાં એ સંતના જેવું સુખ ક્યાંય દેખતા નથી. આ સમજણ અંતિમ શ્વાસ સુધી એવી ને એવી રહે તે સર્વ સંતોમાં શ્રેષ્ઠ સંત છે.”","e":null,"s":["27/16/2-4"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1667,"k":"para","g":"શ્રીહરિએ બોચાસણમાં કાશીદાસના ભવનમાં સંત મહિમા કહેતાં કહ્યું, “સંત ઉદધિ જેવા છે. સંતનું હૃદય નવનીત કહ્યું છે. નિષ્કામાદિક મહાન ગુણના ધારક સંત છે. પ્રગટ હરિનો નિશ્ચય જેટલો દૃઢ તેટલો તે સંતમાં કરોડો સૂર્યનો પ્રકાશ પ્રગટે છે. ભગવાનના વચનમાં તે સુખ માને છે. આવા સંત બ્રહ્માંડમાં મળવા દુર્લભ છે. સંત થઈને કપટ રાખે, મોટા સંતની અદબ ન રાખે, સંતને નિત્ય નમન કરવાનો નિયમ ન હોય, કથા-કીર્તનાદિનો કોઈ નિયમ ન હોય - એવા હોય તે આચરણથી જણાઈ આવે છે. મુમુક્ષુએ ઉત્તમ સાધુને ઓળખી તેનો સંગ કરવો.”","e":null,"s":["27/16/9-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1668,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1669,"k":"para","g":"લોજમાં શ્રીહરિ પોતાની રસોઈ જાતે કરીને જમતા. બીજાની કરેલી રસોઈ જમતા નહિ. જમીને સંતોને પીરસતા. સંતોને પીરસવા પધારતા ત્યારે અતિ પ્રેમમગ્ન થઈ જતા. સંતોની સેવા કરવામાં તેમને અધિક ઉમંગ રહેતો. દિન દિન પ્રત્યે અધિક ને અધિક સેવાનો રંગ રહેતો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1670,"k":"para","g":"શ્રીહરિ સંતોને જીવનપ્રાણ માનતા. સંતમાં ભગવાન રહ્યા છે એમ મહિમા સમજતા. સર્વ સિદ્ધો કરતાં પણ પ્રગટના ઉપાસક સંતોને શ્રેષ્ઠ ગણતા, કલ્પવૃક્ષ ને ચિંતામણિ તુલ્ય કહેતા. સંતસમૂહથી વિખૂટા કદી પડતા નહિ. સંતનો વિયોગ એક પળ થાય તો તેને કોટિ કલ્પ જેટલો માનતા.","e":null,"s":["3/3/32-34"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1671,"k":"para","g":"ચાર ઘડી રાત્રિ શેષ રહી ત્યારે બધા સંત જાગ્યા અને સ્વામિનારાયણનું ભજન કરવા લાગ્યા. કથા, ભજન વગરનો ગયેલો સમય સંતો હાનિ માનતા. હરિકથા અને ગુણગાનમાં બધો સમય વ્યતીત કરતા. ભગવાન સિવાય મનમાં બીજો સંકલ્પ કરતા નહિ. વાંચવું-લખવું વગેરે ક્રિયામાં તેનો જ અભ્યાસ રાખતા. કોઈ જાતનો ક્લેશ કરતા નહિ. કોઈની નિંદા કરતા નહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1672,"k":"para","g":"સંતોની આવી પ્રકૃતિ જોઈ ગૃહસ્થને વિશેષ ભાવ થતો અને તેઓ ભગવાનની ઇચ્છાથી અન્ન-વસ્ત્ર લાવી આપતા.","e":null,"s":["3/58/39-42"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1673,"k":"para","g":"સંતો ઉપર શ્રીહરિને અપાર હેત હતું. દેહ, ઇન્દ્રિયો, અંતઃકરણને નિયમમાં રાખવાની રીત શ્રીહરિ સંતોને શીખવતા. સ્થૂળ, સૂક્ષ્મ, કારણ દેહની વિક્તિ ભિન્ન-ભિન્નપણે શીખવતા. એક-એક અવસ્થામાં બે-બે અવસ્થાઓ કેવી રીતે રહી છે તેની સમજ આપતા. ઇન્દ્રિયોને જીતવામાં પ્રથમ જિહ્‌વા ઇન્દ્રિયને જીતવાની કળા શીખવતા ને કહેતા એક જિહ્‌વાને પરિપૂર્ણ જીતે તો બધી ઇન્દ્રિયો જિતાઈ જાય છે. નેત્રની વૃત્તિ નાસિકા પર રાખવાની યુક્તિ શીખવતા. આસન જીતવું. જ્યાં-ત્યાં ફરવું નહિ, જોવું નહિ, આ લોકમાં આવ્યા તો મોક્ષનું કાજ બગડે નહિ તેની અખંડ સૂરત રાખવી. જીવની ઇચ્છાવૃત્તિને તપાસતા રહેવું. સૂરત ન રાખે તો બુદ્ધિમાન પણ ગોથું ખાઈ જાય છે. મનની રુચિ પળપળ બદલાતી રહે છે. મનને તાલે જીવ એક જ દિવસમાં ચોરાસી લાખ તન ધરી લે છે. અંતર્દૃષ્ટિ કરે તેને જ આ જાણ્યામાં આવે છે. જેમ જેમ જ્ઞાન શીખે તેમ તેને અનંત નેત્ર પ્રાપ્ત થાય છે.”","e":null,"s":["5/35/29-39"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1674,"k":"para","g":"સાબરમતી નદીમાં શ્રીહરિ સંતો સહિત સ્નાન કરવા લાગ્યા. શ્રીહરિ ઉપરવાસ નાહતા, રાજાઓ સંતને આગળ રાખીને નાહતા. એમ સંતનું માહાત્મ્ય સમજી વિવેક રાખતા. જેમને સંતનું માહાત્મ્ય ન હતું અને વિવેક ન હતો તેઓ સંતને પાછળ રાખીને નાહતા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1675,"k":"para","g":"ખટ્વાંગ અને પર્વતભાઈ જેવા સંતનું માહાત્મ્ય સમજનારા ભક્તો શ્રીહરિને બહુ પ્રિય હતા. સંત અને હરિભક્તોનો જેને ભાર ન હોય તેને માહાત્મ્ય વિનાનો જાણવો. ફળ અને પાંદડાં વિનાના વૃક્ષ જેવો તેનો સત્સંગ ગણાય. વિવેકી માણસ તેના સંગને ઇચ્છે નહિ. માહાત્મ્ય વિનાનું જ્ઞાન પણ અમૃતમાં જાણે છાનું વિષ રહ્યું હોય તેવું છે. પોતાની પ્રકૃતિએ મળતા આવે એવા સંતને હરિતુલ્ય કહે, બીજાને વિમુખ કહે, એવી જેની બોલી હોય તેને સત્સંગમાં કુસંગ સમજવો.","e":null,"s":["7/58/22-26"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1676,"k":"para","g":"સંતો ભોજન લેવા એક પંક્તિમાં બેસતા. ભોજન પીરસાઈ ન રહે ત્યાં સુધી નારાયણ ધૂન્ય કરતા. પીરસી રહ્યા પછી ‘વાસુદેવ હરે’નો નાદ ઊંચે સાદે થાય તે પછી સંતો કાષ્ઠના પાત્રમાં પીરસાયેલા ભોજનને ભેગું કરતા ને એક અંજલિ જળની દઈ જમતા. જમતી વખતે સંતો ગ્રાસે ગ્રાસે ભગવાનનું નામ લેતા. મનોવાંછિત વસ્તુ કોઈ માગતું નહિ. સૌ પોતપોતાના આહાર પ્રમાણે જમતા. પાત્રમાં કોઈ ભોજનને છોડતા નહિ. જમતાં પરસ્પર વાત કરતા નહિ. એકબીજાને એઠું આપવાનો અનાચાર કરતા નહિ. જળના પાત્રને મુખથી ઊંચું રાખીને પાણી પીતા અને એવી રીતે પીધેલું જળ બીજા સંતને આપતા નહિ. સૌ સંતો જમી રહે ત્યારે પ્રથમ મોટેરા હાથ ધોતા. આવો વિવેક સૌ સંતો રાખતા. દેહમાં રોગ થયા વિના જુદું જમતા નહિ. ભક્તિ, જ્ઞાન, ધર્મ, વૈરાગ્ય તેણે સહિત જે વૃદ્ધ સાધુ તેની આગળ વિવેકી સંતો ઊંચે આસને બેસતા નહિ.","e":null,"s":["8/33/10-24"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1677,"k":"para","g":"અરુણોદય થતાં સંતો ધૂન કરવા લાગ્યા. ધૂન વખતે કોઈ પણ સંત, વર્ણી, પદાતિ કે હરિભક્ત સૂઈ રહેતા નહીં. કોઈ પ્રમાદ કરી સૂએ તેને સૌ નાદાર કહેતા. નાના-મોટા સંતો કોઈ પણ ધૂનના સમયે સૂઈ ન રહે તથા કથા, સભા વખતે આસન પર બેઠા ન રહે એવું એક ધારું સૌનું વર્તન હતું. સૌને સરખું જ તાન રહેતું. ભોજનમાં જેમ પ્રમાદ રાખે નહિ તેવી રીતે ભજનમાં પણ રાખતા નહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1678,"k":"para","g":"શીત, વરસાદ કે તાપથી શરીર બગડે તો ભોજન છૂટે, પણ ભજનમાં કોઈ પ્રમાદ રાખતું નહિ. સેવા, ભક્તિ અને ભજનમાં દિન દિન પ્રત્યે આદર વધતો રહેતો હતો. જેને હરિ રીઝવવાનું તાન ન હોય તે પ્રમાદને અવકાશ આપે, એનું ચિત્ત સંતમાં પણ ભળે નહિ, તેથી અમૂલ્ય સત્સંગ મળવા છતાં વિના દુઃખે દુખિયો રહે. અનંત દુઃખનો અંત અહીં રહ્યો છે તો અહીંનું દુઃખ બીજે ક્યાં છૂટે? એમ જાણી સૌ સંતો પ્રમાદ અને મોહનો ત્યાગ કરતા.","e":null,"s":["8/45/5-15"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1679,"k":"para","g":"વિચરણ કરીને સંતો આવે ત્યારે શ્રીહરિ સમાચાર પૂછતા. તેમાં તે તે દેશમાં મુમુક્ષુઓ કેવા છે, ધર્મમાં કેમ વર્તે છે, ત્યાંના રાજા પ્રજાની રુચિ કેવી છે વગેરે વૃત્તાંત પૂછતા. સંતો જેમ જોયું હોય તે પ્રમાણે કહેતા. શ્રીહરિ ગ્રામ્ય વાત ક્યારેય પૂછતા નહિ અને સંતો ક્યારેય પણ કહેતા નહિ. ભૂલથી કોઈ ગ્રામ્ય વાત બોલે તો શ્રીહરિ તેને નિવારતા.","e":null,"s":["8/50/17-23"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1680,"k":"para","g":"શ્રીહરિ દરેક સંતનું તુંબડું, પુસ્તક અને વસ્ત્રનો અદલોબદલો કરાવતા. પૂર્વ દેશના જે સંતો હતા તેમને સાધુતાના ગુણ શીખવતા. અને કોઈને પણ દ્વેષ ન થાય એવી વાત નિત્ય કરતા. જે જે પ્રકરણ શ્રીહરિ ફેરવે તે સૌને પ્રિય લાગતાં. એક વર્ષમાં બે-ચાર જુદાં જુદાં પ્રકરણ ફેરવતા. લોજમાં રહ્યા ત્યાં સુધી સંતોને ધ્યાન શીખવતા.","e":null,"s":["10/24/4-7"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1681,"k":"para","g":"શ્રીહરિએ સંતોના નિવાસ માટે મોટાં મંદિરો બાંધ્યાં છે. સંતો પાસે શ્રીહરિએ જે રીતે ત્યાગ પળાવ્યો તે જોઈને હરિજનોને તેમનામાં અધિક અનુરાગ થયો, કારણ કે બ્રહ્માંડમાં શ્રીહરિના સંતો સમાન કોઈ ત્યાગી નથી. શ્રીહરિના સંતો દૃષ્ટિ માંડીને સ્ત્રી સામું જુએ નહિ. જો સ્ત્રી અજાણ્યે પણ જોવાઈ જાય, તો તેના પ્રાયશ્ચિત્તનો ઉપવાસ કરે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1682,"k":"para","g":"શ્રીહરિએ સંતો માટે આવા પાંચ નિયમો બાંધ્યા છે - નિષ્કામ, નિર્લોભ, નિઃસ્નેહ, નિઃસ્વાદ ને નિર્માન. આ મોટાં વ્રત છે. અવાંતર નાનાં નિયમો અને વ્રતો તેના પેટા અંગ જેવાં ઘણાં છે. તેનો દિવસ દિવસ પ્રત્યે અભ્યાસ કરે તો તે સંત પાકો થાય. વ્રતપાલન ને વર્તનના અભ્યાસ વગર સંત કાચો રહે. જે કાચો રહે તે ક્યારેય વિષયજાળથી બચી શકે નહિ. શૃંગી ઋષિને સ્ત્રી-પુરુષનું જ્ઞાન ન હતું, છતાં અભ્યાસ ન હતો તો વેશ્યાએ બાંધ્યા. વિષયનું જ્ઞાન ન હોય એવા ત્યાગીને પણ નિયમ લોપ થાય તો વિષયનું બંધન અવશ્ય થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1683,"k":"para","g":"જાણપણા વિના એક પણ નિયમ પળી શકે નહિ, આ વાત પરમ વિવેકી સાધુ જાણે છે. સત્પુરુષના પ્રસંગ વિના જાણપણું આવતું નથી અને અનુપમ એવી મોક્ષની રીત પણ જાણ્યામાં આવતી નથી. અને અજ્ઞાનતમસ પણ એવા મોટાના સંગ વિના ટળતું નથી. અજ્ઞાનતમ છે ત્યાં સુખ થતું નથી, ને વિમુખ રહે છે. ભગવાન વિના બીજા પદાર્થની સ્મૃતિ છે તે જ તેને માટે સંસાર છે, એમ મહામુનિ કહે છે.","e":null,"s":["10/43/17-25"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1684,"k":"para","g":"અંતરનો ત્યાગ જુદો છે અને દેહનો જુદો છે. તેમાં જેટલો ફેર તેટલો ચોર ગણાય. છળકપટ તજીને જે ત્યાગી શ્રીહરિને તન-મન અર્પે ત્યારે જ તે બડભાગી ગણાય, શ્રીહરિને પ્રગટ પ્રમાણ અંતર્યામી જાણે તે જ સાચા ત્યાગી હરિજન છે, બાકી બીજા તે માર્ગે ચાલ્યા છે એમ જાણવું. શ્રીહરિને જે પ્રગટ પાસે દેખે છે તેના નિયમ-ધર્મ ભગવાનના પ્રતાપથી નાશ પામતા નથી, બીજાના નાશ પામે છે.","e":null,"s":["10/44/25-28"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1685,"k":"para","g":"શ્રીહરિની વરતાવવાની મરજી જોઈ સંતો મનધાર્યું ત્યજી એ મુજબ વર્ત્યા. તેથી શ્રીહરિ સંતો પર બહુ હેત રાખતા, એક એકને મળતા, પ્રેમથી બોલાવતા તથા પ્રસાદીના હાર તથા સંતને દેવા યોગ્ય વસ્તુ હોય તે આપતા, પોતાના શરીરથી પણ સંતને અધિક માનતા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1686,"k":"para","g":"શ્રીહરિને અધિક પ્રસન્ન કરવા સારુ સંતો પણ તેમની પ્રમાણે વર્તતા. અને પ્રસન્નતા તે જ મોટું ફળ માનતા. છળકપટ છોડી એકબીજાને ચાહતા. એકબીજાની મોટપ સમજી પ્રીતિ રાખતા. પોતાને મોઢે પોતાનાં વખાણ કરતા નહિ અને બીજા કોઈ વખાણ કરે તો ફુલાતા નહિ. કોઈ અપમાન કરે તો દ્વેષ રાખતા નહિ અને કોઈનું અપમાન કરતા નહિ અને પિંડ-બ્રહ્માંડથી અલગ વર્તી બ્રહ્મવિદ્યામાં મગ્ન રહેતા. લોકને દેખાડવા જ્ઞાન શીખે તેનું અજ્ઞાન જાય નહિ એમ સમજી સદાય નિર્દંભ રહેતા. શ્રીહરિએ મોટા નિષ્કામાદિ ગુણો તેમનામાં સ્થાપન કર્યા હતા, જે દેવને પણ દુર્લભ છે, તે ગુણોને પામીને માયિક તૃષ્ણા રહેતી નથી, જીવમાં બીજરૂપે રહેલી માયિક સુખની કામના પણ ટાળી દીધી હતી. કામ, ક્રોધાદિક અધર્મ વંશના ગુણો તે વિષયનું બીજ છે, તે નાશ પામ્યા પછી સ્પર્શ કરી શકતા નથી.","e":null,"s":["11/15/9-28"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1687,"k":"para","g":"ધોરાજીમાં શ્રીહરિની સવારી જોવા પુરના લોકો ઊમટ્યા. લોકો બોલતા હતા કે મોક્ષની રીત ખરેખરી આ ધર્મમાં પ્રકાશી છે. સિંહ અને સર્પથી ડરીને ભાગે તેમ સંતો સ્વપ્નમાં પણ નારીથી ડરીને ભાગે છે. આવો ધર્મ જગતમાં ક્યાંય નથી. અગ્નિ અને જળમાં પ્રવેશ કરે એવા સિદ્ધ હોય, પણ આવા ત્યાગી હોવા કઠણ છે. આવા સંતો જીવનો ઉદ્ધાર કરે છે. કરોડ વર્ષ તપ કરે તોપણ આવા ગુણ મળે નહિ. સંત અને અસંતની ઓળખ ગુણ પરથી જણાય છે. સંત થઈ ધન, નારી, કેફ, વ્યસન, અભક્ષ્ય રાખે છે તે સંતના ચોર છે. પોતે ચોર હોવા છતાં સંતને ચોર કહે છે, તેથી કરીને દિવેલ વિનાના દીવાની પેઠે તે ફાવે તેવો હોય તોપણ દિવસે દિવસે ઘટી જાય છે.","e":null,"s":["11/20/8-31"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1688,"k":"para","g":"ત્યાગી થઈને હરિભક્તોનો ભોજન અને વસ્ત્રોમાં વિશ્વાસઘાત કરે તેને હરિભક્તનો દોષ લાગે છે અને તેને મૃત્યુ બૂરી પેઠે આવે છે અને રોમે રોમે કોટિ વીંછીનું દુઃખ થાય છે. મર્યા પછીથી પણ દુઃખનો પાર આવતો નથી, જે ધર્મમાં ચાલે અને સંત-હરિજનની બીક રાખીને દાસ થઈને વર્તે છે તેને શ્રીહરિ પોતાનો માને છે. એકનો દાસ થઈને બીજાનો દ્રોહ કરે તો તે સંત-ભક્તોનો ચોર છે.","e":null,"s":["11/23/29-33"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1689,"k":"para","g":"ત્રણ વર્ષ સુધી સંતો દિવસે ગામની સીમમાં રહેતા અને રાતે વનમાં રહેતા. દિવસમાં કોઈ વખત ત્રણ-ચાર સંતો ભેગા રહેતા, અને રાતે તો એક એક રહેતા. રાતે જો કોઈ સ્ત્રીનો શબ્દ કાને સંભળાય તો એક ઉપવાસ કરતા. કોઈ સંત રોગે કરીને દુઃખી હોય તો રાતે ગામની સમીપમાં રહેતા. હરિભક્તો તેમને માટે ગામની સમીપે ઝૂંપડી બનાવી આપતા ને તેમની સેવા કરતા. હરિભક્તો ન હોય તો સાધુ સેવા કરે. ગમે તેવી ઠંડી પડે તોય અગ્નિથી તાપતા નહિ. અને લોઢું સુધ્ધાં પણ ધાતુમાં રાખતા નહિ. ગ્રંથ લખવા માટે ચપ્પુ, કાતર રાખતા અને કંથા સીવવા માટે સોયદોરા માગીને સીવ્યા પછી પાછાં આપી દેતા. ચપ્પુ, કાતર અને સોયને જ્યારે જ્યારે અડે ત્યારે ત્યારે સાત-સાત વાર હાથ ધોતા. આત્મા ને પરમાત્મા વિના દરેક વસ્તુનો સંગ તજતા અને વાંચવા માટે નાની પોથી રાખતા. વરસાદ આવે ત્યારે વડ તળે બેસતા. પાણી સીંચવા દોરી રાખતા. હરિને રીઝવવાનું તાન હોઈ સંતો ક્યારેય ક્ષોભ પામતા નહિ. આગળના પુરુષો સત્સંગ કરીને તરી ગયા છે તેનાં દૃષ્ટાંત આપીને વાત કરતા. જેથી મુમુક્ષુજનો સત્સંગ કરતા. રાતે સંત એકલા વનમાં રહેતા. વાઘ-વરુ તથા ભૂતપ્રેતથી બીતા નહિ. ક્યારેય તો તેમની ચારે તરફ તેઓ તેમને ઘેરી લેતા, પણ સંતો નિધડકપણે રહેતા.","e":null,"s":["13/8/3-29"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1690,"k":"para","g":"કામ, ક્રોધ ને લોભના પ્રવાહમાં ભવ, બ્રહ્મા ને ઇન્દ્રાદિ દેવો તણાયા છે. નારદ, પર્વત, સૌભરિ, પરાશર, શૃંગી ઋષિ - સૌને કામે જીતી લીધા છે. લોભથી હિરણાક્ષ, સહસ્રાર્જુન ને કૌરવોનું મૃત્યુ થયું છે. ક્રોધથી હિરણ્યકશિપુ ને કંસ જેવાનાં મરણ થયાં છે. આમ, આ ત્રણે દોષ સુખને હણી લે છે. અવિચલ સુખ મળતું જ નથી. બ્રહ્માંડના સુખને ક્ષણભંગુર કરી દેખાડતા હોય એવા સંત મળ્યા વિના મોક્ષની બુદ્ધિ ક્યારેય પ્રાપ્ત થતી નથી. સંતને ભગવાનમાં પરમસુખ મનાયું છે. દુર્લભમાં દુર્લભ એ છે. જીવોને એ પરમ સુખનો માર્ગ સંત બતાવે છે. મોક્ષની બુદ્ધિ આવ્યા વિના ચક્રવર્તી રાજા થયો કે દેવતા થયો તોપણ તે વૃથા છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1691,"k":"para","g":"મોક્ષભાગી સંત વિના મોક્ષની વાત કોઈ કરી શકતું નથી, કારણ કે માયિક સુખમાં જે દિન-રાત રચ્યા-પચ્યા રહેતા હોય, ને પેટ ભરવા અપાર પાપ કરતા હોય, ભગવાનનો લેશ પણ ડર ન રાખતા હોય તેવા સંતનો યોગ થાય તેની આગળ શી ગતિ થશે તે ભગવાન જાણે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1692,"k":"verse","g":"‘મોક્ષભાગિ વિન સંત, મોક્ષ કી બાત ન કરે કોઉ;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1693,"k":"verse","g":"માયિક સુખ મેં અતંત, રચે પચે રહે રાત-દિન.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1694,"k":"verse","g":"પાપ કરત જો અપાર, રાત-દિન નિજ પેટ ભરન;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1695,"k":"verse","g":"ડર નહિ રખત લગાર, આગે હોય તાકિ કોન ગતિ.’","e":null,"s":["14/21/29-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1696,"k":"para","g":"સંતોમાં ત્યાગ જોઈ હરિજનોને સત્સંગમાં શ્રદ્ધા વધે છે. કામ, ક્રોધ ને લોભનો ત્યાગ સાધુ કરે તેટલો વિશેષ અનુરાગ હરિભક્તોને થાય. આમ, સંત-હરિજનનું વર્તન જોઈ જગતના સુમતિજનો ખેંચાઈ આવે છે.","e":null,"s":["14/23/24-26"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1697,"k":"para","g":"સંતો અષ્ટપ્રકારે સ્ત્રીનો ત્યાગ રાખે, અષ્ટપ્રકારની ધાતુ અને ધનને તજીને અસત્ માર્ગનું ઉચ્છેદન કરે, ભગવાનની વાત વિના એક ક્ષણ વ્યર્થ જવા દે નહિ, કોઈ પ્રકારનો ફેલ રાખે નહિ - આવાં શુભ વર્તન હોય ત્યાં જ ભગવાન પ્રગટ રહે છે. ભગવાન પ્રગટ ન હોય ત્યાં સત્ય વર્તન સંભવતું નથી.","e":null,"s":["14/48/3-10"],"sv":["सत्संग में जेते, संत वर्णी रहे जो तेहु ।\n\n अष्ट प्रकर के तेते, त्रिया का रखत त्याग हि ॥\n\n धातु अष्ट प्रकार, ताके रखत हि त्याग यह ।\n\n उच्छेदत वार हि वार, असत जितनी रीत रहेउ ॥\n\n वर्तन शुभ होय जेहि ठोरा । हरि की बात विन जाय न पहोरा ॥\n\n निश्चे तिहां जानना एसे । भगवान प्रगट रहे तेसे ॥\n\n भगवान विन वर्तन हि जेता । साचे न रहावे कबहु तेता ॥"],"mt":false,"gl":null,"a":true},{"i":1698,"k":"para","g":"સંત વિચરે તો સત્સંગ નભ્યો રહે. જ્યાં સંત જાય ત્યાં નવો સત્સંગ થાય છે. સંત જેવો રંગ લગાવે તેવો લાગે છે. સંતના વચનથી સંસારી કર્મથી છૂટે છે અને બહુ જન્મના મલિન કર્મના પાશ સંતના વચનથી છૂટી જાય છે.","e":null,"s":["14/75/22-26"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1699,"k":"para","g":"વાતના પેચ ન આવડે તે સરળબુદ્ધિ સંત કહેવાય. પેચથી વાત કરે તે કુટિલ અસાધુ કહેવાય. સરળતા પ્રાપ્ત થાય એ જ ભગવાન મળ્યાનું ફળ છે. સરળતા ન શીખે તો સંત હોય કે ભક્ત તેથી શું? બન્ને જગતને ઠગનારા છે. જેમાં સરળતા છે તેમાં શ્રીહરિ પ્રગટ રહે છે. જેમાં સરળતા નથી તેમાં દોષો અને અધર્મસર્ગ વસે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1700,"k":"verse","g":"‘સરલતા જા માંહિ, પ્રગટ હરિ તા મહિં રહત;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1701,"k":"verse","g":"સરલતા નહિ જાહિ દોષ અધર્મ કે સરગ રહત.’","e":null,"s":["15/7/35-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1702,"k":"para","g":"સંતો જમતા ત્યારે બધું ભેગું કરીને જળ નાખીને જમતા. એમ રસના વગેરે ઇન્દ્રિયોને જીતતા. ઔષધની જેમ આહાર લેતા. તેથી રસના ઇન્દ્રિય બિચારી દુઃખી થઈ જતી! કોઈ સંત વચનથી બહાર વર્તે નહિ. તનની બધી ક્રિયા સંતો હરિના વચનમાં રહીને કરતા ને સમજતા કે હરિના વચનમાં વર્તે તેમાં પ્રતાપનો પાર નથી. રાજાના વચનમાં વર્તે તે પણ મોટો થઈ જાય છે, તો રાજાઓના રાજા શ્રીહરિના પ્રતાપની વાત જ કેમ કહેવાય?","e":null,"s":["15/29/9-14"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1703,"k":"para","g":"શ્રીહરિએ વૌઠાનો સમૈયો કરીને સ્વરૂપાનંદમુનિને કાશી મોકલ્યા હતા, તે સમાધિનિષ્ઠ હતા. નિર્માનાનંદ મુનિ જે સારંગપુરના હતા તેમને વૌઠા ગામથી પુના શ્રીહરિએ મોકલ્યા. ઝાલાવાડના પૂર્ણાનંદને તથા નરનારાયણાનંદ તથા અદ્‌ભુતાનંદ તેમને ચાદરનો ખલકો કરીને કંઠમાં પહેરાવ્યો ને દક્ષિણ દેશમાં વર્તવાની રીત શ્રીહરિએ શિખવાડી અને એક એક જળગરણું આપ્યું, અને કહ્યું કે કૌપીન વિના અલફીભેર સનકાદિકની પેઠે રહેવું. પાણી પીવાનું પાત્ર મળે તોપણ પાસે રાખવું નહિ. અવધૂત ગીતા તથા મણિરત્નમાળા કંઠે કરવી, એમ કહીને પરદેશ જનારા સંતોને મળ્યા ને બોલ્યા કે અમે સદાય તમારી પાસે છીએ એમ માનજો.","e":null,"s":["15/32/28-35"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1704,"k":"para","g":"સત્સંગમાં જે સંતો નિયમ યુક્ત રહે છે તથા ભગવાનનો સંબંધ જેમાં ન હોય એવા સુખને માયાનું બંધન જાણી તેનાથી દૂર રહે છે, ને નિષ્કપટપણે ભગવાન ભજે છે એવા સંત મુક્ત છે. ધ્યાન-ભજન, ધારણા-સમાધિ, નિયમધર્મ, કથા-વાર્તા, કીર્તન એ સંતોનાં આભૂષણો છે. નિષ્કપટપણું એ કાન છે અને નિર્દંભપણું એ નાક છે. એ બન્ને ન હોય ને સંત-હરિજન નામ ધરે તો નાક, કાન વિનાના કહેવાય. સંતમાં તે અવશ્ય હોવા જોઈએ. જે સંત દંભ-કપટ તજીને વર્તે તે દેવોનો દેવ છે. મનુષ્ય હોવા છતાં દેવથી તે અધિક છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1705,"k":"para","g":"નિર્દંભ અને કપટ રહિત સંતને સાચા સંત જાણવા. સાચા સંતમાં વિશ્વાસપૂર્વક જોડાવાથી અપાર જનો હરિના દાસ થયા છે. સાચા સંત અને નિયમધારી હરિજનો આ સત્સંગનું મૂળ છે. સાચા સંત શ્રીહરિને ભૂલીને કોઈ ક્રિયા કરતા નથી, શ્રીહરિ તેના મૂળ છે, સૌના કારણ છે. પણ દુર્બુદ્ધિ લોકો તેમ સમજતા નથી, અલૌકિક બુદ્ધિ હોય તે સુધી રીત સમજે છે. જેવી સંગત થાય તેવી રુચિ જીવમાં આવે. ભગવાન અને ભગવાનના સંત વિના શુભ માર્ગ પર ચાલવાની મતિ કોઈમાં થતી નથી, માયાના જીવ અનાદિકાળથી માયા સન્મુખ દોડી રહ્યા છે એટલા માટે જ શ્રીહરિ, જનના દોષ દેખતા નથી, અનંત જનને તારવા અહીં પ્રગટ થાય છે. અને પોતાના અદોષ (માયાના દોષે રહિત, ગુણાતીત) સંતને સાથે લાવે છે. તે શ્રીહરિના વચને કરીને અપાર જનને શુદ્ધ કરી તેનો ઉદ્ધાર કરે છે.","e":null,"s":["15/61/24-38"],"sv":["निरदंभ कपट रहित संत जेते । साचे संत कहावत तेते ॥\n\n साचे संत हि हरिजन ताके । सत्संग के मूल रहेउ वाके ॥\n\n साचे संत के हरि रहे मूला । एसे वात रहेउ अमूला ॥\n\n माया के जीय में अनादि तेहु । माया सन्मुख दोर रहे एहु ॥\n\n हरि अरु हरि के संत बिन कबहि । शुभ मग पर मति होत न किनहि ॥\n\n तेहि हित वेर वेर हरि, जन के गिनत न दोष ।\n\n अनंत जन तारन हित हि, प्रगट होत अदोष ॥\n\n अदोष संत ले आत संग, हरि के करिके बचन ।\n\n उद्धार करत अपार जन, शुद्ध करि तेहि मन ॥"],"mt":false,"gl":null,"a":true},{"i":1706,"k":"para","g":"મુક્તમુનિ કહે, “શ્રીહરિએ કહ્યું હતું કે, જગતમાં અમારા આશ્રિત ત્યાગી સાધુ શોભે છે તેનું કારણ અમે આપેલા નિયમોનું પાલન છે. શોભા, કીર્તિ, સુજસ - બધું નિયમોમાં રહેલું છે. શાંતિ, સુખ કે રિદ્ધિ-સિદ્ધિ પણ નિયમપાલનમાં છે. જે નિયમ પાળે છે તે નિર્ભય થઈ ચૂક્યો. નિયમની બહાર પગ મૂક્યો તેને અપાર દુઃખ આવે છે. ‘નિયમ મેં જેહિ વરતત જિહાં લગહિ, મોક્ષ હોત તિનિકો તિહાં લગહિ.’ જ્યાં સુધી નિયમમાં વર્તશે, ત્યાં સુધી ચારે વર્ણનો મોક્ષ નિશ્ચિત છે, એમ માનજો.”","e":null,"s":["16/62/33-39"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1707,"k":"para","g":"વડતાલમાં ફૂલદોલ પછી બાગમાં હોજથી પૂર્વ દિશામાં રાયણનું વૃક્ષ હતું ત્યાં જઈને શ્રીહરિ બેઠા. ત્યાં સંતોને બોલાવ્યા. હજારીના ગુચ્છ-તોરા ને હાર ધાર્યા હતા. હરિભક્તોને ત્યાં આવતા બંધ કર્યા. સંત હતા તેમને એક પછી એક દરેકને ગુપ્ત રીતે કાનમાં સ્વપ્ન સંબંધી વિકાર અંગે પૂછવા લાગ્યા. સંતોએ નિષ્કપટભાવે પોતાને સ્વપ્નની જે પ્રમાણે સ્થિતિ હતી તે પ્રમાણે કહ્યું. સંત થયા પછી એકવાર પણ સ્વપ્નમાં સ્ત્રીનો સંબંધ ન થયો હોય એવા બ્રહ્મમુનિ વગેરે સંતો તથા વર્ણીઓ ઉપર શ્રીહરિ પ્રસન્ન થયા. સંતોએ નિષ્કપટભાવે વાત કરી તેથી શ્રીહરિ પ્રસન્ન થયા. શ્રીહરિ કહે, નિષ્કપટ થાય છે તેને અમે અમારા પરમહંસ માનીએ છીએ. અંતરમાં મેલ રાખે તેનાં નેત્ર અંતરને કહી દે છે.","e":null,"s":["17/9-10/1-5"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1708,"k":"para","g":"ભગવાનના સુખ વિનાનું સુખમાત્ર તુચ્છ ને અલ્પ છે. એ સુખ પામવા સાધુ થયા પછી અલ્પ સુખ સારુ સાધુની પદવીનો ત્યાગ કરવો એ બાળકબુદ્ધિ છે. સંતને પરસ્પર અંતર જુદાં પડે એટલી તેની બાળકબુદ્ધિ જાણવી. તેને સાધુતાના પદની ગમ જ પડી નથી. અલ્પ વસ્તુ માટે મમત થાય કે કોઈ માન ખંડન કરે ત્યારે રંગ રહે નહિ એ બાળકબુદ્ધિ છે. સાધુને મમત્વ અને માન હોય તે જરૂર વિઘ્ન કરે છે. માન જ્યાં રાખવું ઘટે ત્યાં રાખવું જેમ કે ભગવાનના નિશ્ચયનું કોઈ ખંડન કરે ત્યારે તેને પરમ શત્રુ માનીને વર્તવું. એમાં દોષ નથી. વળી, ધર્મનિયમ ભંગ કોઈ કરાવે કે સત્સંગ મુકાવે ત્યારે તેનું બળ કળ્યામાં આવે. એવી વાતમાં તો મમતા અને માન દિન-દિન અધિક રાખવાં એને વિવેક કહ્યો છે. જ્યાં જેટલો સંપ હશે ત્યાં તેટલું સુખ વરતાતું હશે. કુસંપ હશે ત્યાં દુઃખ હશે. જેટલો કુસંપ તેટલો કળિયુગ જાણવો ને સંપ તેટલો સત્યયુગ જાણવો.","e":null,"s":["18/51/29-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1709,"k":"para","g":"મુક્તમુનિ કહે, “શ્રીહરિ કલોલથી નીસર્યા, અર્ધો ગાઉ અડાલજ રહ્યું ત્યારે એક વાત બની. નજરે જોયેલી તે વાત કહું છું – ખરુંસાની નળી આગળ સવારી આવી તેમાં આગળ બાઈઓ હતી, પણ દેશકાળમાં સમજે નહિ તેવા સંતો અધીરપણે દોડી દોડીને શ્રીહરિની આગળ ચાલતા થયા. શ્રીહરિની સવારી ઊભી રહી. શ્રીહરિ સંતને જોઈને કહેતા કે નળીમાં ચાલો. નિત્યાનંદમુનિ આવ્યા ત્યારે પણ આગળ ચાલવાનું કહ્યું, પણ શ્રીહરિના હસવાનો મર્મ જાણી ગયા તેથી આગળ પગ દીધો નહિ ને આગળ જતા સંતોને રોક્યા. આગળ ગયા તે તો ગયા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1710,"k":"para","g":"“શ્રીહરિએ તેમને નજરમાં રાખ્યા હતા. પછી અડાલજ આવ્યા ને વાવથી પૂર્વ બાજુ ઊતર્યા. હરિભક્તો આવી દંડવત્ કરી પગે લાગતા. શ્રીહરિ ગાડી ઉપર બેઠા હતા. હરિભક્તો સેવા કરતા હતા. વર્ણીએ રસોઈ કરી તે શ્રીહરિ જમ્યા. કાઠી સવારોને જમાડ્યા પછી મશાલો થઈ ત્યારે ગાડી ઉપર બેઠા. આરતી, ધૂન ને કીર્તન થયાં. શ્રીહરિએ થોડી વાતો કરી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1711,"k":"para","g":"“પુરજનો પુરમાં ગયા પછી શ્રીહરિએ સંતોને બોલાવીને કહ્યું, ‘સાધુતાની રીત કેવી છે? તે તમે કહો. તમારી સાધુતા જોઈને મતપંથવાળા જે મોટા સિદ્ધ થઈને પૂજાતા તે ઝાંખા પડી ગયા છે અને તમારી પેઠે વર્તી શકતા નથી, તમને જોગ થયો છે તેવો કોઈને થયો નથી. તમારામાં બાળબુદ્ધિ છે ત્યાં સુધી ચિંતામણિની મોટપ મનાતી નથી, તે વર્તન ઉપરથી જણાય છે. અત્યારે પણ આ અમે વાત કરીએ છીએ ત્યારથી વિવેક વિનાના કેટલાક સાધુ મોટા સંતની મર્યાદા નહિ રાખીને આસન પર જઈને સૂતા છે. એમાં એમની કઈ શોભા છે? તમને સુખ આપવા માટે તો અમે સાથે રાખ્યા છે, ત્યારે આ ફળ દીઠું. અવિવેક હોય તેને સમાગમનું કશું ફળ ન મળે. પથ્થર સમુદ્રમાં વર્ષો સુધી પડ્યો રહે તો પણ પાણીથી નરમ ન થાય. કેટલાકમાં તો દેવતા ઝરે! જેમાં વિવેક હતો ને જેમાં વિવેક નહોતો તે માર્ગે ચાલતાં માલૂમ પડી ગયું. અમને ખબર છે. અમને પ્રસન્ન કરવા તમે ઘર છોડી આવ્યા છો, તો પણ અમારી મર્યાદા રાખી નહિ. હરિભક્ત બાઈઓ જે છે તે સભા બેસે ત્યાં સુધી બેસી રહે છે, એટલી તેમની અધિક શ્રદ્ધા છે. અમારાં દર્શનનો ત્યાગ કરી ઊંઘવામાં પ્રેમ કરે તેમાં કેટલો લાભ? દર્શન છોડીને આગળ ચાલે તે કોની આજ્ઞામાં ફરતા હશે? તે મોટેરા હો તે પોત-પોતાના મંડળના સાધુને પૂછો. જેની ભેગા જ્યાં સુધી હોય ત્યાં સુધી તેનું કહેવું કરવું જોઈએ; ન કરે તો ભેગો રહ્યો તે ન રહ્યા જેવો છે. બીજે જાય તેની મોટપ હણાય છે. મનનું કહ્યું કરવું હોય તો તે કહી દો. સત્સંગની એ રીત નથી. મનની મતે ચાલવું તે કુસંગ ગણાય. વચનમાં વર્તવું તે સત્સંગ છે. કુમતિનો સત્સંગ પ્રથમ તો સુમતિ કરતાં વધારે રંગવાળો દેખાય, પણ સંત હરિભક્તના દાસ થઈને વર્તવું તે કુમતિવાળાથી બને નહિ. અમારાં વચન જેનું જીવન બની જાય તે સુમતિ છે. સુમતિ સત્સંગ કરે તે દિન દિન વધતો જાય. વર્તનમાં ફેર હોય તે પ્રમાણે પ્રાપ્તિમાં ફેર પડી જાય છે.’”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1712,"k":"para","g":"બીજે દિવસે મુક્તમુનિને શ્રીહરિ કહે, “તમારા પ્રેમી સંતો કીર્તન ગાઈને સૂઈ ગયા. દર્શનની કાંઈ મનાઈ ન હતી. તેમને બોલાવીને પૂછો કે તમે ભેગા શા માટે ચાલો છો?” બોલાવીને પૂછ્યું ત્યારે તેઓ ઉત્તર આપી શક્યા નહિ. પછી શ્રીહરિ સંતોને કહે, “તમે અમારાં દર્શન કરવા સાથે ફરો છો તો નળીમાં આગળ દોડ્યા તે કોનાં દર્શન કરવા દોડ્યા?”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1713,"k":"para","g":"સંતોને પોતાની ભૂલ સમજાઈ. સૌએ ક્ષમા યાચી. શ્રીહરિ કહે, “સંત અને વિપ્રને તાડનનો દંડ ન હોય. જે સૂઈ રહ્યા તેમણે સવાર સુધી ચોકી કરવી.” એમ કહી જે આગળ ચાલ્યા હતા તેને ઉપવાસના દંડ દીધા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1714,"k":"para","g":"મુક્તમુનિ નોંધે છે કે સંધ્યા આરતી ને ધૂન પછી શ્રીહરિ વાત કરવા લાગ્યા ત્યારે ત્રીજા ભાગના સંતો આસને જઈને સૂઈ ગયા હતા! ગાફલ સંતોની ગાફલતા શ્રીહરિએ દેખાડી તે, ભૂલ સુધરે તે માટે દેખાડી.","e":null,"s":["18/76, 77, 78"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1715,"k":"para","g":"ત્યાગી થઈને ગૃહસ્થ જેવી અઘટિત રીત રાખતો હોય તે તરત જણાઈ આવતું. ગૃહસ્થની રીતનો ત્યાગ કરે તેને સાચા ત્યાગી માનતા. સંતની શોભા ત્યાગમાં છે. ત્યાગીનું જીવન જોઈને ગૃહસ્થ તેનું વચન માને છે. ગૃહસ્થને પ્રથમ સંતમાં પ્રતીતિ આવે છે, પછી વાતો સાંભળીને ભગવાનમાં પ્રતીતિ આવે છે. પ્રગટ હરિના નિશ્ચયમાં સંતનું વર્તન રહેલું છે. સંતની અલૌકિક વર્તનની રીત, કથા-કીર્તન અને વાર્તા - એ બધું અનંત જીવના ઉદ્ધાર માટે છે. જીવોના ઉદ્ધાર માટે આ વખતે મોટી સડક મોક્ષની શ્રીહરિએ બાંધી છે. તેમાં અંતર-બાહ્ય સંગ એવા સંતનો કરવો, જે બાંધેલી સડક પર ચાલતા હોય, નિયમનો ભંગ કરી ચાલનારાને ઓળખીને શ્વપચની જેમ ત્યાગ કરવો. નિયમ-ધર્મયુક્ત સાચા સંત મળે તેને મન સોંપી દેવું. સંત જેમ વધુ ને વધુ પ્રસન્ન થાય તેમ વર્તવું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1716,"k":"para","g":"સાચા સાધુને પોતાના સ્વાર્થ પર તાન હોતું નથી. જે અસાધુ છે તે પોતાનો સ્વાર્થ સાધવા રાત-દિવસ પુરુષાર્થ કરે છે. બીજા સંતની મોટપ તલભાર પણ સહન કરી શકતા નથી. એટલે સંતના ગુણ તેમાં આવતા નથી. પ્રગટ ભગવાનના નિશ્ચયવાળા અન્ય ભક્તને પોતાના કરતાં મોટા જાણે અને એવા સંતનાં દર્શનથી પોતાને ધન્ય માને ને પોતાનો આનંદ-કેફ ઓછો થવા ન દે એ સંતને મોટા જાણવા. પોતે નિર્માનીપણે વર્તીને બીજાને યથાયોગ્ય માન આપતા રહે છે. પોતાના ગુણનો તેમને ક્યારેય ગર્વ હોતો નથી. સંતમાં જ્યારે માન દોષ પ્રવેશે છે, ત્યારે પોતાના જેવી સાધુતા કોઈમાં દેખાતી નથી. એટલે સંતને તો ગરીબ થવું, સહન કરવું, સાંભળી લેવું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1717,"k":"para","g":"સહન કરવું તે સંતનો ગુણ છે. શાસ્ત્ર ભણેલો વાતો સારી કરે, પણ મનમાં ફુલાય કે મારા જેવી કથા કોઈ સંત ન કરી શકે તો તેની તલ જેટલીય મોટપ રહેતી નથી. દત્તાત્રેયે ચોવીસ ગુરુ કર્યા એ સંતની રીત છે. સત્સંગની પ્રથામાં મળતું આવે એટલું ગ્રહણ કરવું. નિષ્કામશુદ્ધિ અને ધર્મામૃતમાં સંતની રીત કહી છે. એ પ્રમાણે વર્તે તેને જ શ્રીહરિ સાધુ કહે છે. પોતે પોતાની રીતે ફાવે તેટલો મોટો સંત માનતો હોય, પણ ધર્મામૃત અને નિષ્કામશુદ્ધિ આ બન્ને ગ્રંથ તેને પ્રમાણ કરે ત્યારે સાચું. પોતે અધિક માને તેથી કંઈ અધિક થવાતું નથી. ભલે તેને ઊંચે આસને બેસારીને લોકો પૂજે, પણ તે સાચા સાધુ પાસે તુચ્છ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1718,"k":"para","g":"સાચો સંત તો સંતની આગળ ઊંચે આસને બેસવું તેમાં કોચવાય છે. ગુણે કરીને બેસવું પડે તોપણ તેને શૂલી કરતાં અધિક માને છે. આમ, સંત અને અસંતમાં આસમાન-જમીનનો ફેર છે. બધા સંતો જુદાં જુદાં ધામથી આવેલા છે. કેટલાક અક્ષરધામથી તો કેટલાક ગોલોકમાંથી, કેટલાક વૈકુંઠમાંથી તો કેટલાક શ્વેતદ્વીપ ને બદરિકાશ્રમમાંથી - એમ પૃથક્ પૃથક્ આવ્યા હોવાથી બધાની રીત એક સરખી મળતી નથી.","e":null,"s":["22/88/12-38"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1719,"k":"para","g":"ત્યાગ-વૈરાગ્ય, ભક્તિ, ધર્મ, જ્ઞાનાદિક અપાર ગુણ હોય પણ જો લોકને દેખાડવા માત્રના હોય તો તેનાથી અર્થ સરતો નથી. ભગવાનને રાજી કરવા આ ગુણો કેળવે તો તે સત્ય બને છે. દ્રવ્યનો લોભ રાખે ને લોક રીઝવવા ભજન કરે તે અસત્પુરુષપણું છે. સાચા સંત તો લોકમાં વિચરીને કુવાર્તાનો ત્યાગ કરાવે ને ભગવાનને ભજે ને ભજવે. બધી વાતમાં ભગવાનનું પ્રધાનપણું રાખે તે સાચા સંતનો માર્ગ છે. એવા સાધુ ધર્મે સહિત ભગવાનની ઉપાસના કરે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1720,"k":"verse","g":"‘સાચે સંત કા મારગ તેહિ, ભગવાન કું અધિક રખત એહિ;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1721,"k":"verse","g":"ધર્મ જુત ભગવાન તાકી, ઉપાસના કરત રહે વાકી.’","e":null,"s":["23/81/45-48"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1722,"k":"para","g":"કોઈ મુમુક્ષુ જન ત્યાગી થવાની ઇચ્છા રાખતો હોય, પણ એના ત્યાગી થવાથી ગામ કે દેશના હરિજનોને જો સંતનો કે સત્સંગનો અભાવ આવે એવી પરિસ્થિતિ ઊભી થવાની હોય તો શ્રીહરિ તેને ત્યાગી બનાવતા નહિ. સૌને સંતમાં, સત્સંગમાં દિન-દિન ભાવ વૃદ્ધિ પામતો રહે ને જીવમાં સમાસ થાય એમ શ્રીહરિ કરતા.","e":null,"s":["26/7/31-34"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1723,"k":"para","g":"ત્યાગી થયો તેણે દેહના સંબંધીને ક્યારેય સંભારવા નહીં. ત્યાગી થઈને સંબંધી સાથે નાતો રાખે છે ને મનમાં સંભારે છે તેને શુક સનકાદિક અને નારદ આદિ સાધુની પંક્તિમાં ગણતા નથી. ત્યાગીને તો ભગવાન જ સાચા સંબંધી છે. અને જે ભગવાનના ભક્ત છે તેને ભગવાન સિવાય બીજું કોઈ અધિક હોય નહીં.","e":null,"s":["25/51/9-11"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1724,"k":"para","g":"જે આત્મસ્વરૂપ છે, ધર્મ, ભક્તિ, જ્ઞાન, વૈરાગ્ય અને ભગવાનની ઉપર જેને તાન છે, સર્વોપરી વર્તનવાળો છે અને સુખમાત્રનું મૂળ ભગવાન છે એમ માને છે તેને બધી સિદ્ધિઓ દાસીની પેઠે તેની સેવામાં પાછળ પાછળ ફરે છે.","e":null,"s":["26/51/27-28"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":21,"gu":"પ્રગટ","en":"Pragat — The Manifest Form","url":"https://www.anirdesh.com/pbp/index.php?page=chp_21","b":[{"i":1725,"k":"para","g":"કારિયાણીમાં ખટ્વાંગ રાજાએ શ્રીહરિ અને સંતોની પૂજા કરી. અને ગદ્‌ગદભાવે પ્રાર્થના કરી. શ્રીહરિએ તેમને પ્રસન્ન થઈ કહ્યું, “ભગવાનના પ્રગટ સ્વરૂપમાં જેનો નિષ્ઠાભાવ છે તે ભક્તને સર્વથી શ્રેષ્ઠ જાણવો. પ્રગટ સ્વરૂપને મૂકી જે અન્યને ભજે છે તે કુમતિ છે. જેમ જેની કૂખે જન્મ ધર્યો તે માતાપિતાને મૂકી કોઈ બીજા પર બહુ પ્યાર રાખે તે શું ડાહ્યો કહેવાય! એ કુમતિ જન છે. હાલ જેના દ્વારા જન્મ મળ્યો તેને છોડીને પૂર્વે થઈ ગયેલાં માતાપિતામાં મન જોડે તે મૂર્ખ છે. તેમ પૂર્વે થઈ ગયા તેમાં મન જોડે ને તેની પરમ સેવા કરે તેને પ્રગટની વાત હાથ આવી નથી. તેને કુમતિ જાણવો. પ્રગટ સ્વરૂપને ઓળખી તેમાં જીવ બાંધવો એને પતિવ્રતા તુલ્ય ભક્તિ કહી છે. એવી ભક્તિ કરનાર ભક્ત પાવનકારી છે. તે વિના અન્ય સર્વ ભક્તોને વ્યભિચારી ભક્ત જાણવા.”","e":null,"s":["4/28/49-52"],"sv":["तेहि भक्त सर्वोपरि, प्रगट स्वरूप में भाव ।\n\n प्रगट स्वरूपकुं तज के, भजे सो कुमति कहाव ॥\n\n मात तात जीव किन बहु, गिनत न आवे पार ।\n\n जन्म लियो तेहि तजके, और पर रखे बहु प्यार ॥\n\n सोई कुमति जन, जन्म भयो तेहि छोर देत ।\n\n हो गये तेहि जोरे मन, परम सेव ओरकी करे ॥\n\n पतिव्रता की रीत, प्रगट स्वरूप में बांधनो जीव ।\n\n भक्त सो परम पुनीत, तेहि बिन भक्त व्यभिचारी सब ॥"],"mt":false,"gl":null,"a":false},{"i":1726,"k":"para","g":"કારિયાણીમાં શ્રીહરિએ વાત કરી કે, “પ્રગટ વગર મુક્તિ નથી.” ત્યારે મુક્તમુનિએ પૂછ્યું, “પ્રગટ સ્વરૂપની વાત તમે કહો છો, પણ શાસ્ત્રમાં એ નથી. તો અન્યને કેમ સમજ પડે! ગ્રંથમાં કલ્યાણની વાત અનેક પ્રકારે લખી છે. તે જોઈને મતિ ભમી જાય છે. તો કોનામાં સ્નેહ કરવો?”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1727,"k":"para","g":"આ સાંભળી શ્રીહરિએ વિસ્તારથી વાર્તા કરી, “એક કાર્યને સિદ્ધ કરવા અનેક સાધન જોઈએ. એમ મોક્ષનું કામ સરળ કરવા શાસ્ત્રો અનેક પ્રકારનાં રહ્યાં છે. એક એક શાસ્ત્રમાં વાતો પણ અનંત પ્રકારે લખાઈ. જેનો પાર આવે તેમ નથી. વળી, જીવે અનંત જન્મ ધર્યા છે તે એક એક જન્મની રુચિ ભિન્ન ભિન્ન ભેગી થઈ છે. કોઈને એક શ્રદ્ધા નથી. વળી, જાતિ અનેક છે, તેમાં પણ દેશકાળ અનુસારે તે તે જાતિ માટે વિચારીને કેટલીક વાતો લખી હોય, કેટલીક યુગ અનુસાર લખી હોય, કેટલીક આપત્કાળે કેમ રહેવું તે વાતો લખી હોય. એમ, શાસ્ત્રોમાંથી મોક્ષની વાત હાથમાં આવતી નથી. ખોટા સંત મળે તો શાસ્ત્રને વિપરીત નિરૂપે. પરંતુ ભગવાન પ્રગટ મળે છે, ત્યારે જુદી જ વાત બને છે. સર્વે શાસ્ત્ર પ્રગટમાં આવી મળે છે. પ્રગટ સૂર્ય વિના અંધારું ટળે નહિ, પ્રગટ અન્ન વિના ક્ષુધા ટળે નહિ. પ્રગટ જળ વિના તૃષા છિપે નહિ - એમ લોકમાં પણ પ્રગટનું મા’તમ છે. તેમ પ્રગટ ભગવાનના સંબંધ વિના કોટિ ઉપાયે મોક્ષનું કાર્ય સરતું નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1728,"k":"para","g":"“પ્રગટની વાત પણ શાસ્ત્રમાં છે. કોઈ વાત શાસ્ત્રની બહાર નથી. શાસ્ત્ર બહાર કહેનારો ગમાર છે. ભગવાન ને સંતનાં લક્ષણો શાસ્ત્રમાં કહ્યાં છે. તે મુજબ તેને ઓળખી જીવ જોડે તો મોક્ષ થાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1729,"k":"para","g":"“પ્રગટ ભગવાનના સંકલ્પમાં શાસ્ત્રમાત્ર સમાઈ જાય છે. એમની વાણીને જ શાસ્ત્ર કહ્યું છે. એટલે જ એ શાસ્ત્રને જે ન માને તે અસુર છે. સંત મળે છે ત્યારે આ વાત સમજાય છે. સંતની રીત સાચી છે, અસંતની ખોટી છે. જેણે પોતાનું શ્રેય કરવું છે, તે વારંવાર આ પ્રગટની વાત ધારે ને વિચારે તો તેને અવશ્ય સમજાશે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1730,"k":"verse","g":"‘સંત કી હે સત્ રીત, અસંત કી હે અસત્ મહા,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1731,"k":"verse","g":"અપને કરનહિ હિત, વાર વાર ધારના વિચાર કર.’","e":null,"s":["4/29/1-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1732,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ જીવેન્દ્ર નૃપને વાત કરતાં કહ્યું, “ભક્તજનોએ અમારી આજ્ઞામાં વર્તી અત્યંત નિર્વાસનિક થવું, તો અમારા ધામમાં જવાશે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1733,"k":"para","g":"“અપાર જનોના મોક્ષ કાજે આજ અમે પુરુષોત્તમ સ્વયં પ્રગટ થયા છીએ. સૂર્ય વિના કોટિ ઉપાયે અંધારું ન ટળે, તેમ અજ્ઞાનરૂપ અંધારું જીવને અનંતકાળથી વળગ્યું છે. તેનો પ્રગટ હરિ વિના અંત આવે નહિ.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1734,"k":"verse","g":"‘અનંત જન કે મોક્ષ હિ કાજા, પુરુષોત્તમ પ્રગટ હેં આજા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1735,"k":"verse","g":"અજ્ઞાનરૂપ તિમિ તમ અનંતા, પ્રગટ હરિ બિન આત ન અંતા.’","e":null,"s":["4/11/45-48"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1736,"k":"para","g":"બોટાદના મહાજન પાસે શ્રીહરિએ વાત કરતાં કહ્યું, “પૂર્વે જેને જે જે અવતારનો યોગ થયો, તેણે તે તે અવતારમાં જ અધિક ભાવ રાખ્યો છે. તેમ તમારે પણ સંપ્રદાયની રીતિ અનુસાર સમજવું. બીજાના ઘરનું દ્રવ્ય પોતાને ખપ ન લાગે. તમને જે મળ્યું છે તેવું બીજાને મળ્યું નથી. બહુ પ્રકારે જતન કરીને તે જાળવવું. કુસંગથી છેટે રહી પ્રગટનાં ચરિત્રોનું ચિંતવન, મનન અહોનિશ કરવું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1737,"k":"para","g":"“પ્રગટનું ધ્યાન-ભજન, કથાવાર્તા-કીર્તન, સ્મરણ કરવું. અનેક પ્રકારે તેની પૂજા કરવી. જેને સત્સંગ થયો છે તેને આ પ્રકારે પ્રગટનો સંગ કદી છૂટતો નથી. જેટલું ભગવાનનું વિસ્મરણ એટલો તેને કુસંગ જાણવો. એ કુસંગ ન લાગે તેનો ભય સદા રાખવો.”","e":null,"s":["4/42/43-48"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1738,"k":"para","g":"લોયા-નાગડકામાં શ્રીહરિએ સંતોની પંક્તિમાં પીરસ્યું. સૌને જમતાં જોઈ શ્રીહરિ અપાર પ્રસન્ન થયા ને કહ્યું, “અમારે એક એક સંત દ્વારા અનંત જનનો મોક્ષ કરવો છે. અક્ષરપતિ અવિનાશી અમે પોતે અનંત શક્તિના ધરનારા આજે મોક્ષના દ્વાર રૂપે પ્રગટ છીએ. આજે હેતે કરીને તમને પોતાની વાત કરીએ છીએ.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1739,"k":"verse","g":"‘અક્ષરપતિ અવિનાશ હરિ, અનંત શક્તિ ધર તાય,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1740,"k":"verse","g":"પ્રગટ રહે મોક્ષ દ્વારહિ, તુમકું કહત હિત લાય.’","e":null,"s":["4/56/11-13"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1741,"k":"para","g":"મેમકામાં શ્રીહરિ સંતોને કહેવા લાગ્યા, “ધર્મ, જ્ઞાન, વૈરાગ્ય ને ભક્તિ - આ એકાંતિક ધર્મ છે. તેમાં રુચિ થાય, અનુરાગ જાગે તો બ્રહ્મવિદ્યા વરે. એકાંતિક ધર્મ વિના બ્રહ્મવિદ્યા ફળીભૂત થતી નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1742,"k":"para","g":"“આ સર્વેનું મૂળ બીજ પ્રગટની દૃઢ ઉપાસના છે. જે દી તે દી આમ વિચારીને પ્રગટને આધીન વર્તશે, ત્યારે મોક્ષ પ્રાપ્ત કરશે.”","e":null,"s":["4/89/22-23"],"sv":["तामें धर्म भक्ति वैरागा । अरु ज्ञान को चहिए अनुरागा ॥\n\n ता बिन ब्रह्मविद्या जोऊ । फलीभूत न होवे सोऊ ॥\n\n प्रगट उपासना दृढ जेहू । सबको मूल बीज हें तेहू ॥\n\n मूल बीज से रहे अधीना । सोचत मोक्ष लहे कोउ दिना ॥"],"mt":false,"gl":null,"a":false},{"i":1743,"k":"para","g":"ભુજમાં શ્રીહરિએ ભક્તો આગળ વાત કરતાં કહ્યું, “અમે આ લોકમાં મનુષ્યદેહ ધર્યો છે. મનુષ્યોને શરણે લઈ તેનું હિત કરવા મનુષ્યની રીતે વર્તન કરીએ છીએ. અમારા જન્મથી લઈને બધાં ચરિત્ર પરમ પવિત્ર છે. કોઈ તેમાં પરોક્ષભાવ લાવીને વર્ણન કરે, પણ આશય પ્રત્યક્ષ મૂર્તિનો છે. પહેલાં પરોક્ષમાં પ્રીત થાય પછી પ્રત્યક્ષમાં થાય એવી અનાદિની રીત છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1744,"k":"para","g":"“જેને પ્રત્યક્ષ સ્વરૂપનું યથાર્થ જ્ઞાન થયું તે તેની મરજીને બરાબર જાણે છે. પ્રત્યક્ષ ભગવાનની રુચિ, મરજી અનુસાર ગ્રંથરચના કરે તે મહાકવિ કહેવાય. જે ગ્રંથ પરસ્પર વૈરભાવ પ્રગટાવે, તે ગ્રંથ જ ન કહેવાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1745,"k":"para","g":"“લોક, શાસ્ત્ર અને અનુભવમાં મળતું આવે તેમ હરિનાં ચરિત્ર વર્ણવ્યાં હોય તો તેને સાંભળીને કોઈને અભાવ આવે નહિ.”","e":null,"s":["5/59/14-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1746,"k":"para","g":"ગઢપુરમાં શ્રીહરિને જીવાખાચરે પૂછ્યું કે, “એકને ભગવાન મુખ્ય છે અને બીજાને માયા મુખ્ય છે. તેનું શું કારણ?” ત્યારે શ્રીહરિ કહે, “બધાની બુદ્ધિ એક નથી હોતી. અર્જુન અને ભીષ્મ બંને ભક્ત હતા. બંને કૃષ્ણ વિના બીજાને માનતા નહોતા, પણ અર્જુન શ્રીકૃષ્ણ કહે તેમ ચાલતા. જ્યારે ભીષ્મ પોતાનું ધાર્યું કરતા. મહિમા ઘણો જણાયો પણ કૃષ્ણનું ગમતું ન કર્યું. ભગવાન પાસે ચક્ર ધરાવડાવ્યું. પછી પોતે મરવા ઇચ્છ્યું. ટેક છોડાવીને પછી બહુ સ્તુતિ કરી. ભક્તની તે રીત નહીં. ત્યાગ, જપ, તપ, વ્રત, તીર્થ, યજ્ઞ, બ્રહ્મભોજન તથા નાના પ્રકારનાં દાન કરે પણ મનમુખી હોય તેનું કલ્યાણ થતું નથી એમ અમે માનીએ છીએ. સૂર્ય ઉદય થાય તો દીવા, મશાલની જરૂર રહેતી નથી; વરસાદ પડે ત્યારે કોસથી પાણી કાઢવાની જરૂર રહેતી નથી; વહાણમાં બેસે તેને તુંબડાં બાંધવાની જરૂર રહેતી નથી, તેમ ભગવાન પ્રગટ મળે ને તેનું ગમતું કરે તેને બીજાં સાધન આપોઆપ થઈ જ જાય છે.”","e":null,"s":["5/72/1-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1747,"k":"para","g":"માંગરોળમાં ગામ-ગામના હરિજન આવ્યા અને અન્નકૂટોત્સવ કર્યો. શ્રીહરિની આરતી ઉતારી. જય-જયનાદ ગુંજાવ્યો, સૌએ સ્તુતિ કરતાં કહ્યું, “આપ અમને મળ્યા. અમારાં ભાગ્યનો પાર નથી. અમારો મનુષ્યજન્મ સાર્થક કર્યો. મનુષ્યદેહ પામીને જેને શ્રીહરિનો યોગ નથી થયો, તેને અમે અતિ અભાગી કહીએ છીએ.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1748,"k":"para","g":"ત્યારે શ્રીહરિ કહે, “અમે સત્સંગમાંથી જતા નથી. અમારા પછી પણ જે જીવ સત્સંગમાં જન્મ લેશે ને અમારાં જે જે વચન છે તેમાં પ્રતીતિ લાવીને તે પ્રમાણે વર્તશે તેનો અમે મોક્ષ કરીશું. અમારાં ચરિત્ર જે સાંભળશે, તેને અમે અતિ સુખિયા કરીશું. અમારાં વચન એ અમે જ છીએ એમ જરૂર જાણજો. અમારાં વચન જે પાળે તેની પાસે અમે રહીએ છીએ. અમારાં વચન ન માને અને રાત-દિવસ અમારી પાસે રહી સેવા કરે, તેને અમે દૂર માનીએ છીએ. આ અમારો મત સૌ હરિજનો નિશ્ચય કરીને માનજો. અમારાં વચન અમારા કરતાં પણ મુખ્ય અમે માનીએ છીએ. પંચભૂતનું તન તો પંચભૂતમાં મળશે પણ અમે જે જે વચન કહ્યાં છે તે વિચારશો તો અમારું પ્રગટપણું જણાશે.”","e":null,"s":["6/73/22-27"],"sv":["हरि कहे हम पिछें जेहा । सत्संग में आवहि तेहा ॥\n\n हमारे वचन कुं मानहि जाहि । मोक्ष सो हम करहि ताहि ॥\n\n हमारे चरित्र सुनहि जेहि । अति सुख हम देवहि तेहि ॥\n\n हमारे जो वचन हि जितना । हमकुं सो जानना तितना ॥\n\n हमकुं जानि पालहि जोई । वचनरूप ता पास हें सोई ॥\n\n हमारि पास रहत दिन रेनां । सेवा करत रहत प्रवेनां ॥\n\n वचन में न वरतहि जोउ । हमसें दूर तेहि जानत सोउ ॥\n\n हमारो मत नकि हे एउ । सब हरिजन सो जानिके लेउ ॥\n\n हमसें वचन हम मुख्य हि माने । वचन में हम अखंड ठाने ॥\n\n यह तन जितनो काज रहावुं । सो पुरे करि कें चलि जहावु ॥\n\n परोजन हित हे तन यह, परोजन भये न रहात ।\n\n वचनरूप तन रहहि सदा, सिद्धांत कहि यह बात ॥"],"mt":false,"gl":null,"a":false},{"i":1749,"k":"para","g":"જૂનાગઢમાં શ્રીહરિએ મુક્તમુનિને ધ્યાનમાંથી જાગ્રત કરી કહ્યું, “અમારાં પ્રગટ ચરિત્રોનું તમારે નિત્ય ચિંતવન કર્યા કરવું. અમે જ્યારથી પ્રગટ થયા ત્યારથી આજ સુધી જે કંઈ ચરિત્રો કર્યાં છે તે બધાં પરમ પવિત્ર છે ને કલ્યાણકારી છે. એના જેવી કોઈમાં શાંતિ નથી. બ્રહ્મસુખના કરતાં પણ કોટિગણી શાંતિ અમારાં ચરિત્રોમાં રહેલી છે. અમારાં ચરિત્રો અને વચનનાં કાવ્ય-કીર્તન તમારે સદા કરવાં એ તમને અમારી આજ્ઞા છે.”","e":null,"s":["6/80/26-28"],"sv":["श्रीहरि मुक्तमुनि कुं, देह में लाए ततखेव ।\n\n मुक्तमुनि सें कहत भये, वचन अमृत सम एव ॥\n\n हमारो प्रगट चरित्र, तुमारे करना चिंतवन ।\n\n सबसें परम पवित्र, प्रगट भये जांइ से अब ॥\n\n एहि सम शांति न कोई, ब्रह्मसुख सें कोटि गनि हे यह ।\n\n वचन हम कहत सोई, काव्य कीर्तन एहि करनो सदा ॥"],"mt":false,"gl":null,"a":false},{"i":1750,"k":"para","g":"શ્રીહરિએ કહેલી વાત મુક્તમુનિએ કહી, “ભગવાન પ્રગટ થાય છે ત્યારે ભક્તના સર્વે મનોરથ પૂર્ણ કરે છે. આ વખતે ધર્મ, જ્ઞાન, વૈરાગ્ય અને ભક્તિ સહિત એકાંતિક ધર્મનું સ્થાપન કર્યું છે. આ ચારેને ધારણ કરે તેની મહત્તા છે ને તેનો જ યશ લોકમાં વધે છે. જે પુરુષ જેટલા અંશે તેનું ધારણ કરે તેને તે મુજબ ઉત્તમ, મધ્યમ ને કનિષ્ઠ ભક્ત કહેવાય છે. ચારેને ધારણ કરનારો અતિ પરમ ને અનુપમ કહેવાય છે. ઇહલોક-પરલોકમાં આ ચારે ઉત્તમ આભરણ છે. ઉત્તમ ભક્ત તેને અખંડ ધારણ કરી રાખે છે. ભગવાન પ્રગટ થાય છે ત્યારે તેનું તાન સૌને આ આભરણ પહેરાવવાનું છે. કારણ, મોક્ષરૂપી ફળ આ એકાંતિક ધર્મમાં રહેલું છે ને તેના વગર મોક્ષ અધૂરો રહે છે. ભગવાનના નિશ્ચયરૂપી સાધનના આ ચાર પાયા છે, પરંતુ પ્રગટ ભગવાનના નિશ્ચય વિના કોઈ સાધન ફળીભૂત થતું નથી.”","e":null,"s":["6/101/26-32"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1751,"k":"para","g":"શ્રીહરિએ અલર્ક રાજાને વાત કરતાં કહ્યું, “જેને પ્રગટ હરિ મળ્યા છે તે દુઃખમાત્રથી તરી ગયા છે. તેમાં તો વિશ્વાસ રાખી તેમના વચનને જ ખીલો માની, તે ખીલે મનને બાંધી દેવું. મનનું રાજ્ય હોય ત્યાં સુધી મોક્ષ થાય નહિ. મનનો વિશ્વાસ નહિ રાખતાં શ્રીહરિનાં વચનનો વિશ્વાસ રાખી અનંત ભક્તો ધામમાં ગયા છે, તેને દેખ્યા છતાં જે નથી માનતા તે બુદ્ધિમાન હોય તોપણ જમપુરી અને ચોરાશીનાં દુઃખ છૂટતાં નથી, અને ત્યાં બુદ્ધિ કામ લાગતી નથી. માટે જેણે અમને વશ કરવા હોય, તેણે તો પ્રથમ અમને વશ થવું પડે.”","e":null,"s":["9/40(41)/34-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1752,"k":"para","g":"શ્રીહરિ સંતો-ભક્તો કરિયાણાથી નીકળ્યા. માર્ગમાં નદી આવી. તેમાં કીર્તનો ગાતાં ગાતાં સ્નાન કર્યું. ત્યાં ખંભાળાના માણસિયા ખાચર તથા મોકા ખાચર આવ્યા ને શ્રીહરિને દંડવત્ કરી વિનંતી કરી કે, “અમારે ગામ કેમ ન આવ્યા! સૌ પુરજનો તમારાં દર્શન માટે તલસે છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1753,"k":"para","g":"શ્રીહરિ કહે, “અમારે ક્યાં અહીંયાં એક વખત આવવાનું છે? દેહ પર્યંત ગામોગામ ફરતા જ રહીએ છીએ. અને દેહ છૂટ્યા પછી પણ ફરવું છે. કારણ, વૈકુંઠ ગોલોકાદિ ધામ પણ સત્સંગ તુલ્ય નથી. તે ધામના વાસીઓ, ભવ, બ્રહ્મા, શેષ શારદા ને અન્ય દેવો, ઋષિ-મુનિઓ પણ સત્સંગ કરવા ઇચ્છે છે. બીજાં સુખ જીવને મળવાં સહેલાં છે, પણ સત્સંગ મળવો દુર્લભ છે.”","e":null,"s":["10/9/3-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1754,"k":"para","g":"જૂનાગઢમાં દીવાનને શ્રીહરિ કહે કે, “કામ, ક્રોધ આદિકનો અમે તથા અમારા સંતો વિશ્વાસ રાખતા નથી. ભગવાનના ધામના સુખમાં જેની મતિ દૃઢ ચોંટી હોય તે અહીંના તથા ત્યાંના સુખનો વિચાર કરે. હરિના શરણ વિના ક્યાંય સુખ ન દેખાય તેવી સમજણ સમાધિથી કોટિગણી શ્રેષ્ઠ છે. સમાધિ કઠણ નથી, સ્વપ્ન જેવી છે. સ્વપ્નમાં રાજા થાય પણ જાગ્રત થાય ત્યારે તેના તે, તેમ કોટિ વાર સમાધિ થાય તોપણ મતિ શુદ્ધ ન થાય તો અષ્ટાંગયોગ શીખ્યો હોય તોપણ બધું વ્યર્થ છે. ગજ અથવા ગર્દભને વારંવાર નવડાવો તોય બહાર નીકળે ત્યારે તેવાને તેવા થઈ જાય. દીવો દેખીને જેમ પતંગિયું લોભાય છે તેમ જગતનું સુખ દેખીને લોભાય ત્યાં સુધી સમાધિનો કાંઈ અર્થ નથી. પ્રગટ હરિનો જોગ રાખીને જે મરે છે તે ભગવાનના ધામમાં જાય છે. વચમાં ક્યાંય અટકતો નથી. શ્રીહરિનો જોગ તે અગ્નિ રૂપ છે, તે જીવના મળમાત્રને બાળી મૂકે છે. તેમના યોગ વિના મળ છૂટે એવા નથી.”","e":null,"s":["11/38/22-32"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1755,"k":"para","g":"ભૂજમાં શ્રીહરિ કહે, “જીવનો મોક્ષ કરવા દેવતાઓ પણ સમર્થ નથી. મોક્ષ આપવામાં તો પ્રગટ ભગવાન કે ભગવાનના સાધુ સમર્થ છે. પ્રગટ હરિના સંતો, ભક્તો દેવથી પણ અધિક છે. તેમની જે સહાય કરે છે તે જન્મમરણથી અને ચોરાશીથી મુકાય છે.”","e":null,"s":["12/37(36)/22-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1756,"k":"para","g":"હળવદમાં વિપ્ર નારણજીને ત્યાં શ્રીહરિએ કહ્યું, “શુભ આચરણ કરતો હોય, પણ પ્રગટ ભગવાનનો નિશ્ચય ન હોય તો તે શુભ યોનિને પામે, પણ જન્મમરણથી રહિત ન થાય. માટે પ્રગટ ભગવાનનો નિશ્ચય તે મુખ્ય શુભ માર્ગ છે. જ્યારે જે રૂપે હરિ પ્રગટ હોય તેને પ્રગટ હરિ જાણવા. પ્રગટને ઓળખી નિશ્ચય કરે તે જ ભક્ત કહેવાય છે. હરિ ભૂતળ પર સદા પ્રગટ રહે છે. જે સમયે જેના દ્વારા પ્રગટ હોય તે પ્રગટ હરિ છે. તેનો નિશ્ચય તે પ્રગટનો નિશ્ચય છે. તે પ્રગટ ગુરુરૂપ હરિ જગતનો ઉદ્ધાર કરવા સમર્થ છે.” એવી શ્રીહરિની વાત જે હરિજને સાંભળી તે સૌ ધન્ય ધન્ય થયા.”","e":null,"s":["15/3/47-53"],"sv":["प्रगट हरि को निश्चय नाहि । शुभ आचरण केसो रहे ताहि ॥\n\n शुभ जोनि कुं पावे तेहा । जन्ममरण न छूटे कबु एहा ॥\n\n प्रगट हरि को निश्चय जाकुं । मुख्य शुभ मारग कहत ताकुं ॥\n\n श्रीहरि को प्रगट निश्चय, हरि प्रगट जब जाहि ।\n\n कहत है हरिजन तितने, कहावत हें भक्त ताहि ॥\n\n जो जो समय भगवान जो, प्रगट होत जेहि वार ।\n\n प्रगट हरि सो जानना, बात कहे निरधार ॥\n\n भगवान प्रगट जिहां लगहुं, फेर होवहि तिंहा लग ।\n\n प्रगट हरि तेहि रहत हि, समर्थ हि तारन जग ॥\n\n ऐसी करत हरि बात, सत्संग में फिरत जिहां ।\n\n सुनत जो जन रहात, धन्य धन्य भये भाग्य तेहि ॥"],"mt":false,"gl":null,"a":false},{"i":1757,"k":"para","g":"મુક્તમુનિ કહે શ્રીહરિ એક વાત વારંવાર કહેતાં કે, “ભગવાન અને ભગવાનના સંત-હરિજન જ્યાં વિચરણ કરે તે ભૂમિ તીર્થધામ બની જાય છે. અન્ય તીર્થ નામમાત્ર તીર્થ, ધામ કે સ્થલ તરીકે રહે છે.”","e":null,"s":["15/44/37-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1758,"k":"para","g":"શ્રીહરિએ રામદાસ, મુક્તમુનિ, બ્રહ્મમુનિ ઇત્યાદિ પર પત્ર લખાવતાં એક વાત લખી, “ભગવાનનાં સર્વ ચરિત્રોને સદા દિવ્ય જ માનતા હોય તે ભગવાનના અનાદિ ભક્ત છે. અનાદિ ભગવાન (પુરુષોત્તમ) અને અનાદિ ભક્ત (અક્ષર) અહીં આવે છે, રહે છે અને શરણાગત જીવોનો ઉદ્ધાર કરે છે તેને ઓળખી લેવા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1759,"k":"verse","g":"‘અનાદિ જો ભગવાન, અનાદિ રહે ભક્ત જેહુ;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1760,"k":"verse","g":"આવત રહત પિછાન, શરનાગત કે ઉદ્ધાર કરત.’","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1761,"k":"para","g":"“જ્યાં મોક્ષકારક એકાંતિક ધર્મનું સ્થાપન કરવાનું તાન છે અને અધર્મનું ઉત્થાપન કરવાનું તાન રહે છે, એવી કપટ રહિત રીત જ્યાં દેખાય ત્યાં ભગવાનનો વાસ છે એમ જાણવું.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1762,"k":"verse","g":"‘મોક્ષ-ધર્મ સ્થાપન પર તાના, અધર્મ ઉથાપન તાન રહાના.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1763,"k":"verse","g":"નિષ્કપટ એસિ રીત જિહાં રહેઉ, ભગવાન કે વાસ તિહાં કહેઉ.’","e":null,"s":["15/69/27-30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1764,"k":"para","g":"શ્રીહરિએ પત્રમાં લખાવતાં કહ્યું, “પ્રગટ ભગવાન અથવા ભગવાનના સાચા સંત વિના કોઈ મોક્ષનો માર્ગ જીવને દેખાડી શકતું નથી. સંતના યોગથી જીવ ભવબંધનથી છૂટે છે. જેમ પ્રગટ ભોજન મળ્યા વિના ભૂખ ભાગે નહિ, તેમ ભગવાન પ્રગટ મળ્યા વિના મોક્ષ ન થાય.”","e":null,"s":["15/86/35-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1765,"k":"para","g":"શ્રીહરિએ સાંખ્યયોગી બાઈ-ભાઈઓને પત્રમાં લખ્યું, “જેને પ્રગટ ભગવાન કે ભગવાનના સંતની પ્રાપ્તિ થઈ છે એવા હરિભક્તો ફાવે તેમ દેહ મૂકે, તે ભગવાનના ધામમાં જ જાય છે. તેમાં હરિભક્તોએ સંશય રાખવો નહિ. જેને સત્સંગ નથી એવા લોકો ગમે તેવા તીર્થમાં રહે કે યોગ, યજ્ઞ કરે અને શાસ્ત્ર પ્રમાણે વિધિ સહિત દેહ મૂકે તોપણ તે મુક્ત થઈ શકતો નથી. સત્સંગની રીત અલૌકિક છે, તેને લૌકિક ન સમજવી. લૌકિક દેખે છે ત્યાં સુધી કુસંગ છે અને સત્સંગનું સુખ તેને આવતું નથી.”","e":null,"s":["15/91/25-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1766,"k":"para","g":"શ્રીહરિએ પત્રમાં એક વાત લખી, “ભગવાનની મૂર્તિમાં હેત લાવીને પરોક્ષપણે ભાવ લાવીને ભજે છે તે અક્ષરધામ સિવાયના અન્ય ધામને પામે છે. અથવા અપાર બ્રહ્માંડની રચનામાં તેને જોડે છે. અવતારોનો પાર નથી. જેટલાં બ્રહ્માંડો છે તેટલા ભગવાનના અવતાર છે. સ્વયં પુરુષોત્તમ ભગવાન પૃથ્વી પર કેવળ જીવોના કલ્યાણને વાસ્તે જ કરુણા કરીને પ્રગટ થાય છે. તે જે જે ચરિત્ર કરે છે તે કલ્યાણરૂપ છે. એમાં સર્વોપરી રસ સમાયેલો છે. એ રસની આગળ અન્ય રસમાત્ર સંસૃતિ(જન્મમરણ)રૂપ છે. સાક્ષાત્કાર પ્રગટ ભગવાનનું ભજન કરે છે તેના પર અમારે હેત રહે છે. એ હેતને અનુરૂપ અમે વાર્તા કરીએ છીએ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1767,"k":"para","g":"“ભગવાનને ક્રિયા કરતા દેખે છે તે સઘળી ક્રિયાને કલ્યાણરૂપ માનીને તેનું ગાન કરે છે. ભગવાનની બધી ક્રિયા ભક્તને અર્થે છે. એમ ચરિત્રને કલ્યાણકારી જાણનારાં નરનારી પણ કર્મદોષથી મુક્ત થઈ નિર્દોષ ને શ્રેષ્ઠ ભક્ત થઈ જાય છે. પછી દેહને અસત્ય ને આત્માને સત્ય જાણી ભગવાનને ઉપાસે છે. દેહ મૂકીને અક્ષરધામમાં ભગવાનનું સુખ લે છે. પરોક્ષભાવે ભગવાનની મૂર્તિમાં અતિ હેતથી વળગ્યો હોય ને પિંડ-બ્રહ્માંડને મિથ્યા જાણી નૈષ્કર્મ્ય રહીને ભગવાનને ભજતો હોય એવો ભક્ત અક્ષરધામ સિવાયના તે ઇચ્છે તે ધામને ભગવાન પમાડે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1768,"k":"para","g":"“પૃથ્વી પર ભગવાનના અવતાર જુદા જુદા રૂપે થયા કરે છે. જીવોના કલ્યાણ માટે વિચરતા ભગવાનને ઓળખીને તેની સાથે પ્રીત કરે છે, ને ભક્તિ કરે છે તેના પર અમને પણ પ્રીત થાય છે. ભગવાનની પ્રત્યેક ક્રિયા કલ્યાણકારી માનનાર ભક્ત શ્રેષ્ઠ છે. સાક્ષાત્કાર પ્રગટ શ્રીહરિને અસંગી, નિર્દોષ, કર્મ કરવા છતાં અકર્તા માનનારો આ ભક્ત દેહને મિથ્યા જાણે છે ને આત્માને એક સત્ય જાણે છે. તે દેહ મૂકે છે ત્યારે અક્ષરધામનો અધિકારી થઈને ભગવાન પુરુષોત્તમનું અખંડ સુખ લે છે.”","e":null,"s":["15/99/28-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1769,"k":"para","g":"શ્રીહરિએ ઉગામેડીના વૈષ્ણવ-પટેલને વાત કરતાં કહ્યું, “મનુષ્યતન મળવું દુર્લભ છે. કોટાનકોટિ કલ્પ વીતે પછી મનુષ્ય તન મળે છે. તે પણ ભરતખંડમાં મળવું દુર્લભ છે. તેમાં પણ ઉત્તમ, સંસ્કારી કુળમાં મળવું કઠણ છે. તેમાં પણ પ્રગટ ભગવાન અથવા ભગવાનના સંતનો યોગ થવો ઘણો દુર્લભ છે.”","e":null,"s":["16/43/10-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1770,"k":"para","g":"જેતલપુરમાં સંત-હરિજનોને રાત્રે જાગ્રત કરી શ્રીહરિ પ્રસન્નતાપૂર્વક વાતો કરવા લાગ્યા, “આજે આ ભગવાન પૃથ્વી પર પ્રગટ થયા છે તે સર્વનું કારણ છે. યત્કિંચિત્ વાત પ્રગટના ધાર્યા પ્રમાણે થાય છે. જગતની ઉત્પત્તિ, સ્થિતિ અને પ્રલય તેમની આજ્ઞામાં રહીને દેવો કરે છે. ભગવાન સંબંધી વાતમાં પ્રગટની વાત સર્વનું કારણ છે. પ્રગટની વાત સર્વએ ધારવી ને વિચારવી. પ્રગટ વિના સઘળું કાષ્ઠના પૂતળા જેવું છે. સર્વે અવતારો, દેવો, દેવીઓ પ્રગટને આધીન છે. પ્રગટ મૂર્તિ વિના તેને પોતાનું કોઈ બળ નથી. આ પ્રકારે પ્રગટને જાણ્યા પછી પણ જે જન પરચા ઇચ્છે છે, તેને પ્રગટના પ્રતાપની લેશ પણ ગમ નથી. પરચા તો અપાર થાય છે પણ અજ્ઞાનીને તે જોવાની દૃષ્ટિ નથી. જે પ્રગટનો પ્રતાપ જાણે છે, તે પરચા ઇચ્છતો નથી. આ બધું જેનું કર્યું થાય છે તેની પાસે બીજા પરચા કયા જોવા! એમ સમજી તેને સંશય થતો નથી. દેશકાળાદિ પ્રવૃત્તિ ક્ષણ ક્ષણ પ્રત્યે થાય છે તે તેમનો પ્રતાપ છે.”","e":null,"s":["17/50/1-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1771,"k":"para","g":"જેતલપુરના મહોલમાં રંગોત્સવ યોજ્યો હતો. શ્રીહરિ હિંડોળે વિરાજ્યા. ત્યાં એકત્ર થયેલા સંતોને શ્રીહરિએ પ્રશ્ન પૂછ્યો કે, “તમે સંતો-હરિભક્તો અમારું ધ્યાન, સ્મરણ પૂજન કરો છો તેણે કરીને મોક્ષ માનો છો તથા અમારાં વચન અને અમારા સંબંધવાળી વસ્તુ પણ મોક્ષકારી માનો છો. તે અમે ના હોઈએ ત્યારે ભક્તો મુક્તમુનિનું ધ્યાન કરે તો મોક્ષ થાય કે ન થાય?”","e":null,"s":["17/82/39-42"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1772,"k":"para","g":"ત્યારે હાથ જોડીને સંત બોલ્યા કે, “અમને એ પ્રશ્નનો ઉત્તર સૂઝતો નથી. અમારી મતિ ટૂંકી છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1773,"k":"para","g":"ત્યારે શ્રીહરિ કહે, “મંડળમાં જે મુખ્ય સંત હોય તે વિચાર કરીને બોલે.” એમ કહીને પછી પોતે જ કહેવા લાગ્યા જે, “મોક્ષદાતા સંત મળે છે ત્યારે તેમની સેવા મન, કર્મ વચને કરે તો વ્યાવહારિક બુદ્ધિને પણ મોક્ષપરક તે બનાવી દે છે. ભગવાનને મળવાનું પ્રથમ દ્વાર સંત છે. સંતના સમાગમ વિના કોઈ ભવપાર થઈ શકતું નથી. તમને બધાયને પણ પહેલા સંત મળ્યા ત્યારે અમારો નિશ્ચય થયો છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1774,"k":"para","g":"“ભગવાનના અવતારો થયા તેણે પોતાના મુખે ‘અમે ભગવાન છીએ’ એવી વાત ક્યારેય નથી કરી. સંતને મુખેથી ભગવાનનો મહિમા વિસ્તરે છે. ભગવાન તેમાં રહીને કાર્ય કરે છે. જીવનાં ચાહે તેટલાં પાપ હોય, પણ તે પલકમાં બાળી દે છે. જેમ મોટો દારૂનો ઢગલો હોય તેમાં તલભાર પ્રગટ અગ્નિનો યોગ થાય તો તરત સળગી ઊઠે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1775,"k":"para","g":"“ભગવાન સદા પ્રગટ રહે છે. ભગવાનનાં નામ, ચરિત્ર પણ ક્યારેય પરોક્ષ થતાં નથી. ભગવાનની મૂર્તિ પ્રગટ રહે તેનાં ચરિત્ર આશ્ચર્યકારી છે. બ્રહ્માદિ દેવોને પણ તેમાં ગમ પડતી નથી, તો બીજા જનની તો વાત જ શી કરવી! ભગવાન તેની બુદ્ધિમાં પ્રેરણા કરે તેટલી તેને ગમ પડે છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1776,"k":"para","g":"એટલી વાત શ્રીહરિએ કહી પછી સંતોને બુદ્ધિ અનુસાર ઉત્તર વિચારવાનું કહ્યું. એટલે સંતો ઊઠીને એકબાજુ બેઠા અને શ્રીહરિના પ્રશ્નનો ઉત્તર વિચારવા લાગ્યા. પછી નિશ્ચય કરીને સભામાં આવ્યા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1777,"k":"para","g":"શ્રીહરિનો કહેવાનો મર્મ કોઈ પૂરો સમજ્યા નહિ. ભણનારા સંતમાં નિત્યાનંદમુનિ યથાર્થ સમજ્યા હતા. ફરતા સંતમાં કૃષ્ણાનંદમુનિ શૂરવીર હતા. તે સૌથી પ્રથમ બોલ્યા, પણ પ્રશ્નનો મર્મ સમજ્યા નહોતા. ફરતા સંતો જે બોલ્યા તે સૌનો વિચાર એક સરખો હતો કે, “તમારા વિના જે બીજાનું ધ્યાન કરે તે વ્યભિચારી ભક્તિ છે. તમારા જેવા જો બીજાને અમે જાણીએ તો જન્મ વ્યર્થ ગયો.” આમ, કોઈને પ્રશ્નનું રહસ્ય હાથ ન લાગ્યું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1778,"k":"para","g":"શ્રીહરિ પ્રશ્ન પૂછે તે કંઈ નિશાન વિના પૂછે નહિ. જેનાથી અપાર જીવના ચોરાશીના ફેરા મટે અને પ્રગટ હરિ હોય ત્યાર પછી પણ એવું ને એવું રહે એટલા માટે શ્રીહરિને જેટલાં બાઈ-ભાઈ કે સંતો મળેલાં તે સિવાયના અર્થાત્ શ્રીહરિનો સાક્ષાત્ સંબંધ જેને નથી થયો, એવાં બાઈ-ભાઈ ને ત્યાગીઓના ઉપર આ પ્રશ્ન હતો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1779,"k":"para","g":"શ્રીહરિની મરજી જાણીને નિત્યાનંદમુનિએ પોતાની સૂઝ પ્રમાણે ઉત્તર કર્યો કે, “મોટા સંતના વચનથી મોક્ષ થાય છે. એ મોટા સંત પણ ભગવાનનાં વચનને મોક્ષરૂપ માની વચનમાં વર્તે છે ને તે વિના હાનિ સમજે છે. વળી, પોતાને પ્રગટ ભગવાન મળ્યા છે તેનું ધ્યાન-સ્મરણ કરે છે. શ્રીહરિના જન્મથી માંડી સ્વધામગમન સુધીનાં ચરિત્રોનું નિશદિન ગાન કરતા રહે છે. એવા સંતને પૃથ્વીના સર્વે મનુષ્યો પામી શકતા નથી. પણ એવા સંત જેને મળે છે ને જેવા તેમને સમજે છે તેવો તેનો મોક્ષ થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1780,"k":"para","g":"“શુકદેવજીના વચનથી પરીક્ષિત તરી ગયા અને નારદના વચનથી પ્રિયવ્રત, પ્રહ્‌લાદ, ધ્રુવ, દક્ષના પુત્રો, ચિત્રકેતુ વગેરે તરી ગયા. નારદજી દાસીપુત્ર હતા, પણ સંતની સેવા અને વચનથી તરી ગયા. એમ સંતથી ઉદ્ધાર થયેલાની વાતો શાસ્ત્રમાં લખેલી છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1781,"k":"para","g":"“ગોપ-ગોપી, ઉદ્ધવ, પાંડવ વગેરે પ્રગટમાં હેત-સંબંધ કરીને તરી ગયાં, પૂતના વગેરે વૈરભાવથી તર્યાં, પણ સંતમાં વૈર ભાવ રાખીને કોઈ તર્યો સાંભળ્યો નથી. સંત ધર્મમાં દૃઢપણે વર્તે છે. શ્રીહરિના દાસના દાસ થઈને વર્તે છે. શ્રેષ્ઠ ગુણોના ભંડાર હોવા છતાં સંતને ગુણનું અભિમાન હોતું નથી. એવા સંતની સેવા જેટલી માહાત્મ્ય અને શ્રદ્ધાપૂર્વક થાય તેટલો તેમાં પ્રગટ મોક્ષ રહ્યો છે, પણ આ વાત તરત સમજ્યામાં આવતી નથી. જ્યાં સુધી સમજાય નહિ, ત્યાં સુધી પ્રાકૃતમતિ ટળે નહિ. પ્રાકૃતમતિથી પ્રાકૃત સુખ મળે તેમાં દુઃખ રહ્યાં છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1782,"k":"para","g":"“ભજનારામાં દોષ હોય પણ જેનો આશ્રય છે એવા સંતમાં તલભાર દોષ ન હોવાથી ભજનારાનો મોક્ષ થાય છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1783,"k":"para","g":"શ્રીહરિ કહે, “પ્રશ્નનો ઉત્તર યથાર્થ થયો.”","e":null,"s":["17/84/1-31"],"sv":["हिंडोरे बैठेउ, श्रीहरि तेहि आइ कर ।\n\n प्रश्न हि पूछत भयेउ, संत सब ताकुं हितकर ॥\n\n संत-हरिजन जेते, ध्यान, स्मरन, पूजन सबहि ॥\n\n हमारो करत तेते, तामें मानत मोक्ष तुम ॥\n\n हमारे बचन हि जेहि, हम संबंधि वस्तु कोउ ।\n\n मोक्षरूप हि तेहि, मानत हो मन, क्रम कर ॥\n\n हम हि न होवे जबहि, मुक्तानंद मुनि के जन ।\n\n ध्यान करे यह तबहि, मोक्ष होय न होय कहो ॥\n\n (૧૭/૮૨/૩૯-૪૨)\n\n संत बोले तेहि वार सब, श्रीहरि से कर जोरि ।\n\n उत्तर सूझत नहि प्रश्न के, हमारी मति हे थोरि ॥\n\n श्रीहरि तब बोलत भये, संत प्रति तेहि वार ।\n\n मंडल में मुखि संत जो, बोले करि के विचार ॥\n\n एसि रीत के जीतने संता । प्रबल महा रहे बुद्धिवंता ॥\n\n एक कोर बैठो तुम जाई । उत्तर विचारो सबहि ताई ॥\n\n आशंका अरु उत्तर तामें । बुद्धि की परीक्षा होत यामें ॥\n\n व्यावहारिक बुद्धि जिहां लगहु । रहत हे जनकी तिहां लगहुं ॥\n\n जन्ममरण रहत तिहां लगहि । दुःख अति पावत इहां लगहि ॥\n\n मोक्षभागि संत मिले जबहु । व्यावहारिक बुद्धि कुं तबहु ॥\n\n मोक्ष परक बुद्धि कर देवे । मन, कर्म, वचन संतकुं सेवे ॥\n\n भगवान ताकुं मिलन के, संत प्रथम हे द्वार ।\n\n संत के समागम बिन हि, कोउ न भये भव पार ॥\n\n तुम हो सबहि तिनकुं जो, पेले मिले जब संत ।\n\n निश्चय जो हमारो तेहि, कराये बुद्धिवंत ॥\n\n भगवान में गुन रहे एसे । अनंत ब्रह्मांड में केसे ॥\n\n पाप होत तेहि देत जारी । पलभर में लगत नहिं वारी ॥\n\n दारू ताके पुंज होय जेता । तिलभर अनल परे जो तेता ॥\n\n जारि देवे एक पलक मांहि । प्रगट अनल के जोग कराहि ॥\n\n हरि हरिनाम चरित्र हि जितने । प्रोक्ष कबु नहि होवत तितने ॥\n\n मूर्ति प्रत्यक्ष प्रोक्ष कबहि । देखे में आत जबहि जबहि ॥\n\n आश्चर्य चरित्र रहे तेहु । ब्रह्मादिक कुं गम परत न तेहु ॥\n\n ओर जनकी रहे कहां बाता । कोइ कुं न आवत देखाता ॥\n\n आप आपकी बात ताकी । कोउ कुं गम न रहे वाकि ॥\n\n भगवान जितने देवे जाहि । तितनि गम कबु परे ताहि ॥\n\n इतनि बात हि जोउ, श्रीहरि कर रहेउ जब ।\n\n संत सब उठे सोउ, बैठे जाई दूर तबहि ॥\n\n हरि के प्रश्न ताके, उत्तर परस्पर करत भये ।\n\n निश्चय करि के वाके, सभा में बैठे आईकर ॥\n\n (૧૭/૮૩/૧-૪૦)\n\n श्रीहरि ताके प्रश्न कुं, भमते जितने संत ।\n\n समजे नहि पुरे मर्म कुं, समझे तिमि उचरंत ॥\n\n पढनेवारे संत में, नित्यानंद मुनि जेह ।\n\n जथार्थ प्रश्न समझे यह, भमते न समझे तेह ॥\n\n रमते साधु जो मांहि, समाधिनिष्ट जो संत जेहि ।\n\n कृष्णानंद रहां हि, कृपानंद हि मुनि रहेउ ॥\n\n कृष्णानंद हि जेहु, शुरवीर बोलत भये ।\n\n सबसे प्रथम तेहु, प्रश्न के मर्म न जाने कछु ॥\n\n प्रश्न कुं आप समझे जिस रीता । उत्तर करत भये तिस रीता ॥\n\n तुम बिन हि ध्यान करे जेहा । व्यभिचारि ताकुं कहत तेहा ॥\n\n ओर जन के नहि काम हमारे । हमारी समझ त्युं कहत प्यारे ॥\n\n तुम सम ओरकुं समझे जबहि । हमारे जन्म व्यर्थ भये तबहि ॥\n\n भमते संत रहाये जितना । एक रीत सब बोलेउ तितना ॥\n\n पढने वारे संत जो तामें । नित्यानंदमुनि मुख्य यामें ॥\n\n प्रश्न श्रीहरि पुछे जो ताके । ज्यार्थ तान हि जानत वाके ॥\n\n प्रश्न के तान जानना जोउ । कठिनतर हि बात रहे सोउ ॥\n\n तान निशान एक हि कहाते । ता बिन प्रश्न निर्जीव देखाते ॥\n\n जिनकरि अपार जन जो केरा । मिट हि जावे चोराशि फेरा ॥\n\n प्रगट हरि रहे जिस रीता । पिछे रहेउ एसे उदीता ॥\n\n हरिकुं मिले जितने जो, बाई भाई संत ।\n\n वर्णि संन्यासि पदाति हि, सनातन मुक्त रहंत ॥\n\n हरि के संबंध भये बिन, बाई भाई जेउ ।\n\n त्यागि संबंध बिन जीतने, तापर प्रश्न हे तेउ ॥\n\n नित्यानंद मुनि जेउ, ताके उत्तर करत भये ।\n\n जेसे सुझेउ तेउ, श्रीहरि सुनि प्रसन्न भयेउ ॥\n\n जेसे प्रश्न रहेउ, तेसे उत्तर करत रहे ।\n\n बडे संत रहे तेउ, ताके बचन सें मोक्ष होत ॥\n\n वडे संत रहायेउ जेते । भगवान के बचन में तेते ॥\n\n वरतत रहत मोक्षरूप मानी । बचन बिन मानत रहे हानी ॥\n\n प्रगट मिले भगवान तिनके । ध्यान स्मरन करत रहे इनके ॥\n\n जन्म से इनके चरित्र जीतने । स्वधाम जावत तिहां लग तितने ॥\n\n निशदीन हि करत रहे गानां । चरित्र तामें अधिक रहे तानां ॥\n\n ऐसे संतकुं मिलत न जेता । भोमि पर जन रहेउ तेता ॥\n\n संतकुं मानत यह जीस रीता । मोक्ष ताके होत तिस रीता ॥\n\n परिक्षित शुकके बचन करिके । चोराशिके दुःख गये तरिके ॥\n\n प्रियवृत प्रल्हाद हि जेहा । उत्तानपाद ध्रुव सम हि तेहा ॥\n\n दक्ष ताके पुत्र हि केता । नारद के बचन कर एता ॥\n\n परम मोक्ष तेहि पावत रहेउ । चित्रकेतु आदिक हितेउ ॥\n\n नारद दासिपुत्र जब भयेउ । संतकि सेवा बचन कर एउ ॥\n\n केतके जन उध्धार करेउ । कहे में सब न आत बनेउ ॥\n\n संत सें उध्धार भये जीतनां । शास्त्र में सब हि लिखेउं तितनां ॥\n\n गोपिगोप श्रीकृष्ण तामें । हितकर मोक्ष भयेउ यामें ॥\n\n उध्धव, पांडव, द्रुपहि ताके । मोक्ष हरिके संबंध भये वाके ॥\n\n पुतना अघासुर, बकासुर, दंतवक्र शिशुपाल ।\n\n सालव्य कंस वैर भाव कर, मोक्ष भये तत्काल ॥\n\n वैर भाव कर संतसुं, एक हि जनके जोउ ।\n\n मोक्ष भयेउ सुने वहि, सेवा सें भये सोउ ॥\n\n संतके धर्म हि जे ते, तामें वरत हि दृढकर ।\n\n हरि के दास जे ते, ताके दास वर्तत रहत ॥\n\n संत हि ताके जोउ, श्रेष्ठ श्रेष्ठ रहे गुन जेहि ।\n\n भंडार रहाये सोउ, गुन के नहि अभिमान कछु ॥\n\n एसे संत की सेवा जितना । माहात्म्य रु श्रद्धा जुत तितना ॥\n\n प्रगट मोक्ष रहाये एहा । समझ में तरत न आवत तेहा ॥\n\n समझ में आये बिन उछाहा । आत न चलत प्राकृत राहा ॥\n\n प्राकृत राह चलत जिहां लगहु । प्राकृत मति रहत तिहां लगहुं ॥\n\n प्राकृत मति से प्राकृत सुखा । पावत रहे ते ता महिं दुःखा ॥\n\n संत में दोष न रहे तिल भारा । जन में दोष रहे अपारा ॥\n\n हरि बोले यह प्रश्न ताके । जथार्थ उत्तर भये अब वाके ॥"],"mt":false,"gl":null,"a":false},{"i":1784,"k":"para","g":"મુક્તમુનિએ શ્રીહરિની સ્મૃતિ કરતા કહ્યું, “શ્રીહરિ જ્યારે જ્યારે સંતોને પાસે તેડાવતા ને સ્નેહપૂર્વક રાખતા, ત્યારે પોતાના પ્રગટ થવાની રીત (હેતુ) વારંવાર કહેતા.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1785,"k":"para","g":"વળી શ્રીહરિ કહેતા કે, “આ સત્સંગમાં જે સંત છે તેમાં જન્મ લઈ અમે સંતનો સંગ ઇચ્છીએ છીએ. અમારી રુચિમાં તો ભગવાનના ધામમાં રહેવું તે કરતાં પણ અમે અહીં સંતનો સમાગમ અધિક માન્યો છે. સંતને અમે સૌથી અધિક એટલા માટે કહીએ છીએ કેમ કે, ભગવાન સંબંધી જે કંઈ વાત કહેવાય છે તે સત્સંગ વિના સમજાતી નથી. માયિક જન કોટિ જન્મે પણ સત્સંગના જોગ વિના ભગવાનનું ધામ પામતા નથી. એ ધામ કરતાં પણ સંતના સમાગમનું માહાત્મ્ય અપાર છે તે અમે જ જાણીએ છીએ. બીજાને તેની લગારેય ગમ પડતી નથી. જેમ જગતના જીવમાં જગતની વાત રહે છે, તેમ ભગવાનની વાત સંતમાં રહી છે. જેમનામાં ભગવાન પ્રગટ વસે છે, એવા સંતને ભગવાનની વાતમાં અધિક રુચિ હોય છે. તે ભગવાનના સંબંધ વિનાની વાતમાં ક્યારેય ચિત્ત પરોવતા નથી. ભગવાનની વાતે કરીને સંતનો મહિમા અપાર રહ્યો છે. જે સંતમાં ભગવાનસંબંધી વાતનું અધિકપણું હોય, તેમાં ભગવાનનો નિવાસ જાણવો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1786,"k":"para","g":"“અમે સંતને અધિક જાણીએ છીએ, બીજાને તો તે પોતાના જેવા જ દેખાય તેને લીધે સંતની મોટપ તેની નજરમાં આવતી નથી. ભેગો રહીને સંતની કરે તોપણ તેની સાધારણ મતિ રહે છે. જેવી મતિ તેવો મોક્ષ થાય એમ સર્વ શાસ્ત્ર કહે છે.” આ પ્રકારની વાત શ્રીહરિ બહુ વખત વારંવાર અપારપણે કરતા. પ્રસન્નતાપૂર્વક જેમ પોતાને વર્તતું તેમ શ્રીહરિ કહેતા. અહીં તો એ વાત દિશમાત્ર લખી છે. બધી વાત કહ્યામાં આવતી નથી. સોનાની ભૂમિ હોય ત્યાં સોનાનું શું આશ્ચર્ય?","e":null,"s":["19/6/29-46"],"sv":["श्रीहरि हरिजन सब जो ताकु । संत की सेवा के अधिक वाकुं ॥\n\n माहात्म्य कहत देखावत भारी । संत की सेवा करत अपारी ॥\n\n स्नेह सहित बहु करी देखाते । जब जब संत कुं पास बोलाते ॥\n\n श्रीहरि कहेउ वेर हि वेरा । जन्म केति रीत कही फेर फेरा ॥\n\n सत्संग में यह संत तामें । जन्म लइ संग इच्छत यामें ॥\n\n भगवान के धाम जो तिनसें । संत के संत के समागम इनसे ॥\n\n अधिक रहेउ अपार हि ताई । रुचि हमारि एसी ही रहाई ॥\n\n भगवान के धाम सम कोउ । और कोउ न रहाये सोउ ॥\n\n मायिक जन रहाये जेते । भगवान के धाम कुं तेते ॥\n\n कोटि जन्म लग पावत नाहीं । सत्संग जोग विन हि ताहि ॥\n\n धाम करते संत के जो, समागम के अपार ।\n\n माहात्म्य हम जानत रहे, ओर हि गम न लगार ॥\n\n भगवान की जेति बात हि, कहावत हि जोउ ।\n\n संत में रहे निवास कर, तिन करी अधिक ही सोउ ॥\n\n जग के जन हि तामें, जग की जौसे बात रहेउ ।\n\n संत हि जेते यामें, हरि की तेसें बात रहे ॥\n\n भगवान प्रगट कर बसत जिनके । भगवान की बात में तिनके ॥\n\n रुचि होवत रहेउ अपारा । ता बिन ओर करत न उच्चारा ॥\n\n भगवान संबंध बिन बात तामें । चित कबहुं न प्रोवत यामें ॥\n\n भगवान की करि के बाता । संत के महिमा अपार रहाता ।\n\n भगवान की बात अधिक जामें । भगवान के निवास हि तामें ॥\n\n अधिक हम जो जानत रहाते । ओर कुं आप सम देखाते ॥\n\n तिन करी संत की मोटप जेती । देखे में लेश न आवत तेती ॥\n\n भेगे रहे सेवा करे तोउ । साधारण मति रहेवे सोउ ॥\n\n जेसी मति मोक्ष रहे तेसे । शास्त्र सब कहत रहे एसे ॥\n\n एसी बात हरि वेर हि वेरा । अपार करत रहे बहु फेरा ॥\n\n प्रसन्नता में वर्तन जिस रीता । तेसि बात हरि तब उचरिता ॥\n\n दिशमात्र यह कहि देखाये । सबहि बात कहे में न आये ॥\n\n कनक की भोमि यहाँ सबहि । कनक के आश्चर्य तिहां न कबहि ॥"],"mt":false,"gl":null,"a":false},{"i":1787,"k":"para","g":"શ્રીહરિએ જેતલપુરના મહોલ પર વાત કરી હતી તે મુક્તમુનિએ સ્મૃતિમાં રાખેલી કહી - પ્રગટ ભગવાન મેળવાવે તે પાકો સત્સંગ છે. પૂર્વે અવતારો ઘણા થયા, પરંતુ એ પરોક્ષના ભજનથી કામ થતું નથી. આ વાત તો જે બુદ્ધિવાળો હોય ને વિચારીને હૃદયમાં તપાસ કરે તો જણાઈ આવે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1788,"k":"verse","g":"‘પ્રગટ મેં તાન મેલાવે તાકો, તબ સત્સંગ સો જાનના પાકો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1789,"k":"verse","g":"પ્રોક્ષ સે કબુ કામ ન હોવે, બુદ્ધિવંત નિજ દિલ મેં જોવે.’","e":null,"s":["19/40(39)/35-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1790,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ વાત કરતાં કહ્યું, “અનેક જીવના કલ્યાણને અર્થે પુરુષોત્તમ ભગવાન પૃથ્વી પર પ્રગટ થાય છે. તેમનો સમાગમ જીવને જ્યારે થાય છે ત્યારે તેને પુરુષોત્તમ ભગવાનનો યથાર્થ મહિમા સમજ્યામાં આવે છે. પછી તે જીવના ઇન્દ્રિયો-અંતઃકરણ પણ પુરુષોત્તમરૂપ થઈ જાય છે.”","e":null,"s":["21/48/53-55"],"sv":["अनेक जीव के कल्यान हित, भोमि पर सब जन कुं ।\n\n प्रत्यक्ष दर्शन देत हें तब, जन संत जो तिनकुं ॥\n\n मिलत समागम करत, पुरुषोत्तम भगवान के ।\n\n महिमा समझत हें अविध, अंतरबुद्धिमान के ॥\n\n इन्द्रियों अंतःकरन, सब हि पुरुषोत्तमरूप हि ।\n\n होई जावत तेहि करीके, महा परम अनूप हि ॥"],"mt":false,"gl":null,"a":false},{"i":1791,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સંતો-ભક્તોને વાત કરી કે, “પોતાના ભક્તજનને અપાર દિવ્ય સુખ આપવું એવો નિરધાર કરીને ભગવાન તેની સેવા પ્રીતિપૂર્વક અંગીકાર કરે છે. એ ભગવાન અહીં પૃથ્વી પર પોતાનું અક્ષરધામ સહિત પધારે છે. અને પૃથ્વી ઉપર વિરાજમાન રહે છે. આવી રીતે સમજીને આ વાત બીજાને પણ કરવી.”","e":null,"s":["21/75/77-80"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1792,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સંતો-ભક્તોની સભામાં એક વાત કરી, “રામ, કૃષ્ણ ઇત્યાદિ પરોક્ષ અવતારોનું માહાત્મ્ય જન જાણે છે અને શુક, સનકાદિક, નારદ, જડભરત, ઉદ્ધવ, હનુમાનજી આદિ પરોક્ષ સાધુનું માહાત્મ્ય જાણે છે એવું માહાત્મ્ય આ પ્રત્યક્ષ ભગવાન(શ્રીહરિ)ના સાધુનું સમજે તેને કલ્યાણના માર્ગમાં બીજું સમજવું બાકી રહેતું નથી. અને એવા માહાત્મ્યના સમજનારાએ સાધનમાત્ર કરી લીધા જાણવાં. આ વાત એકવાર કહ્યે સમજો કે લાખવાર પણ આટલું જ સમજવાનું છે. એ સમજ્યા વગર છૂટકો નથી. શિવ-બ્રહ્મા કે શુક નારદ-સનકાદિકને પૂછો તો તે પણ નિપુણ છે, તે અનેક યુક્તિ લડાવીને પણ પ્રત્યક્ષ ભગવાન અને પ્રત્યક્ષ સંતને જ કલ્યાણના દાતા કહી બતાવે છે. પરોક્ષ ભગવાન ને પરોક્ષ સંત જેવો મહિમા પ્રત્યક્ષ ભગવાન ને પ્રત્યક્ષ ભગવાનના પ્રત્યક્ષ સંતનો કહેતા હોય તેનો નિશ્ચય પણ દૃઢ જાણવો એ ક્યારેય કલ્યાણના માર્ગથી પડે નહિ.”","e":null,"s":["22/100/17-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1793,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સંતો-ભક્તોને વાત કરી કે, “કથા-કીર્તન, ચિંતવન, ધ્યાન, ભજન-સ્મરણ, પૂજન - જે કંઈ કહો તેમાં પ્રગટ ભગવાનનો સંબંધ રહ્યો છે. જે ભક્ત પરોક્ષ માનીને ભજે છે તેને આ પ્રાપ્તિ નથી. પ્રત્યક્ષ ને પરોક્ષભાવ સમજણમાં જણાઈ આવે છે. પ્રત્યક્ષ માને છે તેને વાતોના કરનારા, દર્શન-સુખના દેનારા તેની સામે છે. માટે જે પ્રત્યક્ષને ભજે છે તે સૌથી શ્રેષ્ઠ છે. ને તે પોતે પણ પોતાને ક્યારેય ન્યૂન માનતો નથી.”","e":null,"s":["22/101/32-39"],"sv":["कथा, कीर्तन, चिंतवन, ध्याना । भजन, स्मरन, पूजन रहाना ॥\n\n भगवान संबंधि सेवा बाता । ऐह सबहि संबंध रहाता ॥\n\n प्रगट यह भगवान ताके । ईतना संबंध रहाये वाके ॥\n\n याकुं प्रोक्ष समझत जाहि । प्रोक्ष भक्त यह रहेउ ताहि ॥\n\n प्रत्यक्ष प्रोक्ष भक्त जीनहि । समझ में देखावत ईनहि ॥\n\n प्रत्यक्ष जो भगवान भयेउ । ताकि बात हि जेते रहेउ ॥\n\n यह सब बात प्रत्यक्ष रहाते । याकुं प्रोक्ष करि जे ते कहाते ॥\n\n प्रोक्ष भक्त कहावत तावु । समझ ताकि करिके रहावु ॥\n\n प्रत्यक्ष भगवान कि जेति । बातहि जीतनी कहावत तेति ॥\n\n प्रत्यक्ष समझत जीतनां, भक्त जेते हि जाहि ।\n\n प्रत्यक्ष के भक्त ऐहि, रहायेउ यह ताहि ॥\n\n प्रत्यक्ष कि जेति बात, प्रत्यक्ष मुख्य रहे तिनमें ।\n\n मानत जेहि रहात, भक्त तेहि सब सें अधिक ॥"],"mt":false,"gl":null,"a":false},{"i":1794,"k":"para","g":"કારિયાણીમાં શ્રીહરિ વાત કરવા લાગ્યા, “આ પૃથ્વી પર અમે પ્રગટ હશું ત્યાં સુધી અધર્મનું જોર લેશમાત્ર ચાલશે નહિ. અમારી આગળ અધર્મ થરથર ધ્રૂજે છે. સૂર્ય આગળ અંધારું કેવી રીતે ટકી શકે?”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1795,"k":"para","g":"હીરજીભાઈ કહે, “આપે સાચી વાત કહી. તમે પ્રગટ થયા છો તે દિવસથી શરણે આવેલા અપાર જીવોનો ઉદ્ધાર થયો છે, પણ તમારા પછી એવી પુનિત કલ્યાણની રીત કેવી રીતે ચાલશે તે કહો.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1796,"k":"para","g":"ત્યારે શ્રીહરિ કહે, “તમે જે રીતે વિચાર્યું તેનો વિચાર અમે નિત્ય કરીએ છીએ. આ જ રીતે કલ્યાણનો માર્ગ અમારા પછી પણ ચાલુ રહેશે અને તો જ અમારું આ લોકમાં આવ્યું સાર્થક કહેવાય ને! કલ્યાણની પરંપરા ન રહે તો પ્રગટ થયાનો અર્થ રહે નહિ. કલ્યાણનો આવો જ પ્રવાહ ચાલશે. એમાં તલભાર પણ મિથ્યા જાણશો નહિ. કલ્યાણના પ્રવાહ માટે નિયમની એક સડક અમે બનાવી છે. બધાં શાસ્ત્રોમાંથી સારરૂપ મોક્ષપરાયણ વચન શોધીને તે સડકમાં જડી દીધાં છે, અને તેમાં વિઘ્નરૂપ અધર્મી ગુરુ (અસત્પુરુષ)ની ઓળખાણ કરાવીને કુમાર્ગ પણ દેખાડી દીધા છે. અને સત્પુરુષના સંગરૂપી અનુપમ મોક્ષમાર્ગ બતાવ્યો છે, તેથી બ્રહ્માંડ રહે ત્યાં સુધી કલ્યાણનો પ્રવાહ ચાલશે. અમારાં વચન તે અમે છીએ. હરિજન થઈને સત્સંગની રીત બહાર ચાલશે તેનો ઉદ્ધાર થશે નહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1797,"k":"para","g":"“ભગવાન અને ભગવાનના સંતો-ભક્તોને જે દિવ્ય જાણશે અને તેની સેવામાં ક્યારેય મન ચોરશે નહિ ને પોતાનો દોષ જોતો રહેશે તેનો ઉદ્ધાર થશે, પરંતુ પોતાને અધિક માનશે અને બીજાને તુચ્છ સમજશે ને તે જ્ઞાની, ત્યાગી ને ધ્યાની હશે તોપણ તેના કલ્યાણમાં ફેર છે. સંત-હરિભક્તના ચરણની રજ પોતાને સમજે ને નિષ્કપટ વર્તે તેનો નિશ્ચય મોક્ષ થાય છે.”","e":null,"s":["23/58/14-35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1798,"k":"para","g":"લોયામાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “જેને સાચો સત્સંગ મળે છે તે પૂર્ણમાસીના ચંદ્રની પેઠે સતત વૃદ્ધિ પામ્યા કરે છે. જ્યાં ભગવાન અને ભગવાનનું ધામ રહ્યું છે, ને ભગવાનના ભક્તોનો મહિમા પણ અપાર છે એવા સત્સંગની તોલે અનંતકોટિ બ્રહ્માંડ આવતાં નથી, કેમ કે એ અનંતકોટિ બ્રહ્માંડનું સુખ આ સત્સંગના સુખ આગળ લૂખું છે. નારદ, શુક, સનકાદિક, ઉદ્ધવ, હનુમાનજી જેવા ભક્તો આ પ્રગટ ભગવાનના સુખ પાસે અનંતકોટિ બ્રહ્માંડનાં સુખને મળ તુલ્ય સમજે છે.”","e":null,"s":["24/50/32-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1799,"k":"para","g":"અંકલેશ્વરમાં શ્રીહરિએ કહેલી વાત મુક્તમુનિએ ઉત્તમ નૃપને કહેતાં કહ્યું, “અજામિલને અજાણતાં પણ સાચા સંતનો સંગ થયો ને તેની સેવા કરી તો એના જીવનો ઉદ્ધાર થયો છે. પિંગલા જેવી વેશ્યા પણ દત્તાત્રેયનો યોગ થવાથી તરી ગઈ. યવન, ગીધ, કંક, વાનર જાતિ કે શ્વપચ પણ પ્રગટ ભગવાન કે તેમના સત્પુરુષના યોગે ભવપાર થયા છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1800,"k":"para","g":"“ભગવાન કે સત્પુરુષના યોગ વિના ચહાય તેટલા ગ્રંથ ભણે કે વેદ ભણે તો પણ તે શબ તુલ્ય છે. કાષ્ઠ અને પથ્થરમાં અગ્નિ રહ્યો છે એ વાત સાચી, પણ પ્રગટ અગ્નિ વિના કાર્ય સરતું નથી. તેમ પ્રગટ ભગવાન કે પ્રગટ સત્પુરુષ વિના જીવોનો મોક્ષ ક્યારેય થતો નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1801,"k":"para","g":"“સત્ય માર્ગ પર ચાલવે કરીને સત્પુરુષ ઓળખાય છે. સૂર્ય ઊગે તેનો પ્રકાશ ચારે દિશામાં પ્રસરે પણ ઘુવડ તેને જીવનભર દેખી શકતા નથી. સૂર્યના પ્રતાપની તેને પરખ જ નથી, તેમ શ્રીહરિનો પ્રતાપ પ્રગટ છે. તેને જેમ છે તેમ જે નથી જાણતા તે બુદ્ધિમાન હોવા છતાં બુદ્ધિ વિનામાં ખપે છે.”","e":null,"s":["27/31/14-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1802,"k":"para","g":"મુક્તમુનિએ ઉત્તમ નૃપને શ્રીહરિની પ્રસાદી તુલ્ય વાર્તા કહેતાં કહ્યું, “સત્યવાતનું આચરણ જ્યાં થતું હોય ને જીવનું અજ્ઞાન ટાળે ત્યાં ધર્મવંશ જાણવો. જેનામાં ધર્મવંશ છે તેનામાં ભગવાનનું પ્રગટપણું માનવું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1803,"k":"verse","g":"‘અજ્ઞાન ટારત જેતી બાતા, ધર્મવંશ હિ તેતિ રહતા,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1804,"k":"verse","g":"ધર્મવંશ કી બાત રહે જામેં, પ્રગટ ભગવાન રહત તામે.’","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1805,"k":"para","g":"“અધર્માચરણ થતું હોય ત્યાં ભગવાન ક્યારેય રહેતા નથી, એવાં તીર્થ કે ધામ પણ ભગવાન વિનાનાં જાણવાં. પૂર્વે કહેલો ધર્મવંશ જેને રુચે તેને આ વાત દેખ્યામાં આવે છે. ભગવાનના નિવાસ વિના સત્ય વાત પણ રુચતી નથી ને એટલે જ જીવને દુઃખ મટતું નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1806,"k":"verse","g":"‘એસે શ્રીહરિ બાત બહુ, કરતા રહે હિત લાય,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1807,"k":"verse","g":"હરિજન પર રહે હિત બહુ, મુખ કહે ન આય.’","e":null,"s":["28/10/21-37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1808,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1809,"k":"para","g":"જ્યાં ભાગવત ધર્મ, એકાંતિક ધર્મ છે, ત્યાં ભગવાન પ્રત્યક્ષપણે રહે છે. પ્રત્યક્ષ હરિના ભજન વિના, ભક્ત થયો હોય તોપણ તેનો મોક્ષ થતો નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1810,"k":"para","g":"ભગવાન જ્યારે પરોક્ષ હોય છે, ત્યારે તેમને માનવાવાળા ભક્તો પણ અપાર હોય છે, પરંતુ પ્રત્યક્ષને જ્યારે તે નિશ્ચય કરી માને છે, ત્યારે અક્ષરધામમાં જાય છે. પ્રગટ માન્યા વિના અક્ષરધામની પ્રાપ્તિ થતી નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1811,"k":"verse","g":"‘પરોક્ષ હરિ હોત જબ, અનંત હિ ભક્ત હોત તબે,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1812,"k":"verse","g":"પ્રત્યક્ષ હિ માને તબ, અક્ષરધામ મેં જાત તેહિ.’","e":null,"s":["4/31/38-39"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1813,"k":"para","g":"મનુષ્ય માત્ર પરોક્ષને આધીન રહે છે. પ્રગટની વાત કઠણ પડે છે. સૂઝે તેવો જ્ઞાની હોય તોપણ પ્રગટની વાત આવે ત્યાં અટકી પડે છે.","e":null,"s":["6/5/29-30"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1814,"k":"para","g":"રામાનંદ સ્વામીએ શ્રીહરિને કહ્યું, “સદ્‌ધર્મ અને સદ્‌ભક્તિ તમારાં માતાપિતા છે. તથા સત્ જ્ઞાન અને સત્ વૈરાગ્ય તમારા બંધુ છે. આ ચારે ઉપરાંત ભગવાનના સ્વરૂપ સંબંધી જ્ઞાન વિના ફક્ત ધર્મનો વંશ હોય, તો એકવાર અન્ન આપવા યોગ્ય છે પણ માનવા યોગ્ય નથી. કારણ કે, વંધ્યા ગાયથી વિસ્તાર થાય નહિ.”","e":null,"s":["6/52/1-19"],"sv":["सत धर्म के पुत्र तुम, भक्ति सत मात हि तोर ।\n\n ज्ञान वैराग्य सत बंधु तव, देखे में आये मोर ॥\n\n हरि को ज्ञान बिन धर्मवंशि भारि । एक वेर अन्न देवे को अधिकारि ॥\n\n मानने को नहि तेहि अधिकारा । वर्ल गाउ सें कहा होय विस्तारा ॥"],"mt":false,"gl":null,"a":true},{"i":1815,"k":"para","g":"તપ, વ્રત, તીર્થ એ બધાનું પ્રયોજન પ્રગટ ભગવાન મળી આવે એ છે. જ્યાં સુધી પ્રગટ ન મળે, ત્યાં સુધી એ કર્યા કરવું, પરંતુ જ્યારે ભગવાન પ્રગટ મળે છે ત્યારે તે કહે તેમ કરવું તેમાં બધાં સાધન આવી ગયાં. પ્રગટ મૂર્તિ મળે ને જો એના વચન મુજબ ન વર્તે તો તેને પ્રગટ મળ્યાનું કોઈ ફળ નથી.","e":null,"s":["7/38/29-31"],"sv":["तप व्रत तीर्थ विविध नाना । यह मूर्ति हित करत रहाना ॥\n\n तप व्रत तीर्थ को फल इता । प्रगट मूर्ति कबहु मिलिता ॥\n\n तप व्रत तीर्थ करे बिन कबहु । मूर्ति मिलत नहि सबहु ॥\n\n प्रगट मिले जब मूर्ति आई । मूर्ति कहे त्युं करना ताई ॥\n\n मूर्ति को कह्यो न करे जेहा । मूर्ति मिले की फल नहिं तेहा ॥"],"mt":false,"gl":null,"a":true},{"i":1816,"k":"para","g":"મોક્ષભાગી જનો અસત્ તત્ત્વોને કુસંગ જાણી તેનો સંગ કરતા નથી. દેહ-ગેહાદિક સાંસારિક પદાર્થ, દેહસંબંધી માત-તાત, કુટુંબ-પરિવાર તેમજ સત્સંગ કરવામાં વિઘ્નકર્તા પિંડ-બ્રહ્માંડ બધું ભગવાનના ધામ આગળ અસત્ છે. સારમાં સાર સર્વોપરી શ્રીહરિ છે. ઇન્દ્રિયો-અંતઃકરણ તેને પિછાણી ન શકે તો તે અસત્ છે. મોક્ષપરક ગ્રંથો પણ પિંડ-બ્રહ્માંડને અસત્ જાણી, મન-ઇન્દ્રિયોના સંગને કુસંગ જાણી તેનાથી છેટે રહે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1817,"k":"para","g":"સાચા સંત મળતાં આ વાત સમજ્યામાં આવે છે. આત્મા-પરમાત્માનું જ્ઞાન સાચા સંત દૃઢ કરાવે છે. ભગવાનના સંબંધવાળા ભક્તો, સંતો, વર્ણીઓ સર્વે સત્ છે. સત્ ધર્મ, સત્ જ્ઞાન, સત્ ભક્તિ ને સત્ વૈરાગ્ય જેમનામાં સદા વર્તતાં હોય તો જાણવું કે શ્રીહરિ ત્યાં પ્રગટ છે. એવા સંત ભગવાનનું ધામ કહેવાય છે. જેમાં શ્રીહરિ નિવાસ કરીને સદા રહે છે.","e":null,"s":["13/41/16-21"],"sv":["असत नाम रहाये जितना । कुसंग मोक्षभागी कहत तितना ॥\n\n असत नाशवंत जेहि जेता । देह गेहादिक पदार्थ तेता ॥\n\n देह के संबंधि जो जो कहावे । मात-तात हि कुटुंब रहावे ॥\n\n सत्संग करत विघ्न करे जेते । पिंड ब्रह्मांडादिक तेते ॥\n\n हरिजन एसो विचार, सार में सार हरि सर्वोपरि ।\n\n सतसंग सत नरनारि, करत भये कुसंग तज ॥\n\n माया के संबंधि रहे ज्यां लगहि । इन्द्रि अंतःकरण जो त्यां लगहि ॥\n\n मोक्ष पर ग्रंथ में वचन जितना । असत कुसंग कहत तितना ॥\n\n आत्मा परमात्मा हरिजन जितने । साचे संत सत वरणि तितने ॥\n\n हरि के धाम जेते कहावा । निवास करि हरि जामें रहावा ॥\n\n सत धर्म, सत भक्ति जो जेहा । सत वैराग्य सत ज्ञान तेहा ॥\n\n जिहां लग वरतंत जेहि ठोरा । तिहां लग हरि रहत तेहि कोरा ॥"],"mt":false,"gl":null,"a":true},{"i":1818,"k":"para","g":"જીવને મોક્ષનું કામ પ્રગટ ભગવાન મળે ત્યારે જ સરે છે. પ્રત્યક્ષ શ્રીહરિથી જેવો મોક્ષ થાય છે, તેવો બીજા કોઈથી થતો નથી. પ્રગટ ભગવાન વિના જો બીજાથી મોક્ષ થતો હોત તો કોઈ પ્રગટને ભજેત જ નહિ. શ્રીહરિ સ્વયં મનુષ્યદેહે પ્રગટ હોય અથવા શ્રીહરિ જ કોઈને મોક્ષ કરવાની સામર્થિ આપે તેનાથી જીવનો મોક્ષ થાય છે. શ્રીહરિના વચનથી એવા જન (શ્રીહરિના ભાવને પામેલા એકાંતિક સાધુ) કોટિ જીવોનો મોક્ષ કરે છે. શ્રીહરિના વચનનું આ સામર્થ્ય છે. જેનો વિચાર્યા વગર ખ્યાલ આવતો નથી. વિચાર ન કરે તે કલ્પો સુધી દુઃખી રહે.","e":null,"s":["15/9/5-8"],"sv":["मोक्ष को काम जितनी जोउ । प्रत्यक्ष हरि से होवत सोउ ॥\n\n प्रत्यक्ष हरि से मोक्ष होत जेसा । और कोई से न होत तेसा ॥\n\n और से होवे मोक्ष हि जबहु । हरिकुं भजे नहि कोउ तबहु ॥\n\n मोक्ष करन को काम जेहु । हरि आपमें रखे हें तेहु ॥\n\n मोक्ष करन को वचन जेहि । जो जनकुं हरि देवत तेहि ॥\n\n हरि के बचन से जन जेहा । कोटि जन के मोक्ष करे तेहा ॥\n\n हरि के वचन में साम्रथ भारी । देखे आवत जोत विचारी ॥"],"mt":false,"gl":null,"a":true},{"i":1819,"k":"para","g":"જ્યાં વિષય, ફેલ કે વ્યસનસંબંધી કોઈ વાત ન હોય. ધર્મ, જ્ઞાન, વૈરાગ્ય, ભક્તિ સહિત ભગવાન શ્રીહરિની વાતો, કથા ને કીર્તન હોય, ગ્રામ્યવાર્તાનો ઉચ્છેદ થઈ ગયો હોય, ત્યાં પ્રગટ મોક્ષ રહ્યો છે તેમ જાણવું.","e":null,"s":["18/44/16-18"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1820,"k":"para","g":"પ્રગટ ભગવાનના સંબંધ વિના ગમે તેટલાં જપ-તપ કરે, પણ બ્રહ્માંડની બહાર ગતિ નથી.","e":null,"s":["18/71/26"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1821,"k":"para","g":"જ્યાં વર્તન છે ત્યાં જ પ્રગટ મોક્ષ છે ને પ્રગટ શ્રીહરિ પણ એ સ્થાને જ વસે છે. શ્રીહરિની જે કંઈ વાત છે તે પણ વર્તનમાં જણાઈ આવે છે. આવું વર્તન જ્યાં દેખાય ત્યાં મોક્ષ માનવો. કારણ, શ્રીહરિ જ્યાં પ્રગટ હોય ત્યાં જ આવું શક્ય બને. પ્રગટની આવી સમજ નથી ત્યાં સુધી એટલી કસર હરિજનને રહે છે.","e":null,"s":["26/8/25-31"],"sv":["एसी रीत के जोउ, निशदिन हि वर्तन जिहां ।\n\n प्रगट मोक्ष जो सोउ, प्रगट हरि यह ठोर रहत ॥\n\n वर्तन में देखात, हरि की बात हरि रहत तिहां ।\n\n हरि जिहां रहात, मोक्ष के रहे निवास इहां ॥\n\n समझ में तिहां लगहि ताकुं । कसर रहाये तितनी वाकुं ॥"],"mt":false,"gl":null,"a":true},{"i":1822,"k":"para","g":"જ્યાં પંચવિષયનું ખંડન હોય, ઇન્દ્રિયોનો નિગ્રહ હોય, ત્યાં ભગવાન પ્રગટ હોય છે. શુભ વર્તન ઉપરથી પ્રગટ ભગવાન ઓળખાય છે. નારી-ધનને જે બંધનરૂપ માને તેને પ્રગટ ભગવાન મળે છે. પ્રગટને મળેલ સંતથી પ્રગટ ભગવાનનું જ્ઞાન થાય છે.","e":null,"s":["27/22/14-17"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1823,"k":"para","g":"સત્શાસ્ત્ર મુજબ ચાલતા હોય ને અસત્શાસ્ત્રનો ત્યાગ કર્યો હોય, તેણે કરીને તેને સત્પુરુષ કહેવાય છે. અહીંનું સુખ ચ્હાય તેટલું મળે, પણ તેને અસત્ય ને તુચ્છ કરી વર્તતા હોય. દેહ ને દેહના સંબંધીમાં હેત-મમત્વ ન હોય, એક ભગવાનને જ સત્ય માનતા હોય એવા સત્પુરુષ પ્રગટ ભગવાન છે.","e":null,"s":["27/22/32, 39-40"],"sv":["सत्पुरुष होवत रहे जेते । सत्शास्त्र पर चलत हें तेते ॥\n\n तिन करी सत्पुरुष हि कहाते । असत् शास्त्र के त्याग कराते ॥\n\n इहां के सुख हि जेही, चाय तेसे मिलेउ तेहि ।\n\n असत् रहाये तेहि, देह देह के संबंध सब ॥\n\n ऐसे देखात जेहु, भगवान सत्य जनात रहे ।\n\n सत्पुरुष रहे तेहु, प्रगट भगवान कर तेहि ॥"],"mt":false,"gl":null,"a":true}]},{"n":22,"gu":"ઉપાસના-નિશ્ચય-આશરો","en":"Upāsanā, Nishchay, Āsharo — Worship, Conviction, Refuge","url":"https://www.anirdesh.com/pbp/index.php?page=chp_22","b":[{"i":1824,"k":"para","g":"ઈંગોરાળા ગામે શ્રીહરિ કહે, “જેટલા મનુષ્ય સત્સંગમાં આવે છે, તે જો ધર્મ પ્રમાણે વર્તે ને ભગવાનનો દૃઢ નિશ્ચય થાય તો તે અક્ષરધામમાં પહોંચે છે, પરંતુ સત્સંગમાં રહીને જે અન્ય દેવોની આરાધના-ઉપાસના કરે તો તે અક્ષરધામમાં જઈ શકતો નથી. અન્ય દેવોની આરાધના કરનાર ભક્તને સકામ જાણવો. તે દેહ મૂકે છે ત્યારે ભગવાન કે ભગવાનના સંત-હરિજન તેને કોઈ દિવસ તેડવા આવતા નથી. વળી, અંતરમાં તપાસીને જુઓ તો જણાશે કે ઉપાસનારહિત સત્સંગીના દેહને કષ્ટ ખૂબ પડતું હશે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1825,"k":"para","g":"દેહના કષ્ટને ટાળવા અન્ય દેવની ઉપાસના કરે, પણ અંતે તે એકવાર પડી જવાનું છે. કોઈ અમર રહ્યો નથી. જે’દી તે’દી મરવું છે તો તેને કાજે જતન શીદ કરવું? સત્સંગમાં અનંત જાતિના જીવ આવે છે. તેમાં કેટલાક ધીરજવાન છે ને કેટલાક ધૈર્યરહિત છે. જેને ધીરજ નથી તે એક ગણપતિ અને હનુમંતને માને છે. આ બન્ને દેવો હરિભક્ત છે. તેના જેવા બીજા કોઈ દેવ નથી. પાર્વતી-મહાદેવ અને બીજાં બધાં તેમાં આવી ગયાં.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1826,"k":"para","g":"વળી, આવા ધીરજરહિત સત્સંગીએ પણ એ દેવોની માનતા કરતાં પૂર્વે અમારી આજ્ઞા લેવી. અમને પૂછીને પૂજે તે હરિભક્ત અમને વળગ્યો રહે છે. જે મનમુખી છે તેને અમારો સત્સંગી જાણવો નહિ. અમારી આજ્ઞામાં રહે તે અમારો સત્સંગી છે. ત્યાગી પણ જો મનમુખી વર્તે (ઉપાસના બાબતે) પછી સૂઝે તેટલો ધર્મ પાળે, ખાન-પાન ત્યાગે, લોકો તેને મહાવૈરાગી જાણે, શરીર પર ફાટ્યાં-તૂટ્યાં વસ્ત્રો પહેરે, વળી, મુખે મારા નામનું ઉચ્ચારણ કરે, મારો મહિમા અપરંપાર કહે, અરે, ક્યારેક તો મને સંભારીને રુદન કરે, સત્સંગનો સાધુનો અપાર મહિમા ગાય, શરીર સૂકવી નાખે, પલક માર્યા વિના અહોનિશ ધ્યાન કરે, પરંતુ સંતથી વિરુદ્ધ વર્તન હોય તો અંત સમે અમે તેને તેડવા આવતા નથી. તેને દેખીને ભૂલા ન પડવું.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1827,"k":"verse","g":"‘મનમુખી જાન માનહિ દેહા, સત્સંગી ન સમઝના એહા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1828,"k":"verse","g":"નિજ તનકું નાખે સુકાઈ, ભુલના નહિં દેખિકે તાઈ.’","e":null,"s":["4/19(18)/33-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1829,"k":"para","g":"કારિયાણીમાં ખટ્વાંગ રાજાને ત્યાં શ્રીહરિએ ભગવાનના સ્વરૂપની વાત કરતાં કહ્યું કે, “સદા દિવ્ય સાકાર એવું ભગવાનનું સ્વરૂપ છે. તેને જે નિરાકાર માને છે તે મહાપાપી છે. અમારા આશ્રિત સત્સંગીએ ક્યારેય ભૂલમાં પણ નિરાકારના માર્ગે ચાલવું નહિ. નિરાકારનો મત ઊંડો અંધારિયો કૂવો છે. તેમાં પડનાર કદી બહાર નીકળી શકતો નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1830,"k":"para","g":"“નિરાકારના મતે વિધિનિષેધ રહેતા નથી, તેથી ધર્મનો નાશ થાય છે. જ્યાં ધર્મ નથી, ત્યાં ભક્તિ પણ નથી. અંતે એવા મતને અનુસરનારનો જમપુરીમાં વાસ થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1831,"k":"para","g":"“નિરાકાર મતવાદીઓ જમપુરીને મિથ્યા કહે છે, ચોરાશી લાખ યોનિને ભ્રાન્તિ ગણે છે. આ ભ્રાન્તિ તેને કદી મટવાની નહિ. વ્યાસજી સર્વજ્ઞ હતા. ભગવાનનો અવતાર હતા. તેમણે જે વાત લખી છે તેને પ્રમાણ માની આપણે તેને અનુસરવું. ભાગવતમાં નારાયણને જ એક ધ્યેય કહ્યા છે. સર્વોપરિ ભક્ત તેને જ કહ્યો છે જે પ્રગટ ભગવાનને વિષે દૃઢ નિષ્ઠાવાન હોય. પ્રગટ સ્વરૂપને ત્યજી જે અન્યને ભજે છે તે કુમતિ છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1832,"k":"verse","g":"‘તેહિ ભક્ત સર્વોપરિ પ્રગટ સ્વરૂપ મેં ભાવ;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1833,"k":"verse","g":"પ્રગટ સ્વરૂપ કું તજ કે ભજે સો કુમતિ કહાવ.’","e":null,"s":["4/28(27)/40-49"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1834,"k":"para","g":"કારિયાણીમાં શ્રીહરિ કહે, “સંત મળે છે ત્યારે ભગવાનના સ્વરૂપનું જ્ઞાન થાય છે જેને ભગવાનનું સ્વરૂપ ઓળખાયું તેનો વિચાર અતિ બળવાન હોય. જેમ પારસમણિ પ્રાપ્ત થઈ તે છાની રહેતી નથી, તેમ જેને ભગવાનનું જ્ઞાન થયું તેની રીત-ભાત બદલાઈ જાય છે. જ્ઞાનમાર્ગની અને સંસારની બંને રીત જુદી છે.”","e":null,"s":["5/71/16-19"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1835,"k":"para","g":"ગઢપુરમાં જીવેન્દ્ર નૃપના દરબારમાં શ્રીહરિએ વાત કરતાં કહ્યું, “જેના હૃદયમાં ભગવાનની ઉપાસના હોય તે સેવક થઈને વર્તે. ભગવાનના જે દાસ તેનો પણ દાસ થઈને વર્તે. ભગવાન સિવાય તેને બીજી કોઈ આશા જ ન હોય. ભગવાન પણ આવા ઉપાસકને દુર્લભ માને છે અને તેનાથી પળમાત્ર દૂર રહેતા નથી. એવી ઉપાસનાવાળાની સમજણ ઊંચી હોય છે. તેને આ જગતના લોકો માને કે ન માને પણ પોતે સૌ સાથે સામે ચાલીને નેહ બાંધે છે. જગતના બધા જીવોનો ઉદ્ધાર કરવા તેમણે ધાર્યું છે અને એટલે જ કોઈ અપમાન કરે તેનાથી હારતા નથી. પાછો પગ ભરતા નથી.”","e":null,"s":["6/99/9-16"],"sv":["हरि की रखे उपासना जेहा । सेवक होई के वर्ते तेहा ॥\n\n हरि के दास ताके रहे दासा । हरि विन ओर नहिं जेहि आसा ॥\n\n हरि मानत अति दुर्लभ ताकुं । पल एक दूर रहत न वाकुं ॥\n\n जन मानो न मानो केहा । तजत न तोऊ जन से नेहा ॥\n\n उद्धार करन सब जग को धारे । अपमान करे तिनसे न हारे ॥"],"mt":false,"gl":null,"a":false},{"i":1836,"k":"para","g":"લોયા નાગડકામાં શ્રીહરિ કાઠી ભક્તોને કહે, “અમે પૃથ્વી પર જે દિવસથી પ્રગટ થયા છીએ તે દિવસથી નિત્યે જીવોનાં કોટિ કોટિ કર્મબંધન છોડાવીએ છીએ. અમારા સ્વરૂપનો જેવો છે તેવો પ્રતાપ નિષ્પાપ એવા એક અક્ષર જાણે છે. કોઈ અમારો પ્રતાપ પોતાની બુદ્ધિ પહોંચે તેટલો કહે, તેનાથી અપાર પ્રતાપ જાણે તેને ભવબ્રહ્મા આદિ દેવતા વખાણે છે. અમારો પ્રતાપ સાંભળી સંશય ન કરે, તે જન માયાને તરી ગયો જાણવો. જે સંશય કરે છે તે મોહમાયામાં લપટાયેલો રહે છે.”","e":null,"s":["11/73/9-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1837,"k":"para","g":"કુંડળમાં શ્રીહરિએ કાઠી હરિભક્તોને કહ્યું, “તમે અમારો અડગ નિશ્ચય કર્યો છે તોપણ આ લોકની રીત છે કે પળમાં મતિ વિપરીત થઈ જાય. તમારો નિશ્ચય અમે જ રખાવીએ છીએ, અને એ નિશ્રય રહે તેવો રાતદિવસ વિચાર રાખીએ છીએ તેની તમને ખબર નથી. નિશ્ચયની વાત બહુ કઠણ છે.”","e":null,"s":["11/71(61)/32-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1838,"k":"para","g":"બોટાદમાં માતરા ધાધલના ભુવનમાં શ્રીહરિએ વાત કરતાં કહ્યું, “અમે અક્ષરધામમાં અખંડ રહ્યા થકો આ ભૂમિમાં દેખાઈએ છીએ. અમારી કળાને જે જાણે છે તેને આ વાત સમજાય છે. સમજણની દશ જ્યાં સુધી આવતી નથી ત્યાં સુધી અમારી વિદ્યા દુર્ઘટ રહે છે. લૌકિક વિદ્યાઓ અપાર છે, એ બધી શીખવી સુલભ છે, પરંતુ અમારી વિદ્યા અલૌકિક છે, જે કોઈથી શીખી શકાતી નથી. દંભી, નાસ્તિક, અધર્મી, કપટી, કુટિલ અને ખોટાબોલાઓમાં તો અતિ શુદ્ધ આ બ્રહ્મવિદ્યા ક્યારેય લેશ પણ આવતી નથી.”","e":null,"s":["12/46/34-38"],"sv":["श्रीहरि कहे हमारो जबहि । अवकाश महिं हो परत तबहि ॥\n\n अखंड रहे थके अक्षरधामा । देखाई आत यह भोमि ठामा ॥\n\n हमारि कलाकुं जाने जाहि । समझना कठिन नहि ताहि ॥\n\n समझकि दश न ज्यां लग आवे । दुर्घट त्यां लग तेहि रहावे ॥\n\n अनंत विद्या लौकिक जोउ । सिखने सब सुलभ हें सोउ ॥\n\n हमारि विद्या अलौकिक जेहु । सिखने में दुर्लभ हें तेहु ॥\n\n कपटि कुटिल, कुकर्मि, मिथ्या बोलन हार ।\n\n ब्रह्म विद्या अति शुद्ध हि, ताकुं न आवे लगार ॥"],"mt":false,"gl":null,"a":false},{"i":1839,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ વણિક પ્રત્યે વાત કરતાં કહ્યું, “ભગવાનના શરણ વિના જે કાંઈ તપ કરે છે તે બંધન કરનારું છે. ભગવાનની પ્રસન્નતા માટે કરેલું તપ જન્મ-મરણથી મુક્ત કરે છે. નાક-કાન કાપીને સોના-મોતીથી તન શોભાડવું દૂષણરૂપ છે તેમ ભગવાનના શરણ વિનાનું તપ પણ દૂષણરૂપ થાય છે.”","e":null,"s":["13/45/29-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1840,"k":"para","g":"ગઢપુરમાં શ્રીહરિ મુક્તમુનિને વાત કરવા લાગ્યા, “ઉપાસક કોને કહેવાય? તો જે ગુરુના વચન મુજબ ઉપાસના કરે, પૂર્વે અવતારોએ પણ ગુરુ તો કર્યા છે, તેમ ગુરુને ઓળખે, લક્ષણો જાણે, પછી આશ્રય કરે. માયાના ગુલામ હોય ને પોતે બ્રહ્મ માની વિધિનિષેધનો ત્યાગ કરીને ચ્હાય તેમ વર્તતા હોય તેવા પાખંડી ગુરુનો ત્યાગ કરે. ભગવાનના અવતારોની આઠે પ્રકારની પ્રતિમામાં પૂજ્યભાવ રાખે. ભગવાનના વચન મુજબ સેવા કરવા યોગ્ય પંચદેવ વિષ્ણુ, ગણપતિ, શિવ, પાર્વતી ને સૂર્યને માને. પાપ કરવામાં ડરે. મન, કર્મ, વચને કોઈ પ્રકારે પ્રાણીનો ઘાત ન કરે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1841,"k":"para","g":"“પોતાના જીવાત્માને બ્રહ્મરૂપ માનીને ભગવાનની સેવા (ઉપાસના) કરે તે સાચા બ્રહ્મ છે. તે સિવાય બધા પાખંડી જાણવા. સાચા બ્રહ્મ હોય તે અસત્ય વાતમાં પગલું ભરતા નથી. પરબ્રહ્મને ભજે તે સાચા બ્રહ્મ છે. પરબ્રહ્મના જેટલા ઉપાસક ભક્તો છે તે સૌને બ્રહ્મરૂપ માને. પોતાના ગુરુ જે કંઈ ધર્મનાં વચન કહે તેને શિર ચઢાવી માને. સંતની રીતે ચાલે પણ વચનથી ક્યારેય બહાર પગ ન ભરે. જે ભગવાનનાં વચનમાં વર્તે છે તેને માયા પણ વિઘ્ન કરી શકતી નથી. કારણ કે માયા ભગવાનને આધીન છે. ગૃહસ્થો ગૃહસ્થની રીતે ને સાધુ સાધુની રીતે ચાલે. પોતપોતાના ધર્મમાં સૌ રહે. વચનથી ન્યૂન વર્તે કે અધિક વર્તે તો માયા વિઘ્ન કરે છે. મનના મતે ચાલે તેને માયા ગળી જાય છે. તે સત્સંગી હોવા છતાં અભાવ લઈને પાછો પડી જાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1842,"k":"para","g":"“સંત કે હરિજનનો અભાવ લેતો હોય તે પાછો પડી જાય છે. સત્સંગમાં તેનો પગ ટકતો નથી, અંતે વિમુખ થઈ લખચોરાશી ભટકે છે. આ વાત અમે ફરી ફરીને કહીએ છીએ તેને દૃઢપણે સમજી હૃદયમાં રાખવી. ખપ હોય તેને આ સમજાશે. સાધુ કે હરિજન ખપ વિના સત્સંગમાં ટકી શકતો નથી. થોડો પણ ખપ હશે તો સત્સંગમાં ટકી જશે.”","e":null,"s":["13/61/15-27"],"sv":["ब्रह्म होइके जेते, भगवान की करत सेव ही ।\n\n साचे ब्रह्म हें तेते, ता विन जो पाखंड सब ॥\n\n असत जेति जो बात, तामें धरत न पाव कब ।\n\n साचे ब्रह्म कहात, परब्रह्म कुं भजहि नित ॥\n\n परब्रह्म के उपासक जेते । ताकुं देखत ब्रह्म कर तेते ॥\n\n धर्म के वचन कहे गुरु जेता । मानत शिर चढाइ के तेता ॥\n\n वचन से ब्हार वरतहि न कबहु । संत की रीत संत चले तबहु ॥\n\n गृही की रीत में गृही चलावे । माया ताकुं विघ्न न करावे ॥\n\n वचन से अधिक चले जेहि । माया प्रवेश जानना तेहि ॥\n\n वचन से न्यून वरतत जेतो । प्रवेश किये माया तेतो ॥\n\n माया हें हरिवचन अधीना । वचन में चलना होइ के दीना ॥\n\n विघ्न करत नहि माया ताकुं । रूप विन नहि मनावत वाकुं ॥\n\n मन के कहे में वरतत जेहा । दिन दिन माया गलत तेहा ॥\n\n संत वा हरिजन जो ताको । अभाव लेवहि निश्चे वाको ॥\n\n सत्संग में पिछे पाव न टकहि । विमुख होइ चोराशि भटकहि ॥\n\n समझना एसे दृढ करि के । बात कहत हम फरी फरी के ॥\n\n खप विन जेते संत, खप बिन हरिजन जेहि ।\n\n सत्संग में न रहंत, टिकवे को मुख्य रूप यह ॥"],"mt":false,"gl":null,"a":false},{"i":1843,"k":"para","g":"મોટેરા ગામમાં શ્રીહરિ કહે, “ભગવાન અને ભગવાનના સંતો-ભક્તોમાં જેટલું હેત એટલું કારણશરીર ટળ્યું જાણવું. એકબીજામાં મન ન મળે, એ કારણ-શરીરનો ભાગ છે. સત્સંગમાં કષ્ટ પડે, તેમાં પોતાનું ધન્યભાગ્ય માને અને જીવે ત્યાં સુધી મનમાં મગન રહે, તેને સિદ્ધ જાણવો. ધર્મ-નિયમ પ્રીતિપૂર્વક પાળે તેને હરિભક્ત જાણવો. નિયમ વિના કોઈ હરિજન કહેવાતો નથી. કોઈ નિયમ-ધર્મમાં બધાથી શ્રેષ્ઠ વર્તે ને અપાર સેવા કરે, પણ પ્રગટ શ્રીહરિનો નિશ્ચય ન હોય તો તેને હરિજન ન જાણવો. ભગવાનનો નિશ્ચય ન હોય તે વગર દોષે દોષિત છે. નિશ્ચયવાળાને તનના દોષોનો શો ભાર છે! ભગવાનની કૃપાથી એ નિર્દોષ થશે. જીવમાં હરિનો નિશ્ચય નહિ તે ન્યૂનતા મોટી છે.”","e":null,"s":["14/64/28-35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1844,"k":"para","g":"હળવદના વિપ્ર નારણજીને ત્યાં શ્રીહરિએ હરિજનોને વાત કરતાં કહ્યું, “મહાસિંધુ પોતાના બાહુબળે તરાતો નથી. ફાવે તેવો તરવૈયો હોય તે પણ સિંધુમાં ડૂબે. તેમ ભવસિંધુ પોતાના બળે ઉલ્લંઘાતો નથી. નાવમાં બેસે તે સમુદ્ર તરે. તેમ સત્સંગરૂપી નાવ ભવસાગર તારનારું છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1845,"k":"para","g":"“પ્રગટ હરિ અને એમના શુભ માર્ગનો સંગ તે સત્સંગ છે. તેમાં નિષ્કપટ થઈને જે ચાલે તે સંતો-ભક્તોનો સંગ પણ સત્સંગ છે. શુભ આચરણ કરતો હોય, પણ પ્રગટ ભગવાનનો નિશ્ચય ન હોય તો તે જન્મમરણથી છૂટે નહિ. માટે પ્રગટ શ્રીહરિનો નિશ્ચય તે મુખ્ય શુભ માર્ગ છે. પ્રગટને ઓળખી નિશ્ચય કરે તે જ ભક્ત કહેવાય છે. જ્યારે જે રૂપે હરિ પ્રગટ હોય તેને પ્રગટ હરિ જાણવા.”","e":null,"s":["15/3/31-51"],"sv":["महासिंधु तरना होय जबहु । आप बल कोउ न तरे कबहु ॥\n\n गमे तेसे तारे जो होई । सिंधु में डूबे विन रहे न कोई ॥\n\n सिद्धगति कुं पावत हि जेते । अगाध सिंधु उल्लंघन तेते ॥\n\n जेते बैठत नाव, सिंधु तरे तहिं सहज तेहि ।\n\n सत्संग नाव रहाव, तारत हें भवसिंधु यह ॥\n\n शुभ सत बात रहे जो जेता । शुभ सत् मारग कहेउ तेता ॥\n\n ताके नाम सत्संग कहावे । सत् तामें चले हरिजन रहावे ॥\n\n तेसे जन जो हरिजन साचे । प्रगट हरि तामें मन राचे ॥\n\n प्रगट हरि शुभ मारग तामें । निष्कपट होई चले यामें ॥\n\n ऐसे संत हरिजन ताको । मन कर्म वचन संग करना याको ॥\n\n प्रगट हरि को निश्चय नाहि । शुभ आचरण केसो रहे ताहि ॥\n\n शुभ जोनि कुं पावे तेहा । जन्म मरण न छूटे कबु एहा ॥\n\n प्रगट हरि को निश्चे जाकुं । मुख्य शुभ मारग कहत ताकुं ॥\n\n श्रीहरि को प्रगट निश्चय, हरि प्रगट जब जाहि ।\n\n कहत हें हरिजन तितने, कहावत हें भक्त ताहि ॥\n\n जो जो समय भगवान जो, प्रगट होत जेहि वार ।\n\n प्रगट हरि जो जानना, बात कहे निरधार ॥"],"mt":false,"gl":null,"a":false},{"i":1846,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ કહેલી વાત મુક્તમુનિએ કહી, “શ્રીહરિ કહેતા - જેને પ્રગટ ભગવાનનો નિશ્ચય હોય તેને ભગવાનની વાત અમૃત જેવી લાગે છે. ને પ્રગટના નિશ્ચયવાળાને જ તેનો સ્વાદ આવે છે. પ્રગટ શ્રીહરિનો જેને નિશ્ચય નથી તે માટીનું કાચું વાસણ છે. તેને લેશ પણ સ્વાદ ન આવે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1847,"k":"para","g":"“પ્રગટ શ્રીહરિનું શરણ જ્યાં સુધી લીધું નથી ત્યાં સુધી તેની મતિ વિપરીત રહે છે. પ્રગટ વગર માયાનું આવરણ કોઈ ભેદી શકે નહિ. જપ, તપ, તીર્થ, વ્રત કે યોગની સાધના કરે તોપણ ભવસંકટ જે મહારોગ છે તે મટે નહિ. વેદ, પુરાણ અપાર ભણે પણ સંસૃતિ ક્યારેય મટતી નથી. સત્સંગ મળે છે ત્યારે તેને માયા સામે પટા ખેલવાની ચાતુરી આવે છે ને ભવભટકણ પણ દૂર થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1848,"k":"para","g":"“મોક્ષરૂપી ગુણ સત્પુરુષના સંગ વિના પ્રાપ્ત થતો નથી. સત્સંગ ન કર્યો તો અપાર સમૃદ્ધિ મળે તોપણ રંકનો રંક જ રહે છે. કલ્પતરુ ને ચિંતામણિ કરતાં પણ સત્સંગનો પ્રતાપ અધિક છે. સત્સંગ (આશરો) કરે છે તેને કાળ બચાવે છે અને બીજાને કાળ ચાવી જાય છે.”","e":null,"s":["15/23/29-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1849,"k":"para","g":"ગઢપુરમાં શ્રીહરિ કહે, “દેશ અને કાળરૂપી ભગવાનની શક્તિ મહા બળવાન છે. તે ધારે તેમ થાય છે. ભગવાનને દેશકાળ સ્પર્શતા નથી. તે સમર્થ છે તેથી દેશકાળનું સામર્થ્ય ઘટે તેટલું ચાલવા દે. છતાં પણ મનુષ્યાકૃતિ કૃપા કરીને ધરે છે ત્યારે કાળની મરજી જોઈને ચાલે છે. ભગવાન પણ કાળની મરજી લોપતા નથી. ભગવાનનાં ચરિત્રો દિવ્ય હોય કે લૌકિક - તેનું ગાન ભક્ત ગદ્‌ગદકંઠ થઈને કરે તો તે તત્કાળ દિવ્ય સ્થિતિ પ્રાપ્ત કરે છે. ભગવાનના પ્રત્યેક ચરિત્રમાં એટલું દૈવત રહ્યું છે. ભગવાનનાં ચરિત્રો કોટિ કોટિ કલ્પ વીતે તોપણ સદા નવીન ને નવીન રહે છે, ક્યારેય જીર્ણ થતાં નથી. જે જીર્ણ થયેલાં માને છે તે તુચ્છ પ્રાકૃત મતિવાળો છે.”","e":null,"s":["15/25/19-27"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1850,"k":"para","g":"શ્રીહરિએ પત્રમાં સાંખ્યયોગી હરિજનો પ્રત્યે લખાવ્યું કે, “જેને ભગવાન ને સંતનો યોગ નથી થયો તેનું ક્યારેય કલ્યાણ થતું નથી. જેને ભગવાન કે સંતનો સંબંધ થયો છે તેની સમજણ અલૌકિક હોય છે. તે દેહને અનિત્ય જાણે છે તેનો ફાવે તેમ દેહ પડે, પણ તે ભગવાનના ધામમાં જ જાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1851,"k":"para","g":"“દેહ કાશીમાં છૂટે કે શ્વપચને ઘરે છૂટે તોપણ કાંઈ સંશય નહિ. અનાર્ય દેશમાં, વનમાં કે નગરમાં છૂટે, આજે પડે કે બહુ કાળે પડે, છતાં જ્ઞાની લોકો આનંદ પામે છે અને સંશયથી રહિત હોય છે. ઉત્તરાયણ કે દક્ષિણાયનનો પણ તેને સંશય નથી. કોઈ પ્રાણી આવીને ખાય કે અગ્નિ કે જળ વગેરેથી મૃત્યુ થાય, ચંદન અને તુલસીના કાષ્ઠમાં શ્રીફળ અને ઘી સાથે બાળવામાં આવે કે જ્યાં ત્યાં દેહ પડી રહે અને તેને પશુ-પક્ષી ખાઈ જાય, તોપણ તેને કાંઈ સંશય નથી. માસે માસે પાછળ વિધિ કરવામાં આવે કે ન આવે તેનો પણ તેને શોક નથી. દેહ પર સોનાનું મંદિર કરી જગત બધું પૂજે તેનો પણ તેને હર્ષ નથી.”","e":null,"s":["15/91/28-49"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1852,"k":"para","g":"શ્રીહરિએ પત્રમાં લખાવ્યું કે: “અમારા વિવેકી અને સમર્થ હરિભક્ત છે તે દેહને અસત્ય માને છે. આત્માને સત્ય માને છે. સર્વથી પર જે ચિદાકાશ (અક્ષરધામ)માં પુરુષોત્તમ નારાયણ સદા વિરાજમાન છે, એ અક્ષરબ્રહ્મને પોતાનું રૂપ માની, આત્માની તે બ્રહ્મ સાથે એકતા કરીને પરબ્રહ્મની ઉપાસના સ્વામી-સેવકભાવે સદાય કરે છે. તેને બ્રહ્મરૂપ એવા હરિના દાસ જાણવા.”","e":null,"s":["15/96/25-29"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1853,"k":"para","g":"પીપળાવમાં શ્રીહરિ આનંદાનંદ મુનિને ફરી વાત કરવા લાગ્યા, “જે સાધુ અમને પ્રસન્ન કરવા ત્યાગ રાખે છે, તેને ભગવન્નિષ્ઠ સાધુ જાણવા. ત્યાગનિષ્ઠ, યોગનિષ્ઠ, જ્ઞાનનિષ્ઠ ત્રણેય ભગવન્નિષ્ઠથી ન્યૂન છે. કોઈ તો વળી, તેજનિષ્ઠ હોય તે ભગવાનના આકારને માયિક કહે, અને વિધિનિષેધને કલ્પિત કહે છે, પણ મૂર્તિ વિના તેજને કહેતા હોય એ તો અજ્ઞાનીમાં અતિશય અજ્ઞાની છે. તારા, ચંદ્ર, સૂર્યનું જેટલું તેજ દેખાય છે તે મૂર્તિ વગરનું નથી. એ દૂર છે એટલે મૂર્તિ દેખાતી નથી. કેટલીક માયિક વાત પણ બુદ્ધિના તર્કમાં આવતી નથી, તો અમાયિક ક્યાંથી બુદ્ધિના તર્કમાં આવે! દૃષ્ટાંતે કરીને ન સમજે તેને પશુ જાણવો. સત્સંગના યોગ વગર તેની અવળી સમજણ ટળતી નથી. વેદ, પુરાણ અપાર ભણે, પરંતુ તેને શાસ્ત્રનો બોધ સવળો ગ્રહણ થતો નથી. સત્પુરુષના સંગ વગર ગમે તેવી વાત હોય, તોપણ નિષ્ફળ છે. એ પ્રત્યક્ષ દેખ્યામાં આવે છે. ભગવાન અને સત્પુરુષનો સંગ એ બંને જીવનદોરી છે.”","e":null,"s":["16/54/1-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1854,"k":"para","g":"ગઢપુરમાં શ્રીહરિ કહે, “પુરુષોત્તમ ભગવાન, અક્ષરબ્રહ્મ, માયા, ઈશ્વર અને જીવ - આ પાંચે ભેદ અનાદિ, અવિચળ રહ્યા છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1855,"k":"verse","g":"‘પુરુષોત્તમ ભગવાન તાકું, અક્ષરબ્રહ્મ હિ કહે વાકું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1856,"k":"verse","g":"માયા અરુ ઈશ્વર કું, જીવ - યહ પાંચ ભેદ;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1857,"k":"verse","g":"અનાદિ રહાયેઉ તે હિ, અવિચલ કરહિ અછેદ.’","e":null,"s":["21/5/35-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1858,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ મોક્ષના નિર્વિઘ્ન માર્ગની વાત કરતાં કહ્યું, “બ્રહ્મથી પરબ્રહ્મ પુરુષોત્તમનારાયણ પૃથક્ છે. એ તો બ્રહ્મના પણ કારણ છે, આધાર છે ને પ્રેરક છે. એવું સમજીને જીવાત્માની એ બ્રહ્મ સંગાથે એકતા કરવી. પછી પરબ્રહ્મને સ્વામી-સેવકભાવે ઉપાસના કરવી. આવું બ્રહ્મજ્ઞાન પરમપદ-મોક્ષ માટેનો નિર્વિઘ્ન અને શ્રેષ્ઠ માર્ગ કહ્યો છે.”","e":null,"s":["22/9/89-92"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1859,"k":"para","g":"સારંગપુરમાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “ભગવાનના વચનમાં રહે તેને નિવૃત્તિમાર્ગવાળો જાણવો. મનમુખીપણે વર્તતો હોય તો તે નરકને પામે છે. ગમે તેવો ત્યાગ-વૈરાગ્ય રાખે, અન્નજળનો ત્યાગ કરે પણ મનમુખી વર્તન કરે તેને ભગવાન લેશ પણ ગણતા નથી. તે તો વિમુખ થઈને અંતે નરકે જાય છે. ભગવાનના દાસના દાસનો દાસ થાય, દાસનો ગુલામ થાય, તેનો પણ ગુલામ થવા કોટિ કલ્પ સુધી ઇચ્છે રાખે ને પ્રાર્થના કરે પછી તેને ભગવાન મનુષ્યમાં શ્વપચનો દેહ આપે છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1860,"k":"verse","g":"‘ભગવાન હુ કે દાસ, તાકે દાસ કે દાસ હુ કે,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1861,"k":"verse","g":"ગુલામ તાકે જાસ, તાકે ગુલામ હોન કું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1862,"k":"verse","g":"ઇછત જબ જો રહેઉ, કોટિ જો કોટિ કલ્પ લગ,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1863,"k":"verse","g":"પ્રાર્થના કરત તેઉ, શ્વપચ કે તન પાવત તબ.’","e":null,"s":["23/12/34-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1864,"k":"para","g":"શ્રીહરિ સોરઠમાં ફરતાં બંધિયા, પીપલિયા, રાયપુરથી રાજનગર આવ્યા. અહીં શ્રીહરિએ ભગવાન સૌનું કારણ છે ઇત્યાદિ વાતો કરતાં કહ્યું, “સત્સંગની વાતો શીખીને કોઈ ભગવાન થવા જાય તો તે કસાઈથી પણ કોટિગણો કસાઈ છે, એવા દુર્બુદ્ધિને જોઈ તેની છાયામાં દબાવું નહિ. કોઈ અગણિત બાઈ-ભાઈના અંતરનું કહી દે તેણે કરીને તે ભગવાન થઈ શકતો નથી. મનુષ્ય, ઋષિ, પંચભૂત, સ્થાવર-જંગમ સૃષ્ટિથી પર સૂર્ય, ચંદ્ર, તારા અગણિત છે. તેનાથી પર દેવતા ને બ્રહ્મા છે. બ્રહ્માથી પર વૈરાટ છે. એવા અનંતકોટિ વૈરાટના કારણ અનંત પ્રધાનપુરુષ છે. તેના પણ કારણ પ્રકૃતિ પુરુષ છે. પ્રકૃતિ પુરુષનું કારણ અક્ષર છે. અક્ષરથી પર પુરુષોત્તમ છે. પુરુષોત્તમથી પર કોઈ નથી. અજ્ઞાની જન ચાહે તેમ કહે. પુરુષોત્તમથી નીચેના સૌ કોઈ પુરુષોત્તમના દાસ છે ને તેનું ભજન કરે છે. પુરુષોત્તમનું દાસપણું ઇચ્છે તેની મોટપ સૌથી ઊંચી છે. તેને સામર્થિ મળે છે તોપણ તે પુરુષોત્તમના દાસ થઈને વર્તે છે અને તેનું ભજન કરે છે. સત્સંગની આવી અતિનિર્બાધ સમજણ જેને આવે છે, તે અત્યંત સામર્થિ પામે છે તોપણ તે હરિના દાસ થઈને રહે છે.”","e":null,"s":["25/50/29-40"],"sv":["सत्संगकि सिखकर बाता । भगवान जेहि होत रहाता ॥\n\n कसाई सें कोटि गन कसाई । रहाये ऐसे जन हि ताई ॥\n\n सत्संग कि समझ रहे ऐसी । सत्संग कि बात सुनकर तेसी ॥\n\n सत्संग में भगवान होउ । चलावन मत जावन कोउ ॥\n\n दुरबुद्धि देख आवत ताकि । छाये में नहि दबावत वाकि ॥\n\n अंतरकि के’वत रहे केते । बाई-भाई अगणित तेते ॥\n\n तिन करिके तेहि भगवाना । होवत नहि कबु रहाना ॥\n\n मनुष्य, दैत्य, देव अब ताकी । पशु पक्षी कहावत वाकी ॥\n\n मनु, कश्यप, ऋषि पंचभूत तिनके । स्थावर जंगम अगणित इनके ॥\n\n सूर्य, चंद्र भव तारे जेते । गनत पार न पावत हि तेते ॥\n\n ब्रह्मा सबके कारन कहाते । ब्रह्मा के कारण वैराट रहाते ॥\n\n अनंतकोटि वैराट तिनके । अनंत प्रधान पुरुष ईनके ॥\n\n कारन यह कहावत रहावा । प्रकृति पुरुष ताके कहावा ॥\n\n प्रकृति पुरुष के अक्षर रहेउ । अक्षर के पुरुषोतम कहेउ ॥\n\n पुरुषोत्तम सें पर हि जो, कोउ हि नहि कहात ।\n\n अज्ञानि रहे जीतना हि, चाय तेसे उचरात ॥\n\n पुरुषोत्तम सें ओरें हि, जो जो जेते जेहि ।\n\n पुषोत्तम के दास रहे, भजत रहत हें तेहि ॥\n\n पुरुषोत्तम हि ताके, दासपना इच्छत रहत ।\n\n बडता अति वाके, होवत रहे सबहि पर ॥\n\n सत्संग ताकि ऐसि, समझ रहे निरबाध अति ॥\n\n सामृथि पावे केसी, तोउ हरि के दास रहत ॥"],"mt":false,"gl":null,"a":false},{"i":1865,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ અક્ષરની વાત કરતાં કહ્યું, “બ્રહ્મા એક બ્રહ્માંડના અધિપતિ છે, તેનું અક્ષર પાસે શું લેખું? જે અક્ષરના એક રોમમાં અનંતકોટિ બ્રહ્માંડ અણુની પેઠે ઊડતાં રહે છે! એવા અક્ષરધામની અપાર મોટપ છે તો પણ તેઓ પોતાની આ મોટપ ભગવાન પુરુષોત્તમ નારાયણ પાસે કંઈ જ દેખાડતા નથી અને ભગવાનના દાસ થઈને પોતાને અલ્પ માનીને બહુ ભાવથી તેમને ભજે છે.”","e":null,"s":["26/23/36-38"],"sv":["ब्रह्मा जेसे कौन लेख रहेउ । अनंतकोटि ब्रह्मांड तेउ ॥\n\n अक्षर के एक रोम तामें । उडत रहे अणु समहि यामें ॥\n\n ऐसे अक्षरधाम जो, भगवान ताकि जेहु ।\n\n मोटप आगे मोटप हि, कुछ न देखावत तेऊ ॥\n\n तब भगवान के दास होई, भगवान जो ताकुं ।\n\n भजत रहे बहु भाव कर, अल्प मानि निज वाकुं ॥"],"mt":false,"gl":null,"a":false},{"i":1866,"k":"para","g":"શ્રીહરિએ ખરડામાં એક અલૌકિક વાત લખાવી કે, “પોતામાં અવતાર જેવું ઐશ્વર્ય હોય અને સર્વનું કારણ પોતાને સમજે તો તે તેની કસર છે. કુબુદ્ધિજન હોય તો તે થોડુંક જ્ઞાન શીખ્યો કે તરત હું ભગવાન છું એમ માનવા લાગે છે. ભગવાનના જ્ઞાનનું પાત્ર થયા વિના પોતાને અધિક માને તેને મનમલીન જાણવો. જ્ઞાનનું પાત્ર વસિષ્ઠ, જનક, ઉદ્ધવ, પ્રહ્‌લાદ થયા. અક્ષરના એક એક રોમમાં અનંતકોટિ બ્રહ્માંડ અણુની જેમ ઊડ્યાં કરે છે, એ અક્ષર પણ ‘હું ભગવાન છું’ એમ ક્યારેય કહેતા નથી, પણ ભગવાનના દાસ થઈને વર્તે છે. વળી, અક્ષર તો મોટા મોટા ઈશ્વરોના આધાર છે, કશ્યપાદિ પ્રજાપતિઓ, સમગ્ર સૃષ્ટિ અને સર્વે પ્રાણીઓના સર્જનહાર બ્રહ્માદિ દેવોના પણ જે આધાર છે ને એ જ અક્ષરબ્રહ્મ સૌને જિવાડવાની ક્રિયા કરે છે અર્થાત્ સૌના નાડી-પ્રાણ પોતાના હાથમાં છે. તોપણ એને એ વાતનું અભિમાન નથી. એ તો ભગવાનના દાસ થઈને વર્તે છે. એ એવા પાત્ર થયા છે તો, તે ઇચ્છતા ન હોવા છતાં ભગવાને પોતાનું સઘળું ઐશ્વર્ય તેમને આપ્યું છે. તોપણ તે છકી જતા નથી. કારણ, અક્ષર એ ભગવાનને રહેવાનું પાત્ર છે. પાત્ર રહિત જીવ કીર્તન-શ્લોક શીખે, પણ ભગવાનનો તેને ભાર કે મહિમા નથી તે તુચ્છ છે. અંતે એવા જન નારકી થાય છે.”","e":null,"s":["27/85/17-22"],"sv":["श्रीहरि खरडे तामे जोई । अलौकिक बात लिखाये सोई ॥\n\n पोतामें ऐश्वर्य रहे जीमि । जे ते अवतार तामें तीमि ॥\n\n सबके कारन हि आप हि, आप से अधिक केउ ।\n\n जानत जेहि जीहां लग हि, तितनां कसर हि तेउ ॥\n\n कुबुद्धि जन रहे जीतने, ज्ञान सिखि के जेहि ।\n\n में रहे भगवान जोउ, ऐसे मानत तेहिं ॥\n\n ज्ञान के पात्र बिन, ज्ञान सिख कर आप हु कुं ।\n\n जितने मनमलिन, सबसे अधिक मानत यह ॥\n\n अक्षर के एक एक रोम तामें । अनंत कोटि ब्रह्मांड वामें ॥\n\n उडत रहे अणु उडत जेसे I मैं भगवान हूँ कहत न तेसे ॥\n\n बडे बडे हि कहावत जेते । जाके आधार कर प्राणि तेते ॥\n\n ब्रह्मा, कश्यप सृष्टि ताके । कर्ता रहायेउ जोउ वाके ॥\n\n जीवत हि क्रिया करत रहाते | ताके अभिमान न ताकुं आते ॥\n\n तोउ न कहत मैं भगवाना । भगवान के दास हि रहाना ॥\n\n ऐसे पात्र भये यह जबहु । भगवान पोताके ऐश्वर्य तबहु ॥\n\n देवत रहाये इच्छे बिन हि । छकि न जावत तिन करी तिनहि ॥\n\n पात्र विन रहायेउ जितने । कीर्तन श्लोक बहु सिखत तितने ॥\n\n भगवान ताकुं गिनत नाहि । नारकी जितने जीन रहाहि ॥"],"mt":false,"gl":null,"a":false},{"i":1867,"k":"para","g":"ગઢપુરમાં શ્રીહરિ કહે, “સત્સંગ, આ ભગવાન, તેમનું ધામ (અક્ષરબ્રહ્મ), ભગવાનના ભક્તો, ભગવાનનાં ચરિત્રો અને ભગવાન સંબંધી વાતોની તોલે કોઈ આવી શકે નહિ. આ વાત અમૂલ્યમાં અમૂલ્ય અને સર્વોપરિ છે. બીજી બધી વાતને અસત્ય કરી આ વાતમાં ચિત્ત ચોટાડવું. જો તેમ થાય તો તેના જેવો કોઈ બડભાગી નથી. તેને કંઈ કરવું રહ્યું નથી. મોટા-મોટાની આ સમજણ રહી છે. આ વાત સિદ્ધાંતમાં સિદ્ધાંત છે. આ વાતનો જેને રંગ લાગ્યો હોય તેનો સમાગમ નિત્ય કરવો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1868,"k":"para","g":"જીવ, ઈશ્વર, માયા, બ્રહ્મ અને પરબ્રહ્મ - આ પાંચ ભેદ અનાદિ છે. તેને આટલા કલ્પ થયા તેમ પણ ન કહેવાય. આ સનાતન તત્ત્વો છે. જેમ શબ્દમાત્રનું બીજ એવા વેદો સનાતન છે, તેમ આ પાંચ ભેદ સનાતન છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1869,"k":"verse","g":"‘એસે શ્રીહરિ બાત બહુ, કરત રહે હિત લાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1870,"k":"verse","g":"હરિજન પર રહે હિત બહુ, મુખ કહે ન આય.’","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1871,"k":"para","g":"“આવી વાત શ્રીહરિ હરિજન પર હેત લાવીને બહુવાર કરતા. જે મુખથી કહેતા પાર આવે તેમ નથી.” એમ મુક્તમુનિએ ઉત્તમ નૃપને કહ્યું.","e":null,"s":["28/10/29-37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1872,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1873,"k":"para","g":"કર્મ કરવાથી કર્મ બળતાં નથી, તે કોટિ જન્મ સુધી કર્મ કરે તોપણ તે શુદ્ધ થતો નથી. કર્મ પોતે જ અશુદ્ધ છે તો તે કેવી રીતે શુદ્ધ કરે! ભગવાન અને ભગવાનના સંત એ બે જ શુદ્ધ છે તેના થકી કર્મ બળે છે ને જગત બધું અશુદ્ધ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1874,"k":"verse","g":"‘સંત હરિ હે શુદ્ધ હિ દોઉ, તેહિ બિન અશુદ્ધ સબ જગ સોઉં.’","e":null,"s":["5/71/23-24"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1875,"k":"para","g":"શ્રીહરિનો જેમને દૃઢ વિશ્વાસ અને નિશ્ચય હોય તે હરિવચનમાં ગુલતાન રહે છે. ગમે તેવી વિપત્તિ પડે પણ તે ઉદાસ થતો નથી. વિપત્તિને તે તપ માને છે, જેને ખપ છે તે એવી સવળી સમજણ ગ્રહણ કરે છે, અને એમ માને છે કે હરિભક્તને શ્રીહરિ ક્યારેય દુઃખ દે જ નહિ. શ્રીહરિનું સુખ વિચારે છે, ત્યારે તેનાં અનંત દુઃખ ઊડી જાય છે. ચિંતામણિ હોવા છતાં તેને પથ્થર માનીને સુખ ન લઈ શકે તે જડ કહેવાય.","e":null,"s":["6/21/33"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1876,"k":"para","g":"શ્રીહરિનો નિશ્ચય એ ખરો સત્સંગ છે. શ્રીહરિની ઉપાસના વિના આત્મદર્શી હોય તે સંભવતું નથી.","e":null,"s":["6/24/22"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1877,"k":"para","g":"સામર્થ્યની દૃષ્ટિએ અવતારો અને સંતો સમાન નથી. એક અવતાર અને બીજા અવતાર વચ્ચે ઘણી તારતમ્યતા છે. એક સંત ને બીજા સંત વચ્ચે કોટિ પ્રકારના ભેદ છે. પ્રતાપથી અધિક-ન્યૂનતા જણાઈ આવે છે. જેમ બધું સુવર્ણ સોળવલું હોતું નથી, બધાં મોતી પણ સમાન મૂલ્યવાળાં હોતાં નથી. પારસમણિના પણ પ્રકાર છે ને ચિંતામણિ પણ ભેદે કરીને જુદી જુદી છે, તેમ અવતારોમાં સામર્થ્યભેદથી ઘણા ભેદ છે. નામથી તો બધા સમાન લાગે, પણ ભેદ ઘણો છે. તે ભેદ જોઈને તેની નિંદા ન કરવી. ભગવાન, સંત, દેવતા, વિપ્ર, પતિવ્રતા સ્ત્રી અને વેદ – આટલાની નિંદા કદી ન કરવી. જે તેની નિંદા કરે છે, તે નારકી થાય છે.","e":null,"s":["6/72/36-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1878,"k":"para","g":"શ્રીહરિના ગુણ બીજા મુક્તમાં ક્યારેય આવતા નથી. જે બ્રહ્મરૂપ થાય છે તેમાં તે ગુણ આવે છે. મુક્ત જો (બ્રહ્મના સાધર્મ્યપણાને પામ્યો ન હોય ને) પોતાને બ્રહ્મરૂપ કહેવડાવતો હોય તો તે બંધનકર્તા બને છે. જેમ નારદજીને બ્રહ્મની સ્થિતિ નહોતી થઈ ને પોતાને બ્રહ્મરૂપ માનતા તો વિષયનો સંકલ્પ થયો ને માંકડાનું મોં થયું.","e":null,"s":["8/72/37-38"],"sv":["हरि के गुन ओर मुक्त में, कबहु सो आवत नाहि ॥\n\n ब्रह्मरुप होई वरते, बंधन होत हे तांहि ॥\n\n नारद हरि के मन हि, ब्रह्मरूप सदाय ।\n\n विषय को करे संकल्प हि, वानरमुख भये ताय ॥"],"mt":false,"gl":null,"a":true},{"i":1879,"k":"para","g":"જે ભક્તને પ્રગટ ભગવાનને વિષે અપાર નિશ્ચય હોય, તે તેમનામાં લેશ પણ સંશય ન કરે. દેશકાળ વિષમ આવે ને મન ફરી જાય તોપણ ભગવાનનો અવગુણ ન આવે. કોઈનું ચિત્ત ભ્રમી જાય છે ત્યારે વર્ણાશ્રમનો વિવેક રહેતો નથી. જેનું તેનું ખાવા લાગે, વસ્ત્રનું ભાન રહે નહિ, ખાય ન ખાય એવું કરે, અન્ન ખાતો ખાતો મળ ત્યાગ કરે, શુદ્ધ અશુદ્ધ જગ્યા જુએ નહિ, માને વહુ કહે ને વહુને મા કહે, બાપને મોટાભાઈ કહે - એવી વિપરીત મતિ થાય તોપણ ભગવાનનો નિશ્ચય જાય નહિ. જાગ્રતમાં હોય તે પ્રમાણે સ્વપ્નમાં નિશ્ચય રહે. દીર્ઘરોગ થાય અને રાતદિવસ પીડાથી રડે તોપણ અજાણ ઔષધ ખાય નહિ. મલિન મંત્ર જપાવે નહિ, દોરા બંધાવે નહિ, ભૂવા અને મલિન દેવની પ્રતીતિ રાખે નહિ. સત્સંગ રાખતાં હાનિ થાય તોપણ હઠે નહિ, પરંતુ ચઢતો રંગ રહે અને અગ્નિમાં સુવર્ણની પેઠે જેમ તપે તેમ પ્રદીપ્ત થાય એ નિશ્ચયવાળાનું લક્ષણ છે. જેને જેટલો નિશ્ચય હોય તે કામ પડે ત્યારે દેખાય. વિપત્તિ આવે તથા સંપત્તિ નાશ પામે તે અગ્નિ જેવી કસોટી છે.","e":null,"s":["10/54/17-36"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":23,"gu":"શ્રીહરિનો સ્વાભાવિક ગુણ","en":"Shrihari's Natural Virtues","url":"https://www.anirdesh.com/pbp/index.php?page=chp_23","b":[{"i":1880,"k":"para","g":"ચૂડામાં શ્રીહરિ થાળ જમ્યા અને પ્રસાદી જીવેન્દ્ર અને ઉત્તમ નૃપને આપી. જાલમસિંહે માંગીને લીધી. ત્યારે શ્રીહરિએ બ્રહ્મચારીને નજીક બોલાવી કહ્યું, “જેને જેને પ્રસાદીનો ભાવ હોય તે બધાને આપો.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1881,"k":"para","g":"બ્રહ્મચારી જોઈ રહ્યા, કારણ કે થાળમાં એટલી પ્રસાદી હતી નહિ. શ્રીહરિ કહે, “થાળ કરો ત્યારે હરિભક્તોની શ્રદ્ધાનો વિચાર રાખવો. વધારે ભક્તો હોય તો મોટો થાળ કરવો. અમે કોઈને બોલાવીને પ્રસાદી આપીએ તે જીવનભર સ્મૃતિમાં રાખે. વાત કરી હોય તે યાદ ન રહે, પણ પ્રસાદી તો યાદ રહે.”","e":null,"s":["4/74/1-4"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1882,"k":"para","g":"અલૈયા ગામમાં શ્રીહરિએ હરિભક્તોને ઉદ્દેશીને એક પત્ર લખ્યો તેમાં લખ્યું કે, “સત્સંગ વિના પાપ ટળતાં નથી, પણ ઘરમાં ઉપાધિ હોય તેણે બહાર ન જતાં ઘરે રહીને સત્સંગ કરવો, પણ સત્સંગ છોડવો નહિ. ઘરમાં જેને બીજાની ઉપાધિ ન હોય તેણે દર્શન કરવા આવવું, પણ પોતાની ગાંઠનું ખાવું. હરિભક્તનું અન્ન ક્યારેય ખાવું નહિ. સગાં-સંબંધી ન હોય તેનું ખાવું નહિ. વિવેકી પુરુષો તીર્થમાં જાય છે, ત્યારે ઘરે પાછા આવે છે ત્યાં સુધી ગાંઠનું ખર્ચ કરે છે. અમારો આ નિયમ સર્વ રાખજો. કોઈ ધનવાન હરિભક્ત હોય તે શ્રદ્ધાએ કરીને જમાડે તો ધનથી દુર્બળ હોય તેણે એકવાર જમવું અથવા ગામમાં કોઈ ધનવાન હરિભક્ત પોતાની સાથે લાવ્યા હોય અને જમાડે તો દર્શન કરવા આવવું. દર્શનનું ફળ જમાડનારને મળે છે. જે જમાડે તેની સેવા કરે તો વધુ પુણ્ય મળે છે. કોઈકના વાહનમાં બેસીને દર્શન કરવા આવે તો તેનું ફળ વાહનવાળાને મળે છે.”","e":null,"s":["5/19/37-48"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1883,"k":"para","g":"માનકુવામાં શ્રીહરિએ વાત કરતાં કહ્યું, “પ્રથમ અમારું અંગ કહીએ - અમને હરિભક્તને જોઈને અંતરમાં બહુ ઉમંગ થાય છે. કોઈનો દોષ અમારાથી દેખાઈ જાય છે ત્યારે અમારા અંતરમાં બહુ દુઃખ થાય છે. અને તેને રાજી કરીએ છીએ ત્યારે અંતરમાં શાંતિ થાય છે. સંતો-ભક્તો એક એકથી ગુણે કરીને ઉત્તમ છે. અમારા હાથે તેમની સેવા જે દિવસે બની આવે છે તે દિવસે અતિ આનંદ રહે છે. સેવા ન થાય તે વખતે અંતરમાં અપાર દુઃખ થાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1884,"k":"para","g":"“એક હરિભક્ત બીજા હરિભક્તને દબાવે તે જોઈને તેનો તરત અંતરમાં અભાવ આવે છે. તેનો તિરસ્કાર કરી વઢીને અપમાન કરીએ ત્યારે અંતરમાં સુખ થાય છે. અમારે બાળપણાથી એવી પ્રકૃતિ છે કે ગરીબનો પક્ષ સહેજે રહે. બરોબરિયા બે જણ ઝઘડતા હોય તેને દેખી અંતરમાં ભાવ થતો નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1885,"k":"para","g":"“અમે એવા ભક્તની સેવા ગ્રહણ કરીએ છીએ, જે હરિભક્તોથી અંતરમાં અતિશય ડરતો રહે અને રાત-દિવસ સૌ ભક્તોના ગુણ ગાયા કરે. એવા ભક્તની સેવા અંગીકાર કરતા અમારી છાતી ઠરે છે. ભલે અમારી સેવા ન કરતો હોય, પણ હરિભક્તના ગુણ કહેતો હોય તો તેણે અમારી અતિશય સેવા કરી એમ માનીએ છીએ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1886,"k":"para","g":"“કોઈ અમારી સેવા કરે ને ભક્તોનો અવગુણ ગાય, બીજાના અવગુણ જોવા પર જ તાન હોય, બીજાનું હીણું દેખાય એ રીતે અમારી સેવા કરતો હોય તેની સેવાથી અમે અતિશય ડરીએ છીએ. એવા જનની સેવા અમને વજ્રના પ્રહાર સમી લાગે છે. ભલે નિત્ય નવી નવી શ્રદ્ધાથી સેવા કરે તોપણ તે સત્સંગમાં ઘટતો જાય છે. કોણ કેવી ને કેટલી સેવા કરે છે - તેના જુદા જુદા ભાવ અમે જાણીએ છીએ. અમે કોઈનું અહિત કરતા નથી, પણ સૌ પોતપોતાની રુચિ અનુસાર ફળ પ્રાપ્ત કરે છે.”","e":null,"s":["5/52/29-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1887,"k":"para","g":"સુખપુરમાં રાવત ધાધલને ત્યાં શ્રીહરિએ વાત કરતાં કહ્યું, “આ સત્સંગરૂપી મહેલ તૈયાર નહિ થાય ત્યાં સુધી અમે ભૂમિ ઉપર રહીશું. તેના ઉપર કળશ ચઢાવીને જ અમે આરામ કરીશું.”","e":null,"s":["6/4/39-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1888,"k":"para","g":"મેથાણમાં શ્રીહરિએ વાત કરતાં કહ્યું, “રામાનંદ સ્વામીએ સત્સંગરૂપી મોક્ષનું વન અમને સોંપ્યું છે. તેમાં હરિભક્તો રૂપી વિવિધ કલ્પવૃક્ષો છે. તેમાં કેટલાંકનાં મૂળ પાતાળ સુધી ઊંડાં ગયાં છે. તેમનો કંઈ ડર નથી, પણ જેનાં મૂળ ઉપરછલ્લાં છે તેનો ડર રાખવો પડે છે. કુસંગરૂપી વાયુ આવે તો તેમનાં મૂળ ઉખાડી નાંખે, જેથી અમે તથા સંત બધા દેશમાં ફરતા રહીએ છીએ અને નિયમની વાડો વારે વારે કરીએ છીએ. પછી કાચો કોટ કરીશું જેથી અગ્નિનો ભય ન રહે. પછી પાકો વજ્રનો કોટ કરીશું કે જેથી હાથી અને તોપની પણ ધાક રહે નહિ. જેમ જેમ સંત-હરિભક્તોને ખપનું બળ આવતું જશે, તેમ તેમ નિયમ પાકા કરીશું. પછી એક સ્થાનમાં સુખે રહીશું.”","e":null,"s":["6/19/7-16"],"sv":["श्रीहरि तब बोलत भयेउ । अमृत वचन रस भरेउ ॥\n\n सत्संग रूप मोक्ष वन जेहा । रामानंद स्वामी सुंपे तेहा ॥\n\n तामें हरिजन रूपी हि जेहु । विविध कल्पतरु रहे हैं तेहु ॥\n\n कितनेक के मूल गये हैं पाताला । ताको नहि हैं डर कोउ काला ॥\n\n उपर छल्ले मूल रहे हैं जाके । अति डर रखत हैं वाके ॥\n\n कुसंग रूप हि वायु जोरा । उखारि देवे रहे नहि ठोरा ॥\n\n संत रहे चहु देश मांहि । फिरत रहत हैं जंपत नाहि ॥\n\n नियम रूप वार विविध प्रकारा । करने लगे हैं वारम वारा ॥\n\n काचे कोट पिछे करहि ताकु । अनल को भय न लगे वाकु ॥\n\n पिछे वज्र कोट करहि पक्का । हाथी तोप को न लगे धक्का ॥\n\n ज्युं ज्युं संत हरिजन ताई । खप रूप बात आत देखाई ॥\n\n त्युं त्युं करहि नियम को दृढावा । एक स्थान पिछे सुखे रहावा ॥"],"mt":false,"gl":null,"a":false},{"i":1889,"k":"para","g":"મેથાણમાં શ્રીહરિ કહે, “ભક્તોને અલૌકિક સુખ આપવા અમે સત્સંગમાં વારે વારે ફરીએ છીએ. અમારી એક પણ ક્રિયા સ્વાર્થને માટે નથી.”","e":null,"s":["6/26/12-13"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1890,"k":"para","g":"ભોંયરા ગામમાં શ્રીહરિએ વાત કરતાં કહ્યું, “ભગવાનની કૃપા વિના જીવને પોતાના દોષ ક્યારેય દેખ્યામાં આવતા નથી, જ્યારે પોતાના દોષ દેખાવા લાગે ત્યારે જાણવું કે શ્રીહરિની કૃપા થઈ છે. પોતાના દોષ જાણ્યા વિના મોક્ષરૂપી ગુણ પ્રાપ્ત થતો નથી. મોક્ષરૂપ ગુણ ન આવે ત્યાં સુધી અન્ય ગુણ શોભતા નથી. પાતાળથી પ્રકૃતિપુરુષના લોક સુધી મોક્ષગુણ વિના લૂખું દેખાય છે. ભલે દૈહિક સુખ અપાર મળે, પણ એ જીવને દુઃખરૂપ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1891,"k":"para","g":"“હરિના ચિંતવન વિના બીજાનું ચિંતવન કરવું એ દોષમાત્રમાં વિકટ દોષ છે. ભગવાન વિના અન્યનું ચિંતવન કાકવિષ્ટા સમાન જે જાણે છે તે સર્વગુણસંપન્ન છે.”","e":null,"s":["6/39/31-39"],"sv":["हरि कृपा विन दोष निज केरा । देखे में न आवे कोउ वेरा ॥\n\n निज को दोष देखाय जाकु । हरि कि कृपा जानना ताकु ॥\n\n निज को दोष जाने विन कबहु । मोक्ष रूप गुन न आवत तबहु ॥\n\n मोक्ष रूप गुन विन गुन ओरा । सोहत नाहि देखे कोउ ठोरा ॥\n\n पुरुष प्रकृति पाताल प्रजंता । मोक्ष रूप गुन विन लुखे देखंता ॥\n\n देहिक सुख मिले वार न पारा । सोई दुःख रुप जीय के अपारा ॥\n\n हरि विन चिंतवन जीय में जेता । सो गुन विन असार हैं तेता ॥\n\n चिंतवन हरि विन जितनो जाई । दोष में दोष विकट यह ताई ॥\n\n और चिंतवन काग विष्ट समाना । समजे तव तेहि भयो गुनवाना ॥\n\n और में दोष होय अपरमपारा । तामें गुन तितनो ग्रहे सारा ॥\n\n नखशिख देह अपार है एहा । सार मानत इतनो दोष है तेहा ॥\n\n दोष, मोह, इहाँ कहत एका । बुद्धिमान सो जाने विवेका ॥"],"mt":false,"gl":null,"a":false},{"i":1892,"k":"para","g":"જેતપુરમાં શ્રીહરિ કહે, “ગરીબનો અપરાધ કદાચ મારાથી જો થઈ જાય તો મને અતિ દુઃખ થાય છે. તો બીજાની શી વાત કરવી!","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1893,"k":"para","g":"“જેનો દેહ પરવશ છે તેને ગરીબ સમજવો. જે હરિનો ભક્ત વચન સહન કરી લે, સામે કશું બોલે નહિ તેને ગરીબ સમજવો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1894,"k":"para","g":"“અતિબાળક અને અતિવૃદ્ધ હોય તેને પણ ગરીબ સમજવો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1895,"k":"para","g":"“જે સ્ત્રીઓ સ્ત્રીધર્મથી યુક્ત હોય તેને પણ ગરીબ સમજવી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1896,"k":"para","g":"“રાજા, ગુરુ ને ધનવાન - એ ત્રણમાં જો દયા ન હોય તો તે વજ્ર સમાન કહેવાય. અને તે ક્યારેય યશ પામે નહિ. કોઈનું બૂરું થાય તે અમને ગમતું નથી એવો અમારો સ્વભાવ છે.”","e":null,"s":["6/65/28-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1897,"k":"para","g":"જૂનાગઢમાં શ્રીહરિ મુક્તમુનિ આદિ સંતોને કહેવા લાગ્યા, “કોટિ બ્રહ્માંડોનાં નાડીપ્રાણ પળમાં સંકેલી લેવાં તે અમારે કઠણ નથી. એમ કરવામાં અમે મોટપ પણ માની નથી, પરંતુ અનાદિકાળથી જીવોને અજ્ઞાનરૂપ માયાનું ઘોર તમ વળગ્યું છે, ને તેમાં જ સુખ માની બેઠા છે, તે માયા-અજ્ઞાનને અમે પૂરણ પાપરૂપ દેખીએ છીએ. તે પાપથી સર્વને ઉગારીને નિષ્પાપ કરવા છે. એ અજ્ઞાનરૂપ માયાએ સૌને બેહાલ કરી મૂક્યા છે. પોતે દુઃખી છે તેનું મૂળ આ અજ્ઞાન છે, એવી ખબર એ જીવને નથી, તેથી એ દુઃખમાં સુખ માની બેઠા છે. એ અનાદિ અજ્ઞાનથી જીવને મુક્ત કરવો તે મોટી સામર્થિ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1898,"k":"para","g":"“અમારી વાતોમાં પણ જીવને અનાદિ અજ્ઞાનથી મુક્ત કરવા સંબંધી વાતોનું મુખ્યપણું છે. એ સાંભળીને સૌને તત્કાલ યાદ રાખીને લખી લેવી ને બીજાને તે વાત કરવી. તેમાં અમારી પ્રસન્નતા છે. કોઈ અમારી વાત સાંભળશે કે તેનું અજ્ઞાનરૂપી જાળું તૂટી જશે.”","e":null,"s":["6/80/29-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1899,"k":"para","g":"જીવેન્દ્ર નૃપના ભવનમાં શ્રીહરિ વિરાજતા હતા. નૃપે પ્રાર્થના કરી, “હે પ્રભુ! અમે અલ્પમતિ છીએ. જીવ, દેહ અને જગત સંગાથે જોડાણો છે એ સત્સંગમાં બંધાય. તમે ને તમારા સંત જીવનું બંધન ટાળવાની રીત જાણો છો તો તેનો ઉપાય કહો અને, પ્રભુ! અહીં સદા નિવાસ કરીને રહો. ક્યારેય ઉદાસ થશો નહિ.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1900,"k":"para","g":"ત્યારે શ્રીહરિ બોલ્યા, “અમને રાખવા ઘણું કઠણ કામ છે. અમે અમારા જનને વારંવાર વઢીએ છીએ એ અમારો સહજ સ્વભાવ છે. જીવને ભગવાન સિવાયના જેટલા ઠરાવ છે તે મુકાવી દઈએ છીએ. એ મૂકે પછી તેમાં અમને ભાવ ઊપજે છે. જીવને સંસાર ગમે છે ને તે બાજુ દોડે છે અને અમારી દોટ ભગવાન તરફ છે. સ્વપ્નમાં ચક્રવર્તી રાજાને મળેલું સુખ અસત્ છે તેમ અમે સંસારને સ્વપ્ન જેવો અસત્ જાણીએ છીએ. મોટા ચક્રવર્તી પણ રાજ મૂકીને ગયા છે તેમ બધા લોકનું સુખ નાશવંત છે. જીવવું પોતાના હાથમાં નથી, મનુષ્યમાત્રને મરતાં જુએ છે છતાં આ જીવને ભય થતો નથી. તોપને મોઢે બાંધીને અનંત પકવાન ધરે પણ પલીતો ચાંપે તેટલી જ વાર છે એમ જાણ્યા પછી તેમાં કોને સ્વાદ રહે! એવો પાકો અભાવ જગતના સુખનો થાય ત્યારે વૈરાગ્ય કહેવાય. અનંતકોટિ બ્રહ્માંડના પ્રલયનો વિચાર કરે તો મોહ ટળે. સત્સંગ-કુસંગની રીત ઓળખીને સત્સંગમાં પ્રીત કરે ત્યારે સદ્‌બુદ્ધિ આવે અને સંત ગમે. સંતને પણ ઓળખવા. દોષમાત્રનો ત્યાગ કરી દે તે સંત. કળિયુગની ઓથ લઈ દોષોને પોષે તે અસંત છે. સાચા સંતને ભગવાનનો આશરો હોય અને ખોટાએ કળિયુગનો આશરો લીધો છે.”","e":null,"s":["7/4/1-18, 27-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1901,"k":"para","g":"સરવઈમાં જીવણા ધાધલના દરબારમાં શ્રીહરિ થાળ જમ્યા. વર્ણીને બોલાવી શ્રીહરિએ કહ્યું કે, “સાંજ-સવાર અમે થાળ જમીએ તે બન્ને વખતની પ્રસાદી દરરોજ નિત્યાનંદ સ્વામીને બોલાવીને આપજો. તેમાં ફેર ન પડે. જ્યાં સુધી અમે તેમને પાસે રાખીએ ત્યાં સુધી તેમને થાળ આપજો. અમે જે વાત કરીએ છીએ તેનું રહસ્ય જેટલું હોય તે બધું તેમના હૃદયમાં લખાઈ જાય છે, જે ક્યારેય પણ ભુલાય નહિ એવું તેમનું અંતર સહજ સ્વભાવે છે અને બુદ્ધિનો તો પાર નથી છતાં તેનો તેમને ગર્વ નથી. સદાય અમારી પાસે વિનમ્ર રહે છે. બ્રહ્મા પણ તેમની બુદ્ધિનો પાર પામે નહિ, તેમ અગાધભુદ્ધિ છે.”","e":null,"s":["9/47/9-13"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1902,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ જીવેન્દ્ર નૃપને કહ્યું, “જે કોઈ મોક્ષ માટે પુરુષાર્થ કરે છે એ બધા જન અમારા છે. અમે એવા મોક્ષભાગી જન માટે જ સત્સંગમાં વિચરણ કરીએ છીએ. દેશ-દેશમાં વિચરવાનો બીજો કોઈ અમારે હેતુ નથી.”","e":null,"s":["10/7/38-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1903,"k":"para","g":"કૌકામાં શ્રીહરિએ પોતાની પ્રકૃતિ જણાવતાં કહ્યું, “અમને શહેર અને ઘરથી વન સારું લાગતું. વિકટ ગિરિ વનમાં વર્ણિવેષે ફર્યા અને ધન, નારી, ખાન-પાન વગેરે સંસારી સુખ તજી તપ અને ધ્યાનની રુચિ રાખતા. યોગ સાધના અને કીર્તન-કથામાં પ્રેમ રાખતા. એ પાંચમાં બધાં સાધન આવી ગયાં. સત્સંગનું માહાત્મ્ય ઉદ્ધવ સંપૂર્ણ જાણતા. તેમનાથી અમે કરોડગણું જાણીએ છીએ.”","e":null,"s":["12/58(57)/10-17"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1904,"k":"para","g":"ડભાણમાં વાત કરતાં શ્રીહરિએ કહ્યું, “અમને ત્યાગ બહુ ગમે છે. જ્યારે ત્યાગનો છક આવી જાય છે ત્યારે રોકી શકાતો નથી. અમારી એવી સ્વાભાવિક પ્રકૃતિ છે. અતિ છક આવે ત્યારે દેહનું ભાન પણ રહેતું નથી. જગતમાં જે જે રસ છે તે ત્યાગ આગળ લૂખા છે. બધાયથી ત્યાગનો કેફ અધિક છે. અનંત બ્રહ્માંડનાં સુખ પણ તેને તુચ્છ લાગે છે. ત્યાગવૃત્તિરૂપી નિધિથી ભગવાન સંબંધી સુખ જ દૃષ્ટિમાં આવે છે.”","e":null,"s":["13/21/22-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1905,"k":"para","g":"કુંડળમાં મામૈયા પટગરના ભવનમાં શ્રીહરિએ વાત કરતાં કહ્યું, “દક્ષિણ અને નૈઋત્ય બાજુ જ્યારે કેતુ ઊગે ત્યારે અન્નનો સંગ્રહ કરવો, પણ પશુનો લોભ રાખવો નહિ. (આ સમયે દુકાળ પડે છે.) માટે પશુ વેચીને અનાજ લેજો. કુસંગીને આ વાત કરશો નહિ, કારણ કે ઈશ્વરની વાત અકળ છે. ધારે તેમ ન પણ કરે, કારણ કે ભક્તને આધીન છે. ભક્ત કહે તેમ તે કરે છે. કુસંગીને એ જોઈ અભાવ આવે. જેને અભાવ ન આવે એવા અમારા ડાહ્યા ભક્તોએ બે વર્ષ ચાલે તેટલું અનાજ રાખવું. ઘરખર્ચનો હિસાબ ગણી અનાજ રાખવું ને સાચવી શકાય તેટલાં પશુ રાખવાં. કૂવો, વાડી હોય એણે અન્ન ને ઘાસ કરવું. સોનું રૂપું હશે તો ખાધા-પીધાના કામમાં નહિ આવે. ગોળ-ઘી વિના ચાલશે, પાણી-અનાજ વિના નહિ ચાલે.”","e":null,"s":["14/38/30-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1906,"k":"para","g":"પીપળાવમાં શ્રીહરિ કહે, “ભગવન્નિષ્ઠ સંતની સેવા કરવા માટે અમે માર્ગ શોધતા હતા, તે એક માર્ગ જડ્યો કે જીવતા સુધી દરેક સમૈયાના પ્રસંગે હરિભક્તો સંતોને જમવા રસોઈ આપે, ત્યારે ભાવથી પીરસવું. સત્સંગમાં આવ્યા ત્યારથી આ નિયમ શ્રદ્ધાથી રાખ્યો છે. કોઈ દિવસ ભૂલતા નથી. અંગમાં વ્યથા હોય ત્યારે તો નિર્ધાર રહે નહિ એ અમારો નિયમ છે, તે તમને આજે કહ્યો. બીજો નિયમ એ છે કે સમૈયે સમૈયે એક વાર સંતને મળવું. ધર્મસર્ગને આશ્રિત બ્રાહ્મણથી અંત્યજ સુધી જે કોઈ છે, તેને અંત સમે દર્શન દેવામાં, ગમે ત્યાં તેનો દેહ છૂટે તોપણ, દેશકાળ નડતો નથી. સ્મૃતિ રહે કે ન રહે, પણ અમે તેને ભૂલતા નથી, એ ત્રીજો નિયમ છે તે અમે ક્યારેય કોઈ પણ અવસ્થામાં ભૂલતા નથી.”","e":null,"s":["16/55/3-13"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1907,"k":"para","g":"શ્રીહરિએ મુક્તમુનિને વાત કરતાં કહ્યું, “જેમાં છલ-કપટ નથી એવા જન સાથે મારે અખંડ પ્રીત રહે છે, જે કોઈ રીતે ટાળી ટળતી નથી. જેનામાં રંચમાત્ર કપટ દેખુ છું તેની સાથે ક્યારેય મારે પ્રીતિ થતી નથી. એવો મારો સહજ સ્વભાવ છે.”","e":null,"s":["3/60/18-19"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1908,"k":"para","g":"શ્રીહરિએ વરિષ્ઠબંધુને કહ્યું, “અમારું જે શરણ લેશે તથા દર્શન, સ્પર્શ કરશે તેને માથે કાળ, કર્મ, માયા અને યમનો તાપ નહિ રહે ને વસ્ત્રથી પૂજા કરશે તેનો મોક્ષ થશે. અનંત જીવોનો મોક્ષ કરવા અમે ધાર્યું છે. કંક, કોળી, કણબી વગેરેનો અમે ઉદ્ધાર કરીશું.”","e":null,"s":["1/80/47-49"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1909,"k":"para","g":"માંગરોળમાં શ્રીહરિએ વાત કરતાં કહ્યું, “જ્યારે ભગવાન અનંત જીવોને શરણે લઈ કલ્યાણ કરવા આવે છે, ત્યારે તેમના દોષ-અદોષ ગણતા નથી, પણ પોતાનું બિરુદ વિચારીને અભયપદ આપે છે. જેમ ચક્રવર્તી રાજા પ્રથમ ગાદીએ બેસે ત્યારે કેદીઓને છોડી દે છે, તેમ ભગવાન પણ મોક્ષને માટે જ્યારે પ્રગટે છે ત્યારે તેમનું નામ સાંભળી જે જે જનો આવે, તેમને અભય કરે છે.”","e":null,"s":["3/25/37-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1910,"k":"para","g":"સરધારમાં શ્રીહરિએ મુક્તમુનિને ઉદ્દેશીને એકાંતમાં વાત કરતાં કહ્યું, “અમારું વચન જે માને છે તેને ક્યારેય લેશ પણ દુઃખ આવતું નથી. જેમ જરાસંધે અપાર રાજાઓનાં પુર કબજે કર્યાં હતાં, પરંતુ જે શ્રીકૃષ્ણના શરણમાં આવ્યા તે સૌની રક્ષા તેમણે કરી. તે રીતે જે મારો વિશ્વાસ રાખે છે, તેની હું રક્ષા કરું છું. તેનાં પાપમાત્ર ટાળી દઉં છું, એમાં સંદેહ રાખવો નહીં. હું ધર્મનો લાલ છું; જ્યાં ધર્મ ત્યાં મારો નિવાસ છે. જે મારાં વચન પાળે છે તેની સંગે હું નિવાસ કરું છું. મારા ભક્તોને મારા પ્રાણ કરીને માન્યા છે. હું મારા ભક્તને સદાય આધીન રહું છું. ભક્ત મને ભક્તિએ કરીને બાંધી લે છે. જે જન મારી સાથે પ્રીતિ કરે છે તેનાથી કોટિ ગણી પ્રીતિ હું તેની સાથે કરું છું. જે નિષ્કપટપણે વર્તે છે તેની સાથે મારી પ્રીત ક્યારેય ટળતી નથી. જેનામાં રંચ માત્ર કપટ દેખ્યું તો તે મારી સાથે પ્રીતિ કરવા જાય તોપણ મારે તેની સાથે પ્રીતિ થતી નથી. આ મારો સહજ સ્વભાવ છે તે મેં આજે કહી દેખાડ્યો.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1911,"k":"para","g":"શ્રીહરિની આ વાણીને સાંભળી મુક્તમુનિએ પોતાની હિતકારી માની અને મનમાં દૃઢ નિર્ધાર કર્યો કે શ્રીહરિને ગમીએ તેવા થવું છે. પોતાની મરજીનો ત્યાગ કરી શ્રીહરિની મરજી મુજબ કરવું છે. જ્યારે શ્રીહરિને તન, મન, પ્રાણ અર્પણ કર્યાં ત્યારે હવે પોતાનું છાનું શું રહ્યું? મુક્તમુનિએ આ પ્રસંગ પર આઠ પદ ‘એસી ભક્તિ કરો મન મીતા’ વગેરે બનાવ્યાં છે.","e":null,"s":["3/60/15-22"],"sv":["रक्षा में करूँ तेह, रखे विश्वास जो मोर हि ।\n\n इनमें नहि संदेह, पाप मात्र दिये छोरि के ॥\n\n में हूँ धर्म के लाल, धर्म तिहाँ निवास मोर ।\n\n जो वचन देहु रहे पाल, तब तेहि संग निवास करूँ ॥\n\n मोरे भक्त हैं मोरे ही प्राना । तिनकुं तेसे करि में माना ॥\n\n भक्त के मैं सदा आधिना । भक्त मोय तेहि बाँधि के लिना ॥\n\n मो संग प्रीति करे जन कोई । तिन सें कोटि गनि करू सोई ॥\n\n निष्कपट जो तेहि रहावे । तिन सें मेरी प्रीत न जावे ॥\n\n रंच भर कपट देखुं में तामे । तो कबु न प्रीति रहे यामे ॥\n\n एसो है मेरो सहज स्वभावा । सो तुमकुं सब कहि देखावा ॥\n\n सुनि के मगन भये हरि वानी । मुनिवर लिये हित सो आनी ॥\n\n निज मन में मुनि किन निरधारा । अपने एसो करनो निरधारा ॥\n\n ज्युं हरि मरजी तैंसे करना । आप कि मरजी त्याग हि करना ॥\n\n जब हरिकुं दिये तन मन प्राना । अपनो क्या अब रखना छाना ॥\n\n मुक्तमुनि तेहि पर जोई । आठ पद बनाये सोई ॥\n\n ऐसि भक्ति करो मन मिता । जाकर तरत होउ पुनिता ॥"],"mt":false,"gl":null,"a":false},{"i":1912,"k":"para","g":"કોટડામાં શ્રીહરિ કહે, “ધર્મ-ભક્તિ જે દૃઢ રાખે છે, તેનો હાથ અમે કદી છોડતા નથી. તેનો પરમ મોક્ષ કરવો એ અમારું બિરુદ છે. અમે સૌ હરિભક્તોને અર્થે દેશ-દેશમાં વિચરણ કરીએ છીએ. પ્રીતિ કરીને ધર્મભક્તિમાં તેની વૃદ્ધિ કરાવીએ છીએ.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1913,"k":"verse","g":"‘ધર્મ-ભક્તિ કું રખે દૃઢ જાહિ, કબહું મેં ન છોડૂઁ તાહિ,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1914,"k":"verse","g":"એસો હૈ અબ બિરદ હમારે, પરમ મોક્ષ કરન તુમ્હારે.’","e":null,"s":["5/38/4-5"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1915,"k":"para","g":"જેતપુરના રાજાએ શ્રીહરિની વિદાયવેળાએ પ્રાર્થના કરતાં કહ્યું, “અમે તમારી પાસે રહીએ ને દેહ પર્યંત રાજ્ય બંધન કરે નહિ એવો વર આપો.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1916,"k":"para","g":"ત્યારે શ્રીહરિ કહે, “અમારું ભજન કરો તો રાજ્ય બંધન નહિ કરે. જે અમારું ભજન કરે છે તેની પાસે અમે નિરંતર રહીએ છીએ, પણ એ વાત સમજણમાં આવતી નથી.”","e":null,"s":["6/49/29-30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1917,"k":"para","g":"જેતપુરના રસ્તે શ્રીહરિ કહે, “અમારી પ્રકૃતિ એવી છે કે દેહ અને દેહના સંબંધી ઉપર ક્યારેય પણ હેત રાખતા નથી અને હરિભક્તો, સંતો ઉપર દેહ કુરબાન કરીએ છીએ. તેને અર્થે જેટલું થાય તેટલું સફળ છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1918,"k":"verse","g":"‘શ્રીહરિ પુનિ કહત હે, પ્રકૃતિ હમાર હે એહ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1919,"k":"verse","g":"દેહ દેહ કે સંબંધિ મેં, રખત ન કબઉ નેહ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1920,"k":"verse","g":"હરિસંત હરિજન ઉપરિ, દેહ કરત કુરબાન.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1921,"k":"verse","g":"તેહિ અર્થ જિતનો આવહિ, તિતનો હિ ફલ માન.’","e":null,"s":["6/50/1-2"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1922,"k":"para","g":"જેતપુરમાં શ્રીહરિ કહે, “હું આકાશ જેવો નિર્બંધ છું, કોઈના બંધનમાં આવું તેવો નથી, પણ જેનામાં અપાર સાધુતા દેખું છું તેના બંધનમાં આવું છું અને ત્યાંથી છૂટી શકતો નથી. દેવ, મનુષ્યો અને દૈત્યને મારી સાથે વૈર નથી હોતું, પણ સાધુનો પક્ષ રાખું છું ત્યારે તે મારી સાથે વૈર કરે છે.”","e":null,"s":["6/60/17-18"],"sv":["मैं निर्बंध हूँ आकाश हि जैसा । कोईके बंधन में आवे न ऐसा ॥\n\n साधुता जामें देखूं अनंता । ताके बंधन में आई रहंता ॥\n\n साधुता देखूं ज्या लगहि । तिहां से छुटाय न त्यां लगहि ॥\n\n मोसंग वैर नहि है केहा । देव मनुष्य दैत्य लग तेहा ॥\n\n साधु को रखूं पक्ष में जबहु । मो संग वेर बांधत तबहु ॥"],"mt":false,"gl":null,"a":false},{"i":1923,"k":"para","g":"જેતલપુરમાં શ્રીહરિએ કહ્યું, “અમારે તો હરિભક્તોને બ્રહ્મરૂપ કરવા એટલો જ ઘાટ છે. તેને માટે વિચરણ કરીએ છીએ, કોઈ સ્થાને ઠરીને બેસતા નથી. બીજા જાણે કે ન જાણે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1924,"k":"verse","g":"‘હરિજન બ્રહ્મરૂપ હિ કરનાં, તેહિ હિત હેં હમારો વિચરનાં,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1925,"k":"verse","g":"એહિ વિન ઘાટ નહિ મન ઓરા, એહિ હિત ઠરત નહિ એક ઠોરા.’","e":null,"s":["8/20(19)/34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1926,"k":"para","g":"શ્રીહરિ શેખપાટ પધાર્યા ત્યારે લાલજી સુથારને માથામાં ચોટ લાગવાથી મૂર્છિત થઈ ગયા હતા. તેમનાં માતુશ્રી તેને મૃત જાણી રડવા લાગ્યાં ને શ્રીહરિને કહ્યું, “લાલજીને જીવતો કરો.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1927,"k":"para","g":"શ્રીહરિ કહે, “અમે મારનારા નથી કે મરેલાને જિવાડવાનું અમને આવડતું નથી. જો અમને જિવાડતાં આવડતું હોત તો ગુરુ રામાનંદ સ્વામીને અમે તરત જ જિવાડત. અમને તો એવું જિવાડતાં આવડે છે કે ફરી મરવું જ ન પડે. તે વિના તો મરેલાને જિવાડે તોપણ તેને અમે મરેલો જ માનીએ છીએ. માયિક દેહનો તો મરણ જ ધર્મ છે. જીવ ક્યારેય મરતો નથી.” એમ કહી શ્રીહરિ કહે, “લાલજી મર્યા નથી, પણ મૂર્છિત થયા છે.” પછી શ્રીહરિએ જાતે પાટો બાંધ્યો ને ઘા રુઝાવ્યો. શીરો જમાડીને સાજા કર્યા.","e":null,"s":["10/26/3-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1928,"k":"para","g":"શાપુરમાં શ્રીહરિ કહે, “અમે તો સદા નિર્બંધ છીએ, અમારા દેહનો પણ અમને વિશ્વાસ નથી, અમે અનંતકોટિ બ્રહ્માંડના મુકામ અને ભોગને ચલાયમાન દેખી અમારા અચળ મુકામ અક્ષરધામમાં સદા રહીએ છીએ. પિંડ-બ્રહ્માંડના સુખમાં અમે ક્યારેય બંધાતા નથી. જે ત્યાગી-ગૃહી અમારી સાથે હેત રાખે, અમારી રીતિ પ્રમાણે વર્તે, અમારો વિશ્વાસ રાખે તેને અમે મોક્ષ કરવાનો કોલ આપીએ છીએ. અમને લલચાવવા કરે તે અમને ગમતો નથી. આશાવાળા લોકો લલચાય. અમારે કોઈ આશા નથી. લલચાવે તેને ત્યાં એક રાત પણ અમે રહેતા નથી, અને જેને ભગવાનમાં પ્રેમ હોય અને પિંડ-બ્રહ્માંડનો અભાવ હોય તે અમારો અનાદર કરે તો પણ અમે તેને છોડતા નથી, કારણ કે એવા ભક્તો જ અમારે કુટુંબ-પરિવાર છે. તેનાથી અમે પલવાર છેટે રહેતા નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1929,"k":"para","g":"“ગામ, ગરાસ કે ધન-માલ ભૂપાળ જો શ્રીહરિના ચરણે કરી રાખે તો તેને અમે બંધન માનતા નથી. ભગવાનથી જે વિમુખ રાખે તેને અમે બંધનરૂપ માનીએ છીએ. ત્રણેય અવસ્થામાં અમને એવી વૃત્તિ રહે છે.”","e":null,"s":["12/85/26-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1930,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સ્વરૂપાનંદ સ્વામીની સેવામાં રહેલા નિષ્કુળાનંદ સ્વામી તથા પરમહંસાનંદ સ્વામીની પ્રશંસા કરી, પછી કહ્યું, “પોતાનામાં દોષ જુએ ને સત્સંગમાં બધાના ગુણ ગાતો રહે તેને અંત સમે ભગવાન તેડી જાય છે ને તેનો મોક્ષ કરે છે. જે ભગવાન અને સંતમાં દોષ કલ્પે છે તેને જમદૂતો લઈ જાય છે. લખચોરાસીમાં નાખે છે. ફરી એકવાર તેને સત્સંગનો યોગ ભગવાન આપે છે ને તેનો મોક્ષ કરે છે. ભગવાનને પોતાના બિરુદ પર તાન છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1931,"k":"para","g":"“શુદ્ધ પવિત્રપણે રહી સત્સંગ કરે તેનો અણુ જેટલો ગુણ પણ ભગવાન મેરુ જેટલો માની લે છે. ભગવાન એ ગુણ અનંત કલ્પ સુધી પણ ભૂલતા નથી, તેને અપાર સુખ આપે છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1932,"k":"verse","g":"‘અનુ જિતનો ગુન હોય જાહિ, મેરુ જેતો સુખ દેવત તાહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1933,"k":"verse","g":"અનંત કલ્પ હોઈ જાવે જોઉ, ભગવાન કબુ ન ભૂલત સોઉ.’","e":null,"s":["15/47/17-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1934,"k":"para","g":"વડનગરમાં શ્રીહરિએ વાત કરતાં કહ્યું, “સહુનો મોક્ષ કરવો તે અમારો સિદ્ધાંત છે. અને તે અમને સહુથી વધારે ગમે છે. સહુ કોઈનું હિત કરવું એવી અમારી સ્વાભાવિક રુચિ છે. મોક્ષમાર્ગે ચાલવું તે જ સૌથી અધિક છે. બધાનું હિત થાય એમ જ અમારી ઇચ્છા છે.”","e":null,"s":["18/47/9-10"],"sv":[],"mt":false,"gl":null,"a":false}]},{"n":24,"gu":"માન-મોટપ","en":"Mān-Motap — Ego and Status","url":"https://www.anirdesh.com/pbp/index.php?page=chp_24","b":[{"i":1935,"k":"para","g":"સુખપુરમાં શ્રીહરિએ રાવત ધાધલ નૃપને વાત કરતાં કહ્યું, “જે ભક્ત થયો તેને તો ભગવાનના વચનનું પાલન કરવાનું દૃઢ માન હોય, બીજું માન હોય નહિ. જ્યાં સુધી ઘટમાં પ્રાણ છે, ત્યાં સુધી એ વચન પાલન કરે છે. વિષમ દેશકાળે પણ વચન બહાર પગ ભરતો નથી. જેમ ધજા પવનની દિશા અનુસાર વારંવાર વહેવાની દિશા બદલે છે, તેમ ભક્ત પણ પોતાનું ધાર્યું મૂકી ભગવાન ને સંત કહે તે દિશા પકડી રાખે તે સર્વે ભક્તોમાં શિરદાર છે, મોટો છે.”","e":"Speaking to Rawat Dhadhal Nrip in Sukhpur, Srihari said, \"A devotee who has become a devotee should have a firm respect for obeying God's promise, there is no other respect. As long as there is life in him, he keeps his promise. Even in odd seasons, he does not step outside the promise. Just as the stream changes its direction frequently according to the direction of the wind, so also a devotee who assumes that God calls him a saint and holds to the direction is the leader among all the devotees. is big.”","s":["6/5/37-38"],"sv":[],"mt":true,"gl":null,"a":false},{"i":1936,"k":"para","g":"ભુજમાં શ્રીહરિ કહે, “મોટાને અમે સત્સંગ કરાવતા નથી, કારણ કે તે આખા સત્સંગને ડુબાડે. ધાર્યું તો ઈશ્વરનું થાય છે, તોપણ અંતરમાં ડરતા રહીએ છીએ. કરંડિયામાં સર્પ નાખીને ગરુડી જો ગાફેલ રહે તો પ્રાણ ખુએ. તેમ એવા અમલવાળા જે મોટા તે પણ અગ્નિ જેમ સ્પર્શ કરતાં જ ગુણ જણાવે તેવા પરાક્રમવાળા હોય છે. મોટા મોટા ભૂપોએ સત્સંગ જાણ્યો નથી, ત્યાં સુધી હરિભક્તને આનંદ છે. આ સભામાં સાચા હરિભક્તો વિના કોઈ નજરે આવતો નથી, પરંતુ એવા મોટા ભળે ત્યારે આવું રહેવું કઠણ છે.”","e":"In Bhuj Srihari says, \"We don't do satsang to the big one, because it drowns the whole satsang. If we think it is from God, we are still afraid in the distance. An eagle with a snake in its fangs will die if it is heedless. Even those big ones are capable of telling the virtues just by touching them like fire. Big big bhupas have not known satsang, till then. A Haribhakta is happy. No one is seen in this meeting without a true Haribhakta, but it is difficult to remain so when there is such a large crowd.\"","s":["7/10/22-30"],"sv":[],"mt":true,"gl":null,"a":false},{"i":1937,"k":"para","g":"ઝીંઝાવદરમાં અલર્ક નૃપને શ્રીહરિએ વાત કરતાં કહ્યું, “માન બધાં કામ બગાડી નાખે છે. સત્સંગ કર્યા વિના માન ટળવું અશક્ય છે અને અજ્ઞાન એ જ માનનું મૂળ છે. સત્સંગ કરે છતાં માન રહી જાય, તે મટવું બહુ કઠણ છે. માનનું કોઈ ખંડન કરે તો તે સંત હોય કે ભગવાન હોય તોપણ જગતથી પણ તેનો અધિક અભાવ આવે. અને એનું માથું ફરી જાય કે સંતને સંત અને ભગવાનને ભગવાન પણ માને નહિ. જ્યારે માન ખંડન થાય ત્યારે જો ભગવાનનો ખપ હોય તો લગારેય ખસે નહિ. માન નજરે દેખાતું નથી, પણ માન વિનાના બધા રસ ખોટા લાગે છે.","e":"Talking to Alark Nirpan in Jhinjavdar, Srihari said, \"Respect destroys all work. It is impossible to avoid respect without doing satsang and ignorance is the root of respect. Even if you do satsang, respect remains, it is very difficult to get rid of it. If someone refutes respect, whether he is a saint or a god, the world also lacks him. And his head turns that a saint is a saint and a god is also a god.\" Do not believe. When respect is rejected, if God is pleased, respect is not visible, but all interests without respect seem wrong.","s":[],"sv":[],"mt":true,"gl":null,"a":false},{"i":1938,"k":"para","g":"“સંતને મોક્ષદાતા જાણે ને દાસ થઈને સત્સંગ કરે તેને માન આવે નહિ. સૌ પાપોમાં મોટું પાપ અને સૌ કલંકમાં મોટું કલંક માન છે. સત્સંગ તો બિલોરી કાચ જેવો નિર્મળ છે. દર્પણમાં જેવું પોતાનું રૂપ હોય તેવું દેખાય. કાચનો જે દોષ દેખે એ કુબુદ્ધિ કહેવાય. તેમ સત્સંગનો દોષ જોનારને પણ તેવો જ જાણવો.”","e":"\"He who performs satsang as a slave knowing that a saint is a savior will not be respected. Sin is the greatest of all sins and the greatest stigma of all taints. Satsang is as clear as a clear glass. It looks as if it has its own image in a mirror. The one who sees the flaw in the glass is called kubuddhi. Similarly, the one who sees the flaw in satsang should know the same.\"","s":["9/41(42)/10-28"],"sv":[],"mt":true,"gl":null,"a":false},{"i":1939,"k":"para","g":"મુક્તમુનિએ શ્રીહરિએ કહેલી વાતો ગઢપુરમાં કહી કે, “શ્રીહરિ કહેતા કે - હું માન હોય તેને પગે લાગતો નથી, પરંતુ જે હરિ ને હરિજનનો દાસ થયો તે ભક્તને સર્વોપરી માનું છું. આ અમારા નિશ્ચય જેવો જેને મતિમાં નિશ્ચય હશે તેને કદી માન નહિ આવે. અમારું ધામ સર્વોપરી છે. તેના નિવાસી આ સર્વે હરિજન છે. આવી બુદ્ધિ સદા જેને હોય તેને ક્યારેય માન આવતું નથી.","e":"Muktmuni said what Srihari had said in Garhpur, \"Srihari used to say that - I do not trample on those who have respect, but I consider the devotee who has become a slave of Hari to be supreme. This is like our determination. He who is determined in his opinion will never be respected. Our abode is supreme. Its inhabitants are all Harijans. He who has such intelligence will never be respected.\"","s":[],"sv":[],"mt":true,"gl":null,"a":false},{"i":1940,"k":"para","g":"“હરિજનને આ લોકના સમજે છે તેના હૃદયમાં કામ, ક્રોધ, લોભનાં પૂર આવ્યાં કરે છે. તેમાં તે તણાયા કરે છે ને અધર્મવંશથી દુઃખી થાય છે.”","e":"\"A Harijan who perceives this world fills his heart with work, anger and greed. He is strained and saddened by iniquity.\"","s":["11/87/30-35"],"sv":[],"mt":true,"gl":null,"a":false},{"i":1941,"k":"para","g":"કરિયાણામાં આવેલા નાગર સેનાપતિને શ્રીહરિએ વાત કરતાં કહ્યું, “ભગવાનના સંબંધ વિનાની મોટપ કાકતીર્થ જેવી છે. કાગડો પશુ-પંખીમાં નીચ યોનિ કહેવાય છે, તે મડદાંને ચૂંથે છે. નીચ હોય તે મડદામાં માલ માને છે. હંસ ઉત્તમ પંખી છે. તેનો આહાર દૂધ અને મોતી છે. કાગડાને તે દૂરથી પણ ગમે નહિ. ભગવાનના ભક્ત હંસ સમાન છે. તે તો ભગવાનના ચરિત્રરૂપી મોતીનો ચારો કરે છે અને અક્ષરધામને પામે છે.”","e":"Speaking to the Nagar Senapati, who was in the grocery store, Srihari said, \"A fat man without God's relation is like a crow. The crow is called the ugly vagina among animals and birds, it picks at the help. The ugly one considers the help to be good. The goose is an excellent bird. Its diet is milk and pearls. The crow does not like it even remotely. A devotee of God is like a goose. He is God's.\" Charitrarupi forages pearls and attains Akshardham.”","s":["13/31/17-22"],"sv":[],"mt":true,"gl":null,"a":false},{"i":1942,"k":"para","g":"સારંગપુરના જીવાખાચરના દરબારમાં શ્રીહરિએ હરિજનોને કહ્યું, “ધન-સ્ત્રીને ત્યાગે પણ માનરૂપી વિષ તેથી પણ ભારે છે. માનરૂપી વિષ જેમાં આવે તે સંતમાં બ્રહ્માને પણ દુર્લભ એવા ઉત્તમ ગુણો હોય તે દોષરૂપ થઈ જાય છે. જે ગુણ છે તે જ સ્વયં મોટાઈ રૂપ છે. જેમ ગુણ આવે તેમ દીન થાય અને સંતને આધીન રહે ત્યાં સુધી ગુણ શોભે છે.”","e":"In Sarangpur's Jivakhachar court, Sri Hari said to the Harijans, \"Even if one abandons wealth and women, the poison of honor is even worse. The saint who has great qualities that are rare even for Brahma becomes a fault. The virtue that is rare is itself magnanimity. As soon as the virtue comes, it becomes humble and remains subservient to the saint.\"","s":["14/83/30-33"],"sv":[],"mt":true,"gl":null,"a":false},{"i":1943,"k":"para","g":"મુક્તમુનિને તવરા મેળામાં મોકલતી વખતે શ્રીહરિ કહે, “માનથી જે ડરે છે તેને અમે પૂજાની મોટપ આપીએ છીએ. માનમાં દોષ દેખે તેને માન આવતું નથી. તમારા જીવમાં જો માનનો અંકુર દેખાય તો સંત-હરિભક્તનાં ચરણની રજ પૂજા થઈ રહ્યા પછી માથે ચઢાવજો. તેના પ્રતાપે માન નહિ આવે.”","e":"While sending Muktamuni to Tavara Mela, Sri Hari said, \"We give honor to those who are afraid of honor. He who sees fault in honor will not be respected. If a sprout of honor appears in your life, then worship the feet of the Saint-Haribhakta after worshiping. His glory will not be respected.\"","s":["14/94(95)/23-24"],"sv":[],"mt":true,"gl":null,"a":false},{"i":1944,"k":"para","g":"અલર્ક રાજાના ભવનમાં શ્રીહરિએ વાત કરતાં કહ્યું, “સંત-હરિભક્તમાં કોઈ જાતનો છક દેખાય તેટલો તેનો અમને ડર લાગે છે. ભક્તિ-ધર્મ વગેરે ગુણનો છક છે તે વિઘ્નરૂપ છે. છક મોટાઈ રહેવા દેતો નથી. વસ્ત્ર વિનાનો માણસ સભામાં જેવો શોભે તેવો છકવાળો માણસ શોભે. જેટલો છક છે તેટલી તુચ્છતા ગણાય. જેટલી નમ્રતા છે તેટલી મોટાઈ ગણાય. નમ્રતા વિના મોટાઈ શોભે નહિ. વિદ્યાનું ફળ નમ્રતા છે. સારાં વસ્ત્ર-આભૂષણ પહેર્યાં હોય તોપણ નમ્રતાથી શોભે છે. બીજા ગુણ ઘણા મેળવ્યા હોય, પણ નમ્રતા ન હોય તો તે ગુણ ઝેરરૂપ છે. પારસમણિ તથા ચિંતામણિ તથા બીજી રિદ્ધિ-સિદ્ધિ પામે, પણ નમ્રતા ન આવે ત્યાં સુધી મોટપ શોભે નહિ. સારા ભોજનમાં ઝેર પડે તો બધું ઝેર થાય, તેમ છક ઝેરરૂપ છે.”","e":"Speaking in the palace of Alark Raja, Srihari said, \"We are afraid of any kind of mole in a Saint-Haribhakta. It is a mole of virtues such as devotion-religion, etc. It is disruptive. The mole does not allow to grow. A man without clothes adorns a man with moles as he adorns a meeting. The more moles are considered insignificant. The more humility there is, the greater is considered. The fruit of learning is modesty. Even if you wear good clothes, you are beautiful. If you don't have modesty, it's poisonous. But if you don't have modesty, everything is poisoned.","s":["14/13/29-36"],"sv":[],"mt":true,"gl":null,"a":false},{"i":1945,"k":"para","g":"કુંડળમાં મામૈયા પટગરના ભવનમાં રાજાઓ પ્રત્યે શ્રીહરિએ વાત કરતાં કહ્યું, “જેને સત્સંગનો દિવસે દિવસે અધિક રંગ ચઢાવવો હોય, તેણે એવા સંત-હરિજનનો સંગ કરવો જેનો રંગ અપમાનમાં પણ ઝાંખો થતો ન હોય. સાધુ હોય કે હરિભક્ત બન્નેમાં જેને માન હોય તેટલો કુસંગ છે ને તે ક્ષય રોગ સમાન છે. જે સંત હરિભક્તો નિર્માની થઈને સરળ વર્તે છે તેમનો શુદ્ધ સત્સંગ છે. જેનો જીવ જેવી રીતે વર્તતો હોય તે તેવું વચન ઉચ્ચારે છે. સંત-હરિભક્તની મોટાઈ જે સમજે છે અને તેમનાં દર્શનથી જેનું અંતર ઠરે છે, તેને વિઘ્ન નડતાં નથી. દાસભાવ ન હોય તો મેરુ સમાન ગુણ હોય તોપણ શોભતા નથી.","e":"Speaking to the kings in the palace of Mamaiya Patgar in Kundal, Srihari said, \"Whoever wants to increase the color of satsang day by day, should associate with a saint-Harijan whose color does not fade even in insults. Whether it is a monk or a Haribhakta, whoever has kusang as much as respect is like tuberculosis. A saint who is a Haribhakta and behaves easily is pure. He who behaves like a saint, who understands the greatness of a devotee, and who is distanced from his vision, is not disturbed even if he has the same qualities as me.","s":[],"sv":[],"mt":true,"gl":null,"a":false},{"i":1946,"k":"para","g":"“અનંત ધ્યાન-ધારણા કરતો હોય, ભૂત-ભવિષ્ય ને વર્તમાન કહેતો હોય, અંતરની વાત જાણતો હોય, અનંત જીવોની નાડી તાણતો હોય, અનંત પરાક્રમ કરતો હોય તોપણ જો દાસપણું ન હોય તો અંક વિનાના શૂન્ય જેવું છે.","e":"\"The infinite meditates, calls the past and future the present, knows the distance, stretches the pulse of the infinite beings, performs infinite prowess, but if there is no servitude, it is like a numberless zero.","s":[],"sv":[],"mt":true,"gl":null,"a":false},{"i":1947,"k":"para","g":"“ભગવાન બધા અપરાધને ક્ષમા કરે છે, પણ પોતાના દાસને જે પીડે છે તેને સહન કરતા નથી. દાસના ઉરમાં શ્રીહરિ નિવાસ કરીને રહે છે. તેના પ્રત્યેક ગુણરૂપે શ્રીહરિ રહ્યા છે. ભગવાન સમર્થ હોવા છતાં પોતે જ્યારે મનુષ્ય તન ધારે છે ત્યારે દાસની પેઠે વર્તે છે ને ભક્ત કહે તેમ કરે છે. માન રાખતા નથી. ભગવાન સમુદ્ર સમાન બધા ગુણોના નિધાન છે. સંત-હરિભક્તો સરોવર સમાન છે. તેમાં થોડા ગુણો ટકે છે. સરોવર પુરાઈ જાય તો જળ ટકે નહિ. તેમ માનરૂપી કાદવ ભરાતાં શુભગુણ ટકતા નથી.","e":"\"The Lord forgives all offences, but does not bear the sufferings of His servant. Srihari resides in the servant's ur. Srihari remains in every quality. Though God is powerful, when He assumes human form, He acts like a servant and does as the devotee says. He does not respect. God is like an ocean, the reservoir of all qualities. Saints and devotees are like a lake. A few qualities remain in it. Sarovar If it runs out, the water will not last.","s":[],"sv":[],"mt":true,"gl":null,"a":false},{"i":1948,"k":"para","g":"“સંત-હરિભક્તનું કોઈ ઘસાતું બોલે ને તેની અદબ ન રાખે તો તેને બ્રહ્મવેત્તા સંતની હત્યા જેટલું પાપ લાગે છે. સંત-હરિભક્તોના દ્રોહ સમાન કોઈ પાપ નથી અને તે પાપનું પ્રાયશ્ચિત્ત નથી. માટે સંત હરિભક્તોના ગુણ ઉચ્ચારવા, દોષ બોલે તેણે સત્સંગ કર્યો જ નથી.”","e":"\"If someone speaks abusively of a Saint-Haribhakta and does not respect him, he feels as guilty as killing a Brahmavetta saint. There is no sin like betrayal of Saint-Haribhaktas and it is not an atonement for that sin. Therefore, if he praises the virtues of Saint Haribhaktas, he has not done satsang.\"","s":["16/39/1-37"],"sv":[],"mt":true,"gl":null,"a":false},{"i":1949,"k":"para","g":"ગઢપુરમાં ઉત્તમના દરબારમાં ધર્મપુરની વાત શ્રીહરિએ હરિજનોને કરતાં કહ્યું, “ભગવાનના ભક્તમાં લગારેય માન આવે તે ભગવાન સહન કરતા નથી. દોષમાત્રને પ્રવેશવાનું મહાદ્વાર માન છે. જ્યાં સુધી ભક્તમાં માનનો ઉદય ન હોય અને નિર્માની રહેતો હોય ત્યાં સુધી તે સત્સંગમાં વૃદ્ધિ પામતો રહે છે. પણ જેવું માન આવ્યું કે તરત તે ભક્ત ધીરે ધીરે ઘટી જાય છે. હરિજનમાં જેટલો નિર્માની ગુણ તે તેટલો મોટો. માનરૂપી રોગ જીવને ઉદ્વેગ કરાવે છે. અને ભગવાનથી વિમુખ કરે છે. મનને મતે ચાલે તે માની છે. અને તેના પર ભગવાનનો કોપ થાય છે. માનરૂપી વિષ પીને પણ માની માણસ પોતાની બડાઈ સમજે છે પણ તેમાં તે બહુ દુઃખી થાય છે.”","e":"Shri Hari told the Harijans about Dharmapur in the court of Uttam in Garhpur, \"God does not tolerate a lack of respect in a devotee of God. Respect is the only entrance to evil. As long as respect does not rise in a devotee and Nirmani remains, he continues to grow in Satsang. But as soon as he has respect, the devotee gradually declines. The more Nirma in a Harijan, That's how big it is. Manipuri makes the soul estranged from God. Manipuri also gets angry at him, but he gets very sad about it.\"","s":["16/46/12-21"],"sv":[],"mt":true,"gl":null,"a":false},{"i":1950,"k":"para","g":"વડતાલમાં શ્રીહરિએ વાત કરતાં કહ્યું, “સાંખ્યનિષ્ઠા, યોગનિષ્ઠા, ધર્મનિષ્ઠા, ભક્તિનિષ્ઠા, સ્વરૂપનિષ્ઠા હોય, પણ જો તેમાં માન હોય તો તેના બધા ગુણ નાશ પામે છે. માનમાં દોષમાત્ર વસે છે.”","e":"Speaking in Vadtal, Srihari said, \"Sankhyanishtha, yoganishtha, dharmanishtha, bhaktinishtha, swarupanishtha, but if there is respect in it, all its virtues are destroyed. Only dosha resides in respect.\"","s":["17/41/22-24"],"sv":[],"mt":true,"gl":null,"a":false},{"i":1951,"k":"para","g":"લોયામાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “ધનનો મદ ચઢે છે ત્યારે ભગવાનમાં રુચિ રહેતી નથી. ધનનો દાસ થઈને રહે તેની પાસે ભગવાન રહેતા નથી. ભગવાન હોય ત્યાં ધર્મ, ભક્તિ, જ્ઞાન, વૈરાગ્ય રહેલાં છે.”","e":"Speaking to the saints in Loya, Srihari said, \"When wealth increases, there is no interest in God. He who remains a slave to wealth does not have God. Where there is God, there is religion, devotion, knowledge, dispassion.\"","s":["24/66/34, 40"],"sv":[],"mt":true,"gl":null,"a":false}]},{"n":25,"gu":"સુખ-દુઃખ","en":"Sukh-Dukh — Happiness and Misery","url":"https://www.anirdesh.com/pbp/index.php?page=chp_25","b":[{"i":1952,"k":"para","g":"ભુજમાં શ્રીહરિએ વાત કરતાં કહ્યું, “અમારે અધિકારનો મોહ નથી. પાતાળથી સત્યલોક સુધી અને પ્રકૃતિ-પુરુષ સુધીના સુખમાં અમે જમપુરીથી વધારે દુઃખ માનીએ છીએ. ભગવાનની સ્મૃતિ ભુલાવે તે બધાં દુઃખ જ છે. ભગવાનની વિસ્મૃતિ કરાવે એવાં વૈકુંઠનાં સુખ હોય તોપણ તેમાં અમારું મન ટકે નહિ. બીજા લોકો અમને માને કે ન માને પણ ભગવાનમાં અખંડ ચિત્ત રહે તે જ મોટો અધિકાર છે, એમ અમે માન્યું છે. હરિભક્તના દાસાનુદાસ થઈને રહેવું છે એટલો મનમાં ઘાટ રહે છે. ધર્મ, ભક્તિ, વૈરાગ્ય અને જ્ઞાન તેને રાખવાનું નિશદિન તાન રહે છે. બીજાને પણ તેનો રંગ લગાડી દેવાનું મનમાં તાન રહે છે. ખાવું-પીવું, ઓઢવું-પહેરવું કે શ્રેષ્ઠ વાહન પર બેસવું, તે સઘળું મહાદુઃખરૂપ સમજીએ છીએ.”","e":"At Bhuj, while talking, Shriharí said, “We have no attachment to position or authority. The happiness that lies anywhere from Patal up to Satyalok, and up to Prakruti-Purush, we consider to be greater misery than Yampuri. Whatever makes one forget the remembrance of Bhagwan is nothing but misery. Even if the happiness of Vaikunth were such that it caused forgetfulness of Bhagwan, our mind would not stay in it. Whether others regard us highly or not, we have held this to be the great position: that the mind remains unbrokenly fixed on Bhagwan. The one intention that stays in our mind is to remain the servant of the servants of the haribhaktas. Day and night we are absorbed in preserving dharma, bhakti, vairagya and gnan — and in colouring others with them as well. Eating and drinking, clothing and covering, or riding upon a fine vehicle — all of this we understand to be a form of great misery.”","s":["5/58/31-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1953,"k":"para","g":"કડીમાં નૃપને શ્રીહરિએ વાત કરતાં કહ્યું, “સુખમાત્ર સમજણમાં છે. જેણે ભગવાનને રાખ્યા છે તેની પાસે સુખ સદાય રહે છે. એવું માને તેને પણ સુખ મળે છે. અલૌકિક સમજણ વિના તો ફાવે તેવી મોટી સ્થિતિમાં પણ દુઃખી સમજે છે. માટે અનંત સુખ સમજણમાં જ રહ્યું છે.","e":"At Kadi, while talking with the king, Shriharí said, “Happiness lies entirely in one’s understanding. Happiness abides forever with the one who has kept Bhagwan. And whoever understands this also attains happiness. Without this transcendental understanding, a person feels miserable even in whatever grand circumstances he may be in. Therefore infinite happiness rests in understanding alone.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1954,"k":"para","g":"“જેટલાં બ્રહ્માંડનાં દુઃખો છે તે રાજ્યના સુખમાં રહેલાં છે. એટલે રાજપાટના સુખને લેશ પણ સુખ માનવું નહિ. રાજનું સુખ વિષ સમાન છે. પ્રહ્‌લાદ, પ્રિયવ્રત, ઋષભદેવ, ચિત્રકેતુ, ઉત્તાનપાદ, પાંચ પાંડવ - એ સર્વેએ રાજ કરતાં વનમાં જઈ પ્રભુ-સ્મરણમાં અધિક સુખ માન્યું હતું. જેથી રાજનો ત્યાગ કરતાં વાર ન લાગી. જેટલો અધિકાર એટલું દુઃખ. રાજ-અધિકાર થોડો એટલું દુઃખ ઓછું. ખરું સુખ તો ભગવાન ભજવામાં જ છે, જેટલા ભજાય તેટલો લાભ. દુઃખ થાય તેવું સુખ દેતા અમને આવડતું નથી. ફરી ક્યારેય દુઃખ ન આવે એવું સુખ દેતાં અમને આવડે છે.”","e":"“All the miseries of the brahmands reside within the happiness of a kingdom. So one should not consider the happiness of a throne to be happiness in the least. The happiness of kingship is like poison. Prahlad, Priyavrat, Rushabhdev, Chitraketu, Uttanpad, the five Pandavs — all of them considered the remembrance of God in the forest to be greater happiness than ruling. So it took them no time at all to renounce their kingdoms. The greater the authority, the greater the misery. The less the authority of rule, the less the misery. True happiness lies only in worshipping Bhagwan; the more one worships, the greater the gain. We do not know how to give a happiness that turns into misery. We know how to give a happiness after which misery never comes again.”","s":["7/35/4-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1955,"k":"para","g":"જેતલપુરના મહોલમાં શ્રીહરિએ સત્સંગ કરવાની રીત હરિજનોને કહી કે, “જપ, તપ, દાન આદિક ધર્મ શુદ્ધ થઈને પાળે ત્યારે દેવલોકનું સુખ પામે અને મનોવાંછિત ભોગ મળે, પણ હરિ ભજવાની શુદ્ધિ રહે નહિ. પ્રલયમાં જ્યારે ભોગ નાશ પામે ત્યારે અલ્પ દેહમાં જન્મવું પડે. તેથી કરીને દેવલોકને નરકના ખાડા જેવો કહ્યો છે. હરિના સંબંધ વિનાનાં જે બ્રહ્મલોક પર્યંતનાં સુખ તે બધાં પ્રાકૃત ગણાય.”","e":"In the mansion at Jetalpur, Shriharí told the harijans the method of doing satsang: “When one observes purely the dharma of japa, tapa, charity and the rest, one attains the happiness of Devlok and receives the enjoyments one desires — but the purity of worshipping Hari does not remain. When those enjoyments perish at the time of dissolution, one has to be born in a lowly body. For this reason Devlok has been called a pit of hell. All the happiness up to Brahmalok that has no relation with Hari is to be counted as worldly.”","s":["8/20(19)/19-22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1956,"k":"para","g":"વડતાલમાં શ્રીહરિ કહે, “માયિક સુખમાં જ્યાં સુધી રાગ છે ત્યાં સુધી અમાયિક સુખ ન જ મળે અને ભવભટકણ પણ મટે નહિ.”","e":"At Vartal, Shriharí said, “As long as there is attachment to mayik happiness, amayik happiness simply cannot be attained, nor does the wandering through births come to an end.”","s":["9/3/17"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1957,"k":"para","g":"શ્રીહરિએ જીવેન્દ્ર નૃપને વાત કરતાં કહ્યું, “જ્ઞાનરૂપી નેત્રથી અંતરમાં તપાસે ત્યારે વિપરીત મતિ જોવામાં આવે. જીવ દેહમાં રહ્યો છે ત્યાં સુધી તેને ગુણનો સંબંધ છે. તેમાં સત્ત્વગુણ તે શુદ્ધ છે. તમોગુણ, રજોગુણમાં અંતર અશુદ્ધ રહે છે. ગુણ દેહના છે, પણ જીવમાં તેની સાથે એકાત્મસંબંધ થયો છે, જેથી તે દોષ જીવના ગણાય છે અને સુખના ફળને જીવ ભોગવવા ઇચ્છે છે, માટે જ તેને દુઃખનું ફળ પણ મળે છે. જ્યારે સત્સંગ થાય છે ત્યારે સુખ અને દુઃખ આપનારાં કર્મ બળી જાય છે. સંતના વચનથી ભગવાનનો આશ્રય કરવો તે સર્વ સાધનમાં અધિક સાધન છે.”","e":"While talking with King Jivendra, Shriharí said, “When one examines within by the eye of gnan, one sees the perverse tendencies of the mind. As long as the jiva dwells in the body, it has a relation with the gunas. Of these, sattvagun is pure. In tamogun and rajogun the inner self remains impure. The gunas belong to the body, but the jiva has formed a relation of identity with them, so those faults are counted as the jiva’s — and because the jiva wishes to enjoy the fruit of happiness, it also receives the fruit of misery. When satsang is attained, the karmas that give happiness and misery are burnt away. To take the refuge of Bhagwan by the word of the Sant is the greatest of all spiritual endeavours.”","s":["10/4/35-42"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1958,"k":"para","g":"મેઘપુરમાં જન્માષ્ટમીના ઉત્સવ ઉપર એકત્ર થયેલ હરિજનોને શ્રીહરિ કહે, “વિવાહમાં પુત્રને નિમિત્તે બાપ ગાળો સાંભળીને રાજી થાય છે પણ દ્વેષ રાખતો નથી, તે અજ્ઞાને કરીને સહન કરે છે, તેમ હરિભક્તે જ્ઞાને કરીને વર્તવું એ અમારી આજ્ઞા છે. તેને પાળશો તો કોઈ દિવસ દુઃખી નહિ થાઓ. મનુષ્યદેહનું દુઃખ તો કાંઈ નથી, તેના કરતાં તો જન્મમરણનાં દુઃખ અપાર છે, પણ એ અજ્ઞાનથી અંધ થયેલાને દેખાતાં નથી.”","e":"At Meghpur, to the harijans gathered for the Janmashtami festival, Shriharí said, “At a wedding a father hears abuse on his son’s account and is pleased by it, holding no malice — he bears it out of ignorance. In the same way, it is our command that a haribhakta should conduct himself so out of gnan. If you observe this, you will never be miserable. The misery of a human body is nothing at all; compared to it the miseries of birth and death are boundless — but one blinded by ignorance does not see them.”","s":["10/23/9-11"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1959,"k":"para","g":"મૂળીલા ગામમાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “કોઈ પણ સુખ છે તે દુઃખ વિના આવતું નથી. જેને ભગવાનનું સુખ સર્વથી અધિક મનાયું હોય તે તો પોતાને જેમ વધુ દુઃખ પડે તેમ તેને સુખ માની આનંદમાં રહે, કારણ કે તે જાણે છે કે ભગવાનનું સુખ અતિ દુર્લભ છે. તે અતિ દુઃખ સહ્યા વિના પ્રાપ્ત થતું નથી. ને અહીંનું જે કંઈ સુખ કહેવાય છે તે હકીકતે દુઃખ જ છે. છતાં એ દુઃખને સુખ સમજીને તેની પાછળ ઉદ્યમ કરે છે તે ભૂલ્યો છે, તેનો ભાવ ફર્યો છે.”","e":"In the village of Muli, while talking to the sadhus, Shriharí said, “There is no happiness whatsoever that comes without misery. One who has come to regard the happiness of Bhagwan as greater than all else regards whatever misery befalls him as happiness and remains joyful — because he knows that the happiness of Bhagwan is exceedingly rare, and that it is not attained without enduring great misery. And whatever here is called happiness is in fact nothing but misery. Yet one who takes that misery to be happiness and labours after it has gone astray; his disposition has turned.”","s":["11/13/23-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1960,"k":"para","g":"જૂનાગઢમાં શ્રીહરિએ દામોદર કુંડ જતાં વાત કરી, “બ્રહ્માંડનાં જેટલાં કંઈ સુખ કહેવાય છે તે સઘળાં દુઃખમય છે અને અસત્ય, મિથ્યા છે. એવું જે સમજે તે અપાર બુદ્ધિવાળો છે, તે ક્યારેય દૈહિક સુખમાં લોભાતો નથી. દૈહિક સુખમાં લોભાય છે તેને અંધ-તમસથી અવરાયેલો જાણવો. એ અજ્ઞાન અંધકાર ગાઢ છે, તે સત્સંગ (સત્પુરુપના સંગ) વિના ટળતો નથી.”","e":"At Junagadh, while going to Damodar Kund, Shriharí talked, saying, “All that is called happiness in the brahmands is full of misery, and is false and unreal. Whoever understands this is of boundless intelligence; he is never lured by bodily happiness. One who is lured by bodily happiness should be known as one shrouded in blind darkness. That darkness of ignorance is dense, and it does not go without satsang — the company of the Satpurush.”","s":["11/53/22-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1961,"k":"para","g":"શ્રીહરિએ ભુજમાં જગજીવનને ઉપદેશ દેતાં કહ્યું, “જીવ જતાં મડદું થઈ જાય અને ભસ્મ, કીટ કે મળરૂપ બની જાય એવો આ ક્ષણભંગુર દેહ પરાધીન છે છતાં જીવ તેને માટે મિથ્યા મમત્વે કરીને ખુવાર થાય છે. આ જીવ દેહ ને દેહના સંબંધીને કાજે જે કંઈ પાપ કરે છે તે રજેરજ પાપનું ફળ તેને ભોગવવું પડે છે. એક પાપનું ફળ હજારગણું મળે છે. દેહે કરીને જેટલા જીવ અહીં મારે છે તે પ્રત્યેક જીવ તેને તે તે દેહમાં હજાર વખત મારે છે. માટે આવું દુઃખ સહન કરવાની તૈયારી હોય તેણે પાપ કરવું, નહિ તો પાપ કરવાથી ડરવું, દૂર રહેવું. અમારા આશ્રિત સત્સંગીએ તો જૂ-માંકડથી માંડી પશુ સુધીના કોઈ પણ પ્રાણીની હિંસા કોઈ પ્રકારે કરવી નહિ. થોડા પાપમાં અપાર દુઃખ રહેલું છે એમ સમજી અહોનિશ ડરતા રહેવું.”","e":"While giving instruction to Jagjivan at Bhuj, Shriharí said, “When the jiva departs, this body becomes a corpse and turns to ash, worms or filth — such is this perishable, dependent body; yet the jiva ruins itself through false attachment to it. Whatever sin this jiva commits for the sake of the body and the body’s relations, it must suffer the fruit of every particle of that sin. The fruit of a single sin is received a thousandfold. Every jiva that one kills here by the body kills him a thousand times over in each of those bodies. Therefore let him sin who is prepared to endure such misery; otherwise one should fear sin and stay far from it. Our ashrit satsangis should not in any manner commit violence against any living creature, from lice and bedbugs up to animals. Knowing that boundless misery lies within even a small sin, one should remain fearful day and night.”","s":["12/30/28-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1962,"k":"para","g":"ભૂજમાં શ્રીહરિએ વાત કરતાં કહ્યું, “હરિભક્ત થયા છે તે સૌને કષ્ટ આવ્યાં છે. હરિભક્ત કાચો છે કે પાકો તે કષ્ટ આવે ત્યારે જણાય છે. કષ્ટમાં જે ધીરજ રાખે તેની કીર્તિ યુગોયુગ ગવાય છે. માટે જેનાં મોટાં ભાગ્ય હોય તેને જ સત્સંગ કર્યાથી કષ્ટ આવે. સત્સંગ નિમિત્તે કષ્ટ સહે તેટલું અધિક સુખ મળે છે. કષ્ટ વિના સુખ નથી. ત્રિલોકીના રાજા પ્રહ્‌લાદ, ધ્રુવ, અંબરીષને સત્સંગ માટે અપાર કષ્ટ આવ્યાં. ભગવાન જેના પતિ છે એવાં સીતાજીને પણ અપાર કષ્ટ સહન કરવા પડ્યાં છે. ભગવાનનાં માત-પિતા હોવા છતાં વસુદેવ-દેવકીને દુઃખ આવ્યાં છે. આજે કાંઈ આ નવી વાત નથી. ભક્ત-અભક્ત સૌને દુઃખ આવ્યાં કરે છે. કષ્ટ આવે ત્યારે સહન કરવાં જ જોઈએ. સહન કર્યા વિના અતિ દુર્લભ મોક્ષ કેવી રીતે મળે? હરિભક્તને તો કષ્ટ છે જ નહિ, પણ સમજણમાં ફેર છે, તેથી કષ્ટ દેખે છે.","e":"At Bhuj, while talking, Shriharí said, “All who have become haribhaktas have met with hardship. Whether a haribhakta is unripe or ripe becomes known when hardship comes. The glory of one who keeps patience in hardship is sung age after age. So hardship comes through doing satsang only to one whose fortune is great. The more hardship one endures for the sake of satsang, the greater the happiness one receives. There is no happiness without hardship. Prahlad, Dhruv and Ambarish — kings of the three realms — met with boundless hardship for satsang. Even Sitaji, whose husband was Bhagwan Himself, had to endure boundless hardship. Though they were the parents of Bhagwan, misery came to Vasudev and Devaki. This is nothing new today. Misery keeps coming to devotee and non-devotee alike. When hardship comes it must simply be borne. Without bearing it, how is the exceedingly rare moksha to be attained? For a haribhakta there is in fact no hardship at all — but there is an error in his understanding, and so he sees hardship.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1963,"k":"para","g":"“સત્સંગ નિમિત્તે દુઃખ આવે તેને સુખ માને તે જ સાચો સત્સંગ છે. સંસારમાં હેત છે તો અપાર દુઃખ આવે તોપણ તે દુઃખ મનાતું નથી, ઊલટું સુખ માને છે. કષ્ટ જાણીને કોઈ ભોગનો ત્યાગ કરતું નથી, સત્સંગમાં જ જ્યાં સુધી કષ્ટ જણાય છે ત્યાં સુધી સત્સંગ કાચો છે, અને તેને વિઘ્ન છે. જેને જેમાં ખપ હોય તેને કાંઈ કઠણ પડતું નથી. સત્સંગ કરવામાં કષ્ટ આવે તેને સુખકર સમજે તે સૌ હરિભક્તોમાં મુખિયો છે.”","e":"“Only that is true satsang in which one regards the misery that comes for the sake of satsang as happiness. When there is affection for worldly life, then even though boundless misery comes, it is not felt to be misery — on the contrary it is taken to be happiness. No one renounces an enjoyment on the grounds that it is hardship. So long as hardship is felt in satsang, that satsang is unripe, and there is an obstacle in it. To one who has khap for a thing, nothing about it feels difficult. He who understands the hardship that comes in doing satsang to be a source of happiness is the foremost among all haribhaktas.”","s":["12/36(35)/3-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1964,"k":"para","g":"વઢવાણમાં તુલસી દૂબેના ઘરે શ્રીહરિએ વાત કરતાં કહ્યું, “આગળ જે જનોએ સત્સંગ કર્યો છે તેની રીત તપાસવી. તે રીત તપાસ્યા વિના સત્સંગના શુભ ગુણ આવે નહિ. અને તેથી નિશદિન અમારી પાસે રહે તોપણ દુઃખ ટળે નહિ. વિવેકમાં અપાર સુખ રહેલું છે. જેવો સ્વભાવ હોય તેવું સુખ પામે છે. સમજણ વિનાના જનો સુખદુઃખ પામતા રહે છે. ધાર્યું મળે ત્યારે સુખ પામે ને ન મળે ત્યારે દુઃખ પામે. માયિક ભોગ સુખ-દુઃખથી મિશ્રિત છે, એમ જાણી આનંદ માની મગ્ન રહેવું. કોઈનો દોષ લેવો નહિ.”","e":"At Wadhwan, at the home of Tulsi Dubey, while talking, Shriharí said, “One should examine the manner of those who have done satsang before. Without examining that manner, the noble virtues of satsang do not come. And so, even if one stays near us day and night, one’s misery does not go. Boundless happiness lies in vivek. As one’s swabhav is, so is the happiness one attains. People without understanding keep meeting with happiness and misery — they find happiness when they get what they intended and misery when they do not. Knowing that mayik enjoyments are mixed with both happiness and misery, one should remain joyful and absorbed. One should not take up anyone’s faults.”","s":["12/50(49)/3-30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1965,"k":"para","g":"ખોખરા મહેમદાવાદમાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “હરિમાં અપાર અને અવિચળ સુખ રહેલું છે, તેથી તેમને પ્રસન્ન કરવા માટે રાજ્ય સમૃદ્ધિને છોડીને ત્રિલોકોના રાજાઓ પણ દેહ અને દેહના સુખનો ત્યાગ કરી પ્રભુપદમાં પ્રીતિ કરી ગયા છે, ભગવાનમાં જ્યારે અગાધ સુખ મનાયું ત્યારે વન-પર્વતમાં જઈને રહ્યા અને માગ્યા વિના જે કંઈ કૌપીન-કંથા વગેરે ફાટ્યાં-તૂટ્યાં મળે તેનાથી નિર્વાહ કર્યો. ભયમાત્ર તજી નિર્ભય થયા.”","e":"At Khokhra Mehmedabad, while talking to the sadhus, Shriharí said, “Boundless and unshakeable happiness lies in Hari; therefore, to please Him, even the kings of the three realms have abandoned their kingdoms and riches, renounced the body and the body’s happiness, and gone on to love the feet of the Lord. When they came to regard the happiness in Bhagwan as unfathomable, they went and lived in forests and mountains, and sustained themselves on whatever torn and tattered loincloth or rag came to them unasked. Casting off all fear, they became fearless.”","s":["13/6/17-22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1966,"k":"para","g":"ગઢપુરમાં વણિક પાસે વાત કરતાં શ્રીહરિ કહે, “જે ભગવાનથી ડરીને ધર્મના માર્ગે ચાલે છે તે સુખી થાય છે. આ લોકનું સુખ અતિ અલ્પ છે. તેને માટે અપાર ઉદ્યમ કરે છે. જેમ સૂકા હાડકાને ચાટીને કૂતરું તેમાં સુખ માને છે, તેમ અજ્ઞાની જીવો સુખથી રહિત જગતના પદાર્થોમાં સુખ માને છે. યથાર્થ સત્સંગી હોય તેને જ આવી અલૌકિક સમજણ હોય છે. જેને ખપ નથી તેવા પંડિતો ધર્મ, અર્થ અને કામ પરાયણ વચનો શાસ્ત્રમાંથી ગ્રહણ કરે છે ને દેહના પોષણ માટેના ઉપાયો લોકમાં પ્રવર્તાવે છે, અને અલ્પ સુખને માટે કુટુંબે સહિત બધાં સંસારમાં ડૂબી રહ્યાં છે.”","e":"At Gadhpur, while talking before a merchant, Shriharí said, “One who fears Bhagwan and walks the path of dharma becomes happy. The happiness of this world is exceedingly small, yet for it a person makes boundless effort. Just as a dog licks a dry bone and imagines happiness in it, so ignorant jivas imagine happiness in the objects of the world, which are devoid of happiness. Only one who is a true satsangi has such transcendental understanding. Scholars who have no khap take from the shastras only those words that serve dharma, artha and kama, and spread among people the means of nourishing the body; and for the sake of a trifling happiness they, together with their families, all remain drowned in worldly life.”","s":["13/46/29-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1967,"k":"para","g":"ખેડામાં વિલાયતી સાહેબને શ્રીહરિ કહે, “અમારી રીત એવી છે કે આ લોકનાં સુખ-દુઃખ પર તાન રાખવું નહિ, કારણ કે તે બહુ દિવસ રહેવાનાં નહિ. વિરાટના એક દિવસમાં ચૌદ ઇન્દ્ર મરે છે. સતયુગ, ત્રેતા, દ્વાપર, કળિ - એમ ચાર યુગની એક ચોકડી કહી છે. તેવી એકોતેર ચોકડી સુધી એક ઇન્દ્ર રાજ કરે છે ને અંતે નાશ પામે છે. એવા એક ઇન્દ્રની હયાતીમાં કેટલાય ચક્રવર્તી મરે છે! એમ આ લોકનું સુખ-દુઃખ ક્ષણભંગુર છે. જે ક્ષણભંગુર સુખ માટે યત્ન કરે, તે બુદ્ધિશાળી ન કહેવાય. પરદેશ જઈને ઉદ્યમ કરે ને બહુ ધન કમાય તેને લોક બુદ્ધિશાળી કહે છે, પણ તે બુદ્ધિશાળી નથી, અલ્પમતિ છે.","e":"At Kheda, Shriharí said to a European gentleman, “Our way is this: not to fix one’s attention on the happiness and misery of this world, because they are not going to last many days. In a single day of Virat, fourteen Indras die. Satya, Treta, Dwapar and Kali — these four yugs are called one chokdi. One Indra rules for seventy-one such chokdis and then perishes at the end. And within the lifetime of a single such Indra, how many emperors die! Thus the happiness and misery of this world are momentary. One who strives for a momentary happiness cannot be called intelligent. People call a man intelligent who goes abroad, labours and earns much wealth — but he is not intelligent; he is of small understanding.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1968,"k":"para","g":"“અહીંના લોક ભોગ કાજે જેટલો કંઈ ઉદ્યમ કરે છે તે ઘાંચીના બળદ જેવો છે. જેમ ઘાંચીનો બળદ આખી જિંદગી ચાલે પણ ઠેરનો ઠેર જ રહે છે. માટે ઉદ્યમ એવો કરવો કે જે શાશ્વત સુખ આપે, ક્યારેય નાશ ન પામે.”","e":"“Whatever effort the people here make for the sake of enjoyments is like the ox of an oil-presser. Just as the oil-presser’s ox walks its whole life yet remains exactly where it was, so it is with them. Therefore one should make the kind of effort that gives everlasting happiness — that never perishes.”","s":["14/9/2-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1969,"k":"para","g":"સારંગપુરમાં શ્રીહરિએ સંતોને વાત કરતાં કહ્યું, “અમે શુદ્ધ જ્ઞાન આપીએ છીએ, પણ મનન કરવામાં કસર રહે છે. ખપનો વેગ એક સરખો રહેતો નથી. અનાદિ અજ્ઞાનમય કારણ શરીર સાથે જીવ મળી જાય છે, તેથી દુખિયો રહે છે. તે બધી જીવની જ કાચપ છે. જ્ઞાનનું મનન કરવામાં પ્રમાદ રહે તેટલું દુઃખ આવે છે. કેફી માણસ જેટલો કેફ છોડી દે તેટલો સુખી થાય તેમ હરિભક્ત તન અને મન અર્પણ કરવામાં જેટલી ચોરી રાખે તેટલો તે દુઃખી થાય. જે સંતની વાત સાંભળે નહિ, વિષયમાં તૃપ્ત થાય નહિ, તેઓ જન્મોજન્મ દુઃખી થાય છે. સત્સંગ કરે તે હરિભક્તને દેહે દુઃખ સહન કરવું પડે છે, પણ પાછળથી અપાર સુખ મળે છે. દેહનું જેટલું મમત્વ રાખે તેટલું વધુ દુઃખ થાય છે.”","e":"At Sarangpur, while talking to the sadhus, Shriharí said, “We give pure gnan, but a deficiency remains in contemplating upon it. The force of khap does not stay even. The jiva merges with the causal body, which is made of beginningless ignorance, and so remains miserable. All of this is the jiva’s own unripeness. However much negligence remains in contemplating gnan, that much misery comes. Just as an intoxicated man becomes happy to the extent that he gives up his intoxication, so a haribhakta becomes miserable to the extent that he holds something back in offering his body and mind. Those who do not listen to the words of the Sant, and are never satisfied in the vishays, remain miserable birth after birth. A haribhakta who does satsang has to endure misery in the body, but afterwards he receives boundless happiness. The more attachment one keeps to the body, the more misery there is.”","s":["14/91/9-14, 20-23"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1970,"k":"para","g":"શ્રીહરિએ ગઢપુરમાં સંતોને વાત કરતાં કહ્યું, “ભગવાન અને ભગવાનના સંતમાં સુખમાત્ર રહેલું છે ને તે અત્યંત પ્રમાણમાં રહેલું છે. તેમનામાં સુખ નથી દેખાતું ત્યાં સુધી દુઃખ રહે છે. જ્યારે સંતમાં સુખ મનાશે, ત્યારે દુઃખમાત્ર ટળી જશે. આ સમજણ ન આવે ને ગ્રંથમાત્ર ભણે તોપણ ધગતું અંતર શાંત નહિ થાય, લેશ પણ સુખ નહિ આવે. આ સમજણ વિનાનું સઘળું જન્મ-મરણ કરાવનાર છે. બ્રહ્માંડોના દેવતા પણ આ સમજણ વિના દુઃખી છે.","e":"At Gadhpur, while talking to the sadhus, Shriharí said, “All happiness resides in Bhagwan and in the Sant of Bhagwan, and it resides there in the highest measure. Until one sees that happiness in them, misery remains. When happiness comes to be perceived in the Sant, then all misery will go. Without this understanding, one may study every scripture there is and still the burning within will not be stilled; not the least happiness will come. Everything done without this understanding is what causes birth and death. Even the deities of the brahmands are miserable without this understanding.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1971,"k":"para","g":"“સુખ અને દુઃખ તો આ માયિક શરીરના સંગને લીધે જ અનુભવાય છે. જેને પોતાના આત્મસ્વરૂપનું ને પરમાત્માના સ્વરૂપનું શુદ્ધ જ્ઞાન થયું છે તેને પિંડ-બ્રહ્માંડનો સંગ સ્વપ્ન તુલ્ય લાગે છે. જે એકવાર ભગવાનના સુખે સુખિયો થયો, તે ફરી ક્યારેય દુખિયો રહેતો નથી. જ્ઞાનીજન સુખદુઃખને પણ સ્વપ્ન માને છે, તેમાં ચોંટતા નથી. કમળના પત્ર પર જળનું બુંદ પૃથક્ રહે તેમ જ્ઞાની દેહથી જુદો વર્તે છે. જ્ઞાની તો ચિંતામણિ ને કલ્પવૃક્ષ છે.”","e":"“Happiness and misery are experienced only on account of the company of this mayik body. To one who has attained pure gnan of his own atma-swarup and of the swarup of Paramatma, the company of body and brahmand seems like a dream. One who has once become happy with the happiness of Bhagwan never again remains miserable. The gnani regards even happiness and misery as a dream and does not cling to them. As a drop of water rests separate upon a lotus leaf, so the gnani abides apart from the body. The gnani is indeed a chintamani and a kalpavruksh.”","s":["14/92/29-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1972,"k":"para","g":"શ્રીહરિએ ભાવનગરના વિજયસિંહ ઠાકોરના પાટવીકુંવરને વાત કરતાં કહ્યું, “રાજાનો કાયદો લોપે છે તેને જેમ પાછળથી દુઃખ આવે છે તેમ વિષયનાં અલ્પ સુખ માટે જે ભગવાનના કાયદાનું ઉલ્લંઘન કરે છે, તેને અપાર દુઃખ આવ્યા વિના રહેતું નથી. વિષય બંધનમાં સુખ દેખાય ત્યાં સુધી પશુબુદ્ધિ છે.”","e":"Shriharí said, while talking to the crown prince of Vijaysinh Thakor of Bhavnagar, “Just as one who breaks the king’s law meets with misery afterwards, so one who transgresses the law of Bhagwan for the trifling happiness of the vishays cannot but meet with boundless misery. So long as happiness is seen in the bondage of the vishays, it is the intelligence of an animal.”","s":["15/39/36, 39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1973,"k":"para","g":"ગઢપુરમાં શ્રીહરિ સંતોને વાત કહેવા લાગ્યા, “ઇચ્છિત પદાર્થ ન મળે ત્યારે તત્કાળ ક્લેશ થાય છે. જ્યાં સુધી લૌકિક પદાર્થ મળે ને આનંદ થાય, ત્યાં સુધી એ તુચ્છમતિ છે, એને સુખની દિશા હાથ લાગી નથી.","e":"At Gadhpur, Shriharí began to talk to the sadhus: “When a desired object is not obtained, distress arises at once. So long as one obtains worldly objects and feels delight in them, he is of petty understanding; he has not laid his hand on the direction in which happiness lies.","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1974,"k":"para","g":"“પદાર્થે કરીને થયેલ સત્સંગ મૂળ વિનાનો છે. મનનું ધાર્યું થાય ત્યાં સુધી સત્સંગમાં દિવસો વિતાવે, પદાર્થ ન મળે કે તરત વિમુખ થઈ જાય. પદાર્થની ઇચ્છાથી સત્સંગ કરે તેને મોક્ષનો ખપ નથી. દેહના અંત સુધી તેની ઇચ્છા મુજબ પદાર્થ મળ્યા કરે તો સત્સંગમાં તન છૂટે ત્યાં સુધી ટકી રહે. કોઈને દોષબુદ્ધિ થઈ જાય તોપણ સત્સંગથી વિમુખ થાય છે.”","e":"“Satsang founded upon material objects is without root. He passes his days in satsang so long as his mind’s intentions are fulfilled; the moment the objects are not obtained he turns away. One who does satsang out of a desire for objects has no khap for moksha. If objects keep coming to him according to his wish until the end of his body, then he will remain in satsang until the body falls. And even so, should fault-finding towards anyone arise, he turns away from satsang.”","s":["15/47/10-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1975,"k":"para","g":"શ્રીહરિએ પત્રમાં લખ્યું કે, “દુઃખ વગર ભગવાનનું ભજન કોઈ કરતું નથી. દુઃખમાં ભગવાન સાંભરે છે તેવા સુખમાં સાંભરતા નથી. સુખી માણસો ભગવાનથી પણ વિષયમાં કોટિ ગણાં સુખ માને છે. બંધનમાં તેમને સુખબુદ્ધિ થઈ છે. ભાગવત તેને પશુથી પણ નીચ કહે છે. સાચો સત્સંગ કરે તે વિના અંતરમાં પ્રકાશ થતો નથી. જીવને અંતરમાં પ્રકાશ થાય તે હેતુથી વ્યાસજીએ ભાગવત, ગીતા જેવા ગ્રંથો રચ્યા, તોપણ ભગવાન જો પ્રગટ ન મળે તો મોક્ષનો માર્ગ હાથ લાગતો નથી. ભગવાન મળે અથવા ભગવાનના સાચા સંત મળે ને તેમનો જોગ જે જન કરે તેટલું તેનું ભવબંધન ટળે.”","e":"Shriharí wrote in a letter, “No one worships Bhagwan without misery. Bhagwan is remembered in misery as He is not remembered in happiness. Happy people consider the happiness of the vishays to be ten million times greater even than Bhagwan. They have come to regard bondage as happiness. The Bhagwat calls such a one lower even than an animal. Without doing true satsang, the light does not dawn within. It was so that light might dawn within the jiva that Vyasji composed scriptures such as the Bhagwat and the Gita; yet even so, if Bhagwan is not obtained in His manifest form, the path of moksha is not laid hold of. To the extent that a person attains Bhagwan, or attains the true Sant of Bhagwan, and keeps their company, to that extent his worldly bondage is severed.”","s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1976,"k":"verse","g":"‘વા ભગવાન કે સાચે સંતા, જેહિ જનકું મિલત રહંતા.","e":"‘Vā Bhagvān ke sāche santā, jehi jankun milat rahantā.","s":[],"sv":[],"mt":false,"gl":"[Either Bhagwan or His true Sant — whichever of these a person keeps meeting…]","a":false},{"i":1977,"k":"verse","g":"તાકે જોગ કર જન જિતના, ભવબંધન છુટત રહે તિતના.”","e":"Tāke jog kar jan jitnā, bhavbandhan chhutat rahe titnā.’","s":["15/86/29-36"],"sv":[],"mt":false,"gl":"[…to the extent that a person keeps their company, to that extent the bondage of birth and death falls away.]","a":false},{"i":1978,"k":"para","g":"ધર્મપુરમાં શ્રીહરિ રાજાને કહેવા લાગ્યા, “માયિક વિષયમાં અને પદાર્થમાં દુઃખ હોવા છતાં દુઃખ દેખાતું નથી, પણ દુઃખ આવ્યા વિના રહેતું નથી. સુખ ઉપર તાન હોવાથી દુઃખથી મરી જાય તોપણ માયિક સુખ માટે દુઃખ સહન કરે છે, એવો આ સંસાર છે. દારૂ વગેરેમાં કોઈ સુખ ન હોવા છતાં તેને માટે મરે છે ને વારે વારે ફજેત થાય, તોપણ તે માર્ગે ચાલે છે. સત્સંગથી તો અપાર સુખ થાય છે, છતાં તેને માટે જીવને તાન નથી.”","e":"At Dharmapur, Shriharí said to the king, “Though there is misery in mayik vishays and in material objects, the misery is not seen — but it does not fail to come. Because the attention is fixed on happiness, a person endures misery for the sake of mayik happiness even to the point of dying of it; such is this world. Though there is no happiness at all in liquor and the like, people die for it and are disgraced again and again, yet still they walk that path. From satsang comes boundless happiness, and yet the jiva has no zeal for it.”","s":["16/25/12-20"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1979,"k":"para","g":"ગઢપુરમાં શ્રીહરિ ધરમપુરની વાત કરતાં કહે, “સમજણ હોય તેટલું સુખ મળે છે. સમજણરૂપી સુદર્શનચક્ર જ્યાં હોય ત્યાં માયા રહી શકતી નથી. આગળના ભક્તોએ રાજ્ય તજીને પણ ભગવાનને માટે કષ્ટ સહન કર્યાં છે. ભગવાનમાં સુખ ન હોય તો શા માટે તે દુઃખ ભોગવે? પણ તે જાણતા હતા કે બ્રહ્માંડમાં જે સુખ છે, તે કથનમાત્ર છે. અને તેમાં પણ કેટલાંય દુઃખ ભેગાં રહેલાં છે. ભગવાનના ધામનું સુખ તો અપાર અને અવિચલ છે. અહીંનાં સુખ તો બંધનરૂપ છે, એમ સમજીને તેમણે કષ્ટ સહન કર્યાં છે.”","e":"At Gadhpur, speaking of the affair at Dharampur, Shriharí said, “One receives happiness in the measure of one’s understanding. Where the Sudarshan chakra of understanding is, maya cannot remain. The devotees of old renounced even kingdoms and endured hardships for Bhagwan. If there were no happiness in Bhagwan, why would they have suffered that misery? But they knew that the happiness which is in the brahmand is happiness in name only, and that a great deal of misery is mixed into it as well. The happiness of the abode of Bhagwan is boundless and unshakeable. Understanding that the happiness here is a form of bondage, they endured hardships.”","s":["16/48/15-25"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1980,"k":"para","g":"શ્રીહરિએ જીવક નૃપને વાત કરતાં કહ્યું, “બલિરાજાને વામન ભગવાને બહુ તાવી જોયા, છતાં તે ગુણ જ લેતા રહ્યા, ત્યારે ભગવાન તેમને વશ થયા. અમારી રીત પણ એવી છે. જેને અમારો વિશ્વાસ છે, તેને દુઃખ દઈએ છતાં સુખ માને, તેને અમે તજી શકતા નથી. અમે દુઃખ દઈએ તે તેના સુખને માટે હોય. વિપરીત મતિવાળાને તે સમજાય નહિ. જેટલું મન ચોરે છે તેટલું દુઃખ આવે છે. જે મન અમને સોંપી દે છે તે ક્યારેય દુઃખી થતો નથી. પાંડવોએ ભગવાનનો વિશ્વાસ રાખ્યો તો આજ સુધી તેમની કીર્તિ ગવાય છે ને ભગવાને તેમનો પક્ષ રાખ્યો.”","e":"While talking to King Jivak, Shriharí said, “Vaman Bhagwan tested King Bali severely, yet he went on perceiving only virtue — and then Bhagwan became subject to him. Our way, too, is like this. One who has faith in us regards it as happiness even when we give him misery; such a one we cannot abandon. When we give misery, it is for his happiness. One of perverse understanding does not understand this. However much one withholds his mind, that much misery comes. One who surrenders his mind to us is never miserable. The Pandavs kept faith in Bhagwan, and so their glory is sung to this day, and Bhagwan took their side.”","s":["17/44/5-17"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1981,"k":"para","g":"જેતલપુરમાં દિવાળીની રાત્રે શ્રીહરિએ વાત કરવાની શરૂઆત કરી, તે મધ્યરાત સુધી વાત કરી. શ્રીહરિ કહે, “ભગવાનની વાત અમાયિક છે. જગતના જીવો તેને માયિક કહે છે. અને માયિક પદાર્થમાં સુખ માને છે. પરંતુ, માયામાંથી ઊપજ્યું સઘળું નાશવંત છે. માયિક સુખ અને અમાયિક સુખ - બન્નેમાં રાત-દિવસ જેટલો ભેદ છે. માયિક સુખ અસત્ય છે. તેને સત્ય માનીને જીવ ભવસાગરમાં ભટકે છે. માટે હરિભક્તે માયિક સુખમાં રાગ રાખવો નહિ. જે માયિક સુખમાં પ્રીતિ કરે છે, તેટલો તે ન્યૂન રહે છે. ભગવાન, સંત, હરિભક્ત અને ભગવાનનું ધામ અમાયિક છે તેમાં જીવને જોડી દેવો.”","e":"At Jetalpur, on the night of Diwali, Shriharí began to talk, and talked until midnight. Shriharí said, “The matter of Bhagwan is amayik. The jivas of the world call it mayik, and imagine happiness in mayik objects. But everything born of maya is perishable. Between mayik happiness and amayik happiness there is as much difference as between night and day. Mayik happiness is false. Taking it to be true, the jiva wanders in the ocean of worldly life. Therefore a haribhakta should keep no attachment to mayik happiness. However much a person loves mayik happiness, by that much he remains deficient. Bhagwan, the Sant, the haribhaktas and the abode of Bhagwan are amayik — the jiva should be joined to them.”","s":["17/57/12-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1982,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ સંત-હરિજનો પ્રતિ વાત કરતાં કહ્યું, “ભગવાનના સુખમાં નજર પહોંચે છે તેને જ સાચો સત્સંગ થયો છે. જેમ અન્ન ને જળ વિના ચાલતું નથી, તેમ સંત હરિભક્ત વિના ચાલે નહિ એમ જે માને તે જ મોક્ષનો અધિકારી થાય છે.”","e":"At Gadhpur, while talking to the sadhus and harijans, Shriharí said, “Only he whose sight reaches the happiness of Bhagwan has attained true satsang. Just as one cannot manage without food and water, whoever holds that he cannot manage without the Sant and the haribhaktas becomes worthy of moksha.”","s":["22/27/31-32"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1983,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":"The author’s notes and corroboration upon the foregoing subject as spoken by Shriharí:","s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":1984,"k":"para","g":"હરિના માર્ગ વિના બીજા માર્ગે જેમ જેમ અધિક દોડે છે તેમ તેમ સુખથી દૂર થાય છે. ખોટાં સુખ લેવા કરોડો લોકો મરે છે. મિથ્યા સુખનો મોહ મદિરા કરતાં પણ બળવાન છે. સત્સંગ કર્યામાં લેશમાત્ર દુઃખ નથી. જગતનાં કષ્ટ વિચારે તો સત્સંગ થતાં વાર ન લાગે.","e":"The faster one runs upon any path other than the path of Hari, the further one goes from happiness. Millions of people die trying to seize false happiness. The attachment to illusory happiness is stronger even than liquor. There is not the least misery in doing satsang. If one were to consider the hardships of the world, it would take no time at all for satsang to take hold.","s":["8/73/5-7"],"sv":[],"mt":false,"gl":null,"a":true},{"i":1985,"k":"para","g":"સુખમાં સુખ એટલું જ છે કે જેમાં ભગવાનનો સંબંધ હોય. ભગવાનના સંબંધ વિનાના અપરિમિત સુખને પણ અક્ષરધામના મુક્ત અતિ દુઃખ જ માને છે. ભગવાન વિના બીજી વાતમાં જેટલું કંઈ સુખ જણાતું હોય એવી સમજણવાળો વિમુખ છે. ભગવાનનું ધામ અને તેમાં રહેલા મુક્તોની સમજણ મુજબ હરિજને ચાલવું.","e":"The only happiness within happiness is that in which there is a relation with Bhagwan. Even limitless happiness that has no relation with Bhagwan is regarded by the muktas of Akshardham as nothing but great misery. Whoever finds some happiness in any matter apart from Bhagwan is, in that understanding, turned away from Him. A harijan should conduct himself according to the understanding of the abode of Bhagwan and of the muktas who dwell in it.","s":["14/18/24-27"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":26,"gu":"પંચવિષય","en":"Panchvishay — The Five Sense Pleasures","url":"https://www.anirdesh.com/pbp/index.php?page=chp_26","b":[{"i":1986,"k":"para","g":"શ્રીહરિએ નારસંગજી નૃપને વાત કરતાં કહ્યું, “ચૌદ લોકનું બ્રહ્માંડ છે. એક એક લોકથી અધિક વિષય ત્યાં છે. એમ પ્રકૃતિપુરુષના લોક સુધી વિષયનું સામ્રાજ્ય છે - એ બધા વિષયોને ઝેર સમાન જાણે ને તેનો ત્યાગ કરે, જીવપ્રાણીમાત્રને વિષય સાથે પરમ મિત્રતા છે, પણ વિષયને સાચા શત્રુ જાણી તેનો ત્યાગ કરે ને અમારો આશ્રય કરે તે માયા તજીને અમારા ધામને પામે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1987,"k":"para","g":"“જે વિષયને મિત્ર માને છે તેનો જન્મ ખુવાર થાય છે. જે જે યોનિમાં જાય ત્યાં તેને પોતાની રુચિ અનુસાર વિષય મળતા નથી, વિષયની તૃષ્ણા વધે છે ને અપાર દુઃખને પામે છે.”","e":null,"s":["4/71/20-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1988,"k":"para","g":"શ્રીહરિએ તેરાપુરના જનો પ્રત્યે સંતની વાત કરતાં કહ્યું, “વિષયવાસનાને કારણે લખચોરાશીમાં જીવ અનંતવાર જન્મ્યો છે. અને નરકમાં દુઃખ ભોગવ્યાં છે, છતાં તેનો અભાવ થતો નથી. સાચા સંત મળે છે ત્યારે જમના બંધનથી તથા વિષયના બંધનથી છોડાવે છે. મનુષ્ય-દેહ પામીને પણ જે દુઃખમાંથી છૂટવાનો ઉપાય કરતો નથી, તે આત્મહત્યારો કહેવાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1989,"k":"para","g":"“કુકર અને શૂકરની પેઠે વિષયમાં જીવને રાગ રહ્યો છે. સાચા સંત ધન્વંતરિ વૈદ્ય છે. તે જીવનો અસાધ્ય રોગ ટાળે છે. કારણ, સંત પોતે વિષયમાંથી છૂટેલા છે, તેથી તેમની વાત જીવને માન્યામાં આવે છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1990,"k":"verse","g":"‘સાચે સંત મિલત જબ આઈ, જિય કે બંધન દેત છોરાઈ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1991,"k":"verse","g":"સંત મિલે જબ સાચે જબહિ, હિત કરી કહે જિય કુ તબહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":1992,"k":"verse","g":"ધન્વંતરિ વૈદ્ય હે તેહા, અસાધ્ય રોગ દે ટારી એહા.’","e":null,"s":["5/45/24-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1993,"k":"para","g":"જૂનાગઢમાં શ્રીહરિએ સભામાં વાત કરતાં કહ્યું, “પંચવિષયની આસક્તિને લીધે જીવ લખચોરાસી ભમે છે. ગર્ભવાસ ને જમપુરીનું દુઃખ પામે છે, તેને સુખ તો ક્યાંય મળતું નથી. સુખ ભગવાનના ભક્તો-સંતોને મળ્યું છે. એ બડભાગી છે તેને પણ ભગવાન વિના જેટલું કંઈ ચિંતવન થાય છે તેટલો તેનામાં કુસંગ ભર્યો જાણવો. ભગવાન સિવાય બીજો ઘાટ ન ઊઠે ત્યાં સુધી સત્સંગ કરવો છે. ને એ જ ખરો સત્સંગ છે.”","e":null,"s":["6/79/19-22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1994,"k":"para","g":"ઘુઘરાળામાં શ્રીહરિએ સંતોને કહ્યું, “કીર્તન ગાઓ. કારણ કે કથા-વાર્તા-કીર્તન જો મનમાં ધારે નહીં તો ત્રણેય એક સરખાં જ છે. ધાર્યા વિના જીવને તે સમાસ કરતાં નથી. જીવને તો વિષયમાં તાન છે. જ્યાં વિષયનું પોષણ થતું હોય ત્યાં પ્રીતિ કરે છે. જેના સંગથી વિષય છૂટે છે તેની સાથે પ્રીત ક્યારેય કરતો નથી. દુઃખમાત્ર વિષયમાં રહ્યાં છે, પણ વિષયમાં દુઃખ દેખાતાં નથી ને દુઃખ આવી પડે તોપણ વિષયનો કોઈ દોષ લેતું નથી, એવો જીવને વિપરીત મોહ છે. નાક, કાન, શિર અને ધન ખોવડાવે તોપણ જીવ વિષયનાં વખાણ કરે છે, પણ તેનો ઇશક છોડતો નથી.”","e":null,"s":["6/90/28-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1995,"k":"para","g":"જેતલપુરમાં શ્રીહરિએ વાત કરતાં કહ્યું, “પાયા વિનાનું સોનાનું મકાન હોય કે સ્ફટિક મણિનું હોય તોપણ જેને જીવવાનો લોભ હોય તે તેમાં રહેવાની ઇચ્છા રાખે નહિ. તેમ આખા બ્રહ્માંડનાં સુખ મળે તોપણ જેને જન્મ-મરણનો ભય હોય, તેને તે સુખમાત્ર કોટિ વીંછીના ડંખ જેવાં લાગે.”","e":null,"s":["8/9/27-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1996,"k":"para","g":"નડિયાદમાં શ્રીહરિએ વાત કરતાં કહ્યું, “માછલું અધિક સ્વાદ કરે છે, તો તે જીવ ખુએ છે. મૃગલું શબ્દમાં સ્વાદ માને છે અને હાથી વગેરેને સ્પર્શમાં સ્વાદ હોય છે. આ બધાં એકેક વિષયના સ્વાદથી પણ પ્રાણ ખુએ છે. જેને પાંચે વિષયના સ્વાદ બળવાન હોય તે તો મોક્ષ-માર્ગથી પડેલો જ છે. એ પાંચે સ્વાદ ભોગવનારને અનંત જન્મ સુધી તેમાં તૃપ્તિ થતી નથી અને નરકનાં દુઃખનો અંત આવતો નથી. ભગવાનમાં અધિક સુખ છે તે સમજવા માટે જગતમાં થોડું સુખ રચ્યું છે, પણ અલ્પ સુખમાં બંધાઈ ગયેલા જીવો તેમાંથી છૂટતા નથી... અલ્પ વિષય ભોગવતાં મેરુ સમાન દુઃખ આવી પડે છે. એકવીસ-એકવીસ લાખની ચાર ખાણોમાં કરોડો કલ્પ સુધી જન્મવું-મરવું પડે છે.”","e":null,"s":["8/32/5-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1997,"k":"para","g":"માનકુવામાં વાત કરતાં શ્રીહરિએ કહ્યું, “જીવ અનંત પ્રકારના વિષયમાં ખૂતેલા છે. સત્સંગ વિનાની જેટલી વાતો કરે, ગ્રંથ વાંચે, પણ તેનું તાન વિષયમાં હોય છે. અનેક મતના જે જે મોટાઓ થઈ ગયા, તેમણે જે ગ્રંથ બનાવ્યા તેનું તાત્પર્ય તો જીવને વિષયનું બંધન તોડાવવામાં છે. અનંત દુઃખોનું મૂળ પંચવિષય છે. પંચવિષય છૂટે તો દુઃખમાત્ર છૂટી જાય.”","e":null,"s":["10/39/21-25"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1998,"k":"para","g":"શ્રીનગરમાં શ્રીહરિએ દીવાનને ઉદ્દેશીને કહ્યું, “વિષયનો રોગ પ્રબળ અને અસાધ્ય છે. સ્થાવર, જંગમ બધા દેહોમાં પ્રાણીને એ રોગ પીડે છે. ચોરાસી લાખ યોનિમાં દેહ ધરીને આ જીવે સપ્તસિંધુથી પણ અપાર માતાનું દૂધ વારંવાર પીધું છે, અને તે તે દેહમાં વધુ ને વધુ વિષયમાં લીન રહ્યો છે. તેથી હવે ક્યાંથી તૃપ્તિ થાય? અગ્નિમાં ઘી અને કાષ્ઠ હોમવાથી જેમ અગ્નિ વધુ ને વધુ પ્રદીપ્ત થાય તેમ વિષયોનું સેવન કરવાથી તેની કામનાઓ વધતી જાય છે. સાચા સંતનો સંગ મળે તો પામર પશુ જેવો જીવ દેવકોટિનો થઈ જાય છે, વિષયમાત્ર છૂટી જાય છે ને મતિ ઉત્તમ થાય છે.”","e":null,"s":["14/69/24-32"],"sv":[],"mt":false,"gl":null,"a":false},{"i":1999,"k":"para","g":"શ્રીહરિએ ડાકોરના પૂજારીને વાત કરતાં કહ્યું, “અજ્ઞાની લોકો વારે વારે પંચવિષયની માંગણી કરે છે, પણ તેમાં રહેલું દુઃખ જોતા નથી. તીર્થ, વ્રત, દાન, યજ્ઞ વગેરે કરી લાખો વિપ્રને જમાડે છે, મોટાં મોટાં મંદિર કરાવી ભગવાનની પ્રતિમા પધરાવે છે અને આજીવિકામાં ગામગરાસ વગેરે આપે છે, પણ જ્યાં સુધી વિષય પર તાન છે ત્યાં સુધી અજ્ઞાન રહ્યું હોવાથી જન્મમરણથી છૂટતા નથી.”","e":null,"s":["15/49/17-23"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2000,"k":"para","g":"ધરમપુરમાં શ્રીહરિએ નૃપને વાત કરતાં કહ્યું, “જે કરવાનું છે તે ન થયું તે પછી ઇન્દ્ર કે બ્રહ્મા થાય તોપણ શું થયું? વિષયમાં સુખ મનાય ત્યાં સુધી બાળબુદ્ધિ છે. ભવસિંધુ તરવા માટે ભગવાને મનુષ્યજન્મ આપ્યો છે, એવી સમજ ન હોય અને પોતપોતાના મનમાં તે ફાવે તેટલા મોટા કે ડાહ્યા સમજતા હોય, તોપણ તેને મોટા કહેવાય નહિ. સત્સંગ કરે તેની બધી વાતો સુધરે છે. તીર્થ-વ્રતાદિક કરવું તે પણ સત્સંગ થાય તે માટે છે.”","e":null,"s":["16/23/6-15"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2001,"k":"para","g":"ઉમરેઠમાં શ્રીહરિ કહે, “ફાવે તેવાં સરસ ભોજન હોય, પણ ઉદરમાં ગયાં પછી નકારાં થઈ જાય છે અને તેમાં પ્રીત રહેતી નથી. આવો વિચાર વારે વારે કરે તેને વિષયમાત્ર અસાર જણાય છે અને તે શ્રેષ્ઠ હરિભક્ત છે.”","e":null,"s":["17/90/30-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2002,"k":"para","g":"ભીમનાથના ગોસાઈને શ્રીહરિ કહે, “ભગવાનની વાત સમાગમ વગર સમજાતી નથી. સંતના સમાગમથી બ્રહ્મવિદ્યાની વાત સમજ્યામાં આવે છે. જેવો સમાગમનો ખપ તેટલી વાત સમજાય. વાત સમજાયા પછી, કોઈ રૂપવાન માણસ હોય અને તે રોગે કરીને અત્યંત કુરૂપ બની જાય, પછી તેમાં જેવી અરુચિ થાય તેવી અરુચિ વિષયમાં થઈ જાય. જેમ ફાવે તેવા સરસ રસ હોય, પણ તેની ઊલટી થઈ જાય પછી તે દુઃખરૂપ લાગે છે, તેમ દરેક વિષયનો વસ્તુતઃ જો વિચાર કરીએ તો દુઃખરૂપ દેખાય છે. વિષયમાં દોષ દેખતાં શીખે ત્યારે તેમાં પ્રીતિ રહે નહિ.”","e":null,"s":["17/97/36-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2003,"k":"para","g":"વડનગરમાં શ્રીહરિએ વિદ્વાન વિપ્રોને વાત કરી કે, “જ્યાં સુધી જીવને મોક્ષનો ખપ નથી, ત્યાં સુધી વિભ્રાંત મને ફરે છે ને મોહ મદિરાએ કરીને એક મતિ રાખી શકતો નથી. ગુલાબના બાગમાં બેસે ત્યાં સુધી ગુલાબની સુગંધ આવે. મળના ખાડામાં બેસે ત્યારે એવો ગંધ આવે. જેવું ખાય તેવો ઓડકાર આવે છે. જેમ ખાધા-પીધાની ચીજમાં જેવો ગુણ હોય તેવું અંતર થઈ જાય છે. તેવી જ રીતે રૂપ, શબ્દ, સ્પર્શ વગેરે વિષયોનું પણ જાણવું. ભગવાન ને ભગવાનના સાચા સંતના શરણ (આશ્રય) વિના સાચા જ્ઞાનની ગમ પડે નહિ ને અજ્ઞાન જાય નહિ. ભગવાન અને ભગવાનના સાચા સંત તે જ્ઞાનનાં બે નેત્ર છે. બંને નેત્ર વિના અંધ કહેવાય છે. બંનેમાંથી એકનો યોગ ન હોય તોપણ સાચા જ્ઞાનને પામતો નથી. બંનેના જોગ વિના બ્રહ્મા જેવો સમર્થ હોય તોપણ શું થયું? તેના અજ્ઞાનપાશનો નાશ થતો નથી.”","e":null,"s":["18/50/14-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2004,"k":"para","g":"સુરતમાં શ્રીહરિએ પુરજનોને જે વાત કરી હતી તે મુક્તમુનિએ ઉત્તમ નૃપને કહી, “પંચવિષય દસ સાગર કરતાં પણ અધિક ગહરા છે. તેમાં ભૂત-પ્રાણીમાત્ર સુખ દેખી રચ્યાંપચ્યાં રહે છે ને બ્રહ્માંડ રહે ત્યાં સુધી જન્મમરણમાં ભમ્યા કરે છે. વિષય માટે અપાર દુઃખ પામે છે. જ્યાં સુધી વિષયમાં સુખ મનાય છે, ત્યાં સુધી બ્રહ્મા જેવો થયો હોય તોપણ તુચ્છમતિમાં ખપે છે. વિષય બંધનકારી છે ને મોક્ષમાર્ગે વિઘ્નરૂપ છે એવી સમજણ સત્સંગના યોગથી આવે છે. ભગવાન જેવું કોઈ વહાલું ન રહે ત્યારે વિષય છૂટે.”","e":null,"s":["27/45/21-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2005,"k":"para","g":"સુરતમાં શ્રીહરિએ પુરજનોને જે વાત કરી હતી તે મુક્તમુનિએ ઉત્તમ નૃપને કહી, “ચ્હાયે તેવો બુદ્ધિમાન હોય, પણ જો વિષયને ઝેર ન જાણ્યા હોય ને વિષયલાભને જ મોક્ષ માનતો હોય એવા જનને મૂઢ જાણવો અને એવા સંપ્રદાયને મતપંથ જાણવો. ભગવાન પુરુષોત્તમ અને તેનું ધામ (અક્ષરબ્રહ્મ) તે બે વિના અવાંતર રહેલાં અપાર બ્રહ્માંડો, ને તેમાં રહેલાં સ્થાવર, જંગમ, ભૂત-પ્રાણીમાત્ર વિષયભોગમાં સબડે છે. તેમાં રહેલું દુઃખ કોઈને જાણ્યામાં આવતું નથી. જ્યાં વિષયનું ખંડન થતું હોય ને ભગવાનના સંબંધે કરીને જ સુખ માનવામાં આવતું હોય એવો મત તથા એવા ગુરુ, આચાર્ય, તીર્થ, વ્રત, ધામ એ બધાં સત્ય છે. એવાં ગ્રંથ, કીર્તન, બધા શબ્દ સત્ય છે. ત્યાં ધર્મ-ભક્તિ સહિત ધર્મવંશ રહે છે.”","e":null,"s":["27/48/31-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2006,"k":"para","g":"સુરતમાં શ્રીહરિએ હરિજનોને વાત કરતાં કહ્યું, “કથાવાર્તાનો યોગ રાખે તો વિષય ખેંચે નહિ. સત્સંગની વાત વિષયમાં દુઃખ દેખાડે છે ને ભગવાનમાં સુખ દેખાડે છે. ઇન્દ્રિયો-અંતઃકરણ જેટલાં વિષયમાં ચોંટે તેટલો સત્સંગમાં પાયો કાચો છે. અનંત શરીર ધારીને વિષયમાં જીવ વળગ્યો રહ્યો છે, પણ સત્સંગ વિના તેની અરુચિ થતી નથી.”","e":null,"s":["27/84/31-35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2007,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2008,"k":"para","g":"પંચવિષયના ફંદામાં જીવમાત્ર ફસાયા છે. વિષયનો ફાંસલો કોઈનો ટાળ્યો ટળતો નથી. પંચવિષય સારુ શત્રુ પણ મિત્ર બની જાય છે. પંચવિષય મહાબળવાન છે. ભવ, બ્રહ્મા ને મુનિવરોનું માન પંચવિષયે હણ્યું છે. હિરણ્યકશિપુ ને રાવણ જેવાનાં મસ્તક છેદ્યાં છે. ભગવાન અને સંત પાસે પંચવિષય થરથર ધ્રૂજે છે. પાંચે વિષય અહોનિશ તેમને આધીન વર્તે છે. શ્રીહરિનો આશરો કરે ને કપટ રહિત થઈ સંતના વચનમાં વર્તે તેને પંચવિષય પરાભવ કરી શકતા નથી. સંત પાસે પંચવિષયને પલટી નાખવાની ઊલટ વિદ્યા છે, તે શીખે તો રક્ષા થાય. જે સંત નથી તે સર્વે પંચવિષયના દાસ છે.","e":null,"s":["5/47/28-32"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2009,"k":"para","g":"દેહસંબંધી વિષયો બ્રહ્માંડ ભરાય તેટલા અપાર છે. તે અનંત જન્મોથી જીવ ભોગવતો આવ્યો છે, પણ થાક્યો નથી. વિષય કાજે કેટલું દુઃખ તેણે વેઠ્યું છે! જન્મ-મરણ લખચોરાશી - વારંવાર પામીને વિષયથી દુઃખી થયો છે. તેમાં રોગ પણ અનેક પ્રકારના પામ્યો છે. દુઃખ ને રોગનું કારણ વિષય છે. તે વિષયની અરુચિ જીવને થતી નથી. સંતોએ વિષયની અરુચિ કરાવવા નિત્ય વાતો કરવી, કારણ કે વિષયનું બંધન વિકટ છે તે ક્યારેય શસ્ત્રોથી છેદાતું નથી, પણ જ્ઞાનરૂપી શસ્ત્ર વિવેકરૂપી કુશળતાથી વાપરે તો તે વિષયબંધન છેદાય છે.","e":null,"s":["15/25/32-38"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2010,"k":"para","g":"વિષયમાં જ્યાં સુધી સુખ દેખતો રહે છે ત્યાં સુધી જન્મ-મરણ અને જમપુરીનાં દુઃખ પામ્યા કરે છે. એવાં દુઃખ વિષયમાં જ્યારે જુએ અને અંતરમાં ત્રાસ પામે ત્યારે વિષયમાંથી નિવૃત્ત થઈ ભગવાન ભજવામાં સુખ માને. મોતિયા લાડુ દેખવામાં ઘણા ઊજળા છે, પણ તેમાં થોડો સોમલ પડેલો જોવામાં આવ્યો હોય, તો ગમે તેવી ભૂખ લાગી હોય તોપણ જમવાનો ભાવ રહે નહિ. તેમ બીજા કોઈ પણ વિષયમાં ગમે તેટલો પ્રેમ હોય તોપણ તેમાં દોષ દેખ્યામાં આવે તો અપ્રિય થતાં વાર લાગતી નથી. પુરુષને નારી, ને નારીને પુરુષ બંધનરૂપ છે, ને કામદેવ જેવો રૂપાળો મનુષ્ય હોય, પણ જો તેમાંથી જીવ જતો રહે તો તેને પ્રિય લાગતો નથી.","e":null,"s":["19/33(32)/29-36"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":27,"gu":"માયા","en":"Māyā","url":"https://www.anirdesh.com/pbp/index.php?page=chp_27","b":[{"i":2011,"k":"para","g":"શ્રીહરિએ માતાને ઉપદેશ આપતાં કહ્યું, “ભગવાનની માયા સૌ લોકને મોહ પમાડી સંસારમાં ભટકાવે છે. જે ભગવાનને શરણે જાય છે, તે તેમની માયાને તરે છે. બીજો કોઈ કોટિ સાધને કરીને પણ તરતો નથી.”","e":null,"s":["1/53/30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2012,"k":"para","g":"ગઢપુરમાં જીવાખાચરના દરબારમાં સંતોને વાત કરતાં શ્રીહરિએ કહ્યું, “સત્સંગ તો સૌ કરે છે, પણ જેવો ખપ હોય તે પ્રમાણે અંગવૃદ્ધિ પામે છે. અમારો જેણે આશ્રય કર્યો છે તેમાં માયાના ગુણ રહેવા નહિ દઈએ. એવા શુદ્ધ કરીશું કે ફરી તે અશુદ્ધ જ ન થાય. શુદ્ધ કરવા માટે જ અમે નિયમ-ધર્મ પળાવીએ છીએ. સંતોનાં પ્રકરણ ફેરવતા રહીએ છીએ.”","e":null,"s":["5/5/34, 35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2013,"k":"para","g":"શ્રીહરિએ મુક્તમુનિને ભોજન લેતાં વાત કરી, “જીવને અનંત જુગથી માયાનું બંધન વળગ્યું છે. તેને માયાથી મુક્ત કરવાનું તાન ભગવાન અને ભગવાનના સંતને છે. સ્થાવર-જંગમ સર્વત્ર માયાનો પ્રભાવ પ્રગટ જણાય છે. તેમાં માયા-પાર ચૈતન્ય અણુઅણુમાં દિવ્યરૂપે વ્યાપીને રહ્યું છે. એ અમાયિક હોવાથી જ્ઞાનચક્ષુ સિવાયના કોઈ તેને ક્યારેય દેખી શકતા નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2014,"k":"para","g":"“જેમ શેરડીના સાંઠામાં રસ, ગોળ, મિશ્ર અને સાકર ગુપ્તપણે રહ્યાં છે, તે જ્ઞાનીજન જાણે છે અને જેની જેવી રુચિ તેવું ફળ તે શેરડીમાંથી મેળવે છે, તેમ બંધન અને મોક્ષ - બન્ને ગુણ માયામાં છુપાયા છે. જેવો ગુણ સેવે તેવું ફળ તે પામે છે. માયામાંથી છૂટવા ભગવાન તેને મનુષ્ય તન આપે છે. તેમાં પણ જે અજ્ઞાની રહે છે, તેને પાપીઓમાં પણ પાપી જાણવો.”","e":null,"s":["6/101/15-23"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2015,"k":"para","g":"મૂલેન્દ્ર નૃપને શ્રીહરિએ કહ્યું, “માયા અકળ અને અરૂપી છે, તેમાં અનંત સુખ-દુઃખ ભર્યાં છે. સત્ અને અસત્‌રૂપે તે કહેવાય છે. જડ, દુઃખ અને મિથ્યા તેનું નામ છે. અનંત બ્રહ્માંડ તેને વશ છે. આવરણ ને વિક્ષેપ અનંત પ્રકારનો તેમાં રહેલાં છે. સંકલ્પ-વિકલ્પ, અહંમમત્વ અને અપાર હર્ષ-શોકને તે કરાવનારી છે. મહાપ્રલય સુધી તે રહેનારી છે. પછી ભગવાન તેને અક્ષરમાં લીન કરી દે છે. અને જ્યારે બ્રહ્માંડ રચવાની ઇચ્છા કરે છે, ત્યારે તે દીઠામાં આવે છે. મૂળપુરુષ સહિત તે ભગવાનના સંકલ્પ પ્રમાણે કરે છે. ભગવાનના સંકલ્પથી માયા મૂર્ત રૂપ ધરે છે, ત્યારે તેના સંકલ્પ પ્રમાણે દેખાય છે. અને સંકલ્પ ન કરે ત્યારે જેમ બાજીગરના સંકલ્પમાં કંઈ દેખાતું નથી, તેમ કાંઈ દેખાતું નથી. મનના સંકલ્પને આધીન માયાની પ્રવૃત્તિ-નિવૃત્તિ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2016,"k":"para","g":"“મૃત્તિકામાં કાંઈ ઘાટ દેખાતો નથી, પણ જે પ્રમાણે કુંભાર સંકલ્પ કરે તેવો ઘાટ બની આવે છે. તેમ ભગવાનને જેવું કાર્ય કરવું હોય તે પ્રમાણે સંકલ્પ કરે છે અને તે પ્રમાણે કાર્ય થાય છે. સત્સંગમાં મોક્ષમાર્ગમાં જે વિપરીત મતિ તેનું નામ જ મૂર્તિમાન માયા છે.”","e":null,"s":["10/6/5-20, 35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2017,"k":"para","g":"મેઘપુરમાં શ્રીહરિએ વાત કરતાં કહ્યું, “કલ્પવૃક્ષ ને ચિંતામણિ શ્રેષ્ઠ ધન છે. તેમાં કલ્પવૃક્ષ છે તે હોય ત્યાં ને ત્યાં રહે, પણ આપણી ઇચ્છા પ્રમાણે સાથે આવે નહિ. ચિંતામણિ સાથે આવે પણ મર્યા પછી બન્નેમાંથી કોઈ મોક્ષ માટે કામ લાગે નહિ. બન્ને હરિભક્તને વિઘ્ન કરે છે, ભગવાનના સામર્થ્યની દૃષ્ટિએ સર્વે પદાર્થ નિર્જીવ છે માટે ભગવાન વિના ક્યાંય ચોટવું નહિ.”","e":null,"s":["10/20/29-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2018,"k":"para","g":"શ્રીહરિએ તેરા ગામે રામનવમીનો ઉત્સવ કર્યો અને સંતોને ઉદ્દેશીને વાત કરતાં કહ્યું, “માયાનો વેગ અપાર છે. તેને નારદ જેવાને પણ મર્કટમુખા કર્યા છે. પરાશર, સૌભરિ, ચ્યવન વગેરે ઋષિ તથા ઇન્દ્ર, ચંદ્ર, બ્રહ્મા, શિવ વગેરે દેવને પણ વિઘ્ન કર્યું છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2019,"k":"para","g":"“હજારો માણસોને તોપે ઉડાવી દે તેવો સમર્થ હોય તોપણ મનનું કહ્યું માનતાં તેને શરમ રહેતી નથી. આ દેહમાં જીવ વિનાનો જે સાજમાત્ર છે તે માયા છે. દારૂ અને અગ્નિ જુદા રહે ત્યાં સુધી ઊડે નહિ, તેમ બહુ લાજમર્યાદા રાખતો હોય અને અપકીર્તિથી ડરતો હોય તેને મન લોપે નહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2020,"k":"para","g":"“કાયા નગરમાં જીવ રાજા છે. ઇન્દ્રિયો-અંતઃકરણ એની પ્રજા છે. રાજા પ્રજાને જો કબજે ન રાખે તો તે રાજા થઈ બેસે અને જીવ દુઃખી થાય. જીવ વિના દેહ, ઇન્દ્રિયો અને અંતઃકરણ કંઈ પણ સંકલ્પ કરવા શક્તિમાન નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2021,"k":"para","g":"“જીવ ધારે તો તેને દાબીને વર્તી શકે, પણ જો દેહાદિકનું અયોગ્ય કહ્યું માને તો સત્સંગના સુખથી ભ્રષ્ટ કરે. મન કાફરમાં કાફર અને શેતાનોમાં શેતાન છે. જીવનો મિત્ર થઈને જીવને હેરાન કરે છે. સંત ક્યારેય મનનો વિશ્વાસ કરતા નથી.”","e":null,"s":["13/34/19-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2022,"k":"para","g":"સારંગપુરના જીવાખાચરના દરબારમાં શ્રીહરિએ હરિજનોને કહ્યું, “અમે બેઠા છીએ ત્યાં સુધી તો માયા અને અસુરનું લેશ પણ ચાલશે નહિ. વળી, સંત સંતનું હિત કહેશે ત્યાં સુધી માયાનું જોર નહિ ચાલે, પણ એકબીજાની મોટપ દેખીને સહન નહિ કરે ત્યારે માયા અને અસુર પ્રવેશ કરશે. ઉપરથી તે પ્રીતિ રાખશે ને અંદરથી બહુ જુદા રહેશે.”","e":null,"s":["14/82/29-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2023,"k":"para","g":"ગઢપુરમાં શ્રીહરિ હરિજનોને વાત કરવા લાગ્યા કે, “જેટલી કંઈ અમાયિક વાત છે તે સત્સંગમાં જ રહેલી છે. જેનાથી પ્રગટ મોક્ષ મળે છે. માયિક જનને આ વાત દેખ્યામાં આવતી નથી. માયિક જનોની સમજણ માયિક છે. જેની ગતિ જ ભૂચર (જમીન પર ચાલવા) પૂરતી હોય તે ગોચરગતિ (દિવ્ય આત્મા)ની સમજ ક્યાંથી લઈ શકે!!","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2024,"k":"para","g":"“સૂર્યને વાદળું ઢાંકે તેમ આત્માને માયા ઢાંકી દે છે. તેને લીધે આત્માનું બળ હણાઈ જાય છે ને તે માયામાં લપટાય છે. જીવમાં ભગવાન સિવાય જેટલા ઘાટ થાય છે તે માયા છે. તે માયા ઓળખાતી નથી. હરિજનને જ્યાં સુધી જગતના ઘાટ છે, ત્યાં સુધી અંતરમાં સુખ થતું નથી. જ્ઞાનરૂપી સુદર્શન ચક્ર જેને હાથ લાગ્યું તે માયાનું આવરણ કાપે છે.”","e":null,"s":["16/48/10-17"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2025,"k":"para","g":"શ્રીહરિએ જીવક નૃપને વાત કરતાં કહ્યું, “જે ભગવાનને શરણે થયા છે તેને માયા લાગતી નથી. બીજાનો તો તે પરાભવ કરે છે. માયા અનીતિ કરાવે. સત્સંગી થયો તે અનીતિ ન કરે. શરણાગતિને કાળ, કર્મ, માયા, યમદૂત તે પણ સ્પર્શ કરી શકતાં નથી. તેને તો અનંતકોટિ બ્રહ્માંડના અધિપતિ શ્રીહરિ મળ્યા છે, તે જ સર્વસ્વ છે. ભગવાનના નિયમમાં સત્સંગના આશ્રિત વર્તે છે તેને માટે કર્મનું ફળ સાક્ષાત્ શ્રીહરિ પોતે છે.”","e":null,"s":["17/45/30-35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2026,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ મુક્તમુનિને કહ્યું, “દ્રવ્યનો લોભી યથાર્થ વાત કરી શકે નહિ. દ્રવ્યને બંધનરૂપ દેખાડે પણ દ્રવ્યનો સંગ્રહ કરતો હોય તો તેની વાત નિર્જીવ હોય છે.”","e":null,"s":["19/3/5-6"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2027,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2028,"k":"para","g":"મુક્તમુનિએ શ્રીહરિની વાત કરતાં કહ્યું, “શ્રીહરિ કહેતા - જે મનના કહ્યામાં વર્તે છે તેને માયા ગળી જાય છે, તે સત્સંગી હોય છતાં અભાવ લઈને પાછો પડી જાય છે. માટે સંતનો, હરિભક્તનો કે અમારો કોઈ અભાવ લેશે તો તે દિવસે દિવસે ક્ષયરોગી જેમ ઘટી જશે.”","e":null,"s":["13/61/21-23"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2029,"k":"para","g":"ભગવાન ને સંત હેત આપીને જીવને નિજ મૂર્તિમાં બાંધે છે. કોઈ પ્રત્યે ભાવ ને કોઈ પ્રત્યે અભાવ જેવું ભગવાનને વિષે જણાય છે તે તેમની ઇન્દ્રજાળ વિદ્યા જાણવી. નિર્માનીપણું એ એમનો વશીકરણ મંત્ર છે. પોતે દીન થઈને સર્વ જગતને પોતાને આધીન કરી લે છે. જગતનો ઉપહાસ સહે છે તે એમની મોટપ છે. સમર્થ થકા જરણા કરવી તે પ્રતાપ સર્વ થકી અધિક જાણવો. કુમતિજનને આ પ્રતાપ જાણ્યામાં આવે નહિ. આકાશગુણ - નિર્લેપપણું - ગ્રહણ કરી નિષ્કલંકપણે વર્તે છે. નિષ્કલંકને કલંકિત કહે તે કલંક પોતાને ચોટે છે. જે ભગવાનને આ રીતે અમાયિક જાણે છે તે સુબુદ્ધિજન સંસાર-માયાથી પાર થઈ જાય છે.","e":null,"s":["4/26/48-52"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2030,"k":"para","g":"ભગવાનની માયાનું જોર અપાર છે. જીવ જે યોનિમાં જાય ત્યાં બંધાઈ જાય છે ને તેમાં સુખ માને છે, તે માયાનો પ્રભાવ છે. અજ્ઞાનરૂપી અંધકાર સર્વત્ર વ્યાપ્યો છે. તેને કોઈ ખોટો કરવાને સમર્થ નથી. માયાજન્ય સુખ ભ્રાન્તિમાત્ર છે. સુખ જેવું જણાય છે, પણ પ્રાપ્ત કરતાં લાગે છે કે એ કોટિ ગણું દુઃખ છે. આ અજ્ઞાન, અંધારું ટાળવાનો વિચાર સંત વિના કોઈ આપી શકવાને સમર્થ નથી. સંતનો પ્રસંગ કરે ત્યારે સંત તેને જ્ઞાન આપે છે. પછી અજ્ઞાનતમથી હટે છે. પછી જેમ જેમ સત્સંગ કરે, તેમ તેમ મોક્ષનો અધિક રંગ ચઢે. મોક્ષમાર્ગે જે વિઘ્ન કરે તેની સાથે શત્રુભાવ રાખે. મોક્ષનું થાણું જ્યાં માને ત્યાં તન-મન-ધન સમર્પણ કરે એ મોક્ષદાતા ગુરુ પાસે મન ચોરે નહિ. મોક્ષદાતા ગુરુનાં લક્ષણ પણ જાણી રાખવાં.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2031,"k":"verse","g":"‘મોક્ષ કો જાને જિહાં થાના, ધન-તન દેવત તાકું દાના.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2032,"k":"verse","g":"મોક્ષદાતા ગુરુ માનત તેહા, તિનમેં મન ન ચોરત એહા.’","e":null,"s":["9/23/17-24"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2033,"k":"para","g":"માયિક અને અમાયિક વચ્ચે રાત્રિ ને દિવસ જેટલો ભેદ છે. બ્રહ્માંડનું સુખ માયિક છે ને તેમાં અપાર દુઃખ રહેલું છે. ભગવાનનું સુખ અમાયિક છે, એ સિવાયનાં સુખમાત્ર માયિક છે. આ લોકમાં પણ ભગવાનની કથાવાર્તા, કીર્તન, સેવા અમાયિક છે. અમાયિક સુખને કાળ પરાભવ કરી શકતો નથી. એ અવિનાશી સુખ છે. સત્પુરુષના સંગે કરીને એ સુખ પમાય છે. નારદ, શુકજી જેવાને પણ અમાયિક સંત મળ્યા ત્યારે અમાયિક માર્ગ હાથ લાગ્યો.","e":null,"s":["25/58/9-16, 23-24"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":28,"gu":"કપટ નિષ્કપટ","en":"Kapat-Nishkapat — Deceit and Sincerity","url":"https://www.anirdesh.com/pbp/index.php?page=chp_28","b":[{"i":2034,"k":"para","g":"ચૂડાપુરમાં શ્રીહરિએ કહ્યું, “હરિભક્ત બે પ્રકારના - કપટી અને નિષ્કપટ. નિષ્કપટ સાધારણ વર્તે. બધા સાધુને તે સરખા માને. અધિક ન્યૂનનો વિચાર તેને ન હોય. કપટી અધિક વર્તી બતાવે ને સાધારણનો દોષ કહે, પણ મનમાં તો નિષ્કપટને યથાર્થ જાણતો હોય. આ બન્નેનો ભેદ પાકા અંતરવાળો કળે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2035,"k":"para","g":"“કપટી હોય તે કપટરહિત ભક્તને પોતાના સંગમાં ખેંચી જાય છે. આમ, બન્ને મળીને પાકા અંતરવાળા હરિભક્તનો દોષ દેખાડી તેને પાછો પાડે છે. એ હરિભક્ત આ બન્નેની ઠગવિદ્યાને ક્યારેય પરખી શકતો નથી. સૂધા સારા જણાતા હોય એવા હરિજન પણ એમને ઠગી જાય છે. અવસર આવ્યે તેનું રૂપ ઉઘાડું થાય છે ત્યારે તેની પરખ પડે છે.”","e":null,"s":["4/74/39-42"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2036,"k":"para","g":"મોડા ગામે રણમલજીને ત્યાં શ્રીહરિ વાત કરતાં કહે, “નિષ્કપટપણે સત્સંગ કરે છે તેની પ્રીતિ સત્સંગમાં દિન દિન વધતી રહે છે. સંતો-ભક્તોને પણ તેના પ્રત્યે પ્રીત અધિક ને અધિક થાય છે. જે નિષ્કપટ નથી તેનું મોં સદા મ્લાન દીસે છે. જેવો અંતરનો ભાવ હોય, તેવો મુખ પર જણાઈ આવે. કપટીની આંખો તેનું કપટ કહી દે છે.”","e":null,"s":["5/16/29-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2037,"k":"para","g":"અલર્ક રાજાને શ્રીહરિએ વાત કરતાં કહ્યું, “સત્સંગે કરીને જેવી મતિ થાય છે તેવી અષ્ટાંગ યોગથી પણ થતી નથી. બીજાં અનંત સાધન કરો તેનું ફળ સત્સંગ છે. કોટિ જન્મ સુધી સાધન કરે તોપણ તે કોઈ સાધન સત્સંગને તોલે ન આવે. સત્સંગમાં દંભથી ચાલે તે પાર ન પડે, અને અતિ દંભી હોય તે વિમુખ થઈને સત્સંગની દેશી કાઢે, અને સત્સંગની વાત શીખીને વિમુખ જીવને ધૂતે. એમ સત્સંગ તજીને જે સત્સંગનો દ્રોહ કરે તે કૃતઘ્નીમાં કૃતઘ્ની, ચંડાળમાં ચંડાળ અને નીચમાં નીચ છે.”","e":null,"s":["9/45/9-13"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2038,"k":"para","g":"શ્રીહરિએ જેતપુરમાં મૂળુવાળાને વાત કરતાં કહ્યું, “ગમે તેટલો ધર્મ પાળે પણ જો લોકને દેખાડવા માટે હોય તો અંતે તે વિમુખની ગતિને પામે છે. ભગવાન તેને સહાય કરે નહિ. નિર્દંભપણે વાત કરે તથા હરિનાં ગ્રહણ કરવા યોગ્ય જે વચન તેને નિર્દંભ થઈને પાળે તેનું નામ સત્સંગ છે. સત્સંગ (સત્પુરુષ) વિના સત્સંગ ઓળખાય નહિ. લોક ઠગવા ધર્મનો વેષ ઉપરથી ધારે અને અંતરમાં ધર્મનો દ્વેષ રાખતો હોય તે જમપુરીનો અધિકારી છે. પોતામાં અવગુણ પરઠે અને સત્સંગને સત્ય માની નિર્દંભપણે ગુણ ગાય તેનો ઉદ્ધાર થાય છે.”","e":null,"s":["10/15/28-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2039,"k":"para","g":"આખા ગામમાં શ્રીહરિએ કહ્યું, “જે સાચા સંત સાથે ને હરિજન સાથે સુમેળ ન રાખે ને કુમેળ રાખે તે અમારો દ્રોહી છે. જે હરિજન સાચા સંત કે ભક્ત પાસે ચિત્ત ચોરે, કપટ રાખે એટલો તે કાચો રહે છે. સાચા સંત-હરિજનને મનથી નિર્દોષ જાણી તેમની સાથે સરળ વર્તે એવા ભક્તને સત્સંગનો આનંદ અખંડ રહે છે.”","e":null,"s":["14/31/26-27"],"sv":["साचे संत हरिजन से, जितनो चित्त चोरात ।\n\n तितनो वगल हे ताहि में, प्रसिद्ध आत देखात ॥\n\n साचे संत हरिजन, तिनसे जितने सरल रहत ।\n\n शुद्ध हि जानत मन, सत्संग में मोज करत ॥"],"mt":false,"gl":null,"a":false},{"i":2040,"k":"para","g":"શ્રીહરિએ દંભીની ઓળખ પત્રમાં લખતાં કહ્યું, “મનમુખી અને દંભી ભક્ત મારા ધામને પામતો નથી. જે નિર્દંભ વર્તે છે તે જ મારા ધામને પામે છે. પૂજાવા માટે દંભ થતો હોય છે. દંભી પુરુષ બીજાને પ્રતીતિ આવે તેમ વર્તે. સત્યને ત્યજી જે વર્તન થાય તેટલો દંભ જાણવો. દંભીમાં અપાર કલા રહેલી હોય છે. તે કોઈ જનના કળ્યામાં આવતી નથી, દંભીનું કલ્યાણ થતું નથી. દંભ ન રહે તે માટે અમે વારંવાર વર્તન બદલીએ છીએ.”","e":null,"s":["15/72/21-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2041,"k":"para","g":"શ્રીહરિએ પત્રમાં વાત લખતાં કહ્યું, “જે નિષ્કપટભાવે સત્સંગ કરે છે, તે ભગવાનના ધામમાં છતી દેહે બેઠેલા છે. ભગવાનનો અનન્ય આશ્રય હોય અને કોઈ પ્રકારનું અભિમાન ન હોય તો તેનો દંભ ભગવાન અંતકાળે પણ ત્યાગ કરાવે છે. અભિમાન ન હોય તો ભગવાન તેનું સંભાળી લે.”","e":null,"s":["15/84/13-16"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2042,"k":"para","g":"વડતાલમાં શ્રીહરિએ મુખી અને પગીને જે વાત કરેલી તે મુક્તમુનિએ કહી, “શ્રીહરિ કહે - સંતો-હરિભક્તોને વિષે જેવો ભાવ પરઠાય એવી પોતાની મતિ થાય છે. શુભ ભાવથી શુભ મતિ થાય, અશુભ ભાવથી અશુભ મતિ થાય. પોતાના દોષને ગુણ કરીને દેખાડે તે સત્સંગમાં રહે તોપણ મોટપ પામે નહિ. પાંચ દસ સંત તથા પાંચ પચીસ હરિભક્તોના ગુણ ગાય, પણ મનમાં પોતાના સમાન કોઈને માને નહિ. અંતર્યામી ભગવાન સંત-હરિભક્તમાં જેવી તેની મતિ હોય તે પ્રમાણે કરી દે છે. નિર્દોષ મતિ હોય તો નિર્દોષ થાય છે, અને દોષયુક્ત મતિ હોય તો દુષ્ટ થાય છે, જેથી વિના અગ્નિએ અગ્નિની પેઠે અંતરમાં વ્યથા રહ્યા કરે છે. નિષ્કપટ સત્સંગ કરે તે જ ટકે છે. ભગવાન આગળ કપટ ચાલતું નથી. સત્સંગથી ફાવે તેવા જનો સુધરે છે, પણ કપટી સુધરી શકતો નથી, કપટી ચપટ થઈ જાય.”","e":null,"s":["16/58/18-27"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2043,"k":"para","g":"વડતાલમાં શ્રીહરિએ વાત કરતાં કહ્યું, “અમને પ્રસન્ન કરવા દિલ ચોર્યા વિના જે કાંઈ કરે છે તેના ઉપર પ્રસન્ન થઈએ છીએ. જાતિ-કુજાતિ જોતા નથી. દિલચોર હોય તેને કનિષ્ઠ માનીએ છીએ. સત્સંગ કરવામાં જેટલું દિલ ચોરાય છે તેટલી હેતમાં કસર રહે છે. નિર્દંભ આચરણ અમને ગમે છે.”","e":null,"s":["17/32/28-29"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2044,"k":"para","g":"શ્રીહરિ ગઢપુરમાં સંતોને કહે, “જેવા બહાર હોય તેવા અંદરથી વર્તે તો સાચો વેશ કહેવાય. એમ સમજી સત્સંગ કરે તેને તે ફળીભૂત થાય છે.”","e":null,"s":["18/14/27"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2045,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ મુક્તમુનિને કહ્યું, “જે વસ્તુ ભગવાન અને સંતને અર્થે કામ ન આવી તે બંધનકારી છે. ભગવાનના ઉપયોગમાં આવે એટલું જ નિર્બાધ છે - એવી નિષ્કપટ મતિવાળા ભક્તથી ભગવાન લગારેય દૂર રહેતા નથી.”","e":null,"s":["19/3/9-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2046,"k":"para","g":"બોટાદમાં શ્રીહરિએ ભગાશેઠ આદિ ભક્તો આગળ વાત કરતાં કહ્યું, “સમજણમાં કસર રહે છે તેટલાં વિઘ્નો આવે છે. જે હરિભક્ત કપટ, દંભ, માન-મત્સરથી રહિત થઈને વર્તતો હોય અને સંત-હરિભક્તને દિવ્ય માનતો હોય તેનો જ સંગ રાખવો. જેટલો હરિભક્તમાં મનમેળ રહે, તેટલો જ સત્સંગ છે. મન ચોરાય તેટલો કુસંગ પ્રવેશ કરે છે.”","e":null,"s":["19/12/22-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2047,"k":"para","g":"શ્રીહરિએ જેતલપુરના મહોલ પર વાત કરી કે, “દંભી જેટલું કંઈ કરે છે તે લોકને દેખાડવા કાજે કરે છે. દંભીનું કોઈ બીજું નહિ પણ પોતે જ પ્રમાણ છે. સત્સંગમાં જેટલા દંભી છે તે સાચા સંત ને હરિજનો કરતાં પોતાનું વર્તન અધિક દેખાડે છે અને સાચા જનમાં દોષ જણાવે છે. વિશ્વાસી લોકો દંભીને ભગવાન જેવા માને છે ને બીજાનો દોષ લે છે. દંભી અધિક વાની રાખતો હોવાથી તેને સૌ તરત માને છે, પણ સરળ નિર્દંભી સંતને માને નહિ. દંભીનો સત્સંગ પણ અધિક દેખાય. તે લોક ઠગવા વર્તે છે. સાચા સંત દંભીને નખશિખ ઓળખે છે, પણ તેની પ્રતિષ્ઠા ભંગ કરતા નથી. દંભી હોય તે બને તેટલો છાનો સંતનો દ્રોહ કર્યા વિના રહે નહિ, ઉપરથી સારો રહે. એવાનો સંગ કરે તેને સંત-હરિભક્તોનો ભાવ ન રહે ને કુસંગને તે અધિક સત્સંગ માને છે.”","e":null,"s":["19/39(38)/21-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2048,"k":"para","g":"વડતાલમાં ગોમતીકાંઠે સભાજનોને વાત કરતાં શ્રીહરિએ કહ્યું, “સત્સંગ કરે છે તે મોક્ષના ખપવાળા છે પણ સમજણમાં બહુ ફેર છે તે રુચિ અને ભાવથી દેખાય છે. ભગવાન વિના ક્યાંય સુખ ન માને તેવા હજારોમાં એકાદ જ હોય. દંભીને તો અમે યથાર્થ ઓળખીએ છીએ. દંભી તો સાચાથી પણ અધિક ભાવ દેખાડે છે. તેથી સાચા હરિભક્તો તેમાં લેવાઈ જાય છે. પોતાને લોકો માને તેમાં જ દંભીઓને વર્તવાનું ધ્યાન હોય છે. દંભીનું જ્ઞાન ગુપ્ત હોય છે. તેને જે માને તેની તે પ્રશંસા કરે છે અને તેને ખોદે તેને કુસંગી માને છે, પણ કપટીને જે સરસ માને છે તે કપટીની ગતિ જ પામે છે. માટે વિચારીને કપટીને પારખી લેવો. કપટ કળ્યામાં આવે તો જાહેર ન થાય તેમ તેની શિક્ષા કરવી, જેથી સત્સંગની લાજ જાય નહિ. સર્વોપરી સત્સંગની અપાર આબરૂ છે તેનું જતન કરે તો જ રહે. મમત્વ હોય તેટલું જતન થાય. જેને પોતાના જેવી જ સત્સંગની જતન કરવાની વૃત્તિ હોય તે ભગવાન સમાન ગુણવાળો કહેવાય.”","e":null,"s":["19/60(59)/28-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2049,"k":"para","g":"વડતાલમાં ઉત્સવ બાદ શ્રીહરિએ હરિજનોને વાત કરતાં કહ્યું, “સાચા કરતાં દંભીનું બહુ દેખાય, પણ ધર્મનિયમથી ખસે છે ત્યારે કોઈ ભાવ રાખતું નથી. દંભી ફાવે તેવો હોય, પણ અમે એવી પ્રથા બાંધી છે ને ત્યાગી-ગૃહીની એવી સડક કરી છે કે તેનાથી સત્સંગ વિરુદ્ધ વાત થઈ શકે નહિ. નટના દોરની પેઠે સાવધાન થઈને વર્તે ને ગફલત ન રાખે તો જ ત્યાગી અને ગૃહી પોતપોતાની પ્રથામાં વર્તી શકે. પ્રથા લોપે તો પોતે લોપાઈ જાય, એવી અમે વેદ-પુરાણ સંમત પ્રથા હજારવાર તપાસીને બાંધી છે.”","e":null,"s":["19/61(60)/3-4, 13-19"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2050,"k":"para","g":"આમોદમાં દીનાનાથ ભક્તને ઘરે શ્રીહરિએ વાત કરતાં કહ્યું, “ભગવાનનો જેને ખપ નથી તે દુર્બુદ્ધિ રહે છે. કપટનો ત્યાગ કરી સત્સંગ કરે તો દુર્બુદ્ધિ ટળે. નિષ્કપટ વર્તે તે જ બુદ્ધિશાળી છે. આચરણમાં કપટ રહે તેટલો નિર્મત્સર સંત સાથે અંતરાય રહે. કપટ રાખે તેટલું દુઃખ મળે જ છે. શરીરમાં તેને એવો વ્યાધિ થાય છે કે જાણીએ જીવ હમણાં નીકળી જશે! નિષ્કપટ સંતમાં કપટ પરઠે તો તે કપટ દોષ તેને વળગે છે. જો પોતામાં દોષ દેખતો રહે તો તેને રતીભાર દુઃખ રહેતું નથી, બીજાના ગુણ ગ્રહે તે ઉત્તમ પુરુષ કહ્યો છે. ગુણગ્રાહ્યતા એવો ગુણ છે કે તેનાથી ઉત્તમ કીર્તિ પ્રાપ્ત થાય છે.”","e":null,"s":["27/21/14-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2051,"k":"para","g":"સુરતમાં શ્રીહરિએ વાત કરતાં કહ્યું, “કપટ તજી જે ભક્તિ કરે છે તેને દુઃખ આવે ત્યારે એ દુઃખને ટાળવા બીજા નિષ્કપટ સંત-હરિભક્તો, ભગવાનની પ્રાર્થના કરે છે. તેવાની નિષ્કામ પ્રાર્થનાથી શ્રીહરિ જરૂર સહાય કરે છે, પણ કપટીની સહાય તે કરતા નથી. માટે કપટનો ત્યાગ કરીને સત્સંગ કરવો.”","e":null,"s":["27/99/29-32"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2052,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2053,"k":"para","g":"મુક્તમુનિ કહે શ્રીહરિએ મને વાત કરી હતી કે, “સંત-હરિભક્તને દિવસે દિવસે અધિક ગરજુ થવું અને દંભનો ત્યાગ કરવો એ જ સત્સંગ કરવાનું ફળ છે. ગરજુનો સત્સંગ શોભે છે અને શુક્લ પક્ષના ચંદ્રની પેઠે વૃદ્ધિ પામે છે.” એમ દરેક વાતમાં શ્રીહરિ નિર્દંભપણાનું પ્રતિપાદન કરતા. દંભીનો શ્રીહરિ મળની પેઠે ત્યાગ કરતા.","e":null,"s":["17/25/33-37"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2054,"k":"para","g":"નિષ્કપટ થઈને ભગવાન ભજવાની બુદ્ધિ છે તે દેવથી પણ ઉત્તમ બુદ્ધિ છે. નિષ્કપટ હોય તેને જ શ્રીહરિ ને સત્સંગમાં રુચિ થાય છે. કપટીની મોટપનો ક્યારેક ભંગ થાય છે અને પછી તે શોભતો નથી, મોટો શાહુકાર હોય અને તેનું કપટ ઉઘાડું થાય તો માની સ્વભાવનો હોય તો મર્યા વિના રહે નહિ.","e":null,"s":["11/10/20-23"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2055,"k":"para","g":"ભક્તોના દોષો ટળે તેની ચાડ શ્રીહરિ અંતર્યામીપણે રાખતા. જનોના ઉત્તમ ગુણો જેટલા વધે તેમ જતન કરતા. તેમાં પણ નિષ્કપટપણું એ તો અમૃત જેવો ગુણ છે. કપટ એ ઝેર છે. શ્રીહરિ કપટીનો ત્યાગ કરતા અને નિષ્કપટ વર્તે તેમાં અનુરાગ રાખતા, કોઈમાં નિષ્કપટપણું હોય છતાં થોડું કપટ રહી જતું હોય તો શ્રીહરિ એમાં અમૃત છે તેટલું ગ્રહણ કરતા ને તેટલો પ્રેમ દાખવતા.","e":null,"s":["15/59/36-38"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2056,"k":"para","g":"શ્રીહરિ વારે વારે કપટીની વાતો બહુ કરતા, કારણ કે વિશ્વાસી ભક્ત કપટીને પરમ એકાંતિક કરીને માને છે. પૂરેપૂરો કપટી હોય તે સહજમાં ઓળખાતો નથી. તે સાચા સંત કરતાં દસગણું સારું વર્તન દેખાડે છે અને લોકો જ્યારે તેનો વિશ્વાસ કરે છે ત્યારે તે સાચાને ખોટા અને ખોટાને સાચા કહે છે. વળી, દંભથી અગ્રેસર બનીને સ્વયં પૂજાવા લાગે છે.","e":null,"s":["19/26(25)/34-38"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2057,"k":"para","g":"સંતની સભાથી જે જુદી ગોષ્ઠી કરે તથા પૂજાવાનો દંભ કરે તે વિમુખથી પણ વિમુખ છે. તેમને વચનમાં વર્તવું કઠણ પડે. ગુપ્ત જ્ઞાનગોષ્ઠિમાં મૂરખ જનોને ભાવ અધિક રહે અને તેને એટલા જ લોકો ગમે. સભાથી પૃથક્ જ્ઞાનગોષ્ઠિી કરનારા મુક્તમુનિ જેવા હોય તોપણ વિમુખ કહેવાય. એમ શ્રીહરિ વારે વારે કહેતા, તોપણ દંભી જુદા જ ચાલતા.","e":null,"s":["19/30(29)/36-39"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":29,"gu":"શ્રીહરિની રુચિ, સ્વાભાવિક ગુણ","en":"Shrihari's Likes and Natural Virtues","url":"https://www.anirdesh.com/pbp/index.php?page=chp_29","b":[{"i":2058,"k":"para","g":"શ્રીનગરમાં નવાવાસમાં ભાત-ભાતનાં સ્વાદિષ્ટ વ્યંજન થાળમાં ભર્યા હતા. શ્રીહરિ જમતાં જમતાં કહેવા લાગ્યા કે, “કોટિ જન્મથી સ્વાદ ચાખ્યા પણ તેનો પાર આવતો નથી. તેનું નામ જ મોહ છે... મોહનો મારગ છૂટે તો જ ભગવાનમાં સ્નેહ થાય છે. માટે મારા ભક્તોને તેમાં દોષ દેખાડી, અભાવ લાવી, હું ત્યાગ કરાવું છું. જ્યાં સુધી રસાસ્વાદ, કામ, લોભ, સ્નેહ અને માન આદિ શત્રુ છે ત્યાં સુધી મોહ ટળે નહિ. અને મોહ ટળ્યા વિના પ્રભુમાં પ્રીતિ થાય નહિ. પાતાળથી પ્રકૃતિ પુરુષ સુધીનું સુખમાત્ર મોહથી આવૃત્ત છે. તેનો દોષ જાણ્યા વિના અભાવ બુદ્ધિ ન થાય. જ્યાં સુધી વિષયનો અભાવ ન થાય ત્યાં સુધી મોહ પણ ટળતો નથી. મોહ જીવને જન્મ-મરણનો હેતુ છે. મનુષ્ય, મોહનો અભાવ જે કરાવે છે તેનો અભાવ લે છે પણ મોહનો અભાવ તેને આવતો નથી. મર્યા વિના મોહ ન જાય. એ કરોડ પ્રકારની વાતથી દેખાઈ આવે છે. મારામાં મોહનો લેશ નથી. મારો આવો સ્વભાવ તમે બધા જાણો છો. મને નિશ્ચય ભગવાન માનો છો. મારા સ્વરૂપનું જ્ઞાન છે. મારી સિવાય બીજા બધા મોહમાં બંધાયેલા છે, એમ જે માને છે, વળી, મને જીવનું જીવન માને છે અને બીજાને માયાના ગુલામ જાણે છે, મારા સંતને દંભ રહિત સાચા ત્યાગી માને છે, ત્યારે અમારું વચન તેના હૃદયમાં પ્રવેશ કરે છે.”","e":null,"s":["4/99/21-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2059,"k":"para","g":"રામદાસ સ્વામીને શ્રીહરિ કહે, “રઘુનાથદાસને અમે મળવા આવ્યા હતા, પણ તે અમને મળ્યા નહિ. તમે તેને બોલાવી લાવો તો અમે તેને ગાદી સોંપી દઈએ. અમારે અધિકારનો મોહ નથી. પાતાળથી સત્યલોક, પ્રકૃતિ-પુરુષ સુધીના સુખમાં અમે જમપુરીથી વધારે દુઃખ માનીએ છીએ. ભગવાનની સ્મૃતિ ભુલાવે તે બધાં દુઃખ જ છે. તે પછી ભલેને અતિ સુખ કહેવાતાં હોય તોય અમે તેને ઘોર નરકના કુંડ જાણીએ છીએ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2060,"k":"para","g":"“અમારો સિદ્ધાંત તો એ છે જે ભલે અતિશય દુઃખ હોય, પણ તે દુઃખમાં ભગવાનની સ્મૃતિ હોય તે પરમસુખ છે. અમારા જીવમાં એમ મનાયું છે. ભગવાનની વિસ્મૃતિ કરાવે એવાં વૈકુંઠનાં સુખ હોય તોપણ તેને ઘોર જમપુર જાણીએ છીએ. અમારું મન ત્યાં ટકતું નથી. બીજા લોકો અમને માને કે ન માને, પણ ભગવાનમાં અખંડ ચિત્ત રહે તે જ મોટો અધિકાર છે, એમ અમે માન્યું છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2061,"k":"para","g":"“હરિજનનો દાસાનુદાસ થઈને રહું એટલો ઘાટ મનમાં રહ્યા કરે છે. અને અહોનિશ ધર્મ, જ્ઞાન, વૈરાગ્ય અને ભક્તિ ઉપર તાન રહ્યા કરે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2062,"k":"verse","g":"‘દાસાનુદાસ હરિજન કે હોઊં, ઇતનો ઘાટ રહત હે મોએ;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2063,"k":"verse","g":"ધર્મ ભક્તિ વૈરાગ્ય રુ જ્ઞાના, તાકો નિશદિન રખના તાના.’","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2064,"k":"para","g":"“અમને ઉત્તમ પ્રકારનાં ખાન-પાન, અમૂલ્ય વસ્ત્રો અને આભૂષણો, શ્રેષ્ઠ વાહનનો યોગ રહે છે, પણ આ સઘળું અમે મહા દુઃખરૂપ માન્યું છે. ઉત્તમ વિષય પ્રાપ્ત થાય ત્યારે એમ માનીએ છીએ જે તપમાં કશી ખામી આવી છે.”","e":null,"s":["5/58/25-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2065,"k":"para","g":"ફાગણ વદ-૧૧, પાપમોચિની એકાદશીને દિન શ્રીહરિ જેતપુરમાં હતા. સાથે સંતો તથા સુરા, માતરા, સોમલા, અલૈયા વગેરે રાજાઓ પણ હતા. ભદ્રાવતી - ભાદર નદીમાં સૌ સાથે શ્રીહરિએ સ્નાન કર્યું. જળમાં ઊભા રહીને તાળી વજાડીને ‘ધન્ય જમુનાજી...’ તથા ‘કાંઈ દુર્લભ હરિજન...’ કીર્તનો ગવરાવ્યાં. દિવસ ચાર ઘડી ચઢ્યો ત્યાં સુધી નાહ્યા. પછી જળની બહાર નીસરી વસ્ત્રો ધારણ કર્યાં. તે વખતે સોમલા ખાચરે જરા ઊંચેથી મર્મનાં વચન કહ્યાં, “અલૈયા! ગભરાશો નહિ, ફરાળ તૈયાર છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2066,"k":"para","g":"ત્યારે મહારાજ કહે, “એકાદશીનો ઉપવાસ માસમાં બે વાર આવે છે, તે અવશ્ય કરવો. એકાદશી જો ફરાળ રહિત નકોરડી કે નિર્જળ કરવામાં આવે તો તેનું ફળ બહુ મોટું પ્રાપ્ત થાય છે. આજે ફરાળની કોઈ આશા રાખશો નહિ, ભજન કરીને દહાડો કાઢવાનો છે. વળી, એકાદશી એ ભગવાનનો વાસર (દિવસ) છે. બીજા દિવસો કરતાં આ દિવસ ઉત્તમ કહેવાય છે. એક એક એકાદશીને દિવસે ચોવીસે અવતારમાંથી એક એક અવતાર રહેલા છે. એકાદશીનાં પણ ચોવીસ સ્વરૂપ છે. આજે પાપમોચનીનું અનુપમ વ્રત છે. એટલે કોઈએ ફરાળ કરવાનું નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2067,"k":"para","g":"ત્યારે કાઠી કહે, “અમે તો હરિભક્ત થયા પછી પાપ ક્યાં રહ્યાં?”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2068,"k":"para","g":"શ્રીહરિ કહે, “તમે શાસ્ત્રની રીત જાણતા નથી. ભવ, બ્રહ્મા, ઇન્દ્રાદિક દેવતા પણ એ રીત જાણીને વર્તે છે. જેટલાએ શાસ્ત્રની આજ્ઞા ઉપર પગ દીધો છે તેની આજ સુધી ફજેતી થતી રહી છે. દેવો ઈશ્વરો તો મહાસમર્થ કહેવાય, તેની પાસે મનુષ્ય શા લેખામાં? એ મોટા હતા તોપણ આજ્ઞા લોપી તો કલંક લાગ્યાં છે. મનમુખી વર્તનાર બેહાલ થયા છે. જેને સત્સંગ રાખવો હોય તેણે લગારેય પણ મનમુખી ન થવું. નટ જેમ દોર પર નજર બાંધે છે, તેમ આજ્ઞારૂપી દોર પર નજર રાખીને જે ચાલે તેની જીત થાય છે. ભૂલથી પણ વચન ભંગ કરે છે તેની ફજેતી થાય છે. વળી, હરિભક્તને પાપ ન હોય તેમ કહો છો, પણ ભગવાન સિવાય બીજામાં વૃત્તિ રહે તે પાપ છે. અને અમે તો એને જ હરિભક્ત જાણીએ છીએ કે જે અમારાં વચન પાળે, ગમતામાં વર્તે, નાની-મોટી આજ્ઞાઓમાં વિશ્વાસ કરે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2069,"k":"para","g":"રામદાસ, મુક્તાનંદ સ્વામી આદિ સંતો કહે, “મહારાજ! અમે સદાય આપના વચનમાં રહેવાનો નિશ્ચય કર્યો છે ને તેમાં જ લાભ માન્યો છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2070,"k":"para","g":"પછી નહાઈને ઉતારે આવ્યા ત્યારે બધા કાઠી ભક્તોએ હાથ જોડીને કહ્યું, “મહારાજ! તમારા વચનમાં સુખ છે, તમને રાજી કરવા છે. અમે એકાદશીને દિવસે ફરાળ કરીશું નહિ.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2071,"k":"para","g":"આ સાંભળી શ્રીહરિ બહુ રાજી થયા. શ્રીહરિ કહે, “ખપ વિના સત્સંગમાં ટકાય નહિ. સત્સંગ કરીને અભાવ લે તો એકેય ગુણ રહે નહિ.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2072,"k":"verse","g":"‘નૃપ કહત કર જોરિ કે, શ્રીહરિ કું તેહિ વાર;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2073,"k":"verse","g":"તુમારે વચન મેં સુખ હે, હમ કિયે નિરધાર.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2074,"k":"verse","g":"હમ અબ કોઉ વાર, એકાદશી કે દિન તેહિ;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2075,"k":"verse","g":"કરનો નહિં ફરાર, દુખિ હોવે તબ જોર નહિ.’","e":null,"s":["6/64/12-40, 65/1-2"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2076,"k":"para","g":"લોયા-નાગડકામાં શ્રીહરિએ સંતોની પંક્તિ કરી. પોતાના સાધુને ઉચ્ચકોટિ પર લઈ જવા જમવાની રીત પોતે હેતથી શીખવવા લાગ્યા. પ્રથમ પોતે અન્ન લઈ એક પાત્રમાં મેળવ્યું ને જળ મિલાવી નીરસ કર્યું. પછી સૌને તે બતાવીને કહેવા લાગ્યા, “મારી આજ્ઞાથી મેળવીને જળ નાખીને જમે છે તે નિષ્પાપ થાય છે. જે ત્યાગી મેળાવ્યા વિના જમે છે તેને પંચવિષયમાં અનુરાગ છે એમ જાણવું. પૂર્વે મહામુક્ત જે કહેવાતા હતા તે પણ દેહભાવને લીધે ભ્રષ્ટ થયા છે. પંચવિષયમાં જેને જેટલી પ્રીતિ હોય તે ભોજનટાણે જણાઈ આવે છે. મેળાવીને જમતો હોય તો જાણવું તેને પંચવિષયમાં પ્રીતિ નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2077,"k":"para","g":"“જેમ જિહ્‌વા બધું એક રસ કરી કંઠ નીચે ધકેલે છે, તેમ પાત્રમાં બધું એકરસ કરીને જમવું. એ નીરસ આહાર પણ અમુક માત્રામાં જ લેવો. શબ્દ, સ્પર્શ, રૂપ, રસ અને ગંધ - પાંચે વિષય આખો મીંચીને ભોગવવા નહિ. વિષયના પ્રત્યેક દ્વાર પર મારી આજ્ઞારૂપી મૂર્તિ ઊભી છે, તેને પૂછીને પગ મૂકવો. વિચારીને ક્રિયા કરવી.” આટલો ઉપદેશ આપી શ્રીહરિ ખેસ આડસોડે નાખી સંતોને પ્રેમપૂર્વક પીરસવા લાગ્યા.","e":null,"s":["4/56/1-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2078,"k":"para","g":"સમઢિયાળામાં લાખાખાચરને ઘરે શ્રીહરિ દૂધ, ભાત, સાકર, જમીને દહીં, ભાત, સાકર જમ્યા અને બોલ્યા, “દહીં સાકર જ્યારે અમે જમીએ ત્યારે અમને શીતળતા રહે છે. ઉનાળાનો તાપ અમારાથી સહન થતો નથી. પૂર્વે લવિંગ, મરચાં, કસ્તૂરી વગેરે ઘણુંક જમેલા. તે વખતે સાત વર્ષ વનમાં ફરીને તપ કરવાથી શરીર શૂન્ય જેવું થઈ ગયું હતું. અને ઈશ્વર-ઇચ્છાથી તન રહ્યું હતું. શરીરનું અનુસંધાન અમે રાખતા જ નહિ, પરંતુ સત્સંગરૂપ પ્રારબ્ધથી દેહ રહ્યો. નહિ તો અમે સદા વનમાં વિચરતા ત્યારે સિંહ સર્પાદિકની વચ્ચે રહેતા, પણ તેનાથી ક્યારેય ડરતા નહિ. વળી, ઘણા દિવસો સુધી તો અન્ન-જળાદિકનો પણ ત્યાગ કરેલો. ત્યારે તો દેહ રહેવો અશક્ય હતો. સત્સંગમાં આવ્યા પછી રામાનંદ સ્વામીએ અમને વચનરૂપી પાંજરામાં રાખી તેમની રુચિ પ્રમાણે આ દેહનું જતન કરાવ્યું. અને સત્સંગમાં એવા બાંધી દીધા કે અમારું કશું જોર રહ્યું નહિ.”","e":null,"s":["9/51/29-37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2079,"k":"para","g":"આરતી પછી શ્રીહરિ ‘સ્વામિનારાયણ’ મંત્રની ધૂન કરતા. તે તાળી વગાડી ગગન ગાજે તેમ ધૂન કરતા એકતાન થઈ જતા, અને શરીર તથા શિર પરના વસ્ત્રનું પણ ભાન ન રહેતું. એમ ધૂનમાં લીન થતા.","e":null,"s":["11/8/23-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2080,"k":"para","g":"બોટાદમાં પોઢ્યા પછી શ્રીહરિ પુરની બહાર નદીમાં નહાયા, ત્યાં લીલી વનરાજી જોઈને કહે, “આવી જગ્યાઓ અમને બહુ ગમે છે, પરંતુ હરિભક્તના હિતને માટે પુરમાં રહીએ છીએ. કારણ કે વનથી પણ દુર્લભ સત્સંગ માન્યો છે. ભગવાનના ધામ કરતાં પણ અમે સત્સંગને દુર્લભ માનીએ છીએ અને તેથી કરીને પુર દેખીને મૂંઝાવા છતાં સત્સંગની બહાર જઈ શકતા નથી. જેમ શેરડીમાં રસ છે, તલમાં તેલ છે, દૂધમાં ઘી છે, દેહમાં જીવ છે તેમ અમે અમારા દેહને સત્સંગમાં એકરસ કરી દીધો છે.”","e":null,"s":["11/80(70)/6-11"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2081,"k":"para","g":"માંગરોળમાં શ્રીહરિએ અરુણોદય થતાં વાત કરતાં કહ્યું, “જે પુર અને ગામમાં સંત-હરિજન ધૂન કરે છે અને કીર્તન ગાય છે તેને ત્યાં અમે જઈને પ્રેમથી સાંભળીએ છીએ, એવી અમારી સદાય રીત છે. મનુષ્ય દેહનો લાભ જ એટલો છે કે પોતપોતાના ધર્મમાં રહીને ભજન કરવું.”","e":null,"s":["12/15/26-29"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2082,"k":"para","g":"અલર્ક નૃપના ભુવનમાં શ્રીહરિએ વાત કરતાં કહ્યું, “હરિભક્તો ને સંતનું અમે રાતદિવસ હિત વિચારીએ છીએ, પણ કોઈ હિત સમજતું નથી. અનુભવ વિનાના બુદ્ધિશાળીની બુદ્ધિ ફરી ગયા વિના રહે નહિ. બુદ્ધિ ફરે ત્યારે હિતમાં અહિત દેખાય. દેશકાળના વિષમપણાથી કોઈકનું માથું ફરે ત્યારે બહુ માણસ કહે તોપણ મનાય નહિ, પણ ડાહ્યો માણસ વિચાર કરે કે દસ વીશનાં માથાં ફરે નહિ માટે આપણો જ દોષ છે.”","e":null,"s":["15/13/13-19"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2083,"k":"para","g":"શ્રીહરિએ ગઢપુરમાં સંતો-ભક્તોને વિવિધ ભાતનાં ભોજન કરાવીને વાત કરતાં કહ્યું, “જેને અક્ષરધામના ધામી પ્રગટ મળ્યા તેને વેદ, પુરાણ અને સઘળાં સાધન તેમાં આવી ગયાં. પછી જે સાધન કરવાનું છે તે કહીએ જે –","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2084,"k":"para","g":"“પ્રથમ અમારો મત યથાર્થ સમજવો તે મોટું સાધન છે. સાધનમાત્રમાં એ પરમ સાર છે. તે સમજ્યા વિના બધાં સાધન નિર્જીવ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2085,"k":"para","g":"“તારાથી ચંદ્રમા અધિક છે, ચંદ્રથી સૂર્ય અધિક છે, એમ ચૈતન્ય ચૈતન્યમાં ઘણો ભેદ છે. પશુથી મનુષ્ય શ્રેષ્ઠ છે. મનુષ્યથી દેવ, દેવ કરતા ઈશ્વર અધિક છે. અને ઈશ્વરથી પરમેશ્વર અતિ અધિક છે. એ જ રીતે સંત અને અસંતમાં ગંગોદક અને મદિરા જેટલો ભેદ છે. જેને જે વખતે જે ભગવાન પ્રગટ મળ્યા તેણે તે વખતે તેનું ભજન કર્યું છે. અને તે જ હરિજન કહેવાયા છે. તેને તુલ્ય બીજા જન આવે નહીં. ચાહે તેટલાં સાધન કરે તોય તે માયિકજન કહેવાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2086,"k":"para","g":"“ભગવાન અને ભગવાનના મળેલા સંત કે તે સંતના મળેલાનો આશ્રય કરે ત્યારે શ્રીહરિનો નિશ્ચય થાય છે, અને અપાર જન ભવસિંધુ તરે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2087,"k":"para","g":"“મારાં લીલાચરિત્ર કહે તથા સાંભળે તેમાં આનંદ પામનાર મારા આશ્રિતોને અંતકાળે રથ વિમાનમાં બેસાડીને ધામમાં લઈ જાઉં છું. દાસનો દાસ થઈને જે નિત્ય સત્સંગ કરે છે તેની ભક્તિ હું પ્રમાણિત કરું છું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2088,"k":"para","g":"“મારી મૂર્તિ મારું ધામ અને મારું ભજન કરતાં મારા સંતો-હરિજનો સર્વે ગુણાતીત છે. તેને જે અસત્ કહે છે અને અસત્ જાણે છે અને તેનો દ્રોહ કરે છે તેને જમ કિંકર જોરે કરીને પકડીને લઈ જાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2089,"k":"para","g":"“આ બ્રહ્માંડમાં હું અખંડ નિવાસ કરીને રહું છું. જોગી નૃપ કે વિપ્રનું રૂપ ધરીને વિચરતો રહું છું. આ પ્રકારની મારી રીત છે. તે તમને મારા જાણીને પ્રેમથી કહી છે. આ રીત જાણીને જે મને ભજે છે તે મારા સુખને નિશ્ચય પામે છે.”","e":null,"s":["15/57/1-23"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2090,"k":"para","g":"પીપળાવમાં શ્રીહરિ કહે, “ભગવાનના સંત અને ભક્ત માટે પ્રેમથી જે સેવા સહાય કરે છે, તેટલી ભગવાન તેની સહાય કરે છે. અમારા મનમાં ભગવાન અને ભક્તના જ સંકલ્પ થાય છે. બીજા સંકલ્પને અમે સંસૃતિ (જન્મ-મરણ) માનીએ છીએ. ભગવાનનાં કથા-કીર્તનાદિક અને ઉત્સવ-સમૈયામાં મંદિરમાં હરિભક્તો સાથે ભેગા થવામાં જે કાંઈ કાળ જાય છે તે લેખે લાગે છે. બીજો કાળ વ્યર્થ જાય છે. સત્સંગ વિના મોહ અને મદ ઊતરતો નથી. તે સત્સંગ કરાવવા માટે જ અમે ઉત્સવ-સમૈયા કરીએ છીએ અને સંતોને પીરસીએ છીએ. હરિભક્તોને રાજી રાખવા અમે જુદું જુદું પીરસીએ, પણ સંતોએ સંતની રીતે જમવું. પોતપોતાનાં તુંબડાં જળથી ભરીને બેસવું. લોકમાં અનાચાર થાય છે તેમ ન કરવું.”","e":null,"s":["16/55/18-35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2091,"k":"para","g":"મહેમદાવાદમાં શ્રીહરિ કહે, “હરિજન થઈને હરિજનને, વ્યાવહારિક વાત માટે પણ કુવેણ કહે તે પૂરો ભક્ત કહેવાય નહિ. હરિભક્ત હોય તે બધાયનું હિત ઇચ્છે. હરિભક્ત થઈને મનમાં બીજાનું ખરાબ ઇચ્છે તેને જીવમાં કુસંગ જાણવો. કોઈ સ્વાર્થને લીધે હરિજન થઈને હરિજન સાથે વેર રાખે તે પૂરો હરિભક્ત નથી. અમારે સૌ પર હેત છે તેથી હિતની વાત કહીએ છીએ. અમે ધર્મનો પક્ષ રાખીએ છીએ. વચનમાં વર્તનારા પર અમારી નિરંતર કૃપા રહ્યા કરે છે.” એટલી વાત કરીને શ્રીહરિ અંબારામના ભવનમાં થાળ જમવા પધાર્યા.”","e":null,"s":["17/85/27-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2092,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ વાત કરતાં કહ્યું, “ઈર્ષ્યા સમાન કોઈ બીજો દોષ નથી. વિમુખ થાય પણ મરે ત્યાં સુધી ઈર્ષ્યા જાય નહિ. મોટા દૈત્યોએ મરવા છતાં ઈર્ષ્યા મૂકી નથી. સંત થઈને ઈર્ષ્યા રાખે તે દૈત્ય સમાન છે. જેનામાં ઈર્ષ્યાનો સ્વભાવ છે તે અમોને ગમતા નથી. તેને અમે સંત કહેતા નથી.”","e":null,"s":["18/14/5-7"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2093,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ ઉન્મત્તગંગા તટે વાત કરતાં કહ્યું, “અમારી ઉપર રતીભર જે ભાવ રાખે છે તેને અમે મેરુ સમાન માનીએ છીએ, તેવો અમારો સહજ સ્વભાવ છે. અમારું જે ચિંતવન કરે છે તેને અમે કદી ભૂલતા નથી. અમારાં ચરિત્રોનું ગાન હરિજનોએ કરવું. અમારા સિવાય કોઈનામાં જેને પ્રીતિ નથી તેને અમે પૂરો હરિજન કહીએ છીએ. અમારે એવા હરિજનો પર તાન રહે છે. અમારા સિવાય અન્યમાં પ્રીતિ રહે તેટલી તેમાં કસર જાણવી. અને એવો કસરવાળો અમારાથી દૂર છે. સમીપ અને દૂરની રીત કહ્યા વિના જાણ્યામાં આવતી નથી.”","e":null,"s":["28/44/6-10"],"sv":["हम पर भाव रखत रतिभर हि । मेरू सम तेहि मानत कर हि ॥\n\n एसे हमरे रहेउ स्वभावा । सहज स्वाभाविक जोउ रहावा ॥\n\n हमारे चिंतवन करत जिनकुं । हम नहि भुलत रहे इनकुं ॥\n\n हम चरित्र करत हें जितनां । अवतार जेते धरिके तितनां ॥\n\n हरिजनकुं करने हित गानां । हरिजन सम कोउ न रहानां ॥\n\n हरिजन पर हमारेउ तानां । रात दिन रहत जो कहानां ॥\n\n हम बिन रहे न प्रीति जाही । हरिजन पुरे कहत हि ताही ॥\n\n हम बिन जितनां रहे तामें । जितनां प्रीति वरतत यामें ॥\n\n तितनां तामे कसर रहेउ । तितनां हमसें दूर रहे तेउ ॥\n\n समिप दूर कि कहायेउ रीता । कहे बिन नहि जानत कीता ॥"],"mt":false,"gl":null,"a":false},{"i":2094,"k":"para","g":"સં. ૧૮૭૮ની જળઝીલણી શ્રીહરિએ ગઢપુરમાં કરી. લાલજી, ગણપતિની સવારી કાઢી. સૌ ઉન્મત્તગંગા તટે આવ્યા. શ્રીહરિ ભાવસારના આરે તટ પર આવીને બેઠા, શ્વેત વસ્ત્ર ધારણ કર્યાં હતાં. એટલામાં એક સંતે આવીને ફૂલના દસબાર હાર તથા ગુચ્છ તોરા વગેરે શ્રીહરિને ધરાવ્યા. પછી શ્રીહરિએ સંતોને પૂછ્યું, “લાલજીને ધરાવીને અમને ધરાવ્યા છે?” સંત આ વાત જાણતા ન હતા. તે જાણી લાવવા શ્રીહરિએ કહ્યું, ત્યારે સંતો બોલ્યા કે લાલજીને ધરાવ્યા નથી. ત્યારે શ્રીહરિએ હાર તોડીને ભૂમિ ઉપર નાખી દીધા ને કહ્યું કે, “પૃથુ ભગવાન થયા હતા. તે મૂર્તિની સેવા કરતા ત્યારે મૂર્તિનું સન્માન અધિક રાખતા હતા. સત્ય વાત માનવામાં અમે શરમાતા નથી. સત્પુરુષના જોગ વિના મોક્ષની રુચિ થતી નથી. સત્પુરુષ પોતે મોક્ષને માર્ગે ચાલીને અજ્ઞાની જનોને સાચી વાત બતાવી મોક્ષને માર્ગે ચલાવે છે. અને ભગવાનની જે આઠ પ્રકારની મૂર્તિ કહી છે, તેમાંથી હરકોઈ પ્રકારની મૂર્તિ પોતાના શિષ્યોને પૂજવા આપે તે મૂર્તિમાં પ્રગટ હરિની બુદ્ધિ રાખીને સેવા કરવી જોઈએ. જેથી નિશ્ચય મોક્ષ થાય છે. અમે પ્રગટ થયા ત્યારથી અધિક અધિક સુખ આપતા રહ્યા છીએ અને મોક્ષની પ્રથા ક્યારેય ન તૂટે તેવી બાંધી છે, પણ પુણ્ય વિના સમજાય નહિ. રખેવાળ વિના ખેતરમાં ગધેડાં ચરી ખાય. જેને કોઈ વાતનો નિયમ ન હોય તેમાં પણ મોક્ષ માને તેને ગધેડા કહેવાય. ધર્મરહિત થઈને ભગવાનની મૂર્તિ પૂજે તેને તો બ્રહ્માંડ હણ્યાનું પાપ લાગે છે. છતાં લોકો ત્યાં પ્રેમે કરીને દોડે છે. કાદવમાં કાદવવાળાં વસ્ત્ર ધોવાથી ઊજળાં થાય તો તેમનું કલ્યાણ થાય!”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2095,"k":"para","g":"એમ વાત કરી લાલજીને વહાણમાં બેસાડી આરતી કરી. ગણપતિને ગંગામાં પધરાવ્યા પછી લાલજીને જળવિહાર કરાવી બહાર આવ્યા. શ્રીહરિ તથા સંત-હરિભક્તો નાહ્યા. પછી પુરમાં ચાલ્યા. દરબારમાં તેમજ આહીરોને ત્યાં લાલજીની પધરામણીની પૂજા થઈ. પુરના ભક્તોએ ઘેર ઘેર પધરાવી પૂજ્યા.","e":null,"s":["22/tarang: 37-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2096,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2097,"k":"para","g":"ઝાલાવાડ અને હળવદ મચ્છુકાંઠા સુધીના હરિભક્તો દર્શન કરવા સારુ આવ્યા. પોતપોતાનું ભાથું સાથે લાવ્યા હતા. આ રીત જોઈ શ્રીહરિ પ્રસન્ન થયા. શ્રીહરિ એકએક ભક્તને મળી નામઠામ પૂછતા હતા. ઉતારો કરાવતા હતા. કોઈ મા-બાપની ભીતિથી ભાથું લીધા વિના આવ્યો હોય તેની બરદાશ શ્રીહરિ કરતા. કોને શું કહેવાનું છે તે ભૂલે નહિ, બધું સ્મરણમાં રાખે, એવો શ્રીહરિને અભ્યાસ હતો. પાછા ઘરે જાય ત્યાં સુધી દરેક હરિભક્તની જાતે ખબર રાખે, બીજા પાસે રખાવે, શ્રીહરિની સૂરત એવી કે અપાર ભીડમાં પણ ભક્તને કહેવાનું ચૂકતા નહિ. જેમ વધુ ભીડ તેમ વધુ સૂરત રાખતા. અનંત પ્રકારની વાર્તા કરીને તેનો મોક્ષ કરવાનું એક તાન શ્રીહરિને રહેતું. કોઈને હેતે બોલાવે, કોઈનાં વખાણ કરે, કોઈ ન આપે તો માગીને લે ને કોઈ આપે તો પણ ન લે. આમ, કોઈ પણ પ્રકારે હેત કરી મોક્ષ કરવાનું તાન એમને રહેતું. શ્રીહરિનું ચરિત્ર એક પણ એવું નહોતું જેમાં અવગુણ આવે. મનુષ્યચરિત્રમાં પણ અવગુણ ન જુએ તે એકાંતિક, હરિનો દાસ કહેવાય.","e":null,"s":["4/77/7-17"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2098,"k":"para","g":"મુક્તમુનિએ શ્રીહરિની અનાસક્તિની વાત કરતાં કહ્યું, “શ્રીહરિ પાસે ગામ-ગામના હરિજનો આવતા અને અપાર સેવા કરતા, પૂજા કરતા, વસ્ત્ર આભૂષણ કેટલાક પ્રકારના લાવતા, શ્રીહરિને પ્રેમથી પહેરાવતા, પરંતુ શ્રીહરિ તે સઘળું બીજાને આપી દેતા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2099,"k":"para","g":"શ્રીહરિ પાસે જેટલું ધન આવતું તે તરત બ્રાહ્મણોને વહેંચી દેતા. જો બ્રાહ્મણ કોઈ ન મળે, તો નૃપને આપી દેતા. ફરી જરૂર પડે તોપણ પાછું માગતા નહિ. પૃથ્વી ઉપર વિચર્યા ત્યાં સુધી શ્રીહરિએ પોતાની પાસે ધન રાખ્યું કે રખાવ્યું નથી. વસ્ત્રો, ઘરેણાં, વાહન, કંઈ પણ પોતાનું કરીને રાખ્યું નથી. પોતે અત્યંત નિર્બંધ રહ્યા, આકાશ જેવા શુદ્ધ રહ્યા. આવું વર્તન કોઈમાં જોવા મળે નહિ. શ્રીહરિ સૌ સાથે એકરસ થઈ જતા, છતાં સૌથી પૃથક્ રહેતા. બીજાની દેશી(નકલ) કરીને વર્તે, પણ શ્રીહરિની દેશી તો કોઈ કરી શકતું નહિ. મત પંથ સઘળા હારી ગયા.","e":null,"s":["5/71/5-10"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2100,"k":"para","g":"હરિભક્તો ધન આપે તે શ્રીહરિ પોતે હાથે લેતા નહિ. ચરણમાં મૂકે તો સેવક લઈ લેતા. આવેલી રકમ શ્રીહરિના ખર્ચમાં વપરાતી. શ્રીહરિ આવક પ્રમાણે ખર્ચ કરતા, ધનસંચય કરતા નહિ. વધુ આવક હોય તો બ્રહ્મભોજન કરાવતા. વિપ્રને જનોઈ કે કન્યાદાન દેતા. વારે વારે યજ્ઞ કરાવતા. મોટાં મોટાં મંદિરો કરાવતા. તેમાં પણ કોઈની પાસે માંગતા નહિ ને રકમ ભેગી કરાવી રાખતા નહિ. મંદિરોમાં ક્યારેય અન્ન-વસ્ત્રની તાણ રહેતી નહિ.","e":null,"s":["6/65/14-20"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2101,"k":"para","g":"શ્રીહરિ નિજ ભક્તોને નિતનિવી પ્રીત કરતા, જમાડતા, લાડ લડાવતા, સાથે ફરતા રાજાઓ - ગામધણીઓને મન ગામગરાસ ખોટાં થઈ ગયાં હતાં. કોઈને ઘરે પાછા જવાનો ભાવ થતો નહિ. શ્રીહરિ પાસે માસ-બે માસ રહે તોય એ ઉદાસ થતા નહિ. જેને જે પ્રમાણે વસ્ત્ર જોઈએ તેને તેટલું વસ્ત્ર શ્રીહરિ આપતા રહેતા. શ્રીહરિ એટલું જમાડતા કે એ બધી વાત કહીએ તેટલી ઓછી પડે. કરોડ વાતની એક વાત એ કે શ્રીહરિની બધી વાત માપની બહાર રહેતી.","e":null,"s":["8/11/8-12"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2102,"k":"para","g":"સંતો-ભક્તોની પંક્તિમાં શ્રીહરિ સ્વયં પીરસતા. બીજા કોઈ પીરસે તેથી શ્રીહરિનું મન માનતું નહિ, કારણ કે જન જનની જે ભિન્ન રુચિ તેને શ્રીહરિ જાણતા. કેટલાક પીરસનારા ‘લો લો’નો બકોર કરે, પણ લગારે આપે નહિ, માગે તો સાંભળે નહિ, વારે વારે ક્રોધ કરે, આપે તો ખૂબ આપી દે, ન આપે તો કશું આપે નહિ, ધીરે ધીરે પંક્તિમાં ફરે, પીરસવામાં પંક્તિભેદ કરે, મમત્વથી રહિત થઈને પીરસે નહિ, એવો સ્વભાવ જેનો દેખ્યામાં આવે તેના હાથમાંથી શ્રીહરિ ખેંચી લેતા. ફરી તેને પીરસવા દેતા નહિ. પીરસવામાં જેની નિર્દોષ મતિ હોય, ભેદબુદ્ધિ હોય નહિ, ઓછું અધિક જોઈએ તેટલું આપે, પાછળથી માગે તો ફજેત કરે નહિ, તેવાની પાસે ક્યારેક પિરસાવે તોપણ પોતે ફરે તેટલો સંતોષ રહેતો નહિ. કોઈ રસોઈ આપે તેને ફરવા દેતા, જેથી તેના મનમાં હર્ષ રહે અને વારે વારે સંભારે અને ધ્યાનમાં આવે.","e":null,"s":["11/21/17-24"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2103,"k":"para","g":"કારિયાણીમાં યજ્ઞ કર્યો. શ્રીહરિએ પૂર્ણાહુતિ વખતે બ્રાહ્મણોને ભાવથી દક્ષિણા આપી. ઘી વધ્યું તે બ્રાહ્મણોને પિવડાવી દીધું. પોતે ઘીનું પાત્ર હાથમાં લઈને પાતા. જેટલા શેર ઘી વિપ્ર પીએ તેટલા રૂપિયા તે બ્રાહ્મણને આપતા. એમ સૌને પ્રસન્ન કર્યા ને વિદાય આપી. ઘી, ગોળ અને લોટ વધેલો તેનાથી શ્રીહરિએ સંત-હરિભક્તો અને પુરના લોકોને જમાડ્યા. શ્રીહરિ કહે - અમે જ્યારે જ્યારે જમાડીએ છીએ ત્યારે સામાન બહુ વધે છે. રામાનંદ સ્વામી અમારી સહાય કરે છે, નહિ તો એવું બને નહિ.","e":null,"s":["12/44/25-30"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2104,"k":"para","g":"લોયાથી શ્રીહરિ પંચાળા આવ્યા. લોયામાં અયોધ્યાવાસી મળ્યા ત્યારથી શ્રીહરિએ ઉદાસી ગ્રહણ કરી હતી અને અન્ન છોડ્યું હતું. શ્રીહરિની સ્વાભાવિક પ્રકૃતિ વિષે મુક્તાનંદ સ્વામીને રામાનંદ સ્વામીએ વાત કરેલી તે તેમણે સ્મરણમાં રાખી હતી. અન્ય વરિષ્ઠ પરમહંસોને તેમણે આ વાત કહી. મુક્તમુનિ કહે, “રામાનંદ સ્વામીએ શ્રીહરિના વિરક્ત સ્વભાવ વિષે મને એકાંતમાં કહ્યું હતું કે શ્રીહરિના સંબંધી ભેગા નહિ થાય ત્યાં સુધી તે સંત-હરિભક્તોને અપાર સુખ આપશે. જ્યારે સંબંધીનો જોગ કદી પણ થયો ત્યારે જાણજો કે શ્રીહરિ ઉદાસ થઈ જશે, કારણ કે પોતે ત્યાગી વર્તે છે. ઉપરથી સંત-હરિભક્તને બોલાવશે પણ અંતરમાં દેહ ક્યારે ત્યાગ કરવો તેના વિચારમાં રહેશે. બીજી ઉદાસી તો તમે કોઈ પણ રીતે દૂર કરાવી શકશો, પણ દેહના સંબંધથી થયેલી ઉદાસી પ્રાણ ત્યજાવીને રહેશે. કારણ શ્રીહરિ તેને જ સંબંધી માને છે જેનામાં ભક્તપણું હોય અને ધર્મ રાખવામાં પ્રીતિ હોય. એવા દૃઢ વિશ્વાસવાળા ભગવાનના ભક્તને પોતાના સાચા સગા માને છે, એનો ત્યાગ તેઓ ક્યારેય કરતા નથી. ભગવાનના ભક્તપણામાં ને ધર્મપાલનમાં જેને કસર હોય તેને શ્રીહરિ રતિ-રતિ જાણે છે. વર્તન જોઈ શ્રીહરિ સુખ આપે છે.”","e":null,"s":["25/48/1-13"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":30,"gu":"પ્રકીર્ણ","en":"Prakīrna — Miscellaneous","url":"https://www.anirdesh.com/pbp/index.php?page=chp_30","b":[{"i":null,"k":"heading","g":"પ્રવૃત્તિ-નિવૃત્તિ, પુરુષ પ્રયત્ન","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2105,"k":"para","g":"સરધારમાં શ્રીહરિએ વાત કરતાં કહ્યું, “હરિમાં તાન વધે એટલા માટે જે પ્રવૃત્તિ કરે છે તે નિવૃત્તિ જ ગણાય, એમ એકાંતિક ભક્તો જાણે છે.”","e":null,"s":["3/56/21-22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2106,"k":"para","g":"શ્રીહરિએ ગોંડળમાં વાત કરતાં કહ્યું કે, “અભયપદ મેળવવાનો પ્રયત્ન કરે તો તે પણ મળે છે. ઉપાય કર્યા વિના કાંઈ મળતું નથી. આ જીવ બીજા સુખને માટે ઉપાય કરે છે, પણ મોક્ષને માટે કરતો નથી.”","e":null,"s":["6/47/9-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2107,"k":"para","g":"શ્રીહરિ સંતોને કહે, “મોક્ષના માર્ગમાં કામ ન આવે તે બધું નિરર્થક છે. કેવળ નામમાત્ર છે.” ‘નામમાત્ર તેહિ સબ કાવે, મોક્ષ કે મગ મેં કામ ન આવે.’","e":null,"s":["6/89/12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2108,"k":"para","g":"સમઢિયાળામાં લાખાખાચરને ઘરે શ્રીહરિ દૂધ, ભાત, સાકર, જમીને દહીં, ભાત, સાકર જમ્યા અને બોલ્યા, “જેવો અભ્યાસ રાખે તેવી વાત સિદ્ધ થાય. જગતની વાત અતિ તુચ્છ છે, તોપણ અભ્યાસ કર્યા વિના આવડતી નથી તેમ સત્સંગનો અભ્યાસ કરે તો તે દૃઢ થાય, અને જન્મ-મરણનો વ્યાધિ મટે, તે વ્યાધિ મટાડવા માટે જ ભગવાને મનુષ્ય તન આપ્યું છે, પણ પંડિત-પુરાણી થવા છતાં જીવને ગમ રહેતી નથી.”","e":null,"s":["9/48(49)/19-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2109,"k":"para","g":"મૂલેન્દ્ર નૃપને શ્રીહરિએ વાત કરતાં કહ્યું, “અભ્યાસ કર્યા વિના કોઈ વાત તત્કાળ દેખ્યામાં આવે નહિ. સૌને વગર અભ્યાસે જોવાની ઇચ્છા છે, પણ તે વગર અભ્યાસે કેમ દેખી શકાય? જેવી રુચિ હોય તેવું ચિત્ત ચોંટે અને તે પ્રમાણે અભ્યાસ કરવામાં તત્પર થાય. રુચિ હોય તો કઠણ અભ્યાસ પણ સૌ કરે છે અને મરણ સુધીનું કાર્ય પણ તેને કઠણ લાગતું નથી.”","e":null,"s":["10/6/22-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2110,"k":"para","g":"ગઢપુરમાં જીવેન્દ્ર નૃપના દરબારમાં શ્રીહરિએ કહેલી વાત મુક્તમુનિએ કહી, “દરેક વાત સિદ્ધ કરવામાં પ્રથમ શ્રમ કરવો પડે છે. પછી ફળ આવે છે ત્યારે અપાર સુખ થાય છે. વધારે અન્ન મેળવવા માટે પ્રથમ ઘરનું અન્ન પૃથ્વીમાં નાંખવું પડે છે, અને ઉપરથી શ્રમ થાય છે. તેવી રીતે મોક્ષના ફળમાં સમજવું.”","e":null,"s":["13/63/36-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2111,"k":"para","g":"ભાદરામાં વશરામ સુથારને ઘરે શ્રીહરિએ વાત કરતાં કહ્યું, “સમય વિનાની કથા કે કીર્તન સારાં હોય તો પણ મનને શાંતિ કરે નહિ. તાવનું જોર હોય ત્યારે અન્નની રુચિ નાશ પામે. તે વખતે શીરો લાવે તોપણ શત્રુ સમાન લાગે. તાવ ગયા પછી અન્નની વધારે રુચિ થાય ત્યારે ભાવથી માગે તોપણ દેતા નથી. ચાતુર્માસમાં વરસાદ જેટલો જોઈએ તેટલો વરસે તો સારો લાગે પણ જરૂર ન હોય અને આવે તો સારો લાગે નહીં.”","e":null,"s":["11/9/10-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2112,"k":"para","g":"શ્રીહરિએ જીવેન્દ્ર નૃપના ભવનમાં સભામાં વાત કરતાં કહ્યું, “કરોડપતિ હોય પણ જેનો જીવ કૃપણ(લોભી, કંજુસ) હોય તે ધન ખરચી ન શકે. ઘરમાં દીવો કરવો હોય તેમાં પણ કસર કર્યા કરે, મા-બાપની સાથે મહોબત રાખે નહિ, પુત્ર, ભાઈ, ભત્રીજા તથા તેઓની પત્નીઓનાં વસ્ત્ર, આભૂષણ અને ખાનપાનમાં સંકોચ રાખ્યા કરે. કૃપણનો વ્યવહાર કોઈ સંકોચ વિના હોય નહિ. એમ કરતાં જો ખર્ચ આવે તો ખાવું-પીવું ઝેર જેવું લાગે ને નિદ્રા આવે નહિ. માથું કાપ્યા જેવું લાગે. એવા કૃપણનું ધન સંત કે બ્રાહ્મણના મુખે જાય નહિ, નાશ પામે કે પાપને માર્ગે જ વપરાઈ જાય. કૃપણતા ટળી નહિ તો અંતે મરીને સાપ થાય. કંજૂસનું ધન મર્યા પછી પણ રંચમાત્ર કામ લાગે નહિ. મોક્ષના માર્ગમાં વાપરે તેટલું જ ધન સાથે લીધું કહેવાય.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2113,"k":"para","g":"“અમારી પૂજા થાય છે ત્યારે અનંત વસ્ત્રાભૂષણ આવે છે તે મયારામ ભટ્ટ રાખે છે, કારણ કે તેમની પ્રકૃતિ એવી છે કે કોઈ પણ ચીજમાં લલચાય નહિ. ફાવે તેવી રૂપવતી સ્ત્રી હોય તોપણ કાળી નાગણી જેવી સમજે છે. વીસ વર્ષ તેમને થયાં ત્યારે તેમની સ્ત્રી મરણ પામી, છતાં અતિ આનંદ પામ્યા કે હવે આપણે નિર્બંધ થયા. કામ અને લોભ બેઉ નરકનાં દ્વાર કહ્યાં છે. જ્યાં સુધી તેમાં મન રહે છે, ત્યાં સુધી તેને અનાસક્ત પુરુષ નરકમાં પડેલાં દેખે છે. નારી અને ધનને લીધે વારંવાર જન્મમરણ થાય છે. લખચોરાશીનું દુઃખ પણ ધન અને નારીમાં રહેલું છે. જે કંઈ દુઃખમાત્ર છે, તે ધન અને નારીમાં રહ્યાં છે. ધન-નારીનો જે ત્યાગ કરે છે તેને બ્રહ્માદિ દેવતાઓ વંદન કરે છે.”","e":null,"s":["13/66/19-37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"ખપ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2114,"k":"para","g":"ઝીંઝાવદરમાં શ્રીહરિએ અલર્ક રાજાને વાત કરતાં કહ્યું, “મોક્ષનો ખપ હોય એવાં સ્ત્રી-પુરુષો તો લોભને ગણતાં જ નથી. અને તન-ધનને ધૂળ જેવાં જાણે છે. જેને સત્યનો જ ખપ હોય છે તે સત્ય રાખવા માટે અગ્નિમાં પડીને દેહત્યાગ કરે છે. તેમ જેને ખપ હોય તેનાથી શું ન થાય! ખપમાં જેટલી ખોટ તેટલો દોષ ભાસે છે. ખપ વિના કોટિ ઉપાયે મોક્ષ થાય નહિ.”","e":null,"s":["9/41(40)/24-27"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2115,"k":"para","g":"ભાદરામાં શ્રીહરિએ વાત કરતાં કહ્યું, “વેશ્યાનો ધંધો તે અતિ નીચ પાપ છે. ધનમાં માલ માન્યો છે તેથી તે પાપનો અભાવ થતો નથી. તેવો માલ જો ભગવાનમાં મનાય તો કોઈનો છોડાવ્યો કેમ છૂટે? પણ ભગવાનનો ખપ ધનના જેટલો નથી, એવું જીવને અજ્ઞાન છે. પ્રહ્‌લાદ અને બલિ જેવાને જ્યારે ભગવાનનો ખપ સમજાયો, ત્યારે ત્રિલોકીના ભૂપ હોવા છતાં ત્રિલોકીના સુખને ચિંતામણિ આગળ કાચ ગણાય તેવું જાણ્યું. ભગવાનનું જ્ઞાન ન હોય ત્યાં સુધી દેવો અને મનુષ્યો ચિંતામણિ છોડીને કાચમાં માલ સમજે છે. ભગવાન વિનાનું બીજું ફાવે તેવું જ્ઞાન હોય તો પણ અજ્ઞાન છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2116,"k":"para","g":"“વેદ પુરાણ જાણવાં, ધર્મ રાખવો, જપ, તપ, વ્રત, તીર્થ, દાન વગેરે કરવું તે બધાંયનું ફળ એટલું જ છે કે ભગવાનનું જ્ઞાન થાય. તે બધાં સાધન કરીને પણ જો ભોગ મેળવવાની આશા રાખે તો સંસારનો રોગ મટતો નથી, અને રેંટે જોડેલો બળદ જેમ સવારથી સાંજ સુધી ચાલે, પણ જ્યાં હોય ત્યાંનો ત્યાં જ રહે છે તેમ ભોગની આશા રાખીને ફાવે તેવાં સાધનો કરે, પણ અંતે સંસારમાં ને સંસારમાં રહે છે. આત્મનિષ્ઠા તો એટલું ફળ આપે છે કે સુખદુઃખમાં શાંતિ રહે અને દેહનાં દુઃખ જે નદી જેવાં છે તેને તરી જાય, પણ મૃત્યુ સમયનાં દુઃખ તો સમુદ્ર જેવાં છે, ત્યાં મોટાં વહાણ વિના તરી શકાય નહિ. ભગવાનનું શરણ એ જ મોટું વહાણ છે. તેનાથી જ મૃત્યુરૂપી સમુદ્ર તરાય છે. આત્મજ્ઞાન તો તુંબડા જેવું ગણાય.”","e":null,"s":["11/9/21-35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2117,"k":"para","g":"શ્રીહરિએ મુક્તમુનિને કહેલી વાત તેમણે કરતાં કહ્યું, “મહારાજ કહે - મોક્ષના ખપ વિનાના મનુષ્ય પશુ સમાન છે ને અપાર ક્લેશ સહે છે. ભગવાન વિનાનું જ્યાં સુધી તાન છે, ત્યાં સુધી હેરાન થાય છે, પણ અજ્ઞાનથી અંધ થયેલાઓને જાણવા છતાં ત્રાસ થતો નથી. ભગવાનના સાચા સંતો જીવમાત્રનું હિત કરવા તેમને ભગવાનનું જ્ઞાન અને તાન થાય એવી વાત કરે છે. બ્રહ્મા સમાન બુદ્ધિશાળી હોય, પણ હરિના સુખ જેવું સુખ બીજે મનાય અને હરિમાં તાન ન રહે તો તે પશુથી પણ તુચ્છ છે. પછી ભલે તેણે જ્ઞાન, વિદ્યા અને સન્માન મેળવ્યું હોય. આખા બ્રહ્માંડને સોનાનું બનાવતો હોય અને બ્રહ્માંડમાં બધાંને પકવાન જમાડતો હોય, પણ ભગવાનની ઉપાસના વિના જન્મમરણથી છૂટતો નથી.”","e":null,"s":["14/15/1-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2118,"k":"para","g":"વસ્તાણા ગામે શ્રીહરિએ પદાતીને વાત કરતાં કહ્યું, “ભજન, સ્મરણ, માળા, પૂજન, વંદન, દુઃખી સંતની સેવા કરવી, કીર્તન કંઠે કરવાં, પ્રાકૃતગ્રંથ વાંચવા, રસોઈ કરવી ઇત્યાદિ પ્રમાદીથી બને નહિ. પ્રમાદીનું કોઈ પણ કામ ક્લેશ વિનાનું હોય નહિ. પ્રમાદી અને આળસુ હોય તે નામમાત્રનો મનુષ્ય છે. સર્પ, સિંહ કે અગ્નિનો ભય આવે કે સરકારના સિપાઈ વેઠ માટે પકડે ત્યારે આળસ અને પ્રમાદ ભાગી જાય છે. જીવને જેના ઉપર ભાવ હોય તેમાં આળસ કે પ્રમાદ રહેતાં નથી. ભાંડ-ભવાઈમાં તથા વિવાહમાં આળસ-પ્રમાદ રહેતા નથી, કારણ કે તેમાં ભાવ છે.","e":null,"s":["14/43/20-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"વચન પાલન","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2119,"k":"para","g":"સરધારમાં શ્રીહરિએ મુક્તમુનિને ઉદ્દેશીને એકાંતમાં વાત કરતાં કહ્યું, “અમારું વચન જે માને છે તેને ક્યારેય લેશ પણ દુઃખ આવતું નથી. જેમ જરાસંધે અપાર રાજાઓનાં પુર કબ્જે કર્યાં હતાં, પરંતુ જે શ્રીકૃષ્ણના શરણમાં આવ્યા તે સૌની રક્ષા તેમણે કરી. તે રીતે જે મારો વિશ્વાસ રાખે છે, તેની હું રક્ષા કરું છું. તેનાં પાપમાત્ર ટાળી દઉં છું, એમાં સંદેહ રાખવો નહીં.”","e":null,"s":["3/60/15-18"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2120,"k":"para","g":"સત્યપુરમાં શ્રીહરિએ નારસંગજી નૃપને વાત કરતાં કહ્યું, “અમારો અવતાર કેવળ જનોના મોક્ષ માટે છે. મોક્ષમાં વિઘ્નરૂપ વિષયાસક્તિરૂપ રોગોના અમે વૈદ્ય છીએ. ચરી પળાવીએ અને દવા આપીએ. અમારાં વચનરૂપ ઔષધ ખાય તેનો વાસનારૂપ રોગ જાય, મોક્ષરૂપ ભગવાનનું ધામ પામે અને વિષયોને શત્રુરૂપ જાણે. દૂધપાક જેવું ભોજન નહીં પણ તેમાં સર્પની લાળ પડે ને ખાય તેના પ્રાણ જાય તેમ ચૌદલોક સુધી અધિક અધિક વિષય ભર્યા છે, પ્રકૃતિપુરુષના લોક સુધી વિષયનું રાજ રહ્યું છે. એ વિષયોને શત્રુ જાણી ત્યાગ કરે અને અમારો આશ્રય કરે તે માયા તજીને અમારા ધામને પામે.”","e":null,"s":["4/71/19-25"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2121,"k":"para","g":"શ્રીહરિએ ભુજના હરિભક્તો પર પત્ર પાઠવ્યો. તેમાં લખ્યું - મારા વચનનો આદર રાખે તે મારો આદર રાખ્યા બરાબર માનું છું. મારા વચનમાં મારો નિવાસ છે. તેમાં જેટલો આદર રાખો તેટલો હું તમારી પાસે છું. મનુષ્યતનુ ધાર્યું હોવાથી તે પ્રમાણે વર્તીએ છીએ. પ્રત્યક્ષ અને પરોક્ષ બેય ભાવ મનુષ્યતનમાં રહ્યા છે. તેમાં વચનરૂપી મારું શરીર ક્યારેય પરોક્ષ થતું નથી. મનુષ્યતન ચરિત્ર માટે છે.","e":null,"s":["14/75/31-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2122,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ વાત કરતાં કહ્યું, “ભગવાન અને સંતનાં વચન પદાર્થ કરતાં અધિક છે. વચનમાં વર્તવાથી તો અંતઃકરણ શુદ્ધ થાય છે. પદાર્થથી એ શુદ્ધ ન થાય.”","e":null,"s":["15/47/9"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2123,"k":"para","g":"શ્રીહરિએ બીજો એક પત્ર સંત-હરિભક્તોના હિત માટે હેતથી લખાવ્યો: “સ્વસ્તિશ્રી સત્સંગ મહાશુભ સ્થાને શુભોપમા લાયક પૂજ્યારાધ્યે સર્વ ઉમંગ શુભ ઉપમા લાયક પરમહંસ મુક્તાનંદ સ્વામી, રામદાસજી સ્વામી, શ્રીપાત દેવાનંદ સ્વામી આદિ સમસ્ત પરમહંસ તથા જયાનંદ, મુકુન્દાનંદ આદિ સમસ્ત બ્રહ્મચારી, કર્મયોગી વિપ્ર નાનાભાઈ વગેરે ગૃહસ્થ, તથા કર્મયોગી સમસ્ત બાઈઓ તથા જીવુબાઈ, રાજબાઈ વગેરે ત્યાગી સમસ્ત બાઈઓ પ્રત્યે, અનિર્દેશથી લિખાવિતંગ સ્વામીશ્રી સાત સહજાનંદજીના જય સચ્ચિદાનંદ વાંચશો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2124,"k":"para","g":"“પત્ર લખવાનું કારણ સર્વે એકાગ્ર મનથી સાંભળજો. શુદ્ધ અંતઃકરણ વિના વાત ગ્રહણ થતી નથી. જેમ સમુદ્ર વધારે ઊંડો છે તો ત્યાં વધારે પાણી માય છે, તેમ જેનું જેવું અંતઃકરણ હોય તે પ્રમાણે વાત તેમાં ટકે છે. અમારી વાતનું રહસ્ય તમને સમજાવવા માટે અમે આ મનુષ્યતન ધર્યું છે. અમે આ લોકમાં ક્યારેય આવ્યા નથી એટલે પરમ રસપૂર્વક અમારું રહસ્ય પ્રગટ કરીએ છીએ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2125,"k":"para","g":"“પૂર્વે રામ અને શ્રીકૃષ્ણ કાર્ય-કારણ અવતાર થયા. તેમણે સામર્થ્ય બતાવ્યું, પણ મંદમતિ અસુર ગુરુઓ અને તેમના શિષ્યો તેમની સામે પડ્યા છે. તે ભગવાનને મનુષ્ય કહે છે. અસુર ગુરુ પોતાના જેવી મતિ શિષ્યોને દે છે. અમૃત જેવા ભોજનમાં થોડું ઝેર પડે તોપણ તેને ઝેર કરી દે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2126,"k":"para","g":"“અસુર ગુરુને જીવોનો મોક્ષ કરવાનો પ્રતાપ લેશ હોતો નથી, પણ ઉપદેશની વાતો શીખી શીખીને ઉપદેશ દે છે. તે જીવને સત્સંગના માર્ગથી પાડે છે અને બ્રહ્માંડ ભાંગ્યાનું પાપ તેને શિર ચોંટે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2127,"k":"para","g":"“એવા ગુરુને નારી અને ધનનો ત્યાગ હોતો નથી. વળી, એક પણ નિયમધર્મ તે પાળતા નથી. લાગ આવ્યે વિષય લંપટ થઈ જાય છે. નારીનો સંગ અને ધનનો સંગ્રહ કરતા હોવાથી તેનું ચિત્ત અતિ મલિન રહે છે. એવા અસુરને અને ભગવાનને કોઈ સંબંધ નથી. એવા ગુરુ ષટ્ચક્રની મોટી વાતો કરે, પણ યોગકળા સાધ્યા વિના ષટ્ચક્ર દેખાડવાં તથા નેત્રની વૃત્તિથી સામાની વૃત્તિ સંકેલી લઈ તેમાં મૂર્તિનો પ્રવેશ કરાવવો વગેરે યોગકળાની વાત પાખંડીમાં હોઈ શકે નહિ. તેના માથેથી યમ ને કાળનો ભય મટતો નથી. સ્ત્રી-પુત્રમાં બંધાયેલો હોય તે, તેમાં બંધાયેલાને છોડાવે એવું આજ સુધી બન્યું નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2128,"k":"para","g":"“પત્ર લખવાનું બીજું કારણ કહીએ છીએ - ત્રણ દેહ (સ્થૂળ, સૂક્ષ્મ ને કારણ) તથા ત્રણ અવસ્થા (જાગ્રત, સ્વપ્ન ને સુષુપ્તિ) તેનાથી પર આત્મારૂપ પોતાને માનીને ભજન કરવાવાળાનો જીવ શુદ્ધ જાણવો. દેહ અને જીવનો ગુણ એક સમજે છે ત્યાં સુધી દુઃખનો પાર આવતો નથી. જીવને વળગેલો દેહભાવ છૂટે અને દિવ્યભાવ (બ્રહ્મભાવ) કેળવાય એવો વિચાર અમે રાત-દિવસ કરીએ છીએ. અક્ષરભાવ પામ્યા વિના અક્ષરધામમાં ગતિ ક્યારેય થતી નથી. ભગવાનને જેમ દિવ્ય માનતા જશો, તેમ મતિ દિવ્ય થતી જશે.”","e":null,"s":["15/92/1-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2129,"k":"para","g":"શ્રીહરિએ પત્રમાં ધારણાની વાત કરતાં લખ્યું કે: “લક્ષ્યની વાત અનેક પ્રકારે કહેવામાં ને દેખવામાં આવે છે. લક્ષ્ય પણ અનેક પ્રકારનાં છે. ચિદાકાશ જે ભગવાનનું અક્ષરબ્રહ્મધામ છે તે આકારે જીવની વૃત્તિ થાય ત્યારે તે જીવમાંથી મુક્ત દશા પ્રાપ્ત કરે છે. જે અક્ષરધામમાં અનંતકોટિ મુક્તો રહ્યા છે એ ચિદ્‌ભૂમિમાં તેનો વાસ થાય છે.”","e":null,"s":["15/95/8-11"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2130,"k":"para","g":"શ્રીહરિ પત્રમાં કહે, “સત્સંગ જેને નથી તે આ નરક જેવા શરીરમાં ચોટી રહે છે. ભગવાન અને ભગવાનના ભક્ત જે સુખના સિંધુ છે તેને મલિન વસ્તુને અધિક કરી માને છે. ભગવાનનો ભક્ત તો ભગવાન અને સંતની સેવામાં જે ન આવે તે ચિંતામણિ ને કલ્પવૃક્ષ હોય તોપણ તેને મહા કુસંગ સમ લેખે છે.”","e":null,"s":["15/96/1-17"],"sv":["भगवान संत हित हि जेता । ताकी सेवा में न आवत तेता ॥\n\n चिंतामनि कल्पतरु सम होवे । भक्त ताकुं कुसंग सब जोवे ॥"],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"વૈરાગ્ય","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2131,"k":"para","g":"શ્રીહરિએ માતાને ઉપદેશ આપતાં કહ્યું, “વૈરાગ્યવાળા સંતના પ્રસંગથી વૈરાગ્ય ઊપજે છે તથા તેમને મુખે સાંભળેલી પાતાળથી પ્રકૃતિપુરુષ પર્યંત સમગ્ર લોકોની અનિત્યતા, જે ચાર પ્રકારના પ્રલયે કરીને સમજ્યામાં આવે છે, તેનાથી પણ વૈરાગ્ય થાય છે. તથા એ પ્રલયોમાં નાશ પામતા નાના પ્રકારના જીવોને જન્મતાં, મરતાં તથા જીવતાં જે અનંત પ્રકારનાં દુઃખ પડે છે તેને સમજવાથી પણ વૈરાગ્ય થાય છે. વિષયોના ભોગમાંથી દુઃખ ઉત્પન્ન થાય છે. તથા અનીતિના ફળરૂપ યમપુરીનાં દુઃખ ભોગવવાં પડે છે. તેને જાણીને પણ વૈરાગ્ય થાય છે.”","e":null,"s":["1/61/14-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2132,"k":"para","g":"શ્રીહરિએ માતાને કહ્યું, “જેમ ભોજન, પાત્ર તથા આભૂષણ અગ્નિ વિના તૈયાર થાય નહિ અને સુધરે નહિ તેમ વૈરાગ્ય પક્વ થયા વિના મોક્ષનો માર્ગ સુધરે નહિ. વૈરાગ્યથી પાપરૂપી મળ બળી જાય છે. અગ્નિ પ્રગટ થાય નહિ ત્યાં સુધી કાગળમાં લખેલા અગ્નિથી કામ થાય નહિ. તેમ વૈરાગ્ય પ્રગટ્યા વિના કેવળ વૈરાગ્યની વાતથી પાપનો નાશ થાય નહિ. વૈરાગ્ય વિના મોક્ષની લાલચ રાખવી તે વ્યર્થ છે. વૈરાગ્યમાં દૈવત છે તેવું કશામાં નથી. નિધિનો પણ નિધિ વૈરાગ્ય છે. વૈરાગ્યરૂપ નિધિ મળે તો અનંતકોટિ બ્રહ્માંડનાં સુખ લૂખાં લાગે.”","e":null,"s":["1/63/1-9"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2133,"k":"para","g":"શ્રીહરિએ જેતપુરમાં મૂળુવાળાને વાત કરતાં કહ્યું, “કરોડો જનમાં કોઈક જ મોક્ષભાગી હોય. મોટાપુરુષોએ ગ્રંથ રચ્યા છે તેમાં ધર્મ, અર્થ, કામ લખીને તેમાં દોષ દેખાડીને મોક્ષનું ફળ સત્ય બતાવ્યું છે. સંસારમાં કુટાતા અત્યંત દુઃખી થઈ વૈરાગ્ય પામેલા મુમુક્ષુને મોક્ષનો માર્ગ પોતાની રીતે હાથ લાગતો નથી, પરંતુ આવા જનને જો સાચા સંત મળે ને તેનો સત્સંગ કરે તો ભવપાર તરે છે. ગૃહી-ત્યાગીનો કંઈ વિવેક ન હોય એવો અધર્મ હોય ત્યાં ક્યારેય મોક્ષ હોય નહિ.”","e":null,"s":["10/15/6-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"સ્વામિનારાયણ મંત્ર","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2134,"k":"para","g":"લોજમાં જન્માષ્ટમી ઉત્સવ પર આવેલા હરિજનોએ શ્રીહરિને અસુરો થકી રક્ષા કરવા પ્રાર્થના કરી ત્યારે શ્રીહરિ કહે, “તમારો દ્રોહ કરશે તેનો નાશ થશે. મારી કાળશક્તિ અધર્મવંશને ઉખેડી નાખશે. સ્વામિનારાયણ નામ તે અમારી મોટી મંત્રશક્તિ છે. તેનો જપ કરનારાને ભૂત, પ્રેત, મૂઠ, ચોટ, જાદુ જીન, વીર, કૃત્યા આદિક મલિન દેવ કાંઈ પણ કરી શકે તેમ નથી. જમકિંકર પણ તેને દેખી દૂર ભાગે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2135,"k":"para","g":"“સ્વામિનારાયણ નામનો જાપ જે કરે છે તેના સર્વ મનોરથ પૂર્ણ થાય છે. મૂઠ-ચોટ કે જાદુ-મંતર તેને સ્પર્શી શકતાં નથી. જે જે મલિન દેવ છે તે કોઈ આ નામ જપનારને પીડી શકતા નથી. સ્વામિનારાયણ મંત્ર કાને પડતાં જ તે બળવા લાગે છે. મહા ભયંકર જમદૂતો પણ આ નામ સાંભળીને નજીક આવી શકતા નથી. જે જીવનભર આ મંત્ર જપે તેને અંતકાળે ભગવાન પોતે સંતો તથા પાર્ષદોને સાથે લઈને તેડવા આવે છે. અને રથ, વિમાન વગેરે વાહનમાં બેસાડી અંતકાળે પોતાના ધામમાં તેડી જાય છે. આવો આ મંત્રનો મહાપ્રતાપ છે. એવો મહિમા સમજી અહોનિશ તેનું રટણ કરવું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2136,"k":"para","g":"“જે જે નિયમ કહ્યા છે તેમાં દૃઢ રહેવું. ચિત્ત ભગવાનમાં રાખવું. દેહ-ગેહ, સુત, નારીનો સંબંધ બે દિવસનો છે. સૌ ઘડી કે પળના મહેમાન છે, એમ જાણી મનમાંથી તેને ટાળી દેવાં, સાચી પ્રીત ભગવાનની સાથે કરવી, સત્પુરુષનો સંગ કરવો ને કુસંગનો ત્યાગ કરવો.”","e":null,"s":["3/3/39-52"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2137,"k":"para","g":"શિયાણીમાં શિવરામ વિપ્રને ઘરે સ્વામિનારાયણ મહામંત્રની ધૂન મુનિ જ્યારે કરી રહ્યા ત્યારે શ્રીહરિ બોલ્યા, “મુનિ! તમે જ્યારે ધૂન કરતા હતા ત્યારે ‘સ્વામિનારાયણ’ નાદ ત્રિલોકમાં વ્યાપી ગયો. જે કોઈ વારંવાર સ્વામિનારાયણ નામનું ઉચ્ચારણ કરે છે તેમાં તેને ભગવાનના બધાં નામ જપનું ફળ મળી જાય છે. આ નામનો જાપ કળિયુગી મળનો અને પાપમાત્રનો નાશ કરે છે. આ મંત્ર સર્વથી પર છે. આજે આ મંત્ર પ્રગટ છે. જેમ પ્રગટ અગ્નિથી કામ થાય છે, તેમ આ મંત્ર દ્વારા સર્વ કાર્ય સફળ થાય છે. કારણ આ મંત્રમાં પરમાત્મા પ્રગટ વસે છે.”","e":null,"s":["6/12/22-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2138,"k":"para","g":"શ્રીહરિએ મોડા ગામનાં પુરજનો પ્રત્યે કહ્યું, “મોક્ષદાતા પ્રગટ ભગવાનનો જોગ થાય નહિ ત્યાં સુધી કર્મનો રોગ મટે નહિ. સ્વામિનારાયણનું નામ છે તે કર્મ બાળવામાં અગ્નિરૂપ છે.”","e":null,"s":["11/12/22"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2139,"k":"para","g":"કરિયાણામાં શ્રીહરિ નાગર સેનાપતિને કહે, “સ્વામિનારાયણ મંત્ર આજ કળિયુગમાં જીવનો ઉદ્ધાર કરનાર છે. સર્વે સંતો-હરિજનો સ્વામિનારાયણ મંત્રની માળા ફેરવે છે. તમારે જેટલી શ્રદ્ધા હોય તે પ્રમાણે નિત્ય સ્વામિનારાયણ જપ સાથે માળા ફેરવવી, પાંચ માળાથી ઓછી ક્યારેય ન ફેરવવી. અધિક કરો તો અધિક લાભ થાય. જીવને સાચો લાભ આ મંત્રના જપથી થાય છે.”","e":null,"s":["13/32/5-7"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2140,"k":"para","g":"શ્રીહરિએ પત્ર લખાવ્યો, “જે ભક્ત ત્રણ દેહ, ત્રણ અવસ્થાથી પર વર્તે, દેહને અસત્ય માને, આત્માને સત્ય માને, પોતાના આત્માને દેહથી પૃથક્ બ્રહ્મરૂપ જાણે ને પરબ્રહ્મ ભગવાન પુરુષોત્તમનો જોગ (ઉપાસના) કરે. એવા ભક્તને વિવેકી ને સમર્થ જાણવો. એવો ભક્ત ‘સ્વામિનારાયણ’ મહામંત્રનું ઉચ્ચારણ શ્વાસોચ્છ્‌વાસે કરે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2141,"k":"para","g":"“સ્વામિનારાયણ મંત્ર સર્વોપરી સુખનું ધામ છે. કળિયુગમાં આ મંત્રનો મહિમા સર્વ મંત્રોથી પર કહેવાયો છે. ઊઠતાં-બેઠતાં, હાલત-ચાલતાં, ખાતાં-પીતાં, સૂતાં-જાગતાં જે જે ક્રિયા થાય તેની સાથે આ મંત્રનો દોર ચાલુ રાખવો. દેહ પરવશ થઈ જાય તોપણ તેની જીભ પરથી ‘સ્વામિનારાયણ’ નામ ન જાય. બધા જન સાંભળે તે રીતે જિહ્‌વાથી આ મંત્રનો ઉચ્ચાર કરવો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2142,"k":"para","g":"“સ્વામિનારાયણ મંત્ર રટણ કરતાં તાલીનાદ કરવો અથવા કરમાં જપમાળા ઘુમાવવી. જ્યારે ઉચ્ચારણ કરવું ત્યારે મનમાં ઊઠતા મિથ્યા સંકલ્પનો ત્યાગ કરવો. સ્વામિનારાયણ નામ જપમાં જે વધુ આગ્રહ છે તે તેના નામી સાથે નામ જપનો છે. તેને જ અલૌકિક સુખ મળે છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2143,"k":"verse","g":"‘સ્વામિનારાયણ નામ કે, આગ્રહ નામી જુત;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2144,"k":"verse","g":"રખત ભક્તજન તિનકું, સુખ મિલત હિ અદ્‌ભુત.’","e":null,"s":["15/96/25-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2145,"k":"para","g":"શ્રીહરિએ પત્રમાં વાત લખાવી કે: “ભગવાનનું નામ નામી સહિત લેવું. અતિ ભાવથી નામ લે તો દેહ છતાં ભગવાનના ધામને દેખે છે. જે હરિભક્ત નામીએ યુક્ત નામનું પ્રતિપાદન ન કરે તેને અમે દેહાભિમાની અને ગુરુદ્રોહી તથા સંતદ્રોહી માનીએ છીએ. નામીએ સહિત નામ લે તેને આત્મદર્શી, ગુરુભક્ત અને સંતભક્ત માનીએ છીએ ને અક્ષરધામમાં તે રહે છે. અમારા આ પત્રનું અતિ પ્રતિપાદન કરજો.”","e":null,"s":["15/97/1-7"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2146,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ મુક્તમુનિના પ્રશ્નનો ઉત્તર કરતાં કહ્યું, “ઉત્કૃષ્ટ ઉપાસનાવાળો ભગવન્નિષ્ઠ ભક્ત એવું સમજે છે કે ‘સ્વામિનારાયણ’ એવા નામનું ઉચ્ચારણ, ગમે તેવા પાપી જીવને જો અંતકાળે થઈ આવે તો તે તત્કાળ સર્વે પાપથી મુકાય છે ને બ્રહ્મમહોલ-અક્ષરધામમાં જાય છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2147,"k":"verse","g":"‘ગમે તેસે પાપી હોય અરુ, અંત મેં જો તિનકું;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2148,"k":"verse","g":"સ્વામિનારાયણ અસે નામ કે ઉચ્ચારન ઇનકું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2149,"k":"verse","g":"હોય જો તેહ સબ પાપ સેં, છુટ જાય તતખેવ હિ;","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2150,"k":"verse","g":"બ્રહ્મમહોલ કે વિષે નિવાસ કરે સદ્ય એહ હિ.’","e":null,"s":["21/55/29-30"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"આશ્રય-અભયદાન","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2151,"k":"para","g":"કુંડળમાં મામૈયાના ભવનમાં શ્રીહરિએ વાત કરતાં કહ્યું, “મારો જે આશ્રિત થાય છે તેને લોકો હડધૂત કરે છે, છતાં અનંત નરનારી હરિજન મને વળગી રહ્યાં છે. મને નિશ્ચય ભગવાન જાણીને જગતનું અપમાન સહે છે. જે મારો થાય છે, તેને કોઈ માન દેતું નથી. માતા-પિતા, પત્ની, ભાઈઓ કે પુત્રોમાં સ્નેહ રાખતાં નથી. મારો આશ્રિત જે થાય તેને બીજા તો દૂર પણ પોતાનાં જ કુટુંબીજન વૈરી ગણે છે. કારણ, મારો આશ્રિત નિષ્પાપ થયો. તેથી બીજાં પાપ આચરનારા કુટુંબીઓ અંતરમાં ભય પામે છે. ધર્મ-અધર્મ, ચોર, શાહુકારને સદા વૈરભાવ હોય છે. પતિવ્રતા અને વેશ્યાને કદી સ્નેહ થતો નથી, તેમ સત્સંગી અને કુસંગીને હેત થતું નથી. હેત થાય તો તેનો સત્સંગ રહે નહિ તે નક્કી વાત છે.”","e":null,"s":["4/33/17-24"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2152,"k":"para","g":"ગઢપુરમાં જીવાખાચરના દરબારમાં સંતોને વાત કરતાં શ્રીહરિએ કહ્યું, “અમારો જેણે આશ્રય કર્યો છે તેને અમારે શુદ્ધ કરવા છે. એટલા માટે જ અમે પ્રકરણ ફેરવીએ છીએ અને સત્સંગમાં ફરીએ છીએ.”","e":null,"s":["5/5/35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2153,"k":"para","g":"માંડવીમાં શ્રીહરિ કહે, “જેણે જેણે મારું શરણ લીધું છે તેને ક્યારેય દુઃખ પડવા દઈશ નહીં. સંત મારા પરમ નિધિ છે. તેનાથી મારે અધિક કોઈ નથી. સંતને હું અક્ષરધામથી અધિક માનું છું.”","e":null,"s":["5/36/25-26"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2154,"k":"para","g":"ગઢપુરમાં જીવેન્દ્ર નૃપને શ્રીહરિ કહે, “‘બધું ભગવાનનું છે’ એમ કહેવામાં ફેર છે. ભગવાનને તો સૌ જાણે છે, પણ તેના નિમિત્તે ક્યારેય કશું થતું નથી. ભગવાન પોતે આવીને કહે, ‘તમારો પુત્ર આપો,’ ત્યારે અંતરમાં હરખ ન રહે અને વિમુખ થાય. ભગવાન જાણ્યામાં સંશય નથી, પણ પ્રાકૃત સમજણ વિશેષ રહી જાય છે. ભગવાનને યથાર્થપણે ભગવાન જાણીને એ મુજબ વર્તે એવા શૂરવીર હરિભક્તો થોડા હોય.” એમ કહી શ્રીહરિએ સમસ્ત સત્સંગમાં એક કાગળ લખાવ્યો કે: “સંત-હરિભક્ત, બાઈ-ભાઈ આદિ કોઈએ દેહને પોતાનું સ્વરૂપ ન માનવું પણ જીવનું સ્વરૂપ શુદ્ધ અક્ષરરૂપ છે એમ જાણી ચિંતવન કરવું. અક્ષરબ્રહ્મનો ભાવ જ્યારે જીવમાં આવે છે ત્યારે પ્રાકૃતભાવ બધો દૂર થઈ જાય છે. અક્ષરમાં સદાય અલૌકિક દિવ્યમૂર્તિ શ્રીહરિ રહ્યા છે. અને સત્સંગમાં જે મૂર્તિ વિચરે છે તે એક જ જીવમાત્રમાં રહી છે. આ દેહનાં સગાં-સંબંધીનો સ્નેહનો તાંતણો દેહ છૂટતાં પણ તૂટતો નથી. દેહ મરે છે પણ જીવ મરતો નથી. છતાં, મિથ્યા સ્વાર્થ માનીને પોતે અજ્ઞાનરૂપ થઈ ગયો છે. એવો સ્વાર્થ સત્ય (બ્રહ્મ-પરબ્રહ્મ)નો સાધે તો તેનું અજ્ઞાન જાય ને અક્ષર જેવો થઈ જાય. હરિભક્તને કાંઈ ભય નથી પણ સમજણ વિના તુચ્છ મતિ રહે છે. હીરો અને કાંકરો સમજણ વિના સરખા દેખાય. માન ન મળે તો સમજણ વિનાનો ભક્ત તે હરિરૂપ હીરાને ફેંકી દે, પણ સત્સંગની મોટપ તો એવી છે કે ભવ-બ્રહ્માદિક દેવો પણ માગે છે. આવો યોગ વારે વારે મળે નહીં.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2155,"k":"para","g":"“જગતની રીતમાં વર્તતા અનંતકાળ ગયા પણ ભક્ત ન થયા ત્યાં સુધી દુઃખ ટળ્યું નહીં. બ્રહ્માના સુખ આગળ કીટનું સુખ કાંઈ નથી. તેમ ભક્ત ન થાય અને અનંત પુણ્ય કરી બ્રહ્મલોકનું સુખ મેળવે તોપણ તે કીટનો કીટ જ છે. અમારે તો હરિભક્તોને બ્રહ્મરૂપ કરવા એટલો જ ઘાટ છે. તેને માટે ચરિત્ર કરીએ છીએ. બીજા જાણે કે ન જાણે અમને જેવા જાણશે તેવું સુખ મળશે. આ પત્રને પ્રાણપ્રિય કરીને રાખજો. જેને કીટ મટવું હોય તથા જે ખળ અને કુટિલ ન હોય, જેને હરિભક્તનો સ્વભાવ રુચે એમ હોય, એવાને જોઈને ભક્ત કરવો. કુટિલ સત્સંગ કરે તો વધારે કુટિલ થઈને સત્સંગીનો દ્રોહ કરે. હરિભક્ત તો નિશ્ચયે કરીને ભગવાનના ધામમાં જાય, પણ કુટિલને અપાર દુઃખ થાય. તે દુઃખ દેખીને કુટિલતા તજી જ્યારે નમ્ર થઈને પોકાર કરે, ત્યારે હરિભક્ત તેનો ઉદ્ધાર કરે.”","e":null,"s":["8/21(20)/17-40"],"sv":["सत्संगमें अब लिखिये एसा । कागद एकहि सुंदर तेसा ॥\n\n संत हरिजन कहावत जेते । बाई भाई आदिक तेते ॥\n\n प्राकृत देह यह जीयेको जेहा । जीयको स्वरूप न मानना तेहा ॥\n\n अक्षर शुद्ध रूप हें अपना । एसो स्वरूप जीयको चिंतवना ॥\n\n अक्षरभावना जीयमें लाई । चिंतवन करनां चित्तमें ताई ॥\n\n अक्षरभाव जब जीयमें आवे । प्राकृत भाव तब दूर रहावे ॥\n\n अक्षरमें हरि रहे हैं सदाई । दिव्यमूर्ति अलौकिक जाई ॥\n\n सत्संगमें विचरत मूर्ति जेहि । एकि एह जीयमें रहे तेहि ॥\n\n देह अरु देह संबंधि जो, विजाति हें अपार ।\n\n देह मरे जीय मरत नहि, छुटत नहि स्नेहतार ॥\n\n मिथ्या स्वार्थ मानिके, अज्ञानरूप भये आप ।\n\n सत्य में करे तिस विध, होई जावे सो अमाप ॥"],"mt":false,"gl":null,"a":false},{"i":2156,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ જીવેન્દ્ર નૃપને કહ્યું, “જે જેને શરણે હોય તે તેના વચનમાં વર્તે અને પોતાનું ધાર્યું મૂકી દે, તે શરણાગતિનું લક્ષણ છે. વર્તનમાં જેટલો ફરક પડે તેટલી શરણમાં કસર છે. દર્દી વૈદ્યનું શરણું લે પછી વૈદ્ય તેને ચરી બતાવે ને તે પ્રમાણે દર્દી વર્તે તો તેનો રોગ જાય. ચરી પાળ્યા વિના રોગ જાય નહિ. શરણાગતિનું લક્ષણ જ એ કે તે વચન પાળે. વચન પાળવાં તે મોક્ષ માટે ચરી છે.”","e":null,"s":["10/5/3-6"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2157,"k":"para","g":"ભાદરામાં શ્રીહરિએ વાત કરતાં કહ્યું, “આત્મનિષ્ઠા તો એટલું ફળ આપે છે કે સુખ-દુઃખમાં શાંતિ રહે અને દેહનાં દુઃખ જે નદી જેવાં છે તેને તરી જાય પણ મૃત્યુ સમયનાં દુઃખ તો સમુદ્ર જેવાં છે. ત્યાં મોટાં વહાણ વિના તરી શકાય નહિ. ભગવાનનું શરણ એ જ મોટું વહાણ છે. તેનાથી જ મૃત્યુરૂપી સમુદ્ર તરાય છે. આત્મજ્ઞાન તો તુંબડા જેવું ગણાય.”","e":null,"s":["11/9/32-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2158,"k":"para","g":"જૂનાગઢમાં દીવાનને ઉદ્દેશીને શ્રીહરિએ કહ્યું, “હરિના શરણ વિના ક્યાંય સુખ ન દેખાય તેવી સમજણ સમાધિથી કોટિગણી શ્રેષ્ઠ છે. સમાધિ કઠણ નથી, સ્વપ્ન જેવી છે. સ્વપ્નમાં રાજા થાય અથવા અષ્ટાંગયોગ શીખ્યો હોય તોપણ બધું વ્યર્થ છે. દીવો દેખીને જેમ પતંગિયું લોભાય તેમ જગતનું સુખ દેખીને લોભાય ત્યાં સુધી સમાધિનો કાંઈ અર્થ નથી.”","e":null,"s":["11/38/24-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2159,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ વણિક પ્રત્યે વાત કરતાં કહ્યું, “ભગવાનના શરણ વિના જે કાંઈ તપ કરે છે તે બંધન કરનારું છે. નાક-કાન કાપીને સોના-મોતીથી તન શોભાડે, તેમ ભગવાનના શરણ વિનાનું તપ પણ દૂષણરૂપ થાય છે.”","e":null,"s":["13/45/29-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2160,"k":"para","g":"વડતાલમાં શ્રીહરિ કહે, “જેને અમારો આશરો છે એવા હરિભક્તને અંતકાળે અમારી સ્મૃતિ રહે અથવા ન રહે તોપણ અમે ને અમારા સંત તેની પાસે જ રહીએ છીએ.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2161,"k":"verse","g":"‘શ્રીહરિ કહે હરિજન જો, જે તે શરન ભયેઉ,","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2162,"k":"verse","g":"સ્મૃતિ રહો ન રહો યહ, હમ સંત પાસ રહે તોઉ.’","e":null,"s":["15/64/14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2163,"k":"para","g":"માણસામાં સંધ્યા પછી સભામાં શ્રીહરિએ કહ્યું, “મોક્ષ માટે જે દુઃખ સહન કરે છે તેના ઉપર ભગવાનની અપાર પ્રસન્નતા થાય છે. ભક્તનું સુખ દેખીને ભગવાન પ્રગટ થતા નથી, પણ દુઃખ દેખીને પ્રગટ થાય છે. ભક્તને બીજું આલંબન હોય ત્યાં સુધી ભગવાન સહાય કરતા નથી.”","e":null,"s":["18/43/23, 31-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"ધીરજ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2164,"k":"para","g":"નીલકંઠવર્ણીરૂપે શ્રીહરિએ પુરીના નૃપને કહ્યું, “‘ધર્મ હોઈ તિહાં રહેનો જાઈ, હમારો સિદ્ધાંત ઇતનો રહાઈ. અધર્મ કો ફલ પાપકું પાવે, ધર્મ કો ફલ ધર્મ રહાવે.’ અમે સિદ્ધાંત કર્યો છે કે ધર્મ હોય ત્યાં જઈને રહેવું. અધર્મનું ફળ પાપ ને ધર્મનું ફળ પુણ્ય મળે છે. ઈશ્વરનું કાળચક્ર બધાને નજરમાં રાખે છે. પરમાત્મા અંતર્યામી છે. જે કોઈ એનું સ્મરણ કરે છે તેની રક્ષા તે કરે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2165,"k":"para","g":"“ભક્તે દેશકાળમાં ધીરજ ધરવી. બધાની નાડી હરિના હાથમાં છે. કોઈ કુમતિ જન ગાળ દે કે તાડન કરે તે સાધુએ સહન કરવું. મનમાં તેનું હિત ચિંતવવું પણ બૂરું ક્યારેય ન ઇચ્છવું. જડભરત ક્યારેય કોઈનું ખરાબ ઇચ્છતા નહિ. આથી ભગવાન તેની રક્ષા કરતા. પ્રહ્‌લાદે કેટલી ધીરજ રાખી! મયૂરધ્વજ, હરિચંદ્ર, દધીચિ વગેરેએ સહન કર્યું તો સંતની પંક્તિમાં આવી ગયા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2166,"k":"para","g":"“સહન કરવું એ સાધુનો માર્ગ છે. ન સહે તે અસુરનો માર્ગ છે.”","e":null,"s":["2/41/20-28"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2167,"k":"para","g":"સરધારમાં શ્રીહરિએ વાત કરતાં કહ્યું, “દેશકાળ સદાય સરખા રહેતા નથી. સત્સંગનો રંગ ચઢ્યો છે તેને જીવતાં સુધી પાર પાડવો. જેની સદાય એક સ્થિતિ રહે છે, સુખ-દુઃખમાં ધીરજ ડગતી નથી તેનો યશ આ બ્રહ્માંડમાં અખંડ રહે છે. ધીરજવાળો કાળના માથે પગ મૂકે છે. સુખ અને દુઃખ વાદળની છાયા જેવાં છે. છાયા આપણા હાથમાં નથી. સંતને હિતકારી માની તેના વચનમાં વિશ્વાસ કરવો.”","e":null,"s":["3/56/45-48"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2168,"k":"para","g":"ગઢપુરમાં જીવાખાચરને શ્રીહરિ કહે, “અમે સમજુને જ વઢીએ છીએ, બીજાને તો બોલાવતા પણ નથી, તોપનો મારો તો પથ્થરના કિલ્લા ઉપર હોય, પણ ઘાસની ગંજી ઉપર હોય નહિ.”","e":null,"s":["5/2/2"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2169,"k":"para","g":"ધમડકામાં રાયધણજી નૃપના ભવનમાં શ્રીહરિએ જમીને સંતોને પીરસ્યું. પછી સભામાં વાત કરતાં કહ્યું, “સુખ-દુઃખમાં ધીરજ રાખે અને ભગવાનનો આશ્રય રાખે તેને કષ્ટ રહે નહિ. ધીરજ રાખનારનો અંતે જય થાય છે. ધીરજ ન રાખે તો અતિશય કષ્ટો સહન કરવાં પડે.”","e":null,"s":["7/17/26, 40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2170,"k":"para","g":"ધમડકામાં શ્રીહરિ કહે, “અમે પ્રથમ વિચાર કર્યા વિના કંઈ પણ કામ કરતા નથી. જે કામનું ફળ અને પોતાની પહોંચ વિચારીને કામ કરે છે તે સુખી થાય છે. નહિ તો ન ટળે એવું દુઃખ તેને આવે છે.”","e":null,"s":["7/18/3-4"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2171,"k":"para","g":"જૂનાગઢમાં શ્રીહરિએ દામોદર કુંડ જતાં વાત કરી, “સત્સંગથી જ મનોવાંછિત સુખ પમાય છે. પણ ધીરજ તજી દે તે દુઃખી થાય છે. દુઃખ દેખી ડગે નહિ તેનો સત્સંગ સાચો છે.”","e":null,"s":["11/53/20-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2172,"k":"para","g":"વડતાલમાં ફૂલદોલના ઉત્સવ પર શ્રીહરિ સંતો-ભક્તોને કહે, “વિચાર્યા વિના જેટલું કરે તેને તેટલો ક્લેશ આવે છે. ક્લેશ આવે પછી ધીરજ રાખે તો શાંતિ રહે. ધીરજ વિના પાર ઊતરવું મુશ્કેલ છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2173,"k":"para","g":"“આ લોક જ એવો છે જેમાં મહા સમર્થને પણ દુઃખ આવ્યાં છે ને આવે છે. ધીરજરૂપી મનવારમાં બેસી ગયો તે દુઃખમાત્રને ઉલ્લંઘી જાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2174,"k":"para","g":"“ધીરજ જેવી બીજી કોઈ સમજણ નથી. જેટલી જેને ધીરજ તેટલો તે મરદ કહેવાય. ધીરજ ખોઈ તો બધું ખોયું. ધીરજ મોટું ધન છે. ક્ષત્રિયને યુદ્ધ વેળાએ ધીરજ પરખાય. સંતની ધીરજ સાધુતામાં પરખાય છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2175,"k":"para","g":"“હરિભક્તની ધીરજ આશરો ન ફરે ત્યારે દેખાય છે. વળી, આધિ, વ્યાધિ, ઉપાધિમાં પણ તેનો આશરો ન છૂટે ત્યારે ધીરજ કળ્યામાં આવે.”","e":null,"s":["16/69/9-13"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"વાસના-દોષ-સ્વભાવ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2176,"k":"para","g":"ગોંડલમાં શ્રીહરિએ હઠીસિંહ રાજાને વાત કરતાં કહ્યું, “માણસનો ક્રોધ પણ ત્રણ પ્રકારનો છે, જેથી મનુષ્યો ત્રણ પ્રકારના કહેવાય છે. ઉત્તમ મનુષ્યનો ક્રોધ જળમાં લીટો કર્યો હોય તેવો ક્ષણસ્થાયી છે. મધ્યમ પ્રકારનો ક્રોધ રેતીમાં લીટા જેવો છે, અને કનિષ્ઠ પ્રકારનો ક્રોધ પથ્થરના લીટા જેવો છે કે જે પ્રાણ જાય તોપણ મટે નહીં.”","e":null,"s":["3/48/50-52"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2177,"k":"para","g":"માંડવીમાં શ્રીહરિ કહે, “મોહરૂપી સમુદ્રમાં જગત આખું ડૂબ્યું છે. સંત મળે છે, ત્યારે બાંહ્ય ગ્રહીને જીવને બહાર કાઢે છે અને તેનો ઉદ્ધાર કરે છે.”","e":null,"s":["5/37/37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2178,"k":"para","g":"શ્રીહરિએ તેરાપુરના જનો પ્રત્યે વાત કરી કે, “વિષય-વાસનાને કારણે લખચોરાશીમાં જીવ અનંત વાર જન્મ્યો છે અને નરકનાં દુઃખ ભોગવ્યાં છે. છતાં તેનો અભાવ થતો નથી. મનુષ્ય દેહ પામીને પણ જે દુઃખમાંથી છૂટવાનો ઉપાય કરતો નથી તે આત્મહત્યારો કહેવાય છે.”","e":null,"s":["5/45/28-31"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2179,"k":"para","g":"શ્રીહરિએ અંજાર ગામના હરિજનોને હેત લાવીને વાત કરી, “જે વાત કરવા જેવી નથી તે કરવા માટે લોક-શાસ્ત્રમાં નિષેધ કરેલો છે, તેને જે કરે છે તે આ લોક અને પરલોકમાં દુઃખી થાય છે છતાં કરે છે, તેનું નામ મોહ છે. દરેક પ્રકારની મદિરાથી મોહમદિરા ભારે ઉન્મત્ત કરનારી છે. મોહમદિરાથી મનુષ્યો અંધ થાય છે. અને જેમાં તે ખોટી રીતે સુખ માની બેઠો છે તેમાં કોઈ દુઃખ દેખાડે તો તેને શત્રુ માને છે.”","e":null,"s":["11/5/34-39"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2180,"k":"para","g":"વડતાલમાં શ્રીહરિએ કહ્યું, “સમર્થ થઈને લોભ કરે તે મળ સમાન છે. ભગવાનને માર્ગે લોભ રાખે અને સુમાર્ગે પણ ધન વાપરે નહિ એ અમને રુચે નહીં. સુમાર્ગે ન વાપરે એનું કુમાર્ગે જાય છે. તેનું ફળ મહાપાપરૂપે ભોગવવું પડે છે.”","e":null,"s":["17/38/30-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2181,"k":"para","g":"ગઢપુરમાં શ્રીહરિએ કહ્યું, “જ્યાં સુધી સત્સંગ ન કરે ત્યાં સુધી મોહના પૂરમાં વહે છે અને અવશ્ય કરવાની વાત તેને દેખાતી નથી. ભગવાન વિનાની વાત ઝેર જેવી લાગે ત્યારે મોહ ગયો કહેવાય.”","e":null,"s":["20/16/13-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"વાણી અને વિવેક","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2182,"k":"para","g":"માનકુવામાં શ્રીહરિ કહે, “એકબીજાની મર્યાદા રાખવી. કટુ વચન બોલવું નહિ. કટુ વચન બોલે તે કુસંગી કહેવાય.”","e":null,"s":["5/50/9-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2183,"k":"para","g":"પીપળીમાં શ્રીહરિ પુરજનો પ્રત્યે કહેવા લાગ્યા કે, “પથ્થર બધા પારસમણિ હોતા નથી એ મનમાં સમજી રાખવું. પારસ અને ચિંતામણિ પથ્થર જ છે પણ તેના ગુણ જુદા છે. ધાતુની જાતિ પણ અનંત છે તેના ભેદ બુદ્ધિવંતને જાણ્યામાં આવે છે. જેના હૃદયમાં વિવેક છે તે ભેદને પારખી શકે છે. વ્યવહાર માત્ર વિવેક વિના થતો નથી. વિવેક રહિત મનુષ્ય દરેકની સાથે સરખો વ્યવહાર કરે, તે ક્યારેય સુખી થાય નહિ. જગતમાં રાજાઓ ઘણા કહેવાય તેમાં પણ અનંત ભેદ છે. તે જ રીતે સંત-સંતમાં પણ ઘણા ભેદ છે. તેને બુદ્ધિમાન હોય તે જાણે છે. બુદ્ધિ-બુદ્ધિમાં પણ અનંત ભેદ છે. બધાની બુદ્ધિના ગુણો સરખા નથી.”","e":null,"s":["5/69/1-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2184,"k":"para","g":"ભૂજ કોટડામાં શ્રીહરિએ સભાજનોને વાત કરતાં કહ્યું, “અન્ય વ્યક્તિમાં અપરંપાર દોષ હોય, પરંતુ તેમાંથી એકાદ સારભૂત ગુણ શોધી તેને ગ્રહણ કરે તે વિવેકી અને બુદ્ધિમાન છે. વિવેકી જન જાણે છે કે આ દેહ નખથી શિખા પર્યંત અસાર વસ્તુથી ભરેલો છે, એટલે તેને મોહ થતો નથી.”","e":null,"s":["6/39/35-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2185,"k":"para","g":"સાથે ફરનારાને શ્રીહરિ એક વાત કરતા કે, “અમારી સાથે જે રહે તેણે કોઈ પ્રકારની રીસ રાખવી નહિ તથા સંત હરિભક્તોને ડારો દેવો નહિ. કોઈને કંઈ કહેવું હોય તો હાથ જોડીને બોલવું. તમને જે શસ્ત્ર બંધાવ્યાં છે તે સંત અને હરિભક્તોની રક્ષા માટે બંધાવ્યાં છે, પણ તેના કેફથી કોઈને દબાવવા નહિ. સંત-હરિજનોને લગારેય દુખવશો તેના દુઃખનો પાર નહિ આવે. તેની સન્મુખ અમે ક્યારેય જોઈશું નહિ, તમારું કરેલું તમે જાણો.”","e":null,"s":["8/50/29-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2186,"k":"para","g":"કૌકામાં હરિજનો પ્રત્યે શ્રીહરિએ કહ્યું, “સીતા અને રાધા જેવાં કોઈ ભક્ત ગણાય નહિ. તેમનો મહિમા રામ અને કૃષ્ણ જેવો છે અને મૂર્તિઓ પણ સાથે જ પધરાવાય છે. ભજન પણ તેમનું સાથે થાય છે. તોપણ બે-ત્રણ વાર તેમના વચનમાં દોષ આવ્યો. બાઈઓમાં જો ઈર્ષ્યા અને ક્રોધ ન હોય તો તેમનાં જેવાં કોઈ પ્રેમી નહિ, પણ ઈર્ષ્યા, ક્રોધ હોય તેથી ન બોલ્યાની વાત બોલાવે, જેમાંથી બીજાનું મરણ થશે તેનું પણ ભાન રાખે નહિ. બીજા ઘણાક ગુણો હોય, પણ તેમના ક્રોધથી ડરતું રહેવું પડે છે. બીજાને પાછા પાડવા માટે પણ તેમની ભાષા પ્રવર્તે છે, પણ તેમાંથી લાજવાળા માણસનું મરણ થાય છે. જે હરિભક્ત પુરુષો બાઈઓના વચનને સહન કરે છે તેમને ધન્ય છે. સીતાનાં વચન સાંભળીને વચનના ભયથી અમે પણ ઘર છોડીને બ્રહ્મચારી થઈ ગયા.”","e":null,"s":["12/57/31-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2187,"k":"para","g":"ગઢપુરમાં જીવેન્દ્ર નૃપના દરબારમાં શ્રીહરિએ કહેલી વાત મુક્તમુનિએ કહી, “સત્સંગની વૃદ્ધિ વાતે કરીને થાય છે, એ પ્રગટ દેખાઈ આવે છે. કથા-કીર્તન, ધ્યાન-સ્મરણ નિયમ પ્રમાણે થતાં હોય ત્યારે સૌ ભેગાં મળે, સમજણ થાય ને સત્સંગ વધે. મનમાં ધારો તો થાય. જે ધારો તે ફળે છે. તેનું મૂળ કથાવાર્તા છે. કથાવાર્તામાં અમૃત રહ્યું છે. વાત કરતાં ન આવડે તો વિષ બની જાય છે. વાતે કરીને ઝાઝા જન ઊગરે છે ને વાતે કરીને ઝાઝા જન મરે પણ છે. નટ જેમ દોર પર ચાલે તેમ વાત કરનારે કોઈ સામું જોયા વિના ભગવાન સામે સૂરત રાખવી. બધી વાત ગુરુ થકી શિખાય છે.”","e":null,"s":["13/63/13-20"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2188,"k":"para","g":"ગઢપુરમાં જીવેન્દ્ર નૃપને શ્રીહરિએ વાત કરી, “બુદ્ધિ હોય પણ વિવેક વિના મોક્ષના માર્ગે પ્રતીતિ થતી નથી. મનુષ્યતન પામીને મોક્ષને માર્ગે ન ચાલે અને ફાવે તેવો બુદ્ધિશાળી હોય તોપણ વ્યર્થ છે. બુદ્ધિ તે જ સારી કે તે મોક્ષના કામમાં આવે. મનુષ્યતન પામી જે કરવાનું છે તે ન થાય તેથી કોઈ બીજો મોટો દ્રોહ કે અજ્ઞાન નથી. ચિંતામણિ હાથમાં આવે અને અલ્પ સુખ માટે તેને તજી દે તેના જેવો તે અજ્ઞાની કહેવાય.”","e":null,"s":["16/45/6-9"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2189,"k":"para","g":"શ્રીહરિએ સુરતમાં અરદેશર કોટવાલ સાથે વાત કરતાં કહ્યું, “અનંત પ્રકારનાં શરીર છે. તેમાં મનુષ્ય તન સમાન કોઈ નથી. તેમાં બધા પ્રકારનો વિવેક રહેલો છે. મનુષ્ય થઈને પણ વિવેક ન આવે તો તે શરીર પશુમાં ખપે છે. વિવેક કરી સાર-અસાર સમજીને જન્મ-મરણ ને જમપુરીના દુઃખથી છૂટવું એ મનુષ્ય તનનું ફળ છે. એ દુઃખ જ્યાં સુધી રહ્યું ત્યાં સુધી વિવેક આવ્યો કહેવાય નહિ. પોતાને બહુ ચતુર માને તેથી કરીને શું થયું? મનુષ્ય તન સુફળ કરે તે જ ખરો ચતુર છે.”","e":null,"s":["27/50/34-38"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"કુસંગ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2190,"k":"para","g":"જૂનાગઢમાં શ્રીહરિએ વિપ્રોને વાત કરતાં કહ્યું, “કુસંગ ઓળખવામાં આવે એ જ સત્સંગનું ફળ છે. કુસંગ જ ન ઓળખાય તેનું નામ સત્સંગ નહિ.”","e":null,"s":["11/51/8"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2191,"k":"para","g":"શ્રીહરિએ ડભાણના હરિભક્તોને વાત કરતાં કહ્યું, “સત્સંગ દૃઢ કરીને રાખવો. જેમ પોતાની જાતની દૃઢતા છે એવી દૃઢતા કરવી. સત્સંગથી કોઈ વાત અધિક નથી. દુર્લભમાં દુર્લભ સત્સંગ છે જે સહેજે પ્રાપ્ત થયો છે. બાળકબુદ્ધિ રાખે તેનો સત્સંગ નાશ થઈ જાય છે. પાકો હરિભક્ત હોય પણ વિમુખની વાત સાંભળે તો બુદ્ધિ પલટાઈ જાય છે. માટે હરિભક્તે સાવધ રહેવું.”","e":null,"s":["14/26/1-5"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2192,"k":"para","g":"શ્રીહરિએ પત્રમાં એક વાત લખી હતી: “અસત્ પુરુષના સંગથી અસત્ ગુણ આવે છે. મોક્ષ-માર્ગની તેઓ હાંસી કરે છે. જેથી સુમતિનો નાશ થાય છે અને કુમતિનો ઉદય થાય છે.”","e":null,"s":["15/80/33-34"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2193,"k":"para","g":"શ્રીહરિ ફરી પત્રમાં વાત કહેવા લાગ્યા: “મુમુક્ષુ હોય તેને અસત્ પુરુષનો યોગ થાય તો તેની મતિ અસત્ થઈ જાય છે. પછી તે તીર્થ-વ્રત વગેરેને અસત્ કહે છે અને અસત્ માર્ગે દોડે છે, તેથી અસત્ ગતિ પામે છે. ઝેરનાં બી વાવે તેવું જ ફળ પામે છે. એવા જનો જીવે ત્યાં સુધી બીજાને સુખ થવા દે નહિ.”","e":null,"s":["15/81/3-4"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2194,"k":"para","g":"આદરજમાં શ્રીહરિએ કહ્યું, “સન્માર્ગે ચાલતા જનને અસન્માર્ગે ચલાવે તેને આખા બ્રહ્માંડના જીવોને માર્યા જેટલું પાપ લાગે છે.”","e":null,"s":["18/28/21-23"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"અંતર્દૃષ્ટિ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2195,"k":"para","g":"શ્રીહરિએ મેઘપુરમાં વાત કરતાં કહ્યું, “દોર પર નટ ચાલે છે ત્યારે એક જ સૂરત રાખે છે અને સફળ થાય છે. દોર પર ચાલવા કરતાં પણ મોક્ષનું કામ ભારે છે. તેમાં બાળકબુદ્ધિ રાખે તો તે ખુવાર થાય છે. નારદ, પ્રહ્‌લાદ અને ધ્રુવની રીત રાખીને ચાલવું અને ભગવાનમાં પ્રીતિ કરવી. સત્ય, અસત્ય અને સારાસારનો વિચાર કરવો. કોઈ દિવસ ગબરગંડ રહેવું નહિ. સુવર્ણ જેમ તપાવીને શુદ્ધ કરી શકાય છે, તેમ જીવને ખૂબ શોધવો, પણ ગાફલ રહેવું નહિ. ગાફલનો વિશ્વાસ અને સંગ કરવો નહિ.”","e":null,"s":["3/34/44-48"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2196,"k":"para","g":"શ્રીહરિએ પત્રમાં જણાવ્યું: “ગાફલને દેખીને કળિનું જોર પ્રવર્તે છે. સત્સંગી બાઈ-ભાઈએ પોતાના ગમે તેવા સંબંધી સાથે પણ એકાંતમાં બેસવું, ઊઠવું તથા ચાલવું નહિ તથા ગાફલપણું રાખવું નહિ. ગાફલપણું રાખે તેને સત્સંગ બહાર કરવો અને હરિજનબાઈ પુરુષ સાથે છાની પ્રીત અને પ્રસંગ રાખે, તો તેનો પણ તરત ત્યાગ કરવો. જેને મોક્ષનો ખપ હોય તે નિયમમાં વર્તે છે. નિયમ વગરની વાત બધી દૈવત વિનાની જાણવી. જે બાઈ-ભાઈ-હરિજન નિયમમાં યથાર્થ વર્તશે, એને અમે અંત સમયે નિશ્ચય વિમાન લઈને તેડવા આવીશું અને અવિચલ સુખ આપીશું.”","e":null,"s":["15/79/19-25"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"કથાવાર્તા","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2197,"k":"para","g":"ગઢપુરમાં શ્રીહરિ કહે, “કથામાં પ્રીતિ ન હોય તે અમને બહુ પ્રિય લાગતા નથી. કથા-કીર્તનના અંગવાળાનાં અમે વખાણ કરીએ છીએ.”","e":null,"s":["15/55/35"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2198,"k":"para","g":"પત્રમાં શ્રીહરિ હરિજનોને ફરી કહેવા લાગ્યા, “કથા, કીર્તન ને સેવામાં જેનું ચિત્ત પરોવાય નહિ, તેને રોગી અને બાળક જાણવો. જેનો રોગ અને બાળબુદ્ધિ જાય તેને કથા-કીર્તનમાં રુચિ થાય છે. તે વિના સત્સંગમાં મૂળ જામતું નથી.”","e":null,"s":["15/76/11-14"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2199,"k":"para","g":"શ્રીહરિએ સંતો-હરિજનોને પત્રમાં એકાદશીના જાગરણની વાત કહીને કહ્યું, “હરિજનોએ ભેગા મળીને કથા-કીર્તન કરવાં અને અમારાં ચરિત્ર જે દેખ્યામાં આવ્યાં હોય તે સંભારવાં. શ્વાસોચ્છ્‌વાસે ભગવાનનું નામ બોલવાનો અભ્યાસ રાખવો. એવી રીતે ભજન કરે તેને મનના સંકલ્પ બંધ થાય છે.”","e":null,"s":["15/89/1-2, 25-27"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2200,"k":"para","g":"ગઢપુરમાં શ્રીહરિ કહે, “અમે સંતો માટે, મંદિર માટે જેટલું કરીએ તે તલભાર પણ કઠણ મનાતું નથી. અન્ન ને જળ જેમ મનુષ્યનું જીવન છે, તેમ ભગવાન સંબંધી કથા-કીર્તન પણ ભક્તનું જીવન છે. કથા, કીર્તન ને સત્સંગની સેવામાં જેટલો ભાવ છે તેટલો જ સત્સંગ સાચો છે.”","e":null,"s":["28/65/33-36"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"મહિમા, માહાત્મ્ય, ગુણગ્રાહક દૃષ્ટિ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2201,"k":"para","g":"બોટાદમાં શ્રીહરિ કહે, “માહાત્મ્ય વિના ગુણદોષ આવે છે અને ગુણદોષ આવે ત્યાં સુધી વિઘ્ન રહેલાં છે.”","e":null,"s":["11/80/13"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2202,"k":"para","g":"કૌકામાં હરિજનો પ્રત્યે શ્રીહરિએ કહ્યું, “મહિમા વિના સત્સંગ સમજાય નહિ, મહિમા હોય તે સત્સંગમાં દિવસે દિવસે વધે છે. મહિમા વિનાનાં સાધન વૃથા છે. મહિમા વિનાનાં સાધન મેરુ સમાન હોય તોપણ મહિમાએ યુક્ત અણુ જેટલાં સાધન બરાબર થાય નહિ. કરોડો મચ્છર ગરુડ તુલ્ય થઈ શકે નહિ. હરિભક્તને પરસ્પર હેત ન હોય તો સાધન અપાર કરે તોપણ ફળ મળતું નથી. બીજાં અંગ નીરોગી હોય પણ શ્વાસ બંધ થાય તો કોઈ સહાય કરી શકે નહિ, તેમ મહિમા વિનાનાં સાધન જાણવાં. મહિમા રસ છે અને સાધન કૂચા છે. માયિક જીવને તે ગમે નહિ. તેને તો માયિક વસ્તુ ગમે. ગીંગો ગોબરમાં જ લોભાય અને ગધેડો કૂચામાં જ લોભાય છે. ચિંતામણિનો મહિમા તે બાળક જાણતો નથી, તેથી બોરને પણ તેથી અધિક માને છે... મહિમા વિના પરીક્ષિતને પણ સંશય થયો.”","e":null,"s":["12/57/10-21"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2203,"k":"para","g":"આખા ગામમાં શ્રીહરિ કહે, “ગુરુ, સંતો અને હરિભક્તોના અલ્પ ગુણ હોય તેને મેરુ સમાન કહે તો શુદ્ધ મનવાળો છે. તપ કરવા કરતાં પણ સંતના ગુણ ગ્રહણ કરવા તેનું બળ વધારે છે.”","e":null,"s":["14/31/30-33"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"ધ્યેય, અંતિમ લક્ષ્ય","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2204,"k":"para","g":"શ્રીહરિએ હરિજનોને પત્રમાં વાત લખતાં કહ્યું: “દુઃખ સહન કર્યા વગર સુખ મળતું નથી. મોક્ષને માટે પ્રથમ સુખનો ત્યાગ કરે ત્યારે તેને અવિચલ સુખ મળે છે. ઉદ્યમ વગર અલ્પ વાત પણ સિદ્ધ થતી નથી. મોક્ષને માર્ગે ચલાય તેટલું જ મનુષ્યદેહનું ફળ છે. બુદ્ધિમાન થઈને મોક્ષને માર્ગે ન ચાલે તો તે ગમે તેવો બીજી વાતે કુશળ હોય છતાં મનુષ્ય તન ન પામ્યા બરાબર છે. બુદ્ધિનું ખરું ફળ અવિચળ સુખ સિદ્ધ કરવું એટલું જ છે, બીજા ઉદ્યમ કાંઈ પણ અર્થમાં આવતા નથી.”","e":null,"s":["15/80/5-9"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પરિશિષ્ટ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2205,"k":"para","g":"શ્રીહરિ કથિત પ્રસ્તુત વિષય પર ગ્રંથકારની ટિપ્પણી અને પુષ્ટિ:","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":null,"k":"heading","g":"સ્વામિનારાયણ મંત્ર","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2206,"k":"para","g":"શ્રીહરિએ સ્વામિનારાયણ મંત્રની ધૂન સ્વયં કરાવી. એ શબ્દ ચૌદ ભુવન, ગિરિ, વન, તરુવરો બધે વ્યાપ્યો. જમપુરીમાં જેના કાને એ મંત્ર પડ્યો તેનાં સર્વે પાપ બળી ગયાં. ધર્મરાજ કહે, “પૂર્વે અવતારોએ આવું ઐશ્વર્ય જણાવ્યું નથી.” નરકના કુંડ ખાલી થવા લાગ્યા. જીવો પાપમુક્ત થઈ ચતુર્ભજ રૂપ ધારણ કરીને દેવ થવા લાગ્યા. ધર્મરાજાએ એ જીવોને કહ્યું, “દેવ થયા તે તમારાં પુણ્ય નથી. આજ સ્વામિનારાયણ ભૂતલમાં પ્રગટ વિરાજે છે. તેમના મંત્રના પ્રતાપે તમારો ઉદ્ધાર થયો છે. એમ નિશ્ચય જાણજો.”","e":null,"s":["4/103/17-26"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2207,"k":"para","g":"‘સ્વામિનારાયણ’ મંત્રનું ઉચ્ચારણ જે જન કરતો હોય ને તેના કંઠમાં પ્રાણ આવી ગયો હોય તોપણ તેને અન્ન-જળનું પોષણ થતું રહે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2208,"k":"para","g":"દુખિયારાને કદી કડવું વચન ન કહેવું. જો કડવું વચન કહે તો તે દુખિયારાનાં સઘળાં પાપ તેને વળગે છે. આ સત્સંગની રીતિ છે. નિયમ-ધર્મનું પાલન કરોડ વરસ સુધી કરે, પણ જો ગરીબ ભક્તને દુખવે તો તેના પરથી શ્રીહરિનો રોષ ઊતરતો નથી. ભલે દિવસ-રાત સ્વામિનારાયણનું ભજન કરે, પણ તેને જોઈને શ્રીહરિની છાતી ઠરતી નથી. આ લોકમાં કદાચ તેની કીર્તિ અપાર હોય, જગત તેને પૂજ્ય કરીને માને, પણ અનાથને જો દૂભવે તો તેને દુઃખ અત્યંત ભોગવવાં પડે છે.","e":null,"s":["6/65/20-24"],"sv":["स्वामिनारायण उचरे जेहि । कंठ में प्रान जानना तेही ॥\n\n जल अन्न ताकुं होवत रेना । कटु कुबेन दुखिन कुं न केना ॥\n\n कटु कबेन दुःखी कुं केवे । ताके पाप सो सब लेवे ॥\n\n ऐसे हे सत्संग की रीति । भावे तेसी करो अनीति ॥\n\n नियम-धर्म कोटि रखे वर्षा । ता पर हरिकुं रहत अमर्षा ॥\n\n कथा भजन करो दिन-राती । हरि कुं जोई न ठरत छाती ॥\n\n यह लोक तेहि कीर्ति अपारा । पूज्य करिके मानहि सारा ॥\n\n देह दुखी होवहि न पारा । अनाथ के जे दूभनहारा ॥"],"mt":false,"gl":null,"a":true},{"i":2209,"k":"para","g":"શ્રીહરિએ જીવેન્દ્ર નૃપના ભવનમાં રંગોત્સવ કર્યો. જાણે બારે મેઘ મળી હેલી મચાવી હોય તેમ શ્રીહરિએ રંગવર્ષા કરી. આકાશમંડળમાં ‘સ્વામિનારાયણ’ મંત્રની ધૂન, દેવો વાજિંત્ર સાથે ગુંજાવવા લાગ્યા. ચૌદ લોકનાં ધામોમાં એક સાથે સ્વામિનારાયણ મંત્રનાદ ગુંજ્યો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2210,"k":"para","g":"સ્વામિનારાયણ નામનો મહિમા કળિયુગમાં ઠેર ઠેર છવાઈ ગયો. અવતાર માત્ર પોતાના ભક્ત સહિત આ સ્વામિનારાયણ મંત્રનો ઉચ્ચાર કરવા લાગ્યા. સ્થાવર જાતિ પણ આ મંત્રનું ઉચ્ચારણ કરવા લાગી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2211,"k":"para","g":"શ્રીહરિ સ્વયં સ્વમુખે સ્વામિનારાયણ મંત્રજાપ કરવા લાગ્યા ત્યારે અવતારોનાં અન્ય અનંત નામો ને મંત્રો આ સ્વામિનારાયણ નામમાં આવીને લીન થતાં હોય તેવું સૌને દેખાયું.","e":null,"s":["7/5/29-36"],"sv":["रमत भये हरि होरी जैसे । संतजन गावत भये सब तैसे ॥\n\n गावत स्वामिनारायण सबहु । देव वाजित्र बजाई के तबहु ॥\n\n चौद लोक में धाम हि जेता । स्वामिनारायण उचरत तेता ॥\n\n स्वामिनारायण नाम को जोऊ । कलि में महिमा भयो है सोऊ ॥\n\n अवतार मात्र कहावत जेऊ । आप आपके धाम में रहे तेऊ ॥\n\n स्वामिनारायण नाम हि तेहा । भक्त सह उचरत भये एहा ॥\n\n स्थावर जाति कहावत जेति । स्वामिनारायण उचरत तेति ॥\n\n एसो नाम को भयो प्रतापा । श्रीहरि मुख जपत भये आपा ॥\n\n स्वामिनारायण नाम में आई । नाम अनंत लीन होत दिखाई ॥"],"mt":false,"gl":null,"a":true},{"i":2212,"k":"para","g":"ભુજમાં શ્રીહરિ ગંગારામ મલ્લને ત્યાં ઉતારે બિરાજતા હતા. સંધ્યા વખત થયો ત્યારે પૂજા કરી નાહ્યા અને મશાલો તથા બિલોરી ઝાડનો પ્રકાશ થયો. સૌ સંધ્યા આરતી કરીને તાળી વગાડતાં ‘સ્વામિનારાયણ’ મહામંત્રની ધૂન કરવા લાગ્યા. શ્રીહરિ હિંડોળામાં ઊભા રહીને ધૂન કરતા હતા. તે બે ઘડી (૪૮ મિનિટ) સુધી એકધારી ધૂન કરી અને સર્વત્ર નાદ વ્યાપી ગયો. સ્વામિનારાયણ નામ સર્વથી વિખ્યાત છે. જેમાં અન્ય બધાં નામ સમાઈ જાય છે. તેનો જપ કરતાં બીજાં કોઈ નામ બાકી રહેતાં નથી. આ મંત્ર કોઈ એક જ વાર જપે તોપણ અન્ય સર્વે મંત્રોનો જાપ તેમાં આવી જાય છે. આવો મહિમા-પ્રતાપ જાણીને જે જન ‘સ્વામિનારાયણ’ મંત્રનું ઉચ્ચારણ કરે છે, તેને સકલ મંત્રોનો પ્રતાપ અને ફળ પ્રાપ્ત થાય છે. બીજા નામમાં બધાંય નામનો પ્રતાપ આવે નહિ. જેને મહિમા નથી તે બીજા નામને અધિક કરીને માને છે.","e":null,"s":["10/35/3-9"],"sv":[],"mt":false,"gl":null,"a":true},{"i":null,"k":"heading","g":"વાણી-વિવેક","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2213,"k":"para","g":"કટુ વચન તે મોટામાં મોટું ઝેર છે. લગારેક કટુ વચન કહે તોપણ તેને દુઃખનો પાર રહેતો નથી. વારંવાર કટુ વચન કહે તેની સહાય શ્રીહરિ કરતા નથી. વળી, કટુ બોલનારને મર્યા પછી પણ જશ મળતો નથી. માણસ માત્ર તેને વગોવે છે. નર કે નારી કડવું વચન સુણીને મરે છે. ગરીબ મૂંઝાઈને મરે પણ જે ગરીબ નથી તેને વાણી મારે છે. કટુ ભાષણ એ મર્યા વિનાનું મૃત્યુ છે. અપશબ્દ બોલવામાં જેને લાભ મનાતો હોય તો તે ઠગારો લાભ છે. એવા જનની ધન-સંપત્તિ નાશ પામે છે. અરે, પોતાનું પણ મૃત્યુ થાય છે તોપણ તે પોતાનો કટુભાષણનો સ્વભાવ છોડતો નથી. જેને અતિ સંપત્તિ મળે છે તેનો મદ વચનમાં જણાઈ આવે છે. દ્રવ્ય અને મોટાઈ પાત્ર વિના ટકતાં નથી. અપાત્ર હોય તેને ધન-મોટાઈ મળે તો તે નિધડક બોલવા લાગે છે.","e":null,"s":["5/66/32-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2214,"k":"para","g":"સંતનાં વચન વિચારપૂત હોય છે. શુદ્ધ મનમાંથી આવતાં હોય છે. સંત ક્યારેય અપ્રિય ઉચ્ચારતા નથી. પ્રિય જ બોલે છે, અને સંત તેને જ કહેવાય. અપ્રિય બોલે તે અસંત છે. સંત ક્યારેક અપ્રિય કહે તો તે વચન જીવ માટેનું ઔષધ છે એમ સુજ્ઞ જનો જાણે છે. અસાધુને તે સમજાતું નથી.","e":null,"s":["15/44/1-4"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2215,"k":"para","g":"સંતના મંડળમાં જે મુખ્ય હોય તે પોતાનું વર્તન શુદ્ધ રાખી બીજા સંતને વાત કરે તો તેઓ ગ્રહણ કરે. વર્તન વિના કરેલી વાત અસર કરે નહિ. વચનામૃત મુખે કર્યાં હોય, સત્સંગના ગ્રંથોનું રહસ્ય યાદ રાખ્યું હોય, યોગકળા શીખી રાખી હોય, તે બીજા સંત-હરિભક્તને હરાવવા માટે કે પોતાના સ્વાર્થને માટે કર્યું હોય તો તે ઝેર સમાન છે.","e":null,"s":["18/37/22-26"],"sv":[],"mt":false,"gl":null,"a":true},{"i":null,"k":"heading","g":"સહનશીલતા","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2216,"k":"para","g":"અક્ષર પણ જેને આધીન વર્તે છે જેની મરજીને ક્યારેય લોપતા નથી એવા શ્રીહરિ સામર્થ્ય છુપાડીને વર્તે છે. અલ્પ મનુષ્ય જેમ તેમ બોલી જાય તોપણ તેને સહન કરે છે. આવી સહનશીલતા હરિ સિવાય કોઈમાં સંભવે નહિ. સમર્થ હોય ને સહન કરવું તે કપરું છે. સામર્થિ હોય ને સહન કરે તેને ભગવાન જાણવા. સહન ન કરે તે જીવકોટિના છે. આ તફાવત વિષમ દેશકાળ આવે ત્યારે પરખાય છે. તે વિના પરખાય નહિ.","e":null,"s":["4/56/36-40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2217,"k":"para","g":"શ્રીહરિની સેવામાં જે પાળા રહેતા તે શ્રીહરિની મરજી ક્યારેય લોપતા નહિ. શ્રીહરિ તેમનો તિરસ્કાર કરે, વઢે તો સવળું લેતા. દુખાતા નહિ. સવળું લઈ મહિમાથી સેવા કરે તેને શ્રીહરિ રાખતા, વઢે ત્યારે દુઃખ લગાડે તેને દૂર કરતા. કહે ને ખોટું લગાડે તેનો વિશ્વાસ શ્રીહરિ કરતા નહિ. સહન ન કરી શકે તેને જેમ તેમ કરીને નભાવી લેતા, દુખવતા નહિ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2218,"k":"verse","g":"‘જ્યું ત્યું કર તેહિ કરત નિભાવા, કોઈ રીત કર ન દેત દુખાવા...’","e":null,"s":["4/107/8-12"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2219,"k":"para","g":"આ સત્સંગમાં એક હરિભક્ત બીજા હરિભક્તનું અપમાન કરે ને જો તે અપમાનને સહી લે તો તે હરિભક્તને સત્સંગમાં શિરોમણિ જાણવો. હરિભક્ત થઈને હરિભક્તનું અપમાન ન કરવું. અજાણે અપરાધ થઈ જાય તો કર જોડીને, ક્ષમાની પ્રાર્થના કરવી એ હરિભક્તની રીત છે. અને સામેના હરિભક્તે પણ ક્ષમા કરી દેવી. કાંઈ અપરાધ થયો નથી એમ કહેવું. વિનય તજી ક્રોધ કરીને કહેવું તે સત્સંગની રીત નથી.","e":null,"s":["11/42/11-15"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2220,"k":"para","g":"મનુષ્યની જાતિ એક છે, પણ જેવો ખપ હોય તેવો સત્સંગ થાય. વાત સાંભળતાં સાંભળતાં પાપ ટળે છે ત્યારે સત્સંગ થાય છે. ધીરે ધીરે સત્સંગ વૃદ્ધિ પામે. એક દિવસે બધા સત્સંગી થાય નહિ. હિત દઈને કહેતાં આવડે તે સંતથી સત્સંગ થાય. કડવાં વચન બોલવાથી દસ વર્ષનો સત્સંગ પણ ટળી જાય. સો વર્ષની ઇમારત નવી ને નવી રાખવી હોય, પણ અગ્નિ લાગે તો કાંઈ રહે નહિ, તેમ કડવાં વચન ઝેર અને અગ્નિ સમાન છે. કડવાં વચન પણ ઔષધિ સમાન મનાયાં હોય તો વિવાહની ગાળો પેઠે પ્રિય લાગે.","e":null,"s":["11/81(71)/31-39"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2221,"k":"para","g":"ભગવાન જેવી ક્ષમા આપે છે તેવું બીજા કોઈથી થઈ શકે નહિ. જેમના હાથમાં અનંતકોટિ બ્રહ્માંડની દોરી છે એવા એ મોટા સમર્થ હોવા છતાં જરણાં કરે, કટુક વચન ક્યારે મુખથી ઉચરતા નથી. ક્ષમાવાનથી મોટો કોઈ નથી. સર્વે મોટપમાં આ મોટપ અધિક છે. એ જીવની દૃષ્ટિમાં આવતી નથી, મોટાની મોટપ જ એ કે જરણા કરે, જેટલી જરણા કરે તેટલી મોટપ વધુ. જેનું કંઈ ઊપજે નહિ ને જરણા કરે એ કંઈ મોટપ નથી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2222,"k":"para","g":"સર્વથી મહાન કહેવાતો હોય ને તેનામાં જો ક્ષમાનો ગુણ ન હોય તો તેના દ્વારા અનંત જીવોનો મોક્ષ થાય નહિ. અનંત રિદ્ધિ-સિદ્ધિ ક્ષમાવંત પુરુષની દાસી થઈને રહે છે. અને અનંત શુભ ગુણો પણ ક્ષમાવંતના દાસ થઈને રહે છે. ક્ષમા જેવી કોઈ પ્રભુતા નથી, ક્ષમા સત્પુરુષને જ વરે છે જે સમર્થ હોવા છતાં ક્ષમા કરે છે.","e":null,"s":["12/72/23-30"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2223,"k":"para","g":"મુક્તમુનિ કહે, “શ્રીહરિ કહેતા, ક્ષમા કરે તેને સમર્થ જાણવો. ભૂમિ અપાર પાપ સહન કરે છે, તો તેની મોટાઈ છે. તેના કરતાં દશગણું જળ મહાન છે. જળ કરતાં તેજ, વાયુ, આકાશ, અહંકાર, મહામાયા તે દશ-દશ ગણાં મહાન છે. માયાથી પાર અક્ષરધામ છે. તે ધામના અધિપતિ શ્રીહરિનું સામર્થ્ય વર્ણવ્યામાં જ કેમ આવે! પોતાનામાં અધિક સામર્થ્ય હોવા છતાં તેને જણાવે નહિ તે જ મોટાની મોટાઈ છે.”","e":null,"s":["16/70/29-36"],"sv":[],"mt":false,"gl":null,"a":true},{"i":null,"k":"heading","g":"દેહભાવ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2224,"k":"para","g":"દેહ-અધ્યાસ એ પંચ મહાપાપોમાં અધિક પાપ છે. સત્પુરુષના પ્રસંગથી દેહભાવ ટળે છે, એમ શ્રીહરિ કહેતા.","e":null,"s":["5/9/42"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2225,"k":"para","g":"બ્રહ્મભાવ કેળવી આત્યંતિક પ્રલય કરે તો તીવ્ર વેગે વૃત્તિ જોડાય. ભગવાનમાં મન જોડવા દેહભાવ નડે છે. દેહભાવ ટળ્યો ન હોય ને કહે જે મને બહુ સુખ આવ્યું - તે કથનમાત્ર છે. દેહભાવ સહિત કોટિ વર્ષ સુધી સત્સંગ કરે તોપણ તેને કશું ફળ મળતું નથી, દેહભાવ ટળે પછી ફળ મળે.","e":null,"s":["5/17/6-9"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2226,"k":"para","g":"જે ભક્ત સેવા કરવામાં આળસ રાખે તેના પર શ્રીહરિ ક્યારેય રીઝતા નહિ. જેને આળસ ન હોય કે આળસને હટાવીને સેવા કરતો હોય તેનાં અપાર વખાણ શ્રીહરિ કરતા. દિન-દિન પ્રત્યે અધિક ને અધિક શ્રદ્ધા રાખીને સંતની સેવા કરે ને તેમાં શુદ્ધભાવ રાખે તો શ્રીહરિ પ્રસન્ન થઈ જતા ને સેવા કરનારામાં શુભ ગુણો મૂકતા.","e":null,"s":["13/66/9-10"],"sv":[],"mt":false,"gl":null,"a":true},{"i":null,"k":"heading","g":"પ્રકીર્ણ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":true},{"i":2227,"k":"para","g":"અનુવૃત્તિમાં જે વર્તે છે તેને શ્રીહરિ અક્ષર સમાન કરે છે અને અક્ષરમુક્ત હોય તોપણ જો મરજી વિરુદ્ધ વર્તે ને અનુવૃત્તિ ન પાળે તો કીટ જેવો થઈ જાય છે.","e":null,"s":["18/39/40"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2228,"k":"para","g":"સત્સંગથી વિમુખ રહે ત્યાં સુધી અંતરમાં સુખ આવે નહિ. જે દોષથી વિમુખ થયો હોય તે દોષ પર વૈરબુદ્ધિ રાખી ભગવાન અને ભક્તના ગુણ બોલે તો તેમની કૃપાથી તેના દોષ નાશ પામે છે અને સન્મુખ થાય છે. સન્મુખ થવાનું કારણ પોતાનો સ્વભાવ છે. પોતાના દોષ દેખે નહિ ને સંત-હરિભક્તોથી મન જુદાં પડે તો ફાવે તેવો મોટાઈ પામેલો હોય તોપણ વિમુખ થઈ જાય. એકબીજાની મોટપ સહન થઈ શકતી નથી, જે બીજાની મોટપ સહન કરે તે સાચા સંત-હરિભક્ત કહેવાય, સત્સંગની આ રીત છે. આનો જેટલો ત્યાગ કરે તેટલો સત્સંગનો ત્યાગ કર્યો કહેવાય.","e":null,"s":["22/106/5-13"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2229,"k":"para","g":"જે હરિભક્ત અણુ સમાન ગુણને પણ મેરુ સમાન દેખે છે તે હરિભક્ત મુખ્ય છે.","e":null,"s":["28/130/44"],"sv":[],"mt":false,"gl":null,"a":true},{"i":2230,"k":"para","g":"નિર્માની સંત શ્રીહરિને ખૂબ ગમે છે. માન તો લેશ પણ ગમતું જ નથી. જે સંત માનરહિત વર્તે તે સંતને શ્રીહરિ બધાથી અધિક કહીને વખાણતા અને સંતોને નિર્માની થવા નિરંતર વાતો કરતા. એક દિન નહિ, પણ સદા નિર્માની રહેવા પર ભાર દેતા.","e":null,"s":["9/61/24-26"],"sv":[],"mt":false,"gl":null,"a":true}]},{"n":31,"gu":"શ્રીહરિનાં ચરિત્રનું આચમન","en":"A Sip of Shrihari's Charitra — Divine Episodes","url":"https://www.anirdesh.com/pbp/index.php?page=chp_31","b":[{"i":2231,"k":"para","g":"શ્રીહરિનાં ચરિત્ર વિનાનાં બીજાં સાધનો વારંવાર ભટકાવનારાં થાય છે. હરિનાં ચરિત્ર સાંભળ્યાં વિના જીવતા સુધી અશ્વમેધ યજ્ઞ કરે, કોટિ ગોદાન કરે, તીર્થ-તપ કરે, તોપણ એક મનથી શ્રીહરિનાં ચરિત્ર એક દિવસ સાંભળે તે બરાબર થઈ શકે નહિ. (૯/૩૦) ભગવાનનાં ચરિત્ર-ગાન કરવામાં નિત્ય તાન રાખવું. ચરિત્ર આગળ બીજાં સાધન તુચ્છ છે. સૂર્ય અને પતંગિયા જેટલો તેમાં ભેદ છે. એમ ચરિત્રનો મહિમા સમજવો. (૧૨/૧૭) વિષયી જનને જેમ વિષયમાં તાન છે, તેમ પ્રત્યક્ષ ભગવાનના ચરિત્રમાં તાન રહે તે જ સાચી બ્રહ્મવિદ્યા છે. (૧૪/૪) ઇત્યાદિ ‘હરિચરિત્રામૃતસાગર’માં નોંધાયેલ સંદર્ભ ભક્તોને ભક્તિના માર્ગે ગતિશીલ કરે છે. અહીં એ લીલા ચરિત્રો પૈકી અમુકનો આસ્વાદ માણીએ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"ગઢડામાં પુષ્પદોલોત્સવ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2232,"k":"para","g":"ગઢપુરમાં મુક્તમુનિ, બ્રહ્મમુનિ, પ્રેમાનંદમુનિ વગેરે વીસ-પચીસ મુનિઓ ઝાંઝ, મૃદંગ સાથે સવારથી ઉત્સવ કરવા લાગ્યા. ભોજન જમતાં સુધી જ ઉત્સવ બંધ રહ્યો. જમ્યા પછી ચાર ઘડી શ્રીહરિ પલંગ પર બેઠા. બેય દરબારના ચોકમાં રંગમંડપ બનાવ્યા. રંગના બબ્બે હોજ કર્યા હતા. રંગના કેટલાંય પાત્ર તથા હોજ ભરાયા અને ગુલાલના ઢગલા થયા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2233,"k":"para","g":"લીંબડાની ડાળે ફૂલનો હિંડોળો બાંધ્યો. બે ઘડી દિવસ ચઢતાં શ્રીહરિ તેમાં બેઠા અને સંત-હરિભક્તોની સભા થઈ ત્યારે શ્રીહરિએ કહ્યું કે હરિભક્તોએ પોતાના ગામમાં મર્યાદા રહિત કુસંગી લોકો સાથે હોળી રમવી નહિ. ભાંડ-ભવાઈ વિવાહ અને હુતાશનીના દિવસોમાં ભાભી વગેરે સ્ત્રીઓ સાથે મર્યાદા વિનાનું બોલે તે દારૂ પીધા સમાન છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2234,"k":"para","g":"હરિભક્ત હરિભક્તની રીતે વર્તે. હરિભક્ત અને કુસંગીમાં દિવસ અને રાત જેટલો ફેર છે. જેને બુદ્ધિ હોય તેને મોક્ષની રીત સમજાય છે. એમ વાત કરી શ્રીહરિ રંગ રમવા તૈયાર થયા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2235,"k":"para","g":"હરિભક્તોને પોતાની પડખે રાખ્યા. સંતોનું એક જૂથ બનાવ્યું. જાતજાતનાં વાજિંત્ર વાગવાં લાગ્યાં. શ્રીહરિએ હિંડોળા ઉપર ઊભા રહીને પહેલી પિચકારી ચલાવી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2236,"k":"para","g":"શ્રીહરિ અને હરિભક્તો, સંતો પર રંગ નાખતા અને સંતો તેમના પર નાખતા. એમ ભારે રંગની ઝડી મચી. અતિશય રંગ પડવાથી સહન ન થયો, ત્યારે શ્રીહરિ હિંડોળાની દોરીએ થઈ લીંબડાના ઝાડ પર ચઢી ગયા. તે કોઈના જાણ્યામાં પણ આવ્યું નહિ. પછી તપાસ કરતાં લીમડા પર ચઢેલા ધારીને લીમડા પર પિચકારીઓ નાખવા લાગ્યા. રંગ ખૂટતા સુધી રંગની ઝડી મચી. પછી ગુલાલ ઉડાડ્યો. બધું રંગ-રંગ થઈ ગયું. શ્રીહરિ નીચે ઊતર્યા. સંતોએ શોર કર્યો, “અમે જીત્યા, તમે હાર્યા.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2237,"k":"para","g":"નિત્યાનંદમુનિએ શ્રીહરિને પ્રેમથી પકડી લીધા અને પૂર્વ શરત મુજબ શ્રીહરિના હાથમાંથી કનકનાં કડાં કાઢી લીધાં.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2238,"k":"para","g":"શ્રીહરિ કહે, “તમે સૌ સંતો જીત્યા. અમે અને હરિભક્તો તમારાથી ડરીએ છીએ. બધા જગતના તમે પૂજ્ય છો. ભૂપ અને દેવો પણ તમારાથી ડરે છે. તમારું અપમાન કરનારનું અતિ અપમાન થાય છે. તમે સનાતન ઋષિઓ છો. જનોના ઉદ્ધાર માટે પ્રગટ થયા છો. તમને પૂજે તેના ભાગ્યનો પાર નથી.” ત્યારે મુનિઓ હાથ જોડી બોલ્યા કે, “અમે તમારો અપરાધ કર્યો છે. તમારા હાથનાં કડાં કાઢી લીધાં. અમે તમારા છીએ. પ્રસન્ન રહેજો. તમારી સાથે રમવાનું ક્યાંથી મળે?” એમ કહી કડાં પહેરાવી દીધાં.","e":null,"s":["16/3-4/1-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"ભક્તોના સંઘની રક્ષા","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2239,"k":"para","g":"ચરોતર અને ગુજરાતના ભક્તો ગઢડે ફૂલદોલમાં આવ્યા હતા. તે સમૈયા પછી પાછા ફર્યા ત્યારે શ્રીહરિ ઘોડે ચઢી ભાલ દેશ સુધી તે સંઘની રક્ષા માટે ચાલ્યા. પાછલા પહોરના ચાલ્યા તે ઝીંઝાવદર નદી પર રાત રહ્યા, સવારમાં કારિયાણી પહોંચ્યા. ત્યાં રસોઈ જમી સાંજના ચાલ્યા તે સંધ્યા વખતે કુંડળ આવી નદી પર રાત રહ્યા. મધ્યરાત્રિએ ચંદ્રમા ઉદય થતાં રોજીદ થઈને ચોકડી આવ્યા. ત્યાંથી ખરડ આવી તળાવની પાળે ઊતર્યા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2240,"k":"para","g":"સંઘમાં નાનાભાઈ વિપ્ર તથા કાશીદાસ પટેલ મુખ્ય હતા. ચારસો માણસોનો સંઘ હતો, તેને જમાડવા માટે ત્રણ મણની ખીચડી બનાવી, પણ આઠ મણ ખીચડીની તાણ પડી. પૂરી ખીચડી નહિ મળવાથી ભોજનમાં કસર રહી, સંત ભૂખ્યા રહેશે એમ જાણી હરિભક્તો બે મણ ઘી લાવ્યા. તોપણ શ્રીહરિને અડધી કસર દેખાઈ. તેથી કુંભારને ઘેરથી રામપાતર લાવ્યા. વાણિયાની દુકાનેથી બે મણ ઘી પ્રથમ મળ્યું હતું. લોકોને ઘેરથી મળે તેટલું ઘી પૈસા આપીને લેવડાવ્યું. તોય શ્રીહરિનું મન માન્યું નહિ. તેથી ભરવાડને ઘરે જઈ ત્યાંથી છ મણ ઘી લીધું ત્યારે મન માન્યું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2241,"k":"para","g":"પછી ઉતારે આવી સંતની પંક્તિ કરાવી દોઢ-દોઢ પાશેર ખીચડી બધાને પીરસી. અને પછી ઘી પીરસવા લાગ્યા. ઘી સમાય તેવી ખીચડી કરી હતી. થીજેલું ઘી પીરસતા હતા. જેમ છૂટા હાથે દહીં જમાડે તે રીતે ઘી જમાડ્યું. એમ ખરડના તળાવની પાળે ઘીથી સંતોને તૃપ્ત કર્યા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2242,"k":"para","g":"જમીને તરત ચાલ્યા. બધાની પાસે જળપાત્ર ભરાવી લીધા. રોજકા થઈ પચ્છમનો માર્ગ પૂછી ચાલ્યા. સાત ગાઉનું રણ ત્યાં આવેલું છે. વચ્ચે ફક્ત એક નાની તલાવડી આવે છે. શ્રીહરિ ત્યાં સુધી સંઘની સાથે આવ્યા. પછી શ્રીહરિ રામદાસ સ્વામી પાસે આવીને રજા માગવા લાગ્યા. અને કહ્યું કે અહીં સુધી અમો રક્ષા કરવા માટે આવ્યા, હવે પાછા વળીએ છીએ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2243,"k":"para","g":"પછી આખા સંઘમાં ત્રણ વખત ફરી શ્રીહરિ જય સચ્ચિદાનંદ કહી પોતાની સાથે અલૈયા, સૂરા, સોમલા વગેરે પંદર સવારો સાથે ચાલી નીકળ્યા. શ્રીહરિનો પ્રેમ દેખી હરિભક્તોની આંખોમાંથી આંસુ વહેવા લાગ્યાં. હૃદયને થોભી રાખ્યા છતાં ધીરજ રહી નહીં. જે સંતો સંઘમાં નહોતા અને આગળ ચાલતા હતા તે દર્શન વિના રહી જવાથી પસ્તાવા લાગ્યા.","e":null,"s":["16/5-6/13-40, 1-6"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"વડતાલમાં ફૂલદોલ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2244,"k":"para","g":"વડતાલમાં ફૂલદોલ યોજાયો. નિષ્કુળાનંદમુનિએ બાર બારણાનો હિંડોળો બનાવ્યો. સુંદર થાંભલા બનાવ્યા. કારીગરીનો પાર ન હતો. અલંકારોથી અમૂલ્ય હિંડોળા તળે સોનાની ઘુઘરમાળ બાંધી હતી. બે આંબા વચ્ચે તે અદ્‌ભુત શોભતો હતો. હરિભક્તોએ ગુલાલના ગંજ કરી દીધા. ચાર ઘડી દિવસ રહેતાં રામદાસજીએ શ્રીહરિને હિંડોળે બેસવા કહ્યું. તેથી હરિભક્તોના જયજયકાર સાથે શ્રીહરિ હિંડોળે ઉત્તરમુખે બેઠા. વાજિંત્ર વાગવાં લાગ્યાં.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2245,"k":"para","g":"સંતોને પૂજા કરવા શ્રીહરિએ બોલાવ્યા. સંતો શેર શેર ગુલાલ લઈને શ્રીહરિ આગળ ધરતા. શ્રીહરિ તેમાં ચરણ મૂકતા. એમ સંતોએ પૂજા કરી ગુલાલ પ્રસાદીભૂત કર્યો. સંતો એક એક સાકરનો ગાંગડો શ્રીહરિના મુખમાં મૂકતા. શ્રીહરિ તે બધાયની સાકર જમ્યા. પછી આરતી ધૂન થઈ રહી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2246,"k":"para","g":"હરિભક્તો ફૂલના હાર લાવતા તે ચાલતે હિંડોળે શ્રીહરિ ઘણી ચાતુરીથી લેતા. વેગથી ચાલતા હિંડોળા પર શ્રીહરિ ઊભા રહેતા. જમણા હાથે થાંભલો ગ્રહણ કરી ડાબો હાથ છૂટો રાખતા અને હાર લેતા. હારથી હિંડોળો ભરાઈ ગયો. ક્યારેક હાથમાં રાખેલી છડી વડે હાર લેતા. ક્યારેક બે હાથથી બેઉ થાંભલા પકડી પગ વડે હાર લેતા. એમ દોઢ પ્રહર રાત્રિ સુધી હાર લીધા પછી બંધ કર્યું. પ્રસાદીના હાર સંત કાઠી અને ભક્તોને આપ્યા. ત્રણ લાખ ભક્તો ભેગા થયા હતા. પૂનમનો મહિમા સમજી સુરતના ભક્તો સુંદર મુગટ તથા જરીમય વસ્ત્રો લાવ્યા હતા, એ બધો પોષાક શ્રીહરિને પહેરાવ્યો તથા સોનાનાં આભૂષણ અંગોઅંગ પહેરાવ્યાં.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2247,"k":"para","g":"શ્રીહરિએ ઊભા રહીને માથે મુગટ ધાર્યો હતો તેથી મુગટની કલગી ઠેઠ હિંડોળે અડતી હતી. પછી શ્રીહરિ પશ્ચિમ મુખે ઊભા. મુક્તમુનિએ આવીને તેમને કેસર કુંકુમનો ચાંદલો કર્યો તથા દાઢીને મધ્ય કુંકુમનું બિંદુ કર્યું. ગાલ ઉપર એક એક બિંદુ કર્યું. તેથી મૂર્તિ બહુ મનોહર લાગતી હતી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2248,"k":"para","g":"દર્શન કરનારા જનોની વૃત્તિ મૂર્તિમાં ચોંટી જતી. કેટલાકને સમાધિ થઈ જતી. કેટલાકને દિવ્ય દૃષ્ટિ થતી અને દિવ્ય ધામ દેખાતું ને પોતાના ભાવ પ્રમાણે દર્શન થતાં. એમ ચાર ઘડી શ્રીહરિએ મુગટ ધારણ કરી દર્શન દીધાં. હિંડોળામાં ઊભા ઊભા ચારે બાજુ ફરીને સૌનાં ચિત્ત ચોરતા. કેટલાક ભક્તો વૃક્ષ ઉપર ચઢી દર્શન કરતા. શ્રીહરિએ મુગટ ઉતાર્યો પછી સુરતની જરીની પાઘ માથે ધારણ કરી અને સોનાની કલમ જમણા કાને ઘાલી. અદ્‌ભુત શોભા બની. સૌને બોલાવી રંગનું આયોજન કર્યું. પશ્ચિમ તરફના રંગના હોજ ભક્તોના ઠરાવ્યા અને પૂર્વના સંતના ઠરાવ્યા. હરિભક્તોએ સંતો ઉપર જ પિચકારી નાખવી અને સંતોએ હરિભક્તો ઉપર નાખવી, પણ રંગખેલ થતાં સુધી ભેગાં થઈ જવું નહિ. એમ નિયમ કરી શ્રીહરિ પુરમાં જઈ સૂઈ ગયા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2249,"k":"para","g":"સવારે ઊઠી સૌએ નિત્ય વિધિ કર્યો, પછી કુંડ પર ચાલ્યા. શ્રીહરિ પાર્ષદોને કહે કે અમારા ઉપર પિચકારી ભરી કોઈ રંગ નાખે તેની તમે તપાસ રાખજો. સંતો પિચકારી નાખશે તેનો વાંધો નથી. બીજા તો રંગ નાખનારા એવા છે કે મરે કે જીવે તેની પરવા રાખે નહિ. તમારે ઢાલનો કોટ બનાવી દેવો અને અમને બચાવી લેવા. એક જણ પર બધી પિચકારી છૂટે ત્યારે તે જણાયા વિના રહે નહિ. અમ ઉપર કોઈ પિચકારી ધરે તો તેને રોકવો, દૂર રાખવો ને જોરથી આવે તો પિચકારી લઈ લેવી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2250,"k":"para","g":"શ્રીહરિએ બન્ને કુંડમાં ચરણ બોળી રંગ પ્રસાદીભૂત કર્યો. શ્રીહરિ તથા સૌએ કમર કસી, બોકાની વાળી. પાર્ષદો ઢાલ લઈ શ્રીહરિની રક્ષા કરવા લાગ્યા. હરિભક્તોએ પિચકારી ભરી સંતો ઉપર ચલાવી. કોઈ કોઈને દેખે નહિ તેટલા રંગની વૃષ્ટિ થઈ. બે ઘડીમાં રંગ ઉડાવી દીધો. પછી કૂવામાંથી નીક દ્વારા હોજમાં પાણી લાવ્યા. તેમાં ગુલાલ નાખી રંગ બનાવ્યો ને બે પહોર સુધી રંગે રમ્યા. શ્રીહરિએ પછી બંધ કરાવ્યું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2251,"k":"para","g":"રંગમાં રસબસ થઈને શ્રીહરિ મંચ ઉપર ઊભા રહ્યા. અને રંગથી ભીંજાયેલા સંત અને હરિભક્ત ઉપર પોશે પોશે ગુલાલ ઉડાડવા લાગ્યા. સંત અને હરિભક્તો પણ હરિ સન્મુખ ઉડાડવા લાગ્યા. ગુલાલની ઝોળી ભરીને શ્રીહરિ ફેંકતા તેથી આકાશ અને ભૂમિ ગુલાલમય બની ગયાં. પછી શ્રીહરિ મૂળજી પટેલને કૂવે જઈને નાહ્યા. સંતો પણ સંતની જગ્યામાં આવ્યા. આજે સુરતના હરિભક્તોની રસોઈ હોવાથી તેમણે પૂજા કરી.","e":null,"s":["16/61-66"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"શ્રીહરિનું અદ્‌ભુત વિચરણ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2252,"k":"para","g":"શ્રીહરિ વડથલ આવ્યા. પુરની બહાર ઉત્તર બાજુ વડની છાયામાં ઉતારો કર્યો. વડની ડાળે હિંડોળો બાંધ્યો હતો, ત્યાં બેઠા, સંતની સભા થઈ. અન્ય સવારો આંબાની છાયામાં ઊતર્યા. ભક્તો પાકી કેરીના ટોપલા લાવ્યા. શ્રીહરિએ એક-એક કેરી સૌને આપી, પોતે પણ જમ્યા. વિપ્ર હરિભક્તોએ રસ-રોટલીનો થાળ કરીને ઘેર ઘેર પધરાવી શ્રીહરિને જમાડ્યા અને પૂજા કરી. સંતની જગ્યામાં રસોઈ થઈ ત્યારે પંક્તિ કરાવી લાડુ પીરસ્યા. પછી હરિભક્તોએ સંતોને એક એક વસ્ત્ર ઓઢાડ્યું. વડ નીચે રાતે આરતી-ધૂન કરીને શ્રીહરિએ વાતો કરી. પછી ગરબીનાં પદ ગવરાવ્યાં. દસ ઘડી રાત્રિ ગઈ પછી ત્યાં જ વડ નીચે પોઢી ગયા. સંતો પણ નિયમ પૂરા કરી શ્રીહરિના ફરતે સૂઈ ગયા. કેટલાક ધ્યાનમાં બેઠા. પાર્ષદો વારા ફરતી ચોકી કરતા. ચાર ઘડી રાત રહેતાં સંતો નારાયણની ધૂન કરવા લાગ્યા. સવારે નિત્યવિધિ કરીને શ્રીહરિ હિંડોળા ઉપર બેઠા, સન્મુખ સંતો બેઠા ને ગરબીનાં પદ ગાવા લાગ્યા. કાળિદાસ વિપ્રે ખૂબ ઘી નાખી લાડુની રસોઈ કરાવી. કેરીનો રસ કાઢી પ્રથમ શ્રીહરિને જમાડ્યા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2253,"k":"para","g":"સંતોની પંક્તિમાં લાડુ પીરસતાં શ્રીહરિ બોલતા, “લાડુ લો. ફરી અમે પીરસવા આવવાના નથી.” એમ વારે વારે બોલતા. પછી પાર્ષદો, કાઠી ભક્તો ને ઠાકોરોની પંક્તિમાં લાડુ પીરસ્યા. કાળિદાસે શ્રીહરિની પૂજા કરી. બપોર પછી ચાલ્યા તે ડડુસર આવ્યા.","e":null,"s":["17/86-87"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2254,"k":"para","g":"શ્રીહરિ ગાના ગામ આવ્યા. પુરના જનો દર્શન કરવા સારુ બજારમાં હાર લઈને ઊભા હતા. હરિભક્તોએ ઘેર ઘેર પધરાવી પૂજા કરી. શ્રીહરિ પુર બહાર સરોવર પર આવીને ઊતર્યા. અહીંના લોકો ચીણો ખાતા. ચીણાનો સ્વાદ જોવા માટે શ્રીહરિએ તેનો રોટલો કરાવ્યો. પહેલા ચોથિયું રોટલો જમ્યા અને બોલ્યા કે સરસ રોટલો છે. જમતાં કઠણ પડે તેમ નથી. ઘઉંથી ઊજળો છે ને કુસ્વાદ નથી. એમ કરી સંતને પ્રસાદી આપી. ચણા ચણા જેટલો પ્રસાદ પામી સંતો રાજી રાજી થયા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2255,"k":"para","g":"મેઘવા, વહેરા થઈ બોચાસણ આવ્યા. કાશીદાસ વગેરે પાટીદાર ભક્તોએ પુરમાં પધરાવી પૂજા કરી. પછી શ્રીહરિ પુર બહાર તળાવની પાળે સંત સહિત ઊતર્યા. વડની છાયામાં પલંગનો હિંડોળો બાંધ્યો હતો, તેની પર બિરાજમાન થયા. કાશીદાસના ભવનમાં સંતોની પંક્તિ કરી લાડુ પીરસ્યા. પોતે જમ્યા. પછી તળાવ પર આવ્યા. થોડીવારમાં વાદળાં ચઢી આવ્યાં ને આંધી થઈ. સંતોને છાતીમાં ચરણ ચાંપી વિચરણમાં મોકલ્યા. ભણનારા સંતોને સાથે લઈ ચાલ્યા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2256,"k":"para","g":"શ્રીહરિ કહે, “અમે આગળ જઈએ છીએ, તમે પાછળ આવજો.” સાથેના બાઈ-ભાઈના સંઘને પણ પાછળ આવવા કહ્યું. શ્રીહરિએ અશ્વ દોડાવ્યો. માથા પર ધારણ કરેલા તોરા માર્ગમાં નમેલી આંબાની ડાળીઓમાં ભરાઈને તૂટી ગયા. માર્ગમાં તોરાનાં ફૂલ વેરાયાં. સુંદરડાના ભક્તોએ કેરી આપી તે સંતોને વહેંચી. પાછળ જે સંતો અને હરિભક્તો રહ્યા તેમણે જેટલી જોઈએ તેટલી કેરી લીધી. માર્ગમાં વરસાદ વધારે થયો તેથી કેરીનો સ્વાદ આવ્યો નહિ. ચાલતાં ચાલતાં લપસી જવાતું. શ્રીહરિ બુધેજ પહોંચ્યા. હરિભક્તો મોડા પડ્યા. બુધેજના ખોડાભાઈએ બધા હરિભક્તોને કોરાં વસ્ત્ર પહેરવા આપ્યાં. ભીનાં સુકવાવી દીધાં. હરિભક્તોને દેખી શ્રીહરિ હસવા લાગ્યા. ઉકા ભગતને પૂછ્યું કે માર્ગમાં કેમ થયું? તે કહો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2257,"k":"para","g":"ત્યારે ઉકા ભગત કહે, “માર્ગની શું વાત કહીએ? અમે જીવીશું ત્યાં સુધી ભુલાશે નહિ. એવી વિકટ વાત બની. કોઈ એકબીજાની સાથે રહી શક્યું નહિ. રાતે સઘન વાદળાં ઝામ્યાં. એવું અંધારું થયું કે એકબીજાને દેખે નહિ. બોલે ત્યારે માલૂમ પડે. બધા ડગલે પગલે લપસી પડતા. કેરી લીધી હતી તે માર્ગમાં છૂટી પડી, તેની ખબર પણ રહી નહિ.” શ્રીહરિ વાત સાંભળીને પલંગ પર આમતેમ લોટીને ખૂબ હસ્યા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2258,"k":"para","g":"પ્રેમી ભક્તો ફાવે તેટલા ગાઉ દૂર રહેતા હોય, તોપણ કષ્ટ વેઠીને શ્રીહરિ તેમને ઘરે જતા. શ્રીહરિ પોતાને ત્યાં દિવસે, રાતે, વહેલા, મોડા ફાવે ત્યારે આવે તોપણ તે હરિભક્તોના ભાવમાં ફેર પડતો નહિ. એક રંગ રહેતો. જેમાં એક રંગ રહે અને ઘરમાં સંપ હોય તેને ઘરે શ્રીહરિ જતા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2259,"k":"para","g":"ગોરાડ-ગોલાણા થઈ, સાબરમતી નદી ઊતરી, મોટીબોરુમાં વણિક ભક્તોને દર્શન દઈ ભોળાદ આવ્યા. ભોગાવો નદી ઊતરી પીપળી થાળ જમ્યા. દાદાભાઈને ત્યાં રાત રહી સવારે ચાલ્યા. ગાંફના ભક્તોને દર્શન દઈ ત્યાંથી ચાલ્યા ને બોલ્યા કે રણ ઊતરીશું પછી કાદવ બંધ થશે ને ચાલવાનું સુખ આવશે. ખરડ આવ્યા ત્યારે બોલ્યા કે હવે દુઃખ ન રહ્યું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2260,"k":"para","g":"ઝીંઝર, પરવડી, ભીમનાથ, પોલારપુર થઈ સારંગપુર આવ્યા. અહીં સંઘ ભેગો થયો. પછી સંઘ સાથે ચાલ્યા. પીપલિયા દર્શન દીધાં. આમ, ગઢપુર દોઢ મહિને પહોંચ્યા. ઉત્તમ રાજા શ્રીહરિના વિયોગથી ગદ્‌ગદ કંઠ થઈ ગયા હતા.","e":null,"s":["17/95-98"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2261,"k":"para","g":"સુંદરિયાણામાં હિમરાજ શાહ સત્સંગી થયા હતા. શ્રીહરિ પધાર્યા ત્યારે પ્રથમ ડોસાખાચરને ઘરે ઊતર્યા. પછી હિમરાજ શાહનો થાળ જમીને તળાવ પર ઊતર્યા. અનાજનાં ખળાં હતાં ત્યાં મુકામ કરાવ્યો હતો. પહોર રાત બાકી રહી ત્યારે ચંદ્રના અજવાળે શ્રીહરિ તૈયાર થઈને ચાલ્યા. વચ્ચે લીમડીમાં ઘેલા ધાધલને જે મળે તે ટીમણ લાવવા માટે મોકલ્યા. સાથે બે પાર્ષદો પણ ગયા. હલવાઈની દુકાનેથી મોતિયા, જલેબી લીધાં અને શ્રીહરિ માટે પેંડા જુદા લીધા. ગાંઠિયા, કળી ને શેકેલા ચણા પણ લીધા. પછી ભલગામડાના તળાવ પર ઊતર્યા. સહુ સ્નાન પૂજા ત્યાં કરવા લાગ્યા. ગામમાં એક ગરાસિયા બાઈ હરિભક્ત હતી, તેણે શ્રીહરિને બેસવા સારુ ખાટલો મોકલ્યો, તેના ઉપર શ્રીહરિ બેઠા. સૌને ટીમણ કરાવ્યું ને શ્રીહરિ પોતે પેંડા જમ્યા. બાઈની ઇચ્છાથી શ્રીહરિએ તેને ઘરે પધરામણી કરી, બાઈ મર્યાદા પ્રમાણે પગે લાગી અને શ્રીહરિનાં ચરણમાં દસ રૂપિયા મૂક્યા. આગળ ચાલતાં શિયાણી આવ્યું. અહીં શ્રીહરિ તળાવ પર ઊતર્યા. ખબર સાંભળી ગામજનો દર્શને આવ્યા. તળાવ પાળે પાળિયાનાં દેરાં હતાં તેના પર પથ્થર પર શ્રીહરિ બેઠા. લીમડી શહેરના કેટલાક દરબારો કંઈક સંશય સાથે આવ્યા હતા ને શ્રીહરિએ સંશય હરવા ધોતી સિવાય બીજાં વસ્ત્ર ઉતારી નાખ્યાં. એમ વાત કર્યા વિના સૌનો સંશય ટાળ્યો. સૌ ભાવથી પગે લાગ્યા. શિવરામ ભટ્ટે શ્રીહરિ માટે ઘરે થાળ કરેલો તે બોલાવી ગયા. કાઠી અને પાળા માટે મેઘા પટેલ દહીં ને રોટલા લાવ્યા તે સૌ જમ્યા.","e":null,"s":["18/17, 18"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2262,"k":"para","g":"શ્રીહરિએ ગાડીમાં બેસી ચાલ્યા. આખી રાત ચાલી બરોળ ગામ થઈ પહોર દિવસ ચઢતાં રોઝકા આવ્યા. હરિભક્તોએ વર્ણી પાસે રસોઈ કરાવી અને સૌ જમ્યા ને સૌ પાછલી બે ઘડી રાત રહેતાં ગાડીમાં બેસીને ચાલ્યા તે જીંજર આવી આખો દિવસ રહ્યા. ખોડાભાઈએ રસોઈ કરાવી તે સૌ જમ્યા. સરોવર પાળે પીપરના વૃક્ષ નીચે પલંગમાં પોઢી ગયા. બપોરે ચાર ઘડી ગામમાં ખોડાભાઈના બળદ બાંધવાના ઘરમાં પલંગ પર પોઢ્યા અને સાંજના સરોવર પર પોઢ્યા. નાના પ્રજ્ઞાનંદ અને નાના આધારાનંદ ચરણ ચાંપતા હતા. દોઢ પહોર સુધી ચાંપતા રહ્યા. શ્રીહરિ તેમને ચરણ ચોળવાનું શિખવાડતા. સંધ્યા વખતે ગાડીએ બેસી ચાલ્યા. મોટા કરીમ ગાડી હાંકતા. હરિની મરજી પ્રમાણે ગાડી હાંકતા. ભીમનાથ, પોલારપુર, કુંડળ થઈ કારિયાણી આવ્યા. આખો દિવસ ત્યાં રહ્યા ને સૌ રસોઈ જમ્યા. રાત થઈ ત્યારે ચાલ્યા તે ઝીંઝાવદર, ઉગામેડી થઈને ગઢપુર આવ્યા. ગઢપુરના ભક્તો દર્શન કરી સુખી થયા.","e":null,"s":["22/99"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"પીરસવાની લીલા","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2263,"k":"para","g":"વડતાલના નારાયણગિરિ ગોસાંઈ ગઢડે સંતોને રસોઈ દેવા આવ્યા. શ્રીહરિ જમ્યા. સંતોને જમાડ્યા. શ્રીહરિ સંતોને શીરો પીરસતા હતા ત્યારે ગોસાંઈ કહે, “જમાડવામાં કસર રાખશો નહિ...”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2264,"k":"para","g":"શ્રીહરિ કહે, “સંતોને ખૂબ જમાડ્યા છે. કાંઈ કસર રાખી નથી, તમારે કસર હોય તો શીરો દઈએ.” એમ કહી શ્રીહરિ તેમની તરફ ફર્યા. ગોસાંઈ દોડ્યા. શ્રીહરિ તેમની પાછળ શીરો ઉડાડતાં દોડ્યા. આમ, દિવસમાં બે-ત્રણ રમૂજી ચરિત્ર શ્રીહરિ કરતા.","e":null,"s":["16/5/4-10"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2265,"k":"para","g":"અણિયાળીમાં લખાજી નામના ભૂપે શ્રીહરિની ખૂબ સેવા કરી. સવારમાં બહુ ઠંડી પડી. શ્રીહરિ ઠંડા પાણીએ નાહીને ચાલ્યા. તે શિયાલ ગામ આવ્યા. ત્યાં મધુ નામે વણિક ભક્ત હતા તે રસોઈ આપવા માટે ઘી ભરીને પાત્ર લાવ્યા. ને શ્રીહરિને વિનંતી કરી કે મારો મનોરથ પૂરો કરો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2266,"k":"para","g":"શ્રીહરિ સંઘમાં સાદ પાડીને બોલ્યા, “અમારી આજ્ઞા છે મધુનો ભાવ પૂરો કરો. જેને થીના ઘી પર રુચિ હોય તે આજે છૂટથી જમો. બરફી જેવાં ઘીનાં ચોસલાં કરી રાખ્યાં છે.” શ્રીહરિની આજ્ઞાથી સંત, વર્ણી, હરિભક્તો, પાર્ષદો ભાવે તેટલું ઘી જમ્યા. મધ્યરાત્રિ થતાં સુખડી તૈયાર કરી. ઘી ઉપર સુખડીનું ભોજન કરાવ્યું! જમવામાં જેણે વિચાર ન રાખ્યો તે મૂર્છિત થઈ ગયા. શ્રીહરિએ તેમને ગરમ પાણી મીઠું નાખી પાયું ને ઊલટી કરાવી જીવ બચાવ્યો. પુર બહાર જળ દેખીને રાત રહ્યા. સવારે શ્રીહરિ નાહ્યા ત્યારે પાણી હિમ થઈ ગયું હતું.","e":null,"s":["20/18/23-37"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2267,"k":"para","g":"મુક્તમુનિ અને બ્રહ્મમુનિ વર્તમાન સંબંધી એક એક પદ નિત્ય બોલતા. વર્તમાન બોલ્યા વિના સંત જમતા નહિ. શ્રીહરિએ શ્રાદ્ધપક્ષમાં અભયરાજાનું શ્રાદ્ધ કરાવ્યું. ઉત્તમના નવા ભવનમાં સંતની પંક્તિ બેસાડી, બહુ ચીજો જમાડી. શ્રીહરિએ ડંકો ભરી ભરી ખીર પીરસી. પીરસી રહ્યા ત્યારે બબ્બે પોશ સાકર આપી. કોઈ ના પાડે તો સાંભળતા નહિ. સાકર પીરસીને ઘીની તાંબડી લીધી. પાત્ર ભરાઈ જાય અને નીચે પડે ત્યારે બીજાને પીરસતા! એકધારે ઘી શ્રીહરિ પીરસતા. પછી રોટલી ને શાક પીરસ્યાં. પછી સૌને જમવાની રજા દીધી. સુખાનંદમુનિને ચાર પોશ સાકર દીધી.","e":null,"s":["20/62/6-12"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2268,"k":"para","g":"ચાતુર્માસમાં સંતો ધારણાં-પારણાં કરતા તેમને પારણાના દિવસે નિત્ય જમાડવાનો ઉત્તમની માતાએ નિયમ રાખ્યો હતો ને શ્રીહરિએ પીરસવાનો નિયમ રાખ્યો હતો. ઘઉંની સાતપડી રોટલી શ્રીહરિ બનાવડાવતા. પ્રથમ શ્રીહરિ તે પીરસતા. પૂર્વ મુખે ભવનમાં પંક્તિ થતી. શ્રીહરિ એ રોટલીને ચોળાવી દેતા પછી ગોળ પીરસીને ઘી પીરસતા. જેની જેટલી ઇચ્છા હોય તેને તેટલું ઘી પીરસતા. અડદની મોગર દાળ બનાવતા. પાપડ તથા અથાણાં પણ પીરસતા. જે દિવસે ખીચડી કરે ત્યારે પણ ખૂબ ઘી આપતા. ફૂલવડી ને વડી સાથે દહીંની કઢી કરાવી પીરસતા. ભાત કર્યો હોય ત્યારે ખૂબ દૂધ સાકર દેતા. જમ્યા પછી ઉત્તમ રાજા શ્રીહરિ તથા સંતોની પૂજા કરતા. એમ ઉત્તમે પૂજાનો નિયમ રાખ્યો હતો.","e":null,"s":["23/4"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"*","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2269,"k":"para","g":"ગઢપુરમાં હુતાશનીનો ઉત્સવ કર્યો. પૂર્ણાનંદ અને કૃપાનંદ હુતાશનીને દિવસે આવ્યા. તેમને શ્રીહરિએ કંસાર, ઘી, વડાં, ભજિયાં વગેરે જમાડ્યું. જીવુબાની રસોઈ હતી. સંતોને શ્રીહરિએ પોતાના પૂર્વ મુખેના ભવનમાં બોલાવી જમવા બેસાડ્યા. પોતે સાંગામાંચી પર બેસી દર્શન દેવા લાગ્યા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2270,"k":"para","g":"શ્રીહરિએ બ્રહ્મચારીને કહ્યું, “તમે કંસાર પહેલો પીરસો અને પછી અમે ઘી પીરસીશું.” બ્રહ્મચારીએ અડધું પાત્ર કંસાર પીરસ્યો. શ્રીહરિએ ઘી પીરસી પાત્ર છલકાવી દીધું અને કહ્યું, “કંસારને ચોળીને એક રસ બનાવી દો. ઝાલાવાડના કણબી પાણીની પેઠે એક એક તાંબડી ઘી પી જાય છે તે જોતાં આ કાંઈ નથી. જમશો એટલું લેખે લાગશે. અમારું માહાત્મ્ય જેટલું સમજતા હશો એટલું જમાશે.” એમ કહી હસ્યા. પછી કહ્યું, “જમાય એટલું જમો. વધે તેની ચિંતા નથી. તમારી પ્રસાદીને ઘણા ઇચ્છે છે.” ત્યારે સંતને હિંમત આવી અને જમાય તેટલું જમ્યા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2271,"k":"para","g":"શ્રીહરિએ કહ્યું, “હજી ત્રણ ચાર રસોઈ છે. હરિભક્તોને એમ સમજણ છે કે તેમને જમાડવાનો ફરી આવો સમય આવવાનો નથી. એમ સમજી અત્યંત પ્રેમથી જમાડે છે. કારણ કે પ્રીતની રીત સદાય એક ન રહે પણ ગુણ રહે ત્યાં સુધી પ્રીતિ રહે ને દેશકાળે કરીને દોષ દેખાય ત્યારે પ્રીતિ રહે નહિ.”","e":null,"s":["22/99"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"શ્રીહરિના અંગમાં ટૂંટિયું","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2272,"k":"para","g":"ગઢપુરમાં એકાદશી પછી શ્રીહરિએ ટૂંટિયાનો વ્યાધિ ગ્રહણ કર્યો. વ્યાધિ જોરદાર રહ્યો. મધ્ય દિવસ થયો અને જ્યારે કોઈ પાસે ન હતું ત્યારે ટૂંટિયું આવ્યું. તેને શ્રીહરિએ તેનું પરાક્રમ જોવા પોતામાં પ્રવેશ કરવા દીધો, પણ તે ધ્રૂજતું હતું. શ્રીહરિ કહે, “ટૂંટિયું બીજાને કેવી પીડા કરે છે તે મારે જોવી છે.” ત્યારે ટૂંટિયું કહે, “મને અપરાધ લાગે. હું જેમાં પ્રવેશ કરું છું તેની નાડીઓ ખેંચાય છે, રક્તનું પાણી થઈ જાય છે, નાડીના બંધ છૂટી જાય છે, મુખ અને મળ દ્વારથી પાણી ફુવારાની માફક છૂટે છે, તનમાં શીત વ્યાપે છે, સ્મૃતિ રહેતી નથી, અને એક-બે કે ત્રણ દિવસમાં બચે તો બચે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2273,"k":"para","g":"ટૂંટિયાના તીવ્ર, મધ્યમ અને કનિષ્ઠ એમ ત્રણ પ્રકાર હોય છે, તીવ્ર વેગમાં તત્કાળ મૃત્યુ થાય છે, મધ્યમ અને કનિષ્ઠ પ્રકારમાં મૃત્યુ નજીક આવે છે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2274,"k":"para","g":"પછી શ્રીહરિમાં ટૂંટિયાનો વેગ દેખાવા માંડ્યો. ઓખાલ-પખાલ બહુ થવા લાગી. અંદરથી તાવ પણ રહેવા લાગ્યો. જોનારને મોહ ઊપજે એવાં ચરિત્ર શ્રીહરિ કરવા લાગ્યા. મોહ ન ઊપજે એવા મુકુંદવર્ણી, નિર્ગુણાનંદ, વૈષ્ણવાનંદ, નિત્યાનંદ, શુકાનંદ, નિષ્કુળાનંદ સેવામાં રહ્યા. મોહ ઊપજે તેવાને પાસે જવા દેતા નહિ. પીવા માટે પાણીના અનેક કુંભ મંગાવ્યા. શ્રીહરિ પાણી વારંવાર પીવા લાગ્યા, તેમજ ઊલટી કરી બહાર પણ કાઢી નાખતા હતા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2275,"k":"para","g":"શ્રીહરિએ જાણે ખરેખર દેહથી જુદા થવા નિર્ધાર્યું હોય તેવું થઈ ગયું. સત્સંગની કેવી સ્થિતિ થશે તેવો વિચાર ઊપજ્યો. શ્રીહરિ કહે, “શાસ્ત્ર, મંદિર અને ત્યાગી સંત એ સત્સંગનાં મૂળ છે. મૂળ વિના સત્સંગ ન રહે. આ વખતે અમારું તન ટકે તો દેહ રહે ત્યાં સુધી સત્સંગનાં મૂળ દૃઢ કરવાં.” એવો સંકલ્પ જ્યારે કર્યો ત્યારે તનની સ્મૃતિ આવી. સંધ્યા વખત થયો. ત્યારે પોતે દહીં, સાકર પીધું. બીજું કંઈ ખાતા નહિ. ખાય તો ટકતું નહિ, પછી પોતે બોલ્યા કે, “હવે અમારું તન છૂટશે નહિ, હરિજનના હિત માટે ટક્યું છે. દાદાખાચરના દરબારની પાછળ છૂટી જમીન છે, તેમાં વચમાં લીમડાના વૃક્ષની છાયા છે, ત્યાં ઘેલા નદી લાવી દો જેથી અમને અકળામણ થતી મટે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2276,"k":"para","g":"પછી ત્યાં હિમાળા જેવો શીતલ નિવાસ કરી દીધો. રેતી સઘળી જળથી ભીંજવી નાખી અને ચોકમાં બધે પાણી છાંટી દીધું. ચાર ઘડી રાત્રિ જ્યારે ગઈ અને ચંદ્ર ઉદય થયો અને લૂ વાતી બંધ થઈ ત્યારે શ્રીહરિ બોલ્યા કે, “હવે સંત હરિજનોને દર્શન કરવા દો. કોઈએ હજી ખાધું નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2277,"k":"para","g":"પછી તેમણે કહ્યું ત્યાં પલંગ મૂક્યો અને સૌએ દર્શન કર્યાં. દર્શન થવાથી જાણે તનમાં પ્રાણનો નવો જ સંચાર થયો હોય ને શું! તેમ સૌને થયું. પછી શ્રીહરિનો પલંગ જ્યાં હતો ત્યાં વિરણના વાળાની ટટ્ટીઓ બાંધી દીધી અને હરિજનો તેવા જ પંખા ભીંજવીને પવન ઢોળવા લાગ્યા. શ્રીહરિ ફક્ત કૌપીનભર હતા, શરીર બહુ દુર્બળ થઈ ગયું હતું. ત્રણ દિવસ ગયા પછી શ્રીહરિના કહેવાથી મુક્તાનંદ મુનિ, બ્રહ્માનંદ મુનિ, પ્રેમાનંદ મુનિ વાજાં લઈ કીર્તન બોલવા લાગ્યા. બે ઘડી કીર્તન સાંભળીને શ્રીહરિએ કીર્તન બંધ રખાવ્યાં અને બોલ્યા કે, “જે કીર્તનના પદમાં ભગવાન સંબંધી વાત હોય તેવાં કીર્તન જેવી અન્ય કોઈની વાત નથી. તેનાથી ભગવાનની મૂર્તિનો સંબંધ રહે છે. ભગવાનની કથા અને વાર્તા જીવને સુખદાયક છે ને મોક્ષરૂપ ફળ આપનારી છે. ભગવાનના જે ભક્ત છે તેને આવું મનાય છે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2278,"k":"para","g":"સંતો મુકામ પર ગયા ને સૌની વિનંતીથી શ્રીહરિ થોડી રબડી જમ્યા. પ્રથમ દિવસે નવટાંક, પછી એક એક ગ્રાસ વધારતા ગયા. આ પ્રમાણે દસ દિવસ પછી ઊઠવા બેસવાની શક્તિ આવી. પછી દસવીશ પગલાં ચાલવા માંડ્યું. મલમલનાં વસ્ત્ર ધારણ કરતા. સુરોખાર દશબાર ઘડા ભરી રખાતો, તેમાં શુદ્ધ જળ ભરેલાં નાનાં પાત્ર મૂકવામાં આવતાં, તેથી જળ હિમ જેવું ઠંડું રહેતું તે પીતા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2279,"k":"para","g":"પછી શેરડી ખાવા માંડી. તે જોઈ નિષ્કુળાનંદ સ્વામીએ એક ગજ નાનું સરખું કોલું બનાવ્યું, તેમાં શેરડી પીલીને રસ કાઢીને એક કટોરો આપતા તે પીતા. દાડમના બે દાણા પણ ખાતા. કેરીને સંભારતા પણ ફળ નાનાં હતાં તેથી તે મળી શકી નહિ. ભાવનગરમાં રૂપાભાઈ અને રાજાભાઈ તથા ઝીણાભાઈ શ્રીમાળી વિપ્ર હતા. તેમણે શ્રીહરિને તાવ આવવા માંડ્યો ત્યારથી સુરતથી સોનેરી કેળાં મંગાવી મોકલેલાં તે શ્રીહરિ ભાવથી જમતા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2280,"k":"para","g":"પછી એક દિવસ સંધ્યા વખત થયો ત્યારે સંતોને દર્શન દેવા સાધુની જગ્યામાં શ્રીહરિ પધાર્યા ને સંતોને રાજી કર્યા, પણ ગરમ પવન વાવા લાગ્યો એટલે ત્યાંથી ચાલી નીસર્યા. શ્રીહરિ કહે, “અગ્નિ જેવો ગરમ પવન અમને લાગે છે. વિચરણ કરતા સંતોને કહેશો કે તાપમાં ફરે નહિ. તેમાં મૃત્યુ થઈ જાય એવો કાળ વર્તે છે. એક વરસાદ થાય પછી બોલાવ્યા વિના પણ અમારે દર્શને આવવું.” એવો પત્ર લખાવ્યો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2281,"k":"para","g":"ઉત્તમ રાજાના દરબારમાં ચોકમાં પાણી છંટાતું. સાંજે ત્યાં સભા થતી. હરિજનો ફૂલના હાર શ્રીહરિને પહેરાવતા. પોતાના નિવાસ સ્થાન નજીક એક કૂવો કરાવવા માંડેલો તેમાં ખૂબ પાણી આવ્યું. દશ દિવસમાં પથ્થરથી આ કૂવો ચણી દીધો. થોડા વખતમાં વરસાદ પણ આવ્યો અને ઉષ્ણકાળ વીતી ગયો.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2282,"k":"para","g":"શ્રીહરિનાં દર્શન માટે સંતો આવવા લાગ્યા. ત્યાં દ્વિતીય જેઠ માસમાં ભીમ એકાદશી આવી એટલે શ્રીહરિએ સભા બોલાવી. દાદાખાચરના દરબારમાં વાસુદેવનારાયણના ભવનના ચોકમાં ઘેલા નદીમાંથી રેતી લાવીને પાથરી અને જળનો છંટકાવ કર્યો. વાસુદેવનારાયણના ભવનના ચોકથી લીંબવૃક્ષ સુધી મંડપ રચીને છાંયો કર્યો હતો. દશ બાર માટીની ઘડીઓ જળથી ભરીને તેમાં વરિયાળી ઘૂંટીને નાખી ને તેને શીતળ બનાવ્યું હતું. વિરણના વાળા બાંધવામાં આવ્યા હતા. ત્યાં શ્રીહરિ સવાર-સાંજ સભા કરતા. ગરબીનાં કીર્તનો વાજાં સાથે ગવડાવતા. જેને તરસ લાગે તેણે આ શીતળ જળ પીવું અને જેને નિદ્રા આવે તેણે સભાની પાછળ જઈ ઊભા રહેવું. જો નિદ્રા આવે છતાં ન ઊઠે તો પાસે બેઠેલાએ ઉઠાડવા. ઊભા થયા છતાં નિદ્રા આવે તો દશ દંડવત્ કરવા અને દંડવત્ કરવા છતાં ઊંઘ આવે તો ઉન્મત્તગંગામાં નાહી આવવું, અને છતાં ઊંઘ આવે તો સભામાં ન આવવું તેવો આદેશ આપ્યો.","e":null,"s":["21/83-85"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"ગઢપુરમાં દીપોત્સવ","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2283,"k":"para","g":"સં. ૧૮૭૮ની દીપોત્સવી શ્રીહરિએ ગઢપુરમાં કરી. નિષ્કુળાનંદ મુનિએ વાસુદેવનારાયણના મંદિર આગળ વિચિત્ર શોભાએ યુક્ત દીપમાળા બાંધી, અપાર દીવાઓ પ્રગટાવ્યા. તે પંચદ્વારી દીપમાળાની વચ્ચે સિંહાસન પર શ્રીહરિ બિરાજ્યા. આગળ દીવાનાં બે ઝાડ (દીપદાન) પણ પ્રગટાવ્યાં. શોભાનો પાર રહ્યો નહિ. આરતી-ધૂન થયાં પછી મધ્યરાત્રિ સુધી ઉત્સવ થયો. દીપમાળાની ચારે બાજુ અમુક સંતો ફરતા ગાતા હતા. ગુણાતીતાનંદ, વિરક્તાનંદ, પ્રજ્ઞાનંદ, ગોવિંદમુનિ તથા નિષ્કામાનંદ મુનિને એક એક હજાર પદ કંઠે હતાં. મુનિને ફરતા દેખીને શ્રીહરિથી ન રહેવાયું. તેઓ પણ ઊભા થઈને સંતો સાથે ફરવા લાગ્યા ને કીર્તન ગાવા લાગ્યા. સુંદર વસ્ત્રાલંકાર પહેર્યાં હતાં. એમ શ્રીહરિ બહુ પ્રકારનો રસ ભક્તજનના આનંદ માટે પ્રગટ કરતા. એમ કરતાં સવાર થયું ત્યારે ઉત્સવ બંધ કર્યો, પછી શ્રીહરિ સૌ સંતો-ભક્તો સાથે ઉન્મત્તગંગામાં સ્નાન કરવા ગયા. પાછા વળતાં નાગાજણ અને હમીર નૃત્ય કરતા હતા, રાવળ રવાજ વગાડતા હતા. ઉત્તમના દરબારમાં સૌ આવ્યા. શ્રીહરિ ઓસરી પર સિંહાસનમાં બિરાજ્યા. સંતો ભક્તો પણ પૂજા-માળા કરીને આવી ગયા. શ્રીહરિએ અશ્વ મંગાવી નાગાજણ રાવળ જે ગાતો હતો તેને અર્પણ કર્યો. માણેકવર્ણનો ઘોડો હતો. બીજા જે જે ગાતા હતા તેમને પણ પાઘ બંધાવી અને એકેક ફૂલનો હાર આપ્યો. રાતે ગુણાતીતાનંદ મુનિ વગેરે જે સંતો ગાતા હતા તે સૌને હાર આપી મળ્યા.","e":null,"s":["22/44-46"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"અમદાવાદમાં ચોરાશી","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2284,"k":"para","g":"અમદાવાદમાં શ્રીહરિ ચોથને દિવસે નિત્યકર્મ કરી સભામાં વિરાજ્યા. મંદિરની સેવામાં જેમણે ભાગ લીધો હતો એવા શહેરના હરિભક્તોને શ્રીહરિએ હાર દઈ ચરણકમળ દીધાં અને સેવાનો મહિમા કહ્યો. શણગાર આરતી થયા પછી સરકારના હરદત્ત શાસ્ત્રીને બોલાવ્યા. તેમને શ્રીહરિએ કહ્યું કે તમે વ્યવસ્થાનું માથે રાખો તો અમે વિપ્રની ચોરાસી એક દિવસમાં કરાવીએ. ત્યારે હરદત્ત શાસ્ત્રી બોલ્યા કે, “તમે તો મહાજોગી છો. તેથી તમારી વાત થાય નહિ, પણ રાજાની વાત હું કહું. પહેલાં શ્રીનગરમાં એક રાજા થયો હતો, તે પણ છ માસથી પ્રયત્ન કરવા માંડ્યો ત્યારે ચોરાસી થઈ હતી. ત્યાર પછી કોઈએ ચોરાસી કરી નથી. તમે એક દિવસમાં ને તે પણ હાલ ને હાલ ચોરાસી કરવાનો વિચાર કરો છો પણ પાર પડશે નહિ.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2285,"k":"para","g":"ત્યારે શ્રીહરિ કહે, “તમે વિપ્રને જમવાની હા પડાવો. અમે આજે જ કાંકરિયા સરોવર ઉપર સાંજ પહેલાં સામાન પહોંચતો કરીએ છીએ. સૌ પોતપોતાની ન્યાતનાં વાસણ લાવે, રાતે રસોઈ થાય અને પાંચમને દિવસે જમે.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2286,"k":"para","g":"ત્યારે બધી જ્ઞાતિના આગેવાનોને બોલાવી જમવાનું પૂછ્યું. સૌએ હા પાડી ત્યારે જય બોલાવી. મધ્યાહ્‌ન કાળ થયો હતો. વિપ્રો આશ્ચર્ય પામતા અને કહેતા કે આજે સ્વામિનારાયણ પ્રભુ દેખવામાં આવશે. એમ ઉચ્ચારતાં સૌ ઘરે ગયા અને પોતપોતાની જ્ઞાતિનાં વાસણ ભેગાં કર્યાં.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2287,"k":"para","g":"શ્રીહરિએ સંત-હરિભક્તોને કહ્યું કે આટો, દાળ, ઘી, ગોળ, વગેરે માથે ઊપડે તેટલું ઉપાડીને લાવો. જ્યાં દેખો ત્યાંથી નામું માંડીને લાવો. એવી શરત કરજો કે ઘી, ગોળ, લોટ, દાળ ને ચોખા, એ પાંચ વસ્તુઓ વીસ મણ જેટલી ખરીદી હોય તો તેણે વધે તો દશ મણ પાછી લેવી, એમ લખાણ કરીને લાવવું. કારણ, આ તો અમાપ વાત છે, તે પાછું આપવાનો વખત પણ આવે.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2288,"k":"para","g":"પછી શ્રીહરિના કહ્યા પ્રમાણે બધો સામાન, મસાલા તથા કાષ્ઠ વગેરે પહોંચતું થયું. પછી બધી જ્ઞાતિના વિપ્રોને બોલાવવા ગયા. બધી જ્ઞાતિના વિપ્રો વાસણ લઈને આવ્યા. ચોરાસી ચોકા જુદા જુદા થયા. મણે અડધા મણ લેખે ઘી આપીને દરેક ચોકે લાડુ કરાવ્યા. ચોકે ચોકે સંતને દેખરેખ માટે મૂક્યા હતા. કાંકરિયાની દક્ષિણ બાજુ ચોકા હતા. ચોકાથી દક્ષિણ બાજુ સંઘ રહ્યો હતો. કેટલાક તો કાષ્ઠ લાગે નહિ ત્યારે ચૂલામાં ઘી નાખતા. સંત ના પાડે તો લડવા તૈયાર થતા. કોઈ વિપ્રો થીનું ઘી ખાતા. કેટલાક તળેલાં મૂઠિયાં ખાતા જતા. કેટલાક દિવેલને બદલે ઘીના કાકડા કરતા. એમ ઘી ખુટવાડવાનો ઉપાય કરતા. સંતો જ્યારે શ્રીહરિને આ વાત કહેતા ત્યારે શ્રીહરિ બોલતા કે ઘી ચોરે તો જ કહેવું. વિપ્રને જમવા માટે આ ઘી ભેગું કર્યું છે, માટે ખાવામાં ના પાડવી નહિ. પ્રસન્ન રહે એમ કરવું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2289,"k":"para","g":"એક બ્રાહ્મણે ઘીનો દેગડો ભરેલો ચોરી લીધો ને ભોંયમાં દાટ્યો પછી ઘી નથી એમ કહ્યું. તે ચોકા ઉપર નિષ્કુળાનંદ મુનિ હતા. તેમણે વિપ્રને કહ્યું કે અહીં કોઈ ચોર તો આવ્યો નથી ને? ઘી ખૂટે શી રીતે?","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2290,"k":"para","g":"ત્યારે વિપ્ર કહે, “અમે કાંઈ ઘી ચોરી ગયા નથી. તમે ઘી થોડું લાવ્યા હશો. માટે ઘી લાવો તો કઢાઈ ચાલશે.” એમ કહી કઢાઈ ઉતારી પાડી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2291,"k":"para","g":"સંત કહે, “ઘી થઈ રહે એમ મનાતું નથી.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2292,"k":"para","g":"ત્યારે વિપ્ર કહે, “અમે પી ગયા શું? લાવવું હોય તો લાવો.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2293,"k":"para","g":"ત્યારે સંત કહે, “તમને ક્રોધ ન ચઢે તો અમે ઘી દેખાડીએ. કારણ કે વિપ્રના ક્રોધથી અમે ડરીએ છીએ.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2294,"k":"para","g":"ત્યારે વિપ્ર કહે, “અમે તો જાણતા નથી. તમે ચોર્યું હશે, દેખાડો તો તમે ચોર સાચા, નહિ તો કાચા.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2295,"k":"para","g":"ત્યારે નિષ્કુળાનંદ સ્વામીને સંકટ થયું. ચોરી કરીને બીજાને માથે નાખે છે. ચોર શાહુકારને દંડે એમ થયું. નિષ્કુળાનંદ મુનિને ઠગનો અનુભવ થયો. કુબેરસિંગે પહેલાં કહ્યું હતું કે, શહેરમાં આવા બહુ ઠગ હોય છે. કેટલાક તો બજારમાં સંત-હરિભક્તની આગળ રૂપિયા નાખે અને જો કોઈ અડે તો ચોર છે એમ કહેવા માંડે. કોઈ સંત-હરિભક્ત અડે નહિ ત્યારે તેઓ મનમાં પસ્તાય અને બળી મરે... માટે કોઈ સંત-હરિજનને ઠગ મળે તો અમને કહેજો. ઠગની પાછળ અમે છીએ. ઠગને અમે સમજી લઈશું. એમ સંત-હરિભક્તને કહેલું તે નિષ્કુળાનંદ મુનિ જાણતા હતા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2296,"k":"para","g":"તેમણે કુબેરસિંગને વિપ્રની વાત કહી તેથી તે આવીને વિપ્રને કહેવા લાગ્યા કે અમારા સંત ચોરીનો ત્યાગ કરાવે છે તે સરકાર સુધી પ્રસિદ્ધ છે. માટે ઘી તેં ચોરીને સંતાડ્યું છે. તમારે ચોરી ન કરવાનો નિયમ નથી. અમારા સંતો તો વિપ્રને જમાડવા હજારો મણ ઘી લાવ્યા છે. તે ચોરી શું કરવા કરે?","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2297,"k":"para","g":"પછી સરકારી મનુષ્ય આવ્યો તેણે વિપ્રને કહ્યું કે ઘી સંતાડેલું કાઢી દો. વિપ્ર કહે, “અમે સંતાડ્યું નથી. દેખ્યા વિના ક્યાંથી કાઢે?” ત્યારે નિષ્કુળાનંદ મુનિએ દેખાડ્યું તેથી વિપ્રે આવીને તેમને કાંડે બચકું ભર્યું. સરકારી મનુષ્યે વિપ્રને પકડી લીધો. હાથ બાંધી દીધા. શ્રીહરિને જઈને વાત કરી, ત્યારે શ્રીહરિએ વિપ્રને છોડાવી અધિક ઘી અપાવ્યું. વિપ્રને પ્રસન્ન કર્યો અને બધાય વિપ્રોને સંભાળાવ્યું કે, “તમને પ્રસન્ન કરવા માટે અમે આ ચોરાશી કરી છે. માટે તમે ઘી, ગોળ, આનંદથી ફાવે તેટલાં જમો. અમે તેમાં રાજી છીએ. તમારે મુખે ભગવાન જમે છે એમ જાણીને જમાડીએ છીએ. તમે ભૂદેવ છો. માંસ, મદિરા, ચોરી, વ્યભિચાર તમે કરતા નથી. ત્યાગી તો વિપ્રોના પણ ગુરુ કહેવાય, છતાં વિપ્ર થઈને ત્યાગીનું અપમાન કરે તેને કેવો કહેવાય! તે શાસ્ત્રમાં સમજતા હો તે બોલો.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2298,"k":"para","g":"ત્યારે વિપ્રો બોલ્યા કે, “વિપ્રની રીતમાં રહે તે વિપ્ર કહેવાય, નહિ તો નેત્ર વિનાના મનુષ્ય જેવો છે. આપ તો ભગવાન છો તે આ ચોરાસી કરી તે પરથી અમે જાણ્યું. શ્રીનગરની ચોરાસી કરવાની કોઈ હામ ભીડતું નથી. તમે તો એક પહોરમાં સામાન ભેગો કરી દીધો. તમે ધન તો રાખતા રખાવતા નથી. કરોડપતિ શાહુકારોએ ચોરાસી કરી નથી, પણ લોભના માર્યા ધન ભેગું કર્યા કરે છે. ચોરાસી કર્યા વિના ચોરાસીમાં ભટકે છે. તમે તો ચોરાસી મટાડનારા છો, છતાંય ઘણી ચોરાસી અને યજ્ઞ કર્યા. કેટલાય વિપ્રોને કન્યાદાન તથા ઉપવીત દેવડાવ્યાં. કેટલાયને અન્ન-વસ્ત્ર વાહનનાં દાન આપ્યાં છે. તમારા સમાન કોઈ ત્યાગી નથી. અપાર ધન-વાહન મળે છે છતાં નિર્લેપ રહો છો.” એમ સન્મતિ વિપ્રોએ કહ્યું.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2299,"k":"para","g":"એક શ્રીમાળી વિપ્ર સીધાનાં બે ગાડાં ભરીને પુરમાં લઈ ચાલ્યો. સંતોએ ના પાડી છતાં માન્યું નહિ. શ્રીહરિને વાત સંભળાવી ત્યારે શ્રીહરિ ગાડાં પાછા લાવવા ઘોડા પર બેસી આગળ દરવાજે ઊભા રહ્યા. ચાળીસ સવારો સાથે હતા. નારૂપંત નાના, ચીમનરાવ વગેરે દસબાર ગાયકવાડી ઘોડેસવારો હતા. ગાડાં પાછાં લાવ્યા. દિવસ ઊગતાં સરકારનાં મનુષ્ય આવ્યાં. તેમનો પણ ચોકો કરાવ્યો. લાડુ તૈયાર થયા. બે પહોર દિવસ નમ્યો ત્યારે પંક્તિ કરાવી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2300,"k":"para","g":"વિપ્રો જમતાં નરનારાયણ અને સ્વામિનારાયણની જય બોલાવતા તાંબડી ભરી ભરીને લાડુમાં ઘી ફેરવતા. ઘીમાં લાડુ નરમ કરી સબડકે ખાતા. દાળ-ભાતને કોઈ અડકતું નહિ. કંઠ સુધી જમીને પ્રસન્ન થયા. શલોક બોલી આકાશ ગજાવતા. પાછલી એક ઘડી દિવસ રહ્યો ત્યાં સુધી વિપ્રો જમ્યા. વિપ્રની બાઈઓ પણ જમી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2301,"k":"para","g":"શ્રીહરિ પોતાના તંબુમાં વિરાજમાન હતા. ચાર ઘડી રાત્રિ જતાં પલંગ પર ઉત્તર મુખે બેઠા હતા. ત્યાં લાલદાસ ભક્ત શ્રીહરિને સામાનનું નામું થયું હતું તે બતાવવા આવ્યા. ત્યારે દામોદર અને ભાણાભાઈને શ્રીહરિએ કહ્યું કે ગામોગામના હરિભક્તોને કહો કે કાલે અમે જવાના છીએ, પગે લાગવું હોય તો અત્યારે નિવૃત્તિ છે. ફરી આવો અવસર નહિ આવે. ત્યારે તે બન્ને જણે તે પ્રમાણે કહ્યું. તેથી સૌ આનંદ ભર્યા ભાવ પ્રમાણે પૂજા લઈને ચાલ્યા. અડધા રૂપિયાથી આરંભી હજાર રૂપિયા સુધીની ભેટ જેવી શ્રદ્ધા હોય તે પ્રમાણે આપતા. જેથી ખર્ચ થયેલું તે બધું પૂરું થઈ ગયું. ઉપર પાંચ રૂપિયા વધ્યા. પછી શ્રીહરિ સુખેથી પોઢી ગયા. ધારેલી વાત નિર્વિઘ્ને પૂરી થઈ.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2302,"k":"para","g":"બેસવાને માટે બે મંચ તૈયાર કર્યા હતા, તેમાંથી પૂર્વના મંચ પર પહોર દિન ચઢતાં શ્રીહરિ આવીને બેઠા. આંબલીની ઘાટી છાયા હતી, પશ્ચિમ મુખે શ્રીહરિ બેઠા. સભા થઈ ફૂલના હારમાં મૂર્તિ ગરકાવ હતી. પાછલો દોઢ પહોર દિવસ રહ્યો ત્યારે પણ તેવી રીતે સભા કરી.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2303,"k":"para","g":"તે વખતે ફકીર જેવા વેશમાં એક માણસ શ્રીહરિની સમીપે આવ્યો. એક કફની વિના પાસે કાંઈ હતું નહિ અને માથે એક વેંત લાંબા છૂટા કેશ હતા. ચાલીશ વર્ષની ઉમર હતી. શ્રીહરિનાં દર્શન ચાર ઘડી ઊભા રહીને કર્યાં. દર્શન કરતાં મટકું ભરતો નહિ. શ્રીહરિ પણ તેની સામું જોઈ રહ્યા. પરસ્પર કોઈ બોલ્યું નહિ. નેત્રની વૃત્તિથી પરસ્પર સમજી લીધું. શ્રીહરિ પાસે દસ-બાર કેળાંની લૂમ આવેલી હતી. તે જોગીને આપી. કોઈ મુક્ત જેવા અકળ જોગી શ્રીહરિની મરજી લેવા આવ્યા હતા. તે મરજી લઈને ચાલ્યા ગયા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2304,"k":"para","g":"પછી શ્રીહરિ ચાલવા તૈયાર થયા. ઘી, ગોળ, આટો જ્યાં હતાં ત્યાં આવીને જોયું તો હતો તેટલો ને તેટલો જથ્થો દીઠો. શ્રીહરિએ આનંદમુનિને કહ્યું કે, “આ બધો સામાન સંભાળો, કામમાં આવે તેટલા સંત હરિભક્તોને મદદમાં રાખજો. વિપ્રોએ લાડુ કર્યા છે તે અડધોઅડધ વધ્યા છે. તે સૌ સંઘને તથા પુરના ભક્તોને જમાડજો અને વધે તો ભાતોમાં આપજો. ખોખરા મહેમદાવાદના લોકોને તથા કોઈ અન્નાર્થી હોય તેને જમાડજો.”","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2305,"k":"para","g":"એટલી વાત કરી વિપ્રો ફરતાં પાંચ પ્રદક્ષિણા કરી શુકમુનિ, નિષ્કુળાનંદ મુનિ અને આધારાનંદ મુનિ ગઢપુર આવે એમ આનંદ મુનિને કહીને પાર્ષદો સાથે શ્રીહરિ ચાલી નીકળ્યા.","e":null,"s":["22/95-98"],"sv":[],"mt":false,"gl":null,"a":false},{"i":null,"k":"heading","g":"શ્રીહરિની દૈનંદિની","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2306,"k":"para","g":"હુતાશનીના સમૈયામાં હરિભક્તો ખજૂર, ખારેક, ટોપરાં લાવે તે શ્રીહરિ અડધો પ્રસાદ પાછો આપતા. સાકરના મોટા મોટા હાર પણ ભક્તો લાવતા. એમ આખો દિવસ શ્રીહરિની પૂજા થતી. કેટલાક ગુલાલના થાળ ભરીને લાવતા તે ઉડાડીને સંત-હરિભક્તોને ગુલાલમય કરી દેતા. કોઈ ગુલાલગોટા લાવતા તે પણ ઉડાડતા.","e":null,"s":["16/3-4/1-40"],"sv":[],"mt":false,"gl":null,"a":false},{"i":2307,"k":"para","g":"ઉત્સવ ઉપર હરિભક્તો આવે ત્યારે શ્રીહરિને પગે લાગી શ્રીફળ તથા હાર અર્પણ કરતા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2308,"k":"para","g":"શહેરના હરિભક્તો મેવા-મીઠાઈ લાવતા. શ્રીહરિ તેમને પ્રસન્ન કરવા થોડુંક જમતા. સૌ ઉતારા કરીને પગે લાગી સંત, વર્ણી, સંન્યાસી તથા ચારેય વર્ણના હરિભક્તો સભામાં પોતપોતાના વિભાગમાં બેસતા. સંતો વાજિંત્રો સાથે તથા ઝાંઝ-મૃદંગ વગાડી સાંજે વસંતનો ઉત્સવ કરતા. પછી આરતી-ધૂન થઈ રહે ત્યારે શ્રીહરિ વાત કરતા. શુકમુનિ પત્રલેખનની સેવામાં હતા. શ્રીહરિ જે સ્થાનમાં રહ્યા હોય ત્યાં ગાદી-તકિયા પર બેસી પત્રમાં જે વાત લખાવવી હોય તે બોલતા અને શુકમુનિ ધ્યાન રાખીને તે પ્રમાણે લખી લેતા. જેટલી વાત સમજાય નહિ તેટલી ફરી પૂછીને દૃઢ કરતા. દરેક પત્ર લખીને શ્રીહરિને વંચાવતા. સભામાં પણ વાંચી બતાવતા, અક્ષર અને ઉચ્ચાર સ્પષ્ટ હોવાથી બધી સભાને સારું લાગતું. ન સમજાય તેવી વાત શ્રીહરિ સમજાવતા.","e":null,"s":[],"sv":[],"mt":false,"gl":null,"a":false},{"i":2309,"k":"para","g":"દસ ઘડી રાત્રિ જાય ત્યારે શ્રીહરિ પોઢતા, અને બે ઘડી રાત્રિ રહે ત્યારે ઊઠીને નિત્યવિધિ કરતા. દાતણ કર્યા પછી માણકી ઉપર પલાણ મૂકી તેના પર બેસી ચોકમાં મધ્ય રહેલા લીમડાની ચારે બાજુ તેને નિત્ય ફેરવતા. હરિભક્તો દર્શન કરવા સારું ચારે બાજુ ઊભા રહેતા. બે-ત્રણ ઘડી ઘોડી ફેરવતા પછી સ્નાન કરી સભામાં પલંગ પર બેસતા. હરિભક્તો ભાવ પ્રમાણે શ્રીહરિની પૂજા કરતા. દોઢ પહોર દિવસ ચઢે ત્યાં સુધી પૂજા થતી. જનોની અપાર ભીડ થતી. રસોઈ તૈયાર થાય ત્યારે શ્રીહરિ પ્રથમ જમીને સંતોને જમવા બોલાવતા. સંત-પાર્ષદોની પંક્તિમાં શ્રીહરિ વારે વારે પીરસતા.","e":null,"s":["16/2/1-40"],"sv":[],"mt":false,"gl":null,"a":false}]}]};